[Proposition 6 (Exact control identity) of arXiv:2608.02417, 'A Bismut--Elworthy--Li formula for linear stochastic evolution equations in Banach spaces'] Let \(\xi\in\mathscr D_t\). Then
\begin{equation}
    R_tv_a^\xi=S(t)\xi.
\end{equation}

[Definition def:defBmu of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For every $\tau\in\mathcal{T}_*$, we define 
    \begin{equs}
        \text{$\mathrm{Ind}$}(\tau)\eqdef\Big\{(\tau_1,\tau_2)\in\mathcal{T}^2 :\exists\,\underline{\tau}_i\in\tau_i\in\mathcal{T}\,,\;\exists\,n\in N(\underline{\tau}_1)\,,\;\underline{\tau}_2\graft_n\underline{\tau}_1\in\tau\Big\}
    \end{equs}

[Theorem 5 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] Let $ X $ be a discrete random variable with the bi$^{s}$nomial distribution with parameters $ n $ and $ p $, $ X\sim \mathcal{B}^{(s)}(n,p) $. Then, since $X$ is a sum of $n$ i.i.d.\ $s$-Bernoulli variables, $G_X=(G_{X_1})^n$; explicitly,
	\begin{equation}
		G_X(t) =\left(\frac{q^{s+1}-(pt)^{s+1} }{q-p t}\right)^n=\sum_{k=0}^{sn}{n\choose k}_s (pt)^kq^{sn-k},\quad \text{ for } p\neq q,
	\end{equation}
	and
	\begin{equation}
		G_X(t) =\frac{1}{\left( s+1\right)^n}\left( \frac{1-t^{s+1}}{1-t}\right)^n=\frac{1}{\left( s+1\right)^n}\sum_{k=0}^{sn}{n\choose k}_s t^k, \quad \text{ for } p=q.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:fokker_superpo of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $\nu\in\mathcal{P}(\mathbb{R}^d)$ and let ${\boldsymbol\mu}:[0,\infty)\to \mathcal{M}_{+}(\mathbb{R}^d)$ (with ${\boldsymbol\mu}_0 = \nu$) be such that
\begin{equation}
\big[(t,x)\mapsto {\bf b}(t,x,{\boldsymbol\mu}_t)\big],  \ \big[ (t,x)\mapsto {\boldsymbol\sigma} {\boldsymbol\sigma}^\top(t,x,{\boldsymbol\mu}_t)\big] \in L^{1}_{\text{loc}}([0,\infty) \times \mathbb{R}^d , \overline{\boldsymbol\mu}),
\end{equation}
with $\overline{\boldsymbol\mu}$ as in Notation (not:measure_dt_dx of the paper).

Then:

\begin{itemize}
\item[(i)] If $X$ is a solution to MKV$({\bf b},{\boldsymbol\sigma};\nu)$, with $[X_t]={\boldsymbol\mu}_t $ for $t\geq0$, then ${\boldsymbol\mu}$ is a weak solution to NL-FP$({\bf b},{\boldsymbol\sigma};\nu)$.
\item[(ii)] [Superposition] Under the additional assumption that 
\begin{equation}
\Big[ t \mapsto \int_{\mathbb{R}^d} \Big( |{\bf b}(t,x,{\boldsymbol\mu}_t)| + \| {\boldsymbol\sigma}{\boldsymbol\sigma}^\top(t,x,{\boldsymbol\mu}_t) \| \Big) {\boldsymbol\mu}_t (d x)\Big], \  \big[ t \mapsto {\boldsymbol\mu}_{t} (\mathbb{R}^d) \big]  \in L^{\infty}_{\text{loc}}([0,\infty) ,
\end{equation}

if ${\boldsymbol\mu}$ is a (weak) solution to NL-FP$({\bf b},{\boldsymbol\sigma};\nu)$, 
 then there exists a solution $X$ to MKV$({\bf b},{\boldsymbol\sigma};\nu)$ such that $ [X_t] = {\boldsymbol\mu}_t $.

\end{itemize}

