body:
[Theorem thm:intro-lbm-spectrum of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $0<\gamma<2$, almost surely, $A_h$ has compact resolvent, and its
positive eigenvalues, listed with multiplicity, satisfy
\begin{equation}
 0<\Lambda_1^h<\Lambda_2^h<\cdots\uparrow\infty.

\end{equation}
Moreover, for every $N\ge1$ and $1\le n_1<\cdots<n_N$,
\begin{equation}
 (\Lambda_{n_1}^h,\ldots,\Lambda_{n_N}^h)_\#\mathbb P
 \ll\mathcal L^N.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 55 (Second-order singular block profiles) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Assume \eqref{eq:group-growth}, let
\[
 \frac D4<\sigma\le\frac D2,\qquad
 c_x=\langle x\rangle^{-\sigma},\qquad
 \beta:=D-2\sigma,\qquad
 \gamma:=4\sigma-D,
\]
and set
\begin{equation}

 \omega_\sigma(R):=
 \begin{cases}
  R^\beta,&D/4<\sigma<D/2,\\
  \log(e+R),&\sigma=D/2.
 \end{cases}
\end{equation}
For $L,Q\in\Dya$, write
$R_+:=\max\{L,Q\}$ and $R_-:=\min\{L,Q\}$.  Then, for
$2\le r\le\infty$ and every $N\ge1$,
\begin{equation}

 \Prof_{2,r}(K_{2,N}^{L,Q}(c))
 \le C_{\Gamma,D,\sigma,r}
 \omega_\sigma(R_+)R_-^{D/r},
\end{equation}
where $R_-^{D/r}=1$ at $r=\infty$.  For $N\ge M\ge1$,
\begin{align}

 &\Prof_{2,r}\bigl(
 K_{2,N}^{L,Q}(c)-K_{2,M}^{L,Q}(c)
 \bigr)\notag\\
 &\qquad\le C_{\Gamma,D,\sigma,r}
 \omega_\sigma(R_+)R_-^{D/r}
 \min\left\{1,
 \left(\frac{R_+}{M}\right)^{\gamma/2}\right\}.
\end{align}

[Proposition 9 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] Fix $m \geq 1$, $A \geq 1$ and $\e \in (0,1)$, and let $H_T$ be as in (\ref{Eq.HeightFunction}). There exists a constant $C_1(m,A,\e) > 0$ such that for all $T \geq e$ and $t \in \mathbb{R}$
\begin{equation}

\sup_{x \in [-A, -T^{-\e}]} \E\ockets{\Abs{H_T(t, x)}^m} \le C_1(m,A,\e) \cdot (\log T)^{m/2}.
\end{equation}

