[Prop unmin of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Under the assumptions of Proposition (cormain of the paper), the following hold
\begin{enumerate}

\item[(i)] We have that
\begin{equation}
\begin{aligned}
&\inf_{\mu \in {\mathcal M }_1({\mathcal C }_\beta)}\Bigl\{I^{{\scriptscriptstyle{({\rm sym}})}}_{W,{\mathfrak m}}(\mu)-\langle \mu_{0,\beta},\log g\rangle\Bigr\}=\\
&\inf\limits_{q\in{\mathcal M }_1^{\ssup{{\rm s}}}(\mathbb{R}^d\times\mathbb{R}^d)}\Big\{H(q|\overline{q}\otimes{\mathfrak m})-\int_{\mathbb{R} ^d}\int_{\mathbb{R} ^d}\log \mathbb{E}^\beta_{x,y}\Big[e^{-\Tilde{W} }\Big]q({\rm d} x, {\rm d} y)-\langle g,\log g\rangle\Bigr\}.\\
\end{aligned}
\end{equation}

\item[(ii)] The unique minimizer of the (non-normalized) rate function defined in Proposition (cormain of the paper) (i) is given by 
\begin{equation}
    \mu^*_{g,{\mathfrak m},W}=\int_{\mathbb{R}^d}\int_{\mathbb{R}^d}Q^{\beta}_{x,y}\circ B^{-1}q^*_{g,{\mathfrak m},W}({\rm d} x, {\rm d} y),
\end{equation}
where for $x,y \in \mathbb{R} ^d $, we define
\begin{equation}
    Q^\beta_{x,y}({\rm d} \omega):=\frac{1}{\mathbb{E}^\beta_{x,y}\big[e^{-\Tilde{W} }\big]}e^{-\Tilde{W}(\omega)}\mathbb{P}^\beta_{x,y}({\rm d} \omega),\qquad \omega \in {\mathcal C }_\beta,
\end{equation}
and $q_{g,{\mathfrak m},W}^*\in{\mathcal M }_1^{\ssup{{\rm s}}}(\mathbb{R}^d\times\mathbb{R}^d)$ is the unique minimizer of the formula on the right hand side of (equation infIg of the paper).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 (Theorem 2.3 of \cite{zhang2016central}) of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Suppose $\{Z_{n}\}$ converges to the constant $\theta^{*}$ almost surely, and that Assumptions~\eqref{gen_assump_dist_1} and \eqref{gen_assump_dist_3} are satisfied. Suppose $\rho>1/2$, and that
\begin{equation}
\sum_{i=0}^{n-1}\delta_{i}=o\left(\sqrt{n}\right) \text{ almost surely}.
\end{equation}
Then 
\begin{equation}
\sqrt{n}\left(Z_{n}-\theta^{*}\right)\convd N(0,\Sigma),
\end{equation}
where, with $\Gamma$ is the matrix mentioned in Assumption~\eqref{gen_assump_dist_3}, we set
\begin{equation}
\Sigma=\int_{0}^{\infty}\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\Gamma\left[\exp\left\{\left(J_{G}(\theta^{*})+I_{d}/2\right)u\right\}\right]^{t}du.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

