[Definition 43 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same parameters as in Definition \ref{Def.ParametersBulk}. Fix $m \in \mathbb{N}$, $t_1, \dots, t_m \in [0, \infty)$ with $t_1 < t_2 < \cdots < t_m$, and set $\mathcal{T} = \{t_1, \dots, t_m\}$. We also define for $t \in \mathcal{T}$ the quantity $T_{t} = T_t(N) =  \lfloor t N^{2/3} \rfloor$ and the lattice $\Lambda_t(N) = a_t(N) \cdot \mathbb{Z} + b_t(N)$, where 
\begin{equation}
a_t(N) = \sigma_1^{-1} N^{-1/3}, \mbox{ and } b_t(N) = \sigma_1^{-1} N^{-1/3} \cdot \left( - h_1 N - p_1 T_{t} \right).
\end{equation}

We let $\mathbb{P}_N$ be the Pfaffian Schur process from Definition \ref{Def.SchurProcess}. Here, we assume that $M = M(N)$ is sufficiently large so that $M \geq T_{t_m}$. If $(\lambda^0, \dots, \lambda^M)$ have law $\mathbb{P}_N$, we define the random variables
\begin{equation}
X_i^{j,N} = \sigma_1^{-1} N^{-1/3} \cdot \left( \lambda_i^{T_{t_j}} - h_1 N - p_1 T_{t_j}  - i\right) \mbox{ for } i \in \mathbb{N} \mbox{ and } j \in \llbracket 1, m \rrbracket.
\end{equation}

