[Thm 15 of arXiv:2506.18834, '\large\bf On the random-time and finite-time ruin probability for widely dependent claim s'] In a nonstandard renewal risk model, let $Y_i,i\geq 1$ be WUOD random variables
with dominating coefficient $g_{U,G}(n)$ for all $n\ge1$ and $EY_1^r<\infty$ for some $r>1$.

(1) If $G\in\mathcal{C}$ and
\begin{eqnarray}
g_{U,G}(n)=o(n^d)\ \ \ \ \ \text{for some}\ \ \ \ d>0,
\end{eqnarray}
then for each $\gamma>\mu_G$,
\begin{eqnarray}
\limsup\limits_{n\to\infty}\sup\limits_{x\ge\gamma n}P(S^G_n>x)\big(n\overline{G}(x)\big)^{-1}
\le\overline{G^*}\big((r-1)(J^+_G+d-1)^{-1}\big)\overline{G_*}^{-1}((1-\mu_G\gamma^{-1})^{-1}).
\end{eqnarray}

(2) If condition (\ref{112}) is satisfied,

then
\begin{eqnarray}
\liminf\limits_{n\to\infty}\inf\limits_{x\ge\gamma n}P(S^G_n>x)\big(n\overline{G}(x)\big)^{-1}\ge1.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.03669, 'Volterra Integral Reduction \\ for Boundary Diffusion Problems'] For every compact set $K\subset\mathbb R$, the spatial derivative of the
transition density $p(t,x,y)$ admits, as $t\to0^+$, the asymptotic expansion
\begin{equation} 
\partial_x p(t,x,y)
=
e^{-d^2(x,y)/(2t)}\!\left[
c_0(x,y)\,t^{-3/2}
+
c_1(x,y)\,t^{-1/2}
+
O_K\!\left(
t^{1/2}
\right)
\right],
\end{equation}
uniformly for $(x,y)\in K\times K$, in which $c_0(x,y)$ and $c_1(x,y)$ are explicit coefficients given in Remark~\ref{rem:coefficients}, while $d(x,y)$ is a suitable distance defined in Lemma~\ref{lemma:BB}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 17 (Martingale Criterion) of arXiv:2606.04245, 'Properties of a Special Type of Filtration and its Martingale Criteria'] Let $\cT=\{t\in\RR_+:\PP(\gamma\geq t)>0\}$. 
    Let $F=(F_t)_{t\in\cT}$ be an $\cH$-measurable process with càdlàg paths, and let $L$ be an arbitrary random variable.

    Consider the process $M=(M_t)_{t\in\RR_+}$ defined by the equality:
    \begin{equation}
       M_t =F(t)\ind_{\{t<\gamma\} }+L\ind_{\{t\geq \gamma\}}. 
    \end{equation}   
    Then the following statements are equivalent:
    \begin{enumerate}
        \item 
        The process $(M_t)_{t\in\cT}$ is a martingale.

        \item 
        For all $t\in\cT$, the integrability condition  \begin{equation}
            \EE(|M_t|)<\infty
        \end{equation}
        holds, and
        \begin{equation}
            \EE(M_t-M_0|\cH)=0\quad\text{a.s.}
        \end{equation}
    \end{enumerate}

[Prop 3 of arXiv:2607.01291, 'On perturbations that preserve the connectivity properties in tree percolations'] Let $C\subset[0,1]$ be a Cantor set. There is a constant $c>0$ and a sequence $\{q_n\}_{n\in\N}\subset(0,1)$ (allowed to depend on $C$) with $\prod_{n\in\N} q_n=0$, such that for all $\tfrac14\le\lambda\le\tfrac12$, $0<t<\tfrac12$,
\begin{equation}
    \p_{\bq}[o\longleftrightarrow \partial\T_{\lambda C+t}]>c\,.
\end{equation}

