[Definition 6 of arXiv:2506.14145, '\bf Global-in-time optimal control of stochastic third-grade fluids with additive noise'] A function  $\ub \in  \mathrm{C}([0,T]; \Drm(\A))\cap \mathrm{L}^{\infty}(0,T;\Drm(\A^{\frac32}))$  with $\partial_t\ub \in\mathrm{L}^{2}(0,T;\Drm(\A)),$ 
    is called a \emph{strong solution} to system \eqref{CTGF-Projected}, if for $\vb_0$, $\fb$ and $\zb$ satisfying \eqref{pathwise-regularity}, it satisfies 
	\begin{itemize}
		\item [(i)] for any $\psi\in \Hb,$ 
		\begin{align}
\left\langle\partial_t\Upsilon(\ub(t)),\psi\right\rangle &=-\int_0^t\langle\nu \A\ub(s) - (\alpha_1+\alpha_2) \Jcal(\ub(s)+\zb(s)) - \beta\Kcal(\ub(s)+\zb(s)),\psi\rangle\drm s
            \nonumber \\ &\quad  +\int_0^t b(\ub(s)+\zb(s),\psi(s),\Upsilon(\ub(s)+\zb(s))) \drm s  - \int_0^t b(\psi(s), \ub(s)+\zb(s),\Upsilon(\ub(s)+\zb(s)))  \drm s 
            \nonumber \\ &\quad  + \int_0^t(\fb(s)  +  \zb(s) +  (\theta+\alpha_1-\nu)\A\zb(s) + \theta\alpha_1 \A^2\z(s) ,\psi)\drm s,
		\end{align}
		for a.e. $t\in[0,T];$
		\item [(ii)] the initial data:
		$$\ub(0)=\vb_0 \ \text{ in }\ \Drm(\A^{\frac32}).$$
	\end{itemize}

