body:
[Proposition 22 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Given $f\in \cC^{3k}_p(\cB^1\cup \cB^2)$, with $\cB^1$ and $\cB^2$ Hilbert bases of $H_1$ and $H_2$. We set
    $y= (y_e)_{e\in\cB^2_p}$ a family of semicircular variables, if $\cB^2_p = (g_{e,i})_{e\in\cB^2,i\in [1,p]}$, we assume that 
    \begin{itemize}
        \item if $e\neq f$, then $y_{g_{e,i}}$ and $y_{g_{f,j}}$ are free for any $i,j$,
        \item otherwise, either $y_{g_{e,i}}=y_{g_{e,j}}$ for all $e\in\cB^2_p$, or $y_{g_{e,i}} $ and $y_{g_{e,j}}$ are free for all $e\in\cB^2_p$.
    \end{itemize}
    We define $\tr\big(f|\cB^1\big)$ the conditional expectation of $f$ knowing $y$ by
    $$ \left( \tr\big(f|\cB^1\big) \right)^{\cA} \colon x\in \cA_{c_1,\sa}^{\cB^1,p} \mapsto \tau\big(f^{\cA}(x,y)|\cA\big),$$
    where $y$ is taken to be free from $\cA$, and $\tau\big(\cdot|\cA\big)$ is the conditional expectation on $\cA$. Then $\tr\big(f|\cB^1\big)$ is an element of $\cC^k_p(\cB^1)$. Besides, there is a constant $C_{k,p}$ such that for all $R>0$,
    \begin{equation}

        \norm{\tr\big(f|\cB^1\big)}_{\cC^k(\cB^1),R} \leq C_{k,p} \norm{f}_{\cC^{3k}(\cB^1\cup\cB^2),R}.
    \end{equation}

