body:
[Theorem Theorem Existence of Limit Law of arXiv:2411.09260, 'The Hydrodynamic Limit of Hawkes Processes on Adaptive Stochastic Networks'] Let $\lbrace y_{\theta, \alpha\mapsto\beta}(t) \rbrace_{\theta\in \mathcal{E} \fatsemi \alpha,\beta \in \Gamma}$ be independent unit intensity Poisson counting processes.  For any $T > 0$, there exists a unique set of $\Gamma$-valued stochastic processes $\lbrace z_{\theta}(t) \rbrace_{\theta\in \mathcal{E}, t\leq T}$ that satisfy the following properties. Let $\lbrace z_{\theta,0} \rbrace_{\theta\in \mathcal{E}}$ be independent $\Gamma$-valued variables, such that
\begin{align}
\mathbb{P}\big( z_{\theta}(0) = \alpha \big) = \sum_{\beta\in\Gamma} \sum_{a\in \Gamma_E} \int_{\mathcal{E}} v_{\theta\eta}(\alpha,\beta,a) d\mu_{\mathcal{E}}(\eta).
\end{align}
For $t > 0$, define $z_{\theta}(t) = \alpha \in \Gamma$ precisely when
\begin{multline}
\mathbf{1}\lbrace z_{\theta}(0) = \alpha \rbrace + \sum_{\beta \neq \alpha} \bigg\lbrace y_{\theta, \beta\mapsto\alpha}\bigg( \int_0^t \mathbf{1}\lbrace z_{\theta}(s) = \beta \rbrace f_{\beta\mapsto\alpha}\big( \psi_{\theta,s}(z_{\theta},\mu_s) \big) ds \bigg)\\
- y_{\theta, \alpha\mapsto\beta}\bigg( \int_0^t \mathbf{1}\lbrace z_{\theta}(s) = \alpha \rbrace f_{\alpha\mapsto\beta}\big( \psi_{\theta,s}(z_{\theta},\mu_s) \big) ds \bigg) \bigg\rbrace = 1,
\end{multline}
and in the above $\mu_s \in \mathcal{P}\big(\mathcal{E} \times \mathcal{D}([0,s], \Gamma) \big)$ is such that for any measurable $A \subset \mathcal{E}$ and any measurable $B \subset  \mathcal{D}([0,s], \Gamma)$,
\[
\mu_s(A \times B) = \int_A \mathbb{P}\big( z_{\theta}([0,s]) \in B \big) d\mu_{\mathcal{E}}(\theta).
\]

