body:
[Theorem thm:leaves of arXiv:2607.24705, 'Derangetropy Operators'] Let $f, g \in \mathcal{D}_{+}(R)$. The following are equivalent:
		\begin{enumerate}[label=\normalfont(\roman*), leftmargin=*]
			\item $g$ is reachable from $f$ by finitely many coordinate
			derangetropy moves whose kernels are continuous and positive on
			the open unit interval, possibly degenerate at its endpoints;
			\item $g$ is reachable in at most three moves, one per coordinate
			and one revisit;
			\item $g = \varphi(x_{1})\,\psi(x_{2})\,f$ for continuous positive
			$\varphi, \psi$, a separable tilt;
			\item $f$ and $g$ have the same odds-ratio structure: for all
			$x, y \in R$,
			\begin{equation}
				\frac{f(x_{1},x_{2})\,f(y_{1},y_{2})}
				{f(x_{1},y_{2})\,f(y_{1},x_{2})}
				=
				\frac{g(x_{1},x_{2})\,g(y_{1},y_{2})}
				{g(x_{1},y_{2})\,g(y_{1},x_{2})},

			\end{equation}
			equivalently, for twice continuously differentiable densities,
			$\partial_{1}\partial_{2}\log f
			= \partial_{1}\partial_{2}\log g$.
		\end{enumerate}
		The classes $\mathcal{T}(f) := \{\varphi\psi f\}$ thus foliate
		$\mathcal{D}_{+}(R)$ with tangent distribution $\mathcal{H}$; the
		interaction function $\partial_{1}\partial_{2}\log f$ is a complete
		leaf invariant; the independent laws form a single leaf, consisting
		of all products on $R$; and that leaf is the unique one on which all
		coordinate moves commute. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 3 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Assume that $\eta$ has a standard normal distribution and set $s_n=2^{-1}\eee^{-n^2}$ for $n\in\mn$. Then there exists a sequence $(a_k)$ satisfying \eqref{eq:standing} for which
    \begin{equation}
        \limsup_{n\to\infty}\frac{\log|X(s_n)|-n\log 2}{\log\log n}=\frac{1}{2}\quad\text{{\rm a.s.}}
    \end{equation}
    and
    \begin{equation}
        \liminf_{n\to\infty}\frac{\log|X(s_n)|-n\log 2}{\log n}=-1\quad\text{{\rm a.s.}}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pr:mSHE-characterization of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] {parekh_moment_2025}}]
Let $(\ensuremath{\mathcal Z}_{s,t})_{s\le t}$ be a family of $\mathscr M(\mathbb{R}^2)$-valued random variables indexed by $-\infty <s\le t<\infty$ with $s,t \in \mathbb Q$, all defined on some complete probability space $(\Omega,\ensuremath{\mathcal F},\mathbb{P})$. Fix $\gamma >0$,  and suppose that the following conditions hold true:
\begin{enumerate}[(1)]
    \item $\ensuremath{\mathcal Z}_{s_j,t_j}$ are independent under $\mathbb{P}$ whenever $(s_j,t_j)$ are disjoint intervals.
    \item For all functions $f\in \ensuremath{\mathcal C}_c^\infty(\mathbb{R}^2)$, $\psi \in \ensuremath{\mathcal C}_c^\infty(\mathbb{R})$ with $\int_\mathbb{R}\psi=1$, and indices $s<t<u$, 
    \begin{equation}
    \begin{aligned}
    &\int_{\mathbb{R}^4} \varepsilon^{-1}\psi(\varepsilon^{-1}(y_1-y_2))\, f(x,z)\, \ensuremath{\mathcal Z}_{t,u}({\rm d} y_1,{\rm d} z)\ensuremath{\mathcal Z}_{s,t}({\rm d} x,{\rm d} y_2)\\
    &\qquad\xrightarrow[\varepsilon\to 0]{\mathbb{P}} \int_{\mathbb{R}^2} f(x,z)\,\ensuremath{\mathcal Z}_{s,u}({\rm d} x,{\rm d} z)\; \text{,}\;\;
    \end{aligned}
    \end{equation}
    where the above convergence holds in $\mathbb{P}$-probability.
    \item For all integers $k\ge 1$, functions $\phi,\psi \in \ensuremath{\mathcal C}_c^\infty(\mathbb{R})$, and indices $s<t$,
    \begin{equation}
    \begin{aligned}
&\mathbb{E}\bigg[\bigg(\int_{\mathbb{R}^2}\phi(x)\psi(y)\,\ensuremath{\mathcal Z}_{s,t}({\rm d} x,{\rm d} y)\bigg)^k\bigg]\\
&= \int_{\mathbb{R}^k} \prod_{j=1}^k \phi(x_j)\mathbf E_{(x_1,\ldots,x_k)}^{{\rm BM}^{\otimes k}}\bigg[\exp\bigg\{\gamma^2 \sum_{1\le i<j\le k} L_{t-s}^{W^i-W^j}\bigg\}\prod_{j=1}^k \psi(W_{t-s}^j)\bigg]{\rm d} x_1\cdots {\rm d} x_k\; \text{,}\;\;
\end{aligned}
    \end{equation}
    where, as before (see, e.g., the text above Proposition (pr:second-moment of the paper)), the expectation is with respect to a $k$-dimensional standard Brownian motion $\mathbf W=(W^1,\ldots,W^k)$ started at $\mathbf x\in \mathbb{R}^k$, while $L_t$ stands for the local time at the origin in the time interval $[0,t]$ for the process in the superscript.
\end{enumerate}

Then, there exists a $\ensuremath{\mathcal C}(\mathbb{R}_\uparrow^4)$-valued random element $\tilde \ensuremath{\mathcal Z}=(\tilde \ensuremath{\mathcal Z}_{s,t}(x,z))_{(s,t,x,z)\in \mathbb{R}_\uparrow^4}$, defined on the same probability space and satisfying, for every $\psi\in \ensuremath{\mathcal C}_c(\mathbb{R})$, $\phi\in \ensuremath{\mathcal C}_b(\mathbb{R})$, and $s<t$ in ${\mathbb Q}$, 
\begin{equation}
 \ensuremath{\mathcal Z}_{s,t}(\psi\otimes \phi)= \int_{\mathbb{R}^2}\psi(x)\phi(z)\,\tilde \ensuremath{\mathcal Z}_{s,t}(x,z)\,{\rm d} x{\rm d} z\; \text{,}\;\;\qquad \mathbb{P}\text{-a.s.}\; \text{.}
\end{equation}
Furthermore, on the same probability space, there exists a space-time white noise $\xi$ on $\mathbb{R}^2$, with the property that $(\tilde \ensuremath{\mathcal Z}_{s,t})_{s\le t}$ is the \textit{propagator} of the multiplicative ${\rm SHE}$ in (equation eq:mSHE of the paper), driven by $\xi$ and with noise coefficient $\gamma>0$. More precisely, for all $s,x \in \mathbb{R}$, 
\begin{equation}
(t,y)\in (s,\infty)\times \mathbb{R}\longmapsto \tilde \ensuremath{\mathcal Z}_{s,t}(x,y)
\end{equation}
is, $\mathbb{P}$-a.s., the It\^o--Walsh solution to the equation in (equation eq:mSHE of the paper) started from $s$ with initial datum $\delta_x$. Further,
$t\longmapsto \tilde \ensuremath{\mathcal Z}_{s,t}(x,{\,\cdot\,})$ may be realized as a process in $\ensuremath{\mathcal C}([s,\infty),\ensuremath{\mathcal M}_f(\mathbb{R}))$.

Consequently, for any finite collection of indices $s_1\le t_1, \ldots, s_m\le t_k$ in ${\mathbb Q}$, the finite-dimensional laws $(\ensuremath{\mathcal Z}_{s_1,t_1},\ldots, \ensuremath{\mathcal Z}_{s_m,t_m})$ are uniquely determined by the conditions in (it:SHE1 of the paper)--(it:SHE3 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2604.23610, 'Scaling limits of Lévy walks with random velocities'] Let $\left\{\mathbf{J}_i\right\}_{i\geq 1}$ be defined as in Eq. \eqref{jumpdef}. Then, we have the following
    \begin{equation}
    n^{-1/\alpha^*}\sum_{i=1}^{\left[nt\right]} \mathbf{J}_i \overunderset{\mathbb{J}_1}{n \to \infty}{\to } \mathbf{L}_{\alpha^*}\left(t\right),
\end{equation}
where $\mathbf{L}_\alpha\left(t \right)$ is described by L\'evy triplet
\begin{equation}
    \left[\int_{\mathbf{x}\neq\mathbf{0}}\frac{\mathbf{x}}{1+\left\|\mathbf{x}\right\|^2}\nu_{L_{\alpha^*}}\left(d\mathbf{x}\right), \mathbf{0}, \nu_{L_{\alpha^*}}\left(d\mathbf{x}\right)=\int_{\mathbf{D}}\frac{\alpha^* r^{-\alpha^*-1}}{\Gamma\left(1-\alpha^*\right)}\mathbf{1}_{\left\{r>0\right\}}\mathbf{\Lambda}\left(d\mathbf{u}\right)\right],
\end{equation}
and $\alpha^* = \min\left\{\alpha, \beta\right\}$.
\begin{proof}
    Applying Lemma \ref{auxlemma1} and Eq. \eqref{auxilaryjumpslimit} to jumps, we obtain the thesis.
\end{proof}
\noindent The next result shows the behavior of the tails of the product of random variables $T$ and $V$, which represent waiting times and velocities respectively in the critical case $\alpha=\beta$.
\begin{lemma}
    Let $V, T$ be independent, positive heavy-tailed random variables with the same index of stability $\alpha$. Then
\begin{equation}
    \mathbb{P}(VT > z) \sim \alpha z^{-\alpha}\log z, \quad \text{as } z \to \infty.
\end{equation}
\begin{proof}
By the definition of asymptotic equivalence, for any arbitrarily small $\epsilon > 0$, there exists a sufficiently large $M > 0$ such that for all $x \ge M$, we have
\begin{equation}
    (1-\epsilon)x^{-\alpha} \le \bar{F}_V(x) \le (1+\epsilon)x^{-\alpha}.
\end{equation}
Using the law of total probability and the conditioning on $T = x$, the tail of the product is given by
\begin{equation}
    H(t) = \mathbb{P}(T V > t) = \int_0^\infty \mathbb{P}(V > t/x) dF_T(x) = \int_0^\infty \bar{F}_V(t/x) dF_T(x).
\end{equation}
Assume $t$ is large enough such that $t > M^2$ (which implies $M < t/M$). We split the integral in Eq. \eqref{eqint} into three parts
\begin{equation}
    H(t) = \int_0^M \bar{F}_V(t/x) dF_T(x) + \int_M^{t/M} \bar{F}_V(t/x) dF_T(x) + \int_{t/M}^\infty \bar{F}_V(t/x) dF_T(x) = I_1(t) + I_2(t) + I_3(t).
\end{equation}
First, let us analyze $I_1(t)$. Since $x \in (0, M]$, thus we have $t/x \ge t/M \ge M$. Applying the upper bound from \eqref{eq:epsilon_bound}, we have
\begin{equation}
    I_1(t) \le \int_0^M (1+\epsilon)(t/x)^{-\alpha} \, dF_T(x) = (1+\epsilon)t^{-\alpha} \int_0^M x^\alpha \, dF_T(x).
\end{equation}
Because $\int_0^M x^\alpha \, dF_T(x)\le M^{\alpha}\int_0^M dF_T(x)\leq M^{\alpha}$, where $M^{\alpha}$ is a finite constant independent of $t$, thus $I_1(t) = \mathcal{O}(t^{-\alpha})$. For $I_3(t)$, we use the trivial bound that probability is not greater than $1$ and obtain
\begin{equation}
    I_3(t) = \int_{t/M}^\infty \mathbb{P}(V > t/x) \, dF_T(x) \le \int_{t/M}^\infty 1 \, dF_T(x) = \bar{F}_T(t/M).
\end{equation}
Since $t/M \ge M$, thus $\bar{F}_T(t/M) \sim (t/M)^{-\alpha} = M^\alpha t^{-\alpha}$. Therefore, $I_3(t) = \mathcal{O}(t^{-\alpha})$. \\
Since both $I_1(t)$ and $I_3(t)$ lack a logarithmic factor, they are negligible compared to $t^{-\alpha} \log(t)$ as $t \to \infty$. Now, we analyze $I_2(t)$. The integration limits ensure that both $x \ge M$ and $t/x \ge M$. We can therefore apply the bounds from \eqref{eq:epsilon_bound} to the integrand $\bar{F}_V(t/x)$
\begin{equation}
    (1-\epsilon) t^{-\alpha} \int_M^{t/M} x^\alpha \, dF_T(x) \le I_2(t) \le (1+\epsilon) t^{-\alpha} \int_M^{t/M} x^\alpha \, dF_T(x).
\end{equation}
Let $J(y) = \int_M^y x^\alpha \, dF_T(x)$ where $y = t/M$. Using integration by parts and noting that $dF_T(x) = -d\bar{F}_T(x)$, we have
\begin{equation}
\begin{aligned}
    J(y) &= -\int_M^y x^\alpha \, d\bar{F}_T(x) = -\left( \left[ x^\alpha \bar{F}_T(x) \right]_M^y - \int_M^y \bar{F}_T(x) \, d(x^\alpha) \right) \\
         &= M^\alpha \bar{F}_T(M) - y^\alpha \bar{F}_T(y) + \int_M^y \bar{F}_T(x) \alpha x^{\alp (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2608.21905, '\bf Ruin theory incorporating MIPP-type jumps'] Assume that $c>\lambda^nm$. The survival probability $\Lambda_n(x)$ is continuous on $\mathbb{R}_+$, possessing right and left derivatives denoted by $\Lambda_n^{+}(x)$ and $\Lambda_n^-(x)$, respectively. In addition, we have
\begin{equation}
\begin{split}
 c\Lambda_n^{+}(x)&=\lambda q_{n-1}\Lambda_n(x)-\lambda\sum_{k=1}^{\infty}P(V_1^{(n-1)}=k)\int_0^x\Lambda_n(x-y)dF^{*k}(y),\\
 c\Lambda_n^-(x)&=\lambda q_{n-1}\Lambda_n(x)-\lambda\sum_{k=1}^{\infty}P(V_1^{(n-1)}=k)\int_0^{x_-}\Lambda_n(x-y)dF^{*k}(y).
\end{split}
\end{equation}

