[Lemma lem:f-basic of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] For $j=1,2$, the functions $F^{(j)}(y_1,y_2,x_1,x_2,x_3)$ are finite and locally bounded. Furthermore, for $\eta$ sampled from $\mu_{\mathbbm{H},y_1, y_2}^\#$ and parameterized by its half-plane capacity, let $g_t:\mathbbm{H}\setminus\eta_t\to\mathbbm{H}$ be the corresponding Loewner map such that $g_t(\eta_t)=W_t$. Then
\begin{equation}
M_t^{(j)}(y_1,y_2,x_1,x_2,x_3):=\left(\prod_{i=1}^3|g_t'(x_i)|^h\right)\cdot F^{(j)}(W_t,g_t(y_2),g_t(x_1),g_t(x_2),g_t(x_3))
\end{equation}
is a continuous local martingale.

[Lemma 44 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ and $d\neq 6$, there exist $\Cl,\Cl, \Cl,\cl>0$ such that for any $v\neq v'\in \widetilde{B}(\Cref{const_additional_lemma_four_point1})$, any sufficiently large $N\ge 1$, and $w,w'\in \widetilde{B}(10N)\setminus \widetilde{B}(N)$ with $|w-w'|\ge N$, 
	 	\begin{equation}
	 		\mathbb{P}\big( \widehat{\mathsf{H}}_{v',w'}^{v,w}   \big)\gtrsim |v-v'|^{\frac{3}{2}}N^{-[(\frac{3d}{2}-1)\boxdot (2d-4)]},
	 	\end{equation}
	 	where $\widehat{\mathsf{H}}_{v',w'}^{v,w}$ is defined as $\mathsf{H}_{v',w'}^{v,w} \cap \{v\xleftrightarrow{\ge 0} \partial B(\Cref{const_additional_lemma_four_point2}N)  \}^c \cap \{v' \xleftrightarrow{\le 0} \partial B(\Cref{const_additional_lemma_four_point2}N) \}^c 
			 	  \cap \big\{ |\widetilde{\phi}_{v}|,|\widetilde{\phi}_{v'}| \in [\cref{const_additional_lemma_four_point4}, \Cref{const_additional_lemma_four_point3}] \big\} $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2604.13454, 'Invariant and periodic measures in classical spin systems on infinite lattices with highly'] Let $P\in Pr(\Omega_{Spin})$ be such that 
        \begin{equation*}
            P(C([0,\infty);\ell^{2\theta}_{\rho,\sigma}(\mathbb{Z^+}))\bigcap \Omega_{Spin})=1.
        \end{equation*}
        Then, for any given $t\geq 0$, the canonical process $X(t,\omega)=\omega(t)$ has a $P$-modification on $\mathscr{B}_t$ which is $\mathscr{B}_t$-measurable with values in $(\ell^{2\theta}_{\rho}(\mathbb{Z^+}),\mathscr{B}(\ell^{2\theta}_{\rho}(\mathbb{Z^+})))$, where $\mathscr{B}(\ell^{2\theta}_{\rho}(\mathbb{Z^+}))$ is the Borel $\sigma$-field of $\ell^{2\theta}_{\rho}(\mathbb{Z^+})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def eq2 of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call  a stochastic process
\begin{align*}
\tilde y\in L_{{\mathbb{F}}}^2(\Omega;C([0,T];L^2_{\rm loc}(G)))\cap L_{{\mathbb{F}}}^2(0,T;H^1_{\rm loc}(G))
\end{align*}
a solution to the equation (system-sp1 of the paper) if for any
$t\in[0,T]$, $\widehat G\subset\!\subset G$ and $\rho\in H_0^1(\widehat G)$, it holds that
\begin{align} \notag
& \int_{\widehat G}\tilde y(t,x)\rho(x)dx-\int_{\widehat G}\tilde y(0,x)\rho(x)dx
\\ \notag
& = \int_0^t\int_{\widehat G} \!\Big[\!-\!\sum_{j,k=1}^n b^{jk}
\tilde y_{x_j}(s,x)\rho_{x_k}(x) \!+\!\tilde a_1\cdot \nabla \tilde y(s,x)\rho(x)
\!+\! \tilde a_2     \tilde y(s,x)\rho(x)     \Big]dx ds
\\
& \quad +\int_0^t\int_{\widehat G} \tilde a_3 \tilde y(s,x)\rho (x) dx dW(s), \quad ~ \text{${\mathbb{P}}$-a.s.}
\end{align}

