[Theorem 13 (Predictive stability for GPs) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Let $P$ and $Q$ be Gaussian process laws on $L^2(\bP_X)$. Then there exists an absolute constant $L_{\cM}>0$ such that
    \begin{equation}
    \cM_t(Q)-\cM_t(P)
    \le  L_{\cM}\cbr{ \W(P,\delta_{f^\star})\W(P,Q)+\W(P,Q)^2+\overline v(P,Q)\W(P,\delta_{f^\star})^2 }
\end{equation}
with $\overline v(P,Q):=\sup_{x\in\cX}\{v_P(x)+v_Q(x)\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 44 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] There exists a constant $g_0 = g_0(\mu) \geq 1$ such that if $\epsilon \geq n^{-1/3}$, $\beta \epsilon \geq (n \log n)^{1/\alpha}$ and $p_0 = (1 + g_0 \epsilon )/n$, then
\begin{equation}
    \widehat{\E}[ \diam(\cT)] = \widehat{\E}\Big[ \diam\Big( \ClCp{1}{p_0} \Big) \Big] + \bigO{\frac{n^{1/3}}{\sqrt{\epsilon n^{1/3}}}}. 
\end{equation}
Furthermore,
\begin{equation}
    \diam\Big(\ClCp{1}{p_0} \Big) \leq  \diam (\cT ) \leq \diam\Big( \ClCp{1}{p_0} \Big) + \bigO{\frac{n^{1/3}}{\sqrt{\epsilon n^{1/3}}} + (\log n)^6} 
\end{equation}
with $\widehat{\P}$-probability at least
\begin{equation*}
    1 - \bigO{\exp \Big(- \frac{1}{4} \sqrt{g_0 \epsilon n^{1/3}} \Big)} - \bigO{\frac{1}{n}}. 
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

