body:
[Definition def:proj of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Given $\tt u\in\R$ and some force coefficients $(\mathfrak{z}^\tau)^{\tau\in\mathcal{T}_*}$, we define the projector $\Pi$ acting on functionals $L:C^\infty([0,1],\R^{\mcb{n}})\longrightarrow C^\infty([0,1],\R^{\mcb{n}})$ of the form 
\begin{equs}
    L[v](t)=\sum_{\tau\in\mathcal{T}_*}\int_{\R^{\mathfrak{s}(\tau)}}\langle \mathfrak{z}^{\tau}(t,s^{\tau}),\Upsilon^{\tau}[v+{\tt u}](s^{\tau})\rangle_{\mathcal{H}^{\tau}}\mathrm{d} s^{\tau}\,,
\end{equs}
by projection onto $\mathcal{T}$. More precisely, we have
\begin{equs}
    \Pi L[v](t)\eqdef\sum_{\tau\in \mathcal{T}} \int_{\R^{\mathfrak{s}(\tau)}}\langle \mathfrak{z}^{\tau}(t,s^{\tau}),\Upsilon^{\tau}[v+{\tt u}](s^{\tau})\rangle_{\mathcal{H}^{\tau}}\mathrm{d} s^{\tau}\,.
\end{equs}
Finally, we also define an operator $\mathrm{Pol}_\mu$ acting on families $(L_\mu)_{\mu\in(0,1]}$ of functionals of the form (equation eq:formL of the paper) -- where the $(\mathfrak{z}^\tau)^{\tau\in\mathcal{T}_*}$ is replaced with $(\mathfrak{z}^\tau_\mu)^{\tau\in\mathcal{T}_*}_{\mu \in (0,1]}$ -- by
\begin{equs}
    \mathrm{Pol}_{\mu}(L_\mu)[]\eqdef\Pi\big(\d_\mu L_\mu[]+ \mathrm{D} L_\mu\big[,\dot G_\mu L_{\mu}[]\big]\big)\,.
\end{equs}
Note that $\mathrm{Pol}_{\mu}$ is a truncated version of the Polchinski flow equation.

[Theorem thm:extension of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] Let $n\geqslant 2$ be an integer, and let $K\geqslant 0$. Let $(X,\mathrm{d},\mathcal{H}^n)$ be an $\mathrm{RCD}(-K,n)$ space. Let us assume the following:
    \begin{enumerate}
        \item There is a closed set $\Sigma \subset X$ with Assouad codimension greater than $2$ (see (def:Codimension of the paper)) such that $X\setminus\Sigma$ is a smooth Riemannian manifold;
        \item $|\mathrm{Ric}| \leqslant K$ on $X\setminus \Sigma$.
    \end{enumerate}
    Let $X^{\mathrm{reg}}$ be the set of regular points of $X$. Then $X^{\mathrm{reg}}$ is open, and has the structure of a $C^{1,\alpha}$-Riemannian manifold for any $\alpha < 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop_17 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $r(A)\geq 3$, $\lambda_1,\cdots, \lambda_k$ be as in ((poloi_1 of the paper)) and $r(A)-k$ be even. If 
\begin{eqnarray}

t+b_k\ge0,
\end{eqnarray}
then 

\begin{eqnarray}

&&\Pr(\boldsymbol{\Delta}>t)\leq \Big(1+\frac{t+b_k}{(r(A)-k)a_k}\Big)^{\frac{r(A)-k}{2}}e^{-\frac{t+b_k}{2a_k}}\notag\\ 
&&\hskip2.5cm\times \sum_{\substack{i_0,i_1,\cdots, i_k\ge0\\ i_0+i_1+\cdots+i_k=\frac{r(A)-k}{2}}}c_{i_0,i_1,\cdots, i_k}\prod_{j=1}^k\frac{(\frac{-\lambda_j}{a_k})^{i_j}}{\big(n-k+\frac{t+b_k}{a_k}\big)^{i_j}(\frac{-\lambda_j}{a_k}+1)^{i_j+\frac{1}{2}}},
\end{eqnarray}

where $a_k, b_k$ are given in ((a_k_b_k of the paper)), the coefficients $c_{i_0,i_1,\cdots, i_k}$ are defined by 
\begin{eqnarray}
c_{i_0,i_1,\cdots, i_k}=\frac{(\frac{r(A)-k}{2})!}{i_0!i_1!\cdots i_{k}!}\prod_{j=1}^k(2i_j-1)!!
\end{eqnarray}
and the double factorial notation is given by
\begin{eqnarray}

(2i-1)!!=\left\{\begin{array}{cc}
    1  &  i=0  \\
    1\times 3\times 5\times\cdots\times (2i-1)  &   i\geq 1
\end{array}\right..
\end{eqnarray}

[Proposition prop: conv-zeta-signed of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] The balanced Whitney number polynomial may be obtained by the convolution of the deformed character $\zeta_x$:
\begin{equation}
 w_\Sigma^b(x,2t) = \zeta^{\ast t}_x (\Sigma).
\end{equation}

