body:
[Lemma interpolation of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] For $t \geq 0$, let $\mathcal{X}_t:=\{X_t(v):v\in \mathcal{N}_t\}$ and $\bar{\mathbf{v}}$ the effective drift. Fix $T>0$ and $\kappa>0$. Consider the event
    \begin{equation*}
        A_n:=\Bigl\{\sup_{\ell \in [nT,(n+1)T]} d_\mathrm{H}(\mathcal{X}_{nT}- nT \bar{\mathbf{v}},\mathcal{X}_\ell-\ell\bar{\mathbf{v}})> \kappa nT \Bigl \}, 
    \end{equation*}
    then, $\sum_{n=1}^\infty \left(\sup_{x\in \mathbb{R}^d} \proba{x}{}{A_n}\right) < + \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem ++ of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\beta> 0$ and $L\geq 1$. There exist measures $\langle \cdot \rangle^{+,+}_{\mathcal{R}(L),\beta}$ and $\langle \cdot \rangle^{+,-}_{\mathcal{R}(L),\beta}$ such that 
\begin{equation}
\lim_{M\to\infty}\langle \cdot \rangle^{+,+}_{\mathcal{R}(L,M),\beta}=\langle \cdot \rangle^{+,+}_{\mathcal{R}(L),\beta}  \quad \text{and} \quad \lim_{M\to\infty}\langle \cdot \rangle^{+,-}_{\mathcal{R}(L,M),\beta}=\langle \cdot \rangle^{+,-}_{\mathcal{R}(L),\beta},
\end{equation}
where the limits hold in the weak sense.
Furthermore, for every $x\in \{-L,\ldots,L\}^{d-1}$ we have 
\begin{equation}
\lim_{N\to\infty} \langle \tau_{(x,N)} \rangle^{+,-}_{\mathcal{R}(L),\beta}=\langle \tau_{(x,0)} \rangle^{+,+}_{\mathcal{R}(L),\beta} \quad \text{and} \quad \lim_{N\to\infty} \langle \tau_{(x,-N)} \rangle^{+,-}_{\mathcal{R}(L),\beta}=-\langle \tau_{(x,0)} \rangle^{+,+}_{\mathcal{R}(L),\beta}.
\end{equation}

[Lemma lem:exponential1 of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Let $Y_0 = \mu + m\delta_{x_0}$ with $\mu \in \mathcal{M}_F^+$, $x_0 \in \mathbb{R}$ and $m \in \mathbb{N}\cup\{ \infty\}$. Furthermore, let $I_t(Y_0)$ be defined as in (equation eq:defI_t of the paper). Then for every $\gamma > 0$, $K>0$, there exists $T_0 >0$ such that 
		\begin{equation}
			\sup_{\nu: \nu((0,\infty]) \leq K} \mathbb{E}[ \ee^{\gamma |I_t(Y_0)|}] < \infty,
		\end{equation}
	for all $t \leq T_0$ . Hereby, $T_0>0$ depends only on $K$, $\langle \mu,1\rangle$ and $\gamma$.

