body:
[Prop poc of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions \mbox{\normalfont  (asum:ic of the paper)} to \mbox{\normalfont  (asum:con of the paper)}    are satisfied, then the rate of convergence of the interacting particle system (equation eq:int of the paper) to the non-interacting particle system (equation eq:non-int of the paper)  is given~by
		\begin{align*}
			\sup_{i\in\{1,\ldots,N\}}\,\,\sup_{ t\in[0,T]}E|x_t^i-x_t^{i, N}|^2\leq K
			\begin{cases}
				N^{-1/2}, & \mbox{ if }  d <4,
				\\
				N^{-1/2}\ \log_2 N, & \mbox{ if } d=4,
				\\
				N^{-2/d}  &  \mbox{ if }d>4,
			\end{cases}
		\end{align*}
		where $K>0$ is a constant independent of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Introducing
\begin{equation}
    \mu_{M,\bar{M}} := \inf_{(u,w)\in \mathcal{I}_{M,\bar{M},rad}(\mathbb{B}_R)} \mathcal{L}(u,w) \in [-\infty,\infty)\,, \quad \bar{M}\ge M>0\,, 
\end{equation}
with $\mathcal{I}_{M,\bar{M},rad}(\mathbb{B}_R)$ defined in~\eqref{IS}, there holds:
\begin{equation}
\begin{split}
    \mu_{M,\bar{M}} & = -\infty \;\;\text{ for }\;\; \bar{M}\ge M>M_c\,,\\ 
    \mu_{M,\bar{M}} & > -\infty \;\;\text{ for }\;\; M\in (0,M_c] \;\text{ and }\;\bar{M}\ge M\,.
\end{split}
\end{equation}
More precisely, in the second case, there is $c_0=c_0(d,R)>0$ such that, for all $(u,w)\in \mathcal{I}_{M,\bar{M},rad}(\mathbb{B}_R)$,
\begin{equation}
\begin{split}
    \mathcal{L}(u,w) \ge \frac{1}{2} \left( 1 - \left( \frac{M}{M_c} \right)^{2/d} \right) \|\nabla\mathcal{K}[w-\langle w\rangle]\|_2^2 - c_0 \frac{M\bar{M}}{|\mathbb{B}_R|} - \frac{mM}{m-1}\,. 
\end{split}
\end{equation}

[Proposition 20 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] Let $A \subset T$ be given, and let $S=\{s_1,\ldots,s_n\} \subseteq A$ be a $4\sigma$-packing of $A$, i.e., $d(s_i,s_j) \ge 4\sigma$ for all distinct $i,j$. Then the following inequality holds with some universal constant $c<1$:
  \begin{align*}
    \sup_{\mu \in \eP(A)} \eF_\beta(X;\mu)
    \ge c \sigma \sqrt{\eta(n,\sigma \beta)} + 
    \min_{i\le n} \sup_{\mu \in \eP(B(s_i,\sigma))} 
    \eF_\beta(X;\mu).
  \end{align*}

