body:
[Thm 35 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Consider $\ind_{\Ns_{\varepsilon}(A)}$ the Lebesgue measure on 
$\Ns_{\varepsilon}(A)$ (indicator function).
It satisfies the following asymptotic expansion:
for every $N\geq 0$,
\begin{equation}

\ind_{\Ns_{\varepsilon}(A)}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\psi_{2k+1,A}}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+~R_{N,\varepsilon},
\end{equation}
where the error term $R_{N,\varepsilon}$ satisfies, as $\varepsilon \to 0$,
\begin{displaymath}
\forall \eta >0,~
\E\big[\Vert R_{N,\varepsilon} \Vert_{H^{-\eta}(\C)}^{2}\big]^{1/2}
=\, o (\vert\log \varepsilon\vert^{-(N+1/2)}).
\end{displaymath}
As for the Lebesgue measure on $\widetilde{\Ns}_{\varepsilon}(A)$,
fix a deterministic smooth cutoff function $f_{0}:D\rightarrow [0,1]$, compactly supported in $D$.
Then  $\ind_{\widetilde{\Ns}_{\varepsilon}(A)}f_{0}$ satisfies the following asymptotic expansion:
for every $N\geq 0$,
\begin{equation}

\ind_{\widetilde{\Ns}_{\varepsilon}(A)}f_{0}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{f_{0}\,\tilde{\psi}_{2k+1,A}}{\big(\frac{1}{2\pi}
\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+~\widetilde{R}_{N,\varepsilon, f_{0}},
\end{equation}
where
\begin{equation}

\tilde{\psi}_{2k+1,A} = 
\sum_{j=0}^{k} \dfrac{(2k+1)!}{2^{j} j! (2(k-j)+1)!}
\,\Big(\dfrac{1}{2\pi} \log \CR(z,D)\Big)^{j}\,\psi_{2(k-j)+1,A},
\end{equation}
and the error term $\widetilde{R}_{N,\varepsilon, f_{0}}$ satisfies, as $\varepsilon \to 0$,
\begin{displaymath}
\forall \eta >0,~
\E\big[\Vert \widetilde{R}_{N,\varepsilon, f_{0}} \Vert_{H^{-\eta}(\C)}^{2}\big]^{1/2}
=\, o (\vert\log \varepsilon\vert^{-(N+1/2)}).
\end{displaymath}
Further assume that
\begin{eqnarray}

\forall \beta >0,~
\operatorname{Leb}(\{ z\in D \vert \,d(z,\partial D)<\varepsilon\}) 
= o(\vert \log\varepsilon\vert^{-\beta})
\text{ as } \varepsilon\to 0.
\end{eqnarray}
Then for every $N\geq 0$,
\begin{equation}

\ind_{\widetilde{\Ns}_{\varepsilon}(A)}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\tilde{\psi}_{2k+1,A}}{\big(\frac{1}{2\pi}
\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+~\widetilde{R}_{N,\varepsilon},
\end{equation}
where the error term $\widetilde{R}_{N,\varepsilon}$ satisfies, as $\varepsilon \to 0$,
\begin{displaymath}
\forall \eta >0,~
\E\big[\Vert \widetilde{R}_{N,\varepsilon} \Vert_{H^{-\eta}(\C)}^{2}\big]^{1/2}
=\, o (\vert\log \varepsilon\vert^{-(N+1/2)}).
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 7 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] A sequence $(X^n)_{n\in\mathbb{N}}$ of $\mathbb{A}\text{-valued}$ random variables satisfies the {\bf Aldous criterion} if and only if the following holds
\begin{itemize}
    \item[{\bf [A]}]  
    {For all
    $\epsilon>0$ and $\delta >0$}, there exist $\theta_0 > 0$ and $n_0 \in \mathbb{N}$ such that if $\theta \leq \theta_0$ and $n\geq n_0$ and if $\tau$ is a discrete  $\mathfrak{F}\text{-stopping}$ time satisfying  $\tau \leq T$, one has 
    \begin{align*}
        \sup_{n\geq n_0}\sup_{0\leq \theta \leq \theta_0}\mathbb{P}\Big\{\rho\big( X^n_{(\tau+\theta)\wedge T},X^n_{\tau}\big)\geq {\delta} \Big\} \leq \epsilon.
    \end{align*}
\end{itemize}

[Lemma lem_Gronwall_bounded of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Let $(\gamma_k)_{k\ge 1}$ be a nonincreasing
		sequence of positive numbers such that $t_k=\sum_{i=1}^k \gamma_i \to_{k\to
			\infty}+\infty$ and $\gamma_k\to_{k\to \infty}0$. Let $(f_{k})_{k\in \mathbb{
				N}}\in {\mathbb{R}}_+^{\mathbb{N}}$, such that there exists $K\in {\mathbb{N}
		}$, such that for all $k\ge K$, 
		\begin{equation*}
			\frac{f_{k+1}-f_{k}}{\gamma _{k+1}}\leq -bf_{k}+\frac{a}{t_{k}}
			\sum_{i=1}^{k}\gamma _{i}f_{i}+C  
		\end{equation*}
		for some $b>a>0$, $C\in{\mathbb{R}}_+$. Then, $\sup_{k\in {\mathbb{N}}
		}f_k<\infty$.

