[Defn 71 (Elliptic H\"older spaces) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] For $\alpha\in(0,1)$ we define the space $C^{\alpha,\tau}(\mathbb R^d)$ to be the completion of $C_c^\infty(\mathbb R)$ with respect to the norm given by $$\|f\|_{C^{\alpha,\tau}(\mathbb R^d)}:= \sup_{x\in\mathbb R^d} \frac{|f(x)|}{w(x)} + \sup_{|x-y|\leq 1} \frac{|f(x)-f(   y)|}{w(x)|x-y|^{\alpha}}.$$
		For $\alpha<0$ we let $r=-\lfloor \alpha\rfloor$ and we define $C^{\alpha,\tau}(\mathbb R^d)$ to be the completion of $C_c^\infty(\mathbb R)$ with respect to the norm $$\|f\|_{C^{\alpha,\tau}(\mathbb R^d)}:= \sup_{x\in\mathbb R} \sup_{\lambda\in (0,1]} \sup_{\phi \in B_r} \frac{(f,S^\lambda_{x}\phi)_{L^2(\mathbb R)}}{w(x)\lambda^\alpha}$$ where the scaling operators $S^\lambda_{x}$ are defined by 
  \begin{align}
  S^\lambda_{x}\phi (y) = \lambda^{-d}\phi(\lambda^{-1}(x-y)),\end{align} 
  and where $B_r$ is the set of all smooth functions of {$C^r$ norm} less than 1 with support contained in the unit ball of $\mathbb R^d$.

[Lemma lem:coefficient_bounds of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Suppose $g \in L^\infty_m(\mathbb R^3)$ for some $m \in (2,3) \cup(3,\infty)$. Then,
    \begin{equation*}
        \left\vertA[g](v)\right\vert \lesssim \left(\left\langle v \right\rangle^{-1} + \left\langle v \right\rangle^{2-m}\right) \left\|g\right\|_{L^\infty_m}.
    \end{equation*}
    Similarly, if $g\in L^\infty_m(\mathbb R^3)$ for some $m \in (1,3)\cup (3,\infty)$, then
    \begin{equation*}
        \left\vert\nabla a[g](v)\right\vert \lesssim \left(\left\langle v \right\rangle^{-2} + \left\langle v \right\rangle^{1 - m}\right)\left\|g\right\|_{L^\infty_m}.
    \end{equation*}
    If $m>5$, we have the improved estimate
    \begin{equation}
        A[g] \lesssim \left(\frac{\Pi(v)}{\left\langle v \right\rangle} + \frac{\mathrm{Id} - \Pi(v)}{\left\langle v \right\rangle^3}\right) \|g\|_{L^\infty_m}.
    \end{equation}
    The implicit constant above depends only on $m-5$.

[Theorem 18 of arXiv:2606.15843, 'Long-time behaviour of DLRA for SDEs'] Suppose Assumptions (H3) and (H7) hold. 
	For any initial condition $\zeta\in L^2(\Omega,V_r(\bb R^d))$ and $\xi\in L^2(\Omega,\bb R^r)$ and any $T\ge0$, there exists a constant $C(b,\sigma,T)$ such that 
    \begin{equation}
        \begin{aligned}
            &\bb E_0[\|U^{(\mu)}_t\|^2_\rrm{HS}]=\zeta;\\
            &\bb E_0[|Y^{(\mu)}_t|^2]\le C(b,\sigma,T)\big(|\xi|^2+1\big),
        \end{aligned}
    \end{equation}
    for all $t\in[0,T]$. In particular,
    \begin{equation}
        \begin{aligned}
            &\bb E[\|U^{(\mu)}_t\|^2_\rrm{HS}]=r;\\
            &\bb E[|Y^{(\mu)}_t|^2]\le C(b,\sigma,T)\big(\bb E[|\xi|^2]+1\big),
        \end{aligned}
    \end{equation}
    holds for every $t\in[0,T]$.

