body:
[Proposition 10 of arXiv:2607.08129, '2607.08129'] The function $\Lambda_\theta$ in \eqref{eq:endpoint-cumulant} is finite and real analytic on $\R$, with
\begin{align}
 \Lambda_\theta'(\lambda)
 &=\sum_{j\ge1}\frac1{j(j+1)}
 \frac{(1-q^j)e^\lambda}
 {q^j+(1-q^j)e^\lambda},
 \\
 \Lambda_\theta''(\lambda)
 &=\sum_{j\ge1}\frac1{j(j+1)}
 \frac{q^j(1-q^j)e^\lambda}
 {\bigl(q^j+(1-q^j)e^\lambda\bigr)^2}>0.

\end{align}
Moreover,
\begin{equation}
 \lim_{\lambda\to-\infty}\Lambda_\theta'(\lambda)=0,
 \qquad
 \lim_{\lambda\to\infty}\Lambda_\theta'(\lambda)=1.
\end{equation}
Consequently, the equation \eqref{eq:lambda-y-equation} has a unique solution $\lambda_y$ for every $y\in(0,1)$, the endpoint rate is strictly convex on $(0,1)$, and the formulas in Corollary~\ref{cor:endpoint-LDP} hold.  In addition,
\begin{equation}
 I_\theta^{\mathrm{end}}(c_\theta+u)
 =\frac{u^2}{2\sigma_\theta^2}+O(u^3),
 \qquad u\to0.
\end{equation}

[Proposition prop:evaluation of arXiv:2609.00336, 'Critical points of point charge potentials along lines'] Let $p>0$, $\lbrace (a_j,b_j)\rbrace_{j=1,\ldots,N} \subset  \mathbb{R} \times [0,+\infty) $ be pairwise distinct, and $x_1,\ldots,x_{2N}\in\mathbb{R}$ also distinct. Assume that $x_r\neq a_j$ whenever $b_j=0$. Then
		\begin{equation}
			\det\left[
			R_j(x_r)^{-(p+2)/2}\ \ \ (x_r-a_j)R_j(x_r)^{-(p+2)/2}
			\right]_{\substack{r=1,\ldots,2N\\ j=1,\ldots,N}}
			\neq0,
		\end{equation}
		where the columns are ordered in the indicated consecutive pairs.

