[Prop Smooth of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] \begin{enumerate}	
\item[\rm(1)] Any $G$-Kato measure is smooth in the sense of Definition~(defi:smooth of the paper).
\item[\rm(2)] Any $G$-bounded measure charging no semi-polar sets is smooth in the sense of Definition~(defi:smooth of the paper). 
\end{enumerate}

[Proposition prop:r-tail-compensator-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] There exist constants \(C<\infty\) and \(c>0\) such that, for every \(n\ge1\),
\begin{equation}
\mathbb{P}\left(
\sup_{2^n\le\lvert\xi\rvert\le2^{n+1}}
\left(
\mathfrak C^{\mathrm{pre}}_{\xi,n}
+
\sup_{L\ge1}\mathfrak C^{\mathrm{post}}_{\xi,n,L}
\right)
>
2n^{-2}2^{-sn/2}
\right)
\le
C2^{-cn}.
\end{equation}
Consequently, the probabilities in (equation eq:r-tail-compensator-probability-paper of the paper) are summable in 
\(n\).

[Lemma spde E T2 of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Under the same setting as in Proposition (entropy estimate of the paper), for every $\delta\in(0,1)$ fixed, $\beta > 2$ and $0 < \alpha <1/2$, we have
\begin{align}	
\sup_{\eta >0, \gamma > 0}\mathbb{E}\left(\|h_{\delta}(\rho^{\gamma, \eta})\|_{W^{\alpha,1}_{[0,T]}H^{-\beta}_{\mathbb{T}^2}}\right) < \infty
\end{align}

[Lemma valueofgradp of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] For all $f\in L^2(\mathbb{R}^d)$, $t\in [0,1)$ and $x\in \mathbb{R}^d$, we have
    \begin{align*}
    \int f(y)\nabla_x p^{t,x}(y)d\lambda^d(y) =\frac{t}{1-t^2}\int f(y)H(y,x) dp^{t,x}(y)
\end{align*}
and 
\begin{align*}
     \int f(y)\nabla_x^2 p^{t,x}(y)d\lambda^d(y)
    = & \frac{t^2}{(1-t^2)^2}\int f(y)\left(H(y,x)^{\otimes 2} - \int H(w,x)^{\otimes 2} dp^{t,x}(w)\right)dp^{t,x}(y).
\end{align*}

