body:
[Lemma 8 of arXiv:2607.16017, 'On large networks of integrate-and-fire neurons with short-term synaptic plasticity'] \begin{equation}
R_{s, t}^a (x)  = K^{0 }_a (s, t) \psi_{ t - s } ( x) + \int_s^t R_{u, t }^a ( (1- U) \psi_{u- s } ( x))   K^{0 }_a ( s, u ) \d u . 
\end{equation}
The latter equation has a unique solution of the form 
\begin{equation}
R_{s, t }^a ( x) = R_{s,t }^{a, 1} + R_{s,t}^{a, 2} x  ,
\end{equation}
where $ R_{s,t }^{a, 1} $ and $ R_{s,t}^{a, 2}$ are given explicitly in~\eqref{eq:R12} below.

[Lemma lem:flow-D-with-power of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] For all $(s, t) \in [0, 1]^2_{\leq}$ and $x \in {\mathbb{R}}^d$, we have that $\phi^{s, x}_t \in \mathbb{D}^\infty$. In addition, for any $ n \geq 1$, there exists a random variable $\Lambda_n$ such that for all  $(s, t) \in [0, 1]^2_{\leq}$, $x \in {\mathbb{R}}^d$, with probability one,  we have 
\begin{equs}
    \|D^n \phi^{s, x}_t\|_{{\mathbb{R}}^d \otimes \mathcal{H}^{\otimes n}} \leq \Lambda_n |t-s|^{H_-},
\end{equs}
 Moreover,  for any $p \geq 1$, there exists a  constant $C=C(n, p, \|\sigma\|_{\mathcal{C}^{n+4}},H_-)$, such that  $\|\Lambda_n\|_{L_p(\Omega)}\leq C$.       
 Finally, one has the identity
 \begin{equ}
    D_r\phi^{s,x}_t=J^{r,x}_t\sigma(\phi^{s,x}_r)\mathbf{1}_{r\in[s,t]}.
\end{equ}

[Lemma lem:local CLT of arXiv:2412.02160, 'A functional central limit theorem for weighted occupancy processes of the Karlin model'] Fix $\epsilon\in(0,1)$. Then, there exists $C>0$ such that
\begin{equation}
\max_{k\in J_{np}}\abs{\mathbb P(N(np) = k) - \mathbb P(B_{n,p} = k)} \le \frac C{\sqrt {np}}\pp{p\log^2n+\frac{\log^4n}{np}},
\end{equation}
and
\begin{equation}
\sup_{|x|\le d_n}\max_{k\in J_{np}}\abs{\mathbb P(N((n+x)p) = k) - \mathbb P(N(np) = k)} \le \frac C{\sqrt {np}}\pp{\sqrt p\log^2n+\frac{\log^3n}{\sqrt{np}}},
\end{equation} 
for all $n\in{\mathbb N}, p\in[ n^{-\epsilon},1/2]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: numerics for the error term for 52 cards of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $n=52$. We have the following bounds.
\begin{enumerate}
    \item For any $t\geq 186$, we have $\varepsilon^{(n)}(t) \leq 9.6\cdot 10^{-4}$. 
     \item For any $t\geq 245$, we have $\varepsilon^{(n)}(t) \leq 10^{-5}$. 
     \item For any $t\geq 303$, we have $\varepsilon^{(n)}(t) \leq 10^{-7}$.
\end{enumerate}

