body:
[Conjecture of arXiv:2509.23069, 'Every cutoff profile is possible'] Consider, for $n\geq 2$, the random transposition shuffle $(X_t^{(n)})_{t\geq 0}$ on ${\ensuremath{\mathfrak{S}}} _n$, in discrete or continuous time, and denote the associated separation distance to stationarity at time $t\geq 0$ by $\mathrm{d}_{\textup{sep}}^{(n)}(t)$. For any $c\in {\ensuremath{\mathbb R}} $ we have
    \begin{equation}
        \mathrm{d}_{\textup{sep}}^{(n)} \left( \left\lfloor \frac{1}{2}n(\ln n + c) \right\rfloor\right) \xrightarrow[n\to \infty]{} 1-e^{-e^{-c}}.
    \end{equation}
In words, the separation profile for random transpositions is given by a Gumbel distribution. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem 9 of arXiv:2604.10266, 'A singular SDE driven by additive fractional Brownian motion with Hurst parameter $H<\frac'] The limit process $X=\{X_t,t\geq 0\}$ has the following properties:
 \begin{itemize}
 \item[(a)] the set $\{t>0: X_t>0\}$ is open in the natural topology on $\RR$;
 \item[(b)] $X$ is continuous on $\{t\geq 0: X_t>0\}$.
 \end{itemize}

[Lemma 3 of arXiv:2604.14396, 'On the tails of Dickman-like perpetuities'] Under the assumptions of Example 3, $s_\alpha(t)$ admits a representation
\begin{multline}
s_\alpha(t)=b^{-1}\Big(\log (\delta t)+\log\log (\delta t)\\+\sum_{n\geq 1}\frac{(-1)^{n+1}}{(\log (\delta t) )^n}\sum_{m=1}^n (-1)^{n+m}\genfrac{[}{]}{0pt}{}{n}{n-m+1}\frac{(\log\log (\delta t))^m}{m!}\Big)+O((t\log t)^{-1}),
\end{multline}
where the series converges for large $t$, $\delta:=(\alpha b p)^{-1}$, and $(\genfrac{[}{]}{0pt}{}{i}{j})_{i,j\geq 1}$ are the unsigned Stirling numbers of the first kind.

[Theorem eqItoWeakFor of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Suppose that $X_0 \in L_{\mathcal{F}_0}^2(\Omega ; H)$,  $ \phi(\cdot) \in L_{\mathbb{F}}^2\left(0, T ; \mathcal{V}^*\right)$, and $\Phi(\cdot) \in$ $L_{\mathbb{F}}^2 ( 0, T ; H) $.
    Assume
    \begin{align*}
    X(t)=X_0+\int_0^t \phi(s) d s+\int_0^t \Phi(s) d W(s), \quad t \in[0, T]
    .
    \end{align*}
    If $X(\cdot) \in L_{\mathbb{F}}^2(0, T ; \mathcal{V})$, then $X(\cdot) \in C([0, T] ; H)$, a.s., and for any $t \in[0, T]$,
    \begin{align}
        \notag

        |X(t)|_H^2= & \left|X_0\right|_H^2+2 \int_0^t\langle\phi(s), X(s)\rangle_{\mathcal{V}^*, \mathcal{V}} d s \\
        & +2 \int_0^t\langle\Phi(s), X(s)\rangle_H d W(s)+\int_0^t|\Phi(s)|_H^2 d s, \quad \text { a.s. }
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary COR35 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Under the same assumptions as in Theorem~(THM3.2 of the paper), the following estimates hold true: for any $\delta,\rho>0$, 
\begin{equation}
    {\mathbb{P}}^x[\sigma_B\le t]\ge \mathrm{Cap}_{(0)}(B_{x,\delta/2})\cdot \widetilde C_3\cdot \exp\left\{ -C_2 (1+\rho) \left( \frac{\widetilde{d}(x,B)+\delta}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall 0<t\le T,
\end{equation}
where $\widetilde C_3>0$ is a constant depending on $T,\alpha, \beta, \delta$ and $\rho$.

[Proposition 27 (Exploration of the left part) of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] With probability 1, the following statement holds for every spindle $\cT$: if $(a,r)$ denotes its bottom point and $(c,z)$ its top point, then

(i)   
  $s_{\cT}=\sigma_a^r$; 

(ii) $t_{\cT}$ is the smallest time  $t>s_{\cT}$ when $\varrho$ reaches the top of the spindle, thus $\varrho_{t_{\cT}}= (c,z)$;

(iii) the end of the exploration of the spindle happens at time $\tau_a^r$, when $X$ completes an excursion above $r$, hence \ $\sup\{t\ge 0 \colon \varrho_{t} \in \cT\} = \tau_a^r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] Let $k \geq 1$ and $x \in \vertices$. We have the inclusion of events
  \begin{equation*}
      \{\#\cycV(x) \geq 3k\} \subset \mathrm{ED}_{k, r}(x)\,.
  \end{equation*}

[Proposition prop_LSI_quadratic_W of arXiv:2503.24372, 'A criterion on the free energy for log-Sobolev inequalities in mean-field particle systems'] Let $T>0$ be such that
 $\nu^r_T(d\varphi)\propto e^{-NV_T(\varphi)}\, d\varphi$ satisfies a log-Sobolev inequality with constant $N\lambda_T$
for some $\lambda_T>0$. 
Then $m^N_T$ satisfies a log-Sobolev inequality with constant:

\begin{equation}
\frac{1}{\gamma^{N}_{\rm LS}(T)}
\leq 
\frac{1}{\gamma_V} + \frac{ 1}{\gamma_V^2T^2\, \lambda_T}
.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Given $1<p<\infty$ and a matrix weight $W$, we say that $W$ satisfies the $A_p$ condition (denoted by $W\in A_p$) if
		\begin{equation}
			[W]_{A_p}:=\sup_{n\geq 1}\|\widetilde W_n\widehat W_n\|^p<\infty.
		\end{equation}
Similarly, we say that $W$ satisfies the $A_1$ condition (denoted by $W\in A_1$) if
\begin{equation}
[W]_{A_1}:=\sup_{n\geq 1}\|\widetilde{W}_nW^{-1}\|<\infty.
\end{equation}
The number $[W]_{A_p}$ is called the $A_p$ characteristic of $W$.

[Prop pr:noise_support of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] For $\boldsymbol{\xi}$ and $\mathcal{M}$ as above, one has
	\begin{equ}
		\supp \big(\boldsymbol{\xi}\big) = \overline{\Bigl\{(f,\mathbf{P} \div(f^{\otimes 2})): f \text{ is smooth}, \div(f) = \int_{\mathbf{T}^2} f(x) \, \mathrm{d} x = 0\Bigr\}}	\;,
	\end{equ}
where the closure is taken in $\mathcal{M}$.

