body:
[Theorem 3 (Local limit theorem) of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] Fix $\beta >0$.
Let $Y_T=A_T-\theta_\beta T$ with $\theta_\beta = \lambda'(\beta)$ and $\sigma^2_\beta = - \lambda''(\beta)$.  For every directly Riemann-integrable
$h:\mathbb R\to\mathbb R$, every compact $K\subset\mathbb R^d$, and every $M<\infty$,
\begin{equation}
    \nonumber
 \sup_{\substack{x\in K\\|a|\leq M}}
 \left|
  \sqrt T\,\bbE^{\bbPh^{\beta,T}_x}[h(Y_T-a)]
  -\frac1{\sqrt{2\pi\sigma_\beta^2}}
   \int_\R \de y \, h(y)
 \right|
 \longrightarrow0.
\end{equation}
In particular,
\begin{equation}
\nonumber
 \sqrt T\bbE^{\bbPh^{\beta,T}_x}[h(Y_T)]
 \longrightarrow
 \frac1{\sqrt{2\pi\sigma_\beta^2}}
 \int_\bbR \de y \, h(y),
\end{equation}
locally uniformly in $x$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eqn:Ppos of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Given any countable discrete set $\mathcal{Z}$ and $\mu\in \P(\mathcal{Z})$, we say that $\mu$ lies {\em in the interior} (of $\P(\mathcal{Z})$) if $\mu(z)>0$ for all $z\in \mathcal{Z}$. Otherwise, we say that $\mu$ lies {\em on the boundary} (of $\P(\mathcal{Z})$). The collection of all probability measures in the interior and the collection of all probability measures on the boundary are denoted, respectively,  by
\begin{align}
    \Ppos(\mathcal{Z})&\coloneqq \pr{\mu\in \P(\mathcal{Z}):\mu(z)>0 \, \forall z\in \mathcal{Z}};\\
    \Pzero(\mathcal{Z})&\coloneqq \pr{\mu\in \P(\mathcal{Z}):\exists z_*\in \mathcal{Z}\text{ s.t. }\mu(z_*)=0}.
\end{align}
We also define analogous subsets of symmetric measures as follows:
\begin{align}
        \Psympos{\X}&\coloneqq \pr{\pi\in \Psym{\X}: \pi(x,z)>0 \, \forall x,z\in \X}; \\
        \Psymzero{\X}&\coloneqq \pr{\pi\in \Psym{\X}: \exists \, x,z\in \X \text{ such that } \pi(x,z)=0}. 
\end{align}

[Theorem 92 (Conditional fermionic Dol\'eans law and ideal transfer) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Assume that $\mathcal G_0$ reveals $R$.  Put
$E_m=\{V_T\le m\}\in\mathcal G_0$,
$M^{(m)}=\mathbf1_{E_m}M$, and $R^{(m)}=\mathbf1_{E_m}R$.
Let $\mathscr U^{x,(m)}$ denote
\eqref{eq:compact-fermionic-propagator} with $R$ replaced by $R^{(m)}$.
Then, for every $t\le T$ and $\lambda\in\mathbb R$,
\begin{equation}
 \mathbb E\!\left[
 Z_t^{\lambda,(m)}\otimes Z_t^{\lambda,(m)}\mid\mathcal G_0\right]
 =\mathscr U_{0,t}^{\lambda^2,(m)}(P_0)
 \quad\text{in }\mathcal S_1(\mathcal F_\wedge(H)),

\end{equation}
with trace at most $e^{\lambda^2m}$.  The local conditional covariance is
therefore
\begin{equation}
 C_t^{\lambda,\mathrm{loc}}
 =e^{\lambda^2\mathcal B_{R_t^c}}
  \prod_{0<s\le t}(I+\lambda^2\mathcal B_{\Delta R_s})(P_0).

\end{equation}
Its particle-two block gives the exact atomic defect
\begin{equation}
 4C_{\alpha_A,t}^{\mathrm{loc}}
 =\Lambda^2R_t-\sum_{0<s\le t}\Lambda^2\Delta R_s.

\end{equation}
Let $A$ be the chronological area of $M$ and $Q=R_T$.  For every $z\ge0$,
locally on the events $E_m$,
\begin{equation}
 \mathbb E\!\left[
 \exp\!\left(\sup_{t\le T}\mathfrak F_{A_t}(z)\right)
 \middle|\mathcal G_0\right]
 \le4\det\!\left(I+\frac z2Q\right).

\end{equation}
Consequently, if $0<p<1$ and $Q\in\mathcal S_{p,\infty}$, then for every
$0<r<2$,
\[
 \left(\mathbb E\!\left[
  \sup_{t\le T}\|A_t\|_{\mathcal S_{p,\infty}}^r
  \middle|\mathcal G_0\right]\right)^{1/r}
 \le C_{p,r}\|Q\|_{\mathcal S_{p,\infty}}.
\]
Little weak ideals transfer to little weak ideals; in particular
$Q\in\mathcal S_1$ implies
\begin{equation}
 \sup_{t\le T}n s_n(A_t)\longrightarrow0
 \qquad\text{almost surely}.

\end{equation}

[Thm comp-gl-models of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $G$ be any compact Lie group. Then the functors 
    \[
        \textup{const}\colon\cat{$\bm{G}$-OrthSp}\to\cat{$\bm G$-$\textbf{\textup{L}}$-Sp}
        \qquad\text{and}
        \qquad
        \textup{diag}\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Sp}\to\cat{$\bm{G}$-OrthSp}
    \]
    descend to mutually inverse equivalences ${\mathfrak S\kern-.5pt\mathfrak p}_\textup{$G$-gl}\simeq{\mathfrak d\kern-.25pt}{\mathfrak S\kern-.5pt\mathfrak p}_\textup{$G$-gl}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 17 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] Under the same setup as in Proposition~\ref{prop:one arm}, we have 
\begin{align}
\Ll|\bc^\delta(\eps)^{2}\phi_\delta[B_\eps(0)\longleftrightarrow B_\eps(x)]-\tfrac{a_{\eps}(x)}{2}\big(\tfrac\eps{|x|}\big)^{1/4}\Rr|&\le C\pi^\delta_1(\eps,|x|)^2\big(\tfrac\eps{|x|}\big)^c+o_\delta(1).
\end{align}
As a consequence, there exist~$c',C'>0$ such that for every~$x\neq 0$ and every~$\eps>0$ sufficiently small,
\begin{equation}
c'\big(\tfrac\eps{|x|}\big)^{1/8}\le \liminf_{\delta\rightarrow0}\pi_1^\delta (\ep,|x|)\le\limsup_{\delta\rightarrow0}\pi_1^\delta (\ep,|x|)\le C'\big(\tfrac\eps{|x|}\big)^{1/8}.
\end{equation}

