[Lemma 16 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $\tau_n$ and $\sigma_n$ as defined in equations \eqref{Eq: Def_tau_1}- \eqref{Eq: Def_sigma_k+1}. Then, for all $n \ge 1$,
\begin{equation}

\PP \left(\tau_n \ge 1\right)=1,
\end{equation}
and 
\begin{equation}

\PP \left(\sigma_n \ge 1\right)=1.
\end{equation}
Furthermore, 
\begin{equation}

\PP \left(\mu_n \ge n\right)=1.
\end{equation}

[Proposition prop:0 process of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] Suppose that
\[
j_n\to\infty
\qquad\mbox{and}\qquad
j_n=o\pp{
\frac{n^{\alpha/(1+\alpha)}}
{(\log\log n)^{1/(1+\alpha)}}
}.
\]
Then, for every $T>0$,
\begin{equation}
\lim_{n\to\infty}\frac{j_n^{(\alpha+1)/2}}{n^{\alpha/2}}\sup_{t\in[-T,T]}
\abs{
{
{\mathbb E}\pp{C_{j_n}(\floor{s_n(t)})\mid{\mathcal P}}
-s_n(t)^\alpha p_{j_n}\topp\alpha S_\alpha
}}
=0
\qquad\mbox{in probability}.
\end{equation}
If, in addition,
\begin{equation}
\frac{j_n}{(\log n)^2}\to\infty,
\end{equation}
then the convergence in (equation eq:centering probability of the paper) holds almost
surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 (Tightness of $\{{\rm Law}(X^n)\}$) of arXiv:2605.22445, 'Generalized specific entropy on Wiener space with application to Martingale Optimal Transp'] Assume:
\begin{enumerate}
\item[{\rm (i)}] $\{{\rm Law}(X^n_0)\}$ is tight in \(\mathcal M_1(\mathbb R^d)\);
\item[{\rm (ii)}] the entropy bound \eqref{eq:entropy_integrability} holds.
\end{enumerate}
Then $\{{\rm Law}(X^n)\}$ is tight in $\mathcal M_1\bigl(C([0,1];\mathbb R^d)\bigr)$.

