[Cor 11 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\gamma \in \mathcal{P}_\mathcal{W}$, $\vartheta \in \mathcal{P_A}$, $C$ be its corresponding Archimax copula and let $L$, $R$ be defined according to eq. \eqref{eq:definition_L_R_measure}. Then the following assertions hold:
    \begin{itemize}
        \item[$(i)$] If $\gamma$ has full support and $L = 0$ as well as $R = 1$, then $\mathrm{supp}(\mu_{C}) = \mathbb{I}^2$.
        \item[$(ii)$] If $\gamma$ is strict and $\vartheta$ has full support, then $\mathrm{supp}(\mu_{C}) = \mathbb{I}^2$.
        \item[$(iii)$] If $\mathrm{supp}(\mu_{C}) = \mathbb{I}^2$, then $\gamma$ is strict and $L = 0$ as well as $R = 1$.
    \end{itemize}

[Def property-b of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d,k\in\mathds{N}$, $s,\alpha\in\mathds{R}$, and $p\in (0,\infty]$.
We say that \emph{Property B is satisfied} if one of the following sets of conditions is satisfied
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{$p\in (0,1)$, $k>\max\setn{s,d\lr{\frac{1}{p}-1}-s}$,}
\item{$p\in [1,\infty]$, $k>\left\lverts\right\rvert$.}
\end{enumerate}
We say that \emph{Property B' is satisfied} if one of the following sets of conditions is satisfied
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{$p\in (0,1)$, $k>d\lr{\frac{1}{p}-1}+\frac{d}{2}+\alpha$,}
\item{$p\in [1,\infty]$, $k>\frac{d}{2}+\alpha$.}
\end{enumerate}

[Lemma thm:factor_hl of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $\tau_1,\ldots,\tau_{\binom{n}{k}} \in S_n$ be a set of coset representatives for $S_n/(S_k \times S_{n-k})$, let $\mu \in \Sig_k, \nu \in \Sig_{n-k}$, and define
\begin{equation}
\lambda(D) = (\mu_1+D,\ldots,\mu_k+D,\nu_1,\ldots,\nu_n)
\end{equation}
for all $D$ large enough such that this is a valid signature. Then 
\begin{multline}
P_{\lambda(D)}(x_1,\ldots,x_n;t) = \\ 
\sum_{j=1}^{\binom{n}{k}} \tau_j\left( \Pi_t(x_1^{-1},\ldots,x_k^{-1};x_{k+1},\ldots,x_n) x_1^D \cdots x_k^D P_\mu(x_1,\ldots,x_k;t) P_\nu(x_{k+1},\ldots,x_n;t)\right).
\end{multline}

