[Lemma lem:orbit-matrix of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] For $1\le k\le N$, the compression of $K_N$ to $V_k(N)$ is the symmetric
tridiagonal matrix $M_N^{(k)}$ with
\begin{equation}
 (M_N^{(k)})_{jj}=2Nj,
 \qquad
 (M_N^{(k)})_{j,j+1}=(M_N^{(k)})_{j+1,j}
 =-(j+1)\sqrt{2j(N-j)}
\end{equation}
for $1\le j<k$.

[Thmint 2 of arXiv:2608.27022, 'On LCK Geometry of Gauduchon Connections'] Let $(M, J, \omega)$ be an lck manifold and assume $\omega$ is Gauduchon satisfying the {second Bismut--Einstein equation}
    \begin{equation*}
        \Ric^{B, 2}=f \omega, \qquad \text{for some}\, f \in \mathcal{C}^{\infty}(M).
    \end{equation*}
    If $\mathrm{dim}_{\mathbb{C}}M\geq 4$, then $\omega$ is Vaisman and $f \equiv 0$.   If $\mathrm{dim}_{\mathbb{C}}M \in \{2, 3\}$ and $f \geq 0$, then $\omega$ is Vaisman and $f\equiv 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2609.00978, 'Towards Categorical K\"ahler Geometry'] Let $X$ be a Noetherian separated scheme over $\mathbf k$ and $j\colon Z\hookrightarrow X$ a closed subscheme with ideal sheaf $\cI_Z\subseteq \cO_X$.
Suppose that $X$ is regular and $\cI_Z$ is invertible, thus $Z$ an effective divisor.
Then there is a comonadic adjunction
\[
\begin{tikzcd}
     \mathrm{Perf}(\widehat{X}_Z)\arrow[r,shift left,"j^*"] & D^b\mathrm{Coh}(Z) \arrow[l,shift left,"j_*"]
\end{tikzcd}
\]
and the unit and counit fit into exact triangles
\begin{gather*}
\cI_Z\otimes\_\longrightarrow 1_{\mathrm{Perf}(\widehat{X}_Z)}\xrightarrow{\eta} j_*j^*\xrightarrow{+1} \\
j^*\cI_Z[1]\otimes\_\longrightarrow j^*j_*\xrightarrow{\varepsilon} 1_{D^b\mathrm{Coh}(Z)}\xrightarrow{+1}
\end{gather*}
where $j^*\cI_Z=\cN_{Z/X}^\vee$ is the conormal sheaf of $Z\subseteq X$.

[Lemma lem:S_lh of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Let $(k_n)$ be such that $k_n=n^{o(1)}$ if $\kappa=1$, and
$\kappa^{k_n}=n^{o(1)}$ if $\kappa\ge2$. Fix
$\eta\in(0,1-1/\alpha)$ and set
$M_n=\lfloor n^{1-\eta}\rfloor$. Then:
\begin{enumerate}
\item[(i)] $(G_k)$ satisfies Assumption (hyp:S of the paper) along $(k_n)$ with
respect to $(M_n)$;
\item[(ii)] $\mathbb{E}[N_{k_n}(\mathcal T^n)]\sim n\pi_{k_n}$.
\end{enumerate}

[Theorem 6 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $p\in [1,2)$,
\begin{equation}
    \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-Tal-isoper-Boolean}}}(p)^k\Wop^{\geq k}(f) \left[1+ \frac{1}{2k}\ln\left(\frac{1}{\Wop^{\geq k}(f)}\right)\right]^\frac{kp}{2},
\end{equation}
with $C^{\text{\rm\ref{thm:high-order-Tal-isoper-Boolean}}}(p) = \left(M(p)^{-\frac{2}{p}}+\frac{p}{2\upe(2-p)}\right)^{-\frac{p}{2}}  \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition vp of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] \item Assume (a1 of the paper)--(a5 of the paper). Let $\alpha:=\frac{2\gamma-d+2}{3}$ for all $\gamma \in (\frac{d}{2},\frac{d+4}{2})$.  Then, the eigenvalue $\mu(\eta)$ satisfies
\begin{equation}
\mu(\eta) - \mathrm{i} \eta j^\vare_1 = \kappa \eta^{\alpha}\big(1+O(\eta^\alpha)\big) ,
\end{equation}
where we recall that 
\begin{equation}
j^\vare_1 := \left\{\begin{array}{l}  0,   \hspace{3.9cm} \mbox{ if } \quad \displaystyle 2\gamma\in \left(d,d+1\right),  \\
 \\
 \displaystyle \int_{\{|v|  \leqslant \vare^{-\frac{1}{3}}\}} v_1 M^2(v)  \mathrm{d} v , \quad  \ \ \mbox{if } \quad 2\gamma = d+1 ,  \\
 \\
\displaystyle \int_{\mathbb{R}^d} v_1 M^2(v)  \mathrm{d} v ,   \hspace{1.6cm}  \mbox{ if } \quad  2\gamma\in \left(d+1,d+4\right)  ,
\end{array}\right.  
\end{equation}
and $\kappa$ is a positive constant given by
\begin{equation}
\kappa :=  - \int_{\{|s_1| >0\}} s_1 m(s)  \mathrm{Im} H_0(s) \ \mathrm{d}s ,
\end{equation}
and where $H_0$ is the unique solution to  
\begin{equation}
- \frac{1}{m} \nabla_s \cdot \bigg(m^2 \ \nabla_s\bigg(\frac{H_0}{m}\bigg)\bigg) + \mathrm{i} s_1 H_0 = 0 \quad \mbox{ in } \  \mathcal{D}'(\mathbb{R}^d\setminus\{0\})  ,
\end{equation}
satisfying \begin{equation}
\int_{\{|s_1|\geqslant 1\}}|H_0(s)|^2\mathrm{d}s <+\infty \qquad  \mbox{ and } \qquad   H_0(s)\underset{0}{\sim} m(s).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma BoundProductSDriftBound of arXiv:2608.11178, 'A submartingale for the probability of avoiding the origin in one-point interaction ground'] Let \(T,\gamma>0\). Then there exists a constant
\(C=C(\gamma,T)>0\) such that, for all \(0<t\le T\) and all
\(x\in\mathbb R^3\setminus\{0\}\),
\begin{align}
\bigl|S_t^\gamma(x)b^\gamma(x)\bigr|
\le
C\left(
1+
\frac{1}{\sqrt t}\mathbf 1_{\{|x|\le \sqrt t\}}
+
\frac{1}{|x|}\mathbf 1_{\{|x|>\sqrt t\}}
\right).
\end{align}

