[Theorem Mainthm: activate_constant_fraction of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $d \ge 2$. Assume $Q$ is a symmetric, translation-invariant, and heavy-tailed transition kernel on $\mathbb Z^d$ with exponent $\alpha > 0$, and let $Q_L$ be its standard projection onto $\mathbb{T}^d_L$. Consider the frog model on $\mathbb{T}^d_L$ equipped with $Q_L$. Assume the lifespan $\ell_o$ of the planted particle diverges as $L$ approaches infinity.
\begin{enumerate}[itemsep=5pt, left=0.3cm]
\item If $\alpha \in (0, d)$, then for any particle density $\lambda > 0$, $\rho \in (0, 1)$, and $\varepsilon > 0$, there exists a positive constant $C_0$ such that
  \begin{align*}
    \lim_{L \to \infty} \mathbb P_L^+\left(\frac{|\mathcal{A}\left((\log L)^{\Delta + \varepsilon}\right)|}{L^d} \geq \rho\right) = 1,
  \end{align*}
  for any particle lifespan $\ell > C_0$.

\item If $\alpha \ge d$, then for any $\rho \in (0, 1)$, there exist positive constants $C$ and $C_0$ such that
  \begin{align*}
    \lim_{L \to \infty} \mathbb P_L^+\left(\frac{|\mathcal{A}(CL)|}{L^d} \geq \rho\right) = 1
  \end{align*}
  for any particle lifespan $\ell > C_0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Under the assumptions of Corollary~\ref{corollary1}, suppose that there exists $\alpha>0$ such that
	\begin{align}
		\|\psi(t,\omega)x-\psi(t,\omega)y\|_X^2
		\leq e^{-\alpha t}\|x-y\|_X^2,
		\qquad t\geq0,
	\end{align}
	for all $\omega\in\Omega$ and $x,y\in X$. Assume also that every $B_X\in\mathfrak D_X$ has bounded values and satisfies
	\begin{align}
		\lim_{t\to\infty}
		e^{-\alpha t}
		\operatorname{diam}_X^2 B_X(\theta_{-t}\omega)=0,
		\qquad \omega\in\Omega,
	\end{align}
	where $\operatorname{diam}_X C=\sup_{x,y\in C}\|x-y\|_X$. Then there exists a measurable map $\xi:\Omega\to X$ such that
	\begin{align}
		A_X(\omega)=\{\xi(\omega)\},
		\qquad
		\mathcal A(\omega)=\{(\xi(\omega),\mu^*)\},
	\end{align}
	and
	\begin{align*}
		\psi(t,\omega)\xi(\omega)
		=
		\xi(\theta_t\omega),
		\qquad t\geq0.
	\end{align*}

