[Thm 5 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $d \geq 2$, $(k_n)_{n \in \BN}$ is a $\BN$-valued sequence satisfying $k_n \to \infty$ as $n \to \infty$ and $k_n = o(\log n)$.
    Assume also that a density $f$ of $X_1$ satisfies the above two conditions.
    Then, as $n \to \infty$,
    \begin{equation*}
        \begin{aligned}
            -e f_{\max}n^{1+1/k_n}\theta S_{k_n}(\CX_n)^d \exp\left(-\frac{f_{\max}n\theta S_{k_n}(\CX_n)^d}{k_n}\right)&\\
            + k_n + \left(\frac{1+(d/m)}{2}\right)\log k_n + \log \frac{\sqrt{2\pi}}{\gamma f_{\max}^{1+d/(2m)}} &\xrightarrow{d} Z,
        \end{aligned}
    \end{equation*}
    where $\gamma := \int_{\BR^d} \exp(\partial^{2m}f(\bm{0})[z]/((2m)!)) \,dz$ and $Z$ is a random variable with the Gumbel distribution $P[Z \leq x] = \exp(-\exp(-x))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: proof of condition K2 of arXiv:2608.23756, 'Measure-valued fluid limits for partial service queues\\with correlated patience and servi'] For each $t \geq 0$ and $\varphi \in C_b(\mathbbm{R}_+^3)$, we have:
	\begin{subequations}
		\begin{align}
			&\lim_{\delta \to 0} \limsup_{N \to \infty} E\left|\bar\boldsymbol{A}_{t + \delta}^N(\varphi) - \bar\boldsymbol{A}_t^N(\varphi)\right| = 0,  \\
			&\lim_{\delta \to 0} \limsup_{N \to \infty} E\left|\bar\boldsymbol{D}_{t + \delta}^N(\varphi) - \bar\boldsymbol{D}_t^N(\varphi)\right| = 0,  \\
			&\lim_{\delta \to 0} \limsup_{N \to \infty} E\left|\bar\boldsymbol{D}_{t + \delta}^{N, c}(\varphi) - \bar\boldsymbol{D}_t^{N, c}(\varphi)\right| = 0. 
		\end{align}
	\end{subequations}

