[Proposition 7 of arXiv:2606.24485, 'On the convex hull of a planar Brownian bridge with a random Gaussian endpoint'] For $0 < t < 1$ and $0 < \sigma \le 1$, the quantity $A_\si(t)$ is given by
	\begin{equation}
		A_\sigma(t)
		=
		\frac{\sigma}{\pi}\sqrt{\frac{t}{1-t}}
		+
		(1-\sigma^2)\ug{
			\frac12-\frac{1}{\pi}
			\arctan \ob{\sigma\sqrt{\frac{1-t}{t}} }
		}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6 of arXiv:2608.27307, '2608.27307'] Under the assumptions of Theorem~\ref{thm:opt_ll}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item For every $\eps>0$ and $D>0$,
                      \begin{align}
                              \bb P\left(\spec W\cap[E_*+N^{-2/3+\eps},E_*+\eps_*]\neq\varnothing\right)\leq N^{-D}. 
                      \end{align}
                      If $E_*=E_+$, then
                      \begin{align}
                              \bb P(\la_1>E_++N^{-2/3+\eps})\leq N^{-D}. 
                      \end{align}
                \item For any $j$ satisfying $E_+-\eps_*/2\leq \gamma_j\leq E_+ $,
                      \begin{align}
                              \abs{\la_j-\gamma_j}\prec N^{-2/3}j^{-1/3}. 
                      \end{align}
                      In particular, for every fixed $K\in\N$,
                      \begin{align}
                              \max_{1\leq j\leq K}\abs{\la_j-E_+}\prec N^{-2/3}. 
                      \end{align}
                \item For each nonzero eigenvalue $\la_j$, let $\bfru_j\in\R^M$ and $\bfrv_j\in\R^N$ be normalized left and right singular vectors of $Y$, respectively. Then, for every fixed $K\in\N$, uniformly for $1\leq j\leq K$ and deterministic vectors $\bhv\in\C^M$, $\btw\in\C^N$,
                      \begin{align}
                              \abs{\scalar{\bhv}{\bfru_j}}^2\prec N^{-1}\|\bhv\|^2,\qquad \abs{\scalar{\btw}{\bfrv_j}}^2\prec N^{-1}\|\btw\|^2. 
                      \end{align}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] Let $\Theta=\frac{na_n}{\gamma}$ and $m=\frac{na_n\Lambda_\kappa}{\gamma^2}$. We have 
	\begin{align*}
		Z_{\kappa,\gamma}=e^{-\Theta\scalar{\frac n\gamma\kappa}{Q}}Z_{0,\gamma}.
	\end{align*}
	Moreover, if $\hbar\sim Q_{0,\gamma}^{\mathrm{sc}}$, then $\hbar+\kappa\sim Q_{\kappa,\gamma}^{\mathrm{sc}}$ for $\kappa\in \R$.

[Theorem 12 (Explicit Hom--Lie MSS bound) of arXiv:2609.00215, 'Hom--Lie Algebras and Explicit MSS Partition Bounds for $(6,3)$ Biangular Frames'] For the $(6,3)$ biangular Parseval frame with parameters~\eqref{eq:srg-params} and angles~\eqref{eq:angles}, for any subset $S \subset \{1,\dots,6\}$ of size $m$,
		\begin{equation}
			\|G_S\| \le 1 + \frac{1}{2}\alpha(m) + \frac{1}{4}\beta(m) + \frac{1}{8}\alpha(m)\beta(m), 
		\end{equation}
		where $\alpha(m)$ and $\beta(m)$ are given in Lemma~\ref{lem:subset-norms}.

[Lemma lem:explore-plus-spin-clusters of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a universal constant $c_{11}>0$ such that for any increasing event $\mathcal I\in\mathscr F_0$ and any boundary condition $\xi$ we have 
    \begin{equation}
        \mu_{\Lambda_M}^{\xi}(\mathcal C_1\cap\Lambda_{0.95M}=\emptyset\mid \mathcal I\cap\mathcal Y^-)\geq c_{11}.
    \end{equation}
    In particular, we could choose $\mathcal I=\mathcal Y^+$ so that $\mathcal I\cap\mathcal Y^-=\mathcal Y.$ We keep the flexibility of choosing $\mathcal I$ for later convenience.

