			\Phi_{\eta,\tau}
			=\Phi_\eta-\tau d+\frac{2\tau}{\rho_0}d^2.
		\end{equation}
		On $d=0$ and $d=\rho_0$, the difference
		$v-\Phi_{\eta,\tau}$ is nonpositive.  Since $v$ is $C^{1,1}$ and has
		the same first jet as $1+bd$ at $x_0$, along the normal ...","release_manifest_digest":"sha256:44fb6202836e892cd33976fbc87ae32c8133fc2d944c8b8f418951aeadeea3d3","revision_digest":"sha256:02e0e90f23570b6d72826bfc5513eee1e1dd4dd25bb7dd455d54716c72dcbe1d","source_id":"arxiv:2609.03339","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

