body:
[Theorem 15 (Study determinant--permanent comparison) of arXiv:2607.20329, '2607.20329'] For every $n\ge1$,
		\begin{equation}
			\Sdet(G_n^{\Hh})^2
			\le_{\mathrm{Lt}}|\per_{\Hh}G_n^{\Hh}|^2.
		\end{equation}
		Equivalently, $\Delta_n^{\Hh}\le_{\mathrm{Lt}}X_n^{\Hh}$.

[Proposition 2 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] Assume that $b$ and $\sigma$ are globally Lipschitz with Lipschitz constants $L_b$ and $L_\sigma$, respectively. Assume further that the initial condition $u_0$ is bounded with bounded derivatives and that $v_0$ is bounded. Under assumption~\eqref{E:ZeroOrderDifference}, there exists a unique random field solution $u$ to the stochastic wave equation~\eqref{E:SWE} such that, for all $p\ge 2$ and $T>0$,
    \begin{equation} 
        \sup_{(t,x)\in [0,T]\times \mathbb{R}^3}\mathbb{E}|u(t,x)|^p
        \le (3M)^{\frac{p}{2}} e^{cp\beta_0 T}.
    \end{equation}
    Here 
    \begin{equation}
    M=3\lr{T\|v_0\|_{L^\infty(\R^3)}+\|u_0\|_{L^\infty(\R^3)}+T\|\nabla u_0\|_{L^\infty(\R^3)}}^2 +Cp|\sigma(0)|^2\frac{T^{\nu+1}}{\nu+1}+C|b(0)|^2T^4\,,
\end{equation}

  and 
  $\beta_0 = C L_b^{1/2} + C p^{1/(\nu+1)} L_\sigma^{2/(\nu+1)}$, and the parameter $\nu$ is defined in~\eqref{E:ZeroOrderDifference}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2605.21005, 'Double-transform Tauberian method\\ for precise large deviations'] Let $G_t(x)$ be non-decreasing $\forall t\geq0$ with $\lim_{x\to-\infty}G_t(x)=0$. Let $\hat G_t(s)$ be non-decreasing\footnote{The monotonicity assumption can be relaxed to $\hat G_t(s)$ non-negative and eventually non-decreasing in $t$ uniformly for $s\in(0,\varepsilon)$.} in $t$ for all $s\in(0,\varepsilon)$. Suppose that there exists $(s_\lambda)_{\lambda>0}$ with $s_\lambda>0$ for all $\lambda$ and $s_\lambda\to 0$ as $\lambda \to 0$ such that for some $\alpha>0$, $\gamma>1$ and $\ell(x)$, $L(t)$ positive slowly varying functions at infinity we have\footnote{Recall that, for any $\gamma\neq 0$, we can assume that $\ell(1/s)s^\gamma$ is monotone without loss of generality by the monotone equivalents theorem~\cite[Thm.~1.5.3]{bingham}.}
\begin{equation}
\forall \theta>0,\qquad\lim_{\lambda\to0}\sup_{0<s\leq \theta s_\lambda}\left| \frac{\hat{\mathfrak G}(\lambda,s)}{L(1/\lambda)\lambda^{-\gamma}s^{-\alpha}\ell(1/s)} - 1 \right|=0.
\end{equation}
Then, defining $x_t\coloneqq 1/ s_{\frac 1 t}$,
\begin{equation}
\lim_{t\to\infty} \sup_{x\geq x_t}\left|\Gamma(\gamma)\Gamma(\alpha+1) \frac{G_t(x)}{L(t)t^{\gamma-1}\ell(x)x^\alpha}- 1 \right| =0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 10 of arXiv:2512.08745, 'Variance strikes back: sub-game--perfect Nash equilibria in time‑inconsistent $N$‑player g'] Let $\hat\alpha \in \cA_1$, and $\varepsilon >0$. We define
\begin{align*}
\ell_\varepsilon \coloneqq \inf \Big\{ \ell >0 : \exists (t,\alpha) \in [0,T] \times \cA_1, \; \P \big[\big\{\omega \in \Omega: J^1\big(t,\omega,\hat\alpha;\xi\big) < J^1\big(t,\omega,\alpha\otimes_{t+\ell}\hat\alpha;\xi\big) - \varepsilon \ell \big\}\big] >0 \Big\}.
\end{align*}
We say that $\hat\alpha$ is a {\rm sub-game--perfect mean-field equilibrium} for this mean-field game if it holds that $\ell_\varepsilon >0$ for any $\varepsilon >0$, and $\P^{\hat\alpha} \circ (X^1_{\cdot \land t}, \hat\alpha_t)^{-1} = \xi_t$, for $\d t\text{\rm--a.e.} \; t \in [0,T]$.

[Lemma lem:upper_bound_on_width of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Suppose that we have the same setup described above.  Then,  there exists a universal constant $c>0$,  and a constant $\varepsilon_0 \in (0,1)$ depending only on $a,\delta,N$ and $\theta$ such that
\begin{align*}
L_j \leq \frac{c}{(\theta - 3a\log(2)) \log(1/\varepsilon)} \quad \text{for all} \quad \varepsilon \in (0,\varepsilon_0) , \,\,\, j \in \{1,2,3,4\}.
\end{align*}

