[Proposition propoAiry: Airy estimate of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Fix $\alpha\in(0,1/2]$ and consider the PDE (equation eqAiry: PDE, u, sigma, r of the paper) with $r$ satisfying (equation eqAiry: conditions on r of the paper). There exist constants $s_\star,L_\star,C\in(0,\infty)$ such that, for every $s_0\geq s_\star$, the following hold.
	\begin{enumerate}
		\item If $0\leq t_1<t_2$ and $t_2-t_1\geq L_\star S(t_1)^{2/3}$, then, for all $x,y\geq 0$,
		\begin{equation}
			G_u(x,y;t_1,t_2)
			\leq Cxy\sqrt{V(t_1)V(t_2)}
			\exp\Biggl\{\int_{t_1}^{t_2}\frac{r(s)}{\sigma(s)}\,\text{d} s\Biggr\}.
		\end{equation}
		\item If $T>0$ and $T\geq L_\star S(0)^{2/3}$, then, for all $0\leq x\leq V(0)^{-1/3}$ and $0\leq y\leq V(T)^{-1/3}$,
		\begin{equation}
			G_u(x,y;0,T)
			\geq C^{-1}xy\sqrt{V(0)V(T)}
			\exp\Biggl\{\int_0^T\frac{r(s)}{\sigma(s)}\,\text{d} s\Biggr\}.
		\end{equation}
	\end{enumerate}

