[Lemma 13 of arXiv:2607.18104, '2607.18104'] Let $\varepsilon>0$ and $n\in \N$. For all $M \in \N_0$, $i \in \lbr \varepsilon^{-1}\rbr$, and $z>0$, we define the events 
\begin{equation}
    \mathsf{B}^{M,i}_{n,\varepsilon}(z) := \left\{ \sup_{ (i-1)\varepsilon\leq s < t \leq i\varepsilon,\, |x-y|\geq \frac{1}{8}M} \Lpat(x,s;y,t)  \leq -\frac{1}{260} M\varepsilon^{-1} + z\right\} . 
\end{equation}
There exist  $\varepsilon_0,c,C>0$ 
such that for all $\varepsilon \in (0,\varepsilon_0)$, all $n \geq \varepsilon^{-2}$, and all $z\in (0,\varepsilon^{-1/3}]$, 
\begin{equation}
    \P\Big( \mathsf{B}^{M,i}_{n,\varepsilon}(z)  \text{ holds for all } M \in \N_0 \text{ and } i \in \lbr \varepsilon^{-1} \rbr \Big) \geq 1- C\varepsilon^{-1}\exp\big(-c z^{3/2}\big) . 
\end{equation}

