		\mathbb{E}_{x\mathbf{y}}\left( \tau_{x}\right)<\infty\quad \mbox{and}\quad \lim_{M\to\infty} \sup_{x> 1}\sup_{\mathbf{y}\in \overline{D}_1}
		x^{-2}
		\mathbb{E}_{x \mathbf{y}} \big( \tau_{x} 1_{\{\tau_{x} > M x^2\}} \big)=0. 
	\end{equation}

