  \item (Long-range decay) For some   constants $T, K > d$ and $C_T, C_{K} > 1$,
  \begin{equation}
      f(x),\tilde{f}(x)\le \frac{C_T}{(1+|x|)^{T}},
    \qquad |\widehat f(\xi)|, |\widehat {\tilde{f}}(\xi)| \;\le\; \frac{C_K}{(1+|\xi|)^{K}}
