body:
[Lemma lem:one-step of arXiv:2607.18070, 'The Brownian loop-catcher'] Fix $A\subset R$,  let $H$ be a legal record from $a$ to $b$, and set
$P=\Phi_A(H)$.  List $\operatorname{supp}(P)\setminus A$ as $u_1,\ldots,u_m$ in first-visit
order along the directed path $\gamma$ corresponding to $P$. For each $1\le j\le m$, let $t_j$ be the first-visit time of $u_j$
and
\[
 D_j=R\setminus\bigl(A\cup\{u_1,\ldots,u_{j-1}\}\bigr).
\]
Then there are unique ordered lists $(\ell_{j,s})_{1\le s\le n_j}$ of loops in
$D_j$ from $u_j$ to $u_j$, with no intermediate visit to $u_j$, whose insertion
in $\gamma$ at $t_j$ reconstructs $H$.  Conversely, every such collection of lists determines one legal
record $H$ with $\Phi_A(H)=P$, and
\begin{equation}
 q(H)=q(P)\prod_{j=1}^m\prod_{s=1}^{n_j}q(\ell_{j,s}).
\end{equation}
Consequently,
\begin{align}
 d_{R\setminus A}
 \sum_{\substack{H\text{ legal in }R\\\Phi_A(H)=P}}q(H)
 &=q(P)d_{R\setminus(A\cup\operatorname{supp}(P))},\\
 \mathcal G_R(a,b)d_{R\setminus A}
 &=\sum_{\substack{P:a\to b\text{ legal in }R\\\Phi_A(P)=P}}
 q(P)d_{R\setminus(A\cup\operatorname{supp}(P))}.
\end{align}

As a corollary, suppose $H$ is the record of a normalized random walk from $a$ to $b$ in $R$. Then conditioned on $P=\Phi_A(H)$, the lists are
independent and
\begin{equation}
 \mathbb P[(\ell_{j,1},\ldots,\ell_{j,n_j})=(\xi_1,\ldots,\xi_d)\mid P]
 =\frac{\prod_{s=1}^d q(\xi_s)}{\mathcal G_{D_j}(u_j,u_j)}.
\end{equation}

[Lem 17 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For an isometric embedding between two compact metric spaces $f:X\to Z$, define $A_f\subseteq Z\times \calM(Z)_{\mathrm{fin}}$ by setting
\begin{align*}
  A_f:=\{(f(x),\mu\circ f^{-1}):x\in X,\;\mu\in \calM(X)_{\mathrm{fin}}\}.
\end{align*}
Let $f:X\to Z$ and $f_n:X_n\to Z,\;n\in\N,$ be isometric embeddings between compact metric spaces $(X,d^X),\;(X_n,d^{X_n})$ and $(Z,d^Z)$.
Suppose that $\lim_{n\to\infty}d^{Z}_{\mathrm{H}}(f(X),f_n(X_n))=0$. It is then the case that
\begin{align*}
  \lim_{n\to\infty}d_{\mathrm{H}}(A_f,A_{f_n})= 0.
\end{align*}
Here, we equip $Z\times \calM(Z)_{\mathrm{fin}}$ with the maximum metric $d$, which is defined by 
\begin{align*}
  d((z,\lambda),(w,\theta)):=d^Z(z,w)\vee d^Z_{\BL^{\kappa}}(\lambda,\theta),\qquad (z,\lambda),(w,\theta)\in Z\times \calM(Z)_{\mathrm{fin}},
\end{align*}
and we denote the Hausdorff distance between $A_f$ and $A_{f_n}$ with respect to $d$ by $d_{\mathrm{H}}(A_f,A_{f_n})$.

[Lemma 49 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Let \(F\subset(0,\infty)\cap\mathbb D\) be finite and nonempty, let
\(x\geq0\), and put
\begin{equation}
  \begin{aligned}
    Q_{F,x}
    &:=\mathcal L(G\mid G_s\geq-x,\ s\in F),\\
    g_{F,x}(t)&:=\EE_{Q_{F,x}}G_t,
    &\qquad
    Z_{F,x}(t)&:=G_t-g_{F,x}(t).
  \end{aligned}

\end{equation}
There are coefficients \(\lambda_{F,x}(s)\geq0\), \(s\in F\), such that
\begin{equation}
  g_{F,x}(t)
  =\sum_{s\in F}\lambda_{F,x}(s)K_H(t,s).

\end{equation}
Uniformly in \(F\) and \(x\geq0\),
\begin{equation}
  0\leq g_{F,x}(t)\leq g_{F,0}(t)\leq C_H|t|^H,
  \qquad t\in\mathbb R.

\end{equation}
For every \(0<a<R<\infty\), there is \(C_{H,a,R}<\infty\) such that
\begin{equation}
  |g_{F,x}(t)-g_{F,x}(s)|
  \leq C_{H,a,R}|t-s|^{2H},
  \qquad s,t\in[a,R].

\end{equation}
Consequently, for every \(R<\infty\),
\begin{equation}
  \lim_{\delta\downarrow0}\sup_{F,x}
  \sup_{\substack{s,t\in[0,R]\\|s-t|\leq\delta}}
  |g_{F,x}(t)-g_{F,x}(s)|=0,

\end{equation}
and, for every \(\varepsilon>0\),
\begin{equation}
  \lim_{\delta\downarrow0}\sup_{F,x}
  Q_{F,x}\left(
    \sup_{\substack{s,t\in[0,R]\\|s-t|\leq\delta}}
    |Z_{F,x}(t)-Z_{F,x}(s)|>\varepsilon
  \right)=0.

\end{equation}

For \(T>0\) and \(x>0\), these bounds pass to
\begin{equation}
  \mathbb P_{T,x}
  =\mathcal L(B\mid M_T\leq x)

\end{equation}
by dense finite-grid hard-wall approximation.  In particular, for every
\(A,R<\infty\), the laws of \(x-B\) on \(C([0,R])\), under
\(\mathbb P_{T,x}\) with \(T\geq R\) and \(0<x\leq A\), are tight uniformly
in \(T\) and \(x\).

