[Definition 73 ($\gfour$-orthogonal projection onto the double-null tori $\doublenulltoritwoarg{\ubar}{u}$ and $\doublenulltoritwoarg{\ubar}{u}$-tangency) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill
	\begin{itemize}
		\item We define the $\doublenulltoritwoarg{\ubar}{u}$-projection tensorfield $\nulltorusproject$ as follows, where $\MagnitueofinnerproductofnewLandnewuL$ is the scalar function from \eqref{E:RECIPROCALOFNEGATIVENULLGEODESICVECTORFIELDINNERPRODUCT} and $\newL$, $\newuL$ are the vectorfields from \eqref{E:DOUBLENULLEIKONALFUNCTIONNORMALIZEDNULLVECTORFIELDS}:
			\begin{align}
				\nulltorusproject_\beta^\alpha & \eqdef \updelta_{\beta}^{\alpha}
				+
				\frac{1}{\MagnitueofinnerproductofnewLandnewuL}
				\newL^{\alpha} \newuL_{\beta}
				+
				\frac{1}{\MagnitueofinnerproductofnewLandnewuL}
				\newuL^{\alpha} \newL_{\beta}, 
				 \\
				& = \updelta_\beta^\alpha + \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \Lunit^\alpha \uLunit_\beta + \frac{1}{\MagnitueofinnerproductofLunitanduLunit} \uLunit^\alpha \Lunit_\beta. 
			\end{align}
		\item Given any type $\binom{m}{n}$ spacetime tensorfield $\xi$, we define its $\gfour$-orthogonal projection onto $\doublenulltoritwoarg{\ubar}{u}$, denoted by $\nulltorusproject \xi$, as follows: 
			\begin{equation} 
				(\nulltorusproject \xi)_{\beta_1 \cdots \beta_n}^{\alpha_1\cdots\alpha_m} \eqdef \nulltorusproject_{\widetilde{\alpha}_1}^{\alpha_1} \cdots \nulltorusproject_{\widetilde{\alpha}_m}^{\alpha_m} \nulltorusproject^{\widetilde{\beta}_1}_{\beta_1} \cdots \nulltorusproject^{\widetilde{\beta}_n}_{\beta_n} \xi_{\widetilde{\beta}_1 \cdots \widetilde{\beta}_n}^{\widetilde{\alpha}_1 \cdots \widetilde{\alpha}_m}.
			\end{equation}
		\item Let $f$ be a scalar function. We define $\nullangrmD f$ to be the $\doublenulltoritwoarg{\ubar}{u}$-tangent one-form given by:
			\begin{align} 
				\nullangrmD f \eqdef \nulltorusproject \mathrm{d} f.
			\end{align}
			Note that $\nullangrmD f \cdot \nullgeop{x^A} = \nullgeop{x^A} f$ for $A = 2,3$.
	\end{itemize}

[Proposition eqn.412 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] There exists a constant $\beta_0\geq 0$ such that for each $\beta \geq \beta_0$, we can always find two constants $n_0\geq 1$ and $T_0>0$ satisfying that 
 \begin{eqnarray}
 \sup_{n\geq n_0} \int_{T_0}^\infty  t e^{-\frac{\beta}{n} t} \cdot \gamma_n  \overline\varPi_n(t)\, dt \leq   \frac{c}{8}  
  \quad \mbox{and} \quad
  \inf_{n\geq n_0}\int_0^{T_0} t e^{-\frac{\beta}{n} t} \cdot \gamma_n \overline\varPi_n(t)\,dt \geq \frac{3\cdot c}{4} .
 \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

