[Corollary cor:centered-lyapunov-moment-equivalence of arXiv:2605.20697, 'Uniform-in-time propagation of chaos for \\ Second-Order Consensus-Based Optimization'] Let \(p\geqslant2\). Under the parameter conditions of (assump:admissibility of the paper), the strict positivity of the equivalence constants \(c_1^{(2)}>0\) and \(c_1(a_p,p)>0\) is guaranteed. Define the constant \(K_{p,\gamma} := \max\{1+2^{p-1}\gamma^{-p}, \, 2^{p-1}\}\), and set
\begin{equation}
    C_{p,1} := \frac{1}{K_{p,\gamma}} \begin{cases} c_1^{(2)}, & p=2,\\ c_1(a_p,p), & p>2 \end{cases}, \qquad
    C_{p,2} := K_{p,\gamma} \begin{cases} c_2^{(2)}, & p=2,\\ c_2(a_p,p), & p>2 \end{cases}.
\end{equation}
Then the pathwise functional satisfies
\begin{equation}
    C_{p,1} \left( \momentp{p}{\mu_{\mathcal X^J_{t}}} + \momentp{p}{\mu_{\mathcal V^J_{t}}} \right)
    \leqslant L_p(t) \leqslant
    C_{p,2} \left( \momentp{p}{\mu_{\mathcal X^J_{t}}} + \momentp{p}{\mu_{\mathcal V^J_{t}}} \right).
\end{equation}
Consequently, taking expectations yields
\begin{equation}
    C_{p,1} \mathbf{E}\left[ \momentp{p}{\mu_{\mathcal X^J_{t}}} + \momentp{p}{\mu_{\mathcal V^J_{t}}} \right]
    \leqslant \mathcal L_p(t) \leqslant
    C_{p,2} \mathbf{E}\left[ \momentp{p}{\mu_{\mathcal X^J_{t}}} + \momentp{p}{\mu_{\mathcal V^J_{t}}} \right].
\end{equation}

[Definition Good event for percolation configurations on the dual lattice of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any $x \in (\ensuremath{\mathbb{Z}}^2)^*$ and any (large) integer $L \in \ensuremath{\mathbb{N}}$, we let
\begin{multline*}
    G_{x,L} := \left\{ \mbox{Any horizontal or vertical rectangle with short and long sidelengths equal to}~ \left\lceil \frac{L}{100} \right\rceil ~\mathrm{and} ~ \left\lceil \frac{22 L}{10} \right\rceil  \right. \\ \left. \mbox{included in } \left(x + \Lambda_{\left\lceil \frac{11L}{10} \right\rceil} \right) \mbox{ is crossed in the long direction by a cluster of \underline{closed edges} for}~ \omega^* \right\}.
\end{multline*}
We refer to Figure~(fig:goodbox of the paper) for an illustration of this event.

[Definition 5 of arXiv:2608.22693, 'Uniformity of extremal behaviour along geodesics in Liouville quantum gravity'] For distinct points $u_+,v_+,u_-,v_-\in \CC$, the event $\scX_{u_-,v_-}^{u_+,v_+}$ is said to occur if the following hold.
  \begin{enumerate}
  \item The $D_h$-geodesics $P_+,P_-$ from $u_+$ to $v_+$ and $u_-$ to $v_-$ respectively are unique. Moreover, $P_+\cap P_-$ is non-empty and is a non-trivial simple path, whose (distinct) starting and ending points are $u$ and $v$ respectively.
  \item There is a unique $D_h$-geodesic $\Gamma_{u_+,v_-}$ (resp.\ $\Gamma_{u_-,v_+}$) and this is equal to the concatenation of $\Gamma_{u_+,u},\Gamma_{u,v},\Gamma_{v,v_-}$ (resp.\ $\Gamma_{u_-,u},\Gamma_{u,v},\Gamma_{v,v_+}$).
  \item The geodesics $\Gamma_{u_-,u},\Gamma_{v,v_-}$ (resp.\ $\Gamma_{u_+,u}, \Gamma_{v,v_+}$) lie to the right (resp.\ left) of $P_+$ (resp.\ $P_-$).
  \end{enumerate}

[Theorem 2dsubcritical of arXiv:2511.08479, '\Large From disordered systems to the Critical 2D Stochastic Heat Flow'] Let $Z_{N,\beta_N}^{\omega}$ be the partition function of the 2D DPM with $\beta_N$ chosen as in (equation 2interm of the paper).
 We have
 \begin{equation} 
	Z_{N,\beta_N}^\omega \xrightarrow[\,N\to\infty\,]{dist}
	\begin{cases}
	\exp\big( \sigma_{\hat\beta} \, {\ensuremath{\mathcal N}} -
	\frac{1}{2} \sigma_{\hat\beta}^2
	\,\big)
	& \text{if } \hat \beta < 1 \\
	0 & \text{if } \hat\beta \ge 1
	\end{cases} \,,
\end{equation}
where ${\ensuremath{\mathcal N}} $ is a standard normal variable and $ \sigma_{\hat\beta}^2  = \log (1-\hat\beta^2)^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

