[Lemma 61 (cf.\ {\cite[Lemma 3.1 and Lemma 3.5) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {Mak24}}] 
     Assume $\beta \ll n/ \log n$ and fix $K > 0$. Then the following holds with probability at least $1 - O(n^{-K})$:
     \begin{enumerate}[(i)]
        \item for all $u,v \in V$
            \begin{equation} 
                \effR{}{u}{v} = \frac{2(1 + o(1))}{n \xi};
            \end{equation}
        \item for all edges $e,f$ with $|e \cap f| = 0$
            \begin{equation} 
                \effR{G / f}{u}{v} = \frac{2(1 + o(1))}{n \xi};
            \end{equation}

        \item and for all edges $e = (u,v)$ and $f$ with $|e \cap f| = 1$
            \begin{equation} 
                \effR{G / f}{u}{v} = \frac{3(1 + o(1))}{2n \xi}.
            \end{equation}
     \end{enumerate}

[Thm discrete_continuum_boundary_convergence of arXiv:2506.12171, 'The multinomial dimer model'] Let $R\subset \mathbb{R}^d$ be compact with piecewise smooth boundary, and let $b$ be a boundary asymptotic flow which is extendable outside. Let $\omega$ be an asymptotic flow with $T(\omega) = b$ and suppose that $R_n\subset \frac{1}{n}\Lambda$ approximates $R$ as above, and $\omega_n$ is a discrete flow on $R_n$. If $\lim_{n\to \infty} \omega_n=\omega\in \text{AF}(\Lambda,R,b)$ in the weak topology on flows, then 
    \begin{align}
        \lim_{n\to \infty} \mathbb{W}_1^{1,1}(b_n , b) = 0
    \end{align}
    with $b_n$ from ((eq:boundary_discrete_flow of the paper)) and $\beta_n(u) = \sum_{e\ni u} \omega_n(e)$ as above.

