body:
[Proposition 21 (Integral one-sided color expansion) of arXiv:2608.29585, '2608.29585'] For every fixed $n\ge2$ and every zero-framed knot $K$, there are Laurent
polynomials
\begin{equation}
 b_k^{(n)}(K;q)=\varepsilon_n a_{(k)}(K;q^2)
 \in\Z[q^{\pm1}]
\end{equation}
such that, for every $r\ge0$,
\begin{equation}
 J_r^{SU(n)}(K;q)=
 \sum_{k=0}^{r}b_k^{(n)}(K;q)
 \prod_{j=0}^{k-1}(1-q^{2(r-j)}).
\end{equation}
Here $a_{(k)}(K;q^2)$ is the coefficient defined by the finite dual
formula in \textup{(BG3)}.  Explicitly, for each partition $\mu$ one has
the finite representationwise identity
\begin{equation}
 J_K(V(\mu);q^2)\id_{V(\mu)}
 =\left(\sum_{\lambda\subseteq\mu}
 a_\lambda(K;q^2)\sigma_\lambda\right)\Big|_{V(\mu)}.
\end{equation}

[Lemma lem-Sanovcritsatisfied of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] We consider either periodic or particle boundary condition.

\begin{enumerate}

\item For any $N\in\mathbb{N}$ and any $z\in Z_{N,R}$, the map ${\mathcal T }_{W_z}\times  {\mathcal G }^{{{\scriptscriptstyle{({\mathcal S }})}}}_{W_z}\ni(\mu,{\rm d}\xi)\mapsto {\tt K}_{W_z}^{\ssup {\Lambda_N,{\rm bc}}}(\mu,{\rm d} \xi)$ is equal to the kernel $\Pi_{W_z}^{{{\scriptscriptstyle{({\mathcal S }})}}}({{\tt Q}}^{\ssup{\Lambda_N,{\rm bc}}})_{{\mathcal T }_{W_z}\to  {\mathcal S }_{W_z}}$, where we recall that $W_z=z+W$.

\item The empirical measure of the kernels from (1) converges to the kernel ${\tt K}_W$ in the following sense. Assume that $\frac 1{\# Z_{N,R}}\sum_{z\in Z_{N,R}}\delta_{\mu_z}\to \delta_\mu$ in ${\mathcal M }_1({\mathcal T }_W)$ as $N\to\infty$, then 
\begin{equation}
\lim_{N\to\infty}\frac 1{\# Z_{N,R}}\sum_{z\in Z_{N,R}}
\log \mathbb{E}_{\mu_z}\big[{\operatorname e }^{f(\theta_z(\Pi_{W_z}^{{{\scriptscriptstyle{({\mathcal S }})}}}))}\big]
=\log {\tt K}_W\Big(\mu,{\operatorname e }^{f(\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}})}\Big),\qquad f\in {\mathcal C }_{\rm b}({\mathcal S }_W),
\end{equation}
where $\mathbb{E}_{\mu_z}[\cdot]={\tt Q}^{\ssup{\Lambda_N,{\rm bc}}}[\cdot\mid \theta_z(\partial\Pi_{W_z}^{{{\scriptscriptstyle{({\mathcal S }})}}})=\mu_z]$.

\item   Both under ${\tt Q}^{\ssup{\Lambda_N,{\rm par}}}$ and ${\tt Q}^{\ssup{\Lambda_N,{\rm per}}}$, under the assumption that $\frac 1{\# Z_{N,R}}\sum_{z\in Z_{N,R}}\delta_{\mu_z}\to \delta_\mu$ in ${\mathcal M }_1({\mathcal T }_W)$ as $N\to\infty$, the
pairs $(\theta_z(\omega_{W_z}^{{{\scriptscriptstyle{({\mathcal L }})}}}), \theta_z(\omega_{W_z}^{{{\scriptscriptstyle{({\mathcal S }})}}}))$, $z\in Z_{N,R}$ satisfy (equation SanovCriterion of the paper).
\end{enumerate}

[Lem 25 of arXiv:2604.00190, '2604.00190'] For each $n\in\bN$, we have 
\begin{align}
\lim_{k\to\infty}U^{\rmP, n}_{(k)} (x, y)= V^{\rmP, n}(x, y),\qquad (x, y)\in\bR\times E. 
\end{align}

