[Theorem 27 (Du, 2025) of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Fix $\lambda_1, \lambda_2 > 0$, $\beta \in (0, 1)$. Let $G^\uparrow \sim \mc{G}(n, \frac{\lambda_1}{n^\beta})$ and $s \sim \lambda_2n^{-\left(\frac{1-\beta}{2}\right)}$, and consider a correlated inhomogeneous graph system $(G, H)$ obtained by subsampling $G^\uparrow$ with parameter $s$. In particular,

    \begin{equation}
        I \sim \mc{G}(n, \frac{\lambda_1 \lambda_2^2}{n}); \qquad U \sim \mc{G}(n, \frac{\lambda_1 \lambda_2 (2-o(1))}{n^{\frac{1+\beta}{2}}})
    \end{equation}

    Then, for any $\eps > 0$: 

    \begin{itemize}
        \item there exists an estimator recovering $\sigma^*$ on at least $|V_{\geq (\beta^{-1} + \eps)}|(1 - o_\Proba(1))$ vertices;
        \item any estimator must be wrong on at least $|V_{\leq (\beta^{-1} - \eps)}|(1 - o_\Proba(1))$ vertices.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Model estimates) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let the random field $\zeta$ satisfy Assumption~\ref{ass_zeta} and denote its rescaling for $\ve>0$ as in \eqref{rescaled_noise} by $\xi_\ve$.
Let $\kk\geq3$ be an odd integer satisfying \eqref{subcritical}.
Then there exist (unique, deterministic, $\ve$-dependent) $c^{(k)}$ for $k<\kk$ satisfying

\begin{equation}
c^{(k)}_\beta\neq0
\quad\implies\quad 
|\beta|<2+k\alpha \, , \quad
\sum_\n\beta(\n)=0 \, , \quad
\sum_{k\geq\kk}\beta(k)\geq2 \, ,
\end{equation}

such that the following holds almost surely. 

For all $x\in\RR^{1+d}$ and $\beta$ there exist smooth $\Pi^\ve_{x\beta}$ and $\Pi^{-,\ve}_{x\beta}$ satisfying \eqref{model_poly} and the first two items of \eqref{model_pop}, 
$\Pi^{-,\ve}_{x\beta}$ is given by \eqref{hierarchy}, and $\Pi^\ve_{x\beta}$ satisfies \eqref{pde_Pi} for $[\beta]\geq0$. 
For $\kappa>0$ sufficiently small (depending on $\beta$) and for all $1\leq p<\infty$ 
\begin{equation}
\begin{aligned}
\EE^{ \frac{1}{p}} \big|
\Pi^\ve_{x \beta t} (x)\big|^{p} 
\lesssim \ve^{\kappa\sum_{k>\kk}\beta(k)} \big(\sqrt[4]{t} \big)^{|\beta|-\kappa\sum_{k>\kk}\beta(k)} \, ,
\end{aligned}
\end{equation}
where the implicit constant only depends on $\alpha$, $ \beta$, $\kappa$, and $p$, 
but is independent of $\ve>0$, $x\in\RR^{1+d}$, and $t>0$.

For all $x,y\in\RR^{1+d}$ and all $\beta,\gamma$ 
there exists $(\Gamma^\ve_{xy})_\beta^\gamma$ satisfying \eqref{model_recentre}, \eqref{model_gamma_props}, \eqref{model_gamma_def}, and the last item of \eqref{model_pop}. 
For $\kappa>0$ sufficiently small (depending on $\beta$) and for all $1\leq p<\infty$ 
\begin{equation}
\begin{aligned}
\EE^{ \frac{1}{p}} \big|
\big(\Gamma^\ve_{xy} \big)_{ \beta}^{\gamma} \big|^{p} 
\lesssim \ve^{\kappa \sum_{k>\kk}(\beta(k)-\gamma(k))} |x-y|^{|\beta|-|\gamma|-\kappa\sum_{k>\kk}(\beta(k)-\gamma(k))} \, ,
\end{aligned}
\end{equation}
where the implicit constant only depends on $\alpha$, $ \beta$, $\kappa$, and $p$,
but is independent of $ \ve>0$, $x, y\in\RR^{1+d}$, and $\gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Second-order junction expansion) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Under \cref{ass:jet}, for every compact $\cQ\subset\R^D$ and every fixed integer $m\ge 0$, there are $C_{m,\cQ}<\infty$ and $\sigma_0>0$ such that
\begin{equation}
\norm{\widetilde Q_\sigma-Q_0-\sigma Q_1}_{C^m(\cQ)}
\le C_{m,\cQ}\sigma^{1+\alpha},
\qquad 0<\sigma\le\sigma_0,

\end{equation}
where $\widetilde Q_\sigma$ is the locally rescaled Gaussian convolution after removal of its $z$-independent normalization. Consequently, for $m\ge1$,
\begin{equation}
\norm{F_\sigma-F_0-\sigma G}_{C^{m-1}(\cQ)}
\le C'_{m,\cQ}\sigma^{1+\alpha},

\end{equation}
with
\begin{equation}
F_0=\nabla\log Q_0,
\qquad
G=\nabla\left(\frac{Q_1}{Q_0}\right).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm exp_mixing of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] If the noise satisfies Assumption~(as:noise of the paper) with $\limsup_{k\rightarrow \infty}|\phi_k| \leq \frac{1}{2}\alpha_0$ and
    \begin{equ}

        \inf_{k\neq 0} |\phi_k| > 0\;,
    \end{equ}
    then (equation e:SNS of the paper) has exactly one invariant measure $\mu_\star$ on $\mathcal{C}^{-\kappa}$. Moreover, there exist some constants $C, \Tilde{\gamma}, T_* > 0$ such that 
    \begin{equ}

    	\|\mathcal{P}_t(x, \cdot) - \mu_\star \|_{TV} \leq C\big(1 + V_{2\alpha_0}(x)\big)e^{-\Tilde{\gamma} t}
    \end{equ}
    for any $t \geq T_*$ and $x\in \mathcal{C}^{-\kappa}$, and $\mu_\star$ satisfies the tail bound
\begin{equ}

	\mu_\star(V_{2\alpha_0}(x) \geq K) \leq C\exp(-C^{-1}\sqrt{K})\;.
\end{equ} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 (Negligibility of the remainders) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[proposition]{prop:ll_remainders_ucp_zero_new}
Assume that \(f\in C^3(\mathbb R^d;\mathbb R^d)\).  Then
\begin{equation}
    R^{(\ell),n}
    \xrightarrow{\mathrm{ucp}}0,
    \qquad
    \ell=1,\dots,5 .
\end{equation}

[Lemma lem:good_scales of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] Suppose that $d=3\alpha$. There exists a constant $C$ such that for each $0<\lambda\leq 1$ the estimate

$\tilde \mathbb E_{r,\lambda}|K|\leq C\lambda^{-1} r^\alpha$ holds
for an unbounded set of $r\in [1,\infty)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 36 (Convergence of the quadratic term) of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let {$0\le s\le t\le T$} and $\psi,\xi\in \Vp$. Then, for {$h\in C_b(C([0, T]; L^2(\bO)); \R)$}
				\begin{align}
					& \lim_{m\to\infty} \wtilde{\E}\bigg[\bigg(\sum_{i=1}^M\int_s^t (S_{m-1} \Nn_i (\wtilde{u}_m), \psi) (S_{m-1} \Nn_i(\wtilde{u}_m), \xi) d\sigma\bigg) h(\wtilde{u}_{m}|_{[0,s]})\bigg]\\
					& = \wtilde{\E}\bigg[\bigg(\sum_{i=1}^M\int_s^t ( \Nn_i (\wtilde{u}), \psi) ( \Nn_i(\wtilde{u}), \xi) d\sigma\bigg) h(\wtilde{u}|_{[0,s]})\bigg].
				\end{align}

