{\mathcal Q}_{2,r}^{(j-1)}
\right)
{\mathcal P}_{1,l}^{(0)}
\right)
Q_{2,m}^*(0), \qquad m\geq0

\\
\left(P_{1,m}^{(j)}(0)\right)^*=&-j\left(\sum_{l=0}^{m-1}\left(\sum_{r=0}^{l}
{\mathcal P}_{1,r}^{(j-1)}\right){\mathcal Q}_{2,l}^{(0)}\right)P_{1,m}^*(0), \qquad m\geq1,

\\
\left(Q_{1,m}^{(j)}(0)\right)^*=&-j\left(\sum_{l=0}^{m-1}\left(\sum_{r=0}^{l}{\mathcal Q}_{1,r}^{(j-1)}\right)
{\mathcal Q}_{2,l}^{(0)}\right)P_{1,m}^*(0),
\qquad m\geq1,

\end{align}
and
\begin{equation}
\left(P_{2,m}^{(j)}(0)\right)^*=-j
\left(
\sum_{l=0}^{m}
\left(
\sum_{r=0}^{l-1}
{\mathcal P}_{2,r}^{(j-1)}
\right)
{\mathcal P}_{1,l}^{(0)}
\right)
Q_{2,m}^*(0), \qquad m\geq0.

\end{equation}

