[Prop delta of arXiv:2607.01877, 'Coupling some conditioned L\'evy trees with the Kesten tree'] Assume~(equation eq:hyp-param of the paper)-(equation eq:critical of the paper)  hold  and  $\pi\neq 0$. If  $\delta'\geq \delta>0$ are
  not atoms of $\pi$ and  $\bar\pi(\delta')>0$, then we have a.s.\ that:
\begin{equation}

  {\mathcal K}^{\mathbf{\mathrm{node}},*}_\delta \subset
  {\mathcal K}^{\mathbf{\mathrm{node}},*}_{\delta'}, \quad
  H_\delta\in \II{{\varrho}, H_{\delta'}}
    \quad\text{and}\quad
{\mathcal T}^\mathbf{\mathrm{node}}_{[\delta]}\subset {\mathcal T}^\mathbf{\mathrm{node}}_{[\delta']}.
  \end{equation}  
  Furthermore,  in  the  critical  case,   we have
  $\lim_{\delta\rightarrow \infty } d^{\mathcal K}(0,
H_\delta)=+\infty $ and,  if the  support  of  $\pi$  is
  unbounded and $\pi $ has no atom,
  the following  convergences hold  in $({\mathbb T},  {d_\mathrm {LGH}})$:
\begin{equation}

    {\mathcal K}^{\mathbf{\mathrm{node}},*}_\delta \xrightarrow[\delta\rightarrow +\infty]{\text{a.s.}} {\mathcal K}
   \quad\text{and}\quad
    {\mathcal K}^{\mathbf{\mathrm{node}}}_\delta \xrightarrow[\delta\rightarrow +\infty]{\text{a.s.}} {\mathcal K}.
  \end{equation}

[Theorem thm:dichotomy of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Fix $C_\star>C_{\mathrm{GTD}}$ and $\kappa\ge2C_\star$. Let $h,\gamma>0$ satisfy $h<2/\sqrt\kappa$, and let $s$, $\beta$, and $q_\kappa$ be defined as above. Then at least one of the following two cases holds.

\begin{enumerate}
\item[\rm(Q)] There is $\lambda\in[1,\kappa]$ such that, for the
two-dimensional quadratic potential
$U_\lambda(x)=\lambda\lvert x\rvert^2/2$, two initial states
$z,\widetilde z\in\mathbb R^4$ satisfy
\begin{equation}
 \lim_{n\to\infty}
 \norm{\delta_z(Q_{h,\gamma}^{U_\lambda})^n-
       \delta_{\widetilde z}(Q_{h,\gamma}^{U_\lambda})^n}_{\mathrm{TV}}^{1/n}
 =\rho_{\mathrm q}(s,\beta;\kappa)\ge q_\kappa.
\end{equation}

\item[\rm(C)] There exist $U\in\mathcal U_\kappa^2$ and constants $c_0,C_0>0$ such that, for every $R\ge1$, the following holds. The dilated potential $U_R(x)=R^2U(x/R)$ also belongs to $\mathcal U_\kappa^2$, the kernel $Q_{h,\gamma}^{U_R}$ has a unique invariant law $\pi_R$, and there is an initial state $z_R\in\mathbb R^4$ satisfying
\begin{equation}
 W_2(\delta_{z_R},\pi_R)\le C_0(1+R),
\end{equation}
while
\begin{equation}
 \norm{\delta_{z_R}(Q_{h,\gamma}^{U_R})^n-\pi_R}_{\mathrm{TV}}\ge\frac38,
 \qquad
 0\le n\le\left\lfloor\frac1{16}e^{c_0R^2}\right\rfloor.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 41 of arXiv:2609.01389, 'K-stability and birational rigidity of Fano 3-fold weighted complete intersections'] The following assertions hold.
\begin{enumerate}
\item If $\varphi' \colon Y' \to \mbP (1, 2, 4, 5)$ contracts a divisor, then $\msp$ is not a maximal center.
\item If $\varphi'$ does not contract a divisor, then $\varphi$ initiates a Sarkisov self-link.
\end{enumerate}

[Lemma 8 of arXiv:2506.17094, 'Nonlinear random perturbations of Reaction Diffusion Equations'] If  $u, z\in C([\lambda,t];E)$  verify \eqref{SalinsMild}, for all $s\in [\lambda,t]$ and $\xi \in \Oc$, then
\begin{equation}
    \sup_{s \in\,[\lambda,t]}|u(s)|_E\leq c_T \left( \sup_{s\in [\lambda,T]} |F(z(s))|_E+ \sup_{s\in [\lambda,t]}|z(s)|_E\right),
\end{equation}
for some constant $c_T$ which depends only on $T$, $f$ and $K$.

