[Corollary cor:local_subgraph_clt of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Assume that there are sequences $\varsigma_n \gtrsim \sqrt{n}$ and $\delta_n \to 0$ such that
\begin{equation}
    \mathbf{d}_\mathrm{Was}\mleft(\frac{\mathsf{deg}_v(X) - \mathbb{E}[\mathsf{deg}_v(X)]}{\varsigma_n}, Z \mright) \leq \delta_n,
\end{equation}
where $Z \sim \mathcal{N}(0,1)$.
Then for all $\varepsilon > 0$,
\begin{equation}
    \mathbf{d}_\mathrm{Was}\mleft(\frac{\mathsf{N}_G^{\rho \to v}(X) - \mathbb{E}[\mathsf{N}_G^{\rho \to v}(X)]}{\mathsf{d}_\rho p^{\mathsf{e}-1} n^{\mathsf{v}-2} \varsigma_n}, Z\mright)
    \lesssim n^{-\frac{1}{4}+\varepsilon} + \delta_n.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition GBSDE-propo2 of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] Let $(\xi^1_T,\mathfrak{f}^1(\cdot),A)$ and $(\xi^2_T,\mathfrak{f}^2(\cdot),A)$ be two sets of data satisfying assumption \textbf{(H)}. Let $(Y^1,M^1)$ and $(Y^2,M^2)$ be two solutions of the GBSDE (equation GBSDE of the paper) associated with $(\xi^1_T,\mathfrak{f}^1(\cdot),A)$ and $(\xi^2_T,\mathfrak{f}^2(\cdot),A)$, respectively. Then there exists a constant $\mathfrak{C}_{\beta}>0$ such that
	\begin{equation*}
		\begin{split}
			&\mathbb{E}\left[\sup_{0\leq t\leq T}\mathcal{E}(\beta A)_t |Y^1_t-Y^2_t|^2\right]
			+\mathbb{E}\left[\int_{0}^{T}\mathcal{E}(\beta A)_s |Y^1_{s-}-Y^2_{s-}|^2\,dA_s\right] 			
			+\mathbb{E}\left[\int_{0}^{T}\mathcal{E}(\beta A)_s\,d[M^1-M^2]_s\right] \\
			&\leq
			\mathfrak{C}_{\beta,\mathfrak{C}_{A}}
			\left(
			\mathbb{E}\left[\mathcal{E}(\beta A)_T |\xi^1_T-\xi^2_T|^2\right]
			+
			\mathbb{E}\left[\int_{0}^{T}\mathcal{E}(\beta A)_s
			|\mathfrak{f}^1(s)-\mathfrak{f}^2(s)|^2\,dA_s\right]
			\right).
		\end{split}
	\end{equation*}

