body:
[Theorem 12 ($\omega^2$-closure) of arXiv:2608.25925, '\textbf{Jump Closure and Limit Uniformization\\in the Ideal Completion of the Turing Degre'] The closure ordinal of $\Theta_{<\omega^2}$ from $\down\mathbf0$ is exactly
\[
\omega^2,
\]
and its least fixed point is
\begin{equation}
A_{\omega^2}
=
\bigcup_{\beta<\omega^2}\down\mathbf0^{(\beta)}.

\end{equation}

[Cor 44 of arXiv:2511.10535, 'Eigenvalues of Brownian Motions on $\mathrm{GL}(N,\mathbb{C})$'] There exists a constant $C_{\rho,t}$ such that, for any functions $f\in\CC^5(\R)$ with compact support bounded by $K$,
    \begin{equation} 
    \begin{aligned}
        &\left| \E\left[\ts_N\left(f\left(\left|B^N_0B^N(t)-z\right|^2\right)\right)\right] - \tau_N\left(f\left( |B^N_0b(t)-z|^2\right)\right) \right| \\
        &\leq C_{\rho,t} \sqrt{K} \frac{(1+|z|^4)(1+\norm{B^N_0}^4)\norm{f}_{\mathcal{C}^5(\R)}}{N^2},
    \end{aligned}
    \end{equation}
    where $\norm{f}_{\mathcal{C}^5(\R)} = \sum_{k=0}^5\sup_{x\in\R} |f^{(k)}(x)|$.

[Theorem 5 of arXiv:2511.00764, 'Further Developments on Stochastic Dominance for Convex\\ Combinations of Infinite-Mean Ra'] {\rm \citep{CHSZ25}}\ \ Let $\bm X=(X_1, \ldots, X_n)$ be a vector of iid random variables with a common distribution function $F$. If $F\in\mathcal{H}$, then ${\rm ({\red SD})}$ holds, i.e.,
$$
   \sum_{i=1}^n\eta_i X_i  \le_{\rm st} \sum_{i=1}^n\theta_i X_i  \eqno {\rm (SD)}
$$
for $\bm \theta, \bm \eta\in \R_+^n$ such that $\bm\theta \preceq_{\rm m} \bm \eta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem convergence-guided-diffusion of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] We study the guided diffusion dynamics specified by (equation eq:projected-gradient-guidance-relaxed of the paper) under Assumptions~(assump:linear of the paper) and~(assump:f-strongly-convex of the paper). Let $t_0 = \max\{t:\sigma_t^2 \le \lambda_{\min}(\Sigma)(1-c)/c\}$, where $c\in(0,1)$ is an arbitrary constant. We further assume a constant guidance step size satisfying $\eta_t=\eta<1/(\mu c)$ and $\eta\epsilon\le 1/L$ for all $t\le t_0$.
Define  
    \begin{align}
      \textstyle  \Phi_t(x):= f(x) + \frac{\sigma_t^2 \eta^{-1}}{2} x^\top A^\top \Sigma^{-1} Ax, \qquad x_t^\star = \argmin_{x\in \mathrm{range}(A^\top)} \Phi_t(x)
    \end{align}
    and
    \vspace{-10pt}
    \begin{align*}
       \textstyle  V_t(x):=  (\Phi_{t}(A^\top Ax) - \Phi_{t}(x_{t}^\star)) +  \frac{\eta L^2}{2(1-\eta\mu c)} \|A^\perp x\|^2 + \frac{\eta^{-1}D^2}{2(1-\eta\mu c)}\sigma_t^2,
    \end{align*}
    where $D = \max_{t\le t_0} \|Ax_t^\star\|_{\Sigma^{-1}}$.
    Then running (equation eq:projected-gradient-guidance-relaxed of the paper) starting from $t_0$ we have
    \begin{align*}
        V_{t-1}(x_{t-1}) \le (1-\eta \epsilon \mu c) V_t(x_{t}), ~~\forall t\le t_0
    \end{align*}
    Hence, letting $x^\star
    :=
    \argmin_{x\in\mathrm{range}(A^\top)}f(x),$
the projected component satisfies
\begin{align*}
    f(A^\top Ax_0)-f(x^\star)
    &\textstyle \le
    (1-\eta\epsilon\mu c)^{t_0}V_{t_0}(x_{t_0})
    +
    (1-\epsilon)^{2t_0}\frac{\sigma_T^2}{2\eta}\|Ax^\star\|_{\Sigma^{-1}}^2,
\end{align*}
while the normal component satisfies
    $\|A^\perp x_0\|
    =
    (1-\epsilon)^{t_0}\|A^\perp x_{t_0}\|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lmboundextwo of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] Suppose a population evolves according to Def.\ (hapltwo of the paper). Then there is a constant $B > 0$ with 
\begin{esplit}{eqboundextwo}
 \frac{(N)_2}{c_N} \EE{ \frac{X_1(X_1 - 1)X_2(X_2 - 1) }{ (S_N)_4 }\ensuremath{\mathds{1}_{\left\{ S_N \ge N \right\}}} | \ensuremath{{\alpha_1}}, \ensuremath{{\kappa}} }\frac{ \varepsilon_N}{(N)_2} \ge   \frac{B}{N^{\ensuremath{{\alpha_1}}+\ensuremath{{\kappa}}-1 }} \varepsilon_N
\end{esplit}
for all $k_1, k_2 \ge 2$.

