[Definition def:pll-constraint-model of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] {fairtlough_propositional_1997}}] 
  $\mathfrak{M} = (W, W_\bot, \leq, \sqsubset, V)$ is a \emph{Kripke constraint model}
  if $(W, \leq, \sqsubset, V)$ is a $\sqsubset$-preordered and $\sqsubset$-strong f-model,
  $W_\bot \subseteq W$ is upward closed with respect to $\leq$,
  and $W_\bot \subseteq V(p)$ for every $p \in \mathord{\mathrm{PropVar}}$.
  A satisfaction relation ${\Vdash_\mathfrak{M}} \subseteq W \times \mathscr{L}_{\bigcirc}$ for $\mathfrak{M}$ is defined as follows:
  \begin{itemize}
    \item $x \Vdash_\mathfrak{M} \bot \mathrel{\;\ratio\Longleftrightarrow\;} x \in W_\bot$;
    \item $x \Vdash_\mathfrak{M} \psi_1 \to \psi_2
      \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x\, (x' \Vdash_\mathfrak{M} \psi_1 \mathrel{\Rightarrow} x' \Vdash_\mathfrak{M} \psi_2)$;
    \item $x \Vdash_\mathfrak{M} \bigcirc \varphi
      \mathrel{\;\ratio\Longleftrightarrow\;} \forall x' \geq x\, \exists y' \sqsupset x'\, (y' \Vdash_\mathfrak{M} \varphi)$;
    \item The other cases are identical to the classical one.
  \end{itemize}
  We write $\mathfrak{M} \vDash \varphi$ iff $x \Vdash_\mathfrak{M} \varphi$ for every $x \in W$.

[Corollary 24 (Weak endpoint for one ordered contraction) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $1<r<\infty$ and, for finite-support kernels, set
\begin{align}
 \Prof_{m,r}^{\mathrm w}(K)
 &:=
 \max_{S\subset[m]}
 \norm{\Flat_S(K)}_{\Sch_{r,\infty}},
 \\
 \Prof_{m,r}^{\mathrm{wlog}}(K)
 &:=
 \max_{S\subset[m]}
 \norm{\Flat_S(K)}
  _{\Sch_{r,\infty}(\log\Sch)^{-1/r}}.

\end{align}
For every cross pairing $P\in\mathfrak M_{m,n}$,
\begin{equation}

 \Prof_{q(P),r}^{\mathrm{wlog}}(L\circ_PK)
 \le C_r
 \Prof_{n,r}^{\mathrm w}(L)
 \Prof_{m,r}^{\mathrm w}(K).
\end{equation}
If $K$ and $L$ are same-field kernels, then also
\begin{equation}

 \Prof_{q(P),r}^{\mathrm{wlog}}
 \bigl(\operatorname{Sym}_{q(P)}(L\circ_PK)\bigr)
 \le C_r
 \Prof_{n,r}^{\mathrm w}(L)
 \Prof_{m,r}^{\mathrm w}(K).
\end{equation}

[Theorem t:capuniv of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Let $\alpha \in [0,d)$, and let $f$ be an SGF on $\mathbb{R}^d$ or $\mathbb{Z}^d$ satisfying one of the conditions~(item:1 of the paper), (item:2 of the paper), (item:3 of the paper) or (item:4 of the paper) in Theorem~(t: univ pro of the paper).  Then
\begin{equation}

\text{\textup{Cap}}_f(B(T)) \sim \frac{c_{\alpha,d}}{\mu[B(\tfrac 1 T)]}, \quad \text{ as }T\to\infty .
\end{equation}
If, in addition, $\mu$ is origin dominant~(equation e:ds of the paper), then for every $\eta \in \mathcal{M}_c^\infty$ (required to be radial in case~(item:3 of the paper)),
 \begin{equation}

  \lim_{T \to \infty}\langle h_T, \eta_T \rangle =  \langle h_{\alpha,d}, \eta \rangle  \in (-\infty,\infty) .  
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:annealed cond of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $n\ge2$. Let $\bm{u}=(u_1,\ldots,u_{n})$,
		$\bm{q}=(q_1,\ldots,q_n)$ be strictly increasing
		in~$(0,1)$, and $\zeta\in\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})$.
		Define the \emph{prefix free energy}
		\begin{equation}
			\mathcal{P}^{(n)}(\bm{u};\bm{q})
			\;:=\;
			\inf_{\zeta'\,\in\,\mathrm{Prefix}_{n+1}(\bm{u};\bm{q})}
			\mathcal{P}\mathrm{arisi}(\zeta'),
		\end{equation}
		and the \emph{$n$-step complexity functional at level $f$}
		\begin{equation}
			\mathcal{C}^{(n)}_f(\bm{u};\bm{q})
			\;:=\;
			u_n\,\bigl(\mathcal{P}^{(n)}(\bm{u};\bm{q})-f\bigr).
		\end{equation}

		We assume:
		\begin{enumerate}
			\item[\emph{(i)}]
			\emph{(Tail optimality)} The infimum $\mathcal{P}^{(n)}(\bm{u};\bm{q})$ is
			attained at $\zeta$.
			\item[\emph{(ii)}]
			\emph{(Stationarity)} $(\bm{u};\bm{q})$ is a critical point of
			$\mathcal{C}^{(n)}_f$.
		\end{enumerate}
		Let $\varepsilon\in(0,1)$, let
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)})\in\mathrm{SUSY}_{n-1}(\zeta,\varepsilon)\cap\mathrm{LawMatch}_{n-1}(\zeta,\varepsilon)$. Let
		$\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})$ be the number of critical points $\mathbf{m}$
		of $F_{\mathrm{TAP},\zeta}$ with
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n-1)},\mathbf{m})\in\mathrm{SUSY}_n(\zeta,\varepsilon)$ and
		$\tfrac{1}{N}F_{\mathrm{TAP},\zeta}(\mathbf{m})\in(f-\varepsilon,f+\varepsilon)$. Set
		\begin{equation*}
			\mathrm{Skel}_{n-1}=\left(\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(1)}),\ldots,\nabla F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)}), F_{\mathrm{TAP},\zeta}(\mathbf{m}^{(n-1)})\right).
		\end{equation*} Then
		\begin{multline}
			\lim_{\varepsilon\to0}\lim_{N\to\infty}
			\frac{1}{N}\log\mathbb{E}\Bigl[
			\mathcal{N}_\varepsilon(f,\zeta,q_n,\mathbf{m}^{(n-1)})
			\;\Big|\;
			\mathrm{Skel}_{n-1}=(0,N\mathcal{P}\mathrm{arisi}(\zeta),\ldots,0,N\mathcal{P}\mathrm{arisi}(\zeta))
			\Bigr]
			=
			\mathcal{C}_f^{(n)}(\bm{u};\bm{q})
			\\=
			\zeta([0,q_n))\,(\mathcal{P}\mathrm{arisi}(\zeta)-f).
		\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: lateStop of arXiv:2606.19583, 'Power-law hypothesis and (un)fairness of PageRank on undirected multi-type PAMs'] For every $t>0, \alpha>0$ and $k \in S$,

\begin{equation*}
\begin{split}\limsup_{r \to \infty}\mathbb{P}_k^{\mathcal{T}}\left( d_\phi^{\scriptscriptstyle(-,\geq \alpha)} 
\geq pd^-_\phi \mid d_\phi^- =r\right) \leq \limsup_{r \to \infty}\mathbb{P}_k^{\mathcal{T}}\left( d_\phi^{\scriptscriptstyle(-,\geq \alpha)} 
\geq pd^-_\phi \mid d_\phi^- =r, \ \tau = \sum_{j=1}^r \tilde{\tau}_k^{\scriptscriptstyle(j)}+t\right)
\end{split}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

