body:
[Problem problem-kac of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Let
    \begin{align}
        \Phi(x,y)=\frac{1}{\tfrac{1}{x}+\tfrac{1}{y}-1}.
    \end{align}
    Prove that if
    \begin{align}
        \Phi\left(
            \int_{-\infty}^{+\infty} e^{i\xi t}\,d\sigma_1(t),
            \int_{-\infty}^{+\infty} e^{i\xi t}\,d\sigma_2(t)
        \right)
        =\frac{1}{1+\xi^2},
    \end{align}
    then $\sigma_1$ and $\sigma_2$ are centered Laplace distributions. (Stated as a problem by the paper; open unless the paper says otherwise.)

[Theorem MZ2016 recentered maximum until the log T term of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Let $M_{\mathbf{T}}$ denote the maximal displacement at time $\mathbf{T}$ of the branching Brownian motion with the same variance profile $\sigma(t)=\widetilde{\sigma}(t/\mathbf{T})$ as in Lemma (lemma: macro BBM, lower bound of the paper). Set
	\begin{equation}
		\begin{aligned}
			m_{\mathbf{T}}
			&:=\sqrt{2}\int_0^{\mathbf{T}}\sigma(t)\,\text{d} t
			-(\sqrt{2})^{-1/3}\alpha_1 2^{-1/3}
			\int_0^{\mathbf{T}}
			\lvert\sigma'(t)\rvert^{2/3}
			\lvert\sigma(t)\rvert^{1/3}\,\text{d} t -\frac{\sigma(\mathbf{T})}{\sqrt{2}}\log \mathbf{T},
		\end{aligned}
	\end{equation}
	where $-\alpha_1$ is the largest zero of the Airy function $\mathrm{Ai}$, as in (equation eqA: Airy eigenvalues of the paper). Then there exists $C>0$ such that
	\begin{equation}
		\lvert M_{\mathbf{T}}-m_{\mathbf{T}}\rvert
	\end{equation}
	converges in law as $T\to\infty$ and there is $C>0$ such that
	\begin{equation}
		\mathbb{P}\Bigl(
		\lvert M_{\mathbf{T}}-m_{\mathbf{T}}\rvert\le K
		\Bigr)
		\ge CK\exp\Bigl\{-\frac{K}{\sigma(0)}\Bigr\},
	\end{equation}
	uniformly for all $k\in[1,\mathbf{T}^{1/3}]$ when $\mathbf{T}$ is large. (Proof in the paper; no proof environment follows the statement in the TeX.)

