body:
[Definition 2 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $E$ be a locally compact  and separable Banach space. An $\mathbb{R}\times E$-valued regular strong Markov process $(\xi,\Xi)=(\xi_t,\Xi_t)_{t\geq0}$, living in some (filtered) probability space $(\Omega,\mathcal{G},(\mathcal{G}_t)_{t\geq0},\mathbb{P})$, with probabilities $\left(\mathbb{P}_{(x,\theta)}, (x,\theta)\in\mathbb{R}\times E\right)$, and cemetery state $(-\infty,\partial)$, where $\partial$ is a point not in $E$, is called a \textit{Markov additive process (MAP)} if $\Xi=(\Xi_t)_{t\geq0}$ is a regular strong Markov process on $E$ with cemetery state $\partial$ such that, for every bounded measurable function $f:\mathbb{R}\times E\to \mathbb{R}^{+}$, $t,s\geq0$ and $(y,\theta)\in\mathbb{R}\times E$,
	\begin{equation}

		\mathbb{E}_{(y,\theta)}[f(\xi_{t+s}-\xi_t,\Xi_{t+s})\mathbbm{1}_{\{t+s<\zeta\}}|\mathcal{G}_t]=\mathbb{E}_{(0,\theta')}[f(\xi_{s},\Xi_{s})\mathbbm{1}_{\{s<\zeta\}}]\Bigr|_{\substack{\theta'=\Xi_t}},\quad \mathbb{P}_{(y,\theta)}-\text{a.s.},
	\end{equation} 
	where as usual $\zeta\coloneqq \inf\{t>0:\Xi_t=\partial\}$ denotes the lifetime of $(\xi,\Xi)$. We call the process $\Xi=(\Xi_t)_{t\geq0}$ the \textit{modulator} of the MAP, and $\xi=(\xi_t)_{t\geq0}$ the \textit{ordinate}.

[Corollary 19 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $T = \E X>0$ and $X \sim f \dd \pi_{T}.$ Then, if $f: \N \rightarrow (0,\infty)$ log-concave
     \begin{displaymath}
         H \Big( \sum_{i=1}^{n} T_{1/n}(X_{i}) |\pi_{T} \Big) \le  \frac{1}{n(n-1)} T^{2}  +  \frac{1}{n (n-1)^{2} } \frac{T^{3}}{4}
     \end{displaymath}
     and for large enough $n,$ 
     \begin{displaymath}
          H \Big( \sum_{i=1}^{n} T_{1/n}(X_{i}) |\pi_{T} \Big) \le c  \frac{T^{2}}{n^{2}} 
     \end{displaymath}
     for $c>1$ constant arbitrarily close to 1.

[Definition def:matroid of arXiv:2605.01444, 'From second moments to pairwise negative correlation: \\applications to minimal and unifor'] A matroid ${\ensuremath{\mathscr M}} =(E,{\ensuremath{\mathcal I}} )$ consists of a finite ground set $E$ and a collection ${\ensuremath{\mathcal I}} \subset 2^{E}$ of independent sets satisfying:
	\begin{enumerate}
		\item[(1)] $\emptyset\in{\ensuremath{\mathcal I}} $;

		\item[(2)] if $A\in{\ensuremath{\mathcal I}} $ and $B\subset A$, then $B\in{\ensuremath{\mathcal I}} $;

		\item[(3)] if $A,B\in{\ensuremath{\mathcal I}} $ and $|A|<|B|$, then $\exists e\in B\setminus A$ such that $A\cup\{e\}\in{\ensuremath{\mathcal I}} $. 
	\end{enumerate}
The rank function $r:2^E\to{\ensuremath{\mathbb Z}} _{\;\geqslant\;0}$ associated ${\ensuremath{\mathscr M}} $ is given by 
\[
r(S)\coloneq \max\left\{ |A|  \,\,\big|\,\, A\subset S,A\in{\ensuremath{\mathcal I}}   \right\}\,.
\]

[Lemma lem:I[eps,G] of arXiv:2510.09818, 'On the Fourier dimension of fractional Brownian graphs'] [LL25]
	For any $\varepsilon \in \{-1,1\}^{2q}$, let $G_\varepsilon$ be as defined in (equation lambda,T of the paper) and $\mathcal{I}[\varepsilon, G_\varepsilon]$ as introduced in~(equation I of the paper). Also recall that $\Sigma(q)$ is the set given by~(equation b4 of the paper).
	Then
	\begin{align}
		\mathcal{I}[\varepsilon, G_\varepsilon] = 
		\left( \frac{1}{2\pi i \lambda} \right)^q 
		\prod_{j=1}^q \frac{1}{\varepsilon_{2j-1}} \sum_{\sigma \in \Sigma(q)} 
		\mathcal{I}[\sigma; \varepsilon, G_\varepsilon].
	\end{align}
	Here, $\mathcal{I}[\sigma; \varepsilon, G_\varepsilon]$ is defined by 

	\begin{align}
		\mathcal{I}[\sigma; \varepsilon, G_\varepsilon] := (-1)^{\# J_2(\sigma)} \mathcal{I}[\sigma_{k_m}\cdots\sigma_{k_1}(\varepsilon)\,,\, \sigma_{2q-1} \cdots \sigma_3 \sigma_1 (G_\varepsilon)],
	\end{align}
	where the indices $k_1,\dots,k_m$ are given by (equation J1uJ2 of the paper) above, $\sigma_{k_m}\cdots\sigma_{k_1}(\varepsilon)$ is defined through the actions of $\sigma_j \in \Sigma_j$ on $\varepsilon$ introduced in Definition (def:Phi-j of the paper), $\sigma_{2q-1} \cdots \sigma_1 (G_\varepsilon)$ is defined through the actions of $\sigma_j$ on functions given by (equation Phi-G of the paper) and (equation Phi+G of the paper),
	and $\mathcal{I}[\sigma_{k_m}\cdots\sigma_{k_1}(\varepsilon)\,,\, \sigma_{2q-1} \cdots \sigma_1 (G_\varepsilon)]$ is defined according to (equation I[alpha,G] of the paper) above. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:minimal-m of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:moment-thresholds}
For every \(p\ge3\), matching only the mean and variance suffices for the regularized bulk-pressure conclusion (equation eq:pressure-univ-weak of the paper).  The least matching order sufficient for the ratio conclusion is
\begin{equation}
 m_\star(p)=\left\lfloor\frac{2}{p-2}\right\rfloor+2
 =\begin{cases}
 4,&p=3,\\
 3,&p=4,\\
 2,&p\ge5.
 \end{cases}
\end{equation}
In particular, matching only mean and variance suffices for the stronger ratio conclusion when \(p\ge5\).

[Lemma 9 (Theorem 6.1 in \cite{Adamczak_PTRF}) of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] In the case $1\le \alpha\le 2$, we have  for $r\ge 2$
\begin{align}
		\Big\Vert \sum_{i,j}a_{ij}\xi_{i}\tilde{\xi}_{j}\Big\Vert_{L_{r}}\asymp_{\alpha}&r^{1/2}\Vert A\Vert_{F}+r\Vert A\Vert_{l_{2}\to l_{2}}+r^{1/\alpha}\Vert A\Vert_{l_{\alpha^{*}}(l_{2})}\nonumber\\
		&+r^{(\alpha+2)/2\alpha}\Vert A\Vert_{l_{2}\to l_{\alpha^{*}}}+r^{2/\alpha}\Vert A\Vert_{l_{\alpha}\to l_{\alpha^{*}}},\nonumber
	\end{align}
    where $\Vert A\Vert_{l_{\alpha*}(l_2)}$ is defined in \eqref{matrix_norm}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Pro 2 of arXiv:2608.00811, 'Comparison of Dirichlet forms for stable-like random walks on groups of polynomial volume '] Given two pairs of tuples $(S,\mathbf v)$ and $(\tilde{S},\tilde{\mathbf v})$, we have
$$\|\cdot\|_{S,\mathbf v}\asymp \|\cdot\|_{\tilde{S},\tilde{\mathbf v}
} $$  if and only if
$$\mathfrak w_{S,\mathbf v}(s)=\mathfrak w_{\tilde{S},\tilde{\mathbf v}}(s)
\mbox{ for all } s\in \mbox{core}(S,\mathbf{v}) \cup \mbox{core}(\tilde{S}, \tilde{\mathbf{v}}).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 69 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] For any $\tau\in\dot\mcT$ we have
	\begin{equation}
		\Delta \, j_*(\tau) = (j_*\otimes j_*)\Delta \tau,
	\end{equation}
	and for any $\tau\in\mcT$
	\begin{equation}
		\Delta \, j_*(D_\Xi\tau) = \big(\id\otimes j_*D_\Xi+j_*D_\Xi\otimes \id\big)\Delta\tau
	\end{equation}

[Satz thm:powers of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d,k\in\mathds{N}$, $s,\alpha,\beta,\gamma,\theta\in\mathds{R}$, $p,q\in (0,\infty]$, and $r\in (0,\infty)$.
Assume that $a$ follows a Besov sequence prior and $f$ follows a Besov prior, both with parameters $(\alpha,\beta,\gamma,\theta,k)$ and template random variable $X$, satisfying
\begin{equation}
\begin{cases}\:\exists\: \eps>0:\,\mathds{E}\left[\left\lvertX\right\rvert^{(1+\eps)\max\left\{r,p\right\}}\right]<\infty&\text{if }p\in (0,\infty),\\
\:\exists\: R>0:\,\left\lvertX\right\rvert\stackrel{a.s.}{\leq} R&\text{if }p=\infty.\end{cases}
\end{equation}
If Property A holds, then we have $\mathds{E}[\left\lVerta\right\rVert_{b^s_{p,q}(\mathds{R}^d)}^r]<\infty$.
Moreover, if Properties A and B are satisfied, then we have $\mathds{E}[\left\lVertf\right\rVert_{B^s_{p,q}(\mathds{R}^d)}^r]<\infty$.

