[Proposition prop:risk-severity of arXiv:2608.23860, 'Revelation Control'] Let $\rho=\Pr(S=1)$ and $r=\Pr(S=1,F=1)$. When $r>0$, define the signed stopped-flip severity $\eta_s=\mathbb E[Y\mid S=1,F=1]$ and the positive-harm severity $\eta_+=\mathbb E[Y_+\mid S=1,F=1]$, where $Y_+=\max(Y,0)$. When $r=0$, set $\eta_s=\eta_+=0$ by convention. Then
\begin{equation}
\boxed{\Delta V(S)=\mathbb E[S(c-Y)]=c\rho-r\eta_s.}

\end{equation}
Moreover,
\begin{equation}
\Delta V(S)\ge c\rho-r\eta_+.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 of arXiv:2607.26944, 'Improved bounds on the inradius and inverse inradius process of the convex hull of planar '] For $m \ge 1$, let  
\begin{equation}
    A_m \coloneqq 
\frac{e^{-(2m-1)\pi}}{(1+e^{-(2m-1)\pi})^2}
+\frac{e^{-(2m-1)\pi}}{\pi(2m-1)(1+e^{-(2m-1)\pi})}
+\frac{\log(1+e^{-(2m-1)\pi})}{\pi^2(2m-1)^2}.
\end{equation} Then, it follows that
\begin{equation}
    \E[\sfr^2] \le \frac{1}{4}\E  \mleft[\min\{R_1,R_2\}^2\mright]
=
\frac{1}{2}\int_0^\infty x  \p(R_1\ge x)^2 \D x= 2\log 2
-16\sum_{m=1}^\infty A_m.
\end{equation} Moreover, since $A_m >0$ for all $m \ge 1$, it holds that 
\begin{equation}
    \E  \mleft[\min\{R_1, R_2\}^2\mright]
\;\le\;
8\log 2-64\sum_{m=1}^5 A_m < 1.87988,
\end{equation} yielding that 
\begin{equation}
    \Var(\sfr) < 0.315520.
\end{equation}

