[Lemma 19 (Reciprocal-$\cosh$ integrals) of arXiv:2608.06523, 'On the Gardner Transition in the Ising Pure $p$-Spin Glass II'] For every $r>0$,
\begin{align}
\frac r{r+1}
&\leq
\frac{\int_{\mathbb R}e^{-x^2/(2\xi'(q))}\cosh^{-(r+2)}x\,dx}
     {\int_{\mathbb R}e^{-x^2/(2\xi'(q))}\cosh^{-r}x\,dx}
\leq
\frac r{r+1}+\frac1{\xi'(q)r(r+1)}.

\end{align}
Moreover,
\begin{align}
&\frac{\int_{\mathbb R}\cosh^{-r}x\,dx}
 {\sqrt{2\pi\left(\xi'(q)+2\sum_{j\geq0}(r+2j)^{-2}\right)}}
\leq
\frac{\int_{\mathbb R}e^{-x^2/(2\xi'(q))}\cosh^{-r}x\,dx}
 {\sqrt{2\pi\xi'(q)}}\notag\\
&\hspace{43mm}\leq
\frac{\int_{\mathbb R}\cosh^{-r}x\,dx}
 {\sqrt{2\pi\xi'(q)}}.

\end{align}

