body:
[Definition 40 (Represented four-copy functional) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $q\ge2$ and $\xi=[f_n]_{\mathcal U}\in\cH_q$, define
\begin{equation}
 \mathfrak Q_q(\xi)
 =\Ulim\left\{
  \E[I_q^{W_n}(f_n)^4]
  -3\E[I_q^{W_n}(f_n)^2]^2
 \right\}.

\end{equation}

[Defin def:augmented-stable of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] A L\'evy process $\bm{X}=(\bm{X}_t)_{t \in [0,1]}$ is an augmented $\alpha$-stable process if it has no Gaussian component, and, for some $\alpha\in(0,2]$, its L\'evy measure $\nu_{\bm{X}}$ has the form
\begin{equation} 
\nu_{\bm{X}}(A)
= \int_0^\infty\int_{\mathbb{S}^{d-1}}  \1_{A}(x\bm{v}) \mathcal{Q}(x,\bm{v})  \sigma(\mathrm{d} \bm{v})x^{-\alpha-1}\mathrm{d} x, \quad \text{ for } A \in \mathcal{B}(\mathbb{R}^d_{\bm{0}}),
\end{equation}
where $\sigma$ is a probability measure on $\mathcal{B}(\mathbb{S}^{d-1})$ and $\mathcal{Q}:(0,\infty)\times \mathbb{S}^{d-1} \mapsto [0,\infty)$ is a measurable satisfying $\mathcal{Q}(\cdot,\bm{v})\in\mbox{SV}_0$ for $\bm{v}\in\mathbb{S}^{d-1}$.

[Theorem thm: thm2 of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] There exists an absolute constant $C>0$ such that for every integer $1\leq j \leq m$ and real number $p \geq 2$,
    \begin{align*}
    \mathbb E^{1/p} \sup_{h \in \mathcal{H}_m} \lvert V_{N,j}(h) \rvert^p  \leq C^j\max\left\{A_1(p,j), A_2(p,j), A_3(p,j)\right\},  
\end{align*}
where
\begin{align*}
    A_1(p,j) &=  p^{j/2} \Sigma_{\mathcal H_m} \,, 
    \\
    \\
    A_2(p,j) &= p^{j/2}\left(\frac{m}{j}\right)^{j/2}\left(\frac{j}{N}\right)^{1/4} \left( p\sqrt{\frac{j}{N}}\bigvee \mathbb E \gamma_2 (\mathcal{H}_m, d^{(2)}_{N,j})\right)^{1/2}
    \\
    A_3(p,j) & =  \mathbb E^{1/p} \left(\gamma_{2/j, \lfloor \log_2 (pj)\rfloor}\left(\mathcal{H}_m, d^{(1)}_{N,j}\right) \right)^p  \,.\\
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Fix $T>0.$ Let $X$ be a random variable whose density $f : \N \rightarrow (0, \infty) $ with respect to $\pi_{T}$ is ultra log-concave, then we have
\begin{displaymath}
    \delta_{\mathrm{FI}}(f) \ge a(1-a)T^{2} \Delta_{\frac{f(0)}{f(1)}} \Bigg( \frac{\E X}{T} \Bigg)
\end{displaymath}
where, for $c>0,$ we denote
\begin{displaymath}
    \Delta_{c}(z):= z^{5} \Big( \frac{c}{1 + cz} \Big)^{2}  , \quad z\ge 0.
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 46 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $(t_l)_{l \in \mathbb{N}} \subset \mathbb{R}, \ \lim_{l \rightarrow \infty} t_l = t_{\infty} \in \mathbb{R}$, and $h_k(t_l)$ converge as $l \rightarrow \infty$. Then
\begin{equation}
h_k(t_\infty) \geq \lim_{l \rightarrow \infty} h_k(t_l).
\end{equation}

[Theo 4 (\rm Asymptotic behavior of the return probabilities for random walks  in cone) of arXiv:2603.26228, 'A local limit theorem for nonlattice multidimensional random walks in cones'] Assume  hypotheses  {\bf C},  {\bf M},  {\bf N} and {\bf A}.  Let ${\bf B}_1\subset \mathbb R^s$ be a  bounded Borel  set  whose boundary is negligible with respect to the Lebesgue measure on $\mathbb R^s$   and $ {\bf y}_2\in G_2$ such that ${\bf B}:= {\bf B}_1\times \{{\bf y}_2\}\subset \mathcal C$.  Then,  there exists  a  constant $\mathrm{C}$ such that,    for any $n \geq 1$ and $  {\bf x} \in \cC$,
\begin{equation}
\bP( \tau({\bf x})>n, {\bf x}  +S(n) \in  {\bf B})\leq   
\mathrm{C} \  { 1+\vert {\bf x}\vert^p \over n^{p+d/2}} \  \int_{{\bf B}_1}\widetilde{V}({\bf y}_1, {\bf y}_2) {\rm d} {\bf y}_1.
\end{equation}
Furthermore,   as $n \to +\infty$,  
\begin{equation}
\bP( \tau({\bf x})>n,  {\bf x}  +S(n) \in  {\bf B})\sim  
\mathfrak \kappa_1  { V({\bf x})\over n^{p+d/2}} \int_{{\bf B}_1}\widetilde{V}({\bf y}_1, {\bf y}_2) {\rm d} {\bf y}_1,
\end{equation}
where $\widetilde V$ is the harmonic function  for the random walk $(-S(n))_{n \geq 0}$   killed at   time $\tilde{\tau}$ of leaving $\mathcal C$ and $\kappa_1= \kappa_0^2H_0^2  \int_{\mathcal C} u^2({\bf y}) e^{-\vert {\bf y}\vert^2/2}{\rm d}{\bf y}.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $r>0$ and an even number $n=2N$. For $\bs{\alpha}, \bs{\beta}\in\LX_n$, we write $\bs{x}=\ee^{\ii\bs{\alpha}}$ and $\bs{y}=\ee^{\ii\bs{\beta}-r}$.
Let $\varphiann{n}$ be the bounded harmonic function in annulus $\A_r$ with alternating boundary data~\eqref{eqn::boundarydata}. Then
\begin{align} 
	\begin{split}
		\| \varphiann{n} \|_{\nabla(\A_r),\mathrm{reg}}^2= & \frac{\pi}{2r}\left(\sum_{j=1}^{n}(-1)^j (\alpha_j-\beta_j) \right)^2-6n\pi \sum_{m=1}^{\infty} \log \left(  1-\ee^{-2mr} \right) - \frac{n}{2}\pi r \\
		& - 2\pi \sum_{1\le i<j \le n} (-1)^{j-i} \left( \log \left| \Theta_1(r; \beta_{j}-\beta_i) \right| +\log \left| \Theta_1(r; \alpha_{j}-\alpha_i) \right| \right) \\
		& +2 \pi \sum_{i=1}^{n} \sum_{j=1}^{n} (-1)^{j-i} \log \left| \Theta_3(r; \beta_{j}-\alpha_i) \right| .
	\end{split}
\end{align}
Moreover, its regularized Dirichlet energy is related to the partition function $\LZann{n}$ in~\eqref{eqn::LZann_def}: 
\begin{align}
\LZann{n}(r; \bs{\alpha}, \bs{\beta})=\exp\left(-\frac{1}{4\pi}\| \varphiann{n} \|_{\nabla(\A_r),\mathrm{reg}}^2\right). 
\end{align}

