[Corollary mgf of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] For any direction parameters $\rho_1, \dots, \rho_n \in (0,1)$, any down-right path $\mathcal{Y} = (\mathbf y_i)_{i\in \mathbb{Z}}$, and any $\alpha_1,\ldots,\alpha_n\ge0$, we have
\begin{subequations} 
\begin{align} 
\mathbb{E}\Big[\exp\Big(\sum_{i=1}^n \alpha_i B^{\rho_i}_{\mathbf y_i, \mathbf y_{i+1}}\Big)\Big]
&\leq \prod_{i=1}^n \mathbb{E}\big[\exp\big(\alpha_i B^{\rho_i}_{\mathbf y_i, \mathbf y_{i+1}}\big)\big] \\
\text{and}\quad 
\mathbb{E}\Big[\exp\Big(-\sum_{i=1}^n \alpha_i B^{\rho_i}_{\mathbf y_i, \mathbf y_{i+1}}\Big)\Big]
&\leq \prod_{i=1}^n \mathbb{E}\big[\exp\big(-\alpha_i B^{\rho_i}_{\mathbf y_i, \mathbf y_{i+1}}\big)\big].
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 34 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Under the assumptions of Theorem \ref{distribution of outliers}, for each $1\le i\le r$ and $1\le \mu \le s$, we have 
\begin{align}
\wt\lambda_{\alpha(i)}-\theta_i^a&=-\frac{1}{\sigma_i^am'_{2c}(\theta_i^a)}\pa{\frac{d_i^a}{d_i^a+1}}^2\cdot\theta_i^a\vv_i^*\pa{G(\theta_i^a)-\Pi(\theta_i^a)}\vv_i+\OO_{\prec}(n^{-1}),\\
\wt\lambda_{\beta(\mu)}-\theta_\mu^b&=-\frac{1}{\sigma_\mu^bm'_{1c}(\theta_\mu^b)}\pbb{\frac{d_\mu^b}{d_\mu^b+1}}^2\cdot\theta_\mu^b \uu_\mu^*\pa{G(\theta_\mu^b)-\Pi(\theta_\mu^b)}\uu_\mu+\OO_{\prec}(n^{-1}).
\end{align}
where $\vv_i:=((\vv_i^a)^T, 0)^T\in\RR^{p+n}$ and $\uu_\mu:= (0^T, (\vv_\mu^b)^T)^T\in\RR^{p+n}$ are the canonical extensions of the population eigenvectors $\vv_i^a$ and $\vv_\mu^b$ to $\RR^{p+n}$, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t2.1 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] Suppose that the assumptions $(\mathbf{A}_{\text{slow}})$, $(\mathbf{A}_{\text{fast}})$, $(\mathbf{H}_1)$ and $(\mathbf{H}_2)$ hold and that $\delta = o(\varepsilon)$.

	\vspace{1mm}
	\textbf{Case 1.} $[$$\sigma$ is independent of $y$ $($i.e.~$\sigma(x,\mu,y,\nu)\equiv\sigma(x,\mu,\nu)$$)]$.  $\{X^\varepsilon\}_{\varepsilon\in(0,1)}$  satisfies the LDP with the good rate function $I$ given by
	\begin{equation}
		I(\varphi):=\inf_{(\varphi,{\boldsymbol{ {\Pi}}})\in\mathscr{V}_{(x,\bar{X},\Theta,\nu^{\mathscr{L}_{\bar{X}}})}}\left\{\frac{1}{2}\int_{\mathbb{R}^d\times\mathbb{R}^m\times\mathscr{P}_2({\mathbb R}^m)\times[0,T]}|h|^{2} {\boldsymbol{ {\Pi}}}(dhdyd\rho dt)\right\},
	\end{equation}
	with the convention that $\inf\emptyset= \infty$.

	\vspace{1mm}
	\textbf{Case 2.} $[$$\sigma$ depends on $y$$]$. Suppose further that the assumption $(\mathbf{H}_3)$ holds. Then $\{X^\varepsilon\}_{\varepsilon\in(0,1)}$  satisfies the LDP with the good rate function $I$ given by $((sulv of the paper))$.
	Furthermore, the rate function $I$ admits the following explicit representation
	\begin{align}
		{I(\varphi)=\begin{cases}\frac{1}{2}\int_0^T|Q_2^{-1/2}(\varphi_{t},\mathscr{L}_{\bar{X}_t},\nu^{\mathscr{L}_{\bar{X}_t}})(\dot{\varphi}_t-\bar{b}(\varphi_t,\mathscr{L}_{\bar{X}_t}))|^2dt,&\varphi \in \mathscr{H} ,\\+\infty,&otherwise,\end{cases}}
	\end{align}
	where
	$\mathscr{H}:=\big\{ \varphi : \varphi_0=x, \varphi~\text{is absolutely continuous}\big\}$, and
	\begin{align}
		Q_{2}(\varphi_{t},\mathscr{L}_{\bar{X}_{t}},\nu^{\mathscr{L}_{\bar{X}_t}}):=\int_{\mathbb{R}^m}\sigma(\varphi_{t},\mathscr{L}_{\bar{X}_{t}},y,\nu^{\mathscr{L}_{\bar{X}_t}})  \pi_1 \pi_1^*\sigma ^{*}(\varphi_{t},\mathscr{L}_{\bar{X}_{t}},y,\nu^{\mathscr{L}_{\bar{X}_t}}) \nu^{\mathscr{L}_{\bar{X}_t}}(dy).
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

