body:
[Proposition prop:plateauInt of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Assume (equation asmp:obsRG of the paper) and $Y$ be an $\R^n$-valued random variable as in Lemma~(lemma:NGcnst of the paper).  Then
\begin{align}
	\langle \varphi_{\sf o}^{(1)} \varphi_{\sf x}^{(1)} \rangle_{g,\nu, \Lambda} &=  w_N ({\sf x}) +  \frac{(h'_N)^2 \E [ |Y|^2] }{n} + \psi_1 ({\sf x}) + \psi_2 ({\sf x},N)
\end{align}
as $N\rightarrow \infty$,  
where $\psi_1 ({\sf x})$ is a function independent of $N$ such that $\lim_{|{\sf x}|\rightarrow \infty} |{\sf x}|^{d-2+\eta} \psi_1 ({\sf x}) =0$ and $|\psi_2 ({\sf x} , N)| \le c_N ( (h'_N)^2 + (1 \vee |{\sf x}|)^{-(d-2+\eta)} )$ for some sequence $\lim_{N\rightarrow \infty} c_N =0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:sde_non_unique of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] \begin{enumerate}[label=(\roman*)]
	\item Weak uniqueness does not hold for 
		\begin{equation}
					dx_t =  \mathbbm{1}_{x_t>0}dt + \sqrt{x_t}dB_t,  \quad x_0 =0, \quad t \geq 0.
	\end{equation}
	\item  The solutions to 
	\begin{equation}
		dx_t =  h_{c,1}(x_t)dt + \sqrt{x_t}dB_t,  \quad t \geq 0, 
	\end{equation}
	have the same law for each $c \in (0,1)$. 
	\item   There exists no solution to the equation
	\begin{equation}
		dx_t = \mathbbm{1}_{x_t =0}dt + \sqrt{|x_t|}dB_t, \quad x_0 = 0, \quad t \geq 0.
	\end{equation} 
\end{enumerate}

