[Definition 6 (Level lines of the discrete height) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Given $a,b,c>0$ and the height function $H$ of a tiling $\eta$ of $\mX_{a,b,c}$ we define the level lines $\mathtt U_{a,b,c}^h:[0,a+c]\cap(1/N)\mathbb Z\mapsto[0,b+c]\cap(1/N)(\mathbb Z+1/2)$ with $h\in[0,b]\cap(1/N)(\mathbb Z+1/2)$ as
          \begin{eqnarray}
            \mathtt U^h_{a,b,c}(x)=y\in [0,b+c]\cap(1/N)(\mathbb Z+1/2):H(x,y)=h.
          \end{eqnarray}

[Proposition 21 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] Fix $t\geq0$. Then
	\begin{equation}
		L_t^x-L_t^0=\int_0^x D_t^y \d y,\qquad x\in \mathbb R,
	\end{equation}
	holds $\mathbb P_{\delta_0}$-a.s., where
	\begin{equation}
		D_t^y:=-\sgn(y)+X_t(\sgn(y-\cdot))-M_t(\sgn(y-\cdot)),\ y\in \mathbb R.
	\end{equation}

