[Corollary cor_a=0 of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] \phantom{a}
\begin{itemize}
\item[(a)]
In the limit $a\to 0$, $\left. N_q\, \right| {\varphi (0)}=a$ converges in distribution to $1+N_q$, where
\begin{align}
\operatorname{{Pr}} \{N_q\!=\!m \} =  \delta_{m,0}+ \sum_{k=m}^{\infty} (-1)^{k-m} \binom{k}{m} \frac{ q^{k(k+1)/2} }{(q;q)_k}, \quad m\ge 0.
\end{align}
\item[(b)] The conditional joint distribution of the first $m$ left-most points $(q_{(1)}, q_{(2)}, \ldots, q_{(m)})$ of $\mathcal{Q}$ given that ${\varphi (0)}=a$ converges, in the limit $a\to 0$, to that of  $(0, q_{(1)}, \ldots, q_{(m-1)})$ whose marginal distributions are given by
\begin{align}
\operatorname{{Pr}} \{q_{(m)}\!>\!q \} =
\displaystyle{
1+ \sum_{k=m}^{\infty} (-1)^{k+m-1}  \binom{k-1}{m-1}\, \frac{q^{\frac{k(k+1)}{2}} }{(q;q)_k}
}, \quad q\in (0,1),\,\, m\ge 1.
\end{align}
\end{itemize}

[Theorem thm:kolmo of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] Let $\alpha \in [0,1]$ be fixed. Assume that $\{X_{(x_1,x_2)}\}_{(x_1,x_2) \in \mathbb{R}^2}$ is a stochastic field for which there exist some constants $\beta, \eta, c, R>0$ such that 
   \begin{equation}  \mathbb{E}[|\Delta  X_{(h_1,h_2);(x_1,x_2)}|^\eta] \leq c \left(\max\{|h_1|,|h_2| \}^{1-\alpha}\min\{|h_1|,|h_2| \}^{1+\alpha}\right)^{1+\beta}
    \end{equation}
    for all $(x_1,x_2)\in \mathbb{R}^2$ and $(h_1,h_2) \in \mathbb{R}^2$ with $|h_1| < R$ and $|h_2|<R$. Then, there exists a version $\{\widetilde{X}_{(x_1,x_2)}\}_{(x_1,x_2) \in \mathbb{R}^2}$ of $\{X_{(x_1,x_2)}\}_{(x_1,x_2) \in \mathbb{R}^2}$ such that, for every $\gamma \in [0,\frac{\beta}{\eta})$ and for every bounded intervals $I,J$ of $\mathbb{R}$, for all $\omega \in \Omega$, there exists a finite constant $C(\omega)>0$ such that
    \begin{equation}
        |\Delta  \widetilde{X}_{(h_1,h_2);(x_1,x_2)}| \leq C(\omega)\left(\max\{|h_1|,|h_2| \}^{1-\alpha}\min\{|h_1|,|h_2| \}^{1+\alpha}\right)^\gamma
    \end{equation}
for every $x_1 \in I$, $x_2 \in J$ and $h_1, h_2 \in \mathbb{R}$ with $x_1+h_1 \in I$ and $x_2 + h_2 \in J$.

[Lemma lem:sector-barrier of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Let $0<\omega<\pi$, and let $s\in\mathbb R$ and $a>0$ satisfy
\begin{align}
 \abs s<a<\frac\pi\omega .

\end{align}
Let $e_{\rm bis}$ be the unit bisector of $K_\omega$, and for $\ell_0>0$ let $(\varrho,\vartheta)$ be polar coordinates centered at the pole $-\ell_0e_{\rm bis}$, with angle measured from $e_{\rm bis}$. There is $\ell_0=\ell_0(\omega,s,a)>0$ such that
\begin{align}
 B(Y):=\varrho^{\,s}\cos(a\vartheta)

\end{align}
is positive and smooth on $\overline{K_\omega}$ and satisfies, for constants $c,C>0$ depending only on $\omega,s,a$,
\begin{align}
 c\left\langleR\right\rangle^{\,s}\le B(Y)\le C\left\langleR\right\rangle^{\,s},
 \qquad
 (I-\mathsf T_\omega)B(Y)\ge c\left\langleR\right\rangle^{\,s-2},
 \qquad Y\in K_\omega .

\end{align}

[Lemma L:omega-limit-set of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Given a semiflow $P^*$ on $\mathcal P_2(\mathbb R)$, then
\begin{enumerate}[label=\textnormal{(\roman*)}]
    \item a measure $\nu\in\omega(B)$ if and only if there exist two sequences $t_k\to\infty$, and $\nu_k\in B$ such that $\mathcal W_2(P^*_{t_k}\nu_k,\nu)\to0$, as $k\to\infty$;
    \item if $B$ is connected in  $\mathcal P_2(\mathbb R)$, then $\omega(B)$ is connected in $\mathcal P_2(\mathbb R)$;
    \item if there exists a compact set $K\subset\mathcal P_2(\mathbb R)$ attracting a bounded set $B\subset\mathcal P_2(\mathbb R)$, then $\omega(B)$ is a nonempty, compact, invariant subset of $K$ and $\omega(B)$ attracts $B$;
    \item if there exists a nonempty compact set $K\subset\mathcal P_2(\mathbb R)$ that attracts each compact subset of $\mathcal P_2(\mathbb R)$, then $\mathop{\bigcap}\limits_{t\geq0}P^*_tK$ is the maximal compact invariant set.
\end{enumerate}

[Proposition 32 of arXiv:2507.06186, '2507.06186'] For every $\ka>0$,
there exists a constant $\th_\ka>0$ such that
for every $t\in(0,\th_\ka)$, the following holds:
\begin{align}

\lim_{\eps\to0}\mbf E\big[\msf T_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]
=\frac{\mr e^{\ka^2t\log t/2\pi}}{2\pi t}\int_D\mbf E\Big[\mbf 1_{\{\tau_D(B^{x,x}_t)>t\}}\mr e^{\ka^2\ga_t(B^{x,x}_t)}\Big]\d x;
\end{align}
\begin{align}

\lim_{\eps\to0}\mbf E\big[\msf M_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]
=\mr e^{\ka^2(t\log t-t)/2\pi}\int_D\mbf E\Big[\mbf 1_{\{\tau_D(B^x)>t\}}\mr e^{\ka^2\ga_t(B^x)}\Big]\d x;
\end{align}
\begin{multline}

\lim_{\eps\to0}\mbf{Var}\big[\msf T_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]=\frac{\mr e^{\ka^2t\log t/\pi}}{(2\pi t)^2}\int_{D^2}\mbf E\Bigg[\mbf 1_{\cap_{i\leq2}\{\tau_D({_i}B^{x_i,x_i}_t)>t\}}\\
\cdot\mr e^{\ka^2\sum_{i=1}^2\ga_t({_i}B^{x_i,x_i}_t)}\left(\mr e^{\ka^2\al_t({_1}B^{x_1,x_1}_t,{_2}B^{x_2,x_2}_t)}-1\right)\Bigg]\d x;
\end{multline}
\begin{multline}

\lim_{\eps\to0}\mbf{Var}\big[\msf M_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]=\mr e^{\ka^2(t\log t-t)/\pi}\int_{D^2}\mbf E\Bigg[\mbf 1_{\cap_{i\leq2}\{\tau_D({_i}B^{x_i})>t\}}\\
\cdot\mr e^{\ka^2\sum_{i=1}^2\ga_t({_i}B^{x_i})}\left(\mr e^{\ka^2\al_t({_1}B^{x_1},{_2}B^{x_2})}-1\right)\Bigg]\d x.
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:asymptotic of arXiv:2412.01086, 'Spectral radii of sparse non-Hermitian random matrices'] \upshape{
For a sequence of random variables $\lbrace X_n\rbrace$ we write $X_n=O_{\mathsf{p}}(f(n))$ ($X_n=\Omega_{\mathsf{p}}(f(n))$) if for every function $\phi$ satisfying $\lim_{n\to\infty}\phi (n)\to\infty$, the inequality $X_n\leq \phi (n)f(n)$ ($X_n\geq f(n)/\phi (n)$) holds with high probability. We will write $X_n=\Theta_{\mathsf{p}} (f(n))$ if both $X_n=O_{\mathsf{p}}(f(n))$ and $X_n=\Omega_{\mathsf{p}}(f(n))$ hold.
}

[OPEN PROBLEM - not a proved fact. Stated in arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF' (conj environment labelled Conj Wiener sausage CR).] Fix $M>0$ and $\eta>0$.
The following asymptotic expansion holds in
$L^{2}(d\PP,\sigma((B_{t})_{0\leq t< \zeta_M}),H^{-\eta}(\C))$.
For every $N\geq 1$,
\begin{align*}
&\ind_{S_{\varepsilon}^{\rm CR}(\zeta_M)}
\\&
=
\sum_{n=1}^{N} \dfrac{(-1)^{n-1}}{n!}
\hat{\mu}^{\rm loop}_{\text{SLE}_{8/3}}
\Big(
\Big(\frac{1}{\pi}\vert \log (\varepsilon d(0,\Gamma)/\CR(0,\inter{\Gamma}))\vert + \cst (M)\Big)^{-n}
\Big)
:\Theta_{\zeta_M}^{n}:
\, + o(\vert \log\varepsilon\vert^{-N})
\\&
=
\sum_{n=1}^{N} \dfrac{(-1)^{n-1}}{n!}
\dfrac{1}{\big(\frac{1}{\pi} \vert \log \varepsilon\vert\big)^{n}}
\sum_{k=1}^{n} 
\dfrac{n!(n-1)!}{(n-k)! k! (k-1)!} C^{\text{SLE}_{8/3}}_{n-k,M}\,
:\Theta_{\zeta_M}^{k}:
\, + o(\vert \log\varepsilon\vert^{-N}).
\end{align*} (Verbatim from the paper's TeX; symbols are the source paper's. Stated as open/conjectural; no resolution of it was found in the paper's own text by the rules of problem_index.py - a paper may still prove special cases of a conjecture it states.)

