[Lemma lem:bound_h of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $a>-1$, $M\in \mathbb{Z}_{+}$ and $\varepsilon>0$.  Then, there exist $N_0=N_0(M,\varepsilon)$ such that for all $N\geq N_0,$ and for all $l\in\{1,\dots,M\}$,
\begin{equation}{}
(1-\varepsilon)\pi   \left(\frac{\log N}{2M}\right)^{a+1}\left(l+\mathds{1}_{a\leq0}\right)^a\leq \sum_{x\in A_{l}} h(x) \leq (1+\varepsilon)\pi 
   \left(\frac{\log N}{2M}\right)^{a+1}{\left(l+\mathds{1}_{a>0}\right)^a}\,.
\end{equation} 
Moreover, $\sum_{x\in A_0} h(x) \leq C_a \left(\frac{\log N}{M}\right)^{a+1}$ where $C_a>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemOccTree of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Fix $M> 0$, $\gamma \in [0,1)$, and $\vartheta>0$. Fix $\zeta \in (0,1]$ and let $H$ be a graph on $n$ vertices such that $\Delta = \Delta(H)=\omega(1)$ and 
\begin{equation}
 \delta(H) = (1+o(1)) \Delta \,.   
\end{equation}
Let $k=\omega(1)$ and suppose that  for all $\ell\leq k$
\[
C_\ell(H)\leq nM^{\ell}  \Delta^{\ell-2}\, .
\]
Then if 
\begin{equation}
  \vartheta \le  e\lambda \zeta \Delta \le \gamma \, ,
\end{equation}
we have the following:
\begin{align}
 \alpha_{H,\lambda,\zeta}=(1+o(1)) \alpha(\Delta,\lambda,\zeta) \,, 
 \intertext{and}

 \rho_{H,\lambda,\zeta} = (1+o(1)) \rho(\Delta,\lambda,\zeta) \, .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:partial-affine of arXiv:2608.20480, 'When Clean Data Hurts: Learning with Monotone \\ Corruptions Beyond Binary Classification'] For $B,C\in\mathcal{B}_r$ and $s,t\in[r]$:
\vspace{-0.3 cm}
\begin{enumerate}[label=(\roman*),leftmargin=2em]
    \item $\phi_B(z_t)\neq0$;
    \item for fixed $(p,B,t)$, the values $p(z_t)+a\phi_B(z_t)$, $a\in\mathbb{F}_q$, enumerate $\mathbb{F}_q$;
    \item if $a\phi_B=a'\phi_C\neq0$ as affine functions, then $a=a'$ and $B=C$;
    \item an affine function is determined by its values at two distinct points $z_s,z_t$.
\end{enumerate}

[Corollary 126 (Summed integrated kernel) of arXiv:2607.10813, '2607.10813'] For every $0<\eps<1-2\beta_a$, the dyadic sum converges and
\begin{equation}
  \sup_{0\le u\le t\le T}
  |\mathcal K_a(\xi;t,u)|
  \lesssim_{T,\eps}\la\xi\ra^{-2+\beta_{\Gamma,a}+\eps}.
\end{equation}
The internal tail above a dyadic scale $L$ satisfies
\begin{equation}
  \sup_{u,t}|\mathcal K_{a,>L}(\xi;t,u)|
  \lesssim_{T,\eps}
  N^{-1+\beta_{a^\perp}}\max\{N,L\}^{-1+2\beta_a+\eps}.
\end{equation}

[Corollary BE2-cor-3 of arXiv:2411.13788, '\bf Gradient bounds and Liouville property for a class of hypoelliptic diffusion via coupl'] Let $f\in C^1\left(\mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}\right)$ be a globally Lipschitz function. Then for any $t\ge0$, $x=(x^{(1)},\cdots,x^{(r+1)})\in \mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}$,  we have
\begin{equation}
2\Gamma(P_tf)(x)\le P_t\left(\left\langle E(-t)AE^*(-t)\nabla f,\nabla f\right\rangle\right)(x).
\end{equation}
and the following reverse inequality:
\begin{equation}
\left\langle E(t)AE^*(t)\nabla P_tf(x),\nabla P_tf(x)\right\rangle\le 2P_t\left(\Gamma(f)\right)(x).
\end{equation}

