body:
[Proposition prop:gaussian-Ritz-general of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] Let $N\ge1$, let $m\ge1$, and let $q_1,\ldots,q_m\in(0,1)$ be distinct.
Set
\[
 V_N(q):=\operatorname{span}\{g_{q_1,N},\ldots,g_{q_m,N}\}.
\]
Define the symmetric matrices
\begin{align}
 \mathsf E_N(q)_{ij}
 &=2N\,G(q_i,q_j)\vartheta(q_iq_j)^{N-1}
   +2N(q_i+q_j-1),\\
 \mathsf D_N(q)_{ij}
 &=F_N(q_iq_j).
\end{align}
Then $\mathsf D_N(q)$ is positive definite and
\begin{equation}
 \min_{0\ne v\in V_N(q)}\frac{\mathcal E_N[v]}{\mathcal D_N[v]}
 =\min_{c\ne0}\frac{c^T\mathsf E_N(q)c}{c^T\mathsf D_N(q)c}.
\end{equation}
Equivalently, this minimum is the smallest generalized eigenvalue of
\begin{equation}
 \mathsf E_N(q)c=\lambda\mathsf D_N(q)c.
\end{equation}

