[Lemma lem:support of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Assume that the force coefficient $\text{$\mathfrak{z}$}_{\eps,\mu}^{\raisebox{0ex}{\includegraphics[scale=1.2]{figures/Xi.pdf}}}(t,s)$ is supported on the diagonal $\{t=s\}$. Then, for every $\tau\in\mathcal{T}$ and ${\eps,\mu}\in(0,1]$, we have the following support property of $\text{$\mathfrak{z}$}^{\tau}_{\eps,\mu}$:   
\begin{equs}    \text{$\mathfrak{z}$}^\tau_{\eps,\mu}(t,s^\tau)=0\;\text{$\mathrm{if}$}\; s^\tau\notin[t-2\mu{\mathfrak{o}}(\tau),t]^{\mathfrak{s}(\tau)}\,.
\end{equs}

[Definition 39 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $\mO$ is a separable Banach space and 
that $(\Omega, \mathscr{F}, \mathbb{F},\mathbb{P})$ is a filtered complete probability space satisfying the usual condition \ref{ass-usual}, and    
 $(\bu_n)_{n \in \mathbb{N}}$is a sequence of $\mathbb{F}$-adapted, $\mO$-valued continuous processes. We say that this sequence satisfies the \textbf{Aldous-Rebolledo} condition in the space $\mO$  if and only if 
for every  $\eta>0$, for  every sequence $(\tau_n)_{n=1}^\infty$ of $[0,T]$-valued  stopping times, for every $[0,1]$-valued  sequence $\vartheta_n$ such that  $\vartheta_n \to 0$ as $n \to \infty$, 
\begin{equation}
    \lim_{n \to \infty} \mathbb{P} (\Vert \bu_n(\tau_n + \vartheta_n) - \bu_n(\tau_n) \Vert_{\mO} > \eta)= 0.
  \end{equation}
Equivalently, for every sequence $(\tau_n)_{n=1}^\infty$ of $[0,T]$-valued  stopping times, for every $[0,1]$-valued  sequence $\vartheta_n$ such that  $\vartheta_n \to 0$ as $n \to \infty$, for every  $\eta>0$, condition \eqref{eqn-Aldous-Rebolledo} holds. \\
 Equivalently, 
 for  every sequence $(\tau_n)_{n=1}^\infty$ of $[0,T]$-valued  stopping times, for every $[0,1]$-valued  sequence $\vartheta_n$ such that  $\vartheta_n \to 0$ as $n \to \infty$, 
    \begin{equation}
    \lim_{n \to \infty} \Vert \bu_n(\tau_n + \vartheta_n) - \bu_n(\tau_n) \Vert_{\mO} = 0 \mbox{ in } \mathbb{P}. 
  \end{equation}

[Lemma 21 of arXiv:2604.09933, 'Explicit cutoff profiles for colored top-\texorpdfstring{$m$}{m}-to-random shuffles'] For \(0\le u\le n\),
\begin{equation}
U\{L_p\ge u\}=\frac{1}{u!\,p^u}.
\end{equation}
Hence, for \(0\le \ell\le n-1\),
\begin{equation}
U\{L_p=\ell\}
=\frac{1}{\ell!\,p^\ell}-\frac{1}{(\ell+1)!\,p^{\ell+1}},
\end{equation}
and
\[
U\{L_p=n\}=\frac{1}{n!\,p^n}.
\]

