\[
    U\{L_p\ge u\}=U(A_u)=\frac{|A_u|}{|G_{n,p}|}
=\frac{\binom{n}{u}p^{\,n-u}(n-u)!}{p^n n!}
=\frac{n!}{u!(n-u)!}\cdot\frac{p^{\,n-u}(n-u)!}{p^n n!}
=\frac{1}{u!\,p^u}.
