[Lemma 22 (Arbitrarily-Accurate ReLU MLP Approximation of Haar Basis of $O(1)$ complexity) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $p \in \mathbb{N}_{+}$ and $q\in\{0,\ldots,2^p-1\}$. For every $0<\eta_{\mathrm t}<2^{-(p+2)}$ there exists a $\operatorname{ReLU-MLP}$  $\Phi_{p,q;\eta_{\mathrm t}}:\mathbb R\to\mathbb R$ of depth $1$, width $6$, and at most $18$ non-zero parameters such that
\begin{equation*}
    \left\|
\psi_{p,q}
-
\Phi_{p,q;\eta_{\mathrm t}}
\right\|_{L^2([0,T])}
=
\frac{2^{1+p/2}}{\sqrt3}
\sqrt{\eta_{\mathrm t}}
\end{equation*}
Moreover, $\operatorname{supp}(\Phi_{p,q;\eta_{\mathrm t}}) = \operatorname{supp}(\psi_{p,q}) = [a_{p,q},b_{p,q}]$.

[Lemma lem:lower_bound_alpha_stab of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let $\bm{X}$ be a L\'evy process that differs in law from the $\alpha$-stable process~$\bm{Z}$, $\alpha\in(0,2]$. Let $\psi_{\bm{X}}$ and $\psi_{\bm{Z}}$ denote their L\'evy--Khintchine exponents. Pick any $q\in(0,1]\cap(0,\alpha)$ and $\bm{u}_*\in \mathbb{R}^d\setminus\{\bm 0\}$ for which $C_*\coloneqq 2^{q-1}|\bm{u}_*|^{-q}|\psi_{\bm{X}_1}(\bm{u}_*)-\psi_{\bm{Z}_1}(\bm{u}_*)|> 0$. Then, we have
\begin{align*}
\mathcal{W}_q(\bm{X}^t_1,\bm{Z}_1)
\geqslant C_*t^{1-q/\alpha}
+ \mathcal{O}(t^{2-q/\alpha}),
\qquad\text{as }t \downarrow 0.
\end{align*}

[Lemma lem-condensatenotion of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Suppose that $v$ satisfies Assumption (V).
Fix $\rho\in(0,\infty)$ and let $\Lambda_N$ be the centered box in $\mathbb{R}^d$ with volume $|\Lambda_N|/N\to 1/\rho$ as $N\to\infty$. Then there are diverging sequences $(L_R^{{{\scriptscriptstyle{({>}})}}})_{R\in\mathbb{N}}$ and $(L_R^{{{\scriptscriptstyle{({\leq }})}}})_{R\in\mathbb{N}}$ such that, for any $\varepsilon\in(0,1)$,
\begin{eqnarray}
\limsup_{R\to\infty}\limsup_{N\to\infty}\frac 1{|\Lambda_N|}\log \widehat{{\tt Q}}^{{{\scriptscriptstyle{({\Lambda_N,\rm bc}})}}}\big(\mathfrak N^{{{\scriptscriptstyle{({\ell,R}})}}}_{\Lambda_N,\leq L_R^{{{\scriptscriptstyle{({\leq}})}}}}>\varepsilon |\Lambda_N|\big)&=& - \infty,\\
\limsup_{R\to\infty}\limsup_{N\to\infty}\frac 1{|\Lambda_N|}\log \widehat{{\tt Q}}^{{{\scriptscriptstyle{({\Lambda_N,\rm bc}})}}}\big(\mathfrak N^{{{\scriptscriptstyle{({\ell,\neg R}})}}}_{\Lambda_N, > L_R^{{{\scriptscriptstyle{({> }})}}}}>\varepsilon |\Lambda_N|\big)&=& - \infty.
\end{eqnarray}

[Lemma 54 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta\in (0,1)$, $j\geq 1$, $l\geq 0$, and $b\geq v + 2\lambda + 2\log(2)\pi$.
Then
\begin{multline*}
\int_{D^{2}}
e^{-(b-v-2\lambda)^{2}/(2\log(2)/\pi + 2 G_{D}(z,w))}
\Big(
1\vee\log\Big(\dfrac{2(1\vee\diam(D))}{\vert w-z\vert}\Big)^{j+2l}
\Big)
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w
\\
\leq 
e^{-((2\pi\eta)\wedge 1)(b-v-2\lambda - 2\log(2)/\pi)}
\\
\times
(c_{\eta,j,l}\vert D\vert \diam(D)^{2\eta}
(1\vee(\pi b + 2\log(2)-\log(1\wedge\diam(D)))^{j+2l}) 
+ I_{\eta,j,l}(D) 
),
\end{multline*}
where $\vert D\vert$ is the Lebesgue measure (area) of $D$,
and $c_{\eta,j,l}>0$ is a constant depending on $\eta, j, l$, and
\begin{displaymath}
I_{\eta,j,l}(D) = 
\int_{D^{2}}
\Big(
1\vee\log\Big(\dfrac{2(1\vee\diam(D))}{\vert w-z\vert}\Big)^{j+2l}
\Big)
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w.
\end{displaymath}

