[Lemma lem:v cdot x^0>C of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] In the setting of Theorem (thm:fast-switching-transience of the paper), for any constant $C\in\mathbb R$, any $i\in[n]$, and any $x\in\mathbb Z^d_{\ge0}$ such that $\operatorname{supp}(v)\cap\operatorname{supp}(x)\ne\varnothing$, there exists an $x^0\in\mathbb Z^d_{\ge0}$ such that $(x^0,i)$ is reachable from $(x,i)$ and $v\cdot x^0>C$.
\begin{proof}
Let $\Xi=\{y'-y:\exists i, y\to y'\in\mathcal R_i\text{ and }\operatorname{supp}(v)\cap\operatorname{supp}(y'-y)\ne\varnothing\}$ be the set of reactions in any environment which affect at least one species seen by $v$. By Lemma (lem:v not orthogonal to reactions of the paper), we may assume without loss of generality that $v$ sees all these reactions; that is, that $v\cdot(y'-y)\ne0$ for all $y'-y\in\Xi$.

For $m\in[d]$ let $z^m$ be as in the statement of Lemma (lem:generator positive of the paper); similarly, let $h_\kappa$ and $\mathcal L_\kappa$ be as in the statement of Lemma (lem:generator positive of the paper). As in the proof of Lemma (lem:generator positive of the paper), let $\varphi^i=(\varphi^i_1,\cdots,\varphi^i_d)$ be the vector defined by $\varphi^i_m:=v_m +\kappa^{-1} z^m_i$.

The proof will consist of three claims.

\textit{Claim 1:} As long as $\kappa$ is large enough, for any $i$ and any reaction $y\to y'\in\mathcal R_i$, the numbers $\varphi^i\cdot(y'-y)$ and $v\cdot(y'-y)$ have the same sign (positive, negative, or zero).

\vspace{.2cm}

Notice that for any reaction $y\to y'$, 
\begin{align*}
    \varphi^i\cdot(y'-y)
    &=\sum_{m=1}^d(v_m+\kappa^{-1}z^m_i)(y'_m-y_m)\\
    &=v\cdot(y'-y)+\kappa^{-1}\sum_{m=1}^d(z^m_i)(y'_m-y_m)
\end{align*}
In particular, $\varphi^i\cdot(y'-y)\to v\cdot(y'-y)$ as $\kappa\to\infty$, and hence $\varphi^i\cdot(y'-y)$ will have the same sign as $v\cdot(y'-y)$ whenever $\kappa$ is large enough, provided $v\cdot(y'-y)\ne0$. By our application of Lemma (lem:v not orthogonal to reactions of the paper) above, this includes all reactions $y\to y'$ with $\operatorname{supp}(v)\cap\operatorname{supp}(y'-y)\ne\varnothing$. Since there are only finitely many possible reactions, as long as $\kappa$ is large enough it follows that $\varphi^i\cdot(y'-y)$ has the same sign as $v\cdot(y'-y)$ whenever $\operatorname{supp}(v)\cap\operatorname{supp}(y'-y)\ne\varnothing$.

Now recall that $z_i^m=0$ whenever $v_m=0$. Therefore, $\operatorname{supp}(\varphi^i)=\operatorname{supp}(v)$ and hence if $y\to y'$ is a reaction such that $\operatorname{supp}(v)\cap\operatorname{supp}(y'-y)=\varnothing$ then $\operatorname{supp}(\varphi^i)\cap\operatorname{supp}(y'-y)=\operatorname{supp}(v)\cap(y'-y)=\varnothing$ and in particular $\varphi^i\cdot(y'-y)=0=v\cdot(y'-y)$. Therefore, $\varphi^i\cdot(y'-y)$ and $v\cdot(y'-y)$ still have the same sign in the case where $\operatorname{supp}(v)\cap\operatorname{supp}(y'-y)=\varnothing$, completing the proof of the claim.

\vspace{.2cm}

\textit{Claim 2:} If $x$ is such that $\operatorname{supp}(v)\cap\operatorname{supp}(x)\ne\varnothing$, then there exists at least one environment $i$ and at least one reaction $y\to y'\in\mathcal R_i$ such that $\lambda_{i,y\to y'}(x)>0$ and $v\cdot(y'-y)>0$.

\vspace{.2cm}

Let $x$ be such that $\operatorname{supp}(v)\cap\operatorname{supp}(x)\ne\varnothing$. For $m=1,\cdots,d$, let $e^m$ denote the standard basis vector in direction $m$ (that is, $e^m_l$ is one if $m=l$ and zero otherwise). Fix $m\in\operatorname{supp}(v)\cap\operatorname{supp}(x)$ and consider the vector $z:=x+e_m \@ifstar{\oldceil}{\oldceil*}{(v_m)^{-1} b}$, where $\@ifstar{\oldceil}{\oldceil*}{(v_m)^{-1} b}$ is the least integer greater than $(v_m)^{-1} b$ and $b$ the constant given by Lemma (lem:generator positive of the paper). Notice that $v\cdot z\ge v\cdot x+b>b$. It follows from Lemma (lem:generator positive of the paper) that $\mathcal L_\kappa h_\kappa(z,j)>0$ for every $j$, and hence for each $j$ there exists at least one transition which increases $h_\kappa$ in state $(z,j)$. In particular, there exist (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 (Symmetric factor extension to Theorem~\ref{thm:pL_rankM_integral}) of arXiv:2608.03273, 'On the Asymptotic of Coupled Spherical Integrals: An Operator-Valued Extension of the Free'] Let $\theta_{lk,i}\in \mathbb R^+$ and $a_{lk,i}\in\{\pm 1\}$ for all $(l,k,i)$, $M(N)=O\left(N^{1/2-\epsilon}\right)$,
    $\Theta_{lk} = \mathrm{diag}\big\{\theta_{lk,1},\ldots, \theta_{lk,M(N)},0,\ldots,0\big\}\in\mathbb R^{N\times N}$, and $A_{lk}=\mathrm{diag}\big\{a_{lk,1},\ldots, a_{lk,M(N)},0,\ldots,0\big\}\in \mathbb R^{N\times N}$ with $A_{lk}=A_{kl}$ and $\Theta_{lk}=\Theta_{kl}$.
    Define an $L$-fold, coupled spherical integral of the form
    \begin{align*}
        \hat I_N^{(\beta)}
        \left(
            \{\Theta_{lk}\},\{A_{lk}\},\{E_{lk}\}
        \right)
        =
        \int
            \exp\left\{
                \sum_{l,k=1}^L
                    N \mathrm{tr}\left(
                        A_{lk}\Theta_{lk}  U_l^\dagger E_{lk} U_k
                    \right)
            \right\}
            \prod_{l=1}^L 
                \mathrm d m_N^{(\beta)}(U_l),
    \end{align*}
    and let the following block matrix $C_{N,i}$ converge to some $C_{i}$ for all $i\in[M(N)]$ in the sense of Definition~\ref{def:operator_valued_convergence}
    \begin{align*}
        C_{N,i}
        =
        \begin{bmatrix}
            a_{11,i} E_{11} 
            & a_{12,i} \frac{\theta_{12,i}}{\sqrt{\theta_{11,i}\theta_{22,i}}} E_{12}
            & \ldots
            \\
            a_{21,i} \frac{\theta_{21,i}}{\sqrt{\theta_{11,i}\theta_{22,i}}}E_{21}
            & a_{22,i} E_{22}  
            \\
            \vdots && \ddots
        \end{bmatrix}
        \in \mathbb A^{LN\times LN}.
    \end{align*}
    Furthermore, all moments of $C_{i}$ are finite, $C_{i}$ is R-cyclic and self-adjoint, and $||E_{lk}||_\infty$ is finitely bounded for all $(l,k)$ as $N\uparrow\infty$.
    If $M(N)=O\left(N^{1/2-\epsilon}\right)$ for any $\epsilon>0$, $L=O(1)$ and all $\theta_{lk,i}$ are small enough such that
    \begin{align*}
        -P_i = -\mathrm{diag}\left\{
            \frac{2\theta_{11,i}}{\beta},\frac{2\theta_{22,i}}{\beta}, \ldots, \frac{2\theta_{LL,i}}{\beta}
        \right\}
        \in \left\{
            \left.
            G_{C_{i}}^{\mathcal D_L}(S)
            \right|
            S\in\mathcal S_{\{-\}^L}^{C_i}
        \right\},
    \end{align*}
    then
    \begin{align*}
        \lim_{N\uparrow\infty}
        \frac{1}{NM(N)} \log \hat I_N^{(\beta)}\left(
            \{\Theta_{lk}\},\{A_{lk}\},\{E_{lk}\}
        \right)
        =
        \frac{1}{M(N)}
        \sum_{i=1}^{M(N)}
        \frac{\beta}{2}
        \int_0^1
            \mathrm{tr}\left(
                R^{\mathcal D_L}_{C_{i}}(P_i w) P_i
            \right)
            \mathrm d w.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma rho_in_l2_l2 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] All limit points $\mathbb{Q}$ of the sequence $( \mathbb{Q}_{\nu_N})_{ {N \geq 1}}$ are concentrated on one path of absolutely continuous measures whose density, which we denote by $\rho_t$, is such that
    \begin{equation*}
        \int_0^T \int_0^1 [\rho_t(u)]^2 du ds < \infty \quad \textrm{ $\mathbb{Q}$-a.s. }
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:NGlimit of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Under the conditions of Theorem~(thm:NGlimit of the paper),  for any $p \in \Z_{\ge 1}$ and $\lambda \in \R^n$ 
\begin{align}
	\langle | \lambda \cdot \Phi_N (\varphi)|^{2p} \rangle_{g,\nu_c, N}
		\sim c_3^{-\frac{p}{2}} \,  {\sf b}_N^{2p}  \,  \E \big[ | \lambda \cdot  Y|^{2p} \big]
		\qquad \text{as } N\rightarrow \infty

\end{align}
for $Y$ defined as in (equation eq:Ydistn of the paper).  In particular,  as $N\rightarrow \infty$,
\begin{align}
	\chi_{g,\nu_c,N} \sim c_3^{-1/2} \E \big[ |Y|^{2} \big] \times \begin{cases}
		N^{1/2} L^{2 N}  \propto ( \log |\Lambda| )^{1/2} |\Lambda|^{1/2} & (d = d_{c,u}) \\
		L^{\frac{d}{2} N}  \propto |\Lambda |^{1/2} & (d > d_{c,u})  .
	\end{cases}

\end{align}

[Theorem thm:sierpiski.multi of arXiv:2604.08505, '\LARGE{On $d$-stochastic measures with fractal support and uniform $(d-1)$-marginals, and '] Let $d \geq 3$ as well as $N \geq 2$ be arbitrary but fixed,    
and suppose that the probability measure $\tau$ on $\{1,\ldots,N\}^d$ is given by   
\begin{equation}
\tau(\mathbf{i})=
\begin{cases}
\frac{1}{N^{d-1}} & \text{if } \sum_{j=1}^d (i_j-1) \, \in \{0,N,2N,\ldots,\}=:N\cdot \mathbb{N}_0\\
0 & \text{otherwise.}  
\end{cases}
\end{equation}
Then $\tau \in \mathcal{U}_d^N$ and the resulting measure $\mu_\tau^\star$ has the following properties:
\begin{itemize}
    \item[(P1)] $\mu_\tau^\star$ is an element of $\mathcal{P}_d^{\lambda_{d-1}}$,
    \item[(P2)] the measure $\mu_\tau^\star$ is singular w.r.t. $\lambda_d$ 
    and has a self-similar set with Hausdorff dimension $d-1$ as support,     
    \item[(P3)] for $\mathbf{X}=(X_1,\ldots,X_d) \sim \mu_\tau^\star$ we have that 
each variable $X_j$ is almost surely a function of the other $(d-1)$ variables.  
\end{itemize}

[Theorem 6 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] Let Condition $B1$ be valid. Then

1) if $n\gg k\gg m=n-r$ then, for any $y\in (-\infty ,0)$ and $t>0$
\begin{equation}
\lim_{m\rightarrow \infty }I_{n}^{\ast }(r,k;y,t)=\mathbf{E}_{0}^{+}\left[
H_{\infty }\right] ;  
\end{equation}

2) if either $k\sim \theta m,\theta >0,$ or $\min (r,n-r)\gg k$, or $k\sim
\theta _{1}r,\theta _{1}>0$ or $k\gg r$ then, for any $y>0$ and $t>0$
\begin{equation}
\lim_{k\wedge r\rightarrow \infty }I_{n}(r,k;y,t)=\mathbf{E}_{0}^{+}\left[
H_{\infty }\right] .  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

