[Definition 2 of arXiv:2605.29608, '2605.29608'] We say that $P$ satisfies a Poincar\'e inequality with constant $C_{\text{PI}}$ if
	\begin{align*} 
		\mathrm{Var}_{\mu_{N}}(f)
		:=E_{\mu_{N}}[f^{2}]-(E_{\mu_{N}}[f])^{2}\leq&C_{\text{PI}}\mathcal{E}_{\mu_{N}}(f),
	\end{align*}
	for all functions $f$ defined on $\Omega$.

[Mainlocal 4 (Mesoscopic form of the relative pressure-work principle) of arXiv:2608.30715, 'Endpoint Energy Atoms Force Local Pressure Concentration in Three-Dimensional Navier--Stok'] Under the assumptions of Theorem~\ref{thm:main}, let
\(R_n\downarrow0\) be arbitrary. There exist
\(\tau_n\uparrow T_*\), with \(\tau_n>s\), and
\(t_n\in(\tau_n,T_*)\), \(t_n\uparrow T_*\), such that
\begin{equation}
 \frac{A(\tau_n)}{R_n}
 +\frac{\sqrt{\nu\delta_{\tau_n}}}{R_n}
 \longrightarrow0,

\end{equation}
and
\begin{equation}
 \liminf_{n\to\infty}
 \int_{\tau_n}^{t_n}\int_\Omega
 \chi_{R_n}\nabla\pi_w\cdot g_{\tau_n}\dd x\dd t
 \ge\frac m2.

\end{equation}
Consequently,
\begin{equation}
 \liminf_{n\to\infty}
 \int_{\tau_n}^{t_n}\int_{B_{2R_n}(a)}
 [\nabla\pi_w\cdot g_{\tau_n}]_+\dd x\dd t
 \ge\frac m2,

\end{equation}
where \([h]_+=\max\{h,0\}\).
Moreover,
\begin{equation}
 \liminf_{n\to\infty}
 \operatorname{Osc}_2\!\left(
 \pi_w;(\tau_n,T_*)\times B_{2R_n}(a)\right)
 \ge c_{\Omega,\chi}\frac{m\sqrt\nu}{\norm{f}_2},

\end{equation}
and
\begin{equation}
 \liminf_{n\to\infty}
 R_n^2\int_{\tau_n}^{T_*}\int_{B_{2R_n}(a)}
 \abs{\nabla\pi_w}^2\dd x\dd t
 \ge c_{\Omega,\chi}\frac{m^2\nu}{\norm{f}_2^2}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 34 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such that for any $T>0$, distinct $v,v',w\in \widetilde{\mathbb{Z}}^d$ with $|v-w|\ge d$, and event $\mathsf{A}$ measurable with respect to $\mathcal{C}_{v'}$,  	\begin{equation}
		\mathbb{P}\big( \widehat{\mathcal{L}}^{v}_{1/2} \ge T \mid \big\{ v\xleftrightarrow{} w \Vert \mathsf{A}  \big\}  \big)\le Ce^{-cT}. 
	\end{equation}

