[Lemma 23 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $r>0$ and $n\ge 1$. For $\bs{\alpha}, \bs{\beta}\in\LX_n$, we write $\bs{x}=\ee^{\ii\bs{\alpha}}$ and $\bs{y}=\ee^{\ii\bs{\beta}-r}$.
Define
\begin{equation}
	\varphicro{n}(z)=n\pi- \sum_{j=1}^{n} \arg \Theta_1(r; -\ii \log z-\alpha_j) + \sum_{j=1}^{n} \arg \Theta_3(r; -\ii \log z-\beta_j) - \sum_{j=1}^{n} (\alpha_j-\beta_j) \frac{\log |z|}{2r}.
\end{equation}
Then we have
\begin{align} 
	\begin{split}
	\| \varphicro{n} \|_{\nabla(\A_r),\mathrm{reg}}^2= & \frac{\pi}{2r}\left(\sum_{j=1}^{n} (\alpha_j-\beta_j) \right)^2-6n\pi \sum_{m=1}^{\infty} \log \left(  1-\ee^{-2mr} \right)  - \frac{n}{2}\pi r\\
	& - 2\pi \sum_{1\le i<j\le n} \left( \log \left| \Theta_1(r; \beta_{j}-\beta_i) \right| +\log \left| \Theta_1(r; \alpha_{j}-\alpha_i) \right| \right) \\
	& +2 \pi \sum_{i=1}^{n} \sum_{j=1}^{n} \log \left| \Theta_3(r; \beta_{j}-\alpha_i) \right| .
\end{split}
\end{align}
Moreover, its regularized Dirichlet energy is related to the partition function $\LZcro{n}^{(\ell)}$ in~\eqref{eqn::LZcroell_def}: 
\begin{align}
\begin{split}
\LZcro{n}^{(0)}(r; \bs{\alpha}, \bs{\beta})=&\exp\left(-\frac{1}{4\pi}\| \varphicro{n} \|_{\nabla(\A_r),\mathrm{reg}}^2\right), \\
 \LZcro{n}^{(\ell)}(r; \bs{\alpha}, \bs{\beta})=&\LZcro{n}^{(0)}(r; \bs{\alpha}, \beta_{1}+2\pi\ell, \ldots, \beta_{n}+2\pi\ell). 
 \end{split}
\end{align}

