[Proposition 23 (\textsf{Uniform truncation principle}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] Let $K\subset\R$ be compact and $q>0$.  Then
  \begin{align}
    \sup_{u\in K}
    \int_{\DN}
      \left|e^{q\be H_u^\eps(\ga)}
        -e^{q\be H_u(\ga)}\right|\,\mu_\be(d\ga)
    \longrightarrow0.
  \end{align}
  More generally, suppose that
  $h_\eps:K\times\DN\to\R$ are uniformly bounded
  over $\eps\in [0, 1]$, and  for every
  $R<\infty$,
  \[
    \sup_{\substack{u\in K\\\ga_n\leq R}}
    |h_\eps(u,\ga)-h_0(u,\ga)|\longrightarrow0.
  \]
  Then
  \begin{align}
    \sup_{u\in K}\left|
      \int_{\DN} e^{q\be H_u^\eps(\ga)}h_\eps(u,\ga)\,\mu_\be(d\ga)
      -\int_{\DN} e^{q\be H_u(\ga)}h_0(u,\ga)\,\mu_\be(d\ga)
    \right|\longrightarrow0.
  \end{align}

