[Cor lp_relu_approximation of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $d\in\mathbb{N}_+$, $L>0$, $1\le p\le\infty$, and $X=[0,1]^d$, and fix an $L$-Lipschitz function $f:([0,1]^d,\|\cdot\|_p)\to(\mathbb{R},|\cdot|)$. For every $N\ge2$, there exists a \texttt{ReLU}-MLP $\Phi:\mathbb{R}^d\to\mathbb{R}$ of depth $\mathcal{O}(\log N)$, width $\mathcal{O}(N)$, and with $\mathcal{O}(N)$ non-zero parameters such that:
\begin{enumerate}
    \item[(i)] \textbf{Uniform Approximation:} 
    \[
    \sup\limits_{x\in[0,1]^d}|f(x)-\Phi(x)|
    \le 
    \frac{
        C'_{p,d}
        \,
        L
        }{
        N^{1/d}
        }
    ;
    \]
    \item[(ii)] \textbf{Regularity:} $\Phi$ is $L\,d^{\min\{1/p,\,1-1/p\}}$-Lipschitz with respect to $\|\cdot\|_p$,
\end{enumerate}
where $
C'_{p,d}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} d
$
if $1\le p\le2$ and
$
C'_{p,d}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} d^{1/p}
$
if $2<p\le\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:intro-Einaiiagapi of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] (Theorem (Einaiiagapi of the paper))
  Let $A$ be a random Hermitian matrix of size $N$. Assume that for every finite $r$ one has
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N} \log \mathbb{E}[H \text{}
    C (x_1, \ldots, x_r, 0^{N - r} ; \lambda_1 (A), \ldots, \lambda_N (A))] -
    \sum_{i = 1}^r \Psi (x_i) \right) = \sum_{i = 1}^r \Phi (x_i), 
  \end{equation}
  where $\Psi, \Phi$ are smooth functions in a (complex) neighborhood of $0$ and the
  above convergence is uniform in a (complex) neighborhood of $0^r$. Then one has the following     limit:
  \begin{equation}
    \lim_{N \rightarrow \infty} N \left( \frac{1}{N^{k + 1}} \mathbb{E} \left[
    \sum_{i = 1}^N \lambda_i^k (A) \right] -\ensuremath{\boldsymbol{\mu}}_k \right)
    =\ensuremath{\boldsymbol{\mu}}'_k, 
  \end{equation}
  where 
  \begin{equation}
    \ensuremath{\boldsymbol{\mu}}_n = \sum_{m = 0}^{n - 1} \frac{n!}{m! (m + 1) ! (n - m) !}
    \frac{\mathrm{d}^m}{\mathrm{d} x^m} ((\Psi' (x))^{n - m}) {\mbox{\rotatebox[origin=c]{-90}{${-\!\!-}$}}}_{x =
    0}, 
  \end{equation}
  \begin{equation}
    \ensuremath{\boldsymbol{\mu}}'_k := \sum_{m = 0}^{k - 1} \frac{k!}{m! (m + 1) !
    (k - m - 1) !}  \left. \frac{\mathrm{d}^m}{\mathrm{d} x^m} ((\Psi' (x))^{k - m
    - 1} \Phi' (x)) \right|_{x = 0} . 
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary eq:block-cap-coordinate-lower of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:block-growing-cutoff-separation}
Retain the notation of (thm:mesoscopic-block-lower of the paper).  Every
\(x\in\mathcal K_{N,t}\) satisfies
\begin{equation}
 \left\lVertx\right\rVert_\infty\ge\frac{t}{\sqrt{k_N}}
 =\left(\frac{t}{\sqrt c}+o(1)\right)N^{-1/(2p)}.
\end{equation}
Consequently, if a point cutoff \(D_{N,r_N}\) from
(thm:growing-point-cutoff of the paper) intersects \(\mathcal K_{N,t}\), then
\begin{equation}
 q_N^{\rm gr}=\sqrt N\,r_N^{p-1}
 \ge
 \left(t^{p-1}c^{-(p-1)/2}+o(1)\right)N^{1/(2p)}.
\end{equation}
In particular, every growing cutoff for which
\(q_N^{\rm gr}=O(1)\), and hence every cutoff in the pressure-universal
regime \(q_N^{\rm gr}\to0\), is eventually disjoint from the entire cap
\(\mathcal K_{N,t}\) that creates the coherent-block critical point.

[Thm 22 (Local law in supercritical regime) of arXiv:2606.24887, '2606.24887'] Fix $ 0 < \delta \le 1/2$ and $L \ge 1$. Let $d$ satisfy \eqref{regimed3}. Let $X$ be a sparse matrix as in \cref{defiX}, define $M$ as in \eqref{eq:def_M_X_plus_f} with some deterministic $0 \le f \le N^{\delta/6}$, $G$ as in \eqref{Greenfunction} and $g$ as in \eqref{eq:def_g}. 
		Then  
		\begin{equation*}
			\widetilde{\Lambda}(w,\eta) \le \mathcal C \widetilde{\psi}_w(\eta)
		\end{equation*}
		with very high probability uniformly for all $w \in \mathrm{D}_2$ and $\eta \in [N^{-1 + \delta}, L]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] The following claims hold.

	\begin{enumerate}
		\item The number of directed dyads is $|N_n|=n(n-1)$. 

		\item For any \((i,j)\in N_n\), the shells $S((i,j),r) : = \{ (l,k) \in N_{n} \colon d_{n}((i,j),(k,l)) = r   \}$ satisfy
		\begin{align*}
			|S((i,j),0)| = 1,~	|S((i,j),1)| \asymp n,~and~|S((i,j),2)| \asymp  n^2.
		\end{align*}


		\item  The chromatic number satisfies	$K_n(0)=1,~K_n(1) \asymp n,~and~K_n(r) \asymp n^{2}$ for all $r\geq 2$. 


		\item $	\tau_{\mathrm{cone} \mathcal F,G_n}(r,q)=0$ for all  $r\geq 2$.
	\end{enumerate}

[Lemma 58 (Compact-scale tail) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] If
\[
 R_{r+1}^2
 =\sup_n\sum_q\omega_q^{(r+1)}E_{n,q}<\infty,
\]
then
\begin{equation}
 \sup_n\sum_{q>Q}\omega_q^{(r)}E_{n,q}
 \le R_{r+1}^2\rho_r(Q)\longrightarrow0.

\end{equation}

