[Definition of arXiv:2607.02410, 'Polynomial mixing for polygonal side matchings'] Let $P$ be a $2n$-gon whose vertices are labelled from $1$ to $2n$ in a clockwise manner, and let $X$ be a chord diagram on $P$. The \textit{gluing graph} of $X$, denoted $G(X)$, is a directed graph whose vertices are the vertices of $P$ and whose edges are
	\begin{equation*}
		E = \bigcup_{\{\{x,x+1\}, \{y,y+1\}\} \in X } \{ (x, y+1), (y, x+1) \} \, ,
	\end{equation*}
	where the vertices $1$ and $2n+1$ are equivalent.

[Lemma 12 of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] For $n\ge1$,~$t>0$ and~$\lambda>0$, denote
\begin{equation}

\Gamma(\lambda):=\bigl\{x\in\BbbL_n\colon \sqrt{L_t(x)}\ge m_n-\lambda\bigr\}.
\end{equation}
Then for all~$\lambda>0$,
\begin{equation}

\lim_{k\to\infty}\,\limsup_{n\to\infty}\,P^\varrho\Bigl(\exists x,y\in\Gamma(\lambda)\colon y\in B_{n-k}(x)\smallsetminus B_k(x)\Bigr) = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma compofI of arXiv:2609.01990, 'Jacquet-Zagier treatment of the beyond endoscopy trace formula for \(\GL_2\)'] The individual components of \(\mathbf{I}\) are given by 
    \begin{align*}
        &\int_{1}^{\infty} \vartheta_{\Delta} \left(\frac{1}{|t^2-4n|x}\right) x^{-\frac{s+\delta_t}{2}} d^{\times}x \\
        &= \sum_{k=1}^{\infty} v_{k,l} \: \chi_{D}\left(\frac{k}{v_{k,l}^2}\right) k^{s-1} \left(\frac{|t^2-4n|}{\pi}\right)^{-\frac{s}{2} + \frac{\delta_t + 1}{2}} \Gamma\left(-\frac{s}{2}+ \frac{\delta_t+1}{2}, \frac{\pi k^2}{|t^2-4n|}\right)
    \end{align*}
    and 
    \begin{align*}
        &\int_{1}^{\infty} \vartheta_{\Delta}\left(\frac{x}{|t^2-4n|}\right) x^{\frac{s+\delta_t}{2}} d^{\times}x \\
        &= \sum_{f^2 \mid \delta}^{'} f^{2\delta_t+1} \sum_{l=1}^{\infty} l^{\delta_t} \chi_{\frac{t^2-4n}{f^2}}(l) \left( \frac{|t^2-4n|}{\pi l^2f^4}\right)^{\frac{s+\delta_t}{2}} \Gamma\left(\frac{s+\delta_t}{2}, \frac{\pi l^2f^4}{|t^2-4n|}\right)
    \end{align*}
    where 
    \[
    \Gamma(z,x) = \int_{x}^{\infty} e^{-u} u^{z-1} du, \qquad x \in \mathbb{R}_{>0},\: z \in \mathbb{C}
    \]

