body:
[Theorem thm:reverse_coupling of arXiv:2412.04005, '$\SLE_{\kappa}(\rho)$ processes in the light cone regime on\\ Liouville quantum gravity'] Let $\kappa$, $\widetilde{\rho}$ be as above, let $\widetilde{W}$ be the driving function associated with a reverse ${\rm SLE}_{\kappa}(\widetilde{\rho})$ with a single force point located at $0_+$ of weight $\widetilde{\rho}$, and let $(\widetilde{f}_{t})$ be the centered reverse Loewner evolution driven by $\widetilde{W}$. For each $t \geq 0$, let 
\begin{align*}
\widetilde{\mathfrak {h}}_{t}(z) = \widehat{\mathfrak {h}}_{t}(z) + \frac{\widetilde{\rho}}{2\sqrt{\kappa}}\widetilde{G}_{t}(0_+,z)
\end{align*}
and let $h$ be an instance of the free boundary $\text{GFF}$ on $\mathbf{H}$ independent of $\widetilde{W}$. Suppose that $\widetilde{\tau}$ is an a.s.\ finite stopping time for the filtration generated by the Brownian motion which drives $\widetilde{W}$. Then
\begin{align*}
\widetilde{\mathfrak {h}}_{0} + h \stackrel{d}{=} \widetilde{\mathfrak {h}}_{\widetilde{\tau}} + h \circ \widetilde{f}_{\widetilde{\tau}}
\end{align*}
where the left and right sides are viewed as distributions modulo additive constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 (Estimate of \(\mathcal P\) and \(\mathcal P'\)) of arXiv:2609.01436, '2609.01436'] The series in \eqref{eq:Pcal} converges uniformly on
$[t_0,\infty)$ and defines a bounded, nondecreasing, locally absolutely
continuous function.  It satisfies
\begin{equation}
 0\leq\mathcal P(t)\leq\Theta_j(h),
 \qquad t\geq t_0,
\end{equation}
and, for almost every $t\geq t_0$,
\begin{equation}
 \mathcal P'(t)
 =
 \sum_{\substack{k\geq j\\
                  Z_k(t)<\Lambda_k(h)}}
 \frac{\omega_k(h)}{\Lambda_k(h)}Z_k'(t)\geq \sum_{\substack{k\geq j\\
                  Z_k(t)<\Lambda_k(h)}}
 \frac{A_k(t)^2}{\omega_k(h)}.
\end{equation}

[Proposition 56 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Assume the hypothesis of Theorem \ref{theorem:geometric-interpolation-equivalent-Gaussian-Hilbert-space}.
	For $i=0,1$
	\begin{align}

		\lim_{\gamma \approach 0^{+}}d^1_{\logdet}[(C_i + \gamma I), C_{\alpha,\gamma}]= -\log\dettwo[(I-S_{\alpha})^{-1}(I-S_i)],
	\end{align}
	where $S_{\alpha}$ is as given in Theorem \ref{theorem:geometric-interpolation-equivalent-Gaussian-Hilbert-space}.

[Lem 6 of arXiv:2608.21090, 'Ornstein--Uhlenbeck process conditioned to have restricted $L_2$-norm'] For each $c>0$ and $T\geq T_0$, we have
    \begin{equation}
        \psi(c+iv)=\psi(c)+i\psi'(c)v-\frac{\psi''(c)}{2}v^2+R_T(c+iv)\quad\text{for}~\abs v\abs\leq c
    \end{equation}
    where 
    \begin{equation}
        \abs R_T(c+iv)\abs\leq \frac{3}{\gamma}\frac{\abs v\abs^3}{c^2}\frac{1}{1-\frac{\abs v\abs}{c}}.
    \end{equation}

