body:
[Theorem 17 of arXiv:2609.03750, '\bf Pullback Measure Attractors, Zero-Noise Limits, and Moderate Deviations for 2D Stochas'] Suppose Hypotheses \ref{PEeqAssum-2.2}, \ref{PEeqAssum-2.3}, \ref{PEeqAssum-2.4} and \eqref{PETNs-3.01} hold. Then, for every $\epsilon\in(0,\epsilon_0)$, the measure evolution process $S_\epsilon$ on $\mathcal P_{4,z}(H)$ has a unique $\mathfrak D$-pullback measure attractor $\mathscr A_\epsilon$. For every $\tau\in\mathbb R$,
	\begin{align}
		\mathscr A_\epsilon(\tau)
		=\bigcap_{s\ge0}
		\overline{\bigcup_{t\ge s}
			S_\epsilon(\tau,\tau-t)\mathscr K(\tau-t)}.
	\end{align}
	Moreover, $\mathscr A_\epsilon(\tau)\subset\mathscr K(\tau)$; in particular, every attractor section is a compact subset of $\mathcal P_{4,z}(H)$ in the ambient weak topology.

[Lemma lem: bdry quadratic of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $\delta > 0$ sufficiently small there exists $C>0$ such that, for every $T > 0$,
\begin{multline}
\Big|\int_{[-1,1]\times \mathbb T^2} \llbracket (\overline HW_T^0)^2 \rrbracket  (\overline HZ_T^0(u))^2 dx \Big| 
\\
\leq
C\||\tau|^{1/2 - \delta}	\llbracket (\overline H W_T^0)^2 (\tau,\cdot)\rrbracket\|_{L^4_\tau \mathcal C^{-1/2+\delta}_z} \| |\tau|^{-1/2+\delta} \overline H Z_T^0(u)(\tau,\cdot) \|_{L^2_\tau H^{1/2-\delta}_z} \|\overline HZ_T^0(u)\|_{L^4},
\end{multline}
and
\begin{equation}
\Big| \int_{[-1,1]\times\mathbb T^2} \overline HW_T^0 \cdot (\overline HZ_T^0(u))^3 dx \Big| \leq C\|\overline HW_T^0\|_{L^{8(1-\delta)}_\tau \mathcal C^{-1/2+\delta}_z} \| \overline H Z_T^0(u)\|^{
\frac{1/2-\delta}{1-\delta}}_{L^2_\tau H^{1-\delta}_z} \|\overline H Z_T^0(u)\|^{{2+\frac{1/2}{1-\delta}}}_{L^4}.
\end{equation}

