[Lem 137 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Adopt the notation and assumptions of \Cref{cor:cella1}, and denote
	\begin{flalign}
          \widetilde{\mathcal{H}} (\hat{x}, \hat{y}) = \mathfrak{d}^{-1/2} \mathfrak{e}^{-3/2} \mathcal{H}_{q;a,b,c} (x, y) \quad \text{if}\quad \gamma'>0,\\
          \widetilde{\mathcal{H}} (\hat{x}, \hat{y}) = \mathfrak{d}^{-1/2} \mathfrak{e}^{-3/2}(y- \mathcal{H}_{q;a,b,c} (x, y)) \quad \text{if}\quad \gamma'<0. 
	\end{flalign}
	\noindent Then,  we have
	\begin{flalign}

		\begin{aligned} 
		& \partial_{\hat{x}} \widetilde{\mathcal{H}} (\hat{x}, \hat{y}) = \displaystyle\frac{\mathfrak{d} (1-\gamma')^3}{\pi |\gamma'|} \cdot \Real \hat{f}(\hat{x}, \hat{y}) \cdot \Imaginary \hat{f} (\hat{x}, \hat{y}) + \mathcal{O} ( (\mathfrak{d}^{-1} \mathfrak{e})^{1/2}); \\  
		& \partial_{\hat{y}} \widetilde{\mathcal{H}} (\hat{x}, \hat{y}) = \displaystyle\frac{\mathfrak{d} (1-\gamma') (\gamma'^2+1)}{\pi |\gamma'|} \cdot \Imaginary \hat{f} (\hat{x}, \hat{y}) + \mathcal{O} ( (\mathfrak{d}^{-1} \mathfrak{e})^{1/2} ).
		\end{aligned} 
	\end{flalign}

