body:
[Theorem 3 (Finite passage to a strict subcritical target) of arXiv:2608.20638, 'Provable Edge-of-Stability for Adam on a One-Dimensional Quadratic'] Assume $\beta_1=0$, $w_{\max}>2$, and
\[
    w_T<\widehat w<2.
\]
Define
\begin{align}
    M_T&:=\max\{v_T,x_T^2\},
    &\underline w_T&:=\frac{\eta}{\sqrt{M_T}+\varepsilon},
\\
    \rho_T&:=\max\{\abs{1-\underline w_T},\abs{1-\widehat w}\},
    &r_T&:=\rho_T^2,

\end{align}
and
\begin{equation}
    U_n^{(T)}
    :=\beta_2^n v_T
      +(1-\beta_2)x_T^2G_n(r_T,\beta_2),
    \qquad n\in\Npos.

\end{equation}
Then
\begin{equation}
    N_T^{\mathrm{imp}}
    :=\min\left\{
        n\in\Npos:
        U_n^{(T)}
        \le
        \left(\frac{\eta}{\widehat w}-\varepsilon\right)^2
    \right\}
    <\infty,

\end{equation}
and
\begin{equation}
    1\le\sigma_{\widehat w}(T)\le N_T^{\mathrm{imp}}.

\end{equation}

Moreover, introduce
\begin{align*}
 C_{\beta,T}&:=v_T+
      \frac{1-\beta_2}{\beta_2-r_T}x_T^2
      &&\text{if }\beta_2>r_T,\\
 C_{r,T}&:=v_T+
      \frac{1-\beta_2}{r_T-\beta_2}x_T^2
      &&\text{if }\beta_2<r_T,\\
 C_{=,T}&:=v_T+
      \frac{1-r_T}{(1-\sqrt{r_T})^2}x_T^2
      &&\text{if }\beta_2=r_T.
\end{align*}
The implicit bound satisfies
\begin{equation}
N_T^{\mathrm{imp}}\le \overline N_T:=
\begin{cases}
\displaystyle
 \left\lceil
 \frac{
 \log\!\left(
 \dfrac{C_{\beta,T}}
 {\left(\eta/\widehat w-\varepsilon\right)^2}
 \right)}
 {\log(1/\beta_2)}
 \right\rceil,
 &\beta_2>r_T,\\[5mm]
\displaystyle
 \left\lceil
 \frac{
 \log\!\left(
 \dfrac{C_{r,T}}
 {\left(\eta/\widehat w-\varepsilon\right)^2}
 \right)}
 {\log(1/r_T)}
 \right\rceil,
 &\beta_2<r_T,\\[5mm]
\displaystyle
 1+\left\lceil
 \frac{
 \log\!\left(
 \dfrac{C_{=,T}}
 {\left(\eta/\widehat w-\varepsilon\right)^2}
 \right)}
 {\log(1/\sqrt{r_T})}
 \right\rceil,
 &\beta_2=r_T.
\end{cases}

\end{equation}

