[Lemma lem:exit_pt_comp_ptp of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Let $j \in \mathbb{Z}$, and let $f:\mathbb{Z}_{\ge j} \to \mathbb{R}$ be an initial condition. Let $\ell \ge m \ge n \ge j$ be integers. Then, for all integers $p \ge Z_{f,j}(\ell,n)$, we have 
 \begin{equation} 
 G_{f,j}(\ell,n) - G_{f,j}(m,n) \le G\bigl((p,j),(\ell,n)\bigr) - G\bigl((p,j),(m,n)\bigr).
 \end{equation}
 Furthermore,  for all $p \in \llbracket j, Z_{f,j}(m,n) \rrbracket$, we have 
 \begin{equation} 
 G_{f,j}(\ell,n) - G_{f,j}(m,n) \ge G\bigl((p,j),(\ell,n)\bigr) - G\bigl((p,j),(m,n)\bigr).
 \end{equation}
 Lastly, if $p \in \mathbb{Z}_{\le r}$, then
 \begin{equation} 
 G\bigl((p,j),(\ell,n)\bigr) - G\bigl((p,j),(m,n)\bigr) \le G\bigl((r,j),(\ell,n)\bigr) - G\bigl((r,j),(m,n)\bigr).
 \end{equation}

[Definition def:hypocoercivesemi of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] We say that $\{P_t\}_{t \geq 0}$ \emph{converges to equilibrium} if for each $x \in \mathcal{H}$, there exists a decay function $r: \mathbb{R}_+ \to \mathbb{R}_+$ with $\lim_{t \to \infty} r(t) = 0$ such that
\begin{align} 
    \|P_t x - P_\infty x\|_{\mathcal{H}} \leq r(t) \|x - P_\infty x\|_{\mathcal{H}}.
\end{align}
When $r(t) = Ce^{- \nu t}$ for some $C >  1, \nu > 0$, we say the semigroup is \emph{hypocoercive}. In the case of $r(t) = e^{-\nu t}$ (i.e., $C = 1$), it is called \emph{coercive}.

