[Lemma lem:E-properties of arXiv:2606.10973, 'Quasisymmetric rigidity of the Brownian sphere'] \begin{enumerate}
        \item The event $E_{z,r,I}$ is almost surely determined by $\Phi_2|_{B_r(z)}$ modulo additive constant.
        \item The probability $\BP\lbrack E_{z,r,I}\rbrack$ does not depend on $z$ and $r$. 
        \item There exists $p = p(\eta) \in (0, 1)$ such that $\BP\lbrack E_{z,r,I}\rbrack \ge p$ for all admissible intervals $I$.
    \end{enumerate}

