body:
[Theorem 14 (\textsf{Master bounds}) of arXiv:2608.12451, '2608.12451'] Fix $r\in\N$ and
let $F\in L^4(\PP)$ belong to the $r$-th chaos in the Poisson setting
or Rademacher setting.
Recall $\cD(F)$ and $\fE_r(F)$ from \eqref{def_CD} and \eqref{E_abs}.
Assume that a nonnegative quantity $\rho(F)$ satisfies

\noi
\begin{align}
 \|J_{2r}(F^2)\|_2^2\geq2m_2(F)^2-\rho(F).

\end{align}

\noi
Put

\noi
\begin{align}
 \cT_F:=\frac1r\Gamma(F,F)-m_2(F)-\frac F2
 \AND
 \mathfrak d(F):=\abs{\cD(F)}+\rho(F).

\end{align}
Then,
\begin{align}
 \fE_r(F)&\leq\mathfrak{d}(F),
 \\
 \abs{m_3(F)-m_2(F)}
 &\leq\sqrt{m_2(F)\mathfrak d(F)},
 \\
 \norm{\cT_F}_2
 &\leq\frac{2r-1}{2r}\sqrt{\mathfrak d(F)}.

\end{align}
Moreover, without any lattice assumption,
\begin{align}
 \cJ(F)
 &\leq4\sqrt{m_2(F)\mathfrak d(F)}
   +12\mathfrak d(F).

\end{align}
If, in addition, $\rho(F)=0$ and $\cD(F)\geq0$, then
$12\mathfrak d(F)$ in \eqref{J_master} can be replaced by
$8\mathfrak d(F)$.

If $F$ additionally satisfies the lattice condition \eqref{cond_La}
with shift $\theta>0$, then, with
$c_\theta:=(1-e^{-\theta})/\theta$,
\noi
\begin{align}
 \dTV(F+\theta,P_\theta)
 &\leq c_\theta\bigg[
 \abs{m_2(F)-\theta}
 +\frac{2r-1}{2r}\sqrt{\mathfrak d(F)}
 +\frac23\sqrt{m_2(F)\mathfrak d(F)}
 +2\mathfrak d(F)
 \bigg].

\end{align}
In the preceding special case $\rho(F)=0$ and $\cD(F)\geq0$,
$2\mathfrak d(F)$ in \eqref{master_TV} can be replaced by
$\frac43\mathfrak d(F)$.

[Lemma lem: large deviation for sle interface dimension of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] For any $\kappa_1\in (0,0.1)$, there exists  a constant $c_7=c_7(\kappa_1)>0$ such that for any $\lambda>0$ we have \begin{equation}
        \mu^{\pm}_{\Lambda_N,0 }\Big(S(\gamma)\ge N^{\frac{7}{4}}\lambda\Big)\le c_7\exp(-c_7^{-1}\lambda^{4-\kappa_1}).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 3.4 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] Let $\xi\in L_\tau^p(0;{\mathbb R}^k)$ and the generator $g$ satisfy assumptions (A:H1b of the paper) and (A:H2 of the paper)-(A:H5 of the paper). Assume further that for some constant $M>0$,
\begin{align}
\int_0^\tau \left(\mu_t+\frac{\theta}{2[1\wedge(p-1)]}\nu_t^2\right)^+ {\rm d}t\leq M.
\end{align}
Then, BSDE (equation BSDE1.1 of the paper) admits a unique $L^p$ solution $(y_t,z_t)_{t\in[0,\tau]}$ in the space of $H_\tau^p(0;{\mathbb R}^{k}\times{\mathbb R}^{k\times d})$. Moreover, if $|\xi|+\int_0^\tau |g(s,0,0)|{\rm d}s\in L^\infty(\Omega,\mathcal{F}_\tau, \mathbb{P};{\mathbb R})$, then $(y_t)_{t\in[0,\tau]}\in S^\infty({\mathbb R}^k)$.\vspace{0.1cm}

