[Definition def:multinomial_measures of arXiv:2506.12171, 'The multinomial dimer model'] Let $G = (V,E)$ be a bipartite graph with 
 vertex multiplicities ${\mathbf N} = (N_v)_{v\in V}$. Given edge weights $(w_e)_{e\in E}$, the corresponding \textit{multinomial dimer measure} is the probability measure on $\Omega_{{\mathbf N}}$ where
\begin{align*}
    \mathbb{P}(M) = \frac{\left|\pi^{-1}(M)\right|}{Z} \prod_{e\in M} w_e^{M_e}
\end{align*}
where $Z=Z_{G,{\mathbf N}}$ is the same partition function, given below. In other words, the multinomial dimer measure is the measure on $\Omega_{{\mathbf N}}$ which is the projection of the Boltzmann measure on dimer covers of $G_{{\mathbf N}}$ defined in (equation eq:lifted_measures of the paper). We also refer to the measure in (equation eq:lifted_measures of the paper) as the \textit{lifted} version of the multinomial dimer measure.

[Lemma operators_with_M of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix a path $\pi(t,dx)=\rho_t(x)\;dx$ in $ {\mathcal{D}}([0,T],\mathscr{M}_{ac})$. Assume $ {\rho}$  {to satisfy the same hypothesis as in Lemma (decomposition_lemma of the paper).} Then, there exists an $M\in L^2(\sigma(\rho)^{-1})$ satisfying 
     \begin{equation}
         L_0^{(\partial_t)}(H)=\int_0^T\langle M_s,\nabla H_s\rangle\;ds\quad,\quad\int_0^1 \frac{M_t}{\sigma(\rho_t)}\;dx=0
     \end{equation}
     for almost every $0\leq t\leq T$ and for all $H\in C_0^{0,1}(\Omega_T)$ such that 
     \begin{equation}
         I^{(1)}_{[0,T]}(\rho)=\frac{1}{4}\int_0^T\Big\{||M_t+\nabla \rho_t||^2_{\sigma(\rho_t)^{-1}}-R_t\Big\}\;dt {,}
     \end{equation}
     where $R_t=\Big\langle \frac{\nabla \rho_t}{\sigma(\rho_t)} \Big\rangle^2\frac{1}{\langle \sigma(\rho_t)^{-1}\rangle}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:description of arXiv:2512.17808, 'Zeros of polynomial powers under the heat flow'] For any $t>0$, the limiting distribution $\mu_t$ satisfies the following.
\begin{enumerate}
\item Its Stieltjes transform $m_t$ is given by
\begin{align}
m_t(z)=\frac 1 t (z-u^*_t(z)), \quad z\in\mathcal D_t
\end{align}
and solves the equation
\begin{align}
m_t(z)=\frac 1 \alpha \sum_{j=1}^d\frac{\alpha_j}{z-tm_t(z)-\lambda_j}, \quad z\in\mathcal D_t .
\end{align}
\item Its logarithmic potential satisfies
\begin{align}
U_t(z)=G(z,u_t^*(z)), \quad z\in\mathcal D_t .
\end{align}
\item It is compactly supported on finitely many smooth curves (plus endpoints) within
 $$\supp(\mu_t)\subseteq\mathcal D_t^c= \{z\in\mathbb{C}\setminus B: G(z,u_t^i(z))=G(z,u_t^j(z))\text{ for some }1\le i< j\le d+1\}\cup B.$$
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:FV-condition of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] There exists a constant $C=C(H)$  such that for all $(s,t, u, v, T)\in [0,1]^5_{\leq}$ we have 
    \begin{equs}
        \mathbb{E} \big( \widetilde{B}^{s,1}_{t, T}\widetilde{B}^{s,1}_{u, v} \big) \leq C |v-u|^{2H}. 
    \end{equs}

