\begin{equation*}
    \Eb\max_{1\leq j\leq p}
    \Abs{\frac{1}{n}\sum_{i=1}^n\epsilon_{ij}}
    \geq
    \frac{1}{\sqrt{2\log2}}\sqrt{\frac{\log(2p)}{n}}.
\end{equation*}

