[Definition 34 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] For $T > 0$, we say that a measurable function $u: Q_{T}\to \R$ is a \emph{distributional solution} of $u_{t} - \frac{1}{2d}\Delta(u^{m+1}) = 0$ in $Q_{T}$ if 
	\begin{enumerate}
		\item $u \in L^{1}_{\loc}(Q_{T})$, the space of locally integrable functions on $Q_{T}$.
		\item $u^{m+1} \in L^{1}_{\loc}(Q_{T})$.
		\item $u \in C((0,T);L^{1}_{\loc}(\R^{d}))$.
		\item For all $\vp \in C^{\infty}_{c}(Q_{T})$, we have
		\begin{equation} 
			\int_{\R^{d}} \int_{0}^{T} \left(u \vp_{t} + (u^{m+1})\frac{1}{2d}\Delta\vp\right)\,dt\,dx = 0.
		\end{equation}
	\end{enumerate}

[Lem 60 of arXiv:2609.01389, 'K-stability and birational rigidity of Fano 3-fold weighted complete intersections'] \begin{enumerate}
\item Suppose that $z t \in \msF_1$.
Then the defining polynomials of $X$ can be written as
\[
\begin{split}
\msF_1 &= z t + s^2 + f_{10}, \\
\msF_2 &= z^3 y + z^2 g_6 + z (\alpha s^2 + g_{10}) + w^2 + g_{14},
\end{split}
\]
where $\alpha \in \mbC$ and $f_i, g_i \in (x, y) \subset \mbC [x, y, s, t, w]$.
\item Suppose that $z t \notin \msF_1$. 
Then the defining polynomials of $X$ can be written as
\[
\begin{split}
\msF_1 &= z^2 y + z f_6 + s^2 + f_{10}, \\
\msF_2 &= z^2 t + z (\alpha s^2 + g_{10}) + w^2 + g_{14},
\end{split}
\]
where $\alpha \in \mbC$ and $f_i, g_i \in (x, y) \subset \mbC [x, y, s, t, w]$.
\end{enumerate}

[Lemma Lemma exponential decay of increment of arXiv:2411.09260, 'The Hydrodynamic Limit of Hawkes Processes on Adaptive Stochastic Networks'] For all $m \geq 2$ and $0\leq b \leq m-1$,
\begin{multline}
\underset{n\to\infty}{\overline{\lim}} n^{-1}\log \mathbb{P}\bigg(  \sup_{t\in [t^{(m)}_b \wedge \tau_m , t^{(m)}_{b+1} \wedge \tau_m ]} \big\lbrace \tilde{z}_n\big(t \big) - \tilde{z}_n\big( t^{(m)}_b \big) \big\rbrace \geq n\tilde{\epsilon}_m \text{ or } \\
  \sup_{t\in [t^{(m)}_b  \wedge \tau_m , t^{(m)}_{b+1} \wedge \tau_m]} \big\lbrace \tilde{u}_n\big(t \big) - \tilde{u}_n\big( t^{(m)}_b \big) \big\rbrace \geq n^2 \tilde{\epsilon}_m \;  \;
 \bigg) < 0.
\end{multline}

