[Definition OLKasefzs of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] For each $\omega=(\omega^-,\omega^+)\in \tilde{\Omega}$, $n\in\mathbb{N}$ and each Borel set $A\subseteq \mathbb{R}^d$, we define
	\begin{align*}
		\mathcal{U}(n,\omega,A)
		:=
		\frac{1}{p}\sum_{1\leq i\leq p}
		\int_{0}^{n}
		\delta_{\{ b_{i}(P_{t}(\omega^-,\omega^+)) \}}(A)\,\mathrm{d}t.
	\end{align*}

	We also define the marginal of $\mu$ on $\mathbb{R}^d$ by
	\begin{align}
		\pi(A):=[(\Pi_{\mathbb{R}^d})_{\star}(\mu)](A).  
	\end{align}

