[Lemma lem:reduction of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Let $p_n(x,y)$ be the $n$-step transition probability of the Wegner model. For any $x \in \mathcal{I}_{\alpha}$ and $y \in \mathcal{I}_{\beta}$, we have
\begin{equation}
    p_n(x,y) = \frac{1}{M} \overline{p}_n(\alpha, \beta),
\end{equation}
where $\overline{p}_n(\alpha, \beta)$ is the $n$-step transition probability associated with $\overline{P}$.

[Theorem 2 (Wendel's formula) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $d\geq 1$ and $n\geq d+1$.  Let  $\xi_1,\dots, \xi_n$ be (possibly dependent) random vectors in $\R^d$ such that the following conditions hold:
\begin{itemize}
\item[(i)] \emph{Sign-flip invariance}:  For every vector of signs $(\eps_1,\dots, \eps_n)\in \{+1,-1\}^n$, we have the distributional equality
$$
(\eps_1 \xi_1,\dots, \eps_n \xi_n)
\stackrel{d}{=} (\xi_1,\dots, \xi_n).
$$
\item[(ii)] \emph{General position}:  For every $1\leq i_1 < \dots < i_d\leq n$, the probability that the vectors $\xi_{i_1}, \dots,\xi_{i_d}$ are linearly dependent is $0$.
\end{itemize}
Then
\begin{align}
    \pwend{n}{d}
    &:=
    \pr[0\in \Conv(\xi_1,\dots, \xi_n)]
    =
    \frac{1}{2^{n-1}}
    \sum_{j=d}^{n-1}
    \binom{n-1}{j},

    \\
    \qwend{n}{d}
    &:=
    \pr[0\notin \Conv(\xi_1,\dots, \xi_n)]
    =
    \frac{1}{2^{n-1}}
    \sum_{j=0}^{d-1}
    \binom{n-1}{j}.

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop wtapprox of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] For all $A,\varepsilon>0$, there exists a polynomial
    $P\in\mathbb{R}[h,\varphi]$ such that

    \begin{align*}
\sup_{(h,\varphi)\in[-C,C]\times\mathbb{R}} e^{-A\varphi^2}
|V_h'(\varphi)-P(h,\varphi)| < \varepsilon\, .
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2606.21394, 'McKean-Vlasov Equations for Large Networks of Neurons with Adaptive Asymmetric Edges'] With unit probability,
\begin{align}
\lim_{n\to\infty} n^{-1} \sup_{t\leq T} \sum_{j\in \mathbb{N}_n} \| \bar{u}^j_t - u^j_t \|^2 &= 0 \\
\lim_{n\to\infty} n^{-2} \sup_{t\leq T} \sum_{j,k\in \mathbb{N}_n} \| \bar{z}^{jk}_t - z^{jk}_t \|^2 &= 0 .
\end{align}

