[Lemma lem:mtg_bound_w of arXiv:2609.01984, 'Instantaneous shrinking of supports for stochastic PDEs\footnote{JY was supported by a KIA'] Let $\alpha\in(0,1)$, $q\ge0$, and $n\in\mathbb N$, and assume
$\mathbb{E}[W_q(w_n(0))^\alpha]<\infty$. Then there exists a constant
$N=N(\alpha,q,\nu,T)>0$ such that
\begin{equation}
\mathbb{E}\left[
\sup_{t\le T}
W_q(w_n(t))^\alpha
\right]
\le
N
\mathbb{E}\left[
W_q(w_n(0))^\alpha
\right].
\end{equation}
In particular, $w_n(t)\in L_1(\mathbb{R})$ for all $t\in[0,T]$ almost surely.
Furthermore, there exists $K=K(\nu)>0$ such that, for all $0\le s\le t\le T$,
\begin{equation}
\begin{aligned}
e^{-Kt}\int_{\mathbb{R}}w_n(t,x)\,\mathrm{d} x
&\le
e^{-Ks}\int_{\mathbb{R}}w_n(s,x)\,\mathrm{d} x  \\
&\quad+
\int_s^t e^{-Kr}\int_{\mathbb{R}}
\sqrt{
\sigma^2(w_n(r,x)+v_n(r,x))-\sigma^2(v_n(r,x))
}\,
\xi_2(\mathrm{d} r,\mathrm{d} x).
\end{aligned}
\end{equation}
Consequently,
$\left(e^{-Kt}\int_{\mathbb{R}}w_n(t,x)\,\mathrm{d} x\right)_{t\in[0,T]}$
is a nonnegative continuous supermartingale.

[Definition symmetric_integral of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] For a given process $u=(u^i)_{1\leq i\leq d}:[s,t]\rightarrow \mathbb{R}^d$, the symmetric integral is defined as 
			\begin{align*}
				\int_{s}^{t}u(x) \mathrm{d}^{\circ} B_{x}:=L^{2}(\Omega)-\sum_{1\leq i\leq d}\lim_{\epsilon\rightarrow 0}\int_{s}^{t}u^i(x)\frac{B_{r+\epsilon}^i-B_{x-\epsilon}^i}{2\epsilon} \mathrm{d}r.
			\end{align*} 
			when it exists. We also set
			\begin{align*}
				\int_{s}^{t}u(x)\otimes \mathrm{d}^{\circ} B_{x}:=L^{2}(\Omega)-\sum_{1\leq i,j\leq d}\lim_{\epsilon\rightarrow 0}\int_{s}^{t}u^i(x)\frac{B_{r+\epsilon}^j-B_{x-\epsilon}^j}{2\epsilon} \mathrm{d}r\  e_{i}\otimes e_j,
			\end{align*}  
			when it exists.

