[Thm 25 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N$ be a fixed even integer. Let $L:\widetilde{\mathcal{X}}\times\widetilde{\mathcal{X}}\to\mathbb{C}^{2\times 2}$ be defined as follows:
	\begin{equation}
	\begin{split}
		L(\virst_i,\virst_j)&\,=\,\left[\begin{array}{cc}
			1 & 0 \\
			0 & 0
		\end{array}\right]\mathbbm{1}_{i+1=j}
		+\left[\begin{array}{cc}
			-1 & 0 \\
			0 & 0
		\end{array}\right]\mathbbm{1}_{j+1=i},\\
		L(\virst_i,(j,x_2))&\,=\,\left[\begin{array}{cc}
			0 & 0 \\
			\phi_{i}(\virst_i,x_2) & 0
		\end{array}\right]\mathbbm{1}_{i=j},\\
		L((i,x_1),\virst_j)&\,=\,-L(\virst_j,(i,x_1))^T,\\
		L((i,x_1),(j,x_2))&\,=\,\left[\begin{array}{cc}
			0 & 0 \\
			\phi_{i}(x_1,x_2) & 0
		\end{array}\right]\mathbbm{1}_{i+1=j<N}+\left[\begin{array}{cc}
			0 & \phi_{j}(x_2,x_1) \\
			0 & 0
		\end{array}\right]\mathbbm{1}_{j+1=i<N} +\left[\begin{array}{cc}
			0 & 0 \\
			0 & \Psi(x_1,x_2)
		\end{array}\right]\mathbbm{1}_{i=j=N},\hspace{-40pt}
	\end{split}
	\end{equation}
	for $1\leq i,j\leq N$ and $x_1,x_2\in\mathbb{N}$.
        Then for $A\subset \mathcal{X}$ we have
	\[\Pf\left[L\big|_{\mathcal{V}\cup A}\right]=\begin{dcases*}
		\mathcal{W}_{N,0}(A|\emptyset) & if $A\in\Lambda_N$,\\
		0 & otherwise.
	\end{dcases*}\]

[Prop shuffling-general-m of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $(\mathbb{X},\mathcal X)$ be a measurable space.
	Let $\psi$ be a measurable $\mathbb{X}$-shuffling rule, and let $({\mathfrak{m}}_T)_{T\in\trees}$ be a collection  of finite measures on $\mathbb{X}^T$ respectively.
	If $\psi$ is $\mathfrak{S}$-equivariant  and $({\mathfrak{m}}_T)_{T\in\trees}$ is $\mathfrak{S}$-consistent, then the measure ${\mathfrak{m}}$ on $\trees{[\mathbb{X}]}$ given by
	\begin{align}
	{\mathfrak{m}}(\mathop{}\!\mathrm{d}T,\mathop{}\!\mathrm{d}{\boldsymbol{x}})=\sum_{T_0\in\trees}\delta_{T_0}(\mathop{}\!\mathrm{d}T)\,{\mathfrak{m}}_{T_0}(\mathop{}\!\mathrm{d}{\boldsymbol{x}})
	\end{align}
	is invariant
	\footnote{
		We say that a measure $m$ is invariant under $f$ if we have $f_\#\,m=m$.
	}
	under the mapping $F^\psi\colon(T,{\boldsymbol{x}})\mapsto \bigl(({\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}})\cdotT,({\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}})_*\,{\boldsymbol{x}}\bigr)$.

