[Definition 25 of arXiv:2605.24445, 'Matrix concentration inequalities for time-inhomogeneous Markov chains'] \label[definition]{def:sigma}
Let \(t\ge 1\). Since \(\mu_t=\mu_{t-1}P_t\), the Markov operator $P_t$
maps \(L^2(\mu_t)\) to \(L^2(\mu_{t-1})\). Define
the \emph{one-step (second) singular value}
\[
\sigma_t
:=\|P_t\|_{L^2_0(\mu_t)\to L^2_0(\mu_{t-1})}
=\sup\Big\{\|P_t f\|_{2,\mu_{t-1}}:\ \|f\|_{2,\mu_t}=1,\ \mu_t(f)=0\Big\}.
\]
Equivalently, for all \(f\in L^2(\mu_t)\) with \(\mu_t(f)=0\),
\begin{equation}
\|P_t f\|_{2,\mu_{t-1}}\le \sigma_t\,\|f\|_{2,\mu_t}.
\end{equation}

[Cor 93 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Fix a grounded enumeration $g_0,g_1,\dots$ of $\G$, let $F_n := \{g_0,g_1,\dots,g_n\}$ for each $n$, and assume that $F_{n+1}$ is an enlargement of $F_n$ in direction $s_n$.  Given $\phi \in \S^\circ_k(\G)$, let $C_n$ be the Verblunsky coefficient of $\phi$ from $F_n$ to $F_{n+1}$.  Then the map
\begin{equation}
	\S^\circ_k(\G) \to \prod_{n\ge 0}\Xi^\circ(k,k|F_n\setminus s_nF_n|):\phi\mapsto (C_0,C_1,\dots)
	\end{equation}
	is a bijection.

[Theorem 25 ({\cite[Theorem 1.7 and Remark 1.10) of arXiv:2607.18104, '2607.18104'] {DV:LongestSub}}]
On the full-space $\R^{4}_{\uparrow}$, we have convergence of the LPP landscape $\LLeps$  to the directed landscape $\mathcal{L}$  (Definition \ref{def:DirectedLandscape}), i.e., as $\varepsilon \rightarrow 0$ 
\begin{equation}
\big(\LLeps(x,s\tilde{\omega}^{-1};y,t\tilde{\omega}^{-1})\big)_{(x,s;y,t) \in \R^{4}_{\uparrow}} \rightarrow \big(\mathcal{L}(x,s;y, t)\big)_{(x,s;y,t) \in \R^{4}_{\uparrow}}
\end{equation} in distribution, where we have $\tilde{\omega}=  2^{3/2} (1 + \sqrt{\rho})^{-1/2} \rho^{1/4}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem high-mass-decays of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] For every $\tilde z_0 \in \mathbb{R}^d$, $\eta \in (0,\eta^*(\tilde z_0))$, and $C, \kappa, \rho > 0$ there is some $\delta > 0$ such that for all $v_0 \in S^{n-1}$, $z_0 \in \mathbb{R}^d$ with $\|\tilde z_0 - z_0\| < \delta$, and $\epsilon < \delta$ we have
    \begin{align*}
       \mathbb{P}\Big( \sup_{t \leq T_\epsilon} \|P_{\eta}(z_0)v^\epsilon(t)\| \leq \delta \text{ and } \|x^\epsilon(T_\epsilon)\| \geq e^{(\lambda-\eta+\kappa)T_\epsilon}\|x_0\|\Big) < \rho\,,
    \end{align*}
    where we set $T_\epsilon = C\ln \epsilon^{-1}$ and $\lambda \coloneqq \lambda^\epsilon(z_0) \coloneqq \lambda(A^\epsilon(z_0))$.

[Proposition integrability of arXiv:2410.23509, 'Dynkin Games for L\'evy Processes'] Consider a L\'evy process $X$,
a discount rate $r>0$,  a function $G\colon\mathbb{cR}\to\mathbb{cR}$, 
and assume that there exist positive constants $A,B,\alpha$ such that
\begin{equation}
|G(x)|\leq A+B\cosh(\alpha x),    
\end{equation}
and    
\begin{equation}
    \operatorname{\mathbf{E}} e^{\alpha X_1}< e^r\qquad\text{and}\qquad \operatorname{\mathbf{E}} e^{-\alpha X_1}< e^r.
\end{equation}
Then, the function $G$ satisfies conditions (equation eq:ic of the paper) and (equation eq:limit of the paper).

[Theorem 7 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] Consider large $n\in\mN$  and let $A_{ij}\sim \cN(0,1)$ be the independent elements of $A\in\mR^{n\times n}$. For a real scalar $c_3\geq 0$ set
  \begin{eqnarray}

 \hat{\bar{\gamma}}_{1} & = &  \frac{c_3\sqrt{2} + \sqrt{2 c_3^2+4}}{4}
 \nonumber \\
 \bar{\phi}_{1}(\gamma_1) & = &  \gamma_{1}c_3\sqrt{2} - \frac{1}{2}\log \lp 1 - \frac{c_3\sqrt{2}}{2 \gamma_{1}}   \rp
 \end{eqnarray}
 Let $\xi^+_{wig}$ be as in (\ref{eq:wiginteq1ab0}) and for a real scalar $u\geq \mE \xi^+_{wig}$ set
 \begin{eqnarray}

 \nonumber \\
 \bar{\phi}_u(u) & = & -\frac{c_3^2}{2} + \bar{\phi}_{1}(\hat{\bar{\gamma}}_1)  -c_3 u .
 \end{eqnarray}
One then has the following LDP with the indicator rate function $\zeta_u(u)$
\begin{eqnarray}

\lim_{n\rightarrow \infty} \frac{\log\lp \mP\lp \xi^+_{wig} \geq u  \rp \rp}{n} \leq \min_{c_3\geq 0}\bar{\phi}_u(u) \triangleq -\bar{\zeta}_u(u).
\end{eqnarray}

