body:
[Theorem T:CLT-Yn of arXiv:2511.17101, 'Central limit theorem for the range of critical branching random walk'] Assume (equation eq:assmption of the paper). When $d>8$, there is a constant $\kappa=\kappa_d>0$ such that
\begin{equation}    
\lim_{n\to\infty}\frac{\mathrm{Var}(Y_n)}{n}=\kappa. 

\end{equation}
When $d>16$, for every continuous real function $\varphi$  satisfying $\sup_{x\in\mathbb R}|\varphi(x)/(1+x^2)|<\infty$, we have
\begin{align}
{\mathbb E} \left|{\mathbb E} \Big[ \varphi\left(\frac{ Y_n- {\mathbb E}[Y_n]}{\sqrt{n}}\right) \,\big|\, {{\mathscr F}_0}\Big] - {\mathbb E}[\varphi({\tt g}_\kappa)] \right| \to 0, \quad n\rightarrow\infty,
\end{align}
where  ${\tt g}_\kappa\sim {\mathcal N}(0, \kappa)$ denotes a centered Gaussian random variable with variance $\kappa$. 
In particular, $\frac{ Y_n- {\mathbb E}[Y_n]}{\sqrt{n}}$ converges in law to $\mathcal N(0,\kappa)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop main of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] Let $z_{c}(N)>0,\ z_{c}>0$ be the unique root of $V'_{N}(z),\ V'(z)$ on $(0,\frac{1}{a_{1}})$ respectively. Then $V_{N}(z_{c}(N))>0,\ V(z_{c})>0$, and  
    \begin{equation}
    \begin{split}
        &\mu_{+}(N)=V_{N}(z_{c}(N))\rightarrow\mu_{+}=V(z_{c})\ \text{as}\ N\rightarrow\infty,\\
        &\tilde{C}=2^{-\frac{1}{3}}V''(z_{c})^{\frac{1}{3}}.
    \end{split}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2609.03003, 'Causal Foundation Models'] In the binary or multi-armed treatment case, a DGP satisfies the \textbf{positivity} assumption if 
\begin{equation}
    P(T = t \mid X = x) > 0 \qquad \forall t \in \mathcal{T}, x \in \mathcal{X}.
\end{equation}
In the continuous treatment case, a DGP satisfies the positivity assumption if the conditional density function $p$ for $P$ satisfies
\begin{equation}
    p(T = t \mid X = x) > 0 \qquad \text{almost everywhere}.
\end{equation}
The positivity assumption is also called the overlap assumption. It is needed because we can only learn the causal effect of a treatment for covariate values where that treatment can actually be observed. For example, if we assume ignorability, then by \cref{eq:ignorability_example} the quantity $\mathbb{E}[Y(t) \mid X=x]$ is equal to $\mathbb{E}[Y \mid T=t, X=x]$, but if $P(T = t \mid X = x) = 0$ there will be no observations of $Y$ for individuals with covariates $X=x$ who receive treatment $T=t$.

[Prop 24 of arXiv:2609.02261, 'Quantization and process'] For all symbols $F\in {\cal S}(\R^{2n})$,

  \begin{align} 
  <( {\rm Op }_h^{\rm Weyl}  F) \Psi _{X h}, 
 \Psi _{X h}> &=  (\pi  h) ^{-n} \int _{\R^{2n}} 
 e^{ - \frac {1} {h} |X-T|^2 } F(T) dT \\[3mm]
 & = (F \star \nu_h^{\rm Weyl} ) (X), 
 \end{align}

where $ \nu_h^{\rm Weyl}$ denotes the measure defined in (\ref{mesure-Weyl}), that is,

   $$ d \nu_h^{\rm Weyl} (X) =  ( \pi h) ^{-n}
  e^{ - \frac {1} {h} |X|^2 } dX. $$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Characterization of the static regime-switching Schr\"odinger bridge,
\cite{nutz2022eot}) of arXiv:2607.19176, 'Exponential Convergence of the Sinkhorn Algorithm for the Schrödinger Bridge with Regime S'] Under Assumption \ref{assum:reference_marginals}
the static regime-switching Schr\"odinger bridge problem \eqref{eq:static_SSBP} admits a unique optimal
solution $\pi^{\rho,\mu}\ll P_{0,T}$, characterized as follows.
The Radon--Nikodym derivative of the optimal measure $\pi^{\rho,\mu}$ with respect to the reference measure $P_{0,T}$ satisfies
\begin{equation}
   \frac{d\pi^{\rho,\mu}}{dP_{0,T}}(z_0,z_T) = \tilde{f}_{i_0}(x_0) \tilde{g}_{i_T}(x_T) \quad \text{for }\pi^{\rho,\mu}\text{-a.e. } (z_0,z_T)=((x_0,i_0),(x_T,i_T)).
\end{equation}
where $(\tilde{f}_i)_{i \in \mathcal I}$ and $(\tilde{g}_j)_{j \in \mathcal I}$ are nonnegative measurable functions, unique up to the transformation
\begin{equation}
    (\tilde{f}, \tilde{g}) \sim (\lambda \tilde{f}, \lambda^{-1} \tilde{g}), \quad \lambda > 0,
\end{equation}
and solve the Schr\"odinger system
\begin{equation}
\begin{cases}
    1 = \tilde{f}_i(x) \displaystyle\sum_{j \in \mathcal I} \int_{\mathbb{R}^d} p_{ij}(x, y) \tilde{g}_j(y) \mu_j(dy), & \rho_i\text{-a.e. } x, \\
    1 = \tilde{g}_j(y) \displaystyle\sum_{i \in \mathcal I} \int_{\mathbb{R}^d} p_{ij}(x, y) \tilde{f}_i(x) \rho_i(dx), & \mu_j\text{-a.e. } y.
\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 216 of arXiv:2601.16377, '2601.16377'] The fundamental solution $\boldsymbol{\mathcal{F}}(z_1,z_2)$ has the following properties.
\begin{enumerate}
\item[(F1)] Writing $\{i,j\} = \{1,2\}$, it is tame with exponent $1$ with respect to $z_i$, uniformly so for $z_j$ in any compact subset of ${\amsmathbb{C}} \setminus [\alpha_{h_j},\beta_{h_j}]$.
\item[(F2)] It is a solution of the master Riemann--Hilbert problem with respect to both its variables. Namely, for any $h_1,h_2 \in [H]$, $z_i \in \amsmathbb{C} \setminus [\alpha_{h_i},\beta_{h_i}]$ and $x_i \in (\alpha_{h_i},\beta_{h_i})$ we have
\begin{equation*}
\begin{split}
\theta_{h_1,h_2}\big(\mathcal{F}_{h_1,h_2}(x_1^+,z_2) + \mathcal{F}_{h_1,h_2}(x_1^-,z_2)\big) + \sum_{g_1 \neq h_1} 2\theta_{h_1,g_1} \mathcal{F}_{g_1,h_2}(x_1,z_2) & = - \frac{\delta_{h_1,h_2}}{(x_1 - z_2)^2}, \\
\theta_{h_1,h_2}\big(\mathcal{F}_{h_1,h_2}(z_1,x_2^+) + \mathcal{F}_{h_1,h_2}(z_1,x_2^-)\big) + \sum_{g_2 \neq h_2} 2\theta_{h_2,g_2} \mathcal{F}_{h_1,g_2}(z_1,x_2) & = - \frac{1}{(z_1 - x_2)^2} .
\end{split}
\end{equation*}
Writing $\{i,j\} = \{1,2\}$, the limit indicated by $x_i^{\pm}$ is uniform with respect to $z_j$ in any compact of ${\amsmathbb{C}} \setminus [\alpha_{h_j},\beta_{h_j}]$, and a continuous function of $x_i$. Note that the source function in both cases is $D_{h_1,h_2}(z_1,z_2) = -\frac{\delta_{h_1,h_2}}{(z_1 - z_2)^2}$. \item[(F3)] It has a joint tameness property, namely there exists a constant $M > 0$ such that, for any $z_1 \in {\amsmathbb{C}} \setminus [\alpha_{h_1},\beta_{h_1}]$ and $z_2 \in {\amsmathbb{C}} \setminus [\alpha_{h_2},\beta_{h_2}]$
\[
\big|(z_1 - z_2)^{2\delta_{h_1,h_2}}\sigma_{h_1}(z_1)\sigma_{h_2}(z_2)\mathcal{F}_{h_1,h_2}(z_1,z_2)\big| \leq M
\]
\item[(F4)] For each $\varepsilon_i \in \{\pm 1\}$ and $x_i \in (\alpha_{h_i},\beta_{h_i})$ with $i = 1,2$, the joint boundary values
\[
\lim_{(t_1,t_2) \rightarrow (0^+,0^+)} \bigg(\mathcal{F}_{h_1,h_2}( x_1 + \ii \varepsilon_1 t_1,\,x_2 + \ii \varepsilon_2 t_2) + \frac{\delta_{h_1,h_2}\delta_{\varepsilon_1 + \varepsilon_2,0}}{( x_1 + \ii \varepsilon_1 t_1 - x_2 - \ii \varepsilon_2 t_2)^2}\bigg)
\]
exist uniformly for $x_i$ in any compact subset of $(\alpha_{h_i},\beta_{h_i})$, and are continuous functions of $x_1,x_2$.
\item[(F5)] for any $h, h_i \in [H]$ and $z_i \in \amsmathbb{C} \setminus [\alpha_{h_i},\beta_{h_i}]$ with $i = 1,2$, we have
\begin{equation}

\oint_{\gamma_{h}} \mathcal{F}_{h_1,h_2}({z}_1,z_2)\dd z_1 = \oint_{\gamma_{h}} \mathcal{F}_{h_1,h_2}(z_1,{z}_2)\dd z_2 = 0.
\end{equation}
\item[(F6)] $\mathcal{F}_{h_1,h_2}(z_1^*,z_2^*) = \big(\mathcal{F}_{h_1,h_2}(z_1,z_2)\big)^*$.
\end{enumerate}

