body:
[Theorem t:DNM_intro of arXiv:2511.12692, 'A stochastic flow approach to De Giorgi--Nash--Moser estimates for SPDE\lowercase{s} with '] Let the coefficient fields $a\colon \Omega \times [0,T]\times \mathbb{T}^d \to {\mathbb R}^{d\times d}$ and $b_n \colon  \Omega \times [0,T]\times \mathbb{T}^d \to {\mathbb R}^{d}$ for $n\ge 1$ be progressively measurable and suppose that for some $\gamma_0>0$, $u_0\colon \Omega \to  C^{\gamma_0}(\mathbb{T}^d)$ is strongly ${\mathscr F}_0$-measurable. Suppose that there exist $\delta\in (0,1)$ and $\nu, M, C \in (0,\infty)$ such that (equation eq:stoch_para_intro of the paper), (equation eq:bddness_intro of the paper) and 
\begin{equation}

    \|(b_n)_{n\ge 1}\|_{C^{3+\delta}(\mathbb{T}^d;\ell^2({\mathbb R}^d)) }\,\le\, C,\qquad t\in [0,T],
\end{equation}
holds almost surely. Then, the weak solution $u$ to (equation eq:SPDE_lin_intro of the paper) satisfies
\begin{equation}
{\mathbb P}\big(\,u :(0,T)\times \mathbb{T}^d \to {\mathbb R} \,\text{\normalfont{ is H\"older continuous}}\big)\,=\,1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.13631, 'The classical discrete laws near the mode:\\ complete local expansions for the negative bi'] As $N\to\infty$, uniformly for $(\kappa,\eta)$ in compact subsets of $(0,1)^{2}$ and
	$t\in H$ with $\mu+t\in\Z$,
	\begin{equation}
		\log\Bigl[\sqrt{2\pi\Sigma_0^{2}}\;P(\mu+t)\Bigr]
		\sim\sum_{m\ge1}\frac{A_m(t)}{N^{m}},
	\end{equation}
	with
	\begin{multline}
		A_m=\frac{(-1)^{m+1}}{m(m+1)}
		\Bigl[(W_m-1)\,B_{m+1}
		-\bigl(a^{-m}+d^{-m}\bigr)B_{m+1}(t+1)\\
		-\bigl(b^{-m}+c^{-m}\bigr)B_{m+1}(1-t)\Bigr],
	\end{multline}
	where $W_m=\kappa^{-m}+(1-\kappa)^{-m}+\eta^{-m}+(1-\eta)^{-m}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma part2 of arXiv:2606.15203, 'The existence of invariant sublinear expectations for $G\text{-}$SDEs'] Under the assumptions \textbf{(H1)} and \textbf{(H2)}, for any $\varphi \in B_b(\mathbb{R}^d)$,
  \begin{equation*}
   \nu(t,x) \coloneqq \underset{\theta \in  \mathcal{A}^{\Theta}_{t,T}}{{\rm sup}} E_P[\varphi(x+\int^T_t b(X_s^{t,x,\theta})ds+\int_t^T\theta_sdW_s)]  
 \end{equation*}
  is 
  continuous in $t$ for any fixed $0\leq T<\infty$, $0\leq t < T $, $x \in \bar{O}$, where $\bar{O}$ is a bounded subset of $\mathbb{R}^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

