[Corollary coro:m_easy of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Let $\mathsf{m}_{\textsc{e}}=\sqrt{1-\frac{1}{\beta(\lambda_1-\lambda_2)}}$ and let $h(x) = 2H(x)/N$. Then  for any $\varepsilon < \mathsf{m}_{\textsc{e}}$, 
  \begin{align*}
        \inf_{\{x : |m(x)|<\varepsilon\}} (\lambda_1 - h(x)) - (1-\frac{1}{N}) \frac{1}{\beta} > (\lambda_1-\lambda_2)(\mathsf{m}_{\textsc{e}}^2 - \varepsilon^2)\,.
    \end{align*}

[Lemma lem:cut_edge_prob of arXiv:2605.06511, 'Logarithmic Mixing of Random Walks on Dynamical Random Cluster Models'] Let $n \in \mathbb{N}$ be sufficiently large and $G = (V, E)$ a $d$-regular graph on $n$ vertices. For all $\mu > 0$, $t \geq 0$, $\Delta > 0$ such that $\mu \Delta > 2 \log 2$, $e = \{u, u'\} \in E$ such that $u$ does not lie on a cycle of length less than $r$ and $B_R(u)$ has at most one cycle, and $(\eta, v) \in \{0, 1\}^E \times V$,
		\begin{align*}
			&\ \mathbb{P}\left[\xi_{u, e}^{\mathrm{cut}} (t, \tau_e(t, t + \Delta))\mid \mathsf{C}_e\left(t, t + \Delta\right), (\eta_t, X_t) = (\eta, v)\right] \\
			\geq&\ \mathbb{P}\left[S_{[t, t + \Delta]} \left(R, K\right) \mid \left(\eta_t, X_t\right) = \left(\eta, v\right)\right] \left(1 - (2K + 1) e^{-{\mu \Delta}/{2}} - O\left((\log n)^{-3}\right)\right).
		\end{align*}

[Lem 21 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] The Shannon entropy is given by
\begin{align}
\mathcal{S}^{(1,n)} = 2^{-n}\mathcal{S}^{(n)}  + n\log(2), 
\end{align}
for every $n\geq 2$. Hence, $-2^nn\log(2) \leq \mathcal{S}^{(n)} < 0$ for every $n\geq 2$.

