body:
[Lemma 41 (cf. {\cite[Lemma 3.4 and Lemma 3.5) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {MSS24}}] 
    There exists a constant $C_1 = C_1(b, \Delta, \mu)$ such that if $\beta \leq C_1 (\deg_{\mathrm{min}}/\log n)^{1/\alpha}$, then the following holds with high probability:
    \begin{enumerate}
        \item For all $v \in V_n$ we have
        \begin{equation} 
            \frac{1}{3 \Delta n} \leq \pi(v) \leq \frac{3\Delta}{n};
        \end{equation}
    \item and for all $S \subset V_n$ with $0 < \pi(S) \leq 1/2$, it holds that
        \begin{equation} 
            \Phi_{(G_n,\weight)}(S) \geq \frac{b}{72\Delta^2}.
        \end{equation}
    \end{enumerate}

