[Theorem intro:thm:asympt of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] Let $e_\alpha=( \cos \alpha, \sin \alpha)$ with $\alpha_0 \in (0, \pi/2)$. 
Then as $r \to \infty$ and $\alpha\to\alpha_0$ we have
\begin{equation}
\pi (r e_\alpha) = 
  (1+o(1))\cdot  \left\{
\begin{array}{ll}
\frac{C_0}{\sqrt{r}}e^{-r \langle e_\alpha \vert\theta(\alpha) \rangle}  & \text{ in } \mathscr{Q}_{--},\\
C_1e^{-r \langle e_\alpha \vert\eta\theta^{*}\rangle} & \text{ in } \mathscr{Q}_{+-},\\
C_2 e^{-r \langle e_\alpha \vert\zeta\theta^{**}\rangle}& \text{ in } \mathscr{Q}_{-+},\\
C_1e^{-r \langle e_\alpha \vert\eta\theta^{*}\rangle}  +
 C_2e^{-r \langle e_\alpha \vert\zeta\theta^{**}\rangle} & \text{ in } \mathscr{Q}_{++},
\end{array}
\right.
\end{equation}
  where $C_0$, $C_1$ and $C_2$ are constants and the sets $\mathscr{Q}_{\pm\pm}$ are explicit parameter-dependent regions. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 10 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] A decoupling field $w$ is called regular 
    if it is uniformly Lipschitz in $x$, 
    i.e. there is a positive constant $L_w > 0$,
    for all $x,y\in\R^n$ and $(s,\oz)\in [0,T]\times\Oz$,
    \begin{equation}
        |w(s,\oz,x) - w(s,\oz,y)|\leq L_w|x - y|.
    \end{equation}

[Definition def:trajectory of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Let $g_0 \in L^2(\pi)$ satisfy the centering condition $\langle g_0, \mathbf{1} \rangle_\pi = 0$. The \emph{relaxation trajectory} generated by $g_0$ is the sequence
\begin{equation}
g_k := P^k g_0, \qquad k = 0,1,2,\dots
\end{equation}
The \emph{energy} of the trajectory at step $k$ is
\begin{equation}
E_k := \|g_k\|_\pi^2.
\end{equation}

[Prop p.prob.space of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] Notation as above.
\begin{enumerate}
\item 
The polymer measures $M^{\theta}_{[s,t]}$ for $s<t\in q\mathbb{D}$ can be constructed on $(\Omega,\mathscr{F},\mathbf{P})$ with each $M^{\theta}_{[s,t]}$ being $\mathscr{F}_{[s,t]}$-measurable.
\item 
For $t_1<\cdots<t_{2\ell} \in q\mathbb{D}$, $I_{i}:=[t_{2i-1},t_{2i}]$, and $r_i:=t_{2i+1}-t_{2i}$\ ,
\begin{align}

	\mathbf{E}\big[ 
		M^{\theta}_{[t_1,t_{2\ell}]} 
	\,\big|\,
		\mathscr{F}_{I_1\cup\cdots\cup I_{\ell}}
	\big]
	=
	M^{\theta}_{I_1} \,\raisebox{0.1ex}{\scalebox{.75}{$\odot$}}_{\,r_1}\, \cdots \,\raisebox{0.1ex}{\scalebox{.75}{$\odot$}}_{\,r_{\ell-1}}\, M^{\theta}_{I_\ell}\ .
\end{align}
\item 
Take the notation in (equation p.prob.space.2 of the paper), fix $t_1,t_{2\ell}$, and, for each $i=1,\ldots,\ell-1$, fix $t_{2i}$ or $t_{2i+1}$ and vary $r_i\inq\mathbb{D}_{>0}$ so that $t_{2i+1}:=t_{2i}+r_{i}$ or $t_{2i}:=t_{2i+1}-r_{i}$. 
We have
\begin{align}

	\bigvee_{r_1,\ldots,r_{\ell}\inq\mathbb{D}_{>0}} \mathscr{F}_{I_1\cup\cdots\cup I_\ell}
    =
    \mathscr{F}_{[t_1,t_{2\ell}]}\ .
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

