[Lem 10 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] {\rm (1)} We assume the condition {\rm (SG)} in Section \ref{sec:1.20.4}
and the following bound for $\bar\mu_{\ell,0}$ and every $p'>2$
\begin{align} 
\inf_{\bar\phi\in \R^{2\ell-1}} \int_{\R^{2\ell-1}} | \phi(x)-\bar\phi(x)|^{p'} 
\bar\mu_{\ell,0}(d\phi)   \le C \ell^{p'/2},
\end{align}
with $C=C_{p'}>0$, uniform in $x$ and $\ell$.  
Then, for $2< q < p<\infty$, we have
\begin{align}  
\|f\|_{L^q(\bar\mu_{\ell,m})} \le C_{p,q} \ell \|D_\phi f\|_{L^p(\bar\mu_{\ell,m})}
\end{align}
for $f$ satisfying $\int_{\R^{2\ell-1}}f(\phi) \bar\mu_{\ell,m}(d\phi)=0$,
where $C_{p,q}>0$ is uniform in $\ell$ and $m$. \\
{\rm (2)} The uniform bound \eqref{eq:uniform-phi} holds if $V$ satisfies
\begin{align} 
V\in C^2(\R) \quad \text{and} \quad V''\ge c >0.
\end{align}

