[Definition of arXiv:2608.10415, 'Continuous random variables'] A measurable space is a set $X$, given with a set of subsets $M\subset P(X)$, called measurable sets, which form an algebra, in the sense that:
\begin{enumerate}
\item $\emptyset,X\in M$.

\item $E\in M\implies E^c\in M$.

\item $M$ is stable under countable unions and intersections.
\end{enumerate}

[Lemma 26 of arXiv:2511.02725, 'Mixing of general biased adjacent transposition chains'] Let $Y^{(k)}$ be drawn from the $k$-particle $q$-ASEP stationary distribution with $q> \rc 2$ as in~\eqref{eq:q-eps-relation} ($\fc{q}{1-q}=1+\ep$). Then for every $k\le n$, for $r \ge C_q$,        \begin{align*}
            \nu^{(k)}_{[n]}( \max \{v: Y^{(k)}(v) =1\} \ge k + r) 
            \le             e^{-\ep' r/4}
        \end{align*}
                                when $r\ge \fc{4}{\ep'}\log \pf{2}{\ep'}$.

[Theorem 3 of arXiv:2608.30551, 'Critical Discrete Hardy Inequalities in $L^p$'] Let $p>1$, $\sigma\in(0,1/2)$, and $\alpha\in(\sigma,1/2)$. If
$u\in\ell^p(\Z,(1+|x|)^{-2\sigma})$, then
\begin{equation}
\mathcal{E}_p^{\Z,\sigma}(u)
\geq
\sum_{x\in\Z}w_{p,\sigma,\alpha}(x)|u(x)|^p,
\end{equation}
where $w_{p,\sigma,\alpha}$ is given by
\begin{equation}
w_{p,\sigma,\alpha}(x)
:=
\frac{1}{a_p+1}
\frac{\Delta^\sigma k_{-\alpha}^{a_p}(x)}
     {k_{-\alpha}^{a_p}(x)}
+
\frac{a_p}{a_p+1}
\frac{\Delta^\sigma k_{-\alpha}(x)}
     {k_{-\alpha}(x)},
\qquad x\in\Z.
\end{equation}
The Hardy weight $w_{p, \sigma, \alpha}$ is strictly positive and as $|x|\to\infty$,
\begin{equation}
w_{p,\sigma,\alpha}(x)
=
\frac{\Psi(p,\sigma,\alpha)}{|x|^{2\sigma}}
+
O\left(
\frac{1}{
|x|^{2\sigma+1-\max\{2\sigma,1-2\alpha\}}
}
\right),
\end{equation}
where
\begin{equation}
\Psi(p,\sigma,\alpha)
:=
\frac{1}{a_p+1}
\frac{\mathcal{A}_{\gamma_p-\sigma}}
     {\mathcal{A}_{\gamma_p}}
+
\frac{a_p}{a_p+1}
\frac{\mathcal{A}_{\alpha-\sigma}}
     {\mathcal{A}_{\alpha}},
\end{equation}
with
\begin{equation}
\gamma_p
:=
\frac{1-a_p(1-2\alpha)}{2}.
\end{equation}
Moreover, $w_{p,\sigma,\alpha}$ is critical whenever
\begin{equation}
\alpha
\leq
\frac{2\sigma+a_p}{2(a_p+1)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:local convergence of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $q\in (0,1)$, $c\in [0,1)$, and $M>1$. For each $m\in \mathbb{N}$, let $(y_{1,m},y_{2,m})\in \mathbb{Z}^2$ satisfy
\begin{align}
    y_{1,m}-y_{2,m} \in  [M^{-1}\sqrt{m},M\sqrt{m}].
\end{align}
Suppose $Q_{m}:=(Q_{1,m},Q_{2,m})$ has the law $\mathbb P_{\mathrm{Inter};q,c}^{m,(y_{1,m},y_{2,m})}$ defined in Definition (def:gibbslaw of the paper).
Extend $Q_m$ to all $j\ge0$ by setting $Q_m(j)=Q_m(m)$ for $j>m$.
Then, as $m\rightarrow\infty$, the law on
$\mathsf{Sign}_2^{\mathbb Z_{\ge0}}$ of
\begin{equation}
\left(Q_{1,m}(j)-Q_{2,m}(0),\,Q_{2,m}(j)-Q_{2,m}(0)\right)_{j\in \mathbb{Z}_{\ge 0}}
\end{equation}
converges weakly to the law of the Markov chain $\{\lambda^j\}_{j=0}^{\infty}$ on state space $\mathsf{Sign}_2$ defined as in Lemma (lem:limit MC of the paper).

