[Proposition 9 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] For the costs $\cost(x,y,z)$ satisfying the assumptions (H1)-(H3),
	the problems $(\mathrm{M^2OT})$ and \eqref{eq:3plans} are equivalent in the following sense: $\inf (\mathrm{M^2OT})= \inf \eqref{eq:3plans}$ and,
	\begin{enumerate}[label={(\roman*)}]
		\item assuming that $(\gamma,q)=(\gamma,\zeta\gamma)$ solves $(\mathrm{M^2OT})$, the following probability solves \eqref{eq:3plans},
		\begin{equation}

			\varpi = (\pi_1,\pi_2,\zeta)\# \gamma = \gamma(dxdy) \otimes \delta_{\zeta(x,y)}(dz);
		\end{equation}
		\item assuming that $\tilde{\varpi}$ solves \eqref{eq:3plans}, define the marginal $\tilde\gamma := \pi_{1,2}\# \tilde\varpi$ and perform the disintegration $\tilde\varpi(dxdydz) = \tilde\gamma(dxdy) \otimes \tilde\varpi_{x,y}(dz)$; then  the following pair solves $(\mathrm{M^2OT})$,
		\begin{equation*}
			(\tilde\gamma,\tilde{q}) = (\tilde\gamma,\tilde\zeta \tilde\gamma ), \qquad \text{where} \qquad \tilde\zeta(x,y) := [\tilde\varpi_{x,y}] = \int_{\Rd} z\, \tilde\varpi_{x,y}(dz).			
		\end{equation*} 
	\end{enumerate}
	Moreover, if $\cost(x,y,\argu)$ is strictly convex for all $(x,y) \in X \times Y$, then every solution of \eqref{eq:3plans} is of the form \eqref{eq:omega-gamma}.

