body:
[Lem basic of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] The critical points of $\mathrm G(z)$ are
\begin{equation} 
    z_c^{\pm}= \frac{-\alpha_3+\alpha_1-\alpha_2 \pm \sqrt{\mathrm Q}}{2\alpha_3} 
    \qquad \text{where} \quad 
    \mathrm Q= \alpha_3^2 -2(\alpha_1 + \alpha_2)\alpha_3 + (\alpha_1-\alpha_2)^2, 
\end{equation}
with the following cases: 
\begin{enumerate}[(a)]
\item If $\alpha_1,\alpha_2 > 0$ and $\alpha_3>(\sqrt{\alpha_1}+\sqrt{\alpha_2})^2$, then  $\mathrm Q>0$,  
$\mathrm G''(z_c^{+}) <0$, $\mathrm G''(z_c^{-}) >0$, and $-1< z_c^-< z_c^+<0$.  

\item If $\alpha_1 < 0$ and $\alpha_2,\alpha_3 > 0$, then $\mathrm Q > 0$, $\mathrm G''(z_c^{+}) <0$, $\mathrm G''(z_c^{-}) <0$, and $z_c^- < -1 < z_c^+ < 0$.  

\item If $\alpha_2 < 0$ and $\alpha_1,\alpha_3 > 0$ then $\mathrm Q > 0$, $\mathrm G''(z_c^{+}) >0$, $\mathrm G''(z_c^{-}) >0$, and $-1 < z_c^- < 0 < z_c^+$.  
\end{enumerate}
Furthermore,  
\begin{equation} 
    \mathrm G''(z_c^{\pm})= \mp \frac{\sqrt{\mathrm Q}}{2\alpha_1\alpha_2} \left[ (\alpha_1+\alpha_2)\alpha_3-  (\alpha_1-\alpha_2)^2 \pm  (\alpha_1-\alpha_2) \sqrt{\mathrm Q} \right]. 
\end{equation}

[Lem l:300.3.7 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] For each $k \geq 1$ there exists a measure $\nu_k$ on $\mathbb{R}^{{\rm Q}(k)}$ with Radon marginals such that, for any $M \in (0,\infty)$,  
\begin{multline}

\lim_{n \to \infty} \sup_{{\rm X}_{n,k}}
 \sup_{(f_{k,x})_{x \in {\rm X}_{n,k}}} \bigg| \mathbb{E} \exp \Big(-\sum_{x \in {\rm X}_{n,k}} f_{k,x} \big(h_n({\rm Q}(x;k))\big) \Big)  \\
- \exp \Big(- \tfrac{1}{\sqrt{n}} \sum_{x \in {\rm X}_{n,k}} \int_{\mathbb{R}^{{\rm Q}(k)}} \big(1-{\rm e}^{-f_{k,x}(\sigma)}\big) \nu_k({\rm d} \sigma) \Big) \bigg| = 0 \,,
\end{multline} 
where the first supremum is taken over all sets ${\rm X}_{n,k} \subset {\rm D}_n$ such that
$\log \|x-x'\| > n-r_n-M$ for all $x \neq x' \in {\rm X}_{n,k}$ and the second is over all families $(f_{k,x}: x \in {\rm X}_{n,k})$ of measurable positive functions on $\mathbb{R}^{{\rm Q}(k)}$ satisfying
\begin{equation}

\|f_{k,x}\|_\infty \leq M 
\quad ; \quad
{\rm supp}\big(f_{k,x}\big) \subseteq \big\{ \sigma \in \mathbb{R}^{{\rm Q}(k)} :\:
\min_{x \in {\rm Q}(k)} |\sigma(x)| \leq M \big\} \,.
\end{equation}

