[Proposition 16 (Deterministic control of the shifted distances) of arXiv:2605.24937, '2605.24937'] Let $L\in[\tfrac12,2]$, $\overline a_0,\overline a_1\ge0$, and $\bar N := N\wedge 1/(1-L)_{+}$.
There exists a sequence
$(\eta_n)_{n=0}^{N-2}\subset[0,1]$ with $\eta_{N-1}=1$ such that any
nonnegative sequence $(d_n)_{n=0}^{N-1}$
satisfying~\eqref{eq:dn-recursion} and $d_0=\W(\mu,\nu)$ obeys
\begin{align}
  d_{N-1}^{\,2}
  &\;\lesssim\;
  \tfrac{L^{-1}-1}{L^{-N}-1}\,d_0^{\,2}
  +\bigl(((L-1)N)\vee\log\bar N\bigr)\,\overline a_0^{\,2}
  +\bar N\,\overline a_1^{\,2},
  \\[2pt]
  \sum_{n=0}^{N-2}\eta_n^{2}\,d_n^{\,2}
  &\;\lesssim\;
  \tfrac{L^{-1}-1}{L^{-N}-1}\,d_0^{\,2}
  +\bigl(((L-1)N)\vee\log\bar N\bigr)\,\overline a_0^{\,2}
  +\bar N\,\overline a_1^{\,2}.

\end{align}

[Proposition prop:FG-restricted-barycenter of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] For \(\mathbb{Y}=\mathbb{G}^{b,M}\in\mathcal{FG}(T,d)\),
\begin{equation}

\sum_{k=1}^K\lambda_k\mathcal{AW}_2^2(\mathbb{X}^k,\mathbb{Y})
=
\sum_{k=1}^K\lambda_k\|a^k-b\|_2^2+
\sum_{t=1}^T\sum_{k=1}^K\lambda_k\mathrm{dist}_{\mathrm{BW}}^2(L_{\cdot,t}^k(L_{\cdot,t}^k)^\intercal,M_{\cdot,t}M_{\cdot,t}^\intercal).
\end{equation}
Consequently,
\begin{equation}

\inf_{\mathbb{Y}\in\mathcal{FG}}\sum_{k=1}^K\lambda_k\mathcal{AW}_2^2(\mathbb{X}^k,\mathbb{Y})
=
\sum_{k=1}^K\lambda_k\|a^k-\overline a\|_2^2+
\sum_{t=1}^T\min_{\substack{\mathbf P_t\in\mathscr{P}_+(K,d)\\ \rank(\mathbf P_t)=d}}\Phi_t(\mathbf P_t).
\end{equation}
Equivalently, the second sum on the right-hand side of (equation eq:restricted.value of the paper) is the infimum of the global trace functional \(\Phi(\mathbf P)\) over those \(\mathbf P\in\mathscr{P}_+(K,T,d)\) whose one-step blocks satisfy \(\rank(\mathbf P_t)=d\) for every \(t\).
In the language of Theorem~(thm:explicit.value of the paper), the restricted problem amounts to imposing the rank constraint \(\rank(\Sigma)\le d\) in the local Bures--Wasserstein barycenter problems (equation eq:local.BW.barycenter.identity of the paper).
For fixed \(t\), the local rank-\(d\) infimum admits the equivalent factor form
\begin{equation}

\min_{\substack{\mathbf P_t\in\mathscr{P}_+(K,d)\\ \rank(\mathbf P_t)=d}}\Phi_t(\mathbf P_t)
=
\inf_{ Q^1,\ldots,Q^K\in\mathscr O(d)}
\left\{
\sum_{k=1}^K\lambda_k\|L_{\cdot,t}^k\|_F^2-
\left\|\sum_{k=1}^K\lambda_kL_{\cdot,t}^k Q^k\right\|_F^2
\right\}.
\end{equation}
For fixed \( Q^1,\ldots, Q^K\), the minimizing block-column is
\begin{equation}

Y_t=\sum_{k=1}^K\lambda_kL_{\cdot,t}^k Q^k.
\end{equation}

