[Theorem thm:ulmc_cvx of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Let $\hat{\boldsymbol{P}}$ denote the kernel for~(eq:ULMC of the paper), and let $\boldsymbol{P}$ denote the kernel for~(eq:ULD of the paper) run for time $h$.
    Assume that $0 \preceq \alpha I \preceq \nabla^2 V \preceq \beta I$ and set $\gamma = \sqrt{32\beta}$.
    Write $W^2 \coloneqq \mathcal{W}_2^2(\bs\mu,\bs\pi)$, where $\mathcal{W}_2$ denotes the $2$-Wasserstein distance in the twisted norm $(x,p) \mapsto \sqrt{\norm x^2 + \gamma_0^{-2}\,\norm p^2}$.
    \begin{enumerate}
        \item \underline{$\alpha > 0$ case:} If $\varepsilon \in (0, \frac{d^{1/2}}{\kappa^{1/2}}]$ and $h = \Theta( \frac{\varepsilon}{\beta^{1/2} \kappa^{1/2} d^{1/2}})$, then $\KL(\bs\mu \hat{\boldsymbol{P}}{}^N \mathbin{\|} \bs\pi) \leqslant \varepsilon^2$ for all
        \begin{align*}
            N \gtrsim \frac{\kappa^{3/2} d^{1/2}}{\varepsilon} \log \frac{\alpha W^2}{\varepsilon^2}\,.
        \end{align*}

        \item \underline{$\alpha = 0$ case:} If $\varepsilon\in  (0,\beta^{1/2} W]$ and $h = \Theta(\frac{\varepsilon^2}{\beta d^{1/2} W + \beta^{3/2} W^2})$, then $\KL(\bs\mu\hat{\boldsymbol{P}}{}^N \mathbin{\|} \bs\pi) \leqslant \varepsilon^2$ for
        \begin{align*}
            N \asymp \frac{\beta^{3/2} d^{1/2} W^3 + \beta^2 W^4}{\varepsilon^4}\,.
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $H\in(0,1)$ and let $(x_t)_{t\geq 0}$ be a stationary solution to \eqref{eq:fast system simplified} in the setting \nameref{S1}. Then, we get for all $\omega\in\R$
    \begin{align}
        S_x(\omega) &= \sigma^2\Gamma(2H+1)\sin(\pi H) \frac{|\omega|^{1-2H}}{A(\lambda)^2 + \omega^2}\nonumber \\
        &=\sigma^2C_H \frac{|\omega|^{1-2H}}{A(\lambda)^2 + \omega^2}.
    \end{align}

