[Corollary cor:variance-bounds of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Assume $\lambda_2 > \lambda_3$. Then for any $k \ge 0$,
\begin{equation}
\alpha_2(k) (1 - \alpha_2(k)) (\lambda_2^2 - \lambda_3^2)^2
\;\le\; \widehat{V}_k
\;\le\; (1 - \alpha_2(k)) \lambda_2^4.
\end{equation}
Equivalently, when $\alpha_2(k) \ge 1/2$,
\begin{equation}
1 - \alpha_2(k) \;\le\; \frac{2 \widehat{V}_k}{(\lambda_2^2 - \lambda_3^2)^2}.
\end{equation}

[Lemma 14 (Weighted transitions) of arXiv:2608.30304, '2608.30304'] Let $a,b\ge-\tfrac12$, $n\ge1$ and $-1<x<1$. Then
\begin{align}
F_{n,a,b}(x)&\le A^L_{n,a,b}\,F_{n-1,a,b+2}(x)
+B^L_{n,a,b}\,(1+x)^{-1/2}F_{n-1,a,b+1}(x),\\
F_{n,a,b}(x)&\le A^R_{n,a,b}\,F_{n-1,a+2,b}(x)
+B^R_{n,a,b}\,(1-x)^{-1/2}F_{n-1,a+1,b}(x),
\end{align}
where
\begin{equation}
\begin{aligned}
(A^L_{n,a,b})^2&=\frac{(n+a+b+1)(n+b+1)}{n(n+a)},\\
(B^L_{n,a,b})^2&=\frac{(b+1)^2}{n^2}\cdot
\frac{2n(2n+a+b+1)}{(2n+a+b)(n+a)},
\end{aligned}
\end{equation}
and
\begin{equation}
\begin{aligned}
(A^R_{n,a,b})^2&=\frac{(n+a+b+1)(n+a+1)}{n(n+b)},\\
(B^R_{n,a,b})^2&=\frac{(a+1)^2}{n^2}\cdot
\frac{2n(2n+a+b+1)}{(2n+a+b)(n+b)}.
\end{aligned}
\end{equation}

[Theorem thm:muckenhoupt_maximal of arXiv:2505.14012, 'Ergodicity for stochastic neural field equations'] If $\rho\in A_2$, then there exists a constant $C(d)>0$ such that for $u\in L^2(\mathbb{R}^d,\rho)$,
\begin{align*}
\|\mathfrak{M}(u)\|_{L^2(\mathbb{R}^d,\rho)}\leq C(d)[\rho]_{A_2}\|u\|_{L^2(\mathbb{R}^d,\rho)},
\end{align*}
where $\mathfrak{M}$ denotes the \emph{Hardy-Littlewood maximal} function given by
\begin{equation}
\mathfrak{M}(u)(x): = \sup_{x\in B,\;B\;\textup{ball}}\frac{1}{|B|}\int_{\mathbb{R}^d}|u(y)|\, dy,\quad x\in\mathbb{R}^d.
\end{equation}

