[Lemma lem-CondRW of arXiv:2504.20963, 'Exponential moments of truncated branching random walk martingales'] Let $(S_{n}^+)$ denote the Doob $h$-transform of the  $(S_{n})$ and  $(Q_{n})$ be a random sequence such that for all non-negative, measurable function $f$,
  \begin{equation}
     \mathbf{E} \left[ f(  S^+_{n+1}, Q_{n+1} ) | (S^+_{j}, Q_{j}), 1 \leq j \leq n\right] =  \mathbf{E}_{x} [ f(S^{+}_1,Q_{1})]|_{x= S_{n}}.
  \end{equation} 
  If  there is $ \delta >0$ and $C_{\delta}>0$ such that 
  \begin{equation}
         \mathbf{E}_{x}[ e^{  \delta Q_{1} } ] \leq  e^{C_{\delta}}  \ , \ \forall \, x \geq 0 . 
  \end{equation}  
  Then there exists $ \epsilon >0$   such that 
  \begin{equation}
   \sup_{x \ge 0} \mathbf{E}_{x} \left[ \exp \left(   \epsilon  \sum_{k=0}^{\infty} R( S^{+}_{k} )e^{- S^{+} _{k} } Q_{k+1}\right) \right] \le 2. \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 33 of arXiv:2609.03976, '2609.03976'] We define the Fischer pairing as follows.
	\begin{flalign*}
		\langle \cdot, \cdot \rangle: \mathbb{C}[x_{1},...,x_{n}] \times \mathbb{C}[x_{1},...,x_{n}] &\rightarrow \mathbb{C}  \\
		(f(x),g(x)) &\mapsto f(\partial) \cdot g(x)|_{x=0},
	\end{flalign*}
	where $f(\partial)$ denotes the differential operator obtained by replacing every $x_{i}$ with the corresponding $\partial_{i}$.

[Lemma 43 of arXiv:2511.13559, 'Asymptotic analysis of rare events in high dimensions'] Let $f$ be a function on $\br^d$ and $h(x) = f(x) -f(0_d)-\nabla f(0_d)^\top x - \frac12x^\top\nabla^2f(0_d)x$. Let $X\sim \mathcal N(0_d, (\la H)^{-1})$ and $\us = \us(R\e)$. Let $f_3 = \|\nabla^3f(0_d)\|_H$ and $f_4=\sup_{x\in\us}\|\nabla^4f(x)\|_H$. Then 
\begin{align}
\la\E[h(X)^2\ind\{X\in\us\}]^{1/2} &\les f_3\frac{d}{\sqrt\la} + f_4\frac{d^2}{\la},
\end{align} Now, suppose that  $R$ is large enough that $\mathbb P(\|Z\|\leq R\sqrt d)\geq1/2$, and 
\be
(f_3^2+f_4)\frac{d^2}{\la}\leq \Cf.\ee Then
\begin{align}
\E[\exp(\la h(X))\ind\{X\in\us\}]&\leq C(R, \Cf).
\end{align}

[Lem uniftotallybounded of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $\delta>0$. Let $N^p_n(\delta,m,Q)$ be the minimum number of $\delta$-balls in the metric $d^{{\mathrm {path}}}_{Q,n}$ needed to cover $\mathcal{X}^{(m)}_{Q,n}$. Let $N'(\delta)$ denote some integer-valued function of $\delta$. Let $E_n(N')$ be the event that for all $\delta>0$, $m\in\mathbf N$, and $Q\in\mathcal{Q}$, we have $N^p_n(\delta,m,Q)\leq N'(\delta)$. Then for all $\varepsilon>0$, there exists a function $N'_{\varepsilon}$ such that for all $n$,
\begin{equation}
\mathbf{P}(E_n(N'_{\varepsilon}))>1-\varepsilon.
\end{equation}

[Cor vartheta expansion and analysis of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] There is a $C=C(T,k)>0$ such that on a set $A_k$ with $\mathbb{P}(A_k)>1-c(T,k)n^{-2}$ the following holds.
    \begin{enumerate}
        \item For any deterministic unit vector $v \in V_{k}=\mathrm{Span}(\{e_j\}_{j=1}^k)$ and $x(t) \in \{\vartheta_j(t)\}_{j\leq k} \cup\{M(t)^{j_1}e_{j_2+2}\}_{0 \leq j_1 \leq k, 0 \leq j_2 \leq k-1}$
    \begin{equation}
        \sup_{t \in [0,T]} |\langle x(t),v \rangle| \leq \frac{C\log(n)^k}{\sqrt{n}}.

    \end{equation}
    In particular, the inequality also holds for $x(t)=\vartheta_j(t)$ for $j=1,\dots ,k$.
    \item For $j, \ell =0,1,\dots,k$,
    \begin{equation}
        \sup_{t \in [0,T]} |\vartheta_j(t)^T\vartheta_{\ell}(t)-\delta_{j,\ell}| \leq \frac{C\log(n)}{\sqrt{n}}.

    \end{equation}
    \item For $j, \ell =0,1,\dots ,k$, we have
    \begin{equation}
        \begin{split}
            ~&\vartheta_j(t)=(c_j(t)+\mu_j(t))\theta_j(t)+\\
            &\bigg( \vartheta_j(t)^T\frac{\theta_{j-1}(t)}{\|\theta_{j-1}(t)\|^2}-c_j(t)\theta_j(t)^T\theta_{j-1}(t)+\tilde{\mu}_j(t)\bigg)\theta_{j-1}(t)+\tilde{\epsilon}_{j}(t)
        \end{split}
    \end{equation}
     with $c_j(t):=\frac{1}{\|\theta_{j-1}(t)\|}$, $\tilde{\epsilon}_{j}(t) \in \Theta_{j-2}(t)+ \mathcal{E}_j(t)$, $\sup_{t \in [0,T]}||\tilde{\epsilon}_{j}(t)|| \leq C_{k,T} \frac{\log(n)^{k}}{\sqrt{n}}$, and $\sup_{t \in [0,T]} (|\mu_j(t)|+|\tilde{\mu}_j(t)|) \leq C_{k,T}\frac{\log(n)^{2(k-1)}}{n}$.
    \end{enumerate}

