[Lemma E[deg-edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e = \delta\in O(1)$ and
\begin{enumerate}
    \item $\mathds{E}[d_U^{\delta}] \in o(n)$
    \item $\exists c>0: \lim_{n \rightarrow \infty} \mathds{P}(d_U \geq 1) \geq c$
\end{enumerate}
then 
\begin{align*}
    \mathds{E}[DH_n] =  \frac{\delta-1}{\delta} \frac{\delta \mathds{E}[d_U^2] - 2 \mathds{E}[d_U]}{2 \mathds{E}[d_U]} (1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition WW of arXiv:2411.05204, '\Large\bf Sample Path Properties of the Fractional Wiener--Weierstrass Bridge'] ([schied2024weierstrass]) For $\alpha\in(0,1)$ and $b\in\{2,3,\dots\}$, the stochastic process
\begin{equation}
Y(t)=Y_{\alpha,b,H}(t):=
\sum_{n=0}^\infty \alpha^nB_H(\fp{b^n t}),\qquad 0\le t\le 1,
\end{equation}
is called the \emph{fractional Wiener--Weierstrass  bridge} with parameters $\alpha$, $b$, and $H$.

[Proposition Hypo_Conseq-B of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] Assume that Hypothesis (Hyp-f-B of the paper) holds. Then
		\begin{align}
			\int_{-\infty}^{\mathfrak{r}} e^{\delta\zeta}\|\boldsymbol{\mathfrak{K}}(\cdot,\zeta)\|^2_{\mathbb{H}^{-1}}\/\mathrm{d}\/ \zeta<\infty, \ \ \text{ for all } \mathfrak{r}\in\mathbb{R},
		\end{align}
		where $\delta$ is the same as in (equation forcing2-B of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2506.18834, '\large\bf On the random-time and finite-time ruin probability for widely dependent claim s'] (1) Under the assumptions of Theorem \ref{thm104} but without requiring conditions (\ref{110}) and $G\in\mathcal{C}$, we have

\begin{eqnarray}
\lim\inf_{t>0}\psi(x;t)E^{-1}N(t)\overline{G}^{-1}(x+ct)\ge1.
\end{eqnarray}

(2) Under the assumptions of Theorem \ref{thm105} but without requiring conditions (\ref{110}) and $G\in\mathcal{C}$,
(\ref{32010}) still holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:moment-identities of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] Let $A=(a_i)$ and $B=(b_i)$ be the spoke and rim labels of a geodesic Leech labeling. Then
\begin{equation}
  (m-2)\sum_i a_i+3\sum_i b_i=\frac{N(N+1)}2,
\end{equation}
\begin{equation}
  \sum_{t\in T(A)}t=3\sum_i b_i,
\end{equation}
and
\begin{equation}
\begin{aligned}
  \frac{N(N+1)(2N+1)}6
  ={}&\left(\sum_i a_i\right)^2
  +(m-3)\sum_i a_i^2
  -2\sum_i a_i a_{i+1}\\
  &+3\sum_i b_i^2
  +2\sum_i b_i b_{i+1}
\end{aligned}
\end{equation}
hold. In particular,
\[
  \sum_{t\in T(A)}t\equiv0\pmod3.
\]

[Lemma 10 of arXiv:2604.17973, 'Schauder estimates and classical solutions of the Dirichlet problem for stochastic parabol'] Let $\alpha\in(0,1)$, let $h\in C^{1+\alpha/2}([0,T];L_\omega^\gamma)$ satisfy
\[
h(0)=0,
\qquad
h'(0)=0,
\]
and let $v$ be the solution of
\begin{equation}
\partial_t v(t,y)=\partial_y^2 v(t,y),
\qquad
v(0,y)=0,
\qquad
v(t,0)=h(t).
\end{equation}
Then
\begin{equation}
|\partial_t v|_{(\alpha,\alpha/2);[0,T]\times\R_+}^{L_\omega^\gamma}
+|\partial_y^2 v|_{(\alpha,\alpha/2);[0,T]\times\R_+}^{L_\omega^\gamma}
\le C\,[h']_{\alpha/2;[0,T]}^{L_\omega^\gamma},
\end{equation}
where $C=C(\alpha,\gamma,T)$. 

Moreover, if $v_1$ and $v_2$ correspond to boundary data $h_1$ and $h_2$, respectively, and if $h_1'(0)=h_2'(0)=0$, then
\begin{equation}
\sup_{(t,y)\in[0,T]\times\R_+}
\E\bigl|\partial_y^2 v_1(t,y)-\partial_y^2 v_2(t,y)\bigr|^\gamma
\le C\sup_{t\in[0,T]}\E\bigl|h_1'(t)-h_2'(t)\bigr|^\gamma.
\end{equation}

[Lemma 23 of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] (Method of stationary phase)
			Let $w(x)$ be a nice function supported on $x\asymp X$, and suppose for all $j\geq 1$ the phase function $\phi(x)$ satisfies, 
			\begin{equation*}
				X^j \partial_x^j \phi(x)\ll Y.
			\end{equation*}
			Now suppose for some $x_0\asymp X$, known as stationary point, we have $\phi^\prime(x_0)=0$ and $X^2\partial_x^2\phi(x)\gg Y$. If $Y\gg R\geq 1$ for some $R$, then for any large $A>0$ we have
			\begin{equation}
				\int_\R w(x)e\left(\phi(x)\right)\, dx = \frac{X}{\sqrt{Y}}e\left(\phi(x_0)+\frac{1}{8}\right)w(x_0)+O_A\left(\frac{X}{R^A}\right).
			\end{equation}

[Definition 27 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] For $V \subset [0,\infty)^n$ closed, define 
\begin{equation} 
   \widetilde{V} = \bigcup_{x \in V} \{x' \in \mathbb{R}^n \ | \ x' \geq' x \}.  
\end{equation}

[Dfn 3. dfn: resistance metrics of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] [{Resistance metric, [Kigami_01_Analysis]}]

  A metric $R$ on a non-empty set $F$ is called a \textit{resistance metric}
  if and only if,
  for any non-empty finite subset $V \subseteq F$,
  there exists an electrical network $G$ with the vertex set $V$ 
  such that the effective resistance on $G$ coincides with $R|_{V \times V}$.

