[Corollary cor:two-sided of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] There are absolute constants $0<c_1<C_1<\infty$ such that
\[
 \mathbb{P}\!\left(
 n^{n/2}e^{-C_1n}
 \leq \abs{\operatorname{Per}(M_n)}
 \leq n^{n/2}e^{-c_1n}
 \right)=1-o(1).
\]

[Corollary 13 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Let $\alpha>0$. Then
\[
\begin{aligned}
&\mathbb P\!\left(
M_T^-<\alpha,\,
H_I<H_S
\right)
\\[1mm]
&=
\int_0^\alpha
\frac{
\left[
\gamma W^{(\gamma)}(r)
-
\bigl(Z^{(\gamma)}(r)-1\bigr)
\dfrac{W^{(\gamma)\prime}(r)}
{W^{(\gamma)}(r)}
\right]^2
}{
\gamma W^{(\gamma)}(r)
}\,dr
+
\frac{
\left[
\gamma W^{(\gamma)}(\alpha)
-
\bigl(Z^{(\gamma)}(\alpha)-1\bigr)
\dfrac{W^{(\gamma)\prime}(\alpha)}
{W^{(\gamma)}(\alpha)}
\right]^2
}{
\gamma W^{(\gamma)\prime}(\alpha)
},~\alpha>0.
\end{aligned}
\]

[Lemma lem::cvg_proba_aux1 of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Let $\mathbf{Q}$ be a partition of $\{1,2,\ldots,n\}$ that contains no singletons. Then, for any $\epsilon>0$ with 
	\begin{equation*}
		\epsilon<\frac{\min \{\min_{j\neq k}|z_j-z_k|,\min_{1\leq j\leq n}d(\Omega ,z_j)\}}{100},
	\end{equation*}
we have the convergence
\begin{equation} 
	\lim_{a \to 0}\frac{\mathbb{P}^a\left[G(\mathbf{Q};z_1^a,\ldots,z_{n}^a)\right]}{\mathbb{P}^a\left[z_i^a\longleftrightarrow \partial B_{\epsilon}(z_j^a), \enspace 1\leq j\leq n\right]}=\mathbb{P}\left[G(\mathbf{Q};z_1,\ldots,z_n) | z_j\longleftrightarrow \partial B_{\epsilon}(z_j),\enspace 1\leq j\leq n\right],
\end{equation}
where  the right hand side of~(equation eqn::cvg_proba_aux1 of the paper), which belongs to $(0,\infty)$, can be defined in terms of conditional crossing probabilities as in~(equation eqn::def_lemaux1_aux1 of the paper) and~(equation eqn::def_lemaux1_aux2 of the paper) below for $\mathbf{Q}_n=(\{1,2,\ldots,n\})$, and in~(equation eqn::P_def_4 of the paper) below for $\mathbf{Q}=(\{1,2\},\{3,4\})$. For general $\mathbf{Q}$, the quantity 
\[\mathbb{P}\left[G(\mathbf{Q};z_1,\ldots,z_n) | z_j\longleftrightarrow \partial B_{\epsilon}(z_j),\enspace 1\leq j
\leq n\right]\]
 can be defined analogously. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] Suppose that $u:\Z^d\to \R$ and $f:\Z^d\to \R^d$ are related on $\Z^d$ via
\begin{equation}
-\nabla^*\cdot A\nabla u=\nabla^*\cdot f.
\end{equation}
There exists $\beta>1$ depending only on $\Lambda$ such that for any $p\in[1,\beta]$ and any ball $B$, we have almost surely
\begin{equation}
\fint_{x\in B}\Big(\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u\Big)^{p}\,\lesssim \,\fint_{x\in 2B}\Big(\fint_{B_{\di}(x)}A^{-1} f\cdot f\Big)^{p}+\Big(\fint_{x\in 2B}\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u \Big)^{p}.
\end{equation}
Furthermore, the following elliptic regularity estimates hold:
\begin{enumerate}
\item
(Global quenched Meyers' estimates) For $p\in[1,\beta]$,
\begin{equation}
\int_{x\in \ZZ^d}\Big(\fint_{B_{\di}(x)}A\nabla u\cdot\nabla u\Big)^{p}\,\lesssim  \,\int_{x\in \ZZ^d}\Big(\fint_{B_{\di}(x)}A^{-1} f\cdot f\Big)^{p}.
\end{equation}
\item
(Large-scale hole-filling estimates) For $\rd(x)\le r\le R$, if $f\equiv0$ in $B_R(x)$, then 
\begin{equation}
\int_{ B_r (x) }A\nabla u\cdot \nabla u\,\lesssim \, \Big(\frac rR\Big)^{\frac d{\beta'}}\int_{B_{R} (x) } A\nabla u\cdot \nabla u.
\end{equation}
Here we recall that $\beta':=\frac\beta{\beta-1}$ is the H\"older conjugate of $\beta$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

