[Corollary 27 (Central-area directions) of arXiv:2608.06393, 'Intrinsic Tangential Hadamard Differentiability of Rough-BSDE Solution Maps'] For $a\in\mathcal V_0^q(\mathfrak{so}(E))$, define
\begin{equation}
 \chi_{\mathbf x}^{\mathrm{area}}(a)
 :=(1,x,\mathbb x+a).
\end{equation}
The pullback
$\mathcal S\circ\chi_{\mathbf x}^{\mathrm{area}}$ is Fr\'echet
differentiable at zero, and
\begin{equation}
 D(\mathcal S\circ\chi_{\mathbf x}^{\mathrm{area}})(0)[a]
 =A_{\mathbf x}(0,a).
\end{equation}

[Lemma 2602021059 of arXiv:2609.02626, 'Comparison principles and symmetry for subquadratic fractional $p$-Laplacian equations'] Let $N\ge 1$, $s\in (0, 1)$, $1<p<2$, and $u\in \widetilde{W}^{s,p}(U)\cap\widetilde{W}^{s,p}(\mathcal{T}(U))\cap  L^{\infty}(\mathbb{R}^N)$ where $U\subset  \mathbb{R}_+^N$ is a bounded open set.  If $w=u-u^*\ge 0$ a.e. in $\mathbb{R}^N_+\backslash U$, there holds 
\begin{equation}
\begin{aligned}
&\quad \int_{\mathbb{R}^{N}\times \mathbb{R}^{N}}\frac{(J_{u}(x, y)-J_{u^*}(x, y))\left(w_-(x){\mathbbm 1}_{U}(x)-w_-(y){\mathbbm 1}_{U}(y)\right)}{|x-y|^{N+sp}}{\rm d}x{\rm d}y\\
&\le-2^{p-1}(p-1)\|u\|^{p-2}_{L^\infty(\mathbb{R}^N)}\Big[\int_{A_3}\frac{w_-^2(x)}{|x-y|^{N+sp}}{\rm d}x{\rm d}y+\frac12\int_{A_4}\frac{\big|w_-(x)-w_-(y)\big|^2}{|x-y|^{N+sp}}{\rm d}x{\rm d}y\\
&\quad +\int_{A_4}\frac{w_-^2(x)}{|x-y^*|^{N+sp}}{\rm d}x{\rm d}y+\int_{U\times (\mathbb{R}^N_+\backslash U)}\frac{w_-^2(x)}{|x-y|^{N+sp}}{\rm d}x{\rm d}y\Big].\\
\end{aligned}
\end{equation}

[Lemma lem:BinomialSum of arXiv:2410.23915, 'Asymptotic Bounds and Online Algorithms for Average-Case Matrix Discrepancy'] Let $t,n \in \mathbb{N}$ with $t \leq n$. Then
        \begin{equation*}
            \sum_{k=0}^t \binom{n}{k} = \sum_{k=n-t}^n \binom{n}{k} \leq \left(\frac{en}{t}\right)^t.
        \end{equation*}

