body:
[Lemma lem:loop-mass-estimates of arXiv:2607.18070, 'The Brownian loop-catcher'] These estimates hold with
constants independent of the mesh.
\begin{enumerate}
\item For every \(\varepsilon>0\),
\begin{align*}
 \lim_{\eta\downarrow0}\limsup_{\delta\downarrow0}
 m_\delta\{\operatorname{dur}(\ell)\geq\varepsilon,\
       \ell\not\subset D_\eta\}=0,\qquad
 \lim_{\eta\downarrow0}
 m_D\{\operatorname{dur}(\ell)\geq\varepsilon,\
       \ell\not\subset D_\eta\}=0.
\end{align*}
\item If two sets \(A_\delta,B_\delta\subset D^\delta\) have distance at
least \(a>0\), then, for \(\delta<a/8\),
\begin{equation}
 m_\delta\{\operatorname{dur}(\ell)<\varepsilon,\
       \ell\cap A_\delta\ne\varnothing,\ \ell\cap B_\delta\ne\varnothing\}
 \leq \frac C{a^2}e^{-ca^2/\varepsilon}.
\end{equation}
The same bound holds for Brownian loops and two sets at distance \(a\).
\item For \(T\geq1\),
\begin{equation}
 m_\delta\{\operatorname{dur}(\ell)>T\}
 +m_D\{\operatorname{dur}(\ell)>T\}
 \leq C\int_T^\infty t^{-2}e^{-ct}\,\,\mathrm d t .
\end{equation}
\end{enumerate}

[Theorem 7 (Regulated-base product-form representation) of arXiv:2607.24533, 'Colored Markov-Modulated Brownian Motion for Preemptive Workload Stacks'] {Suppose that Assumptions~\ref{assump:intensity}, \ref{assump:stability}, and~\ref{assump:first-moment} hold for the regulated-base model. Then the model admits a stationary probability law.} On the face
$\Theta_{1,c_2,\dots,c_n}$, the stationary density row vector is
\begin{equation}

\vect{\pi}^{\mathrm R}(\bm{x})
=
\vect{\nu}^{\mathrm R}(x_1)
\prod_{r=1}^{n-1}
\Lop{c_r}{c_{r+1}}(x_{c_{r+1}}),
\qquad x_1>0,
\end{equation}
where $c_1=1$ and $\vect{\nu}^{\mathrm R}$ has the form
\eqref{eq:regulated-base-density}, with the direction of
$\vect g_{\mathrm{reg}}$ fixed by the reflecting boundary condition
\eqref{eq:regulated-base-boundary-g}. Because color $1$ is only one component
of the full stack, $\vect{\nu}^{\mathrm{R}}$ is not normalized to integrate
to $1$ on its own. Its scale is fixed jointly with the excursion mass by the
global normalization below. {Thus, $\vect\nu^{\mathrm R}$ is the density on the base face and an anchor for the full stack, not the marginal stationary density of $X_1$ after higher-color faces have been included.}

With
\begin{align*}
\mathfrak{M}^{\mathrm R}
=
\begin{bmatrix}
\vect{0} & \vect{M}^{(2,3)} & \cdots & \vect{M}^{(2,C)}\\
\vect{0} & \vect{0} & \cdots & \vect{M}^{(3,C)}\\
\vdots & \ddots & \ddots & \vdots\\
\vect{0} & \cdots & \vect{0} & \vect{0}
\end{bmatrix},
\end{align*}
$\vect{m}^{\mathrm R}
=
[\vect{M}^{(1,2)},\dots,\vect{M}^{(1,C)}]$,
$\e^{\mathrm R}$ the column vector obtained by stacking $C-1$
copies of $\e$, and $\I^{\mathrm R}$ the identity matrix of the same dimension
as $\mathfrak M^{\mathrm R}$, the
normalization condition is
\begin{equation}

\int_0^\infty
\vect{\nu}^{\mathrm R}(x)\,\dd x
\left[
\e
+
\vect{m}^{\mathrm R}
(\I^{\mathrm R}-\mathfrak{M}^{\mathrm R})^{-1}
\e^{\mathrm R}
\right]
=
1.
\end{equation}

[Theorem prop: holo generalkernel of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Let $X=(X_t)_{t\in [0,T]}$ be an $S$-valued jump-diffusion with characteristics $(b,a,K)$ and extended generator $\mathcal A$. Fix $\varepsilon>0$ and assume that $b_j,a_{ij},K\in \mathcal O_\varepsilon(S)$.
Suppose that the following conditions hold true.
\begin{enumerate}
\item  for all $z\in {S_\varepsilon}$, $ \int_{\|\xi\|>1} \exp(|\xi_1|+\dots+|\xi_d|) K_\varepsilon(z,d\xi)<\infty;$
    \item the real valued map
$\sum_{|\beta|\geq2}\frac{1}{\beta!}|h_{\mathbf{m}^\beta}(\cdot)|
$
is locally bounded on $P^d_{R(S)+\varepsilon}(0)$.
\end{enumerate}
Fix $G=(G_1,\ldots,G_d)$ such that 
\begin{equation}
    G_j>\sup_{z\in {S_\varepsilon}}\sup_{\xi\in \textup{supp}(K_\varepsilon(z,\cdot))}|z_j|+|\xi_j|,
\end{equation}
and set
\begin{equation}
\begin{aligned}
    \mathcal{V}&\subseteq\{h\in H(P^d_G(0))\ \colon
      (h^{(\beta)})_{|\beta|\geq2} \text{ is locally uniformly bounded on }P^d_G(0)\},
      \\
      \mathcal{V}^*&:=\{\mathbf{u}\in \mathcal{S}^* \colon h_\mathbf{u}=h|_{{P}^d_{R(S)}(0)},  \ h\in \mathcal{V}\}.\\
\end{aligned}
\end{equation}
Then $X$ is an $S$-valued $\mathcal{V}$-holomorphic process and
for all $\mathbf{u}\in\mathcal{V}^*$  
$$\mathcal{A}h_\mathbf{u}=h_{L(\mathbf{u})}|_S,$$
where $L:\mathcal{V}^*\rightarrow \mathcal{S}^*$  is given by
\begin{align}
    L(\mathbf{u})_\alpha=\sum_{|\beta|=1}(\mathbf{u}^{(\beta)}\ast \underline{\mathbf{b}}^{\beta})_\alpha+\sum_{|\beta|=2}\frac{1}{\beta!}(\mathbf{u}^{(\beta)}\ast (\underline{\underline{\mathbf{a}}}^{\beta}+\mathbf{m}^{\beta}))_\alpha+\sum_{|\beta|\geq 3}\frac{1}{\beta!}(\mathbf{u}^{(\beta)}\ast \mathbf{m}^{\beta})_\alpha,
\end{align}
for all $\mathbf{u}\in\mathcal{V}^*$, $\alpha\in\mathbb{N}^d_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 12 of arXiv:2608.29585, '2608.29585'] If $h_k\in\mathscr D$ for all $k$, then, for $0\le m<r$,
