[Lemma lem: spatial mixing of Ising model of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Let $K<N$ be two integers.  Then there exists an absolute constant $c>0$ such that for any event $\mathcal{E}$ supporting on $\Lambda_K$ and any $\xi_1,\xi_2$ be two boundary conditions on $\partial\Lambda_N$, we have \begin{equation}
        \Big|\frac{\mu^{\xi_1}_{\Lambda_N}(\mathcal{E})}{\mu^{\xi_2}_{\Lambda_N}(\mathcal{E})}-1\Big|\le c(\frac{N}{K})^{-\frac{1}{8}}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 58 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] [\cite{Minh:2020regularizedDiv}]

	Let $A$ be a self-adjoint, compact, strictly positive operator on $\Hcal$. Then
	\begin{align}
		\lim_{\gamma \approach 0^{+}}\la x, (A+\gamma I)^{-1}x\ra 
		= \left\{
		\begin{matrix}
			||A^{-1/2}x||^2 & \text{ if } x \in \range(A^{1/2}),
			\\
			\infty & \text{otherwise}.
		\end{matrix}
		\right.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 39 of arXiv:2606.24887, '2606.24887'] Let $ \frac{\Gamma^2}{64 \mathfrak c} \leq d \leq N^{\delta/2}$ and $x\in [N]$, $ T \subset[N]$ be deterministic  such that $x \notin T$ and $\abs{T} \le \ccc    d/ \Gamma^2 $, where $\ccc= \ccc(\delta,\nu)>0$ is the constant given by \cref{lem:roughboundsGT}. Then  
		\begin{align}
			\mathbb{P} \left( T \subset \mathcal{T}_{\varphi/2}^c,\theta =1 \right) &\le  4^{|T|} \ee^{-\frac{\varphi^2d}{2^{12} (\ee\Gamma)^2}|T|} + \mathcal{C}N^{- \nu}  \\
			\mathbb{P} \left( T \subset \left(\mathcal{T}^{\bset{x}}_{ \varphi/2}\right)^c,\theta^{\bset{x}} =1 \right) &\le 4^{|T|} \ee^{-\frac{\varphi^2d}{2^{12} (\ee\Gamma)^2}|T|} + \mathcal{C}N^{- \nu}

		\end{align}
	for all $ \varphi \in [\mathcal C \Gamma^3 \abs{T} d^{-1},1]$.

