[Proposition prop:sum_CL_stable of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] Let $X$ and $Y$ be independent stable random variables such that $X\sim S_\alpha (\sigma_0,\beta_0,\delta_0)$ and $Y\sim S_\alpha(\sigma_1,\beta_1,\delta_1)$ where $\alpha \in (0,2]$, $\beta_i \in [-1,1]$ and $\delta_i \in \mathbb{R}$ and $i\in \{1,2\}.$
\begin{enumerate}
    \item For any $a\neq 0, b\in \mathbb{R}$ we have that
    \begin{align*}
        aX + b \sim \begin{cases}
            S_\alpha \left(|a| \sigma_0, sign(a)\beta_0, a\delta_0 +b\right) &\text{ if } \alpha \neq 1\\
            S_1\left( |a| \sigma_0, sign(a)\beta_0, a \delta_0 + b- \frac{2}{\pi}\beta_0 a \log(|a|)\right) &\text{ if } \alpha=1.
        \end{cases}
    \end{align*}

    \item The sum $X+Y \sim S_\alpha \left(\sigma_1^\alpha + \sigma_2^\alpha, \frac{\beta_0 \sigma_0^\alpha + \beta_1 \sigma_1^\alpha}{\sigma_0^\alpha + \sigma_1^\alpha}, \delta_0 + \delta_1 \right)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

