[Theorem 5 of arXiv:2607.28614, 'Tampered Memory Elephant Random Walk on one-dimensional integer lattice'] Let $S_n$ be a TMERW. 
Let $\mathcal{D}$ be any collection of sets that is not necessarily nested, such that $\frac{\mid D_n \mid }{n} \rightarrow 0, \text{a.s.}$, as $n \to \infty$. Then for $0 \le p<1$,
\begin{equation}

\frac{S_n}{n}\longrightarrow 0, \text{ a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm-singular-limit-PF of arXiv:2605.15742, 'Turbulent stretching of FENE dumbbell polymer model via special stochastic scaling and sin'] Assume that $f_{\tau, 0} \to f_0$ in $H_0$ as $\tau \downarrow 0.$ Then the following  hold.
    \begin{itemize}
        \item $ f_\tau$ converges to 
        $ \rho_0\otimes \mathbf{M}_0$ in $L^2(0,T;H_0)$, 
     where  $\rho_0(x)=\int_D f_0(x,r) dr$ and $f_\tau$ is the unique solution  to (equation limit-PDE-final-NOCUT-V1***** of the paper). Moreover, the following estimate (convergence rate) holds
              \begin{align}
 \int_0^T  \Vert f_{\tau}(t)-\rho_0\otimes \mathbf{M}_0\Vert_{H_0}^2 dt \leq C_P  \xi\tau (\Vert f_{\tau, 0}\Vert_{H_0}^2+\Vert \rho_0 \Vert^2_{L^2(\mathbb{T}^2)})+2T\Vert f_{\tau,0}-f_0\Vert_{H_0}^2.
          \end{align}
          \item Assume that $f_{\tau,0}$ converges to $ \rho_{0}\otimes\mathbf{M}_0$ in $H_0.$ Then,  $ f_\tau$ converges to 
        $ \rho_0\otimes \mathbf{M}_0$ in $C([0,T];H_0)$, 
     where  $\rho_0(x)=\int_D f_0(x,r) dr$. Moreover, the following estimate (convergence rate) holds
     \begin{align}
         \displaystyle\sup_{t\in [0,T]}\Vert f_{\tau}(t)-\rho_0\otimes \mathbf{M}_0\Vert_{H_0}^2 \leq   \Vert f_{\tau,0}- \rho_{0}\otimes\mathbf{M}_0\Vert_{H_0}^2.
     \end{align}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2608.10415, 'Continuous random variables'] We have embeddings of compact quantum spaces, as follows,
$$\xymatrix@R=15mm@C=15mm{
S^{N-1}_{\mathbb R,+}\ar[r]&S^{N-1}_{\mathbb C,+}\\
S^{N-1}_\mathbb R\ar[r]\ar[u]&S^{N-1}_\mathbb C\ar[u]
}$$
and the spaces on top appear as liberations of the spaces on the bottom.

[Lemma 10 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[lemma]{time:compactness_averaging}
        For each $\tau\in(0,1)$ and $0\leq s\leq t\leq T$,
    \begin{align*}
        \|\psi^{\tau}_t-\psi^{\tau}_s\|_{H^{-2}}&\leq  
        K|t-s|^{1/2}\|\psi_0\|
        \left(\int_0^T
        (1+\|A^{\tau}_r\|^4_{L^{\infty}})\,dr\right)^{1/2}
        \quad \mathbb{P}-a.s.
\end{align*}
for some positive non-random constant $K>0$ independent of $\tau,s,t.$

