body:
[Lem graph_averaged_labels_equal_virtual_McShane_Whitney of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $(X,\rho)$ be a metric space, let
$N_0,N_1\in\mathbb{N}_+$, and set $N\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} N_0+N_1$.  Let $
    \mathbb{D}_N
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    ((X_n,Y_n))_{n=1}^{N}
    \in
    (X\times\mathbb{R})^N$, fix $\beta>0$, $q\in[N_1]_+$, and $L>0$.  For each
$i\in[N_1]_+$ and $k\in[N_0]_+$, define
\[
\begin{aligned}
    H_{ik}^{(\beta)}
    & \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \mathbbm{1}_{\{
        \rho(X_{N_0+i},X_k)\le\beta
    \}},
\,\,
    S_k^{(\beta)}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \sum_{i=1}^{N_1}H_{ik}^{(\beta)}
,\,\,
    R_{ik}^{(\beta)}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \sum_{\ell=1}^{i}H_{\ell k}^{(\beta)},
\\
    A_{ik}^{(\beta,q)}
    & \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \mathbbm{1}_{\{S_k^{(\beta)}\ge q\}}
    H_{ik}^{(\beta)}
    \mathbbm{1}_{\{R_{ik}^{(\beta)}\le q\}}
,\,\,
    G^{(\beta,q)}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \frac{1}{q}A^{(\beta,q)}
\\a^{\operatorname{av}}
    & \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    (Y_{N_0+1},\ldots,Y_{N_0+N_1})
,\,\,
\mbox{ and }
    V^{(\beta,q)}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    a^{\operatorname{av}}G^{(\beta,q)}.
\end{aligned}
\]
Let
$
    ((X_k,\overline Y_k))_{k=1}^{N_0}
$
be the output of
Algorithm~(alg:LocalAveragingRobustification of the paper) with inputs
$(\mathbb{D}_N,\beta,q)$.  Then
\begin{equation}

    \overline Y_k
    =
    V_k^{(\beta,q)}
    =
    \left(
        a^{\operatorname{av}}
        G^{(\beta,q)}
    \right)_k
\end{equation}
for every $k\in[N_0]_+$.  Consequently, if
$
    \theta^{(\beta,q,L)}
\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \left(
        \left(
            V_k^{(\beta,q)},X_k,L
        \right)
    \right)_{k=1}^{N_0}
$, then
\begin{equation}

    \hat{f}_{\mathbb{D}_N}^{(\beta,q,L)}(x)
    =
    \hat{f}_{\theta^{(\beta,q,L)}}(x)
\end{equation}
for each $x\in \mathcal{X}$.

[Prop eq:switching of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] For any set of vertices $A\subset D_\delta\backslash \partial D_{\delta}$,
    \begin{equation}
        \mathbb E^+_{\delta, \beta}\left[\prod_{v\in A}\tau_\delta(v)\right] = \mathbf{P}^{\textup{w},\mathrm{DRC}}_{\delta, \beta}\left(\hat{\mathbf{n}}_\delta\in\mathfrak F_A\right)
    \end{equation}
    where $\mathfrak{F}_A$ is the event that every cluster of $\hat\mathbf{n}_\delta$ intersects $A$ (resp. $A\cup\{\partial D_\delta\}$) an even number of times if $|A|$ is even (resp. $|A|$ is odd). The dual statement with free boundary conditions also holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem two-arm-vs-one-arm of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] For every $\varepsilon>0$, there exists $\delta=\delta(\varepsilon)>0$ and $n_0=n_0(\varepsilon)$ such that for all measurable $A\subset Y$ and $n\geq n_0$, we have
\begin{equation*}
    \mu^{\mathcal{H}_\ell}\!\left(\pi(\psi^{-1}(A))^{\delta}\setminus\pi(\psi^{-1}(A^\varepsilon))\right)<\varepsilon ,\qquad \mu_n^{\mathcal{H}_\ell}\!\left(\pi_n(\psi_n^{-1}(A))^\delta\setminus\pi_n(\psi_n^{-1}(A^\varepsilon))\right)<\varepsilon
\end{equation*}

