[Definition def: spine_surface_with_divides of arXiv:2609.00163, 'Decompositions and diagrams of symplectic surfaces in Weinstein domains'] A {\it spine} is a tuple $(H_1,\cdots, H_n;\tau_1,\cdots, \tau_n)$, of contact handlebodies $H_i$ and braids $\tau_i$ in the corresponding half-open book structure on $H_i$, such that 
\begin{itemize}
    \item each consecutive union $H_i\cup \bar H_{i-1}$, $i=2,\dots, n$, is a  connected sum of $S^1\times S^2$'s, and the induced contact structure is its standard tight contact structure;
    \item the induced contact structure on $H_1\cup \bar H_n$ is also tight;
    \item $(H_i,\tau_i)\cup (\bar H_{i-1},\bar \tau_{i-1})$ forms a braided max-$sl$  unlink in a the open book structure on $H_i\cup \bar H_{i-1}$ determined by the half-open book structures on $H_i$ and $H_{i-1}$; 
    \item $(\Sigma,\{p_1,\dots,p_{2b}\})=\cap_{i=1}^n (H_i,\tau_i)$ is a surface  with $2b$ marked points; and
    \item the contact structure on each $H_i$ induces the same dividing set on $\Sigma$.
\end{itemize}

[Definition def:weak-neg-assoc of arXiv:2602.21315, 'The Instability of all Backoff Protocols\thanks{For the purpose of Open Access, the author'] We say that a family of random variables $Z_1, \dots, Z_n$ is \emph{negatively associated} if for all tuples $A_1$ and $A_2$ whose elements lie in $\{Z_1,\dots,Z_n\}$ and are mutually distinct, and all real non-decreasing functions $f_1,f_2$ on those tuples,
    \begin{equation*}
        \mathbb{E}\big(f_1(A_1)f_2(A_2)\big) \le \mathbb{E}(f_1(A_1))\mathbb{E}(f_2(A_2)).
    \end{equation*}

[Lemma lem:CT-TASEP-propagator of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The propagator $B_{\mathbf{a},\mathbf{n}}$ satisfies:
\begin{enumerate}[label=\textup{(\roman*)},
leftmargin=*]
\item For all $i > j$ and $r, r' \in \mathbb{Z}$,
\begin{equation}
[B_{\mathbf{a}+\mathbf{1},\mathbf{n}}]_{ij}(r{+}1, r'{+}1)
= [B_{\mathbf{a},\mathbf{n}}]_{ij}(r, r').
\end{equation}

\item For all $i > j$ and $r, r' \in \mathbb{Z}$,
\begin{align}
[B_{\mathbf{a}+\mathbf{1},\mathbf{n}}]_{ij}(r, r')
- [B_{\mathbf{a},\mathbf{n}}]_{ij}(r, r')
= \sum_{j < \mu < i}
[B_{\mathbf{a},\mathbf{n}}]_{i\mu}(r, a_\mu{+}1)
[B_{\mathbf{a}+\mathbf{1},\mathbf{n}}]_{\mu j}
(a_\mu{+}1, r').
\end{align}

\item The propagator is $t$-independent and
invariant under uniform shifts of the particle
labels: replacing each $n_i$ by $n_i + 1$ leaves
$[B_{\mathbf{a},\mathbf{n}}]_{ij}(r, r')$ unchanged.
\end{enumerate}

[Theorem 31 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Let the following objects be given:
	\begin{itemize}
        \item $\cU$ and $\cV$ Hilbert bases of Hilbert spaces $H_{\cU}$ and $H_{\cV}$,
		\item $Z^N = (Z_i^N)_{1\leq i\leq d}$ deterministic matrices of size $N$,
		\item $X^N = (X_e^N)_{e\in U}$ independent GUE random matrices of size $N$,
		\item $x^i = (x_e^i)_{e\in \cU}$, $y^i = (y_e^i)_{e\in \cV}$ free semicircular variables,
		\item $f\in \cL^{k}\left(\cB\right)$ where $\cB$ is a basis of $\C^d\oplus H_{\cU}\oplus H_{\cV}$,
        \item $K$ such that $\norm{f}_{\cL^k,K}<\infty$.
	\end{itemize}

	\noindent Then if our weights satisfy Assumption \ref{Assum:weight}, there exist a function $g\in \cL^{k-4}\left(\widetilde{\cB}\right)$, where $\widetilde{\cB}$ is a basis of $\C^d\oplus H_{\cU}^{\oplus 6} \otimes H_{\cV}^{\oplus 7}$, such that for $N>2K$,
	\begin{align}

		\E\left[ \tau_N\Big(f\left(Z^N,X^N,y^0\right)\Big| \M_N(\C)\Big)\right] = &\ \tau_N\Big( f\left(Z^N,x^0,y^0\right)\Big| \M_N(\C)\Big) \\
        &+ \frac{1}{N^{2}} \E\left[ \tau_N\Big(g\left(Z^N,X^N,x^1,\dots,x^6,y^1,\dots,y^6\right)\Big| \M_N(\C)\Big)\right], \nonumber
	\end{align}
    where $\tau_N(\ \cdot\ | \M_N(\C))$ is the noncommutative conditional expectation on $\M_N(\C)$. Besides, there exists a constant $C_k$ such that for any $R>0$,
    \begin{equation}

        \norm{g}_{\cC^{k-4},R} \leq C_k \norm{f}_{\cC^k,R}.
    \end{equation}

[Definition 1 of arXiv:2608.23462, '2608.23462'] Let $p \geq 2$ and $\beta > 0$. We say that the fast variable $(Y_t)_{t \ge 0}$ is \emph{$p$-dissipative (with constant $\beta$)}, if for all $x\in \R^{d_1}$ and $y_1,y_2 \in \R^{d_2}$
\begin{align*}
    \langle y_1 - y_2, g(x,y_1)-g(x,y_2) \rangle + \frac{p-1}{2} |\sigma(x,y_1)-\sigma(x,y_2)|_F^2 \leq -\beta|y_1-y_2|^2.
\end{align*}

[Definition def:gibbslaw of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Let $\Omega(m,y)$ be the set of all functions $B : \llbracket 0,m\rrbracket \to \mathbb{Z}$ satisfying  $B(m) =y$  and
    $B(j+1) \ge B(j)$ for $j\in \llbracket 0,m-1\rrbracket$.  For $p\in (0,1)$ we define the \textit{reversed geometric random walk law} $\mathbb{P}_{\mathrm{Geom};p}^{m,y}$ to be the measure on $\Omega(m,y)$ such that  
\begin{align*}
    \mathbb{P}_{\mathrm{Geom};p}^{m,y}(Q = B) \propto p^{-B(0)},
\end{align*}
where $Q$ denotes a $\Omega(m,y)$-valued random variable with this law. 

    Let $\Omega_{\mathrm{Inter}}(m,(y_1,y_2))$ be the set of all functions $(B_1,B_2) \in \Omega(m,y_1)\times \Omega(m,y_2)$ satisfying 
    $B_1(j) \ge B_2(j+1)$ for  $j\in \llbracket 0,m-1\rrbracket$. For $q\in (0,1)$ and $c\in [0,q^{-1})$ we define the \textit{interlacing Gibbs law} $\mathbb P_{\mathrm{Inter};q,c}^{m,(y_1,y_2)}$ to be the measure on $\Omega_{\mathrm{Inter}}(m,(y_1,y_2))$ such that
\begin{align}
  \mathbb P_{\mathrm{Inter};q,c}^{m,(y_1,y_2)}(Q_1 = B_1,Q_2 = B_2) \propto   c^{B_1(0)-B_2(0)}q^{-B_1(0)-B_2(0)},
\end{align}
where $(Q_1,Q_2)$ denotes a  $\Omega_{\mathrm{Inter}}(m,(y_1,y_2))$-valued random variable with this law.

[Defprop gamma fct of arXiv:2609.02409, 'Membranes and Maps'] The power series
    \begin{equation}
        \gamfct{x}{u}
        =
        \exp\bigg(
            \sum_{k>0}
                \frac{B_{2k}}{2k \, (2k+1)!} \,
                B_{2k+1}(x) \,
                u^{2k}
        \bigg) \,.
    \end{equation}
    is the unique element of $\bQ[x]\llbracket u \rrbracket$ satisfying
    \begin{equation}

        \gamfct{x+1}{u}
        =
        \cS(u x) \, \gamfct{x}{u} \,,
        \qquad
        \gamfct{0}{u}
        =
        1 \,.
    \end{equation}
    Here, $B_k(x)$ denotes the Bernoulli polynomial $\frac{t \mathrm{e}^{x t}}{\mathrm{e}^{t}-1} \eqqcolon \sum_{k\geq 0} \frac{B_k(x)}{k!} t^k $, and $B_k \coloneqq B_k(0)$ denotes the Bernoulli number.

