[Lemma lem:approx_psi_phi of arXiv:2605.07832, 'A Bismut -Elworthy formula for BSDEs with degenerate noise'] Let $\psi$ and $\phi$ satisfy Hypothesis (ip-psiphi-li of the paper). Hence, there exist sequences $(\psi_n)$ and $(\phi_n)$ such that
\begin{enumerate}[\rm(i)]
\item for every $n\in\mathbb N$ we have $\phi_n\in\mathcal G^{1}(H,\mathbb R)$ and $\psi(t,\cdot,\cdot,\cdot)\in\mathcal G^{1,1,1}(H\times \mathbb R\times U,\mathbb R)$ for every $t\in[0,T]$;
\item for every $n\in\mathbb N$ there exist constants $C_n>0$ and $m_n\geq0$ such that 
\begin{align*}
|\nabla_x\psi_n(t,x,y,z)h|\leq C_n|h|(1+|z|)(1+|x|+|y|)^{m_n}, \qquad |\nabla_x\phi_n(x)h|\leq C_n|h|
\end{align*}
for every $t\in[0,T]$ and every $(x,y,z,h)\in H\times \mathbb R\times U\times H$;
\item there exist positive constants $\widetilde L_\psi$, $\widetilde K_\psi$ and $ \widetilde K_\phi$, which only depend on $L_\psi,K_\psi$, $K_\phi$ and $m$, such that
\begin{align*}
& |\psi_n(t,x,y_1,z_1)-\psi_n(t,x,y_2,z_2)|\leq \widetilde L_\psi(|y_1-y_2|+|z_!-z_2|), \\
& |\psi_n(t,x,0,0)\leq K_\psi(1+|x|^m), \qquad |\phi_n(x)|\leq K_\phi(1+|x|^m)
\end{align*}
for every $n\in\mathbb N$, every $t>0$ and every $(x,y,z)\in H\times \mathbb R\times U$;
\item $(\psi_n)$ and $(\phi_n)$ pointwise converge to $\psi$ and $\phi$, respectively, as $n$ tends to infinity.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm eq:C_ell of arXiv:2604.20629, 'Rates of forgetting for the sequentially Markov coalescent'] Let $(Y_{\ell})_{\ell\ge0}$ denote the SMC process from Definition~(def:smc of the paper).
Let $N_{\ell}$ be a Poisson process of rate $1/4$ independent of $(Y_{\ell})$.
Define
the increasing process,
\begin{equation}
C_{\ell}:=\frac{\ell}{2}+2N_{\ell}
\end{equation}
and the subordinated process $Y'_{\ell}=Y_{C_{\ell}}$. Then $Y'_{\ell}$
is equal in law to the SMC' process defined above.

[Theorem 3 of arXiv:2604.01978, 'Homogenized Transformers'] Fix $d, n\geq2$ and $\upbeta>0$, and assume $\langle x_i(0),x_j(0)\rangle = \gamma_0$ for some $\gamma_0\in(-1/(n-1), 1)$.  For any configuration $(x_1,\ldots,x_n)\in(\S^{d-1})^n$ with $\langle x_i, x_j\rangle=\gamma$ for $i\neq j$, define  
\begin{equation*} 
\pi_{i\to k}^{\bA}(\gamma)
\coloneqq
\frac{e^{\upbeta\langle \bA x_i, x_k \rangle}}
{\sum_{\ell=1}^n e^{\upbeta\langle \bA x_i, x_\ell\rangle}}.
\end{equation*}
Then 
\begin{align} 
f(\gamma)
&\coloneqq \E\,\sum_{k=1}^n \left(\pi_{i\to k}^{\bA}(\gamma)\right)^2,
\nonumber\\
g(\gamma)
&\coloneqq \E\,\sum_{k=1}^n \pi_{i\to k}^{\bA}(\gamma)\,\pi_{j\to k}^{\bA}(\gamma),
\qquad (i\ne j),
\end{align}
are well-defined (i.e. independent of the particular simplex configuration and of the choice of indices),
and satisfy $0\le f(\gamma)\le 1$ and $0\le g(\gamma)\le 1$. Let
\begin{equation}
b(\gamma)
\coloneqq \gamma+(1-\gamma) g(\gamma)
-\gamma\left(\gamma+(1-\gamma) f(\gamma)\right),
\end{equation}
and $\gamma\in C^1(\R_{\geq0})$ be the solution of the Cauchy problem
\begin{equation} 
\begin{cases}
\dot\gamma(t)=b(\gamma(t)) \\
\gamma(0)=\gamma_0.
\end{cases}
\end{equation}
Then there exists $C>0$ such that for every $T>0$ and every $\delta\in(0,1)$, with probability at least $1-\delta$, the solution to \eqref{eq:Diffusive_gaussian_case} satisfies
\begin{equation*}
\sup_{t\in[0,T]}\max_{i\ne j}|\langle x_i(t), x_j(t)\rangle-\gamma(t)|
\le e^{CT} 
\sqrt{\frac{8T}{d} \log\left(\frac{2n^2}{\delta}\right)}.
\end{equation*}
Moreover $C=O(1+d\sigma_{\bA}^{4}\upbeta^{2}n).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theo:existence large a of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] For all $L\in \mathbb{N}$ and $a>200 L$ there exist $q\in (0,1)$ and an isometry-invariant kernel $J$ on $\mathbb{H}_L^1$ satisfying 
	\begin{align*}
		J \sim \frac{a L \log\log(n)}{n^{2}}
	\end{align*}
	such that $\mathbb{P}_{q,J} \left( |K_0| = \infty \right)> 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma7 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A8 of the paper) hold. Then,
\begin{enumerate}[label=(\textbf{\roman*})]
\item For $\lambda \in \Lambda_{\geq}$ of multiplicity $k \in \mathbb{N}$ and fix vectors $a,b \in \mathbb{R}^{k}$, the characteristic $a^{\top} \phi_{\lambda} b$ has c\`adl\`ag paths and satisfies (C1 of the paper)-(C3 of the paper). Moreover, for all $h \in \mathbb{N}_{0}$ and $\varepsilon >0$, 
\begin{align} 
\mathbb{E} \left[ \sum_{i=0}^{h} \sum_{|u|=i} \sup_{|s-t|\leq \varepsilon}|a^{\top}\phi_{\lambda, u}(s-S(u))b| \mathbf{1}_{(-\infty,0)}(s-S(u)) \right] < \infty
\end{align}
\noindent and 
\begin{align} 
\left(\sum_{i=0}^{h} \left( \sum_{|u|=i}|a^{\top}\phi_{\lambda, u}(s-S(u))b|  \right)^{2}\right)_{|s-t|\leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}

\item For $\lambda \in \Lambda$ of multiplicity $k \in \mathbb{N}$ and fix vectors $a,b \in \mathbb{R}^{k}$, the characteristic $a^{\top} \chi_{\lambda} b$ has c\`adl\`ag paths and satisfies (C1 of the paper)-(C3 of the paper). Moreover, for all $h \in \mathbb{N}_{0}$ and $\varepsilon >0$,  
\begin{align} 
\mathbb{E} \left[ \sum_{i=0}^{h} \sum_{|u|=i} \sup_{|s-t|\leq \varepsilon}|a^{\top}\chi_{\lambda, u}(s-S(u))b| \mathbf{1}_{(-\infty,0)}(s-S(u)) \right] < \infty
\end{align}
\noindent and 
\begin{align} 
\left(\sum_{i=0}^{h} \left( \sum_{|u|=i}|a^{\top}\chi_{\lambda, u}(s-S(u))b|  \right)^{2}\right)_{|s-t|\leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}
\end{enumerate}

[Lemma 11 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] We have
  \begin{align}
    \frac{s_{h_{j+1}}^2 -s_{h_j}^2}{\sigma_j^2} &= 1+ O(B_j^{-\delta/4}\cdot (\log B_j)^{1/2}) \quad \text{as $j\to \infty$; and}\\
    s_{h_{M+1}}^2 -\sum_{j=1}^{M}\sigma_j^2 &= O(B_M^{1-\delta/8}\cdot (\log B_M)^{1/2} ) \quad \text{as $M\to \infty$.}
  \end{align}

