[Lemma lem:FP-kernel of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The joint distribution satisfies
\begin{equation}
\mathbb{P}\Bigl(\bigcap_{i=1}^m
\{\mathfrak{h}(t, x_i) \leq a_i\}\Bigr)
= \det(I - K_{t,\mathbf{x},\mathbf{a}})_{L^2(\mathbb{R})},
\end{equation}
where
\begin{equation}
K_{t,\mathbf{x},\mathbf{a}}
= \sum_{1 \leq i \leq j \leq m}
\int_{a_i}^{\infty}
\int_{a_j}^{\infty}
\psi_{t,x_i,z}
[B_{\mathbf{x},\mathbf{a}}]_{ij}(z, w)
\phi_{t,x_j,w}
\mathrm{d} w \mathrm{d} z.
\end{equation}

