[Definition eq:renormalisation_scales of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{def:recursive_tiles}
    Given $\overline{r}_0 \ge r_0 > 0$ and a sequence of positive reals $(m_i)_{i \geq 1}$, we define the \textbf{renormalisation scales} to be the sequence of positive reals $(r_i)_{i \geq 0}$ recursively defined by 

    \begin{equation}

        r_{i + 1} = m_{i + 1} r_i.
    \end{equation}

    We let $(V_i)_{i\geq 0}$ be a sequence of maximal $r_i$-separated nets, where a given net $V_i$ consists of the elements $\{\netvertex{i}{j}\}_{j \geq 0}$, and we let $((\vor{\netvertex{i}{j}})_{j \geq 0})_{i \geq 0}$ be the sequence of Voronoi tilings associated to the nets $(V_i)_{i \geq 0}$. 

    We define a \textbf{level $0$ tile} $\Tile{0}{j} = \tile{0}{\netvertex{0}{j}} = \vor{\netvertex{0}{j}}$ and its associated \textbf{cell} $\Cell{0}{j} = \cell{0}{\netvertex{0}{j}} = B(\netvertex{0}{j}, \overline{r}_0)$. 

    For $i \geq 1$, we define a \textbf{level-$i$ tile} as the union of level-$i-1$ tiles whose centre is contained in $\vor{\netvertex{i}{j}}$,

    \begin{equation}

        \Tile{i}{j}
        =
        \tile{i}{\netvertex{i}{j}}
        =
        \bigcup_{\netvertex{i-1}{k} \in \vor{\netvertex{i}{j}}}
        \tile{i-1}{\netvertex{i-1}{k}},
    \end{equation}

    and its associated \textbf{cell} is similarly defined

    \begin{equation}

        \Cell{i}{j}
        =
        \cell{i}{\netvertex{i}{j}}
        = 
        \bigcup_{\netvertex{i-1}{k} \in \vor{\netvertex{i}{j}}}
        \cell{i-1}{\netvertex{i-1}{k}}.
    \end{equation}

    We say that $\netvertex{i}{j}$ is the \textbf{centre} of $\Tile{i}{j}$ and we call the level $i-1$ tiles in $\Tile{i}{j}$ the \textbf{subtiles} of $T_{i,j}$. 

    Similarly, we say that $\netvertex{i}{j}$ is the \textbf{centre} of $\Cell{i}{j}$ and we call the level $i-1$ cells in $\Cell{i}{j}$ the \textbf{subcells} of $\Cell{i}{j}$.

    We write $\kappa_{i,j}$ for the number of level-$i-1$ net vertices in $\vor{\netvertex{i}{j}}$.

    We define the \textbf{renormalization scheme} associated to the renormalisation scales $(r_i)_{i \geq 0}$ to be the sequence of tilings $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ associated to the sequence of nets $(V_i)_{i \geq 0}$.

[Prop Prop_AdmissibleZ2ZSpinor_LeadingOrderTerm of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] {BeraWalpuski2025}}]

  Let $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Dir} \times \mathbf{Ram}$ and set $Z \coloneq \mathrm{Br}({\mathfrak l})$.
  Choose a local infinitesimal uniformiser as in (Prop_InfinitesimalSliceUniformisers of the paper).
  For every $\Phi \in K^\infty(X{\backslash} Z, S\otimes{\mathfrak l};{\mathbf{p}})$ and $v \in T_{[{\mathfrak l}]}\mathbf{Ram} = \Gamma\paren{Z,NZ}$  
  \begin{equation*}
    \mathscr{L}_{\bar v}^K \Phi \in H_a^\infty\Gamma\paren{X{\backslash} Z, S\otimes{\mathfrak l};{\mathbf{p}}};
  \end{equation*}
  moreover,
  for every $\Phi \in K^\infty(X{\backslash} Z, S\otimes{\mathfrak l};{\mathbf{p}})$
  there is a unique ${\mathbf{L}}_\Phi \in \Gamma\paren{Z,\Hom_\mathbb{A}(\overline{NZ},\check S_{\mathbf{p}})}$
  such that for every $v \in T_{[{\mathfrak l}]}\mathbf{Ram}$
  \begin{equation*}
    \res(\mathscr{L}_{\bar v}^K\Phi) = {\mathbf{L}}_\Phi (v|_Z).
  \end{equation*}

[Lemma 2 of arXiv:2604.24390, 'Weak solutions to distribution-dependent stochastic Volterra equations'] Suppose Assumption~\ref{ass:short}. Let $(X_t)_{t\in [0,T]}$ be an $(\mathcal{F}_t)$-progressively measurable process in $L^1(\Omega\times [0,T];\R^d)$ and $(Z_t)_{t\in [0,T]}$ be an $(\mathcal{F}_t)$-adapted and continuous $d$-dimensional  stochastic process on a filtered probability space $(\Omega,\mathcal{F},(\mathcal{F}_t)_{t\in[0,T]},\P)$ with $Z_0=X_0$ $\P$-a.s. satisfying the usual conditions. If $(\mathcal{M}^f_t)_{t\in[0,T]}$ is a local martingale for every $f\in C_0^2(\R^d)$, then we have:
  \begin{enumerate}
    \item[(i)] $(Z_t)_{t\in[0,T]}$ is a semimartingale with characteristics
    \begin{equation*}
      \bigg(\int_0^{\cdot} b(s,X_s, \mathcal{L}(X_s))\dd s , \int_0^{\cdot}(\sigma \sigma^\top)(s,X_s,\mathcal{L}(X_s))\dd s,0\bigg).
    \end{equation*}
    \item[(ii)] There exists a filtered probability space $(\tilde{\Omega},\tilde{\mathcal{F}},(\tilde{\mathcal{F}}_t)_{t\in[0,T]},\tilde{\P})$ satisfying the usual conditions such that $(Z_t)_{t\in [0,T]}$ is a semimartingale on $(\tilde{\Omega},\tilde{\mathcal{F}},(\tilde{\mathcal{F}}_t)_{t\in[0,T]},\tilde{\P})$ and
    \begin{equation*}
      Z_t= X_0+\int_0^t b(s,X_s,\mathcal{L}(X_s))\dd s + \int_0^t \sigma(s,X_s,\mathcal{L}(X_s))\dd B_s,\quad t\in[0,T],
    \end{equation*}
    holds $\tilde{\P}$-a.s., for some $m$-dimensional Brownian motion $(B_t)_{t\in[0,T]}$ on the mentioned filtered probability space.
  \end{enumerate}

