[Definition def:tops of arXiv:2412.04212, 'Rectangular Gilbert Tessellation'] Let $v\in \mathbb{R}^2$ and a direction vector $d_v$ be fixed arbitrarily. For any given realization of $\mathcal{V}$ containing $v$, a point $u\in \mathcal{V}$
is called a {\normalfont top} with respect to $\mathcal{L}_{v, d_v}^\pm(t)$ in $\mathcal{V}
$,  if
\begin{equation}
\{L_{v, d_v}^\pm(t) = t\}\cap \{d_u \neq d_v\}= \emptyset 
\end{equation}
for all $t$ such that $\{L_{v, d_v}^\pm(t) = t\} \neq \emptyset$.

[Definition 33 (Viscosity solutions) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\bar\xi$ be a regularization of $\xi$, and let $\H$ be defined by~\eqref{e.def_H_spin_glass}. Consider the Hamilton--Jacobi equation
\begin{align}
    \partial_t f- \H(\partial_q f)=0,\quad &\text{on $\R_+\times \mcl Q^\D_2$}.
\end{align}
\begin{enumerate}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity subsolution} of~\eqref{e.hj_H} if, for every $(t,q) \in (0,\infty)\times \mcl Q_2^\D$ and every smooth $\phi:(0,\infty)\times \mcl Q_2^\D\to\R$ such that $f-\phi$ has a local maximum at $(t,q)$, we have
    \begin{align*}
        \left(\partial_t \phi - \H(\partial_q\phi)\right)(t,q)\leq 0.
    \end{align*}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity supersolution} of~\eqref{e.hj_H} if, for every $(t,q) \in (0,\infty)\times \mcl Q_2^\D$ and every smooth $\phi:(0,\infty)\times \mcl Q_2^\D\to\R$ such that $f-\phi$ has a local minimum at $(t,q)$, we have
    \begin{align*}
        \left(\partial_t \phi - \H(\partial_q\phi)\right)(t,q)\geq 0.
    \end{align*}
    \item A continuous function $f:\R_+\times \mcl Q_2^\D\to \R$ is a \textbf{viscosity solution} of~\eqref{e.hj_H} if it is both a viscosity subsolution and a viscosity supersolution.
\end{enumerate}
Finally, a continuous function $f:\R_+\times \mcl Q^\D_2\to\R$ is called a \textbf{viscosity solution} of~\eqref{e.hj} if it is a viscosity solution of~\eqref{e.hj_H} for some regularization $\bar\xi$.

[Prop p:cond-var-delta of arXiv:2607.18194, 'Temperature chaos in directed polymers'] There exists $C,c>0$ depending only on $R_1,R_2$, such that for all sufficiently small $\delta$,
    \begin{align*}
        \max_{i\in\llbracket 0, N-1\rrbracket}
        \sup_{z,w\in J^\delta}
        \mathbb{E}\left[
            \Var\left(
                \mathcal{L}(s_i,z ;s_{i+1}, w)\,\middle|\,\mathcal{F}_{R_1}\vee\mathcal{F}_{R_2}
            \right)
        \right]
        \leqslant Ce^{-c\log^2(1/\delta)}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

