- \mathcal{M}_{t+1, \mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\bigl(\mathcal{M}_{t+1, \mathbf{a},
\mathbf{n}+\mathbf{1}}
- q\mathcal{M}_{t, \mathbf{a},
\mathbf{n}}\bigr) = 0,
\end{equation}
at every $(t, \mathbf{a}, \mathbf{n})$ with $n_m < N$ and
$a_i < y_{n_i+1} - 1$ for all~$i$.

[Proposition 130 (First-chaos spectral bounds) of arXiv:2607.10813, '2607.10813'] For every $\eps>0$,
\begin{equation}
  \sup_{\Lambda\ge1}\sup_{t\le T}
  q_{a,\Lambda}^{(1)}(t,\xi)
  \lesssim_{T,\eps}\la\xi\ra^{-4+2\beta_{\Gamma,a}+\eps}.
\end{equation}
For every $0<\theta<1/2$,
\begin{equation}
  q_{a,\Lambda}^{(1),\Delta}(t,t';\xi)
  \lesssim_{T,\eps,\theta}
  |t-t'|^{2\theta}
  \la\xi\ra^{-4+2\beta_{\Gamma,a}+2\theta+\eps}.
\end{equation}
For every $s<1/2-\beta_{\Gamma,a}$, one may choose
$0<\theta<1/2$ and $\delta>0$ such that the cutoff-difference densities
satisfy the tail criterion in \eqref{eq:path-criterion-tail}, uniformly over
the four projection conventions.

[Lemma rescomY of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Under the assumptions of Theorem (MixEV of the paper), let $G$ and $G_{{\mathfrak t}}$ denote the resolvents of ${H_{\Lambda}}$ and ${H_{\Lambda}}({\mathfrak t})$, respectively. 
Let $F: \mathbb{R}^n \rightarrow \mathbb{R}$ be a function whose derivatives satisfy the following bound: for any fixed $l\in \mathbb{Z}_+$, there exists a constant $C_l>0$ such that
\begin{equation}
    \begin{aligned}
        \max_{\left\lvert \alpha \right\rvert=1,2,\ldots,l}\max_x\left|F^{(\alpha)}(x)\right|(|x|+1)^{-C_l} \leqslant C_l.
    \end{aligned}
\end{equation}
Denote $\widehat m=\left\langle G \right\rangle$ and $\widehat m_t=\left\langle G_t \right\rangle$ for any $t\in \qa{0,{\mathfrak t}}$. Then, there exists a constant $\sigma_0>0$ such that for any constant $0<\sigma<\sigma_0$, and for any sequences of real numbers $\ha{E_1\left({i}\right)}_{i=1}^n$ and $\ha{E_2\left({t}\right)}_{i=1}^n$ satisfying
\begin{equation}\nonumber
    \begin{aligned}
        \left|E_1\left({i}\right)-E^+\right| \leqslant N^{-2 / 3+\sigma}, \quad\left|E_2\left({i}\right)-E^+\right| \leqslant N^{-2 / 3+\sigma}, \quad {i=1,2,\ldots,n},
    \end{aligned}
\end{equation}
setting $\eta=N^{-2 / 3-\sigma}$, we have
\begin{equation}
    \begin{aligned}
        \Bigg|\mathbb{E} &F\left({DN} \int_{E_1\left({1}\right)}^{E_2\left({1}\right)} \mathrm{~d} y \operatorname{Im} \widehat m(y+\mathrm{i} \eta),\ldots,DN \int_{E_1\left({n}\right)}^{E_2\left({n}\right)} \mathrm{~d} y \operatorname{Im} \widehat m(y+\mathrm{i} \eta)\right)\\
        &-\mathbb{E} F\left(DN \int_{E_1\left({1}\right)}^{E_2\left({1}\right)} \mathrm{~d} y \operatorname{Im} \widehat m_{{\mathfrak t}}(y+\mathrm{i} \eta),\ldots,DN \int_{E_1\left({n}\right)}^{E_2\left({n}\right)} \mathrm{~d} y \operatorname{Im} \widehat m_{{\mathfrak t}}(y+\mathrm{i} \eta)\right)\Bigg| \lesssim N^{-\delta}
    \end{aligned}
\end{equation}
for some small constant $\delta>0$ depending only on $\delta_A,\ \varepsilon_A$, and the constants $C_l$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2608.30178, '2608.30178'] {
Assume that $0 < q_1, q_2 \le 1$. If \(b_{10},b_{20}>0\), then $(X_t,Y_t)\rightarrow(0,0)$ on $\{\tau_0=\infty\}.$
}

