[Theo 3 of arXiv:2609.00186, 'Macroscopic scalar curvature bounds on surfaces'] Let $(\Sigma,g)$ be a closed oriented Riemannian surface of genus $k= 1$. Then, for every $r>0$,
    \begin{equation}
    \max_{\tilde x\in \tilde \Sigma}\area_{\tilde g}(B_{\tilde g}(\tilde x,r))\geq \pi r^2,
    \end{equation}
    with equality for a given $r>0$ if and only if $g$ has constant curvature 0. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture conj:1 of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $\operatorname{\bf NG}_{s}$ be a probability measure given by moment generating function
\begin{align}
	\operatorname{\bf NG}_s [e^{(\psi, f)} ] \propto \int_{\R} e^{(\psi,  \Phi(f) )} e^{-\frac{1}{4} |y|^4 -  s |y|^2} {\rm d} y .
\end{align}
Under the assumptions of Theorem~(thm:NGlimit of the paper),  there exists $c>0$ such that
\begin{align}
	\lim_{N\rightarrow \infty}  \langle e^{(\varphi,f_N) / {\sf b}_N} \rangle_{g,\nu_c + sw_N, N} = \operatorname{\bf NG}_{cs} ( e^{(\psi, f) / c_3^{1/4}}  ) .
\end{align} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Dfn def:meanvalueproperty of arXiv:2411.13765, 'Schr\"odinger Bridge Problem for Jump Diffusions'] We say that $h$ satisfies the \textit{mean-value property} if for all $0 \leq s \leq t \leq T$ and $x\in\mathbb{R}^n$,
        \begin{equation}
            h(s,x)=\int_{\mathbb{R}^n} h(t,y)P_{s,t}(x,dy).
        \end{equation}

[Lem thm:norm-lemma-bernoulli of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $s,\alpha,\beta,\gamma\in\mathds{R}$, $p,r\in (0,\infty)$, $q\in (0,\infty]$, and $\mu,\nu \in (-\infty,0]$.
Let further $(\xi_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ and $(\lambda_{j,t,m})_{(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d}$ be two families of random variables with $\xi_{j,t,m}\in\mathds{R}$ and $\lambda_{j,t,m}\in\left\{0,1\right\}$ for $(j,t,m)\in\mathds{N}_0\times\left\{F,M\right\}^d\times\mathds{Z}^d$.
Set
\begin{equation*}
\varrho_{j,m}\mathrel{\mathop:}= 2^{j\mu}\lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j }}^\nu
\end{equation*}
and $a=(a_{j,t,m})_{(j,t,m)\in J}$ where
\begin{equation*}
a_{j,t,m}\mathrel{\mathop:}= 2^{j\alpha} \lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j}}^{\beta + (\gamma-\beta)\mathds{1}_{j=0}}\lambda_{j,t,m}\xi_{j,t,m}
\end{equation*}
for $(j,t,m)\in J$.
If Property A'' is satisfied, then for $\widetilde{\Xi}$ as in 
  \hyperref[{eq:master-quantity-bernoulli}]{\textup{\tagform@{\ref*{eq:master-quantity-bernoulli}}}}
, we have $\left\lVerta\right\rVert_{b^s_{p,q}(\mathds{R}^d)}\lesssim\widetilde{\Xi}^{\frac{1}{p}}$ where the implied constant only depends on $\mu$, $\nu$, $\beta$, $\gamma$, $p$, $d$, and $r$.

