body:
[Lemma 19 (Theorem A.2 in \cite{BW}) of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] Let $\nu$ be a nonnegative random measure on $\mathbb{R}_+$, $\nu(t) := \int_0^t \nu(ds)$, and suppose the Laplace transform
\begin{align*}
    \hat{\nu}(\lambda) := \int_0^\infty e^{-\lambda s} \nu(ds)
\end{align*}

\noindent exists almost surely for any $\lambda > 0$. If
\begin{itemize}\setlength\itemsep{0em}
\item $\rho \in [0, \infty)$ is fixed;
\item $L: (0, \infty) \to (0, \infty)$ is a deterministic slowly varying function at $0$; and 
\item $C_\nu$ is some non-negative (finite) random variable,
\end{itemize}

\noindent then we have:
\begin{align}
    \frac{\lambda^\rho}{L(\lambda^{-1})} \hat{\nu}(\lambda) \xrightarrow[\lambda \to \infty]{p} C_\nu
    \qquad \Rightarrow \qquad 
    \frac{t^{-\rho}}{L(t)} \nu(t) \xrightarrow[t \to 0^+]{p} \frac{C_\nu}{\Gamma(1+\rho)}.
\end{align}

\noindent The same implication also holds when one considers the asymptotics as $\lambda \to 0^+$ and $t \to \infty$ in \eqref{eq:tauberian} (but with $L$ being slowly varying at infinity) instead. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:properties-brownian of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] Let $\mathbf{X}(t)$ be the solution to~(equation e:reparametrized-brownian-general of the paper). Then, the following holds.
 \begin{enumerate}
 \item for every $p\geqslant 1$ and for every $0=t_0< t_1< t_2<\ldots< t_p\leq 1$, $\mathbf{X}(t_1)$, $\mathbf{X}(t_1)^{-1}\mathbf{X}(t_2)$, $\ldots$, $\mathbf{X}(t_{p-1})^{-1}\mathbf{X}(t_p)$ are independent;
 \item for all $0\leqslant s\leqslant t\leqslant 1$, $\mathbf{X}(s)^{-1}\mathbf{X}(t)$ has the same distribution as $\mathbf{X}(t-s)$;
 \item for every $\mathrm{h}$ in $G$, $\mathbf{X}(t)$ and $\mathrm{h}\mathbf{X}(t)\mathrm{h}^{-1}$ have the same distribution.
 \end{enumerate}

[Lemma 2 of arXiv:2608.26038, 'Rotated semicircle laws for permanental roots of Gaussian random matrices'] For every complex \(N\times N\) matrix \(A\),
\begin{equation}
  \Per(zI_N-A)
  =
  \sum_{S\subseteq\{1,\dots,N\}}
  (-1)^{|S|}\Per A[S]z^{N-|S|}.
\end{equation}
In particular, \(\Per(zI_N-A)\) is monic of degree \(N\).

[Thm minimax_sharp of arXiv:2604.07183, 'Stopping on the last success with unknown odds: asymptotic minimax optimality of the plug-'] Fix~$p_0\in(0,\frac12)$. Then, with~$C_\star$ as in~((eq:Cstar of the paper)),
\begin{equation}
\lim_{n\to\infty}
\ \sqrt n\,
\inf_\pi\sup_{p\in[p_0,1)}\bigl(V_n(p)-W_n^\pi(p)\bigr)
=
C_\star
,
\end{equation}
where the infimum is over all (possibly randomized) \mbox{$p$-blind} rules. Consequently, the plug-in rule is asymptotically minimax optimal, with the exact constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor robustified_consistency_total_sample of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Suppose that Assumption~(assumption:main_1Lip of the paper) holds and that
$\operatorname{diam}(X)>0$.  Let $(Z_n)_{n=1}^{\infty}$ be an i.i.d.\ sequence
with law $\mu=\mu_X\otimes\nu$, where $Z_n=(X_n,\varepsilon_n)$.  

Fix any $\kappa>1$.  For every total sample budget
$\mathsf N\in\mathbb N_+$, set
\[
    \delta_{\operatorname{net},\mathsf N}
    =
    \delta_{\operatorname{noise},\mathsf N}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \mathsf N^{-\kappa}.
\]
Choose $A>0$ as specified below and set
\[
    \varepsilon_{\mathsf N}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    A\mathsf N^{-1/(s+2)},
    \qquad
    \beta_{\mathsf N}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \frac{\varepsilon_{\mathsf N}}{2},
    \qquad
    q_{\mathsf N}
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}
    \left\lceil
        \varepsilon_{\mathsf N}^{-2}
    \right\rceil.
\]
For all sufficiently large $\mathsf N$, choose
$N_{0,\mathsf N},N_{1,\mathsf N}\in\mathbb N_+$ satisfying
$
    N_{0,\mathsf N}+N_{1,\mathsf N}\le\mathsf N
$
and the sample-size conditions below:

and choose integers $N_{0,\mathsf{N}},N_{1,\mathsf{N}}\in\mathbb N_+$ satisfying
$N_{0,\mathsf{N}}+N_{1,\mathsf{N}}\le \mathsf{N}$ and
\begin{align}

    N_{0,\mathsf{N}}
  &   \ge
    \frac{1}{a(\varepsilon_{\mathsf{N}}/8)^s}
    \log\left(
        \frac{
            2N_{\varepsilon_{\mathsf{N}}/8}(X,\rho)
        }{
            \delta_{\operatorname{net},\mathsf{N}}
        }
    \right)
\quad \mbox{ and }\quad
    \\
    N_{1,\mathsf{N}}
  &   \ge
    \frac{1}{a(\varepsilon_{\mathsf{N}}/2)^s}
    \max\left\{
        2q_{\mathsf{N}},
        8\log\left(
            \frac{
                2N_{0,\mathsf{N}}
            }{
                \delta_{\operatorname{net},\mathsf{N}}
            }
        \right)
    \right\}
.
\end{align}
Then, for every fixed
$f\in\operatorname{Lip}((X,\rho);1)$, there exists a constant
$K\in(0,\infty)$, depending only on
$a,s,C,A,\kappa$, such that, for all sufficiently large $\mathsf N$,
\begin{equation}

    \mathbb{P}\left(
        \|\hat{f}_{\mathsf N}-f\|_\infty
        >
        K
        \mathsf N^{-1/(s+2)}
        \sqrt{\log\mathsf N}
    \right)
    \le
    2\mathsf N^{-\kappa}.
\end{equation}

[Proposition 15 of arXiv:2604.01978, 'Homogenized Transformers'] Under Assumption \ref{ass:high_order_short}, 
\begin{equation*}
    \|G_{\mu}(x, \cdot)-G_{\nu}(y, \cdot)\|_{L^{2}({\uprho_*})}\leq C\left(W_{2}(\mu,\nu)\,+\, \|x-y\|\right)
    \end{equation*}
for all $(\mu,\nu)\in \cP(\S^{d-1})$ and $(x,y)\in \S^{d-1}$, where 
\begin{equation*}
C=O\left(\upbeta^{2}e^{4\upbeta\|\Bar{\bA}\|}e^{\upbeta^{2}d\sigma_{\bA}^{2}}\right).
\end{equation*}

[Lemma 6 of arXiv:2608.13732, '\textbf{On the First Hitting Time Problems \\ for Diffusion Processes: \\ Local Time-Space'] Let $\{x_i\}_{i\ge 1}$ be a sequence of real numbers. Assume that there exists a constant $K>0$ such that $|x_1|\le K$ and, for all $i\ge 1$,
\begin{equation}
|x_{i+1}| \le \sum_{j=1}^{i} |c_{i,j}|\,|x_j| + |b_i|.
\end{equation}
Suppose further that
\begin{equation}
\varrho_i := 1-\sum_{j=1}^{i}|c_{i,j}| > 0,
\quad
|b_i| \le K\varrho_i,
\quad i\ge 1.
\end{equation}
Then $|x_i| \le K$, for all $i \ge 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 38 (Hereditary non-ghost property) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For every fixed $J$, define the internal ultraproduct module
\[
 \mathbb M_{q,\mathcal U}^{[J]}
 =\left\{[m_n]_{\mathcal U}:m_n\in M_{n,q}^{[J]},\
       \sup_n\norm{m_n}<\infty\right\}.
\]
Then
\begin{equation}
 \boxed{\mathbb M_{q,\mathcal U}^{[J]}\subset\cD_q.}

\end{equation}

[Corollary 31 (Homogeneous case) of arXiv:2608.17374, '\textbf{On the Pseudo-Mixing of Kac's Walk}'] For homogeneous $T\in \mathbb{R}^{[n]^d\times [n]^d}$ define
$f_T(X)=\mathrm{Ev}_d(T)(X)$ as in \eqref{eq:eval-map}, and let $T^\sharp$ be the
Frobenius-orthogonal projection of $T$ onto $\mathcal C_d^\perp$. Then
\begin{equation}
\Var(f_T(X)) \;\ge\; n^{-d}\,\|T^\sharp\|_F^2.
\end{equation}

[Lemma lem:ZN2-laplace of arXiv:2411.09075, 'Weak Poincar{\'e} Inequalities, Simulated Annealing, and Sampling from Spherical Spin Glas'] With probability $1-e^{-cN}$ over $H_{N,2}$,
    \begin{equation}

        Z_{N,2} = (1 + O(N^{-c})) \sqrt{\fr{2}{G''(\gamma_*)}} (2e)^{-N/2} \exp(NG(\gamma_*)).
    \end{equation}

