body:
[Corollary 46 (Free capacity and the Fredholm derivative) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] For positive trace-class operators \(Q\) on \(H\) and \(T\) on
\(\mathcal F_{\wedge}(H)\), define the free capacity of \(T\) in the
direction \(Q\) by
\begin{equation}
 \operatorname{Cap}^{\mathrm{free}}_Q(T)
 :=(\operatorname{Tr}Q)(\operatorname{Tr}T)
   -\operatorname{Tr}(\mathrm d\Gamma(Q)T)
 =\operatorname{Tr}\mathcal B_Q(T).

\end{equation}
Then
\[
 0\leq\operatorname{Cap}^{\mathrm{free}}_Q(T)
 \leq(\operatorname{Tr}Q)(\operatorname{Tr}T).
\]
Moreover, for positive trace-class \(P,Q\) on \(H\),
\begin{equation}
 \operatorname{Cap}^{\mathrm{free}}_Q(\Gamma_{\wedge}(P))
 =\det(I+P)\operatorname{Tr}((I+P)^{-1}Q).

\end{equation}
Consequently,
\begin{equation}
 \frac{\operatorname{Cap}^{\mathrm{free}}_Q(\Gamma_{\wedge}(P))}
      {\operatorname{Tr}_{\mathcal F_{\wedge}(H)}\Gamma_{\wedge}(P)}
 =\left.\frac{\mathrm d}{\mathrm d\varepsilon}\right|_{\varepsilon=0}
   \log\det(I+P+\varepsilon Q)
 =\operatorname{Tr}((I+P)^{-1}Q).

\end{equation}

[Lemma 28 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $t>0$ and $q\in\mcl Q_{\upa,c}^\D$ for some $c>0$. There is a constant $b>0$ such that
\begin{align*}
    \frac{\d^2}{\d r^2}\bar F_N\Ll(t,\ q+a_i r q_i+N^{-\gamma/2}\sum_{j\neq i}a_j y_jq_j \Rr) \leq b,\quad\forall i\in\N,\  N\in \N, \  r\in[0,1).
\end{align*}
Moreover, the same holds for $\tilde F_N^x$ and $\bar F^x_{N+1}$ in place of $\bar F_N$ uniformly in $x\in[0,3]^{\N^4}$.

