body:
[Lemma lem:commutatorTruncationEstimates of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $0<\mathsf{s}<\mathsf{d}$, let $n\ge1$, and let $v:{\mathbb{R}}^\mathsf{d}\to{\mathbb{R}}^\mathsf{d}$ be globally Lipschitz.  For a differentiable kernel $\phi$, let
\begin{align}
\mathsf{k}_{n,\phi}(x,y) \coloneqq \nabla^{\otimes n}\phi(x-y):(v(x)-v(y))^{\otimes n},
\end{align}
which is symmetric whenever $\phi$ is even.  There are constants $C_n$ and $c_n\ge2$, depending only on $\mathsf{d},\mathsf{s},n$, such that the truncations in (equation eq:HCRStruncDef of the paper) satisfy
\begin{align}
|\mathsf{k}_{n,{\mathsf{g}}_\eta}(x,y)|&\le C_n\|\nabla v\|_{L^\infty}^n{\mathsf{g}}_\eta(x-y),\nonumber\\
|\mathsf{k}_{n,\mathsf{f}_\eta}(x,y)|&\le C_n\|\nabla v\|_{L^\infty}^n\mathsf{f}_{c_n\eta}(x-y).
\end{align}
If $\mu\in L^\infty$ and $\sigma\in\{\pm1\}$, then the short-range deterministic estimate holds:
\begin{multline}
\frac{\sigma}{N^2}\sum_{1\le i\ne j\le N}\tilde{\mathsf{k}}_{n,\mathsf{f}_\eta}(x_i,x_j) \le \frac{C_{\mathrm{sr},n}\|\nabla v\|_{L^\infty}^n}{N^2}\sum_{1\le i\ne j\le N}\mathsf{f}_{c_n\eta}(x_i-x_j)\\
{}+ C_n\|\nabla v\|_{L^\infty}^n\|\mu\|_{L^\infty}\eta^{\mathsf{d}-\mathsf{s}},
\end{multline}
where $C_{\mathrm{sr},n}$ depends only on $\mathsf{d},\mathsf{s},n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2507.03552, 'On one-dimensional Cluster cluster model'] For $-2 < \alpha < 0$, $\forall \varepsilon>0, n\in {\mathbb{N}}, \exists c>0$ s.t:
    \begin{equation}
        \lim_{t \to \infty}{\Prob{\abs{\mathfs{C}_0(t)} \le ct^{\gamma_n}}} \le \varepsilon  
    \end{equation}
    For $\alpha < -2$:
    \begin{equation}
        \lim_{t \to \infty}{\Prob{\abs{\mathfs{C}_0(t)} < \infty}} = 0
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2608.28307, 'Rigidity of closed $\lambda$-self-expanders'] Let $x:M^n\to \mathbb{R}^{n+1}$ be a $\lambda$-self-expander. If $H>0$, then we have
\begin{equation}
\begin{split}
L\Big(\frac{S}{H^2}\Big)&=-\frac{2}{H}\langle \nabla\Big(\frac{S}{H^2}\Big), \nabla H\rangle+\frac{2}{H^4}\sum_{ij,k}|Hh_{ij,k}-H_kh_{ij}|^2\\
&+\frac{2\lambda}{H^3}\Big[Htr(h^3)-S^2\Big].
\end{split}
\end{equation}

