body:
[Definition 21 of arXiv:2609.02105, 'Contact fundamental forms and \\ adjoint varieties'] Let $(M, H \subset TM)$ be a contact manifold and let $\sL$ be a line bundle on $M$. Twisting the exact sequence in Definition \ref{d.contact} (iii), we have the exact sequence of vector bundles
\begin{equation} 0 \to U_{k}(\fn)^*\otimes \sL \longrightarrow J^{k} \otimes \sL  \longrightarrow J^{k-1}\otimes \sL \to 0. \end{equation}
Suppose we have a fixed embedding $M \subset \BP^N$ as a complex submanifold of projective space. Let $\sL$ be the restriction of the hyperplane line bundle on $\BP^N$ to $M$. The embedding is given by a subspace $W \subset H^0(M, \sL)$.   For a point $z \in M$, we have a natural inclusion $W \subset \sO(\sL)_z$, determining a subspace  $j^k_z(W) \subset  J^k_z \otimes \sL_z$ for all $k \geq 0$. Define $$W^k_z := W \cap \mathbf{m}_z^k\cdot \sO(\sL)_z.$$  Then $j^{k}_z (W^{k+1}_z)=0$ and (\ref{eq.jet}) determine a  homomorphism $${\rm CF}^k_z : W_z^k/W_z^{k+1} \to U_k(\fn_z)^*\otimes \sL_z,$$ which we call the $k$-th {\em contact fundamental form } of $M \subset \BP^N$ at $z$. Let $S^k_z \subset U_k(\fn_z)^*$ be the image of ${\rm CF}^k_z$, modulo a local trivialization of $\sL$ at $z$. The graded subspace $S_z := \oplus_k S^k_z$ of $U(\fn_z)^*$ is called the {\em system of contact fundamental forms}. It is easy to see that $S_z$ is independent of the choice of a local trivialization of $\sL$ near $z$.

[Definition def:sol_lin_fp of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$ and $\nu\in \mathcal{M}(\mathbb{R}^d)$. A measurable flow ${\boldsymbol\mu}:[s,T)\to \mathcal{M}(\mathbb{R}^d)$ is a (weak) solution to FP$(b,\sigma;s,\nu)$ if
\begin{equation}
\int_{\mathbb{R}^d} \varphi(y) {\boldsymbol\mu}_t (d y)    = \int_{\mathbb{R}^d} \varphi(y) \nu (d y) + \int_{s}^{t} \int_{\mathbb{R}^d}  \Big[\big\langle b(r , y) , \nabla \varphi(y)\big\rangle + \frac{1}{2} \text{tr}\big( \sigma\sigma^\top(r , y ) \nabla^2 \varphi(y) \big)   \Big]  {\boldsymbol\mu}_r (d y) d r, \qquad t\in [s,T),

\end{equation}

for any $\varphi\in C^{\infty}_0(\mathbb{R}^d)$. 

Furthermore, if ${\boldsymbol\mu}_t$ is absolutely continuous with respect to the Lebesgue measure, namely
\begin{equation}
{\boldsymbol\mu}_t (d x) = v_t(x) d x, \qquad t\in [s,T), 
\end{equation}
then the density flow $v:[s,T)\to L^{1}(\mathbb{R}^d)$ will be called a density solution to FP$(b,\sigma;\nu)$.

[Definition 33 (Projection tensorfields and hypersurface tangency) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill
\begin{enumerate}
\item We define the type $\binom{1}{1}$
$\Sigma_t$-projection tensorfield $\Sigmatproject$ and the type $\binom{1}{1}$ $\ell_{t,u}$-projection tensorfield 
$\smoothtorusproject$ as follows, where $\updelta_{\beta}^{\alpha}$ denotes the Kronecker delta: 
\begin{subequations}
\begin{align}
\Sigmatproject_{\beta}^{\ \alpha}
& \eqdef 
	\updelta_{\beta}^{\alpha}
	+ 
	\Transport^{\alpha} 
	\Transport_\beta,  

	\\
\smoothtorusproject^{\ \alpha}_\beta 
& 
\eqdef 
\updelta_{\beta}^{\alpha}
+  
\Transport^{\alpha} \Transport_\beta 
- 
X^{\alpha} X_\beta 
= 
\updelta_{\beta}^{\alpha}
- 
\Lunit^{\alpha} \updelta^0_\beta 
+
X^{\alpha} \Lunit_{\beta}.

\end{align} 
\end{subequations}\item Given any type $\binom{m}{n}$ spacetime tensorfield $\upxi$, 
we respectively define its $\gfour$-orthogonal projection onto $\Sigma_t$, denoted by $\Sigmatproject \upxi$, its $\gfour$-orthogonal projection onto $\ell_{t,u}$, denoted by $\smoothtorusproject \upxi$, as follows:
\begin{subequations}
\begin{align}
(\Sigmatproject \upxi)_{\beta_1 \cdots \beta_n}^{\alpha_1 \cdots \alpha_m}
& 
\eqdef 
\Sigmatproject_{\widetilde{\alpha}_1}^{\ \alpha_1}
\cdots 
\Sigmatproject_{\widetilde{\alpha}_m}^{\ \alpha_m}
\Sigmatproject_{\beta_1}^{\ \widetilde{\beta}_1}
\cdots 
\Sigmatproject_{ \beta_n}^{\ \widetilde{\beta}_n}
\upxi_{\widetilde{\beta}_1 \cdots \widetilde{\beta}_n}^{\widetilde{\alpha}_1 \cdots \widetilde{\alpha}_m}, 

	\\
(\smoothtorusproject \upxi)_{\beta_1\cdots\beta_n}^{\alpha_1\cdots\alpha_m} 
& \eqdef 
\smoothtorusproject_{\widetilde{\alpha}_1}^{\ \alpha_1} 
\cdots 
\smoothtorusproject_{\widetilde{\alpha}_m}^{\ \alpha_m} 
\smoothtorusproject_{ \beta_1}^{\ \widetilde{\beta}_1}
\cdots 
\smoothtorusproject_{ \beta_n}^{\ \widetilde{\beta}_n}
\upxi_{\widetilde{\beta}_1 \cdots \widetilde{\beta}_n}^{\widetilde{\alpha}_1 \cdots \widetilde{\alpha}_m}.

\end{align}
\end{subequations}\item
We say that a spacetime tensorfield $\upxi$ is $\Sigma_t$-tangent if $\Sigmatproject \upxi = \upxi$. 
We say that a spacetime tensorfield $\upxi$ is $\ell_{t,u}$-tangent if $\smoothtorusproject \upxi = \upxi$.  
\item If $\upxi$ is a symmetric type $\binom{0}{2}$-spacetime tensor and $V$ is a vectorfield, 
then we define $\slashed{\upxi}_V \eqdef \smoothtorusproject(\upxi \cdot V)$, 
where $\upxi \cdot V$ is the one-form with components
$(\upxi \cdot V)_{\alpha} \eqdef \upxi_{\alpha \beta} V^{\beta}$.
\item If $\upxi$ is a spacetime tensor, then we define $\slashed{\upxi} = \smoothtorusproject \upxi$.
From 3 above, it follows that $\xi$ is $\ell_{t,u}$-tangent if and only if $\slashed{\upxi} = \xi$.
\end{enumerate}

[Proposition prop:L1contraction of arXiv:2512.18598, 'Long-time reverse transportation inequalities for non-globally-dissipative Langevin dynami'] Under Assumption (ass:farfield of the paper),  Let $f(\cdot)$ be a Lyapunov function as defined in (equation eq:Lyapunov of the paper) with $R_f = R$ and $C_f = \frac{1}{4}R(L+m)$. 
