        \eta_t =\frac{aa'}{e^{a(T-t)}-1},\quad t\in [0,T)
    \end{equation}
    with any $a$, $a'>0$.
    Then for any $t\in [0,T]$ and $x \neq x'$,
    \begin{equation}
        \mathbb{E}|X_t-X_t''| \leq C_1\mathbb{E}f(|X_t-X_t''|) \leq C_1\exp\left(-2\nu t - C_1^{-1}\big(\sqrt{|x-x'|}\vee\sqrt{R+1}\big)^{-1}\int_0^t \eta_s ds \right)|x-x'|.
    \end{equation}







    where
    \begin{equation}
        \nu := \frac{m}{2}\exp\bigl(-\frac{1}{4}R^2(L+m)\bigr),\quad C_1 := \exp\bigl(\frac{1}{4}R^2(L+m)\bigr),
    \end{equation}
    In particular,
    \begin{equation}
        X_T = X_T'' \quad a.s..
    \end{equation}

