[Theorem 2 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that $X=(X_t)_{t\in[0,T]}$ satisfies Assumption \ref{a1} and that $\alpha$ is as in \eqref{E:parameters}. 
		\begin{enumerate}
			\item[(i)] For any $t \in (0,T)$  there is a constant $c_4(t)>0$ such that
			\begin{equation}		
				\liminf _{r \to 0} \sup_{s \in (t-r,t+r)} \frac{\|X_t - X_s \| }{r^H(\log\log r^{-1})^{-H(\frac{\theta}{d-\alpha}+1)}} \geq c_4(t)\qquad \text{$\mathbb{P}$-a.s.}
			\end{equation}
			\item[(ii)] There is a constant $c_5>0$ such that		
			\begin{equation}		
				\liminf _{r \to 0} \inf_{t\in (0,T)} \sup_{s \in (t-r,t+r)} \frac{\|X_t - X_s \| }{r^{H} ( \log r^{-1})^{-H(\frac{\theta}{d-\alpha}+1)}} \geq c_5\qquad \text{$\mathbb{P}$-a.s.}
			\end{equation}
		\end{enumerate}
		In particular, $X$ is almost surely nowhere differentiable. (Proof in the paper; no proof environment follows the statement in the TeX.)

