[Corollary 35 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] For each  continuous function $f\in C(\bb T)$,
\begin{align*}
& \lim_{\epsilon \to 0}
\frac{1}{\epsilon}e^{-\mf h_{\widehat{\mf q}}/\epsilon}
\sum_{k\in S_{\widehat{\mf q}}}\int_{\mc E_{\widehat{\mf q}}(k)}f(x)
\frac{1}{\mtt a(x)} \, \phi_{\widehat{\mf q},\epsilon}(x)^2
\sum_{j\in \mf I_k }\sum_{\sigma\in \mc W_{j,j+1}^{(\widehat{\mf q})}}
\int_{\sigma-\eta_0}^{\sigma+\eta_0}\frac{e^{ [S(y) - S(x)] /\epsilon}}{
\phi_{\widehat{\mf q},\epsilon}(y)^2}\,dy\,dx \notag
\\
& \quad = \sum_{k\in S_{\widehat{\mf q}}}\widehat{h}(\mc M_{\widehat{\mf q}}(k))^2
\sum_{j\in \mf I_k}\frac{\sigma_{\widehat{\mf q}}(j,j+1)}
{\widehat{h}(\mc M_{\widehat{\mf q}}(j)) \, \widehat{h}(\mc M_{\widehat{\mf q}}(j+1))}
\sum_{m\in\mc M_{\widehat{\mf q}}(k)}\pi_1 (\{m\}) \, f(m)
\end{align*}

