[Proposition 7 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Suppose $(N_{n},V_{n})$ has exponential (shell) growth with constant $a$. Then, for any $n \in \mathbb{N}$, any $a,b >0$, any $p \in [1,\infty]$, and any $d \geq 1$, there exists a  partition \(\mathcal P_n(q_n)=\{B_1,\ldots,B_{M_n}\}\) satisfying $\max_{m\in[M_n]}|B_m|\lesssim q_n $ with $q_{n} \in [n] $ such that
	\begin{align}
		\left\|
		\sup_{f\in\mathcal F}\mathbb G_n(f)
		\right\|_{L^1(\mathbb P)}
		\lesssim\;&
		q_n e^{a r_n/2}
		\max_{m\in[M_n]}\Gamma_p(B_m)
		\gamma_{2,a}
		\left(
		\mathcal F,
		\max_{i\in N_n}\|\cdot\|_{L^{2p}(P_{Z_i})}
		\right)
		\\
		&+
		\left(
		\frac{q_n^3 e^{a r_n}}{\sqrt n}
		+
		\sqrt n 	\bar{\tau}_{\operatorname{cone} \mathcal F,G_n}
		\left( 	\mathcal P_{n}(q_{n}), 	\mathcal C_{r_{n}}[\mathcal P_{n}(q_{n}) ] \right) 
		\right)
		\gamma_{1,b}
		\left(
		\mathcal F,\|\cdot\|_\infty
		\right).
	\end{align}
	In particular, if \(q_n\asymp 1\) and
	\(	\bar{\tau}_{\operatorname{cone} \mathcal F,G_n}
	\left( 	\mathcal P_{n}(1), 	\mathcal C_{r_{n}}[\mathcal P_{n}(1) ] \right)    = : 
	\bar{\tau}_{\operatorname{cone}\mathcal F,G_n}(r_n)\), then
	\begin{align}
		\left\|
		\sup_{f\in\mathcal F}\mathbb G_n(f)
		\right\|_{L^1(\mathbb P)}
		\lesssim\;&
		e^{a r_n/2}
		\gamma_{2,a}
		\left(
		\mathcal F,
		\max_{i\in N_n}\|\cdot\|_{L^{2p}(P_{Z_i})}
		\right)
		\\
		&+
		\left(
		\frac{e^{a r_n}}{\sqrt n}
		+
		\sqrt n\,
		\bar{\tau}_{\operatorname{cone}\mathcal F,G_n}(r_n)
		\right)
		\gamma_{1,b}
		\left(
		\mathcal F,\|\cdot\|_\infty
		\right).
	\end{align}

[Proposition th:GR of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] \begin{enumerate}
    \item Let $\alpha \le 1 < \beta$ or $\alpha > 1 \ge \beta$. Then $\mathbf H_{GR}(\alpha, \beta, \lambda)$ increases as a function of~$\lambda\in(0,\infty)$.
    \item Let $J$ be a subset of $(0,1)$ (as in Proposition~(prop:anomalGR1zero of the paper)) or a subset of $(1,\infty)$ (see Remark~(rem:anomGR1largealpha of the paper)) such that, for each $\alpha\in J$, the entropy $\mathbf H_{GR}(\alpha,\lambda)$ is decreasing in $\lambda$ on some interval (dependent on $\alpha$). Then, for each $\alpha\in J$ and for each $\beta$ in a neighborhood of $\alpha$, the entropy $\mathbf H_{GR}(\alpha,\beta,\lambda)$ is also decreasing in $\lambda$ on some interval (dependent on $\alpha,\beta$).    
\end{enumerate}

[Theorem thm:error-identity of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] Let $v_k = g_k / \|g_k\|_\pi$ be the normalized iterate, and let $s_2 = \operatorname{sign}(c_2)$ where $c_2 = \langle g_0, \phi_2 \rangle_\pi \neq 0$. Then for all $k \ge 0$,
\begin{equation}
\|v_k - s_2 \phi_2\|_\pi^2 = 2\bigl(1 - \sqrt{\alpha_2(k)}\bigr),
\end{equation}
where $\alpha_2(k) = n_2(k)/E_k$ is the slow-mode energy fraction defined in (equation eq:alpha-def of the paper).

