body:
[Proposition 15 of arXiv:2608.30059, 'Multihomogeneous Measures and Stochastic Polar Representations'] Let \(Z\) and \(W\) be \(E\)-valued random elements. If  
\(\nu_Z \in M_{\chi_\alpha,\sigma}(E)\),  then
\begin{equation}

\nu_W=\nu_Z
\quad\Longleftrightarrow\quad
\E{\Gamma(W)}=\E{\Gamma(Z)}
\quad\text{for every }\Gamma\in\mathcal H_\alpha(E),
\end{equation}
where equality is understood in \([0,\infty]\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Fix a graph $G=(V,E)$ and let $G_\star$ denote the star subgraph on vertex set $\{v,u_1,\dots,u_k\}$ with center $v$ (so $G_\star\subseteq G$). Assume that the initial configuration $\boldsymbol{\sigma}(0)$ is arbitrary on $V$ satisfying $\sigma_v(0)=I$. Let $T_{I,0}^{(v)}:=0$, and define
$$T_{R,i+1}^{(v)}:=\inf\{t>T_{I,i}^{(v)}: t\in N_v^{\mathrm{rec}} \}, \quad T_{S,i+1}^{(v)}:=\inf\{t>T_{R, i+1}^{(v)}:t\in N_v^{\mathrm{sus}} \}, \quad T_{I,i+1}^{(v)}:=T_{S,i+1}^{(v)}+k^{-1/48} $$
for all $i$; then they are all measurable with respect to $\mathcal{G}(v, \{u_1,\dots, u_k\})$, where $\mathcal{G}(v, \{u_1,\dots, u_k\})$ is defined in Definition~\ref{def:local_graphical_data}. Then there exists an event $A_4^{(v)}\in \mathcal{G}(v, \{u_1,\dots, u_k\})$ such that, for all sufficiently large $k$, the following hold:
\begin{enumerate}
    \item[\normalfont (i)] On $A_4^{(v)}$, $v$ is infected at $T_{I,i}^{(v)}$, and $T_{I,i}^{(v)}-T_{I,i-1}^{(v)}\le \frac{1}{6}\log k+k^{-1/48}$ for all $i=1,\dots,\lfloor 10ek^{\min\{\rho, \lambda,1\}/96}\rfloor$;
    \item[\normalfont (ii)] On $A_4^{(v)}$, $|\{i\le \frac{\frac{1}{2} k^{\min\{\rho,\lambda,1\}/200}}{\log k} : T_{I,i+1}^{(v)}-T_{I,i}^{(v)}\ge 3 \}|\ge \lfloor k^{\min\{\rho,\lambda,1\}/400}\rfloor +1 $;
    \item[\normalfont (iii)] On $A_4^{(v)}$, $v$ is $k^{1/24}$-lit among $\{u_1,\dots, u_k\}$ throughout the time interval $[0, 3k^{\min\{\rho,\lambda,1\}/96}]$;
    \item[\normalfont (iv)] $\mathbb{P}(A_4^{(v)})\ge 1-k^{-\min\{\rho,\lambda,1\}/100}$.
\end{enumerate}

[Lemma X of arXiv:2607.05418, 'On the Group Randomness of 0-1 Real Sequences from Binary Linear Codes'] Let $i,i_1,i_2,i_3,i_4,j,j_1,j_2,j_3,j_4 \in [1\mathrel{{.}\,{.}}\nobreak p]$ and $t,t_1,t_2,t_3,t_4 \in [1\mathrel{{.}\,{.}}\nobreak n]$. Also for $1 \leq q \leq 4$, denote $S_q:=\{i_q,j_q\}$. Then
        \begin{enumerate}
            \item $\mathbb{E}(X_{ijt},\widetilde{\Omega}_p)=0$;
            \item if $d^\bot \geq 3$, and $t_1 \neq t_2$ or $S_1 \cap S_2=\emptyset$, then $\mathbb{E}(X_{i_1j_1t_1}X_{i_2j_2t_2},\widetilde{\Omega}_p)=0$;
            \item if $d^\bot \geq 2, t_1=t_2, \sharp S_1=\sharp S_2=2$ and $\sharp(S_1 \cap S_2)=1$, then $\mathbb{E}(X_{i_1j_1t_1}X_{i_2j_2t_2},\widetilde{\Omega}_p)=\frac{1}{16}$;
            \item if $d^\bot \geq 5$, then $\mathbb{E}(X_{i_1j_1t_1}X_{i_2j_2t_2}X_{i_3j_3t_3}X_{i_4j_4t_4},\widetilde{\Omega}_p)=0$ unless $t_1,t_2,t_3,t_4$ come in pairs and there is no $q$ such that $S_q \cap S_{q'}=\emptyset$ for all $q' \neq q$.
        \end{enumerate}

