[Proposition 20 of arXiv:2511.06414, 'Non-uniform Edgeworth expansions for weakly dependent random variables and their applicati'] Let $m\geq 3$.
Suppose that for some $c$ domain of the form $\{|t|\in [c, Bn^{(m-3)/2}]\}$, $c,B>0$ we have 
\begin{equation}
\|\cL_{it}^n\|\leq A(1+C|t|)e^{-c_0 n |t|^{-\zeta}}
\end{equation}
for some constants  $A,C>0$  and $0\leq \zeta<\frac{2}{m-3}$ (where when $m=3$ we set $\frac{2}{m-3}=\infty$). Then the estimate in Assumption \ref{DerAss} holds true with these $m,c$ and some $B'>0$.

[Lemma 34 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] The following hold with high probability.

\begin{enumerate}
    \item For every $P, Q\subseteq C$, set
    \begin{equation}
        c_A(P) = \frac{1}{n}\#\{x\in A:|S_x \cap P| = d\}, \qquad  c_B(Q) = \frac{1}{n}\#\{y\in B:|S_y \cap Q| = d\}. 
    \end{equation}
    Then, if $P, Q$ are disjoint, $c_A(P) + c_B(Q) \leq \frac{2}{3} + o_\Proba(1)$ (uniformly in $P, Q \subseteq C$), with equality iff $|Q \Delta C| = o_\Proba(q)$.
    \item Uniformly over every permutation $\sigma\in\Sym_n$,
    \begin{equation} 
        \#\left\{
            v\in (A\sqcup B)\cap \Der\sigma:
            \deg_{U\land_\sigma U}(v)\geq d
        \right\}
        =o(n).
    \end{equation}
\end{enumerate}

