[Definition 4 (Visible informative maps) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] For an admissible depth $m$ and visible states $y,y'\in\cS_m$, define the stationary one-step visible transition law by
\begin{equation}
q_{y,y'}^{(m)}(\theta):=P_{\theta,\mathrm{stat}}(Z_{t+1}^{(m)}=y'\mid Z_t^{(m)}=y),
\end{equation}
whenever the conditioning event has positive stationary probability.
Flattening all state-pair coordinates gives the full informative map
\begin{equation}
q_{\cQ}^{(m)}(\theta)\in\RR^{|\cS_m|^2}.
\end{equation}
Forced zeros and row-sum constraints are retained in this full map.

[Proposition p.nonvacuum of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Fix $\kappa \in[0,\kappa_0]$. Suppose that the assumptions of (t.nonvacuum of the paper) hold, with the only modification being that we assume that $f$ is a classical solution to
    \begin{equation}
        (\partial_t + v\cdot\nabla_x)f
            = \kappa \Delta_v f + Q_{\rm LFD}(f),
    \end{equation}
    in place of~(equation e.LFD of the paper).  Then the conclusion~(equation e.nonvacuum_on_compacts of the paper) holds with additional dependence on $\kappa_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:domination of arXiv:2605.03703, 'Scaling Limits of Bivariate Nearly-Unstable Hawkes Processes and Applications to Rough Vol'] There exist $T_0$ and $C<\infty$ such that for all $T\ge T_0$ and all $\xi\in\mathbb{R}$,
\begin{equation}
\bigl|\widehat{g_T^i}(i\xi)\bigr|\le \frac{C}{1+|\xi|^{\alpha_i}} .
\end{equation}
The right-hand side lies in $L^2(\mathbb{R})$ because $2\alpha_i>1$.

[Theorem 4 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Under $\mathbb{P}_{a,b}^{<}$, the pre-$H_I$ process, the intermediate process
\[
\{X_{H_I+u}:0\leq u\leq H_S-H_I\},
\]
and the post-$H_S$ process are independent. Their laws are as follows.
\begin{enumerate}[label=\textup{(\roman*)}]
\item The pre-infimum process is the Doob transform of the process killed on leaving $(a,b)$ through the lower boundary, with
\begin{equation}
h_1(x)=
\frac{W^{(\gamma)\prime}(x-a)W^{(\gamma)}(b-a)-W^{(\gamma)\prime}(b-a)W^{(\gamma)}(x-a)}
{\bigl(W^{(\gamma)}(b-a)\bigr)^2},
\qquad a<x<b.
\end{equation}

\item The intermediate process has the law of $a+\Gamma$, where $\Gamma$ is the Doob transform of a spectrally negative L\'{e}vy process killed at $\tau_{b-a}^+\wedge\tau_0^-$, with
\begin{equation}
h_2(x)=e^{-\Phi(\gamma)(b-a-x)}\frac{W^{(\gamma)}(x)}{W^{(\gamma)}(b-a)},
\qquad 0<x<b-a.
\end{equation}

\item The post-$H_S$ process is the Doob transform of the process killed on leaving $(a,b)$ before $T$, with
\begin{equation}
h_3(x)=1-Z^{(\gamma)}(x-a)+\bigl(Z^{(\gamma)}(b-a)-1\bigr)
\frac{W^{(\gamma)}(x-a)}{W^{(\gamma)}(b-a)},
\qquad a<x<b.
\end{equation}
\end{enumerate}

