[Proposition 5 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] The distributions $\widetilde{L}_t^{\otimes p}$ satisfy a large deviation principle in the compact metric space $(\widetilde{\mathcal{X}}_{\le 1}^{\otimes p}, \mathbf{D}^{\otimes p})$ with good rate function
    \begin{equation}

    \mathcal{I}(\xi^{\otimes p}) = \begin{cases}
    \displaystyle \frac{1}{2} \sum_{i \in I} \sum_{j=1}^p \| \nabla \psi_i^j \|_2^2  & \text{if } \psi_i^j = \sqrt{\frac{\mathrm{d} \alpha_i^j}{\mathrm{d} x}} \in H^1(\mathbb{R}^d) \text{ for all } i, j \\
    \infty &\text{otherwise}.
    \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma components=critical of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] Let $\{\beta_j\}_{j=1}^{n-1}$ be the critical points of the random polynomial $P_n$. Then,
\begin{enumerate}[label=(\alph*)]
    \item $\mathscr{C}(\Lambda_n)= 1+ \left|\left\{ j: |P_n(\beta_j)| \geq 1\right \}\right|$. 

    \item All the critical points of $P_n$ are simple, i.e. $P_n''(\beta_j) \neq 0$ for all $j$ almost surely. Furthermore, $|P_n(\beta_j)| \neq 1 $ for all $j$  almost surely. In particular, 
    \begin{align*}
           \mathscr{C}(\Lambda_n)= 1+ \left|\left\{ j: |P_n(\beta_j)| > 1\right \}\right|. 
    \end{align*}
\end{enumerate}

