[Proposition lem:zeros:entropyAndMoments of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfies Assumption (as:results:fixedPoint of the paper). If $\nu \in \mathcal{S}_\kappa$, then $\nu\in \mathcal{Q}_{\kappa, d}$ and we have
    \begin{equation}

        \int_{\ensuremath{\mathbb{R}}^d} \big| \nabla \log \nu_0(x)\big|^2 \nu_0(x) dx < \infty,
    \end{equation}
    Furthermore, $\nu$ is bounded, continuous, and positive, has moments of all orders, and we have for all $x \in \ensuremath{\mathbb{R}}^d$ that  \begin{equation}
\begin{aligned}
    \nabla \log \nu_0(x) 
    &= - \nabla U(x) - \kappa \mathbb E^{\bar{\nu}}\big[ \nabla W(Y_0 - Y_1) | Y_0 = x\big].
\end{aligned}    

\end{equation}

[Lemma lem:forced_zeroes_and_remaining of arXiv:2605.03896, 'Dimer models on astroidal zig-zag graphs'] Let \((x,y)\in \mathbb{R}^2\) and let \(R\) be the cell containing \((x,y)\). Then: 
\begin{itemize}
   \item For each \(1\le j\le g\), the number of zeroes of \(\lambda_c(x,y)\) in \(A_j\) is even and at least two.
    \item For consecutive poles $\alpha,\beta \in A_0$ with \(e(\alpha)\neq
    e(\beta)\), \(\lambda_c(x,y)\) has an odd (resp. even) number of zeroes in \((\alpha,\beta)\subset A_0\) when the residues at \(\alpha\) and
    \(\beta\) have the same (resp. opposite) sign. In particular, there is at least one zero in \((\alpha,\beta)\) when its residues have {the same sign.} 
    \item For consecutive poles $\alpha,\beta \in A_0$ with $e(\alpha) = e(\beta)$ {and \(\res_\alpha(\lambda_c(x,y)) = \res_\beta(\lambda_c(x,y)) \neq 0\)}, \(\lambda_c(x,y)\) has an odd number of zeroes in $(\alpha,\beta) \subset A_0$. In particular, there is at least one zero.
\end{itemize}
The above accounts for all but possibly two zeroes of $\lambda_c(x,y)$. If \(R\subset \mathcal D_c^\circ\), there are exactly two remaining zeroes, while if \(R\subset \mathbb{R}^2\setminus \mathcal D_c^\circ\), then all zeroes are accounted for.

[Lem precise_bounds of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] Let $\alpha \in (0,2)$, $\varrho \geq 1$ and $\xi\in\mathbb{R}$.
	Let $T \in (0,1)$, $\varepsilon_1,\varepsilon_2 \in (0,T/10)$ such that $\varepsilon_2 \leq (1-T)/10$.
	Let $q$ be either $q_*$ or $q^*$ given by Lemma (construction:q_star of the paper). 
	Assume $\varrho \varepsilon_1 \geq 1$ and $\varrho(1-T)^{1-\kappa} \geq 1$.
	Then, there exist $c=c(\alpha)>0$ and $C=C(\alpha)>0$ such that
	\[
	    \mathopen{}\mathclose\bgroup\originalleft\lvertc_0(T) - c_0(0)\aftergroup\egroup\originalright\rvert
	    \leq \frac{C}{\varrho (1-T)^{1-\kappa}} 
	    \mathopen{}\mathclose\bgroup\originalleft( 
	    e^{-c \mathopen{}\mathclose\bgroup\originalleft\lvert\xi\aftergroup\egroup\originalright\rvert^{(2+\alpha)/2}}
	    + e^{-c \varrho \varepsilon_1 (1+\mathopen{}\mathclose\bgroup\originalleft\lvert\xi\aftergroup\egroup\originalright\rvert^{\alpha})}
	    \aftergroup\egroup\originalright),
	\]
	and, for any $n \geq 1$,
	\begin{align*}
	\mathopen{}\mathclose\bgroup\originalleft\lvertc_n(T)\aftergroup\egroup\originalright\rvert
	\leq C \mathopen{}\mathclose\bgroup\originalleft( \frac{1}{\varrho(1-T)^{1-\kappa}} + e^{- c\varrho T} \aftergroup\egroup\originalright)
	\mathopen{}\mathclose\bgroup\originalleft( 
	e^{-c \mathopen{}\mathclose\bgroup\originalleft\lvert\xi\aftergroup\egroup\originalright\rvert^{(2+\alpha)/2}}
	+ e^{-c \varrho \varepsilon_1 (1+\mathopen{}\mathclose\bgroup\originalleft\lvert\xi\aftergroup\egroup\originalright\rvert^{\alpha})}
	\aftergroup\egroup\originalright) 
	e^{-c \varrho \varepsilon_2 (1-T)^{-\kappa} n^{\kappa}}.
	\end{align*}

