body:
[Prop Prop_UniformlyFredholm_GenericTransversality of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let ${\mathbf{X}}$, ${\mathbf{Y}}$, and ${\mathbf{P}}$ be second-countable tame Fréchet manifolds,
  $Z$ a second-countable (finite-dimensional) manifold, and
  $f \mskip0.5mu\colon\thinspace {\mathbf{X}} \to {\mathbf{Y}}$ uniformly Fredholm.
  If $G \mskip0.5mu\colon\thinspace {\mathbf{P}} \times Z \to {\mathbf{Y}}$ is transverse to $f$,
  in particular, if it is a \defined{naive submersion};
  that is:
  $T_{(p,z)}G \mskip0.5mu\colon\thinspace T_p{\mathbf{P}} \oplus T_zZ \to T_{G(p,z)}{\mathbf{Y}}$ is surjective for every $(p,z) \in {\mathbf{P}} \times Z$,
  then the subset  
  \begin{equation*}
    {\mathbf{P}}^{\pitchfork}
    \coloneq
    \set[\big]{
      p \in {\mathbf{P}}
      :
      g_p \coloneq G(p,-) \mskip0.5mu\colon\thinspace Z \to {\mathbf{Y}} \text{ is transverse to } f
    }
  \end{equation*}
  is comeager. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm-martingale_rep of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Assume that
\[
\mathfrak{A}=\bigl( {\Omega}, {\mathscr{F}}, {\mathbb{P}}, {\mathbb{F}} \bigr), \mbox{ with } {\mathbb{F}}=({\mathscr{F}}_t)_{t\geq 0} ,
\]
is a  filtered probability space.
Assume that $\mathbf{X}$ is a separable Banach space. Denote the Borel $\sigma$-field on $\mathbf{X}$ (resp. on $\mathbf{X}\setminus\{0\}$) by $\mathscr{B}({\mathbf{X}})$ (resp. $\mathscr{B}(\mathbf{X}\setminus\{0\})$).
Assume that $M=\bigl(M(t):\; t\geq 0\bigr)$ is a square integrable $\mathbf{X}$-valued c\`adl\`ag,
purely discontinuous martingale defined on $\mathfrak{A}$.

Let $\eta_M$ be an  integer valued random measure  on  $(\mathbb{R}_+ \times \mathbf{X}\setminus\{0\},\mathscr{B}(\mathbb{R}_+) \otimes \mathscr{B}(\mathbf{X}\setminus\{0\}))$ and  $\mathfrak{A}$ associated with $M$,  defined for $\mathbb{P}$-almost every $\omega\in \Omega$ by
 \begin{equation}

\eta_M\bigl((0,t]\times A;\omega\bigr)
\coloneqq\sum_{s\in (0,t]}\1_A(\Delta M(s,\omega))
\end{equation}
for all $t\in [0,\infty)$, $A\in \mathscr{B}(\mathbf{X}\setminus\{0\})$.
\footnote{Note that $\eta_M\bigl((0,t]\times A;\omega\bigr) = \#\bigl\{s\in (0,t]: \Delta M(s,\omega) \in A \bigr\} = \sum_{s>0}\1_{(0,t] \times A}(s,\Delta M(s,\omega))$.}
Assume that  $\eta_M$ is of class \textbf{(QL)}.\\
Assume also that  $(Y,\mathscr{Y})$ is  a standard measurable space, see [Ikeda+Watanabe_1989],
 $m$ is a $\sigma$-finite non-negative measure defined  on it and
\[
\theta\colon  [0,\infty) \times Y\times \Omega \to (\mathbf{X}\setminus\{0\})^\ast\coloneqq(\mathbf{X}\setminus\{0\}) \cup \{ \partial\}
\]
is a generalized predictable process such that
\begin{equation}

\mathbb{E} \left[ \int_0^t \int_{Y} \vert \theta(s,u) \vert^2 m(\mathrm{d} u)\, \mathrm{d}s \right] < \infty.
\end{equation}
Assume finally that the compensator  $\widehat{\eta}_M$ of $\eta_M$   satisfies
\begin{equation}

\begin{aligned}
\widehat{\eta}_M\bigl((0,t]\times A;\omega\bigr)&=\int_0^t  m(\{ u \in Y: \theta(s,u,\omega) \in A\}) \, \mathrm{d}s   \mbox{ for all } t>0,\,A\in \mathscr{B}(\mathbf{X}\setminus\{0\}).
\end{aligned}
\end{equation}
Then there exists an extension
$\bigl(\tilde{\mathfrak{A}}, \pi  \bigr)$ of  $\mathfrak{A}$, where
\[
\tilde{\mathfrak{A}}=\bigl( \tilde{\Omega}, \tilde{\mathscr{F}}, \tilde{\mathbb{P}}, \tilde{\mathbb{F}}  \bigr), \mbox{ with } \tilde{\mathbb{F}}=(\tilde{\mathscr{F}}_t)_{t\geq 0} ,
\]
 and there exists a stationary $Y$-valued  Poisson point   process $\tilde{p}$ on $\tilde{\mathfrak{A}}$,
with  the  corresponding the Poisson random measure  denoted by ${\eta}_{\tilde{p}}$,  such that
\begin{trivlist}
\item[(i)] the characteristic measure of the stationary Poisson point process $\tilde{p}$ is equal to the measure $m$, and
\item[(ii)] the following equality holds for $\tilde{\mathbb{P}}$-almost every  
$\tilde{\omega}\in \tilde{\Omega}$
 \end{trivlist}
 \begin{equation}
 \begin{aligned}
M(t, \pi(\tilde{\omega}))&=
 \int_0^t \int_{Y}  \theta(s,u,\pi(\tilde{\omega}))\, \tilde{{\eta}}_{\tilde{p}}(\mathrm{d} s,\mathrm{d} u), \;\; \mbox{ for every }t\in [0,\infty).
 \end{aligned}
 \end{equation}

[Thm cor:mixing-from-other-temp of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $h_0$ such that for all $\beta'$ and all $h\ge h_0$, if $X_t$ is continuous-time Glauber dynamics run at $\beta>\beta_c$ on $\mathbb{T}_n^2$, initialized from $x_0 \sim \pi_{\beta',h}$, with probability $1-o(1)$, $x_0$ is such that 
\begin{align*}
    \|\mathbb P_{x_0}( X_t\in \cdot ) - \pi_{\mathbb{T}_n^2,\beta}^+ \| \le n^{-10}\,, \qquad \text{for all }t\in [n^{o(1)} ,  e^{\Omega( n)}]\,.
\end{align*}
The analogous infinite-volume statement as in Theorem~(thm:main of the paper) also holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 14 (Algebra-to-chaos transfer) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Under \eqref{eq:cut-majorant}, for $1\le p<\infty$ and $2\le r<\infty$,
\begin{align}

 &\norm{\cT_{\Theta(K_1,\ldots,K_N)}^{(q)}}
       _{L^p(\Omega;\Sch_r)}\notag\\
 &\qquad\le C_q(p+r)^{q/2}
 \max_{S\subset[q]}
 \sum_{T_1,\ldots,T_N}
 \mathsf M_\Theta^{(r)}(S;T_1,\ldots,T_N)
 \prod_{j=1}^N\norm{\Flat_{T_j}(K_j)}_{\Sch_r}.
\end{align}
For the same $p,r$, if $\Theta$ is same-field compatible and
$K_1,\ldots,K_N$ are symmetric
algebraic same-field inputs, the same-field version holds for
$\Theta^{\mathrm W}(K_1,\ldots,K_N)$, with $A_q$ in place of $C_q$.
Suppose, moreover, that there is $M<\infty$ such that, for all algebraic
inputs,
\begin{align*}
 \max_{S\subset[q]}
 \sum_{T_1,\ldots,T_N}
 \mathsf M_\Theta^{(r)}(S;T_1,\ldots,T_N)
 \prod_{j=1}^N\norm{\Flat_{T_j}(K_j)}_{\Sch_r}
 \le M\prod_{j=1}^N\Prof_{m_j,r}(K_j).
\end{align*}
Then $\Theta$ extends uniquely to a bounded $N$-linear map between the
corresponding simultaneous profile completions, with norm at most $M$.

[Corollary COR:LDPA of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Under $\delta_\varepsilon=\eta \sqrt{\varepsilon \log \frac 1\varepsilon}$  and $d_\varepsilon= \big|\log (\varepsilon \log \frac 1\varepsilon) \big| $, we have 
\begin{align}
&\rho_\varepsilon^Q  \big(\{   \textup{dist}(\phi, \mathcal{M}_Q^\varepsilon ) \ge \delta_\varepsilon   \} \big) \lesssim e^{-c \log \frac 1\varepsilon} \\
&\rho_\varepsilon^Q  \big(\{   \textup{dist}(\phi, \mathcal{M}_Q^{\varepsilon, <d_\varepsilon} ) < \delta_\varepsilon    \} \big)  \lesssim e^{-c \log \frac 1 \varepsilon}

\end{align}

\noindent
where $\mathcal{M}_Q^\varepsilon$, $\mathcal{M}^{\varepsilon, <d}_Q$ are approximating soliton manifolds, defined as in (equation MAN00 of the paper) and (equation MAN0 of the paper).

