body:
[Theorem thm:limit_op of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] For any $r$, $s$ and $\beta=1,2,4$,
let $\mathbf{T}_n \sim \mathtt{H}_{n,\beta}(r,s)$. Denote by \smash{$\lambda_0^{(n)} < \lambda_1^{(n)} < \cdots $} the eigenvalues
of the renormalized
\begin{equation*}
\mathbf{H}_n = \gamma^{-1/2} (rn)^{1/6} \bigl(2 \sqrt{(r+s)n} {I}_{rn} - \mathbf{T}_n \bigr),
\end{equation*}
and by $\Lambda_0 < \Lambda_1 < \cdots$ the Dirichlet eigenvalues of
$ \mathcal{H}_{\beta, \gamma}$ with the choice $\gamma = \frac{r+s}{r}$ .
Then the point process \smash{$\big\{ \lambda_0^{(n)} ,\lambda_1^{(n)} , \dots\big\}$} converges in law to $\{\Lambda_0, \Lambda_1, \dots \}
$ as $n\to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $\alpha,\mu \in \R$ and $p,q \in [1,\infty ]$. Then there exists a constant $C>0$ such that
\begin{equation*} 
\Big| \int_{\R^d} u(x)v(x)\dd x \Big| \leq C \|u\|_{\mathcal{B}_{p,q,\mu}^\alpha(\R^d)} \|v\|_{\mathcal{B}_{p',q',-\mu}^{-\alpha}(\R^d)},
\end{equation*}
where $\frac{1}{p}+\frac{1}{p'}=1$ and  $\frac{1}{q}+\frac{1}{q'}=1$ for any $u,v\in\CS(\IR^d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 35 (Bilateral sub-Gamma class) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] Let $\sigma, \alpha > 0$. A random variable $X$ belongs to the class $\SG(\sigma^2, \alpha)$ if
\begin{align}
    \E\left[e^{\lambda X}\right] \le \exp\left(\frac{\sigma^2\lambda^2}{2\left(1 - \alpha|\lambda|\right)}\right)
    \qquad \text{for all } |\lambda| < \frac{1}{\alpha}.

\end{align}

[Theorem local_limit_boundary of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Fix $\theta \in [0,\frac{1}{2})$, $\displaystyle \frac{g_n}{n} \underset{n \to +\infty}{\longrightarrow}\theta$ and $\mathbf{p}^{n} = (p^n_{1},\cdots,p^n_{\ell_n})$ such that $|\mathbf{p}^{n}| = o(n)$ and $\displaystyle \frac{|\mathbf{p}^{n}|}{\ell_n}  \underset{n \to +\infty}{\longrightarrow}+\infty$. Denote by $e^n$ a uniformly chosen oriented edge on the union $\partial_1\cup \cdots \cup \partial_{\ell_n}$ of the boundaries of $T_{n,g_n,\mathbf{p}^{n}}$. Then, the following convergence holds for the local topology
\begin{align*}
   (T_{n,g_n,\mathbf{p}^{n}},e^n) \overset{(d)}{\to}\mathbb{H}_{\lambda(\theta)},
\end{align*}
where $\lambda(\theta)$ is the unique solution to the equation 
\begin{align}
    d(\lambda(\theta)) = \frac{1-2\theta}{6}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:distinct-pair of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] If $L_w(\ell)\ge\tfrac12$, then
\begin{equation}
  s^{\times}(S)
  \le
  \frac{M_w+\binom{\ell}{2}}{2}
  -\frac{L_w(\ell)^2-L_w(\ell)}4.
\end{equation}

