[Theorem 2 (Canonical directional factorization) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] For \(s\geq0\), with extended values allowed,
\begin{equation}
 K_X(st)=\frac{V_X(t)s^2}{2}M_t(s),
 \qquad M_t(s):=\E\e^{sR_t}.
\end{equation}
For \(r\in\R\), the characteristic exponent satisfies
\begin{equation}
 \Psi_X(rt):=\log\E\e^{ir\ip{t}{X}}
 =-\frac{V_X(t)r^2}{2}\,\varphi_t(r),
 \qquad \varphi_t(r):=\E\e^{irR_t}.
\end{equation}

