body:
[Lemma 9 of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] For every $k\ge1$,
\begin{equation}
  \E|r_- -\gamma_N|^{2k}\le \frac{C}{N^k}.
\end{equation}

[Lemma lem: discrete sewing of arXiv:2609.03589, 'Correlated initialization of deep residual networks'] Suppose that \(\sigma\) satisfies Assumption (assmpt: sufficiently nice function of the paper)
    and \(\norm{w}_\alpha, \holder{g}_\beta \le R\). Let
    \(z_k = \sigma(t_k, w_{t_k}, x^\pi_k)\) for \(x^\pi_k\) and \(t_k\) as defined in Theorem (thm: convergence of euler scheme of the paper). Then, for \(0\le i<j\le n\),
    \[
        \abs[\Bigg]{\sum_{k=i}^{j-1} z_k(g_{t_{k+1}} - g_{t_k}) - z_i (g_{t_j} - g_{t_i})} 
        = \abs[\Bigg]{\sum_{k=i}^{j-1} A_{k, k+1} - A_{i,j}} 
        \le K_{\mathrm{sew}}^R (1+ \norm{x^\pi}_{\alpha,[i:j]}) \abs{t_j - t_i}^{\alpha+\beta}
    \]
    with \(K_{\mathrm{sew}}^R \coloneq \sum_{k=1}^\infty \bigl(\frac{2}{k}\bigr)^{\alpha+\beta}K_{\delta A}^R \).

[Lem 6 of arXiv:2603.29549, 'Multitype PCR branching processes'] The function $\bar F$, defined in \eqref{barF}, is $b_1$-Lipschitz with respect to the $\ell_1$-norm, and it
satisfies  
\begin{equation}
\big|F_i(\bar x)-F_i(\bar y)\big| \le b_i |x_i-y_i| +   x_i \|\bar x-\bar y\|, \quad \bar x,\bar y\in \Real_+^d,\quad i=1,\ldots,d.
\end{equation}
The $n$-th iterate of $\bar F$ admits the bound 
\begin{equation}

F^{(n)}_i (\bar x) \le b_i^n x_i, \quad \bar x\in \Real_+^d,\quad i=1,\ldots,d.
\end{equation}

[Theorem 7 of arXiv:2605.16868, '\ttl'] Under the same assumptions in Theorem \ref{thm-main}, we have
\begin{equation} 
W_1(\nu^N,\bar\nu) \to 0 \quad \mbox{in probability as } N \to \infty. 
\end{equation}
Moreover, for any function $f\colon \mathcal{D}_T\to \RR$ that is Lipschitz with respect to the uniform metric (that is, $|f(x)-f(y)| \le C\sup_{0 \le t \le T} |x(t)-y(t)|$ for all $x,y \in \mathcal{D}_T$ for some $C \in (0,\infty)$), we have
\begin{equation} 
\frac{1}{N} \sum_{i=1}^N f(\bar{Q}^N_i)\to \int_0^1 f(\bar{Q}_u)\,du \quad \mbox{ in probability as } N \to \infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm erasable loops have one plaquette assignment of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] Let $\upbeta\in \mathbb{R}$. For any non-trivial loop $\ell$, \begin{equation}
        \phi(\ell) = \sum_{K\in \mathcal{K}_{\ell}}c(\ell, K)\cdot\upbeta^{\area(K)},
    \end{equation}
    where we recall that:
    \begin{itemize}
        \item $\mathcal{K}_{\ell}$ is the canonical collection $\mathcal{K}_{\ell}$ of plaquette assignments associated with $\ell$ introduced in (defn:collection-plaquette-ass of the paper);
        \item $c(\ell, K) = \sum_{M\in \mathcal{N}\mathcal{P}\mathcal{M}(\ell,K)}w_{\infty}(M)$ are the coefficients (independent of $\upbeta$) introduced in (equation eq:coefficents of the paper);
        \item $\area(K)= \sum_{p\in \mathcal{P}}K(p)$.
    \end{itemize}
    \noindent More specifically, we have that 
    \[\phi^K(\ell)=0, \quad\text{for all } K\notin \mathcal{K}_{\ell}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l.rep_grad_psi of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Under~(i.setting of the paper), let $X_0 = \sqrt{2L_q(0)}\eta$ for a standard $\mathbb{R}^{D}$-valued Gaussian vector $\eta$ independent of everything else. Then, for every smooth increasing path $L':[0,T]\to S^{D}_+$, we have\begin{align*}
    L'(0)\cdot \alpha(0)\mathbb{E}_\eta [R(0)] + \int_0^T L'(t)\cdot \mathbb{E}_\eta[R(t)]\mathrm{d} \alpha(t) = \int_0^T L'(t)\cdot L_p(t)\mathrm{d} \alpha(t),
\end{align*}
where $\mathbb{E}_\eta$ averages over the randomness of $\eta$.

[Proposition cond_traccia_gamma of arXiv:2605.07832, 'A Bismut -Elworthy formula for BSDEs with degenerate noise'] \begin{enumerate}[\rm(i)]
\item There exists $C_B>0$ such that $|\bar B(x)-\bar B(y)|_U\leq C_B|x-y|_H$ for every $x,y\in H$.
\item If there exists a positive constant $\delta$ such that 
\begin{align}

\mu_n\sim  n^{\delta}, \qquad \delta>\frac{1}{2\varepsilon+\alpha},
\end{align}
then, $e^{tA}G(\tau)\in\mathcal L_2(U;H)$ for every $t\in(0,T]$ and every $\tau\in[0,T]$, and there exist positive constants $C_G$ and $\varepsilon_G\in\left(0,\frac12\right)$ such that (equation hyp_base1 of the paper) is satisfied.
\end{enumerate}

