[Proposition 71 (Growth of $k_i$) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] There exists $c=c(\varepsilon)>0$ such that for all $n,i\ge 1$,
\begin{equation}
\widetilde{\p}_n\bigg( k_{i+1}> k_i\Big( 1+ \frac{2}{(\log n)^\alpha}\Big) \,\bigg|\, k_i\bigg) \mathbf{1}\left\{i<S,\,k_i < \frac{\varepsilon n}{16(\log n)^{2\alpha}}\right\}
\le \exp\Big(-\frac{c k_i}{(\log n)^{2\alpha}}\Big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:pure-input of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] Let Hypothesis~(hyp:perfect-efficiency-tensorization-purity of the paper) (1) hold.  
For $j\in[N]$, set
\begin{equation}
\rho_t^{N:(j)}
  :=
  \mathrm{Tr}_{[N]\setminus\{j\}}(\rho_t^N) \qquad \mbox{ and } \qquad  \alpha_{N,j}(t)
  :=
  1-\mathrm{Tr}\bigl(\rho_t^{N:(j)}\gamma_t^j\bigr).

\end{equation}
Then, for every $T>0$, there exists a constant $C_T<\infty$, independent
of $N$ and $j$, such that
\begin{equation}
  \sup_{0\le t\le T}
  \mathbb E\bigl[\alpha_{N,j}(t)\bigr]
  \le
  \frac{C_T}{\sqrt N}.

\end{equation}
Consequently, for every fixed $n\ge1$,
\begin{equation}
  \sup_{0\le t\le T}
  \mathbb E\left[
    \left\|
      \rho_t^{N:n}-\Gamma_t^n
    \right\|_1
  \right]
  \le
  2\sqrt{nC_T}\,N^{-1/4}.

\end{equation}

[Theorem 21 of arXiv:2605.25715, '2605.25715'] {\cite[Corollary 4.4.7]{HJ91}}  
Let $A \in M_{d}(\mathbb{R})$ be symmetric and positive definite. Let $G \in M_d(\mathbb{R})$ and $\sigma(G) = \{ \lambda_1, \dots, \lambda_d \} \subset \mathbb{C}$ be the set of eigenvalues of $G$ counting multiplicities.  Assume that
\begin{equation} 
    \lambda_i + \lambda_j \neq 0 \quad \text{for all } 1 \leq i, j \leq d.
\end{equation}
Then there exists a unique solution $P$ satisfying the Lyapunov equation:
\begin{equation} 
    GP + PG^T = -2A.
\end{equation}
In particular, $P$ is given explicitly by:
\begin{equation} 
\text{\rm Vec}(P) = - (I \otimes G + G \otimes I)^{-1} \text{\rm Vec}(2A).
\end{equation}
where   $\text{Vec}$ and $\otimes$ are defined as in Definitions \ref{vectorizdefn}, \ref{tensorproducde}, respectively.
Moreover, $P$ is symmetric and invertible.

