body:
[Lemma 165 (Decomposition of various components of the energy-momentum tensor) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $f$ be a scalar function, and let $\enmomem$ be the corresponding energy-momentum tensor
	defined in \eqref{E:DEFOFENERGYMOMENTUM}.
	Then the following identities hold:
	\begin{subequations}
		\begin{align}
			\enmomem[f](\Lunit,\Lunit) & = (\Lunit f)^2, 

			\\
			\enmomem[f](X,\Lunit) 
			& = 
			- \frac{1}{2} (\Lunit f)^2 + \frac{1}{2} | \angD f|_{\gtorus}^2, 

			\\
			\enmomem[f](X,X) 
			& = \frac{1}{2} (\Lunit f)^2 + (\Lunit f) Xf + (X f)^2 - \frac{1}{2} |\angD f|_{\gtorus}^2. 
		\end{align}
	\end{subequations}
	Moreover, the following identities also hold: 
	\begin{subequations}
		\begin{align}
			\enmomem[f](\multipliervectorfield,\Lunit) 
			& 
			= (1 + \upmu)(\Lunit f)^2 + \upmu |\angD f|^2_{\gtorus}, 

			\\
			\enmomem[f](\multipliervectorfield,\newuL) & = 2  (\newuL f)^2 + 2  \MagnitueofinnerproductofnewLandnewuL \ToriTangentVectorfieldAssociatedToDoubleNullFolliations f (\newuL f) + \frac{1}{2} \left( \upmu + 2 \upmu \ReciprocaluLunitAppliedtoTimeFunction\right) | \nullangrmD f|^2_{\gnulltori}, 
		\end{align}
	\end{subequations}
	where $\ToriTangentVectorfieldAssociatedToDoubleNullFolliations$ is as in \eqref{E:TORITANGENTVECTORFIELDASSOCIATEDTODOUBLENULLFRAME}.

