[Lem sturm-liouville of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] \begin{enumerate}
		\item For any $n \geq 0$, $\varphi_n$ is convex and decreasing in $[\lambda_n^{1/\alpha},\infty)$;

		\item For any $n \geq 0$, $\varphi_n$ and $\varphi_n'$ tend to zero at infinity;

		\item There exists $C = C(\alpha) >0$ such that, for any $n \geq 0$, $\mathopen{}\mathclose\bgroup\originalleft\lVert\varphi_n\aftergroup\egroup\originalright\rVert_\infty \leq C (n+1)^{\alpha/[2(2+\alpha)]}$.
	\end{enumerate}

