[Lemma lemma-4.6 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let~$\beta>0$ and assume that~$\{v_k'\}_{k=0}^n$ and~$\{v_k''\}_{k=0}^n$ are bounded uniformly in~$n\ge1$. Then for all $n\ge1$ and all $k=0,\dots,n$,
\begin{equation}

\sum_{i=k}^n E\bigl[v_{i}'(\phi_{i+1})^2-v_{i}''(\phi_{i+1})\bigr]
=-b\sum_{i=k}^n E\bigl(v_{i}'(\phi_{i+1})^2\bigr) + O(1),
\end{equation}
where~$O(1)$ is bounded uniformly in~$n\ge k\ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 26 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] The difference
		\begin{equation}
			\zeta_{\pLie}(s)
			-\frac{C_{G,L}}{\Gamma(s)}
			\sum_{\ell=0}^{\infty}
			\frac{\beta_{G,L}^{\ell}}
			{\ell!\,(s-Q/2+\ell)}
		\end{equation}
		is entire. Hence
		\begin{equation}
			\operatorname*{Res}_{s=Q/2-\ell}\zeta_{\pLie}(s)
			=\frac{C_{G,L}\beta_{G,L}^{\ell}}
			{\ell!\,\Gamma(Q/2-\ell)}
		\end{equation}
		whenever $Q/2-\ell$ is not a nonpositive integer. If $Q/2\in\mathbb N_0$, the only possible poles are the simple poles at
		\[
		s=1,\ldots,Q/2.
		\]
		Some of them may disappear when the corresponding local coefficient vanishes. In this case,
		\begin{align}
			\zeta_{\pLie}(0)
			&=C_{G,L}\frac{\beta_{G,L}^{Q/2}}{(Q/2)!}-1,
			\\
			\zeta_{\pLie}(-j)
			&=(-1)^j j!C_{G,L}
			\frac{\beta_{G,L}^{Q/2+j}}{(Q/2+j)!},
			\qquad j\ge1.

		\end{align}
		If $Q/2\in\frac12+\mathbb N_0$, then
		\begin{equation}
			\zeta_{\pLie}(0)=-1,
			\qquad
			\zeta_{\pLie}(-j)=0\quad(j\ge1).
		\end{equation}

