body:
[Lemma tower of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] \begin{enumerate}[label=(\arabic*)]
Let $Q_n$ be the queuing process defined in (construction of the paper) and set $c = x\left(1-x\right)$. Then:
\item For any $n \geq 1$,
    \begin{equation}
        \mathbb{E}_{x}\left[Q_{n+1} - Q_1\right] = c\sum_{i=1}^{n} \mathbb{E}_x\left[q^{Q_i}\right].
    \end{equation}
\item  For any integer $k\geq1$,
    \begin{equation}
        \mathbb{E}_x\left[q^{k Q_1}\right] = \left(q;q\right)_{k}.
    \end{equation}
\item For any integer $k \geq 1$,
    \begin{equation}
        \mathbb{E}_{x}\left[q^{k Q_{n+1}}\right] = \left(1 + c a_k\right) \mathbb{E}_{x}\left[q^{k Q_{n}}\right] + c b_k \mathbb{E}_{x}\left[q^{\left(k+1\right) Q_{n}}\right],
    \end{equation}
    where 
    \[
    a_k = q^k + q^{-k} - 2, \quad b_k = 1 - q^{-k}.
    \]
\end{enumerate}

