[Proposition 6 of arXiv:2607.04012, 'Hölder regularity for backward stochastic Volterra integral equations and applications to '] For every $2\leq\lambda\leq q$ and every $\theta\in[0,T]$, there exists a constant $C>0$, independent of $\pi$ and $\theta$, such that
    \begin{flalign*}
        \mathbb{E} \Bigg[
        \bigg( 
        \int_{0}^{T} 
        |D_\theta Y^{\pi}(\tau(t),t)|^2\,dt 
        \bigg)^{\frac{\lambda}{2}}
        +
        \bigg(
        \sum_{k=0}^{N-1}
        \Delta_k
        \int_{t_{k+1}}^T 
        |D_\theta Z^{\pi}(t_k,s)|^2\,ds
        \bigg)^{\frac{\lambda}{2}}
        \Bigg] 
        \leq
        C \big(
        \norm{D_\theta \Psi^\pi}_{2,\lambda}^{\lambda}
        +
        \norm{\mathcal G_\theta^{1,\pi}}_{\mathcal{H}_{\Delta}^{\lambda}}^{\lambda}
        \big).
    \end{flalign*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] We say that	a centered Gaussian random element $h\colon\Omega\to \mathcal S'(K)$ is a \emph{fractal Gaussian free field} (FGFF) on $K$  if its covariance is given by
	 \begin{equation}
		 \mathbb E[\langle h,u\rangle \langle h,v\rangle]=\int_K\int_{K} k_{d_S}(x,y)u(x)v(y)\, d\mu(x)\, d\mu(y)
     \end{equation}
     for all $u,v\in \mathcal S(K)$.

[Definition def:regeneration of arXiv:2608.15344, 'A Harris recurrent continuous-time Markov process without wide-sense regenerative structur'] The process $X$ is said to be \textit{wide-sense regenerative} if there exist randomized stopping times $0\leq R_0<R_1<\dots<\infty$ such that:
\begin{enumerate}[label=(\roman*)]
    \item for each $n\geq0$, $\Theta_{R_n}X$ is independent of $R_n$;
    \item $\Theta_{R_n}X$ is identically distributed in $n$.
\end{enumerate}

[Prop symmetric-monoidal-LKE of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let ${\mathcal{C}}^\otimes$ be globally presentably symmetric monoidal. Then the restriction 
    $i^{*}_\otimes\colon{\textup{Fun}}^\otimes({N_\textup{top}}(\textbf{\textup{L}}^{\oplus,\flat}),{\mathcal{C}}^\otimes)\rightarrow{\textup{Fun}}^\otimes(\textup{const}\,{N_\textup{top}}(\textbf{\textup{L}}^\oplus),{\mathcal{C}}^\otimes)$
    admits a left adjoint $\smash{i_!^\otimes}$, and the Beck--Chevalley map $\smash{i_!\circ\textup{fgt}\to\textup{fgt}\circ i_!^\otimes}$ associated to
    \[
        \begin{tikzcd}
            {\textup{Fun}}^\otimes({N_\textup{top}}(\textbf{\textup{L}}^{\oplus,\flat}),{\mathcal{C}}^\otimes)\arrow[r,"i^*_\otimes"]\arrow[d,"\textup{fgt}"'] & {\textup{Fun}}^\otimes(\textup{const}\,{N_\textup{top}}(\textbf{\textup{L}}^\oplus),{\mathcal{C}}^\otimes)\arrow[d,"\textup{fgt}"]\\
            {\textup{Fun}}({N_\textup{top}}(\textbf{\textup{L}}^\flat),{\mathcal{C}})\arrow[r,"i^*"'] & {\textup{Fun}}(\textup{const}\,{N_\textup{top}}(\textbf{\textup{L}}),{\mathcal{C}})
        \end{tikzcd}
    \]
    is an equivalence.
    \begin{proof}
        We may identify the diagram in question with
        \begin{equation}
            \begin{tikzcd}
                {\textup{Fun}}^{\text{L},\otimes}(\ul\PSh({N_\textup{top}}(\textbf{\textup{L}})^\flat)^\otimes,{\mathcal{C}}^\otimes)\arrow[r]\arrow[d,"\textup{fgt}"'] & {\textup{Fun}}^{\text{L},\otimes}(\ul\PSh(\textup{const}\,{N_\textup{top}}(\textbf{\textup{L}}))^\otimes,{\mathcal{C}}^\otimes)\arrow[d,"\textup{fgt}"]\\
                {\textup{Fun}}^\text{L}(\ul\PSh({N_\textup{top}}(\textbf{\textup{L}})^\flat),{\mathcal{C}})\arrow[r] & {\textup{Fun}}^\text{L}(\ul\PSh(\textup{const}\,{N_\textup{top}}(\textbf{\textup{L}})),{\mathcal{C}})\rlap,
            \end{tikzcd}
        \end{equation}
        where the top and bottom horizontal arrow are given by precomposing with the symmetric monoidal global left adjoint $L^\otimes\colon\ul\PSh(\textup{const}\,{N_\textup{top}}(\textbf{\textup{L}}))^\otimes\to\ul\PSh({N_\textup{top}}(\textbf{\textup{L}}^\flat))^\otimes$ induced by the inclusion and its underlying global functor $L\colon\smash{\ul\PSh(\textup{const}\,{N_\textup{top}}(\textbf{\textup{L}}))}\to\smash{\ul\PSh({N_\textup{top}}(\textbf{\textup{L}}^\flat))}$, respectively. The latter admits a right adjoint $R$ (namely, the restriction functor) which is again globally cocontinuous, and the left adjoint to the bottom arrow in the above diagram is then given by precomposing with $R$, with unit and counit again given by precomposition. If we can show that $L\dashv R$ upgrades to a symmetric monoidal adjunction $L^\otimes\dashv R^\otimes$, then a left adjoint to the top horizontal arrow in $((diag:too-many-forgetful-functors of the paper))$ will be similarly given by precomposing with $R^\otimes$ and with unit and counit given analogously, which then clearly satisfies the Beck--Chevalley condition.

        For this we will verify the assumptions of Proposition~(prop:Day-restriction of the paper). As observed in the proof of the previous corollary, each ${\textup{triv}}_G\colon{N_\textup{top}}(\textbf{\textup{L}}^\flat)(1)\to{N_\textup{top}}(\textbf{\textup{L}}^\flat)(\mathbb B{G})$ is fully faithful and has a right adjoint induced by taking $G$-fixed points. Unravelling the definitions, the Beck--Chevalley condition amounts to saying that $V^G\oplus W^G\hookrightarrow V\oplus W$ defines an isomorphism onto $(V\oplus W)^G$, which is obvious.
    \end{proof}

