[Corollary 48 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let $A,B,\{A_k\}_{k \in \Nbb}, \{B_k\}_{k \in \Nbb} \in \Sym(\Hcal) \cap \HS(\Hcal)$ be such that $I + A > 0$, $I+B > 0$, $I+A_k > $, $I+B_k > 0$ $\forall k \in \Nbb$. Assume that
	$\lim_{k \approach \infty}||A_k - A||_{\HS} = 0$, $\lim_{k \approach \infty}||B_k - B||_{\HS} = 0$. Then
	\begin{align}
		&\lim_{k \approach \infty}||(I+B_k)^{-1/2}(I+A_k)(I+B_k)^{-1/2} 
		\nonumber
		\\
		& \quad \quad \quad - (I+B)^{-1/2}(I+A)(I+B)^{-1/2}||_{\HS} 
		\\
		&= \lim_{k \approach \infty}||(I+B_k)^{-1/2}(A_k-B_k)(I+B_k)^{-1/2} 
		\nonumber
		\\
		&\quad \quad \quad - (I+B)^{-1/2}(A-B)(I+B)^{-1/2}||_{\HS}
		= 0.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] For any $\alpha,\mu\in\IR$ and $m,\delta_1,\delta_2>0$, we have
\begin{equation}
\|\SU_{\le} f\|_{\CC_{-\mu-m\delta_1}^{\alpha+\delta_1}}\lesssim\|f\|_{\CC_{-\mu}^\alpha}\quad\text{and}\quad\|\SU_>f\|_{\CC_{-\mu+m\delta_2}^{\alpha-\delta_2}}\lesssim\|f\|_{\CC_{-\mu}^\alpha}
\end{equation}
where the constant depends on the parameters $\alpha,\mu,\delta_1,\delta_2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

