[Proposition 5 (Lamperti reduction) of arXiv:2608.08177, 'Uniform-in-Time Smoluchowski--Kramers Approximation\\ in Total Variation for Fractional SD'] Let \Cref{ass:smooth} hold and set
\[
  Z_t^\mu=F(X_t^\mu),\qquad
  U_t^\mu=\frac{Y_t^\mu}{\sigma(X_t^\mu)},
  \qquad z_0=F(x_0),\quad
  u_0=\frac{y_0}{\sigma(x_0)}.
\]
Then \eqref{eq:kinetic-original} is equivalent to
\begin{equation}
\begin{cases}
 dZ_t^\mu=U_t^\mu\,dt,\\[1mm]
 \mu\,dU_t^\mu
 =\bigl(a(Z_t^\mu)-U_t^\mu
        -\mu c(Z_t^\mu)(U_t^\mu)^2\bigr)dt+dB_t^H,\\[1mm]
 Z_0^\mu=z_0,\qquad U_0^\mu=u_0.
\end{cases}
\end{equation}
Moreover, $Z_t=F(X_t)$ solves
\begin{equation}
  Z_t=z_0+\int_0^t a(Z_s)\,ds+B_t^H.
\end{equation}
Finally,
\begin{equation}
  d_{\TV}(\Law(X_t^\mu),\Law(X_t))
  =d_{\TV}(\Law(Z_t^\mu),\Law(Z_t)).
\end{equation}

[Proposition 1 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $\kappa\in (0,4]$ and $n\ge 1$ and $\ell\in\Z$. 
Fix $r>0$ and $\bs{\alpha}, \bs{\beta}\in\LX_n$. For $1\le j\le n$, let $\gamma^j$ be annulus $\SLE_{\kappa}(\LFcro{1}^{(\kappa;\ell)})$ in $(\A_r;\ee^{\ii \alpha_j};\ee^{\ii \beta_j-r})$. 
Let $\Pind{n}^{(\kappa;\ell)}=\Pind{n}^{(\kappa;\ell)}(\A_r; \ee^{\ii\bs{\alpha}}, \ee^{\ii\bs{\beta}})$ be the probability measure on $\bs{\gamma}=(\gamma^{1}, \ldots, \gamma^{n})$ under which the curves are independent.
Define $\LFcro{n}^{(\kappa; \ell)}(r; \bs{\alpha}, \bs{\beta})$ as in~\eqref{eqn::multiannulus_pf_def}: 
\begin{align*}
\LFcro{n}^{(\kappa; \ell)}(r; \bs{\alpha}, \bs{\beta})=\prod_{j=1}^n\LFcro{1}^{(\kappa;\ell)}(r; \alpha_j, \beta_j)\times \Eind{n}^{(\kappa;\ell)}\left[\one_{\LE_{\emptyset}(\bs{\gamma})}\exp\left(\frac{\mathfrak{c}}{2}\blm(\A_r; \gamma^1, \ldots, \gamma^n)\right)\right],
\end{align*}
where $\LE_{\emptyset}(\bs{\gamma}) = \{ \gamma^{j} \cap \gamma^{i}=\emptyset, \, \forall i\neq j\}$ is the event that different curves are disjoint, and $\blm$ is the Brownian loop measure defined in~\eqref{eqn::blm_def}. 
\begin{itemize}
\item The partition function $\LFcro{n}^{(\kappa; \ell)}$ is smooth and it satisfies annulus BPZ equations~\eqref{eqn::annulus_BPZ_alpha}-\eqref{eqn::annulus_BPZ_beta} with
\begin{equation} 
F(r)=	F_n(r):=\frac{6\tilde{\mathfrak{b}}-\mathfrak{b}}{r} + 6 \tilde{\mathfrak{b}} \LE(r) + \mathfrak{b} n. 
\end{equation} 
\item Define $\LFcro{n}^{(\kappa)}(r; \bs{\alpha}, \bs{\beta})$ as in~\eqref{eqn::multiannulus_withoutspiral_def}:
\begin{align*}
\LFcro{n}^{(\kappa)}(r; \bs{\alpha}, \bs{\beta})=\sum_{\ell\in\Z}\LFcro{n}^{(\kappa;\ell)}(r; \bs{\alpha}, \bs{\beta}).
\end{align*}
Then there exists a constant $C=C(n)\in (0,\infty)$ independent of $(r; \bs{\alpha}, \bs{\beta})$ such that
\begin{align}
\LFcro{n}^{(\kappa)}(r; \bs{\alpha}, \bs{\beta})\le C\exp\left(\left(n\mathfrak{b}-\frac{(8-\kappa)}{\kappa}\right)r+\left(\frac{3\kappa}{2}-2n\right)\mathfrak{b}\log r\right). 
\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:WP of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [FSmap]
The \emph{pertubative RG map} for $V_j \in \cV$ is
\begin{align}
	\Phi_{j+1}^{\operatorname{pt}} : V_j \mapsto \E_{j+1} \theta V_{j} - P_{j,V}  ,

\end{align}
where $P_{j,V}$ is a polymer function of degree $\le 6$ that is a quadratic form of $V$ as defined in [FSmap] and satisfies bound Lemma~(lemma:FWPbounds3obs of the paper).  We also denote
\begin{align}
	U_{j+1}^{{\operatorname{pt}}} = \Phi_{j+1}^{\operatorname{pt}} (V_j)  ,\qquad V_{j+1}^{{\operatorname{pt}}} = (1- \pi_0 - \pi_{\sf ox}) U_{j+1}^{{\operatorname{pt}}} 
\end{align}
(recall Section~(sec:effpotes of the paper) for $\pi_0$ and $\pi_{{\sf ox}}$).

For $Q_j \in \cV$ defined as in [FSmap] (as a function of $(V_j, K_j)$),  let $\widehat{V}_j = V_j - Q_j$ and
\begin{align}
	\Phi_{j+1}^U (V_j, K_j) = \mathbb{V}^{(0)} \Phi_{j+1}^{\operatorname{pt}} (\widehat{V}_j ) .
\end{align}

[Lem deter_lemma:no_sausages of arXiv:2601.00119, 'The largest common subtree of two random trees'] If $B_n^{(1)}$ occurs and if $n$ is large enough so that $14\max(c,n^{1/2-\alpha})<\tilde{\delta}\sqrt{n}$, then there exist $w \in \tau$,  $w'\in \tau'$, and $0\leq k\leq \mathrm{Ht}(\tau)-1$ such that at least one of the following two events happens:
\begin{enumerate}
\item[\emph{(i)}] $\displaystyle{\Bigg|ck- \!\sum_{\substack{\varnothing \prec x\preceq w \\ \varnothing \prec x'\preceq w'}}\! {\mathbf 1}_{\left\{|w|-|x|=|w'|-|x'|<k\right\}} \operatorname{LCS}^\bullet\left(\operatorname{Trim}_{x}\tau,\operatorname{Trim}_{x'}\tau'\right)\wedge n^{1/2-\alpha}\Bigg|>\tfrac{\tilde\delta}{14} \sqrt{n} }$;
\item[\emph{(ii)}] $\displaystyle{\Bigg|ck- \!\sum_{\substack{\varnothing \prec x\preceq w \\ \varnothing \prec x'\preceq w'}}\! {\mathbf 1}_{\left\{|w|-|x|=k-1-(|w'|-|x'|)<k\right\}} \operatorname{LCS}^\bullet\left(\operatorname{Trim}_{x}\tau,\operatorname{Trim}_{x'}\tau'\right)\wedge n^{1/2-\alpha}\Bigg|>\tfrac{\tilde\delta}{14} \sqrt{n} }$.
\end{enumerate}

