[Lemma 20 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$ and $0 = t_0 < t_1 < \dots < t_m$. Then, for any $0 \le \theta \le d$ and $0 = x_0, x_1 , \dots , x_m \in \mathbb{R}^d$,
    \begin{equation}

        \mathbb{E} \left[ \prod_{i=1}^m \delta(W (t_i) - x_i) \right] \le C^m \prod_{i=1}^m |t_i - t_{i-1}|^{-(d-\theta)/2} \prod_{i=1}^m |x_i - x_{i-1}|^{-\theta}.
    \end{equation}
    Similarly, if $k < d$ and $0 \le \theta \le k/2$,
    \begin{equation}

        \mathbb{E} \prod_{i=1}^m |W (t_i) - x_i|^{-k} \le C^m \prod_{i=1}^m |t_i - t_{i-1}|^{-(k-\theta)/2} \prod_{i=1}^m |x_i - x_{i-1}|^{-\theta}.
    \end{equation}

