[Lemma 32 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] (Properties of symmetric and positive semi-definite matrices)
Let $A, B \in \mathcal{M}_{d}(\mathbb{R})$, $d \in \mathbb{N}$, symmetric and positive semi-definite matrices.
	Then it holds

\begin{enumerate}

\item 														
\begin{equation}
\lambda_{min}(A) \trace(B) \leq \trace(AB)  \leq  \lambda_{max}(A) \trace(B)
\end{equation}
where $\lambda_{min}(A)$  and $\lambda_{max}(A)$ denote the smallest and largest eigenvalue
	of A, respectively.

	\item  \begin{equation} 
	\dfrac{\trace(B)}{ \trace\left( A^{-1} \right)} \leq   \trace(AB) \leq \trace(A)  \trace (B) 
						\end{equation}														
where for the first inequality A is assumed to be positive definite.

\item \begin{equation}
	\trace^2(A)  \geq \trace\left( A^2 \right) \geq  \dfrac{1}{d} \trace^2 (A)
\end{equation}

\item  \begin{equation}				\vert A\vert_F = \sqrt{\trace\left( A^2 \right)}  \leq \trace(A)
						\end{equation}
			where $\vert A\vert_F$  denotes the Frobenius norm of A.
					\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Teorema 15 of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $ T\in S_m(M,M')$ and $ T'\in S_m(M',M'')$ be two stochastic transformations and $ SDE_{\mu,\sigma}$ be a non-explosive stochastic differential equation such that $ E_{T}(\mu,\sigma)$ and $ E_{T'}(E_{T}(\mu,\sigma))$ are non-explosive.  Given  a weak solution $(X,W)$  to $ SDE_{\mu,\sigma}$ in the probability space $ (\Omega, \mathcal{F}, \mathbb{P})$, then in the probability space $\ (\Omega, \mathcal{F}, \mathbb{Q})$

    it holds that 
    \begin{equation*} P_{T'}\circ P_{T}(X,W) = P_{T' \circ T}(X,W); \ \ \ \ \ \  E_{T'} \circ E_T (\mu,\sigma)= E_{T' \circ T}(\mu,\sigma) \end{equation*}

[Lemma lem: transposition of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Consider $I_k:=\{1,\ldots,k\}$, $I^i_{k}:=\{1,\ldots,i-1,i+1,\ldots,k\}$ and $\tau_1,\ldots,\tau_k\in{\mathcal T}$. Setting $w=\tau_1\cdots\tau_k$, the following identity holds true:
		\begin{align} 
			\sum_{i=1}^k\frac{1}{\pi(\tau_i; w)}\sum_{q\in{\mathcal P}(I^i_k,\boldsymbol{\tau}^i)}\tau_i\otimes\tau_{q(1)}\otimes\ldots\otimes\tau_{q(i-1)}\otimes&\tau_{q(i+1)}\otimes\ldots\otimes\tau_{q(k)}\nonumber
			\\&=\sum_{p\in{\mathcal P}(I_k,\boldsymbol{\tau})}\tau_{p(1)}\otimes\ldots\otimes\tau_{p(k)}\,,
		\end{align}
		where ${\mathcal P}(\cdot)$ is as in Definition (Def: sym H of the paper) and $\pi(\tau_i;w)$ is the number of trees equal to $\tau_i$ in the forest $w$ i.e. for $w=\hat\tau^{\ell_1}_1\cdots\hat\tau_r^{\ell_r}$ such that $\hat\tau_i\ne\hat\tau_j$ for $i\ne j$, we have $\pi(\tau_i;w)=\ell_i$.

