[Prop degree-times-n of arXiv:2510.18856, 'Evolution of recursive trees with limited memory'] Let $\left(\left(\mathscr{E}_{j,k}\right)_{k\geqslant 1}: j\geqslant 0\right)$ be \emph{iid} copies of $\left(\mathscr{E}_{k-1\leadsto k}\right)_{k\geqslant 1}$. Then, as $n \to \infty$,\begin{align*}
 \left(\left(\tau_{j,k}^n\right)_{k\geqslant 1}: j\geqslant 0\right) \stackrel{d}{\longrightarrow} \left(\left(\mathscr{E}_{j,k}\right)_{k\geqslant 1}: j\geqslant 0\right).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p: gaussian mixing of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d, 2]$. Assume that $Z$ is a Gaussian random field and assume that $Z$ and $\Phi$ are independent. Further, assume that
    \begin{equation}
        \int \frac{\big\|\BC[Z(y), Z(0)]\big\|}{1 + \|y\|^{2-p}}\,\alpha_\Phi(dy) < \infty,
    \end{equation}
    where the covariance is the full covariance matrix.
    Then $\Psi$ is $p$-uniform if $\Phi$ is, and if $p<2$, then beyond $p$-uniformity also transfers. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:AC-identities of arXiv:2607.29330, 'Large deviations for the maximum of\\ the generalized TAP free energy'] For the process~(equation eq:AuffingerChen of the paper), the following identities hold.
		\begin{enumerate}[label=\textup{(\roman*)}]
			\item $M_t$ is a martingale and
			\begin{equation}
				\mathrm{d} M_t
				=\sqrt{\xi''(t)}\,\partial_{xx}\Phi_\zeta(t,X_t)\,\mathrm{d} B_t .
			\end{equation}

			\item The Parisi value along the optimal trajectory satisfies
			\begin{equation}
				\mathrm{d}\Phi_\zeta(t,X_t)
				=\frac12\zeta([0,t])\xi''(t)M_t^2\,\mathrm{d} t
				+\sqrt{\xi''(t)}M_t\,\mathrm{d} B_t .
			\end{equation}
			Equivalently, for $s<t$,
			\begin{equation}
				\Phi_\zeta(t,X_t)-\Phi_\zeta(s,X_s)
				=\frac12\int_s^t\zeta([0,r])\xi''(r)M_r^2\,\mathrm{d} r
				+\int_s^t\sqrt{\xi''(r)}M_r\,\mathrm{d} B_r .
			\end{equation}

			\item For $s<t$,
			\begin{equation}
				\mathbb{E}\bigl[(X_t-X_s)M_s\bigr]
				=\mathbb{E}[M_s^2]\int_s^t\zeta([0,r])\xi''(r)\,\mathrm{d} r,
			\end{equation}
			and
			\begin{equation}
				\mathbb{E}\bigl[(M_t-M_s)X_s\bigr]=0 .
			\end{equation}

			\item Suppose that
			\(\mathbb{E}[M_r^2]=r\) for \(\zeta\)-a.e.\ \(r\in[0,1]\).
			If \(s,t\in\mathrm{supp}(\zeta)\cap[0,1)\) and
			\(\zeta((s,t))=0\), then
			\begin{equation}
				\mathbb{E}\bigl[(M_t-M_s)(X_t-X_s)\bigr]
				=\bigl(\xi'(t)-\xi'(s)\bigr)\int_s^1\zeta([0,r])\,\mathrm{d} r .
			\end{equation}
			Consequently,
			\begin{equation}
				\mathbb{E}\bigl[M_t(X_t-X_s)\bigr]
				=\bigl(\xi'(t)-\xi'(s)\bigr)
				\left(\zeta([0,s])\,t+\widehat\zeta(t)\right),
			\end{equation}
			where in the last display we used $\zeta((s,t))=0$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

