body:
[Lemm 14 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Suppose the FBSDE \eqref{fbsde:equ:re} satisfies all the following conditions: 
    \begin{itemize}
        \item[(a)] Assumption~\ref{coefficient:assume:general}, Assumption~\ref{fbsde:basic:assume:p:general} and Assumption~\ref{ass:linear:diffusion} hold with $p = 2$.
        \item[(b)] The equation admits a regular decoupling field $w$ with $L_w L_{\mu,3} < 1$.
    \end{itemize}
    Then, there exists a constant $\ol{\dz}>0$ such that,
    for any partition $t = t_0 \leq t_1\leq\cdots\leq t_n = T$ satisfying $t_{i + 1} - t_i \leq \ol{\dz}$, 
    there exists a sequence of measurable functions $\{w^{\vz,i}\}^n_{i = 0}$ satisfying the following properties:
    For each $i\in\{0,1,\dots,n\}$, the following hold
    \begin{itemize}
        \item[(1)] Coupling Consistency:
        $w^{\vz,i}(\cdot,x)\in \cC_{\vz,0}(w(t_i,\cdot,x))$ for any $x\in\R^n$;
        \item[(2)] Lipschitz Continuity:
        For all $x,y\in\R^n$ and $\oz\in\Oz$,
        \begin{equation}
            |w^{\vz,i}(\oz,x) - w^{\vz,i}(\oz,x)| \leq L_w |x - y|;
        \end{equation}
        \item[(3)] Existence and Uniqueness of Local FBSDE Solution:
        For any $\ol{\xi}\in \cL^2(\cF^{\ol{W}}_{t_i})$,
        where $\ol{W} := 
        \begin{pmatrix}
        W \\
        W'
        \end{pmatrix}$,
        the following FBSDE
    \begin{align}
    \begin{cases}
        \ol{X}_s = \ol{\xi} + \int^s_{t_i} \ol{b^{\vz}}(u,\ol{X}_u,\ol{Y}_u,\ol{Z}_u)\,\od u + \int^s_{t_i} \ol{\sz^{\vz}}(u,\ol{X}_u,\ol{Y}_u,\ol{Z}_u)\,\od \ol{W}_u;\\
        \ \\
        \ol{Y}_s = w^{\vz,i}(\ol{X}_{t_{i + 1}}) + \int^{t_{i + 1}}_s \ol{f^{\vz}}(u,\ol{X}_u,\ol{Y}_u,\ol{Z}_u)\,\od u - \int^{t_{i + 1}}_s \ol{Z}_u\,\od \ol{W}_u
    \end{cases}
    \end{align}
    admits a unique solution $(\ol{X}^{\ol{\xi},[t_i,t_{i + 1}]},\ol{Y}^{\ol{\xi},[t_i,t_{i + 1}]},\ol{Z}^{\ol{\xi},[t_i,t_{i + 1}]})$
    where the coefficients $(\ol{b^{\vz}},\ol{\sz^{\vz}},\ol{f^{\vz}})$ is defined as in \eqref{coefficients:couple};
    \item[(4)] Decoupling Field Property:
    The solution in $(3)$ satisfies,
    for any $\ol{\xi}\in \cL^2(\cF^{\ol{W}}_{t_i})$,
    \begin{equation}
        \ol{Y}^{\ol{\xi},[t_i,t_{i + 1}]}_{t_i} = w^{\vz,i}(\ol{\xi})\quad \P-a.s.;
    \end{equation}
    \item[(5)] Structure of $\ol{Z}$:
    The solution in $(3)$ satisfies,
    there is a $\R^{m\times d}$ predictable process $\wt{Z}\in \cL^{2,2}$ such that 
    $$\ol{Z} = (\sqrt{1 - (\vz(\cdot))^2}\,\wt{Z}, \vz(\cdot)\wt{Z}).$$
    \end{itemize}

[Theorem MHnp1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] The handover frequency in multi-speed case with set of speeds $v_{[n]}$ is given by:

\begin{enumerate}
\item  The pure handover frequencies are 
\begin{equation}
     \Lambda_i= \frac{4v_i\sqrt{\lambda}}{\pi}\left(\frac{\lambda_i}{\lambda}\right)^2, \text{ for }i\in [n].
\end{equation}
\item   For any pair $i\neq j\in [n]$, the mixed handover frequencies satisfies, $\Lambda^{(1)}_{i,j}=\Lambda^{(2)}_{j,i}$ and $\Lambda^{(2)}_{i,j}=\Lambda^{(1)}_{i,j}$.

\item    For any pair $j<i\in [n]$ and $k\in \{1,2\}$, 
\begin{align}
\Lambda^{(k)}_{i,j}&= 4\lambda_i\lambda_j v_i v_j\int_{0}^{\infty}\left[\int_0^{h_j}\int_{t^*}^\infty e^{-\lambda\pi\hat h^2_k(t, h_j, h_i)}   \,{\rm d}t \, {\rm d}h_i +\int_{h_j}^{\infty}\int_{0}^{\infty} e^{-\lambda\pi\hat h^2_k(t, h_j, h_i)}   \,{\rm d}t \, {\rm d}h_i\right] {\rm d}h_j,

\end{align}

\end{enumerate} 
where 

\[
\hat h^2_k(t, h_j, h_i)= v_j^2 \left(\frac{v_i^2 t+ (-1)^k \Delta^{{\frac{1}{2}}}_{i,j}}{v_j^2-v_i^2}\right)^2\!\!\!\!{+} h_j^2 \text{ and } \Delta_{i,j}\equiv \Delta_{i,j}(t, h_j, h_i)= v_j^2v_i^2 t^2- (h_j^2-h_i^2)(v_j^2-v_i^2),
\]

both of them as a function of $t, h_j, h_i$. The quantity
$t^*\equiv t^*(h_j,h_i):=\frac{1}{v_j v_i}(h_j^2-h_i^2)^{\frac{1}{2}} (v_j^2-v_i^2)^{\frac{1}{2}}$, is the non-negative solution of $\Delta_{i,j}(t, h_j, h_i)=0$ in the variable $t$.

