[Proposition prop_unif_case of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Consider any four position parameters $a,b,f_a,f_b\in\mathbb{R}$ and any two slope parameters $s_a,s_b\in\mathbb{R}\cup\{-\infty,\infty\}$ such that
\begin{equation} 
a<b \quad \text{and} \quad s_a < \frac{f_b - f_a}{b- a} < s_b.
\end{equation}
Denote by $\mathcal{F}_\partial$ the set of continuous convex $f\colon[a,b]\to\mathbb{R}$ with the following boundary data:
\begin{align} 
f(a)\geqslant f_a,\quad 
f(b)\leqslant f_b,\quad 
\partial^+f(a)\geqslant s_a,\quad 
\partial^-f(b)\leqslant s_b.
\end{align}
Denote by $\mathcal{F}_\partial^=$ the set of continuous convex $f\colon[a,b]\to\mathbb{R}$ satisfying (equation boundary_data of the paper) with equalities:
\begin{linenomath}\postdisplaypenalty=0\begin{align*} 
f(a)=f_a,\quad f(b)=f_b,\quad \partial^+f(a)= s_a,\quad \partial^-f(b)= s_b.
 \end{align*}\end{linenomath}
Then the following statements hold:
\begin{enumerate}[label=\textup{(\alph*)}]

\item 
If $-\infty<s_a<s_b=\infty$, then

\begin{gather}

\sup_{f \in \mathcal{F}_\partial} \int_a^b f''(x)^{1/3}\ \mathrm{d} x 

= \big(4(b-a)\Delta_1\big)^{1/3},

\quad \text{where} \quad
\Delta_1 \coloneqq f_b-f_a-s_a(b-a) > 0.
\end{gather}

The unique maximizer belongs to $\mathcal{F}_\partial^=$ and has second derivative given by
\eeq{ 
f''(x) &= \frac{\Delta_1}{2\sqrt{b-a}}(b-x)^{-3/2}.
}

\item 
If $-\infty=s_a<s_b<\infty$, then

\begin{gather}

\sup_{f \in \mathcal{F}_\partial} \int_a^b f''(x)^{1/3}\ \mathrm{d} x 

= \big(4(b-a)\Delta_2\big)^{1/3},

\quad \text{where} \quad
\Delta_2 \coloneqq s_b(b-a)-(f_b-f_a).
\end{gather}

The unique maximizer belongs to $\mathcal{F}_\partial^=$ and has second derivative given by
\eq{
f''(x) &= \frac{\Delta_2}{2\sqrt{b-a}}(x-a)^{-3/2}.
}

\item 
If $-\infty<s_a<s_b<\infty$, then
\eeq{ 
\sup_{f \in \mathcal{F}_\partial} \int_a^b f''(x)^{1/3}\ \mathrm{d} x = \Big(\frac{4\Delta_1\Delta_2}{s_b-s_a}\Big)^{1/3}.
}
The unique maximizer belongs to $\mathcal{F}_\partial^=$ and has second derivative given by
\eeq{ 
f''(x) = \frac{1}{3^{3/2}}\Big(u^2\cdot\frac{x-a}{b-a} + v^2\cdot\frac{b-x}{b-a}\Big)^{-3/2},
}
where $u$ and $v$ solve (equation both_crit of the paper).
\end{enumerate}

