[Proposition 19 of arXiv:2603.25400, 'One-arm probabilities for the two-dimensional metric-graph and discrete Gaussian free fiel'] There exist $r\in(0,1/4)$ and $c=c(r,h)>0$ such that for all $N$,
    \begin{equation}
        \mathbb P[\Lambda]\ge\frac c{\sqrt{\log N}}.
    \end{equation}

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ f $ be a random variable. If $ f $ is Bochner integrable with respect to the probability measure $ \mathbb{P} $, then we denote 
    \begin{align*}
        \mathbb{E} f = \int_{\Omega} f d \mathbb{P}
    \end{align*}
    and call it the mean or mathematical expectation of $ f $.

[Definition {Following \cite[Thm.\ B of arXiv:2609.00163, 'Decompositions and diagrams of symplectic surfaces in Weinstein domains'] {gironella2020some}}]
    Let $(W',\omega')$ be a (weak, strong, Weinstein) filling of $(M',\xi')$, and $(W,\omega)$ be a (weak, strong, Weinstein) filling of $(M,\xi)$. A {\it branched cover of (weak, strong, Weinstein) fillings} $f:(W',S')\rightarrow (W,S)$ is a smooth branched cover with branching set $S$, such that
    \begin{enumerate}
    \item $S$ and $S'$ are symplectic surfaces in $(W,\omega)$ and $(W',\omega')$, respectively;
    \item $\partial S$ and $\partial S'$ are transverse links in $(M,\xi)$ and $(M',\xi')$, respectively;
    \item $(M',\xi')$ is a contact branched cover of $(M,\xi)$ along $\partial S$ in the sense of [geiges2008introduction]; and
    \item $\omega'$ is deformation equivalent 
    to the form $\hat{\omega}_\epsilon$ in [gironella2020some] for $\epsilon$ sufficiently small.
    \end{enumerate}

[Theorem 1 (\cite{Bog78,Bog80,SS85}) of arXiv:2609.01965, 'A logarithmic Bogomolov--Sommese vanishing theorem on compact K\"ahler manifolds'] Let $X$ be a projective manifold and $L$ a line bundle over $X$. 
    Let $D$ be a reduced simple normal crossing divisor on $X$. Then
    \begin{equation*}
        H^0(X,\Omega^p_X(\log D)\otimes L^{-1})=0 \quad \text{for every } p<\kappa(L),
    \end{equation*}
    where $\kappa(L)$ denotes the Kodaira--Iitaka dimension of $L$. (Proof in the paper; no proof environment follows the statement in the TeX.)

