[Theorem 9 (Global well-posedness in the weak setting) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Suppose that Assumption~\ref{assumption_weak_setting} holds. Let $u_0\in L^0_{\F_0}(\Omega;L^2(\sO))$, then \eqref{eq:AVP} has a unique global solution with

\begin{equation}
    u\in C([0,\infty);L^2(\sO))\cap L^2_{\loc}([0,\infty);\nH^2(\sO)) \quad \text{a.s.}
\end{equation}
If, in addition, $u_0\in  L_{\F_0}^2(\Omega;L^2(\sO))$, then for every $T>0$  there exists a constant $C_T > 0$ independent of $u_0$ such that 
\begin{equation}
    \E \Vert u \Vert_{C([0,T]; L^2(\sO))}^2 + \E \Vert u \Vert_{L^2(0, T; H^2(\sO))}^2 \leq C_T \big(1 + \E \Vert u_0 \Vert_{L^2(\sO)}^2\big).
\end{equation}

[Proposition 57 (Sharp escape obstruction) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] The natural isometry
\begin{equation}
 \bigoplus_{q\ge1}(H_n^{\odot q})_{\mathcal U}
 \longrightarrow
 \left(\bigoplus_{q\ge1}H_n^{\odot q}\right)_{\mathcal U}

\end{equation}
is not onto.  Indeed, choose
\[
 \norm{x_{n,n}}=1,
 \qquad x_{n,q}=0\quad(q\ne n).
\]
Then every fixed-grade ultralimit and every fixed-$Q$ terminal is zero, whereas the full norm
is one.

[Definition 48 of arXiv:2606.11758, '2606.11758'] Define the capped-martingale exceptional event
\(\mathcal E_n^{\mathrm{cap}}\) to be the event that there exist
\(\xi\in\mathcal N_n\),
\(d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}\),
such that \(\mathcal G_n^{\mathrm{pre}}\) holds and
\[
    |F_{\xi,d,n}^{\mathrm{pre,cap}}|
    +
    \sup_{L>m_{\xi,d,+}}
    |F_{\xi,d,n,L}^{\mathrm{post,cap}}|
    >
    2^{-sn/2}2^{-2\varepsilon n}.
\]
Define the compensator exceptional event \(\mathcal E_n^{\mathrm{comp}}\) by
\[
\begin{aligned}
    \mathcal E_n^{\mathrm{comp}}
    =
    \Bigg\{
    \sup_{\xi\in\mathcal A_n}
    \Bigg(
        \sum_{d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}}
        \mathfrak C_{\xi,d,n}^{\mathrm{pre}}
        +
        \sup_{L\ge1}
        \sum_{d\in\mathfrak D_{\xi,n}^{\mathrm{osc}}}
        \mathfrak C_{\xi,d,n,L}^{\mathrm{post}}
    \Bigg)
    >
    2n^{-2}2^{-sn/2}
    \Bigg\}.
\end{aligned}
\]

[Definition def:dag of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $m \in \mathbb{N}$ and a choice sequence $\mathbf x\in \{-1,1\}^\mathbb{N}$. We recursively construct a sequence $(G^{(n)})_{n\in\mathbb{N}}$ of directed graphs. We initialise $G^{(1)}$ as the graph consisting of one \emph{active} vertex with label $(1,a)$ if $x_1=1$ and we initialise $G^{(1)}\coloneq\varnothing$ otherwise. Conditionally on $G^{(i-1)}$ for some $i\geq 2$, we construct $G^{(i)}$ from $G^{(i-1)}$ in the following manner. If $A_{i-1}>0$, then:
\begin{itemize}
\item If $x_i=-1$, choose an active vertex $(v,a)$ in $G^{(i-1)}$ uniformly at random.  \emph{Freeze} this vertex by changing its label to $(v,i)$.
\item If $x_i=1$, add an active vertex labelled $(i,a)$ to $G^{(i-1)}$. Select  $m\land A_{i-1}$ many distinct active vertices $(k_1,a),\ldots,( k_{m \land A_{i-1}},a)$ in $G^{(i-1)}$ uniformly at random, and connect $(i,a)$ to $(k_j,a)$ by a directed edge for each $j\in[m\wedge A_{i-1}]$.
\end{itemize} 
Else, if $A_{i-1}\leq0$,  set $G^{(j)} \coloneq G^{(i-1)}$ for all $j\geq i-1$ and terminate the process.

[Cor 3 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] The quantity $\mathscr{E}_{\alpha}(u,v)$ for $u\in 
D(\mathscr{E})_{\loc}^{\diamond}$ {\rm(}resp.~$u\in 
D(\mathscr{E})_{\loc}^{\dag}${\rm )}
and 
$v\in D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m})$ 
{\rm(}resp.~$v\in D(\mathscr{E}_D)_c${\rm)}
defined by 
\begin{align*}
\mathscr{E}(u,v):&=\frac12\mu^{(c)}_{\langle u,v\rangle}(D)+\int_{E^2\setminus {\sf diag}}
\hspace{-0.2cm}
(\tilde{u}(x)-\tilde{u}(y))(\tilde{v}(x)-\tilde{v}(y))J({\d} x{\d} y)+\int_D\tilde{u}(x)\tilde{v}(x)\kappa({\d} x),\\
\mathscr{E}_{\alpha}(u,v):&=\mathscr{E}(u,v)+\alpha\int_Duv\,{\d}{\m}
\end{align*}
is well-defined for $\alpha>0$.  
Moreover, the quantity $\mathscr{E}(u,v)$ for $u\in
D(\mathscr{E})_{e,\loc}^{\diamond}$ 
{\rm(}resp.~$u\in
D(\mathscr{E})_{e,\loc}^{\dag}${\rm)}
and 
$v\in D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m})$ 
{\rm(}resp.~$v\in D(\mathscr{E}_D)_c${\rm)} is also well-defined.
So $\mathscr{E}_{\alpha}$ is a bilinear form on 
$D(\mathscr{E})_{\loc}^{\diamond}\times (D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m}))$ {\rm(}resp.~$D(\mathscr{E})_{e,\loc}^{\diamond}\times (D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m}))${\rm)} under $\alpha>0$ {\rm(}resp.~$\alpha=0${\rm)}, and 
 also a bilinear form on $D(\mathscr{E})_{\loc}^{\dag}\times D(\mathscr{E}_D)_c$ {\rm(}resp.~$D(\mathscr{E})_{e,\loc}^{\dag}\times D(\mathscr{E}_D)_c${\rm)} under $\alpha>0$ {\rm(}resp.~$\alpha=0${\rm)}.
When $\alpha=0$, we write $\mathscr{E}(u,v)$ instead of $\mathscr{E}_0(u,v)$.

