[Lemma 22 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] Assuming Assumption~\ref{as:growth} and setting 
  \begin{equation}
    h(\epsilon) := \epsilon^{(N - 1 + \theta)\gamma}\|R^{\mathbf{Z}, \mathbf{1}}\|_{N\gamma; I^{k, R}_{\le \epsilon}},
  \end{equation}
  we have for all \(\epsilon \le l(R(k + 1))^{-1} \wedge 1\),
  \begin{align*}
    & \epsilon^{(N - 1 + \theta)\gamma} \epsilon^{(|f| + 1)\gamma} \|R^{\sharp, f}\|_{N\gamma; I}
    \lesssim \sum_{k = 0}^{N - |f| - 1} 
      \epsilon^{(1 - \theta + \kappa)k \gamma}h(\epsilon)^k.
  \end{align*}

