body:
[Theorem 10 (The general linear Gaussian Kalman filter) of arXiv:2608.25164, 'A time-fractional Kalman filter'] \begin{myenumerate}
\item
The best estimate $\widehat{X}(t)=\E[X(t)\mid\Y_t]$ of $X(t)$, given the
observations $Y(s)$ for $s\leq t$, satisfies the stochastic integral equation

\begin{align}
\widehat{X}(t)=\E[X(t)]
-\int_0^t\frac{G^2(s)}{D^2(s)}H(t,s)\widehat{X}(s)ds
+\int_0^t\frac{G(s)}{D^2(s)}H(t,s)dY(s),

\end{align}
where
\begin{align*}
H(t,s)=\E[X(t)\widetilde X(s)],\qquad
\widetilde X(s)=X(s)-\widehat X(s),\qquad 0\leq s\leq t.
\end{align*}
\item
The error function $H(t,s)=\E[X(t)\widetilde X(s)]$ satisfies the following Riccati  intehral equation
\begin{align}
H(t,s)
&=\operatorname{Cov}(X(t),X(s))\nonumber\\
&\quad-\int_0^s\frac{G^2(r)}{D^2(r)}H(t,r)H(s,r)dr,
\qquad 0\leq s\leq t,                                      
\end{align} 
\end{myenumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 6.1 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] Assume that $\xi\in L_\tau^p(\rho_\cdot;{\mathbb R})$, $\int_0^\tau e^{\int_{0}^{s}\rho_r{\rm d}r}h_s{\rm d}s\in L_\tau^p(0;{\mathbb R}_+)$ and the random core function $f$ satisfies assumption (A:A3 of the paper). Then, the process $\{U_t(\xi),t\in[0,\tau]\}$ defined by
\begin{align}
U_{t\wedge \tau}(\xi):=e^{-\int_0^{t\wedge \tau}\mu_r{\rm d} r }\mathop{\operatorname{ess\,inf}}\limits_{q\in\mathcal{H}(\xi,f,\mu_\cdot,\nu_\cdot)}\mathbb{E}_{{\mathbb Q}^q}\Big[e^{\int_0^\tau \mu_r{\rm d} r}\xi+\int_{t\wedge \tau}^{\tau}e^{\int_0^s \mu_r{\rm d} r}f(s,q_s){\rm d} s\big|\mathcal{F}_{t\wedge \tau}\Big], \ \ t\geq 0
\end{align}
can be represented as the value process $y_\cdot$ of the unique weighted $L^p$ solution $(y_t,z_t)_{t\in[0,\tau]}$ in the space of $H_\tau^p(\rho_\cdot;{\mathbb R}\times {\mathbb R}^{1\times d})$ of the following BSDE
\begin{align}
 y_t=\xi+\int_t^\tau [\mu_s y_s-g(s,-z_s)] {\rm d}s-\int_t^\tau z_s{\rm d}B_s, \ \ t\in[0,\tau],
\end{align}
where the random function $g$ is the Legendre-Fenchel transform of $f$, i.e.,
\begin{align}
g(\omega,t,z):=\sup_{q\in{\mathbb R}^{1\times d}}\big(q\cdot z-f(\omega,t,q)\big),\ \ (\omega,t,z)\in\Omega\times[0,\tau]\times{\mathbb R}^{1\times d}.
\end{align}
Consequently, the operator $\{U_t(\cdot),t\in[0,\tau]\}$ constitutes a dynamic concave utility function defined on the space of $L_\tau^p(\rho_\cdot;{\mathbb R})$, i.e., it satisfies the following properties: for each $t\geq 0$,
\begin{itemize}
\item [\textbullet]\text{Monotonicity:} $U_{t\wedge \tau}(\xi)\geq U_{t\wedge \tau}(\eta)$ for each $\xi, \eta\in L_\tau^p(\rho_\cdot;{\mathbb R})$ such that $\xi\geq\eta$;
\item [\textbullet]\text{Concavity:} $U_{t\wedge \tau}(\lambda\xi+(1-\lambda)\eta)\geq \lambda U_{t\wedge \tau}(\xi)+(1-\lambda) U_{t\wedge \tau}(\eta)$ for all $\xi, \eta\in L_\tau^p(\rho_\cdot;{\mathbb R})$ and $\lambda\in(0,1)$;
\item [\textbullet]\text{Time consistency:} $U_{s\wedge \tau}(\xi)=U_{s\wedge \tau}(U_{t\wedge \tau}(\xi))$ for each $\xi\in L_\tau^p(\rho_\cdot;{\mathbb R})$ and each $s\in [0,t]$.
\end{itemize}
Moreover, let $\tilde q_s\in\partial g(s,-z_s), \ s\in[0,\tau]$. By this notation we mean that $(\tilde q_t)_{t\in [0,\tau]}$ is an $(\mathcal{F}_t)$-progressively measurable ${\mathbb R}^{1\times d}$-valued process such that for each $s\in[0,\tau]$ and $u\in {\mathbb R}^{1\times d}$,
\begin{align*}
g(s,u)-g(s,-z_s)\geq \tilde q_s\cdot (u+z_s)\ \ \ {\rm or \ equivalently}\ \ \ \tilde q_s\cdot u-g(s,u)\leq -\tilde q_s\cdot z_s-g(s,-z_s).
\end{align*}
Then, the infimum in (equation Ut of the paper) is attained for $\tilde q_\cdot$ provided that anyone of the following three conditions holds:
\begin{itemize}
\item [(i)] $\mathbb{E}[\exp\left(\frac{\bar p}{2}\int_0^\tau \nu_t^2 {\rm d} t\right)]<+\infty$ for any $\bar p>1$;

\item [(ii)] $\mathbb{E}[\exp\left(\frac{1}{2}\int_0^\tau \nu_t^2 {\rm d} t\right)]<+\infty$ and $\int_0^\tau e^{\int_{0}^{s}\mu_r{\rm d}r}h_s{\rm d}s\leq K$ for some constant $K>0$;

\item [(iii)] the process $L_t^{\tilde q}:=\exp(\int_{0}^{t}\tilde q_s{\rm d} B_s-\frac{1}{2}\int_{0}^{t}|\tilde q_s|^2{\rm d} s), \ t\in[0,\tau]$
is a uniformly integrable martingale and $\int_0^\tau e^{\int_{0}^{s}\mu_r{\rm d}r}h_s{\rm d}s\leq K$ for some constant $K>0$.\vspace{0.2cm}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] Let $\cS$ be a ${\rm BESQ}(\overline{\delta})$ flow and $\cD$ be a countable dense subset of $\bR_+\times\bR$. Almost surely for every $(a,r)\in \bR_+\times \bR$ and $x> r$,
    \begin{equation}
\cS_{r,x}(a) =\lim_{\substack{(a_n,r_n)\in \cD \to (a,r)\\ r_n\in (r,x),a_n\ge \cS_{r,r_n}(a)}} \cS_{r_n,x}(a_n)=\limsup_{\substack{(a_n,r_n)\in \cD \to (a,r) \\ r_n\in (r,x)}} \cS_{r_n,x}(a_n).
\end{equation}
If moreover  $a>0$,
\begin{equation}
\cS_{r,x}(a-) =\lim_{\substack{(a_n,r_n)\in \cD \to (a,r)\\ r_n\in (r,x), a_n\le \cS_{r,r_n}(a-)}} \cS_{r_n,x}(a_n)=\liminf_{\substack{(a_n,r_n)\in \cD \to (a,r) \\ r_n\in (r,x)}} \cS_{r_n,x}(a_n). 
\end{equation}

[Theorem 3 (Finite lifetime regime) of arXiv:2505.06187, 'Preferential Attachment Trees with Vertex Death: Persistence of the Maximum Degree'] Consider the PAVD model, as in Definition~\ref{def:pavd}.  Suppose that $b$ and $d$ are such that Assumptions~\eqref{ass:A1}, \eqref{ass:C1}, \eqref{ass:A2}, and~\eqref{ass:varphi2} are satisfied. Recall $R$ from~\eqref{eq:R} and suppose that $d$ satisfies~\eqref{eq:dconv} with $d^*\in[0,R)$, and let Assumption~\hyperref[ass:Kalpha]{$\cK_\alpha$} be satisfied. Then,
		\begin{align}
			\Big(\log O_n-\frac{d^*}{\lambda^*+d^*}\log n-\frac{\lambda^*}{\lambda^*+d^*}\cK_\alpha\big(r\big(\tfrac{1}{\lambda^*}\log n\big)\big)\Big)_{n\in\N},
			\intertext{and} 
			\Big(\log I_n^{(1)}-\frac{d^*}{\lambda^*+d^*}\log  n-\frac{\lambda^*}{\lambda^*+d^*}\cK_\alpha \big(r\big(\tfrac{1}{\lambda^*}\log n\big)\big)\Big)_{n\in\N}, 
			\intertext{and} 
			\Big(\varphi_1(\max_{v\in \cA_n}\deg_n(v))-\frac{1}{\lambda^*+d^*}\log n+\frac{1}{\lambda^*+d^*}\cK_\alpha\big(r\big(\tfrac{1}{\lambda^*}\log n\big)\big)\Big)_{n\in\N}.
		\end{align} 
		are tight sequences of random variables with respect to $\mathbb P_\cS$. In particular, persistence occurs in the sense of~\eqref{eq:pers}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] For $n\ge 1$ and $k=(k_1,\ldots,k_d)\in\mathbb{N}^d$,

\begin{equation*}
\sd^{(n)}(k)=\prod_{u=1}^d \multiset{n}{k_u}
=\prod_{u=1}^d \binom{n+k_u-1}{k_u}.
\end{equation*}

[Lemma 19 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $\alpha_1,\alpha_2 \in \R$ such that $\alpha_1+\alpha_2>0$. Let $\mu_1,\mu_2 \in \R$ with $\mu=\mu_1+\mu_2$ and $p_1,p_2\in[1,\infty]$ with $\frac{1}{p}=\frac{1}{p_1}+\frac{1}{p_2}$. Then for any $\kappa >0$, there exists a constant $C>0$ such that
\begin{equation*} 
\|uv\|_{\mathcal{B}_{p,p,\mu}^{\alpha-\kappa}(\R^d)} \leq C \| u \|_{\mathcal{B}_{p_1,p_1,\mu_1}^{\alpha_1}(\R^d)} \| v \|_{\mathcal{B}_{p_2,p_2,\mu_2}^{\alpha_2}(\R^d)}
\end{equation*}
where $\alpha=\min(\alpha_1,\alpha_2)$. In the case where $p=p_1$, one can take $\kappa=0$. We also have
\begin{equation*} 
\|uv\|_{\CW^{\alpha,p}(\R^d)} \leq C \| u \|_{\CW^{\alpha,p_1}(\R^d)} \| v \|_{L^{p_2}(\R^d)}+ C \| u \|_{L^{p_1'}(\R^d)} \| v \|_{\CW^{\alpha,p_2'}(\R^d)}
\end{equation*}
for $\alpha\in[0,1]$ and $\frac{1}{p}=\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{p_1'}+\frac{1}{p_2'}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Appendix: Bridge like probability of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Under the same assumptions as Lemma (Appendix: Girsanov, exceeding probability of the paper), for any $x,y>0$ and $0\leq t_1<t_2$, we have
	\begin{equation}
		\begin{aligned}
			&\mathbb{P}\Biggl(
			Y_t-Y_{t_1}\le x+\int_{t_1}^t k_r(s)\,\text{d} s
			\ \forall t\in[t_1,t_2],\ 
			x+\int_{t_1}^{t_2}k_r(s)\,\text{d} s
			-(Y_{t_2}-Y_{t_1})\in\text{d} y
			\Biggr)\\
			&\quad=
			\exp\Biggl\{
			-\frac{k_r(t_1)}{\sigma(t_1)^2}x
			+\frac{k_r(t_2)}{\sigma(t_2)^2}y
			-\frac{c_A^2}{2}(t_2-t_1)
			-\frac{1}{2}\int_{t_1}^{t_2}
			\frac{(\eta(s)+r(s))^2}{c_A^2\sigma(s)^2}\,\text{d} s
			\Biggr\}
			G_r(x,y;t_1,t_2)\,\text{d} y.
		\end{aligned}
	\end{equation}

	Here $G_r$ is the fundamental solution of (equation eqA: Airy PDE with sigma diffusion of the paper).

[Definition defin:compressibilitymatrix of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] For any $\rho\in (0,1)$ and $\mathcal{E}\in (\rho ,\kappa\rho)$, we define the \emph{compressibility matrix} to be the covariance matrix
    \begin{equation*}
        \chi (\rho ,\mathcal{E} )\coloneq \begin{pmatrix}
            \mathrm{Var}_{\rho ,\mathcal{E}}(\xi_x) & \mathrm{Cov}_{\rho ,\mathcal{E}}(\xi_x;\eta_x) \\
            \mathrm{Cov}_{\rho ,\mathcal{E}}(\xi_x;\eta_x) & \mathrm{Var}_{\rho ,\mathcal{E}}(\eta_x)
        \end{pmatrix}.
    \end{equation*}
    After calculation, it is given by
    \begin{equation}
        \chi (\rho ,\mathcal{E}) = \begin{pmatrix}
            \rho (1-\rho) & \mathcal{E}(1-\rho)\\
            \mathcal{E}(1-\rho ) & \frac{(\mathcal{E}-\rho )(\kappa\rho -\mathcal{E})}{(\kappa -1)\rho} + \frac{(1-\rho )\mathcal{E}^2}{\rho }
        \end{pmatrix}.
    \end{equation}
    This matrix is symmetric and positive definite.

[Lemma lem:ROC_first_order of arXiv:2609.02491, 'Generalised Random Parking for Trapeziums on a Strip'] There exists some $\ov\lambda(a,b) \in \mathbb{R}$, such that, for all $x > 2a(e+1)$, it holds that
    \begin{equation}
    \bigg|\eta(x) -\ov\lambda(a,b) x +1-\ov\lambda(a,b) \frac{a+b}{2}\bigg|
    \le \begin{dcases}
      \mleft(\frac{2e}{x/a}\mright)^{x/a-3/2} \frac{e^{3/2} K_1}{\sqrt{\pi}}, &\text{ if }a=b,\\
      \mleft(\frac{2e}{x/a}\mright)^{x/a-5/2} \frac{3e^{5/2}(2K_1+K_2)}{\sqrt{\pi}}, &\text{ if }a>b.
    \end{dcases}
\end{equation} where $K_1 \coloneqq 1 + 2a(2/(a+b)+\ov\lambda(a,b)) + \ov\lambda(a,b)\cdot  (a+b)/2>0$ and $K_2 \coloneqq (2/(a+b)+\ov\lambda(a,b))(a-b)/2\ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem asymptotics_f2 of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $z_c^\pm$ be the critical points of $\mathrm G(z)$ as given in (equation eq: z_pm of the paper). 
Let $b\in {\mathbb R}$, and for each $L>0$, define the circles 
\begin{equation}
    \Sigma^{b, L}_{-}= \{ z\in {\mathbb C} \, : \, |z+1|= | z_c^- +1|+b L^{-\frac12} \}, 
    \qquad
    \Sigma^{b, L}_{+}= \{ z\in {\mathbb C} \, : \, |z|= |z_c^+| +b L^{-\frac12} \}. 
\end{equation}
\begin{itemize}
\item If $\alpha_1,\alpha_2 > 0$ and $\alpha_3 > (\sqrt{\alpha_1}+\sqrt{\alpha_2})^2$, then both  statements (eq:propertya of the paper)  and (eq:propertyb of the paper)  below hold.  
\item If $\alpha_1 < 0$ and $\alpha_2, \alpha_3 > 0$, then statement (eq:propertyb of the paper)  holds. 
\item If $\alpha_2 < 0$ and $\alpha_1, \alpha_3>0$, then statement (eq:propertya of the paper)  holds.  
\end{itemize}

\begin{enumerate}[(a)] 
\item 
There exists a constant $c>0$ such that for every $0 < \epsilon < 1/2$, 
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z)}{{\mathsf{f}}_{L}(z_c^-)} \right| =   O(e^{-cL^{2\epsilon/3}})  
    \qquad \text{for $z \in \Sigma^{b, L}_{-}\cap \{ z\in {\mathbb C} : |z-z_c^-| \ge L^{-\frac12 + \frac{\epsilon}{3}}\}$}
\end{equation}
as $L \to \infty$. Furthermore, there exist  $L_0>0$ and $C>0$ such that for all $L>L_0$,
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z)}{{\mathsf{f}}_{L}(z_c^-)} \right| \le C \quad \text{for $z \in \Sigma^{b, L}_{-}$}. 
\end{equation}

\item  
There exists a constant $c>0$ such that for every $0 < \epsilon < 1/2$,
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z_c^+)}{{\mathsf{f}}_{L}(z)} \right| =   O(e^{-cL^{2\epsilon/3}})  
    \qquad \text{for $z \in \Sigma^{b, L}_{+}\cap \{ z\in {\mathbb C} : |z- z_c^+| \ge L^{-\frac12 + \frac{\epsilon}{3}}\}$}
\end{equation}
as $L\to \infty$. 
Furthermore, there exist $L_0>0$ and $C>0$ such that for all $L>L_0$,
\begin{equation} 
    \left| \frac{{\mathsf{f}}_{L}(z_c^+)}{{\mathsf{f}}_{L}(z)} \right| \le C \quad \text{for  $z \in \Sigma^{b, L}_{+}$}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $\varepsilon > 0$ and assume that $\ppp$ is a stationary marked point process on $\rd \times \R$ such that $\p(\hat{\ppp} \in \Msettemp) = 1$. Then there exist constants $K_1,K_2,K_3, r_0 \geq 1$ such that for all $r \geq r_0$,
    \begin{equation*} 
        \max \{ \p(\ppp \in E^1_{r,K_1}),\p(\ppp \in E^2_{r,K_2}),\p(\ppp \in E^3_{r,K_3})\} < \varepsilon.
    \end{equation*}

