[Lemma 82 (Products with a negative H\"older coefficient) of arXiv:2607.10813, '2607.10813'] Let $0<\alpha<1$, $f\in\mathcal C^{-\alpha}(\R^3)$, and
$\varepsilon>0$.  For smooth finite-block functions the following estimates
hold, and they extend to the corresponding completed spaces.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.3em]
\item If $g\in L^2$, then
\begin{equation}
 \|g\prec f\|_{B_{2,\infty}^{-\alpha}}
 +\|g\prec f\|_{H^{-\alpha-\varepsilon}}
 \lesssim_\varepsilon
 \|g\|_{L^2}\|f\|_{\mathcal C^{-\alpha}}.
\end{equation}
\item If $g\in H^s\cap B_{2,\infty}^{\tau}$, then
\begin{align}
 \|f\prec g\|_{H^{s-\alpha}}
 &\lesssim \|f\|_{\mathcal C^{-\alpha}}\|g\|_{H^s},
 \\
 \|f\prec g\|_{B_{2,\infty}^{\tau-\alpha}}
 &\lesssim \|f\|_{\mathcal C^{-\alpha}}
              \|g\|_{B_{2,\infty}^{\tau}}.

\end{align}
If only the Besov norm of $g$ is used, then
\begin{equation}
 \|f\prec g\|_{H^{\tau-\alpha-\varepsilon}}
 \lesssim_\varepsilon
 \|f\|_{\mathcal C^{-\alpha}}
 \|g\|_{B_{2,\infty}^{\tau}}.
\end{equation}
\item If $s>\alpha$ and $g\in H^s$, then the resonant product is defined and
\begin{equation}
 \|g\circ f\|_{B_{2,\infty}^{s-\alpha}}
 +\|g\circ f\|_{H^{s-\alpha-\varepsilon}}
 \lesssim_\varepsilon
 \|g\|_{H^s}\|f\|_{\mathcal C^{-\alpha}}.
\end{equation}
\end{enumerate}
Multiplication of the left-hand sides by a fixed function in
$C_c^\infty(\R^3)$ preserves all estimates.

[Definition 1 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $(\mathbf{x}_t)_{t\geq 0}$ be a $n$-dimensional stochastic process. Then the autocovariance at time $t\ge0$ 
and lag time $\tau\ge0$ is defined as 
\begin{align}
    V_t(\tau):=\E[\mathbf{x}_t\overline{\mathbf{x}}_{t+\tau}^{\text{T}}]-\E[\mathbf{x}_t]\E[\overline{\mathbf{x}}_{t+\tau}^{\text{T}}],
\end{align}
where $\overline{\mathbf{x}}$ is the complex conjugate and $\mathbf{x}^{\text{T}}$ is the transpose.
For $\tau=0$ we recover the variance of the process. For $n=1$ we can also define the autocorrelation function
\begin{align}
    AC_t(\tau):=\frac{V_t(\tau)}{V_t(0)}.
\end{align}

[Proposition prop:lln of arXiv:2605.10361, 'Limit shape of single-source stochastic sandpiles with $p$-topplings on $\Z$'] For $\mathtt{l}_{n}=\inf\{v\in\mathbb{Z}\;|\; \eta_{K_n}^{(n)}(v)>0\}$ and $\mathtt{r}_{n}=\sup\{v\in\mathbb{Z}\;|\;\eta_{K_n}^{(n)}(v)>0\}$, it holds that
    \begin{align*}
        \frac{\mathtt{l}_{n}}{n}\xrightarrow[n\rightarrow\infty]{\mathbb{P}}-\frac{1}{2}&&\text{and}&&\frac{\mathtt{r}_{n}}{n}\xrightarrow[n\rightarrow\infty]{\mathbb{P}}\frac{1}{2}.
    \end{align*}

[Lemma 18 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] For $\beta>1$,
\begin{equation}
 \Gamma'(0)=1,\qquad u_{xx}(0,0)=\frac1\beta.
\end{equation}

