body:
[Thm localfbm of arXiv:2606.21049, '\textsc{Locality of rough path lifts}'] Let $H \in (0,1/2]$ and $0 < \eta <H$ with $1/\eta < \lfloor 1/H \rfloor + 1$. Let $X$ be a $d$-dimensional $H$-fBm.
\begin{enumerate}[label=(\alph*)]
	\item If $d\geq 2$ and $H \leq 1/4$ there exists no local, square-integrable $\eta$-RPL of $X$.
	\item 
If $H > 1/4$, denoting $\overline{\boldsymbol{X}}$ the canonical lift [CQ02], any local, square-integrable $\eta$-RPL $\boldsymbol{X}$ must satisfy
\begin{equation}
	\boldsymbol{X}^{(2)}_{s,t} = \overline{\boldsymbol{X}}{}^{(2)}_{s,t} + \varphi^{(2)}_{s,t}
\end{equation}
and if $H \in (1/4, 1/3]$ additionally
\begin{equation}
	\boldsymbol{X}^{\alpha\beta\gamma}_{s,t} = \overline{\boldsymbol{X}}{}^{\alpha\beta\gamma}_{s,t} + \DOTSI\upintop\ilimits@_s^t \varphi^{\alpha\beta}_{s,u} \,\mathrm{d} X^\gamma_u + \DOTSI\upintop\ilimits@_s^t \varphi^{\beta\gamma}_{u,t} \,\mathrm{d} X^\alpha_u + \varphi^{\alpha\beta\gamma}_{s,t}
	\;,
\end{equation}
where the integrals are defined as Wiener integrals (e.g.\ $\DOTSI\upintop\ilimits@_s^t \varphi^{\alpha\beta}_{s,u} \,\mathrm{d} X^\gamma_u = \sko(\varphi^{\alpha\beta}_{s,\cdot}\mathbbm 1_{[s,t]}^\gamma)$ and
\[
(0, \varphi^{(2)}, \varphi^{(3)})
\]
is a deterministic $\eta$-H\"older rough path above the zero path. Conversely, given any deterministic $\eta$-rough path $(0, \varphi^{(2)}, \varphi^{(3)})$ above the zero path, the formulas (equation eq:bX_level2 of the paper)-(equation eq:bX_level3 of the paper) define a local, square-integrable, geometric $\eta$-RPL of $X$. (Throughout this statement, we intend $\boldsymbol{X}$ and $\varphi$ to be only considered up to level-$2$ if $\eta \in (\frac 13, \frac 12]$.)
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:Frostman-gauge1 of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] Let $(X,d)$ be a separable metric space and let $h$ be a Hausdorff function. Consider a Borel set $A$. If there exists a Borel probability measure $\mu$ such that 
\begin{equation}
\mu(A)>0,  \qquad   
\mu\bigl(B\bigr)\, \le\, C \cdot h(\mathrm{diam\, } B) \ \ \ \forall B ({\rm ball \ in}\ X)
\end{equation}
for some constant $C>0$. Then
\begin{equation}
\mathcal H_{\mathcal{C}_{\text{ball}}}^h(A)\ge \mathcal H^h_{\mathcal{C}_{\text{ball}}, \delta}(A) \ge \frac{\mu(A)}{C}>0 
\end{equation}
for all $0<\delta \le \infty$.

[Lemma 19 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] \cite[Assumption \ref*{Form::Assumption::EstBdry::MaxSubOnSmoothing}\ref*{Form::Item::EstBdry::MaxSubOnSmoothing::MaxSubEstimate},\ref*{Form::Item::EstBdry::MaxSubOnSmoothing::FormQHGivesOp}]{StreetAPrioriEstimatesMaximallySubellipticQuadraticForms}
    hold. Namely, for \(U_1(t,x),U_2(t,x):\R\times \Cubengeq{1}\rightarrow \C^M\), set (whenever it makes sense)
    \begin{equation*}
        \FormQHTwo[U_1][U_2]:=\int \FormQTwo[U_1(t,\cdot)][U_2(t,\cdot)]\: dt + \Ltip*{U_1(t,x)}{h_{\xi,\delta,2}(x) \partial_t U_2(t,x)}[\Ropngeq][\C^M].
    \end{equation*}
    We have
    \begin{enumerate}[(i)]
        \item \(\exists E_1,E_2\geq 0\), \(\forall (\xi,\delta)\in \SSetTwo\cap \left( \CompactZero\times (0,\delta_0] \right)\),
             \(\forall U\in \DSet\), \(\forall S\) of the form \eqref{Eqn::Results::SOperator}, we have
             \begin{equation*}
                \sum_{|\alpha|=\kappa}
                \LtNorm*{\left( V^{\xi,\delta,2} \right)^{\alpha} S U}[\Ropngeq]^2
                \leq E_1 \Real \FormQHTwo[S U][S U] + E_2 \LtNorm{SU}[\Ropngeq]^2.
             \end{equation*}
        \item \(\forall (\xi,\delta)\in \SSetTwo\cap \left( \CompactZero\times (0,\delta_0] \right)\),
             \(\forall U\in \DSet\), \(\forall S\) of the form \eqref{Eqn::Results::SOperator},
             \begin{equation*}
                \FormQHTwo[S U][U] = \Ltip*{SU}{ h_{\xi,\delta,2} \left( \partial_t+\opLTwo \right)U}[\Ropngeq].
             \end{equation*}
    \end{enumerate}

[Lemma lem:Newton-inequalities of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $(\alpha_1,\dots,\alpha_m)$ be a non-negative and non-zero sequence with finite length $m\geq1$, and let $(e_k)_{0\leq k\leq m}$ be the sequence of the elementary symmetric polynomials in the $(\alpha_1,\dots,\alpha_m)$, or equivalently let $e_k=e_k(\alpha_1,\dots,\alpha_m,0,0,\dots)$ for $0\leq k\leq m$.
	Then the sequence $(e_k)_{0\leq k\leq m}$ satisfies the \emph{ultra-log-concavity} inequality, that is
	\begin{align}
	\frac{e_k^2}{\binom{m}{k}^2}\geq 
		\frac{e_{k-1}}{\binom{m}{k-1}}\cdot
		\frac{e_{k+1}}{\binom{m}{k+1}},
		\qquad k\in\{1,\dots,m-1\}.
	\end{align}
	In particular, ${\mathbf{e}}(\alpha_1,\dots,\alpha_m,0,0,\dots)$ is log-concave.
		\footnote{
		This is deduced from the inequality $\binom{m}{k}^2\geq\binom{m}{k-1}\binom{m}{k+1}$ for $0<k<m$, which holds by log-concavity of the binomial coefficients.
		Note that in this paper we require log-concave sequences to have no internal zeros, but we already justified that this is the case for sequences having the form ${\mathbf{e}}({\boldsymbol{\uptheta}})$ with ${\boldsymbol{\uptheta}}$ a summable weight sequence.
		} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem lem:gen_ibp of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] For all $l \in H_0^1~\cap~H^2$ and $F \in C_b^1(L)$ the following two equations hold
    \begin{align}
        \langle \!\langle F(\beta), \bar{l}_a\delta_0(\beta_a)\rangle \!\rangle &= \int_{L} F \langle l,\ufd{\sigma^{(a)}}\rangle \,d\var{\sigma^{(a)}},\\
        \Big\langle \mspace{-7mu} \Big\langle F(\beta), \int_{[0,1]} \bar{l}_x\delta_0(\beta_x) dx \Big\rangle \mspace{-7mu} \Big\rangle &= \int_{L} F \langle l,n_{\nu}\rangle \,d\| \nu \|.
    \end{align}
	Here, the LHSs are interpreted as discussed in Theorem (thm:ibpf of the paper). Moreover, for all elements $l\in H_0^1~\cap~H^2$ and $G \in (C_b^1)_{H_0^1\cap H^2}$, the two equations
    \begin{align}
        \int_{L} D^*G \rho^a \, d\mu^{\beta} &= \int_{L} \langle G,\ufd{\sigma^{(a)}}\rangle \,d\var{\sigma^{(a)}},\\
        \int_{L} D^*G \rho \, d\mu^{\beta} &= \int_{L} \langle G,n_{\nu}\rangle \,d\| \nu \|
    \end{align}
    hold. Using these results, [RZZ12], Theorem 3.1(iii), directly implies that $\rho^a,\, \rho \in \mathrm{BV}(L, H_0^1)$, $V(\rho^a)=\var{\sigma^{(a)}}(L)$ and $V(\rho)=\| \nu \|(L)$.

