[Prop 19 (Rough regularity estimates) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] We have 
    \begin{equation*}
        q(k)=k^{-\frac{1}{2\alpha}-1+o(1)}\qquad \text{ and }\qquad Q(k)= k^{-\frac{1}{2\alpha} +o(1)} \qquad\text{as }k \to \infty,
    \end{equation*}
    where $\alpha \in ( 1/2,1 )$ is as in \cref{thm:main}. Moreover, there is a constant $C>0$ such that for any real $\svx \geq 1$, we have
	\begin{equation}
	(1+o(1))\, \svx^{-C} \leq \frac{Q(\svx k)}{Q(k)} \leq 1 \qquad\text{as }k \to \infty,
	\end{equation}
	and, for any $k \geq 1$,
	\begin{equation}
    C \, \svx^{-C} \leq \frac{q(\svx k)}{q(k)} \leq C, 
    \end{equation}
    where we are using the conventions $Q(z)=Q(\lceil z \rceil)$ and $q(z)=q(\lceil z \rceil)$ for all $z\in\mathbb{R}_{> 0}$ as in \cref{sect:not-proba}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:mixture-of-vrjps of arXiv:2411.06195, 'Restrictions of some reinforced processes to subgraphs'] \mbox{}\\
  Assume that the graph $G$ is finite without self-loops and partition its vertex set $\Lambda=I\cup J$,
  $I\cap J=\emptyset$, with $|J|\ge 2$. 
  Consider the vrjp $(X,T)$ in exchangeable time scale on $\Lambda$
  starting at $\rho\in J$ with weights $W$. 
  The restrictions $(X^J,T^J)$ and $(X^{J\neq},T^{J\neq})$ to $J$ without or with
  self-loops removed are
  mixtures of vrjps in exchangeable time scale on $J$ with random weights
    \begin{align}

    W^J(\beta_I)=&(W^J_{ij}(\beta_I))_{i,j\in J}:=W_{JJ}+W_{JI}([H_\beta]_{II})^{-1}W_{IJ}
                    \text{ and }\\

    W^{J\neq}(\beta_I):=&\left(W^J_{ij}(\beta_I)1_{\{ i\neq j\}}\right)_{i,j\in J},
  \end{align}
  respectively. They depend on a random
  vector $\beta_I\in{\mathbb R}^I$, where $\beta_{I\cup\{\rho\}}\in{\mathbb R}^{I\cup\{\rho\}}$ is distributed
  according to $\nu_{I\cup\{\rho\}}^{\widehat W}$ with $\widehat W\in{\mathbb R}^{(I\cup\{\rho\})\times(I\cup\{\rho\})}$
  obtained by restricting the parameters $W$ to $I$ and wiring all points
  in $J$ at $\rho$:
  \begin{align}

    \widehat W_{ij}=\widehat W_{ji}=
    \begin{cases}
      W_{ij} &\text{ for }i,j\in I,\\
      \sum_{k\in J}W_{ik} &\text{ for }i\in I, j=\rho,\\
      0 &\text{ for }i=j=\rho.
    \end{cases}
  \end{align}
  In the case of $(X^{J\neq},T^{J\neq})$ this means the
  following for any event $A\subseteq J^{{\mathbb N}_0}\times{\mathbb R}_+^{{\mathbb N}_0}$. 
  \begin{align}
    P_\rho^{W,\Lambda}((X^{J\neq},T^{J\neq})\in A)
    =&\int_{{\mathbb R}^{I\cup\{\rho\}}}
       P_\rho^{W^{J\neq}(\beta_I),J}((X,T)\in A)\,\nu_{I\cup\{\rho\}}^{\widehat W}(d\beta_{I\cup\{\rho\}})\nonumber\\
    =&\int_{{\mathbb R}^\Lambda}
       P_\rho^{W^{J\neq}(\beta_I),J}((X,T)\in A)\,\nu_\Lambda^W(d\beta_\Lambda).

  \end{align}
  The analogous statement holds for $(X^J,T^J)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

