body:
[Theorem 17 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Assume that the conditions {\rm [A1-A5]} hold. For any $\gamma_0 > \tilde{\gamma}_0$ and $0 \leq \epsilon< \tilde{\epsilon}$, there is a pathwise unique stationary solution $\cY^{\epsilon} \in  L^{\infty}(\R; L^{2}(\Omega; H))$ for cocycle $(U^{\epsilon},\theta)$. The stationary solution $\cY^{\epsilon}(t)$ satisfies
\begin{small}
  \begin{gather}
     \E \exp \Big\{ \delta \big\{ \| \cY^{\epsilon}(t) \|_{H}^2 \big\} \Big\}  \leq 2 \, e^{2 \delta \frac{C_{A,\rho,\epsilon}}{\lambda_1 \gamma_0}};  \\
     \E \Big[ \exp \Big\{  \frac{\delta}{2} \sup_{t \geq t_1} \big( \frac{\gamma_0}{2} \int_{t_1}^t \| \cY^{\epsilon}(s) \|_{V}^{2} \, \d s-C_{A,\rho,\epsilon}   \big)(t-t_1) \big) \Big\} \Big]  \leq    2 e^{\delta  \frac{ C_{A,\rho,\epsilon} }{\lambda_1 \gamma_0}};  \\
      \E \Big[ \exp \Big\{  \frac{\delta}{2} \sup_{t \geq t_1} \big( \frac{\gamma_0}{2} \int_{t_1}^t \| \cY^{\epsilon}(s) \|_{H}^{\beta} \| \cY^{\epsilon}(s) \|_{V}^{2} \d s-\big( C_{A, \rho}+ \beta C_B \epsilon \big)(t-t_1) \big) \Big\} \Big]  \leq   2  e^{\delta  \frac{2+\beta}{2} \big( \frac{ C_{A,\rho,\epsilon} + \beta C_{B} \epsilon  }{\lambda_1 \gamma_0} \big)}, 
 \end{gather}
\end{small}
for any $t_0 \in \R$, where $\frac{ 4 C_{\rho_1}}{\gamma_0} \leq \delta<  \frac{ (1+\beta)\lambda_1 \gamma_{0}}{2(2+\beta)^2 C_{B} \epsilon} \leq \frac{ \lambda_1 \gamma_{0}}{8 C_{B} \epsilon}$. For any $-\infty<t_0<t<+\infty$, the stationary solution $\cY^{\epsilon} \in L^{2}(\Omega;\sC_{-\infty})$ $\P$-a.s. satisfies
\begin{equation} 
    \scalV{\cY^{\epsilon}(t),v} = \scalV{\cY^{\epsilon}(t_0),v} + \int_{t_0}^{t} \scalV{A^{\epsilon}(\cY^{\epsilon}(s)),v} \d s + \sqrt{\epsilon} \int_{t_0}^{t} \scalH{B (\cY^{\epsilon}(s)) \, \d W_s,v},
\end{equation}
for any $v \in V$. It is called the ``very weak solution'' in \cite[Definition 3.4]{Brzezniak_Large_2017}.

Conversely, if a $\cF_{t}$-adapted process $\cY^{\epsilon}$ satisfies Eq. \eqref{eq: stationary solution} and $\sup_{t \in \R} \E \|\cY^{\epsilon}(t) \|_{H}^2< +\infty$, then it is indeed the stationary solution for cocycle $(U^{\epsilon},\theta)$. There exists a Borel measurable map $\mathcal{G}^{\epsilon}_{-\infty}: \W \rightarrow \sC_{-\infty}$ such that $\mathcal{G}^{\epsilon}_{-\infty}(W)(\cdot)$ is an $\mathcal{F}_{t}$-adapted solution to Eq. \eqref{eq: stationary solution} and $\sup_{t \in \R} \E \|\mathcal{G}^{\epsilon}_{-\infty}(W)(t) \|_{H}^2< +\infty$, called the strong stationary solution for cocycle $(U^{\epsilon},\theta)$.

