[Theorem 5 of arXiv:2608.17493, 'Integrals of some compound processes'] $M\sim CP(\lambda, F)$ if and only if $M$ is a stochastic process having independent increments, $M(0)=0$ a.s. and, for $t\ge0, x\in\mathbb{R}$,
	\begin{align}
		P\{M[t,t+\dif t) \in \dif x\} = \begin{cases}
			\begin{array}{l l}
				\lambda(t)\dif t F(\dif x) + o(\dif t), & x\in\mathbb{R}\setminus\{0\},\\
				1-\lambda(t)\dif t + \lambda(t)\dif t F(\dif 0) + o(\dif t), & x = 0.
			\end{array}
		\end{cases} 
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm Factorization Lemma of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Let $M(t)$ be the stationary GOE processes. Then for $k$ fixed times $t_1, \dots, t_k$ and exponents $j_1,\dots,j_k$ we have,
\begin{equation*}
    \mathbb{E}\left[\mathrm{Tr}(M(t_1)^{j_1})\dots\mathrm{Tr}(M(t_k)^{j_k})\right] =  \mathbb{E}\left[\mathrm{Tr}(M(t_1)^{j_1})\right]\dots\mathbb{E}\left[\mathrm{Tr}(M(t_k)^{j_k})\right]+O(n^{(j_1+\dots+j_k)/2+k-1}).
\end{equation*}

[Lemma 7 of arXiv:2608.18075, '2608.18075'] Let $F_S(t)=\langle\beta_t,S\rho_t\rangle$ on $I\Subset(0,T)$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $S$ is a finite Fourier matrix and $F_S\equiv0$, then
\begin{align}
 F_{[S,\mathcal{C}]}\equiv0
 \qquad\text{for every finite Lie word }\mathcal{C}.
\end{align}
\item Suppose $R_1,R_2$ are finite Fourier matrices,
$F_{R_1}\equiv0$, and $\mathcal{C}_n$ are Lie words with
\begin{align*}
 \mathcal{C}_n\to R_2\quad\text{in }\mathcal B(H^1,H).
\end{align*}
If $F_{[R_1,\mathcal{C}_n]}\equiv0$ for every $n$, then
\begin{align*}
 F_{[R_1,R_2]}\equiv0.
\end{align*}
\end{enumerate}
Thus no operator algebra property of the
$\mathcal B(H^1,H)$ closure is assumed.

[Theorem 29 of arXiv:2605.17296, 'Zero correlations and averaged fields of orthonormal Gaussian Functions'] For every compact $K\subset \C$, as $N \to \infty$, 
\begin{equation*}
\frac{1}{\sqrt{N}} \sum_{k=0}^{N-1}
\Big( \spec_{h_{k}}\cW(\sqrt{N} \cdot ) - 1 \Big) 
\inlawto \widetilde{\cG} \quad \text{ in $C(K)$},  
\end{equation*}
where $\widetilde{\cG}$ is the Gaussian process 
with covariance $\kappa(\sqrt{\pi}|\xi-\eta|)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Weak solution and uniqueness in law of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] \emph{Weak existence} holds for the path-dependent SDE (equation eq:path-dependent-SDE of the paper) if, for any prescribed joint probability law \(\mu \in \mathcal{P}(\mathbb{R}^d\times E \times E)\) governing \((X_0,\lambda,\bar{\lambda})\), there exists a probabilistic setup consisting of:
	\begin{enumerate}
		\item A filtered probability space \((\Omega,\mathcal{F}, \{\mathcal{F}_t\}_{t\in[0,T]}, \mathbb{P})\) equipped with a Wiener process \(W\);
		\item Random variables \(X_0:\Omega\to \mathbb{R}^d\) and \(\lambda,\bar{\lambda}:\Omega\to E\);
		\item An \(\{\mathcal{F}_t\}\)-adapted process \(X\) with continuous paths;
	\end{enumerate}
	such that the joint law of \((X_0,\lambda,\bar{\lambda})\) is exactly \(\mu\), and \(X\) satisfies the integral equation (equation eq:integral-equation-path-dependent-SDE of the paper) \(\mathbb{P}\)-a.s.

	\emph{Uniqueness in law} holds if any two weak solutions starting with the same initial joint law \(\mu\) induce the same pathwise law for \(X\) on \(\mathcal{C}_T^d\).

