body:
[Lemma Lemma-convergence of measures of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $(E,d_E)$ be an arbitrary metric space.
		Let $(\mathbf{P}(E),\widetilde d_E)$  be the corresponding space of probability measures equipped with the Prohorov metric $\widetilde d_E$. Then,  for $\{\mu_n,\mu\}_{n\ge1}\subset \mathbf{P}(E)$, the following conditions (measure conver 2.2 of the paper)--(measure conver 2.4 of the paper) are equivalent and are implied by (measure conver 2.1 of the paper):
		\begin{enumerate}[leftmargin=0.79cm,label={${\bf (\alph*)}$}]\setlength\itemsep{0.2em}
			\item $\widetilde d_E(\mu_n,\mu)\to0$ as $n\to\infty$;
			\item $\mu_n$ converges weakly to $\mu$ as $n\to\infty$;
			\item For all open subset $G\subset E,\, \mu(G) \le \liminf_{n\to\infty}\mu_n(G)$.
		\end{enumerate}

		Moreover, when $(E,d_E)$ is separable, then all the conditions 
		(measure conver 2.1 of the paper)--(measure conver 2.4 of the paper) are equivalent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor prop_2.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Consider a TASEP $(\tilde{x}(t),t\geq 0)$ with a deterministic initial condition $\{x_n^f, n \in \mathbb{Z} \}$ with $x_n^f \leq 0$ for $n \in \mathbb{N}$ and $x_n^f > 0$ for $n \in \mathbb{Z}_{\leq 0}$. Let $d > 1$, define $\hat{c}_2$ and $c_1$ as in Assumption~(assumpt:2.9 of the paper) and suppose that
	\begin{equation}  
	y_T(\tau) \coloneqq \frac{x^f_{\hat{c}_2 \tau T^{2/3}}+d\hat{c}_2 \tau T^{2/3}}{c_1 T^{1/3}}, \ \ \tau \in \mathbb{R}, 
	\end{equation}
	fulfils $y_T(\tau) \geq - 2 (1+d)^{-2} \tau^2$ for $\tau \in [-\hat{c}_2^{-1} (1-d^{-2})T^{1/3}, \hat{c}_2^{-1} d^{-2} T^{1/3}]$ and for all $T$ large enough. Further, suppose that $y_T$ converges uniformly on compact sets to a piecewise continuous and càdlàg function $y$. Then, it holds 
	\begin{equation}
	\begin{aligned} 
	\lim_{T \to \infty} \mathbb{P}(\tilde{x}_{d^{-2} T}(T) > (1-2d^{-1}) T - S T^{1/3})
	&= \mathbb{P}\left( \sup_{\tau \in \mathbb{R}} \{ \mathcal{A}_2(\tau) - \tau^2 - y(-\tau) \} < c_1^{-1} S \right).
	\end{aligned}  
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:2mmnew of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] For $\alpha > 0$ fixed and $\mathcal{A}_j$ defined as above, let us define the event
\begin{equation}
    \mathcal{G} \coloneqq \mleft\{ \# \mleft\{ j \in \mathbb{Z} : |j \Delta| \leqslant T \text{ and } \mathcal{A}_j \text{ holds} \mright\}
    \geqslant \frac{\alpha-2}{\alpha} \mleft( \frac{2T}{\Delta} - 1 \mright) \mright\}.
\end{equation}
Then we have $\mathbb{P}[\mathcal{G} | X^1 ] \geqslant \mleft( \frac{1 - \Delta/2T}{\alpha} \mright)^2$ almost surely.

