[Lemma 10 (Cai--Lu convex positivity) of arXiv:2609.01436, '2609.01436'] Under \cref{ass:CL}, let
$F\in\mathcal B_1^+([0,\infty))$.  If
$\varphi\in C_b^{1,1}([0,\infty))$ is convex, then
\begin{equation}
 \int\mathcal K[\varphi]\,dF^{\otimes3}
 \geq
 \int_{\{0\leq x<y\leq z\}}
 \chi_{y,z}W\Delta_{\mathrm{sym}}\varphi\,dF^{\otimes3}
 \geq0.
\end{equation}

[Definition defn:tie of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] A \emph{term in expansion} of $(\hat{\mathfrak D}_{i_m}^{N_m})^{k_m} \cdots (\hat{\mathfrak D}_{i_1}^{N_1})^{k_1}$ is a sequence $\{O(t), P(t)\}_{t=1}^{Q_m}$, where each $O(t)\in\{+,-,\top\}$ denotes the operation at each step, and each $P(t)$ is a monomial\footnote{In this paper, a monomial refers to a product of powers of variables with nonnegative integer exponents, and a non-zero constant. In particular, any non-zero constant is a monomial.} of $x_1,\ldots, x_N$. For each $\ell\in\llbracket 1, m\rrbracket$, and $t\in \llbracket Q_{\ell-1}+1, Q_\ell \rrbracket$, one of the following is required to hold for $P(t)$ (assuming that $P(0)=1$ for the ease of notations):
\begin{enumerate}
    \item[1:] $O(t)=+$, and $P(t)=\frac{2Nx_{i_\ell}P(t-1)}{\beta}$;
    \item[2:] $O(t)=-$, and $P(t)=\big(\deg_{i_\ell}(P(t-1))+\tfrac{\beta}{2} R(t-1)\big)\frac{P(t-1)}{x_{i_\ell}}$, where $R(t-1)$ is the number of $j\in\llbracket 1, N_\ell\rrbracket$ with $\deg_{i_\ell}(P(t-1))>\deg_j(P(t-1))$;\\
    (We note that in this case, necessarily $\deg_{i_\ell}(P(t-1))>0$, since otherwise $R(t-1)$ would also be zero, and $P(t)$ equals zero, which is not a monomial.)
    \item[3(a):] $O(t)=\top$, and $P(t)=x_{i_\ell}^{-\gamma} x_j^{\gamma-1}\frac{\beta P(t-1)}{2}$ for some $j\in\llbracket 1, N_\ell\rrbracket$ with $\deg_{i_\ell}(P(t-1))\ge \deg_j(P(t-1))+2$, and some $\gamma \in \llbracket 2, \deg_{i_\ell}(P(t-1))- \deg_j(P(t-1))\rrbracket$;
    \item[3(b):] $O(t)=\top$, and $P(t)=-x_{i_\ell}^{\gamma-1} x_j^{-\gamma}\frac{\beta P(t-1)}{2}$ for some $j\in\llbracket 1, N_\ell\rrbracket$ with $\deg_{i_\ell}(P(t-1))\le\deg_j(P(t-1))-1$, and some $\gamma \in \llbracket 1, \deg_j(P(t-1))-\deg_{i_\ell}(P(t-1))\rrbracket$.
\end{enumerate}
In addition, we require that $\deg_i(P(Q_m))=0$ for each $i\in\llbracket 1, N\rrbracket$, i.e., $P(Q_m)$ is a constant.

[Cor cA3 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] For any $q\in (0,p)$
\begin{equation}\begin{aligned}
\sup_{t\in[t_k, t_{k+1})} \mathbf{E}^{(N)}_{t_1,\dots,t_N}\Big[\|\Delta_t^n\|^q\Big|\mathcal{F}_{t_k}\Big]
\leq_C \|\Delta_{t_k}^n\|^q
& + h_n^{(\frac{p-q}{\chi}\wedge q) + (1\wedge\frac{q}{2})}(1+\|X_{t_k}^{(n)}\|^p)
+ h_n^{\frac{p-q}{\chi}\wedge q}(1+\|X_{t_k}^n\|^{p})\\
&+ h_n^{1\wedge\frac{q}{2}}  (U_{t_k}^n)^q
+h_n^{(\frac{p-q}{\chi }\wedge q)   +(1\wedge\frac{q}{2})} (U_{t_k}^n)^{(p-q)\wedge (q\chi)}
+h_n^{1\wedge\frac{q}{2}}
\end{aligned}\end{equation}
for $n$ large enough uniformly over
$N\in\mathbb{N}_0$, partitions $\{t_1,\dots, t_N\}$,  and $k=0, \dots, N$.

