[Proposition 5 (Negative drift of $c_n$) of arXiv:2607.20838, 'Long-memory Markov chains with power-law intensities'] There exists $x_* > 0$ such that the following statements hold.
	\begin{enumerate}
		\item For $0 < x < x_*$, if 
		\begin{equation}
			c > C_1 
			:= \frac{2\mu \gamma + 3 \mu_{\varepsilon} + \sqrt{(2\mu \gamma + 3 \mu_{\varepsilon})^2 
					+ \frac{24  \mu \mu_{\varepsilon} \gamma x_*}{\xi}}}{4\mu}, 
		\end{equation}
		then $\mathbb{E}_{x,c}[c_n] - c < 0$.

		\item For $x \ge x_*$, if 
		\begin{equation}
			c > C_2 
			:= \frac{\gamma + \sqrt{\gamma^2 + \frac{3 \mu_{\varepsilon} \gamma}{k_p \xi}}}{2}, 
		\end{equation}
		then $\mathbb{E}_{x,c}[c_n] - c < 0$.
	\end{enumerate}

