[Lem 48 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Assume that  $a_H < b_H \in \mathbb{R}$ are such that $H(u)=0$ whenever $u \notin (a_H,b_H)$. Then,
	\begin{align*}
		& \frac{1}{n} \sum_{x = - \infty}^{(a_H-1)n} \Bigg\{ \Theta(n) \sum_y | H ( \tfrac{x + q_n^r + y }{n}  )  - H ( \tfrac{x + q_n^r  }{n}  )  |\cdot | y|^{-\gamma-1} \Bigg\}^{2}    \\
		+ & \frac{1}{n} \sum_{x = (b_H+1)n}^{\infty} \Bigg\{ \Theta(n) \sum_y | H ( \tfrac{x + q_n^r + y }{n}  )  - H ( \tfrac{x + q_n^r  }{n}  )  | \cdot | y |^{-\gamma-1} \Bigg\}^{2} \leq C(\gamma) \| H \|_{\infty}^2 \frac{[\Theta(n)]^2}{n^{2\gamma}} (b_H - a_H)^2.
	\end{align*}

