[Proposition pro:covering-packing-4 of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] Consider a metric space $(\mathcal{X},d_\mathcal{X})$, and assume that $d'_\mathcal{X}$ is any other metric on $\mathcal{X}$ such that there exist two constants $C_1,C_2>0$ verifying
$$\frac{1}{C_1}d'_\mathcal{X}(x,y)\leq d_\mathcal{X}(x,y)\leq C_2d'_\mathcal{X}(x,y),$$
for any $x,y\in \mathcal{X}$. Then, for any compact set $K\subset \mathcal{X}$ the following relations holds true
\begin{align*}
\mathcal{N}_{\frac{\varepsilon}{C_2}}(K,d_\mathcal{X}')&\leq \mathcal{N}_\varepsilon(K,d_\mathcal{X})\leq \mathcal{N}_{C_1\varepsilon}(K,d_\mathcal{X}')\\
\mathcal{M}_{C_1\varepsilon}(K,d_\mathcal{X}')&\leq \mathcal{M}_\varepsilon(K,d_\mathcal{X})\leq \mathcal{M}_\frac{\varepsilon}{C_2}(K,d_\mathcal{X}'),
\end{align*}
for every $\varepsilon>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 (Linear Gaussian smoothed likelihood and force) of arXiv:2608.21709, 'Posterior Information Dynamics of Diffusion Models for Linear Inverse Problems'] Let \(X_0\sim\calN(0,\Sigma)\) and
\(R=AX_0+\varepsilon\), where \(\varepsilon\sim\calN(0,\Gamma)\),
\(\Gamma\succ0\), and \(\varepsilon\) is independent of \(X_0\) and of the
forward noising variable used to form \(X_t\).  Define
\begin{equation}

B_t=a_t^2\Sigma+\Delta_t\Id_d,
\qquad
Q=A\Sigma A^\top+\Gamma.
\end{equation}
Then
\begin{equation}

R\mid X_t=x\sim \calN(M_tx,\Sigma_{R\mid t}),
\end{equation}
where
\begin{equation}

M_t=a_tA\Sigma B_t^{-1},
\qquad
\Sigma_{R\mid t}=Q-a_t^2A\Sigma B_t^{-1}\Sigma A^\top.
\end{equation}
Consequently, the exact measurement force is
\begin{equation}

g_t(x,r)=M_t^\top\Sigma_{R\mid t}^{-1}(r-M_tx).
\end{equation}
Under the joint law of \((X_t,R)\),
\begin{equation}

\frac1d\E\|g_t(X_t,R)\|^2
=
\frac1d\operatorname{Tr}
\left(M_t^\top\Sigma_{R\mid t}^{-1}M_t\right).
\end{equation}
Moreover, under the VP schedule \eqref{eq:forward-marginal} (so that
\(\Delta_t=1-a_t^2\)), if along a dimension sequence
\(\lambda_{\min}(\Gamma)\ge\gamma_0>0\) and
\(d^{-1}\|A\Sigma\|_F^2\le C_0\), then as \(a_t\to0\),
\begin{equation}

\frac1d\E\|g_t(X_t,R)\|^2=O(a_t^2),
\end{equation}
which is the Gaussian specialization of
Corollary~\ref{cor:general-high-noise-energy}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop:U_asy of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For the deformed Gaussian matrix $X$ defined in Definition~(def:inhomo of the paper) under Assumptions~(itm:B1 of the paper)--(itm:B2 of the paper) of Definition~(mixingdef of the paper), with $n = \sum_{j=1}^s n_j$ and $a=\|A_N\|_{\mathrm{op}}$, the following statements hold:
\begin{enumerate}[label=(\roman*)]
\item  For all integers $n_j \ge 1$, there exists a constant $C > 0$, independent of $n$ and $N$, such that
\begin{equation} 
\mathbb{E}\Big[\prod_{j=1}^s \operatorname{Tr} \Big(U_{n_j}\big(\frac{X}{2}\big)\Big)\Big]
\le C(1 + a^n)\big(rn+Nb_n\big)^s \exp\big\{C(r+1)^2 n^2b_n \big\}.
\end{equation}
  \item  Let $r$ be fixed. If $a \le 1 + Cn^{-1}$ for some fixed constant $C>0$, $n^2b_n=O(1)$,  $ {\Delta_n}/{b_n}=o(1)$, and $ {\mathcal{E}_n}/{n}=o(1)$ as $N\to \infty$
  , then
  \begin{equation}
   \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \big(U_{n_j}\big(\frac{X}{2}\big)\big)\Big]
    = \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \big( U_{n_j}\big(\frac{\widetilde{X}}{2}\big)\big)\Big]
    + o\big((Nb_n)^s\big).
  \end{equation}
\end{enumerate}

