[Lemma lem:partition_upper_bound of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] For $u\in (0,1]$ and $2\leq r \leq R/32$,
    \begin{align}
         \theta_{r,R} & \leq \theta_{r, 2r}\theta_{8r, R} + \pi_{4r, R/2} + \pi_{r,R/2} + J_1 + J_2,\\
          \theta_{(u), R} & \leq \theta_{(u), 2r}\theta_{8r, R} + \pi_{4r, R/2} + \pi_{2r, R/2} + \pi_{(u), R/2} + J_1 + J_2 + J_3, 
    \end{align}
    and as an immediate consequence,
     \begin{align}
        \theta_{r, R} &\lesssim  \theta_{r}\theta_{8r, R} + \pi_{r, R}  + {J_1 + J_2}, & \\
        \theta_{(u), R} &\lesssim \theta_{(u), {2}r}\theta_{
        8r, R} + \pi_{r, R} + \pi_{(u),R} + J_1 + J_2+J_3, 
    \end{align}
    on $\{r\leq R/32\}$ and where
    \begin{align*}
        J_1 & := \int_{B(0, R/2)\setminus B(0,4r)}\int_{0}^1  \pi_{2r, (y,v)}\theta_{(v), R/2} \, dv \, dy, \\
        {J_2} & :=\int_{B(0,R/2)\setminus B(0,8r)}\int_0^1 \pi_{4r, (y,v)}\theta_{(v), R/2} \, dv \, dy,  \text{ and }\\
        J_3 & := \int_{B(0, R/2)\setminus B(0,4r)}\int_{0}^1  \mathbb P \big( (0,u) \sim (y,v) \big) \theta_{(v), R/2} \,  dv \, dy.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $X$ have density $f$ with respect to $\pi_{T}$ and $T = \E X > 0.$ Then 
    \begin{displaymath}
        \frac{P_{T-s}f(1)}{P_{T-s}f(0)} \le \frac{T}{T-s}
    \end{displaymath}
    for $s < T.$

