[Proposition 11 (Elementary symmetric functions of the principal curvatures) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] Fix a point $x\in \partial K_n$ such that $x_i\neq 0$ for all $i=1,\ldots,n$.
Let $\lambda_1(x),\dots,\lambda_{n-1}(x)$ be the principal curvatures of $\partial K_n$ at $x$. 
Then, for all \(m=1,\dots,n\),
\begin{equation}
\sigma_{m-1}\bigl(\lambda_1(x),\dots,\lambda_{n-1}(x)\bigr)\\
=\frac{1}{
\left(\sum_{i=1}^n (\varphi_i'(x_i))^2\right)^{\frac{m+1}{2}}
}\sum_{i=1}^{n}(\varphi_i'(x_i))^2\sum_{\substack{I\subset \{1,\ldots,r\}\setminus\{i\}\\|I|=m-1}}\prod_{j\in I}\phi''_j(x_j).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:final-dist-bounds of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Under the same assumptions as Theorem~(thm:kl_local_error of the paper),
    \begin{align*}
        \mathtt{d}_t^2
        &\leqslant \exp(-c\omega_+ t)\,\Bigl(\frac{1-\exp(-\omega\,(T+Ah-t))}{1-\exp(-\omega\,(T+Ah))}\Bigr)^{cc_0}\,\mathtt{d}_0^2 + \mathtt{e}_t^2\,,
    \end{align*}
    where $\mathtt{e}_t$ is bounded as follows.
    \begin{enumerate}
        \item \textbf{Convex and high friction case:}
        Let $T_0 \coloneqq T+Ah-|\omega|^{-1}$ and $T_1 \coloneqq T+Ah-|\omega|^{-1}\log(1+c_0|\omega|/\gamma)$.
        Then,
        \begin{align*}
            \mathtt{e}_t^2 \lesssim \begin{dcases}
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{\alpha^2 h^2} + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{\alpha\beta^{1/2} h}\,, & t\leqslant T_0\,, \\[0.25em]
                \Bigl[\frac{(\bar{\mathcal{E}}^{\rm w})^2}{\beta h^2} + (\bar{\mathcal{E}}^{\rm s})^2\Bigr] \, (T+Ah-t)^2 + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{\beta h}\,(T+Ah-t)\,, & t\in [T_0, T_1]\,, \\[0.25em]
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{h^2}\,(T+Ah-t)^4 + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{h}\,(T+Ah-t)^3 
            +\beta^2\,(\bar{\mathcal{E}}^{\rm s})^2\,(T+Ah-t)^6\,, & t \geqslant T_1\,.
            \end{dcases}
        \end{align*}


    \item \textbf{Semi-convex and low friction case:}
        Let $T_0 \coloneqq T+Ah-|\omega|^{-1}$.
        Then,
        \begin{align*}
            \mathtt{e}_t^2 \lesssim \begin{dcases}
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{\beta^2 h^2} + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{\beta^{3/2} h}\,,
                & t\leqslant T_0\,, \\[0.25em]
                \frac{(\bar{\mathcal{E}}^{\rm w})^2}{h^2}\,(T+Ah-t)^4 + \frac{(\bar{\mathcal{E}}^{\rm s})^2}{h}\,(T+Ah-t)^3\,, & t \geqslant T_0\,.
            \end{dcases}
        \end{align*}

    \end{enumerate}
    Moreover, in all cases, $\mathtt{e}_T^2 \lesssim h^2\,(\bar{\mathcal{E}}^{\rm w} + \bar{\mathcal{E}}^{\rm s})^2$.

