[Lem chaos of arXiv:2608.25362, 'Fluctuations of the free energy of the Sherrington--Kirkpatrick model with ferromagnetic i'] {Chen13}}]
    For $\boldsymbol{\beta} \in \mathcal{B}$ and $0 < t < 1$, suppose $(h+\gamma\mu) \neq 0$. Then, for any $\varepsilon > 0$, we have
    \begin{align*}
    \E \langle I\big(\abs{R_{\boldsymbol{\sigma}, \boldsymbol{\tau}} - u_t} \geqslant \varepsilon\big)\rangle_t^{SK} \leqslant K \exp \left( - \tfrac{N}{K}\right),
    \end{align*}
    where $K = K(\varepsilon)$ is a constant independent of $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d.sol_pde_discrete of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] For every smooth increasing path $L:[0,T]\toS^{D}_+$ and $\alpha \in \mathcal M_\mathrm{d}$, the \textbf{Parisi PDE solution} $\Phi=\Phi_{\mu,L,\alpha}$ is defined as follows:
\begin{itemize}
    \item Set $\Phi(T,\cdot) = \phi$ as in~(equation e.phi=initial of the paper).
    \item Inductively, for every $l\in \{1,\cdots,K\}$, $t\in [t_{l-1},t_l)$ and $x\in\mathbb{R}^{D}$, define
    \begin{align}
        \Phi(t,x) = \frac{1}{s_{l-1}}\log\mathbb{E}\exp\left(s_{l-1} \Phi\left(t_l,\,\sqrt{2L(t_l)-2L(t)}g_l+x\right)\right)
    \end{align}
    where $(g_l)_{l\in\{0,\dots,K\}}$ are independent standard $\mathbb{R}^{D}$-valued Gaussian vectors.
\end{itemize}

[Definition def-CTGF of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] Let $\mathfrak{r}\in \mathbb{R}$, $\omega\in\Omega$ and $\boldsymbol{\mathcal{Z}}_\mathfrak{r}\in\mathbb{H}$.	A function $\boldsymbol{\mathcal{Z}}(\cdot):=\boldsymbol{\mathcal{Z}}(\cdot;\mathfrak{r},\omega,\boldsymbol{\mathcal{Z}}_{\mathfrak{r}})$ is called a \textit{weak solution} to system (equation CTGF of the paper) on time interval $[\mathfrak{r}, \infty)$, if $$\boldsymbol{\mathcal{Z}} \in  \mathrm{C}([\mathfrak{r},\infty); \mathbb{H}) \cap \mathrm{L}^{2}_{\mathrm{loc}}(\mathfrak{r},\infty; \mathbb{V})\cap\mathrm{L}^{4}_{\mathrm{loc}}(\mathfrak{r},\infty; \mathbb{W}^{1,4}_0(\mathbb{Q})), \;\;\; \frac{\/\mathrm{d}\/\boldsymbol{\mathcal{Z}}}{\/\mathrm{d}\/ t}\in\mathrm{L}^{2}_{\mathrm{loc}}(\mathfrak{r},\infty;\mathbb{V}^{\prime})+\mathrm{L}^{\frac43}_{\mathrm{loc}}(\mathfrak{r},\infty;\mathbb{W}^{-1,\frac43}(\mathbb{Q})),$$ and it satisfies 
		\begin{itemize}
			\item [(i)] for any $\boldsymbol{\psi}\in \mathbb{X},$ 
			\begin{align}
				\mathopen{}\mathclose\bgroup\originalleft<\frac{\/\mathrm{d}\/\boldsymbol{\mathcal{Z}}(t)}{\/\mathrm{d}\/ t}, \boldsymbol{\psi}\aftergroup\egroup\originalright>&=  - \bigg\langle \nu \mathrm{A}\boldsymbol{\mathcal{Z}}(t)+\mathopen{}\mathclose\bgroup\originalleft[\frac{\sigma^2}{2}-\sigma y(\vartheta_{t}\omega)\aftergroup\egroup\originalright]\boldsymbol{\mathcal{Z}}(t)+\Upsilon^{-1}(t,\omega)\mathrm{B}\big(\boldsymbol{\mathcal{Z}}(t)\big)  + \alpha \Upsilon^{-1}(t,\omega) \mathrm{J}\big(\boldsymbol{\mathcal{Z}}(t)\big) 
				\nonumber \\ & \qquad + \beta \Upsilon^{-2}(t,\omega)\mathrm{K}\big(\boldsymbol{\mathcal{Z}}(t)\big) -\Upsilon(t,\omega) \boldsymbol{\mathfrak{K}}(t) , \boldsymbol{\psi} \bigg\rangle,
			\end{align}
			for a.e. $t\in[\mathfrak{r},\infty);$
			\item [(ii)] the initial data:
			$$\boldsymbol{\mathcal{Z}}(\mathfrak{r})=\boldsymbol{\mathcal{Z}}_\mathfrak{r} \ \text{ in }\ \mathbb{H}.$$
		\end{itemize}

[Corollary of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] Let $(x_i)_{1\le i\le4}$ be in counterclockwise order, and $\lambda=\frac{(x_2-x_1)(x_4-x_3)}{(x_4-x_2)(x_3-x_1)}$ be its cross-ratio. Then
\begin{align*}
\frac{P^{(14)(23)}(x_1,x_2,x_3,x_4)}{P^{\rm total}(x_1,x_2,x_3,x_4)}=A\frac{V_2(\lambda)}{V_0(\lambda)}=A\lambda^2\left(1+\lambda+\lambda^2\left(-\frac{8}{45}|\log\lambda|+\frac{1607}{4950}\right)+O(\lambda^3|\log\lambda|)\right)
\end{align*}
as $\lambda\to0$. Here $A$ is the same constant as in Theorem~(thm:percolation of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

