[Teorema 29 (Lyapunov) of arXiv:2506.11937, 'Random rotational invariance of integration by parts formulas within a Bismut-type approac'] Let $\ a_{ij}:=(\sigma \sigma^T)^{ij} \in W^{1,p}_{loc}(\mathbb{R}^n) \cup C(\mathbb{R}^n)$ 
    and $\mu \in L^p_{loc}(\mathbb{R}^n), p \in (n,\infty).$ A sufficient condition for the martingale problem associated with the infinitesimal generator $ L$ to be well-posed is that, for every $ T > 0$, there exists a number $ M = M_t > 0$ and a non-negative function $\phi \in C^{1,2}(\mathbb{R}^n \times [0,T]) $ such that $\phi$ is a Lyapunov function on $\mathbb{R}^n \times [0,T]$. In this case, the solution process is non-explosive and, for every $ (x,t) \in \mathbb{R}^n \times [0,T]$, the following holds
    \begin{equation*}
        \mathbb{E}_x[\phi(X_t,t)] \leq \exp(Mt) \phi(X_0,0).
    \end{equation*}

[Lemma 11 (Stochastic area inequality) of arXiv:2606.24167, '\bf On the stability of rarefaction for stochastic viscous conservation law'] Let $X_t$ satisfies \eqref{int-dif}-\eqref{young para2}, assume that  
  \begin{enumerate}
      \item[\rm{(A1) }]{ $
\xi_j < \theta^\prime_j(\bar\rho\psi_j -1), \text{ if } \theta^\prime_j>0 \text{ and }\psi_j\geq 0,\, j=1,\cdots, \mathfrak n.$}
      \item[\rm{(A2) }]{  $
\kappa<(\alpha-1)\bar\rho-1.$}
      \item[\rm{(A3) }]{$
\displaystyle\lim_{R \to +\infty} \mathbb P\big(\displaystyle\lim_{t\rightarrow+\infty}C_{t}(\omega) > R\big) = 0.$}  \end{enumerate}
Then for any $\rho<\bar \rho$, almost surely, we have
$X_t =O\big(t^{-\rho}\big).$

[Prop Camrud of arXiv:2412.03560, 'Non-asymptotic entropic bounds for non-linear kinetic Langevin sampler with second-order s'] Under Assumptions~(assu:regularity of the paper) and (assu:moments of the paper), setting $a$ as in~(equation eq:a of the paper), for all $n\in\mathbb N$ and $N\geqslant 1$,
    \begin{equation}

    \mathcal L_a(\nu_{n+1}  ) - \mathcal L_a(\nu_n ) \leqslant - \frac{a h}{3}   \mathcal I(\nu_{n+1} |\nu_\infty^N ) + \left( 9 + \frac1a\right)  C_1  N d^3    h ^5 \,,
    \end{equation}
    with $C_1$ given by~(equation eq:C1 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj GW:vertex of arXiv:2609.02409, 'Membranes and Maps'] For $n\in\{1,\ldots,5\}$ and curve class $\beta = [C_1]+\cdots+[C_n]$, the equivariant Gromov--Witten theory of $Z_n$ is given by
    \begin{equation}

       \GWargs{Z_n}{\mathsf{T}}{\beta} 
       =
       \hat{\mathsf{A}}_{\mathsf{T}}\bigl( \overline{M}_{0}(Z_n,\beta) \bigr) \,,
    \end{equation}
    where $\overline{M}_{0}(Z_n,\beta)$ denotes the moduli space of genus-zero stable maps to $Z_n$ in curve class $\beta$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Proposition sumeq of arXiv:2608.07236, 'Negative association of Busemann functions \\in exponential last-passage percolation'] For any $k\leq m <  n$ and $x, y \in \mathbb{Z}$, we have
\begin{align} 
\sum_{i=k}^n\big[h^i(x) - h^i(y)\big] 
= \sum_{i=k}^n \big[(\sigma^m h)^i(x) -  (\sigma^m h)^i(y)\big] 
= \sum_{i=k}^n \big[(\sigma_{m} h)^i(x) -  (\sigma_{m} h)^i(y)\big].
\end{align}

