    \begin{equs}
        \|K_{N,\mu}^{\otimes1+\mathfrak{s}(\tau)}&\big(\text{$\mathfrak{z}$}^{\tau_2}\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}\big)^\tau\|_{L^\infty_t L^1_{s^\tau}}\\&\lesssim \|   \mathcal{P}_{2N,\mu} \dot G_\mu\|_{\mathcal{L}^{\infty,\infty}}
\|K_{N,\mu}^{\otimes1+\mathfrak{s}(\tau_1)}\text{$\mathfrak{z}$}^{\tau_1}\|_{L^\infty_t L^1_{s^{\tau_1}}}
