[Lem step_t^kappa of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] Let $\alpha \in (0,2)$ and $\beta > 0$. 
	There exist $C,c>0$ such that, for any $s\geq 1$, $t \in [s + s^\kappa,s + 3 s^\kappa]$ and any measurable function $f \colon \mathbb{R}\times (0,\infty) \to \mathbb{R}$, the following holds.
	\begin{enumerate}
		\item If $f \leq 1$, then, for any $M \geq 1$, $\mathopen{}\mathclose\bgroup\originalleft\lvertx\aftergroup\egroup\originalright\rvert \leq Ms^{\kappa/2}$ and $\mathopen{}\mathclose\bgroup\originalleft\lverty\aftergroup\egroup\originalright\rvert \leq Mt^{\kappa/2}$, 
		\[
		\widetilde{G}(s,x;t,y) \geq \frac{ce^{-CM^2}}{t^{\kappa/2}}.
		\]

		\item If $f \geq -1/2$, then, for any $x,y\in \mathbb{R}$ and $\eta \geq 0$,
		\begin{align}
		& \frac{e^{-(y-x)^2/[2(t-s)]}}{\sqrt{2\pi(t-s)}} \nonumber\\
		& \qquad \times \mathbb{E}_{(s,x)} \mathopen{}\mathclose\bgroup\originalleft[ \exp \mathopen{}\mathclose\bgroup\originalleft( - \beta \int_{s}^t \abs{\frac{B_r}{\sqrt{2} r}}^\alpha \mathopen{}\mathclose\bgroup\originalleft( 1+f(B_r,r) \aftergroup\egroup\originalright) \mathop{}\mathopen{}\mathrm{d} r \aftergroup\egroup\originalright)
		\ind{\exists r \in [s,t], \mathopen{}\mathclose\bgroup\originalleft\lvertB_r\aftergroup\egroup\originalright\rvert \geq r^{(\kappa + \eta)/2}}
		\middle| B_t = y \aftergroup\egroup\originalright] \nonumber \\
		& \leq C \exp \mathopen{}\mathclose\bgroup\originalleft( - c t^{\eta \alpha/2}
		- c \mathopen{}\mathclose\bgroup\originalleft( \frac{\mathopen{}\mathclose\bgroup\originalleft\lvertx\aftergroup\egroup\originalright\rvert}{s^{\kappa/2}} \aftergroup\egroup\originalright)^{\alpha} 
		- c \mathopen{}\mathclose\bgroup\originalleft( \frac{\mathopen{}\mathclose\bgroup\originalleft\lverty\aftergroup\egroup\originalright\rvert}{t^{\kappa/2}} \aftergroup\egroup\originalright)^{\alpha}
		\aftergroup\egroup\originalright).  
		\end{align}		
	\end{enumerate}

