[Deff convolutions of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] We use $*$ to denote convolution and $\diamond$ to denote stochastic convolution. That is,
    \begin{equation}
        (S * y)_t \coloneqq \int_0^tS(t-s)y_sds \quad \text{and} \quad (S \diamond Z)_t \coloneqq \int_0^t S(t-s)Z_sdW_s \,.
    \end{equation}

[Theorem 6 of arXiv:2603.27940, '\Large \bf Stability of supermartingale optimal transport problems'] Fix $r\in[1,\infty)$, and let X and Y be Polish subspaces of $\R$. Let $C:X \times\sP_r(Y)\to\R$ be measurable, continuous and convex in the second argument. Assume that there exists $K>0$ such that
$$
\lvert C(x,m)\lvert\leq K\left(1+\lvert x\lvert^r+\int_{Y}\lvert y\lvert^rm(dy)\right),\qquad \forall (x,m)\in X\times\sP_r(Y).
$$
Fix $\mu\in\sP_r(X),\nu\in\sP_r(Y)$ with $\mu\cvd \nu$. Let $\mu^k\in\sP_r(X),\nu^k\in\sP_r(Y)$ satisfy $\mu^k\cvd\nu^k$, and  let $\mu^k,\nu^k$ converge to $\mu$ and $\nu$ under $W_r$, respectively. Then
\begin{equation}
\lim_{k\to\infty} V^C_S(\mu^k,\nu^k) =  V^C_S(\mu,\nu)
\end{equation}
holds under one of the following conditions:
 \begin{itemize}
        \item[(A'')] $C$ is continuous;
        \item[(B'')] $\mu^k$ converges strongly to $\mu$. 
    \end{itemize}
For $k\in\N$, let $\pi^{*,k}\in\Pi_S(\mu^k,\nu^k)$ be a minimiser of $V^C_S(\mu^k,\nu^k)$. Then any accumulation point of $(\pi^{*,k})_{k\in\N}$ (with respect to the weak convergence) is a minimiser of $V^C_S(\mu,\nu)$. If $V^C_S(\mu,\nu)$ has a unique minimiser $\pi^*\in\Pi_S(\mu,\nu)$, then 
\begin{equation}
\pi^{*,k}\xrightarrow{k\to\infty}\pi^*\quad\textrm{in } W_r,
\end{equation}
If moreover, $C$ is strictly convex in the second argument, then the convergence in \eqref{eq:thmCouplingconvergence} holds in $A\Wc_r$.

[Lemma lem:two-inside of arXiv:2609.00645, 'Global persistence of nearly radial concentrated vortices in a bounded domain'] There exist $\delta,\varepsilon_{\rm in},C_{\rm two}>0$, depending only on
$D,\rho$, and $\mathbf a_{*,i},\kappa_i,M_i,R_i$, $i=1,2$, such that the
following holds.

If $0<\varepsilon<\varepsilon_{\rm in}$ and, at some time $t$,
\begin{equation}
  S_\varepsilon(t)\subset\overline{V_\rho},
  \qquad d_\varepsilon(t)\leq\delta,
\end{equation}
then
\begin{align}
  &d_\varepsilon(t)
  +\sup_{\mathbf b\in S_\varepsilon(t)}
  [\mathcal W(\mathbf b)-W_*]
  \leq C_{\rm two}\eta^{(2)}_{\varepsilon,0}.

\end{align}

[Defi 2 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $p \in (0, \infty)$ and assume
 $\{K_n : n \ge 1\}$ is a family of compact subsets of $\cX$. A collection $\{X^n_s : s\in S_n, n \ge 1\}$ of $\cX$-valued random elements is \textit{$(\nu_n)$-compactly uniformly $p$-th order integrable w.r.t. $\{K_n\}$} (or $(\nu_n)$-$\CUI(p)$ w.r.t. $\{K_n\}$, for short) if:
	\begin{enumerate}[\rm (a)]
		\item the map $(\omega, s) \mapsto X^n_s(\omega)$ is $\cF \otimes \cS_n/\cB(\cX)$-measurable for every $n \ge 1$,

		\item  the following convergence holds:
		\begin{align}
			\lim_{n \to \infty} \bE\int_{S_n} \lt\|X^n_s\rt\|^p \1_{\{X^n_s \notin K_n\}} \nu_n(\od s)  =0.
		\end{align}
	\end{enumerate}

[Proposition of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] \begin{equation} 
\delta^M_{I_\ell}=\mathrm{o}(1) \implies N_{I_\ell}^M=\Theta\left( \ell^{n-1}{|I_\ell|} \right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

