body:
[Theorem thm: SSQ Tail bound of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] Under the heavily overloaded Assumption (ass:heavy_overload of the paper) with $\gamma\leq \gamma_0$ (see (equation eq: gamma assumption for SSQ W-p of the paper)), the following inequalities hold,
    \begin{enumerate}[label=(\alph*), ref=\thetheorem~(\alph*)]
        \item 
        For constant deviation $a>0$ and $\gamma\leq (\gamma_a \land \gamma_0)$ (see (equation eq: gamma_a of the paper)), there exists $D_{1,\lambda,\mu}'$ independent of $\gamma$ and $a$ (see (equation eq: Tail bound, first regime of the paper)), such that
        \begin{align*}
            \left|\,\mathbb{P}(\tilde{q} > a) - \mathbb{P}(Z > a)\,\right| 
            \leq D_{1,\lambda,\mu}'\,\sqrt{\gamma}\,\big[\ln(1/\sqrt{\gamma}) + a^2/2\big]\,e^{-a^2/2}
        \end{align*}

        \item 
        For $D_{Tail,2,l} \leq a_{\gamma} \leq D_{Tail,2,u}/\gamma^{\delta}$, $\delta \in (0,1/2-\alpha)$ (see (equation eq: near constant deviation setup of the paper)), we have
        \begin{align*}
            \left|\mathbb{P}(\tilde{q} > a_{\gamma}) - \mathbb{P}(Z > a_{\gamma})\right| 
            &\leq \frac{e D_{1,\lambda,\mu}}{\sqrt{2\pi}}\, \sqrt{\gamma}\, \left[\ln(1/\sqrt{\gamma}) + \frac{a_{\gamma}^2}{2}\right] e^{-a_{\gamma}^2/2 \left(1 - \frac{D_{1,\lambda,\mu}\sqrt{\gamma}[\ln(1/\sqrt{\gamma}) + a_{\gamma}^2/2]}{a_{\gamma}}\right)} 
            + \sqrt{\gamma}\, e^{-a_{\gamma}^2/2}
            \\
            \mathbb{P}(\tilde{q} > a_{\gamma}) &\geq \frac{2}{3}\exp\left\{
                -\frac{a_{\gamma}^2}{2}
                + \triangle \ln\left(1+\frac{\frac{\sqrt{\lambda}}{\sqrt{\gamma}} a_{\gamma}+\triangle/2}{\lambda/\gamma}\right)
                + \frac{\triangle^2}{8\lambda/\gamma}
                - \frac{\left(\frac{\sqrt{\lambda}}{\sqrt{\gamma}} a_{\gamma}+\triangle/2\right)^3}{3(\lambda/\gamma)^2}
            \right\} =: L_{\lambda,\mu}(a_{\gamma},\gamma),
        \end{align*}
        where $\triangle:= 8\sqrt{\frac{\sqrt{\lambda}}{\sqrt{\gamma}} a_{\gamma} + \lambda/\gamma}$.

        \item 
        For $D_{Tail,3,l}/\gamma^{1/2-\alpha} \leq a_{\gamma} \leq D_{Tail,3,u}/\sqrt{\gamma}$ (see (equation eq: sub-Gaussian deviation setup of the paper)),
        \begin{align*}
            L_{\lambda,\mu}(a_{\gamma},\gamma) \leq \mathbb{P}(\tilde{q} > a_{\gamma})
            \leq \min\Bigg\{&\; \mathbb{P}(Z > a_{\gamma}) + \frac{e}{2\sqrt{\pi}}\, a_{\gamma}\, e^{-\frac{a_{\gamma}^2}{2}\big(1-\sqrt{1/2}\big)^2} 
            + \exp\!\left(-\frac{a_{\gamma}^2}{2e^2 D_{2,\lambda,\mu}}\right), \\
            &\; A_{\lambda,\mu}\, \exp\!\left(-\frac{a_{\gamma}^2}{2\lambda/\gamma} + \frac{a_{\gamma}^3}{2(\lambda/\gamma)^2}\right)
            \Bigg\}
        \end{align*}
        with $D_{2,\lambda,\mu}$ as in (equation eq: Wasserstein-$p$ bound, second regime of the paper), $L_{\lambda,\mu}(a_{\gamma},\gamma)$ as above, and $A_{\lambda,\mu}$ as in (equation eq: MGF for q_infty - lambda/mu/gamma, Poisson style of the paper).

        \item 
        For $a_{\gamma} \geq D_{Tail,4,l}/\sqrt{\gamma}$ (see (equation eq: large deviation setup of the paper)),
        \begin{align*}
            \mathbb{P}(\tilde{q} > a_{\gamma})
            &\leq
            \min\Bigg\{\,
            \mathbb{P}(Z>a_{\gamma}) + \frac{e}{2\sqrt{2\pi}}\,a_{\gamma}\,e^{-a_{\gamma}^2/8}
            + \exp\!\Big(-\frac{\sqrt{\lambda}}{2eD_{3,\lambda,\mu}}\cdot\frac{a_{\gamma}}{\sqrt{\gamma}}\log(1+a_{\gamma}\sqrt{\gamma})\Big),\\
            &\qquad\qquad\qquad\qquad\;
            A_{\lambda,\mu}\exp\!\Big(\frac{\sqrt{\lambda}}{\sqrt{\gamma}}a_{\gamma}
            - \Big(\frac{\lambda}{\gamma}+\frac{a_{\gamma}\sqrt{\lambda}}{\sqrt{\gamma}}\Big)
              \log\Big(1+\frac{a_{\gamma}}{\sqrt{\lambda/\gamma}}\Big)\Big)
