[Lemma coalescent_yields_random_chain of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix a choice sequence $\mathbf x$ such that Assumption~$\hyperref[ass:A]{\mathbf{x}}$(item:geq1 of the paper) is satisfied. For $m,n \in \mathbb{N}$, we have $|\mathcal {J}_n^{(m)}(\mathbf x)| = A_n!F_n!|\mathcal {I}_n^{(m)}(\mathbf x)|$ and the Kingman $(m,n)$-coalescent with freezing yields a uniform element of $\mathcal {J}_n^{(m)}(\mathbf x)$.
\proof
Let $(g_n,\ldots,g_1)$ be an element of $\mathcal {J}_n^{(m)}(\mathbf x)$. Here, $g_n$ is always the graph consisting of $A_n$ vertices labelled $a_1\ldots,a_{A_n}$ and $F_n$ vertices labelled $f_1,\ldots,f_{F_n}$ with no edges. At each step $i\geq 2$ such that $x_i=1$, there are $\binom{A_i}{(m+1)\wedge A_i}$ many possibilities to select $(m+1)\wedge A_i$ roots out of the $A_i$ active roots. Then, we choose one out of these $(m+1)\wedge A_i$ selected roots to be the losing root. As we connect the losing root to the other selected roots by directed edges, each choice of these $(m+1)\wedge A_i$ roots and a loser amongst them leads to a distinct realisation of the sequence $(g_n,\ldots,g_1)$. On the other hand, for each step $i\geq 2$ such that $x_i=-1$, we activate a uniform frozen vertex and relabel it $i$. As this relabelling does not depend on which frozen vertex we selected, the sequence $(g_n,\ldots,g_1)$ is only affected by the order in which the vertices $f_1,\ldots,f_{F_n}$ are chosen to be activated. Consequently, we have
\begin{equation}

|\mathcal {J}_n^{(m)}(\mathbf x)| = F_n!\prod_{\substack{2\leq i\leq n\\ x_i=1}}((m+1)\wedge A_i)\binom{A_i}{(m+1)\wedge A_i}=F_n!\prod_{\substack{2\leq i\leq n\\ x_i=1}}A_i \binom{A_{i-1}}{m\wedge A_{i-1}},
\end{equation}
where the last step uses that $\ell \binom k\ell =k\binom{k-1}{\ell-1}$ for all $k\geq \ell\geq 1$ and that $A_i=A_{i-1}+1$ when $x_i=1$. By Lemma~(prop:cardinality_increasing_dags of the paper), to prove that $|\mathcal{J}_n^{(m)}(\mathbf x)|=A_n!F_n!|\mathcal{I}_n^{(m)}(\mathbf x)|$, it suffices to show that
\begin{equation}

\prod_{\substack{2\leq i\leq n\\ x_i=1}}A_i  = A_n!\prod_{\substack{2\leq j\leq n \\ x_j=-1}} A_{j-1}=A_n!\prod_{\substack{2\leq j\leq n\\ x_j=-1}}(A_j+1).
\end{equation}
This readily follows from the fact that every step $j$ such that $x_j=-1$ can be uniquely paired with the largest step $i<j$ such that $x_i=1$ and $A_i=A_j+1$, and that the remaining $A_n$ many steps $i$ such that $x_i=1$ satisfy that the values of $A_i$ are unique and in $\{1,2,\ldots, A_n\}$. Since all selections in the Kingman $(m,n)$-coalescent are uniform, it follows that $(G_n,\ldots, G_1)$ is a uniform element of $\mathcal{J}_n^{(m)}(\mathbf x)$.\qed (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 35 of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] Let $\Gamma$ be a ribbon graph with partial ribbon-colouring $\mathbf{K}$. Let $T$ be a ribbon subtree whose edges are uncoloured. Then $\mathbf{K}$ induces a (partial) ribbon-colouring $\mathbf{K}_{/T}$ of $\Gamma/T$.

    \begin{enumerate}
        \item There is a canonical ``composition'' isomorphism $\bigcirc:\mathcal{V}_{\mathbf{K}}(\Gamma)\rightarrow\mathcal{V}_{\mathbf{K}_{/T}}(\Gamma/T)$.
        \item If $\Gamma$ is in addition an embedded ribbon graph in a manifold $M$, the corresponding embedded ribbon graph $\Gamma/T$ in $M$ satisfies $$\tau(M,\Gamma,\mathbf{K},\mathbf{f}) = \tau(M,\Gamma/T,\mathbf{K}_{/T},\bigcirc(\mathbf{f}))$$ for each $\mathbf{f}\in\mathcal{V}_\mathbf{K}(\Gamma)$.
    \end{enumerate}

[Lemma 4 of arXiv:2604.20617, 'Structured random perturbations of \\ tridiagonal twisted Toeplitz matrices'] For all sufficiently large $n$, for every $z\in K$ and every $k\ge1$: 
\begin{enumerate} 
\item $Y_k^{(n)}(z)\in\mathcal{C}$; 
\item \[ \bigl(\rho(z)-2\delta_n\bigr)|u_{k-1}| \le |u_k| \le \bigl(\rho(z)+2\delta_n\bigr)|u_{k-1}|. \] 
\end{enumerate}
Consequently, 
\begin{equation}

\bigl(\rho(z)-2\delta_n\bigr)^n |u_0| \le |u_n| \le \bigl(\rho(z)+2\delta_n\bigr)^n |u_0|.
\end{equation}

[Lemma majorization_property of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\mathcal{B}, \tilde{\mathcal{B}}: \R^{d_1 \times d_2} \to \R^{d_1 \times d_2}$ be linear operators.
    Let $\mathbf{P}_{\mathbf{U}} \in \R^{d_1 \times d_1}, \mathbf{P}_{\mathbf{V}} \in \R^{d_2 \times d_2}$
    be orthogonal projection matrices.
    Denote by $\mathbf{P}_{\mathbf{U},\bot} := \mathbf{I} - \mathbf{P}_{\mathbf{U}}$ 
    and 
    $\mathbf{P}_{\mathbf{V},\bot} := \mathbf{I} - \mathbf{P}_{\mathbf{V}}$
    the projections onto the orthogonal complement.
    Define the operation
    $\mathcal{C} (\mathbf{A}) := \mathbf{P}_{\mathbf{U}} \mathbf{A} \mathbf{P}_{\mathbf{V}} + \mathbf{P}_{\mathbf{U},\bot} \mathbf{A} \mathbf{P}_{\mathbf{V},\bot}$
    for any matrix $\mathbf{A} \in \R^{d_1 \times d_2}$.
    Let now $\mathbf{Z} \in \R^{d_1 \times d_2}$ be fixed.
    Assume that the following properties hold:
    \begin{enumerate}
        \item 
        Assume that 
        $ \mathbf{Z} = \mathcal{C} (\mathbf{Z}) $.
        \item $\mathcal{B}$ is self-adjoint, i.e.,
        $\innerproduct{ \mathcal{B}(\mathbf{W}_1), \mathbf{W}_2 }
        = \innerproduct{ \mathbf{W}_1, \mathcal{B}(\mathbf{W}_2) }$
        for all $\mathbf{W}_1, \mathbf{W}_2 \in \R^{d_1 \times d_2}$.
        In addition, $\mathcal{B}$ is positive definite,
        i.e., $\innerproduct{ \mathcal{B}(\mathbf{W}_1), \mathbf{W}_1 } > 0$
        for all $\mathbf{W}_1 \in \R^{d_1 \times d_2} \backslash \{ \mathbf{0} \}$.
        \item $\tilde{\mathcal{B}}$ is self-adjoint and positive definite.
        \item It holds that 
        \begin{equation*}
          \mathcal{C}
          (\tilde{\mathcal{B}} 
          ( 
            \mathcal{C} ( \hat{\mathbf{W}} ) 
          )
          )
          =
          \mathcal{C} ( \mathcal{B} ( \mathcal{C} ( \hat{\mathbf{W}} ) ) )
        \end{equation*}
        for any matrix $\hat{\mathbf{W}} \in \R^{d_1 \times d_2}$. 
        \item It holds that 
        \begin{equation}
           \mathbf{P}_{\mathbf{U}} \tilde{\mathcal{B}} 
           ( \mathcal{C} ( \hat{\mathbf{W}} )  ) \mathbf{P}_{\mathbf{V},\bot} 
           +
           \mathbf{P}_{\mathbf{U},\bot} \tilde{\mathcal{B}} 
           ( \mathcal{C} ( \hat{\mathbf{W}} )  ) \mathbf{P}_{\mathbf{V}}
           = \mathbf{0}
        \end{equation}
        for any matrix $\hat{\mathbf{W}} \in \R^{d_1 \times d_2}$.
    \end{enumerate}
    Define $\mathbf{W} := \mathcal{B}^{-1} (\mathbf{Z})$
    and $\widetilde{\mathbf{W}} := \tilde{\mathcal{B}}^{-1} (\mathbf{Z})$.
    Then it holds that
    \begin{equation*}
        \langle  \mathbf{Z}, \mathbf{W}  \rangle_{F}
        \ge 
        \innerproduct{\mathbf{Z}, \widetilde{\mathbf{W}}}.
    \end{equation*}

