[Lemma 9 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Suppose the assumptions \eqref{eq_ratio}, \eqref{assm3}, and \eqref{assm_gap} hold. Then
there exists sufficiently small constant $\wt c>0$ such that the following estimates hold:
\begin{itemize}
\item[(1)] We have
\begin{equation}
\rho_{\al c}(x) \sim \sqrt{\lambda_+-x}, \quad  \text{ for } \ \ x \in \left[\lambda_+ - 2\wt c,\lambda_+ \right],\ \al\in\{1,2\}.
\end{equation}
\item[(2)] For $z =E+\ii \eta\in S(\wt c,C_0,-\infty)$ and $\al\in\{1,2\}$, 
\begin{equation}
\vert m_{\al c}(z) \vert \sim 1,  \quad  \im m_{\al c}(z) \sim \begin{cases}
    {\eta}/{\sqrt{\kappa+\eta}}, & \text{ if } E\geq \lambda_+ \\
    \sqrt{\kappa+\eta}, & \text{ if } E \le \lambda_+\\
  \end{cases}.
\end{equation}
\item[(3)] There exists a constant $\tau'>0$ such that
\begin{equation}
\min_{\mu} \vert 1 + m_{1c}(z)\wt \sigma_\mu \vert \ge \tau', \quad \min_{i} \vert 1 + m_{2c}(z)\sigma_i  \vert \ge \tau',
\end{equation}
for any $z \in S(\wt c,C_0,-\infty)$.
\end{itemize}
The estimates \eqref{SQUAREROOT} and \eqref{Immc} also hold for $\rho_c$ and $m_c$.

[Thm decomp of arXiv:2605.21366, 'The Martin boundary of the Directed Landscape'] The following holds on a full probability event.
    For any $x_0,s_0\in\mathbb{R}$, and any eternal solution $\mathfrak h$ with $\mathfrak h(x_0,s_0)=0$, we have for all $x,s\in\mathbb{R}$
    \begin{align}
    \mathfrak h(x,s)=\sup_{\theta\in\mathbb{R},{\raisebox{0.5pt}{\scaleobj{0.7}{\boxempty}}}\in\{-,+\}}\{W^{\theta{\raisebox{1pt}{\scaleobj{0.6}{\boxempty}}}}(x,s;x_0,s_0)+a^{\theta{\raisebox{1pt}{\scaleobj{0.6}{\boxempty}}}}_{(x_0,s_0)}(\mathfrak h)\}
    \end{align}
    and
    \begin{align}
    \sup_{\theta\in\mathbb{R},{\raisebox{0.5pt}{\scaleobj{0.7}{\boxempty}}}\in\{-,+\}}a^{\theta{\raisebox{1pt}{\scaleobj{0.6}{\boxempty}}}}_{(x_0,s_0)}(\mathfrak h)=0.
    \end{align}

