[Lemma l4.1 of arXiv:2603.14447, '\Large \bf Backward doubly stochastic differential equations with and without reflection u'] \sl
		Let the conditions \(\textbf{(A2)}\) and \(\textbf{(G2)}\) be satisfied. Moreover, let \( C >0 \) be a constant, \(a:[0,T] \longmapsto \mathbb{R}_+ \) and \( b: [0,T]\longmapsto \mathbb{R}_+\) be two non-negative functions, such that for all \((t,y,z)\in [0,T]\times\mathbb{R}\times\mathbb{R}^d\), 
		\begin{align*}
			|f(t,y,z)|\leqslant a_t+b_t|y|+C|z|^2.
		\end{align*}
		If \((Y,Z)\in S^\infty_{\mathbb{F}}([0,T];\mathbb{R})\times L^2_{\mathbb{F}}([0,T];\mathbb{R}^d)\) is a solution of BDSDE (equation 1 of the paper),
		then for any \(t\in[0,T]\),
		\begin{align}
			Y_t\leqslant  \|\xi\|_{\infty}\exp\left\{\int_t^T b_sds\right\}+\int_t^T a_s \exp\left\{\int_t^s b_rdr\right\}ds+\frac{4C}{1-\alpha}\int_t^T|\lambda(s)|^2\exp\left\{\int_t^s b_rdr\right\}ds,\quad\ \hbox{a.s.}
		\end{align}
		respectively,
		\begin{align}
			\Big(	Y_t\geqslant   -\|\xi\|_{\infty}\exp\left\{\int_t^T b_sds\right\}-\int_t^T a_s \exp\left\{\int_t^s b_rdr\right\}ds-\frac{4C}{1-\alpha}\int_t^T|\lambda(s)|^2\exp\left\{\int_t^s b_rdr\right\}ds,\quad\ \hbox{a.s.} \Big)
		\end{align}
		Furthermore, there exists a constant $\hat{K}>0$ which depends on $\alpha,C,T, \|a\|_{L^1([0,T];\mathbb{R}_+)}, \|b\|_{L^1([0,T];\mathbb{R}_+)}$ and $\|Y\|_{S_{\mathbb{F}}^\infty([0,T];\mathbb{R})}$, such that
		\begin{align}
			\mathbb{E}\int_0^T|Z_s|^2ds\leqslant\hat{ K}.
		\end{align}

