[Lemma lem:secondhalfsum of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] Fix some $a>1$ and $b>0$. Let the sequence $v_k$ be such that
\begin{align}

    |v_k| \le \frac{C\log^d k}{k^a}.
\end{align}
Then there exist polynomials $K_\nu$ of degree $\nu$ such that the following equality holds uniformly in $z$:
\begin{align*}
    \sum_{k=2}^{\lfloor n/2\rfloor} 
        \frac{z^m v_k}{(n-k)^{b}}e^{-\frac{z^2}{2 (n-k)}}
=
    \frac{z^m}{n^b} 
    e^{-\frac{z^2}{2 n}}
    \sum_{\nu=0}^{\lfloor a \rfloor-1}
            \frac{K_{\nu}(z^2/n)}{n^{\nu}}
+
    O\left(\frac{\log^{d+\delta_a} n}{n^{a+b-m/2-1}}\right),
\end{align*}
where $\delta_a:={\rm 1}\{a\in\mathbb N\}$.

[Proposition 20 (Uniform spectral lower bound) of arXiv:2608.30211, '2608.30211'] For $\mu_\varrho$ from \eqref{eq:mu-rho},
\begin{equation}
 \liminf_{\kappa\to\infty}\inf_{\varrho\in[0,1]}
 \bigl(\Lambda_{\kappa,\varrho}-\mu_\varrho\bigr)\geq0.
\end{equation}
As a consequence, with $\mu_*$ from \eqref{eq:uniform-gap}, there is
$\kappa_1(f,\Omega)$ such that
\begin{equation}
 \Lambda_{\kappa,\varrho}\geq\frac{\mu_*}{2}
 \qquad(\kappa\geq\kappa_1,\ \varrho\in[0,1]).
\end{equation}

[Lemma lem:It_decay of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d\ge 1$ and $t > 0$.
For any integer $n \in [0, 2 \vee (d-1)]$, we have
\begin{equation} 
\abs{ I_{t} (x) }
	\lesssim \frac 1 {(1+\sqrt t  )^d}
	\biggl( \frac{ 1 + \sqrt t } { \abs{ x - \integer{t \eta} } } \biggr)^n
\end{equation}
(here $n=0$ means the factor is absent)
with a constant depending only on
$n, d, M, K_{\mathrm{IR}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 19 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $\mathbf{D}^{(n)}$ be an ordered finite subset of $\R$ with cardinality $|\mathbf{D}^{(n)}| = n+1$ for any $n \geq 2$, and $X^{(n)} : \Omega \rightarrow \mathbf{D}^{(n)}$ be a random variable with probability mass function
\begin{align}
\P\left(X^{(n)} = d^{(n)}_j\right) = \T^{(1)}_{n,j} \notag
\end{align}
for every $d^{(n)}_j \in \mathbf{D}^{(n)}$. Then, the following hold:
\begin{enumerate}
\item $X^{(2)}$, $X^{(3)}$ and $X^{(4)}$ are log-concave random variables with $\mathcal{I}_{|\mathbf{D}^{(n)}|}^{(0)} = \mathcal{I}_{|\mathbf{D}^{(n)}|}$ for $n=2,3,4$
\item $X^{(n)}$ is a \emph{near}-log-concave random variable of degree \emph{1} with $\mathcal{I}_{|\mathbf{D}^{(n)}|}^{(1)} = \mathcal{I}_{|\mathbf{D}^{(n)}|}\setminus\{4\}$ for every $n\geq 5$
\end{enumerate}
given that $\mathcal{I}_{|\mathbf{D}^{(n)}|} = \{2,\ldots,|\mathbf{D}^{(n)}|-1\}$ for every finite $n\geq 2$.

