[Definition of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] An upper semicontinuous function $F : \mathbb{R} \times (0,+\infty) \to \mathbb{R}$ is said to satisfy the differential inequality $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial_{x}^{2} F ) + Q(F) \leq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ if it has the following property: If $\varphi$ is a smooth function defined in some open set $U \subseteq \mathbb{R} \times (0,+\infty)$ and if there is a point $(x_{0},t_{0}) \in U$ at which $\varphi$ touches $F$ from above (that is, $F(x,t) \leq \varphi(x,t)$ for all $(x,t) \in U$ with equality when $(x,t) = (x_{0},t_{0})$), then
		\begin{align*}
			\partial_{t}\varphi(x_{0},t_{0}) - \mathcal{F} ( \partial_{x} \varphi(x_{0},t_{0}), \partial_{x}^{2} \varphi(x_{0},t_{0}) ) + Q( \varphi(x_{0},t_{0}) ) \leq 0.
		\end{align*}

	A lower semicontinuous function $G : \mathbb{R} \times (0,+\infty) \to \mathbb{R}$ is said to satisfy the differential inequality $\partial_{t} G - \mathcal{F} ( \partial_{x} G, \partial_{x}^{2} G ) + Q(G) \geq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ if it has the following property: If $\varphi$ is a smooth function defined in some open set $U \subseteq \mathbb{R} \times (0,+\infty)$ and if there is a point $(x_{0},t_{0}) \in U$ at which $\varphi$ touches $F$ from below (that is, $F(x,t) \geq \varphi(x,t)$ for all $(x,t) \in U$ with equality when $(x,t) = (x_{0},t_{0})$), then
		\begin{align*}
			\partial_{t} \varphi(x_{0},t_{0}) - \mathcal{F} ( \partial_{x} \varphi(x_{0},t_{0}), \partial_{x}^{2}\varphi(x_{0},t_{0}) ) + Q( \varphi(x_{0},t_{0}) ) \geq 0.
		\end{align*}

	A continuous function $F : \mathbb{R} \times (0,+\infty) \to \mathbb{R}$ is said to satisfy the differential equation $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial^{2}_{x} F ) + Q(F) = 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$ if it satisfies both $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial_{x}^{2} F ) + Q(F) \leq 0$ and $\partial_{t} F - \mathcal{F} ( \partial_{x} F, \partial^{2}_{x} F ) + Q(F) \geq 0$ in the viscosity sense in $\mathbb{R} \times (0,+\infty)$.

[Lem 15 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)$ be a subgraph of $\mathbb Z^d$. Let $J\in (\mathbb R^+)^E$, $\mathsf{h}\in \mathbb R^V$, and $A\subset V$. Then, for every $x\in V$,
\begin{equation}
	\partial_{\mathsf{h}_x}\langle \sigma_A\rangle_{G,J,\mathsf{h}}=\langle \sigma_A;\sigma_x\rangle_{G,J,\mathsf{h}},
\end{equation}
and for every $uv\in E$,
\begin{equation}
	\partial_{J_{uv}}\langle \sigma_A\rangle_{G,J,\mathsf{h}}=\langle \sigma_A;\sigma_u\sigma_v\rangle_{G,J,\mathsf{h}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 1 (Ideal weak equivalence implies path correctness) of arXiv:2608.29107, 'PathGuide: Dynamic Classifier-Free Guidance via On-Policy Transport Alignment'] Fix condition $y$. Assume that the generated rollout distribution $\hat{p}_s(\cdot \mid y; \omega_{[0,s)})$ is weakly continuous in time and satisfies the weak continuity identity with the guided field $v_s^\theta$ (per Assumption~\ref{ass:rollout-law}):
\begin{equation}
\frac{\mathrm{d}}{\mathrm{d}s}\int_{\mathbb{R}^d}\psi(x)\, \hat{p}_s(x\mid y; \omega_{[0,s)}) \,\mathrm{d}x
=
\int_{\mathbb{R}^d} \nabla\psi(x)\cdot v_s^\theta(x \mid y; \omega_s)\, \hat{p}_s(x\mid y; \omega_{[0,s)}) \,\mathrm{d}x
\end{equation}
for every $\psi \in C_c^\infty(\mathbb{R}^d)$ and almost every $s \in [0, t]$. 

Assume further that the guided field and the exact velocity field $u_s(\cdot \mid y)$ are weakly equivalent under the generated rollout:
\begin{equation}
\int_{\mathbb{R}^d} \nabla\psi(x)\cdot v_s^\theta(x \mid y; \omega_s)\, \hat{p}_s(x\mid y; \omega_{[0,s)}) \,\mathrm{d}x
=
\int_{\mathbb{R}^d} \nabla\psi(x)\cdot u_s(x \mid y)\, \hat{p}_s(x\mid y; \omega_{[0,s)}) \,\mathrm{d}x.
\end{equation}
Since the exact conditional path $p_s(\cdot \mid y)$ is the unique weak solution to the continuity equation driven by $u_s(\cdot \mid y)$ (under Assumption~\ref{ass:ce-uniqueness}) with the same initial condition $\hat{p}_0 = p_0$, then
\begin{equation}
\hat{p}_s(\cdot \mid y; \omega_{[0,s)}) = p_s(\cdot \mid y), \qquad \forall s \in [0,t].
\end{equation}

