[Prop 34 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\mc{K}\subset\subset \C$. Let $\phi_{\mu_N}$ be as in \eqref{Expression simplifiée du potentiel logarithmique en fonction du déterminant} and $\phi_{\widetilde{\mu}_N}$ be as in \eqref{Expression simplifiée du potentiel logarithmique en fonction du déterminant - 2}. Let $\beta>0$ be as in Proposition \ref{Différence des potentiels loga entre mu_N tilde et mu}. Then, there exists $C_0>0$ such that for all $z\in \mc{K}$, 
    \begin{equation}
        \begin{split}
            \phi_{\mu_N}(z) &\leq \phi_{\widetilde{\mu}_N}(z)+\mc{O}(N^{-\vartheta}\log(\delta N^{-\beta}))+\mc{O}(N^{-\vartheta})\\
            &+\mc{O}\pr{N^{-\vartheta}\log\pr{1+C_0N^{\beta-\varrho\eta/2}\delta^{-1}}}+\log\pr{1+2C_0N^{-\varrho\eta/2}\alpha^{-1/2}}\\
            &+\mc{O}\pr{\alpha^{{\kappa_2}}\log\pr{1+C_0N^{\beta-\varrho\eta/2}\delta^{-1}}}
        \end{split}

    \end{equation}
    with probability $1-o(1)$, and
    \begin{equation}
        \begin{split}
            \phi_{\mu_N}(z)&\geq \phi_{\widetilde{\mu}_N}(z)+\mc{O}(N^{-\vartheta})+\mc{O}(\alpha^{{\kappa_2}})+\mc{O}(\alpha^{-1/2}N^{-\varrho\eta/2})\\
            &+\mc{O}(N^{-\vartheta}\log(\delta N^{-\beta}))+\mc{O}(\alpha^{{\kappa_2}}\log(\delta N^{-\beta}))
        \end{split}

    \end{equation}
    with probability $\geq 1-o(1)$.

