[Lemma beta-i of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$, we have:
\begin{enumerate}[(i).]
\item  For all $l\in \{1,2\}$,
\begin{equation}
\mathbb{E}_{{\mathcal V }_l}^0 [f ({\mathcal H })]=\mathbb{E}_{{\mathcal R }_l}^0 \left[f (\theta_{\beta_l(0)}({\mathcal H }))\right], 

\end{equation}

where $\beta_l$ is the bijection  between the point processes ${\mathcal V }_l$ and  ${\mathcal R }_l$, corresponding to handovers of pure type $l$.
\item  For all $l\neq r, k\in \{1,2\}$,

\begin{equation}
\mathbb{E}_{{\mathcal V }^{(k)}_{l,r}}^0 [f ({\mathcal H })]=\mathbb{E}_{{\mathcal R }^{(k)}_{l,r}}^0 \left[f (\theta_{\beta^{(k)}_{l,r}(0)}({\mathcal H }))\right], 

\end{equation}
where $\beta^{(k)}_{l,r}$ is the bijection between the point processes ${\mathcal V }_{l,r}^{(k)}$ and ${\mathcal R }_{l,r}^{(k)}$, corresponding to handovers of mixed type $\binom{k}{l,r}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Orientation of the stationary level curve) of arXiv:2608.06523, 'On the Gardner Transition in the Ising Pure $p$-Spin Glass II'] At a point satisfying both \eqref{mt:eq:mass} and
\eqref{mt:eq:endpoint-marginal}, direct differentiation gives
\begin{align}
 &\frac{\partial}{\partial m}
 \{\text{left-hand side of \eqref{mt:eq:mass}}\}\notag\\
 &\quad=\frac1m\Big\{
 \E[(\log\cosh(M(q)))^2e^{W_\mu(q)}]
 -\E[\log\cosh(M(q))e^{W_\mu(q)}]^2
 -\frac{p-1}{p}\xi'(q)\Gamma_\mu(q)\Big\}\notag\\
 &\qquad-\frac{p-1}{2p}\xi'(q)
 \frac{\partial}{\partial m}\Gamma_\mu(q),
 \\
 &\frac{\partial}{\partial\xi'(q)}
 \{\text{left-hand side of \eqref{mt:eq:mass}}\}\notag\\
 &\quad=\frac{1-m}{2p}\Bigg[(p-1)\xi'(q)\Bigg(
 2\Big\{\E[\cosh^{-2}(M(q))e^{W_\mu(q)}]
          -\E[\cosh^{-4}(M(q))e^{W_\mu(q)}]\Big\}\notag\\
 &\hspace{34mm}+\frac m2\Big\{
 \E[\cosh^{-4}(M(q))e^{W_\mu(q)}]
 -\E[\cosh^{-2}(M(q))e^{W_\mu(q)}]^2\Big\}\Bigg)\notag\\
 &\hspace{29mm}-p\frac{\partial}{\partial m}
 \Gamma_\mu(q)\Bigg].

\end{align}
Proposition~\ref{mt:prop:strict-sign} gives
\begin{equation}
 \frac{\partial}{\partial m}
 \{\text{left-hand side of \eqref{mt:eq:mass}}\}>0,
 \qquad
 \frac{\partial}{\partial\xi'(q)}
 \{\text{left-hand side of \eqref{mt:eq:mass}}\}>0.

\end{equation}
Consequently \eqref{mt:eq:mass} has a locally unique $C^1$ level curve,
and on it
\begin{equation}
 \frac{d\,\xi'(q)}{dm}
 =-\frac{
 \frac{\partial}{\partial m}
 \{\text{left-hand side of \eqref{mt:eq:mass}}\}}
 {\frac{\partial}{\partial\xi'(q)}
 \{\text{left-hand side of \eqref{mt:eq:mass}}\}}<0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop job of arXiv:2604.19184, 'Growing random planar network with \\oriented branching and fusion\\'] For any  $L_, \ell<\infty$ and $a\in [0,L]$ and $t\geq 0$ and $\varepsilon\leq   L\ell$, we have
\begin{align}
   i) \quad  &\mathbb P_{(L, \ell,a)}(\tau \geq t)\leq 2C_F\exp\left(-\frac{c_Ft}{2(L\vee \ell \vee 1)}\right)  \\

    ii) \quad   &  M_t 1_{< \varepsilon}(L,\ell,a)\leq C\big( 1+L+\ell\big)^3, 
    \, \varepsilon_{\ell,L} 
    \end{align}
    where  $C_F,c_F$ are constants given by Proposition (Gel of the paper) and  $1_{< \varepsilon}(x, y, b) = 1_{\{ x y < \varepsilon\}}$ and $C$ is also a universal constant (independent of the parameters) and 
    $$\varepsilon_{\ell,L}=\textsc{min}\left\{\varepsilon\left(  \frac{1}{\ell} +\frac{1}{L}+  \log\left(1+\frac{1}{\varepsilon}\right)\right) \, , \,  1 \right\}.$$

[Lemma 18 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] Let
\[
y(s)=\arcosh(s^{-1/2}), \qquad s\in(0,1).
\]
Then $S=\sech^2(h+\sigma Z)$ has density
\begin{equation}
\rho_S(s)=
\frac{1}{2\sigma\sqrt{2\pi}\,s\sqrt{1-s}}
\left(
 e^{-\frac{(y(s)-h)^2}{2\sigma^2}}+e^{-\frac{(y(s)+h)^2}{2\sigma^2}}
\right),
\qquad s\in(0,1).
\end{equation}

[Lem lem_hfbmUpperBound of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let $(X_H(\eta))_{\eta\in\mathbb{H}_{d}}$ be the hyperbolic fractional L\'evy field on $\mathbb{H}_{d}$ and let $R>0$. Then, for some constant $c>0$,
    \begin{align*}
        \prob{ \sup_{\eta\in\mathcal{B}^{\mathbb{H}_d}_R(O)} X_H(\eta) < \varepsilon } \leq \varepsilon^{\frac{d}{H}} \exp( \sqrt{ - c \log \varepsilon} )
    \end{align*}
    for some constant $c>0$ and $\varepsilon>0$ small enough.

