[Lemma l: fourier smooth differentiation of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $f\in L^1(\R^d, \C)$ is Fourier-smooth with exponent $p\in (d, \infty)$. Then $f$ is $\lceil \tfrac{p-d}{2}-1\rceil$-times continuously differentiable and every component of the $q$-th derivative $f^{(q)}$ is Fourier-smooth with exponent $p-2q$ for $q\in\{0,..., \lceil \tfrac{p-d}{2}-1\rceil\}$.
    \begin{proof}
        Since $f$ is Fourier-smooth with exponent $p>d$, we know that, by~(equation e: fourier smooth 12 of the paper),
        \begin{equation*}
            (1+\|k\|)^{ \big\lceil\tfrac{p-d}{2}-1\big\rceil}|\hat{f}(k)|\leq c \frac{(1+\|k\|)^{ \big\lceil\tfrac{p-d}{2}-1\big\rceil}} {(1+\|k\|)^{\frac{d+p}{2}}} = c \frac{1}{(1+\|k\|)^{d+\big(\tfrac{d+p}{2}-\big\lceil\tfrac{p+d}{2}-1\big\rceil\big)}}, \quad k\in\R^d,
        \end{equation*}
        for some $c>0$. Since the exponent in the denominator of the right-most side is strictly greater than $d$, this fact implies that $k\mapsto (1+\|k\|)^{ \big\lceil\tfrac{p-d}{2}-1\big\rceil}|\hat{f}(k)|$ is integrable, whereby $f$ is \linebreak $\lceil \tfrac{p-d}{2}-1\big\rceil$-times continuously differentiable. The Fourier-smoothness of the components of $f^{(q)}$ then is a direct consequence of the fact that
        \begin{equation*}
            \|\widehat{f^{(q)}}(k)\|=\|k^{\otimes q}\hat{f}(k)\|\leq \|k\|^q |\hat{f}(k)|, \quad k\in\R^d.
        \end{equation*}
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm_sol of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] Suppose Assumptions~(assumption1 of the paper) and~(assumption1.5 of the paper) hold. 

(a) For any $X_0 \in \mathbb{X}_{\mathrm{temp}}^+$, there exists a probability space supporting a continuous $\mathbb{X}_{\mathrm{temp}}^+$-valued solution $X = (X_t)_{t \geq 0}$ with initial state $X_0$.

(b) For a continuous $\mathbb{X}_{\mathrm{temp}}^+$-valued solution $X$, for any $\phi \in \mathbb{X}_{\mathrm{rap}}$, with probability one, for all $t \geq 0$,
\begin{align} 
\langle X_t, \phi \rangle  &= \langle X_0 , \phi\rangle + \int_0^t (\langle X_s, \mathcal{L} \phi \rangle + \langle f(X_s), \phi \rangle ) ds   +  \int_0^t \sum_{j \in \mathbb{Z}^d} \sigma(X_s(j)) \phi(j) dB_s(j).
\end{align}
Furthermore, for all $(t,i) \in \mathbb{R}_+ \times \mathbb{Z}^d$, $X$ a.s.\ satisfies the mild form
	\begin{equation} 
		X_t(i) =  P_t X_0(i)  + \int_0^t  P_{t-s} (f(X_s))(i) ds +\int_0^t  \sum_{j \in \mathbb{Z}^d}    P_{t-s}(i-j) \sigma(X_s(j)) dB_s(j),
	\end{equation}
and
	\begin{equation} 
		\mathbb{E}[X_t(i)] \leq e^{Lt} P_t X_0(i),
	\end{equation}
where $L\geq 0$ is the Lipschitz constant of $f$.

(c) If $X$ is a continuous $\mathbb{X}_{\mathrm{temp}}^+$-valued solution and $X_0 \in \mathbb{X}_{\mathrm{rap}}^+$, then $X$ is a continuous $\mathbb{X}_{\mathrm{rap}}^+$-valued solution. In this case, (equation eq_weak of the paper) holds for all $\phi \in \mathbb{X}_{\mathrm{temp}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 47 (Rephrasing of \cref{thm:quantitative_moments}) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] There is $\eps>0$ such that we have 
