[Lemma p<2 moment bound for uniform on disk of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] [Ghosh-numberofcomponents]
     Let $X$ be a uniform random variable on the open unit disk $\mathbb{D}$. For $ p<2 $, there exists a constant $C_p$ such that for all $ z \in \mathbb{D}$,
    \begin{align}
            \mathbb{E}\left[\frac{1}{|z-X|^p}\right] \leq C_p.
        \end{align}
        Furthermore, 
        \begin{equation}
             \mathbb{E}\left[\frac{1}{z-X}\right]  = \overline{z}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 23 (Filtered Gaussian martingales and Markov processes) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] { \ }
\begin{itemize}
\item[(i)] $\cFG_{\mathrm{mgle}}$ is the subset of $\bG^{a, L} \in \cFG$ such that $X$ is an $\bF$-martingale.
\item[(ii)] $\cFG_{\mathrm{Markov}}$ is the subset of $\bG^{a, L} \in \cFG$ such that $X$ is $\bF$-Markovian.\footnote{By definition, this means that $\bE[ \varphi(X_s) \mid \cF_t] = \bE[\varphi(X_s) \mid X_t]$ for all $s \geq t$ and bounded measurable function $\varphi$.}
\end{itemize}
We let $\FG_{\mathrm{mgle}} := \cFG_{\mathrm{mgle}} / \sim$ and $\FG_{\mathrm{Markov}} := \cFG_{\mathrm{Markov}} / \sim$ be the corresponding spaces of equivalence classes in $\FP_2$.

[Theorem thm:general of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $\{Z_N\}_{N \in {\mathbb N}}$ and $\{Z_{k,M,N}\}_{1 \le k \le M, \, M , \, N \in {\mathbb N}}$ be respectively a sequence of positive random variables and an array of random variables with mean one and finite variance, satisfying the following conditions:        \begin{enumerate}[label=(\roman*)]
            \item  \emph{Independence:} for $M,N\in\mathbb N$, $\{Z_{k,M,N}\}_{ 1 \le k\leq M}$ is a collection of independent random variables.    
            \item \emph{Decoupling in $L^2$:} for $M\in\mathbb N$, $Z_N$ admits a multiplicative approximation in $L^2$, i.e.\ \begin{equation}

             Z_N - \prod_{k=1}^{M} Z_{k,M,N} \xrightarrow[N \to \infty]{L^2} 0\,.
            \end{equation}        
    \end{enumerate}
    Moreover, denoting the centered variables $U_{k,M,N}:=Z_{k,M,N}-1$, we assume:
    \begin{enumerate}[label=(\roman*), start=3]
        \item  \emph{Second moment convergence:} there exists $\sigma_M^2>0$ and $\sigma^2>0$ such that
        \begin{equation}

        \lim_{N \to \infty} \sum_{k=1}^M \mathbb{E} \big[ U_{k,M,N}^2 \big] = \sigma_M^2\,, \, \ \text{for }M \in {\mathbb N} \qquad \text{and} \qquad \lim_{M \to \infty} \sigma_M^2 = \sigma^2\,.
        \end{equation}
        \item  \emph{Lyapunov condition:}
        \begin{equation} \exists \, \varepsilon_0>0 : \quad \limsup_{M\to\infty} \,\limsup_{N\to \infty}\, \sum_{k=1}^M \mathbb{E}\big[ \big|U_{k,M,N}\big|^{2+\varepsilon_0} \big]=0\,.
        \end{equation}
    \end{enumerate}
Then, $\log Z_N \, \stackrel{{ (d)}}{\longrightarrow} \, \mathcal{N}\left(-\frac{\sigma^2}{2},\sigma^2\right)\,.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

