[Lemma 2 of arXiv:2606.31133, 'Level-dependent quasi-birth-and-death processes: Application to cost analysis of multi-ser'] We have,
\begin{eqnarray}
\widetilde{\bf C}_{\mathcal{A}}^{n,n+k}(s)&=&
\widetilde{\bf C}_{\mathcal{A}}^{n,n+1}(s)
\widetilde{\bf C}_{\mathcal{A}}^{n+1,n+2}(s)
\times
\cdots
\times
\widetilde{\bf C}_{\mathcal{A}}^{n+k-1,n+k}(s),
\end{eqnarray}
where
\begin{eqnarray}
\widetilde{\bf C}_{\mathcal{A}}^{0,1}(s)&=&
-({\bf Q}^{[0,0]}-s{\bf C}_0\times I(0\in\mathcal{A}))^{-1}
{\bf Q}^{[0,1]},
\end{eqnarray} 
and for $n=1,\ldots,n+k-1$,
\begin{eqnarray}
\widetilde{\bf C}_{\mathcal{A}}^{n,n+1}(s)&=&
-({\bf Q}^{[n,n]}-s{\bf C}_n\times I(n\in\mathcal{A})
+{\bf Q}^{[n,n-1]}\widetilde{\bf C}_{\mathcal{A}}^{n-1,n}(s)
)^{-1}
{\bf Q}^{[n,n+1]}.
\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:QV-estimate of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $1/2<\lambda \le 7/8$ and $\phi \in \ensuremath{\mathcal C}_b^\infty(\mathbb{R})$. Then, there exist $C=C(\phi)>0$ satisfying, for all  $T>0$ and $N$ large enough, 
	\begin{equation}
	\mathbb{E}[(\ensuremath{\mathcal M}_{\lambda,N}(T,\phi))^2]=	\mathbb{E}[\langle \ensuremath{\mathcal M}_{\lambda,N}({\,\cdot\,},\phi)\rangle(T)]\le C e^{CT} \set{N^{2\lambda-2}+ N^{4(\lambda-7/8)}\,T^{1/2}}\; \text{.}
	\end{equation}
	As a consequence, we have
		\begin{align}
		\limsup_{N\to \infty}\int_0^T \mathbb{E}[(\ensuremath{\mathcal Y}_{\lambda,N}(t,\phi))^2]\,{\rm d} t<\infty\; \text{.}
	\end{align}

