body:
[Definition 74 (Hepp sector) of arXiv:2605.14630, '2605.14630'] \index{Hepp sector}
Fix a constant $C>1$. Let $T$ be a binary tree with $m = \abs{\cV}$ leaves, and 
let\/ $\bn$ be a node decoration on the vertices of\/ $T$, which is 
non-decreasing on any path from the root of\/ $T$ to a leaf of\/ $T$. We write 
$\bT = (T,\bn)$ and define a subset of $\Lambda^m$ by 
\begin{equation}
 D_{\bT} := 
 \Bigsetsuch{x\in\Lambda^m}{C^{-1}2^{-\bn_{i\wedge j}} \leqs \norm{x_i-x_j} 
\leqs C2^{-\bn_{i\wedge j}} \; \forall i,j\in \set{1,\dots,m}}\;,
\end{equation} 
where $i\wedge j$ denotes the last common ancestor of $i$ and $j$ in the tree 
$T$. Then $D_{\bT}$ is called the \emph{Hepp sector} associated with $\bT$.

[Lemm 4 of arXiv:2608.19104, 'Record times for coverage thresholds and maximal spacings'] Let $k \in \N$.
	Suppose $(\cF_n)_{n \geq k}$ is a filtration and
	$(I_n,U_n,Y_n)_{n \geq k}$
	is an adapted sequence of random 3-vectors with $I_n$
	and $U_n$ Bernoulli distributed for all $n$, 
	such that for all $n \geq k+1$ we have 
	\begin{align}
		\E [ I_nU_{n-1} | \F_{n-1} ] = Y_{n-1} U_{n-1} ~~~~ {\rm a.s.}

	\end{align}
	and 
	\begin{align}

		\E[ I_n | \F_{n-1} ] \leq Y_{n-1} ~~~~ {\rm a.s.}

	\end{align}
	Suppose moreover that 
	\begin{align}
		\sum_{n=k}^\infty (1- U_n)  < \infty, ~~~~~{\rm a.s.},

		\end{align}
	and that  almost surely, $Y_n \sim (c\, \log n/n)$ as
	$n \to \infty$ for some constant $c >0$,
	and that $\{n Y_n/\log n, n \geq k\}$ is a uniformly integrable
	family of random variables. For $n \in \N \cap [k,\infty)$ set
	$N_n := \sum_{i=k}^n I_i$, set
$\nu_{1} =k$ and for each successive $m \in \N$ set
	$\nu_{m+1} = \inf\{n > \nu_{m}: I_n =1 \}$. 

	Then $\nu_n$ is a.s. finite for all $n$, and as $n \to \infty$ we have 
	\begin{align}
		\E[N_{n}] & \sim (c/2)( \log n )^2;

		\\
		N_{n} & \sim (c/2)( \log n )^2
~~~~{\rm a.s.}

	\end{align} 
and

	\begin{align}
	\nu_{n}^{1/\sqrt{n}} \to \exp \big( \sqrt{2/c} \: \big)   
~~~~{\rm a.s.}

	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Cap interpolation) of arXiv:2607.23980, 'Sharp small-deviation inequalities for sums of independent\\nonnegative random variables'] Let $C\subset\R^m$ be a convex body with centroid $g_C$. Suppose that $L$ is affine and nonnegative on $C$, and put $a=L(g_C)>0$. Then, for $0\le t\le a$,
\begin{equation}
 \frac{\vol_m(C\cap\{L\ge t\})}{\vol_m(C)}
 \ge\left(1-\frac{t}{(m+1)a}\right)^m.
\end{equation}
The estimate is sharp.

