[Theorem 2 (Variational formula for left edge) of arXiv:2606.27774, 'Variational Formulas for the Spectrum of\\ Block Wishart Matrices'] Fix $k \ge 1$ integer, $\alpha \in (0,\infty)$, and $\nu\in\cuP_0(\sa{k}{\C})$.
Let $\mu_{\alpha,\nu}$ 
be as in Proposition~\ref{prop:asymptotic_FP}.
Then we have
\begin{equation}
 \inf \supp(\mu_\up{\alpha,\nu})= \sup_{\bS \in \cP_{-}} \lambda_{\min}\left(\bK_{(\alpha,\nu)}(\bS)\right). 
\end{equation}
where $\cP_-$ is given by
   \begin{equation}

  \cP_- \equiv \cP_-(\alpha,\nu) := \{\bS\succ\bzero : \bS^{-1}+ \bT\succ\bzero \;\; \forall\,\bT\in\supp(\nu),\;\; 
  \cuD_\bS \bK(\bS)[\,\cdot\,]\succ 0\; 
  \}.
   \end{equation}
   Furthermore, the set $\cP_-$ is equivalent to
   \begin{equation}

  \cP_- = \{\bS\succ\bzero : \bS^{-1}+ \bT\succ\bzero \;\; \forall\,\bT\in\supp(\nu),\;\;\textrm{there exists  }\bB\succ\bzero \textrm{ s.t.}  \;
  \cuD_\bS \bK(\bS)[\bB]\succ \bzero\; 
  \}.
   \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 8 ($L^1$-Contraction) of arXiv:2605.05986, '\bf Convergence rate of the occupation measure of { classes of ergodic processes toward th'] Let $(P_t)_{t\ge0}$ denote a  {{Markov}} transition   semi-group  {with unique invariant distribution  $\nu$}. If this semi-group satisfies  the following contraction inequality:
\begin{equation}
\hskip-0.5cm \ATROISter \left\{\begin{array}{ll}
(i)& \; \hbox{there exists $\Psi:\R^2\to \R_+$, Borel function, and $\ee \!\in \mathbb{L}^1([0, +\infty))$ such that  }\\
&\;\forall t\ge0,\forall\, x,\, x'\!\in \R^d, \; \W_1(P_t(x,dy),P_t(x',dy))\le \Psi(x,x')\ee(t),\\
(ii) &\;\displaystyle \hbox{the functions }\psi  :=\int_{\R^d} \Psi(\cdot,x')\nu(dx')<+\infty \mbox{ and $|\cdot |$ satisfy } \ATROISbis(ii)\\
&\; \hbox{ for some $q> 1$ and some probability measure $\mu_0\!\in {\cal P}_q(\R^d)$, $q>1$.}
\end{array}\right.
\end{equation}

Then  $\nu(|\cdot|^q)<+\infty$ and the above assumption $\ATROISbis$ is satisfied. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 79 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let ${\bf L}^{\pm}$ denote the line parallel to the $y$-axis and with $x$-coordinate $x^\pm:=x_0\pm L^2(\md_{w_0}\me_{w_0;q})^{1/2}$. Let $\bf S$ denote the strip between $\bf L^-$ and $\bf L^+$. Given $z\in
    \mathcal Y$, we let ${\bf L}^z$ denote the line parallel to the $y$-axis and containing $z$.    Note that the vertical sides of $\mathcal Y$ are subsets of $\bf L^-,\bf L^+$.

Moreover, as in \Cref{ulevelnew}, let\footnote{With a minor abuse of notation,  ``the level line $\mathcal U_{q'}^{k/N}$'' refers to the graph of the function $x\mapsto \mathcal U_{q'}^{k/N}(x)$.}
$\mathcal U_{q'}^{k/N}$ be the level line of $\cH_{q'}$ at height $k/N$, where
\begin{eqnarray}

	\displaystyle\frac{k}{N}=\frac{L^3}{\omega^3\md}.  
\end{eqnarray}

[Lem fn-in-X of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Let $f_0 \coloneqq (W')^{1/2}$ (see (as-W of the paper)) and $f_1,\dots,f_n$, $h_1,\dots,h_n$ be functions satisfying the following. For $i = 1,\dots,n$, some $T > 0$, and all $x \in \mathcal{M}$:
    \begin{itemize}
        \item $h_i$ vanishes over $f_i$.
        \item $\mathbb{E}\Big[\int_0^t f_i(X_t^x)^2dt\Big] < \infty$ for all $t \geq T$.
        \item
        \begin{equation}
            \begin{aligned}
                 \mathbb{E}\Big[\int_0^T f_i(X_t^x)dt\Big] &\leq h_i(x) + f_{i-1}(x) + \mathbb{E}\Big[\int_0^T f_{i-1}(X_t^x) + h_i(X_t^x)dt\Big] \\
                \mathbb{E}\Big[\int_0^T f_i(X_t^x)^2dt\Big] &\leq h_i(x) + f_{i-1}(x)^2 + \mathbb{E}\Big[\int_0^T f_{i-1}(X_t^x)^2 + h_i(X_t^x)^2dt\Big] \,.
            \end{aligned} 
        \end{equation}
    \end{itemize}
    Then $f_n \in \mathcal{X}$ and $f_n^2 \in \mathcal{Y}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:cap-function of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:cap}
Let \(r:\mathbb S^{N-1}(1)\to\mathbb R\) be continuous with \(\left\lVertr\right\rVert_\infty\le M\), and let
\begin{equation}
 F(x)=a x_1^p+r(x),
 \qquad a>2M.
\end{equation}
Choose \(\delta\in(0,1)\) so that
\begin{equation}
 a\bigl[1-(1-\delta)^p\bigr]>2M.
\end{equation}
Then \(F\) attains a local maximum at an interior point of the cap
\[
 \mathcal K_\delta=\{x\in\mathbb S^{N-1}(1):x_1\ge1-\delta\}.
\]
If \(r\) is \(C^1\), this point is a critical point of \(F\) on the sphere.  Its value lies in \([a-M,a+M]\).

