body:
[Theorem 9 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Consider Scenario~\eqref{Scenario_2}. We consider the following different regimes:
\begin{enumerate}[label=(E\arabic*), ref=E\arabic*]
\item  Suppose that \eqref{thm:C_{n}_a.s.:g_C^{2}} and \eqref{contraction_criterion_g} are satisfied, and, almost surely as $n\rightarrow\infty$, 
\begin{equation}
\text{either }\sum_{i=N}^{n}\E[K_{i}^{-1}]=o(\sqrt{n/\log n}) \quad \text{or} \quad \sum_{i=N}^{n}\E[K_{i}^{-1}](i+1)^{-1/2}=o(\sqrt{\log n}).
\end{equation}
Then the function $\hat{h}$ has a unique root, $(x^{*},y^{*})$, in $\mathcal{S}$. Let $\alpha^{*}=\partial g/\partial x|_{(x^{*},y^{*})}$ and $\beta^{*}=\partial g/\partial y|_{(x^{*},y^{*})}$. Let the scalars $\rho$ and $z^{*}$ be defined as in \eqref{thm:main_5:scalar_defns}, the matrices $\Gamma$, $T$ and $\overline{T}$ be defined as in \eqref{thm:main_5:matrix_defns}, and $\kappa$, $A_{i,j}$ and $B_{i,j}$ for each $(i,j)\in\{(1,1),(1,2),\ldots,(3,3)\}$, and $C_{i,j}$ for each $(i,j)\in\{(1,3),(2,3),(3,3)\}$, be defined as in the statement of Theorem~\ref{thm:main_5}, but with $x^{*}$, $y^{*}$, $\alpha^{*}$ and $\beta^{*}$ as defined in the context of Theorem~\ref{thm:main_6}. If, now, $\rho=1/2$, or equivalently, $\kappa=1/2$, the conclusion given by \eqref{thm:main_5:regime_1:conclusion} remains true.

\item  Let \eqref{thm:C_{n}_a.s.:g_C^{2}} and \eqref{contraction_criterion_g} be satisfied, let $0<\rho<1/2$, or, equivalently, $\kappa>1/2$, and let  
\begin{equation}
\sum_{i=N}^{n}\E[K_{i}^{-1}]=o(n^{1-\rho-\epsilon}) \text{ almost surely}
\end{equation}
for some $0<\epsilon<1-\rho$. Then, for some finite, scalar-valued random variable $W$, and $T$ as described in \eqref{thm:main_6:regime_1}, the same conclusion as shown in \eqref{thm:main_5:regime_2:conclusion} remains true.

\item  Suppose that either \eqref{thm:C_{n}_a.s.:g_C^{1}} and \eqref{contraction_criterion_g} are satisfied, and, almost surely, 
\begin{equation}
\sum_{i=N}^{n}\min\{\omega(\nabla g;(\E[K_{i}^{-1}])^{1/2})(\E[K_{i}^{-1}])^{1/2},\omega(\nabla g;\E[K_{i}^{-1}]/\E[K_{i}^{-1/2}])\E[K_{i}^{-1/2}]\}=o(\sqrt{n}),
\end{equation}
or that \eqref{thm:C_{n}_a.s.:g_C^{2}} and \eqref{contraction_criterion_g} are satisfied, and, almost surely, 
\begin{equation}
\sum_{i=N}^{n}\E[K_{i}^{-1}]=o(\sqrt{n}).
\end{equation}
Let $1/2<\rho\leqslant 1$. When $\kappa\in(-1,1/2)\setminus\{0\}$, the conclusion of \eqref{thm:main_5:regime_3.1:conclusion} remains true. When $\alpha^{*}=\beta^{*}=0$ (so that $\kappa=0$), the conclusion of \eqref{thm:main_5:regime_3.2:conclusion} remains true. Finally, when $\kappa=0$ but $\alpha^{*}\neq 0$ (so that $\beta^{*}\neq 0$ as well), the conclusion of \eqref{thm:main_5:regime_3.3:conclusion} remains true. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:frostman-consequences-good-event-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Suppose that \(\mathcal G_n\) holds. Then the following estimates hold with a universal constant \(C<\infty\).

\begin{enumerate}[label=\textup{(\roman*)}]
\item For every interval \(B\subset[0,1)\),
\begin{equation}
\widetilde\nu(B)\le C2^{\varepsilon n}\lvert B\rvert^a.
\end{equation}

\item For every \(\ell\ge0\) and every interval \(B\subset[0,1)\),
\begin{equation}
\widetilde\nu_\ell(B)
\le
C2^{\varepsilon n}(\lvert B\rvert+2^{-\ell})^a.
\end{equation}

\item For every \(\ell\ge0\) and every interval \(B\subset[0,1)\),
\begin{equation}
\sum_{\substack{I\in\mathcal D_\ell^\circ\\ I\cap B\neq\varnothing}}
\widetilde\nu_\ell(I)^2
\le
C2^{2\varepsilon n}2^{-a\ell}(\lvert B\rvert+2^{-\ell})^a.
\end{equation}
\end{enumerate}

[Lemma 33 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{24}>0$, which depends on $\|v_0\|_{L^4(\Omega)}$, $\|w_0\|_{L^2(\Omega)}$ and $T$, such that the following uniform estimate 
is satisfied:

\begin{equation*}
\sup_{\delta \in (1,\infty),\,\varepsilon\,\in\,(0,1)} \left( \sup_{0 \le t \le T} \|v_{\text{{\tiny $\delta,\!\varepsilon$}}}(t)\|_{L^4(\Omega)} \right) \le C_{24}.
\end{equation*}

