body:
[Theorem 12 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Consider the stochastic approximation process $\{Z_{n}\}$, 
\begin{equation} 
Z_{n+1}-Z_{n}-a_{n+1}E_{n+1}\in a_{n+1}F(Z_{n}),\text{ for each }n\in\mathbb{N}_{0},
\end{equation} 
satisfying the following conditions: 
\begin{enumerate}[label=(C\arabic*), ref=C\arabic*]
\item  the iterates are almost surely bounded, i.e.\ $\sup_{n}||Z_{n}||<\infty$ almost surely,
\item  $F$ is a closed set-valued map on $\mathbb{R}^{d}$, with $F(\mathbf{x})$ a non-empty, compact, convex subset of $\mathbb{R}^{d}$ for each $\mathbf{x}\in\mathbb{R}^{d}$, 
\item  $\sup\{||\mathbf{z}||:\mathbf{z}\in F(\mathbf{x})\}\leqslant \gamma(1+||\mathbf{x}||)$ for all $\mathbf{x}\in\mathbb{R}^{d}$, for some $\gamma>0$
\item  the step-size sequence $\{a_{n}\}$ is such that $\sum_{n}a_{n}=\infty$ and $\lim_{n\rightarrow\infty}a_{n}=0$, 
\item  and having defined $\tau_{0}=0$, $\tau_{n}=\sum_{i\in[n]}a_{i}$ for $n\in\mathbb{N}$, and $m(t)=\sup\{k\geqslant 0:t\geqslant \tau_{k}\}$ for $t>0$,
\begin{equation}
\lim_{n\rightarrow\infty}\sup\left\{\left|\left|\sum_{i=n}^{k-1}a_{i+1}E_{i+1}\right|\right|:k\in\left\{n+1,\ldots,m(\tau_{n}+T)\right\}\right\}=0 \text{ almost surely for each }T>0.
\end{equation}
\end{enumerate}
Then the continuous time affine interpolated process $\{Z(t):t\geqslant 0\}$, defined as
\begin{equation}
Z(\tau_{n}+s)=Z_{n}+\frac{s(Z_{n+1}-Z_{n})}{\tau_{n+1}-\tau_{n}} \text{ for each }s\in[0,a_{n+1}),
\end{equation}
is a perturbed solution to the differential inclusion $\dot{\mathbf{x}}(t)\in F(\mathbf{x}(t))$ for $t\geqslant 0$, and its limit set $L(Z)=\bigcap_{t\geqslant 0}\overline{\{Z(s):s\geqslant t\}}$ is internally chain transitive. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm unique of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Assume $(X_{j})_{j \in \mathbb{N}}, (X'_{j})_{j \in \mathbb{N}}$ are defined as in~(equation eq:def-ex of the paper) and Assumption~(ass:gen-ass of the paper) is satisfied. Moreover, assume~(equation eq:persistent of the paper) is satisfied 
and, in addition, one of the following conditions is satisfied:
\begin{enumerate}
    \item  We have
        \begin{equation} 
        \sum_{k=1}^{\infty} \Prob{0 \leq \sum_{j=1}^{k} (X'_{j} - X_{j}) - \sum_{j=1}^{k} X_{j} < X_{k+1}} < \infty.
        \end{equation}
    \item  It is the case that both of the following conditions are satisfied:
    \begin{enumerate}
        \item We have $\sum_{j=1}^{\infty} \Prob{X_{j} - X'_{j} \neq 0} = \infty$, or for some $j \in \mathbb{N}$, we have $\Prob{X_{j} \neq X'_{j}} = 1$.
        \item For any $\varepsilon > 0$ we have $\sum_{j=1}^{\infty} \Prob{X_{j} > \varepsilon} < \infty$. 
    \end{enumerate}
\end{enumerate}    
Then, almost surely, in the process $(\mathscr{T}_{\tau_{n}})_{n \in \mathbb{N}_{0}}$,

there is a unique persistent hub. (Proof in the paper; no proof environment follows the statement in the TeX.)

