[Prop 2 (The simplest Gaussian convex inequality) of arXiv:2603.25536, 'The $H^{2|2}$ monotonicity theorem revisited'] The integral
\begin{equation*}
    I=\int_{\mathbb{R}}f(x)e^{-\frac{w}{2}x^2}\frac{\sqrt{w}}{\sqrt{2\pi}}dx=\mathbb{E}[f(\mathcal{N})]
\end{equation*}
is non-increasing in $w>0$ if $f:\mathbb{R}\to\mathbb{R}$ is convex. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $Z_0,\eta$ be random variables such that $\Prob(\eta=0)=0$. Let $\Delta W$ be Gaussian with mean $0$ and variance $h$ such that $\Delta W$ is independent of $Z_0$ and $\eta$. Assume that 
    \begin{align*}
        Z_1=Z_0+\eta \Delta W.
    \end{align*} 
    Then $Z_{1}$ has a density given by a convolution-type formula: 
    \begin{align*}
        f_{Z_{1}}(x)=\E\Bigl[\varphi_{h\eta^2}\bigl(x-Z_0\bigr) \Bigr]
    \end{align*}

[Proposition prop_upper_bound_LSI_quadratic of arXiv:2503.24372, 'A criterion on the free energy for log-Sobolev inequalities in mean-field particle systems'] Let $V$ satisfy Assumption~(ass_doublewell of the paper). 
There is $C>0$ such that, for all $T > T_c$, one gets for  $N$  large enough 
\begin{equation}
\gamma^N_{\mathrm{LS}}(T)
\leq  C (T-T_c) .
\end{equation}

[Definition 18 (Chronological inverse) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] The chronological inverse of $L = \cC_{\min}(A)$, $A \in \mathscr{S}_+(n)$, is defined in terms of the notation above by
\begin{equation}
L^{\ominus}:=E (L_{[\cI,\cI]})^{-1} E^{\intercal} \in \mathscr{L}_+(n).
\end{equation}

[Corollary 31 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Let 
		\begin{equation*}
			\phi_{\varepsilon}(x,\omega) = \psi_{0}(x,\omega) + \varepsilon_{1} \psi_{1}\left(x,T\left(\frac{x}{\varepsilon_{1}}\right)\omega\right) + \varepsilon_{2} \psi_{2}\left(x,T\left(\frac{x}{\varepsilon_{1}}\right)\omega,\frac{x}{\varepsilon_{2}}\right),
		\end{equation*}
		with $\varepsilon>0$, $(x,\omega) \in Q\times \Omega$, $\psi_{0} \in \mathcal{C}^{\infty}_{0}(Q)\otimes I^{\Phi}_{nv}(\Omega)$, $\psi_{1} \in \mathcal{C}^{\infty}_{0}(Q)\otimes \mathcal{C}^{\infty}(\Omega)$ and  $\psi_{2} \in \mathcal{C}^{\infty}_{0}(Q)\otimes \mathcal{C}^{\infty}(\Omega)\otimes A^{\infty}$. Then,
		\begin{equation*}
			\begin{array}{l}
				\displaystyle 	\lim_{\varepsilon \to 0} \iint_{Q\times\Omega} f^{\varepsilon}\left(\cdot,\cdot, D\phi_{\varepsilon}\right) dxd\mu  \\ 
				= \displaystyle \iint_{Q\times\Omega} \pounds_{A}\int \varrho \circ f\left(\cdot,\cdot, D_{x}\psi_{0}+ D_{\omega}\psi_{1} +\partial \psi_{2}\right) dydxd\mu,
			\end{array}
		\end{equation*}
		where $(\varrho \circ f\left(\cdot,\cdot, D_{x}\psi_{0}+ D_{\omega}\psi_{1} +\partial \psi_{2}\right))(x,\omega ,y)=\varrho (f(x,\omega ,\cdot ,D_{x}\psi_{0}+ D_{\omega}\psi_{1} +\partial \psi_{2}(x,\omega,\cdot )))(y)$
		for $(x,\omega ,y)\in Q\times \Omega \times \mathbb{R}^{d}$.

