[Mainthm 1 of arXiv:2507.08909, 'Annealed almost periodic entropy'] The function $\hann$ takes values in $[-\infty,\infty)$ for each $k$.	For any positive definite map $\phi:\G\to \rmM_k$, the value $\hann(\phi)$ is equal to both
	\begin{equation}
		\lim_{n\to\infty}\Big(\log\Det
		\,\phi[B_n] - \sum_{s \in S}\log\Det\,\phi[B_n\cap sB_n]\Big)
	\end{equation}
	and
	\begin{equation}
		\lim_{n\to\infty}\Big(\sum_{s \in S}\log\Det\,\phi[B_n\cup sB_n] - (2r-1)\log\Det\,\phi[B_n]\Big)
	\end{equation}
	(interpreting these as $-\infty$ if any of the determinants appearing here equals $0$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2604.15874, 'On Continuous Data Assimilation for a class of 2D and 3D stochastic non-Newtonian fluids o'] A stochastic process $\{\Wrm(t)\}_{t\geq 0}$ is called an \emph{$\Hcal$-valued, $\mathscr{F}_t$-adapted $\Qrm$-Wiener process} with covariance operator $\Qrm$ if:
	\begin{enumerate}
		\item[(i)] for every non-zero $\v\in \Hcal$, the process $\|\Qrm^{1/2}\v\|_{\Hcal}^{-1}(\Wrm(t),\v)$ is a standard one-dimensional Wiener process;
		\item[(ii)] for any $\v\in \Hcal$, the real-valued process $(\Wrm(\cdot),\v)$ is an $\mathscr{F}_t$-adapted martingale.
	\end{enumerate}

[Lemma 10 of arXiv:2604.07697, 'Stochastic fractional heat equation with general rough noise'] Recall $D(x,h)$ defined in \eqref{nota alpha  1}.  For $0<H<\frac{1}2$,  there exists a positive finite constant $c_{H,\alpha}$ depending on $H$ and $\alpha$ such that for any $t>0$  and $x\in\mathbb{R}$,
\begin{equation}
\int_{\mathbb{R}} \left|D(t,x,h)\right|^2|h|^{2H-2}dh\le c_{H,\alpha}\left (t^{\frac{2H-3}{\alpha}}\wedge\frac{|x|^{2H-2}}{t^{\frac1{\alpha}}}\right).
\end{equation}

