[Proposition 9 of arXiv:2608.29152, 'Uniform Statistical Convergence of Empirical Sinkhorn Potentials\\ with Exponential and Po'] Suppose that, for some $\lambda_0>0$ and $r\ge0$ such that $0<\lambda_0\eps^r\le1$, and for all $[u],[v]\in\mathcal U_\eps$,
\begin{equation}
 d_\infty([\Phi_\eps u],[\Phi_\eps v]) \le (1-\lambda_0\eps^r)d_\infty([u],[v]).
\end{equation}
Then Assumption~\ref{ass:poly-stability} holds with $K_0=\lambda_0^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: JSQ Tail bound of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] [Tail Bounds for Load Balancing Policy]  
Consider a test direction $\boldsymbol{\phi}\in\mathbb{R}^n$ with unit norm $\| \boldsymbol{\phi} \| = 1$. Under the heavily overloaded regime (ass:heavy_overload of the paper) with $\gamma\leq\gamma_2$ as defined in (equation eq: gamma assumption for JSQ tail bound of the paper), the following concentration inequalities hold for the normalized queue length vector $\tilde{\mathbf{q}}:=n\sqrt{\gamma}/\sqrt{\lambda}(\mathbf{q}-\frac{\lambda-\mu}{n\gamma}\boldsymbol{1})$. We distinguish two cases depending on the alignment of $\boldsymbol{\phi}$ with the all-ones vector $\boldsymbol{1}$. When $\langle \boldsymbol{\phi},\boldsymbol{1}\rangle \neq 0$, we have the following results.
    \begin{enumerate}[label=(\alph*), ref=\thetheorem~(\alph*)]
        \item 
        For fixed deviation $a$ and $\gamma \leq \gamma_a$ (see (equation eq: gamma_a definition JSQ first regime of the paper)), there exists a constant $B_{1,\lambda,\mu,n}$ (see (equation eq: B1, B2 for JSQ tail bound of the paper)), independent of $\gamma$ and $a$, such that:
        \begin{align*}
            \left| \mathbb{P}\big( \langle \tilde{\mathbf{q}}, \boldsymbol{\phi} \rangle > a \big) 
            - \mathbb{P}\big( Z \cdot \langle \boldsymbol{\phi}, \boldsymbol{1} \rangle > a \big) \right|
            &\leq \frac{e^3 B_{1,\lambda,\mu,n}}{\sqrt{2\pi} |\langle \boldsymbol{\phi}, \boldsymbol{1} \rangle|} \cdot \sqrt{\gamma} \left[ \left( \frac{a^2}{2 \langle \boldsymbol{\phi}, \boldsymbol{1} \rangle^2} + \ln \frac{1}{\sqrt{\gamma}} \right)^2 + \sqrt{2\pi} \right] \\
            &\qquad \cdot \exp\left( -\frac{a^2}{2 \langle \boldsymbol{\phi}, \boldsymbol{1} \rangle^2} \right)
        \end{align*}
        \item 
        For deviations $2 \leq a_\gamma \leq E_{Tail,1,u}/\gamma^\delta$, with $\delta \leq \min\{1/4-\alpha/2,\,1/6\}$ (see (equation eq: a's regime for MDP JSQ of the paper)), the following bound holds:
        \begin{align*}
            &\left|\,\mathbb{P}\big(\langle \tilde{\mathbf{q}},\boldsymbol{\phi}\rangle > a_\gamma\big) 
            - \mathbb{P}\big(Z\cdot\langle\boldsymbol{\phi},\boldsymbol{1}\rangle > a_\gamma\big)\,\right| \\
            &\quad\leq \frac{e B_{1,\lambda,\mu,n}}{\sqrt{2\pi}\,|\langle\boldsymbol{\phi},\boldsymbol{1}\rangle|}\cdot \sqrt{\gamma}\,
            \left[\left(\frac{a_\gamma^2}{2\langle\boldsymbol{\phi},\boldsymbol{1}\rangle^2} + \ln\frac{1}{\sqrt{\gamma}}\right)^2 + \sqrt{2\pi}\right] \\
            &\qquad\qquad \cdot \exp\left\{
                -\frac{a_\gamma^2}{2\langle\boldsymbol{\phi},\boldsymbol{1}\rangle^2}
                \left[1 - e B_{1,\lambda,\mu,n}\left(
                    \frac{a_\gamma^4}{2\langle\boldsymbol{\phi},\boldsymbol{1}\rangle^4}\sqrt{\gamma}
                    + \frac{2\sqrt{\gamma}\ln^2(1/\sqrt{\gamma})}{a_\gamma}
                \right)\right]
            \right\}
        \end{align*}
        \item 
        For deviation $a_\gamma = 1/\gamma^\delta$, $\delta \in [\min\{1/4-\alpha/2,\,1/6\},\,\infty)$, there exists a constant $c$ (see (equation eq: constant c in subweibull regime, JSQ of the paper)) such that:
        \begin{align*}
            \mathbb{P}\big(\langle \tilde{\mathbf{q}},\boldsymbol{\phi}\rangle > a_\gamma\big)
             \leq  \mathbb{P}\big(Z\cdot\langle\boldsymbol{\phi},\boldsymbol{1}\rangle > a_\gamma\big) +
           \frac{e}{2\sqrt{2\pi}}\,a_\gamma\,\exp\left(-\frac{a_\gamma^2}{8}\right)
            + \exp\left(-c\,a_\gamma^{\min\{1/(4\delta)+1/2,\,2\}}\right)
        \end{align*}
        \end{enumerate}
        Alternatively, if $\langle \boldsymbol{\phi},\boldsymbol{1}\rangle = 0$, then the following holds. \begin{enumerate}[label=(\alph*), ref=\thetheorem~(\alph*),start=4 ]
            \item  For $a_\gamma \geq E_{Tail, 2, u} \cdot \sqrt{\gamma}$ (see (equation eq: a's regime for worst case direction JSQ of the paper)), there exists constant $G_{\lambda,\mu,n}$ defined in (equation eq: tail bound for worst case direction of t (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LEM:gra of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Q \in \mathbb{Z}$ with $|Q|=k$. For $0<\eta \ll 1$ sufficiently small, 
\begin{align*}
\| \nabla E(m_{\xi_1,\dots,\xi_k}) \|_{L^2(\mathbb{R}) } 

\le C_\eta e^{- (1-\eta) d},
\end{align*}
uniformly in $\xi_1,\dots,\xi_k$ 

where 
$d:= \min_{i \neq j}|\xi_i-\xi_j| $ and 

$C_\eta = O(\eta^{-1/2})$.

[Thm cor:diff-eqnV of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let  $\mu > -\frac12$, ${\kappa}_i > -1$ for $1 \le i \le d_2$. Let ${\mathfrak D}_i$ denote the operator 
$$
  {\mathfrak D}_i  := (1-|\bm y|) \partial_{y_i} - {\langle} \bm x, \nabla_{\bm x} {\rangle}, \qquad 1 \le i \le d_2.
$$
Then the spectral operator can be written as 
\begin{align} 
  {\mathfrak D}_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle} = \, & \frac{1}{1-|\bm y|} \left[   \frac{1}{\bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}(\bm x, \bm y)}
  \sum_{i=1}^{d_1} \partial_{x_i} \bm W_{\mu+1,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}(\bm x, \bm y) \partial_{x_i} 
  +  \sum_{1 \le i< j \le d_1} \left(D_{i,j}^{(\bm x)}\right)^2 \right] \notag \\
  & + \frac{1}{\bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}(\bm x, \bm y)}  
  \sum_{1\le i< j \le d_2} (\partial_{y_i} - \partial_{y_j}) \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}(\bm x, \bm y)
   (\partial_{y_i} - \partial_{y_j}) \\
   & +  \frac{1}{(1-|\bm y|)^{d_1+1}} \frac{1}{\bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}(\bm x, \bm y)}  \sum_{i=1}^{d_2}  
{\mathfrak D}_i  (1-|\bm y|)^{d_1} y_i \bm W_{\mu,{\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \triangle}(\bm x, \bm y) {\mathfrak D}_i. \notag 

 \end{align}

