  \begin{equation}
    \mathbb{P} \big( \mathcal{I} \big) \leq C_{\textnormal{\tiny (C:invasion of the paper)}}\rho \exp\braces{-c_{\textnormal{\tiny (c:invasion of the paper)}} (w+\dist_{V})}.
