[Lemma 83 (Localized rough stochastic products) of arXiv:2607.10813, '2607.10813'] Assume \eqref{eq:parameter-window}.  Let
$U=\rho V+X+Y$ with $X\in\wt X_T^{s_1,\sigma}$,
$Y\in\wt Y_T^{s_2,\sigma}$, and $V$ as in
\cref{def:Xi-assumptions}.  For $a\in\mathfrak C$, put
\[
 \mathfrak Y_a(Y):=Y\succ\Psi_a+Y\circ\Psi_a.
\]
Then
\begin{align}
  \norm{\chi(U\prec\Psi_a)}_{L_T^1H^{s_1-1}}
  +\norm{\chi(U\prec\Psi_a)}_{L_T^1B_{2,\infty}^{\sigma-1}}
  &\lesssim T^\delta M_T(\Xi)\notag\\
  &\quad\times
  \paren{1+\norm{X}_{\widetilde X_T^{s_1,\sigma}}
  +\norm{Y}_{\widetilde Y_T^{s_2,\sigma}}},
  \\
  \norm{\chi((\rho V)\succ\Psi_a)}_{L_T^1H^{s_2-1}}
  +\norm{\chi((\rho V)\succ\Psi_a)}_{L_T^1B_{2,\infty}^{\sigma-1}}
  &\lesssim T M_T(\Xi)^2,
  \\
  \norm{\chi(X\succ\Psi_a)}_{L_T^1H^{s_2-1}}
  +\norm{\chi(X\succ\Psi_a)}_{L_T^1B_{2,\infty}^{\sigma-1}}
  &\lesssim T^\delta M_T(\Xi)\norm{X}_{\widetilde X_T^{s_1,\sigma}},
  \\
  \norm{\chi\mathfrak Y_a(Y)}_{L_T^1H^{s_2-1}}
  +\norm{\chi\mathfrak Y_a(Y)}_{L_T^1B_{2,\infty}^{\sigma-1}}
  &\lesssim T M_T(\Xi)
  \norm{Y}_{\widetilde Y_T^{s_2,\sigma}}.

\end{align}
The estimates have the corresponding Lipschitz form, including differences of
the weighted pseudolocal terms.

[Cor 80 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] \begin{align*}

\mathbbm{1}_{i \leq j} \sum_{\ell=i}^j \prod_{m=\ell+1}^N (x_i - x_m) \prod_{\substack{m = \ell \\ m \neq j}}^N \frac{1}{x_j - x_m}

= \delta_{ij} & & i,j=1,\dots, N\, .

\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (General structure of $S_n'$) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $0 < \gamma < 1$, let $f(x)=|x|^\gamma$, let $g(x)=\lambda>0$, and let $(S_n)_{n\ge1}$ be defined by the recurrence in \cref{ec:S0S1Sk} of \cref{lem:WKBprime}. Then, for each $n\ge1$, there exist polynomials $A_{n,i}(\gamma)$, $1\le i\le n$, such that for $x\ge x^\ast$,
	\begin{equation} 
		S_n'(x) = \sum_{i=1}^{n} \lambda^i \, A_{n,i}(\gamma)\,|x|^{-((n+i-1)\gamma + (n-i))},
	\end{equation}
	and each $A_{n,i}(\gamma)$ has degree $n-i$ and sign $(-1)^{n-i}$. The leading coefficient is given by
	\begin{equation*}
		A_{n,n} = \frac{1}{n}\binom{2(n-1)}{n-1}.
	\end{equation*}
	Consequently, if $\psi_{k,\varepsilon}$ is the $k$-th non-constant eigenfunction of $-\mathcal{L}_\varepsilon$ with eigenvalue $\lambda_{k,\varepsilon} = \lambda_k \varepsilon^{\frac{\gamma-1}{1+\gamma}}$, and if $N := \big\lceil \frac{1+\gamma}{2\gamma} \big\rceil$, then
	\begin{equation}
		\psi_{k,\varepsilon}(x) \approx \exp \biggl ( \sum_{i=1}^N \int_{x^\ast}^{x \varepsilon^{\frac{-1}{1+\gamma}}} S_i'(s )  \ds\biggr ),
	\end{equation}
	where $S_i'$ is given by \cref{eq:Sk:formula:explicit}. In the resonant case $N = \frac{1+\gamma}{2\gamma}\in \mathbb N$, the last term $i=N$ contributes a logarithmic correction.

