[Lemma L:X:smallball of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $I \subset \mathbb{R}$ be a compact interval and $X=\{X(t): t\in I\}$ be a centered
  Gaussian process. Suppose there exist constants $\rho\in(0,1)$ and $c_1, c_2,
    c_3\in (0,\infty)$ such that
  \begin{align}
    c_1 |t-s|^\rho \le \mathbb{E}[(X(t)-X(s))^2]^{1/2} \le c_2 |t-s|^\rho \quad \text{for all $t,s\in I$}
  \end{align}
  and $X$ satisfies one-sided strong local nondeterminism:
  \begin{align}
    \ensuremath{\mathrm{Var} }(X(t)|X(t_1),\dots,X(t_n)) \ge c_3 \min_{1\le i \le n}(t-t_i)^{2\rho}
  \end{align}
  uniformly for all integers $n \ge 1$ and for all $t,t_1,\dots, t_n\in I$ with
  $\max\{t_1,\dots, t_n\} \le t$. Then there exist constants $0<C_1\le C_2
    <\infty$ such that for all $\varepsilon \in (0,1)$,
  \begin{align}
    \exp\left(- \frac{C_2}{\varepsilon^{1/\rho}} \right) \le \mathbb{P}\left\{ \sup_{t\in I}|X(t)| \le \varepsilon \right\} \le \exp\left( - \frac{C_1}{\varepsilon^{1/\rho}} \right).
  \end{align}

[Definition def:zero-marginals of arXiv:2605.10491, 'Zero-couplings of infinite measures with cyclically monotone support and multivariate regu'] The left and right zero-marginals of a nonnegative Borel measure $\gamma$ on $(\reals^d\times\reals^d) \setminus \left\{0\right\}$ are the nonnegative Borel measures $\varphi_1 \gamma, \varphi_2 \gamma$ on $\reals^d_{\smallsetminus 0}$, respectively, with
    \begin{align*}
       \varphi_1 \gamma(A) = \gamma(A \times \mathbb{R}^d)
       \quad \text{and} \quad
       \varphi_2 \gamma(A) = \gamma(\mathbb{R}^d \times A) 
       \quad \text{for $A \in \mathcal{B}(\reals^d_{\smallsetminus 0})$.}
    \end{align*}

[Proposition prop:uniform-lb of arXiv:2506.03999, 'Large deviations for scaled families of Schr\"odinger bridges with reflection'] Take $\varepsilon \in (0,\frac{1}{2}\wedge \operatorname{diam}(D))$. Then, there exists $\alpha_D = \alpha_D(\varepsilon)> 0, \ \eta_0 = \eta_0 (\varepsilon) > 0$, and $\beta_D >0 $, such that for any $x, y \in \overline{D}$ and $\eta \leq \eta_0$,
    \begin{equation}
        p^r_\eta(1, x, y) \geq \alpha_D \exp{-\left\{\frac{|x - y|^2 + \beta_D \varepsilon}{2 \eta (1 - \varepsilon)}\right\}}.
    \end{equation}

