body:
[Prop 57 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Let $\rho$ be a separable unital representation whose support is a perfect subset of $\hat{\A}$ for the Fell topology: that is, it has no isolated points.
\begin{enumerate}
\item[a.] If another separable unital representation $\pi$ weakly contains $\rho$, then $\pi \gtrsim_\rm{a} \rho$.
\item[b.] If another separable unital representation $\pi$ is weakly equivalent to $\rho$, then ${\pi \simeq_\rm{a} \rho}$.
\item[c.] If a sequence $(\pi_n)_{n\ge 1}$ converges to $\rho$ strongly, then $\t{\pi_n}$ sq-converges to $\t{\rho}$.
\end{enumerate}

[Corollary co:clttozero of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For any $0<\kappa<\frac{d-2}{2}$,
    when $t_R=o(R^2)$, \begin{equation*}
\frac{1}{\sqrt{t_R/R^2}} [u_{t_R/R^2}(B_1) -\omega_d]\to \mathcal{N}(0,\sigma^2) \quad \text{in law},
    \end{equation*}
    as $R \to \infty$, with $\sigma^2$ as defined in (equation eq:1stvar of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cpts-length of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Fix $\varepsilon, \delta \in (0, 1)$, and $A, B$ with $B \in \ensuremath{\mathcal Y}_\delta^\blacktriangleleft(A)\setminus \{A\}$. Let $V$ be an $\varepsilon$-nice domain, and $U$ any domain. There exists $\beta_0, v_0, \delta_0, c > 0$ such that uniformly over $n$, $\beta \geq \beta_0$, and $r \geq 1 + 2\varepsilon$, we have
		\begin{align}
			{\widehat Z}^n_{V, U}(A, B \mid |\gamma| \geq r\lVertA - B\rVert_1) \leq ce^{-v_0\beta r\lVertA - B\rVert_1}{\widehat Z}^n_{V, U}(A, B)\,,\\
			{\widehat Z}^n_{V, U}(A, B \mid |\mathsf{Cpts}(\Gamma)| < 2\delta_0\lVertA - B\rVert_1) \leq ce^{-v_0\beta\lVertA - B\rVert_1}{\widehat Z}^n_{V, U}(A, B)\,.
		\end{align}

