body:
[Lemma hdot-rep of arXiv:2608.30212, 'A Painlev\'e equation for the H\"ormander-Bernhardsson constant'] Let $k$ be even and $c\in J_{k,0}$. Then
\begin{align}
\dot{h}_k(c) = \frac{\pi}{2}   Q_{k,c}(0)^2
\end{align}

Since $h_k(0)>0$, we have $h_{k}> 0$ on $J_{k,0}\cap [0,\infty)$.

[Lemma 15 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let $T^{\infty}(c,d) : = (T_{l}(c,d))_{l \in \mathbb N_0}$ be a sequence of admissible partitions of $\mathcal F$ such that $|T_{0}(c,d)| = 1$ and $|T_{l}(c,d)| \leq 2^{d2^{l/c}}$ for some $c,d \geq 1$. Suppose there exists a $u : \mathbb{N}_{0} \to \mathbb{R}_{+}$ and $\ell : \mathbb{N}_{0} \to \mathbb{R}_{+}$ such that $\sup_{f \in \mathcal{F}}  ||\Delta_{l} f||_{\infty} \leq u(l)$ and $\ell(l) \geq 2 d 2^{l/c}$ for all $l \in \mathbb{N}_{0}$. Then,\footnote{The implicit constant in the $\lesssim$ can depend on $(c,d)$ but otherwise is universal.} 
	\begin{align*}
		&\mathbb P^{\ast} \left(  \sup_{f \in \mathcal{F}}  \sum_{l=1}^{\infty} \sum_{k=1}^{K_l} |\mathbb G^{(k),\ast}_{n}(\Delta_{l} f) | \leq v   \sup_{f \in \mathcal{F}}  \sum_{l=1}^{\infty}  \sum_{k=1}^{K_l}  \left( 2  	\sqrt{  \sum_{m\in\mathcal C_k} \frac{|B_{m}|}{n}  ||\Delta_l f||^{2}_{B_{m}}   } \ell(l)   + \frac{2}{3} \frac{ \max_{m \in [M_l]} |B_{m}| }{\sqrt{ n }} ||\Delta_l f||_{\infty} (\ell(l)  )^{2}    \right)   \right) \\
		& \geq 1 - C \left(  \sum_{l=0}^{\infty} 2^{  2d 2^{l/c}  }  e^{- 0.5 \ell(l)^{2} } \right) e^{-0.25 v}
	\end{align*}
	for any $v \geq 4$ and some universal finite constant $C$.\footnote{Observe that under the choice of $(c,d,\ell)$, the quantity $\sum_{l=0}^{\infty} 2^{  2d 2^{l/c}  }  e^{- 2\ell(l)^{2} }$ is finite.}

