[Lemma le:uniform-estimate of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] Let $u^\epsilon$ be rough path solutions to (equation sf of the paper) (or resp.  (equation sf2 of the paper)) of regularity $\frac{1}{\alpha}-var$ with initial conditions $u_0^\epsilon$ bounded uniformly in $H$.
Assume  Assumptions (assumption of the paper) (resp. Assumption~(ass:Y of the paper)).  Here $\alpha\in (\frac 13, H)$ or as in Assumption~(ass:Y of the paper).
Then we have the uniform estimates:
        \begin{equation*}
      \sup_\epsilon \left\| u^\epsilon \right\|_{C^{\frac{1}{\alpha}\textrm{-var}}([0,T];H^{-1})}^{\frac{1}{\alpha}}
        < \infty, \qquad  \sup_\epsilon \norm{R^{u^\epsilon}}_{C^{\frac{1}{2\alpha}\textrm{-var}}([0,T];H^{-2})}^{\frac{1}{2\alpha}} < \infty \quad a.s.
    \end{equation*}

[Lemma 194 (Remarkable structure in the contraction of the flat current with $\newuL$ for top-order gradient entropy) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\flatcurrent[\SigmatTan,\pmb{\p}\SigmatTan]$ denote the flat current from \eqref{E:FLATELLIPTICHYPERBOLICCURRENT}, where $\SigmatTan$ is a $\Sigma_t$-tangent vectorfield. Then, the following identities hold:
	\begin{align}
		\begin{split} 
			\flatcurrent^\alpha [\tander^N \GradEnt,\pmb{\p}\tander^N\GradEnt] \newuL_\alpha & = \frac{1}{2} \newuL \left( |\tander^N \GradEnt|_{\gfour}^2\right)+  \, ^{(\tander^N \GradEnt)}\Currentboundaryerrorhavetocontrolprincipal^{(\textnormal{Flat})} + \, ^{(\tander^N \GradEnt)}\Currentboundaryerrorhavetocontrollowerorder^{(\textnormal{Flat})}
		\end{split}
	\end{align}

	\begin{align}
		\begin{split} 
			\, ^{(\tander^N \GradEnt)}\Currentboundaryerrorhavetocontrolprincipal^{(\textnormal{Flat})} & = - \exp(2\LogDensity)( \tander^N \GradEnt^\alpha) \newuL _\alpha \tander^N \DivGradEnt \\
			& \ \  -  \frac{\ReciprocaluLunitAppliedtoTimeFunction}{\MagnitueofinnerproductofnewLandnewuL} (\tander^N \GradEnt^\beta) \GradEnt_a \newL_\beta \newuL \tander^N v^a +  \ReciprocaluLunitAppliedtoTimeFunction (\tander^N \GradEnt^\beta) \GradEnt_a \nullangpartial_\beta \tander^N v^a  \\
			& \ \   + \frac{1}{\upmu}(\tander^N \GradEnt^\alpha) \newuL_\alpha \GradEnt_a \newuL \tander^N v^a -   (\tander^N \GradEnt^\alpha) \newuL_\alpha \GradEnt_a  \breve{\slashed{\Transport}} \tander^N v^a.
		\end{split}
	\end{align}	\begin{align}
		\begin{split} 
			\, ^{(\tander^N \GradEnt)}\Currentboundaryerrorhavetocontrollowerorder^{(\textnormal{Flat})} & = (\tander^N \GradEnt^\alpha) (\tander^N \GradEnt^\beta) \newuL \gfour_{\alpha\beta}	- (\tander^N \GradEnt^\beta) (\tander^N \GradEnt^\gamma) \newuL^\alpha \p_\beta \gfour_{\alpha\gamma} 
			\\
			& \ \ +  2  (\newuL \ln \Speed)(\tander^N \GradEnt^\beta)(\tander^N \GradEnt)_\beta - 2 (\tander^N \GradEnt^\beta) (\partial_\beta \ln \Speed)(\tander^N \GradEnt)_\gamma \newuL^\gamma  \\
			& \ \ + (\tander^N \GradEnt^\beta) \Transport_\gamma \newuL^\gamma (\tander^N \GradEnt)_a \p_\beta v^a \\
			& \ \ + \frac{1}{\upmu} \left\{ \updelta_\beta^0 \gfour_{\gamma d} - \updelta_\gamma^0 \gfour_{\beta i}\right\}(\tander^N \GradEnt^\beta)  \newuL^\gamma \, ^{(\tander^N)} \ehcurrent_{(\GradEnt;1)}^i  + \frac{1}{\upmu} \Speed^{-2} \upepsilon_{\beta\gamma\delta i} (\tander^N \GradEnt^\beta)  \newuL^\gamma \Transport^\delta \,^{(\tander^N)}\ehcurrent_{(\GradEnt;2)}^i \\
			& \ \ - \frac{1}{\upmu} ( \tander^N \GradEnt^\alpha) \newuL _\alpha \, ^{(\tander^N)}\ehcurrent_{(\GradEnt;3)} - \frac{1}{\upmu} (\tander^N \GradEnt^\alpha) \newuL_\alpha S_a\, ^{(\tander^N)}\ehcurrent_{(v;1)}^a.
		\end{split}
	\end{align}

