[Theorem 21 of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let $0<s<\min\{1,d/2\}$ and $u\in \mathscr S(\R^{d+1})$. Then
\begin{itemize}
\item[(i)] $\mathscr J^\ve_{2s}(\Le^s u)\longrightarrow u$ in $L^2(\R^{d+1})$ as
$\ve\to0^+$; we write this as $\mathscr J_{2s}\Le^su=u$;
\item[(ii)] if moreover $|p|^{-s}\hat u\in L^2(\R^{d+1})$ --- which holds
automatically when $0<s<\frac12$ --- then $\mathscr J_{2s}u\in\Dom(\Le^s)$ and
$\Le^s\mathscr J_{2s}u=u$.
\end{itemize}
In this sense $\mathscr J_{2s}=\Le^{-s}$.

[Lemma lem:lclt of arXiv:2608.05262, 'The law of $(1+1)$D SOS with an area tilt in a wedge'] For $\underline{y}^{(o)}$ of (eq:y-def of the paper), let 
\[
f_N(\delta) := \sup \Big\{ \frac{\mathbb Q_\star(\underline{y}^{(o)} = \underline{u})}{\mathbb Q_\star(\underline{y}^{(o)}=\underline{v})} :
\|\underline{u}\|_\infty \vee \|\underline{v}\|_\infty \le \delta \sqrt{N}, \;\; 
\underline{u},\underline{v} \in \mathbb Z^K \Big\} \,. 
\]
Then, 
\begin{equation}
\lim_{\delta \to 0}\limsup_{N \to \infty} f_N(\delta) = 1 \,.
\end{equation}

[Dfn def:Bregdiv of arXiv:2506.01746, '\bf Optimal Bregman quantization: existence and uniqueness of optimal quantizers revisited'] Let $F:U\to \mathbb{R}^d$ be a continuously differentiable,  strictly convex function defined on a  {\em convex} $U\subset \mathbb{R}^d$. The convex $U$ will be assumed {\em open} in all what follows, except specific mention  (see e.g. Proposition~(prop:existence of the paper)$(a)$). The $F$-Bregman divergence of $x\!\in U$ with respect to (w.r.t.) another point $\xi\!\in U$ is defined by 
\begin{equation}
 \forall\, x\!\in U,\quad \phi_{_F}(\xi,x)= F(\xi)-F(x) -\langle \nabla F(x) | \xi- x \rangle\ge 0.
\end{equation}
Moreover $\phi_{_F}(\xi,x)=0$  if and only if $\xi=x$ since $F$ is strictly convex.

[Lemma 10 of arXiv:2605.17494, 'Generalized intersection exponents and local cut points for three-dimensional Brownian loo'] Let $W_1= A_{\frac{1}{20}} \cap \mathcal{A}(0,2)$ and $W_2= A_{\frac{1}{18}} \cap \mathcal{A}(-\frac{1}{10},\frac{21}{10})$ be two wedges with $W_1 \subset W_2$. There exists a universal constant $C$ such that for any $x_1 \in W_1 \cap S_0$, $x_2 \in W_1 \cap S_2$,
    \begin{equation}
    \Pb^{x_1}(B[0, \sigma_2] \in W_2 \mid B(\sigma_2)=x_2) \ge C,    
    \end{equation}
    where $\sigma_2$ is the last time $B$ visits $S_2$.

[Proposition thm:clt-upper of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] Let $p_n(x,y)$ and $\widetilde{p}_n(x,y)$ be the $n$-step transition probability given by the Markov chain in Definition (defmodel of the paper), with profile functions $f$ and $\widetilde{f}$  satisfying the assumptions in Definition~(ass:ft of the paper).
If $nW^{-K}=o(1)$, then  for all $x \in \Lambda_L$,
\begin{equation}
    \Bigl|\, p_n(0,x) - \tilde{p}_n(0,x)\,\Bigr|
    = O(W^{-d} n^{-\tfrac{d+\delta}{\alpha}})  +\; O( n W^{-K}).
\end{equation}

