[Lemma 7 of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Fix $T>0$, $D, d_X, d_\alpha \in\mathbb N_+$, and let $b:[0,T]\times\mathbb R^{d_X}\times\mathbb R^{d_\alpha} \to\mathbb R^{d_X}$, $\Sigma:[0,T]\times\mathbb R^{d_X}\times\mathbb R^{d_\alpha} \to\mathbb R^{d_X\times D}$ be measurable functions. Assume that $b$ and $\Sigma$ are bounded and globally Lipschitz in $(x,a)$, uniformly in $t$. Let $x_0\in L^2(\mathcal F_0;\mathbb R^{d_X})$. Then, for every $\alpha\in \mathcal{H}_T^2(\mathbb R^{d_\alpha})$, the SDE
\begin{equation*}
    X_t^\alpha = x_0 + \int_0^t b(s,X_s^\alpha,\alpha_s)\,\ud s + \int_0^t \Sigma(s,X_s^\alpha,\alpha_s)\,\ud W_s
\end{equation*}
admits a unique strong solution with continuous adapted paths. In particular,
\(X^\alpha\) is predictable and belongs to $\mathcal{H}_T^2(\mathbb R^{d_X})$. Moreover, the control-to-state map $\Gamma:\mathcal{H}_T^2(\mathbb R^{d_\alpha})\to \mathcal{H}_T^2(\mathbb R^{d_X})$ such that $\Gamma(\alpha)\eqdef X^\alpha$, is well-defined and globally Lipschitz.

[Lemma eq:local-mass of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:local-centering}
For $a,b,s$ as above,
\begin{align}
 \int f_{a,b}\,d\gamma_1
 &=e^{a^2/2}\Phi(s),\\
 \int zf_{a,b}(z)\,d\gamma_1(z)
 &=e^{a^2/2}\bigl(a\Phi(s)-\varphi(s)\bigr).

\end{align}
Consequently, the first moment vanishes if and only if
\begin{equation}
  a=r(s):=\frac{\varphi(s)}{\Phi(s)},
  \qquad
  b=H(s):=s+r(s).
\end{equation}

[Lemma diag:circ-vs-phi-sym-mon of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] For any compact Lie group $G$, we have a commutative diagram
    \begin{equation}
        \begin{tikzcd}
            \CAlg(\cat{$\textbf{\textup{L}}$-Top}^\boxtimes)\arrow[rr,"{{{\mathfrak S\kern-.4pt}}_\textup{$G$-gl}^\circ[{\textup{triv}}_G(-)]^\otimes}"]\arrow[dr,"\CAlg(\Phi^\otimes\circ\textup{loc})"', bend right=15pt] && \CMon(\Spc)\rlap.
            \\
            &\CMon(\Spc_{\textup{Glo}})\arrow[ur,"\ev_{\mathbb B{G}}"', bend right=15pt]
        \end{tikzcd}
    \end{equation}
    \begin{proof}
        By [schwede2018global]*{Theorem 2.1.15}, $\CAlg(\cat{$\textbf{\textup{L}}$-Top})$ admits a model structure with weak equivalences and fibrations defined after forgetting the commutative algebra structure; in particular, the localization $\mathfrak U_\textup{gl}$ of $\CAlg(\cat{$\textbf{\textup{L}}$-Top})$ has finite coproducts and products with products created by the forgetful functor to ${{\mathfrak S\kern-.4pt}}_\textup{gl}$. Moreover, as discussed right before Definition 2.5.15 of \emph{op.\ cit.}, $\mathfrak U_\textup{gl}$ is semiadditive.

        It is clear that the bottom composite through the above diagram descends to a finite product-preserving functor $\mathfrak U_\textup{gl}\to\CMon(\Spc)$. By [Gepner-Groth-Nikolaus]*{Corollary~2.5}, it will therefore suffice to prove that $((diag:circ-vs-phi-sym-mon of the paper))$ commutes after postcomposition with the forgetful functor $\CMon(\Spc)\to\Spc$. This however follows immediately from the previous lemma.
    \end{proof}

