[Lemma 5 of arXiv:2605.04359, 'Well-posedness of reflected BSDEs with default time and irregular barrier: An application '] There exists a positive constant $\mathfrak{C}_{\beta}$ independent of $n$ such that for all $\beta >1$
		\begin{equation*}
			\begin{split}
				&\left\|Y^n \right\|^2_{\mathfrak{B}^2_{\beta}}+\left\|Z^n \right\|^2_{\mathcal{H}^2_{\beta}}+\left\|U^n \right\|^2_{\mathcal{M}^2_{\gamma,\beta}}+\mathbb{E}\left|K^{n}_T \right|^2 \\
				& \leq \mathfrak{c}_{\beta} \left( \mathbb{E}e^{\beta A_T}\left|\xi \right|^2+  \mathbb{E} \esssup_{\eta \in \mathcal{T}_{[0,T]} } e^{2 \beta A_{\eta}} \left| \xi_{\eta}^{+}\right|^2  +  \mathbb{E} \int_{0}^{T} e^{\beta A_s} \left| \dfrac{g(s)}{\alpha_s} \right|^2 ds \right) .
			\end{split}
		\end{equation*}

