[Lemma return-shift of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Under the assumptions of Theorem~(IP-limit of the paper), define 
\begin{equation}
I=\mathrm{FS}(q_{1},q_{2},\dots ),\qquad I^{\prime }=\mathrm{FS}
(q_{2},q_{3},\dots ),\qquad m=q_{1}.  
\end{equation}
Then:

\begin{enumerate}
\item $a_{n}\rightarrow a^{\ast }$ as $n\rightarrow \infty $ along $n\in I$;

\item $a_{n+m}\rightarrow a^{\ast }$ as $n\rightarrow \infty $ along $n\in
I^{\prime }$;

\item for every $n\in I^{\prime }$, the pair $(n,n+m)$ lies in $I\times I$.
\end{enumerate}

[Theorem LLN0 of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume that $(i)$ $({\bf A}_0)$ with $\ell_0=0$, $({\bf A}_{4})$ and $({\bf A}_{5})$ with $\ell_0^\star=0$ for the EM scheme (equation WW of the paper);   $(ii)$ $({\bf A}_0)$, $({\bf A}_2)$ and $({\bf A}_{3})$ for the TEM scheme (equation EW0- of the paper);   $(iii)$ $({\bf A}_0)$, $({\bf A}_{4})$ and $({\bf A}_{5})$ for the PEM scheme (equation EWW of the paper).
Then, for any $f\in\mathscr C_\rho$, $\varepsilon\in(0,1/2)$, and $x\in\mathds R^d,$ there exist constants $C_0=C_0(x,\rho,\varepsilon,\|f\|_\rho),\sigma_0>0$ and  a random time $N_{\varepsilon,\delta}=N_{\varepsilon,\delta}(x,\rho,d)\ge 1$    such that for all $\delta\in(0,\delta_2^\star]$,  $n\ge N_{\varepsilon,\delta}$ and the noise intensity  $\sigma$ satisfying  $|\sigma|\ge\sigma_0,$
\begin{equation}
\bigg|\frac{1}{n}\sum_{k=0}^{n-1} f(X_{k\delta}^{\delta,x})-\pi_\8(f) \bigg|\le C_0 \big(n^{-{1}/{2}+\varepsilon}\delta^{-1/2}+\delta^{\gamma_\star}   d^{(\ell_\star+ \rho)/2}\big),\quad a.s.,
\end{equation}
where
$\pi_\8$ means the unique IPM of $(X_{t})_{t\ge 0}$ solving (equation E1 of the paper), and the  quantities $\gamma_\star,\ell_\star$ are the same as those given in Theorem (cor of the paper). Moreover, for any $q>0,$ there is a constant $C_q^*>0$ such that
\begin{align}
	\mathbb E N_{\varepsilon,\delta}^q\le C^*_q\big(1+|x|^{2(1+\rho)} +d^{1+\rho}\big)^{\frac{q+2}{2\varepsilon}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture conj:offdiagfl of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $\Omega_1$ and $\Omega_2$ be the regions defined in Conjecture (conj:LLN of the paper), and let $h(x,y)$ be the function defined in (equation eq:LLNconjv of the paper). 
Under the same assumptions and notation as in Theorem (thm:diagfluc of the paper) and (thm:offdiagflucsameside of the paper), and conditional on the event $\mathcal{L}(aN,bN)=\ell N$, we conjecture that the following results hold. 
\begin{enumerate}[(a)]
\item For each $(x,y)\in \Omega_1$, 
\begin{equation} 
    \lim_{N\to \infty} \frac{\mathcal{L}(xaN, ybN)- h(x,y) N}{ (ab(x-1)(y-1))^{-1/6}(\sqrt{a(x-1)}+\sqrt{b(y-1)})^{4/3}  N^{1/3}} \stackrel{d}{=} \TW_2.
\end{equation}
\item We expect that 
\begin{equation} 
    \frac{\mathcal{L}(xaN, ybN)-  h(x,y) N}{ \sqrt{2} \mathsf{\sigma}   N^{1/2}} \xrightarrow{\textit{f.d.d.}} 
    \begin{dcases} \mathsf{c}_{+} \mathbb{B}^{\mathrm{br}}_{+} \left( \frac{\mathrm m y- x}{\mathrm m -1} \right) \quad &\text{for $(x,y)\in \Omega_2\setminus \overline{\Omega}_1$ satisfying $y<x$,} \\
    \mathsf{c}_{-} \mathbb{B}^{\mathrm{br}}_{-} \left( \frac{\mathrm m x- y}{\mathrm m -1} \right) \quad &\text{for $(x,y)\in \Omega_2\setminus \overline{\Omega}_1$ satisfying  $y>x$}
    \end{dcases}
\end{equation}
as $N\to \infty$, where $\mathbb{B}^{\mathrm{br}}_{+}$ and $\mathbb{B}^{\mathrm{br}}_-$ are independent standard Brownian bridges, and furthermore, they are the same ones appearing in (equation eq:defcd of the paper). 

\item For each $(x,y)\in {\mathbb R}_+^2\setminus \overline{\Omega}_2$, 
\begin{equation} 
    \lim_{N\to \infty} \frac{\mathcal{L}(xaN, ybN)- h(x,y) N}{ (abxy)^{-1/6}(\sqrt{ax}+\sqrt{by})^{4/3}  N^{1/3}} \stackrel{d}{=} \TW_2. 
\end{equation}
\end{enumerate} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

