[Theorem 7 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] For every compact connected $G$ and $t>0$, the apparent singularities in \eqref{eq:ambient-W} are removable. The resulting entire function on $\tLie_{G,\C}$ is invariant under $\Wt_G\ltimes\Lambda_G$, and
		\begin{equation}
			q_t^{\C}(\exp Z)
			=\frac{\vol(G)e^{t|\rho_G|^2}}{(4\pi t)^{\dim G/2}}
			\mathscr W_{G,t}(Z),
			\qquad Z\in\tLie_{G,\C}.
		\end{equation}
		Its restriction to $Z\in\tLie_G$ is the ordinary heat kernel $q_t$.

[Lemma lem:FR-derivative-bounds of arXiv:2607.02742, 'Gaussian fluctuations for the parabolic Anderson model with L\'evy white noise'] Let $p\in[1,\frac{3}{2})$ be such that $m_{2p}<\infty$. 

\textup{(i)} For any $0\le r<t\le T$, $y\in\mathbb{R}$ and $z\in\mathbb{R}_0$,
\begin{equation}

\big\lVert D_{r,y,z}F_R(t)\big\rVert_{2p}
\lesssim
|z|\Phi_{t-r,R}^{(p)}(y).
\end{equation}

\textup{(ii)} Let $\xi_i=(r_i,y_i,z_i)$, $i=1,2$. For any
$0\le r_1,r_2<t\le T$ with $r_1\neq r_2$, $y_1,y_2\in\mathbb{R}$ and
$z_1,z_2\in\mathbb{R}_0$, we have
\begin{equation}

\big\lVert D_{\xi_1,\xi_2}^2F_R(t)\big\rVert_{2p}
\lesssim
|z_1z_2|
\begin{cases}
K_{r_2-r_1}^{(p)}(y_2-y_1)\Phi^{(p)}_{t-r_2,R}(y_2),
& \text{if } r_1<r_2,\\
K^{(p)}_{r_1-r_2}(y_1-y_2)\Phi^{(p)}_{t-r_1,R}(y_1),
& \text{if } r_2<r_1.
\end{cases}
\end{equation}

