body:
[Theorem general_bound of arXiv:2411.04322, 'Bounding Hellinger Distance with Stein's Method'] Let $\mathbf{X}$ be random variable taking values in a Polish-space $\mathcal{X}$ and $g:\mathcal{X}\rightarrow\mathbb{R}$ be a measurable function for which $S\triangleq g(\mathbf{X})$ has convex support $\Omega_S\subseteq\mathbb{R}$, $\mbb{E}[S]=0$, 
$\mrm{Var}(S)=1$, Lebesgue density $f_S\in C^1$, 
and {first and second-order score functions} 
$\score[S],I_S \in\Lp[2](S)$ satisfying $\norm{\score[S](S) S}_2<\infty$.

Fix any $D\in(0,1)$ and any anti-symmetric function $F(\cdot,\cdot):\mathcal{X}^2\rightarrow\mathbb{R}$ and, for each $t \geq -\frac{1}{2}\log(1-D)$, 
define $S^t\triangleq g(\mathbf{X}^t)$ where $\mathbf{X}^t$ is an exchangeable copy of $\mathbf{X}$ and
\begin{talign}
\sum_{k=1}^{\infty}\frac{e^{-kt}k}{\sqrt{k-1}!\sqrt{1-e^{-2t}}^k}\|\mbb{E}[(S^t-S)^{k-1}F(\mathbf{X}^t,\mathbf{X}) \mid S]\|_2< \infty.
\end{talign}

Then, for any $s\in\mathbb{R}$,
we may bound the Hellinger distance

\begin{talign}
 H(S,Z) 
 &\triangleq (\frac{1}{2}\int_{\mathbb{R}}(\sqrt{f_S(x)}-\sqrt{\varphi(x)})^2dx)^{1/2}\\
 &\le\frac{1}{\sqrt{2}}\int_0^{\infty}\|I_{Z_t}(Z_t)-I_{Z}(Z_t)+Z_t(\score[Z_t](Z_t)-\score[Z](Z_t))\|_2dt
   \\&\le \frac{1}{\sqrt{2}}

   \{-\frac{1}{2}\log(1-D)(1+\|\score[S](S)S\|_2)


    +\|\score[S](S)\|_2(\sqrt{\frac{D}{1-D}}-\rm{tan}^{-1}(\sqrt{\frac{D}{1-D}}))\\
&+\frac{D}{1-D}\|I_S(S)\|_2
    + 
\int_{-\frac{1}{2}\log(1-D)}^{\infty}\|\frac{e^{-2t}}{{1-e^{-2t}}}h_2(Z)-\frac{e^{-t}}{\sqrt{1-e^{-2t}}}Sh_1(Z)-\tilde\tau_{t,s}\|_2dt\}

\end{talign}
in terms of the Gaussian score functions $\score[Z](z) \triangleq -z$ and $I_Z(z) \triangleq z^2-1$, the interpolants

\begin{talign}
Z_t\triangleq e^{-t}S+\sqrt{1-e^{-2t}}Z 
    \ \ \text{with}\ \  
    Z\perp\!\!\!\perp S, 
    \ \ \text{density}\ \ 
f_{Z_t},
    \ \ \text{and}\ \ 
    (\score[Z_t],I_{Z_t}) \triangleq (\frac{\partial_x{f_{Z_t}}}{f_{Z_t}}, 
\frac{\partial_x^2f_{Z_t}}{f_{Z_t}})
\end{talign}
for $t > 0$,  
and the Hermite sum 

\begin{talign}

\tilde\tau_{t,s}
    &\triangleq
\frac{se^{-t}}{\sqrt{1-e^{-2t}}}\mbb{E}[F(\mathbf{X}^t,\mathbf{X})\mid S]h_1(Z)+\sum_{k=2}^{\infty}\frac{s e^{-kt}}{k!\sqrt{1-e^{-2t}}^k}\mbb{E}[(S^t-S)^{k-1}F(\mathbf{X}^t,\mathbf{X})\mid S]h_k(Z)
\end{talign}
where $h_k(x)\triangleq (-1)^k e^{x^2/2} \frac{\partial^k}{\partial x}e^{-x^2/2}$ designates  the $k$-th Hermite polynomial for $k\in\mathbb{N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: tightness for G at crit of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
The scaled process $\left(\widetilde{\mathcal G}^{(p)}(t): {t\ge 0}\right)$ is continuous in $p \in [0, p_c)$
under the topology of weak convergence, as processes in $C[0,\infty)$. 
Further, if the memory sequence $\{\mu_n\}$ is such that $\{v_n\}$ is unbounded for $p=p_c$, then, for a standard Gaussian random variable $Z$, as $p\uparrow p_c$,we have
\[
\left(\widetilde{\mathcal G}^{(p)}(t): {t\ge 0}\right) \to_{\rm{w}}
\left(\sqrt{t} (2\gamma+1) Z: {t\ge 0}\right) \quad \text{in $C([0,\infty))$.}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Tight ATE for Gaussians (Lemma 3.10, \cite{ascolani:lavenant:zanella2026})}


    Let $\mathcal N$ be the multivariate Gaussian probability measure with mean $\mu \in \R^n$ and covariance matrix $\Sigma \in \R^{n \times n}$ and let $X \sim \mathcal N$. Then, with $\kappa^\star(\Sigma) := \eigmax{D^{1/2} \Sigma D^{1/2}}$ where $D := \diagonal{\Sigma\inv}$ we have
    \begin{align*}
        \ent[\mathcal N]{f} 
        \leq \kappa^\star(\Sigma) \cdot \sum_{i=1}^n \E[\ent[\mathcal N(\cdot | X_{-i})]{f}].
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def: solution of arXiv:2603.01823, 'on a fractional stochastic heat equation arising from the disordered pinning model'] A random field $\{u(t,x), t\in[0,T], x\in \mathbb R\}$ is called a \emph{mild Skorohod solution} to (equation e:she of the paper), if $\{u(t,\cdot), t\in[0,T]\}$ is adapted to the filtration induced by the noise $\xi$, $u(t,x)$ is $L^1$-integrable for each $(t,x)\in[0,T]\times\mathbb R$,  and the following integral equation is satisfied:
\begin{equation}
u(t,x)=\int_\mathbb R g_\rho(t,x-y) u_0(y) dy+\int{\raisebox{-.82em}{\hspace{-1.18em}\scriptsize \bf o}}\hspace{.7em}\1_{[0,t]}(\cdot) g_{\rho}(t-\cdot,x)u(\cdot,0)\xi,
\end{equation}
where $g_\rho$ is the transition density function  of the $\rho$-stable process $X$ and the second integral on the right-hand side is an $L^1$-Skorohod integral (see Section (sec:pre of the paper) for the definition).

[Lem 12 of arXiv:2604.06122, 'REM universality for linear random energy'] For any $h\in \R^{\N}$
\been{
n\e\leq \Gamma_n(h)\leq -n\log(\e).
}

