[Definition Def_PartialConnectionAlongSpaceOfRamifiedLineBundles of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Given a local infinitesimal uniformiser $\mathscr{F}^\mathbf{Ram}|_\mathscr{U} \to \mathrm{Vect}(X), ({\mathbf{p}},[{\mathfrak l}];v) \mapsto \bar v = \bar v({\mathbf{p}},[{\mathfrak l}],v)$ as in (Prop_InfinitesimalSliceUniformisers of the paper),
  define the partial covariant derivatives $\nabla^\mathbf{Ram}$ with respect to $\mathscr{F}^\mathbf{Ram}$ on $\mathbf{E}|_\mathscr{U}$, $\mathbf{F}|_\mathscr{U}$, and $\mathbf{G}|_\mathscr{U}$ by
  \begin{equation*}
    \nabla^\mathbf{Ram}_v \coloneq \nabla^\mathbf{Sl}_{({\mathbf{p}},[{\mathfrak l}],v) \cdot \mathrm{lift}_{\mathbf{p}}^K(\bar v)}.
    \qedhere
  \end{equation*}

[Definition def: loops to be inserted in STEP1 of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] For any $\omega \in \mathcal{A}$ and $\boldsymbol{x}\in \mathcal{R}(\mathcal{L}_{\boldsymbol{F}}^{\beta_N}(\omega))$, we define
    \begin{equation}

        \beta_{\boldsymbol{x}}=\beta_{\boldsymbol{x}}(\omega)=
        \begin{cases}
            \beta(\boldsymbol{x},\mathsf{Near}(\omega,\boldsymbol{x}))&\text{if $\boldsymbol{x} \neq \mathsf{Near}(\omega,\boldsymbol{x})$},\\
            \beta_{i}(\boldsymbol{x})&\text{if $\boldsymbol{x} = \mathsf{Near}(\omega,\boldsymbol{x})$ and $\mathsf{Dir}(\omega,H_{\beta_N}(\omega,\mathsf{Near}(\omega,\boldsymbol{x}))-1)=i$},
        \end{cases}
    \end{equation}
    where $\mathsf{Dir}(\omega,k)=i$ if $\omega(k+1)-\omega(k)=\pm e_i$ for a path $\omega$ and $k \geq 0$. 
    Moreover, we define 
    \begin{equation}

        B(\omega)=\{\beta_{\boldsymbol{x}}(\omega)\,:\, \boldsymbol{x} \in \mathcal{R}(\mathcal{L}^{\beta_N}_{\boldsymbol{F}}(\omega))\}
    \end{equation}
    as the collection of loops to be inserted in the first step.

[Proposition 51 (Metric transfer does not control deterministic response) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] There exist a profile-admissible bounded target transform \(f\), a bounded transform \(h\) with the same unshifted centering and normalization, and a delocalized spike sequence such that
\begin{equation}
        \frac{2}{N(N-1)}\sum_{i<j}
        \E|h(\zeta+s_{ij})-f(\zeta+s_{ij})|^4\longrightarrow0,
\end{equation}
while the deterministic mean-matrix difference converges to a nonzero rank-one perturbation and has a nonvanishing analytic LSS response.

[Lemma lem:HKUB of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $A>0$, $k\ge 1$, $\delta\in (0,\frac14)$, $0<t_0<T$,  and $\hslash>0$. Then, for some $C>0$ and all $\mathbf x, \mathbf y \in \mathbb{Z}^k$, $N\in \mathbb{N}$, $|\beta|\le AN^{-1/8}$, and $t\in [t_0,TN]$, 
\begin{equation}
\mathbf P_\mathbf x^{(\beta,k)}(|R_t^i-\sinh(\beta)t-y_i|\le 1,\,\forall\,1\le i\le k)\le C t^{-k/2+\delta}\ttonde{1+t^{-1/2}|\mathbf x-\mathbf y|}^{-\hslash} \; \text{.}
\end{equation}

