[Corollary 37 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] In the above setting (assuming Assumption \ref{Assumption::Intro::MaximalSub}), the following holds.
    Fix a vertex \(\gamma\in \R\) for \(\left( \FormQF, \BSet \right)\).
    There exists a unique \(K_t(\xi,\eta)\in \CinftySpace[(0,\infty)\times \Omega\times \Omega]\)
    such that for \(g\in \LpSpace{2}[\Omega,\Vol]\),
    \begin{equation*}
        T(t) g(\xi) = \int K_t(\xi,\eta) g(\eta)\: d\Vol[\eta], \quad \forall (t,\xi)\in (0,\infty)\times \Omega,
    \end{equation*}
    where the above integral converges absolutely.\footnote{Here, and in other similar situations,
    we identify \(g\) with a function in \(\LpSpace{2}[\ManifoldN,\Vol]\) by setting it to be zero
    on \(\ManifoldN\setminus\Omega\).}
    Furthermore, for every compact \(\Compact\Subset \Omega\),\footnote{Throughout the paper, we write \(A\Subset B\) to denote that \(A\) is a relatively compact subset of \(B\).} there exist \(\delta_\Compact>0\) and \(c_\Compact>0\) such that, for all ordered multi-indices \(\alpha\) and \(\beta\) and every \(j\in \Zgeq\), there exists \(C_{\alpha,\beta,j,\Compact}\geq 0\) such that the following estimate holds for all \(\xi,\eta\in \Compact\) and all \(t>0\):
    \begin{equation}
    \begin{split}
         \left| \partial_t^j W_\xi^{\alpha} W_\eta^{\beta} K_t(\xi,\eta) \right|
         \leq& C_{\alpha,\beta,j,\Compact}
         e^{-\gamma t}
         \left( \left( \MetricW[\xi][\eta] +t^{1/2\kappa} \right)\wedge \delta_\Compact \right)^{-2\kappa j-|\alpha|-|\beta|}
         \\&\times \exp \left(  -c_\Compact \left( \frac{\left( \MetricW[\xi][\eta]\wedge \delta_\Compact \right)^{2\kappa}}{t}  \right)^{\frac{1}{2\kappa-1}}  \right)
         \\&\times \Vol*[ \BW*{\xi}{\left( \MetricW[\xi][\eta]+t^{1/2\kappa} \right)\wedge \delta_\Compact}]^{-1}.
    \end{split}
    \end{equation}
    Here and throughout the paper, \(a\wedge b=\min\{a,b\}\).
    Also, \(W_\xi\) denotes the list \(\left( W_1,\ldots, W_r \right)\) thought of as 
    first-order partial differential operators
    acting in the \(\xi\)-variable; similarly for \(W_\eta\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def:-2 of arXiv:2411.13403, 'Path weighting method for spot sensitivities and its variance reduction'] For any $\epsilon_{1}>0$ and $\epsilon_{2}>0$, the
\emph{covariance inflated process} $S_{t}^{\epsilon_{1},\epsilon_{2}}$
is defined to be the process given by 
\begin{equation}
\begin{aligned}S_{t_{i+1}}^{\epsilon_{1},\epsilon_{2}} & =H_{i}(S_{t_{i}}^{\epsilon_{1},\epsilon_{2}},\sqrt{\Delta t_{i+1}}Z_{i+1}),\;i\ge1,\\
S_{t_{1}}^{\epsilon_{1},\epsilon_{2}} & =H_{1}^{\epsilon_{1},\epsilon_{2}}(s,\sqrt{\Delta t_{1}}Z_{1}),
\end{aligned}

\end{equation}
where the functional $H_{1}^{\epsilon_{1},\epsilon_{2}}$ is obtained
by replacing the volatility curve (for the time step $[t_{0},t_{1})$
only) $\sigma_{0}^{(k)}(s^{(k)})=\sigma^{(k)}(t_{0},s^{(k)})$ by
\begin{equation}
\sigma_{0,\epsilon_{1}}^{(k)}(t,s^{(k)})=\sigma_{0}^{(k)}(S_{t_{0}}^{(k)})+\epsilon_{1},
\end{equation}
and replacing the correlation matrix $\Sigma=Q\Lambda^{2}Q^{\text{T}}$
(for the time step $[t_{0},t_{1})$ only) by 
\begin{equation}
\Sigma_{\epsilon_{2}}=\epsilon_{2}I+(1-\epsilon_{2})\Sigma.
\end{equation}

[Thm thm3 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Suppose $v^\varepsilon(0) \in H^1$ and $c_i(0) \in {L}^{2}$. Then, the solution of (equation b1 of the paper) is continuous in initial data.
		\begin{proof}
			Applying Lemma (lem1 of the paper) to (equation b20 of the paper), we get
			\begin{align}
				\|v^\varepsilon\|_{L^2}^2+\|\rho\|_{L^2}^2+\|\sigma\|_{L^2}^2 \leq e^{C\int_{0}^{T_0} C(s)ds}(\|v^\varepsilon(0)\|_{L^2}^2+\|\rho(0)\|_{L^2}^2+\|\sigma(0)\|_{L^2}^2).
			\end{align}
			Hence the proof is completed.
		\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

