[Lem lemma:G1decay of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] \begin{enumerate}[(a)]
\item If $\alpha_1,\alpha_2 > 0$ and $\alpha_3 > (\sqrt{\alpha_1}+\sqrt{\alpha_2})^2$, then 
\begin{equation} 
    |z_c^-+1| < s_-:=1-\sqrt{\alpha_2/\alpha_3}, \qquad |z_c^+|< s_+:=1- \sqrt{\alpha_1/\alpha_3},
\end{equation}
and, for every $s \in (0, \mathrm s_-)$,  
\begin{equation} \begin{split}
    &\frac{\partial }{\partial \theta}  \re \mathrm G(-1+se^{\textnormal{\text{i}} \theta })  < 0 \quad \text{for $\theta\in (0,\pi)$;} \qquad 
    \frac{\partial }{\partial \theta}  \re \mathrm G(-1+se^{\textnormal{\text{i}} \theta })  > 0 \quad \text{for $\theta\in (-\pi, 0)$,}
\end{split} \end{equation}
and, for every $s \in (0, \mathrm s_+)$,  
\begin{equation}  \begin{split}
            &\frac{\partial }{\partial \theta}  \re \mathrm G(se^{\textnormal{\text{i}} \theta })  < 0 \quad \text{for $\theta\in (0,\pi)$;} \qquad 
            \frac{\partial }{\partial \theta}  \re \mathrm G(se^{\textnormal{\text{i}} \theta })  > 0 \quad \text{for $\theta\in (-\pi, 0)$.}
\end{split} \end{equation}
\item If $\alpha_1 < 0$ and $\alpha_2,\alpha_3 > 0$, then (equation eq:derG1the2 of the paper) holds with $\mathrm s_+ = 1$.  

\item If $\alpha_2 < 0$ and $\alpha_1,\alpha_3 > 0$, then (equation eq:derG1the1 of the paper) holds with $\mathrm s_- = 1$. 

\end{enumerate}

