			\ErrorIBP^{AG;L}_2[\tander^N v^i; \, \partialmodquant{\tanderY^{N-1}}; \Yvf{A}] \,\voldiamond \right| \\
			 & \lesssim \Errortoparg{N}(\ubar,u).
