[Thm 2 (See Theorems~\ref{thm: transition prob pfaffian kernel} and \ref{thm: transition prob pfaffian kernel initial cond} in the main text) of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N$ be a fixed even integer and let $x=(x_1,\dots,x_N)$ be the ordered coordinates of half-space TASEP particles. Then the half-line open TASEP has transition probability from an empty state to $x$ is given by the Pfaffian
	\begin{equation}
		\mathbb{P}_t(\emptyset\to x) = (-1)^{\binom{N}{2}} \mathrm{e}^{-\alpha t} \Pf \left[\mathsf{Q}\right],
	\end{equation}
    where $\mathsf{Q}$ is a skew-symmetric $N\times N$-dimensional matrix whose entries are given by
    \begin{align*}
        [\mathsf{Q}]_{i,j} := & Q_{i,j}(x_{N-i+1},x_{N-j+1}), 
    \end{align*}
    for all $1\leq i,j\leq N$ and
	\begin{equation}

		Q_{i,j}(x,y) = \alpha^2 \oint_\contour \frac{\dd u}{2\pi\ii} \oint_\contour \frac{\dd w}{2\pi\ii} \frac{u-w}{1-u-w} \frac{w^{i-x}\mathrm{e}^{t(w-1)}}{(w-\alpha)(w-1)^i} \frac{u^{j-y}\mathrm{e}^{t(u-1)}}{(u-\alpha)(u-1)^j},
	\end{equation}
    where the contour $\beta$ surrounds the points $1,0,\alpha$ and $1-\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] For every finite signed Radon measure $\sigma$ on $D$,
\begin{equation}
 \int_Dq\,d\sigma=0\quad(q\in Q)
 \qquad\Longrightarrow\qquad
 \sigma=0.

\end{equation}

[Definition 146 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $q',p',\beta'\in(1,\infty)$ and let $x_{\cdot}$  
 be a solution  of
 \eqref{3.24,1}. We call it {\em
$E_{q',p',\beta'}$-admissible \/} 
\index{$E_{q,p,\beta}$-admissible solutions}
if 
for any $ T\in(0,\infty)$ there exists
a constant $N\in(0,\infty)$ such that for any
  nonnegative Borel  $f$ on $\bR^{d+1} $  
    we have
\begin{equation}

E   \int_{0}^{T}  
f(s,x _{ s} )\,ds \leq N  
 \|  f\| _{E_{q',p',\beta'}} .
\end{equation}

[Prp 20 of arXiv:2605.27974, 'Discrete approximation of semi-Dirichlet forms with non-symmetric perturbations of resista'] For any $f \in \mathcal{F}$, 
\begin{equation}
\norm{f}_{\infty} \leq
\left(\mathrm{diam}_{R}X\right)^{1/2} \mathcal{E}(f)^{1/2}+\norm{f}_{L^{2}(X,\mu)}
\end{equation}
holds, where $\mathrm{diam}_{R}X$ denotes the diameter of $X$ with respect to $R$. In particular, we have 
\begin{equation}
    \norm{f}_{\infty} 
    \leq\left( \left(\mathrm{diam}_{R}X\right)^{1/2}+1 \right) \mathcal{E}_{1}(f)^{1/2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:defecttwolattice of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For every $h\geq2$ and $n\geq1$, the least $D$ for which some
$A\subset[0,D]^n\cap\mathbb Z^n$ with $|A|=4$ satisfies $|hA|=M_h-2$ is
\begin{equation}
 D_h=1+\binom{h+1}{2}.
\end{equation}
Consequently
\begin{equation}
 1+\binom{h+1}{2}
 \leq\nu_n(h,4)\leq\nu_1(h,4)
 \leq\max\{h^2,D_h^{\max}\}.
\end{equation}
In particular, $\nu_n(h,4)=\Theta(h^2)$ with constants uniform in $n$.
Moreover, for every $n\geq2$,
\begin{equation}
 \nu_n(h,4)>\nu_1(h,4)^{1/n}.
\end{equation}
Thus the inequality proposed in [NathansonLattice2026]
fails already for $k=4$, for every $h\geq2$ and every $n\geq2$.

