body:
[Lemma 22 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Let $F_1,F_2$ be two sets with $F_1 \cap F_2 = \{z\}$. For $i=1,2$, let $(\CE_i,\CF_i)$ be a resistance form on $F_i$ with associated resistance metric $R_i$. Define $R\colon (F_1 \cup F_2) \times (F_1 \cup F_2) \to [0,\infty)$ by
 \[
 R(x,y) = \begin{cases}
 R_1(x,y) ,& x,y \in F_1,\\
 R_2(x,y) ,& x,y \in F_2,\\
 R_1(x,z)+R_2(z,y) ,& x \in F_1,\, y \in F_2 .
 \end{cases}
 \]
 Then $R$ is a resistance metric on $F_1 \cup F_2$ and the associated resistance form $(\CE,\CF)$ is given by
 \begin{align}\begin{split}
  \CF &= \{ f : f|_{F_1} \in \CF_1,\, f|_{F_2} \in \CF_2 \} ,\\
  \CE(f,f) &= \CE_1(f|_{F_1},f|_{F_1})+\CE_2(f|_{F_2},f|_{F_2}) .
 \end{split}\end{align}

[Pro 16 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let \( \Omega \subset \R^n \) be an open convex subset and $\phi\in\text{\rm SCL}\,(\Omega)$. Then we have
	\begin{align*} \text{\rm Alex}\,(\phi)\subset\reg(\phi)\subset\text{\rm Diff}\,(\phi).
	\end{align*}

[Lemma eq:configuration_disagree_6 of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:coupling-on-radius}
Let $(G,J)$ be a transitive graph and a transitive kernel, and let $(G_n,J_n)_{n \in \mathbf{N}}$ be a sequence of transitive graphs and kernels converging locally to $(G,J)$.

Let $\beta \in \mathbf{R}_+$ and let $(\beta_n)_{n \in \mathbf{N}}$.

Let $\omega_n$ be a configuration sampled from $\mathbf{P}_{\beta_n,G_n,J_n}$ and let $\omega$ be a configuration sampled from $\mathbf{P}_{\beta,G,J}$.

Then there exists a coupling $\mathbf{P}$ of $\omega_n$ and $\omega$ on $B(R_n)$ so that for any $R\le R_n$ satisfying (equation eq:coupling-recall of the paper),

\begin{equation}

    \mathbf{P}
    \Big(
    \omega_n\big[B(R)\big]
        \neq 
        \eta\big[B(R)\big]
    \Big)
    \leq
    \beta \varepsilon + |\beta_n-\beta|\sum_{x,y \in B(R)} J(x,y).
\end{equation}

Suppose that $R \in \mathbf{N}$ is fixed and that $\beta_n \to \beta$.

Then for $\xi > 0$ and for any event $\mathcal{A}_{R}$ which is locally determined by $B(R)$, for all $n$ sufficiently large

\begin{equation} 
   \left\vert
       \mathbf{P}_{\beta_n,G_n,J_n}
        \left(
            \mathcal{A}_{R}
        \right)-\mathbf{P}_{\beta,G,J}
        \left(
            \mathcal{A}_{R}
        \right) 
    \right\vert
    \le
    \xi.
\end{equation}

