[Lemma lem:key_gluability_lemma_mu of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] Suppose that $d=3\alpha$ 
 and that the modified hydrodynamic condition does \emph{not} hold.
  There exist a family of probability measures $\mu_{r,\lambda}$ on $\mathbb Z^d$ such that the following holds.
\begin{enumerate}
\item If 
 $\liminf_{r\to\infty} r^{-\alpha}\mathbb E_{\beta_c,r}|K|<\infty$ then there exist constants
$\delta>0$ and $C$ and an unbounded set of scales $\mathscr{R}$ such that if $r\in \mathscr{R}$ then $\mathbb E_{\beta_c,r}|K| \leq C r^\alpha$ and
\begin{equation*}
 \liminf_{r\to \infty} 
 \sup_W r^{-\alpha} \mathbb E_{\beta_c,r}\left[ 
 |K^W| \mathbbm{1}\left( 
 \sum_{x\in \mathbb Z^d} |K^W \cap B_r(x)|\mu_{r,0}(x) \leq \delta r^{2\alpha}\right)\right]

  <  \frac{\alpha}{\beta_c}
\end{equation*}
 where  the supremum is taken over all subsets of $\mathbb Z^d$.
\item If $\liminf_{r\to\infty} r^{-\alpha}\mathbb E_{\beta_c,r}|K|=\infty$ then there exists $0<\lambda_0 \leq 1$ such that for every $0<\lambda\leq \lambda_0$ there exists $\delta>0$ such that 
\begin{equation*}
 \liminf_{r\to \infty} \sup_W r^{-\alpha}\tilde \mathbb E_{r,\lambda} \left[ |K^W| \mathbbm{1}\left(
 \sum_{x\in \mathbb Z^d}|K^W\cap B_r(x)|\mu_{r,\lambda}(x) \leq \delta r^{2\alpha}\right)\right] \\<  \frac{\alpha}{\beta_c} \bigl(1+ \lambda \alpha |J|\bigr)^{-1},
\end{equation*}
where the supremum is taken over all subsets of $\mathbb Z^d$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

