\mathbf{P}[F(\underline{z},\underline{r}) \cap E_k] \lesssim \prod_u \left(\frac{ 2^{-k(1-a_1)}}{r_u}\right)^{\alpha_{4,\kappa}-a'}
\end{equation}
where the implicit constant does not depend on the choice of $\underline{z},\underline{r}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem Hypercon of arXiv:2507.02518, '{\bf Exponential Ergodicity in Relative Entropy and $L^2$-Wasserstein Distance for non-equ'] Let $\bar{\mu}$ be the invariant probability measure of $(P_t)_{t\ge0}$, and
assume that $(P_t)_{t\ge0}$ is hyperbounded, i.e.,
$\|P_{t_0}\|_{p\rightarrow q }:= \|P_{t_0}\|_{L^p(\bar{\mu})\rightarrow L^q(\bar{\mu})}<\infty $ for some   $t_0>0 $ and  $1<p<q<\infty$.
Assume moreover that $L^2$-exponential ergodicity holds, i.e.
\begin{align*}\|P_t f-\bar{\mu}(f)\|_{L^2(\bar{\mu})}\leq c\text{\rm{e}}^{-\lambda t}\|f-\bar{\mu}(f)\|_{L^2(\bar{\mu})},\ \ t\geq 0
\end{align*}
for some constants $c,\lambda>0$.
Then hypercontractivity holds, i.e.
\begin{align*}
\|P_{\tilde{t}_0}\|_{p\rightarrow q }\leq 1
\end{align*}
for some constant $\tilde{t}_0>0$ depending only on $c,\lambda,q,p,t_0$ and $\|P_{t_0}\|_{p\rightarrow q }$.
Consequently, exponential ergodicity in relative entropy holds:
\begin{align*}
\bar{\mu}(P_t f\log P_tf)\leq \tilde{c}\text{\rm{e}}^{-\tilde{\lambda} t}\bar{\mu}(f\log f),\ \ \bar{\mu}(f)=1, f>0, t\geq 0
\end{align*}
for some constants $\tilde{c}, \tilde{\lambda}>0$ depending only on $\tilde{t_0},q,p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

