[Proposition lem:basic-props-NLMP of arXiv:2604.25851, '{Non-uniqueness of nonlinear Markov processes in the sense of McKean associated with parab'] {RehmeierRoeckner2025NonlinearMarkov}}]
\begin{enumerate}[leftmargin=20pt, label=(\roman*), font=\normalfont]
    \item Let $\{P^z\}_{z\in \mathbb{R}^d}$ be a normal linear Markov process, and set 
    $$P^\zeta := \int_{\mathbb{R}^d} P^z \,d\zeta(z) 
    $$ for all $\zeta \in \mathcal P$. Then $\{P^\zeta\}_{\zeta \in \mathcal P}$ is a nonlinear Markov process with $\mathcal P_0 = \mathcal P$.
    Likewise, $\{P^\zeta\}_{\zeta \in \bar{\mathcal P}_0}$ is a nonlinear Markov process, where $\bar{\mathcal P}_0 \coloneqq \{P^z_t\,:\, z\in \mathbb{R}^d, t \geq 0\}$. The latter is the minimal nonlinear Markov process containing $\{P^z\}_{z\in \mathbb{R}^d}$, i.e. for any nonlinear Markov process $\{P^\zeta\}_{\zeta \in \mathcal P_0}$ with $\{\delta_z , z\in \mathbb{R}^d\} \subseteq \mathcal P_0$ and $P^{\delta_z} = P^z$ one has $\bar{\mathcal P}_0 \subseteq \mathcal P_0$.
    \item Unlike for linear Markov processes, the one-dimensional time marginals of a nonlinear Markov process in general do not satisfy the Chapman--Kolmogorov equations
    $$\mu^z_{t+s} = \int_{\mathbb{R}^d} \mu^y_t \,d\mu^z_s(y),\quad \forall z \in \mathbb{R}^d, s,t \geq 0,$$
    even if $\{\delta_z\,|\, z\in \mathbb{R}^d\} \subseteq \mathcal P_0$. They do, however, satisfy the \emph{flow property}
    \begin{equation}
        \mu^\zeta_{t+s} = \mu^{\mu^\zeta_s}_t,\quad \forall \zeta \in \mathcal P_0, s,t \geq 0.
    \end{equation} 
    In the linear case, the flow property follows from the Chapman--Kolmogorov equations.
    \item Similarly (but more involved) than in the linear case, a nonlinear Markov process is uniquely determined by a family of certain one-dimensional time marginals. More precisely, let $\{P^\zeta\}_{\zeta \in \mathcal P_0}$ be a nonlinear Markov process and define $p^{\zeta}_{t}(y,dx) \in \mathcal P$ by 
	\begin{equation}
		p^{\zeta}_{t}(y,dx) := P^{\zeta,y}\circ \pi_t^{-1}(dx),
	\end{equation}
	which is uniquely determined for $\zeta$-a.e. $y\in \mathbb{R}^d$. Here, $P^{\zeta, y}$ is as in Definition (def:NL-MP of the paper). Then for all $n \in \mathbb{N}_0$, $f: (\mathbb{R}^d)^{\otimes n} \to \mathbb{R}$ bounded measurable and $0 \leq t_1< \dots <t_n$, we have
	\begin{multline}
		\mathbb{E}_{\,\zeta} [f(\pi_{t_1},\dots,\pi_{t_n})] = \\ \notag \int_{\mathbb{R}^d}\bigg(\dots \int_{\mathbb{R}^d}\bigg(\int_{\mathbb{R}^d} f(x_1,\dots,x_n)\, p^{\mu^\zeta_{t_{n-1}}}_{t_n-t_{n-1}}(x_{n-1},dx_n)\bigg) p^{\mu^\zeta_{t_{n-2}}}_{t_{n-1}-t_{n-2}}(x_{n-2},dx_{n-1})\dots\bigg)\mu^{\zeta}_{t_1}(dx_1),
	\end{multline}
    where $\mathbb{E}_{\,\zeta}[\cdot]$ denotes expectation with respect to $P^\zeta$. 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] Let $s>0$. The fractional Riesz kernel of order $s$ is given by
\begin{equation}
    k_{s}(x,y):=\frac{1}{\Gamma(s/2)}\int_0^\infty t^{s/2}p_t(x,y)\,\frac{dt}{t}
\end{equation}
for all $x,y\in K$, $x\neq y$.

[Lemma 13 (Properties of $v$) of arXiv:2606.24887, '2606.24887'] Let $v$ be the unique solution of \cref{eq:v}. Let $\delta \in (0,1)$ and $L>0$ be constants.
		Then, for all $w\in \CC$ and $\eta \in (0 , \infty)$, we have
		\begin{equation}
			v(w,\eta) \le \min \biggl\{1, \frac{1}{\eta}\biggr\}.  
		\end{equation}
		Uniformly for all $\eta \in (0,L]$ and $w \in \mathrm{D}_2$, we have 
		\begin{equation}  
			v(w,\eta) \asymp_L \begin{cases} (1 - \abs{w}^2)^{1/2} + \eta^{1/3} & \text{ if } \abs{w} \leq 1, \\ 
				\frac{\eta}{\abs{w}^2 - 1 + \eta^{2/3}} & \text{ if } \abs{w} \geq 1. \end{cases}
		\end{equation}
		In particular, for all $\eta \in (0, L]$ and $w \in \mathrm{D}_2$, we have
		\begin{equation}
			v \gtrsim_{L} \eta.
		\end{equation}
		Finally, for all $\eta \in (0,L]$ and $w \in \mathrm{D}_{1-\delta}$, we have 
		\begin{equation} 
			v(w,\eta) \gtrsim_{\delta,L} 1. 
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

