[Theorem thm:score-gPAM of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Let $u$ be the renormalised solution of any subcritical singular SPDE in the framework of [brunedchandrachevyrevhairer2021], with regularised solutions $u^\varepsilon$, along an approximating family as in the discussion above, converging to $u$ in probability on $\{T < \tau\}$. Fix $t \in (0, T)$, let $\varphi \in C^\infty(\mathbb{T}^d)$, and set $F^\varepsilon := \langle u^\varepsilon(t), \varphi\rangle_{L^2(\mathbb{T}^d)}$.

Assume throughout that $F^\varepsilon$ converges in probability to a real-valued random variable $F$ as $\varepsilon \downarrow 0$, as it does in the standard cases of the framework (Remark~(rem:fixed-time-slice of the paper)). Part~\textup{(c)} uses nothing beyond this; parts~\textup{(a)} and~\textup{(b)} carry the further Malliavin hypotheses stated with them.

\begin{enumerate}[leftmargin=2.4em, label=\textup{(\alph*)}, ref=\textup{(\alph*)}]
  \item[\textup{(c)}] (Distributional derivative at the renormalised limit; unconditional.) Under the standing hypothesis alone, the linear functional
  \[
    \Lambda^{(F)}: C_b^1(\mathbb{R}) \to \mathbb{R}, \qquad \Lambda^{(F)}(\psi) \;:=\; -\,\mathbb{E}[\psi'(F)]
  \]
  is the distributional derivative of $\mathrm{Law}(F)$ on $\mathbb{R}$ in the integration-by-parts sense; the corresponding distributional derivatives of the mollified laws converge weak-$*$ in $(C_b^1(\mathbb{R}))^*$:
  \begin{equation}
  \begin{aligned}
    \Lambda^{(F^\varepsilon)}(\psi) \;=\; -\,\mathbb{E}[\psi'(F^\varepsilon)] &\;\longrightarrow\; -\,\mathbb{E}[\psi'(F)] \;=\; \Lambda^{(F)}(\psi) \\
    &\qquad \text{for every } \psi \in C_b^1(\mathbb{R}), \quad \text{as } \varepsilon \downarrow 0.
  \end{aligned}
  \end{equation}

  \medskip\noindent
  \item[\textup{(a)}] (Mollified score at fixed $\varepsilon$; classical Bismut formula.) Suppose, in addition, that at each fixed $\varepsilon > 0$ the regularised equation supports the classical Malliavin framework (in the white-in-time or abstract Gaussian-space form of Remark~(rem:abstract-gaussian of the paper)), i.e., $F^\varepsilon \in \mathbb{D}^{\infty,p}(\Omega)$ for all $p < \infty$, $\sigma_t^{(\varphi,\varepsilon)} > 0$ a.s., and $(\sigma_t^{(\varphi,\varepsilon)})^{-1} \in L^q(\Omega)$ for all $q < \infty$. Then $F^\varepsilon$ admits the intrinsic scalar logarithmic derivative
  \begin{equation}
    \beta^{(F^\varepsilon),\mathrm{int}}(F^\varepsilon) \;=\; -\mathbb{E}\!\left[\delta_U\!\left(\frac{\mathcal{D} F^\varepsilon}{\sigma_t^{(\varphi,\varepsilon)}}\right) \;\bigg|\; F^\varepsilon\right] \quad \text{in } L^2(\mathbb{R}, \mathrm{Law}(F^\varepsilon)).
  \end{equation}
  In the variational subcase, for any deterministic direction $h \in H$ for which the hypotheses of Theorem~(thm:main of the paper), Part~II, hold for the regularised equation and for which $\ip{h}{\varphi}_H \neq 0$, the pushforward identity
  \begin{equation}
    \ip{h}{\varphi}_H \cdot \beta^{(F^\varepsilon),\mathrm{int}}(F^\varepsilon) \;=\; -\,\mathbb{E}\bigl[\delta_U(v_h^{H,\varepsilon}) \,\big|\, F^\varepsilon\bigr]
  \end{equation}
  expresses the scalar logarithmic derivative in terms of the operator-level Bismut--Nualart formula of Theorem~(thm:main of the paper) applied to the mollified variational equation, with $v_h^{H,\varepsilon}$ the $H$-valued covering field of Section~(sec:proof-main of the paper).

  \medskip\noindent
  \item[\textup{(b)}] (Score-as-function at the renormalised limit; cross-term H\"older closure.) Suppose, in addition, that
  \begin{equation}
    F \in \mathbb{D}^{2,p}(\Omega), \qquad \mathbb{E}\bigl[(\sigma_t^{(\varphi)})^{-q}\bigr] < \infty, \qquad p, q > 2 \text{ with } \tfrac{3}{p} + \tfrac{2}{q} \;<\; \tfrac{1}{2},
  \end{equation}
  or, more generally, the intrinsic pointwise integrability condition
  \begin{multline}
    \norm{\mathcal{D} F}_{H_W}^2\,\norm{\mathcal{D}^2 F}_{HS}\,(\sigma_t^{(\varphi)})^{-2} \;\in\; L^2(\Omega) \qquad \text{and} \\
    \qquad \norm{\mathcal{D}^2 F}_{HS}\,(\sigma_t^{(\varphi)})^{-1} \;\i (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem ContDensL of arXiv:2412.04973, 'On the Laplace equation with non-local dynamical boundary conditions'] Let $\Lambda=0$, $l > 0$, $k \in \mathbb{R}$ and $\alpha \in (0,1]$.  Let assume  $\lambda_1\geq 0.$ Let $w$ be the solution to (equation EsolVVw of the paper). Then, the solution (equation uAlfa of the paper) can be written as 
\begin{align*}
u(t,x) = \int_0^\infty w(s,x) \mathbf{P}_0(L_t \in ds)
\end{align*}
where 
\begin{align}
\int_0^\infty e^{-\lambda t} \mathbf{P}_0(L_t \in ds) = E_\alpha(-\lambda t^\alpha), \quad t \geq 0,\; \lambda \geq 0.

\end{align}

