[Proposition prop:generator of arXiv:2608.17022, 'Sharp hypocoercive convergence estimates for underdamped Langevin dynamics with specular r'] Let $f\in\mathscr C$ and let $(X,V)$ solve (equation eq:sde-jump of the paper)--(equation eq:jump-term of the paper) on $[0,T]$ with $\mathcal T\cap[0,T]$ finite and $(X_s,V_{s-})\notin\Gamma_0$ for every $s\in\mathcal T$. Then
\begin{equation}
\begin{aligned}
f(X_t,V_t)&=f(X_0,V_0)+\int_0^t\mathscr{L} f(X_s,V_s)\,\mathrm{d} s
+\sigma\int_0^t\nabla_vf(X_s,V_s)\cdot \mathrm{d} W_s
\\
&\qquad\qquad\qquad+\sum_{0<s\le t}\Big[f\big(X_s,R_{X_s}V_{s-}\big)-f\big(X_s,V_{s-}\big)\Big],
\end{aligned}
\end{equation}
with $\mathscr{L}$ the operator in (equation eq:bke of the paper). In particular, the jump sum vanishes identically --- so that $f(X_t,V_t)-\int_0^t\mathscr{L} f\,\mathrm{d} s$ is a martingale and $\mathscr{L}$ is the infinitesimal generator with no boundary contribution --- \emph{if and only if} $f$ satisfies the specular symmetry (equation eq:specular-class of the paper).

[Lemma lem:AreaVolumeCapEstimates of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] For any $\mathbf{v}\in\mathbb{S}^{m-1}_+$, ${\boldsymbol{\beta}}\in (-1,\infty)^m$ and $-\|\mathbf{v}\|_1<s<\|\mathbf{v}\|_1$ we have
    \begin{equation*}
        \mathbb{P}_{m}(C^+(\mathbf{v},s);{\boldsymbol{\beta}}) 
            \asymp \prod_{i=1}^{m} \left(\min\left\{\frac{\|\mathbf{v}\|_1-s}{2v_i},1\right\}\right)^{\beta_i+1}.
    \end{equation*}
    Furthermore, if $m=1$, $s\ge 0$ and $\beta\in(-1,\infty)$, or if $m\geq 2$ and ${\boldsymbol{\beta}}\in [0,\infty)^{m}$, then
    \begin{equation*}
        \operatorname{Vol}_{m-1}(C(\mathbf{v},s);{\boldsymbol{\beta}}) 
            \lesssim\,(\|\mathbf{v}\|_1-s)^{-1}\, \prod_{i=1}^{m} \left(\min\left\{\frac{\|\mathbf{v}\|_1-s}{2v_i},1\right\}\right)^{\beta_i+1}.
    \end{equation*}

