[Prop porism of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] Assume (assumption1' of the paper) and (assumption2 of the paper).
	\begin{enumerate}
		\item For any $\varepsilon > 0$ and $a\geq 0$, we have
		\begin{equation*}
		\Pp{ \exists u \in \mathcal{N}(t) : 
			R_u(t) \geq m(t)-a,
			\mathopen{}\mathclose\bgroup\originalleft\lvertY_u(t)\aftergroup\egroup\originalright\rvert \geq t^{\frac{\alpha}{2+\alpha} +\varepsilon} }
		\xrightarrow[t\to\infty]{} 0.
		\end{equation*}
		\item For any $\varepsilon > 0$ and $a\geq 0$, we have
		\begin{equation*}
		\Pp{ \exists u \in \mathcal{N}(t) : 
			R_u(t) \geq m(t)-a,
			\mathopen{}\mathclose\bgroup\originalleft\lvert\theta_u(t)\aftergroup\egroup\originalright\rvert \geq t^{-\frac{2}{2+\alpha} +\varepsilon} }
		\xrightarrow[t\to\infty]{} 0.
		\end{equation*}
		\item The following convergence holds in probability:
		\begin{equation*}
			M_t - \max_{u\in\mathcal{N}(t)} X_u(t) \xrightarrow[t\to\infty]{\mathbb{P}} 0.
		\end{equation*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 (Smooth expanding planar simple wave) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] The pair $(\Nr,\Vr)$ defined by \eqref{eq:burgers}--\eqref{eq:rare-invariants}
is an exact smooth planar solution of \eqref{eq:QE-mass}--\eqref{eq:QE-momentum}.
It has the prescribed end states, stays in $[n_*,n^*]$, and, for each fixed
$0\le t_0<T$,
\begin{equation}
  \abs{(\Nr,\Vr)}_{\cX_{s+3M+5,T}}\le C_{t_0,T}\delta. 
\end{equation}
The constant is uniform for end states in a fixed compact subset of the
genuinely nonlinear rarefaction regime.

