[Theorem 2 of arXiv:2608.29736, '2608.29736'] Let $(M^n,\omega)$ be a compact K\"ahler manifold of complex
 dimension $n\geq 2$. Let $\chi$ be another K\"ahler form.  Suppose that the $J$-semistable condition ~\eqref{topintegralnonnegative}--~\eqref{$J$-semistablecondition} holds. Set the positive constant \begin{equation}
     c= \frac{2n\displaystyle\int_M\Big(\chi^n-n\chi^{n-1}\wedge\omega\Big)+\int_M \omega^n}{8n^2\displaystyle\int_M\chi\wedge\omega^{n-1}},
     \end{equation}and let \begin{equation}
     S:=\{ D \,|\,D\; \text{is a prime divisor and } \int_DF_{n-1}(\chi)< c\int_D\omega^{n-1} \}.
 \end{equation}
Then any finite subset of  $S$ is an exceptional family in the sense of Boucksom~\cite{Boucksom}. In particular, the cardinality of  $S$ is bounded by  the Picard number of $M$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Corner process of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $t=1/q$, $n\ge 1$ be an integer.
\begin{enumerate}[left=0pt]
\item(Alternating case)\begin{enumerate}[left=0pt]
\item Let $\nu \in \Sig_n$ and let $A\in\Alt_{2n+1}(F)$ be random, with the unique $GL_{2n+1}(\mathfrak{o})$-invariant distribution such that $\SN^{\alt}(A)=\lambda$. Let $A_{2n}$ be the $2n\times2n$ corner of $A$ on the top left. Then $\SN^{\alt}(A_{2n})\in\Sig_n$ has distribution $\mathbf{P}_{2n<2n+1}^{\alt}(\cdot\mid\nu)$ defined by

\begin{equation}
\mathbf{P}_{2n<2n+1}^{\alt}(\lambda \mid \nu)=\frac{Q_{\lambda/\nu}(t;t^2)P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)}{P_\nu(1,t^2,\ldots,t^{2n-2};t^2)\prod_{t^2}(t;1,t^2,\ldots,t^{2n-2})}
\end{equation}

\item Let $\lambda \in \Sig_n$, and let $A\in \Alt_{2n}(F)$ be random, with the unique $GL_{2n}(\mathfrak{o})$-invariant distribution such that $\SN^{\alt}(A)=\lambda$. Let $A_{2n-1}$ be the top left $(2n-1)\times(2n-1)$ corner of $A$. Then $\SN^{\alt}(A_{2n-1})\in\Sig_{n-1}$ has distribution $\mathbf{P}_{2n-1<2n}^{\alt}(\cdot\mid\lambda)$ given by

\begin{equation}
\mathbf{P}_{2n-1<2n}^{\alt}(\nu\mid\lambda)=\frac{P_{\lambda/\nu}(1;t^2)P_\nu(t^2,t^4,\ldots,t^{2n-2};t^2)}{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)}
\end{equation}
\end{enumerate}

\item(Hermitian case) Let $\lambda \in \Sig_n$ and let $A\in\Her_n(F)$ be random, with the unique $GL_n(\mathfrak{o})$-invariant distribution such that $\SN^{\her}(A)=\lambda$. Let $A_{n-1}$ be the top left $(n-1)\times(n-1)$ corner of $A$. Then $\SN^{\her}(A_{n-1})\in\Sig_{n-1}$ has distribution $\mathbf{P}_{n-1<n}^{\her}(\cdot\mid\lambda)$ given by
\begin{equation}
\mathbf{P}_{n-1<n}^{\her}(\nu\mid\lambda)=\sum_{\kappa\in\Sig_{n-1}} \frac{P_{\lambda/\kappa}(1;-t) Q_{\nu/\kappa}(-1;-t)P_\nu(-t,\ldots,(-t)^{n-1};-t)}{P_\lambda(1,\ldots,(-t)^{n-1};-t)\Pi_{-t}(1;t,\ldots,-(-t)^{n-1})}  
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 38 (Boundedness and continuity of $\delta\Pi$, Step 8.c)) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $[\beta]\geq0$ and assume that $\eqref{est_deltaPi-_bounded}_\beta$ 
