    \begin{equation}
        P^h_{s,t}(x,dy)=
        \begin{cases}
            \displaystyle \frac{h(t,y)}{h(s,x)}P_{s,t}(x,dy) & \text{ if }(s,x)\in \mathcal A_h, \\
            0 & \text{ otherwise}.
        \end{cases}
    \end{equation}

[Lemma 26 (minorisation) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:interior-minorisation}
  Assume \cref{eq:nonconvex-hyp}, and let $C=[0,M_0]$ be compact. There exists a time $T>0$, an
  interval $[a,b]\subset(0,M_0)$, a constant $\varepsilon>0$ and $h_0>0$ such that, writing
  $m_h=\ceil*{T/h}$,
  \begin{equation}
    K_h^{m_h}(x,\cdot)\ \ge\ \varepsilon\,\mathrm{Leb}|_{[a,b]}\qquad\text{for all }x\in C,\ h\le h_0 .
  \end{equation}

[Theorem th:freedman of arXiv:2411.03955, 'Large Deviations Inequalities for Unequal Probability Sampling Without Replacement\thanks{'] The procedures $\mathfrak{X}$ satisfy $\mathbb{P}\left[
i\in S\right] =kw^{i}$ for every $i$ in $[n]$, and
\begin{eqnarray}
\mathbb{P}\left[ \frac{1}{k}\left\vert S\cap A\right\vert \geq \alpha
+\delta \right] &\leq &\pi (\eta ,\delta ,k)\text{\ \ and}
 \\
\mathbb{P}\left[ \frac{1}{k}\left\vert S\cap A\right\vert \leq \alpha
-\delta \right] &\leq &\pi (\eta ,\delta ,k)  
\end{eqnarray}
for every set $A\subset \lbrack n]$ and $\delta \geq 0$, where 
\begin{equation*}
\alpha :=\sum_{i\in A}w^{i}
\end{equation*}
is the relative weight of $A$, and 
\begin{equation}
\eta :=\alpha -k\sum_{i\in A}(w^{i})^{2}\leq \alpha .  
\end{equation}

