body:
[Theo theo18 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $n\ge 1$ and $\Omega\subset\mathbb{R}^n$ be a bounded domain with smooth boundary, let $a>0$,
  and suppose that
  \begin{equation} \label{h}
	h\in \bigcup_{\iota>0} C^{1+\iota}_{loc} (\mathbb{R}^2)
	\quad \mbox{is such that} \quad
	h(0,0)>0,
  \end{equation}
  that
  \begin{equation} \label{f0}
	\left\{ \begin{array}{l}
	f \in \bigcup_{\iota>0} C^{1+\iota}_{loc}(\mathbb{R}^{2n+2})
	\qquad \mbox{with} \\[1mm]
	f(0,0,0,0)=0 \mbox{ and } \nabla f(0,0,0,0)=0
	\end{array} \right.
  \end{equation}
  and that with some $\lambda>1$, for each $M>0$ there exists $K_f(M)>0$ such that
  \begin{equation} \label{f1}
	|f(\xi,\sigma,X,Y)|
	\le K_f(M) \cdot (1+ |X| + |Y| )^\lambda
	\quad \mbox{for all $(\xi,\sigma,X,Y)\in \mathbb{R}^{2n+2}$ such that } |\xi|+|\sigma|\le M.
  \end{equation}
  Then given any
  \begin{equation} \label{18.001}
	p>n\cdot\max\{\lambda,2\}
	\quad \mbox{such that} \quad
	p\ge 2\cdot\max\{\lambda,2\}

  \end{equation}
  and an arbitrary $r\ge\max\{p,2\lambda\}$ fulfilling
  \begin{equation} \label{18.01}
	r>2\lambda
	\qquad \mbox{if } n=2
  \end{equation}
  and
  \begin{equation} \label{18.02}
	\frac{np\lambda}{n+p-2} \le r < \frac{np}{n-2}
	\qquad \mbox{if } n\ge 3,
  \end{equation}
  one can find $\eta=\eta(p,r,a,h,f)>0$, $\beta=\beta(p,r,a,h,f)>0$ and $\Gamma=\Gamma(p,r,a,h,f)>0$ with the property that whenever
  \begin{equation} \label{init}
	u_0\in C^2(\overline{\Omega}) 
	\mbox{ and } 
	u_{0t} \in \bigcup_{\iota>0} C^{1+\iota}(\overline{\Omega})
	\quad \mbox{are such that} \quad
	u_0=u_{0t}=0 \mbox{ on } \partial\Omega,
  \end{equation}
  and that
  \begin{equation} \label{18.1}
	\int_\Omega |\nabla u_0|^r \le \eta
	\qquad \mbox{and} \qquad
	\int_\Omega |\nabla u_{0t}|^p \le \eta,
  \end{equation}
  the problem ((0 of the paper)) admits a global classical solution
  \begin{eqnarray*}
	u\in C^0([0,\infty);C^1(\overline{\Omega})) \cap C^{2,1}(\overline{\Omega}\times (0,\infty))
  \end{eqnarray*}
  with
  \begin{eqnarray*}
	u_t\in C^0([0,\infty);C^1(\overline{\Omega})) \cap C^{2,1}(\overline{\Omega}\times (0,\infty))
  \end{eqnarray*}
  which is such that $h(u,u_t)\ge\frac{1}{\Gamma}$ in $\overline{\Omega}\times [0,\infty)$, and that
  \begin{equation} \label{18.2}
	\|u(\cdot,t)\|_{W^{1,r}(\Omega)}
	+ \|u_t(\cdot,t)\|_{W^{1,p}(\Omega)}
	\le \Gamma e^{-\beta t}
	\qquad \mbox{for all } t>0.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem SMR_blowup+instreg of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Suppose that (equation SMR_nonlinear_hp of the paper) and the hypotesis of (SMR_maximal_thm of the paper) hold and let $(u, \sigma)$ be a maximal $L^p$-solution of (equation abstract_pb of the paper), then
    \begin{align}
        &\mathbb{P}\Big( \sigma< \infty, \lim_{t \rightarrow \sigma }u_t \mbox{ exists in }{X^{Tr}_p} <\infty\Big) =0\\ 
        &\mathbb{P}\Big( \sigma< \infty, \sup_{t\in [0, \sigma)}\|u_t\|_{X^{Tr}_p} + \int_0^\sigma \|u_t\|^p_{X_1} \mathrm{d}t < \infty \Big) =0 \\
        &\mathbb{P}\Big( \sigma< \infty, \sup_{t\in [0, \sigma)}\|u_t\|_{X^{Tr}_p} <\infty\Big) =0 \quad \text{if (equation criticality_cond of the paper) holds with strict inequality}
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

