[Prop 9 (Solutions for $\theta\neq 0$) of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Let $c^2 \neq 4ab$ with $\theta$ defined in~\eqref{def:theta}. Then~\eqref{eq:lemsollangevin} admits the solution 
\begin{subequations}
\begin{align}
\begin{split}
\begin{aligned}
    q_t &=  \Bigl[ \mfrac{1}{2}\Bigl(1-\mfrac{c}{\theta}\Bigr)e^{-\frac{1}{2}(c+\theta) t} + \mfrac{1}{2}\Bigl(1+\mfrac{c}{\theta}\Bigl)e^{-\frac{1}{2}(c-\theta) t} \Bigr] q_0 - \mfrac{a}{\theta} \Bigl(e^{-\frac{1}{2}(c+\theta) t} - e^{-\frac{1}{2}(c-\theta) t}\Bigr)p_0 \\ 
    & \ + \mfrac{a}{\theta} \int_0^t\bigl( e^{-\frac{1}{2}(c+ \theta)(t-s)} -e^{-\frac{1}{2}(c - \theta)(t-s)}\bigr) \nabla V(q_s,\tilde q_s) ds + \mfrac{a \tilde c }{\theta} \int_0^t \bigl(e^{-\frac{1}{2}(c - \theta)(t-s)} - e^{-\frac{1}{2}(c + \theta)(t-s)}\bigr) dB_s  \,,   
\end{aligned}
\end{split}\\
\begin{split}
    \begin{aligned}
    p_t &= \mfrac{b}{\theta} \Bigl(e^{-\frac{1}{2}(c+\theta) t} - e^{-\frac{1}{2}(c-\theta) t}\Bigr)q_0  + \mfrac{a}{\theta} \Bigl[\mfrac{2b}{c-\theta}e^{-\frac{1}{2}(c+\theta) t} - \mfrac{2b}{c+\theta}e^{-\frac{1}{2}(c-\theta) t}\Bigr] p_0  \\
    & \quad - \mfrac{2ab}{\theta} \int_0^t \Bigl( \mfrac{1}{c- \theta}e^{-\frac{1}{2}(c+\theta) (t-s)} - \mfrac{1}{c + \theta} e^{-\frac{1}{2}(c-\theta) (t-s)}\Bigr) \nabla V(q_s,\tilde q_s) ds  \\ 
    & \qquad \quad  +\mfrac{2a b\tilde c}{\theta} \int_0^t \Bigl( \mfrac{1}{c- \theta}e^{-\frac{1}{2}(c+\theta) (t-s)} - \mfrac{1}{c + \theta} e^{-\frac{1}{2}(c-\theta) (t-s)}\Bigr) dB_s.
    \end{aligned}
\end{split}
\end{align}
\end{subequations}

