[Theorem 20 of arXiv:2608.30415, 'On generalized complex projective product spaces'] Let $C_{(\overline{n}, \overline{p})(\ell),\overline{m}(k)}$ be  a generalized complex projective product space. Then
\begin{equation}
2m_1+k+\ell\leq \TC(C_{(\overline{n}, \overline{p})(\ell),\overline{m}(k)})\leq  2(m_1+k+\ell)-1.    
\end{equation}

[Proposition p:er2 of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Assume the conditions of Theorem (t:er of the paper) hold. Then for every $\eta \in \mathcal{T}$ and $\gamma,\Delta > 0$, as $T \to \infty$, eventually
 \begin{align}
    \nonumber  &  -\log \mathbb{P} \Big( \text{\textup{Per}}(B(T)) , \Big| \Big\langle \tfrac{f}{\sqrt{2m(d-\alpha) \log T}}, \eta_T \Big\rangle -  \langle h_T, \eta_T \rangle \Big| \ge   \Delta  \Big)  \\
 \nonumber   & \qquad \qquad \ge  (m(d-\alpha) - \gamma) \Big( \text{\textup{Cap}}_f  (B(T)) + \min\Big\{ \frac{ \Delta^2-\gamma}{ E[\eta_T]}, \text{\textup{Cap}}_f(B(T)) \Big\} \Big) \log T .
       \end{align}

[Lemma lem:apriori of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] Let $p\geqslant 1$ and $\epsilon>0$. Suppose that  Assumption (ass:main1 of the paper) holds. Let $M$ be as (equation def:noise of the paper) and let $Z=(X,V)$ and $Z^n=(X^n,V^n)$ satisfy (equation eq:SDE of the paper) and (equation eq:SDE-EM of the paper) correspondingly. Then for $Y:=Z-M, Y^n:=Z^n-M$ there exists a constant $C=C(d,\beta,\|b\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}},\alpha,\epsilon,p)$ so that
    \begin{align}
   \|Y_t-{\mathbb E}^sY_t  \|_{L_p(\Omega)|{\mathcal F}_s}  \leqslant C|t-s|^{1+(\frac{\beta}{\alpha}\wedge\frac{1}{p})-\epsilon},\\
         \|Y_t^n-{\mathbb E}^sY_t^n  \|_{L_p(\Omega)|{\mathcal F}_s}  \leqslant C|t-s|^{1+(\frac{\beta}{\alpha}\wedge\frac{1}{p})-\epsilon}.  
    \end{align}

