[Corollary cor:lbm-positive-response-gram of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $x\in\Omega_{\rm LBM}$ and $1\le n_1<\cdots<n_N$ satisfy the hypotheses
of Corollary~(cor:lbm-response-transversality of the paper).  Then the matrix
\begin{equation}
 \left(\inner{U_D\eta_{n_i}^x}{U_D\eta_{n_j}^x}_{H}\right)_{i,j=1}^N

\end{equation}
is positive definite.

[Thm Main Theorem of arXiv:2411.07671, 'Long Time Behavior of General Markov Additive Processes'] Let $(\xi,\Theta),\mathbb{P})$ be a MAP such that Assumptions 1,2,3, and 4 are satisfied. Then, we have
\begin{enumerate}[label=(\roman*)]
    \item $\xi_t$ drifts to $-\infty$ $\:\mathbb{P}_{0,\pi}$-a.s., if and only if\begin{equation}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=1
\end{equation}
\item  $\xi_t$ drifts to $+\infty$ $\:\mathbb{P}_{0,\pi}$-a.s.,  if and only if\begin{equation}
    \int_{S\times \mathbb{R}^-}U_\pi^-(dv,dz)\eta^-_v(\zeta^- =+\infty)=1
\end{equation}
\item $\xi_t$ oscillates $\mathbb{P}_{0,\pi}$-a.s., if and only if \begin{equation}
    \int_{S\times \mathbb{R}^+}U_\pi^+(dv,dz)\eta^+_v(\zeta^+ =+\infty)=0 \quad \text{and} \quad \int_{S\times \mathbb{R}^+}U_\pi^-(dv,dz)\eta^-_v(\zeta^- =+\infty)=0
    \end{equation}
\end{enumerate}
where \begin{equation*}
U^+_\theta (dv,dz)= \mathbb{E}_{0,\theta}\left[ \int_0^{\Bar{L}_\infty} \textbf{1}_{\{ \Theta^+_s\in dv, \xi^+_s\in dz\}}ds \right] \quad \text{and} \quad
     U^-_\theta (dv,dz)= 
     \mathbb{E}_{0,\pi}\left[ \int_0^{\underline{L}_\infty} \textbf{1}_{\{ \Theta^-_s\in dv \, , \, \xi^-_s\in dz \} }ds \right].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 38 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] There exist constants $\varepsilon >0$ and $C>1$ such that the following holds for any $q \in [0, \varepsilon]$. Let $h_0\in (0,\varepsilon]$ and $0 \le s_- \le s_0 \le s_+$ be real numbers such that
                \begin{eqnarray}

                 \mathfrak{l}_q (0)-\mathfrak{l}_q (h_0) \le  s_0
                  \le s_+ \le 1 + \varepsilon-\mathfrak{l}_q (h_0) \\
                  0 \le s_+ - s_- \le C^{-1} s_0^{1/2}
                  .
                \end{eqnarray}
                Then there exist real numbers
                $a,b,c\in [1-C \varepsilon,1+C\varepsilon]$ and $\mathfrak{r}$ such that
                                  \begin{eqnarray}

                                \partial_s \cU^{h_0}_{a,b,c}  (\mathfrak{l}_q (h_0) +s_0+\mathfrak r) = \partial_s \cU^{h_0}_{q} (\mathfrak l_q(h_0)+s_0),
                                  \end{eqnarray}
                                  and, defining $\mathfrak{r}'$ via
                                  \begin{eqnarray}

                                  \mathcal{U}_{a,b,c}^{h_0} (\mathfrak{l}_q(h_0) + s_0 + \mathfrak{r} 
                                  )+   \mathfrak{r}' = \mathcal{U}_q^{h_0} (s_0+\mathfrak l_q(h_0)),  
                                  \end{eqnarray}
                                 \noindent the following statements hold.
                                \begin{enumerate}


                                \item  For all $s \in [ \max(s_-,C^{-1} h_0^{1/2}), s_+]$, we have 
                                  \begin{eqnarray}

                                    \begin{aligned} 
					\mathcal{U}_q^{h_0} & (\mathfrak{l}_q (h_0) + s) - \mathcal{U}_q^{h_0} (\mathfrak{l}_q (h_0) + s_0) \\
					& \ge \mathcal{U}_{a,b,c}^{h_0} (\mathfrak{l}_q (h_0) + s + \mathfrak{r}) - \mathcal{U}_{a,b,c}^{h_0} (\mathfrak{l}_q (h_0) + s_0 + \mathfrak{r}) + C^{-1} qs_0 |s-s_0|^2.
					\end{aligned} 
                                  \end{eqnarray}

                                \item  For all $s \in [s_-,C^{-1} h_0^{1/2}]$, we have 
                                  \begin{eqnarray}

                                    \mathcal U_q^{h_0}(\mathfrak l_q(h_0)+s)\ge
                                    \mathcal U^{h_0}_{a,b,c}(\mathfrak{l}_q (h_0) +s+\mathfrak r)+\mathfrak r'.
                                  \end{eqnarray}
                                                                      \item 
                                                                        For all $h\in[0,h_0]$, we have
                                                                         \begin{equation}

                                                                         \cU_q^{h_0}(\mathfrak l_q(h_0)+s_0)-\cU_q^{h}(\mathfrak l_q(h_0)+s_0) \ge \cU_{a,b,c}^{h_0}(\mathfrak{l}_q (h_0) +s_0+\mathfrak r)- \cU_{a,b,c}^{h}(\mathfrak{l}_q (h_0) +s_0+\mathfrak r).
                                  \end{equation}

