\begin{equation}
F_\lambda(s)=
 e^{-\lambda/2}\E\left[\cosh(\sqrt\lambda\,G)
 \frac{1+(4-3s)\sinh^2(\sqrt\lambda\,G)}{(1+s\sinh^2(\sqrt\lambda\,G))^3}
 \right],
 \qquad s\in[0,1].
\end{equation}
Then, for every $0\le \lambda\le \beta^2(1-q)$,
\begin{equation}
a_2(\lambda)=\E\bigl[S^2F_\lambda(S)\bigr].
\end{equation}
Moreover, for every $\lambda>0$, the function $F_\lambda$ is strictly decreasing on $[0,1]$.

