[Lem 5 of arXiv:2607.22414, 'Asymptotic fluctuations in supercritical multi-type Crump--Mode--Jagers processes'] Assume that~\ref{assumpt:Malthusian alpha} holds and let $\chi$ be a centered characteristic satisfying~\ref{assumpt:dRivar}.
Fix $t\in \G$ and let $(u_1, u_2, \dots)$ be an admissible ordering of $\UHTree$.
Then the process $(M_n(t))_{n\in\N_0}$ given by
	\begin{equation*}
	M_n(t) = \sum_{k=1}^n \be_{\tau(u_k)}^\trans \chi_{u_k}(t - S(u_k)),	\quad	n \in \N_0
	\end{equation*}
	is a martingale that converges a.\,s.\ and in $L^2$. The series
	\begin{equation*}
	\cZ_t^\chi = \sum_{u\in\Tree} \be_{\tau(u)}^\trans \chi_u(t-S(u)) 
	\end{equation*}
	converges unconditionally in $L^2$ and a.\,s.
	In particular, $\cZ_t^\chi$ is the limit of the martingale $(M_n(t))_{n\in\N_0}$. Moreover,
	\begin{equation}
	\Varv[\cZ_t^\chi] = \Ev\big[\cZ_t^{\E[\chi^2]}\big] = \Ev\big[\cZ_t^{\Var[\chi]}\big].
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 21 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] Let $f_1,\ldots,f_N$ and $\mu_t$ be as in \cref{prop:response}.  Fix
$t_0\in\R^N$ and $n\ge1$.  Suppose that $\Lambda_n^{\mu_{t_0}}$ has
multiplicity one.  Then there is a neighborhood $U$ of $t_0$ such that
$\Lambda_n^{\mu_t}$ has multiplicity one for every $t\in U$, and the function
$t\mapsto\Lambda_n^{\mu_t}$ is real-analytic on $U$.  Choose a real
eigenfunction $\phi_{n,t_0}$ satisfying
\begin{equation*}
 A_{\mu_{t_0}}\phi_{n,t_0}
 =\Lambda_n^{\mu_{t_0}}\phi_{n,t_0},
 \qquad
 \|\phi_{n,t_0}\|_{L^2(\mu_{t_0})}=1.
\end{equation*}
Then, for $1\le j\le N$,
\begin{equation}
 \partial_{t_j}\Lambda_n^{\mu_t}\big|_{t=t_0}
 =-\gamma\Lambda_n^{\mu_{t_0}}
 \int_Df_j\phi_{n,t_0}^2\,d\mu_{t_0}.

\end{equation}

