[Theorem 15 of arXiv:2605.02713, '2605.02713'] Let $\beta>1$. 
	\begin{itemize}
		\item[(i)] If $\sigma_n^2 \gg  (1 - \alpha_n^2) $ consider $f=\sum_{q=m}^p c_q H_q$. Then 
		$$ \left( \hat{S}_{n,t}(f) \right)_{t \in [0,1]}  \longrightarrow_{\mathcal{D}} \left( t \sum_{l=0}^{\lfloor (p-1)/2 \rfloor} f_{p-2l} \frac{H_{p-2l}(Z)}{\sqrt{(p-2l)!}} \right)_{t \in [0,1]}   \hspace{1mm} \text{in} \; D[0,1]  \text{ as }n\rightarrow\infty;$$
		\item[(ii)] If $\sigma_n^2 =  (1 - \alpha_n^2) $ consider $f \in L^2 \left(\mathcal{N} \left(0, 1 \right) \right)$. Then
		$$\left( \hat{S}_{n,t}(f) \right)_{t \in [0,1]} \longrightarrow_{\mathcal{D}} \left( t \sum_{q=m}^{\infty}
		h_q \frac{H_q(Z)}{\sqrt{q!}}  \right)_{t \in [0,1]}   \hspace{1mm} \text{in} \; D[0,1]  \text{ as }n\rightarrow\infty;$$
		\item[(iii)] If $\sigma_n^2 \ll  (1 - \alpha_n^2) $ consider $f=\sum_{q=m}^p c_q H_q$. Then
		$$ \left( \hat{S}_{n,t}(f) \right)_{t \in [0,1]}  \longrightarrow_{\mathcal{D}} \left( t \sum_{q=1}^{{m_*}} l_{q} \frac{H_{q}(Z)}{\sqrt{q!}} \right)_{t \in [0,1]}    \hspace{1mm} \text{in} \; D[0,1]  \text{ as }n\rightarrow\infty.$$
	\end{itemize}

