[Lemma 41 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume the framework of Definition \ref{lem-Aldous-Rebolledo}. 
 Let us denote by $\mathbb{P}^1_n$ the law of the process $\bu_n$ on the space 
 $C([0,T];E)$. If the Aldous-Rebolledo condition is satisfied, then   
\item[\textbf{[T]}] for every $\eta >0$,
         \begin{equation}
            \lim_{\zeta \to 0} \varlimsup_{n \to \infty} \mathbb{P}^1_n \{\omega \in C([0,T];\mO): \mc_{\mO}(\omega,\zeta)> \eta\}= 0,
         \end{equation}
or, equivalently, 
       \begin{equation}
         \lim_{\zeta \to 0} \varlimsup_{n \to \infty} \mathbb{P} \{\omega \in \Omega: \mc_{\mO}(\bu_n,\zeta)> \eta\}= 0,
       \end{equation}
and vice versa. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main-berry-esseen of arXiv:2507.12502, 'Quantitative Edge Eigenvector Universality for Random Regular Graphs: Berry-Esseen Bounds '] Let $G$ be a uniformly random $d$-regular graph on $N$ vertices with $d \geq 3$ fixed. For any deterministic unit vector $\mathbf{q} \in \mathbb{R}^N$ with $\mathbf{q} \perp \mathbf{e}$, there exists a constant $C_d$ depending only on $d$ such that
\[
\sup_{x \in \mathbb{R}} \left|\mathbb{P}\left(\sqrt{N}\langle \mathbf{q}, \mathbf{u}_2 \rangle \leq x\right) - \Phi(x)\right| \leq C_d N^{-1/6+\varepsilon}
\]
for any $\varepsilon > 0$, where $\Phi$ is the standard normal distribution function. The constant satisfies
\[
C_d \leq C \cdot d^3 \varepsilon^{-10}
\]
for an absolute constant $C$. The same bound holds for the smallest eigenvector $\mathbf{u}_N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition PROP:glim of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $g$ be a smooth, compactly supported function with $\textup{dist}(\supp g, x_0)>0$, where $x_0\in \mathbb{T}_{L}$. Then, we have
\begin{align}
\frac{ \mathbb{E}_{\nu^\perp_{Q, x_0}}  \Big[  e^{i\langle h^\perp, g_L \rangle }  e^{\bar {\mathcal{E}}(h^\perp, t^{+}) } e^{c_0(t^+)^2+b(h^\perp)t^+}, \, D_L, \, B_K     \Big]}{ \mathbb{E}_{\nu^\perp_{Q, x_0}}  \Big[ e^{\bar {\mathcal{E}}(h^\perp, t^{+}) } e^{c_0(t^+)^2+b(h^\perp)t^+}, \, D_L, \, B_K   \Big] }=e^{-\frac{1}{2}\|g\|^2_{L^2}}(1+o_L(1))

\end{align}

\noindent
as $L\to \infty $, uniformly in $x_0 \in \mathbb{T}_{L}$ and $\theta \in [0,2\pi]$, where $g_L(x)=L^{-1/2}g(L^{-1}x)$.

