	\begin{align}
		\mathcal C(\omega)
		=
		\overline{
		\bigcup_{\epsilon\in[0,\epsilon_0]}
		\mathcal A^\epsilon(\omega)
		}^{H\times P},
		\qquad \omega\in\Omega_0.
