[Defi See Definition $3.5$ in \cite{H.F1994} of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] Let $\mathscr{A}(\omega)$ and $B$ be random sets, for $P$-a.e.$~\omega \in \Omega$ if there exists $t_B(\omega)$ such that for all $t \geq  t_B(\omega)$,
	\begin{align*}
		\varphi(t,\theta_{-t}\omega)B \subset \mathscr{A}(\omega),
	\end{align*}
	then we say $\mathscr{A}(\omega)$ absorbs $B$.

[Lemma 38 (The variational representation.) of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Let $f$ be a bounded Borel measurable function mapping $\W$ into $\R$. Then
 \begin{equation*}
  - \log \E \, e^{-f (W)} = \inf_{v \in \mathcal{A}} \E \Big\{ \frac{1}{2} \int_{-\infty}^{+\infty} |v(s)|^2 \, \d s + f \big( W+ \int_{0}^{\cdot} v(s) \, \d s \big) \Big\},
 \end{equation*}
 where $\mathcal{A}$ is defined in \eqref{def: variational space}.

