body:
[Proposition prop_general of arXiv:2608.09105, 'Longest convex chains with i.i.d.\ points'] Let $\triangle$ be a nondegenerate triangle with two distinguished vertices $\mathsf{A},\mathsf{B}\in\mathbb{R}^2$.
Let $\wh\mathfrak{p}$ be a probability density on $\triangle$ such that
\eeq{ 
\frac{\inf_{(x,y)\in\triangle}\wh\mathfrak{p}(x,y)}{1/\mathrm{Area}(\triangle)} \geqslant r\in [0,1]
\qquad \text{and} \qquad
\frac{\sup_{(x,y)\in\triangle}\wh\mathfrak{p}(x,y)}{1/\mathrm{Area}(\triangle)} \leqslant R\in[1,\infty).
}
Let $\mathcal{S}_n$ 
be a set of $n$ independent samples from $\wh\mathfrak{p}$, and define
\eq{
\mathscr{L}_n \coloneqq \max\{\#\mathcal{C}:\, \mathcal{C}\subseteq\mathcal{S}_n \text{ and $\{\mathsf{A},\mathsf{B}\}\cup\mathcal{C}$ is in convex position}\}.
}
Then the following statements hold.
(If $r = 0$, then by convention $R/r = \infty$.)
\begin{enumerate}[label=\textup{(\alph*)}]

\item  \textup{(Comparison to uniform case)} 
Let $\alpha$ be the constant from Theorem~(thm_uniform_known of the paper). 
For every $\delta>0$, there exists $\mathfrak{n} = \mathfrak{n}(R/r,\delta)$ large enough that
\eeq{ 
(1-\delta)\Big(\frac{r}{R}\Big)^{1/3} \leqslant \frac{\mathbb{E}\mathscr{L}_n}{\alpha n^{1/3}} \leqslant (1+\delta)\Big(\frac{R}{r}\Big)^{1/3} \quad \text{for all $n\geqslant\mathfrak{n}$.}
}

\item  \textup{(Likelihood of a full convex chain)}
For every $n\geqslant1$, we have
\eeq{ 
r^n\frac{2^n}{n!(n+1)!} \leqslant \mathbb{P}(\{\mathsf{A},\mathsf{B}\}\cup\mathcal{S}_n \text{ is in convex position})
\leqslant R^n\frac{2^n}{n!(n+1)!}.
}

\item  \textup{(Deep tail event)}
For every $n\geqslant1$ and $t\geqslant0$, we have
\eeq{ 
\mathbb{P}\big(\mathscr{L}_n \geqslant (4R\e^3 n)^{1/3} + t\big) < 2^{-(4R\e^3 n)^{1/3}-t}.
}

\item  \textup{(Concentration)}
For every $t_0>0$ and $\beta\in(\tfrac16,\tfrac13]$, there exist $C=C(t_0,\beta)$ large enough and $\mathfrak{a} = \mathfrak{a}(R,t_0)>0$ small enough that every $n\geqslant1$, $t\geqslant t_0$, we have
\eeq{ 
\mathbb P\Bigl(\big|\mathscr{L}_n-\mathbb{E} \mathscr{L}_n\big| \geqslant tn^\beta\Bigr)
\leqslant
C \exp\bigl(-\mathfrak{a} tn^{2\beta-\frac13} \bigr).
}

\item  \textup{(Convergence after centering)}
For every $\gamma>\tfrac16$, we have
\eeq{ 
\frac{\mathscr{L}_n - \mathbb{E}\mathscr{L}_n}{n^\gamma} \xrightarrow[n\to\infty]{} 0 \quad \text{almost surely and in $L^p$ for every $p\in[1,\infty)$.}
}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l.Holder_coefficients of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Fix $\alpha \in (0,1)$ and let $\alpha' = \nicefrac{2\alpha}{3}$.  Suppose that $\left\langle v \right\rangle^m g \in C^{0,\alpha}_{\rm kin}$ for some $m\neq 3$.  Then, if $m > 2 + \nicefrac\alpha3$,
    \begin{equation}
        \Big[\left\langle v \right\rangle^{(3-m)_+ - 1 + \frac{\alpha}{3} }A[g]\Big]_{C^{0,\alpha'}_{\rm kin}}
        \lesssim [ \left\langle v \right\rangle^m g ] _{C^{0,\alpha}_{\rm kin}}.
    \end{equation}
    If $m> 1 + \nicefrac\alpha3$,
    \begin{equation}
        \Big[\left\langle v \right\rangle^{(3-m)_+ - 2 + \frac{\alpha}{3}} \nabla_v a[g]\Big]_{C^{0,\alpha}_{\rm kin}} \lesssim [ \left\langle v \right\rangle^m g ] _{C^{0,\alpha}_{\rm kin}}.
    \end{equation}

