[Lemma 17 (Giletti) of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] There is a positive supersolution $\bar u_1$ to \eqref{main_eq} for $t \geq T$ and $x < 2t - \frac{3}{2}\log t - Z_\delta(t) + Z_0(t)$.
        Moreover, $Z_0(t)$, defined below in \eqref{z_0_def}, satisfies for any $t \geq T$,
        \begin{equation}
            Z_0(t) > \frac{7}{2}\log t.
        \end{equation}
        In addition, for $x \leq 2t - \frac{3}{2}\log t - Z_\delta(t)$,
        \begin{equation}
            \bar u_1(t, x) = U_*\left(x-2t + \frac{3}{2}\log t\right) + \frac{\gamma}{t}
        \end{equation}
        while, for $x \geq 2t - \frac{3}{2}\log t - Z_\delta(t)$, 
        \begin{equation}
            \left|\bar u_1(t, x) - U_*\left(x - 2t + \frac{3}{2}\log t + Z_\delta(t) - Z_\delta^\infty\right)\right| \leq \left(\frac{3}{t}e^{-\left(x-2t+\sfrac{3}{2}\log t + Z_\delta(t)\right)}\right)^{1-\eta},
        \end{equation}
        with $\eta > 0$ arbitrarily small.
        Lastly, there exists $L_1 > 0$ such that
        \begin{equation}
            \bar u_1(T, x) \geq 1 \qquad \text{ for all } x \leq - L_1. 
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 6 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] We say that a function $f\in C_b(\mathcal{X})$ is $\mathcal{I}$-differentiable at $x\in \mathcal{X}$ if there exists $\ell_x\in E$ such that for every $v\in E$ it holds 
\begin{equation}
\lim_{s\to 0}\abs{\frac{f(x+s\mathcal{I}v)-f(x)}{s}-\langle \ell_x,v\rangle_E}=0.
\end{equation}
We set $\nabla_{\mathcal{I}}f(x):=\ell_x$. We say that a function is $\mathcal{I}$-differentiable if it is $\mathcal{I}$-differentiable at every $x\in \mathcal{X}$. 

Let $\vartheta\in [0,1)$. We denote by $C^{1+\vartheta}_{b,\mathcal{I}}(\mathcal{X})$ the subspace of $C_b(\mathcal{X})$ of $\mathcal{I}$-differentiable functions $f$ such that $\nabla_{\mathcal{I}}f\in C^{\vartheta}_b(\mathcal{X};E)$ if $\vartheta\in (0,1)$ or $\nabla_{\mathcal{I}}f\in C_b(\mathcal{X};E)$ if $\vartheta=0$.

[Lemma lem:Z of arXiv:2608.16915, 'Exact mean--covariance dynamics of the Weber field in the stochastic Lagrangian representa'] Let $B_t=\sqrt{2\nu}\,\beta_t$ for a standard one-dimensional Brownian motion $\beta$, let
$K>0$, $\lambda:=\nu K^2$, and set $Z_t:=\int_0^t e^{iKB_s}\,\mathrm{d} s$. Then
\begin{equation}
  \mathbb{E}\left\lvert Z_t\right\rvert^2=2\Bigl(\frac{t}{\lambda}-\frac{1-e^{-\lambda t}}{\lambda^2}\Bigr)
  \ \ge\ \frac{t}{\lambda}\quad\text{whenever }\lambda t\ge2 ,
\end{equation}
\begin{equation}
  \mathbb{E}\left\lvert Z_t\right\rvert^4\le\frac{12\,t^2}{\lambda^2},
\end{equation}
and consequently, by the Paley--Zygmund inequality applied to $\left\lvert Z_t\right\rvert^2$,
\begin{equation}
  \mathbb{P}\Bigl\{\left\lvert Z_t\right\rvert^2\ge\tfrac12\mathbb{E}\left\lvert Z_t\right\rvert^2\Bigr\}\ge\frac1{48},
  \qquad
  \mathbb{E}\left\lvert Z_t\right\rvert\ge c\,\sqrt{t/\lambda}\qquad(\lambda t\ge2)
\end{equation}
for a universal constant $c>0$.

