[Corollary 5 of arXiv:2607.24533, 'Colored Markov-Modulated Brownian Motion for Preemptive Workload Stacks'] {Suppose that the hypotheses of Lemma~\ref{lem:green} hold.} Then, for every $x>0$,
\begin{equation}

\begin{aligned}
\Lop{c}{\ell}(x)_{i\bullet}
={}&\sum_{j\in E}T^{(c,\ell)}_{ij}\,\bm e_{j}^{\top}
\Big\{
\big[g_{ij}^{(c,\ell)}(x;\vect V_\ell)-g_{ij}^{(c,\ell)}(x;\vect U_\ell)\big]e^{-\vect V_\ell x}
\\
&\hspace{4.4cm}
+h_{ij}^{(c,\ell)}(x;\vect U_\ell)
\big[e^{-\vect U_\ell x}-e^{-\vect V_\ell x}\big]
\Big\}\vect W_\ell,
\qquad i\in E.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 63 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $0\le T\le I_m$, and let $F$ be a $\mathbb C^{m\times m}$-valued function analytic in $\mathbb C_r$. The kernel
\[
  K_{T,1}(z,w)=\frac{F(z)+F(w)^*+T-F(z)TF(w)^*}{z+\overline{w}}
\]
is positive definite in $\mathbb C_r$ if and only if there exists a (non-uniquely determined in general) $\mathbb C^{m\times 2m}$ bounded function
$S=\begin{pmatrix} S_1&S_2\end{pmatrix}$ such that
\begin{equation}

      \begin{split}
        (F(z)+I_m)S_1(z)&=F(z)\sqrt{I_m+T}\\
        (F(z)+I_m)S_2(z)&=\sqrt{I_m-T}.
      \end{split}
    \end{equation}

