[Definition def:local_well_posed of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Given $\omega_0 \in L^0_{\mathcal{F}_0}(\Omega, H^{-1}_{\operatorname{div}})$, $\theta$ satisfying (hyp_noise of the paper), $p\in [2, +\infty)$, a stopping time $\tau:\Omega\rightarrow [0, +\infty]$ and a progressively measurable process $\omega_t: \Omega\times [0, \tau) \rightarrow H^{0}_g(\mathbb{T}^3)$.  We say that :
    \begin{itemize}
        \item[$\bullet$] $(\omega,\tau)$ is a \emph{Local p-Solution} of equation (equation main_ito of the paper) if the following are satisfied:
    \begin{itemize}
        \item[-] $\omega\in L^p((0, \tau); H^{0}_g) $ almost surely
        \item[-] $\mathcal{L}_u\omega \in L^p((0, \tau); H^{-2}_g) $ almost surely
        \item[-] almost surely, it holds for all $t\in [0,\tau)$ 
        \begin{equation*}
            \omega_t- \omega_0 + \int_0^t \left(\mathcal{L}_u  -A - \nu \Delta\right)\omega_s \mathrm{d}s + \sqrt{\nu}\sum_{k\in I} \int_0^t\mathcal{L}_{\sigma_k(s)}\omega_s \mathrm{d}W_s^k=0,
        \end{equation*}
        where the equality is intended as elements of $H^{-2}_g$.
    \end{itemize}
    \item[$\bullet$] A local p-solution $(\omega,\tau)$ to (equation main_ito of the paper) is a said to be a \emph{unique local p-solution} to (equation main_ito of the paper) if for any local solution $(\omega',\tau')$ we have $\omega=\omega'$ a.e. on $[0,\tau\wedge\tau')\times \Omega$.
    \item[$\bullet$] A unique local p-solution $(\omega,\tau)$ to (equation main_ito of the paper) is a said to be a \emph{unique maximal p-solution} to (equation main_ito of the paper) if for any local solution $(\omega',\tau')$ we have $\tau'\leq \tau$ almost surely and $\omega=\omega'$ a.e. on $[0,\tau\wedge\tau')\times \Omega$.
    \end{itemize}

[Lemma vbound of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $k \geq 2$ and a finite-support function $h:\mathbb{Z}\to\mathbb{R}$. Then, there exist $C = C(k,h),\varepsilon = \varepsilon(k,h) > 0$ such that, for all $\beta  \in (-\varepsilon, \varepsilon)$, $0\le s\le t$, $1 \leq i, j \leq k$, and $p\ge 1$, 
    \begin{equation}\sup_{\mathbf x\in\mathbb{Z}^k} \mathbf E_\mathbf x^{(\beta,k)} \bigg[ \bigg( \int_s^t |h(R_r^i -R_r^j )|\,{\rm d}r \bigg)^p\bigg]^{1/p} \leq C\sqrt p \left\lvertt-s\right\rvert^{1/2}\; \text{.}
    \end{equation}
    As a consequence, Taylor expanding the exponential yields, for every $a\ge 0$,
    \begin{equation}\sup_{t>0} \sup_{\mathbf x\in\Bbb Z^k} \mathbf E_\mathbf x^{(\beta,k)}\bigg[ \exp\bigg\{a t^{-1/2} \int_0^t |h(R_r^i -R_r^j )|\,{\rm d}r \bigg\}\bigg]<\infty\; \text{.}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{thm:random_walks}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, let $J : V \times V \to \mathbf{R}_+$ be transitive and suppose that $J(x,y) = \Theta (d_G(x,y)^{-d \alpha})$ with $\alpha \in (1,2)$. Let $\beta > \beta_{c}$.

    Then the infinite cluster $K_{\infty}$ is transient almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:FerreStoltz of arXiv:2603.00773, 'Long-time $L^p$ Wasserstein contraction for diffusion processes without global dissipativi'] Under Assumptions~(assum:Ferre of the paper) and~(Assum:PointwiseContractInfty of the paper), assume furthermore that $\eta$ is bounded\footnote{This assumption could be weakened to $\eta(x) \ll |x|^2$, cf. [FerreStoltz]} and $\mathcal C^\infty$ with all derivatives growing at most polynomially. Then:
\begin{enumerate}
\item For all $R_0>0$ and $p\geqslant 1$, there exists $C_{R_0}>0$ such that for all $t\geqslant 0$,
\begin{equation}
\sup_{x\in \mathcal B(0,R_0)} \left| \frac1t \ln G_p(x,t) - \mathcal J(p\eta)\right| \leqslant \frac{C_{R_0}}{t}\,,
\end{equation}
where, for $f\in L^\infty(\mathbb R^d)$, 
\begin{equation}

\mathcal J(f) = \sup_{\nu\in\mathcal P(\mathbb R^d)}\left\{\int_{\mathbb R^d} f \text{d} \nu - \mathcal I(\nu)\right\}\,,
\end{equation}
with the rate function 
\[\mathcal I(\nu) = \sup_{u\in \mathcal D_+(\mathcal L)}\left\{ -\int_{\mathbb R^d} \frac{\mathcal L u}{u} \text{d} \nu \right\}\,,\]
 where, denoting by $\mathcal D(\mathcal L)$ the extended domain of the generator $\mathcal L$ (cf. [FerreStoltz]) and $\mathcal C(\mathbb R^d)$ the space of continuous functions,
 \[\mathcal D_+(\mathcal L) = \left\{ u \in \mathcal D(\mathcal L) \cap \mathcal C(\mathbb R^d), \ u>0,\ \frac{\mathcal L u}{u} \in L^\infty(\mathbb R^d)\right\}\,.\]
\item For all $p\geqslant 1$, there exists $C>0$ such that for all $t\geqslant 0$,
\begin{equation}

  G_p^*(t)  \leqslant C e^{ t \max\left( -\rho, \mathcal J(p\eta)\right)}  \,.
\end{equation}
If, moreover, there exists $K>0$ such that $|b(x)|\leqslant K|x|+K$ for all $x\in\mathbb R^d$, then for all $p\geqslant 1$, there exists $c>0$ such that for all $t\geqslant 0$,
\begin{equation}

   G_p^*(t) \geqslant c  e^{ t \max\left( -\rho', \mathcal J(p\eta)\right)}\,,
\end{equation}
with $\rho' = -\liminf_{|x|\rightarrow \infty}\eta(x) \in[\rho,\infty]$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 13 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] Let $0\le p<(4a-1)/4a$. Then,
\begin{equation}
\frac{S_n}{\sqrt{n}}\xrightarrow{d}\mathcal{N}\Big(0,\frac{K}{(2a(1-p)-1)^2}\Big),
\end{equation}
where 
\begin{equation}
K=	\frac{(a(2p-1))^2}{4a(1-p)-1}+\frac{(1-2p)(a-1)}{1-p}+(a-1)^2.
\end{equation}

