[Corollary 32 of arXiv:2607.29495, 'Fast Mixing for Low-Temperature Potts Models via Poisson Trees'] Let $\ell$ be a positive integer and
consider $T\sim \cT$. Using the correspondence in Lemma~\ref{lem:gb}, $T\sim \cT^{\down}$. For every vertex $v\in V(T)$,  $T_{v,\ell}$ from Definition~\ref{def:inf-Tvl}
is a subtree of $T^{\down}_{v,\ell}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2606.20948, '\textsc{Slot decomposition of\\ continuous Box-Ball Systems}'] Let $\alpha \in \mathcal A$ and $q \in \mathscr Q$ satisfy
	\begin{align}

		\alpha(\ell)=q(\ell)\, e^{-2\int_0^\ell(\ell-y)q(y)dy},
	\end{align}
	as in \eqref{a=q}.
	Then, 

	\noindent (i) If $\xi\in\hcW$ has excursions and record interval lengths $(\vep_k, \su_k)_{k\in\ZZ}$, satisfying
	\begin{gather}
		(\vep_k)_{k\in\ZZ} \text{ are iid with law $\mu_\alpha$} \\
		(\su_k)_{k\in\ZZ} \text{ are iid Exponential$(Z(\alpha))$} \\
		(\vep_k)_{k\in\ZZ} \text{ and } (\su_k)_{k\in\ZZ}\text{ are independent.}
	\end{gather}
	Then the slot decomposition $\sN[\xi]$ is a Poisson$(q)$ process.

	\noindent (ii) If $\sN$ is a Poisson$(q)$ process, then $\xi[\sN]\in\hcW$ and the excursions and record intervals of $\xi[\sN]$ satisfy \eqref{e12}, \eqref{a12}, and \eqref{i12}.

