body:
[Theorem thm:convergence of arXiv:2607.18824, 'Non-Abelian multiplicative chaos on the circle'] Fix $\varrho$ as above and $\kappa<\min(-2\check h,-\check h-2\lambda_\rho^+)$, with $\lambda_\rho^+$ defined in (equation eq:lambda_rho of the paper).

    For each $\epsilon>0$, let $M_{\kappa,\rho}^\epsilon$ be the random $\mathcal{H}_V$-valued Borel measure on $\mathbb S^1$ defined by 
\begin{equation}
\mathrm d M^\epsilon_{\kappa,\rho}(e^{i\theta}):=\,(1-e^{-2\epsilon})^\frac{-\Omega_\rho}{\kappa+\check h}\varrho\left(H(e^{-\epsilon+i\theta})\right)\mathrm d\theta,\qquad\qquad\theta\in\mathbb R,
\end{equation}
with $H$ sampled from $\nu_\kappa$. Then, the family $(M^\epsilon_{\kappa,\rho})_{\epsilon>0}$ converges weakly in probability as $\epsilon\to0$ to some non-trivial $\mathcal{H}_V$-valued measure $M_{\kappa,\rho}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi def: nu^T_t of arXiv:2607.19658, 'Hitting time mixing for random $k$-cycles'] Let $\nu^T_t$ denote the distribution on $\mathfrak{S}_{[n]\setminus T}$  defined by the following sampling process. First, sample $M_t\in\{0,1,\ldots,n-|T|\}$ according to the distribution $\mathbf{P}[M_t=x]=\mathbf{P}(\Pois(\gamma_{n-|T|,t_T})=x)/\mathbf{P}(\Pois(\gamma_{n-|T|,t_T})\le n-|T|)$, then sample a uniformly random subset $S_t$ of size $M_t$ in $[n]\setminus T$. Finally,
\begin{enumerate}
\item When $k$ is odd, sample a uniformly random element of $\mathfrak{A}_{[n]\backslash S_t \cup T}$ and view it as an element of $\mathfrak{A}_n$ by fixing all of the elements in $S_t$ and $T$.
\item When $k$ is even, and $t$ is odd, sample a uniformly random element of $\mathfrak{A}_{[n]\backslash S_t\cup T}^c$ and view it as an element of $\mathfrak{A}_n^c$ by fixing all of the elements in $S_t$ and $T$.
\item When $k$ is even, and $t$ is even, sample a uniformly random element of $\mathfrak{A}_{[n]\backslash S_t\cup T}$ and view it as an element of $\mathfrak{A}_n$ by fixing all of the elements in $S_t$ and $T$.
\end{enumerate}

[Theorem 10 (Critical Noise Threshold for Demographic Survival) of arXiv:2608.28198, 'Performative Privacy: When Differential Privacy Maximizes Utility'] The condition $C_t(\gamma) \ge 1$ is guaranteed as soon as the mechanism's noise scale satisfies the explicit lower bound $\gamma \ge \gamma_c$. Given an $\ell_2$ clipping bound $R=\Omega(\sqrt{d})$, the critical threshold $\gamma_c$ is defined as:
\begin{equation}
    \gamma_c \triangleq
    {\Omega} \left(\frac{\sqrt{dN_{t-1}}}{N_{t-1}-1}
    \left(
    \frac{\Phi_{q,r}^{-1}
    +\sqrt{(\Phi_{q,r}^{-1})^2+2\tau}}
    {2\tau}
    \right)\right)
\end{equation}
where $\Phi_{q,r}^{-1} \triangleq \Phi^{-1}\left( \frac{q}{q+r} \right)$ is the probit function (the inverse of the standard normal cumulative distribution function) evaluated at the performative survival threshold. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: dimension bound of arXiv:2604.23890, 'The Cutoff Profile for Random Transpositions on Repeated Cards in the Full Range of Parame'] Let $\lambda\vdash n$, and $r:=n-\lambda_1$. Then, we have
\begin{enumerate}
\item $d_\lambda\le\binom{n}{r}\cdot d_{\lambda^*}\le\binom{n}{r}\cdot \sqrt{r!}\le n^r/\sqrt{r!}.$
\item When $r\le \log n$, we have 
$$d_\lambda=\binom{n}{r}\cdot d_{\lambda^*}\left(1-\frac{r}{n}+O(n^{-2+o(1)})\right).$$
\end{enumerate}

[Cor 10 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Suppose that $\left(x_0^{(n)}\right)_{n\in\n}$, $(b_n)_{n\in\n}$ and $(\sigma_n)_{n\in\n}$ satisfies Assumption A.
We define $V=\left(V_t\right)_{0 \le t \le T}$ as
\begin{align*}
V_t=x_0+\int_0^t b_\infty\left(X_{s-}^\infty\right)\rd s+ \int_0^t\sigma_{\infty}\left(X_{s-}^\infty\right)\rd Z_s,
\end{align*}
Then, $$\p\left(V_t=X_t^\infty,\textrm{ for each } t\in[0,T]\right)=1.$$

