[Cor coro:cont of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] The Laplace transforms $\varphi_1$ and $\varphi_2$ can be extended as meromorphic functions on $\{y \in {\mathbb C}, {\textnormal{Re}}(y) < y_{max} + \delta\} \backslash[y_{max}, y_{max} + \delta]$ and $\{x \in {\mathbb C}, {\textnormal{Re}}(x) < x_{max} + \delta\} \backslash[x_{max}, x_{max} + \delta]$ respectively via the formulae:
\begin{equation}

\varphi_1(y)=  \frac{ -\gamma_2(X^-(y),y) \varphi_2(X^-(y)) -\exp \big(a_0 X^-(y) + b_0 y \big)}{\gamma_1(X^-(y),y)}
\end{equation} 
\begin{equation}

\varphi_2(x)=  \frac{ -\gamma_1(x,Y^-(x)) \varphi_1(Y^-(x)) -\exp \big(a_0 x + b_0 Y^{-}(x) \big)}{\gamma_2(x, Y^{-}(x))}.
\end{equation}

[Theorem thm:boundary1 of arXiv:2601.05361, 'Noise sensitivity in last-passage percolation'] For every $p\in(0,1)$, $\lambda\in(0,1)$ and $u\in{\mathbb{Z}}^2$, we have for every $x\in u+{\mathbb{Z}}_{\ge0}^2$ that
\begin{enumerate}[label=(\roman*)]
    \item (stationarity) $\{T(\lambda;x,x+y):y\in{\mathbb{Z}}_{\ge0}^2\}\stackrel{d}{=}\{T(\lambda;u,u+y):y\in{\mathbb{Z}}_{\ge0}^2\}$;
    \item (distribution) $\omega^H_x(\lambda)\sim\textrm{Geom}(p_H(\lambda))$ and $\omega^V_x(\lambda)\sim\textrm{Geom}(p_V(\lambda))$;
    \item (independence) the collection $\{\omega^H_{x+i\mathbf{e}_1},\omega^V_{x+j\mathbf{e}_2}:i,j>0\}$ consists of mutually independent variables; the same holds for $\{\omega^H_{x-i\mathbf{e}_1},\omega^V_{x-j\mathbf{e}_2}:0\le i<x_1-u_1,0\le j<x_2-u_2\}$.
\end{enumerate}

[Lemma lem:change-metric-full of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] Let $h_1$ and $h_2$ be Hermitian metrics on $E$.  Suppose that
$h_2=Kh_1$ for some $K\in\mathrm{Herm}^+(E,h_1)$.  Then
\begin{equation}
 \partial^{h_2}-\partial^{h_1}=K^{-1}\partial^{h_1}K
\end{equation}
and
\begin{equation}
 \theta_{h_2}^{*}=K^{-1}\theta_{h_1}^{*}K.
\end{equation}

[Proposition 11 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] Let $(h_{\ell})_{\ell\in\N}$ the white noise truncation given in \eqref{eq: white noise trunc}.
	\begin{enumerate}[$(i)$]
		\item
		For each ${\ell}\in\N$, \(h_{\ell}\) is a centered continuous Gaussian field on $M$.
		\item 
		For all $\ell,m\in\N$ with $m>\ell$ and for all $x\in M$, $(h_m-h_{\ell})(x)$ is independent from $h_{\ell}(x)$. 

		\item For all $\ell,m\in\N$ with $m>\ell$, the correlation function of $h_m-h_{\ell}$ is non-negative, i.e. for all $x,y\in M$
		\begin{equation}\begin{aligned}
				\E\Big[(h_m-h_\ell)(x)\, (h_m-h_\ell)(y)\Big] \quad\ge0.
		\end{aligned}\end{equation}
		\item
		As \(\ell\to \infty\), the fields \(h_{\ell}\) converge to the field \(h\) on \(M\) in the sense that
		\begin{align*}
			\scalar{h_{\ell}}{\varphi}\to \scalar{h}{\varphi} \text{ in }L^2(\Omega) \quad \forall \varphi\in L^2(M).
		\end{align*}
		\item  for every bounded nonnegative test function $\varphi\colon M\to\R$,
		\begin{align}
			\mathbb{E}\!\left[\scalar{ h-h_{\ell}}{\varphi}^2\right]
			= O(\ell^{-1}),
		\end{align}
	\item For $\ell\in\N$ and $\gamma^2<\frac n8$
	\begin{align}
		\int \Big[e^{\gamma^2\bar G_\ell(x,y)}-1\Big]\, d\vol(y)\leq C\gamma^2\ell^{-1}.
	\end{align}
	where $\bar G_\ell$ is the correlation function of $h-h_\ell$.
	\end{enumerate}

