body:
[Theorem k1k2IIthm of arXiv:2608.04730, 'A new look at some aspects of one-dimensional random sequential adsorption and its continu'] Let $M^{(n)}_{k_1,k_2;II}$ denote the expected number of bonded molecules under Model II in (equation models of the paper),
and let $M^{(n)}_{k_1,k_2;II_1}$ denote the expected number of bonded molecules at the end of stage one, when there are no longer any unbonded $k_2$-tuples.
Then
\begin{equation}
\begin{aligned}
&m_{k_1,k_2;II_1}:=\lim_{n\to\infty}\frac{M^{(n)}_{k_1,k_2;II_1}}n=\\
&\frac12\int_0^1s^{\frac{k_2-k_1}2}\big(k_1+k_2+k_1(k_2-k_1)(1-s)\big)\exp\left(\sum_{j=1}^{k_1-1}\frac{s^j-1}j+\sum_{j=1}^{k_2-1}\frac{s^j-1}j\right) ds,
\end{aligned}
\end{equation}
and
\begin{equation}
m_{k_1,k_2;II}:=\lim_{n\to\infty}\frac{M^{(n)}_{k_1,k_2;II}}n=m_{k_1,k_2;II_1}+
\int_0^1B(s)\exp\left(\sum_{j=1}^{k_1-1}\frac{s^j-1}j+\sum_{j=1}^{k_2-1}\frac{s^j-1}j\right)ds,
\end{equation}
where
\begin{equation}
\begin{aligned}
&B(s)=(1-s)^2s^{-\frac12k_1-\frac12k_2}\left(\sum_{n=\max(k_2,2k_1)}^{k_2+k_1-1}\big(\sum_{j=k_1}^{n-k_1}M^{(j)}_{k_1}\big)s^n+\sum_{n=k_2+k_1}^{2k_2-1}\big(\sum_{j=k_1}^{n-k_2}M^{(j)}_{k_1}\big)s^n\right)+\\
&(1-s)\left(s^{\frac12k_2+\frac12k_1}+s^{\frac32k_2-\frac12k_1}\right)\left(\sum_{j=k_1}^{k_2-1}M^{(j)}_{k_1}\right),
\end{aligned}
    \end{equation}
and $M_{k_1}^{(j)}$ is the expected number of bonded molecules under $k_1$-bonding on a row of $j$ molecules. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition SN of arXiv:2505.11721, 'Variational principles for Hausdorff and packing dimensions of fractal percolation on self'] For $q \ge 0$ set 
\begin{align*}
S_{k}(q)&=\sum_{n=1}^k T_{W^{(n)}}(q)+\sum_{n=k+1}^{g_s} \tau^{D,n}_{r_n}(q)\quad (0\le k\le g_s),
\end{align*}
where $r_n$ is the index $r$ such that $g_{r-1}+1\le n\le g_{r}$.

