[Theorem 14 (Theorem 2.1 of \cite{nutz2021introduction}) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Suppose that $\mathcal{R} \sim \mu_0 \otimes \mu_1$ and that $D_{\textup{KL}}(\mu_{0} \otimes \mu_{1} || \mathcal{R}) < \infty$. Then the following hold.
	\begin{description}[leftmargin=0.6cm]
		\item[(i)] The static Schr\"{o}dinger bridge exists and is unique. Furthermore, there are $\balpha \in L^1(\mu_0)$ and $\bbeta \in L^1(\mu_1)$, unique up to transformations of the form $(\balpha, \bbeta) \mapsto (\balpha + \lambda, \bbeta - \lambda)$ for $\lambda \in \R$, such that
		\begin{align}
			\frac{d\pi^{\mu_0, \mu_1; \mathcal{R}}}{d\mathcal{R}} =  \exp(\balpha \oplus \bbeta) \quad \mathcal{R}  \text{-a.s.}
		\end{align}

		\item[(ii)] Conversely, if $\pi \in \Pi(\mu_0, \mu_1)$ admits a density 
		\begin{align}
			\frac{d\pi}{d\mathcal{R}} = \exp (\balpha \oplus \bbeta) \quad \mathcal{R} \text{-a.s.}
		\end{align}
		for some measurable functions $\balpha,\bbeta$, then $\pi$ is the Schr\"{o}dinger bridge. Moreover, $\balpha \in L^1(\mu_0)$ and $\bbeta \in L^1(\mu_1)$. 
	\end{description} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:pivest of arXiv:2410.23250, 'Strict inequalities for arm exponents in planar percolation'] Let $n\geq k \ge 1$ be such that $10k\le n$. Writing $f=\mathrm 1_{A_n(b)}$ and $g=\mathrm 1_{A_n(w)}$, we have 
\begin{equation}
  \forall t\in[t_k,2t_k]\quad
\sum_{x\in \mathbb H(\Lambda_{k,3k})} -\mathbb{E}[\nabla_xf(\omega)\nabla_xg(\omega_t) ]\gtrsim k^2\cdot \alpha_k\cdot\phi_n(t).
\end{equation}

