body:
[Lemma 18 (Fractional semigroup and central paracontrolled commutators) of arXiv:2608.29726, '\LARGE A Priori Estimates for Singular Fractional Stochastic Burgers Equations'] Let \(I=[t_0,T]\) and assume all functions considered are smooth.
\begin{enumerate}[label=(\roman*),leftmargin=*]
\item If \(0<a<1\) and \(b\in\R\), then
\[
\begin{aligned}
 \norm{\mathrm{Com}_{\Kcal_\gamma}(f,g)}
   _{C(I;\Ccal^{a+b+\gamma-1})}
 \lesssim
 \left(
  \norm f_{C(I;\Ccal^a)}
  +[f]_{C^{a/\gamma}(I;L^\infty)}
 \right)
 \norm g_{C(I;\Ccal^b)}.
\end{aligned}
\]
The same estimate holds with \(\Kcal_{\gamma,\lambda,t_0}\), uniformly in
\(\lambda\ge0\).

\item Let \(0<a<1\) and \(b,c\in\R\), with
\[
 b+c<0<a+b+c.
\]
Then the trilinear expression
\[
 \mathrm{Com}_{\mpara}(f,Q,g)
 :=(f\mpara Q)\odot g-f(Q\odot g),
\]
satisfies
\[
\begin{aligned}
 \norm{\mathrm{Com}_{\mpara}(f,Q,g)}
   _{C(I;\Ccal^{a+b+c})} \lesssim
 \left(
  \norm f_{C(I;\Ccal^a)}
  +[f]_{C^{a/\gamma}(I;L^\infty)}
 \right)
 \norm Q_{C(I;\Ccal^b)}
 \norm g_{C(I;\Ccal^c)}.
\end{aligned}
\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] \begin{multline}

    \frac{\GG_N(\alpha,u,v)}{\Gamma(\alpha+v)\Gamma(\alpha+u)(\Gamma(2\alpha))^{N-1}}
    \\=\,\int_{(0,\infty)^{N-1}}\,\Big(\prod_{j=1}^{N-1}\,\frac{z_j^{\alpha+u-1}}{(1+z_j)^{2\alpha}}\Big)\,\frac{\mathrm dz_1\ldots\mathrm dz_{N-1}}{(1+\sum_{j=1}^{N-1}\,\prod_{k=1}^j\,z_k)^{u+v}}.
    \end{multline}

