body:
[Proposition prop: asymptotic op val cumulants of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $r\geq1$, let $b_1,\ldots,b_n\in\mathcal C$ be cactus-type monomials, and let $\epsilon:[n]\to\{1,-1\}$. Then
    \begin{equation}
        \lim_{N\to\infty}\mathbb{E}\left[\frac{1}{N} \mathrm{Tr}\left(\kappa_n^{\mathcal{B}_N}\bigl(V_N^{\epsilon(1)}b_{1,N},\ldots,V_N^{\epsilon(n)}b_{n,N}\bigr)\right)\right]
    \end{equation}
    is zero unless all the following conditions hold:
    \begin{enumerate}
        \item $n=2m$ for some $m\geq1$ and the sequence $\epsilon(1),\ldots,\epsilon(2m)$ is alternating;
        \item every $b_i$ is balanced;
        \item the word associated with $V_N^{\epsilon(1)}b_{1,N}\cdots V_N^{\epsilon(2m)}b_{2m,N}$ represents the identity of $G$.
    \end{enumerate}
    If these three conditions hold, then 
    \begin{equation}
        \lim_{N\to\infty}\mathbb{E}\left[\frac{1}{N} \mathrm{Tr}\left(\kappa_r^{\mathcal{B}_N}\bigl(V_N^{\epsilon(1)}b_{1,N},\ldots,V_N^{\epsilon(n)}b_{n,N}\bigr)\right)\right]=(-1)^{m-1}C_{m-1}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:functional-nonlinear-lil of arXiv:2606.21006, 'Law of the Iterated Logarithm for Weighted Sums of Functionals of Long-Memory Gaussian Seq'] Let \(m\ge2\). Assume \(((A1 of the paper))\)--\(((A6 of the paper))\), \(\alpha m<1\), and
\(2d+\alpha m<1\). Then, for every fixed \(T>0\), the sequence
\[
    \left\{
        \frac{\mathcal S_n(\cdot)}
        {A_n(2\log\log n)^{m/2}}
        : n\ge3
    \right\}
\]
is almost surely relatively compact in \(C[0,T]\), and
\[
    \operatorname{Cl}_{C[0,T]}
    \left(
        \frac{\mathcal S_n(\cdot)}
        {A_n(2\log\log n)^{m/2}}
    \right)
    =
    \mathcal K_T
    \qquad\text{\rm a.s.}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] If Condition B1 is valid, then, for any $z\in
(-t,\infty )$
\begin{equation*}
\lim_{n\gg k\sim \theta m\rightarrow \infty }\mathbf{P}\left(
S_{r}-S_{n}\leq za_{k}|\mathcal{B}(ta_{k},n)\right) =A_{2}(t,\theta ,z),
\end{equation*}
where
\begin{equation*}
A_{2}(t,\theta ,z)=\frac{\alpha \rho +1}{t^{\alpha \rho +1}}
\int_{0}^{t+z}v^{\alpha \rho }\mathbf{P}\left( -v\theta ^{1/\alpha }\leq
\min_{0\leq s\leq 1}Y_{s},-z\theta ^{1/\alpha }\leq Y_{1}\leq \left(
t-v\right) \theta ^{1/\alpha }\right) dv.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Assume the same setup as in Proposition~\ref{prop::multiannulu_pf_construction}. The law of $n$-annulus $\SLE_{\kappa}(\LFcro{n}^{(\kappa;\ell)})$ in $(\A_r; \ee^{\ii\bs{\alpha}}, \ee^{\ii\bs{\beta}-r})$ is the same as $\Pind{n}^{(\kappa;\ell)}$ weighted by the Radon-Nikodym derivative 
\begin{align}
\frac{\prod_{j=1}^n\LFcro{1}^{(\kappa;\ell)}(r; \alpha_j, \beta_j)}{\LFcro{n}^{(\kappa;\ell)}(r; \bs{\alpha}, \bs{\beta})}\one_{\LE_{\emptyset}(\bs{\gamma})}\exp\left(\frac{\mathfrak{c}}{2}\blm(\A_r; \gamma^1, \ldots, \gamma^n)\right), 
\end{align}
where $\LE_{\emptyset}(\bs{\gamma}) = \{ \gamma^{j} \cap \gamma^{i}=\emptyset, \, \forall i\neq j\}$ is the event that different curves are disjoint, and $\blm$ is the Brownian loop measure defined in~\eqref{eqn::blm_def}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:energy-admissible-vector-law of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] The dyadic vector-weight law is called \emph{energy-admissible} if
\begin{equation}
\mathbb{E} X_0=\mathbb{E} X_1=\frac12,
\end{equation}
\begin{equation}
\mathbb{E}\bigl[X_0\log_2^+X_0+X_1\log_2^+X_1\bigr]<\infty,
\end{equation}
and
\begin{equation}
\mathbb{E}\bigl[X_0\log_2 X_0+X_1\log_2 X_1\bigr]<0,
\end{equation}
where \(0\log_2 0=0\).

