[Theorem eq:truncated_kernel of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{thm:truncation_problem}
    Let $G$ be a transitive graph of polynomial growth with dimension $d \geq 2$ and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega (d_G(x,y)^{-d \alpha})$ with $\alpha \in (1,2)$. 

    Let $\beta > \beta_c(J)$. 

    Then there exists $N=N(\beta) \in \mathbf{N}$ such that the truncated kernel 

    \begin{equation}

        \widetilde{J} 
        = 
        J(x,y) 
        \mathbf{1}(
            d_G(x,y) \leq N
        )
    \end{equation}

    satisfies $ \beta_c(\widetilde{J})<\beta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition PROP:OUproj of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Define the field
\begin{align}
h&:=\mathbf{P}_{V^{L^2}_{x_0,0}} B^{-\frac{1}{2}}w_0 \notag \\
&=\mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-\frac{1}{2}}\Re w_0+i\mathbf{P}_{V^{L^2}_{x_0,0}} B_2^{-\frac{1}{2}} \Im w_0

\end{align}

\noindent 
lies in $H^{\frac{1}{2}-\epsilon}(\mathbb{T}_{L^2})$ for each $\epsilon>0$. Moreover, the $h$ is a Gaussian process with covariance operator
\begin{equation}
\left(\begin{array}{cc}
C_1& \\
& C_2
\end{array}\right)=\mathbf{P}_{V^{L^2}_{x_0,0}}\left(\begin{array}{cc}
B_1^{-1}& \\
& B_2^{-1}
\end{array}\right)\mathbf{P}_{V^{L^2}_{x_0,0}}
\end{equation}
on $L^2(\mathbb{T}_{L^2})=\Re L^2(\mathbb{T}_{L^2})\oplus i\Im L^2(\mathbb{T}_{L^2})$.
\begin{proof}
For $f, g\in L^2(\mathbb{T}_{L^2};\mathbb{R})$, we have
\begin{align*}
\mathbb{E}[\langle \Re h, f \rangle \langle \Re h, g\rangle]&=\sum_{n} \langle \mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-\frac{1}{2}} u_n,f\rangle\langle \mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-\frac{1}{2}} u_n,g\rangle\\
&=\langle B_1^{-\frac{1}{2}} \mathbf{P}_{V^{L^2}_{x_0,0}} f, B_1^{-\frac{1}{2}}\mathbf{P}_{V^{L^2}_{x_0,0}} g\rangle\\
&=\langle f, \mathbf{P}_{V^{L^2}_{x_0,0}} B_1^{-1}\mathbf{P}_{V^{L^2}_{x_0,0}} g\rangle\\
&=\langle f,C_1 g\rangle.
\end{align*}
Similar computations show
\begin{align*}
\mathbb{E}[\langle \Im h, f \rangle \langle \Im h, g\rangle]&=\langle f, C_2 g\rangle,\\
\mathbb{E}[\langle \Im h, f \rangle \langle \Re h, g\rangle]&=0.
\end{align*}
This proves the claim regarding the covariance.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 (Positive-kernel principle) of arXiv:2607.04467, 'Bernstein Functions at Work:\\ Coalescents, Copulas, and Subordination'] Let $d\mu(t)\ge0$ and suppose
\begin{equation}
f(x)=\int_0^\infty e^{-xt}\,d\mu(t)
\end{equation}
converges on $(0,\infty)$. Then $f\in\CM$. If \(\mu\ne0\) and
\(\mu((0,\infty))>0\), then \(f\) is strictly completely monotone.

