[Definition 12 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Let $(X,d)$ be a metric space with $d$ allowed to take on infinite values.
    \begin{itemize}
        \item A \textbf{path} in $(X,d)$ is a continuous function $P : [a,b] \rightarrow X$ for some interval $[a,b]$.
        \item For a curve $P : [a,b] \rightarrow X$, the $d$-\textbf{length} of $P$ is defined by 
        \begin{equation*}
            \text{len}(P ; d):=\sup_T \sum_{i=1}^{|T|}d(P(t_i),P(t_{i-1}))
        \end{equation*}
        where the supremum is over all partitions $T : a=t_0 <t_1<\cdots<t_{|T|} = b$ of $[a,b]$. Note that the $d$-length of a curve can be infinite.
        \item We say that $(X,d)$ is a \textbf{length space} if for all $x,y \in X, \varepsilon>0$, there exists a path in $X$ with $d$-length at most $d(x,y)+\varepsilon$ from $x$ to $y$. If $d(x,y) < \infty$, a curve in $X$ from $x$ to $y$ with $d$-length exactly $d(x,y)$ is called a \textbf{geodesic}. We say that $(X,d)$ is a \textbf{geodesic space} if for all $x,y \in X$, we have that $d(x,y) < \infty$ and there exists a geodesic in $X$ from $x$ to $y$.
        \item For $Y \subseteq X$, the \textbf{internal metric} of $d$ on $Y$ is defined by 
        \begin{equation*}
            d(x,y ; Y):=\inf_{P \subseteq Y} \text{len}(P ; d), \quad \text{for all} \quad x,y \in Y
        \end{equation*}
        where the infimum is over all paths $P$ in $Y$ from $x$ to $y$. We note that $d(\cdot,\cdot;Y)$ is a metric on $Y$.
        \item If $X \subseteq \CC$, we say that $d$ is a \textbf{lower semicontinuous metric} if the function $(x,y) \rightarrow d(x,y)$ is lower semicontinuous with respect to the Euclidean topology. We equip the set of lower semicontinuous metrics on $X$ with the topology of lower semicontinuous functions on $X \times X$ induced by the convergence in Definition~\ref{def:lower_semi_cont}.
    \end{itemize}

