[Lemma PropertiesMuDisc of arXiv:2609.02325, 'A Payne-Weinberger inequality\\for quantum dot Dirac operators'] Given $a>0$, let $\mu_\mathbb{D}(a)$ denote the first eigenvalue of the $\overline{\partial}$-Robin Laplacian $\mathcal{R}_{a}$~in the unit disk and, given $\theta\in(-\frac \pi 2, \frac \pi 2)$ and $m\geqslant 0$, let $\lambda_\mathbb{D}$ denote the first positive eigenvalue of the quantum dot Dirac operator $\mathcal{D}_{\theta, m}$ in the unit disk; that is, $\lambda_\mathbb{D} := \lambda_\mathbb{D}(\theta,m)$.~Then, 
	\begin{enumerate}[label=$(\roman*)$]
		\item the function $a\mapsto \mu_\mathbb{D}(a)$ is real analytic and concave in $(0,+\infty)$;

		\item it holds that
		\begin{equation} 
			\mu_\mathbb{D} \big( \vartheta(\theta) (\lambda_\mathbb{D}+m) \big) = \lambda_\mathbb{D}^2-m^2\text{;}
		\end{equation}
		\item the derivative of $a\mapsto \mu_\mathbb{D}(a)$  satisfies
		\begin{equation}
			a\frac{d}{da}\mu_\mathbb{D}(a) \leqslant \mu_\mathbb{D}(a) \quad \text{ for all } a>0
		\end{equation}
		and
		 \begin{equation}
			\frac{d}{da}\mu_{\mathbb{D}}(a)\Big|_{a=\vartheta(\theta)(\lambda_\mathbb{D}+m)} = \dfrac{2}{1+ \frac{\lambda_\mathbb{D}+m}{\lambda_\mathbb{D}-m}\vartheta(\theta)^2 }.
		\end{equation}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] The random measure $M^{\mathsf{S}; \mathcal{A}}$ in \eqref{Eq.RMS1} is a determinantal point process with reference measure $\mu_{\mathsf{S}} \times \mathrm{Leb}$ as in Definition \ref{Def.Measures}, and with correlation kernel given by 
    \begin{equation}

        \widetilde{K}(t_1, x_1; t_2, x_2) = \frac{1}{(2\pi\im)^2} \int_{\eta + t_1 + \im \mathbb{R}} \diff z \int_{-\eta' + t_2 + \im \mathbb{R} } \diff w \frac{e^{z^3/3 - z^2 t_1 + z(t_1^2 - x_1) - w^3/3 + w^2 t_2 - w(t_2^2 - x_2)}}{z - w}.
    \end{equation}
    In (\ref{Eq.ExtendedAiryKernel}), $\eta,\eta'>0$ are arbitrary, subject to the condition that $\eta+\eta'+t_1-t_2<0$ whenever $t_2>t_1$, and both contours are oriented in the direction of increasing imaginary part.

