[Proposition fig:wk-em-dual-countermodel of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] $\textbf{WK} + \varphi \lor \neg \varphi \subsetneq \textbf{K}$. Consequently, $\textbf{CK} + \varphi \lor \neg \varphi \subsetneq \textbf{K}$.
  \begin{proof}
    It suffices to prove it for $\textbf{WK}$.
    ($\subseteq$) Trivial from the axiomatizations.
    ($\neq$) It suffices to construct an infallible CK-model in which $\varphi \lor \neg \varphi$ is valid for every $\varphi \in \mathscr{L}_{\Box\Diamond}$ but $\neg \Box \neg p \to \Diamond p$ is not.
    We let $\mathfrak{M} = (W, \leq, \sqsubset, V)$, where:
    \begin{itemize}
      \item $W \coloneq \set{ x_i, y_i; i \in \mathbb{N} }$;
      \item $\leq$ is the reflexive and transitive closure of $\set*{ (x_i, x_{i+1}), (y_i, y_{i+1}); i \in \mathbb{N} }$;
      \item $\mathord{\sqsubset} \coloneq \set*{ (x_{2i}, y_{2i}), (y_{2i}, x_{2i}), (x_{2i+1}, x_{2i+1}), (y_{2i+1}, y_{2i+1}); i \in \mathbb{N} }$;
      \item $V(p) \coloneq \set{ y_i; i \in \mathbb{N} }$.
    \end{itemize}
    The model is due to Simpson [simpson_proof_1994] and is visualized in Figure (fig:wk-em-dual-countermodel of the paper).
    \begin{figure}[ht]
      \centering
      \begin{tikzpicture}
      \fill (0,2) circle (2pt);
      \draw (0,2) node[left]{$x_0$};

      \fill (2,2) circle (2pt);
      \draw (2,2) node[right]{$y_0 \Vdash p$};

      \draw [thick, <->, squig, rel] (0,2) to (2,2);
      \draw (1,2) node[above]{\tiny $\sqsubset$};

      \draw (0,3) circle (2pt);
      \draw (0,3) node[left]{$x_1$};
      \draw [thick, ->, rel] (0,2) to (0,3);
      \draw (0,2.5) node[left]{\tiny $\leq$};

      \draw (2,3) circle (2pt);
      \draw (2,3) node[right]{$y_1 \Vdash p$};
      \draw [thick, ->, rel] (2,2) to (2,3);
      \draw (2,2.5) node[right]{\tiny $\leq$};

      \fill (0,4) circle (2pt);
      \draw (0,4) node[left]{$x_2$};
      \draw [thick, ->, rel] (0,3) to (0,4);
      \draw (0,3.5) node[left]{\tiny $\leq$};

      \fill (2,4) circle (2pt);
      \draw (2,4) node[right]{$y_2 \Vdash p$};
      \draw [thick, ->, rel] (2,3) to (2,4);
      \draw (2,3.5) node[right]{\tiny $\leq$};

      \draw [thick, <->, squig, rel] (0,4) to (2,4);
      \draw (1,4) node[above]{\tiny $\sqsubset$};

      \draw (0,5) circle (2pt);
      \draw (0,5) node[left]{$x_3$};
      \draw [thick, ->, rel] (0,4) to (0,5);
      \draw (0,4.5) node[left]{\tiny $\leq$};

      \draw [thick, dashed, rel] (0,5) to (0,6);

      \draw (2,5) circle (2pt);
      \draw (2,5) node[right]{$y_3 \Vdash p$};
      \draw [thick, ->, rel] (2,4) to (2,5);
      \draw (2,4.5) node[right]{\tiny $\leq$};

      \draw [thick, dashed, rel] (2,5) to (2,6);

      \end{tikzpicture}
      \caption{The model $\mathfrak{M}$. $\circ$ denotes a $\sqsubset$-reflexive world.}

    \end{figure}

    Here, $\mathfrak{M}$ is clearly an infallible CK-model.
    Also, it is easy to see that $x_0 \Vdash^{\text{c}}_\mathfrak{M} \neg \Box \neg p$ but $x_0 \not\Vdash^{\text{c}}_\mathfrak{M} \Diamond p$ since there is no $y$ such that $x_0 \leq x_1 \sqsubset y \Vdash^{\text{c}}_\mathfrak{M} p$.
    Now it suffices to show that $w \Vdash^{\text{c}}_\mathfrak{M} \varphi \lor \neg \varphi$ for any $w \in W$ and $\varphi \in \mathscr{L}_{\Box\Diamond}$,
    which is proven by an easy induction on the construction of $\varphi$.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm intro-thm-2 of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] Assume that $N=10$ and $0\le f\le f_H$ in $B_1$ in addition to the hypotheses of Proposition (intro-prop-1 of the paper).
Then, the grow-up rate of the solution to (equation eq-intro-1 of the paper) is characterized as follows:
\begin{align*}
\text{(i) }\lVert u\rVert_{L^{\infty}(B_1)}&=\frac{\mu_1}{2} t +\frac{1}{2}\left(1+\frac{1}{\mu_1 b}\right)\log t+O(1)\text{ as $t\to\infty$ if $f\not \equiv f_{H}$ in $B_{1}$;}\\
\text{(ii) }
\lVert u\rVert_{L^{\infty}(B_1)}&=(\frac{t}{2b})^{1/2}+O(\log t) \hspace{2mm} \text{ as $t\to\infty$ if $f\equiv f_H$ in $B_{1}$,}
\end{align*}
where $\mu_1$ is that in Theorem (intro-thm-1 of the paper) and $b>0$ is a constant depending only on $f$ and defined in (equation defb of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop_PartialCovariantDerivatives_Chiral of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] ~
  \begin{enumerate}
  \item

    The restriction of the slice partial covariant derivatives $\nabla^\mathbf{Sl}$ to $H_\mathrm{BG}^\mathbf{Sl}$ and $V_\nabla$ preserves the splittings (Eq_ChiralDecomposition of the paper).
  \item

    In the situation of (Def_PartialConnectionAlongSpaceOfRamifiedLineBundles of the paper),
    the partial covariant derivatives $\nabla^\mathbf{Ram}$ preserve the splittings
    (Eq_ChiralDecomposition of the paper);
    moreover,
    for every $({\mathbf{p}},[{\mathfrak l}];\phi) \in \mathbf{E}^\pm|_\mathscr{U}$ and $v \in T_{[{\mathfrak l}]}\mathbf{Ram}$
    \begin{equation*}
      \nabla_v^\mathbf{Ram}{\mathbf{D}}^\pm({\mathbf{p}},[{\mathfrak l}];\phi)
      =
      [\mathscr{L}_{\bar v}^K,D_{\mathbf{p}}^{\mathfrak l}]\phi.
    \end{equation*}
  \end{enumerate}

[Theorem 19 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Assume $\mathbbm{E}\!\left[h(X_1)^{\top}h(X_1)\right]<\infty$.
Under \eqref{eq:lambda-scaling},

\begin{equation}
\frac{W_h(k_{1:d})-A_h\,N(k_{1:d})}{\sqrt{|k|_1}}
\xrightarrow[k_{1:d}\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}_s\!\left(0,\mu_\lambda\,\Sigma_h\right),
\end{equation}

where $A_h$ and $\Sigma_h$ are given by \eqref{eq:Ah-Bh}.

[Lemma 12 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Approximate Entropy Conservation (Proposition 39, \cite{chen:eldan2022})}


    Let $\nu_t$ be a stochastic localization process as in Definition \ref{def:stoclocproc} with driving matrix $C_t$. Fix $T > 0$ and suppose that for all $t \in [0,T]$ the $\nu_t$ are $\epsilon_t$-entropically stable \wrt{} $\psi(x,y) := \frac 1 2 \twonorm{C_t(x-y)}^2$. Then, $\nu_t$ fulfills the following approximate entropy conservation
    \begin{align*}
        \ent[\nu]{f}
        \leq \exp\Parent{\int_0^T \epsilon_t dt} \cdot \E[\ent[\nu_T]{f}], 
        \quad \text{for all $f : \R^n \to [0,\infty)$}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 34 (Asymptotic) of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] For $\bs{\theta}=(\theta_1, \ldots, \theta_n)\in\LX_n$, define 
\begin{align}
\LZ_n(\bs{\theta})=\prod_{1\le i<j\le n}\left|\ee^{\ii\theta_i}-\ee^{\ii\theta_j}\right|^{\frac{1}{2}(-1)^{j-i}}, \qquad
\LZradial{n}(\bs{\theta})=\prod_{1\le i<j\le n}\left|\ee^{\ii\theta_i}-\ee^{\ii\theta_j}\right|^{\frac{1}{2}}. 
\end{align}
Assume the same setup as in Theorem~\ref{thm::crossingproba}. The crossing probabilities have the following asymptotic as $r\to\infty$: 
\begin{align}
&\PP[\cross(\bs{\gamma}), \wind(\bs{\gamma})=(m;\ell)]=\sqrt{2}^{n^2}\frac{\LZradial{n}(\bs{\alpha})\LZradial{n}(\bs{\beta})}{\LZ_n(\bs{\alpha})\LZ_n(\bs{\beta})}\exp\left(-\frac{n^2r}{8}-\frac{1}{8r}\LA(\bs{\alpha}, \bs{\beta}; m; \ell)+O(1)\ee^{-r} \right);\\
&\PP[\cross(\bs{\gamma})]=\sqrt{2}^{n^2}\frac{\LZradial{n}(\bs{\alpha})\LZradial{n}(\bs{\beta})}{\sqrt{2\pi}\LZ_n(\bs{\alpha})\LZ_n(\bs{\beta})}\exp\left(-\frac{n^2r}{8}+\frac{\log r}{2}+\frac{1}{8r}\left(\sum_{j=1}^n(-1)^j(\alpha_j-\beta_j)\right)^2+O(1)\ee^{-r/n^2}\right);
\end{align}
where 
\begin{align*}
\LA(\bs{\alpha}, \bs{\beta}; m; \ell)=\left(\sum_{j=1}^{n}(\alpha_j-\beta_{j})-2m\pi-2n\pi\ell\right)^2-\left(\sum_{j=1}^{n}(-1)^j(\alpha_j-\beta_j)\right)^2. 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

