[Theorem thm:main of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For  any  $0<\kappa < \frac{d-2}{2}$, let $\{u_t(\mathrm{d} x):t\geq 0\}$ be {a} solution to (equation eq:microshe of the paper) as defined in [mueller2004singular]. For $t=t_R>0$, the time-dependent spatial averages $u_{t_R}(B_R)$ have the following limits:
    \begin{enumerate}[leftmargin=*]
        \item  When $t_R = o (R^2)$, there exists a Gaussian random variable $\mathcal{N}(0,\sigma^2)$, with  variance  \begin{equation}
        \sigma^2 = \kappa^2\int_{B_1}\int_{B_1} \frac{1}{\|x-y\|^2}\mathrm{d} x \mathrm{d} y = { \frac{\kappa^2 2^{\,d-1}\,\pi^{\,d-\frac12}\,\Gamma\!\left(\frac{d-1}{2}\right)}
{(d-2)\,\Gamma\!\left(\frac d2\right)\,\Gamma(d)}},
        \end{equation}  such that \begin{equation}
\frac{1}{\sqrt{t_R}R^{d-1}} [u_{t_R}(B_R) -\omega_d R^d]\to \mathcal{N}(0,\sigma^2) \quad \text{in law},
    \end{equation}
    as $R \to \infty$. 
    \medskip
    \item  When $t_R= cR^2$ for some $c>0$, we have \begin{equation}
\frac{1}{R^d} u_{t_R}(B_R) =u_c(B_1)  \quad \text{in law},
     \end{equation}
    for any $R>0$. Here $u_c(B_1)$ is a  non-degenerate random variable and is positive almost surely. 
        \medskip

\item  When $ t_R^{-1} = o(R^{-2})$, we have
\begin{equation}
\frac{1}{R^d} u_{t_R}(B_R) \to 0  \quad \text{in probability},
    \end{equation}
    as $R\to \infty$. 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:pr_convergence of arXiv:2606.23547, 'The location of the largest exponential spacing and Euler’s generalized pentagonal numbers'] For each fixed $r\ge1$,
\begin{equation}
p_{r,n}\to p_r
\qquad \text{as } n\to\infty.
\end{equation}
Moreover, $p_r>0$ for every $r\geq 1$, and
\begin{equation}
\sum_{r=1}^\infty p_r = 1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 26 of arXiv:2609.01574, 'A linear bound for Fujita's freeness conjecture'] Let $(R,\m)$ be a $d$-dimensional Cohen--Macaulay local ring with infinite residue field, where $d\geq1$, and let $c:=\edim R-d$. Suppose that $e_1(\m)\leq a e_0(\m)$ for some $a\geq0$. If $c=0$, then $e_0(\m)=1$. Suppose that $c>0$. Then $a\geq\frac{c}{c+1}$. Let $s:=\left\lfloor\frac{(c+1)a}{c}\right\rfloor$. Then
\begin{equation}
 e_0(\m)\leq
 \left\lfloor
 \frac{1}{s+1-a}\binom{c+s+1}{c+1}
 \right\rfloor.
\end{equation}

[Thm eq:diff-eqnST0 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let  ${\kappa}_1,\ldots, {\kappa}_{d_2-1} > -1$. For $(\bm x,\bm y) \in {\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}$, 
let ${\mathfrak D}_{-1,{\boldsymbol{\kappa}}}^{0}$ be the differential operator defined by 
\begin{align}
  {\mathfrak D}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle} : = &  
    \sum_{i=1}^{d_2} \left( y_i \partial_{y_i}^2 + (\kappa_i +1) \partial_{y_i} \right) - {\langle} \bm y, \nabla_{\bm y} {\rangle}^2 \\
         & - (|{\boldsymbol{\kappa}}| +d_1+d_2-1) {\langle} \bm y, \nabla_{\bm y} {\rangle} 
           + \frac{1}{1-|\bm y|} \Delta_0^{(\bm x)}, \notag
\end{align}
where $\Delta_{{\mathbb S} \rtimes \triangle}^{(\bm x)}$ is the Laplace-Beltrami operator on the unit sphere in $\bm x$ variable. 
Then $u \in {\mathcal V}_n\big({\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}, {\mathsf W}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}\big)$ satisfies the 
differential equation 
\begin{align}
             {\mathfrak D}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle} u = - n \big( n+ | {\boldsymbol{\kappa}}| + d_1 +d_2 -2 \big)u.
\end{align}

[Theorem 14 (Statistical guarantees for the exact GP posterior) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under \cref{ass:gp-true,ass:gp-eigenvalues}, the exact GP posterior satisfies
    \begin{equation}
    \E\sbr{\W^2(\Pi_t,\delta_{f^\star})}
    \lesssim t^{-2\fs/(d+2\fs)}
    \end{equation}
and 
    \begin{equation}
    \fR\del[1]{(\Pi_t)_{t=0}^{T-1}}
    \lesssim T^{d/(d+2\fs)}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

