[Theorem thm-MMr of arXiv:2505.00198, '\ttl'] Assume that $\lambda>0$, $\mu>0$, and $\kappa >0$.  
The stationary distribution $\pi$ for the {\rm{M/M/}}$r$ queue with random resetting is given by the following: 
for $k=0,1,\dots, r-1$, 
\begin{align} 
\pi_{k} = \frac{ \theta^k }{k!} \left(  A_{k} -  L_{r-1,r}  C_{k} \right), 

\end{align}
and  for $k\geq r$,
\begin{align} 
\pi_{k} &= \alpha^{k-r+1} \pi_{r-1} \nonumber  \\
&= \frac{\alpha^{ k-r +1}  \theta^{r-1} }{(r-1)!} \left(  A_{r-1} -  L_{r-1,r} C_{r-1} \right).

\end{align}
Here, $\theta = \lambda/\mu$, $\gamma = \kappa/\mu$,
\begin{equation}  
\alpha = \frac{ r + \theta + \gamma - \sqrt{ (r + \theta + \gamma)^2  - 4\theta r } }{2r},
\end{equation}
\begin{equation}  
A_{n} = \int_{0}^{1} \gamma (1-s)^{\gamma -1} s^n e^{-\theta s} \, ds,  \qquad \text{for $n=0,1,\dots$} ,
\end{equation}
\begin{equation} 
C_{k} = \sum_{l=0}^{k} \binom{k}{l} \gamma (\gamma +1) \cdots (\gamma + l-1) \theta^{-l}, \qquad \text{for $k=0,1,\dots$},
\end{equation}
and
\begin{align}  
L_{r-1,r} 

& :=  \frac{  \theta A_{r} - r \alpha A_{r-1} }{ \theta C_{r} - r \alpha C_{r-1} }\,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma poisson_pdf_last_arrival of arXiv:2605.06511, 'Logarithmic Mixing of Random Walks on Dynamical Random Cluster Models'] Let $\mathsf{C}$ be a Poisson clock of rate $\mu > 0$. Let $T > 0$ and let $\tau$ be the last time $\mathsf{C}$ rings on $(0, T)$, conditioned on the event $\mathsf{C}(0, T)$. Then $\tau$ has cumulative distribution function
		\begin{eqnarray*}
			\mathcal{F}_{\tau \vert \mathsf{C}(0, T)} (x) = \mathbb{P}\left[\tau \leq x \mid \mathsf{C}(0, T)\right] = \frac{e^{\mu x} - 1}{e^{\mu T} - 1},& &0 < x < T
		\end{eqnarray*}
		and probability density function $f_{\tau \vert \mathsf{C}(0, T)} (x) = \frac{\mu e^{\mu x}}{e^{\mu T} - 1}$, $0 < x < T$.

[Theorem thm1-intro of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $d\geq 2$ and assume \textnormal{(H1)--(H3)}. 
For each $z\in \mathbb{R}^d$, the McKean--Vlasov SDE
\begin{equation}
\left\{
\begin{aligned}
    \,\mathrm d X_t &= b\bigl( X_t,u(t) \bigr) \,\mathrm d t + \sqrt{2a \bigl( X_t,u(t) \bigr)} \,\mathrm d W_t,
    \\ \mathcal{L}(X_t) &= u(t,x) \,\mathrm d x,\ \forall t>0,\quad X_0 = z
\end{aligned}
\right.
\end{equation}
 has a unique probabilistically weak solution $X^z$ with the prescribed one-dimensional time marginals $\mathcal{L}(X^z_t) = f^z_Q(t,x) \,\mathrm d x$ for all $t>0$. Furthermore, the path laws $P^z := \mathcal{L}(X^z)$ of $X^z$ form a nonlinear Markov process with one-dimensional time marginal densities $f^z_Q(t,\cdot)$, $(t,z)\in (0,\infty) \times \mathbb{R}^d$. Finally, the solutions $X^z$ are probabilistically strong after every strictly positive time. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] Assume the hypotheses of Theorem~\ref{thm:stationary}. For any given free Brownian motion $\{W_t\}_{t\geq 0}$,  let $u, v \in \mathscr{A}_{sa}$ that are free from $\{W_t\}_{t\geq 0}.$
Let $\{U^u_{t}\}_{t \geq 0},\{U^v_{t}\}_{t \geq 0}$ be the unique solutions to the free SDE \eqref{eq:fSDE} with initial values $u,v$, respectively. Then there exists a constant $C>0$ such that
\begin{equation}
 \left\| U^u_t - U^v_t \right\|_2 \leq e^{-Ct}\|u-v\|_2
\end{equation}
for any $t \geq 0.$

