[Lemma lm:C2 of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Suppose that $(\sigma,b)$ satisfy Assumption~(assu:H of the paper) and conditions~(item:1a of the paper)--(item:1d of the paper) on $I$. Let $N\ge 2/|I|+1$. Then there exists a sequence $(\sigma_n,b_n)_{n\ge N}$ satisfying Assumption~(assu:H of the paper) and conditions~(item:1a of the paper)--(item:1d of the paper) on ${\mathbb R}$, such that,
    \begin{align}
        b_n(x,t)=b(x,t)\ \text{ and }\ \sigma_n(x,t,\cdot)=\sigma(x,t,\cdot), \quad \forall x\in I_n,\, t\in {\mathbb R},
    \end{align}
    where $I_n:=\bigl(\inf I+\tfrac{1}{n},\, \sup I-\tfrac{1}{n}\bigr)$, with the convention $-\infty+c=-\infty$ and $+\infty-c=+\infty$.

[Proposition cor:moments of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $\beta\in\mathbb{R}$, $N\in\mathbb{N}$, $k\in\mathbb{N}$, and
	$\mathbf x=(x_1,\ldots,x_k)\in\mathbb{Z}^k$. Recall $\mathscr E_{\beta,k}$ from (equation eq:G-beta-k of the paper). Then, for every $t\ge0$ and every
	$\phi_1,\ldots,\phi_k\in\ensuremath{\mathcal C}_b(\mathbb{R})$,
	\begin{equation}
		\begin{aligned}
		&\mathbb{E}\bigg[
			\prod_{i=1}^k
			\mathfrak H_{\beta,N}(t,x_i,\phi_i)
		\bigg]
		=
		\mathbf E_{\mathbf x}^{(\beta,k)}
		\bigg[
			\mathscr E_{\beta,k}(tN)
			\prod_{i=1}^k
			\phi_i(N^{-1/2}\tttonde{R_{tN}^i-tN\sinh(\beta)})
		\bigg]\; \text{.}
		\end{aligned}
	\end{equation}

