[Lemm l:holder-high-prob of arXiv:2607.18194, 'Temperature chaos in directed polymers'] For all sufficiently small $\varepsilon>0$,
    \begin{align*}
        \limsup_{n\to\infty} \mathbb{P}(\neg \textup{\textsf{EnergyH\"{o}lder}}_{\varepsilon,n})
        \leqslant e^{-\log^2(1/\varepsilon)}.
    \end{align*}

[Thm weak_existence_Volterra_clock of arXiv:2605.29073, 'Volterra clocks and their pure-jump limits: \\hitting times of curved boundaries'] Let $\lambda\,, \nu \geq 0\,, T > 0\,$. We consider $K \in L^1_{loc}(\ensuremath{\mathbb{R}}_+\,, \ensuremath{\mathbb{R}})$ a completely monotone kernel, $g_0 \in \mathcal G_K\,$, and $f : \ensuremath{\mathbb{R}}_+ \to \ensuremath{\mathbb{R}}_+$ satisfying Assumption (assumption:f of the paper). Then, there exists a filtered probability space $\left(\Omega\,, \mathcal F\,, \left(\mathcal F_t\right)_{t \leq T}\,, \mathbb P\right)$ satisfying the usual conditions and adapted continuous processes $\left(X\,, M\right)\,$, starting from $0\,$, such that $X$ is non-decreasing, $M$ is a martingale with quadratic variation $\langle M\rangle_t = f(X_t)\,$, and 
    \begin{equation}

    X_t = G_0(t) + \int_0^t\,K(t-s)\,\left( - \lambda\,X_s + \nu\,M_s\right)\,ds \,, \quad t \leq T\,,
    \end{equation}
    where $G_0 := \int_0^{\cdot}\,g_0(s)\,ds\,$.

[Lemma lma:changinglifts of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $\rho: \Gamma \to PSL_2(\mathbb{R})$ be a representation which lifts to $\widetilde{PSL}_2(\mathbb{R})$. If $\widetilde\rho, \widetilde\rho': \Gamma \to \widetilde{PSL}_2(\mathbb{R})$ are two such lifts of $\rho$, then there is a unique homomorphism $\phi \in H^1(\Gamma; \mathbb{Z}) = \mathrm{Hom}(\Gamma, \mathbb{Z})$ such that $\widetilde\rho'(g) = z^{\phi(g)}\widetilde\rho(g)$ for every $g \in \Gamma$. Consequently, 
\begin{equation*}
	\mathrm{trans}(\widetilde\rho'(g)) - \mathrm{trans}(\widetilde\rho(g)) = \phi(g)
\end{equation*}

