[Theorem 31 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $F$ be a non-anticipative functional such that $F \in \C^{1,2}_b$. Then, for all $t \in [0,T)$,
    \begin{equation*}
        F_t(X_t) = F_0 (X_0) + \int_0^t \cD_u F(X_u) \, du + \int_0^t \nabla_x F_u(X_u) \, dX(u)  + \frac 1 2 \int_0^t \tr(\nabla^2_x F_u(X_u)) \, d\langle X \rangle(u), \quad \text{a.s.}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Cor: Upsilon multiplication of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Let $\tau_0,\ldots,\tau_k\in{\mathcal T}$ and $\rho=[\ldots[\bullet_{k-1},\rho_{m_L(\rho)}],\ldots\rho_1]\in{\mathcal T}_b^{I_{k-1}}$. 
		For $\ell\in\{1,\ldots, m_L(\rho)+1\}$ and $0\le j_1<\cdots<j_\ell<k$, $j_{\ell+1}:= k$, we have 
		\begin{align}	\nonumber
			& \int_{[0,1]_\geq^k}\left[\left(\prod_{i=1}^{\ell}\nabla \Upsilon_{G\left(\rho^{(\ell)}_i\right)}(u_{j_i})\right) \Upsilon_{\tau_k}(z_1)- \Upsilon_{G\left(\bullet_{k}\to_\ell\rho\right)}(u_{j_1})\right]\, {\mathrm d}\mathbf{t}_{k-1}
			\\ & =-\sum_{m=1}^{\ell}\sum_{j=j_{m}+1}^{j_{m+1}}\int_{[0,1]_\geq^{k+1}}\left(\prod_{i=1}^{m+1}
			\nabla \Upsilon_{G\left((\bullet_{k}\to_\ell\rho)^{(m+1)}_i\right)}(u_{j_i'})\right) \cdot z^{[1]}\, {\mathrm d} \mathbf{t}_{k}\, ,

		\end{align}
		recall Definition (Def: link binary to rooted of the paper) and (equation eq:rhoelli of the paper), where $j_i'=j_i$ if $i\le m$ and $j_{m+1}'=j$.

