[Definition 16 of arXiv:2606.11271, '\LARGE The $K$-th nearest neighbor random walk on a Poisson point process gets trapped'] For any $\varepsilon >0$, $R\in \N^*$ and $n\in \N$, $X_n$ is called an $(\varepsilon,R)$-nice point if there exists $u \in \Z^d$ such that
\begin{itemize}
\item[$(i)$] $\Lambda_R (u)$ is $\varepsilon$-good;
\item[$(ii)$] $E_n \cap \Lambda_R(u) = \emptyset$;
\item[$(iii)$] $E_{n+1} \cap \Lambda_R(u) \neq  \emptyset$.
\end{itemize}

[Thm 1 of arXiv:2605.29469, 'Multiscale Asymptotic Analysis of Kernel-Smoothed Solutions to Fractional Riesz-Bessel Equ'] Consider the random field $u(t,x)$, $t>0$, $x\in\mathbb{R}$, defined by \eqref{FRBE} and the random initial condition given by \eqref{Icond}, satisfying Assumption~{\rm\ref{Asumptionmain}} with $A_0=0$.

For  $\rho_1=-{\rho_3}/{2}$, $\rho_2=\alpha\rho_3/\beta$, and  $\rho_3>0$, when $\varepsilon\to 0$, the finite-dimensional distributions of $U_\varepsilon^{g}(t,x)$ converge weakly to those of a zero-mean Gaussian random field~$U_0^{g}(t,x)$ given by
\begin{equation} 
U_0^{g}(t,x)
:=
\sqrt{
C(\bar{\kappa},\bar{w},\bar{A})}
\int_{\mathbb{R}}
\widehat{g}(\lambda,x)\,
E_\beta\!\left(-\mu t^\beta |\lambda|^\alpha\right)\,
W(d\lambda).
\end{equation}

The limit random field $U_0^{g}(t,x)$ has the covariance function
\begin{align}
\operatorname{Cov}\bigl(U_0^g(t,x),U_0^g(t',x')\bigr)
&=
C(\bar{\kappa},\bar{w},\bar{A})
\int_{\mathbb{R}}
\widehat{g}(\lambda,x)\overline{\widehat{g}(\lambda,x')}\nonumber \\ &\quad \quad\times
E_\beta(-\mu t^\beta |\lambda|^\alpha)
E_\beta(-\mu (t')^\beta |\lambda|^\alpha)\,d\lambda.

\end{align}

