body:
[Definition def:approx_currents of arXiv:2607.24640, 'The Yang-Mills measure on surfaces via Morse theory'] A current $\mathbf{T}$ is said to be approximable if 
\begin{itemize}
    \item there exists a sequence of admissible curves $(\gamma_n)_{n\geqslant 1}$ such that the sequence of currents $[\gamma_n]$ converge weakly to the current $\mathbf{T}$ (for the weak topology of $\mathcal{D}^{\prime,1}(\Sigma)$), 
    \item the corresponding sequence of index functions $\left([\blacktriangle (\gamma_n)]\right)_{n\in \mathbb{N}}$ is Cauchy in $L^2_\upsilon(\Sigma)$.
\end{itemize}

[Lemma lem:locally_large_measure_concrete of arXiv:2508.18809, '{\bf Critical long-range percolation III: The upper critical dimension}'] For each $\beta,r>0$ there exists a probability measure $\mu=\mu_{\beta,r}$ on $\mathbb Z^d$ such that
\begin{multline*}
\mathbb E_{\beta,r}\left[ \sum_{y\in B_r} \mathbbm{1}(0\nleftrightarrow y) |K_y| \sum_{z\in K^W} \mathbbm{1}\!\left(K^{W} \in \mathscr{A} \text{ and } \sum_{x\in \mathbb Z^d}|[0,z]_{K^W} \cap B_r(x)|\mu(x) \leq \ell \right)\right] 
\\
\geq\left(1-\frac{\ell\mathbb E_{\beta,r}|K|^2}{|B_r| \mathbb E_{\beta,r}|K|}\right) |B_r|\mathbb E_{\beta,r}|K| \mathbb E_{\beta,r}\left[\sum_{z\in K^W} \mathbbm{1}\!\left(K^{W} \in \mathscr{A} \text{ and } \sum_{x\in \mathbb Z^d}|[0,z]_{K^W} \cap B_r(x)|\mu(x) \leq \ell \right)\right] 
\end{multline*}
for every $\ell\in(0,\infty)$, subset $W$ of $\mathbb Z^d$, and set $\mathscr{A}$ of finite subsets of $\mathbb Z^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p:polymer-ordering of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {AJRS22}}]
    Almost surely, 
    for all $s<t$ and all $x_{1}\leqslant x_{2}$ and $y_{1}\leqslant y_{2}$,
    we have the stochastic dominance  
    \footnote{
        For probability measures $\mu,\nu$ on $C([s,t])$, we say that $\nu$ stochastically dominates $\mu$ (denoted $\mu\preceq_{\mathrm{sd}}\nu$) if $\int F\,d\mu \leqslant \int F\,d\nu$ for all continuous bounded increasing functionals $F: C([s,t])\to\mathbb{R}$, where $F : C([s,t]) \to \mathbb{R}$ is called increasing if for all $X,Y\in C([s,t])$ satisfying $X(r)\leqslant Y(r)$ for all $r\in[s,t]$, we have $F(X)\leqslant F(Y)$.
    }
    \begin{align*}
        \mathbb{P}^\xi_{1,(s,x_1),(t,y_1)}
        \preceq_{\mathrm{sd}}
        \mathbb{P}^\xi_{1,(s,x_2),(t,y_2)}.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p: wasserstein conditions general of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi, \Psi$ are invariant random (nonnegative) measures with the same finite intensity. Let $p\in[0,\infty)$. Assume that $\BE[\Phi(B_\varepsilon)^{2+p}]<\infty$ for some $\varepsilon>0$, and assume that $W_{d+\frac{d}{p}+\vartheta}(\Phi, \Psi)<\infty$ for some $\vartheta>0$. Then $\Psi$ is also locally square-integrable. The same holds if $\Phi(B_\varepsilon)$ is uniformly bounded for some $\varepsilon>0$, e.g., if $\Phi$ is $\infty$-uniform; see Proposition~(p: stealthy uniform bounds of the paper), and if $W_{d}(\Phi, \Psi)<\infty$.
    \begin{proof}
        For $p=0$, the assertion follows from the fact that
        \begin{equation*}
            \BE[\Psi(B_1)^2]\leq \BE[\Phi(B_{1+W_\infty(\Phi,\Psi)})^2]<\infty.
        \end{equation*}
        Hence, from now on we assume that $p\in(0,\infty)$, that $\BE[\Phi(B_\varepsilon)^{2+p}]<\infty$ for some $\varepsilon>0$, and that $W_{d+\frac{1}{p}+\vartheta}(\Phi, \Psi)<\infty$ for some $\vartheta>0$. Then there exists an invariant probability kernel $K$ such that $\Psi=K\Phi$ and 
        \begin{equation*}
            \BE_0^\Phi\bigg[\int\|x\|^{d+\frac{1}{p}+\vartheta}\, K_0(dx)\bigg] < \infty.
        \end{equation*}
        Also note that $\BE[\Phi(B_\varepsilon)^{2+p}]$ for some $\varepsilon>0$ implies that the same holds for every $\varepsilon>0$.
        Now, we can apply the Hölder inequality twice to obtain
        \begin{align*}
            &\BE_0^\Phi\bigg[\Phi(B_1)\bigg(\int \sqrt{\|x\|^{d+\vartheta\frac{p}{1+p}}+1}\, K_0(dx)\bigg)^2\bigg]\nonumber\\
            &\quad\ \ \leq \BE_0^\Phi\big[\Phi(B_1)^{1+p}\big]^{\frac{1}{1+p}}\BE_0^\Phi\bigg[\bigg(\int \sqrt{\|x\|^{d+\vartheta\frac{p}{1+p}}+1}\, K_0(dx)\bigg)^{2\frac{1+p}{p}}\bigg]^{\frac{p}{1+p}}\nonumber\\
            &\quad\ \ \leq \BE_0^\Phi\big[\Phi(B_1)^{1+p}\big]^{\frac{1}{1+p}}\BE_0^\Phi\bigg[\int \big(\|x\|^{d+\vartheta\frac{p}{1+p}}+1\big)^{\frac{1+p}{p}}\, K_0(dx)\bigg]^{\frac{p}{1+p}}\nonumber\\
            &\quad\ \ \leq \bigg(\frac{\BE\big[\Phi(B_{2})^{2+p}\big]}{\BE\big[\Phi(B_{\kappa_d^{-1}})\big]}\bigg)^{\frac{1}{1+p}}\BE_0^\Phi\bigg[2^{\frac{1}{p}}\int \|x\|^{d+\frac{d}{p}+\vartheta}\, K_0(dx)+2^{\frac{1}{p}}\bigg]^{\frac{p}{1+p}}\nonumber\\
            &\quad\ \ < \infty.
        \end{align*}
        Then, by choosing $\rho(r):= r^{\vartheta\frac{p}{1+p}}, r\geq0$, we can see that~(equation e: condition sq int simplified of the paper) from Proposition~(p:independent square-integrable of the paper) holds, which allows the application of Theorem~(t:main square-integrable of the paper) to show that $\Psi$ is locally square-integrable.

        For the last case that $\Phi(B_\varepsilon)$ is uniformly bounded for some $\varepsilon>0$, the assertion follows from the fact that one can use the technique from Appendix~(ss:Reduction to Lebesgue of the paper) to find an invariant kernel $\tilde{K}$ which has uniformly bounded total variation such that $\Psi=\tilde{K}\lambda_d$ additionally to the invariant probability kernel $K$ which fulfills $\Phi=K\Psi$ and Condition~(c:condition square-integrable Markov of the paper). Then $K\tilde{K}, \lambda_d$ also fulfill \linebreak $K\tilde{K}\lambda_d=\Psi$ and Condition~(c:condition square-integrable Markov of the paper), whereby Theorem~(t:main square-integrable of the paper) can be applied.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 4 (\cite{GGT25}) of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{X^n_s : s \in S_n, n\ge 1\}$ be a collection of $\cX$-valued random elements such that $(\omega, s) \mapsto X^n_s(\omega)$ is $\cF\otimes \cS_n/\cB(\cX)$-measurable for all $n \ge 1$. Let $p \in (0, \infty)$. Then, the following assertions are equivalent:
\begin{enumerate}[\rm (i)]
\item $\{X^n_s : s \in S_n, n\ge 1\}$ is $(\nu_n)$-$\CUI(p)$.

\item $\{X^n_s : s \in S_n, n\ge 1\}$ is uniformly tight, which means
\begin{align*}
\forall \ep >0, \, \exists K_\ep \in \cK(\cX)\; :\; \sup_{n \ge 1} (\bP \otimes \nu_n) (X^n_s \notin K_\ep) \le \ep,
\end{align*}
and that 
\begin{align*}
\lim_{a \to \infty} \sup_{n \ge 1} \bE \int_{S_n} \|X^n_s\|^p \, \1_{\{\|X^n_s\| > a\}} \nu_n(\od s) =  0.
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5 of arXiv:2608.21090, 'Ornstein--Uhlenbeck process conditioned to have restricted $L_2$-norm'] For any $r>0$ and $T\geq 1$
    \begin{equation*}
        \limsup\limits_{H\to\infty}\left|I_T(H)-I_T(r)\right|\leq C_{c,r}\,a_x(c)\,\frac{1}{T}\,e^{T\Re\psi(c+ir)},    
    \end{equation*}
    where $C_{c,r}>0$ depends only on $c,r$.

