body:
[Lemma lem_discrete_Gronwall of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Let $(\gamma_k)_{k\ge 1}$ be a nonincreasing
		sequence of positive numbers such that $\gamma_k\to_{k\to \infty}0$ and $
		t_k=\sum_{i=1}^k \gamma_i \to_{k\to \infty}+\infty$. Let $(f_{k})_{k\in 
			\mathbb{N}}\in {\mathbb{R}}_+^{\mathbb{N}}$ be a sequence that verifies for
		all $k\ge 0$, 
		\begin{equation}
			\frac{f_{k+1}-f_{k}}{\gamma _{k+1}}\leq -bf_{k}+\frac{a}{t_{k}}
			\sum_{i=1}^{k}\gamma _{i}f_{i}+Ct_{k}^{-\delta }  
		\end{equation}
		for some $b>a>0$, $C\in{\mathbb{R}}_+$ and $\delta \in (0,1)$. Then, for any 
		$\zeta \in (0,\delta] \cap (0,1-\frac{a}{b})$, there exists a constant $
		C^{\prime }\in {\mathbb{R}}_+$ such that $f_{k}\leq C^{\prime }t_{k}^{-\zeta
		} $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:approx_strat_delay_f of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let \(B^{\epsilon}\) be the regularized path in Definition (REGU of the paper) and 	
			\begin{align*}
				\mathbf{B}_{s,t}^{\epsilon} := \left( B^{\epsilon}_{s,t}, \mathbb{B}_{s,t}^{\epsilon}, \mathbb{B}_{s,t}^{\epsilon}(-r) \right) := \left(B^{\epsilon}_{s,t}, \int_s^t B_{s,u}^{\epsilon}\, \otimes \mathrm{d}B^{\epsilon}_u, \int_s^t B^{\epsilon}_{s-r,u - r}\, \otimes \mathrm{d} B^{\epsilon}_u \right),
			\end{align*}
			Then 
			\begin{align*}
				\lim_{\epsilon \rightarrow\infty}\sup_{q\geqslant 1}\frac{\left\|d_{\gamma;J}\big{(} \mathbf{B}^{\epsilon} , \mathbf{B} \big{)}\right\|_{L^{q}}}{\sqrt{q}} = 0
			\end{align*}
			for each $\gamma <H$ and every compact interval $J \subset \mathbb{R}$ where $d_{\gamma;J}$ represents the homogeneous metric
			\begin{align*}
				d_{\gamma;J}(\mathbf{X},\mathbf{Y}) = \sup_{s,t \in J; s \neq t} \frac{\vert X_{s,t} - Y_{s,t}\vert}{|t-s|^{\gamma}} + \sqrt{ \sup_{s,t \in J; s \neq t} \frac{\vert\mathbb{X}_{s,t} - \mathbb{Y}_{s,t}\vert}{|t-s|^{2 \gamma}}} + \sqrt{ \sup_{s,t \in J; s \neq t} \frac{\vert\mathbb{X}_{s,t}(-r) - \mathbb{Y}_{s,t}(-r)\vert}{|t-s|^{2 \gamma}}} 
			\end{align*}
			and by \(\Vert \cdot \Vert_{L^{q}}\), we mean the usual \(L^{q}(\Omega)\) norm.

