[Thm see \cite{KM21} thm (\textcolor{red}{2.4}) of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Under the neutrality condition $\left(\mathrm{NC}_b\right)$, the value of the differential $C_{\mathbb{H}}\left[\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right]$ in the identity chart of $\mathbb{H}$ (and the chart $z \mapsto-1 / z$ at infinity) is given by

 \begin{equation}
C_{\mathbb{H}}\left[\boldsymbol{\sigma}^{+}, \boldsymbol{\sigma}^{-}\right]=\prod_{j<k}\left(z_j-z_k\right)^{\sigma_j^{+} \sigma_k^{+}}\left(\bar{z}_j-\bar{z}_k\right)^{\sigma_j^{-} \sigma_k^{-}} \prod_{j, k}\left(z_j-\bar{z}_k\right)^{\sigma_j^{+} \sigma_i^{-}},
\end{equation}

where the products are taken over finite $z_j$ and $z_k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 45 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] With $F$ as above
  \begin{equation}
  \frac{ F(z) \sqrt{T}c}{z+\overline{w}}=\int_{\mathbb R}\frac{ ({\rm Re}\, F(x))g_w(x)cdx}{ix+z}
  \end{equation}
  Assume $\det F(z)\not0$. Then,
  \begin{equation}
  \frac{  \sqrt{T}c}{z+\overline{w}}=\int_{\mathbb R}\frac{ ({\rm Re}\, F(x))f_w(x)cdx}{ix+z}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 4 of arXiv:2609.02392, 'Large values of cubic and quartic Dirichlet $L$-functions of prime moduli'] Suppose $\chi$ be a primitive Dirichlet character modulo $q$. Let $A$ and $B$ be positive real numbers with $AB = q$.  Then we have
\begin{align*}

L \left( \frac{1}{2} , \chi \right) = \sum_{m=1}^{\infty} \frac{\chi(m)}{m^{1/2 }} V_{\af}\left(\frac{m}{A}\right)
+ \epsilon(\chi) \sum_{m=1}^{\infty} \frac{\overline{\chi}(m)}{m^{1/2}} V_{\af}\left(\frac{m}{B}\right),
\end{align*}
  where
\begin{align*}
\epsilon(\chi) = i^{-\af} q^{-1/2} \tau(\chi), \quad V_{\af}(x) = \frac{1}{2\pi i} \int\limits_{(2)} \frac{G(s)}{s} \gamma_{\af}(s) x^{-s} \dif s,  \quad \gamma_{\af}(s) = \pi^{-s/2} \frac{\Gamma\left(\tfrac{1/2 + \af+ s}{2}\right)}{\Gamma\left(\tfrac{1/2 + \af}{2}\right)}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

