[Thm Satz: LR-Zerleg. superkrit. Reg. of arXiv:2509.15790, 'Covariance matrices of volume power functionals of random simplicial complexes -- an asymp'] For $n\geq2$ let $\Sigma_n$ be defined as in ((Eq: Kov.matrix Laengen Potenz Funktional of the paper)) in the supercritical regime. The following statements then hold.
\begin{enumerate}
\item 
An LU decomposition $\Sigma_n =LU$ of $\Sigma_n$ is given by the matrices $L= (l_{ij})\in \mathbb{R}^{n \times n}$ and $U=(u_{ij})\in \mathbb{R}^{n \times n}$ which have the entries
\begin{align*} 
l_{ij} = \left\{
\begin{array}{ll}
1&\text{ for }\,i=j,\\
\frac{a_1}{a_i} & \text{ for }\,i >1  \text{ and }  j=1,\\
0& \text{ else}.\\
\end{array}
\right.\, \text{ and }\,
u_{ij} = \left\{
\begin{array}{ll}
\frac{1}{a_1a_j} & \text{ for }\,i=1,\\
0& \text{ else}.\\
\end{array}
\right.
\end{align*}
\item
A Cholesky decomposition $ \Sigma_n = G G^t$ of $\Sigma_n$ is given by the matrix $G= (g_{ij})\in \mathbb{R}^{n \times n}$ which has entries 
\begin{align*} 
g_{ij} = \left\{
\begin{array}{ll}
\frac{1}{a_i}& \text{ for } j=1,\\
0& \text{ else}.\\
\end{array} \right.
\end{align*}
\item
A matrix root $B=(b_{ij})\in \mathbb{R}^{n \times n}$ of $\Sigma_n$ 
(i.e., $B^2=\Sigma_n$) has entries
\begin{align*} 
b_{ij} = \frac{\prod_{k=1}^na_k}{a_ia_j \sqrt{\sum_{i=1}^n\prod_{k \in [n] \setminus \{i\}}a_k^2}}.
\end{align*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:2+eps of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Let $X$, $Y$ be two independent random variables. Then
\begin{equation}
{\mathbb E}\, |X+Y|^{2+{\varepsilon}} \le {\mathbb E}\, |X|^{2+{\varepsilon}}+ {\mathbb E}\, |Y|^{2+{\varepsilon}} + 2^{2+{\varepsilon}} \left({\mathbb E}\, |X| \cdot {\mathbb E}\, |Y|^{1+{\varepsilon}}+ {\mathbb E}\, |X|^{1+{\varepsilon}} \cdot {\mathbb E}\, |Y|\right).
\end{equation}
\end {lemma}

Now, let us apply Lemma~(l:2+eps of the paper) to $X=\widetilde{\xi}_{a;n}$ and $Y=\widetilde{\xi}_{a+n;n'}$. Note that due to the upper bound~(equation eq:C-2-p of the paper) for first and $1+{\varepsilon}$-th moments, we get
\[
{\mathbb E}\, |X|^{1+{\varepsilon}} \cdot {\mathbb E}\,|Y| \le C_{\sigma}^{1+{\varepsilon}}\, \sqrt{n}^{1+{\varepsilon}}\cdot C_{\sigma} \, \sqrt{n'} \le C_{\sigma}^{2+{\varepsilon}} \sqrt{m}^{2+{\varepsilon}},
\]
and the same estimate applies to ${\mathbb E}\, |X|\cdot {\mathbb E}\,|Y|^{1+{\varepsilon}}$.
From the estimate~(equation eq:2+eps of the paper) we thus get
\begin{multline}
{\mathbb E}\, \left| \widetilde{\xi}_{a;n}+\widetilde{\xi}_{a+n;n'}\right|^{2+{\varepsilon}} \le {\mathbb E}\, \left| \widetilde{\xi}_{a;n}\right|^{2+{\varepsilon}} +{\mathbb E}\, \left| \widetilde{\xi}_{a+n;n'}\right|^{2+{\varepsilon}} + 2 (2C_{\sigma})^{2+{\varepsilon}} \cdot \sqrt{m}^{2+{\varepsilon}}
\\
\le (\max(c'_n, c'_{n'}))^{2+{\varepsilon}}\cdot \left( n^{1+\frac{{\varepsilon}}{2}} + (n')^{1+\frac{{\varepsilon}}{2}} \right)+ (4C_{\sigma})^{2+{\varepsilon}} \cdot m^{1+\frac{{\varepsilon}}{2}}

\end{multline}
Now, let
\[
\lambda_m:= \left(\frac{n}{m}\right)^{1+\frac{{\varepsilon}}{2}} + \left(\frac{n'}{m}\right)^{1+\frac{{\varepsilon}}{2}}.
\]

Taking $2+{\varepsilon}$-th power root, and using the concavity inequality $\sqrt[2+{\varepsilon}]{a+b}\le \sqrt[2+{\varepsilon}]{a}+\sqrt[2+{\varepsilon}]{b}$, we obtain
\begin{equation}
\left( {\mathbb E}\, \left| \widetilde{\xi}_{a;n}+\widetilde{\xi}_{a+n;n'}\right|^{2+{\varepsilon}}\right)^{1/(2+{\varepsilon})} \le (\lambda_m^{1/(2+{\varepsilon})} \cdot \max(c'_n, c'_{n'}) + 4C_{\sigma}) \cdot \sqrt{m}.
\end{equation}
Now, using the $L_{2+{\varepsilon}}$--triangle inequality for $(\widetilde{\xi}_{a;n} + \widetilde{\xi}_{a+n;n'})$ and $\widetilde{R}_{a;n,n'}$, we get
\[
\left( {\mathbb E}\, \left| \widetilde{\xi}_{a;m}\right|^{2+{\varepsilon}}\right)^{1/(2+{\varepsilon})} \le  (\lambda_m^{1/(2+{\varepsilon})} \cdot \max(c'_n, c'_{n'}) + 4C_{\sigma}) \cdot \sqrt{m} + 2C_R.
\]
Hence, it suffices to take
\begin{equation}
c'_m:= \lambda_m^{1/(2+{\varepsilon})} \cdot \max(c'_n, c'_{n'}) + 4C_{\sigma} + \frac{2C_R}{\sqrt{m}}
\end{equation}
for the upper bound ${\mathbb E}\,\left| \widetilde{\xi}_{a;m}\right|^{2+{\varepsilon}} \le (c'_m \cdot \sqrt{m})^{2+{\varepsilon}}$ to hold.

Now, for every $m$ one has $\lambda_m<1$, and the values $\lambda_m$ converge to $2^{-\frac{{\varepsilon}}{2}}<1$ as $m\to\infty$. Hence, there exists $\lambda<1$ such that for all $m$, one has $\lambda_m^{1/(2+{\varepsilon})}<\lambda$. Taking
\[
C_{2}:=\frac{4C_{\sigma}+2C_R}{1-\lambda}
\]
to be the fixed point of the map $c\mapsto \lambda c +(4C_{\sigma}+2C_R)$, we see by recurrence that the sequence~$(c'_m)$ satisfies $c'_m\le C_{2}$ for all~$m$. We have thus obtained the desired upper bound
\[
{\mathbb E}\, |\widetilde{\xi}_{a;m}|^{2+{\varepsilon}} \le C_{2}^{2+{\varepsilon}} \cdot \sqrt{m}^{2+{\varepsilon}}.
\]

Let us now prove Lemma~(l:2+eps of the paper):
\begin{proof}[Proof of Lemma~(l:2+eps of the paper)]
Let us first show that for any $a,b\in {\mathbb R}$,
\begin{equation}
|a+b|^{2+{\varepsilon}} \le |a|^{2+{\varepsilon}} + |b|^{2+{\varepsilon}}+ 2^{2+{\varepsilon}}\cdot (|a|^{1+{\varepsilon}} |b| +|a| \cdot |b|^{1+{\varepsilon}}).
\end{equation}
Indeed, Jensen's inequality for the function $(1+x)^{2+{\varepsilon}}$ on $[0,1]$ implies that
\begin{equation}
\forall x\in [0,1] \quad (1+x)^{2+{\varepsilon}} \le (1-x)\cdot 1 + x\cdot 2^{2+{\varepsilon}} \le 1 + 2^{2+{\varepsilon}}x.
\end{equation}
Now, if $|a|\ge |b|$, then
\b

