body:
[Thm Theorem 8.4 of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{peanut butter}
  Consider activated random walk with sleep rate $\lambda>0$.
  Let $\sigma$ be an initial configuration on $\ii{1,n}$ with no sleeping particles.
  Let $Y_n$ be the number of particles left sleeping on $\ii{1,n}$ in the stabilization of 
  $\sigma$ on
  $\ii{1,n}$. For any $\rho>\crist(\lambda)$,
  \begin{align*}
    \mathbf{P}(Y_n\geq \rho n) \leq Ce^{-cn}
  \end{align*}
  where $C,c$ are positive constants depending on $\lambda$ and $\rho$ but not on $n$ or $\sigma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 139 (Pointwise identities and $L^\infty$ estimates tied to the integral curves of $\newL$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $f$ be a function of the double-null coordinates on 
$[\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2] \times \mathbb{T}^2$,
let $\FlowmapnewL$ be the $\leftubar$-normalized flow map of $\newL$ from 
Lemma\,\ref{L:PROPERTIESOFFLOWMAPOFNEWL}.
Then relative to the double-null coordinates, the following identity holds for any 
$\leftubar \le \ubar_1 \le \ubar_2 < \ubarboot$
and any $(u,x^2,x^3) \in [\moreinterestingu_1,\moreinterestingu_2] \times \mathbb{T}^2$:
\begin{align} 
f \circ \FlowmapnewL(\ubar_2,u,x^2,x^3)
& = 
	f \circ \FlowmapnewL(\ubar_1,u,x^2,x^3)
	+ 
	\int_{\timefunction' = \ubar_1}^{\ubar_2} (\newL f) 
	\circ 
	\FlowmapnewL(\ubar',u,x^2,x^3) 
	\, \rmd \ubar'.
\end{align}
In addition, we have the following $L^{\infty}$ estimates:
\begin{subequations}
	\begin{align} 
		\| f \|_{L^{\infty}\left(\doublenulltoritwoarg{\ubar_2}{u}\right)} 
		& \leq 
		\| f\|_{L^{\infty}\left(\doublenulltoritwoarg{\ubar_1}{u}\right)} 
		+
		|\leftubar| \sup_{\ubar' \in [\ubar_1,\ubar_2]} 
		\| \newL f \|_{L^{\infty}\left(\doublenulltoritwoarg{\ubar'}{u}\right)},

	\end{align}
	\begin{align}
		\esssup_{(x^2,x^3) \in \T^2} \left| f \circ \FlowmapnewL(\ubar_2, u,x^2,x^3) -  f \circ \FlowmapnewL(\ubar_1, u,x^2,x^3) \right| \le |\leftubar| \sup_{\ubar' \in [\ubar_1,\ubar_2]} 
		\| \newL f \|_{L^{\infty}\left(\doublenulltoritwoarg{\ubar'}{u}\right)}.

	\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 45 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For all $K \geq (\widetilde C_{\mu}+\varepsilon) \log N$, $\chi,\rho,\varphi>0$ as in \eqref{eq:small-params} sufficiently small, $(\chi,\rho,\varphi)$-almost-$\mu$-like shuffle $(\vec \bn^{(t)})_{t\leq K}$ and $i \in \{\iota(p),\ldots,\tau(p)-2\}$, there exists $\zeta=\zeta(\mu,\varepsilon)>0$ such that on the event $F_{i} \cap (F_{i})'$ constructed in Lemma~\ref{lem:cond-12moment},
         we have
         \begin{equation} 
             \E[|E(G_{u,1},G_{u,1}')|\big\vert \mathbf{a}_i,\mathbf{a}'_i] \leq O(N^{-\zeta}).    
         \end{equation}

[Theorem 2 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Assume that we are in Scenario~\eqref{Scenario_2}, and that each sample is drawn with replacement. Assume that $g$, defined in \eqref{g_defn}, satisfies one of the following criteria:
\begin{enumerate}[label=(B\arabic*), ref=B\arabic*]
\item  that $g$ is Lipschitz on $\mathcal{S}$, and that the series 
\begin{equation}
\sum_{n\geqslant N}(n+1)^{-1}\E\left[K_{n}^{-1/2}\right] \text{ converges};
\end{equation}
\item } that $g\in\mathcal{C}^{(1)}(\mathcal{S})$, and that the series 
\begin{equation}_series_convergence}
\sum_{n\geqslant N}\frac{1}{n+1}\min\left\{\omega\left(\nabla g;\sqrt{\E\left[K_{n}^{-1}\right]}\right)\sqrt{\E\left[K_{n}^{-1}\right]},\omega\left(\nabla g;\frac{\E\left[K_{n}^{-1}\right]}{\E\left[K_{n}^{-1/2}\right]}\right)\E\left[K_{n}^{-1/2}\right]\right\} \text{ converges};
\end{equation}
\item } that $g\in\mathcal{C}^{(2)}(\mathcal{S})$, and that the series 
\begin{equation}_series_convergence}
\sum_{n\geqslant N}(n+1)^{-1}\E\left[K_{n}^{-1}\right]\text{ converges}.
\end{equation}
\end{enumerate}
Then the sequence $\left\{\left(n^{-1}A_{n},n^{-1}B_{n}\right)\right\}$ converges almost surely to a (possibly sample path dependent) compact connected internally chain transitive invariant set, contained in $\mathcal{S}$, corresponding to the autonomous ODE:
\begin{equation}
\left(\dot{x}(t),\dot{y}(t)\right)=\hat{h}\left(x(t),y(t)\right) \text{ for }t\geqslant 0, \quad \text{with} \quad \left(x(0),y(0)\right)\in\mathcal{S},
\end{equation}
where the function $\hat{h}$ is as defined in \eqref{hat{H}_hat{h}_defn}, and $\mathcal{S}$ is as defined in \eqref{domain_defn}. (Proof in the paper; no proof environment follows the statement in the TeX.)

