[Theorem 1 of arXiv:2608.29316, 'Powers of the Dirac Operator on $S^1\times S^{n-1}$'] The square of the Dirac operator acts as a constant
\begin{align}
\dc^2\Phi&=(\ptl^2_t+D^2)\id_{\S_M^\X}\Phi=(-f^2+J^2)\Phi\\
& \text{ on }V(f,j,\X,\e)=(f)\otimes V(j,\e)\text{ type }K-\text{finite }\X-\text{spinors},
\end{align} 
where $J=\tfrac{n-1}{2}+j$ and $V(f,j,\X,\e)$ is the $K=\spin(2)\times\spin(n)$-finite space consisting of $\Phi=e^{\sqrt{-1}ft}\spm$ for $\f\in V(j,\e)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 of arXiv:2412.05764, 'A method of solution for the inverse problem for $h$-functions of planar Brownian motion'] The periodic Poisson integral takes the form
    \begin{align*}
        (P_y\ast f)(x) = \frac{1}{2}\int_T \frac{\sinh\pi y}{\cosh\pi y - \cos\pi(x-t)} f(t) dt.
    \end{align*}
	for $(x, y) \in T\times \mathbb{R}^+$. In the limit we have,
    \begin{align*}
        \lim_{y\to\infty} (P_y\ast f) = \frac{1}{2}\int_T f(t)dt.
    \end{align*}
    This exists for $f\in L^p(T)$, and furthermore the Poisson integral is bounded on $L^p(T)$ and $P_y\ast f$ is harmonic on 
    $T\times \mathbb{R}^+$ with $\lim_{y\to 0} (P_y\ast f) = f$ almost everywhere.

[Dfn $L^r$-quantization error induced by a quantizer of arXiv:2506.01746, '\bf Optimal Bregman quantization: existence and uniqueness of optimal quantizers revisited'] Let  $r>0$ and let $\|\cdot\|$ denote any norm on $\mathbb{R}^d$.  Assume that the distribution $P$ has a finite $r$th moment i.e. $\int_{\mathbb{R}^d}\|\xi\|^rP(\mathrm{d}\xi)<+\infty$. Let $\Gamma  \subset \mathbb{R}^d$ be a  {\em quantizer}. We define the $L^r$-mean quantization error of the distribution $P$ induced by $\Gamma$ by 

\begin{equation*}
    e_r(\Gamma,P,\|.\|) = \left[\int_{\mathbb{R^d}}\min_{a\in\Gamma} \|\xi-a\|^rP(\mathrm{d}\xi)\right]^{\frac{1}{r}}.
\end{equation*}

[Theorem 6 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $|F|\in L^2_{\loc}(\Om_T)$and assume that $u\in L^2_{\loc}(0,T;W^{1,2}_{\loc}(\Om;\mathbb{R}^N))$ is a weak solution to \eqref{eq}.
Then there exist an exponent $q=q(n,L)$, $1<q<2$, and a constant $c=c(n,N,\nu,L)$ such that 
    \begin{equation}
    \biggl(\fiint_{Q }|\na u|^2\,dz\biggr)^\frac{1}{2}
    \le c\biggl( \fiint_{2Q } |\na u| ^q\,dz\biggr)^\frac{1}{q} 
    + c\biggl(\fiint_{2Q } |F|^2 \,dz\biggr)^\frac{1}{2}
    \end{equation}
    for every parabolic cylinder $2Q \Subset \Om_T$.
    Moreover, there exist $c=c(n,N,\nu,L)$ and $\varepsilon_0=\varepsilon_0(n,N,\nu,L)$, $0<\varepsilon_0<1$, such that for every $0<\varepsilon<\varepsilon_0$, we have
     \begin{equation}
    \biggl(\fiint_{Q } |\na u|^{2+\varepsilon}\,dz\biggr)^\frac{1}{2+\epsilon}
    \le c \biggl( \fiint_{2Q } |\na u|^{2}\,dz\biggr)^\frac{1}{2}
    + \biggl(\fiint_{2Q } |F|^{2+\varepsilon}\,dz\biggr)^\frac{1}{2+\varepsilon}
    \end{equation}
    for every parabolic cylinder $2Q \Subset \Om_T$, under the assumption that $|F|\in L^{2+\varepsilon}(2  Q )$.

