[Theorem 12 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let a nonlinear expectation $\mathbb{\tilde{E}}[\cdot]$ be
dominated by a sublinear expectation $\mathbb{\hat{E}}[\cdot]$ on
$(\Omega,\mathcal{H})$, and let $\{(X_{n},Y_{n})\}_{n=1}^{\infty}$ be a
sequence of $2d$-dimensional random vectors such that $(X_{n+1},Y_{n+1}
)\overset{d}{=}(X_{1},Y_{1})$ and $(X_{n+1},Y_{n+1})$ is independent of
$(X_{1}$,$\ldots$,$X_{n}$,$Y_{1}$,$\ldots$,$Y_{n})$ for $n\geq1$ under
$\mathbb{\tilde{E}}[\cdot]$ and $\mathbb{\hat{E}}[\cdot]$ respectively.
Suppose that
\begin{equation}
\mathbb{\hat{E}}[X_{1}]=\mathbb{\hat{E}}[-X_{1}]=0\text{ and }\lim
_{N\rightarrow \infty}\mathbb{\hat{E}}\left[  (|X_{1}|^{2}-N)^{+}
+(|Y_{1}|-N)^{+}\right]  =0, 
\end{equation}
and for each given $(A,p)\in \mathbb{S}_{d}\times \mathbb{R}^{d}$,
\begin{equation}
\tilde{G}(A,p):=\lim_{n\rightarrow \infty}n\mathbb{\tilde{E}}\left[  \frac
{1}{n}\left(  \frac{1}{2}\langle AX_{1},X_{1}\rangle+\langle p,Y_{1}
\rangle \right)  \right]  \text{ exists.} 
\end{equation}
Then for each $\phi \in C_{b.Lip}(\mathbb{R}^{2d})$, we have
\begin{equation}
\lim_{n\rightarrow \infty}\mathbb{\tilde{E}}\left[  \phi \left(  \frac{1}
{\sqrt{n}}\sum_{i=1}^{n}X_{i},\frac{1}{n}\sum_{i=1}^{n}Y_{i}\right)  \right]
=u^{\phi}(1,0,0), 
\end{equation}
where $u^{\phi}$ is the unique viscosity solution of the following PDE:
\begin{equation}
\partial_{t}u-\tilde{G}(D_{x}^{2}u,D_{y}u)=0\text{, }u(0,x,y)=\phi(x,y).

\end{equation}

[Lemma lem:sqrt of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $a, b \geqslant 0$ and $D = |a-b|$. Then,
    \begin{equation}
        \sqrt{a} \leqslant \sqrt{b} + \left( \sqrt{D} \wedge \frac{D}{2\sqrt{b}} \wedge \frac{D}{\sqrt{a}} \right).
    \end{equation}

[Proposition p: random field low uniformity correlations of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d, 2]$. Suppose that the moment condition~(equation e: random field moment condition of the paper) is satisfied, and that for $q\in\N$ with $q<\frac{d+p}{2}$,
    \begin{equation}
        \int \frac{\big\|\BE_{0,y}^\Phi[Z(y)^{\otimes q}\times Z(0)^{\otimes q}] - \BE_{0}^\Phi[Z(0)^{\otimes q}]\times \BE_{0}^\Phi[Z(0)^{\otimes q}]\big\|}{1 + \|y\|^{2q-p}}\,\alpha_\Phi(dy) < \infty,
    \end{equation}
    where $\times$ denotes the component-wise product. 
    Then $\Psi$ is $p$-uniform if $\Phi$ is. If $p<2$, then beyond $p$-uniformity also transfers.

    Further, if $Z$ and $\Phi$ are independent, we can replace the moment condition by~(equation e: random field moment condition independent of the paper) and simplify~(equation e: random field low uniformity condition of the paper) to
    \begin{equation}
        \int \frac{\big\|\BC[Z(y)^{\otimes q}, Z(0)^{\otimes q}]\big\|}{1 + \|y\|^{2q-p}}\,\alpha_\Phi(dy) < \infty
    \end{equation}
    for $q\in\N$ with $q<\frac{d+p}{2}$, where the covariance is taken component-wise.
    \begin{proof}
        The assertions directly follow from Theorem~(t: main theorem displacement of the paper) with an application of Proposition~(p: uniformity with random field density of the paper) and Remark~(r: uniformity with random field density of the paper) to obtain $(p-2q)$-uniformity of the components of $Z^q\cdot\Phi$ for the required $q\in\N$.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

