body:
[Lemma 5 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $p\geq 2$ satisfying (\ref{c1}). 

		\begin{enumerate}
			\item Let $ (Y_{N}=I_{p}(g_{N}), N\geq 1) $ be a sequence of random variables which converges in $ L ^{2}(\Omega)$.  Assume that there exists $\rho \in \mathbb{R}$ such that
			\begin{equation}
				\mathbf{E}[ X_{N} Y_{N} ]\to _{N \to \infty} \rho. 
			\end{equation}
			Then 
			\begin{equation*}
				\langle  DX_{N}, DY_{N} \rangle _{ H ^{\otimes p}} \to _{N \to \infty} p\rho \mbox{ in } L ^{2}(\Omega). 
			\end{equation*}
			\item Let $ (Y_{N}=I_{q}(g_{N}), N\geq 1) $ be a sequence of random variables in the $q$ th Wiener chaos such that $q<p$. Assume that $(Y_{N}, N\geq 1)$ is bounded in $ L ^ {2}(\Omega)$. Then 
			\begin{equation*}
				\langle  DX_{N}, DY_{N} \rangle _{ H ^{\otimes p}} \to _{N \to \infty} 0 \mbox{ in } L ^{2} (\Omega). 
			\end{equation*}

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $p_0<1$ such that for all $p>p_0$ and all $\beta>\beta_c(2)$ the following holds. 

\smallskip
\noindent \textbf{Finite volume.}  Suppose $X_t$  is the continuous-time Ising Glauber dynamics on $\mathbb{T}_n^2$ initialized from $x_0 \sim \bigotimes_{\mathbb{T}^2_n} Rad(p)$. With probability $1-o(1)$, $x_0$ is such that 
\begin{align*}
    \|\mathbb P_{x_0}( X_t\in \cdot ) - \pi_{\mathbb{T}_n^2}^+ \|_{{\textsc{tv}}} \le n^{-10} \qquad \text{for all }t\in [n^{o(1)} ,  e^{\Omega(n)}]\,.
\end{align*}
\textbf{Infinite volume.} If $X_t$ is the continuous-time Glauber dynamics on all of $\mathbb Z^2$ initialized from $x_0 \sim \bigotimes_{\mathbb Z^2} \text{Rad}(p)$, then with probability going to $1$ as $R\to\infty$, $x_0$ is such that for $\Lambda_R = \{-\frac{R}{2},...,\frac{R}{2}\}^2$, for all $t \ge R$, we have 
\begin{align*}
        \|\mathbb P_{x_0}(X_t(\Lambda_R)\in \cdot) - \pi^+_{\mathbb Z^2}(\sigma(\Lambda_R)\in \cdot)\|_{{\textsc{tv}}} \le \exp( - \Omega((\log t)^{10}))\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 33 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let $f \colon Y \to X$ be a qcqs morphism of qcqs $\F_p$-schemes.
\begin{enumerate}
\item If $Y$ is HT-split and $\cO_X \to Rf_*\cO_Y$ splits, then $X$ is HT-split.
\item If $X$ is HT-split and $f$ is \'etale, then $Y$ is HT-split.
\end{enumerate}

[Lem 15 of arXiv:2608.05185, '\large\bf ON THE HEAT FLOW CONJECTURE FOR RANDOM MATRICES'] Let \(\rho_{N,c}\) denote the one-point intensity of the eigenvalues
relative to planar Lebesgue measure.  Then
\begin{equation}
 0\leq\frac{1}{N}\rho_{N,c}(z)
 \leq\frac{1}{\pi(1-\left|c\right|^2)}
 \qquad(z\in\C).
\end{equation}
Moreover, for every \(\delta>0\), there are constants
\(C_\delta,c_\delta>0\) such that
\begin{equation}
 \int_{\{\operatorname{dist}(z,\mathscr{E}_c)>\delta\}}
 \rho_{N,c}(z)\dd A(z)
 \leq C_\delta\mathrm{e}^{-c_\delta N}.
\end{equation}
Consequently,
\[
 \frac{1}{N}\rho_{N,c}(z)\dd A(z)
 \overset{\mathrm{w}}{\longrightarrow}\mu_c.
\]

[Proposition pr:conv-fdd of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix $\lambda = 7/8$. 	Then,   $\ensuremath{\mathcal Y}_{\lambda,N}\Longrightarrow \ensuremath{\mathcal Y}$ as $N\to \infty$, 
	in the sense of finite-dimensional distributions. More specifically, we have, for all integers $k\ge 1$, times $0\le t_1<\ldots<t_k$, and test functions $\phi_1,\ldots,\phi_k \in \ensuremath{\mathcal C}_b(\mathbb{R})$,
	\begin{equation}
		(\ensuremath{\mathcal Y}_{\lambda,N}(t_1,\phi_1),\ldots,\ensuremath{\mathcal Y}_{\lambda,N}(t_k,\phi_k))\xLongrightarrow[N\to \infty]{} (\ensuremath{\mathcal Y}(t_1,\phi_1),\ldots,\ensuremath{\mathcal Y}(t_k,\phi_k))\; \text{.}
	\end{equation}

[Proposition 6 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] There exists two absolute constants $C, c>0$ such that for all $n \in \mathbb{N}$ we have
	\begin{equation*}
		\mathbf{Var}\left( E^\omega_0\left[F(W^{(n)})\right] \right) \le Cn^{-c}.
	\end{equation*}
More precisely, one can choose $c<1/2$ as close to $1/2$ as desired.

