[Lemma 14 of arXiv:2608.19753, 'Uniform large deviation principles for the stochastic heat equation over unbounded sets of'] Let Assumption \ref{asm} hold. Let $N>0$ and $q\in[1,\infty)$. 
  Suppose that $\lambda\in [0,\frac{q}{2})\cap (0,1]$ and $\tilde p\in (6,\frac{3q}{\lambda})$. 
  Then, there exists a constant $M>0$ such that for all $u\in\A_N$ and  $x\in L^q(D)$: 
  \begin{equation}
\int_0^T\int_D  |X_x^{0,u}(t,\xi)|^{\lambda \tilde p}\dd\xi\dd t \leq M(1+\|x\|_{L^q(D)}^{\lambda \tilde p}) \quad\text{a.s.}
  \end{equation}
  The value of $M$ depends only on $T,\lambda,\tilde p,q,|D|,$ and $N$.

[Lemma FejerNew of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $f:[0,1]\rightarrow \lbrack 0,1]$ be continuous and
strictly increasing, with a unique fixed point $p\in (0,1)$ and
single--crossing pattern 
\begin{equation}
f(x)>x\;\text{for }x<p,\qquad f(x)<x\;\text{for }x>p.  
\end{equation}
Then

\begin{enumerate}
\item[(i)] For every $x\in \lbrack 0,1]$, 
\begin{equation}
|f(x)-p|\leq |x-p|,  
\end{equation}
with strict inequality if $x\neq p$;

\item[(ii)] If $x,y$ lie on the same side of $p$ (both $\leq p$ or both $
\geq p$), then 
\begin{equation}
|f(x)-f(y)|\leq |x-y|.  
\end{equation}
\end{enumerate}

[Theorem 21 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Let $\{X_n;n=1,2,\cdots\}$ be a sequence of $m$-dependent and linear stationary random variables in a sub-linear space $\sles$ satisfying condition (CC). If there exists $M$ such that 
    \begin{equation}
        \Vstar\left(\limsup_{n\to\infty}\frac{|S_n|}{\sqrt{2n\log\log n}}\geq M \right) < 1,

    \end{equation}
    then 
    \begin{equation}
        C_{\V}\left[\frac{X_1^2}{\log\log |X_1|}\right]<\infty

    \end{equation}
    and
    \begin{equation}
        \lim_{n\to\infty}\frac{\bE[S_n]}{n}=\lim_{n\to\infty}\frac{\be[S_n]}{n}=0.
