[Defi Def:Weighted-Cap-Prod of arXiv:2608.29013, 'Weighted Homology and Cohomology of Weighted Polyhedra'] Suppose $(X, \lambda)$ is a descending type weighted polyhedron. Define $R$-bilinear \emph{weighted cap product} 
  $$ \Cap:  \mathcal{W}_n(X, \lambda; R)\times \mathcal{W}^p(X, \lambda; R) \rightarrow  \mathcal{W}_{n-p}(X, \lambda; R), \ 0\leqslant p\leqslant n $$ 
  by: for any cochain $\phi\in \mathcal{W}^p(X, \lambda; R)$ and any chain $\theta\in \mathcal{W}_n(X, \lambda; R)$, 
   \begin{equation*} 
   \theta  \,\Cap\, \phi := \frac{\xi\big([ v_0,\cdots, v_{p} ]\big)\xi\big([ v_p,\cdots, v_{n} ]\big)}{\xi\big([ v_0,\cdots, v_{n} ]\big)} \phi\big( \theta|_{  [ v_0,\cdots,v_{p} ]} \big) \theta|_{[ v_{p},\cdots,v_{n} ]}. 
   \end{equation*}
 The coefficient on the right hand side is integral 
  because $\xi$ is a descending weight.

[Definition defi:cLnorm of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] We equip spaces $\cV_\varnothing, \cV_{\sf o},\cV_{\sf x}$ and $\cU_{\sf ox}$ with norm
\begin{align}
	\norm{V_\varnothing}_{\cL_j (\ell)} 
		& = L^{jd} \max \big\{ \ell_{j, \varnothing}^2 L^{- q (\km_1 ) j} | \nu^{(\km_1)} | ,  \;
		\ell_{j, \varnothing}^4 L^{- q (\km_2) j} | g^{(\km_2)}|  \nnb
		& \qquad\qquad\qquad\quad :\,  \km_1 \in \ko_2 \cup \ko_{2,\nabla} ,  \,  \km_2 \in \ko_4 \cup \ko_{4,\nabla}  \big\} ,
		\\
	\norm{\sigma_\hash V_\hash}_{\cL_j (\ell)} 
		& = \ell_{j, \varnothing} \ell_{j, \sigma} \max\{ L^{-q(\km) j} |\lambda_\#^{(\km)} | : \km \in \ko_1 \cup \ko_{1,\nabla} \}  ,   \qquad \# \in \{ {\sf o}, {\sf x} \} \\
	\norm{\sigma_{\sf ox} U_{\sf ox}}_{\cL_j (\ell)} 
		& = \ell_{j, {\sigma\sigma}} \big( |q_{\sf o} | + |q_{\sf x} | \big)
\end{align}
and for $U = u_\varnothing + \sum_{* \in \{\varnothing,{\sf o},{\sf x}\}} \sigma_* V_* + \sigma_{\sf ox} U_{\sf ox} \in \cU$,  
\begin{align}
	\norm{U}_{\cL_j (\ell)} = L^{jd} |u_\varnothing| + \sum_{* \in \{ \varnothing,{\sf o},{\sf x} \}}  \norm{\sigma_* V_*}_{\cL_j (\ell)} + \norm{\sigma_{\sf ox} U_{\sf ox}}_{\cL_j (\ell)} .

\end{align}

[Lemma 10 of arXiv:2605.10609, '\Large \bf Stochastic curve shortening flow driven by a transport-type pure jump L\'evy no'] Let $u_0\in V$,  $u:=\{u(t)\}_{t\geq0}$ be the strong  solution to \eqref{c2eq6}. Then there exists a constant $k_1>0$ (independent of $t$ and $\omega$) such that for any $t\geq0$,
\begin{equation} ||u(t)||^2_H\leq ||u_0||_H^2 e^{-k_1 t},~~\mathbb{P}\text{-}a.s.
\end{equation}

