body:
[Theorem 2 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Let $\Phi$ be a continuous random dynamical system on $\mathbb X$. Suppose that $\Phi$ has a $\mathfrak D$-pullback absorbing random closed set $K\in\mathfrak D$ and is $\mathfrak D$-pullback asymptotically compact. Then $\Phi$ has a unique $\mathfrak D$-pullback random attractor given by
	\begin{align}
		\mathcal A(\omega)
		=
		\bigcap_{\tau\geq0}
		\overline{
			\bigcup_{t\geq\tau}
			\Phi(t,\theta_{-t}\omega)K(\theta_{-t}\omega)
		}^{\mathbb X},
		\qquad \omega\in\Omega.
	\end{align}
	Moreover, $\mathcal A(\omega)\subset K(\omega)$ for every $\omega\in\Omega$.

[Lemma 18 (Hilbert--Schmidt upper bound for $B$) of arXiv:2608.30722, 'Intermediate Singular Values of Random Matrices\\ under Second-Moment and Anti-Concentrati'] There exist constants $C,c,L>0$, depending only on $a$ and $b$, such that for
every $4\le l\le c_0n$,
\begin{equation}
  \bbP\!\left(
    \exists\,S\subseteq[m_l],\ |S|=l:
    \|B_S\|_{HS}>C\sqrt{\frac nl}
  \right)
  \le e^{-cl}.
\end{equation}
Moreover, in the same range, if $l\le L\log(2n)$, then for every $t\ge1$ and
every fixed $S\subseteq[m_l]$, $|S|=l$, one has
\begin{equation}
  \bbP\!\left(\|B\|_{HS} > t\sqrt{\frac{n}{l}}\right)
  \;\le\;
  \left(\frac{C}{t}\right)^l + e^{-cl}.
\end{equation}

[Proposition prop:fractionsettle of arXiv:2510.13733, 'Internal Diffusion Limited Aggregation \\ with Critical Branching Random Walks'] There exists  $c > 0 $  such that,
for each $R >0$ and $x \in B_R$,
we have
$$
\mathbb{E}
\bigg [
  \sum\limits_{z \in \partial B_R  } \big ( 
  \mathcal{\ell}^x_{B_R }(z) -  \1_{ 
   \{ \mathcal{\ell}_{ B_R}^x(z) > 0  \} }  \big )     \bigg]  \leq 
   \begin{cases} 
\displaystyle  1 -     \frac{c}{\log (R - |x|)} & \mbox{ if $d=3$} \\
\displaystyle 1 - c & \mbox{ if $d>3$}.
   \end{cases}
$$

