[Thm main-convergence of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Let $d^{{\mathrm {geo}}}$, $d^{{\mathrm {res}}}$, and $\mu$ be suitable multiples of the geodesic CLE$_6$ metric, the CLE$_6$ resistance metric, and CLE$_6$ gasket measure, respectively. There exist sequences $({\mathfrak{q}}_n^{{\mathrm {geo}}})_{n\in\mathbf N},({\mathfrak{q}}_n^{{\mathrm {res}}})_{n\in\mathbf N}$ such that for all $m$,
\begin{equation}
    \begin{split}
        (\mathcal{X}^{(m)}_n,d^{{\mathrm {path}}}_n,\mu^{(m)}_n,\pi_n)&\rightarrow (\mathcal{X}^{(m)},d^{{\mathrm {path}}},\mu^{(m)},\pi),\\
        (\mathcal{X}^{(m)}_n,d^{{\mathrm {geo}}}_n,\mu^{(m)}_n,\pi_n)&\rightarrow (\mathcal{X}^{(m)},d^{{\mathrm {geo}}},\mu^{(m)},\pi),\\
        (\mathcal{X}^{(m)}_n,d^{{\mathrm {res}}}_n,\mu^{(m)}_n,\pi_n)&\rightarrow (\mathcal{X}^{(m)},d^{{\mathrm {res}}},\mu^{(m)},\pi)\\
    \end{split}
\end{equation}
weakly with respect to the Gromov-Hausdorff-Prokhorov-function topology as $n\rightarrow\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem inv th2 of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $h \in L_{\mathbb{F}}^2 (0, T ; H^1 (G^{\prime} ) )$ and $R \in C^{1,3}(\overline{Q})$ satisfy
\begin{align}
|R(t, x)| \neq 0 \quad \text { for all }(t, x) \in[0, T] \times \bar{G} .
\end{align}
Assume that $g=g_1(t) g_2(x) \in L_{\mathbb{F}}^2 (0, T ; H^1(G) )$, where $g_1 \in L_{\mathbb{F}}^2 (0, T)$,  $ g_2 \in H^1(G)$ and $R=R_1(t) R_2(x)$. If
\begin{align*}
y \in L_{\mathbb{F}}^2 (0, T ; H^2(G) \cap H_0^1(G) )  \cap L_{\mathbb{F}}^2 (\Omega ; C ([0, T] ; H_0^1(G) ) )
\end{align*}
satisfies (system2bu of the paper) and
\begin{align*}
& \frac{\partial y}{\partial v}=0 \quad \text { on }(0, T) \times \partial G, ~ \text{${\mathbb{P}}$-a.s.},  \\
& y(T)=0 \text { in } G, ~ \text{${\mathbb{P}}$-a.s.},  \\
&
\end{align*}
then
\begin{align*}
h (t, x^{\prime} )=0 & \text { for all } (t, x^{\prime} ) \in(0, T) \times G^{\prime},~ \mbox{${\mathbb{P}}$-a.s.}
\end{align*}
and
\begin{align*}
g(t, x)=0 & \text { for all }(t, x) \in(0, T) \times G, ~ \mbox{${\mathbb{P}}$-a.s.}
\end{align*}

