[Dfn 14 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] For $\calX=(X,d^X,\rho_X,\mu_X),\;\calY=(Y,d^Y,\rho_Y,\mu_Y)\in\frK_{\bullet}(\tau)$, we define
\begin{align*}
  d^{\tau,\BL^{\kappa}}_{\frK_{\bullet}}(\calX,\calY):=\inf_{f,g,Z}\Big\{ d^Z_{\mathrm{H}}(f(X),g(Y))\vee d^Z(f(\rho_X),g(\rho_Y))\vee d^Z_{\BL^{\kappa}}(\mu_X\circ f^{-1},\mu_Y\circ g^{-1})\Big\},
\end{align*}
where the infimum is taken over all compact metric spaces $(Z,d^Z)$ and isometric embeddings $f:X\to Z$ and 
$g:Y\to Z$.

[Theorem 7 of arXiv:2606.23099, 'Path-dependent Affine Processes'] Let $X$ be an affine process on $S$ satisfying the full-support condition, Condition \ref{cond:full support_inhom} and Assumption~\ref{LG-Condition}.
    Then, there exist $b^0: [0,T]  \to \R^d$,\ $a^0 : [0,T] \to \R^{d \times d}$ and $b^i: [0,T] \to \ccM([0,T],\R^d)$, $a^i : [0,T] \to \ccM([0,T],\R^{d\times d})$, $i=1,\dots,d$, such that
    \begin{align}
        b(t,x_{[0,t]}) & = b^0(t) + \sum_{i=1}^d  b^i(t) \cdot x^i_{[0,t]}, \\

        a(t,x_{[0,t]}) & = a^0(t) + \sum_{i=1}^d  a^i(t) \cdot x^i_{[0,t]},
    \end{align}
    for all $(t,x) \in \ccC_T(S)$. Moreover, the functions $\phi$ and $\psi$ satisfy the following generalized Riccati equations
    \begin{align}
        \phi'(t,T,\mu) & = -\psi(t,T,\mu) b^0(t) - \frac{1}{2} \psi(t,T,\mu) a^0(t) \psi(t,T,\mu)^\top, \quad dt\text{-a.e. on } t \in [0,T],                   \\

        \psi(t,T,\mu)  & = \mu([t,T]) + \int_{t}^{T} \psi(s,T,\mu)B(s,\Ind_{[t,s]}) + \frac{1}{2} A(s,\Ind_{[t,s]}, \psi(s,T,\mu)) \, ds, \quad t \in (0,T],
    \end{align}
    with $\phi(T,T,\mu)=0$ and $\Psi(T,T,\mu)=\mu$,
    where $\psi$ is given by Assumption~\ref{ass:sm-diff-Psi} and $\phi'(t,T,\mu)$ denotes a Lebesgue density of $\phi$.
    Furthermore,
    \begin{align}
        \begin{split}
            \Psi(t,T,\mu) \cdot X_{[0,t]} & = \Psi(0,T,\mu) \cdot X_{[0,0]} + \int_{0}^{t} \psi(s,T,\mu) \, dX(s)                                                                                             \\
                                          & \quad - \int_{0}^{t} \sum_{i = 1}^{d} \psi(s,T,\mu) ( b^i(s) \cdot X^i_{[0,s]}) + \frac{1}{2} \psi(s,T,\mu) ( a^i(s) \cdot X^i_{[0,s]}) \psi(s,T,\mu)^\top \, ds,
        \end{split}
    \end{align}
    with
    \begin{equation*}
        \Psi(0,T,\mu)(\{0\}) = \mu([0,T]) + \int_{0}^{T} \psi(s,T,\mu)B(s,\Ind_{[0,s]}) + \frac{1}{2} A(s,\Ind_{[0,s]}, \psi(s,T,\mu)) \, ds.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 34 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $q \in (0,1)$, $c \in [0,1)$ and put $p = \frac{q}{1-q}$, $\sigma = \sqrt{p(1+p)}$. In addition, fix $\epsilon$, $\eta$, $M^{\mathrm{bot}}$, $M^{\mathrm{side}}$, $A^{\mathrm{sep}}$, $A^{\mathrm{gap}}\in (0, \infty)$, $\Delta^{\mathrm{gap}}  \in (0,1/2)$, and $k \in \mathbb{N}$. There exist $W_1 \in \mathbb{N}$ and $\delta > 0 $, depending on all previously listed constants, such that the following holds for all $n \geq W_1$. If we assume:
\begin{itemize}
\item $ \vec{y}\in \mathfrak{W}_{2k}$ as in (\ref{Eq.DefSig}), and $|y_i - pn| \leq M^{\mathrm{side}} \cdot n^{1/2}$ for $i \in \llbracket 1, 2k \rrbracket$;
\item $y_i - y_{i+1} \geq A^{\mathrm{sep}} \cdot n^{1/2}$ for $i \in \llbracket 1, 2k -1 \rrbracket$;
\item $g: \llbracket 0, n \rrbracket \rightarrow [-\infty, \infty)$ is increasing and satisfies $g(s) - ps\leq  M^{\mathrm{bot}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n \rrbracket$;
\item $y_{2k} -pn \geq g(s) - ps + A^{\mathrm{gap}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n\rrbracket$ with $s \geq n - \Delta^{\mathrm{gap}} \cdot n$;
\item for an increasing path $Q_i$ on $\llbracket 0, n \rrbracket$, we set $\mathcal{Q}_i(t)= \sigma^{-1}n^{-1/2}(Q_i(tn) - ptn)$ for $t \in [0,1]$;
\end{itemize}
then the following inequality holds for each $i \in \llbracket 1, 2k \rrbracket$
\begin{equation}
\mathbb{P}_{\ice; q,c }^{n, \vec{y},  g}\left( w(\mathcal{Q}_i, \delta) > \eta \right) < \epsilon.
\end{equation}

