[Theorem of arXiv:2608.10415, 'Continuous random variables'] With the above notion of discrete probability measure in hand:
\begin{enumerate}
\item A discrete probability space is simply a space $X$, with a discrete probability measure on it $\nu$. In this picture, the probability function is $P(x)=d\nu(x)$.

\item Each random variable $f:X\to\mathbb R$ has a law, which is a discrete probability measure on $\mathbb R$. This law is given by $\mu=f_*\nu$, push-forward of $\nu$ by $f$.
\end{enumerate}

[Proposition 26 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\in[5/2,3)$. For every $t\in[0,T]$,
    \begin{align*}
        &\mathbb{E}\left[\sup_D\left(\sum_{i=0}^{n-1} \Big\lVert\left(\augpr{X}^{\mu,2}_{t_{i+1}}-\augpr{X}^{\mu,2}_{t_i}\right)-\left(\augpr{Y}^{\nu,2}_{t_{i+1}}-\augpr{Y}^{\nu,2}_{t_i}\right)\Big\rVert^{p/2}_{(\mathbb{R}^{d+1})^{\otimes 2}}\right)^2\right]\\
        &\leq \widetilde{C}\int_0^t\left(\mathbb{E}\left[\big\lVert\augpr{X}^{\mu}-\augpr{Y}^{\nu}\big\rVert_{\textup{$p$-var};[0,s]}^p\right] + \int_{\widehat{G\Omega}_p(\mathbb{R}^{d+1})\times \widehat{G\Omega}_p(\mathbb{R}^{d+1})}C_s\lVert x-y \rVert_{\textup{$p$-var};[0,s]}^p\pi(dx,dy)\right)ds,,
    \end{align*}
    where $D=D_{[0,t]}$ is a partition of $[0,t]$, $\widetilde{C}=\widetilde{C}(p,T,L,M_b,M_\sigma)$, $C_s=C_s(d,p,N,T,\alpha_\infty,\Gamma_s)$, $\alpha_\infty:=\max_{0\leq |I|\leq N}|\alpha_I|$ where $\alpha_I$ are the coefficients in \eqref{eq:linear_comb_in_sig_MKV_SDE}, $\Gamma_s:=\max\{\lVert x\rVert_{\textup{$p$-var};[0,s]},\lVert y\rVert_{\textup{$p$-var};[0,s]}\}$, and $\pi\in\Pi(\mu,\nu)$ is an arbitrary coupling of $\mu$ and $\nu$.

[Definition 14 (Analytic Calder\'on symbol space) of arXiv:2609.01116, 'Vector-Carleson, Calder\'on, and Poisson--Atomic Criteria for\\ Generalized Hilbert Operat'] For an admissible resolution $\sigma$, put
\[
 \mathcal D_{p,\sigma}\phi
 =\bigl(2^{-j/p'}W_j^\sigma\phi\bigr)_{j\ge0}
 \tag{4.17}
\]
and define
\[
\begin{split}
 \mathfrak C_p^\sigma
 &=\{\phi\in\Hol(\D):
     \mathfrak G_p(\mathcal D_{p,\sigma}\phi)<\infty\},\\
 \|\phi\|_{\mathfrak C_p^\sigma}
 &=|\phi(0)|+\mathfrak G_p(\mathcal D_{p,\sigma}\phi).
\end{split}
 \tag{4.18}
\]

[Theorem thm:nonzero of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Let $(M,g)$ be a compact Riemannian manifold of dimension $n\ge 2$ without conjugate points. Let us consider the monochromatic case: $\phi_\ell:=\phi_I^M$, with $I=[\ell-\eta_\ell, \ell]$, where $\eta_\ell=\mathrm{o}(\ell)$. Assume in addition that: if the dimension is $n=2$, then $\eta_\ell\log\ell=\mathrm{O}(\ell)$. Then, we have
      \begin{equation}
{\mathbb{V}\mathrm{ar}}\left( \frac{\mathrm{Vol}^{n-1}(\{x:\phi_\ell(x)=t\sigma_\ell(x)\})[2]}{\lambda_\ell}\right)\ge\Theta\left( \frac{1}{N^M_{[\ell-\eta_\ell,\ell]}}\right),
    \end{equation}
where $\sigma_\ell(x)^2:={\mathbb{V}\mathrm{ar}}(\phi_I^M(x))$ and $\lambda_\ell:=\lambda\left( \phi_{[\ell-\eta_\ell,\ell]}^M\right)$.

[Lem 27 of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] The kinetic solution $u^{h}_{\alpha}$ of \eqref{eq:skeleton-obstacle-problem-viscous} converges to the kinetic solution $u^{h}$ of \eqref{eq:skeleton-obstacle-problem} uniformly on $h\in S_M$. That is,
  \begin{align}
  \lim_{\alpha\rightarrow 0}\sup_{h\in S_M}\Vert u^{h}_{\alpha}-u^{h}\Vert _{L^1(Q_T)}=0.
\end{align}

