[Lemma 8 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Let $-\alpha<u<0$ and $v>u$. 
Then , as $N\to\infty$,
\begin{equation}
R_{N,N-1}:=1+\zeta_{N,1}+\zeta_{N,1}\zeta_{N,2}+\ldots+\zeta_{N,1}\zeta_{N,2}\ldots \zeta_{N,N-1}{\Rightarrow}
R,
\end{equation}
where $R=\lim_{n\to\infty} R_n$   is   given by \eqref{Rseries}; furthermore,
\begin{equation}
\lim_{N\to\infty}\,\mathbb E\,[R_{N,N-1}^{-u-v}]\,=\,\mathbb E\,[R^{-u-v}].
\end{equation}

Let $-\alpha<v<0$ and  $v<u$. 
Then, as $N\to\infty$, \begin{equation}
  R_{N,N-1}':=1+  \zeta_{N,1}'+  \zeta_{N,1}'  \zeta_{N,2}'+\ldots+
  \zeta_{N,1}'  \zeta_{N,2}'\ldots   \zeta_{N,N-1}'{\Rightarrow} 
  R',
\end{equation}
where $  R'=\lim_{n\to\infty}   R_n'$  is  given by \eqref{Rseries2}; furthermore,
\begin{equation}
\lim_{N\to\infty}\,\mathbb E\,[  (R_{N,N-1}')^{-u-v}]\,=\,\mathbb E\,[ (R')^{-u-v}].
\end{equation}

[Proposition prop:d-dbox-derivations of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] (1) $\textbf{WKD} \vdash \textsf{D}_\Box$.
  (2) $\textbf{KI} + \textsf{D}_\Box \vdash \textsf{D}$.
  (3) $\textbf{CKD} \nvdash \textsf{D}_\Box$.\\
  (4) $\textbf{IK} + \textsf{D}_\Box \nvdash \textsf{D}$.
  \begin{proof}
    The following derivations prove (1) and (2), respectively.
    \begin{center}
      \AxiomC{$ $}
      \RightLabel{\scriptsize{$\textsf{D}$}}
      \UnaryInfC{$\Box \bot \to \Diamond \bot$}

      \AxiomC{$ $}
      \RightLabel{\scriptsize{$\textsf{N}_\Diamond$}}
      \UnaryInfC{$\Diamond \bot \to \bot$}

      \RightLabel{\scriptsize{Syll.}}
      \BinaryInfC{$\Box \bot \to \bot$}
      \DisplayProof
    \end{center}

    \begin{center}
      \AxiomC{$ $}
      \UnaryInfC{$\varphi \to (\varphi \lor \bot)$}
      \RightLabel{\scriptsize{$\textsf{M}_\Box$}}
      \UnaryInfC{$\Box \varphi \to \Box (\varphi \lor \bot)$}

      \AxiomC{$ $}
      \RightLabel{\scriptsize{$\textsf{CD}$}}
      \UnaryInfC{$\Box(\varphi \lor \bot) \to (\Diamond \varphi \lor \Box \bot)$}

      \RightLabel{\scriptsize{MP}}
      \BinaryInfC{$\Box \varphi \to (\Diamond \varphi \lor \Box \bot)$}

      \AxiomC{$ $}
      \RightLabel{\scriptsize{$\textsf{D}_\Box$}}
      \UnaryInfC{$\Box \bot \to \bot$}
      \UnaryInfC{$\Box \bot \to \Diamond \varphi$}

      \RightLabel{\scriptsize{Syll.}}
      \BinaryInfC{$\Box \varphi \to \Diamond \varphi$}
      \DisplayProof
    \end{center}
    (3) and (4) are left for the reader as easy exercises. See also Figure (fig:d-countermodels of the paper).
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LvarF of arXiv:2510.22701, 'Gaussian fluctuations in Mean Field Stable matchings'] With $\kappa_n\geqslant \log^{4} n$, there is a constant $C>0$ such that 
    \begin{align*}
        \mathrm{Var}\bclr{W_{n,2}}\leqslant \begin{cases}
            C\kappa_n^{1-2/d},&1< d<2;\\
            C \log n,& d=2;\\
             C n^{1-2/d} , &d>2.
        \end{cases}
    \end{align*}

