[Corollary cor:stoch_int_bd of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Let $s\in (0,d/2)$. For every $(\mathcal{F}_t)_t$-progressively measurable process $M$ with paths in $L^2_t(H^{-s}_{\div})$ $\mathbb{P}$-a.s., the stochastic integral
	\begin{align*}
		N_t:= \int_0^t B[M_r] \,\mathrm{d} W^\mathcal{K}_r
	\end{align*}
	is a well-defined local martingale with values in $\dot{H}^{-s-1}_{\div}$ and the following bound holds for its quadratic variation $[N]$:
	\begin{align} 
		\trace_{\dot{H}^{-s-1}_{\div}}[N]_t  = \int_0^t \| B(M_r) \|^2_{\operatorname{HS}(H^{d/2 + \alpha}_{\div}; \dot{H}^{-s-1})} \,\mathrm{d} r \lesssim \int_0^t \|M_r\|_{H^{-s}}^2 \,\mathrm{d} r.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:complement_r_connected}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and let $R \in \mathbf{N}$ be as in (prop:boundary_connectivity of the paper).

    Let $b \in \mathbf{N}$ and let $\mathbf{A} = (A_0,\ldots,A_{b-1}) \in \mathcal{A}(b)$ be a sequence of $1$-disconnected blocks. Then the set $G \setminus \mathbf{A}$ is $R$-connected.

[Definition 23 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] A sequence $(u_{\varepsilon})_{\varepsilon\in E}\subset 	W^{1}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega))$ is said to be weakly stochastically $\Sigma$-convergent (for $A$) in $	W^{1}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega))$ to some $u_{0} \in 	W^{1}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega;\mathcal{X}_{A}^{\Phi}))$ if there exist two  functions $u_{1} \in L^{1}\left(Q; W^{1}_{\#}L^{\Phi}(\Omega)\right)$ and $u_{2}\in L^{1}(Q\times\Omega; W^{1}_{\#}\mathcal{X}_{A}^{\Phi})$ such that as $E \ni \varepsilon \to 0$, we have 
		\begin{itemize}
			\item[(i)] $u_{\varepsilon} \rightarrow u_{0}$ in $L^{\Phi}(Q\times\Omega)$-weak $\digamma\,\Sigma$,
			\item [(ii)] $\frac{\partial u_{\varepsilon}}{\partial x_{i}} \rightarrow \frac{\partial u_{0}}{\partial x_{i}} + \overline{D}_{i,\Phi}u_{1} + \frac{\overline{\partial} u_{2}}{\partial y_{i}}$ in $L^{\Phi}(Q\times\Omega)$-weak $\digamma\,\Sigma$, $1 \leq i \leq d$.
		\end{itemize}
		We then express by: $u_{\varepsilon} \rightarrow u_{0}$ in $W^{1}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega))$-weak $\digamma\,\Sigma$, and we refer to $u_{0}$ as the weak stochastic $\Sigma$-limit in $W^{1}L^{\Phi}_{D_{x}}(Q; L^{\Phi}(\Omega))$ of $(u_{\varepsilon})_{\varepsilon\in E}$. The functions $u_{1}$ and $u_{2}$ are the stochastic corrector and deterministic corrector for $(u_{\varepsilon})_{\varepsilon\in E}$, respectively.

[Lemma adapted4 of arXiv:2507.20324, 'Non-existence of several random fractals in Brownian motion and Brownian loop soup'] For any integer $1\leq i\leq[L/2]$, on the event $\{S\in\mathfrak{S}_{n}(\delta+2^{\sqrt{n}})\}\cap(\cap_{j=1}^{6}B_{j}^{c})$, whether a box $T\prec\mathcal{A}_{i}$ is $\delta$-good can be fully determined by $\overline{U}_{(i+4)L}$.
\par
As a direct consequence, $N_{i}$ is $\mathscr{F}_{(i+4)}$-measurable under the probability measure $\overline{\mathbb{P}}_{n}$, which is defined by
\begin{equation}
\overline{\mathbb{P}}_{n}(\cdot):=\mathbb{P}(\cdot|S\in\mathfrak{S}_{n}(\delta+2^{-\sqrt{n}}),\cap_{j=1}^{6}B_{j}^{c}).
\end{equation}

[Lemma l:55 of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] For each $ m \in \zN $, the following hold: 
\\\thetag{i} 
$(\Emum , \dbmum ) $ is closable on $ \Lmm $.
\\\thetag{ii} 
$(\Emum , \dcmum ) $ is closable on $ \Lmm $. (Proof in the paper; no proof environment follows the statement in the TeX.)

