body:
[Theorem thm:Okura of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] \begin{enumerate}[(i)]
    \item The Dirichlet form $(\mathcal{E}^S,\mathcal{F}^S)$ is regular.
    \item $\mathcal{F} \subset \mathcal{F}^S$.
    \item $(\mathcal{E}^S,\mathcal{F}^S)$ is pure-jump type and has the following explicit formula
  \begin{equation}
      \mathcal{E}^S(f,g) = \int_{M \times M} (u(x)- u(y))(v(x) - v(y)) J(x,y) d\mu(x)d\mu(y),\quad f,g \in \mathcal{F}^S,
  \end{equation}
  where the jump kernel $J(x,y)$ is 
  \begin{equation}
    J(x,y) = \frac{1}{2}\int_0^\infty p(t,x,y)d\nu(t).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2608.29747, 'Reduced Khovanov-Rozansky homology'] \cite[attributed to Ocneanu]{Jones1987Hecke}
For each $n \in \N$, there exists a unique $T$-module homomorphism $\mathrm{Tr}_n: \mathrm{H}_n \to \Z[a^{\pm 1}, q^{\pm 1}, \frac{1}{q-q^{-1}}]$ such that
\begin{enumerate}
    \item $\mathrm{Tr}_n (BB') = \mathrm{Tr}_n (B'B)$ for all $B, B' \in \mathrm{H}_n$,
    \item $\mathrm{Tr}_{n+1} (i(B)) = \{0\} \mathrm{Tr}_{n}(B)$ and $\mathrm{Tr}_{n+1} (i(B)B_{n}) = \{1\} \mathrm{Tr}_{n}(B)$ for all $B \in \H_n$, and
    \item $\mathrm{Tr}_{1} (1) = 1$,
\end{enumerate}
where $i : H_n \to H_{n+1}$ is the inclusion map that sends $B_j \mapsto B_j$ for all $j \in \{1, \dots, n-1\}$ and $\{n\} = \frac{aq^{-n}-a^{-1}q^n}{q-q^{-1}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture Pure partition function- Coulomb gas integral of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] For irrational $\kappa \in(0,8)$, the pure partition functions are related to Coulomb gas integrals by affine meander matrix:
\begin{equation}
\mathcal{J}_\beta^{(m,n)}(\boldsymbol{\theta})=\sum_{\alpha \in \operatorname{LP}(n,m)} \mathcal{M}_{\kappa}(\alpha, \beta) \mathcal{Z}_\alpha(\boldsymbol{\theta}), \quad  \beta \in \mathrm{LP}(n,m).
\end{equation}

Conversely, we have 

\begin{equation}
\mathcal{Z}_\beta(\boldsymbol{\theta})=\sum_{\alpha \in \operatorname{LP}(n,m)} \mathcal{M}_\kappa(\alpha, \beta)^{-1} \mathcal{J}_\alpha^{(m,n)}(\boldsymbol{\theta}), \quad  \beta \in \mathrm{LP}(n,m).
\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma bootstrap of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $g$ be sufficiently small,  $\mu \in ( \frac{\kt}{2}, \kt)$,  and suppose $(x_j, y_j)_{j\ge 0} \in X_j \times Y_j$ are such that
\begin{align}
	\norm{x_0}_{X_0} \lesssim \ell_0^2 g ,  \quad \norm{y_0}_{Y_0} \lesssim \ell_0^4 g  ,  \qquad
	\norm{x_j}_{X_j}, \norm{y_j}_{Y_j} \le C_1 g r_j^{\mu} \;\;	
	 \text{for some } C_1 > 0
\end{align}
and $(x_{j+1}, y_{j+1}) = (\bar\Phi_{j+1}^{{\operatorname{pt}}, X},  \bar\Phi_{j+1}^{{\operatorname{pt}},Y} ) (x_j, y_j)$ for each $j \ge 0$.  Then for each $j\ge 0$,
\begin{align}
	\norm{x_j}_{\cV_j (\ell)} \lesssim \ell_0^2 g r_j , \qquad 
	\norm{y_j - y_0 }_{\cV_j (\ell)} \le O_L (1) g^2 r_j .

\end{align}

