[Definition def.renormterm of arXiv:2607.10105, 'The four-dimensional Anderson model: a case study for critical SPDEs'] Given $m$ and $\kappa$ and  functions $(G_0,\cdots,G_m)$ with $G_j\in\mathcal E$, we define the renormalization $\mathcal R\mathcal I_{m,\kappa}$ of $\mathcal I_{m,\kappa}$, inductively, as follows:
\begin{enumerate}
\item If there is no fully paired subinterval of $[1,m]$ (and $[1,m]$ itself is not fully paired), then $\mathcal R\mathcal I_{m,\kappa}=\mathcal I_{m,\kappa}$;
\item Otherwise, choose the \emph{smallest (with respect to inclusion) and leftmost} fully paired subinterval $[p+1,p+2q]$ (this could be $[1,m]$). Then:
\begin{enumerate}
\item The indices in $[1,p]\cup[p+2q+1,m]$ are linearly ordered, with a natural partial pairing $\kappa'$, which is inherited from $\kappa$.
\item For $z,w$, denote $x_{p+1}:=z$ and $x_{p+2q}:=w$, and define
\begin{equation}J(z-w):=\lambda_\varepsilon^{2q}\int_{(\mathbb T^4)^{2q-2}}\prod_{j=p+1}^{p+2q-1} G_j(x_j-x_{j+1})\prod_{\{i,j\}\in\kappa}\eta_\varepsilon(x_i-x_j)\,\mathrm{d}x_{p+2}\cdots\mathrm{d}x_{p+2q-1}.
\end{equation}
\end{enumerate}
\item Then, define (inductively)
\begin{align}
\mathcal R\mathcal I_{m,\kappa}[G_0,\cdots,G_m]&:=\mathcal R\mathcal I_{m-2q,\kappa'}[G_0,\cdots,G_{p-1},\widetilde{G},G_{p+2q+1},\cdots G_m],\\

\widetilde{G}(x-y)&:=\int_{(\mathbb T^4)^2}G_p(x-z)\bigg(J(z-w)-\int_{\mathbb T^4}J \cdot \boldsymbol{\delta}(z-w)\bigg)G_{p+2q}(w-y)\,\mathrm{d}z\mathrm{d}w,
\end{align} with $J$ defined in ((eq.setup_5 of the paper)). Here it is easy to check that $\widetilde{G}\in\mathcal E$.
\end{enumerate}

[Lemma 23 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] There exists a constant $C_1 \in (0,\infty)$ depending only on $\alpha,\alpha_0,\varepsilon,A$, and $U$ such that the following holds with probability at least $1-\varepsilon/50$. Fix $z \in U$. For $n \in \NN$, we let $z_n \in (e^{-n-100} \ZZ^2) \cap B_1(U)$ be chosen such that $z \in B_{e^{-n-99}}(z_n)$. Then, for all $t \in [n+1,n+2]$, we have that
\begin{equation*}
    h_{e^{-t}}(z) \leq h_{e^{-n}}(z_n) + C_1 + \left(\frac{2(2t - h_{e^{-t}}(z))}{A}\right)
\end{equation*}
 and
\begin{equation*}
    2n - h_{e^{-n}}(z_n) \leq 2(2t - h_{e^{-t}}(z)) + C_1.
\end{equation*}

