[Lem eq:inside:L:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] For every fixed $y \neq x$ and $\delta,\upsilon\geq 0$, $\varepsilon > 0$ set:
\begin{equation*}
    J_{\delta,\upsilon,\varepsilon}(y):=\mathbb{N}_{y}\Big(\sup_{t\geq 0}\Big|L_t(\rho,W)- \varepsilon^{-1}\int_{0}^{t} {\mathrm{d}} s \,  \mathbbm{1}_{\{\uptau_{\delta, \upsilon}(W_s)<H(\rho_s)<\uptau_{\delta, \upsilon}(W_s)+\varepsilon<\uptau(W_s) \}}\Big|\Big).
\end{equation*}
The following properties hold:
\begin{itemize}
\item[$\mathrm{(i)}$] $J_{\delta, \upsilon,\varepsilon}(y)\leq 2$;
\item[$\mathrm{(ii)}$] $ \limsup_{\upsilon \to 0} \limsup_{\varepsilon \to 0} J_{0,\upsilon,\varepsilon}(y)=0$. 
\end{itemize}

[Theorem 13 (Lam\'e transversality) of arXiv:2608.30174, 'Exact counting of spherical metrics with one conical singularity on rectangular tori'] We have
\begin{equation}
 \frac{\dd}{\dd B}\mathrm{Im}\tr(M_h(B)M_v(B))\bigg|_{B=B_0}\ne0.
\end{equation}

[Lem theta of arXiv:2506.10623, 'Polynomial slowdown in an angle-dependent 2d branching Brownian motion'] For any $\eta>0$, there exists $c>0$ such that, for any $a \geq 0$, for $t$ large enough,
	\begin{align*}
	\Pp{ \exists u \in \mathcal{N}(t) : 
		R_u(t) \geq m(t)-a, \max_{s\in [t/2,t]} \mathopen{}\mathclose\bgroup\originalleft\lvert\theta_u(s)\aftergroup\egroup\originalright\rvert > \eta }
	\leq e^{-ct}.
	\end{align*}

