d\big(z^2_t + r_{2}^{\frac{2}{2-n/p}} z^{2}\big) = 2 z_t d z_t + (dz_t)^2 + 2 r_{2}^{\frac{2}{2-n/p}} z z_{t}.
\end{align*}

