body:
[Theorem 1 of arXiv:2604.09248, '\bfseries Limit laws for longest edges in empty region graphs'] For any of the empty region graphs from Examples \ref{ex:Gabriel}--\ref{ex:ConvBody}, we have $\xi_t \overset{d}{\longrightarrow} \zeta$ as $t \to \infty$, where $\zeta$ is a Poisson process with intensity measure $\vol \otimes \mu \otimes\nu$. More precisely, for any set $W \in \mathcal{B}(\RR^d)$ with $\vol(W)<\infty$ and any $b \in \RR$, it holds that
    \[
    \mathrm{d}_{\mathrm{KR}} (\xi_t|_{W \times [b, \infty)\times\LL^d}, \zeta|_{W \times [b, \infty)\times\LL^d}) \le \begin{cases}
        c\log^{-(d-2)}(t), & d \ge 3,\\
        c\log^{-1/2}(t), & d=2,
    \end{cases}
    \]
for any $t \ge 2$. Here, $c\in(0,\infty)$ is a constant which only depends on $d$, $\vol(W)$, $b$, and the parameters of the particular example. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 28 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] Fix~$R\geq 1$ and a configuration~$\omega$. We say that there exists a \emph{double four-petal flower domain} between~$\Lambda_{R}$ and~$\Lambda_{2R}$ if
\begin{itemize}
    \item~$\Fout$, the outer flower domain on~$\Lambda_{2R}$ is well-separated and has exactly four petals $\Pout_1,\dots,\Pout_4$;
    \item~$\Fin$, the inner flower domain on~$\Lambda_R$ is well-separated and has exactly four petals~$\Pin_1,\dots,\Pin_4$;
    \item~$\Pin_1$ is connected to~$\Pout_1$ and~$\Pin_3$ to~$\Pout_3$ in~$\omega\cap \Fin^\comple\cap\Fout^\comple$;
    \item~$\Pin_2$ is connected to~$\Pout_2$ and~$\Pin_4$ to~$\Pout_4$ in~$\omega^*\cap \Fin^\comple\cap\Fout^\comple$.
\end{itemize}

[Corollary 5 of arXiv:2605.21005, 'Double-transform Tauberian method\\ for precise large deviations'] Let $(S_n,C_n)_{n\in\N_0}$ be as in~\eqref{eq:CCprocess}, with $Y_1=|X_1|$ and $\P(X_1<-x)=\P(X_1>x)\sim \ell(x) x^{-\beta}/\Gamma(1-\beta)$ as $x\to\infty$ for some $\ell(x)$ positive slowly varying function, $\beta\in(0,1)$. Then, for $( x_n)_{n\in\N}$ such that $ x_n\to\infty $ and $n/ x_n^\beta\to 0$ as $n\to\infty$, we have
\begin{equation}
\lim_{n\to\infty}\sup_{x\geq x_n}\left| \frac{\P(C_n>x,\cT^->n)}{2n\P(\cT^{-}>n)\P(X_1>x)}-1\right|=0.
\end{equation}

[Theorem 5 (\cite{aggarwal2020limit}, Theorem 1.1) of arXiv:2604.06532, 'Random permutations from $q$-Demazure products'] Fix $\varepsilon>0$ and let $G(u,v)$ be the entropy solution to the conservation law
  \begin{equation}

    \frac{\partial}{\partial v} G(u,v) + \frac{\partial}{\partial u} \left( \varphi(G(u,v))\right) = 0,
  \end{equation}
  on the cylinder $\mathbb{T} \times [0, \lambda]$, with initial data given by $G(u,0) = \Psi(u)$ and the flux $\varphi(\cdot)$ defined as in \cref{eq:flux_def}.
  For each $M \geq 1$, let $\nu^{(M)} = (\nu_v (u))$ be the particle configuration associated to the sampled stochastic six-vertex configuration on the cylinder $\mathfrak{C}_{M,L}$ described above.
  Then,
  \begin{equation}
    \lim_{M \to \infty} \mathbb{P} \left[ \max_{\substack{0 \leq U_1 \leq U_2 < M \\ 0 \leq V_1 \leq V_2 \leq L}} \left|\frac{1}{M^2}\sum_{j=V_1}^{V_2} \sum_{i=U_1}^{U_2} \nu_{j} (i) - \int_{V_1/M}^{V_2/M}\int_{U_1/M}^{U_2/M} G(u,v) \,du \,dv \right| > \varepsilon \right] = 0.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

