    \begin{equation}

        \liminf_{N \to \infty} \inf_{z \in \cC_N}\frac{1}{|B_z|}\sum_{y \in B_z} \IND_{\{ g_{U_z}^\omega(y,y) \geq \overline{g} - \varepsilon \}} \geq q \,.
    \end{equation}

