	\mathrm{trans}(\widetilde\rho_t(\ell_1\ell_2)) = h_1 + h_2 \ \ \ \ \ \mathrm{trans}(\widetilde\rho_t(\ell_1\ell_2\ell_3)) = h_1 + h_2 + h_3
\end{equation*}
\begin{equation*}
	\mathrm{trans}(\widetilde\rho_t(\lambda)) = h_1+h_2+h_3+h_4
\end{equation*}

