[Theorem thm:stat.dist.alpha>0.beta>lambda0 of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] Let $X=(N,\Lambda,C)$  be a self-exciting PDMP with resetting and $Y=(N,\Lambda)$. Under Assumption (a:finitereset of the paper) holds and with $\alpha>0\ \&\  \beta>{\lambda^o}$, $Y$ has invariant measure $\Pi$ on $\mathbb N_0\times[{\lambda^o}, A)$, given by the following:

\begin{equation} 
    \Pi(n, d\lambda)=\pi(n,\lambda)d\lambda 

\end{equation}
    whose density is defined as

\begin{equation} 
  \begin{split}
    \pi(0,\lambda)=&\mathds{1}_{\{\lambda <\beta\}}\frac{K_0}{\alpha  (\beta -{\lambda^o})} \left(\frac{\beta -\lambda }{\beta -{\lambda^o}}\right)^{\frac{\beta -\alpha }{\alpha }} e^{\frac{\lambda - {\lambda^o}}{\alpha}},\\
    \pi(n,\lambda)=&\mathds{1}_{\{\lambda<\beta\}}\frac{1}{F(\lambda)}\int_{{\lambda^o}}^{\lambda} \frac{F(y)p(n-1,y)}{\alpha(\beta-y)}dy\\
    &+\mathds{1}_{\{\lambda\geq \beta\}}\frac{1}{F(\lambda)}\int_{\lambda}^{A} \frac{F(y)p(n-1,y)}{\alpha(y-\beta)}dy, \quad n\geq 1.
  \end{split}

\end{equation}
  For $n\ge 0$, 

\begin{equation} 
    p(n,\lambda) = \int \mathds{1}_{\{u+{\lambda^o}<\lambda\}} (\lambda-u) \pi(n,\lambda-u)\,dG_{\ell}(n+1, u),

\end{equation}

\begin{equation} 
    F(\lambda)=\exp(-\frac{\lambda}{\alpha})|\lambda-\beta|^{\frac{\alpha-\beta}{\alpha}},

\end{equation}
  and $K_0=\sum_{n=1}^\infty \int_{[{\lambda^o},A)} \lambda \bar{G}_{\ell}(n, (A-\lambda) \textrm{-}) \Pi(n-1, d \lambda)$.

[Lemma 4 of arXiv:2604.10142, 'H\MakeLowercase{arnack inequality for} $p$\MakeLowercase{-harmonic functions: \\ improved '] Let $u$ be a positive continuous function on $B_5(0)\subset \R^d$ with $u(0)=1$. Suppose that there exist     $A\geq 1$ and   $\gamma>0$ such that for all $0<r<R$ and $|x|< 2$,
    \begin{equation}
        \mathrm{osc}(u,B_r(x))\leq A\left(\frac{r}{R}\right)^\gamma \mathrm{osc}(u,B_R(x)) \,.
    \end{equation}
   Assume also that there exist $C>0$ and $\lambda>0$ such that  for all $r\leq 1$  and $|x|< 2 -r$,
    \begin{equation}
        \inf_{B_r(x)}u\leq C r^{-\lambda} \,.
    \end{equation}
     Then
    \begin{equation}
        \sup_{B_1(0)}u\leq 4C\exp\left(\lambda\left(\frac{1}{\gamma}\log4A+2\log 2\lambda\right)\right)
    \end{equation}

