[Lemma 13 of arXiv:2606.14564, 'Upper tails for irregular graphs \\ beyond the mean-field regime'] For every nonempty graph $J$ without isolated vertices and all $0 \le B \le 2A$, the solution to $\mathcal{P}(J;A,B)$ is
  \begin{equation}

    (v_J - \alpha_J^*) \cdot B + (2\alpha_J^* - v_J) \cdot \min\{A, B\}.
  \end{equation}
  Moreover, if $J$ is bipartite, then there is an optimal solution $x$ that takes the value $\max\{0, B-A\}$ on all vertices of some vertex cover of $J$.

[Lemma 5 of arXiv:2604.27519, 'Quantitative homogenization of the maximal action of curves in a Brownian potential'] \begin{align}
 A^+_L\le A^+_{L/l,0}+(L/l)^{-1}\sum_{n=1}^{L/l} A_{l,n}^+(\Pi(h^*_{\ge l}))

\end{align}

where as before $ A_{L/l,0}^{+}=_{\rm law} A_{L/l}^+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2607.08129, '2607.08129'] The rate function $I_\theta$ is convex.  If $I_\theta(f)<\infty$, then $f$ is absolutely continuous and nondecreasing, satisfies $f(0)=0$, and obeys
\begin{equation}
 0\le f(t)\le t,
 \qquad 0\le t\le1.
\end{equation}
For every admissible representation $f=\mathcal T a$,
\begin{equation}
 f'(t)=\sum_{k\ge1}\frac1k a_k(t/k)
 \quad\text{for a.e. }t\in(0,1).
\end{equation}
The unique zero of $I_\theta$ is
\begin{equation}
 \bar f_\theta(t)=c_\theta t.
\end{equation}
Furthermore,
\begin{equation}
 I_\theta(0)=+\infty.
\end{equation}

[Theorem 20 of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] Let $L$ be an oriented link. Then
\begin{enumerate}
    \item $\sigma_2(L)$ is an invariant class in $H_2(L,\Z)$;
    \item $\sigma_3(L)$ is an invariant class in $H^-_3(L,\Z)$;
    \item $\sigma_4(L)$ is an invariant class in $H^+_4(L,\Z)$.
\end{enumerate}
The invariance of $\sigma_n(L)$ means that for any isotopy $f\colon L\to L'$,
\[
\sigma_n(L')=f_*(\sigma_n(L))\in H_n(L',\Z),\quad n=2,3,4.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

