body:
[Prop equiv-thom-from-global of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] The square
    \begin{equation}
        \begin{tikzcd}
            \ul\Spc^\otimes_{{\vphantom{\textup{t}}\smash{\textup{Orb}}}\triangleright\textup{Glo}/\ul\textup{VRep}^{\oplus}}\arrow[d,"L"']\arrow[r,"\ul{\textup{Th}}^\otimes"] &[.5em] {\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}^\otimes\arrow[d,hook]\\
            \ul\Spc_{\textup{Glo}/\ul\textup{VRep}^{\oplus}}^\otimes\arrow[r,"\ul{\textup{Th}}_\textup{gl}^\otimes"'] & {\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}^\otimes
        \end{tikzcd}
    \end{equation}
    of symmetric monoidal global functors commutes up to canonical equivalence, where the map on the left is the unique symmetric monoidal left adjoint compatible with the Yoneda embeddings and the map on the right is the unique symmetric monoidal left adjoint.
    \begin{proof}
        By construction, both paths through the diagram are symmetric monoidal ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-cocontinuous functors extending ${\mathpalette\ulhelper{\mathfrak J}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}^\otimes$, so the claim follows from the universal property of ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-cocompletion.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm2.2 of arXiv:2606.01944, 'Propagation of Chaos for Mean-field Mean Reflected Backward Stochastic Differential Equati'] Under Assumptions (H1)-(H4), the mean-field mean reflected BSDE associated with $(\xi,f,h)$ admits a unique solution $(Y,Z,K)\in \mathcal{S}^2\times\mathcal{H}^2\times I[0,T]$. Moreover, for each $t\in[0,T]$, we have 
 \begin{align*}
     K_T-K_t=\sup_{s\in[t,T]}L_s(\bar{Y}_s), 
 \end{align*}
 where
 \begin{align*}
\bar{Y}_s:=\mathsf{E}\left[\xi+\int_s^T f(r,Y_r,\mathsf{E}[Y_r],Z_r,\mathsf{E}[Z_r])ds\Big|\mathcal{F}_s\right].
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 17 of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The probabilities ${p}^{\alpha,\rho}_n(t)=\Prob\{N(\mathcal{L}^{\alpha,\rho}(t))=n\}$ satisfy the following  equation
	\begin{equation}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) p_n^{\alpha,\rho}(t) = -\lambda(p_n^{\alpha,\rho}(t) - p_{n-1}^{\alpha,\rho}(t)), \quad n \ge 0,
	\end{equation}
	with the standard initial condition, and  the probability generating function $
	{G}_{\alpha,\rho}(u, t)$, $|u| \leq 1$, solves the equation
	\begin{equation*}
		\left({\mathcal D}^{2\alpha,\rho}_t + {\mathcal D}^{\alpha,\rho}_t\right) G_{\alpha,\rho}(u, t) = \lambda(u - 1)G_{\alpha,\rho}(u, t), 
	\end{equation*}
	with $G_{\alpha,\rho}(u, 0) = 1$; the generalized fractional derivatives  in the C-D sense are defined in \eqref{exfDt}.

[Defn embedded-map of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] An \textbf{embedded map} is a pair $M = (m,\psi)$ where
\begin{enumerate}
	\item $m=\{m_1,\dots,m_r\}$ is a multiset of $r$ maps (with or without boundary and of any genus) with the following two properties (see the top of Figure~(fig-embedded-maps-exemp of the paper)):
	\begin{enumerate}
		\item[(1a)] The dual graph of each component of $m$ is bipartite. The faces of $m$ in one partite class are called \textbf{blue faces} and those in the other class are called \textbf{yellow faces}.
		\item[(1b)] The external faces of each component of $m$ with boundary are yellow faces.
	\end{enumerate}
	We call a multiset of maps (with or without boundary and of any genus) with these two properties a \textbf{YB-bipartite maps family}.
	\item $\psi:m \to \Lambda$ is a graph homomorphism  with the following two properties (see the bottom of Figure~(fig-embedded-maps-exemp of the paper)):
	\begin{enumerate}
		\item[(2a)] $\psi$ sends each internal yellow face of $m$ isomorphically to an unoriented plaquette of $\Lambda$,
		\item[(2b)] $\psi$ sends each blue face of $m$ to a single unoriented edge of $\Lambda$.
	\end{enumerate}
	We call a graph homomorphism $\psi:m \to \Lambda$ with these two properties a \textbf{lattice embedding} of $m$.
\end{enumerate}

[Theorem thm:discrete-bound of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Equip $T^{(m)}(\mathbb{R}^d)$ with the projective tensor norm summed over levels. Let
\begin{equation}
V=\sum_{i=1}^n\left\lVert z_i\right\rVert,
\qquad
\delta=\max_i\left\lVert z_i\right\rVert.
\end{equation}
Then
\begin{equation}
\norm{S_m^{\rm PL}(z)-S_m^{\rm disc}(z)}
\le
\exp(2V)\sum_{i=1}^n\sum_{k=2}^{m}\frac{\left\lVert z_i\right\rVert^k}{k!}.
\end{equation}
If $\delta\le 1$, then
\begin{equation}
\norm{S_m^{\rm PL}(z)-S_m^{\rm disc}(z)}
\le
\exp(2V+1)\,\delta V.
\end{equation}
In particular, for increments of a Lipschitz path sampled on a mesh of size $\Delta$, with $\left\lVert z_i\right\rVert\le L\Delta$, the error is $O(\Delta)$ at fixed total variation.

