[Theorem 39 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $F\in\mathcal{HP}_{T,t}$ with representation \eqref{repre-321-11}, and let $\mathfrak H(K)$ denote the reproducing kernel Hilbert space with reproducing kernel
  $K_{T,t}(z,w)$. The map

\begin{equation}
  f\mapsto (T^{-1}+tT)^{1/2}f
\end{equation}
is unitary from $\mathcal H(\sigma)$ onto $\mathfrak H(K)$. In particular we have
\begin{equation}
  \mathfrak H(K)\subset(\mathbf H_2(\mathbb C_+))^m,
\end{equation}
and the elements of $\mathfrak H(K)$ do not contain non-zero constant functions.

[Lemma lem:asympbiasvar of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Steady state Bias-Variance}. Suppose assumptions (ass:Astable of the paper) and (ass:eigsymmA of the paper) holds along with $\mathbb{E}[\varepsilon_0] = 0$ and $C_0 = C_\infty$ where $C_\infty$ satisfies
\begin{align}

	0 = GC_\infty + C_\infty G^\top + \Sigma -rC_\infty H^\top \Xi^{-1} H C_\infty.
\end{align}
For $\nu_t, E_t$ as defined in (equation eq:defnnut of the paper) and (equation eq:defnEt of the paper) respectively,  $\nu_t \rightarrow \nu_\infty$ and $E_t \rightarrow E_\infty$ as $t \rightarrow \infty$, where
\begin{align}

	\nu_\infty &= \| A_\infty^{-1} b \|^2 \\


	E_\infty &=  \text{Tr}\left[ (\Sigma + (r-s) \left( G - A_\infty \right)C_\infty  - 2A_\infty^{-1} b b^\top) X_\infty \right] \\

    & \leq -\frac{1}{\alpha(A_\infty + A_\infty^\top)} \left( - 2 \text{Tr}[A_\infty^{-1}b b^\top] + \text{Tr}[\Sigma] + (r-s)^2 \alpha(H^\top \Xi^{-1}H) \|C_\infty\|_F\right)
\end{align}         
where $X_\infty$ is the unique solution of the Lyapunov equation  
\begin{align*}
	A_\infty^\top X_\infty + X_\infty A_\infty + I = 0.  
\end{align*}
In the scalar case $m=n=1$, $\nu_\infty$ and $E_\infty$ can be characterised entirely in terms of the system parameters $G, H, \Sigma, \Xi, b$, 
\begin{align}

	\nu_\infty &= \left(\frac{b}{A_\infty(r,s)} \right)^2 \\

	E_\infty = \tilde{P}_\infty &=  - \frac{1}{2}\left(\Sigma + \left( \frac{G - A_\infty(r,s)}{H} \right)^2 \Xi  \right)  \frac{1}{A_\infty(r,s)}  + \left(\frac{b}{A_\infty(r,s)} \right)^2
\end{align}
where 
\begin{align}

	A_\infty(r,s) &=  \frac{s}{r} G + \frac{(r-s)}{r} A_\infty(r,0) \\
	A_\infty(r,0) &= -\sqrt{G^2 + rH^2 \Xi^{-1} \Sigma}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ and $v_1,v_2,v_3\in \widetilde{\mathbb{Z}}^d$ with $|v_i-v_j|\ge d$ for all $i\neq j$, 
	\begin{equation}
		\bar{\mathbf{e}}_{v_1,v_2}(\{\widetilde{\eta}: v_3\in \mathrm{ran}(\{\widetilde{\eta}) \}) \lesssim \tfrac{|v_1-v_3|^{2-d}|v_3-v_2|^{2-d}}{|v_1-v_2|^{2-d}}. 
	\end{equation}

