[Thm 21 of arXiv:2607.03924, 'Tree Coordinates and Range Martingales for Positive Operator-Valued Measures'] Let $X=\left\{ X_{w}\right\} $ be a strictly positive
normalized range martingale for $E$. In the factor space coordinates
$S^{X}_{w}=X^{1/2}_{w}E^{1/2}_{w}$, the edge contractions of $E^{X}$
are 
\begin{equation}
C^{X}_{wj}=X^{1/2}_{wj}C_{wj}X^{-1/2}_{w}.
\end{equation}
Consequently, the splitting operators of $E^{X}$ in these coordinates
are 
\begin{equation}
A^{X,\left(j\right)}_{w}=X^{-1/2}_{w}C^{*}_{wj}X_{wj}C_{wj}X^{-1/2}_{w}.
\end{equation}

[Lemma 17 of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Let $\emprashomonset$, $\rretailset$, and $x$ satisfy Assumption \ref{assume:rashomon local} for parameter $\rashlexpctparam > 0$. Let $\rlocaltestmat =  \{\rlocaltest_{j} : j \in [\nogaussianpts]\}$ be a random set of perturbations of $x$, distributed $\iid \Unif(\ltwohsphere(x,\sigma))$, and $\ensmretset(\retailset,\localtestmat)$ be the ensemble model defined in \ref{def: local ensemble}. 
Define
    \begin{align}
    \lcondavg(\retailset,x)
        &= \abs*{\expect_{\rlocaltestmat}*{\ensmretset(\retailset,\rlocaltestmat)} - \frac{1}{2}},
    \\

    \explallavg(x) &= \abs*{\expect_{\rretailset,\rlocaltestmat}*{\ensmretset(\rretailset,\rlocaltestmat)}-\frac{1}{2}}
\end{align}
Then
    \begin{align}

    \prob_{\rretailset}*{
        \abs*{
        \lcondavg(\rretailset,x)
            -  \explallavg(x)
            }
        \ge
        \slackparam
    }
    \le
    2 \exp\parens*{\frac{-\Nretail\slackparam^2}{2\rashlexpctparam^2}}.
    \end{align}

[Lem 38 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $(\mu_n)$ be a sequence of $\mathscr{P}(\C)$ and $\mu\in \mathscr{P}(\C)$ satisfying: there exists a compact $K$ of $\C$ such that
    \begin{equation}
        \Prob{\mathrm{supp}\pr{\mu_n}\not\subset K}=o(1)\m\m\m\text{when}\m\m\m n\to +\infty.

    \end{equation}
    Then,
    \begin{equation*}
        \mu_n\overset{\mathbb{P}}{\rightharpoonup} \mu \Longleftrightarrow \mu_n\overset{\mathbb{P}}{\to} \mu \m\m\m\text{in}\m\m\m \mc{D}'(\C).
    \end{equation*}

