[Cor stronger RW to independent RI coupling of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] Let $\delta > 0, \eta \in (0,1) \text{ and } N \in \mathbb{N}$. Assume that $R \in (N^{\frac{1}{2}}, \frac{N}{1+\delta}]$, $\boldsymbol{F} \subset \mathbb{T}_N$ is $(1+\delta)R$-well separated, and $Q_R(x) \subset Q_\eta$ for all $x \in F$. Then for every $u \geq 1$ and $\rho \in (0,1)$, there exists a probability measure $\widetilde{\mathsf{P}}$ extending $\mathsf{P}$ and carrying independent random interlacements $\left(\mathcal{I}^{(x),u(1\pm\rho)}\right)_{x\in F}$ with the same law as $\mathcal{I}^{u(1\pm\rho)}$, such that
    \begin{multline}

        \widetilde{\mathsf{P}}\Big(\mathcal{I}^{(x), u(1-\rho)} \cap Q_R(x) \subset X[0, uN^d] \cap Q_R(\boldsymbol{x}) \subset \mathcal{I}^{(x), u(1+\rho)} \cap Q_R(x) \text{\quad for all } x \in F \Big) \geq \\
        1-CuN^{3d}\exp\Big(-c\rho^2 \sqrt{uN^{d-2}}\Big)
    \end{multline}
    holds for some constants $c,C \in (0, \infty)$ depending only on $\delta$, $\eta$ and $d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 14 (Procrustes representation) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] For $L, M \in \mathscr{L}(N, d)$, we have
\begin{equation} 
\begin{split}
\dist_{\mathrm{AW}}^2(L, M) = \min_{Q \in \mathscr{O}(N, d)} \|L - MQ\|_{\mathrm{F}}^2 = \sum_{t = 1}^N \min_{Q_t \in \mathscr{O}(d)}  \| L_{\cdot, t} - M_{\cdot, t} Q_t\|_{\mathrm{F}}^2.
\end{split}
\end{equation}
If $(L^{\intercal} M)_{t, t} = (L_{\cdot, t})^{\intercal} M_{\cdot, t}$ has singular value decomposition $U_t \Sigma_t V_t^{\intercal}$, the minimum is attained if and only if $Q_t \in \mathscr{P}( (L^{\intercal}M)_{t,t}) \cap \mathscr{O}(d)$. We let $\mathscr{Q}(L, M)$ be the set of $Q \in \mathscr{O}(N, d)$ that has this form.

