[Definition 16 of arXiv:2608.26803, 'On bubbling of Fueter maps'] For a complex manifold $(X, I)$, let 
    \begin{equation*}
        \Rat(X, I) \coloneq \{ x \in X \; | \; x\in C \; \text{for some irreducible rational curve } C\} 
    \end{equation*}
    denote the \textbf{locus of rational curves} on $(X, I)$.

[Lemma lemmas3.1 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] For every fixed \(\delta>0\),

\begin{equation}
D\to K_\delta(D)-I,
\qquad
D\to S_\delta(D)

\end{equation}
are globally Lipschitz maps from \(H\) to the Hilbert--Schmidt
operators on \(H\).  More precisely,

\begin{equation}
\|K_\delta(D)-K_\delta(E)\|_{\mathrm{HS}}
+\|S_\delta(D)-S_\delta(E)\|_{\mathrm{HS}}
\le C_{K_0}\delta^{-1}\|D-E\|_H,

\end{equation}
where $C_{K_0}>0$ only depends on $K_0$.
Furthermore,

\begin{equation}
\|K_\delta(D)\|_{\mathrm{op}}\le1,
\qquad
\|S_\delta(D)\|_{\mathrm{op}}\le1,
\qquad
K_\delta K_\delta^*+S_\delta S_\delta^*=I.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 30 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Assume \textnormal{(A1)-(A4)}. Then the pullback random attractors obtained in Theorem~\ref{The2} are upper semicontinuous at $\epsilon=0$: for every $\omega\in\Omega_0$,
	\begin{align}
		\lim_{\epsilon\to0}
		\operatorname{dist}_{\mathbb X}\big(
		\mathcal A^\epsilon(\omega),
		\mathcal A^0(\omega)
		\big)=0.
	\end{align}

