[Theorem 1 (Majorizing Measure Theorem) of arXiv:2608.11031, 'A Bayesian Proof of the Bernoulli Theorem'] There are universal constants $c,C>0$ such that every finite
$T\subset\mathbb R^n$ satisfies
\begin{equation}
  c\,\gamma_2(T,\|\cdot\|_2)
  \le W(T)
  \le C\,\gamma_2(T,\|\cdot\|_2),

\end{equation}
where
\begin{equation}
  \gamma_2(T,\|\cdot\|_2)
  :=
  \inf_{\mu\in\cP(T)}
  \sup_{t\in T}
  \int_0^\infty
  \sqrt{\log\frac{1}{\mu(B_2(t,r))}}\,dr.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq: satake of arXiv:2609.01990, 'Jacquet-Zagier treatment of the beyond endoscopy trace formula for \(\GL_2\)'] Consider the normalized basis 
    \[
    \left\{f_{m,n} = q^{-(m-n)/2} \mathbf{1}_{K\left( \begin{matrix}
        q^m & \\ & q^n
    \end{matrix}\right)K}\right\}_{m \geq n}
    \]
    of $\mathcal{H}$ and the basis of $\mathbb{C}[\alpha^{\pm1},\beta^{\pm1}]^{S_2}$ given by 
    \[
    \left\{\tau_{m+n,n}(\alpha, \beta) = \alpha^n \beta^n \left( \alpha^m + \alpha^{m-1}\beta + \cdots + \beta^m \right)\right\}_{m, n \in \mathbb{Z}_{\geq 0}}
    \]
    In terms of these basis, the Satake transform $\mathfrak{S}$ is given by 
    \begin{equation}
        \mathfrak{S}(f_{m,n}) = \begin{cases}
            \tau_{m,n} \qquad \qquad & m = n,n+1\\
            \tau_{m,n} - q^{-1} \tau_{m-1,n+1} & m \geq n+2
        \end{cases} 
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 4 of arXiv:2605.21424, 'A dice game, a multinomial walk, and the inverted Dirichlet distribution'] The winning probability has the form  
 \begin{align*}
 \pi_1&=\mathbb{P}(A_k<n_k,  2\leq k\leq m).
 \end{align*}
where $(A_2,\ldots,A_m)$ has a negative multinomial distribution (see e.g.~\cite[Chapter 36]{JohnKotzBal97}) with parameter set 
$\big(n_1,p_2,\ldots,p_m\big)$, i.e.,
\begin{align}
\pi_1=\Big(1-\sum_{k=2}^m p_k\Big)^{n_1}\sum_{k_2=0}^{n_2-1}\cdots\sum_{k_m=0}^{n_m-1}\binom{n_1+k_2+\dotsb+k_m-1}{n_1-1, k_2,\dotsc ,k_m}\prod_{\ell=2}^m p_\ell^{k_\ell}\,.
\end{align}

[Thm 1 (Theorem~\ref{thm:ASEP transition prob} in the main text) of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N\geq M\geq 0$ be fixed integers and let $x=(x_1,\dots,x_N)$ and $y=(y_1,\dots,y_M)$ be ordered coordinates of particles in the half-space ASEP. The transition probability between $y$ and $x$ for the half-space ASEP under the specialization $\gamma=0$ is given by
	\begin{multline}
		\mathbb{P}_t(y\to x) = V_{N-M} \alpha^{N-M} \mathrm{e}^{-\alpha t} \oint_{\mathcal{C}_1} \frac{\dd w_1}{2\pi\ii} \cdots \oint_{\mathcal{C}_N} \frac{\dd w_N}{2\pi\ii} \prod_{1\leq i<j\leq N}\left[\frac{w_j-w_i}{qw_j-w_i}\frac{1-qw_iw_j}{1- w_iw_j}\right] \\
		\times\prod_{i=1}^N \left[\frac{1-q w_i^2}{w_i(q+\alpha-1-\alpha w_i)(1-qw_i)} \left(\frac{1-w_i}{1-qw_i}\right)^{x_i-1} \exp(\frac{(1-q)^2 w_i t}{(1-w_i)(1-qw_i)})\right] \\
		\times \sum_{\sigma\in\mathcal{B}_N} \sigma\left(\prod_{1\leq i<j\leq N}
		\left[\frac{w_i-qw_j}{w_i-w_j}\frac{1-w_iw_j}{1- qw_iw_j}\right] 	\prod_{i=1}^M \left[ \frac{1-q-\alpha+\alpha w_i}{1-qw_i^2}\frac{(1-q)w_i}{1-w_i}\left(\frac{1-qw_i}{1-w_i}\right)^{y_i-1}\right]
		\right),
	\end{multline}
	where the contours surround singularities at $w_i=1$ and are defined according to Definition \ref{defn:ASEP nested contours}, and where $\mathcal{B}_N$ is the group of signed permutations of size $\{1,\dotsc,N\}$ (see Section \ref{sec:int formula} and \eqref{eq:sigma action} for more details). The overall normalization is given by the following $q$-dependent factor
    \begin{equation}
        V_k = \dfrac{q^{\binom{k}{2}}(1-q)^k}{\prod_{i=1}^k\left[\left(1-q^i\right)\left(1+q^{i-1}\right)\right]}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma coloring of group of arXiv:2605.02226, 'Finitely Dependent Processes on Subshifts'] Let $\epsilon > 0$. Then there exists $ D \in \mathbb{N}$ satisfying the following: For any $ r,l \in \mathbb{N}$, there exists $m \in \mathbb{N}$ such that any shift-invariant $ m$-net process $(J_{v})_{v \in \mathbb{Z}^d}$ has a block factor $(Z_v)_{v \in \mathbb{Z}^d}$ with $ Z_v \in \{1,2,\cdots, D\}$ for which
\begin{enumerate}
    \item There exists $M \in \mathbb{N}$ such that for any $ 1 \leq i \leq D$, the $r$-components of the sets $ W_i = \{ v \in \mathbb{Z}^d: Z_{v} =i\}$ have diameter less than $M$.
     \item In the Voronoi covering corresponding to the $ m$-net process $(J_{v})_{v \in \mathbb{Z}^d}$, the subset $ G_{l} := \{ v \in \mathbb{Z}^d: \mathbf{B}(v, l) \subseteq W_1\}$ occupies at least $ (1-\frac{\epsilon}{2})$ volume of each Voronoi cell i.e. $ \frac{|G_{l} \cap \mathcal{C}|}{\mathcal{|C|}} \geq (1 - \frac{\epsilon}{2})$ for each Voronoi cell $ \mathcal{C}$.
\end{enumerate}

[Lemma JIkDecomp of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] For any $\beta \in (0, 1)$ and each $k \ge 0$ and $l \in \{0,1\}$,
\begin{align}
	J_k = \int_0^\infty \widehat{D}^{[k]}_t {\rm d} t ,  \qquad I_l = \int_0^\infty \widehat{E}_t^{[l]} {\rm d} t

\end{align}
where $\widehat{D}^{[k]}_t$ and $\widehat{E}^{[k]}_t$ are the Fourier transforms of covariance matrices $D^{[k]}_t$ and $E^{[k]}_t$,  respectively,  with range $\le t$ and invariant under lattice symmetries. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2608.26565, 'A Horizon-Free Extrinsic Penrose Inequality'] Fix $t\in(0,t_0)$ and form the one-ended completion
$(\widetilde M_t,\widetilde S_t)$ used in
Theorem~\ref{thm:capillary-mass}.  If
\begin{equation}
 m(\widetilde S_t)=\frac1{\cosh t}
 \sqrt{\frac{|\Sigma_t|}{\pi}},

\end{equation}
then $\Sigma_t$ is a round flat disk and $S_t^+$ is a portion of a catenoid
of waist radius $m(\widetilde S_t)$.

