[Lemma 62 ($\Delta_0$-Collection) of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Suppose that $A(x,y)$ is a $\Delta_0$-formula in the language of set theory. Then
    \begin{equation*}
        H[\ttX]\Vdash [\forall x\in s \exists y A(x,y)] \to [\exists z \forall x\in s\exists y\in z A(x,y)].
    \end{equation*}

[Lemma lem:measure-decomp-weak-poincare of arXiv:2411.09075, 'Weak Poincar{\'e} Inequalities, Simulated Annealing, and Sampling from Spherical Spin Glas'] Let $\pi$ be a distribution over $\R^N$ or $\ScS_N$, and $\pi = \E_{\bz \sim \rho} \pi_{\bz}$ a measure decomposition of $\pi$ such that
    \begin{itemize}
        \item for all functions $f$, $\E_{\bz \sim \rho} \Var_{\pi_{\bz}}[f] \ge \Cvar \Var_{\pi}[f]$, and
        \item with probability $1-\eta$ over $\bz \sim \rho$, $\pi_{\bz}$ satisfies a  $(\CPoi,\delta)$-weak \Poincare~inequality with respect to Langevin diffusion.
    \end{itemize}
    Then, $\pi$ satisfies a $\left( \CPoi\Cvar, \frac{\delta+\eta}{\Cvar} \right)$-weak \Poincare inequality.

[Corollary eq:approximately-sparse-rate of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[corollary]{cor:sharp-approximately-sparse}
Under the hypotheses of (prop:sharp-profile-energy of the paper), let
\(1\le k_N\le N\), \(k_N=o(N)\), and for \(\rho>0\) put
\[
 \mathcal A_N(k_N,\rho)
 =\left\{x\in\mathbb S^{N-1}(1):
 \text{some \(S\subset[N]\), \(\left\lvertS\right\rvert\le k_N\), satisfies }
 \norm{x_{S^c}}_2\le\rho\right\}.
\]
Then, for every \(a>0\),
\begin{equation}
 \lim_{\rho\downarrow0}\limsup_{N\to\infty}\frac1N\log
 \mathbb P\left\{
 \sup_{x\in\mathcal A_N(k_N,\rho)}
 \left\lverth_N^J(x)\right\rvert\ge a\right\}
 \le-\frac{a^2}{2}.
\end{equation}
The same conclusion holds in the standard symmetric-coordinate model
whenever that field satisfies \(({\rm PT})_p\); the orbit-coordinate
joint MGF bound is sufficient.

[Propn 9 of arXiv:2604.27205, 'An Analysis of the Diaconis-Holmes-Neal Markov Chain Sampler Under Generalized Unimodal Un'] Assume the requirements of Lemma~\ref{step1} hold true.  Suppose
        \begin{equation}
            \{G_t\}_{t = 0}^{cn} = \left\{X_t = j'\wedge X_t \neq \tilde{j}\text{ }\forall\text{ } t > 0\wedge X_l \neq j'\text{ }\forall\text{ }0 < l < t\text{ $|$ }X_0 = \tilde{j}\right\}_{t = 0}^{cn}.
        \end{equation}
        \noindent Then if $j^{\prime}=(+1,j)$ or $j^{\prime}=(-1,j)$,
        \begin{equation}
            \sum_{t = 0}^{2n - 1}\Biggl[P(G_t)\Biggr] \geq \dfrac{m_j(n)}{m_{j^*}(n)}\left(\dfrac{n - 1}{n}\right)^{2n - 1}. 
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2609.03191, 'On lifting representations and actions on curves of the metacyclic groups $C_{p^s}\rtimes '] The following properties hold.

\medskip
{\bf (1)} We have a short exact sequence of $R_0[H]$-modules
$$0\rightarrow R_0[H]^H\rightarrow R_0[H]\rightarrow\mathcal U_0(p^s-1;\Xi_s^{\ast})\rightarrow 0.$$

{\bf (2)} Let $V$ be a $k[H]$-module such that it has a lift $\mathcal V$ to $R$ with $r_{\mathcal V}=0$. Then we have a commutative diagram of $R$-modules
\begin{equation}
\xymatrix@R=10pt@C=21pt@L=2pt{
\Hom_{R[H]}\bigl(\mathcal U_0(p^s-1;\Xi_s^{\ast})\otimes_{R_0} R,\mathcal V\bigr) \ar[r]\ar[d] &\Hom_{R[H]}(R[H],\mathcal V)=\mathcal V\ar[d]\\
\Hom_{k[H]}\bigl(U(p^s-1),V\bigr) \ar[r] & \Hom_{k[H]}(k[H],V)=V\\}
\end{equation}
whose vertical arrows are reductions modulo $\upsilon$ and are surjective and whose horizontal arrows are isomorphisms.

[Proposition 3 of arXiv:2512.19517, 'Spiking and Resetting'] For any $\sigma \ge 0$, and $0<a<b\le1$, let us define the analytic function
\begin{equation}

\begin{split}
Z(\cdot, \sigma : a,b): z \in D_{\sigma} (a,b) \mapsto Z(z,\sigma : a,b ):=\frac{1}{\sigma + f(0) + (1-z) f(0) (1/a -1/b)} \in \mathbb C 
\end{split}
\end{equation}
on the open disc $D_\sigma (a,b)$ of radius $R_\sigma (a,b)$, where
\begin{equation}

\begin{split}
R_\sigma (a,b) = 1+\cfrac{\sigma + f(0)}{f(0) (1/a -1/b)} >1 \ .
\end{split}
\end{equation}
Then for any $z\in D_{\sigma} (a,b)$ we have 
 \begin{equation}

\begin{split}
\lim_{\varepsilon \to 0} Z^\varepsilon (z,\sigma : a,b) = Z(z,\sigma : a,b ) \ .
\end{split}
\end{equation}

[Thm expsum_1 of arXiv:2609.04092, 'Short character sums of inhomogeneous polynomials'] Let $n,k$ be positive integers with $n\geq k-1$. Let $F\in \mathbb{F}_p[X_1,...,X_n]$ be a polynomial of degree $k$ with leading form $F_k$. 
   Let
$\mathbf{H}=(H_1,...,H_n)$ with $H\leq H_i\leq 2H$ for some $H>0$, and suppose $p^{1/k}T^{1-1/k}< H \leq  p$, where $TK=H$ and $T,K\geq 1$.  Let 
    \begin{align}
       0<\theta <
       \frac{k - \log(p T^{k-1}) /  \log H}{k-1}.
    \end{align}
   Then for all $\varepsilon>0$,
        \begin{align*}
            S({\bf a};F)
            \ll_{n,\varepsilon} H^nK^nH^{-(n-\dim {\rm sing } F_k)2^{-(k-1)}\theta + \varepsilon},
        \end{align*}
      where ${\rm sing } F_k$ denotes the singular locus of the hypersurface defined by $F_k=0$ over $\mathbb{F}_p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem-time-tail of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] Almost surely, for each $\eta\in\Xi$,  
\begin{equation}  
\lim_{n\to\infty} \sum \mathopen{}\mathclose\bgroup\originalleft\{ T_\xi :  \xi \in\Xi , \,  \xi\leq \eta , \, Y_\xi \notin \mathcal G_n \aftergroup\egroup\originalright\}  = 0  .
\end{equation}

[Corollary strict monochromatic of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Let $n\ge 2$. 
When $\alpha=1$, if $\beta_\ell$ and $\frac{1}{\beta_\ell}$ are bounded, the scaling bound in (equation eq:scalimRW of the paper) becomes
\begin{equation} 
\delta_{[\ell-\beta_\ell,\ell]}^M
=\mathrm{O}\left( \ell \delta_{[0,\ell]}^M\right)+
\mathrm{O}(1)\begin{cases}
    \frac{1}{\ell} & n\ge 3, \\
    \frac{1}{\sqrt{\ell}}  & n =2 .
\end{cases}
\end{equation} 
It is a scaling limit if the manifold $(M,g)$ satisfies the following additional assumption:
\begin{enumerate}
    \item If the manifold has no self-focal points, the error is
\begin{equation} 
\delta_{[\ell-\beta_\ell,\ell]}^M

=\mathrm{o}(1),
\end{equation}
in infinitesimal range: $\rho_\ell=\mathrm{o}(1)$ (equivalent to [canzani_hanin_2018_cinfscasymp]).
\item If the manifold has no conjugate points, the error is
\begin{equation} 
\delta_{[\ell-\beta_\ell,\ell]}^M
= \mathrm{O}\left( \frac{1}{\log \ell}\right),
\end{equation}
in fixed range $\rho_\ell=\frac{1}{2}\mathrm{inj}(M,g)$. {(Equivalent to [Keeler].)}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

