[Definition def:disintegration of arXiv:2507.01236, 'Disintegration theorem for multifunctions, \\ with applications to empirical Wasserstein d'] Let $(\mathfrak{X},\mathcal{A},\mu)$ and $(\mathfrak{Y},\mathcal{B},\nu)$ be probability spaces, and let $F:\mathfrak{X}\rightarrow \mathfrak{Y}$ be a multifunction which is \emph{measurable} in the sense that $F^{-1}B := \{x \in \mathfrak{X}:F(x) \cap B \neq \varnothing\} \in \mathcal{A}$ for all $B\in\mathcal{B}$. A \emph{disintegration of $\mu$ along $F$ with respect to $\nu$} is a map $y\mapsto\mu_y$ from $\mathfrak{Y}$ to the space of Borel probability measures on $\mathfrak{X}$ such that:
    \begin{enumerate}
        \item[{\rm (i)}] $y\mapsto\mu_y$ is \emph{measurable}, in the sense that $y\mapsto\mu_y(A)$ is $\mathcal{B}$-measurable for any $A\in\mathcal{A}$;
        \item[{\rm (ii)}] $\mu_y$ is supported on the fibre $F^{-1}\{y\} = \{x\in\mathfrak{X}:y\in F(x)\}$ for $\nu$-almost every $y\in \mathfrak{Y}$; and
        \item[{\rm (iii)}] one has the disintegration formula $\mu = \int\!\mu_y\,\nu(dy)$.
    \end{enumerate}

[Theorem 4 of arXiv:2608.29316, 'Powers of the Dirac Operator on $S^1\times S^{n-1}$'] On $V(f,j,\X,\e)$ the opeartor $\a^0A$ acts as a constant multiple of
\begin{equation}
Z_L(r,f,j,\Xi,\e)=\Xi\e\cdot\textstyle\frac{\G\left(\frac12(f+J+1+r-\Xi\e/2)\right)\G\left(\frac12(-f+J+1+r+\Xi\e/2)\right)}{\G\left(\frac12(f+J+1-r+\Xi\e/2)\right)\G\left(\frac12(-f+J+1-r-\Xi\e/2)\right)}
\end{equation}
and $A\a^0$ acts as a constant multiple of 
\begin{equation}
\begin{split}
Z_R(r,f,j,\Xi,\e)&=\Xi\e\cdot\textstyle\frac{\G\left(\frac12(f+J+1+r+\Xi\e/2)\right)\G\left(\frac12(-f+J+1+r-\Xi\e/2)\right)}{\G\left(\frac12(f+J+1-r-\Xi\e/2)\right)\G\left(\frac12(-f+J+1-r+\Xi\e/2)\right)}\\
&=-Z_L(r,f,j,\X,-\e).
\end{split}
\end{equation}

