[Proposition prop:link_gat_der_mall_der of arXiv:2605.07832, 'A Bismut -Elworthy formula for BSDEs with degenerate noise'] Let $A$ be defined as in (equation A of the paper), let $\Lambda : \mathcal{D} (\Lambda) \subseteq U \rightarrow U $ be a positive self-adjoint operator on a separable Hilbert space $U$ and Let us denote by $X^x$ the solution of the stochastic wave equation (equation wa1 of the paper) and by $P_t\,f,\, t>0,\, f\in B_b(H) $ its transition semigroup applied to $f$. Then for any $k\in {\cal H}$  there exists $\widetilde u\in L^2_{\cal P}(\Omega \times [0,T];U)$ such that 
\begin{align*}
\nabla_k (P_tf)(x) \langle \nabla^{\cal H} (P_tf)(x),\rangle_{\cal H}
= \mathbb E[f(X_t^x)\int_0^t u_s dW_s]
\end{align*}
and 
\begin{align} 
  | \langle \nabla^{\cal H} (P_tf)(x),\rangle_{\cal H}|
\leq\frac{c}{t^{3/2}} \|f\|_\infty 
\end{align}
Moreover if $h=Jb=\Big(
\begin{array}
[c]{c}
0\\
b
\end{array}
\Big)$ then 
\begin{align} 
  | \langle \nabla^{\cal H} (P_tf)(x),\rangle_{\cal H}|= | \nabla^J_b (P_tf)(x)|
\leq\frac{c}{t^{1/2}} \|f\|_\infty 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2607.11773, '2607.11773'] Suppose that {\bf(H1)}-{\bf(H4)}, \eqref{thetaassum2}, \eqref{dissip1} and \eqref{dissip2} hold.
   Then, for all $\varepsilon \in (0,\varepsilon^{*})$, the non-autonomous cocycle $\Phi$ has a closed $\mathcal{D}$-pullback absorbing set
       $K = \{ K(\tau): \tau \in \mathbb{R} \} \in \mathcal{D}$
   which is given by
   \begin{align*}
      K(\tau) =
                \left\{ \mu \in \mathcal{P}_\theta(D_{\rho}):
                                \int_{D_{\rho}} \| \xi \|_{\infty}^{\theta} \mu(d \xi)
                                \le R_{\tau}
                \right\},
   \end{align*}
   where $  	R_{\tau} >0$ is a  number given by 
        \begin{align}
        	R_{\tau} = &C_{\beta,\theta,
        	\rho}+ C_{\beta,\theta, \rho} \int_{-\infty}^{\tau} e^{\beta (s-\tau) }
        \left( \|g(s)\|^{\theta} + \|h(s)\|^{\theta} 
       + \|\widetilde{h}(s)\|^{\theta}_{L^{\theta}(\mathbb{Y}, \nu; \ell^2)} 
        \right) ds  , 
        \end{align}
   and $C_{\beta,\theta, \rho}$ and $\varepsilon^*$ are 
   the same
    constants as in Lemma \ref{pue}.

[Proposition 10 (Four Schatten flattenings) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] For $2\le r<\infty$, let $C_k=\max\{\norm{k}_{L^1},\norm{k}_{L^2}\}$.  Then
\begin{align}
 \norm{F_1}_{\Sch_r}
 &\lesssim |A_N|C_kN^{d/2}Q^{d/2}M^{d/r},
 \\
 \norm{F_2}_{\Sch_r}
 &\lesssim |A_N|C_kN^{d/2}M^{d/2}Q^{d/r},
 \\
 \norm{F_3}_{\Sch_r}+\norm{F_4}_{\Sch_r}
 &\lesssim |A_N|C_kQ^{d/2}M^{d/2}N^{d/r}.

\end{align}

[Theorem 5 of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $k\ge3$, let $N\ge1$, and let
$\alpha_1,\ldots,\alpha_k\in\mathbb R$.  For every $\varepsilon>0$,
\begin{equation}
  \min_{1\le n\le N}
  \left\|\alpha_kn^k+\cdots+\alpha_1n\right\|
  \ll_{k,\varepsilon}N^{-1/\Delta_k+\varepsilon}.
\end{equation}
In particular, for $k\ge6$ the exponent is $1/[k(k-1)]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2605.12269, 'It\^o integral for a two-sided L\'evy process'] {\rm
Let $\cP=\s(\cE)$ be the predictable $\sigma$-field on $\Omega \times \bR$. A process $\{\Phi(x)\}_{x\in \bR}$ is called {\em (spatially) predictable} if the map $(\omega,x) \mapsto \Phi(\omega,x)$ is $\cP$-measurable.
}

[Lemma 3 of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] The densities $\rho_{c}$, $\rho_{1c}$, and $\rho_{2c}$ share the same support on $(0,\infty)$, which is a union of intervals. For $\al=1,2$,
\begin{equation}
{\rm{supp}} \, \rho_{c} \cap (0,\infty) ={\rm{supp}} \, \rho_{\al c} \cap (0,\infty) = \bigcup_{k=1}^{L} [e_{2k}, e_{2k-1}] \cap (0,\infty),
\end{equation}
where $L\in \mathbb N$ depends only on $\pi_{A,B}$. The points $(x,m)=(e_k, m_{2c}(e_k))$ are the real solutions to
\begin{equation}
f(x,m)=0, \quad \text{and} \quad \frac{\partial f}{\partial m}(x,m) = 0. 
\end{equation}
Finally, $e_1 = {\rm O}(1)$, $m_{1c}(e_1) \in (-(\max_{\mu}\sigma_\mu^b)^{-1}, 0)$, and $m_{2c}(e_1) \in (-(\max_i \sigma_{i}^a)^{-1}, 0)$.

[Proposition 42 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] For any $\delta>0$, we have uniformly for $h_*+\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}\le s \le h^*$,
    \begin{align}
        \e_n\left[\sum_{j=s^{\downarrow}+1}^s \widetilde N_j\right]\asymp (\log n)^{1+\frac78 \varepsilon},\qquad
        \text{Var}_n\left[\sum_{j=s^{\downarrow}+1}^{s}\widetilde{N}_j \right]\lesssim (\log n)^{2+\frac{29}{24}\varepsilon}.
    \end{align}

