[Theorem 21 (Quantitative uniform spectral convergence) of arXiv:2608.30211, '2608.30211'] Assume $\partial\Omega\neq\varnothing$.  There are $C>0$ and
$\kappa_{\rm sp}>0$ such that
\begin{equation}
 \sup_{\varrho\in[0,1]}
 \bigl|\Lambda_{\kappa,\varrho}-\mu_\varrho\bigr|
 \leq C\kappa^{-1/2}
 \qquad(\kappa\geq\kappa_{\rm sp}).
\end{equation}

[Lemma JTtrapRF of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Fix $ \beta \in (0,\infty) $. Then as $ N\to\infty$, under the measure $ \mathbb{P}_{{\mathfrak m},N,W}^{\ssup{{\rm sym}}} $ the empirical path measures $ L_N $ satisfy a Large Deviations Principle on $ {\mathcal M }_1({\mathcal C }_\beta) $ with speed $ N $ and rate function $I_{W,{\mathfrak m}}:{\mathcal M }_1({\mathcal C }_\beta)\to \mathbb{R} \cup \{\infty\}$ given by
\begin{equation}
\hat{I}_{W,{\mathfrak m}}(\mu)=\begin{cases}
    H(\mu_0|{\mathfrak m})+H(\mu_{0,\beta}|\mu_{0}\otimes\mu_{\beta})+{\mathcal S }_W(\mu),\text{ if } \mu_0=\mu_\beta\\
    \infty, \text{ otherwise},
\end{cases}
\end{equation}
where ${\mathcal S }_W(\mu)=\sup_{F \in C_b({\mathcal C }_\beta)}\left\{\langle F,\mu\rangle - \int_{\mathbb{R} ^d}\int_{\mathbb{R} ^d}\mathbb{E}^{\beta}_{x,y}\left[e^{F -\int_0^\beta W(B_s)ds}\right]\mu_{0,\beta}({\rm d} x, {\rm d} y) \right\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 of arXiv:2608.29152, 'Uniform Statistical Convergence of Empirical Sinkhorn Potentials\\ with Exponential and Po'] There is a constant \(c_\kappa^{\mathrm{dev}}>0\), depending only on
\(\kappa\), such that the following holds. Let
\(0<\delta\le1/8\), and suppose
\[
    n\ge
    \frac{
      \bigl(1+\sqrt{\log(1/\delta)}\bigr)^2
    }{
      256\,\bar t_\kappa^2
    }.
\]
Then, for every \(0<\eps\le1\),
\[
    \inf_{\widehat f}
    \sup_{|t|\le1/4}
    \Prob_t^{(n)}
    \left[
      d_\infty\bigl([\widehat f],[f_{\eps,t}]\bigr)
      \ge
      c_\kappa^{\mathrm{dev}}\,
      \frac{\eps}{\sqrt n}
      \left(1+\sqrt{\log\frac1\delta}\right)
    \right]
    \ge\delta.
\]
One may take \(c_\kappa^{\mathrm{dev}}=m_\kappa/32\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 129 (Normalized first-chaos kernel majorant) of arXiv:2607.10813, '2607.10813'] Let $N=\langle\xi\rangle$, $L\ge1$, $0\le\theta<1/2$, and choose
$\varepsilon>0$ so that
$2\beta_a+\theta+\varepsilon<1$.  Define
\begin{equation}
 \mathfrak M_{a,\theta,\varepsilon}(N,L)
 :=N^{-1+\beta_{a^\perp}}
   \max\{N,L\}^{-1+2\beta_a+\theta+\varepsilon}.
\end{equation}
Then the following estimates hold uniformly over all four projection flags:
\begin{align}
 \sup_{u,t}|\mathcal K_{a,>L}(\xi;t,u)|
 &\lesssim \mathfrak M_{a,0,\varepsilon}(N,L),
 \\
 \sup_{0\le u\le t<t'}
 \frac{|\mathcal K_{a,>L}(\xi;t',u)
       -\mathcal K_{a,>L}(\xi;t,u)|}{|t'-t|^\theta}
 &\lesssim \mathfrak M_{a,\theta,\varepsilon}(N,L),
 \\
 \sup_{t<u\le t'}
 \frac{|\mathcal K_{a,>L}(\xi;t',u)|}{|t'-t|^\theta}
 &\lesssim \mathfrak M_{a,\theta,\varepsilon}(N,L).

\end{align}
Here $\mathcal K_{a,>L}$ denotes the sum of internal resonant shells
$M\gtrsim\max\{N,L\}$.  Any cutoff-difference term is bounded by the same
right-hand sides with $L=c\Lambda$; if the active cutoff leg is an output
frequency, it forces $N\gtrsim\Lambda$ and the same formula follows with
$\max\{N,L\}\simeq N$.  Consequently its static and normalized increment
covariance densities are bounded by
\begin{equation}
 \mathfrak M_{a,0,\varepsilon}(N,L)^2,
 \qquad
 \mathfrak M_{a,\theta,\varepsilon}(N,L)^2,
\end{equation}
respectively.

