[Lem Black-Scholes_vs_BM_intro of arXiv:2411.11408, 'Multidimensional specific relative entropy between continuous martingales'] {The specific relative entropy between a $\mathbb{R}^l$-valued martingale Black-Scholes models with parameter $\Gamma\in \mathbb{R}^{l \times l}$ and Brownian motion, both starting at the same point, is given by:
\begin{equation} \begin{split}  
h_l(\mathcal L(M^{\Gamma})|\mathbb{B}^l)=\textstyle \frac{1}{2}\Big(\sum_{i=1}^l \big(e^{\sum_{k=1}^l \Gamma_{ik}^2}-1\big)-l+\frac{1}{2} tr(\Gamma \Gamma^T) - \log \big(\det (\Gamma \Gamma^T) \big)\Big).
\end{split}
\end{equation}} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Uniqueness of blocks of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:uniqueness_and_connectedness}
    Let $C \subset V$ be a non-empty finite set of vertices.

    Then there exists $b \in \mathbf{N}$ and a unique $1$-disconnected sequence of $1$-connected sets $(A_0,\ldots,A_{b-1})$ such that $C = A_0 \sqcup \ldots \sqcup A_{b-1}$.

