		\begin{equation}
			\sum_{k \in K} \sum _{\bfm}\sup _{\mathbf{s}\in F_{\bfm} }|g _{\bb \xi,M,1}(\mathbf{s},k)|<C
			M^{-\xi _1 }, \quad  \sum_{k \in K} \sum _{\bfm}\sup _{\mathbf{s}\in F_{\bfm} }|g _{\bb \xi,1,M}(\mathbf{s},k)|< CM^{-\xi _2}.

