[Definition 25 (Local margin) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Given a Rashomon \smallset{} set $\retailset = \{f_k: k \in [\Nretail]\}$  of size $\Nretail$, a set $\localtestmat = \{\localtest_{j} : j \in [\nogaussianpts]\} \subseteq \ltwohsphere(x,\sigma)$ of $\nogaussianpts$ perturbed samples of $x$, and the local ensemble $\bar{f}(\retailset, \localtestmat)$, we define the local margin of $\bar{f}(\retailset, \localtestmat)$ at a fixed instance $x$ as, 
\begin{align}
    \localmargin(\retailset,\localtestmat,x) = \babs{\ensmretset(\retailset,\localtestmat) &- \frac{1}{2}}
\end{align}

[Lemma lem:classical bound on eigenvalues for transpositions of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $n\geq 2$ be even. Let $\lambda \vdash n$. The following holds.
\begin{enumerate}
    \item If $1\leq \ensuremath{r}_\textup{sym}(\lambda)\leq n/2$, then $|\chi^\lambda({\ensuremath{\mathcal T}} )| \leq 1 - \frac{2 \ensuremath{r}_\textup{sym}(\lambda)(n-\ensuremath{r}_\textup{sym}(\lambda)+1)}{n(n-1)}$.
    \item If $\ensuremath{r}_\textup{sym}(\lambda)\geq n/2$, then $|\chi^\lambda({\ensuremath{\mathcal T}} )| \leq 1/2$.
\end{enumerate}

[Definition of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] For $\delta>0$ and a path $\pi$ in ${D([0,T],H^{-m}(\mathbb T))}$, the uniform modulus of continuity of $\pi$, is defined by
\begin{equation*}
\omega_{\delta}(\pi)=\sup_{\substack{|s-t|<\delta, \\0\leq{s,t}\leq{T}}}\|\pi_{t}-\pi_{s}\|_{-m}.
\end{equation*}

[Theorem thm: main result of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] There exists a stochastic basis $(\Omega, \mathcal F, \mathbb F, \mathbb P)$ supporting processes $u \in \bigcap_{\delta\in(0,1)} \Xi^\delta_{\mathfrak u}$, $u_n \in C([0,T], L^2)$ for $n\in\mathbb N$ and $Q$--Wiener processes $W$ and $W_n$ for $n\in\mathbb N$, s.t.~$((\Omega, \mathcal F, \mathbb F, \mathbb P), u, W)$ is a non-negative martingale solution to the stochastic porous medium equation (equation eq: intro1 of the paper)--(equation eq: intro3 of the paper) in the sense of Definition (def: solution of the paper), satisfying for any $p \geq 1$
    \begin{equation}

        \mathbb E\left[\sup_{r\in[0,T]} \left\| u(r) \right\|_{H^{(\alpha-2)/\alpha}_0}^p \right] + \mathbb E\left[\int_0^T \left\| u(r) \right\|_{H^1_0}^p \mathrm d r \right] < \infty.
    \end{equation}
    Moreover, for any $n\in\mathbb N$ the triples $\left((\Omega, \mathcal F, \mathbb F, \mathbb P), P_n(u_n), W_n \right)$ are martingale solutions to (equation eq: discrete dynamics Rn of the paper) in the sense of Proposition (prop: existence for discrete systems of the paper), and there exists a subsequence of $u_n$ converging to $u$ $\mathbb P$-a.s.~in $\Xi_u$. Furthermore, if for some $\varepsilon > 0$ the pre-limiting systems satisfy
    \begin{equation}

        \limsup_{n\rightarrow\infty} \mathbb P (\mathcal S(u_n) \geq \varepsilon) > 0,
    \end{equation}
    then the system (equation eq: intro1 of the paper)--(equation eq: intro3 of the paper) exhibits sticky behavior (equation eq: limiting stickiness condition of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition DUFJ-INT-SJ-A of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] A random function $v\left( {x} \right)$ is said to be intermittent, if for two positive exponents ${p_1} > {p_2}$, there exists an increasing function $\mathfrak{h}_1\left( r \right)$ such that
\begin{equation}
\frac{{{{\left\| {v} \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| {v} \right\|}_{{L^{{p_2}}}}}}}  \sim  \mathfrak{h}_1\left( r \right) \to  \infty , \ \ \mbox{as}\ r \to  \infty  , \ \mathbb{P}\mbox{-a.s.},
\end{equation}
where $r$ is the cutoff wavenumber associated with the Fourier transform of $v\left( {x} \right)$.

[Lemma 28 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] (\cite[Lemma~3.12]{ding2024critical})

Fix $0 < \alpha < \beta$. Let $T>0$, let $x \in [\alpha \log T, \beta \log T]$, and let $W$ be a Brownian bridge from $0$ to $2T - x$ in time $T$. For $S>0$,
\begin{equation*}
    \mathbb{P}\left[W_t \leq 2t -\alpha \log T,\,\text{for all}\,\,t \in [T/2,T],\,\,\int_{T/2}^T \mathds{1}_{\{W_t \geq 2t - \beta \log T\}} dt >S\right] \leq c_0 \exp\left(-c_1 \frac{S}{(\log T)^2}\right)
\end{equation*}
for constants $c_0,c_1>0$ depending only on $\alpha,\beta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 55 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $\bX_n \to \bX $ in $\bZ_T$. Suppose $z \in \mathscr{V}$. Then       
   \begin{equation}
      \sup_{s \in [0,T]} \lvert  M_s^{n,z}(\bX_n) - M_s^z(\bX) \rvert \underset{n \to \infty}{\to}  0.
    \end{equation}

