[Lemma lem:phi_holomorphic of arXiv:2604.04922, 'Elephant random walk on the infinite dihedral group $\mathbb{Z}_2 * \mathbb{Z}_2$'] Fix $\eta \in (0,\frac{1}{2})$. Define the function $\psi: R_\eta \to \mathbb{C}$, given by
\begin{equation}
    \psi(z):= \frac{1}{2z-1}\int_0^1\frac{u^{-2z + 1} - 1}{1 - u} \cdot \frac{(1 - \frac{u}{2})^{z - 1} - 1}{u} du.
\end{equation}
Then, $\phi$ is holomorphic on $R_\eta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 36 ({\cite[Lemma 4.2) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Cr18}}]\quad\par
  \begin{itemize}
    \item[$\mathrm{(i)}$] If $x\in F$, $A$ is a non-empty closed subset of $F\setminus\{x\}$ and $\delta\in (0,R(x,A))$, then
\begin{align*}
  P_x(\sigma_A\leq t)\leq 2\left[ 1-\left(\frac{R(x,A)-\delta}{R(x,A)+\delta}\right)e^{-\frac{ 2t }{\mu(B(x,\delta))(R(x,A)-\delta)}} \right],\qquad \forall t\geq 0.
\end{align*}
In particular, if $x,y\in F$, $\varepsilon\in (0,R(x,y)/2),\delta\in (0,R(x,y)-2\varepsilon)$, then
\begin{align*}
  P_x\left(\sigma_{\overline{B(y,\varepsilon)}}\leq t\right)\leq 4\left[\frac{\delta}{R(x,y)-2\varepsilon}+\frac{t}{\mu(B(x,r))(R(x,y)-2\varepsilon-\delta)}\right],\qquad \forall t\geq 0.
\end{align*}
\item [$\mathrm{(ii)}$]If $\rho\in F$ and $\delta\in (0,R(\rho,B(\rho,r)^c))$, then 
\begin{align*}
  P_{\rho}\left( \sigma_{B(\rho,r)^c}\leq t \right)\leq 4\left[ \frac{\delta}{R(\rho,B(\rho,r)^c)}+\frac{t}{\mu(B(\rho,\delta))(R(\rho,B(\rho,r)^c)-\delta)} \right],\quad t\geq 0.
\end{align*}
NB. If $B(\rho,r)^c=\emptyset$, then we interpret the right-hand side as being equal to zero.
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] We have
    \begin{equation}

        \partial_{t} F(t,k) = - e^{DF(t,k)} + 1, \quad \forall k \in \N
    \end{equation}
    and 
    \begin{equation}

        \partial_{t} G(t,k) = - G(t,k) DG(t,k), \quad \forall k\in \N.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor concentration_meso of arXiv:2510.18856, 'Evolution of recursive trees with limited memory'] Fix $\beta \in (0,1)$. For any $\epsilon,\delta>0$ and $T < T_\beta = 2(1-\beta)^{-1}$ there exist constants $C=C(\delta,T)>0$ and $\xi=\xi(\epsilon)>0$ such that
    \begin{align*}
        \mathbb{P}\left(\exists\;\;v \in [\delta n, n]: \sup_{t\leqslant T }\left|\frac{1}{v}L_v(\lfloor tv^{1-\beta} \rfloor)-f_{\beta}(t)\right|>v^{\frac{-1+\beta}{2}+\epsilon}\right)\leqslant \exp(-Cn^{\xi}).
    \end{align*}

