[Theorem thm:iteratedfreenck of arXiv:2510.01021, '\Large Random Matrices, Intrinsic Freeness, and Sharp Non-Asymptotic Inequalities\relatedv'] Let $X$ be a matrix chaos as in (equation eq:chaos of the paper). Then
    \begin{equation*}
        \mathbb{E}\|Y\| \lesssim_q 

        \left(\sigma(\mathcal{A}) + \log(d_1+d_2+m)^{\frac{q+2}{2}} v(\mathcal{A})\right),
    \end{equation*}
    where 
\begin{equation}
    v(\mathcal{A}) \coloneqq \max_{\substack{R= [q+2]\backslash C\\q+1, q+2\in C\\R \neq \emptyset}} \left\|\flatta{R}{C}\right\|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 37 of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] Assume that~$(\gamma_1,\gamma_2) \in \mathcal S$ with~$\gamma_2 > 1/2$ and~$\gamma_1 > \kappa(\gamma_2)$. Then, letting
	\begin{equation}
		a^*_1=a^*_1(\gamma_1,\gamma_2):=\frac{\bar{\gamma}_1 \bar{\gamma}_2}{\gamma_2 + \gamma_1\gamma_2 -1 }\qquad\text{and}\qquad a^*_2 = a^*_2(\gamma_1,\gamma_2):= \frac{\gamma_1 + \gamma_1\gamma_2 -1 }{\bar{\gamma}_1 \bar{\gamma}_2},
	\end{equation}
	we have
	\[
		\min\{f_{\mathsf S},f_{\mathsf B},f_{\mathsf D}\} = \begin{cases}
			f_{\mathsf S}&\text{if } a \le a^*_1;\\
			f_{\mathsf D}&\text{if } a^*_1< a \le a^*_2;\\
			f_{\mathsf B}&\text{if } a > a^*_2.
		\end{cases}
	\]

[Lemma 19 ($q$-labeling description of $v_{\lambda}$) of arXiv:2606.12670, 'The censored stochastic six-vertex model and parabolic Kazhdan--Lusztig $R$-polynomials'] The function $v_\lambda$ has the following alternative description.
    \begin{equation}
        v_{\lambda}(\mu) = q^{|\mu|} \prod_{(i,j)\in\lambda/\mu}w_\lambda(i,j)\,.
    \end{equation}

[Corollary cor:scal_prod_lin of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Let $F, F' \in \mathcal{P}(\sigW[T])$ with the coefficients $\bm{\ell}, \bm{\ell}' \in \TA[d+1]$. Then
    \begin{equation}
        \langle \mathbf{D} F, \mathbf{D} F' \rangle_{L^2} = \bracketsigW[T]{\bm{\ell}\diamond\bm{\ell}'}.
    \end{equation}

