[Theorem 4 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Assume the same conditions as in Theorem \ref{mainthm}. Then, there exists a positive constant $C$ such that for any $h>0$,
\begin{align*}
\p\left(\sup_{0\le t \le T}\left|X_t-\tilde{X}_t\right|^{\alpha-1}>h\right) \le
\begin{cases}
    \frac{C}{h}\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S^{\alpha-1/\tilde{\eta}}\right\}\right\}& \text{if~~}\tilde{\eta} \in(1/\alpha,1]\\
	\frac{C}{h}\left[\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \left\{\log\left(\frac{1}{\max\left\{B, S\right\}}\right)\right\}^{-1}\right] & \textrm{if~~}\tilde{\eta} =1/\alpha.
\end{cases}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:one-arm-shells of arXiv:2607.18070, 'The Brownian loop-catcher'] There are \(A_\lambda,q\in(0,\infty)\) and \(L_0<\infty\) such that, for
\(L\ge L_0\),
\begin{align}
 \mu_\mathbb{D}^{c,z}\{L(\ell)\in dL\}
   &=A_\lambda L^\lambda[1+O(e^{-L})]\,dL,
 \\
 \int_{\{L(\ell)\in dL\}}
   \bigl(1-F_\mathbb{D}^{-1,1}(\ell)\bigr)\,\mu_\mathbb{D}^{c,z}(d\ell)
   &=A_\lambda q L^{\lambda-1}[1+O(e^{-L})]\,dL.

\end{align}
Both measures have finite mass on \(0\le L\le L_0\).

[Theorem ChernConnection of arXiv:2609.03909, 'Conic Pseudo-Finslerian Mechanical Systems'] There exists a unique Chern connection and it is characterized by  \textbf{Koszul-type formula}
 \begin{eqnarray*}		2g_V(\nabla^V_XY,Z)&=&Xg_V(Y,Z)-Zg_V(X,Y)+Yg_V(Z,X)\\
			&+&g_V([X,Y],Z)+ g_V([Z,X],Y)-g_V([Y,Z],X)\\
			&+& 2(-C_V(\nabla^V_X V,Y,Z) -C_V(\nabla^V_YV,Z,X) +C_V(\nabla^V_ZV,X,Y)),
		\end{eqnarray*}    
for each vector field without singularities $V$ and vector fields $X,Y,Z$. (Proof in the paper; no proof environment follows the statement in the TeX.)

