body:
[Proposition 10 of arXiv:2606.16083, 'Eyring--Kramers asymptotics for infinite-dimensional stochastic gradient systems'] Given $E,\rho>0$, we find a subspace $\mathcal{V}\subseteq B^*\cap A^{-1}(B^*)$ of finite dimension, containing $\{\eta_1,\dots ,\eta_m\}$, such that the corresponding orthogonal projection $\pi:B\longrightarrow H$ satisfies
    \begin{align*}
        F(x) & \geq F(\pi x)-\rho,
    \end{align*}
    as well as $\|x-\pi x\|_B  < \rho$, for all $x$ with $F(x)\leq E$.

[Thm 4 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Fix $\beta>0$. Assume that $\me [\eta]=0$, ${\rm Var}[\eta]\in (0,\infty)$ and
\begin{equation}
\mmp\{\eta>x\}~\sim~\frac{1}{(x\log x)^2},\quad x\to\infty.
\end{equation}
Then there exists a sequence $(a_k)$ satisfying \eqref{eq:standing} and  \eqref{eq:basic} for which $$\limsup_{s\to 0+}\frac{s^{\beta/2}}{(\log\log 1/s)^{1/2}} X(s)=+\infty\quad\text{{\rm a.s.}}$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main of arXiv:2607.05097, 'Asymptotics of Lyapunov Exponents and Phase Transitions for Fluids with Degenerate Forcing'] Suppose (as:nondegen of the paper) holds. Then, for every $\epsilon_n \downarrow 0$ and initial conditions $(z_n,x_n)$ (with $x_n\neq 0$) for the process $(z^{\epsilon_n}(t), x^{\epsilon_n}(t))$ given by (equation eq:zv-def of the paper), one has
        \begin{equation}
            \lim_{n \to \infty} \lambda_{\epsilon_n} = \lambda^* \coloneqq \mathbb{E}[\lambda(A(Z))]\quad \text{a.s.}
        \end{equation}
        (see (equation eq:lyap-exp-def of the paper) and (def:sigma-lambda of the paper)), where the law of $Z$ is the invariant measure for (equation eq:z-def of the paper).



        Additionally,
        \begin{equation}
            \lim_{\epsilon \downarrow 0} \inf_{\mu^\epsilon \in P_{\mathrm{inv}}^\epsilon}\int \Lambda^\epsilon(z,v)d\mu^\epsilon(z,v) = \lambda^* \,,
        \end{equation}
        where $P^\epsilon_{\mathrm{inv}}$ is the set of invariant measures for $(z^\epsilon(t),v^\epsilon(t))$ and $\Lambda^\epsilon$ is as in (equation eq:L-lnr-def of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 18 of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Let Assumptions \ref{asslip2}, \ref{assLRbounded} and \eqref{bdd of tilde Z} hold. Moreover, suppose that for any $s\in[0,T]$, each of the following two equations admits a unique deterministic nonnegative solution
\begin{equation}
    \begin{split}
        &f(s,\widetilde{Y}_s,\mathbf{E}[\widetilde{Y}_s],\widetilde{Z}_s,\mathbf{E}[\widetilde{Z}_s],k)-f(s,\widetilde{Y}_s,\mathbf{E}[\widetilde{Y}_s],\widetilde{Z}_s,\mathbf{E}[\widetilde{Z}_s],0)+k=\widetilde{k}_s^+,\\
        &f(s,\widetilde{Y}_s,\mathbf{E}[\widetilde{Y}_s],\widetilde{Z}_s,\mathbf{E}[\widetilde{Z}_s],-k)-f(s,\widetilde{Y}_s,\mathbf{E}[\widetilde{Y}_s],\widetilde{Z}_s,\mathbf{E}[\widetilde{Z}_s],0)-k=-\widetilde{k}_s^-.
    \end{split}
\end{equation}
Then the mean doubly reflected MFBSDE \eqref{mfbsdefk} with nonlinear resistance has at least one solution.

