[Theorem 34 (\cite{marshall2011}, Theorem~3.A.4) of arXiv:2604.26026, 'Stochastic Ordering of Dependent Systems under Transformation Models and Archimedean Copul'] Suppose $J \subset \mathbb{R}$ is an open interval and $h: J^{n} \rightarrow \mathbb{R}$ is continuously differentiable. Then, $h$ is Schur-convex (Schur-concave) on $J^{n}$ if and only if
	\begin{enumerate}
		\item $h$ is symmetric on $J^{n}$, and
		\item for all $i \neq j$ and all $\boldsymbol{\alpha} \in J^{n}$,
		\begin{equation}

        \left(\alpha_{i}-\alpha_{j}\right)\left(\frac{\partial h(\boldsymbol{\alpha})}{\partial \alpha_{i}}-\frac{\partial h(\boldsymbol{\alpha})}{\partial \alpha_{j}}\right) \geq (\leq)\,0,
		\end{equation}
		where $\frac{\partial h(\boldsymbol{\alpha})}{\partial \alpha_{i}}$ represents the partial derivative of $h$ with respect to its $i$-th argument.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 48 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $H=E\circ (F+1+G)$ and $\ttX$ be a template order.
    \begin{enumerate}
        \item If $H[\ttX]\sststile{\rho}{\alpha} \Gamma,A\land B$, then $H[\ttX]\sststile{\rho}{\alpha} \Gamma,A$ and $H[\ttX]\sststile{\rho}{\alpha} \Gamma, B$.
        \item Suppose that $H[\ttX]\sststile{\rho}{\alpha} \Gamma,\forall x\in t\ B(x)$. For every template order $\ttY\supseteq\ttX$ and a term $s\in \bfL(u)_\ttY$ satisfying $(\spadesuit)$, we have $H[\ttY] \sststile{\rho}{\alpha} \Gamma, s\dotin t\to B(s)$.
    \end{enumerate}

