[Lemma 63 of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $\theta_1, \ldots, \theta_m$ be unit flows from $u$ to $v$ that are supported on disjoint edges, that is for each edge $e$ we have $\theta_i(e) > 0$ for at most one $i \in \{1, \ldots, m\}$. Then, for any $\alpha_1, \ldots, \alpha_m \geq 0$
    \begin{equation*}
        \Big\Vert \sum_{i=1}^m \alpha_i \theta_i \Big\Vert^2_r = \sum_{i=1}^m \alpha^2_i \Vert\theta_i\Vert^2_r.
    \end{equation*}

[Defi construction of nu of arXiv:2607.19658, 'Hitting time mixing for random $k$-cycles'] Suppose we have $t\in\mathbb{Z}$. Set $t':=t-\frac{n\log n}{k}$, and $\gamma_{n,t}:=e^{-kt'/n}$. Let $\nu_t$ denote the measure on $\mathfrak{S}_n$ defined by the following sampling process: first, sample $M_t\in\{0,1,\ldots,n\}$ according to the distribution $\mathbf{P}[M_t=x]=\mathbf{P}(\Pois(\gamma_{n,t})=x)/\mathbf{P}(\Pois(\gamma_{n,t})\le n)$, then sample a uniformly random subset $S_t$ of size $M_t$ in $[n]$. Finally,
\begin{enumerate}
\item When $k$ is odd, sample a uniformly random element of $\mathfrak{A}_{[n]\backslash S_t}$ and view it as an element of $\mathfrak{A}_n$ by fixing all of the elements in $S_t$.
\item When $k$ is even, and $t$ is odd, sample a uniformly random element of $\mathfrak{A}_{[n]\backslash S_t}^c$ and view it as an element of $\mathfrak{A}_n^c$ by fixing all of the elements in $S_t$.
\item When $k$ is even, and $t$ is even, sample a uniformly random element of $\mathfrak{A}_{[n]\backslash S_t}$ and view it as an element of $\mathfrak{A}_n$ by fixing all of the elements in $S_t$.
\end{enumerate}

[Lem 24 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\mathcal{L}(s,z)$ be a linear functional on $C^\infty([G])$ that is holomorphic and satisfies $\mathcal{L}(s,z)(\varphi)\ll_{s,z}\nu_\varphi^{O(1)}$ continuously in $(s,z)$, in a sufficiently small neighbourhood of the hyperplane $z+\tfrac{n}{2}s=\tfrac{n-1}{2}$. Then
		\begin{multline*}
			\Res_{z=\frac{n-1}{2}-\frac{n}{2}s}\sum_{\varphi\in\B(\1_{n-2}\boxplus\1_1\boxplus\1_1)}\left\langle\phi,\Eis\left(\varphi,\overline{\lambda_{\mathrm{C}}(s,z)}\right)\right\rangle_{[G_n]^1 }\mathcal{L}(s,z)(\varphi)\\
			=\sum_{\beta\in\B(\1_{n-1}\boxplus\1_1)}\left\langle\phi,\Eis\left(\beta,\overline{\lambda_{\mathrm{E}}(s-\tfrac{1}{2})}\right)\right\rangle_{[G_n]^1 }\mathcal{L}\left(s,\tfrac{n-1}{2}-\tfrac{n}{2}s\right)(\beta)
		\end{multline*}
		where $\lambda_{\mathrm{E}}(s)$ is as in \eqref{eq:def-lambda-E}.

