body:
[Definition 2 of arXiv:2608.19976, 'Random valuations'] A \emph{random valuation} $\Phi$ is a stochastic process on $\Kd$
  such that $\Phi(\emptyset)=0$ a.s.\ and, for each fixed admissible
  $K,L\in\Kd$, we have
  \begin{displaymath}
    \Phi(K\cup L)+\Phi(K\cap L)=\Phi(K)+\Phi(L)\quad \text{a.s.}
  \end{displaymath}
  The distributions of $(\Phi(K_1),\dots,\Phi(K_n))$ for $n\ge1$,
  $K_1,\dots,K_n\in \Kd$, are called the finite-dimensional
  distributions of $\Phi$.

[Lemma l4.13 of arXiv:2603.14447, '\Large \bf Backward doubly stochastic differential equations with and without reflection u'] \sl
		Let the conditions \(\textbf{(A1)}\), \(\textbf{(G1)}\) and \(\textbf{(S2)}\) be satisfied. 	For any $(t,\omega,y,z)\in [0,T]\times\Omega\times\mathbb{R}\times\mathbb{R}^d$, we have
		\begin{align*}
			S^1_t\leqslant S^2_t,\quad\
			\xi^1\leqslant \xi^2, \quad\ f^1(t,y,z)\leqslant f^2(t,y,z) \quad\ \hbox{a.s.}
		\end{align*}
		Moreover, assume that,
		$f^2(t,y,z)$ is continuous and is of linear growth in \(y\) and \(z\), i.e., there exists a finite constant $C>0$ such that
		\begin{align*}
			|f^2(t,y,z)|\leqslant C(1+|y|+|z|),\quad\ \hbox{a.s.}
		\end{align*}
		Then for any \(t\in [0,T]\), $Y_t^1\leqslant Y_t^2,  \mathbb{P} $-a.s., where $(Y^1,Z^1,K^1)\in S_\mathbb{F}^{2}([0,T];\mathbb{R})\times L_\mathbb{F}^2([0,T];\mathbb{R}^d)\times A_\mathbb{F}^{2}([0,T];\mathbb{R}_+)$ is a solution of reflected BDSDE (equation r1 of the paper) with parameters $(\xi^1,f^1,g)$ and obstacle $S^1$, $(Y^2,Z^2,K^2)\in S_\mathbb{F}^{2}([0,T];\mathbb{R})\times L_\mathbb{F}^2([0,T];\mathbb{R}^d)\times A_\mathbb{F}^{2}([0,T];\mathbb{R}_+)$ is the maximal  solution of reflected BDSDE (equation r1 of the paper) with parameters $(\xi^2,f^2,g)$ and obstacle $S^2$.

[Defi 17 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] Define recursively for any $\tau\in \mcB \sqcup \mcB^+$ 
		\begin{equation}
			Y_{\tau} = \widetilde{ \PPi}(\tau) - \, \sum_{k\geq 0} \, \sum_{\sigma\prec \tau} \, \frac{1}{k!} \, \P_k\Big( \widetilde{ g}\big(\downarrow^k\hspace{-2pt} \tau/\sigma\big) , \enskip Y_\sigma  \Big).
		\end{equation}

[Lemma 15 of arXiv:2609.03793, 'Typical martingale diverges on a co-$\sigma$-porous set'] Let $\f\in\M_\infty$ and $r>0$ be arbitrary. Then there exists $\g\in\Mi, \pni{\g-\f}\leq\frac{r}{2}$ such that
\begin{equation}

\forall\varepsilon>0\exists m_0\in\N\forall m\geq m_0\forall u\in2^m\exists w\in2^{12m}\cap u\appinf:
\ab{g_{2m}(w)-g_{12m}(w)}
\geq r-\varepsilon
.
\end{equation}

