body:
[Theorem 2 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] Suppose  $(K_b,K_{\sigma})$ and $(\tilde{K}_b,\tilde{K}_{\sigma})$ satisfy Assumption~\ref{ass:kernel}, Assumption~\ref{ass:coefficients1} is satisfied and assume $X_0, \tilde{X}_0 \in L^p(\Omega)$. Let $(X_t)_{t\in[0,T]}$ and $(\tilde{X}_t)_{t\in[0,T]}$ be the strong solution to the DDSVE \eqref{eq:MFSVE} and \eqref{eq:MFSVE2}, respectively. Then, there is some constant $C>0$, depending on $b$, $\sigma$, $\tilde{b}$, $\tilde{\sigma}$, ${K}_b$, ${K}_\sigma$, $\tilde{K}_b$, $\tilde{K}_\sigma$ and $p$, such that
  \begin{equation}
    \sup_{t\in [0,T]}\E[|X_t-\tilde{X}_t|^p]\leq C \Big( \bE[|X_0-\tilde{X}_0|^p]+\|b-\tilde{b}\|_{\infty}^p+\|\sigma-\tilde{\sigma}\|_{\infty}^p+\|K_b-\tilde{K}_b\|_{q}^p + \|K_\sigma -\tilde{K}_\sigma\|_{2\tilde{q}}^p \Big).
  \end{equation}

[Definition Domain of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] Define recursively
\begin{align*}
{\mathrm D}^{(k,\gamma^{(k)})}=
\begin{cases}
(\mathbb Z^{\nu}) , & \gamma^{(k)}=0;\\
(\mathbb Z^{\nu})^3, & \gamma^{(1)}=1;\\
\prod_{j=1}^3 {\mathrm D}^{(k-1,\gamma_j^{(k-1)})}, & \gamma^{(k)}\in(\Gamma^{(k-1)})^3.
\end{cases}
\end{align*}

[Corollary c:natdyn of arXiv:2605.05904, 'Schr\"odinger's problem with constraints'] Assume the setting of Theorem (thm:first of the paper). Then the following dynamics hold for $t\in [0,1]$:
\begin{align}
    dX^1_t&= \chf_{X^1_t\in E}\left(\sigma(t,X^1_t)dB_t^1 + b(t,X^1_t)dt+\sigma^2(t,X^1_t)\frac{\pi^2_y(t,X^1_t)}{\pi^2(t,X^1_t)}dt\right)\\
    dX^2_t&=\chf_{X^2_t\in E}\left(\sigma(t,X^2_t)dB_t^2 + b(t,X^2_t))dt+\sigma^2(t,X^2_t)\frac{\pi^1_y(t,X^2_t)}{\pi^1(t,X^2_t)}dt\right),
\end{align}
where, for $i=1,2$, $B^i$ is a $(P^*,\cF^{X^i})$-Brownian motion, $\pi^i$ is the function defined in Corollary~(c:conddist of the paper), and $\pi^i_y$ stands for the derivative of $\pi^i$ w.r.t. its second argument.

[Lemma 10 (Martingale Difference Inequality) of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] \
  Let $p\in[1,2]$, and
  let $(Y_{m,i}\,, i=1, \ldots,m\,, m\in\NN )\subset L^p(\PP)$ be an
  array of random variables satisfying
\begin{align}

  \EE
  \Bigg[
  Y_{m,\ell + 1} \, \Bigg{|} \, \sum_{i=1}^{\ell}Y_{m,i}
  \Bigg]
  \ = \
  0
  \qquad\text{for all}\ 1\le \ell \le m-1
  \ \text{and all}\  m\in\NN\,.
\end{align}
\begin{enumerate}
  \item
It holds that
\begin{align}

  \EE
  \left|
  \sum_{i=1}^{m}
  Y_{m,i}
  \right|^p
  \ \le \
  2
  \sum_{i=1}^{m}
  \EE
  \left|
  Y_{m,i}
  \right|^p
  \qquad\text{for all}\ m\in\NN\,.
\end{align}
\item
If there exists a sequence $(Y_i)_{i\in\NN}\subset L^p(\PP)$ such that
  \begin{align}

    \lim_{m\to\infty}
    \sum_{i=1}^m
    Y_{m,i}
     =
    \sum_{i=1}^{\infty}
    Y_{i}
    \quad\text{$\PP$-almost surely, and }\quad
    \liminf_{m\to\infty}
    \sum_{i=1}^m
    \EE|
    Y_{m,i}
    |^p
    \le
    \sum_{i=1}^\infty
    \EE|
    Y_{i}
    |^p
    \,,
  \end{align}
  then
\begin{align}

  \EE
  \left|
  \sum_{i=1}^{\infty}
  Y_i
  \right|^p
  \ \le \
  2 \sum_{i=1}^{\infty}
  \EE
  \left|
  Y_i
  \right|^p
  \,.
\end{align}
\end{enumerate}

