[Defi eq: Hall Littlewood polynomial of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $\lambda=(\lambda_1,\ldots,\lambda_n)\in\Sig_n$ be an integer signature of length $n$. For each integer $m\ge 0$, denote $V_m(t)=\frac{(1-t)(1-t^2)\cdots(1-t^m)}{(1-t)^m}$. Then, the \emph{Hall-Littlewood polynomial} $P_\lambda(x_1,\ldots,x_n;t)$ is defined by

\begin{equation}
P_\lambda(x_1,\ldots,x_n;t) = \frac{1}{V_\lambda(t)} \sum_{\sigma \in S_n} \sigma\left(x_1^{\lambda_1}\cdots x_n^{\lambda_n} \prod_{1 \leq i < j \leq n} \frac{x_i-tx_j}{x_i-x_j}\right)
\end{equation}
where $V_\lambda(t) = \prod_{i \in \mathbb{Z}} V_{m_i(\lambda)}(t)=\frac{1}{(1-t)^n}\prod_{i\in\mathbb{Z}}(t;t)_{m_i(\lambda)}$. Here the notation $(a;q)_n := (1-a)(1-aq) \cdots (1-aq^{n-1})$ for $n \geq 0$, with $(a;q)_0 =1$ and $(a;q)_\infty$ defined in the obvious way.

[Proposition PROP:cha of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $ Q \in \mathbb{Z}$ with $Q>0$, $\delta_\varepsilon=\eta\sqrt{\varepsilon \log \frac 1\varepsilon}$, $d_\varepsilon=\big|\log (\varepsilon \log \frac 1\varepsilon)   \big|$, as in (equation LDPIN2 of the paper) and (equation LDPIN3 of the paper), and let $F$ be a bounded, continuous function. Then  
\begin{align}
&\int_{ \{  \textup{dist}(\phi, \mathcal{M}_Q^{\varepsilon, \, \ge d_\varepsilon} ) <\delta_\varepsilon        \}  } F( \sqrt{\varepsilon}^{-1} (\phi- \pi^\varepsilon(\phi) )  )  \rho_{\varepsilon}^Q(d\phi) \notag \\
&=\overline Z_{\varepsilon}^{-1}  \int \cdots \int_{U_\varepsilon }  F(v)  e^{\frac 1\varepsilon \mathcal{E}_{\xi_1\,\dots,\xi_Q}(\sqrt{\varepsilon}v ) }  
\textup{Det}_{\xi_1,\dots,\xi_Q}(\sqrt{\varepsilon}v) \,  \nu^\perp_{\xi_1, \dots, \xi_Q}(dv)  \,  d\xi_1 \dots, d\xi_Q,  

\end{align}

\noindent
where  $\nu^\perp_{ \xi_1, \dots, \xi_Q }$ is the Gaussian measure in Lemma (LEM:Gauss of the paper), and 
\begin{align*}
&U_\varepsilon:=\big\{ ( \xi_1,\dots, \xi_Q, v )\in  \Delta_Q \times V_{\xi_1,\dots,\xi_Q}: \| \sqrt{\varepsilon} v \|_{L^2 }< \delta_\varepsilon \; \textup{and} \; \min_{i \neq j}|\xi_i-\xi_j | \ge d_\varepsilon    \big\}\\
&\mathcal{E}_{\xi_1,\dots,\xi_Q}(\sqrt{\varepsilon}v )= \int_{-L_\varepsilon}^{L_\varepsilon}  \sin\big(\theta_x m_{\xi_1,\dots,\xi_Q}(x) +(1-\theta_x) \sqrt{\varepsilon}v(x)  \big) \cdot (\sqrt{\varepsilon}v  )^3  dx, \quad |\theta_x| \le 1\\
&\textup{Det}_{\xi_1,\dots,\xi_Q}(\sqrt{\varepsilon}v):=\det\big( \Id-W_{\xi_1,\dots \xi_Q, \sqrt{\varepsilon }v }\big).
\end{align*}

 In (equation CC0 of the paper), the partition function $\overline Z_\varepsilon$ represents the integral  over $U_\varepsilon$ with $F=1$, and $W_{\xi_1, \dots, \xi_Q, \sqrt{\varepsilon}v}$ is the Weingarten map, defined in (equation Wein of the paper).

