[Theorem theo.scenario of arXiv:2411.19145, 'On the intersection of critical percolation clusters and other tree-like random graphs'] Assume $d\ge 7$. There exists $\beta>1$, such that the two following claims hold. 
\begin{itemize}
    \item[(i)] There exist  positive constants $\rho$ and $a<b$, such that 
    $$ \lim_{t\to \infty} 
    \mathbb P\Big(at^{\frac{d}{d-2}} \le |\mathcal R_{\beta t}(\beta t^{\frac 1{d-2}},\rho)|\le bt^{\frac{d}{d-2}} \ \big|\ |R_\infty \cap \mathcal R_\infty|>t\Big) =1. $$
    \item[(ii)] For any $\varepsilon>0$, there exists $\rho>0$, such that 
    $$\lim_{t\to \infty}
 \mathbb P\Big(|R_\infty \cap \mathcal R_{\beta t}(\beta t^{\frac 1{d-2}},\rho)|\ge (1-\varepsilon)t  \ \big|\ |R_\infty \cap \mathcal R_\infty|>t\Big) =1. $$    
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem typP 1 suc of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] Suppressing $n$,
  write $\ell_j = \ell_j(n)$ and $t_j = t_j(n)$.
  Fix a compact subset $K \subseteq M$, 
  and define
  $H^{\mathrm{p}}_{n,K} \coloneqq \bigcap_{j=0}^{N_n-1}\{\hat{X}_{t_j}\in K^k\}$.
  Then there exists a constant $c_K \in (0,\infty)$ such that, for all sufficiently large $n \in \mathbb{N}$,
  \begin{align}
    &\sup_{x\in M}
    \hat{P}_{\diag(x)}\!\biggl(
      H^{\mathrm{p}}_{n,K}
      \cap
      \bigcap_{j=0}^{N_n-1}
      \biggl\{
        \Pi_{c_5h_{\ell_{j+1}}}\!\bigl(B(x,r_{\ell_{j+1}})\bigr)
        \circ\hat{\theta}_{t_j}
        <a_2\varphi_2(r_{\ell_{j+1}})\log\ell_{j+1}
      \biggr\}
    \biggr)\\
    &\leq
    \frac{c_K}{n\log n}.
  \end{align}

[Prop 38 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $A$ be a skew-symmetric $n\times n$-dimensional matrix and let $B$ be a $n\times m$-dimensional matrix. The following Pfaffian evaluation holds: whenever $n+m$ is even
    \begin{equation}
        \pf \left[\begin{array}{cc}
            A & B \\[5pt]
            -B^T & 0
        \end{array}\right] = (-1)^{\binom{n}{2}}\times\begin{dcases}
            \sum_S (-1)^{\sum_i S_i}\pf A_S \det B_{(S^\mathsf{C};[m])} & \text{ if }n>m \\
            \det B & \text{ if }n=m \\
            0 & \text{ if } n<m
        \end{dcases},
    \end{equation}
    and whenever $n+m$ is odd
    \begin{equation}
        \pf \left[\begin{array}{ccc}
            A & \vec{\bm1}_n & B \\[5pt]
            -\vec{\bm1}_n^T & 0 & 0 \\[5pt]
            -B^T & 0 & 0
        \end{array}\right] = (-1)^{\binom{n}{2}+n-m}\times\begin{dcases}
            \sum_S (-1)^{\sum_i S_i}\pf \left[\begin{array}{cc}
                A_S & \vec{\bm1}_{n-m} \\[5pt]
                -\vec{\bm1}^T_{n-m} & 0
            \end{array}\right] \det B_{(S^\mathsf{C};[m])} & \text{ if }n>m \\
            0 & \text{ if } n<m
        \end{dcases},
    \end{equation}
    where the sum is over subsets $S\subseteq\{1,\dots,n\}$ of cardinality $n-m$ and $S^\mathsf{C}$ denotes its complement. We have used the shorthand notation $[m] = \{1,\dots,m\}$.

[Lemma 27 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix $\theta \in (0,\xi_c / 8)$ and $\beta > (1+\theta) / \xi_c$. Fix also $\xi_0 \in (((1+\theta)/\beta) \vee (\xi_c / 2) , \xi_c)$. Then, there exists a choice of the functions $b,M$ (depending only on $\theta,\beta$, and $\xi_0$) such that the following holds for all $\xi \in [\xi_0,\xi_c]$. Fix $\varepsilon \in (0,1)$ and let $U \subseteq \CC$ be a bounded open set. Then, there exists deterministic constant $C>0$ (depending only on $\theta,\beta,\varepsilon,\xi_0$, and $U$) such that the following holds with probability at least $1-\varepsilon$. For all $n \in \NN$ and all $z \in (e^{-n-100} \ZZ^2) \cap U$ such that
\begin{equation*}
    h_{e^{-n}}(z) - h_1(z) \geq 2n -\beta \log n,
\end{equation*}
we have that
\begin{equation*}
    \widetilde{D}_h^{\xi}(\partial B_{e^{-n-50}}(z) , \partial B_{e^{-n/2}}(z)) \leq C n^{-\theta}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 102 (Critical) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $p= \frac{1 + \epsilon}{n}$ with $\epsilon = \lambda n^{-1/3}$, $\lambda \in \R$. Then for all $\delta < 1$
\begin{equation*} 
        \P \Big( \delta n^{1/3} \leq |\cC_1(p)| \leq \delta^{-1} n^{1/3}  \Big) \geq 1 - C(\lambda) \delta,
\end{equation*}
where $C(\lambda) > 0$ is some constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 5 (Kernel-density score rate) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Assume a fixed finite query design, a positive lower bound on local tangent mass, bounded branch jets, and the conditions of \cref{thm:perturbation}. For $N$ independent samples and fixed $\lambda>1$, the score of the empirical Gaussian kernel density estimate (KDE) gives, with probability at least $1-\delta$,
\begin{equation}
\norm{\widehat\theta-\theta}
\le C\left[
\sigma^\alpha
+\sqrt{\frac{\log(M/\delta)}{N\sigma^3}}
+\frac{\log(M/\delta)}{N\sigma^2}
+\text{first-stage error}
\right].

\end{equation}
Ignoring the lower-order Bernstein term and assuming a comparably accurate first stage,
\begin{equation}
\sigma_{\mathrm{opt}}
\asymp \left(\frac{\log(M/\delta)}{N}\right)^{1/(2\alpha+3)},
\qquad
\norm{\widehat\theta-\theta}
=O_{\mathbb P}\!\left(
\frac{\log(M/\delta)}{N}
\right)^{\alpha/(2\alpha+3)}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 108 of arXiv:2601.16377, '2601.16377'] We denote $\mathcal{D}^+$ the set of $(\theta,\hat{n},\hat{A}_1,\hat{A}_2,\hat{B}_1,\hat{B}_2) \in \amsmathbb{R}_{> 0}^2 \times \amsmathbb{R}^4$ cut out by the inequalities
\begin{equation}

\hat{B}_1 - \hat{A}_1 > \theta\hat{n} \quad \textnormal{and} \quad \hat{A}_1 > \hat{A}_2 \quad \textnormal{and}\quad \hat{B}_2 > \hat{B}_1.
\end{equation}
Likewise, we denote $\mathcal{D}^-$ the subset of $\amsmathbb{R}_{> 0}^2 \times \amsmathbb{R}^4$ cut out by the inequalities
\begin{equation}

\hat{B}_1 - \hat{A}_1 > \theta\hat{n} \quad \textnormal{and}\quad \hat{A}_2 > \hat{B}_1 \quad \textnormal{and}\quad \hat{A}_1>\hat{B}_2.
\end{equation}
We set $\mathcal{D} = \mathcal{D}^+ \cup \mathcal{D}^-$.

[Lemma 31 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $b>0$ and let $\mathsf{S}^{(N)}:= (\sfU^{(N)} \sfV^{(N)})$ be a random walk on $\bbR^2$ such that 
    \begin{enumerate}
        \item $\sfS^{(N)}_0 = (0, \lfloor b\sqrt{N} \rfloor )$;
        \item $\sfS_{n+1}^{(N)}-\sfS_n^{(N)}$ is i.i.d.~with mean $0$, and its norm is bounded by some constant independent of $N$; 
        \item $\mathbb{E}[(\sfU^{(N)}_{n+1}-\sfU^{(N)}_{n})^2] = \mathbb{E}[(\sfV^{(N)}_{n+1}-\sfV^{(N)}_{n})^2] = a_{11} $ and $\mathbb{E}[(\sfU_{n+1}^{(N)} -\sfU_{n}^{(N)})(\sfV_{n+1}^{(N)} - \sfV_{n}^{(N)})] = a_{12}$ for some constants $a_{11}$ and $a_{12}$.
    \end{enumerate}
    Let $\tau_N = \inf \{ t:\sfV_{t}^{(N)} \leq 0\}$ and let $B_t = (U_t, V_t)$ be a two-dimensional Brownian motion started from $(0,b)$ with covariance matrix $\begin{pmatrix}
        a_{11} & a_{12}\\
        a_{12} & a_{11}
        \end{pmatrix}$.
        Then as $N\to \infty$,  $(\frac{\sfS_{\lfloor Nt\rfloor}}{\sqrt{N}})_{0\leq t\leq \tau_N} $ converges in distribution to $ (B_t)_{0\leq t\leq \tau} $ where $\tau: = \inf\{t: \sfV_t  \leq 0 \}$ with respect to the metric~\eqref{eq:curve-metric}.

