body:
[Proposition prop: second-order distrib of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $m,n\geq0$, $x\in\mathcal E_{n}$ and $y\in\mathcal E_{m}$. Assume that for all $k\in\Gamma=\mathbb{Z}$,
    \begin{equation}
        \Phi^{(1)}\left(xU_{e_{L},k}\right)=\Phi^{(1)}\left(yU_{e_{L},k}\right)=0.
    \end{equation}
    For $k\in\mathbb{Z}$, we define $x^{(k)}:=xU_{e_{L},-k}=xu^{-k}$ and $ y^{(k)}:=yU_{e_{L},-k}=yu^{-k}.$ For $R,S\geq0$, let
    \begin{equation*}
        X^{(R)}:=\sum_{k=-R}^{R}x^{(k)},\qquad Y^{(S)}:=\sum_{k=-S}^{S}y^{(k)}.
    \end{equation*}
    If $R\geq2n+m,$ and $S\geq n+2m,$ then
    \begin{equation}
        \Phi^{(2)}\left(X^{(R)},Y^{(S)}\right)=\Phi^{(1)}\left(X^{(R)}Y^{(S)}\right).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cumulant_flow of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Suppose that the force coefficients satisfy the flow equation (equation eq:flow2 of the paper), we then have the following equations for their joint cumulants as defined in Definition~(def:joint_cumulant of the paper). 

\begin{enumerate}
\item For $\text{${\boldsymbol{\tau}}$}\in\widehat\mathcal{T}$ such that $r(\text{${\boldsymbol{\tau}}$})\geqslant1$, and recall that $k
=
\min\{i\in[p({\boldsymbol{\tau}})]:r_i=1\}$. We then have
\begin{equs}
\text{$\text{{\Large $\kappa$}}$}_{\eps,\mu}^{\text{\scriptsize{${\boldsymbol{\tau}}$}}}=&-  \sum_{(\text{\scriptsize{${\boldsymbol{\sigma}}$}},\pi,\rho)\in\text{\scriptsize{$\mathrm{Ind}$}}(\text{\scriptsize{${\boldsymbol{\tau}}$}})     }  
\mathrm{A}^{\text{\scriptsize{${\boldsymbol{\tau}}$}}, (\text{\scriptsize{${\boldsymbol{\sigma}}$}},\pi,\rho)}_\mu
\Big(\big(\text{{\Large $\kappa$}}_{\eps,\mu}^{\text{\scriptsize{${\boldsymbol{\lambda}}$}}_q}\big)_{q=1}^{|\rho|}\Big)
       \,.
\end{equs}
\item Next, we turn to $\text{${\boldsymbol{\tau}}$}\in\text{$\widehat\mathcal{T}$}$ such that $r({\boldsymbol{\tau}})=0$, and $|{\boldsymbol{\tau}}|>0$. 
We then have 

\begin{equs}
\text{$\text{{\Large $\kappa$}}$}_{\eps,\mu}^{{\boldsymbol{\tau}}}=&-  
\sum_{k = 1}^{p({\boldsymbol{\tau}})} 
\sum_{(\text{\scriptsize{${\boldsymbol{\sigma}}$}},\pi,\rho)\in\text{\scriptsize{$\mathrm{Ind}$}}(\text{\scriptsize{$\mathbf{d}_{k}$}}\text{\scriptsize{${\boldsymbol{\tau}}$}})     } 
\int_0^\mu
\mathrm{A}^{\text{\scriptsize{$\mathbf{d}$}}_{k}{\boldsymbol{\tau}}, ({\boldsymbol{\sigma}},\pi,\rho)}_\nu \Big(\big(\text{{\Large $\kappa$}}_{\eps,\nu}^{\text{\scriptsize{${\boldsymbol{\lambda}}_q$}}}\big)_{q=1}^{|\rho|}
\Big)\mathrm{d}\nu
       \,.
\end{equs}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: large deviation for Tk in sle of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] For any $\kappa_2\in (0,0.1)$, there exists  a constant $c_9=c_9(\kappa_2)>0$ such that for any $\lambda>0$, we have \begin{equation}
        \mu^{\pm}_{\Lambda_N,0}(T_k\ge \lambda\cdot 2^{\frac{7k}{4}-\kappa_2 k})\le c_9\exp\big(-c_9^{-1}\lambda^{\frac{8}{5}} 2^{(\frac{3-16\kappa_2}{5})k} \big).
    \end{equation}

[Prop 14 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $S$ be a finite set of places of $F$ containing all the archimedean and ramified places of $F$ such that $\phi\in\mathcal{S}([\bar{G}_n])$ is right invariant by $K_{n,v}$ for each $v\notin S$. Moreover, we choose a $\Phi\in\mathcal{S}(\A^n)$ such that $\Phi_v=\mathbbm{1}_{\o_v^n}$ for all $v\notin S$, as in \S\ref{sec:unramified-local-choice}. Then, for sufficiently large $\Re(s)$ we have
		\begin{multline*}
			I_2^{\mathrm{D}}(s)=\V\sum_{\pi\in\Pi_{\mathrm{c}}(\bar{G}_2)}\sum_{\varphi\in\B\left(\1_{n-2}\boxplus\pi\right)}\left\langle\phi,\Eis(\varphi, \ol{\lambda_{\mathrm{D}}(s)})\right\rangle_{[G_n]^1 }\\
			\frac{L^S\left(\tfrac{n-1}{2}+\tfrac{n}{2}s,\pi\right)L^S\left(\tfrac{1}{2}+\tfrac{n}{2}s,\pi\right)}{\sqrt{L^S(1,\pi,\Ad)}}
			\optionA{\P_S(-\lambda_{\mathrm{D}}(s);\varphi,f,f_s)}
			\optionB{\P_S(s,-\lambda_{\mathrm{D}}(s);\varphi,\Phi)},
		\end{multline*}
		and
		\begin{multline*}
			I_2^{\mathrm{C}}(s)=\frac{\V}{2}\sum_{\chi\in\Pi(G_1)}\sum_{\varphi\in\B(\1_{n-2}\boxplus\chi\boxplus\chi^{-1})}\intop_{i\mathbb{R}}\left\langle \phi,\Eis(\varphi,\overline{\lambda_{\mathrm{C}}(s,z)})\right\rangle_{[G_n]^1 }\\
			\frac{\prod_{\pm}L^S\left(\tfrac{n-1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm\right)L^S\left(\tfrac{1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm\right)}{L^S(1+2z,\chi^2)}
			\optionA{\P_S(-\lambda_{\mathrm{C}}(s,z);\varphi,f,f_s)}
			\optionB{\P_S(s,-\lambda_{\mathrm{C}}(s,z);\varphi,\Phi)}
			\, dz,
		\end{multline*}
		where $I_2^{\mathrm{D}}$ and $I_2^{\mathrm{C}}$ are as in \eqref{eq:def-I2-disc} and \eqref{eq:def-I2-cont}, respectively;
		and $\P_S:=\prod_{v\in S}\P_v$ where $\P_v$ is as in \eqref{eq:main-RS-period-local}.

[Proposition 9 of arXiv:2604.00742, 'Delayed Logistic equation as a limit\\ of long memory Markov chains'] The entire initial condition converges uniformly on the interval $[-\tau,0]$, i.e, 
	\begin{equation*}
		\lim_{N \rightarrow \infty}\sup_{t \in [-\tau,0]}|Y^{N}(t)-\mu| \;=\; 0
	\end{equation*}
	in probability. In particular, the sequence $\{Y^N(t) : t \in [-\tau,0]\}_{N\geq 1}$ is tight in $D([-\tau,0], \mathbb{R})$ with respect to the Skorokhod topology.

