[Corollary cor_join_bounds of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] For~$x$ and~$t$ as in Lemma~(lem_T_t_and_T of the paper), we have
	\begin{equation}
		\p (| T(x) - Y_{t,x}| \ge \mathfrak C t ) \le 2^{-\Kprime \|x\|} + e^{-\mathfrak{c} t} + \|x\|^{4d} e^{-\mathfrak{c}_1 t},
	\end{equation}
	where~$\Kprime$ is defined in~(equation eq_def_Kprime of the paper),~$\mathfrak C$ and~$\mathfrak c$ are the constants of Lemma~(lem_q_and_no_q of the paper), and~$\mathfrak c_1$ is the constant of Lemma~(lem_T_t_and_T of the paper).

[Theorem thm-Ito-JS-I.4.57 of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Suppose that $\xi$ is  real-valued  semimartingale. Then for every $t\geq 0$, almost surely
\begin{align}
  \xi(t)^2 &=\xi(0)^2+ \int_0^t 2 \xi(s-)\, \mathrm{d} \xi(s) + \langle \xi^{\mathrm{c}}\rangle(t) + \sum_{s\leq t}  (\Delta \xi(s))^2, \\

&=\xi(0)^2+ \int_0^t 2 \xi(s-) \, \mathrm{d} \xi(s)+ [\xi](t).
\end{align}

[Theorem 26 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] Assume condition \eqref{eq:assumptions2}. The following holds.
    \begin{enumerate}
        \item  If $k <k_c$, there are stationary solutions.

        \item  If $k =k_c$, then every well defined solution $u$ decays like $\|u(t)\|_\infty\leq \mathcal O(t^{-\frac{d}{2}}) $.
        \item  If $k>k_c$, and the solution $u$ is uniformly bounded in time and space, i.e. $u \in L^\infty_{t,x}$, then decays like $\|u(t)\|_\infty\leq \mathcal O(t^{-\frac{d}{2}}) $.
    \end{enumerate}

