[Lemma 3.9 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] For all $0<u\le 1$, there exists $K_2(u_1,u)$ such that for all $n>n_2(u_1)$ and $z\in\mathbb R^3$ with $|z|\ge2^{-n}$, we have
    \begin{equation*}
        \mathbb{P}_{z}\Big(\tau_{\mathscr{T}}^{[K_2n^2]}<L_{B(0,2)}\Big)<u^n.
    \end{equation*}

[Theorem 166 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let   $t_{0}>0$,
$f\in E_{p,\beta}$, and assume
that $Ef^{2}(x_{t_{0}})<\infty$. Then 


(i) With probability one   we
have
\begin{equation}

 f(x_{t_{0}})=   T_{0,t_{0}}f(x_{0})+\int_{0}^{t_{0}}\sigma^{ik}D_{i}
   T_{t_{1},t_{0}}f(x_{t_{1}})\,dw^{k}_{t_{1}},
\end{equation}
where $\sigma^{ik}D_{i}
   T_{t,s}f(x )= \sum_{i}\sigma^{ik}(t,x)D_{i}
   T_{t,s}f (x )$ and similar notation is also used below;

(ii) We have
\begin{equation}

   T_{0,t_{0}}f^{2}(x_{0})=(   T_{0,t_{0}}f(x_{0}))^{2}+
\sum_{k}\int_{0}^{t_{0}}   T_{0,t_{1}}\Big[\Big( 
\sigma^{ik}D_{i}   T_{t_{1},t_{0}}f\Big)^{2}\Big](x_{0})\,dt_{1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\phi\in \mathcal{S}([G_n]^1 )$ and $k\in K_n$. Recall $\V$ from \eqref{def-mathcal-V}. For $s,z\in\C$ recall $\lambda_{\mathrm{D}}(s)$ and $\lambda_{\mathrm{C}}(s,z)$ from \eqref{eq:def-lambda-discrete} and \eqref{eq:def-lambda-cont}. Then for $h\in G_2(\A)$ we have
		\begin{multline*}
			\V^{-1}\int_{[G_{n-2}]}\phi_{\Q_{n-2}}\left[\pmat{g&\\&h}k\right]|\det g|^{s-1}\, dg=\sum_{\pi\in\Pi(\bar{G}_2)}\sum_{\varphi\in\B\left(\1_{n-2}\boxplus\pi\right)}\IP{\phi,\Eis(\varphi, \ol{\lambda_{\mathrm{D}}(s)})}_{[G_n]^1 }\\
			\varphi_{-\lambda_{\mathrm{D}}(s)}\left[\begin{pmatrix}\mathrm{I}_{n-2}&\\&h\end{pmatrix}k\right](1)+\frac{1}{2}\sum_{\chi\in\Pi(G_1)}\sum_{\varphi\in\B(\1_{n-2}\boxplus\chi\boxplus\chi^{-1})}\intop_{i\mathbb{R}}\left\langle \phi,\Eis(\varphi,\overline{\lambda_{\mathrm{C}}(s,z)})\right\rangle_{[G_n]^1 }\\
			\Eis^{\Q_{n-2}}(\varphi,-\lambda_{\mathrm{C}}(s,z))\left[\begin{pmatrix}\mathrm{I}_{n-2}&\\&h\end{pmatrix}k\right]\, dz
		\end{multline*}
		if $\Re(s)$ is sufficiently large. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 27 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] For every $H\in(0,1)$, define the measure
\begin{align}

\dd\mu_H(x)=
\frac{\Ga(2H+1)}{2\Ga(H)\Ga(1-H)}|x|^{1-2H}\d x
\qquad x\in\mbb R.
\end{align}
Then, define $\mu=\mu_{H_1}\otimes\cdots\otimes\mu_{H_d}.$
For the time covariance, we denote
\begin{align}

\nu=
\begin{cases}
\mu_{H_0}&\text{if }H_0<1,\\
\de_0&\text{if }H_0=1.
\end{cases}
\end{align}

