[Prop partition of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given a random set of good cubes $\mathcal{G}\subseteq \mathcal{T}$ satisfying (equation e:local_dependence of the paper), then for any cube ${\scaleobj{1}{\square}} \in \mathcal{G}$, there exists its local partition of good cubes denoted by $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}}) \subseteq \mathcal{G}$, such that the following properties hold:
		\begin{enumerate}
			\item All predecessors of elements of $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ in ${\scaleobj{1}{\square}}$ are good: for every ${\scaleobj{1}{\square}}', {\scaleobj{1}{\square}}'' \in \mathcal{T}$, 
			\begin{align*}
				{\scaleobj{1}{\square}}' \in  \mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}}) \text{ and } {\scaleobj{1}{\square}}'  \subseteq {\scaleobj{1}{\square}}'' \subseteq {\scaleobj{1}{\square}}  \Longrightarrow {\scaleobj{1}{\square}}''  \in  \mathcal{G}.
			\end{align*}
			\item Neighboring elements of $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ have comparable sizes: for every ${\scaleobj{1}{\square}}', {\scaleobj{1}{\square}}'' \in \mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ such that $\operatorname{dist}({\scaleobj{1}{\square}}', {\scaleobj{1}{\square}}'')\leqslant 1$, we have
			\begin{equation}

				\frac{1}{3}\leqslant \frac{\size({\scaleobj{1}{\square}}'')}{\size({\scaleobj{1}{\square}}')}\leqslant 3.        
			\end{equation}
			\item Locality: the partition $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ is $\mathcal{F}(3 {\scaleobj{1}{\square}})$-measurable.
			\item Estimate for the coarseness of $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$: if we also assume the tail event estimate (equation e:rarely_bad of the paper) for $\mathcal{G}$, then there exists a finite positive constant $C(K,s)$, such that for any ${\scaleobj{1}{\square}}$ and any $x \in {\scaleobj{1}{\square}}$, we have
			\begin{equation}

				 \mathbb{P}\left[\size({\scaleobj{1}{\square}}_{\mathcal{S}^{loc}_{\mathcal{G}}}(x)) \geqslant t\right] \leqslant \exp(-C^{-1}t^s),
			\end{equation}

			where we denote by ${\scaleobj{1}{\square}}_{\mathcal{S}^{loc}_{\mathcal{G}}}(x)$ the unique cube in partition $\mathcal{S}^{loc}_{\mathcal{G}}({\scaleobj{1}{\square}})$ containing $x$.
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm t:KPZ-to-landscape-reformulated of arXiv:2607.18194, 'Temperature chaos in directed polymers'] We have the following weak convergence
    of $C(\mathbb{R}^{4}_{\uparrow})$-valued random variables:
    \begin{align}
        \frac{2^{1/3}}{n^{1/3}}
        \left(
            \mathcal{H}^{\xi,(n)}(s,x;t,y)
            +
            \frac{(t-s)n}{24}
        \right) 
        \xrightarrow[n\to\infty]{d} \mathcal{L}(s,2^{-1/3}x; t, 2^{-1/3}y),
    \end{align}
    where $\mathcal{H}^{\xi,(n)}$ was defined in (equation e:def-Hn of the paper), and where $\mathcal{L}$ is the directed landscape (see (d:dl of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] For $\theta\neq 0$ and $a>-1$, we have on the common domain of convergence    \begin{align}
        \hat{P}_{a,y,\theta}(z)=\frac{\hat{Q}_{a,y,\theta}(-z)}{1-z\cdot\hat{Q}_{a,\theta}(-z)}.
    \end{align}

