body:
[Definition def:trees of arXiv:2411.07157, 'Rough differential equations in the flow approach'] We associate to any $\underline{\tau}  \in \boldsymbol{\mathfrak{T}}$, an \textit{order} ${\mathfrak{o}}(\underline{\tau}) \eqdef |E(\underline{\tau})|$, a \textit{size} $\mathfrak{s}(\underline{\tau}) \eqdef |N(\underline{\tau})| = |E(\underline{\tau})|+1$, and a \textit{scaling} $|\underline{\tau}|$ defined by
    \begin{equs}
        |\underline{\tau}|\eqdef -1+\mathfrak{s}(\underline{\tau})H\equiv -1+({\mathfrak{o}}(\underline{\tau})+1)H\,.
    \end{equs}
All these quantities are well-defined for elements of $\mathfrak{T}$ as well and we overload notation accordingly. 

For $k\in\N$, we denote by $\mathfrak{T}_{\leqslant k}$ the set of all trees $\tau\in\mathfrak{T}$ with ${\mathfrak{o}}(\tau)\leqslant k$, and let
\begin{equs}
    \mathcal{T}\eqdef\mathfrak{T}_{\leqslant 2}\equiv\Big\{ \raisebox{0ex}{\includegraphics[scale=1.2]{figures/Xi.pdf}},\raisebox{-0.5ex}{\includegraphics[scale=1.2]{figures/XiX.pdf}},\raisebox{-1ex}{\includegraphics[scale=1.2]{figures/Tree1.pdf}},\raisebox{-.5ex}{\includegraphics[scale=1.2]{figures/Tree2.pdf}}\Big\}\,,
\end{equs}    
where in the graphical representation for trees, we always draw the root as the bottom node. 

We also define 
\begin{equs}
    \mathcal{T}_*\eqdef \{\raisebox{+0.05ex}{\includegraphics[scale=1.5]{figures/Xi.pdf}}\}\cup
    \Bigg\{\tau\in\mathfrak{T}_{\leqslant5} :
\begin{array}{c}
\exists\, \underline{\tau}_1\in\tau_1\in\mathcal{T}\,,\;\underline{\tau}_2\in\tau_2\in\mathcal{T},\text{ and}\;n\in N(\underline{\tau}_1)\\
\text{such that}\;\underline{\tau}_2\graft_n\underline{\tau}_1\in\tau
\end{array}
    \Bigg\}\,.
\end{equs}
Observe that $\mathcal{T}\subset\mathcal{T}_*$ and
\begin{equs}
    \tau\in\mathcal{T}_*\setminus\mathcal{T}\Rightarrow{\mathfrak{o}}(\tau)\geqslant3\Rightarrow|\tau|\geqslant\delta\eqdef-1+4H>0\,.
\end{equs}

[Lemma 9 of arXiv:2606.22044, 'Degenerate Stochastic Delay Modified Equation: Approximation of Stochastic Variance Reduce'] Let $\tilde{z}_{s}=z_{sm}$, $\eta\in(0,1)$ and $m\eta\geq1$. Then, for any $s\geq0$, it follows
\begin{align}
\mathbb{E}|\tilde{z}_{s}|^{2}\leq C_{1}e^{C_{2}ms\eta}(1+\mathbb{E}|\tilde{z}_{0}|^{2}),
\end{align}
where $C_{1},C_{2}$ are certain positive constants that do not depend on $m$ or $\eta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $g:\mathbb{R}^n \rightarrow \mathbb{R}$ be Borel measurable such that
   \begin{equation}
   \forall x,y \in \mathbb{R}^n, \ x_i \leq y_i, \ i=1,...,n, \implies g(x) \leq g(y).
   \end{equation} 
   Let $f \in \mathcal{B}_R^n$ \eqref{BRTR} be an $n$-tuple of right tails. Then, 
   \begin{equation}
   \sup_{X \in \mathcal{T}_R(f)} P(g(X) \geq t) = P(g(\widetilde{X}) \geq t), \ \forall t \in \mathbb{R}.
   \end{equation}

[Lem 143 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix $\gamma''>0,\gamma'''\in\mathbb R$. Let $\mu\in\mathbb R$, $\mathfrak H_{q,\gamma'',\gamma'''}$ be as in \eqref{approxG2} and let
  \begin{eqnarray}
 		X=\hat x+\frac{\mathfrak d q}{2\gamma''} (\mu \hat x+\gamma'' \hat x^2);
		\qquad
		Y={\hat y}.
  \end{eqnarray}
  Then,
  \begin{eqnarray}

    \frak H_{q,\gamma''+\mu q \md,\gamma'''+3\gamma'' q}(\hat x,{\hat y})=    \frak H_{0,\gamma'',\gamma'''}(X,Y)+\mathcal O(q \md^2+q^2\md).
  \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:2 of arXiv:2604.20094, 'Persistence and local extinction for superprocesses in random environments'] Let $d\geqslant 1$. Suppose that   $a>0 $ and
	  	 \begin{equation}
  	 	\begin{aligned}
  {\mathcal C}(x, y)=a \Theta(x-y)   \quad \hbox{ for some } \Theta\in C^\beta({\mathbb R}^d) \mbox{ with } \beta>1 \hbox{ and } \Theta(0)=1.
	 	\end{aligned}
  	 	 \tag{{\bf H$_\Theta$}}
  	\end{equation}
  	There exists  a constant $N_0:=N_0(d, \Theta)\geqslant 1$ such that if $a\geqslant N_0$, then for any compact set $K\in {\mathbb R}^d$ there exists a random time $T_K<\infty$ a.s. so that
  	$X_t(K)=0$ for every $ t\geqslant T_K$. (Proof in the paper; no proof environment follows the statement in the TeX.)

