body:
[Theorem 1 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] When we are in Scenario \eqref{Scenario_1}, and the samples are drawn with replacement, the sequence $\left\{\left(n^{-1}A_{n},n^{-1}B_{n}\right)\right\}$ converges, almost surely, to a (possibly sample path dependent) compact connected internally chain transitive invariant set, contained in $\mathcal{S}$, corresponding to the autonomous ODE:
\begin{equation}
\left(\dot{x}(t),\dot{y}(t)\right)=h\left(x(t),y(t)\right) \text{ for } t\geqslant 0, \quad \text{with} \quad \left(x(0),y(0)\right)\in\mathcal{S},
\end{equation}
where the function $h$ is as defined in \eqref{h_H_defns} and $\mathcal{S}$ is as defined in \eqref{domain_defn}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2609.02790, 'Full-Model Optimality for Tunable Linear Generative Priors in Compressed Sensing'] Let $M\in \R^{m\times m}\succeq 0,\widetilde{M}\in \R^{m\times m} \succeq 0$ be positive semidefinite (PSD) matrix, 
    $\widetilde{M} $ is the perturbation of $M$, we have 
    \begin{align*}
    \big(M+\widetilde{M}\big)^{-1} - M^{-1}+M^{-1}\widetilde{M}M^{-1}  \succcurlyeq 0 
    \end{align*}

[Lemma 17 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] For $p > 0.391$, 
\begin{equation}
    \polymerpf^\cE_2 \psim e^{\Delta^\cE}
    \qquad \text{and} \qquad
    \fakepolymerpf^\cE_2 \psim e^{\tilde{\Delta}^\cE}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 45 of arXiv:2609.00245, 'Higher-order Gaussian bounds for maximally subelliptic boundary value problems'] Let \(\sI\) be an index set, and for \(\iota \in \sI\) let \(X_1^\iota,\ldots, X_{q_\iota}^\iota\in \CbinftySpace[U][\Rn]\)
    be smooth vector fields on \(U\). We say \(X_1^\iota,\ldots, X_{q_\iota}^\iota\) \emph{span the tangent space to \(U\),
    uniformly for \(\iota\in \sI\)} if
    \begin{equation*}
        \inf_{\iota\in \sI} \inf_{x\in U} \max_{j_1,\ldots, j_n\in \left\{ 1,\ldots, q_\iota \right\}}
         \left|\det \left(  X_{j_1}^\iota (x) | X_{j_2}^{\iota}(x) | \cdots | X_{j_n}^\iota(x) \right)  \right|>0,
    \end{equation*}
    where \( \left(  X_{j_1}^\iota (x) | X_{j_2}^{\iota}(x) | \cdots | X_{j_n}^\iota(x) \right) \)
    is the \(n\times n\) matrix whose \(k\)-th column is \(X_{j_k}^\iota(x)\) written as a column vector.

[Definition 24 of arXiv:2601.16377, '2601.16377'] Given a weight $w_h(x)$ as in \eqref{eq_ansatzw} and $h\in[H]$ we define two holomorphic functions $\Phi^{\pm}_h(z)$ of $z \in \amsmathbb{M}_{h}$ satisfying
\begin{equation}

\forall x \in [\hat a_h,\hat b_h]\qquad \frac{w_{h}\big(\N x+\frac{1}{2}\big)}{w_{h}\big(\N x-\frac{1}{2}\big)} =
 \frac{\Phi^+_h(x)}{\Phi^-_h(x)}.
\end{equation}
They are specified by
\begin{equation}
\begin{split}

\Phi^+_h(z) & := e^{-\N[U_h(z+\frac{1}{2\N})-U_h(z-\frac{1}{2\N})]} \cdot \prod_{j=1}^{\iota_h^+} \bigg(\hat b_h - z-\frac{1}{2\N} + \frac{\rho^+_{h,j}}{\N}\bigg), \\
\Phi^-_h(z) & := \prod_{j=1}^{\iota_h^-} \bigg(z-\hat a_h -\frac{1}{2\N}+ \frac{\rho^-_{h,j}}{\N}\bigg).
\end{split}
\end{equation}
We also define holomorphic functions $\phi^\pm_h(z)$ of $z \in \amsmathbb{M}_{h}$ satisfying a $\N=\infty$-version of \eqref{eq_ratio_weights} (although they may still be $\N$-dependent as $V_h$ can depend on $\N$)
\begin{equation}
 \forall x \in [\hat{a}'_{h},\hat{b}'_{h}]\qquad
\frac{\phi^{+}_{h}(x)}{\phi^{-}_{h}(x)} = e^{-\partial_x V_h(x)}.
\end{equation}
They are specified by
\begin{equation}

\phi^+_h(z):= e^{-\partial_zU_h(z)} \cdot \big(\hat b'_h - z\big)^{\iota_h^+},\qquad
\phi^-_h(z):= \big(z-\hat a'_h\big)^{\iota_h^-}.
\end{equation}

[Proposition 24 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] Every multiple positive eigenvalue $\Lambda$ of $A_\mu$ admits $q\in Q$ such
that
\begin{equation}
 B_q^\Lambda(\mu)
 \quad\text{has }\dim E_\mu(\Lambda)\text{ distinct eigenvalues}.

\end{equation}

