[Prop 10 of arXiv:2609.03819, 'Stochastic damped wave and Euler-Bernoulli equations with singular locally H\"older contin'] Assume that Hypotheses \ref{H0}, \ref{H0.5} and \ref{H1} hold and let $\vartheta\in [0,1)$. For every $n\in\N$, $\varphi\in C^\vartheta_b(H_n)$ and $t>0$ we have
\begin{align}
&\norm{\mathcal{V}_n^*\nabla(R_n(t)\varphi)}_{C_b^\vartheta(H_n;U)}\leq\left(\|e^{tA_n}\mathcal{V}_n\|_{\mathcal{L}(U,H_n)}^\vartheta\|\Gamma_{t,n}\mathcal{V}_n\|_{\mathcal{L}(U,H_n)}^{1-\vartheta}+\|\Gamma_{t,n}\mathcal{V}_n\|_{\mathcal{L}(U,H_n)}\right)\|\varphi\|_{C^\vartheta_b(H_n)},\\
&\norm{R_n(t)\varphi}_{C^{1+\vartheta}_{b,\mathcal{V}_n}(H_n)}\leq\left(1+\|e^{tA_n}\mathcal{V}_n\|_{\mathcal{L}(U,H_n)}^\vartheta\|\Gamma_{t,n}\mathcal{V}_n\|_{\mathcal{L}(U,H_n)}^{1-\vartheta}+\|\Gamma_{t,n}\mathcal{V}_n\|_{\mathcal{L}(U,H_n)}\right)\|\varphi\|_{C^\vartheta_b(H_n)}.
\end{align}

[Lemma 7 of arXiv:2605.24445, 'Matrix concentration inequalities for time-inhomogeneous Markov chains'] \label[lemma]{lem:coeff_spec}
Let \(\phi \in [-\pi/2,\pi/2]\) and \(0 \le s \le 1/(8\Delta_{\op})\). Then,
\begin{enumerate}
\item[(i)] \(b_{n,1}(\phi)\le \exp(2s^2\Delta_{\op}\Delta_{\mathrm F})\).
\item[(ii)] For each \(i\ge 2\),
\begin{equation}
b_{n,i}(\phi)
\le
4\, s^2\,\Delta_{\op}\Delta_{\mathrm F}\, e^{s\Delta_{\op}} \prod_{\ell=n-i+2}^{n} (e^{s\Delta_{\op}}\sigma_{\ell}).
\end{equation}
\end{enumerate}

