		=
		r_v-1+g d_v.
		$
		\item $\dim_{\mathbb F_p}
		\left(L_v^\times/L_v^{\times p}\right)_{\N\equiv 1}
		=
		2(r_v-1)+2g d_v.$ 

		\item $\dim_{\mathbb F_p}
		\left(
		\mathcal O_{L_v}^{\times}/\mathcal O_{L_v}^{\times p}
		\right)_{\N\equiv 1}
		=
		r_v-1+2g d_v.$
	\end{enumerate}

