[Theorem 16 (Doob's optional stopping version I, supermartingale $\{f_j \equiv \overline{\sigma}_j f\}$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] \hspace{.1in}

\noindent
Let $f \in Q$, $\rho \leq \tau$ be two stopping times and set $f_j = \overline{\sigma}_j f$, $j \geq 0$. Then
\begin{enumerate}
\item
\begin{equation} \nonumber
\overline{\sigma}_{\rho} f^{\tau}_k \leq f^{\rho}_k\;\;\mbox{for all}\;\; k \geq 0.
\end{equation}

\item 
\begin{equation} \nonumber
\overline{\sigma}_{\rho} f_{\tau} \leq f_{\rho}~\mbox{on}~\mathcal{S}.
\end{equation}
\end{enumerate}

[Defn def-fsf of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] The \textbf{$\mathfrak c$-free spanning forest ($\mathfrak c$-FSF)} of $\mathcal G$ is the random spanning forest $\mathcal T^{\operatorname{FSF}}$ of $\mathcal G$ with the following property. Let $\{\mathcal G_n\}_{n\geq 1}$ be an increasing family of finite connected subgraphs of $\mathcal G$ whose union is all of $\mathcal G$. Let $\mathcal T_n$ be the $\mathfrak c$-spanning tree of $\mathcal G_n$. Then for any fixed finite set of edges $E\subset\mathcal G$, we have 
\begin{equation} 
E \cap \mathcal T_n \to E \cap \mathcal T^{\operatorname{FSF}} 
\end{equation} 
in the total variation sense.

