body:
[Cor 136 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $C>1$ be a fixed constant. 
	Denote $\gamma'' = \gamma_{x^{SW}_{q;a,b,c}}'',\gamma'''=\gamma_{x^{SW}_{q;a,b,c}}'''$, and let
	\begin{flalign}

		x = x^{SW}_{q;a,b,c} + \mathfrak{d} \hat{x}; \qquad y =  \mathfrak{d}^2 \hat{y}.
	\end{flalign}	
Assume that $z=(x,y)\in \mathfrak L_{q;a,b,c}$ with {$\me_{z;q}\ge (1/C) \md, \md_z\asymp \md$.}	
	\noindent Denoting  
	\begin{flalign}

		\hat{f}(\hat{x}, \hat{y}) = \mathfrak{d}^{-1} \cdot f(x,y); \qquad \Gamma_{\hat{x}} = \gamma''+\md\hat x(\gamma'''-\gamma''\log {\mathfrak q}+4 \gamma''^2).          
	\end{flalign}

	\noindent we have 
	\begin{flalign}
		\hat{f} (\hat{x}, \hat{y}) & =  \mathrm{i} \Gamma_{\hat{x}}^{1/2}  \Big( 2 \hat{y} - \gamma'' \hat{x}^2 - \displaystyle\frac{\gamma'''}{3} \mathfrak{d} \hat{x}^3 \Big)^{1/2}  - \gamma'' \hat{x}  - \mathfrak{d} \Big( \gamma''^2 + \displaystyle\frac{\gamma'''}{2} \Big) \hat{x}^2         + \mathfrak{d} g  \Big(\hat{y}- \gamma''\displaystyle\frac{\hat{x}^2}{2} \Big)  + \mathcal{O} ( \mathfrak{d}^2),
	\end{flalign}
        where $A',B',D'$ are as in \eqref{DAB} with $x=x^{SW}_{q;a,b,c}$ and
        \begin{eqnarray}

    g=g(q,a,b,c):= \mathfrak{q}^{x_{q;a,b,c}^{SW}} A'^{-1} D' (D' A'^{-1} B' - f_0'' (0)).
  \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2506.21087, 'Quasi-Stationary Distributions of Interacting Dynamical Systems and their approximation'] Let $h>0$. Assume \ref{condhmv} and \ref{condhtronc}. Assume that

there exists $\alpha>0$ such that $\ES[|\zeta_h|^\alpha]<+\infty$ and that $\zeta_h$ has a ${\cal C}^1$ density $g_h$ w.r.t. the Lebesgue measure with $\|g_h\|_\infty+\|\nabla g_h\|_\infty<+\infty$. Also assume that the following condition holds: for every $M>0$ and $(s_1,s_2)\in(0,+\infty)^2$ with $s_1\le s_2$, there exist $c_1,c_2>0$,  and an integrable function $\mathfrak{p}_h:D\mapsto (0,+\infty)$ such that for every $m\in B(0,M)$ and $\sigma\in \mathbb{M}_{d,d}$ with $s_1\le |{\rm det}(\sigma)|\le s_2$,
\begin{equation}
\forall z\in D, \quad c_1 \mathfrak{p}_h(z)\le g_h\left(\sigma^{-1}(z-m)\right)\le c_2 \mathfrak{p}_h(z).
\end{equation}

Then, if $(\gamma_n)$ satisfies \eqref{hyp:pas} and $\sum \gamma_n^2<+\infty$, $(\mu_n)$ is almost surely tight in ${\cal P}(\bar{D})$ and every weak limit $\mu^\star_h$ is a QSD for $(\tilde{K}_{\mu,\partial}^{(h)})_{\mu \in {\cal P}(\bar{D})}$ which satisfies $\mu^\star_h(\partial D)=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $H_N$ be an IRM matrix   defined in Definition (def:inhomo of the paper) but with real/complex Gaussian entries replaced by (equation equ:mix_gaussian of the paper),  the following limits for the largest eigenvalue $\lambda_1$ hold.
\begin{enumerate}
    \item[(1)] If $0\le \alpha\ll N^{-\frac{1}{6}}$, then 
    \begin{equation}
        N^{\frac{2}{3}}(\lambda_1-2)\overset{D}{\rightarrow} \mathrm{TW}_1.
    \end{equation}
    \item[(2)] If $N^{-\frac{1}{6}}\ll \alpha\le \infty$, then 
    \begin{equation}
        N^{\frac{2}{3}}(\lambda_1-2)\overset{D}{\rightarrow}  \mathrm{TW}_2.
    \end{equation}
\end{enumerate}

[Lemma lem:kernel of arXiv:2608.24830, 'Motion helps the contact process: survival below\\ the percolation threshold on Poisson Br'] There are constants $c,C$ depending only on $d$ such that, for all $\Delta>0$ and all
$x,x_1,x_2,y\in\mathbb{R}^d$,
\begin{enumerate}[(H1)]
\item $q_\Delta(x,y)\le(2\pi\Delta)^{-d/2}$;
\item $|q_\Delta(x_1,y)-q_\Delta(x_2,y)|\le c\,\Delta^{-(d+\kappa)/2}|x_1-x_2|^{\kappa}$
  with $\kappa=1$;
\item $\mathbb{P}_x\big[\sup_{s\le t}|B_s-x|\ge R\big]\le4d\,e^{-R^2/(2dt)}$ for $R,t>0$;
\item $\displaystyle(2\pi\Delta)^{-d/2}\int_{|z-y|\ge R}
  \exp\Big\{-\frac{(|z-y|-\varsigma)^2}{2\Delta}\Big\}\,\mathrm dz\ \le\ C\,e^{-R^2/(16\Delta)}$
  whenever $0\le2\varsigma\le R$.
\end{enumerate}

[Lemma 52 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $(\XX,\varrho)$ be a quasi-metric space and let $\emptyset \ne\SC\subset \XX$ be a subset.
  Then
  \begin{equation*}
      \tau\big(\SC, \varrho\big\vert_{\SC\times \SC}\big)
      = \tau(\XX,\varrho) \sigmacap\SC. 
  \end{equation*}

[Corollary 11 (Full Hausdorff convergence in the nonzero case) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Under the hypotheses of Corollary~\ref{cor:classification}, if
$\Var_T\neq0$, then
\begin{equation}

 F_t(\Sigma)\longrightarrow\spt\Var_T
 \qquad\text{in Hausdorff distance as }t\nearrow T.
\end{equation}

[Proposition HNNI-MAIN of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $q \in {\mathbb{Z}^ + }$ and $t \in \mathop  \cap \limits_{j = 0}^q \left[ {0,{\mathfrak{t}_j}} \right]$, there exists a real number $\alpha \in \left( {\frac{\beta }{{b}},\beta } \right)$ such that the Nash elements of the Euler–Reynolds system (equation ERNE-3A.1 of the paper) satisfy the following inductive estimates
\begin{equation}
{\left\| {{u_q} } \right\|_0} + {\left\| {{v_q}} \right\|_0} + {\left\| {{\mathfrak{p}_q}} \right\|_0} \leqslant C  , 
\end{equation}
\begin{equation}
{\left\| {{u_q} } \right\|_N} + {\left\| {{v_q}} \right\|_N} + {\left\| {{\mathfrak{p}_q}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}\lambda _q^N  ,  \ \ \forall \ N \in \left\{ {1, \cdots ,10} \right\} ,
\end{equation}
\begin{equation}
{\left\| {{\mathring{R}_q}} \right\|_N} \lesssim \delta _{q+1}\lambda _q^{N - \alpha}  ,   \ \ \forall \ N \in \left\{ {0 , 1, \cdots ,10} \right\}
\end{equation}
and
\begin{equation}
{\left\| {{D_{t,q}}{\mathring{R}_q}} \right\|_N} \lesssim \delta _q^{\frac{1}{2}}{\delta _{q + 1}}\lambda _q^{N + 1 - \alpha} ,  \ \ \forall \ N \in \left\{ {0 , 1, \cdots ,10} \right\}  , 
\end{equation}
where ${D_{t,q}} \triangleq {\partial _t} + {v_q} \cdot \nabla $ denotes the material derivative corresponding to ${v_q}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 35 of arXiv:2601.16377, '2601.16377'] Suppose that Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic} and
 \ref{Assumptions_offcrit}
 hold. Let $[\mathfrak{a},\mathfrak{b}]$ be a saturation of the equilibrium measure. For each $\eps>0$ there
 exist $\N$-dependent integers $p < q$ and a real $C>0$ independent of $\N$ such that with
 probability greater than $1-C^{-1}e^{-C \N}$ the following two conditions hold:
 \begin{itemize}
  \item $\N \mathfrak{a} \leq \ell_{p}< \N(\mathfrak{a}+\eps)$ and $\N (\mathfrak{b}-\eps) <\ell_{q} \leq \N\mathfrak{b}$;
  \item The particles $\ell_p,\ell_{p+1},\ldots,\ell_{q}$ are densely packed.
 \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

