body:
[Proposition 8 of arXiv:2607.17396, '2607.17396'] Under the assumptions of Theorem 1,
\begin{equation}
\bigl\{Y_{n}^{(1)}(t),\, t \ge 0 \bigr\}
\mathop{\to}\limits^{\mathcal{D}}
\bigl\{\widetilde{Y}(t),\, t\ge 0 \bigr\}, \ \ n\to \infty,
\end{equation}
where the limit process $\{\widetilde{Y}(t),\, t \ge 0\}$ is the pathwise unique strong solution of the SDE
\begin{equation}
\mathrm{d}\widetilde{Y}(t)=\lambda\,\mathrm{d}t+\sigma\sqrt{\widetilde{Y}(t)^{+}}\,\mathrm{d}W(t),
\qquad t \ge 0,
\end{equation}
with initial condition $Y(0)=0$.

[Lemma lem:HCRStruncations of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $\phi\in\mathcal S({\mathbb{R}}^\mathsf{d})$ be nonnegative, radial, decreasing, and satisfy $\widehat{\phi}\ge0$,\footnote{A normalized Gaussian is an admissible choice.} and set $\phi_t(x)\coloneqq t^{-\mathsf{d}}\phi(x/t)$.

For $0<\mathsf{s}<\mathsf{d}$, set
\begin{align}
\mathsf{c}_{\phi,\mathsf{d},\mathsf{s}}^{-1}
&= \mathsf{s} \int_0^\infty r^\mathsf{s} \phi(r)\,\frac{\mathop{}\!\mathrm d r}{r},\\
{\mathsf{g}}(x)
&=\mathsf{c}_{\phi,\mathsf{d},\mathsf{s}}\int_0^\infty t^{\mathsf{d}-\mathsf{s}}\phi_t(x)\,\frac{\mathop{}\!\mathrm d t}{t}, \qquad x\ne0.
\end{align}
For $\eta>0$, define the scale-$\eta$ truncated potential and potential difference
\begin{align}
{\mathsf{g}}_\eta(x)\coloneqq \mathsf{c}_{\phi,\mathsf{d},\mathsf{s}}\int_\eta^\infty t^{\mathsf{d}-\mathsf{s}}\phi_t(x)\,\frac{\mathop{}\!\mathrm d t}{t}, \qquad
\mathsf{f}_\eta(x)\coloneqq {\mathsf{g}}(x)-{\mathsf{g}}_\eta(x)=\mathsf{c}_{\phi,\mathsf{d},\mathsf{s}}\int_0^\eta t^{\mathsf{d}-\mathsf{s}}\phi_t(x)\,\frac{\mathop{}\!\mathrm d t}{t}.
\end{align}
Then, by radial monotonicity,
\begin{align}
\|{\mathsf{g}}_\eta\|_{L^\infty}={\mathsf{g}}_\eta(0)=C_{\phi,\mathsf{d},\mathsf{s}}\eta^{-\mathsf{s}}, \qquad {\mathsf{g}}_\eta\ge0, \qquad \widehat{{\mathsf{g}}_\eta}\ge0, \qquad \widehat{\mathsf{f}_\eta}\ge0,
\end{align}
with the Fourier inequalities understood in the sense of tempered distributions.  Since ${\mathsf{g}}={\mathsf{g}}_\eta+\mathsf{f}_\eta$, this implies
\begin{align}
0\le \widehat{{\mathsf{g}}_\eta}\le \widehat{{\mathsf{g}}}.
\end{align}
Moreover, the potential difference satisfies
\begin{align}
0\le \mathsf{f}_\eta(x)&\le C_\gamma \frac{\eta^{\gamma-\mathsf{s}}}{|x|^\gamma}, \qquad \gamma>\mathsf{s},\nonumber\\
\mathsf{f}_\eta(x)&\ge c{\mathsf{g}}(x),\qquad |x|\le\eta.
\end{align}
In particular, if $\mu\in L^\infty$, then
\begin{align}
\|\mathsf{f}_\eta\ast \mu\|_{L^\infty}
\le \|\mu\|_{L^\infty}\int_{{\mathbb{R}}^\mathsf{d}}\mathsf{f}_\eta(x)\,\mathop{}\!\mathrm d x
\le C_\mu \eta^{\mathsf{d}-\mathsf{s}}.
\end{align}

For $\mathsf{s}=0$, let
\begin{align}
\mathsf{c}_{\phi,\mathsf{d},0}\coloneqq \phi(0)^{-1},\qquad
C_{\phi,T}\coloneqq \phi(0)\log T-\int_0^\infty \log r\,\phi'(r)\,\mathop{}\!\mathrm d r,
\end{align}
set, for $0<\eta<T$,
\begin{align}
{\mathsf{g}}_{\eta,T}(x)\coloneqq \mathsf{c}_{\phi,\mathsf{d},0}\pa*{\int_\eta^T t^\mathsf{d}\phi_t(x)\,\frac{\mathop{}\!\mathrm d t}{t}-C_{\phi,T}},\qquad
\mathsf{f}_\eta(x)\coloneqq {\mathsf{g}}(x)-{\mathsf{g}}_\eta(x)=\mathsf{c}_{\phi,\mathsf{d},0}\int_0^\eta t^\mathsf{d}\phi_t(x)\,\frac{\mathop{}\!\mathrm d t}{t},
\end{align}
where ${\mathsf{g}}_\eta$ is the limit of ${\mathsf{g}}_{\eta,T}$ as $T\to\infty$ in the sense of tempered distributions.  Then
\begin{align}
{\mathsf{g}}_\eta(0)=-\log\eta+O(1),\qquad \widehat{{\mathsf{g}}_\eta}\ge0\quad\hbox{on zero-mean test functions},\qquad \widehat{\mathsf{f}_\eta}\ge0,
\end{align}
\begin{align}
0\le \mathsf{f}_\eta(x)\le C_\gamma\min\Bigg\{1+\pa*{-\log\frac{|x|}{\eta}}_+,\frac{\eta^\gamma}{|x|^\gamma}\Bigg\},\qquad \gamma>0,
\end{align}
and consequently, if $\mu\in L^\infty$,
\begin{align}
\|\mathsf{f}_\eta\ast\mu\|_{L^\infty}\le C_\mu\eta^\mathsf{d}.
\end{align}
For every fixed $n\ge1$, it also holds that
\begin{align}
|x|^n|\nabla^{\otimes n}\mathsf{f}_\eta(x)|\le C_n\mathsf{f}_{c_n\eta}(x)
\end{align}
for a dimensional constant $c_n\ge2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Fix $\theta \in (0,\xi_c / 8)$. Then, there exists $\xi_0 \in (0,\xi_c)$ and a choice of the functions $b,M$ (both depending only on $\theta$) such that the following is true for all $\xi \in [\xi_0 , \xi_c]$. Fix $\varepsilon \in (0,1)$ and a bounded open set $U \subseteq \CC$. Then, there exists deterministic $C>0$ (depending only on $\varepsilon,\theta$, and $U$) such that with probability at least $1-\varepsilon$, we have that
\begin{equation*}
    \widetilde{D}_h^{\xi}(\partial B_{2^{-2^k}}(z) , \partial B_{2^{-2^{\ell}}}(z)) \leq C 2^{-\theta \ell} \quad \text{for all}\quad z \in U,\,\,\ell,k \in \NN,\,\,\ell <k.
\end{equation*}

