body:
[Theo 4 of arXiv:2609.00186, 'Macroscopic scalar curvature bounds on surfaces'] Let $(\Sigma,g)$ be a closed oriented Riemannian surface of genus $k\geq2$, normalized such that $\area_g(\Sigma) = \area_{g_0}(\Sigma)$ where $g_0$ is a metric of constant curvature $-1$. Then, for every $r>0$,
\begin{equation}
    \max_{\tilde x\in \tilde \Sigma}\area_{\tilde g}(B_{\tilde g}(\tilde x,r))\geq 2\pi(\cosh{r}-1), 
\end{equation}
with equality for a given $r>0$ if and only if $g$ has constant curvature $-1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition RKS smooth spde of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] (Renormalized kinetic solution)
	Let the interaction $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper) and $\rho_0\in L^{1}_{\mathbb{T}^2}$. For any $\varepsilon \in (0,1)$ and $\eta \in[0,1)$, a renormalized kinetic solution $\rho$ of (equation SPDE-1 of the paper) with initial datum $\rho_0$ is a nonnegative, almost surely continuous $L^1_{\mathbb{T}^2}$-valued $\mathcal{F}_t$-predictable process $\rho \in L^1_{\Omega \times[0, T]}L^1_{\mathbb{T}^2}$ that satisfies the following properties.



	\begin{enumerate}
		\item Conservation of mass: almost surely for every $t\in[0,T]$,
		\begin{equation}
		\|\rho(\cdot,t)\|_{L^{1}_{\mathbb{T}^{2}}}=\left\|\rho_0\right\|_{L^{1}_{\mathbb{T}^{2}}}.
		\end{equation}




		\item Pathwise entropy dissipation estimates: almost surely, 
		\begin{align}
\int_0^t\int_{\mathbb{T}^2}
|\nabla\sqrt{\rho}|^2\mathrm{d}x\mathrm{d}s
\lesssim&\int_{\mathbb{T}^2}\Psi(\rho_0)\mathrm{d}x+\sqrt{\varepsilon}\int_0^t\int_{\mathbb{T}^2}
2\nabla\sqrt{\rho}\cdot
\xi_{K}
+\varepsilon N_KT+1,
\end{align}
for all $t \in [0,T]$.  








		Furthermore, there exists a nonnegative kinetic measure $q$ ([FG24]) satisfying the following properties. 
		\item Regularity: almost surely
		\begin{align}
		4\delta_{0}(\xi-\rho)\xi|\nabla \sqrt{\rho}|^{2}\leqslant q\quad {\rm{on}}\ \mathbb{T}^2\times(0,\infty)\times[0,T].
		\end{align}
		\item Vanishing at infinity: we have
		\begin{align}
		\liminf_{M\to \infty}\mathbb{E}\Big[q(\mathbb{T}^2\times [0,T]\times [M,M+1])\Big]=0.
		\end{align}


		\item The equation: for every $\psi\in\mathrm{C}_{c}^{\infty}\left(\mathbb{T}^{2}\times(0,\infty)\right)$, almost surely for almost every $t\in[0,T]$,
		\begin{equation}
 \begin{aligned}
&\int_{\mathbb{R}}\int_{\mathbb{T}^2} \chi(x, \xi, \cdot) \psi(x, \xi) \Big|^t_0= -\int_{0}^{t} \int_{\mathbb{T}^2}\nabla\rho \cdot\nabla_x\psi(x,\rho)
-\int_{0}^{t} \int_{\mathbb{R}} \int_{\mathbb{T}^2} \partial_{\xi} \psi(x, \xi) \mathrm{d}m\\
&
-\int_{0}^{t} \int_{\mathbb{T}^2} \nabla\cdot \left(\rho \mathcal{V}[\rho]\right)\psi(x, \rho)
+\sqrt{\varepsilon}\int_{0}^{t} \int_{\mathbb{T}^2} s_{\eta}(\rho)\xi_{K}\cdot \nabla \psi(x, \rho)\\
&-\frac{\varepsilon}{2}\int^t_0\int_{\mathbb{T}^2}F_{1,k}s_{\eta}'(\rho)^2\nabla\rho\cdot(\nabla\psi)(x,\rho)+\frac{\varepsilon N_K}{2}\int_{0}^{t} \int_{\mathbb{T}^2}[s_{\eta}(\rho)]^2 \partial_{\xi} \psi(x, \rho),
\end{aligned}
			\end{equation}
				where $\chi$ is the kinetic function defined by $\chi(x,\xi,t)=\mathbf{1}_{\{0<\xi<\rho(x,t)\}}$ and $N_K$ is defined in (equation eq:def-NK of the paper).
	\end{enumerate}

[Theorem thm:Polya-Schur full version of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\{T_{n}\}$ be a series of operators which commute with $z\partial_z$  such that $\Phi_{T_n}\in\mathcal{LP}$ as defined in (equation eq:Phi_T def of the paper). If $\{p_n\}_{n\geq 1}$ is a sequence of positively-rooted polynomials indexed by their degree, with uniformly bounded roots such that $\llbracket p_n\rrbracket\Rightarrow\mu$ as $n\rightarrow\infty$, and $\{\Phi_{T_n}\}$ satisfy Assumption (assump:main assumption of the paper), then \begin{equation}
		\left\llbracket T_{n}p_n \right\rrbracket\Rightarrow \mu\boxtimes \mathcal{D}_{-1}\mu_{c,\Sigma}^{-1},
	\end{equation} where $\mu_{c,\Sigma}$ is the $\boxplus$-ID limit of the Appell polynomials $A_{n,\Phi_{T_n}}$ from Theorem (thm:main result, general of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Trace identity of resolvent blocks) of arXiv:2606.24887, '2606.24887'] Let $0< d < N/2$, $z \in \C_+$ and $w \in \CC$. 
		Then
		\begin{equation*}
			\sum_{y\in [N]} G_{yy} = \sum_{y\in [N]} G_{\ubarr{y} \ubarr{y}}.
		\end{equation*}

