[Lem lem17 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $h\in \bigcup_{\iota>0} C^{1+\iota}_{loc} (\mathbb{R}^2)$ and
  $f\in \bigcup_{\iota>0} C^{1+\iota}_{loc} (\mathbb{R}^{2n+2})$ be such that there exists $\lambda>1$ with the property that for each $M>0$
  one can find $K_f(M)>0$ such that ((f1 of the paper)) holds.
  Then whenever $u_0\in C^2(\overline{\Omega})$ and $u_{0t} \in \bigcup_{\iota>0} C^{1+\iota}(\overline{\Omega})$ satisfy $u_0=u_{0t}=0$ on $\partial\Omega$,
  for $T_{max}$ and $u$ as correspondingly obtained in Lemma (lem_loc of the paper) it follows that
  \begin{eqnarray}\label{ext1}
	\hspace*{-2mm}
	\mbox{if $T_{max}<\infty$, \ then \  
	either \ } 
	\liminf_{t\nearrowT_{max}} \inf_{x\in\Omega} h\big(u(x,t),u_t(x,t)\big)=0
	\ \mbox{or} \

	\limsup_{t\nearrowT_{max}} \|u_t(\cdot,t)\|_{W^{1,p}(\Omega)} 
	= \infty
  \end{eqnarray}
  for all $p>n\cdot\max\{\lambda,2\}$ fulfilling $p\ge 2\cdot\max\{\lambda,2\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 3 (Case of the torus) of arXiv:2609.01105, 'Obstruction to quasi-invariance of Gaussian measures under transport flows on Riemannian M'] Assume that~\((M,g)\) is the torus with the flat metric. Then the following statements are equivalent:
\begin{enumerate}[(i)]
    \item Gaussian measure $\mu_\alpha$ is quasi-invariant under the flow of \eqref{eq:transport};
    \item Gaussian measure $\mu_\alpha$ is invariant under the flow of \eqref{eq:transport};
    \item vector field $u$ is spatially constant, i.e. $u(t,x)=c(t)$, for a almost every $t$, and where $c$ is a given $L^1_{\rm loc}$ function.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 27 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] For any function $f: (\mathbb{R}^{+})^{\overline{\Lambda}} \times \{0,1\}^{\overline{E}(\Lambda)}    \rightarrow \mathbb{R}$, we have
    \begin{equation*}
        \frac{\mathrm{d} \Psi_{\Lambda, \beta}^{(\xi, \sfb)}[f(\mathsf{a}, \omega)]}{\mathrm{d} \beta}
        = \sum_{xy \in \overline{E}(\Lambda)}  \mathrm{Cov}_{\Lambda, \beta}^{(\xi, \sfb)} \left(f, \frac{2\mathsf{a}_x \mathsf{a}_y \omega_{xy}}{p_{xy}(\mathsf{a})} - \sfa_x \sfa_y \right).
    \end{equation*}

[Lemma lem:phibound of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For any $n\geq 1$ and $\bm{\eta}_n \in \mathbb{R}^{nd}$,
\begin{align}
\varphi(\bm{\eta}_n)\leq \frac{1}{n!}.
  \end{align}
  Thus for any $n\geq 2$ and $\bm{\eta}_n \in \mathbb{R}^{nd}$,
\begin{align}
 \lim_{R\to \infty}   \frac{1}{R^{2n-2}}\varphi(\bm{\eta}_{n}/R) =0.
    \end{align}
  Moreover, for any $n\geq 2$ and $1\leq k\leq n-1$, when $\eta_{i}\neq 0$ for $1\leq i \leq k$, we have
\begin{align}
\varphi(\bm{\eta}_{n}) \leq \left(1\wedge \frac{1}{\|\eta_1\|^2\dots \|\eta_k\|^2} \right)   \varphi(\bm{\eta}_{k,n}).
    \end{align}

