[Lem bootstrap of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $\Omega$ be an open subset of ${\mathbb R}^2$. 
Let $\{Z_n(x,y)\}_{(x,y)\in \Omega}$, $n\in {\mathbb N}$, and $\{Z(x,y)\}_{(x,y)\in \Omega}$ be random fields.  

Let $m\in {\mathbb N}$. 
Suppose that the following two conditions hold: 
\begin{enumerate}[(a)]
\item If $(x_i, y_i)\in \Omega$, $i=1, \cdots, m$ and $y_1, \cdots, y_m$ are distinct, then 
\begin{equation*}
    \{Z_n(x_i,y_i)\}_{i=1,\dots,m} \xrightarrow{d} \{Z(x_i,y_i)\}_{i=1,\dots,m}
    \qquad \textnormal{as $n\to \infty$.}
\end{equation*}

\item 
For every $x_1, \cdots, x_m \in \pi_x(\Omega)$ and $r_1 \cdots, r_m \in {\mathbb R}$
\begin{equation*}
	(y_1, \cdots, y_m) \mapsto \mathbb{P} (Z(x_i, y_i) \leq r_i, \, i = 1, \cdots, m)
\end{equation*}
is jointly continuous in $(y_1, \cdots, y_m) \in \prod_{i=1}^m \pi_y(\Omega \cap (\{x_i\} \times {\mathbb R}))$. 
\end{enumerate}
Then, every $m$-point distribution of $\{Z_n(x,y)\}_{(x,y) \in \Omega}$ converges to that of $\{Z(x,y)\}_{(x,y) \in \Omega}$ as $n\to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $J$ be a set of indices and consider two families of formal variables $\mathbf{x}=(x_{j})_{j\in J}$ and $\mathbf{x^{*}}=(x_{j}^{*})_{j\in J}$.
	    \begin{enumerate}
	        \item A \emph{*-test graph} $T = (G, \gamma, \epsilon )$ in the variables $\mathbf{x}$ is a finite connected multi-digraph $G = (V , E, \mathrm{src}, \mathrm{tar})$ together with edge labels $\epsilon : E \rightarrow \{1,*\}$ and $\gamma : E \rightarrow J$. One can see the maps $\gamma$ and $\epsilon$ as indicating that an edge $e\in E$ is labeled $x_{\gamma(e)}^{\epsilon(e)}$. The maps $\mathrm{src}$, $\mathrm{tar} : E \rightarrow V$ specify the source, $\mathrm{src}(e)$ and target, $\mathrm{tar}(e)$ of each edge $e \in E$. 
            \item A \emph{*-graph monomial} $g=(T,v_{in},v_{out})$ is a *-test graph $T$ together with the data of two vertices  $v_{in}$ and $v_{out}$ in $V$. We refer to the roots $(v_{in}, v_{out}) \in V^{2}$ as the input and the output, respectively, though they need not be distinct. We denote by $\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the set of all such *-graph monomials which can be extended to $\mathbb{C}\mathcal{G}\langle\mathbf{x},\mathbf{x^*}\rangle$ the space of finite linear complex combinations of *-graph monomials in variable $\mathbf{x}$ (graphs are considered up to isomorphisms of graphs preserving labeled and in/outputs).
	    \end{enumerate}

