body:
[Theorem prop_w of arXiv:2606.27549, 'On Analytically Tractable Multidimensional Diffusions via Doob $h$-Transforms, with Resett'] Let $h({\bf x})=h_c({\bf x})\in C^{2}(\mathcal{D})$ be a function satisfying the conditions of Theorem (teo_1 of the paper), with 

\begin{equation}
   h_c({\bf x}):=1+c \,k({\bf x}), 
   \qquad {\bf x}\in \mathcal{D},

\end{equation}

where $k({\bf x})\in C^{2}(\mathcal{D})$ is a positive function, and $c \in (c_m,+\infty)$,  with $c_m=\displaystyle-\inf_{{\bf x} \in {\cal D}} \frac{1}{k({\bf x})}$.

Then, the transition p.d.f.\ given in ((2.1 of the paper)), for all   $t>\tau\geq  0$ and 
$\bf{x},\,\bf{y}\in  {\cal D}$ can be expressed as  

\begin{equation*} 
    f({\bf x}, t \,|\,{\bf y}, \tau)
    ={1+c \,k({\bf x})\over 1+c \,k({\bf y})}\,
    \widehat{f}({\bf x},t\,|\,{\bf y},\tau),
\end{equation*}

and it can be decomposed as the following mixture

\begin{equation}
    f({\bf x},t\,|\,{\bf y},\tau)
    =\theta_c({\bf y})\,
    \widehat{f}({\bf x},t\,|\,{\bf y},\tau)
    +(1-\theta_c({\bf y}))\,
    \widetilde{f}({\bf x},t\,|\,{\bf y},\tau),

\end{equation}

with  
 \begin{equation}
   \theta_c({\bf y})=\frac{1}{h_c({\bf y})},  

 \end{equation}

and where 
  \begin{equation} 
      \widetilde{f}({\bf x}, t\,|\,{\bf y}, \tau)
      =\frac{k({\bf x})}{k({\bf y})}\,
      \widehat{f}({\bf x},t\,|\,{\bf y}, \tau)
       \end{equation}
 is the transition p.d.f.\ of the diffusion process, say 
 $\widetilde{\bf X}_t=\big(\widetilde{\bf X}_t\big)_{t\geq 0}$,  having the following infinitesimal moments:

   \begin{equation}
   \begin{array}{ll}
	\widetilde{b}_i({\bf x})
	=\widehat{b}_i({\bf x})+\displaystyle{1\over k({\bf x})}\sum_{j=1}^n \widehat{a}_{ij}({\bf x})
	\partial_{x_j}k({\bf x})\qquad &(i=1,\ldots,n),
    \\
	\widetilde{a}_{ij}({\bf x})=\widehat{a}_{ij}({\bf x}) 
	\qquad &(i,j=1,\ldots,n), 
\end{array}

\end{equation}

with $\widehat{b}_i({\bf x})$ and $\widehat{a}_{ij}({\bf x})$   defined in  ((inf_mom_X_t_hat of the paper)).

