[Definition DEF71 of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] A positive Borel measure $\mu$ on $\Gamma_\mu\subset \Gamma$ is called \emph{quasi-admissible} if it satisfies the following conditions:
 \begin{itemize}
 \item[(1)] $B_\mu:=\Gamma\setminus \Gamma_\mu$ is quasi-closed.
 \item[(2)] $\mu$,  regarded as a measure on $\overline{\Omega}\setminus B_\mu$ with $\mu(\Omega):=0$,  is smooth with respect to the part Dirichlet form of $(\mathbf{D},\tilde{H}^1(\Omega))$  on $G_\mu:=\overline{\Omega}\setminus B_\mu$. 
\end{itemize}

[Prop 45 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let us define the family of polynomials $\widetilde{\Phi}_0,\dots,\widetilde{\Phi}_{N-1}$ which satisfy the skew-biorthogonalization relations from \eqref{eq:Big Phi skew-biorhtog rels empty}, so that $\widetilde{\Phi}_k(x)$ is a polynomial in $x$ of degree $k$:
\begin{equation}

\sum_{x=1}^\infty \sum_{y=1}^\infty \widetilde{\Phi}_{N-k}(x) \Psi(x,y) \widetilde{\Phi}_{N-\ell}(y) = \left[J_N\right]_{k,\ell}, \qquad 1\le k,\ell \le N.
\end{equation}
These polynomials are constructed explicitly as
\begin{equation}
    \widetilde{\Phi}_{N-k}(x)=\sum_{j=1}^N \left[\mathcal{R}_N^{-1}\right]_{k,j}\Theta_{N-j+1}(x),
\end{equation}
where $\mathcal{R}_N^{-1}$ is the inverse of the upper-triangular skew-Borel matrix of $\mathcal{N}$. Moreover, it is constructed explicitly out of $2\times2$-blocks, where\footnote{The signs have been modified from the conventions of Proposition \ref{prop:skewBorelfactor} since the underlying matrices satisfy $\pf \mathcal{N}=(-1)^{N/2}\pf[Q_{k+1,\ell+1}(1,1)]_{1\leq,k,\ell\leq N}$.}
\begin{equation}
\left\langle\mathcal{R}_{N}^{-1}\right\rangle_{i,j} = \left\{
\begin{array}{cl}
\displaystyle
\begin{pmatrix}
\displaystyle \frac{\pf \widetilde{Q}_{[1,N-2i+2]\backslash\{N-2i+1,N-2j+2\}}}{\pf \widetilde{Q}_{[1,N-2i+2]}} & \displaystyle -\frac{\pf \widetilde{Q}_{[1,N-2i+2]\backslash\{N-2i+1,N-2j+1\}}}{\pf \widetilde{Q}_{[1,N-2i+2]}} \\[5mm]
\displaystyle- \frac{\pf \widetilde{Q}_{[1,N-2i+1]\backslash \{N-2j+2\}}}{\pf \widetilde{Q}_{[1,N-2i]}} & \displaystyle \frac{\pf \widetilde{Q}_{[1,N-2i+1]\backslash \{N-2j+1\}}}{\pf \widetilde{Q}_{[1,N-2i]}} 
\end{pmatrix}, \qquad & 1\le i < j\le \frac{N}2
\\[10mm]
\displaystyle
\begin{pmatrix}
\displaystyle-\frac{\pf \widetilde{Q}_{[1,N-2i]}}{\pf \widetilde{Q}_{[1,N-2i+2]}} & 0 \\[5mm]
0 & 1
\end{pmatrix}, & i=j \\[8mm]
\begin{pmatrix}
    0 & 0 \\
    0 & 0
\end{pmatrix}, & 1\le j < i\le \frac{N}2
\end{array}\right.,
\end{equation}
for each $1\leq i,j\leq N/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 26 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] There exists $c_{c}=c_{c}(d,m)>0$ such that for any $\Ga>0$ and $R>0$, for $\mathcal{C}$ as defined in \eqref{e.regdefs}, \begin{equation*}
\sum_{(k,n)\in \mathcal{C}}\left(\bar{u}(\x, n+1) - \bar{u}(\x, n) - {\partial \bar{u} \over \partial t}(\x,n)\right)_{+}\leq c_{c}R^{d-2} \,\Gamma^{m+1}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

