$$
\nu^{\infty}_{\Gamma}(dz)
=
\1_{z\in\Gamma}
\int_{0}^{2\pi}
G_{\operatorname{Ext}(\Gamma)}(e^{i\theta},\infty)H_{\mathcal{A}_\Gamma}(dz,e^{i\theta})
d\theta
.
$$
In particular,
\begin{equation}

\int_{0}^{2\pi}
\int_{\Gamma}
G_{\operatorname{Ext}(\Gamma)}(e^{i\theta},\infty)H_{\mathcal{A}_\Gamma}(dz,e^{i\theta})d\theta
=1.
\end{equation}

