[Definition 1 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] We define a \emph{weak geodesic CLE$_4$ metric coupling} to be a family of couplings
	\begin{equation*}
		D= \left\{(\Gamma_U, D_{\Gamma_U}^U)\right\}_U
	\end{equation*}
	where $U \subsetneq \BC$ ranges over all simply connected domains, and for each $U$, $\Gamma_U$ is a non-nested CLE$_4$ in $U$, such that the following conditions are satisfied for every such $U$ and all deterministic choices of the auxiliary data ($V$, $I$, $\phi$, arcs) below:
	\begin{enumerate}[label=(\Roman*), ref=\Roman*]
		\item {\bfseries (Weak geodesic metric)} $D_{\Gamma_U}^U$ is a.s.\ a metric on $\Gamma_U$ satisfying the following conditions:
		\begin{enumerate}[label=(\roman*), ref=\roman*]
			\item Let $\SCL \in \Gamma_U$ and $t \ge 0$. Then the metric ball $\SCB_t(\SCL; D_{\Gamma_U}^U)$ is connected.
			\item Let $\SCL \in \Gamma_U$ and $t \ge 0$. Let $\phi\colon U \to \BD$ be a conformal mapping. Then
			\begin{equation*}
				\lim_{t^\prime \downarrow t} \phi (\SCB_{t^\prime}(\SCL; D_{\Gamma_U}^U) )= \phi (\SCB_t(\SCL; D_{\Gamma_U}^U)) \quad \text{and} \quad \lim_{t^\prime \uparrow t} \phi (\SCB_{t^\prime}(\SCL; D_{\Gamma_U}^U)) = \phi (\SCB_t^-(\SCL; D_{\Gamma_U}^U))
			\end{equation*}
			with respect to the Hausdorff metric, the second limit being required only for $t > 0$.
			\item Let $\SCL_1, \SCL_2 \in \Gamma_U$ and $t \ge 0$. Suppose that $\SCB_t(\SCL_1; D_{\Gamma_U}^U) \cap \SCL_2 = \emptyset$. Then
			\begin{equation*}
				D_{\Gamma_U}^U(\SCL_1, \SCL_2) = t + D_{\Gamma_U}^U(\SCB_t(\SCL_1; D_{\Gamma_U}^U), \SCL_2). 
			\end{equation*}
			\item Let $\SCL_1, \SCL_2 \in \Gamma_U$. Then the closed set $K_{\SCL_1, \SCL_2}$ defined as the closure of $\{ z \in \overline U : D_{\Gamma_U}^U(\SCL_1, z)+ D_{\Gamma_U}^U(\SCL_2,z)= D_{\Gamma_U}^U(\SCL_1, \SCL_2) \}$ has a connected component containing $\SCL_1 \cup \SCL_2$.






		\end{enumerate}
		Items~\eqref{it:weak_axiom_geodesic_0}--\eqref{it:weak_axiom_geodesic_4} are also required with a deterministic connected arc (resp.\ two disjoint such arcs) of $\partial U$ in place of $\SCL$ or $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
		\item {\bfseries (Locality)}
		Let $V \subset U$ be a deterministic simply connected subdomain. Let $I \subset \partial U$ be a deterministic connected arc. Let $\{V_j\}_j$ be the connected components of $V^\star$. Then there exists a coupling $(\Gamma_U, D_{\Gamma_U}^U, \{D_{\Gamma_U|_{V_j}}^{V_j}\}_j)$ such that the following hold: 
			\begin{itemize}
				\item Conditionally on the $\sigma$-algebra generated by
				\begin{multline}
					\bigl\{\SCL \in \Gamma_U : \SCL \not\subset V\bigr\}, \quad \bigl\{\SCB_t(\SCL; D_{\Gamma_U}^U) : \SCL \in \Gamma_U, \ \SCL \not\subset V, \ t \in [0, D_{\Gamma_U}^U(\SCL, \partial V^\star)]\bigr\}, \\
					\text{and} \quad \bigl\{\SCB_t(I; D_{\Gamma_U}^U) : t \in [0, D_{\Gamma_U}^U(I, \partial V^\star)]\bigr\}
				\end{multline}
				the $(\Gamma_U|_{V_j}, D_{\Gamma_U|_{V_j}}^{V_j})$'s are independent and their conditional laws are those of $(\Gamma_{V_j}, D_{\Gamma_{V_j}}^{V_j})$, respectively. 
				\item For all $j$, for all $\SCL_1, \SCL_2 \in \Gamma_U|_{V_j}$, we have $D_{\Gamma_U}^U(\SCL_1, \SCL_2)\le D_{\Gamma_U|_{V_j}}^{V_j}(\SCL_1, \SCL_2)$.
				\item For all $j$, for all $\SCL \in \Gamma_U|_{V_j}, \ t \in [0, D_{\Gamma_U}^U(\SCL, \partial V_j)]$, we have $\SCB_t(\SCL; D_{\Gamma_U}^U) = \SCB_t(\SCL; D_{\Gamma_U|_{V_j}}^{V_j})$.

		\end{itemize} 





























		\item {\bfseries (Conformal invariance)} Let $\phi \colon U \to \phi(U)$ be a deterministic conformal mapping. Then,
		\begin{equation*}
				\left(\phi(\Gamma_U), \left( D_{\Gamma_U}^U\left(\phi^{-1}(\SCL_1), \phi^{-1}(\SCL_2) \right) \right)_{\SCL_1, \SCL_2 \in \phi(\Gamma_U)} \right)
				\overset{(\mathrm{d})}{=} \left( \Gamma_{\phi(U)}, \left(D_{\Gamma_{\phi(U)}}^{\phi(U)}(\SCL_1, \SCL_2) \right)_{\SCL_1, \SCL_2 \in \Gamma_{\phi(U)}} \right).
		\end{equation*

[Theorem thm:abstractresolventbounds of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] Let $(T(t))_{t\geq 0}$ be a bounded semigroup with generator $A$ on a Hilbert space $H$  such that $\sigma(A)\cap i\mathbb{R} = \varnothing.$
\begin{enumerate}
    \item \textnormal{(Batty, Duyckaerts, Burq, Lebeau)}
    The semigroup $T$ possesses logarithmic decay with rate $1/d,d>0$, i.e., 
    \begin{align}
        \forall k \in \mathbb{N} ~ \exists C_k>0: ~ \|T(t)x\|_{H} \leq \frac{C_k}{\log(t+2)^{\frac{k}{d}}} \|x\|_{A^k} ~~ \forall t\geq0,  x\in \operatorname{dom}\left(A^k\right),
    \end{align}
    if and only if the generator $A$ has exponential resolvent bounds with power $d>0$, i.e., there exists $C>0$ such that
    \begin{align}

        \|(\lambda i +A)^{-1} \|_{H \to H} \leq C \exp{(C|\lambda|^d)} ~~\forall \lambda\in \mathbb{R}, |\lambda|\gg1.
    \end{align}
    \item   \textnormal{(Borichev, Tomilov)}
    The semigroup $T$ possesses polynomial decay with rate $1/d,$  $d>0$, i.e., 
    \begin{align}
        \forall k \in \mathbb{N} ~ \exists C_k>0: ~ \|T(t)x\|_{H} \leq \frac{C_k}{(1+t)^{\frac{k}{d}}} \|x\|_{A^k} ~~ \forall t\geq0,  x\in \operatorname{dom}\left(A^k\right),
    \end{align}
    if and only if the generator $A$ has polynomial resolvent bounds with power $d>0$, i.e., there exists $C>0$ such that
    \begin{align}

        \|(\lambda i +A)^{-1} \|_{H \to H} \leq C |\lambda|^d ~~\forall \lambda\in \mathbb{R}, |\lambda|\gg 1.
    \end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Local existence of mild solutions) of arXiv:2606.15425, 'Well-posedness of stochastic parabolic equations with gradient nonlinearities and applicat'] Let $d \geq 2$, $q \in (d,2d)$, $\delta \in \left(\frac dq, 1\right)$ and $\sigma >\delta-\frac dq$. Assume that $F$ and $G$ satisfy Assumptions \ref{ass:DriftNonlin} and \ref{ass:nemytskiiLipschitz}. Then, for any $p \in \left[\frac{q}{\delta q-d},\infty\right)$ and $\mathcal F_0$-measurable ${\bm z}_0 \in L^0(\Omega;B^{d/q}_{q,2p}(\mathbb T^d))$, there exists a unique maximal local solution $({\bm z},\tau)$ of \eqref{eq:FullNoiseSPDE} in the sense of Definition \ref{def:localsol}, with
\begin{enumerate}
\item (Maximality) If $(\widetilde {\bm z},\widetilde\tau)$ is any other local solution, then $\widetilde\tau\leq \tau_{\max}$ a.s. and
$\widetilde {\bm z}_t={\bm z}_t$ for all $t<\widetilde\tau$ a.s.
\item (Blow-up criterion) For any stopping time $\tau \leq \tau_{\mathrm{max}}$,
\begin{equation}
\limsup_{t\nearrow \tau_{\max}}   ~\norm{{\bm z}}_{L^\infty([\tau,t];B^{d/q}_{q,2p}(\mathbb T^d))}+ \norm{{\bm z}}_{L^{2}([\tau,t];H^{1,q}(\mathbb T^d))} + \norm{{\bm z}}_{L^4([\tau,t];H^{\delta,q}(\mathbb T^d))} =\infty.
\end{equation}
$\mathbb P$-almost surely on the event $\{\tau < \tau_{\max}<T\}$,
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Y-wellposed of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Under Assumptions~(ass:LR of the paper),~(ass:diff1 of the paper), and~(ass:SC of the paper), for each $r \in [0,T]$ and $v_0 \in H$, the initial value problem
\begin{equation}
\begin{aligned}
  \mathrm{d}Y_v(s) + \mathcal{A}'_u(s, X(s))\,Y_v(s)\,\mathrm{d}s &= \mathcal{B}'_u(s, X(s))(Y_v(s))\,\mathrm{d}W(s), \quad s \in (r, T],\\
  Y_v(r) &= v_0 \in H,
\end{aligned}
\end{equation}
admits a unique $H$-valued continuous variational solution, tested against $V$, in the regularity class determined by the mechanism of~(SC1):
\[
  Y_v(\cdot) \;\in\;
  \begin{cases}
    C([r,T]; H) \ \text{ with } \ \mathcal{E}_r^T(Y_v) < \infty, & \text{under (SC1)(a)},\\[4pt]
    C([r,T]; H) \cap L^2(r,T; V), & \text{under (SC1)(b)},
  \end{cases}
  \quad \text{$\mathbb{P}$-a.s.},
\]
Under~(a) the controlling quantity is the weighted energy intrinsic to the degenerate linearisation, which for the $p$-Laplacian is $\int_r^T\!\!\int \lvert \nabla X \rvert^{p-2}\lvert \nabla Y_v \rvert^2$; under~(b) it is the unweighted quadratic $V$-energy furnished by $\alpha_1$.
The map $v_0 \mapsto Y_v(t)$ is linear; we view it as the linear first variation operator $Y(t,r): H \to L^0(\Omega; H)$ defined by $Y(t,r) v_0 := Y_v(t)$, the variational-SPDE analogue of the Jacobian of the stochastic flow [ELWORTHY1994252, kunita1990stochastic] in the variational framework of Liu--R\"ockner and R\"ockner--Shang--Zhang [liu2015stochastic, rockner2022wellposedness]. Under the additional structural exponential-integrability~(SC2), $Y_v \in L^2(\Omega; C([r,T]; H))$ with the mechanism-matched global energy bound ($\mathbb{E}[\mathcal{E}_r^T(Y_v)] \leq C\lVert v_0 \rVert_H^2$ under~(SC1)(a), $Y_v \in L^2(\Omega; L^2(r,T;V))$ under~(SC1)(b)), and $Y(t,r): H \to L^2(\Omega; H)$ is continuous, with the individual-fibre moment bound $\mathbb{E}[\sup_{r \leq s \leq t}\lVert Y(s,r)v_0 \rVert_H^q] \leq C_q\lVert v_0 \rVert_H^q$ for every $v_0 \in H$ and every $q \in [1, q_{\max}]$ (Proposition~(prop:Y-moments of the paper), $C_q$ independent of $v_0$). (Proof in the paper; no proof environment follows the statement in the TeX.)

