body:
[Lem D12Form of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] The following formulae for $D_{1}L$ and $D_{2}L$ hold true:
\begin{equation}
D_{1}L=\sum_{m=0}^{\infty}\frac{B_{m}}{m!}{\rm ad}_{{\rm e}_{1}}^{m}\big(\int_{0}^{1}e^{x_{t}{\rm ad}_{{\rm e}_{1}}}({\rm e}_{2})dy_{t}\big)
\end{equation}
and
\begin{align}
D_{2}L & =\frac{1}{2}\sum_{m=0}^{\infty}\frac{B_{m}}{m!}{\rm ad}_{{\rm e}_{1}}^{m}\big(\int_{0<s<t<1}\big[e^{x_{s}{\rm ad}_{{\rm e}_{1}}}({\rm e}_{2}),e^{x_{t}{\rm ad}_{{\rm e}_{1}}}({\rm e}_{2})\big]dy_{s}dy_{t}\big)\nonumber \\
 & \ \ \ +\frac{1}{2}\sum_{m,l\geqslant0}\frac{B_{m}B_{l}}{m!l!}\sum_{k=1}^{m}{\rm ad}_{{\rm e}_{1}}^{k-1}\big(\big[{\rm ad}_{{\rm e}_{1}}^{l}(\int_{0}^{1}e^{x_{s}{\rm ad}_{{\rm e}_{1}}}({\rm e}_{2})dy_{s}),{\rm ad}_{{\rm e}_{1}}^{m-k}(\int_{0}^{1}e^{x_{t}{\rm ad}_{{\rm e}_{1}}}({\rm e}_{2})dy_{t})\big]\big).
\end{align}

[Proposition prop:HB-palindromic of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] The following identities hold.
\begin{enumerate}
\item[\rm(i)] \emph{ABOBA.} The force-evaluation points $Y_{m+1}=X_m+\frac h2V_m$, together with $Y_0:=X_0-\frac h2V_0$, satisfy $Y_{m+1}-Y_m=hV_m$ for $m\ge0$ and, for $m\ge1$,
\begin{equation}
 Y_{m+1}=Y_m+\beta(Y_m-Y_{m-1})-s\nabla U(Y_m)+h\varsigma\,\xi_m,
 \qquad s=\frac{h^2}{2}(1+\beta);
\end{equation}
the noise variables $h\varsigma\xi_m$ are independent with covariance $h^2(1-\beta^2)\mathrm{Id}_d$.
\item[\rm(ii)] \emph{AOBOA.} The force-evaluation points $Y_{m+1}=X_m+\frac h2V_m$, together with $Y_0:=X_0-\frac h2V_0$, satisfy $Y_{m+1}-Y_m=hV_m$ for $m\ge0$ and, for $m\ge1$,
\begin{equation}
 Y_{m+1}=Y_m+\beta(Y_m-Y_{m-1})-s\nabla U(Y_m)+h\sigma\bigl(r\xi_m^{(1)}+\xi_m^{(2)}\bigr),
 \qquad s=\sqrt\beta\,h^2;
\end{equation}
the noise variables are independent with covariance $h^2(1-\beta^2)\mathrm{Id}_d$.
\item[\rm(iii)] \emph{BOAOB.} Let $\xi_0^{(2)}\sim\mathcal N(0,\mathrm{Id}_d)$ be independent of the variables driving the chain, or alternatively let $\xi_0^{(2)}$ be the zero vector, and define the auxiliary variable $X_{-1}$ by
\begin{equation}
 V_0=\frac rh(X_0-X_{-1})+\sigma\xi_0^{(2)}-\frac h2\nabla U(X_0).
\end{equation}
Then, for $k\ge0$,
\begin{equation}
 X_{k+1}=X_k+\beta(X_k-X_{k-1})-s\nabla U(X_k)+h\sigma\bigl(r\xi_k^{(2)}+\xi_{k+1}^{(1)}\bigr),
 \qquad s=\sqrt\beta\,h^2;
\end{equation}
the noise variables are independent. If $\xi_0^{(2)}\sim\mathcal N(0,\mathrm{Id}_d)$, every noise variable has covariance $h^2(1-\beta^2)\mathrm{Id}_d$; if $\xi_0^{(2)}=0$, the first has the smaller covariance $h^2(1-\beta)\mathrm{Id}_d$, and each subsequent one has covariance $h^2(1-\beta^2)\mathrm{Id}_d$.
\item[\rm(iv)] \emph{OABAO.} Set $\chi_m=r\xi_{m-1}^{(2)}+\xi_m^{(1)}$ for $m\ge2$. The force-evaluation points $Y_m=X_{m-1}+\frac h2\bigl(rV_{m-1}+\sigma\xi_m^{(1)}\bigr)$ satisfy, for $m\ge2$,
\begin{equation}
 Y_{m+1}=Y_m+\beta(Y_m-Y_{m-1})-s\nabla U(Y_m)+\frac h2\sigma\bigl(\chi_m+\chi_{m+1}\bigr),
 \qquad s=\frac{h^2}{2}(1+\beta).
\end{equation}
The variables $\sigma\chi_m$, $m\ge2$, are independent $\mathcal N(0,(1-\beta^2)\mathrm{Id}_d)$, so the noise is a centered $1$-dependent Gaussian sequence with the covariances (equation eq:zetacov-baoab of the paper); in law it coincides with the BAOAB noise (equation eq:zeta-baoab of the paper).
\end{enumerate}

