 d_{\rm H}(\spn(L_n),\spn(G_\infty))&\longrightarrow0,
 \\
 \trn_{qn}L_n^{2r}
 &\longrightarrow(\trn_q\otimes\tau)(G_\infty^{2r}).

\end{align}

