body:
[Theorem 1 of arXiv:2605.31471, 'Convergence Rates of Continuous-Time Random Walks to Time-Fractional Diffusions with Unbou'] Let $F_t$ be the Feller semigroup of \eqref{eq:SDE-flow}, and let
    Assumptions~\ref{asm:classical} and~\ref{asm:rw} hold.  Then, for any
    $f\in D_4$,
    \begin{equation}
        \sup_{s \leq t} \| U_h^{\lfloor s/h\rfloor} f - F_s f \|_W \leq  C_{\mathrm{RW}} e^{\mu t} h \|f \|_4,
    \end{equation}
    where $\mu:=\mu_4$ is the renormed $D_4$-growth rate of
    Corollary~\ref{coro:norm_estim}, and $C_{\mathrm{RW}}$ depends only on the constants in Assumptions~\ref{asm:classical} and~\ref{asm:rw}.  For the killed semigroups,
    \begin{equation}
        \sup_{s \leq t} \| e^{-c\lfloor s/h\rfloor h} U_h^{\lfloor s/h\rfloor} f - e^{-c s} F_s f \|_W \leq C_{\mathrm{RW}}' e^{(\mu - c) t} h \|f \|_4,
    \end{equation}
    with $C_{\mathrm{RW}}'$ depending on the same data and on $c$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2603.25615, 'Fourier dimension of Mandelbrot cascades on planar curves'] Suppose that $1\leq q<p < q_{\max}$. If $1 < p/q \leq 2$, for any $1 \leq j \leq n $ and  $I \in \Q_j$, we have

    \begin{equation}
    \E(Y_{j,n }(q,I)^{p/q}) \leq \frac{b^{-2\tau(\frac{p}{2})+\frac{p\tau(q)}{q}}}{1-b^{-\tau(p)+\frac{p\tau(q)}{q}}}\,.    
    \end{equation}
    If $2^k < p/q \leq 2^{k+1}$ for some $k \geq 1$, for any $1 \leq j \leq n$ and $I \in \Q_j$, then 
    \begin{equation}
    \E(Y_{j,n}(q,I)^{p/q}) \leq \left({1-b^{-\tau(2q)+2\tau(q)}} \right)^{-2^{k+1}}.
    \end{equation}

[Lem cancellation2 of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] Fix a tuple $(i_{1},\ldots,i_{l})$ that is not composed of mutually distinct indices, and define the set $J$ from $(i_{1},\ldots,i_{l})$ as before. Then there exists a constant $C>1$ that depends on $\mathbf{k}_{1},\ldots,\mathbf{k}_{l}$ and $\sigma$, and is uniform in $N$, such that for all $N\ge 100$, 
    \begin{equation}
    \sum_{(E,\vec{q})\in \mathcal{\tilde{B}}(i_{1},\ldots,i_{l})}\left|w(E,\vec{q})+\sum_{(E,\vec{q}'):\ R(E,\vec{q}')=(E,\vec{q})}w(E,\vec{q}'
        )\right|\le C\cdot N^{-|J|} N^{-1/12}.
    \end{equation}

