[Lemma lemma_upper_bound_three_terms of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] Let $C_1>0$ be as in Item~1.~of Lemma~(lemma_image_og_phi_sigma_right_set of the paper). Then there exists $f:\mathbb{R}_+^* \to \mathbb{R}$ with $\lim_{\varepsilon \to 0^+}f(\varepsilon)=0$ such that, for every $\rho \in \{-,+\}$, 
\begin{align}
& \mathbb{P}\left( \mathscr{C}_n^{\rho}(\mu,2^{-R}\varepsilon) \right)  \notag \\
& \qquad \leq 
\begin{cases}
e^{f(\varepsilon) n + o(n)} \mathbb{P}\Big( \Omega_{\overline{\alpha}_{0,n}}^{(0)}(\mu_0,C_1\varepsilon) \Big) \mathbb{P}_{-\rho R} \left( \Omega_{\overline{\alpha}_{-\rho,n},\textup{exc}}^{-\rho} \right)  \mathbb{P}_{\rho R} \left( \Omega_{\overline{\alpha}_{\rho,n},\textup{mea}}^{\rho} \right), & \text{if } \alpha_0>0, \\
e^{f(\varepsilon) n + o(n)} \mathbb{P}_{-\sigma R} \left( \Omega_{\overline{\alpha}_{-\rho,n},\textup{exc}}^{-\rho} \right)  \mathbb{P}_{\rho R} \left( \Omega_{\overline{\alpha}_{\rho,n},\textup{mea}}^{\rho} \right), & \text{if } \alpha_0=0,
\end{cases} 
\end{align}
and for $\rho=0$, 
\begin{align}
& \mathbb{P}\left( \mathscr{C}_n^{0}(\mu,2^{-R}\varepsilon) \right) \notag \\
& \qquad  \leq
\begin{cases}
e^{f(\varepsilon) n + o(n)} \mathbb{P}\Big( \Omega_{\overline{\alpha}_{0,n}}^{(0)}(\mu_0,C_1\varepsilon) \Big) \mathbb{P}_{-R} \left( \Omega_{\overline{\alpha}_{-,n},\textup{exc}}^{-} \right)  \mathbb{P}_{R} \left( \Omega_{\overline{\alpha}_{+,n},\textup{exc}}^{+} \right), & \text{if } \alpha_0>0, \\
e^{f(\varepsilon) n + o(n)} \mathbb{P}_{-R} \left( \Omega_{\overline{\alpha}_{-,n},\textup{exc}}^{-} \right)  \mathbb{P}_{R} \left( \Omega_{\overline{\alpha}_{+,n},\textup{exc}}^{+} \right), & \text{if } \alpha_0=0.
\end{cases} 
\end{align}

