[Lemma lemma_hz of arXiv:2608.08532, 'Constrained Maximum Weight Paths in Random Geometric Graphs'] The following properties hold:\\
\((a)\) If there exists~\(z_0 > 0\) such that~\(H(z)\) is strictly increasing for all~\(z > z_0,\) then for any~\(z > z_0\) we have
\begin{equation}
\mathbb{P}\left(W(f) > H(z)\right) = \frac{1}{z}.
\end{equation}
\((b)\) If there exists~\(x_0 > 0\) such that~\(F_c(x_0) > 0\) and~\(F_c(x)\) is continuous for all~\(x \geq x_0,\) then~\(H(z)\) is strictly increasing for all~\(z > \frac{1}{F_c(x_0)}.\) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:bivariate-upper-tails}
Let $(G,H)$ be a centered bivariate Gaussian vector with unit variances and
correlation $\rho\in[-1,1]$.  Then
\[
  \lim_{t\to\infty}
  \frac{\mathbb P\{G>t,H>t\}}{\overline\Phi(t)^2}
  =
  \begin{cases}
    0,&\rho<0,\\
    1,&\rho=0,\\
    +\infty,&\rho>0.
  \end{cases}
\]

[Lemma le:B1cpart of arXiv:2411.09058, 'Time-dependent averages of a critical long-range stochastic heat equation'] For  any $0<\kappa<\frac{d-2}{2}$, we have
     \[\lim_{R\to\infty}
     \sum_{n=2}^{\infty}
     \kappa^{2n} c_d^n\mathcal{K}^{(n)}(R)=0.
     \]

[Theorem 4 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Let $X=(X_t)_{t\in[0,T]}$ be a centered Gaussian process $X=(X^1,...,X^d)$ with values in $\mathbb{R}^d$ and with real valued components $X^\ell=(X^\ell_t)_{t\in[0,T]}$ satisfying
		\begin{equation}

			C_- \lvert t-s\rvert^{2H} \leq \mathbb{E}(X^\ell_t - X^\ell_s)^2 \leq C_+\lvert t-s\rvert^{2H},\qquad 0\leq s<t\leq T,
		\end{equation}
		for fixed constants $H \in (0,1)$ and $C_+\geq C_->0$. Suppose that the local non-determinism property
		\begin{equation}

			\E \left| \sum_{k=1}^m \langle \xi_k,X_{t_k}-X_{t_{k-1}}\rangle\right|^2 \geq C \prod_{\ell=1}^d \sum_{k=1}^m \xi_{k,\ell}^2 \E (X^\ell_{t_k}-X^\ell_{t_{k-1}})^2
		\end{equation}
		holds with a constant $C>0$ and for all $m\in \mathbb{N}$, $\xi_k \in \mathbb{R}^d$ and all $0=t_0<t_1<\ldots<t_m\leq T$. Then 
		\begin{enumerate}
			\item[(i)] Assumption \ref{a1} (i) and (ii) hold with $\theta=0$ respectively $\iota = \frac12$.
			\item[(ii)] For any $t \in (0,T)$  there is a constant $c_4(t)>0$ such that
			\[\liminf _{r \to 0} \sup_{s \in (t-r,t+r)} \frac{\|X_t - X_s \| }{r^H(\log\log r^{-1})^{-H}} \geq c_4(t)\qquad \text{$\mathbb{P}$-a.s.}\]
			\item[(iii)] There is a constant $c_5>0$ such that		
			\[\liminf _{r \to 0} \inf_{t\in (0,T)} \sup_{s \in (t-r,t+r)} \frac{\|X_t - X_s \| }{r^{H} ( \log r^{-1})^{-H}} \geq c_5\qquad \text{$\mathbb{P}$-a.s.}\]
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:Ito_Lie_series of arXiv:2411.06827, 'The Exponential Lie Series and a Chen--Strichartz Formula for L{\'e}vy Processes'] In terms of the It{\^o} integrals $I_w$ the Chen--Strichartz series is given by
\begin{align*}
\log\bigl(\varphi_t\bigr) &  = 
\log\biggl(\sum\limits_{w\in{\mathbb A}^\ast} I_w(t)D_w\biggr) 
  = \sum\limits_{w\in{\mathbb A}^\ast} I_{w}(t) \biggl(\sum_{\sigma\in{\mathbb S}(|w|)}
\frac{1}{|\sigma|} c_\sigma 
V_{[\exp_{\mathrm H}^\dag (\sigma (w))]_{{\mathrm L}}}\biggr).
\end{align*}

[Lemma 26 (Weighted beta-trapezoid) of arXiv:2605.11451, '2605.11451'] Let $1/2<\alpha<1$ and let $\delta\ge3\alpha$. Then for $0\le a<b\le1$,
\begin{equation}
 \alpha\int_a^b t^{2\alpha-1}(1-t)^\delta\,\dd t
 \le
 \frac{b^{2\alpha}-a^{2\alpha}}4\left((1-a)^\delta+(1-b)^\delta\right).
\end{equation}

[Proposition 14 (Swapping the local time for GFF) of arXiv:2506.09592, 'Extremal process of the local time of simple\\random walk on a regular tree'] Given two naturals $n>k\ge1$, a real $t>0$ and a function $f\in\Cloc^+$, define
\begin{equation}

U_{n,k}(f):=E^\varrho\biggl(\,\prod_{x\in\BbbL_n}\texte^{-f(\theta_n(x),\sqrt{L_t(x)}-m_n,\,\sqrt{L_t(x)}-\sqrt{L_t(x\cdot)}\,)\,1_{\MM_{n,k}(\sqrt{L_t},\,x)}}\biggr)
\end{equation}
and
\begin{equation}

V_{n,k}(f):=E^\varrho\otimes \wt E\biggl(\,\prod_{x\in\BbbL_n}\texte^{-f(\theta_{n-k}(z),\sqrt{L_t(z)}+h(x)-h(z)-m_n,\,h(x)-h(x\cdot)\,)\,1_{\MM_{n,k}(h,x)\cap \BB_{n,k}(x)}}\biggr),
\end{equation}
where we put $z:=\frakm^k(x)$ to reduce clutter and with the same convention set
 \begin{equation}

\BB_{n,k}(x):=\Bigl\{m_k+k^{1/3}\le m_n-\sqrt{L_t(z)}\le m_k+k^{2/3}\Bigr\}.
\end{equation}
Then
\begin{equation}

\lim_{k\to\infty}\limsup_{n\to\infty}\bigl|U_{n,k}(f)-V_{n,k}(f)\bigr|=0
\end{equation}
holds for all $t>0$ and all $f\in\Cloc^{+}$. Moreover, 
\begin{equation}

\lim_{\ell\to\infty}
\limsup_{k \to \infty} \limsup_{n \to \infty} 
P^\varrho\otimes\wt P\biggl(\,\sum_{x\in\BbbL_n}1_{\MM_{n,k}(h,x)\cap \BB_{n,k}(x)}1_{\{\sqrt{L_t(z)}+h(x)-h(z)>m_n-\lambda\}}>\ell\biggr)=0
\end{equation}
holds for all $t>0$ and all~$\lambda>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 26 of arXiv:2607.16479, 'The Site Frequency Spectrum in an Exponentially-Growing Population with Selection'] \begin{align}
      \lim_{k\to\infty}\limsup_{t\to\infty}\frac{\log(j_k^+(t))}{t}\leq \frac{\lambda_0\lambda_1}{\lambda_0+\lambda_1}
  \end{align}
  on $\Omega_0^\infty$

