[Lemma lem:mu-doublePrime of arXiv:2412.09290, 'Asymptotics of Harish-Chandra transform and infinitesimal freeness'] Let $\Psi, \Phi, \mathrm{T}$ be infinitely differentiable functions at $0$ and
  consider the sequences $(c_n)_{n \in \mathbb{N}}, (c'_n)_{n \in \mathbb{N}},
  (c''_n)_{n \in \mathbb{N}}$, where for every $n \in \mathbb{N}$
  \[ c_n := \frac{\Psi^{(n)} (0)}{(n - 1) !}, \text{\quad} c'_n :=
     \frac{\Phi^{(n)} (0)}{(n - 1) !} \text{\quad and\quad} c''_n := 2
     \frac{\mathrm{T}^{(n)} (0)}{(n - 1) !} . \]
  Then for the sequence $(\ensuremath{\boldsymbol{\mu}}''_k)_{k \in \mathbb{N}}$ defined by
  ((Ss of the paper)), for every $k \in \mathbb{N}$,  we have
  \[ \ensuremath{\boldsymbol{\mu}}''_k = \frac{1}{2} \left( \sum_{\pi \in \ensuremath{\operatorname{NC}} (k)}
     \sum_{V \in \pi} c''_{|V|} \prod_{\underset{W \neq V}{W \in \pi}} c_{|W|}
     + \sum_{\pi \in \ensuremath{\operatorname{NC}} (k)} \sum_{\underset{W \neq V}{V, W \in \pi}}
     c'_{|V|} c'_{|W|} \prod_{\underset{U \neq V, W}{U \in \pi}} c_{|U|}
     \right) . \]

[Lemma 35 (Asymptotic inequalities for $h_\alpha, f_0, f_\pi$) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] Let $\alpha, \beta \in \mathcal M$ with $\alpha \neq \beta$. Then: \begin{itemize}
    \item Suppose that $\beta\in\mathcal M \cap (0, \pi)$. Then there exist $\e > 0$, $\eta > 0$, $r_0 > 0$, and $C > 0$ such that for all $\gamma \in \mathcal M \cap (\beta - \e, \beta + \e)$ and all $r \geq r_0$,
    \begin{equation}
        h_\gamma(r\cos(\beta), r\sin(\beta)) \geq C^{-1}e^{r(x(\beta)\cos(\alpha) + y(\beta)\sin(\beta) - \eta)} 
    \end{equation}
    and such that for all $r\geq r_0$,
    \begin{equation}
        h_\alpha(r\cos(\beta), r\sin(\beta)) \leq Ce^{r(x(\beta)\cos(\alpha) + y(\beta)\sin(\beta) - 2\eta)}.
    \end{equation}
    \item Suppose that $\beta \in \mathcal M \cap (\pi, 2\pi)$. Then there exist $\e > 0$, $\eta > 0$, $r_0 > 0$, and $C > 0$ such that for all $\gamma \in \mathcal M \cap (\beta - \e, \beta + \e)$ and all $r \geq r_0$,
    \begin{equation}
        h_\gamma(r\cos(\beta), r\sin(\beta)) \geq C^{-1}e^{r(x(\beta)\cos(\alpha) + z(\beta)\sin(\beta) - \eta)} 
    \end{equation}
    and such that for all $r\geq r_0$
    \begin{equation}
        h_\alpha(r\cos(\beta), r\sin(\beta)) \leq Ce^{r(x(\beta)\cos(\alpha) + z(\beta)\sin(\beta) - 2\eta)}.
    \end{equation}
\end{itemize}
Inequalities \eqref{ineq:halpha1} and \eqref{ineq:halpha2} also hold if $\alpha$ is replaced by $0$ (resp. $\pi$) and $h_\alpha$ by $f_0$ (resp. $f_\pi$).

