[Theorem prop_4 of arXiv:2412.03774, '{ Refining Concentration for \\Gaussian Quadratic Chaos with\\ Applications in Sonar and C'] Let $m\geq1$ be an integer, $0<b<1$, $\|A\|_{m+1}$ be Schatten norm of order $m+1$ for a symmetric matrix $A$ and $r(A)$ be the rank of $A$. Then  
 \begin{eqnarray}

\Pr(\boldsymbol{\Delta}>t)\leq e^{\Lambda_m(t, b)},
\end{eqnarray} 
 where\footnote{The function $\Lambda(t,a)$ in ((en_exp of the paper)) and the functions $\Lambda_m(t,b)$ in ((Lambda_m of the paper)) are not related. }
 \begin{eqnarray}

\Lambda_m(t, b)=\frac{r(A)}{2}\sum_{k=2}^m \frac{b^k}{k}-\kappa_m(b)\min\bigg\{\frac{t^{1+\frac{1}{m}}}{\|A\|_{m+1}^{1+\frac{1}{m}}}, \frac{t}{\|A\|} \bigg\} 
\end{eqnarray}
and 
\begin{eqnarray}

\kappa_m(b)=\frac{m}{2(m+1)}\min\bigg\{\frac{1}{\big((m+1)\theta_m(b)\big)^{\frac{1}{m}}}, b\bigg\}
\end{eqnarray}
with $\theta_m(b)$ as defined in ((theta_func of the paper)).

[Proposition 2 of arXiv:2608.13358, 'Extreme points of sets of probability measures and $\phi$-divergences'] For an element $p \in \cM$, the following statements are equivalent.
    \begin{enumerate}
        \item $p$ is an extreme point of $\cM$.
        \item  There exists no $p' \in \cM\setminus \{p\}$ with $p'\ll p$ and $p$-a.s.\ bounded density $\frac{\mathrm{d}p'}{\mathrm{d}p}$.
    \end{enumerate}

