[Definition 22 of arXiv:2604.07697, 'Stochastic fractional heat equation with general rough noise'] \begin{itemize}
\item[(i)] A    real-valued adapted stochastic process $u(t,x)$ is called a  strong  (mild) solution  to \eqref{SFHE}, if for all $t\ge0$ and $x\in\mathbb{R}$,
\begin{equation}
u(t,x)=G_{\alpha}(t,\cdot)*u_0(x)+\int_0^t\int_{\mathbb{R}}G_{\alpha}(t-s,y-x)\sigma(s,y,u(s,y))W(ds,dy)\ \ \text{a.s.},
\end{equation}
  where the stochastic integral is understood in the sense of Proposition \ref{prop 2.3}.
\item[(ii)] We say \eqref{SFHE} has a {\it weak solution}, if there exists a probability space with a filtration $(\widetilde{\Omega},\widetilde{\mathcal{F}},\widetilde{\mathbb{P}},\widetilde{\mathcal{F}_t})$, a Gaussian random field $\widetilde{W}$ identical to $W$ in law, and an adapted stochastic process  $\{u(t,x),t\ge0,x\in\mathbb{R}\}$ on this probability space   such that $u(t,x)$ is a mild solution to \eqref{SFHE} with respect to $(\widetilde{\Omega},\widetilde{\mathcal{F}},\widetilde{\mathbb{P}},\widetilde{\mathcal{F}_t})$ and $\widetilde{W}$.
\end{itemize}

[Lemma lem.recurrence_eq of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] For any $F\subseteq E_d({\scaleobj{1}{\square}}_m)$ and $j \in \mathbb{N}$, we have
		\begin{equation}
			-\nabla \cdot ({\mathbf{a}}^{F} \nabla V_m(F,j)) = \nabla \cdot \mathbf{W}_m(F,j) \quad \text{in } \mathrm{int}({\scaleobj{1}{\square}}_m), 
		\end{equation}
		where $\mathbf{W}_m(F,j)$ is an anti-symmetric vector field on $\overrightarrow{E_d}({\scaleobj{1}{\square}}_m)$
		\begin{align}

			\mathbf{W}_m(F,j) &= \sum_{e\in E_d({\scaleobj{1}{\square}}_m) \setminus F}({\mathbf{a}}^{e}-\mathbf{a})\Big(\nabla V_m(F,j-1) - \nabla V_m(F\cup \{e\}, j-2) \\
			\nonumber & \qquad \qquad \qquad \qquad + \nabla V_m(F\cup \{e\}, j-1)\Big) \\
			\nonumber &\qquad +\sum_{e\in F}({\mathbf{a}}^{e}-\mathbf{a})\Big(\nabla V_m(F\setminus\{e\},j)-\nabla V_m(F,j-1)\Big).
		\end{align}

