=
\ds\frac{\ds\prod_{k=1}^{\infty} \psi_k^V(0)}
{1 + \ds\sum_{n=1}^{\infty}
\big( 1 - \psi_n^H(0) \big)
\ds\prod_{k=1}^n \psi_k^V(0)}.

\end{equation}

