body:
[Proposition 1 of arXiv:2608.04716, 'Extinction Time Estimate for Subcritical (Binary) Homogeneous Crump-Mode-Jagers Processes'] There holds
	\begin{equation}
		\begin{split}	q(x,t)&=\P(T\leq t\mid Z_0=\1_{[x,\infty)})=\frac{\int_x^{x+t} W(t+x-s)\d F(s)}{(1-F(x))W(t)}\\&=1+\frac{\lambda \int_0^x (1-F(y))W^\prime(t+x-y)\d y -W^\prime(t+x)}{\lambda(1-F(x))W(t)}.
		\end{split}
	\end{equation}
	where the function $W$ is the scale function  defined in \cite[page 11]{lambert2010contour} having Laplace transform
	\begin{equation}\Lcal(W)(s):=\int_{0}^\infty W(r)e^{-sr}\d r=\frac{1}{\lambda \left( \E[e^{-s\tau }]-1\right)+s}.\end{equation}

[Lemma lem:finite-Green of arXiv:2607.26169, 'Scaling and partial universality of the height zero probability in the 2D Abelian sandpile'] For a finite graph with boundary $(\Lambda, \partial \Lambda)$, we have 
\eqnst{
  G_\Lambda(v,w)
  = -A(v,w) + \sum_{e = (e^-,e^+) \in \partial \Lambda} H_\Lambda(v,e) A(e^+,w), 
    \quad v, w \in \Lambda, }
where $H_\Lambda(v,e) = \mathbf{P}^v [ E_{\tau_\Lambda} = e ]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_function_spaces of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] For $s\in \mathbb{R}$ we denote by 
    \begin{align*}
        H^{s}_g=\Big\{h\in \mathscr{S}'(\mathbb{T}^3;\mathbb{R}^3):\operatorname{div}h=0,\int_{\mathbb{T}^3}h \mathrm{d}x=0, \sum_{k=(m,j)\in I} \lvert m\rvert^{2s}g(|m|)^{s+1}\langle h,e_{k}\rangle^2<+\infty\Big\}
    \end{align*}
    endowed with its natural norm. 
    For $s\in \mathbb{R},\ p\in [1,+\infty)$ we set
    \begin{align*}
        B^{s}_{g,2,p}=\Big\{h\in \mathscr{S}'(\mathbb{T}^3;\mathbb{R}^3)\,&:\, \operatorname{div}h=0,\int_{\mathbb{T}^3}h \mathrm{d}x=0,\\
        &\ \ \sum_{j\geq -1} \left(2^{s j}g(2^j)^{\frac{s+1}{2}}\left\|\Delta_j h\right\|_{L^2(\mathbb{T}^3;\mathbb{R}^3)}\right)^{p}<+\infty \Big\}
    \end{align*}
    endowed with its natural norm, with the obvious modification in the case $p=\infty$.

[Theorem Thm: LLN for subsequence of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Assume that $\{X_t\}_{t\geq 0}$ (resp. $\{X_k\}_{k\geq 0}$) is a d-dimensional $\alpha$-mixing identical process (resp. sequence) on a sublinear expectation space $(\Omega,\mathcal{H},\hat{\mathbb{E}})$ for some $\alpha>0$ with $\hat{\mathbb{E}}[|X_0|^{2}]<\infty$. Let $\{t_k\}_{k\geq 1}$ (resp. $\{m_k\}_{k\geq 1}$) be a $(\gamma,\delta)$-admissible subsequence for some $0<\gamma<1, \delta>0$. Let
		\begin{equation}
			S_n:=\frac{1}{n}\sum_{i=1}^n X_{t_i} \ (resp. \ S_n:=\frac{1}{n}\sum_{i=1}^n X_{m_i}), \ \text{ and } \ X_0\sim \Gamma.
		\end{equation}
		Then there exists $C>0$ depending only on $(\alpha,\gamma,\delta)$, $c_X$ in Definition (def: alpha-mixing of the paper) and $(c_1,c_2,N_0)$ in Definition (Def: admissible of the paper)  such that for any $\phi\in C_{lip}(\mathbb{R}^d)$ with Lipschitz constant $l_{\phi}$,
		\begin{equation}
			\Big|\hat{\mathbb{E}}[\phi(S_n)]-\max_{x\in \Gamma}\phi(x) \Big|\leq C\bigl(1+\hat{\mathbb{E}}[|X_0|^{2}]\bigr)l_{\phi}\bigl(n^{-1/2}+n^{-(1-\gamma)}\bigr)\text{ for any }n\in\mathbb N.
		\end{equation}
		In particular, if $\gamma\leq 1/2$, we have the convergence rate $n^{-1/2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:uit_num of arXiv:2412.05239, 'Conditions for uniform in time convergence: applications to averaging, numerical discretis'] Suppose (ass of the paper) holds. Let $\nu$ be a probability measure on $\mathbb{R}^d$. Then, there exists $\tilde{\mathbf{C}}<\infty$ such that for all $l\in \mathbb{N}$ and $\delta>0$ with $\delta^{-1}\in \mathbb{N}$,
\begin{align*}
\mathbf{dist}(\nu \pi_{\delta}^l, \nu p_{\delta l}) \le \tilde{\mathbf{C}}\delta^{\alpha}.
\end{align*}
Moreover, the constant $\tilde{\mathbf{C}}$ depends on $\lambda$, $C$ and $\mathbf{C}(\nu)$ given in (ass of the paper).

