[Theorem 7 of arXiv:2606.14170, 'Uniform-in-time error estimates for McKean-Vlasov SDEs with common noise and stochastic al'] Suppose that Assumptions \ref{A1}, \ref{A2}, \ref{S1}, \ref{N1} hold with $\lambda_1>2\lambda_2$ and that $\sigma_0\sigma_1\neq 0$. Let 
$$\overline h=1\wedge\frac{\lambda_1-2\lambda_2}{4(l+1)^2(1+\lambda_2)^{2(l+1)^2}},$$
then there exist constants $C>0$ such that for any $\lambda_2\in [0,\lambda_2^*), L\in[0,L^*]$, $h\in (0,\overline h]$, $t>0$ and $i\in\mathbb{S}_N$,
\begin{align*}
\mathcal{W}_1\big(\mathcal{L}(\mu_t^i),\mathcal{L}(\nu_t^{i,N,h})\big)\le C\left\{{\rm e}^{-\lambda_0t}\mathbb{W}_1(\mu,\nu)+\psi(N)+\left(1+\mathbb{E}|X_0^{i,N,h}|^{2(l+1)^2}\right)h^{1/2}\right\}
\end{align*}
in case of $\mathbb{E}|X_0^i|^{q}<\infty$ for some $q>1$ and $\mathbb{E}|X_0^{i,N,h}|^{2(l+1)^2}<\infty$, where $\mu_t^i=\mathcal{L}(X_t^i\vert \mathcal{F}_t^W)$ stands for the regular conditional distribution of $X_t$, determined by \eqref{NIPS}, with the initial distribution $\mathcal{L}(X_0^i)=\mu$, $\nu_t^{i,N,h}=\mathcal{L}(X_t^{i,N,h}\vert \mathcal{F}_t^W)$ stands for the regular conditional distribution of $X_t^{i,N,h}$, determined by \eqref{BEM}, with the initial distribution $\mathcal{L}(X_0^{i,N,h})=\nu$, $\lambda_2^*, L^*$, and $\lambda_0$ were given in Theorem  \ref{main theorem}.

