{"artifact_digest":"sha256:63feea26801b30c5705fc741de01c9ecad1197f3993276fbe79e532468f7f6ad","artifact_path":"objects/sha256/63/63feea26801b30c5705fc741de01c9ecad1197f3993276fbe79e532468f7f6ad.md","bundle_digest":"sha256:d40e723ba4f91162d13ebab86f4dac24bf7afa185cd96d328c324f21c8b2a0d6","bundle_entry_key":"2608-30304-lemma-12-cancellation","bundle_id":"population.tex-extract-s3_127","claim_kind":"lemma","conditions":[],"domain":"probability theory","draft":"tex-extract-20260907/bundle_s3_127.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2608-30304-lemma-12-cancellation","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: The two contiguous relations used below are \cite[\S18.9(ii)]{DLMF}, equivalently
