+\frac{n+a}{2n+a+b+1}P_{n-1}^{(a,b+1)},
\end{equation}
and the second is
\[
(2m+a+b+2)(1+x)P_m^{(a,b+1)}(x)=2(m+b+1)P_m^{(a,b)}(x)+2(m+1)P_{m+1}^{(a,b)}(x),
\]
which at $m=n-1$, with $b$ replaced by $b+1$, becomes
\begin{equation}
P_n^{(a,b+1)}+\frac{n+b+1}{n}P_{n-1}^{(a,b+1)}
=\frac{2n+a+b+1}{2n}(1+x)P_{n-1}^{(a,b+2)} .
\end{equation}
