[Theorem eq:anis_length of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] For any $\nu>0$, the norm defined by (equation eq:anis_holder_gen of the paper) is equivalent to the H\"older-Zygmund norm induced by $|\cdot|_B$. In particular, for any $n\in{\mathbb {N}}_0$ and $\alpha\in(0,1)$, we have
\begin{align}
\| f \|_{B,n+\alpha} & \asymp \sum_{\substack{\eta\in {\mathbb {N}}^d_0\\  |\eta  |_{B} \leq n}} \| \partial^\eta f \|_{\infty} +\sum_{\substack{\eta\in {\mathbb {N}}_0^d\\  |\eta|_B = n  }}  \sup_{x,y\in \mathbb{R}^d} \frac{|\partial^{\eta} f(x) - \partial^{\eta} f(y)|}{|x - y|^{\alpha}_B} 
\\
&\quad +\sum_{i=1}^{\mathfrak{r} }\sum_{\substack{\eta\in {\mathbb {N}}_0^d\\ k\in\{0,1\} \\  |\eta|_B = n - (2 i - k) }}  \sup_{x,y\in \mathbb{R}^d} \frac{|\partial^{\eta} f(x) - \partial^{\eta} f(x^0 ,\, \dots \,, x^{i-1}, y^{i}, \, \dots \, ,  y^{\mathfrak{r}})|}{|x - (x^0 ,\, \dots \,, x^{h-1}, y^{h}, \, \dots \, ,  y^{\mathfrak{r}})|^{\alpha + 2i - k}_B},
\end{align}
where $|\eta|_B$ is the \emph{anisotropic length} of $\eta = (\eta^0, \dots, \eta^{\mathfrak{r}}) \in {\mathbb {N}}^d_0$, defined as
\begin{equation}
|\eta|_B := \sum_{i=0}^{\mathfrak{r}} (2i + 1) |\eta^{i}|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 8 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] There exist $C>0$ and $0<\delta<1$ such that
    \begin{align}
        -C+(1-\delta)\mathbb{E}\left[\Vert \nabla Z_T(u)\Vert_{L^4}^4+\frac{1}{2}\Vert u\Vert_\mathcal{H}^2\right]\leq F_T(u)\leq C+(1+\delta)\mathbb{E}\left[\Vert \nabla Z_T(u)\Vert_{L^4}^4+\frac{1}{2}\Vert u\Vert_\mathcal{H}^2\right].
    \end{align}

