body:
[Theorem 11 ($\AW_2$ between filtered Gaussian processes) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $a, b \in \bR^{Nd}$ and $L, M \in \mathscr{L}(N,d)$.
\begin{enumerate}
\item[(i)] We have
\begin{equation} 
\begin{split}
\AW_2^2(\bG^{a, L}, \bG^{b,M}) = \|a - b\|_2^2 + \dist_{\mathrm{AW}}^2(L, M),
\end{split}
\end{equation}
where $\dist_{\mathrm{AW}}$ is the pseudo-metric on $\mathscr{L}(N, d)$ defined by
\begin{equation} 
\dist_{\mathrm{AW}}(L, M) := \Big(\|L\|_F^2 + \|M\|_F^2 - 2 \sum_{t=1}^N \|(L^{\intercal}M)_{t,t} \|_{*}\Big)^{1/2}.
\end{equation}
We let $\tilde{\mathscr{L}}(N, d)$ be the quotient space $\mathscr{L}(N, d) / \sim$, where $L \sim M$ if and only if $\dist_{\mathrm{AW}}(L, M) = 0$. We use the same symbol $\dist_{\mathrm{AW}}$ to denote the induced metric.
\item[(ii)]
There exists a Gaussian bicausal coupling that is optimal for $\AW_2(\bG^{a, L}, \bG^{b,M})$. A Gaussian bicausal coupling of the form $\pi^P$ defined by \eqref{eqn:joint.Gaussian}, where $P = \diag(P_1, \ldots, P_N)$ is block diagonal, is optimal if and only if
\[
P_t \in \mathscr{P}( (L^{\intercal} M)_{t,t}), \quad t \in [N].
\]
In particular, we may pick $P_t = V_t U_t^{\intercal}$, so that $P$ is block diagonal with orthogonal diagonal blocks (written $P \in \mathscr{O}(N, d)$).
\end{enumerate}

