[Theorem thm:graph_gnz of arXiv:2411.02917, '\hspace*{2mm}\\[-16mm] Stein's Method for Spatial Random Graphs'] For any measurable function $h:\mathfrak{N} \times \mathfrak{N}_2 \times \mathcal{X} \times \mathfrak{N}_2 \to \R_+$ we have
  \vspace*{-5mm}


  \begin{equation*}
  \begin{split}
    &\int_{\mathfrak{N} \times \mathfrak{N}_2} \int_{\mathcal{X}} h \bigl(\xi-\delta_x, \sigma \vert_{(\xi-\delta_x)^{\langle2\rangle}}, x, \sigma \vert_{\langle \xi-\delta_x,x \rangle} \bigr) \; \xi(dx) \; (P \otimes Q)(d(\xi,\sigma)) \\
    &= \int_{\mathfrak{N} \times \mathfrak{N}_2} \int_{\mathcal{X}} \int_{\mathfrak{N}_2} h\bigl(\xi, \sigma, x, \sigma_2 \bigr) \; \tilde{Q}_{2 \,|\, 1}(\xi,x,\sigma ;\, d\sigma_2) \; L(\diff x \,|\, \xi) \; (P \otimes Q)(d(\xi,\sigma))  \\
    &\hspace*{3mm} {} + \int_{\mathfrak{N}} \int_{\mathcal{X}} \int_{\mathfrak{N}_2} \int_{\mathfrak{N}_2}\! h\bigl(\xi, \sigma_1, x, \sigma_2 \bigr) \; \tilde{Q}_{2 \,|\, 1}(\xi,x,\sigma_1 ;\, d\sigma_2) \; \bigl( \tilde{Q}_1(\xi, x;\, d\sigma_1) - Q(\xi, d\sigma_1) \bigr) \; L(dx \,|\, \xi) \; P(d\xi).
  \end{split}
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 45 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] \cite[Theorem 4.2]{karlsenrisebro01} 
	Let $\La > 0$, and $A: [0,\La] \to \R$ be a function such that
	\begin{equation}
		A \text{ is non-decreasing, } A(0) = 0, \text{ and }A\text{ is Lipschitz continuous}.
	\end{equation}
	Let $v_{0} \in L^{1}(\R^{d}) \cap \BD{\La}(\R^{d})$, and let $v_{N}$ be generated by $\mathcal{S}_{N}$ with initial condition $v_{0}$. If there exists $\ve \in (0,1)$ such that for all $N$ sufficiently large, 
	\begin{equation} 
		2N^{-\frac{dm}{dm+2}}\max_{r \in [0,\La]}A'(r) < 1 - \ve,
	\end{equation}
	then there is a function $v: \R^{d}\times [0, \infty)\rightarrow \R$ (independent of $\ve$) such that for any $T>0$, $v_{N} \to v$ in $L^{1}_{\text{loc}}(Q_{T})$, and $v$ is the unique entropy solution to 
	\begin{equation*}
	\begin{cases}
			v_{t}-\frac{1}{2d}\Delta(A(v))=0&\text{in $\R^{d}\times (0, \infty)$},\\
			v(0,x)=v_{0}(x)&\text{in $\R^{d}$}.
		\end{cases}
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem flow of arXiv:2604.10509, 'Nonequilibrium fluctuations and moderate deviations for the occupation time of the SSEP wi'] There exists a flow $\phi_\ell$ connecting $\delta_0$ and $q_\ell$ such that
\begin{itemize}

	\item[(i)] $\phi_\ell (x,y) = 0$ if $x \notin \Lambda_{2\ell-1}$ or $y \notin \Lambda_{2\ell-1}$;


	\item[(ii)] there exists some constant $C_0 = C_0 (d)$ such that
	\[\sum_{x,y \in \mathbb T_n^d \atop |x-y|=1} \phi_\ell (x,y)^2 \leq C_0 g_d (\ell),\]
	where
	\begin{equation}
		g_d (\ell) = \begin{cases}
			\ell, \quad&\text{if}\quad d=1,\\
			\log	\ell, \quad&\text{if}\quad d=2,\\
			1, \quad&\text{if}\quad d \geq 3.
		\end{cases}
	\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm stat_conv of arXiv:2607.08869, 'Inequalities for convex functions of random points inside and on the boundary of convex bo'] For $X, Y \in \mathbb{R}^d$, one has $X \preceq_{cx} Y$ if and only if for every unit vector $u \in S^{d-1}$ and every convex $f \colon \mathbb{R} \to \mathbb{R}$,
    \begin{align}
        \mathbb E f(\langle X, u\rangle) \leqslant \mathbb E f(\langle Y, u\rangle),
    \end{align}
    where $\langle \cdot, \cdot \rangle$ is the scalar product. (Proof in the paper; no proof environment follows the statement in the TeX.)

