[Pro pro2.1 of arXiv:2603.13873, '{Solvability of BSDEs with possibly unbounded stochastic coefficients \\ on a general weig'] Let the assumptions of (pro2.01 of the paper) hold. Then there exists a constant $C_{\bar{p},\theta}>0$ depending only on $\bar{p}$ and $\theta$ such that for each $0\leq r\leq t< +\infty$,
\begin{align*}
\begin{split}
&\mathbb{E}\left[\sup_{s\in[t\wedge\tau,\tau]}\left(e^{\bar{p}\int_{0}^{s}
\bar{\rho}_{r}{\rm d}r}|y_s|^{\bar{p}}\right)\bigg|\mathcal{F}_{r\wedge\tau}\right]+ \mathbb{E}\left[\left(\int_{t\wedge\tau}^{\tau}e^{2 \int_{0}^{s}\bar{\rho}_r{\rm d}r}|z_s|^2{\rm d}s\right)^\frac{\bar{p}}{2}\bigg|\mathcal{F}_{r\wedge\tau}\right]\\
&\hspace{0.6cm}+\mathbb{E}\left[\int_{t\wedge\tau}^{\tau}\bar{p}e^{\bar{p} \int_{0}^{s}\bar{\rho}_r{\rm d}r}(\bar{\rho}_s-\bar{\mu}_s-\frac{\theta}{2[1\wedge(\bar{p}-1)]}
{\bar\nu_s}^2)|y_s|^{\bar{p}}{\rm d}s\bigg|\mathcal{F}_{r\wedge\tau}\right]\\
&\ \ \leq
C_{\bar{p},\theta}\mathbb{E}\left[e^{\bar{p}\int_{0}^{\tau}\bar{\rho}_{r}{\rm d}r}|\xi|^{\bar{p}}+\left(
\int_{t\wedge\tau}^{\tau}e^{ \int_{0}^{s}\bar{\rho}_r{\rm d}r}f_s{\rm d}s\right)^{\bar{p}}\bigg|\mathcal{F}_{r\wedge\tau}\right].
\end{split}
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm
The probability measure $\mu$ is said to satisfy the transportation cost inequality $T_p(C)$ on $(E,d)$ if there exists a constant $C>0$ such that, for any probability measure $\nu$ on $\mathcal{M}(E)$,}
\begin{align}
W_p(\mu,\nu)\leq\sqrt{2CH(\nu|\mu)}.
\end{align}

[Definition eq83 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Define the sub-$\sigma$-algebras $(\mathcal{A}^{(n)})_{n \geq 0}$ of $\mathcal{F}$ by letting, for each $n \in \mathbb{N}_{0}$,
\begin{align}  
\mathcal{A}^{(n)} \coloneqq \sigma( \pi_{v}: v \in \mathcal{I} \, \, \text{such that} \, \, |v| \leq  n).
\end{align}
\noindent We say that a characteristic $\varphi: \Omega \times \mathbb{R} \rightarrow \mathbb{R}$ is an {\sl $h$-dependent descendant characteristic}, for $h \in \mathbb{N}_{0}$, if the map $(\omega, t) \mapsto \varphi(\omega, t)$ is measurable with respect the product $\sigma$-algebra $\mathcal{B}(\mathbb{R})\times \mathcal{A}^{(h)}$, where $\mathcal{B}(\mathbb{R})$ is the Borel $\sigma$-algebra.

[Corollary CLT in critical of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
    Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM with the zero mean innovation sequence $\{\xi_n\}_{n\ge 1}$ satisfying $\mathbb{E}\xi_1^2=1$. If $\{\mu_n\}$ is such that $\{v_n\}$ is unbounded for $p=p_c$, then
    $$\frac{S_n}{\sigma_n} \to_{\rm{w}} N(0,(2\gamma+1)^2).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 24 of arXiv:2506.09609, 'Schramm-Loewner evolution contains a topological Sierpi\'nski carpet when $\kappa$ is clos'] For any $T,\varrho\geq 1$, there exists a constant $c = c(T,\varrho)>0$ such that for all $s \in (0,T)$ and $\iota>0$, the following holds for all sufficiently large $R$. Let $\mathfrak h$ be a whole-plane Gaussian free field normalized so that $\mathfrak h_{2R}(0) = 0$, where $\mathfrak h_{2R}$ is the average of $\mathfrak h$ over $\partial B(0, 2R)$. For each $y \in \mathscr L_R$, let $\mathcal{E}_y$ be an event that is measurable with respect to $\mathfrak h|_{B(y, \varrho)}$ modulo $s \mathbb{Z}$ and satisfies
    \begin{equation}
    \mathbb{P}[\mathcal{E}_y] \geq 1 - c.
    \end{equation}
    Then, with probability at least $1-\iota$, 
    \begin{equation}
    \mbox{all connected components of } \cup_w \overline{B(w, 1)} \mbox{ have } |\cdot|_\infty \mbox{-diameter at most } \iota R,
    \end{equation}
    where the union is over those $w \in \mathscr{L}_R$ for which $\mathcal{E}_w$ does not occur, and two boxes that share exactly one point are also viewed as connected. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop of arXiv:2608.29914, 'Fixed points in abstract provability structures'] There is an APS $S$ satisfying the following conditions:
\begin{enumerate}
    \item Every one-variable APS term of even degree has two distinct fixed points in $S$. 

    \item Every one-variable APS term of odd degree has no fixed point in $S$. 
\end{enumerate}

[Proposition prop:cle-gf-to-bubble of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] Let ${\frak C}$ be the same constant as in Proposition~(prop:touching-equals-bubble of the paper). Then for any $n\ge2$, we have
\begin{equation}
G^\mathrm{Bub}_{x_1}(x_2,...,x_n)dx_1dx_2...dx_n={\frak C}\mathbbm{E}\left[\sum_{\ell\in\mathcal{T}(\Gamma)}\prod_{i=1}^n\nu_{\ell\cap\mathbbm{R}}(dx_i)\right].
\end{equation}
When $n=2$, $G^\mathrm{Bub}_{x_1}(x_2)={\frak C}H_{\mathbbm{H}}(x_1,x_2)^h$ (we choose the constant of $H_{\mathbbm{H}}(x_1,x_2)$ such that the coefficient is ${\frak C}$). In particular, for the $\CLE_\kappa$ boundary Green's functions defined in~(equation eq:four-type-gf of the paper), we have
\begin{align}
G^{(1234)}(x_1,x_2,x_3,x_4)&= {\frak C}G^\mathrm{Bub}_{x_1}(x_2,x_3,x_4)\in(0,\infty),\\
G^{(12)(34)}(x_1,x_2,x_3,x_4)&={\frak C}\int H_{\mathcal{U}(\gamma)}(x_3,x_4)^h\mu_{x_1,x_2}^\mathrm{Bub}(d\gamma)\in(0,\infty)
\end{align}
where $\mu_{x_1,x_2}^\mathrm{Bub}$ is defined in~(equation eq:bubble-two-pinned of the paper).
Recall that $\mathcal{U}(A)$ denotes the unbounded connected component of $\mathbbm{H}\setminus A$ for a compact subset $A\subset\ol\mathbbm{H}$.

[Proposition eq:erdos_renyi_connectivity of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:erdos_renyi_connectivity}
    Consider the Erd\H{o}s-R\'enyi{} random graph $G(n,p_n)$ with $n p_n = \omega(\log n)$. Then 

    \begin{equation}

        \mathbf{P} 
        \left(
            G(n,p_n)
            \text{ is not connected}
        \right)
        \leq 
        3 (en)^2 (1-p_n)^{n/2}
    \end{equation}  

    for all $n \geq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Assume \eqref{assump:alpha},  \eqref{assump:moments}, \eqref{assump:nondeg} and \eqref{eq:mixedblocks}. Suppose that the equivalence relation defined in \eqref{eq:equivalence.relation} has two equivalence classes as described in \eqref{eq:equivalence.classes}. Assume that there  is  $\bb \xi^* \in D \cap (0,1)^2$ such that $m=h(\bb \xi^*)$ and that \eqref{assump:cramer} is satisfied for $\mu_{\bb \xi^*}$. Then there exists a Radon measure $\Lambda_2$ on $\R^d\setminus[\mathsf{blocks}]$ such that for all $f\in \bfC (\R ^d\setminus[\mathsf{blocks}])$,
	\begin{equation}
		\lim_{t \to \infty} (\log t)^{1/2}	t^{\xi^* _1+\xi^* _2}\E \big[ f(t^{-1/\bb \alpha}\bb X)\big]= \int f(\bb x) \Lambda_2(d\bb x) .
	\end{equation} 
	The measure $\Lambda_2$ has the following invariance properties: For all $k \in K$ and $t>0$,
	\begin{equation}
		\int f(k \bb x) \Lambda_2(d \bb x) = \int f(\bb x) \Lambda_2(d \bb x) \ \text{ and } \ \int f(t^{1/\bb \alpha} \bb x) \lambda(d \bb x) = t^{\xi^*_1 + \xi^*_2} \int f(\bb x) \Lambda_2(d \bb x)
	\end{equation}
	as well as, for all $r>0$,
	\begin{equation} 
		\Lambda _2(\wt S _r) = 0.
	\end{equation}
	Moreover, there is a Radon measure $\nu $ on $\wt S_1$   such that for all $f\in \bfC \left (\R ^d\setminus [\mathsf{blocks}]\right )$ 
	\begin{equation}
		\int f(\bb x)\Lambda _2(d\bb x) = \int _{\wt S_1}\int _0^\8 f(s^{1\slash {\bb \a} }\omega )\frac{ds}{s^{\xi^* _1+\xi^* _2+1}}d\nu (\omega),
	\end{equation}
	and this measure $\nu$ is invariant under the action of $K$.
	 and satisfies, for all $g \in \mathcal{C}_c(\wt{S}_1)$,

	The measures $\Lambda_2$ and $\nu$ are nonzero if and only if for every $R>0$
	\begin{equation}
		\P( \norma{X^{(1)}}>R, \, \norma{X^{(2)}}>R)>0.
	\end{equation}
If \eqref{eq:suppX:unbounded} holds, then the measure $\nu$ is unbounded. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma vprocess of arXiv:2607.21443, 'The critical KPZ scale for the averaging process'] Fix  $k \geq 2$, a finite-support function $h:\mathbb{Z}\to\mathbb{R}$, and a sequence $\beta=\beta_N\to 0$ as $N\to \infty$. Consider $\mathbf x^N\in \mathbb{Z}^k$ such that $N^{-1/2}\mathbf x^N\to \mathbf z \in \mathbb{R}^k$ as $N\to \infty$. Then, for all $1\le i,j\le k$, $i\neq j$, the pair
     \begin{equation}
      \tonde{N^{-1/2}\tttonde{R^i_{tN} - R^j_{tN}},N^{-1/2} \textstyle{\int_0^{tN}} h(R^i_s - R^j_s)\,{\rm d} s }_{t\ge 0}\; \text{,}\;\;\quad\text{under}\ \mathbf P_{\mathbf x^N}^{(\beta_N,k)}\; \text{,}\;\;
    \end{equation} weakly converges in  $\ensuremath{\mathcal D}([0,\infty);\mathbb{R}^2)$ as $N\to \infty$ to 
    \begin{equation}
    (W_t, \gamma^2(h)\, L_t^W )_{t\ge 0}\; \text{,}\;\;\quad \text{with}\ \gamma^2(h)\coloneqq \textstyle{\sum_{x\in \mathbb{Z}}}\, h(x)\; \text{,}\;\;
    \end{equation}where $W$ is a Brownian motion with $W_0=z_i-z_j\in \mathbb{R}$, and $L^W$ is its local time at zero. (Proof in the paper; no proof environment follows the statement in the TeX.)

