  \begin{align}
    u_j &= \sum_{\ell = 0}^{\infty} E[Y_{j+\ell} \mid \mathcal{G}_{j-1}]=\sum_{\ell = 0}^{\infty} \sum_{k\in I_{j+\ell}} a_k E[X_k \mid \mathcal{G}_{j-1}]\\
    &= \sum_{k > h_j} a_k \alpha^{k-h_j+1} X_{h_{j-1}} = X_{h_{j-1}} \sum_{k\ge 1} a_{k+h_j} \alpha^{k+1}.
  \end{align}
  We decompose the sum \eqref{eq:u_j} into two terms: 
  \begin{equation}
    \Sigma_1 := \sum_{k\le H_j}^{} a_{k+h_j} \alpha^{k+1},\quad\text{and}\quad \Sigma_2 := \sum_{k> H_j}^{} a_{k+h_j} \alpha^{k+1}.
  \end{equation}
