[Lemma 61 (Summably normalized reduced density) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Enumerate the flattenings entering \eqref{all:eq:4.3} as $(L_{s,\nu})_{\nu\ge1}$ and choose
$\beta_{s,\nu}>0$ with $\sum_\nu\beta_{s,\nu}<\infty$.  Then
\begin{equation}
 \overline D_s^{\,\mathrm{nl}}(F)
 =
 \sum_{\nu\ge1}\beta_{s,\nu}
 \frac{L_{s,\nu}L_{s,\nu}^*}
 {1+\norm{L_{s,\nu}}_{\HS}^2}

\end{equation}
converges in trace norm and
\begin{equation}
 \boxed{
 \cN_s(F)
 =\ol{\Ran\bigl(\overline D_s^{\,\mathrm{nl}}(F)\bigr)^{1/2}}.}

\end{equation}
The analogous density obtained from all flattenings has range $\cS_s(F)$.

[Lemma 9 ({\cite[Lemma 8) of arXiv:2604.27519, 'Quantitative homogenization of the maximal action of curves in a Brownian potential'] {OPW}}] For $\nu\ge e$ we consider

\begin{align}
{\mathcal N}_\nu=\{\,\bar h\in{\mathcal N}\,|\,D(\bar h_{\rho})/L\le(\rho/l)^2\nu
\;\;\mbox{for}\;\;l\le\rho\le L,\quad|\bar h(0)|/L\le\nu\,\}.
\end{align}

Then there exists a universal constant $C_0$ such that

\begin{align*}
\ln \# {\mathcal N}_\nu\le C_0(L/l)\ln\nu.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: Double Roots of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Assume (equation eq: Parameters of the paper). The solutions to $\Delta_1=\Delta_2=0$ are:
\begin{equation}

\left|\begin{array}{lll} 
P_1=(0,1), \ \  P_2=(1-w_-,w_-)\ \ P_3=(1-w_+,w_+),\\
P_4=(0,0), \ \ P_5=(\sigma_5,w_5), \ \ P'_5=(0,r),
\end{array}\right.
\end{equation}
where the points are defined as follows:\\\\
\underline{$P_5$ point}. 
\begin{equation}

P_5=\left(\sigma(P_5)=\frac{r\sqrt{d}}{d+\ell},\ w(P_5)=\frac{\ell r}{d+\ell}\right)
 \end{equation}
\underline{$P_2$, $P_3$ points}. Let $J(w_e)$ as in (equation eq: I and J of the paper). Then
\begin{equation}

w_{\pm}=\frac{1}{2(d-1)}\left(dw_e+d-1-\frac{dw_e}{\ell}\pm\sqrt{J(w_e)}\right)
\end{equation} 
and $P_2$, $P_3$ are on the phase portrait iff  
\begin{equation}

w_\pm  \ \ \mbox{real} \Leftrightarrow (w_e<w_{\ell}^- \ \ \mbox{or}\ \ w_e>w_\ell^+)
\end{equation}
with 
\begin{equation}

w_{\ell}^{\pm}=\frac{\ell(d-1)}{d(1-\ell)^2}\left[\ell+1\pm2\sqrt{\ell}\right].
\end{equation}
If (equation eq: Parameters of the paper) then, $w_e<w_\ell^-$ holds so $P_2$, $P_3$ are indeed on the phase portrait.\\\\
\underline{Location}.  When defined, $P_2,P_3,P_5$ are located on the curve of the middle root $(\sigma, w_2(\sigma))$ of $\Delta_1$. Moreover, $P_2,P_5$ are on the curve of the lower root $w_2^-$ of $\Delta_2$.\\\\
\underline{Position of the middle root}. Let $w_e<w_\ell^-$ and $w_2(\sigma)$ be the middle root of $\Delta _1$, then the relative position of the middle root with respect to the sonic line is:
\begin{equation}

\sigma+w_2(\sigma)\left|\begin{array}{l}
>1\ \ \mbox{for}\ \ 0<\sigma<\sigma(P_3)\\
<1\ \ \mbox{for}\ \ \sigma(P_3)<\sigma<\sigma(P_2)\\
>1\ \ \mbox{for}\ \ \sigma>\sigma(P_2).
\end{array}\right.
\end{equation}

[Proposition 10 of arXiv:2606.12670, 'The censored stochastic six-vertex model and parabolic Kazhdan--Lusztig $R$-polynomials'] The law of the $\mathcal C$-censored stochastic six-vertex process $\eta_t$ started from the initial condition $\bm{1}_{x>0}$ is given by 
\[
\lim_{N\to\infty}\prod_{s=0}^{t-1}\prod_{k=-N}^{t-1-s} {P}_{-k,t-1-s}\delta_{\bm{1}_{x>0}}
\]
where 
\[
{P}_{k,t}=\begin{cases}
    P_k\,\text{, if }(k+t,t)\notin\mathcal C\\
    \mathrm{Id}\,\text{, else.}
\end{cases}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:L2-self of arXiv:2605.03703, 'Scaling Limits of Bivariate Nearly-Unstable Hawkes Processes and Applications to Rough Vol'] For each $i\in\{1,2\}$,
\begin{equation}
g_T^i\longrightarrow K_i^\circ
\quad\text{in }L^2(\mathbb R_+).
\end{equation}
Under~(A5),
\begin{equation}
\tilde h_T\longrightarrow
L_{12}^\circ:=b_\infty^{12}\|\psi^{12}\|_1(K_1^\circ*K_2^\circ)
\quad\text{in }L^2(\mathbb R_+).
\end{equation}
Equivalently, after the dilation~(equation eq:macro-kernels of the paper), the macroscopic
cross-kernel is
$L_{12}=b_\infty^{12}\|\psi^{12}\|_1(K_1*K_2)$.
Moreover, the Fourier transforms satisfy the uniform bounds
\begin{equation}
|\widehat{g_T^i}(i\xi)|\leq\frac{C_i}{1+c_i|\xi|^{\alpha_i}},\qquad i=1,2,
\end{equation}
and
\begin{equation}
|\widehat{\tilde h_T}(i\xi)|\leq
\frac{C}{(1+c_1|\xi|^{\alpha_1})(1+c_2|\xi|^{\alpha_2})},
\end{equation}
with constants independent of $T$.

[Lem 14 of arXiv:2506.21087, 'Quasi-Stationary Distributions of Interacting Dynamical Systems and their approximation'] Assume \ref{condhzero}, \ref{condhun} and \ref{condhdeux}. 

\begin{itemize} 

\item[(i)] For any $\mu_0\in{\cal P}(\MM)$, the differential equation

\begin{equation}
\dot{\mu}_t=\mu_t {\cal A}_{\mu_t}-(\mu_t {\cal A}_{\mu_t}{\bf 1})\mu_t.
\end{equation}
admits a unique solution in ${\cal P}(\MM)$.
Furthermore, 
\begin{equation}
\forall t\ge0,\quad \mu_t=\frac{\nu_0\varphi_t}{\nu_0\varphi_t{\bf 1}},
\end{equation}
where $(\varphi_t)_{t\ge0}$ is the unique solution on $({\cal B}(\MM),\|.\|_\infty)$, space of bounded linear operators on ${\cal C}(\MM,\ER_+)$ starting from ${\rm Id}$ to 
\begin{equation}
\dot{\varphi}=\varphi_{t} {\cal A}_{\mu_t}, \quad t\ge0.
\end{equation}
\item[(ii)] For every $\nu_0\in{\cal P}(\MM)$, the differential equation \eqref{eq:nutdyn} admits a unique solution $(\nu_t)_{t\ge0}$ in ${\cal P}(\MM)$, starting from $\nu_0$. Furthermore, 
if $(\mu_t)_{t\ge0}$ is the solution of \eqref{eq:linearizedmut}, then $\nu_t:=\mu_{\tau(t)}$ where $\tau$ is a ${\cal C}^1$-diffeomorphism from $\ER_+$ to $\ER_+$ being the unique solution of 
\begin{equation}
 \tau'(t)=\frac{1}{\mu_{\tau(t)} {\cal A}_{\mu_{\tau(t)}}{\bf 1}}\quad \textnormal{with $\tau(0)=0$}.
 \end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

