[Thm domain-mon of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $D, \tilde D\subseteq\mathbb C$ be two simply connected domains such that $D\subseteq\tilde D$. Let $\phi$ and $\tilde\phi$ be two GFFs in the respective domains. We have that:
    \begin{enumerate}[label=(\roman*)]
        \item For any $\alpha\in(0,\sqrt{2})$ and any $z,w\in D$, 
        \begin{equation}
             \langle :\! \cos(\alpha\phi(z)) \!: :\! \cos(\alpha\phi(w)) \!: \rangle \geq \langle :\! \cos(\alpha\tilde\phi(z)) \!: :\! \cos(\alpha\tilde\phi(w)) \!: \rangle. 
        \end{equation}
        \item For any $\alpha\in(0,1]$ and any $z,w\in D$, 
        \begin{equation}
             \langle :\! \sin(\alpha\phi(z)) \!: :\! \sin(\alpha\phi(w)) \!: \rangle \leq \langle :\! \sin(\alpha\tilde\phi(z)) \!: :\! \sin(\alpha\tilde\phi(w)) \!: \rangle.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

