body:
[Cor 613595 of arXiv:2606.29143, 'Comonotonic and moment matching approximations for sums of lognormal random variables'] Consider the sum $S = \sum^n_{i = 1}X_i$ of continuous random variables $X_1, ..., X_n$ and let $T$ be a continuous comonotonic approximation of $S$, which means that there exist continuous random variables $Y_1, ..., Y_n$ such that $T = Y^c_1 + ... + Y^c_n.$ Assume that $Var[S] < \infty$ and $Var[T] < \infty$ and denote $c = (1, E[S], E[S^2])^{'}$. Let $Q = (q_1, q_2, q_3)^{'}$ be any fixed numerical vector with $0 = q_0 < q_1 < q_2 < q_3 = 1$ and define the $3 \times 3$ matrix $B$ by $B = (b_1, b_2, b_3)$ where $b_1, b_2, b_3$ are $3$-dimensional column vectors defined by 
\begin{equation} 
b_j = (1, b_{1j}, b_{2j})^{'}, \,\, j = 1, 2, 3
\end{equation}
with  
\begin{equation} 
b_{ij} = E[T^i \,|\, F_{T}^{-1}(q_{j - 1}) \leq T \leq F_{T}^{-1}(q_j)] < \infty, \,\, i = 1, 2, j = 1, 2, 3.
\end{equation}
Denote the convex cone generated by the vectors $b_1, b_2, b_3$ by $$\text{Cone}(b_1, b_2, b_3) = \{\lambda_1b_1 + \lambda_2b_2 + \lambda_3b_3 \,|\, \lambda_j \geq 0, j = 1, 2, 3\}.$$ If $\det(B) \neq 0$ and $c \in \text{Cone}(b_1, b_2, b_3)$ then the step-weighted version $T_\omega $ of the starting comonotonic approximation $T$ associated with the step-weight function $\omega = \omega_{A, Q}$ with 
$$A = \text{diag}((q_1 - q_0)^{-1}, (q_2 - q_1)^{-1}, (q_3 - q_2)^{-1})B^{-1}c$$ 
defines a comonotonic approximation of $S$ such that 
\begin{equation*}
E[T_\omega] = E[S] \,\, \text{and} \,\, Var[T_\omega] = Var[S]. 
\end{equation*}

[Theorem 3 (Bernstein--Widder) of arXiv:2607.04467, 'Bernstein Functions at Work:\\ Coalescents, Copulas, and Subordination'] \(f\in\CM\) if and only if there is a unique positive Radon measure \(\mu\) on
\([0,\infty)\) such that
\begin{equation}
f(x)=\int_{[0,\infty)}e^{-xt}\,d\mu(t).
\end{equation}
The representing measure satisfies
\begin{equation}
\int_{[0,\infty)}e^{-xt}\,d\mu(t)<\infty,\qquad x>0.
\end{equation}
If \(\mu\) is finite, then \(f(0^+)=\mu([0,\infty))\) and
\(f(\infty)=\mu(\{0\})\). Hence \(f\) is a normalized survival transform
(\(f(0^+)=1\), \(f(\infty)=0\)) exactly when \(\mu\) is a probability measure
with no atom at \(0\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Suppose that~\eqref{co:6} and~\eqref{eq:integrability condition} are valid for $\rho > 0$. Then for any positive solution $I$ to~\eqref{eq:SIS epidemic model} and $x_{0} \geq 0$, the following two assertions hold:
\begin{enumerate}[(i)]
\item If $x_{0} > 0$ and for each $\delta\in ]0,x_{0}[$ there is a measurable locally integrable function $w_{\delta}\colon\R_{+}\rightarrow\R$ such that $\limsup_{t\uparrow\infty}\frac{1}{t^{\rho}}\int_{0}^{t}w_{\delta}(s)\,\mathrm{d}s > 0$ and
\begin{equation*}
\liminf_{s\uparrow\infty}\inf_{x\in ]0,N(s)]:\,x < x_{0} - \delta}\frac{1}{s^{\rho -1}}\big(h\big(s,x,N(s),\mathcal{L}(I_{s})\big) - w_{\delta}(s)\big) \geq 0,
\end{equation*}
then $I$ persists above $x_{0}$, that is, $\limsup_{t\uparrow\infty} I_{t}\geq x_{0}$ a.s.

\item If for each $\delta > 0$ there is a measurable locally integrable function $w_{\delta}\colon\R_{+}\rightarrow\R$ such that $\liminf_{t\uparrow\infty}\frac{1}{t^{\rho}}\int_{0}^{t}w_{\delta}(s)\,\mathrm{d}s < 0$ and
\begin{equation*}
\limsup_{s\uparrow\infty}\sup_{x\in ]0,N(s)]:\,x > x_{0} + \delta}\frac{1}{s^{\rho -1}}\big(h\big(s,x,N(s),\mathcal{L}(I_{s})\big) - w_{\delta}(s)\big) \leq 0,
\end{equation*}
then $\liminf_{t\uparrow\infty} I_{t}\leq x_{0}$ a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemmas4.111 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] For each \(s>1/2\), we can find a constant $C_{s,g}>0$ depending only on $s$ and the function $g$ such that 

\begin{equation}
\|B_{F(t)}\|_{\mathcal{L}_2(H,H^{-s})}^2
=\|A^{-s/2}M_{F(t)}\|_{\mathrm{HS}}^2
\le C_{s,g} Z(t)^\beta+C_{s,g}\varepsilon_n^2,

\end{equation}
where $\mathcal{L}_2(H,H^{-s})$ is the space of Hilbert-Schmidt operators from $H$ to $H^{-s}$
and

\begin{equation}
Z(t)\le r_s^{2(1-s)}(t)\mathcal A_s^s(t),\quad \forall t\geq 0.

\end{equation}

