body:
[Theorem thm:even_beta of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] The vector-valued function $\mathbf{q}(\lambda)$ satisfies the ODE
 \begin{align}
     \frac{\beta}{4} \lambda \mathbf{q}'(\lambda) = (i \frac{\beta}{4}\lambda  \mathbf{B}_n   +\mathbf{A}_n) \mathbf{q}(\lambda)+\frac{n+1}{2} \mathbf{e}_n, \qquad \mathbf{q}(0)=\mathbf{f}_n.
\end{align}
The functions $\lambda\mapsto q_k(\lambda)$ can be extended to ${\mathbb C}$ as entire functions  so that (equation eq:ode_q_vec of the paper) holds for all $\lambda\in {\mathbb C}$. With this extension, we have for all $\lambda\in {\mathbb C}$
\begin{align}
    \mathbf{q}(\lambda)=\sum_{j=0}^\infty \mathbf{s}_j \lambda^j.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop asymp 2 pt cut disks CR 1 8 of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] As $\max(\varepsilon_1,\varepsilon_2)\to 0$, we have that 
\begin{multline*}
\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^{v, \rm{holes}})
=
\dfrac{2}{\pi}
\varepsilon_{1}^{1/8}
\varepsilon_{2}^{1/8}
\log(\varepsilon_1^{-1})^{1/2}
\log(\varepsilon_2^{-1})^{1/2}
\\
\times
\mathbb{E}
\big[
\CR(z_1,\widehat{D}_{r_0}(z_1))^{-1/8}
\CR(z_2,\widehat{D}_{r_0}(z_2))^{-1/8}
\1_{E_{r_0}}
\big]
(1+o(1))
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 43 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta>0$, $\varepsilon>0$ and $b> v\vee (2\lambda)$.
Then
\begin{displaymath}
\E\Big[\Big\Vert
\ind_{\Ns_{\varepsilon}(A)}
-\E\big[\ind_{\Ns_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\leq
\int_{D^{2}}
\PP\Big(z\stackrel{D\setminus A_{0,b}}{\longleftrightarrow} w, \ell_{0,b}(z) = b\Big)
\LK_{\eta}(\vert w-z\vert)\,d^{2}z\,d^{2}w,
\end{displaymath}
and
\begin{displaymath}
\E\Big[\Big\Vert
\ind_{\widetilde{\Ns}_{\varepsilon}(A)}
-\E\big[\ind_{\widetilde{\Ns}_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\leq
\int_{D^{2}}
\PP\Big(z\stackrel{D\setminus A_{0,b}}{\longleftrightarrow} w, \ell_{0,b}(z) = b\Big)
\LK_{\eta}(\vert w-z\vert)\,d^{2}z\,d^{2}w.
\end{displaymath}
Given a deterministic smooth cutoff function $f_{0}:D\rightarrow [0,1]$, compactly supported in $D$,
\begin{multline*}
\E\Big[\Big\Vert
f_{0}\ind_{\widetilde{\Ns}_{\varepsilon}(A)}
-\E\big[f_{0}\ind_{\widetilde{\Ns}_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\\
\leq
\int_{D^{2}}
\PP\Big(z\stackrel{D\setminus A_{0,b}}{\longleftrightarrow} w, \ell_{0,b}(z) = b\Big)
\LK_{\eta}(\vert w-z\vert)
f_{0}(z)f_{0}(w)\,d^{2}z\,d^{2}w.
\end{multline*}

[Theorem thm:exact-dissipation of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] For every reversible Markov chain and every centered initial condition $g_0 \perp \mathbf{1}$,
\begin{equation}
E_k - E_{k+1} = \bigl\langle g_k, (2\mathcal{G} - \mathcal{G}^2) g_k \bigr\rangle_\pi,
\qquad \forall\, k \ge 0.
\end{equation}

[Lemma lem: closeness_of_solutions_time of arXiv:2609.00257, 'Stability estimates for the initial-to-final-state inverse problem'] Let $V_j\in L^1((0, T); L^\infty(\mathbb{R}^n))$ with $n\geq 2$ be such that $\| V_j \|_{w}< \infty$ with weight $w:\mathbb{R}^n \to (0,1]$ and satisfying the smallness condition $\|  \mathop\mathrm{Im} V_j \|_{w} \leq \frac{1}{4T} $, for $j\in\{1,2,3\}$.
For $f,g\in L^2(\mathbb{R}^n)$, let $u_j, \, v_j \in C([0, T]; L^2(\mathbb{R}^n))$ be solutions of the corresponding initial and final value problems for the Schr\"odinger equation

\[
\begin{dcases}
(i\partial_t+\Delta - V_j)u_j = 0, \quad &\textup{in}\,\, \Sigma, \\
u_j(0, \centerdot) = f \in L^2(\mathbb{R}^n), &\textup{in}\,\, \mathbb{R}^n
\end{dcases} 

\quad \textup{and} \quad

\begin{dcases}
(i\partial_t+\Delta - \overline{V_j})v_j = 0, \quad &\textup{in}\,\, \Sigma, \\
v_j(T, \centerdot) = g\in L^2(\mathbb{R}^n), &\textup{in}\,\, \mathbb{R}^n.
\end{dcases} 
\]

Then, it holds that 

\begin{equation}
\|u_j - u_k \|_{L^2_w(\Sigma)} \leq 4T \| V_j - V_k \|_{w} \|u_k\|_{L^2_w(\Sigma)}
\end{equation}

and

\begin{equation}
\|v_j - v_k \|_{L^2_w(\Sigma)} \leq 4T \| V_j - V_k \|_{w} \|v_k\|_{L^2_w(\Sigma)},
\end{equation}

for every $j \neq k \in \{1, 2, 3 \}$.

