[Proposition prop:abreu-recurrence of arXiv:2608.12147, 'The Average Singular Value of a Complex Gaussian Random Matrix Strictly Decreases with Dim'] For every $N\geqslant1$,
\begin{equation}
  \Delta_{N+1}(x)-\Delta_N(x)
  =\delta_N \Bigl(L_N(x)\Bigr)^2+\widetilde\delta_NxL_N^{(1)}(x)L_{N-1}^{(1)}(x),
\end{equation}
where
\begin{equation*}
  \delta_N:=(N+1)^{-1/2}-N^{-1/2}<0,
  \qquad
  \widetilde\delta_N:=(N+1)^{-3/2}-N^{-3/2}<0.
\end{equation*}
Consequently,
\begin{equation}
  \alpha_{\mathbb C}(N+1)-\alpha_{\mathbb C}(N)=\delta_NA_N+\widetilde\delta_NB_N,
\end{equation}
where
\begin{align*}
A_N & := \int_0^\infty x^{1/2}\,\mathrm{e}^{-x}\Bigl(L_N(x)\Bigr)^2\,\mathrm d x, \\B_N & := \int_0^\infty x^{3/2}\,\mathrm{e}^{-x}L_N^{(1)}(x)L_{N-1}^{(1)}(x)\,\mathrm d x.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] For any $x\neq0$, 
	\begin{equation}
		L_t^x=-|x|+X_t(g_x)-M_t(g_x),\quad \forall t\geq 0
	\end{equation}
	holds $\mathbb P_{\delta_0}$-a.s.

