body:
[Prop 15 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $W = (W(s, t))_{(s, t) \in [0, \infty) \times [0, 1]}$ be a Brownian sheet. Assume that:
\begin{itemize}
\item $\{r_n : n \ge 1\}$ is a sequence of positive numbers with $r_n \to 0$ as $n \to \infty$.
\item $S_n : = [0, \infty)$, $\nu_n$ is a finite measure on $\cS_n: = \cB([0, \infty))$ with $\sup_{n \ge 1} \nu_n(S_n) = C_\nu \in (0, \infty)$ and satisfies
\begin{align*}
(\nu_n\otimes \nu_n)(D_n) \xrightarrow{n \to \infty} 0, \quad \trm{where } D_n : = \{(s, s') \in [0, \infty) \times [0, \infty) : |s - s'| \le r_n\}.
\end{align*}
\item The coefficients $b, \sigma$ satisfy the conditions in \cref{lem:SDE-wellposed}.
\item $x_0 \in \bR$ is fixed. 
\end{itemize}
For each $n \ge 1$ and each $s \in [0, \infty)$, we define
\begin{align*}
B^n_s(t) : = r^{-1/2}_n (W(s+ r_n, t) - W(s, t)), \quad t \in [0, 1].
\end{align*}
Then, $B^n_s = (B^n_s(t))_{t \in [0, 1]}$ is a standard Brownian motion. Let $X^n_s = (X^n_s(t))_{t \in [0, 1]}$ be a strong solution to the SDE
\begin{align}
X^n_s(t) = x_0 + \int_0^t b(u, X^n_s(u))\od u + \int_0^t \sigma(u, X^n_s(u)) \od B^n_s(u), \quad t \in [0, 1].
\end{align}
Then, there is a process $\widetilde X^n_s = (\widetilde X^n_s(t))_{t \in [0, 1]}$ such that:
\begin{itemize}
\item $\widetilde X^n_s(t) = X^n_s(t)$ for all $t \in [0, 1]$ a.s.,
\item $(\omega, s) \mapsto \widetilde X^n_s(\omega)$ is $\cF\otimes \cB([0, \infty))/\cB(\cC)$-measurable,
\end{itemize}
and for any $p \in [1, \infty)$ it holds
\begin{align}
\lim_{n \to \infty} \bE \lt\| \int_0^\infty \lt(\widetilde X^n_s - \bE \widetilde X^n_s \rt)\nu_n(\od s) \rt\|^p_\infty = 0.
\end{align}

