[Definition 17 (Conventions with variable arrays) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill
\begin{itemize}
\item Given the fluid variable array $\wavearray$ from Def.~\ref{D:ARRAYSOFWAVEVARIABLES}, we define:
\begin{align} 
	|\wavearray| 
	& \eqdef \max_{\iota \in \{0,\cdots,4\}} | \Psi_\iota|.
\end{align}
For any norm $\|\cdot\|$ on scalar functions that appears in the paper, we set:
\begin{align} 
	\| \wavearray\| 
	& \eqdef \max_{\iota \in \{0,\cdots,4\}} \| \Psi_\iota \|.
\end{align}
We use a similar convention for $\vortrenormalized$:
$|\vortrenormalized| = \max_{a = 1,2,3} |\vortrenormalized^a|$, 
and similarly for $\wavearraypartial$, $\GradEnt$, $\VortVort$,
etc. 
\item We use the following convention when taking norms of more than one variable at a time:
\begin{align} 
 \| (\vortrenormalized,\GradEnt)\| 
	& \eqdef \max\{  \| \vortrenormalized\|,  \| \GradEnt \|\}.
\end{align}
\end{itemize}

