body:
[Lemma lem.conceptual of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Let $\nu$ be a quantity defined on an open interval $I$. If $(\nu_L)_{L \in \mathbb{N}_+}$ satisfy conditions (1)(2)(3), then $\nu$ is also smooth on $I$ and the derivatives also converge
		\begin{align}
			\forall \rho \in I, \qquad \nu^{(k)}(\rho) = \lim_{L \to \infty} \nu_L^{(k)}(\rho).
		\end{align}
		\begin{enumerate}
			\item \textit{Approximation}: $\nu_L$ converges pointwisely to $\nu$ on $I$.
			\item \textit{Smoothess}: $\nu_L$ is smooth on $I$ for every $L \in \mathbb{N}_+$.
			\item \textit{Locally bounded derivatives}: for any $k \in \mathbb{N}$, the mapping $\rho \mapsto \sup_{L \in \mathbb{N}_+} \vert \nu_L^{(k)}(\rho) \vert$
			is locally uniform.
		\end{enumerate}


		Moreover, if we replace the condition (1) with a quantitative version:  
		\begin{enumerate}
			\item[(1+)] there exist two finite positive functions $C(\rho), \alpha(\rho)$ locally uniform on $\rho$ such that
			\begin{align*}
				\forall L \in \mathbb{N}_+, \qquad \vert \nu_L(\rho)  - \nu(\rho)\vert \leqslant C L^{-\alpha};
			\end{align*}
		\end{enumerate}
		then we can also improve (equation eq.conceptual of the paper): for any $\alpha' \in (0,\alpha)$ on $I$, there exists a finite positive constant $C(\rho, \alpha')$ such that  
		\begin{align}
			\forall L \in \mathbb{N}_+, \qquad \vert \nu_L^{(k)}(\rho)  - \nu^{(k)}(\rho)\vert \leqslant C'(\rho, \alpha') L^{- \alpha'}.
		\end{align}

