and for $\hash \in \{ {\sf o} ,  {\sf x}\}$,
\begin{align}
	\norm{\sigma_\hash V_{\hash}}_{\cV_j (\ell)} &= 
		\ell_{j,\varnothing} \ell_{j,\sigma}  \max\{ L^{-q (\km) j} |\lambda^{(\km)}_\hash  |  \, : \,  q (\km) \le 1 \}  \\
