\end{align}
For generic $U = u_\varnothing +  \sum_{* \in \{\varnothing,{\sf o},{\sf x}\}} \sigma_* V_* + \sigma_{\sf ox} U_{\sf ox} \in \cU$,
\begin{align}
	\norm{U}_{\cV_j (\ell)} = L^{jd} |u_\varnothing| + \sum_{* \in \{ \varnothing,{\sf o},{\sf x} \}}  \norm{\sigma_* V_*}_{\cV_j (\ell)} +  \norm{\sigma_{\sf ox} U_{\sf ox}}_{\cL_j (\ell)}   .
\end{align}

[Lemma l:one_step_improvement of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Suppose that Assumption (ass:forcing_regularity_iteration of the paper) holds. Let $\mu>0$, $r\in (1,\infty)$, $p_0\in (2,p)$, and fix $0<\gamma_0< (1-\frac{2}{p}-\frac{d}{q})\wedge (1-\frac{2}{p_0})$. 
Then there exist constants 
$$
L_0\geq 1\qquad \text{ and } \qquad \eta\in (0,1/4],
$$ 
depending only on $\mu,p,q,r,p_0,d$ and $\gamma_0$ for which the following assertion holds whenever $\delta\in (0,1]$ and $N\geq 1$ satisfy 
$$
(\delta N)^{-1}\leq L_0^{-1}.
$$
For all local solutions $(v^{N,\delta},\pi^{N,\delta},(\widetilde{\pi}^{N,\delta}_{k,\alpha})_{k,\alpha})$ to the rescaled stochastic Stokes system (equation eq:turbulent_Stokes_scaling_quantitative_iteration of the paper) on $Q$ (see Definition (def:local_solutions_NSE of the paper)), it holds that 
\begin{align}

\Big({\mathbf E} \Big\|v^{N,\delta} -\fint_{\eta B} v^{N,\delta}  \Big\|_{\underline{L}^2(\eta Q)}^{r}\Big)^{1/r}
 \leq \eta^{\gamma_0}
\mathcal{L}_{Q}^{\#},\\

\Big({\mathbf E} \Big\|\pi^{N,\delta} -\fint_{\eta B} \pi^{N,\delta}  \Big\|_{\underline{L}^2(\eta I;\underline{H}^{-1}(\eta B))}^{r}\Big)^{1/r}
 \leq \eta^{\gamma_0}
\mathcal{L}_{Q}^{\#},\\

\Big({\mathbf E} \Big\|\Big( \widetilde{\pi}_{k,\alpha}^{N,\delta} -\fint_{\eta B} \widetilde{\pi}_{k,\alpha}^{N,\delta}\Big)_{k,\alpha} \Big\|_{\underline{L}^{p_0}(\eta I;\underline{L}^2(\eta B; \ell^2))}^{r}\Big)^{1/r}
 \leq \eta^{\gamma_0}
 \mathcal{L}_{Q}^{\#},
\end{align}
where $\mathcal{L}_Q^{\#}$ denotes the sharp Lebesgue-energy of the local solution $(v^{N,\delta},\pi^{N,\delta},(\widetilde{\pi}^{N,\delta}_{k,\alpha})_{k,\alpha})$ at the (large) scale $Q$, i.e.,
\begin{align}
\nonumber
\mathcal{L}_Q^{\#}
=&\Big( \max\Big\{{\mathbf E} \|F \|_{\underline{L}^p(I;\underline{L}^q(B))}^r,\,
{\mathbf E} \|G \|_{\underline{L}^p(I;\underline{L}^q(B))}^r , \,
{\mathbf E} \Big\|v^{N,\delta} -\fint_{B} v^{N,\delta}\Big\|_{\underline{L}^2(Q)}^r
,\\

&{\mathbf E} \Big\|\pi^{N,\delta}-\fint_{B} \pi^{N,\delta}\Big\|_{\underline{L}^2(I;\underline{H}^{-1}(B))}^r,\, 
{\mathbf E} \Big\|\Big( \widetilde{\pi}_{k,\alpha}^{N,\delta}-\fint_{B} \widetilde{\pi}^{N,\delta}_{k,\alpha} \Big)_{k,\alpha}\Big\|_{\underline{L}^{p_0}(I; \underline{L}^2(B;\ell^2))}^r \Big\}\Big)^{1/r}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

