[Lemma 20 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Suppose that $0<h$, $0<x$. Then
\begin{align}
    \gamma(\sqrt{h})\log(4+ \tfrac{x}{h}+3 |\log \sqrt{h}|)\le c (1+h) \log(\max(x,2)) 
\end{align}
with an absolute constant $c>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:NMC of arXiv:2604.25851, '{Non-uniqueness of nonlinear Markov processes in the sense of McKean associated with parab'] Let $\{\mu^z_t\}_{t\geq 0, z \in \mathbb{R}^d} \subset \mathcal P$ be such that $\mu^z_0 = \delta_z$ for all $z \in \mathbb{R}^d$ and $(t,z) \mapsto \mu^z_t$ is injective from $\mathbb{R}_+\times \mathbb{R}^d$ to $ \mathcal P$. We call a family $\{P^z\}_{z\in \mathbb{R}^d} \subset \mathcal P(\mathcal C)$ a \emph{(time-homogeneous) nonlinear Markov core for $\{\mu^z_t\}_{t\geq 0, z \in \mathbb{R}^d}$}
     if
        \begin{enumerate}[label=(\roman*), font=\normalfont]
        \item  $P^z_t = \mu^z_t$ for all $(t,z)\in  \mathbb{R}_+ \times \mathbb{R}^d$;
        \item   the family $\{P^\zeta\}_{\zeta \in \mathcal{P}_0}\subset \mathcal P(\mathcal C)$, defined by $\mathcal P_0 \coloneqq \{\mu^z_t\}_{t\geq 0, z \in \mathbb{R}^d}$ and 
        \begin{equation}
            P^{\zeta} \coloneqq P^z \circ \Pi_t^{-1} \quad \text{for } \zeta = \mu^z_t,
        \end{equation}
     is a nonlinear Markov process in the sense of (def:NL-MP of the paper). We call $\{P^\zeta\}_{\zeta \in \mathcal{P}_0}$ the nonlinear Markov process \emph{induced} by $\{P^z\}_{z\in \mathbb{R}^d}$.
    \end{enumerate}

