[Definition 66 of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Given intervals $I,J \subset \R$ and real numbers $\ubar,u \in \R$, we define:
	\begin{subequations}
		\begin{align}
			\doublenulltoritwoarg{\ubar}{u}  & \eqdef \{ (t,u,x^2,x^3) \in \R\times\R\times\T^2 \ | \ \ubar(t,u,x^2,x^3) = u\},  \\
			\outgoingcharacteristicsurfacetwoarg{u}{I} & \eqdef \bigcup_{\ubar \in I} \doublenulltoritwoarg{\ubar}{u},  \\
			\ingoingcharacteristicsurfacetwoarg{\ubar}{J} & \eqdef \bigcup_{u \in J}  \doublenulltoritwoarg{\ubar}{u},   \\
			\characteristicdiamondtwoarg{I}{J} & \eqdef \bigcup_{\ubar \in I} \ingoingcharacteristicsurfacetwoarg{\ubar}{J} = \bigcup_{u \in J} \outgoingcharacteristicsurfacetwoarg{u}{I}. 
		\end{align}
	\end{subequations}

[Thm 2 of arXiv:2609.02040, '\Large Quantum Landau Damping with Coulomb Repulsion in the Whole Space'] Let $h\in[0,1]$, $\op$ be a solution of Equation~\eqref{eq:Hartree_linear} with initial data $\op^{\init}$ a density operator. Let $f_h^\circ(t,x,v)$ be the solution of the free transport equation with initial data $f_h^\init := \Wigner{\op^\init}$ the Wigner transform of $\op^\init$, namely
		\begin{equation*}
			f_h^\circ(t,x,v) = f_h^\init(x - tv,v) \, .
		\end{equation*}
		Let $\rho_\h := \rho_\op$ and $\rho_\h^\circ$ be the corresponding densities
		\begin{equation*}
			\rho_\h(t,x) = \intd \Wigner{\op}(t,x,v) \d v\, , \qquad \rho_\h^\circ(t,x) = \intd f_h^\circ(t,x,v) \d v \, .
		\end{equation*}
		Then, one can decompose $\rho_\h$ in the following way
		\begin{equation*} 
			\rho_\h = \Gosc_{\h,+} \star_{t,x} \rho_\h^\circ + \Gosc_{\h,-} \star_{t,x} \rho_\h^\circ + \Gr_\h \star_{t,x} \rho_\h^\circ ,
		\end{equation*}
		where $\Gosc_{\h,\pm}$, the oscillatory Green functions, are defined by their Fourier transforms
		\begin{equation*}
			\hatGosc_{\h,\pm}(t,k) = a_{\h,\pm}(k)\, e^{\lambda_{\h,\pm}(k) \,t}
		\end{equation*}
		with, $a_{\h,\pm}(k) = 0$ if $\n{k} \ge 1$, $\lambda_{\h,-}(k) = \bar \lambda_{\h,+}(k)$, $a_{\h,-}(k) = \bar a_{\h,+}(k)$, and uniformly in $\h$, as $k \to 0$,
		\begin{align*}
			a_{\h,\pm}(k) &= \pm \frac{i}{2} + O(\n{k}^2) \, ,
			\\
			\im \lambda_{\h,\pm}(k) &= \pm 1 \mp \n{k}^2 + O(\n{k}^4) \, ,

			\\
			\re \lambda_{\h,\pm}(k) &\sim - \frac{2 \pi}{\n{k}^2} \int_{\mathbb{R}^2} \partial_{v_1} \mu\!\lt( \n{k}^{-1},v_2,v_3 \rt) \d v_2 \d v_3 \, ,
		\end{align*}
		and where, uniformly in $\h$,
		\begin{equation*} 
			\n{\hatGr_\h(t,k)} \lesssim {|k|^3 \over \langle k \rangle^4} e^{- \sigma \n{k} t} 
		\end{equation*}
		for some $\sigma > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 119 (Cubic resonant products) of arXiv:2607.10813, '2607.10813'] Fix $T<\infty$, $a\in\mathfrak C$, $\chi\in C_c^\infty(\R^3)$,
$\kappa>0$, and $2\le p<\infty$.  Let an admissible spectral family tend to
the identity along an arbitrary admissible cofinal sequence.  For every
$(\epsilon_{\mathrm P},\epsilon_{\mathrm O})\in\{0,1\}^2$ and every finite
cutoff has the colored Wick decomposition
\begin{equation}
  \Gamma_{a,\Lambda}^{\epsilon_{\mathrm P},\epsilon_{\mathrm O}}
  =\Gamma_{a,\Lambda}^{(3),\epsilon_{\mathrm P},\epsilon_{\mathrm O}}
   +\Gamma_{a,\Lambda}^{(1),\epsilon_{\mathrm P},\epsilon_{\mathrm O}},
\end{equation}
where the first term is a centered third homogeneous chaos and the second is
a centered first chaos of color $a^\perp$.  The limits below are independent
of the cutoff family, the cofinal sequence, and the two projection flags.  On
suppressing the flags, one has
\begin{align}
  \chi\Gamma_{a,\Lambda}^{(3)}
  &\longrightarrow \chi\Gamma_a^{(3)}
  &&\text{in }L^p\!\left(\Omega;
  C_T\cC^{-\beta_{\Gamma,a}-\kappa}
  \cap L_T^\infty B_{2,\infty}^{-\beta_{\Gamma,a}-\kappa}\right),
  \\
  \chi\Gamma_{a,\Lambda}^{(1)}
  &\longrightarrow \chi\Gamma_a^{(1)}
  &&\text{in }L^p\!\left(\Omega;
  C_T\cC^{\frac12-\beta_{\Gamma,a}-\kappa}
  \cap L_T^\infty B_{2,\infty}^{\frac12-\beta_{\Gamma,a}-\kappa}\right).

\end{align}
Consequently
\begin{equation}
  \Gamma_a=\Gamma_a^{(3)}+\Gamma_a^{(1)}
  \in C_T\cC_{\loc}^{-\beta_{\Gamma,a}-}
  \cap L_T^\infty B_{2,\infty,\loc}^{-\beta_{\Gamma,a}-}.
\end{equation}
Along a fixed-profile dyadic family, all four projection conventions converge
almost surely, along the complete dyadic sequence, on a common
probability-one event obtained by intersecting the event from
\cref{thm:first-picard-fullspace} with the probability-one events supplied by
the third-chaos and first-chaos cubic tail estimates below.

For every exponent quadruple in \eqref{eq:parameter-window}, the total symbol
satisfies the source bounds
\begin{equation}
  \Gamma_a\in
  L_T^1H_{\loc}^{s_2-1}
  \cap L_T^1B_{2,\infty,\loc}^{\sigma-1}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

