[Lemma lem-LowerBound of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix  $\delta\in(0,1)$ and $\rho_1,\rho_2\in[0,\infty)$. Then, for any $M,L,K,T,\mathfrak r\in(0,\infty)$, there are constants $c_M\in(0,1)$ satisfying $ \lim_{M\to\infty}c_M=1$ and  $C_{M,L,K,T}\in(0,\infty)$ (depending only on $M$ respectively only on $M,L,K,T$) such that, for any $N,R\in\mathbb{N}$ such that $R>M$, and for any $\psi\in{\mathcal M }_1({\mathcal T }_W)$ (possibly depending on $N$) such that the following conditional expectation is well-defined,
\begin{equation}
\begin{aligned}
\widehat Z_{N,R,\delta}^{{{\scriptscriptstyle{({\rm bc}})}}}&(\Lambda_N,\rho_1,\rho_2)
\geq
{\operatorname e }^{-\frac 1R{C_{M,L,K,T}}|\Lambda_N |} {\operatorname e }^{-o(|\Lambda_N|)}c_{M}^{|\Lambda_N|}\big[\Pi_W^{{{\scriptscriptstyle{({\mathcal L }})}}}({\tt Q})(A^{{{\scriptscriptstyle{({\mathcal L }})}}}_{W;M,L,K})\big]^{|\Lambda_N'|/|W|}{\operatorname e }^{\frac{|\Lambda_N'|}{|W|}\langle \log p_{W;M,\mathfrak r,T},\psi\rangle }\\
&\quad \times
{{\tt Q}}_{M}^{{{\scriptscriptstyle{({\Lambda_N',\rm par}})}}}\big(\partial \Xi_{N,R}^{\ssup {\circ,\omega,{\mathcal S }}}=\psi \big) \\
&\quad \times
{{\tt Q}}^{\ssup{\Lambda_N',{\rm par}}}_{W;\Theta}\Big[\exp\Big\{-|\Lambda_N'|\big\langle \Xi_{N,R}^{\ssup{\circ,\omega_{\rm P}}},\smfrac 1{|W|}F_{W,W}\big\rangle\Big\}\\
&\quad\quad\times \1\Big\{\langle\Xi_{N,R}^{\ssup{\circ,\omega_{\rm P}}},\smfrac 1{|W|}{\mathfrak N}^{\ssup{\ell,{\mathcal L }}}_W\rangle \in {\mathcal B}_{\delta/3}(\rho_1)\Big\}
\1\Big\{\langle \psi,\smfrac 1{|W|}{\mathfrak N}^{\ssup{\ell,{\mathcal S }}}_{\partial W}\rangle \in {\mathcal B}_{\delta/3}(\rho_2)\Big\}
\Big|\partial \Xi_{N,R}^{\ssup {\circ,\omega,{\mathcal S }}}=\psi\Big] .
\end{aligned}
\end{equation}

[Lemma lm013103-26aa of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] We have
    \begin{equation}

              {\mathcal
