[Lemma lem: Upsilon descent of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For a binary tree $\rho\in{\mathcal T}_{b}^{I_{k-1}}$, a tree $\tau_k\in{\mathcal T}$ and $e\circ\CA$, $e\circ{\mathcal A}'$ as in (equation eq:e(A) of the paper), (equation Eq: A' of the paper) respectively, we have
		\begin{align}
			&\int_{[0,1]_\geq^k}\left[ e(\mathcal{A}(\rho))(\mathbf{t}_{k-1}) \, \Upsilon_{\tau_{k}}(z_1)-
			\sum_{\ell=1}^{m_L(\rho)+1} (-1)^{\un{(\ell>1)}}\sum_{\boldsymbol{j}_\ell\in\{0,\ldots,k-1\}^\ell_<}J_{\rho,\ell}(\,\boldsymbol{j}_\ell)\, \Upsilon_{G\left(\bullet_{k}\to_\ell\rho\right)}(u_{j_1})\right]\, {\mathrm d}\mathbf{t}_{k-1}\nonumber
			\\& = \sum_{\ell=1}^{m_L(\rho)+1} (-1)^{\un{(\ell>1)}} \int_{[0,1]_\geq^{k+1}}e(\mathcal{A}'(\bullet_{k}\to_\ell\rho))(\mathbf{t}_k)\cdot z^{[1]}\, {\mathrm d} \mathbf{t}_k\,.

		\end{align}

