[Lem 11 of arXiv:2604.06122, 'REM universality for linear random energy'] If $h\in \mathfrak{L}^{\e}_n$ and $\lambda>0$, then
\been{

 \frac{4}{n^6\e^4}\(\Gamma_n(h)+M_n(h,\lambda)-\lambda M'_n(h,\lambda)\)^2\leq 2\pi M''_n(h,\lambda)\leq n^{3/2}.
}
and
\been{

  |M''_n(h,\lambda)-M''_n(h,\lambda')|\leq 2\(\sum^n_{i=1}|h^3_i|\)|\lambda-\lambda'|
}

