[Lemma bound_on_tail of arXiv:2411.07878, 'Bernstein-type and Bennett-type inequalities for unbounded matrix martingales'] Let $X_1, \dots, X_n$ be non-negative random variables adapted to a filtration $(\mathscr{F}_i)^n_{i=1}$, $\alpha > 0$, and $U_i \coloneqq \norm*{X_i \bigm| \mathscr{F}_{i-1}}_{\psi_{\alpha}} \in [0, \infty]$.
    Fix $U \ge K > 0$ and set
    \[
    E_n \coloneqq \lrc{\sum^n_{i=1} U^2_i \le U^2,~\max_{i\in [n]} U_i \le K }.
    \]
    Then for any $\tau \ge K$
    \begin{equation}

        \mathbb{P}\left( \{\max_{i \in [n]} X_i \ge \tau\} \cap E_n \right) \le 2 \lr{\frac{4}{\alpha e}}^{\frac{2}{\alpha}}
        \frac{U^2}{\tau^2} e^{-\frac{1}{2} \lr{\frac{\tau}{K}}^{\alpha} }.
    \end{equation}
    Moreover, if 
    \begin{equation*}

        \tau \ge K \left(2 \mathrm{x} + 4 \ln\lr{\frac{2 U}{K}} + \frac{4}{\alpha} \ln \lr{\frac{4}{\alpha e}} \right)^{1/\alpha} ,
    \end{equation*}
    then
    \begin{equation}

        \mathbb{P}\lr{\{\max_{i\in [n]} X_i \ge \tau\} \cap E_n} \le e^{-\mathrm{x}}.
    \end{equation}

[Proposition thm:mvsde-attractor of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Suppose Assumption (asp:potential of the paper) holds.
Let $P_t^*:\mathcal P_2(\mathbb R)\to\mathcal P_2(\mathbb R)$ be the semigroup of the McKean-Vlasov SDE (equation eq:mvsystem of the paper). Then for any $t>0$, $P_t^*$ is a compact map.
Moreover, there exists a nonempty set $K\subset \mathcal P_{\8}(\mathbb R)$ such that
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item $K$ is a connected compact set in $\mathcal P_2(\mathbb R)$;
\item $P_t^*K\subset K$ for all $t\geq 2$;
\item $K$ is order bounded in $\mathcal P_2(\mathbb R)$, i.e., there exist $\underline{\mu},\overline{\mu}\in\mathcal P_2(\mathbb R)$ such that $\underline{\mu}\leq_{\mathrm{st}}K\leq_{\mathrm{st}}\overline{\mu}$;
\item $K$ absorbs all bounded sets in $\mathcal P_2(\mathbb R)$, i.e., for any bounded set $B\subset \mathcal P_2(\mathbb R)$, there exists $T>0$ such that $P_t^*B\subset K$ for all $t\geq T$.
\end{enumerate}

