[Lem See Proposition $9.2$ in \cite{R.T1986} of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] For $n=2$, if $u,~\upsilon,~w \in V$, then
		\begin{align*}
			|b(u,\upsilon,w)|\leq k\|u\|_{L^2}^{\frac{1}{2}}\|\nabla u\|_{L^2}^{\frac{1}{2}}\|\nabla \upsilon\|_{L^2}\|w\|_{L^2}^{\frac{1}{2}}\|\nabla w\|_{L^2}^{\frac{1}{2}}, 
		\end{align*}
		and if $u \in V$, $\upsilon \in D(A)$, and $w \in H$,then
		\begin{align*}
			|b(u,\upsilon,w)|\leq k\|u\|_{L^2}^{\frac{1}{2}}\|\nabla u\|_{L^2}^{\frac{1}{2}}\|\nabla \upsilon\|_{L^2}^{\frac{1}{2}}\|\Delta \upsilon\|_{L^2}^{\frac{1}{2}}\|w\|_{L^2}.
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 11 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] For any $t_0 >-\infty$, we define $\sC_{t_0}$ as the space $C(\R;H) \cap  \{ \cap_{N \geq 1} L^2([t_0,N];V) \}$ equipped with the following distance
    \begin{equation*}
         d_{t_0} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 \wedge \int_{-N \vee t_0}^N  \| X_s -Y_s \|_{V}^2 \, \d s}{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{t_0} $.


    The space $\sC_{+\infty}$ is defined as $C(\R;H)$ equipped with the metric
    \begin{equation*}
         d_{+\infty} (X,Y) := \Big(  \sum_{N=1}^{+\infty} \frac{ 1 \wedge \sup_{s\in [-N,N] } \| X_s -Y_s \|_{H}^2 }{2^{N}} \Big)^{1/2},
    \end{equation*}
    for all $X,Y \in \sC_{+\infty} $. For any $t_0 \in [ -\infty, +\infty]$ and $p \geq 1$, we define $L^{p}(\Omega,\sC_{t_0})$ as the space of all random functions lie on $\sC_{t_0}$ with the metric $ |\E |d_{t_0} (\cdot,\cdot)|^{p}|^{1/p} $.

[Lemma lem-distboundshred of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix $R\in(0,\infty)$ and $W=W_R=[-R,R]^d$ and $M\in(0,R)$.  Assume that $\Lambda$ is a large centred box.

\begin{enumerate}
\item Fix $m\in\mathbb{N}$ and $l_1,l_2,\dots,l_m\in\mathbb{N}$ such that $\sum_{j=1}^m l_j=k$. Fix $w_1,\dots,w_m\in W$ and $z_1,\dots,z_m\in Z_{N,R}$ such that $z_j\not=z_{j-1}$ for any $j$, where $z_0=z_m$. Then
\begin{equation}
\begin{aligned}
\widehat \mathbb{P}^{\ssup{k,\Lambda,{\rm bc}}}&\Big(\mathfrak  m(B)=m,\forall j=1,\dots,m \colon \tau_{j}-\tau_{j-1}=l_j, B_{l_j \beta}\in {\rm d} ( z_j+w_j)\Big)\\
&=\bigotimes_{j=1}^m p_{z_{j-1}+w_{j-1}}^{\ssup{W,\Lambda,{\rm bc}}}(l_i,z_j+w_j)\,{\rm d} w_j, \qquad z_0=z_m, w_0=w_m.
\end{aligned}
\end{equation}
Furthermore, under  conditioning on the event 
\begin{equation}
A_{m}\big((l_j,w_j)_{j\in[m]}\big)=\{\mathfrak m_R(B)=m,\forall j=1,\dots,m \colon \tau_{j+1}-\tau_j=l_j, B_{l_j \beta}=  z_j+w_j\},
\end{equation}
the shreds $(B_{s +\tau_j\beta})_{s\in [0,l_j\beta]}$ are independent over $j\in\{1,\dots,m \}$ and have distribution $q^\ssup{l_j,W,\Lambda,{\rm bc}}_{ z_{j-1}+w_{j-1}, z_j+w_j}$.

\item For ${\rm  bc}={\rm par}$ and $\widehat \mathbb{P}^{\ssup{k,\Lambda,{\rm par}}}$ restricted to all the legs of $B$ lying in ${\mathcal C }_1^{{{\scriptscriptstyle{({M}})}}}$, we can replace $p^{\ssup{W,\Lambda,{\rm par}}}$ by $p^{{{\scriptscriptstyle{({W,M}})}}}$ and $q^\ssup{l_j,W,\Lambda,{\rm par}}$ by $q^{{{\scriptscriptstyle{({l_j,W,M}})}}}$ in these two statements.

\item For any $z\in Z_{N,R}^\circ$ such that all legs start start in $W_z$ have spread $< M$ and for any $j$ satisfying $z_{j-1}=z$, we may replace $p_{ z_{j-1}+w_{j-1}}^{\ssup{W,\Lambda,{\rm per}}}$ by $p_{ z_{j-1}+w_{j-1}}^{{{\scriptscriptstyle{({W,M}})}}}$ and $q^\ssup{l_j,W,\Lambda,{\rm per}}_{ z_{j-1}+w_{j-1}, z_j+w_j}$ by $q^{{\scriptscriptstyle{({l_j,W,M}})}}_{ z_{j-1}+w_{j-1}, z_j+w_j}$ in these statements.
\end{enumerate}

