[Theorem thm:mixing time equivalence within QP,PQ,QPQ of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $P\in \mathcal{S}(\pi)$, $G$ be a finite group acting on $\mathcal{X}$, and assume that $\pi$ is $G$-invariant. For any $1\leq p\leq \infty$ and $\varepsilon>0$, we have
    \begin{align}
        t_{\mathrm{mix},p}((P_{la})_{ra}, 2\varepsilon)&\leq t_{\mathrm{mix},p}(P_{la}, \varepsilon)\leq t_{\mathrm{mix},p}\left((P_{la})_{ra}, \frac{\varepsilon}{2}\right)+1,\\
        t_{\mathrm{mix},p}((P_{la})_{ra}, 2\varepsilon)&\leq t_{\mathrm{mix},p}(P_{ra}, \varepsilon)\leq t_{\mathrm{mix},p}\left((P_{la})_{ra}, \frac{\varepsilon}{2}\right)+1.
    \end{align}

