\[	
\Q^{(k),\bm \theta}_{T,r}\paren{\chi_\emptyset>t}=\frac{\E_r\left[N^{\floor{k}}_{T-t}e^{-\bm \theta\cdot \bo Z_{T-t}}\right]}{\E_r\left[N^{\floor{k}}_{T}e^{-\bm \theta\cdot \bo Z_{T}}\right]}e^{-\alpha_rt}
\]and 
