& \Q^{(k),\bm \theta}_{T,r}\left(c(\varsigma_t^{(1)})=i,\tau_1>t\right)

 = \frac{\E_i\left[N^{\floor{k}}_{T-t}e^{-\bm \theta\cdot \bo Z_{T-t}}\right]}{\E_r\left[N^{\floor{k}}_{T}e^{-\bm \theta\cdot \bo Z_{T}}\right]}\frac{\E_r\left[Z^{(i)}_{t}\prod_{j\in [d]}\E_j\left[e^{-\bm \theta\cdot \bo Z_{T-t}}\right]^{Z^{(j)}_{t}}\right]}{\E_i\left[e^{-\bm \theta\cdot \bo Z_{T-t}}\right]}.
\end{align*}

