[Prop leading of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For $L>0$, define the constant (which is the same as (equation eq:cKdef of the paper))
\begin{equation} 
    \mathsf{Z}_L= \left(\frac{\ell+ a- b+\sqrt{D}} {\ell+ a- b -\sqrt{D}}  \right)^{\lceil aL \rceil} 
    \left(\frac{\ell -a +b+\sqrt{D}} {\ell - a + b -\sqrt{D}}  \right)^{\lceil bL \rceil} 
    e^{- \sqrt{D} L}. 
\end{equation}
As $L\to \infty$, the following hold:
\begin{equation*}  \begin{split}
    &\mathrm I^{(123)}_{123} 
    = - \frac{\sqrt{ab}\mathsf{Z}_L}{2\pi  LD }  \mathbb{P} \left[ \mathsf{c}_{+} \mathbb{B}^{\mathrm{br}}\left(\frac{\mathrm m y_i- x_i}{\mathrm m -1} \right) > \mathrm r_i,  i=1,2 \right] (1+o(1)) \qquad  \text{for $\mathsf{q} \in \mathsf{R}_1 \cup \cdots \cup \mathsf{R}_5$,}\\
    & \mathrm I^{(123)}_{(12)3} 
    = - \frac{\sqrt{ab}\mathsf{Z}_L}{2\pi  LD} \mathbb{P} \left[\mathsf{c}_{+} \mathbb{B}^{\mathrm{br}}\left(\frac{\mathrm m y_2- x_2}{\mathrm m -1} \right) > \mathrm r_2  \right] (1+o(1)) \qquad \text{for $\mathsf{q} \in \mathsf{R}_6 \cup \mathsf{R}_7$,}\\
    &\mathrm I^{(123)2}_{(23)(12)} 
    = - \frac{\sqrt{ab}\mathsf{Z}_L}{2\pi  LD}
    \mathbb{P} \left[ \mathsf{c}_{+} \mathbb{B}^{\mathrm{br}}\left(\frac{\mathrm m y_1- x_1}{\mathrm m -1} \right) \le \mathrm r_1, \, \mathsf{c}_{+} \mathbb{B}^{\mathrm{br}}\left(\frac{\mathrm m y_2- x_2}{\mathrm m -1} \right) > \mathrm r_2 \right]
    (1+o(1)) \quad \text{for $\mathsf{q} \in \mathsf{R}_6 \cup \mathsf{R}_7$.}
\end{split} \end{equation*}

