[Lemma eq:loc_contbd of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Let $g^* = \max\{g_-,g_+,0\}$. Fix $m,n,j,\ell\in \mathbb{N}$ with $M_m \leq j \leq \ell \leq N_n-1$. There exists $m_0 = m_0(\omega) \in \mathbb{N}$ such that if $m \geq m_0$ and $0 \leq s \leq t < \infty$,
\begin{equation} 
\begin{split}
L_{(j,j+1)}^{[m,n]}(t) - L_{(j,j+1)}^{[m,n]}(s) & \leq \frac{q^{-1}(g^* - g_*)(t - s)}{1-r} + \frac{q^{-1}(L_{(\ell,\ell+1)}^0(t) - L_{(\ell,\ell+1)}^0(s))}{1 - r} \\
& \quad + q^{-1}\sum_{k = -\infty}^j r^{j - k}(B_k(t) - B_k(s) - \mathcal{B}^-_{\ell - k + 1}(k,[s,t])).
\end{split}
\end{equation}

[Proposition 11 (Entropy inequality and \(L^1\) bound) of arXiv:2608.29726, '\LARGE A Priori Estimates for Singular Fractional Stochastic Burgers Equations'] There exists \(c_\Psi>0\), depending only on \(\gamma\) and the uniform
Jacobian and bi-Lipschitz bounds of \(\Psi\), such that every smooth solution
satisfies
\begin{equation}
  \begin{aligned}
  N'(t)
  +c_\Psi\norm{\chi'(m(t))}_{\dot H^{\gamma/2}}^2
  \lesssim_\Psi{}&\norm{a(t)}_{\dot H^{1-\gamma/2}}^2
  +\norm{Q_0(t)}_{H^{1-\gamma/2}}^2\\
  &+\norm{R(t)}_{H^{1-\gamma/2}}^2
  +\lambda\norm{J(t)-1}_{L^1}.
  \end{aligned}
\end{equation}
Consequently, if the quantities on the right are integrable on \((0,T)\),
define
\begin{equation}
  \begin{aligned}
  N_T:={}&N(0)
  +\norm{a}_{L^2(0,T;\dot H^{1-\gamma/2})}^2
  +\norm{Q_0}_{L^2(0,T;H^{1-\gamma/2})}^2\\
  &+\norm{R}_{L^2(0,T;H^{1-\gamma/2})}^2
  +\lambda\norm{J-1}_{L^1(0,T;L^1)}.
  \end{aligned}
\end{equation}
Then
\begin{equation}
  \sup_{t\le T}\norm{m(t)}_{L^1}
  \le\sup_{t\le T}N(t)
  \lesssim_\Psi N_T<\infty.
\end{equation}
This bound depends on the initial data and the displayed coefficient norms,
but not on the \(L^2\)-energy of \(m\).

