[Definition 15 of arXiv:2609.02197, '2609.02197'] Let $\left(\alpha,\gamma,r\right)\in \mathbb{R}\times \left[1,+\infty\right[^2,$
\begin{align*} 
\left\Vert\cdot\right\Vert_{\mathscr{C}^\alpha}: \mathscr{S}' &\longrightarrow \overline{\mathbb{R}}_+ \\ f & \longmapsto \left\Vert f\right\Vert_{\mathscr{C}^\alpha}=\sup_{q \in \mathbb{N}}2^{\alpha\left(q-1\right)}\Vert \delta_{q-1}f\Vert_{L^{\infty}\left(\mathbb{T}^d\right)}
\end{align*}
and
\begin{align*} 
\left\Vert\cdot\right\Vert_{B^{\alpha}_{r,\gamma}}: \mathscr{S}' &\longrightarrow \overline{\mathbb{R}}_+ \\ f & \longmapsto \left\Vert f\right\Vert_{B^{\alpha}_{r,\gamma}}=\left(\sum_{q \in \mathbb{N}}2^{\alpha\gamma\left(q-1\right)}\left\Vert \delta_{q-1} f\right\Vert_{L^r\left(\mathbb{T}^d\right)}^\gamma\right)^{\frac{1}{\gamma}}
\end{align*}
We define $$\text{\gls{pc3}}:=\left\{f \in \mathscr{S}',\left\Vert f\right\Vert_{B_{r,\gamma}^\alpha}<+\infty\right\}$$ and $$\text{\gls{pc4}}:=\left\{f \in \mathscr{S}',\lim_{q\to+\infty}2^{\alpha q}\left\Vert\delta_q f\right\Vert_{L^{\infty}\left(\mathbb{T}^d\right)}=0\right\}.$$
The Banach spaces $\left(B^\alpha_{r,\gamma},\left\Vert\cdot\right\Vert_{B^\alpha_{r,\gamma}}\right)$ and $\left(\mathscr{C}^\alpha,\left\Vert\cdot\right\Vert_{\mathscr{C}^\alpha}\right)$ are called Besov spaces.

[Corollary 153 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Suppose that $a,b$ are smooth and bounded and let
$(\sft_{s},x_{s})$ be the corresponding Markov
diffusion process.  Suppose that
\begin{equation}

N_{1} \hat b_{q\beta,p\beta,1}< \sfb_{0}
\end{equation}

Then 
$ \bar b_{1 }\leq \sfb_{0}$ and all results
from Chapter \ref{chapter 10.20.1}
after Theorem \ref{theorem 8.2.1} are applicable
(with $\rho_{b}=1$). In particular, by Corollary
\ref{corollary 10.26.1}
for any $n>0$, $r,s\geq0$, and
$(t,x)$  we have
\begin{equation}

E_{t,x}\sup_{\tau\in[0,r]}|x_{s+\tau}-x_{s}|^{ n}
\leq N(  r ^{ n/2}+ r ^{ n}),
\end{equation}
where $N=N(n,  \sfp_{0}(d,\delta))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 9 of arXiv:2608.30658, 'Higher Regularity of Time-Periodic Solutions to Nonautonomous Hyperbolic Problems: Away fr'] Let $l\ge 1$ be arbitrary fixed integer.
	Assume that all conditions excepting \reff{nonrez} of Theorem \ref{thm:lin} are satisfied.
	Moreover, let $W=(w_{jk})$ be a  constant zero-one $n\times n$-matrix and   $r_{jk}(t)=\tilde r_{jk}(t)w_{jk}$,
	where $\tilde r_{jk}\in C_{per}^l$ for all $j,k\le n$. Assume that   the matrix $W$ fulfills one of the
	following  equivalent conditions:

	$(\io)$ the products $w_{i_1i_2}w_{i_2i_3}\cdots w_{i_{n}i_{n+1}}$  equal  zero for all tuples
	$\left(i_1,\dots,i_{n+1}\right)\in\left\{1,\dots,n\right\}^{n+1}$;

	$(\io\io)$ all principal minors of  the matrix $W$ equal zero;

$(\io\io\io)$ the matrix $W$ is nilpotent, with
	$W^n=0$;

	$(\io v)$ $W$ is the adjacency matrix of a directed acyclic graph.

Then	any continuous  solution to the problem (\ref{lin})--\reff{per} 
	belongs to~$C_{per}^l(\Pi;\R^n)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

