[Proposition 19 of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] Denote
      $\kappa(\gamma,r)=1+1/r-(1-d)(1+\gamma)$.
       \begin{enumerate}[label=(\roman*)]
         \item
      There exists a pair of unique minimizers $(\gamma_0,r_0)$ of $\kappa(\gamma,r)$ over the compact domain
      \begin{align*}
        0
         \ \le \
         \gamma
         \ \le \
  \min \left\{
  \frac{d}{1-d}
  \,,
         1
          -
         \frac{1}{r(1-d)}
         \,,
         \frac{\alpha}{r}
          -
         1
  \right\}
           \qquad\text{and}\qquad
         \frac{1}{1-d}
         \ \le \
         r
         \ \le \
         \alpha
         \,,
      \end{align*}
       namely
       \begin{align*}
 \gamma_0
   :=
  \begin{cases}
    \frac{d}{1-d}
    &
    \ \text{if}\
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\
    \frac{\alpha(1-d)-1}{\alpha(1-d)+1}
    &
    \
    \text{else,}
  \end{cases}
  \
  r_0
   :=
  \begin{cases}
    \alpha(1-d)
    &
    \ \text{if}\
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\
    \frac{1}{2}
    \left(
    \frac{1}{1-d}
    \ + \ \alpha
    \right)
    &
    \
    \text{else,}
  \end{cases}
  \end{align*}
  yielding
  \begin{align*}
  \kappa_0
    \ = \
    \kappa(\gamma_0,r_0)
  \ = \
  \left\{ \begin{array}{l}
    \frac{1}{\alpha(1-d)}
    \ \text{ if } \
    \frac{1}{(1-d)(1-2d)}
    < \alpha\,,\\[10pt]
    \frac{2(1-d) + (1-\alpha(1-d)(1-2d))}{\alpha(1-d)+1} = d
    \ + \
    (1-d)
    \frac{3-\alpha(1-d)}{\alpha(1-d)+1}
    \ \text{ else.}
  \end{array} \right.
\end{align*}
\item
It holds
\begin{align*}
  \gamma_0
  \ = \
  \min \left\{
  \frac{d}{1-d}
  \,,
         1
          -
         \frac{1}{r_0(1-d)}
         \,,
         \frac{\alpha}{r_0}
          -
         1
  \right\}
  \,,\quad
  r_0
  \in
  \left(
  \frac{1}{1-d}
  \,,
  \alpha
  \right)
  \,,
  \end{align*}
  and
  \begin{align*}
  \kappa_0
  \ - \ (d+1/\alpha)
  \ < \
  0
  \,.
\end{align*}
\end{enumerate}

[Lemma 4 of arXiv:2606.14038, 'Trivariate Hypergeometric Series Formulas\\ for Pure Partition Functions of Multiple $3$-S'] \begin{itemize}
  \item [(i)]   For any sequence $(a_m)_{m=0}^\infty$, there is a unique $A\in \R^{\N_0^2}$ that satisfies the
two-dimensional analogue of (\ref{Ljk=}) for all  $j,k\in [2]$, and  $A_{m e_1}=a_m$ for all $m\in\N_0$. Moreover, such $A$ is symmetric, and each $A_{\u n}$ is a linear combination of the $a_m$'s. In other words, there are $C_{\u n}^{(m)}\in\R$, $\u n\in\N_0^2$, $m\in\N_0$, depending only on $\beta$ such that, for each $\u n\in\N_0^2$, there are only finitely many $m$ such that $C_{\u n}^{(m)}\ne 0$, and $A_{\u n}=\sum_{m=0}^\infty C_{\u n}^{(m)} a_m$.
  \item [(ii)] The above statement holds with $ {\N_0^3}$ and $[3]$ in place of $ {\N_0^2}$ and $[2]$, respectively.
\end{itemize}

[Lemma 16 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] We have the following convergence as $m \to \infty$:

\begin{equation}
S_{\text{{\tiny $3,\!\delta$}}}(\tilde{v}_m) \longrightarrow S_{\text{{\tiny $3,\!\delta$}}}(\tilde{v}) \quad \text{in} \quad \left(C([0,T]\,;L^2(\Omega))\right)^2 
\quad \text{and} \quad \left(L^2(0,T\,;H^1(\Omega))\right)^2
\end{equation}

whenever a sequence $\{\tilde{v}_m\}_{m \in \mathbb{N}} \subset \mathcal{V}(v_0)$ and a function $\tilde{v} \in \mathcal{V}(v_0)$ satisfy 

\begin{equation}
\tilde{v}_m \longrightarrow \tilde{v} \quad \text{in} \quad C([0,T]\,;L^2(\Omega)) \quad \text{as} \quad m \to \infty.
\end{equation}

[Lem 24 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] There exists $c_{u}=c_{u}(d,m)>0$ such that for any $\Ga \in (0,1]$, $R\geq 2\sqrt{d}$, for all $k$ with $(k,n)\in \mathcal{G}$, 
\begin{equation*}
U(k)\leq c_{u}{R^d \,\Gamma \over |\x|^{d+1/m}}\quad\text{and}\quad 
 \duration(\x) \,U^m(\x) \le c.
 \end{equation*}

