[Theorem thm:general of arXiv:2607.06249, 'Extreme least singular values of Gaussian row submatrices and a phase retrieval stability '] Let $\mathbb{F}\in\{\mathbb{R},\mathbb{C}\}$ and $d_\mathbb{F}=\dim_\mathbb{R}\mathbb{F}$. Let $A_m\in\mathbb{F}^{N_m\times m}$ have independent standard
Gaussian entries, and assume $N_m/m\to\gamma>1$. Put
\begin{equation}
  h(\gamma)=\gamma\log\gamma-(\gamma-1)\log(\gamma-1),
  \qquad c_\gamma=e^{h(\gamma)}=\frac{\gamma^\gamma}{(\gamma-1)^{\gamma-1}}.
\end{equation}
Then
\begin{equation}
  \frac{1}{m}\log M_m^\mathbb{F}(A_m) \xrightarrow{P} -\frac{h(\gamma)}{d_\mathbb{F}}.
\end{equation}
Equivalently,
\begin{equation}
  M_m^\mathbb{F}(A_m)=c_\gamma^{-m/d_\mathbb{F}+o_P(m)}.
\end{equation}
If in addition $N_m=\gamma m+O(1)$, for instance $N_m=\lfloor\gamma m\rfloor$, then for every fixed
$\varepsilon>0$,
\begin{equation}
  \mathbb{P}\left\{\left|\frac{1}{m}\log M_m^\mathbb{F}(A_m)+\frac{h(\gamma)}{d_\mathbb{F}}\right|>\varepsilon\right\}
  =O_{\gamma,\varepsilon,\mathbb{F}}(m^{-1}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 39 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\gamma \in (0,1]$ and $n \in \bbn$ be arbitrary. We denote by $C_b^{\gamma,n}([0,T] \times W, \bar{W})$ the space of all functions $f : [0,T] \times W \to \bar{W}$ such that:
\begin{enumerate}
\item We have $f(t,\cdot) \in C_b^n(W,\bar{W})$ for all $t \in [0,T]$.

\item We have $f(\cdot,y),\ldots,D_y^{n-1}f(\cdot,y) \in \calc^{\gamma}([0,T],\bar{W})$ for each $y \in W$.

\item We have
\begin{align*}
\| f \|_{C_b^{\gamma,n}} := \sup_{t \in [0,T]} \| f(t,\cdot) \|_{C_b^n} + \sum_{k=0}^{n-1} \sup_{y \in W} \| D_y^k f(\cdot,y) \|_{\gamma} < \infty.
\end{align*}
\end{enumerate}

