[Lemma 13 of arXiv:2605.17328, 'Transportation cost inequalities for mean reflection SPDEs with white noise'] {\rm (\cite[Proposition 3.4]{SZ2019})}
{\rm Let $\left\{\sigma(s,y):(s,y)\in\mathbb{R}_+\times[0,1]\right\}$ be a random field such that the stochastic integral against space time white noise is well defined. Then for any $T>0$, $0<p\leq 10$ and $\e>0$, there exists a constant $C_{T,p,\e}$ such that}
\begin{equation}
\begin{split}
&\mathbb{E}\left[\sup_{(t,x)\in[0,T]\times[0,1]}\left|\int^t_0\int^1_0G_{t-s}(x,y)\sigma(s,y)W(\mathrm{d}s,\mathrm{d}y)\right|^p\right]\\
\leq&\e\mathbb{E}\left[\sup_{(t,x)\in[0,T]\times[0,1]}\left|\sigma(s,y)\right|^p\right]
+C_{T,p,\e}\mathbb{E}\int^T_0\sup_{y\in[0,1]}\left|\sigma(s,y)\right|^p\mathrm{d}s,
\end{split}
\end{equation}
{\rm where}

\begin{align}
C_{T,p,\e}=\inf_{q>10}\frac{p}{q-p}q^{-\frac{q}{p}}\e{1-\frac{q}{p}}\left(q-p+qC_{T,q}\right)^{\frac{q}{p}}
\end{align}
{\rm with}
\begin{align*}
C_{T,q}<q^{\frac{q}{2}}T^{\frac{q}{4}-\frac{3}{2}}\left(\frac{2}{\pi}\right)^q
\left(\frac{1}{\sqrt{2\pi}}\right)^{\frac{q}{2}+1}\left(\frac{6q-8}{q-10}\right)^{\frac{3q}{2}-2}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem secular-general of arXiv:2609.01034, 'The Multiple Timescales of Gradient Descent on~the~Edge~of~Stability: A~Perturbative~Deriv'] Let $\alpha, \beta \in \mathbb{R}$ and $\gamma = \gamma(t_1) \in \mathbb{R}$ such that $\sum_{t_1=0}^{+\infty} |\gamma(t_1)| < +\infty$. The solutions $\varphi = \varphi(t_1)$ of the difference equation
        \begin{equation*}
            \Delta_{t_1} \varphi + 2 \varphi = \alpha + \beta (-1)^{t_1} + \gamma(t_1)
        \end{equation*}
        are 
        \begin{equation*}
            \varphi = \frac{\alpha}{2} + a (-1)^{t_1} - \beta t_1 (-1)^{t_1} - \sum_{s=0}^{t_1-1} (-1)^{t_1+s} \gamma(s) \, , \qquad a \in \mathbb{R} \, .
        \end{equation*} 
        In particular, there exists a bounded solution if and only if $\beta = 0$.

