[Lemma 12 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Assume the set-up and conditions of Proposition~\ref{prop:global}. Fix $p\in\N$ with $p\ge 2$, let $A\in\C^{N\times N}$  be a deterministic matrix, and consider
\begin{equation}
F:=G^kA\,\mathrm{Iso}(\bm{k}_0,\bm{\phi})\Delta(\bm{k}_1)\overline{\mathrm{Iso}(\bm{l}_0,\bm{\phi}')\Delta(\bm{l}_1)},\qquad f_j=\Delta(\bm{k}_j)\overline{\Delta(\bm{l}_j)}, \, \, j\in [2,p],

\end{equation}
with fixed $k\in \N$, $\bm{k}_j\in\N^{n_{1,j}}$, $\bm{l}_j\in \N^{n_{2,j}}$ with $n_{1,j},n_{2,j}\in\N\cup\{0\}$ and sets of index pairs $\bm{\phi},\bm{\phi}'$. Then uniformly in $z\in\mathcal{D}_g$ and $A$ with $\|A\|\lesssim 1$ it holds that    
\begin{equation}
\begin{split}
&\kappa\left(\mathrm{Tr}\left[\underline{WF}\right] ,f_2,\ldots,f_p\right) =\sum_{j=2}^p \kappa\left(\widetilde{\E}\left[\mathrm{Tr}\big[\widetilde{W}F\big]\partial_{\widetilde{W}}[f_j]\right],\{f_i\}_{i\neq j}\right)\\
&\quad -\sum_{\ell=3}^L \sum_{a,b=1}^N \sum_{\bm{\alpha}\in\{ab,ba\}^{\ell-1}}\frac{\kappa(ab,\bm{\alpha})}{(\ell-1)!N^{\ell/2}}\sum_{P_p(\bm{\alpha})}\kappa\left(\Bigg(\partial_{\bm{\alpha}_1}F_{ba} \prod_{\bm{\alpha_j}\neq\emptyset} \partial_{\bm{\alpha}_j}f_j\Bigg),\left\lbrace f_j\right\rbrace_{\bm{\alpha}_j=\emptyset}\right) + \mathcal{O}\left(N^{-D}\right),
\end{split}

\end{equation}
for any fixed $D>0$. The positive integer $L$ does not depend on $N$ and $A$, but may depend on $D$, parameters from \eqref{eq:def_Ff} and the parameters of the domain $\mathcal{D}_g$ defined in \eqref{eq:def_D_global}. In \eqref{eq:underline_exp_general}, $\widetilde{W}$ is an independent copy of $W$ and the expectation $\widetilde{\E}$ is taken with respect to $\widetilde{W}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem stochThiele of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] Let a canonical insurance model $(\alpha, \Lambda, \Phi, B, b)$ be given. 
For given stochastic processes $V^i$, $i \in \mathcal{Z}$, the two following statements are equivalent:
	\begin{itemize}
		\item[(a)]  The process  $(V^i)_{i \in \mathcal{Z}}$  satisfies  $V^i(t)= \mathbb{E}_{t}^i[L(t)]$, $t \in [0,T]${.}
		\item[(b)] The process  $(V^i)_{i \in \mathcal{Z}}$ is a solution in  $\mathcal{Y}(\Lambda)$ for the backward equation
		\begin{align} \begin{split}
				0=\mathds{1}_{\{  \Lambda^{i\raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(t-)< \infty\}} I^i(t-)  \bigg(& V^i(\mathrm{d} t)   +  B^i(\mathrm{d} t) - V^i(t-) \Phi^i (\mathrm{d} t) \\&+ \sum_{j : j\neq i}(b^{ij}(t) + V^j(t)-V^i(t)) \Lambda^{ij}(\mathrm{d} t)\bigg)
		\end{split}\end{align}
		with  terminal value $V^i(T)=0$. 
	\end{itemize}
	If for a  subset $\mathcal{Z}_0 \subset \mathcal{Z}$ we have $\Lambda^{ij}=0$ for all $i \in \mathcal{Z}_0$ and $j \not\in \mathcal{Z}_0$, then the equivalence is also true for the sub-process $(V^i)_{i  \in \mathcal{Z}_0}$ only. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2604.25769, 'The conformal dimension of the Brownian tree is one'] Let $(\SCT, d_\SCT, \SM_\SCT; o)$ be an infinite Brownian tree. Then for each $\zeta > 0$, there almost surely exists $\varepsilon_\ast \in (0, 1)$ such that 
    \begin{equation}
        \SM_\SCT(B_\varepsilon(z; d_\SCT)) \ge \varepsilon^{2 + \zeta}, \quad \forall z \in B_1(o; d_\SCT), \ \forall \varepsilon \in (0, \varepsilon_\ast]. 
    \end{equation}

[Definition def:intercondi of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] [Intertwining condition] 
    Suppose that $\mathcal{P}_t$ is a $\sigma$-KMS detailed balanced with generator $\mathcal{L}$. There exists operators $\{V_j\} = \{V_j^*\}$ such that
    \begin{align*}
        \mathcal{L} = - \sum_{j \in \mathcal{J}} \partial_j^\star \partial_j 
    \end{align*}
    where $\partial_j(\cdot) := [V_j, \cdot]$ with the adjoint
    $\partial_j^\star$ with respect to the KMS inner product. We say $\mathcal{P}_t$ satisfies the $\kappa$-intertwining condition for some $\kappa \in \mathbb{R}$ if for any $j \in \mathcal{J}$,
    \begin{equation} 
        \partial_j \mathcal{P}_t = e^{-\kappa t} \mathcal{P}_t \partial_j\,,\quad \text{equivalently, }\    \partial_j \mathcal{L} = \mathcal{L} \partial_j - \kappa \partial_j\,. 
    \end{equation}

[Proposition thm|BoundAijM of arXiv:2504.08938, 'Fourier Levels and Almost Sure Bounds on Higher-Order Derivatives in First-Passage Percola'] Assume that $a/(b-a)\in\mathbb N$.
Let $\zeta>0$. There is a constant $C$ that depends only on $\zeta$, $a$, $b$, and $p$ such that 
\begin{eqnarray}
\sum_{i,j}\left(\mathbb P(A_{\{i,j\}}^-)\right)^{1+\zeta}&\leq&C\cdot n^{2+\zeta-\zeta d}.

\end{eqnarray}

