[Lemma 27 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Assume the $H$-supralgebra $A$ is an algebra with mean value on $
		\mathbb{R}_{y}^{d}$, i.e., it is translation invariant and each of its
		elements is uniformly continuous. Let $(u_{\varepsilon })_{\varepsilon \in
			E} $ be a sequence in $L^{\Phi}(Q\times \Omega )$  which weakly
		stochastically $\Sigma $-converges towards $u_{0}\in L^{\Phi}(Q\times \Omega ;
		\mathcal{X}_{A}^{\Phi})$. Let the sequence $(v_{\varepsilon })_{\varepsilon \in
			E}$ be defined by 
		\begin{equation*}
			v_{\varepsilon }(x,\omega )=\int_{B_{r}}u_{\varepsilon }(x+\varepsilon
			_{2}\rho ,\omega )d\rho \text{\ \ }((x,\omega )\in Q\times \Omega ).
		\end{equation*}
		Then, as $E\ni \varepsilon \rightarrow 0$, 
		\begin{equation}
			v_{\varepsilon }\rightarrow v_{0}\text{ in }L^{\Phi}(Q\times \Omega )
			\text{-weak } \digamma\,\Sigma  
		\end{equation}
		where $v_{0}$ is defined by $v_{0}(x,\omega ,y)=\int_{B_{r}}u_{0}(x,\omega
		,y+\rho )d\rho $\ for $(x,\omega ,y)\in Q\times \Omega \times \mathbb{
			\mathbb{R}}^{d}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:truth-lemma-box-left of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] Let $L \supseteq \textbf{FIK}$, $x = (\Gamma_x, \Delta_x) \in W_L^*$, $\varphi \in \mathscr{L}_{\Box\Diamond}$.
  If $\Box \varphi \notin \Gamma_x$, then there are $x' = (\Gamma_x', \Delta_x') \in W_L^*$ and $y' = (\Gamma_y', \Delta_y') \in W_L^*$ such that
  $x \leq^* x' \sqsubset^* y'$ and $\varphi \notin \Gamma_y'$.
  \begin{proof}
    Let $(\Gamma_x', \Delta_x')$ be a maximal $L$-final theory such that $(\Gamma_x, \set{ \Box \varphi }) \subseteq (\Gamma_x', \Delta_x')$, which is obtained from Corollary (cor:final-theory of the paper).
    Then $x' = (\Gamma_x', \Delta_x') \in W_L^*$ and $x \leq x'$ by definition.
    Let $\Theta = \set{ \varphi \lor \psi; \psi \in \Diamond^{-1} \Delta_x' }$.
    \begin{claim*}
      $(\Box^{-1} \Gamma_x', \Theta \cup \set{ \varphi })$ is $L$-consistent.
      \begin{subproof}
        Suppose not, then there are finite $A \subseteq \Box^{-1} \Gamma_x'$ and $\psi_1, \psi_2, \ldots, \psi_n \in \Diamond^{-1} \Delta_x'$
        such that $L \vdash \bigwedge A \to \left(\bigvee_{1 \le i \le n} (\varphi \lor \psi_i)\right) \lor \varphi$, then:
        \begin{center}
          \AxiomC{$L \vdash \bigwedge A \to \left(\bigvee_{1 \le i \le n} (\varphi \lor \psi_i)\right) \lor \varphi$}
          \UnaryInfC{$L \vdash \bigwedge A \to \left( \varphi \lor \bigvee_{1 \le i \le n} \psi_i \right)$}
          \RightLabel{\scriptsize{$\textsf{M}_\Box$}}
          \UnaryInfC{$L \vdash \Box \bigwedge A \to \Box \left( \varphi \lor \bigvee_{1 \le i \le n} \psi_i \right)$}
          \RightLabel{\scriptsize{$\textsf{C}_\Box$}}
          \UnaryInfC{$L \vdash \bigwedge \Box A \to \Box \left( \varphi \lor \bigvee_{1 \le i \le n} \psi_i \right)$}
          \RightLabel{\scriptsize{$\textsf{wCD}$}}
          \UnaryInfC{$L \vdash \bigwedge \Box A \to \left(\left(\Diamond \bigvee_{1 \le i \le n} \psi_i \to \Box \varphi\right) \to \Box \varphi\right)$}
          \UnaryInfC{$L \vdash \left(\bigwedge \Box A \land \left(\Diamond \bigvee_{1 \le i \le n} \psi_i \to \Box \varphi\right)\right) \to \Box \varphi$}
          \DisplayProof
        \end{center}
        Let $\psi = \bigvee_{1 \le i \le n} \psi_i$.
        By the above, we have $\left(\Diamond \psi \to \Box \varphi\right) \notin \Gamma_x'$ by maximality and $L$-consistency.
        By Proposition (prop:truth-lemma-imp-left of the paper), this implies that
        there is $x'' = (\Gamma_x'', \Delta_x'')$ such that $x' \leq^* x''$, $\Diamond \psi \in \Gamma_x''$, and $\Box \varphi \in \Delta_x''$.
        Here, $x' \leq^* x''$ implies $\Gamma_x' \subseteq \Gamma_x''$ and $\Delta_x' \supseteq \Delta_x''$,
        so there is $\Pi$ such that $\Gamma_x' \cup \Pi = \Gamma_x''$ and $\Delta_x' = \Delta_x'' \cup \Pi$.
        But by $x'$ being $L$-final, it must be that $\Pi = \emptyset$, so $x'' = x'$, which implies $\Diamond \psi \in \Gamma_x'$.
        Then by Lemma (lem:saturation of the paper), this and $L \vdash \textsf{C}_\Diamond$ imply $\bigvee_{1 \le i \le n} \Diamond \psi_i \in \Gamma_x'$,
        so by Corollary (cor:saturation of the paper), there is at least one $1 \le k \le n$ such that $\Diamond \psi_k \in \Gamma_x'$.
        This is a contradiction since $\Diamond \psi_k \in \Delta_x'$.
      \end{subproof}
    \end{claim*}

    Now that $(\Box^{-1} \Gamma_x', \Theta \cup \set{\varphi})$ is $L$-consistent,
    then by Lindenbaum lemma, there is $y' = (\Gamma_y', \Delta_y') \in W_L^*$ such that $\Box^{-1} \Gamma_x' \subseteq \Gamma_y'$ and $\Theta \cup \set{\varphi} \subseteq \Delta_y'$.
    Now it remains to show $\Diamond^{-1} \Delta_x' \subseteq \Delta_y'$ to obtain $x' \sqsubset^* y'$ and $\varphi \notin \Gamma_y'$.
    Take any $\psi \in \Diamond^{-1} \Delta_x'$, then $\varphi \lor \psi \in \Theta$, then $\varphi \lor \psi \in \Delta_y'$, so $\varphi \lor \psi \notin \Gamma_y'$ by maximality.
    By Corollary (cor:saturation of the paper), this implies $\varphi \notin \Gamma_y'$ and $\psi \notin \Gamma_y'$, the latter of which implies $\psi \in \Delta_y'$ b (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:vandermonde of arXiv:2609.04092, 'Short character sums of inhomogeneous polynomials'] Let $m,n$ be positive integers and  consider the Vandermonde matrix
    \begin{align*}
        \begin{bmatrix}
            1&a_1&a_1^2&\cdots&a_1^n\\
            \vdots &&&&\vdots\\
            1&a_m&a_m^2&\cdots&a_m^n
        \end{bmatrix}.
    \end{align*}
    If $m\leq n+1$, then this has rank $m$ if and only if all $a_i$'s are distinct. If $m>n+1$, then this has rank $n+1$ if and only if $n+1$ of the $a_i$'s are distinct.

