body:
[Lem inequality_mark_variance of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Consider a continuous semi-definite positive kernel $K : \mathbb{R}^2 \to \mathbb{R}$ such that $K(t,t) = 1$ for every $t \in \mathbb{R}$. Fix $a<b \in \mathbb{R}^2$ and denote by $P$ a centered Gaussian measure with covariance function $K.$

		\begin{enumerate}
			\item Assume, for every $s<t \in \mathbb{R}^2$, 
			\begin{equation}
				\sup_{v \in [s,t]} \left|L_v^K(h) - \alpha^K(v) \right| \xrightarrow[h \to 0^+]{} 0.
			\end{equation} 
		Then \[ \forall (R_n)_{n \geq 1} \in \mathcal{A}, \exists M \in \mathbb{R}_+, \forall (s,t) \in [a,b]^2,\forall n \geq 1, 1- K_n(s,t) \leq M|s-t|,\] where $K_n$ stands for the covariance function of $P_{[R_n]}.$
			\item Assume  $K : (s,t) \mapsto \tilde{K}(t-s)$ is a stationary kernel, $ \alpha \in \mathbb{R}_+$ is a cluster point of $L^K : h \in \mathbb{R}_+^* \mapsto h^{-1}(1- \tilde{K}(h)) $ and $L^K$ is bounded. Fix a positive sequence $(s_n)_{n \geq 1}$  converging to zero such that $\lim_{n \to + \infty} L^K(s_n) = \alpha$ and put $(R_n)_{n \geq 1} := \left( \left( s_n \cdot \mathbb{Z} \right) \cap [-n,n] \right)_{n \geq 1} \in \mathcal{A}$.  Then, \[\exists M \in \mathbb{R}_+,\forall (s,t) \in [a,b]^2, \forall n \geq 1, 1- K_n(s,t) \leq M|s-t|,\]
			where $K_n$ stands for the covariance function of $P_{[R_n]}.$ 
		\end{enumerate}

[Thm 2 (Microscopic hop-count LLN and CLT) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Assume that $\ell\ge2$ is fixed and $\go$ is not deterministic. For integers $a<b$, let $H^{(\ell)}(a,b)$ denote the minimum number of edges among all geodesics from $a$ to $b$ in the $\ell$-spread-out line graph. Then
\begin{align}
    \frac1n\cdot {H^{(\ell)}(0,n)}\to \mu_{\mathrm{Hop}}
    \text{ a.s.~and }
    \frac1n\cdot {\E H^{(\ell)}(0,n)}\to \mu_{\mathrm{Hop}}
\end{align}
for some constant $\mu_{\mathrm{Hop}}\in(0,\infty)$.
Moreover,
\begin{align}
    n^{-1/2}\cdot (H^{(\ell)}(0,n)-n\cdot \mu_{\mathrm{Hop}})
    \Longrightarrow 
    \N(0,\gs^2_{\mathrm{Hop}}),
\end{align}
where $\gs^2_{\mathrm{Hop}}$ is a positive constant given in~\eqref{eq:hop-var-def}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mylem 3 of arXiv:2607.00495, 'Rank deficiency of Bernoulli random matrices for growing corank'] Let $X_{1},\dots,X_{n}$ be independent non-negative random variables
\begin{itemize}
    \item Assume that there exist $\eta >0$ and $ \tau >0$ such that $\mathbb{P}( X_{j} \le \eta) \le \tau$. Then for all $\varepsilon \in (0,1]$,
    \begin{align*}
        \mathbb{P}\left( \sum_{j=1}^{n} X_{j} \le \eta \varepsilon n \right) \le \left( \frac{e}{\varepsilon} \right)^{\varepsilon n} \tau^{n-\varepsilon n}.
    \end{align*}
\item  Assume that there exist $M$, $m> 0$ and $s_{0} \ge 0$ such that $\mathbb{P}\left(X_{j}\le s\right)\le \left(Ms \right)^{m}$ for all $s\ge s_{0}$. Then
\begin{align*}
\mathbb{P}\left(\sum_{j=1}^{n}X_{j} \le n s\right)\le \left(C_{\ref{Tenzorization}}M s\right)^{mn}\quad ~\text{for all}~~ s\ge s_{0},
\end{align*}
where $C_{\ref{Tenzorization}}$ is a constant.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] Let $\beta\in\NN^n$, put $m=d-|\beta|\ge0$, and let
$0\le e\le m$.  For any $i,j,k\in[n]$,
\begin{equation}
 \binom{m}{e}
 c_{\beta+(m-e)e_i+ee_j}
 c_{\beta+ee_i+(m-e)e_k}
 \ge
 c_{\beta+me_i}
 c_{\beta+ee_j+(m-e)e_k}.
\end{equation}
Coefficients with an index outside $\NN^n$ are interpreted as zero.

[Lemma 37 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Fix distinct points $x,y \in \BD$ and $\delta \in (0,1)$.  Let also $I,J$ be two disjoint segments connecting $x$ and $y$ respectively to $\partial\BD$.  Then,  there exists a coupling between $(\Gamma_{\BD} ,  D_{\Gamma_{\BD}}^{\BD})$ and a zero-boundary GFF $\Psi$ on $\BD$ such that $\Psi$ and $\Gamma_{\BD}$ are coupled as in \Cref{subsec:nested_cle_gff} and the following holds.  Let $I^{\star}$ (resp.\ $J^{\star}$) denote the closure of the union of the loops in $\Gamma_{\BD}$ that intersect $I$ (resp.\ $J$),  each intersected with the closed Euclidean $\delta$-neighborhood of $I$ (resp.\ $J$).  Let also $\tau$ (resp.\ $\sigma$) be a stopping time with respect to the filtration generated by $(\SCB_t(\SCL(x) ; D^{\BD}_{\Gamma_{\BD}}))_{t \geq 0}$ (resp.\ $(\SCB_t(\SCL(y) ; D_{\Gamma_{\BD}}^{\BD}))_{t \geq 0}$).  Consider the set
\begin{align*}
A\defeq\SCB_{\tau}(\SCL(x) ; D_{\Gamma_{\BD}}^{\BD}) \cup \SCB_{\sigma}(\SCL(y) ; D_{\Gamma_{\BD}}^{\BD}) \cup I^{\star} \cup J^{\star}.
\end{align*}
Then,  $A$ is local for $\Psi$.

