    $$ \rho(t,X,Y)=\frac{d[X,Y]}{dt},\qquad \pi-{\rm a.s.}. $$
    \begin{enumerate}
        \item If $\rho$ is $\mathcal{O}^d$-valued and there exists a strong, pathwise unique  solution to the SDE \begin{equation}

            d\begin{pmatrix}
            Z \\
            \tilde{Z}
        \end{pmatrix}_t = \begin{pmatrix}
            1 \\ 
            \rho\deln{t,Z,\tilde{Z}} 
        \end{pmatrix} dB_t, \quad \begin{pmatrix}
            Z_0 \\
            \tilde{Z}_0
        \end{pmatrix} = 0.
    \end{equation}
         Then, $\pi \in \mathcal{T}_{bc}\deln{\mathbb{W}^d, \mathbb{W}^d}$.
        \item If $\pi$ is induced by a bicausal Monge map $T$, then $\rho$ is $\mathcal{O}^d$-valued and there exists a strong solution to (equation eqn:extendedbrowniansde of the paper). 
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

