[Proposition 29 (Single-exponential moving-product entropy) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under the assumptions of Proposition~\ref{prop:exp-lln},
the map \(t\mapsto J_N(t)\) is locally absolutely continuous and, for almost every \(t>0\),
\begin{equation}
    J_N'(t)
    \le\frac{1}{2\varepsilon\lambda}J_N(t)
      +\frac{\log C_G}{2\varepsilon\lambda}.
\end{equation}
If $P_0^N=\mu_0^{\otimes N}$, then, with
\begin{equation}
    \kappa:=\frac{1}{2\varepsilon\lambda},
\end{equation}
\begin{equation}
    J_N(t)\le (e^{\kappa t}-1)\log C_G.
\end{equation}

[Definition 8 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] A fractional Brownian motion (fBm) $\left(\mathbf{W}^{H}_t\right)_{t\geq 0}\subset \R^n$ with Hurst index $H\in(0,1)$ is a centered Gaussian process with covariance 
\begin{equation}

\left(\E \left[\mathbf{W}^H_t \left(\mathbf{W}^H_s\right)^\textnormal{T}\right]\right)_{j_1,j_2\in\{1,\dots,n\}}=\frac{1}{2} (t^{2H} +s^{2H} -|t-s|^{2H}) \delta_{j_1,j_2},
 \end{equation}
for $\delta$ that indicates the Kronecker delta. Specifically, the fBm in $\R^n$ is composed by i.i.d. scalar fBms with Hurst index $H$.

[Lemma Zm-orbits of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $x\in (0,1)$ and set $x_{k}=Z_{m}^{i,\circ k}(x)$.

\begin{enumerate}
\item If (SC) holds, then 
\begin{equation}
\lim_{k\rightarrow \infty }Z_{m}^{i,\circ k}(x)=p_{m}^{i}\qquad \text{for
every }x\in (0,1),  
\end{equation}
and the convergence is uniform on every compact subinterval $[\delta ,\eta
]\subset (0,1)$;

\item If (SO) holds, then $Z_{m}^{i,\circ k}(x)\uparrow 1$ as $k\rightarrow
\infty $ for every $x\in (0,1)$, and the convergence is uniform on every
compact $[\delta ,\eta ]\subset (0,1)$.
\end{enumerate}

[Theorem th:max_fluct of arXiv:2604.21142, 'Gaussian fluctuations for Internal DLA on cylinders'] Let $(A(t))_{t\geq 0}$ denote an IDLA process on the cylinder ${\ensuremath{\mathbb G}} _N$ starting from $A(0) = R_0$. For every $\n > 0$ and every $m \geq 1$ there exists a constant $C = C(\n, m) < \infty$ such that, with
	\[ T^\sharp \coloneqq N \sqrt{\t_{mix}} \,(\log N)^2\,, \qquad \Delta_N \coloneqq C \max\!\left\{\, \log N,\; \sqrt{\frac{T \wedge T^\sharp}{N}\,\Big( \log N + \log_+\!\big( T/N \big) \Big)} \,\right\}\,, \]
we have
	\begin{equation}
	{\ensuremath{\mathbb P}}  \Big( R_{\lfloor T/N - \Delta_N \rfloor}
	\subseteq A(T) \subseteq R_{T/N +  \Delta_N } \Big) \geq 1-N^{-\n}
	\end{equation}
uniformly over integer $T$ with $1 \leq T \leq N^m$, for every $N$ large enough. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 (Local bounded solutions) of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] There is a maximal time $T_*\in(0,\infty]$ and a unique solution
\begin{equation*}
  u\in C([0,T_*);L^1(\R^d))
  \cap L^\infty_{\mathrm{loc}}
  ([0,T_*)\times\R^d)
\end{equation*}
satisfying
\begin{equation}
  u(t)=G(t)*u_0-
  \int_0^t\nabla G(t-s)*\bigl(b(s)u(s)^{1+k}\bigr)\,d s.
\end{equation}
The solution conserves the mass.

[Lemma lem:secondorder of arXiv:2412.01995, 'Exciting games and Monge-Amp\`{e}re equations'] Suppose $C>10$ and denote $\iota=\frac{1}{4e^{C+10}}$. Then we have 
\begin{align*}
    \textstyle \sup_{y \in \tilde \Omega_C, \, \xi \in \mathcal{S}^{d-1}}\left(C-\tilde \eta (y)-h(y)\right)^{2d} \, \nabla^2_{\xi\xi} \tilde\eta \, e^{\frac{ \iota|y|^2}{2}}\leq K(C),
\end{align*}
where $K(C)$ is a positive constant that only depends on $C$.

