body:
[Theorem thm:main of arXiv:2608.09465, 'Balancing fractional Brownian motion'] Let 
\begin{align*}
c(H) = \begin{cases}
1/2 & H<1/2\\
1/2+H & H\geq 1/2
\end{cases}.
\end{align*}
\begin{enumerate}
\item [(1)] For all large $n$, with probability $1-o(1)$, 
\begin{align*}
n^{1/2-H}\lesssim\disc(f_1,\ldots,f_n)\lesssim n^{1/2-H}(\log n)^{c(H)},
\end{align*}
where the implicit constants depend only on $H$. When $H = 1/2$, for every fixed $\varepsilon\in(0,a_0)$, the implicit constant in the lower bound can be taken as $a_0-\varepsilon$, i.e., $\disc(f_1,\ldots,f_n)>a_0-\varepsilon$. 
\item [(2)] For every $H\in(0,1)$, there exists a randomized polynomial-time algorithm that returns a signing $\sigma\in\{\pm1\}^n$ satisfying, 
\begin{align*}
L(\sigma)\lesssim
\begin{cases}
n^{1/2-H}\sqrt{\log n} &0<H<1/2,\\
(\log n)^{3/2} &H=1/2,\\
\sqrt{\log n} &1/2<H<1,
\end{cases}
\end{align*}
with probability $1-o(1)$ over the sample paths (and the internal randomness of the algorithm), 
where the implicit constants depend only on $H$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 22 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] Let $\mathfrak v_m$ be the optimum in
\eqref{num:eq:exact-input}. Then
\begin{align}
 \mathfrak v_m
 &=
 \frac{\pi^2}{4m^2}+o(m^{-2})\notag\\

 (2m+1)^2\mathfrak v_m
 &\longrightarrow\pi^2.
\end{align}
For every minimizing pair among the zeros of $\Lag_{m+2}$,
\begin{align*}
 \frac{x_{j_m,m+2}}{m+2},\
 \frac{x_{j_m+1,m+2}}{m+2}
 &\longrightarrow2,\\
 x_{j_m+1,m+2}-x_{j_m,m+2}
 &\longrightarrow2\pi,\\
 \frac{j_m}{m+2}
 &\longrightarrow\frac12+\frac1\pi.
\end{align*}

