[Definition defstable of arXiv:2411.15881, 'Stable Approximation for Call Function Via Stein's method'] Let $\alpha\in(1,2)$, $\sigma\geq 0$ and $\delta\in [-1,1]$ be real numbers. We say that $Y$ is distributed according to the \emph{$\alpha$-stable law with parameters $\sigma$ and $\delta$}, and we write $Y\sim S_\alpha(\sigma,\delta)$, to indicate that, for all $\lambda\in(-\infty,\infty)$,
\[
\mathbb{E}[e^{i\lambda Y}]=
\begin{array}{lll}
{\rm exp}\big\{-\sigma^\alpha|\lambda|^\alpha(1-i\,\delta\,{\rm sign}(\lambda)\,\tan\frac{\pi\alpha}2)\big\}
\end{array}
\]

[Proposition 6 (no universal behaviour at the critical dimension) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Assume that \(\alpha > 2 \text{ and } \frac{2\alpha}{\alpha-1} \in \N\). Also assume that $\theta$, defined here on $\Z^{\frac{2\alpha}{\alpha-1}}$, has a finite moment of order $\delta > \frac{2\alpha}{\alpha-1}$. Consider \(\Tree_{n}\)-walk in \(\Z^{\frac{2\alpha}{\alpha-1}}\) with $\theta$-jumps.

\begin{enumerate}[(i)]
  \item 
If \Cref{Assum:SufficientConditionTransience} holds, then this \(\Tree_{n}\)-walk is transient:
\begin{equation*}{
\frac{R^{\theta}(\Tree_{n})}{n} \xrightarrow[n \to +\infty]{(\P)} \P(\esc_{+}) > 0.
}\end{equation*}
  \item If \(L(n) \to +\infty\) then this \(\Tree_{n}\)-walk is
recurrent:
\begin{equation*}{
\frac{R^{\theta}(\Tree_{n})}{n} \xrightarrow[n \to +\infty]{(\P)}  0.
}\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Problem thm:erik-goran of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] The associated game is a specification of the game so far presented corresponding to the functions 
$f,g$ and $h$ being replaced with functions 
$\tilde f,\tilde g,\tilde h: {\cal I}\rightarrow \mathbb{R}$ given by:
\begin{align}
\begin{split}
&\text{$\tilde f = \tilde h \leq \tilde g$ on ${\cal I}$ with:}\\ 
&\text{$\tilde f= f$ and $\tilde g=g$, on $B^{f \leq g}$, and}\\
&\text{$\tilde f = \tilde g = \tilde h$, on $B^{g \leq f}$, where 
$\tilde f = f$ on ${B^{g<f<h}}$, $\tilde g = g$ on ${B^{h<g<f}}$ and $\tilde h = h$ on ${B^{g\leq h \leq f}}$.}
\end{split}
\end{align} (Stated as a problem by the paper; open unless the paper says otherwise.)

[Proposition 8 of arXiv:2606.16083, 'Eyring--Kramers asymptotics for infinite-dimensional stochastic gradient systems'] Let $x,c_x,B_{r_x}(x)$ and $\eta:=\zeta_x$ be as in \eqref{Eq:Open_Saddle}. Then, there exists a constant $C>0$ such that for all $\Psi\in \mathrm{Lip}_b(B)$ with $\mathrm{supp}(\Psi)\subseteq B_{r_x}(x)$
    \begin{align*}
         \frac{1}{\beta}\int_B \|\nabla \Psi\|_H^2  d\mu_\beta    \geq C\|\Psi\|^2_{L^2(\mu_\beta)}.
    \end{align*}

[Proposition 43 of arXiv:2607.18104, '2607.18104'] Fix initial data $\hfix_0 \in \UC$ and $\hfixp_0 \in \UCp$ such that
\begin{equation}
\hfix_0(x) = \hfixp_0(x)
\end{equation} for all $x\in \R$, where with a slight abuse of notation, we extend $\hfixp$ periodically from $\mathbb{T}$ to $\R$. 
Fix some $a\in \R$. 

Then there exist constants $c,C>0$, and a coupling $\mathbf{P}$ between the periodic KPZ fixed point $\hfixp$ and the KPZ fixed point $\hfix$, started from $\hfixp_0$ and $\hfix_0$, respectively, such that 
\begin{equation}
    \mathcal{A}_{\varepsilon} := \left\{ \hfixp\big(\hfixp_0;y,\varepsilon\big) = \hfix(\hfix_0;y,\varepsilon) \ \forall y \in \Big[a-\frac{1}{4},a+\frac{1}{4}\Big] \cap  \textup{ext}_{\varepsilon}(\hfix_0)\right\}
\end{equation}
satisfies for all $\varepsilon>0$
\begin{equation}
\mathbf{P}\left( \mathcal{A}_{\varepsilon} \right) \geq 1- C\exp(-c\varepsilon^{-1/2}) .
\end{equation} Moreover, we get that for all $y\in \mathbb{T}\setminus\textup{supp}(\hfix_0)$ 
\begin{equation}
   \lim_{\varepsilon \rightarrow 0} \hfix\big(\hfix_0;y,\varepsilon\big) =  \lim_{\varepsilon \rightarrow 0} \hfixp\big(\hfixp_0;y,\varepsilon\big) = -\infty ,
\end{equation} in the sense of almost sure convergence in supremum-norm of the function in $y$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:boundary2 of arXiv:2601.05361, 'Noise sensitivity in last-passage percolation'] For every $p\in(0,1)$, $0<\lambda<\lambda'<1$ and $u\in{\mathbb{Z}}^2$, we have for every $x\in u+{\mathbb{Z}}_{\ge0}^2$ that
\begin{enumerate}[label=(\roman*)]
    \item (stationarity) $\{(T(\lambda;x,x+y),T(\lambda';x,x+y)):y\in{\mathbb{Z}}_{\ge0}^2\}\stackrel{d}{=}\{(T(\lambda;u,u+y),T(\lambda';u,u+y)):y\in{\mathbb{Z}}_{\ge0}^2\}$;
    \item (monotonicity) $\omega_x\le\omega^H_x(\lambda')\le\omega^H_x(\lambda)$ and $\omega_x\leq\omega^V_x(\lambda)\le\omega^V_x(\lambda')$;
    \item (independence) $\{\omega^V_{x+j\mathbf{e}_2}(\lambda):j>0\}$ and $\{\omega^V_{x+j\mathbf{e}_2}(\lambda'):u_2-x_2<j\le0\}$ are independent; the same holds for $\{\omega^H_{x+i\mathbf{e}_1}(\lambda):i>0\}$ and $\{\omega^V_{x+i\mathbf{e}_1}(\lambda'):u_1-x_1<i\le0\}$.
\end{enumerate}

[Lem lemmadistance of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] If $\theta\in C^1([0,T])$, then for any $\epsilon\in(0,\frac{\pi}{2})$, there exists a $\lambda_0>0$ such that $\forall\lambda>\lambda_0$, it holds that
$$
\sup_{s\in[0,t]}|\alpha_s-\beta_s|\leq c_{\theta,t}\frac{1-e^{-2\lambda\sin(\epsilon t)}}{2\lambda\sin{\epsilon}},\quad t\in[0,T],
$$
where $c_{\theta,t}:=\sup_{s\in[0,t]}|\dot{\theta}_s|$ and $\alpha_s$, $\beta_s$ are obtained by the following equations
\begin{equation}\left\{
\begin{array}{lllll}
\dot{\alpha}_s=-2\lambda\sin(\alpha_s)-\dot{\theta}_s\\
\dot{\beta}_s=-2\lambda\sin(\beta_s)\\
\alpha_0=\beta_0\in[-\frac{\pi}{2}+\epsilon,\frac{\pi}{2}-\epsilon].
\end{array}
\right.\end{equation}

[Theorem thm:upper of arXiv:2606.21006, 'Law of the Iterated Logarithm for Weighted Sums of Functionals of Long-Memory Gaussian Seq'] There exists \(C_{\mathrm{up}}<\infty\) such that
\[
\limsup_{n\to\infty}
\frac{|S_n|}{A_n(2\log\log n)^{m/2}}
\le C_{\mathrm{up}}
\qquad\text{\rm a.s.}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 10 (\hspace{-0.05em}{{\cite[Lemma~2.2) of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] {csiszár2004information}}}]

		For any fixed $A>0$ and any non-negative real numbers $a_0,a_1,\ldots a_{k-1} \in [0,A]$, satisfying $a_i\log N \in \mathbb{Z}$, 
		\begin{equation*}
			N^{a_{\tot} H(a_0,\dots,a_{k-1})-o_N(1)}\leq \binom{a_{\tot}\log(N)}{a_0\log(N),\dots,a_{k-1}\log(N)}\leq N^{a_{\tot} H(a_0,\dots,a_{k-1})},
		\end{equation*}
		where the term $o_N(1)$ tends to $0$ for any fixed $A$ as $N\to\infty$, uniformly in $a_0,\dots,a_{k-1}\in [0,A]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

