[Lemma structureH-1 of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] A linear functional $L:H_0^1(f)\to\mathbb{R}$ belongs to $H^{-1}(f)$ if, and only if, there exists $P\in L^2(1/f)$ such that 
    \begin{equation*}
        L(H)=\int_0^T\int_0^1 P_t\;\nabla H_t\;dx\;dt,
    \end{equation*}
    for every $H\in C_{c}^{\infty}(\Omega_T)$. In this case, 
    \begin{equation*}
        ||L||^2_{-1,f}=\int_0^T\{\langle P_t, P_t\rangle_{f(t)^{-1}}-c_t\}\;dt,
    \end{equation*}
    where $c_t=\{\langle P_t/f_t\rangle^2\;/\;\langle 1/f(t)\rangle\}\mathds{1}\{\langle 1/f(t)\rangle<\infty\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 19 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] For $x\in C$,

\begin{equation*}
g_D=\psi^C*q^{C,D}.
\end{equation*}

Equivalently, $g_D$ is the minimal non-negative solution of

\begin{equation*}
g_D=q^{C,D}+q^C*g_D.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Z-signchanges of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $f$ be a continuous real-valued function on an
interval $(a,b)$. We denote by 
\begin{equation}
Z(f;(a,b))  
\end{equation}
the maximal integer $m\geq 0$ for which there exist points 
\begin{equation}
a<x_{1}<\cdots <x_{m+1}<b  
\end{equation}
such that 
\begin{equation}
f(x_{i})f(x_{i+1})<0,\qquad i=1,\dots ,m.  
\end{equation}
Thus $Z(f;(a,b))$ is the number of strict sign changes of $f$ on $(a,b)$.
Whenever the interval is $(0,\tfrac{1}{2})$ we write simply 
\begin{equation}
Z(f)=Z\!\left( f;\left( 0,\tfrac{1}{2}\right) \right) .  
\end{equation}

[Corollary Application of Ito formula of arXiv:2607.29548, 'Generalized reflected BSDEs with irregular obstacles driven by RCLL increasing processes o'] Let $\left(Y_t\right)_{t \leq T}$ be a one-dimensional adapted process with regulated paths of the form (equation form of the process for Ito of the paper). Then, for every $t \in [0,T]$, we have
		\begin{equation*}
			\begin{split}
				\mathcal{E}(\beta A)_{t} \left| Y_t \right|^2&=  \left| Y_0 \right|^2+ \int_{0}^{t} \dfrac{\beta}{1+\beta \Delta_- A_s} \mathcal{E}(\beta A)_{s} \left| Y_{s-} \right|^2 dA_s+2\int_{0}^{t}  \mathcal{E}(\beta A)_{s} Y_{s-} dY^{\ast}_s+\int_{0}^{t} \mathcal{E}(\beta A)_{s} d \left[Y^{\ast}\right]^c_s\\
				&\quad +\sum_{0 < s \leq t} \mathcal{E}(\beta A)_{s} \left| \Delta_{-} Y_{s} \right|^2+\sum_{0 \leq s < t} \mathcal{E}(\beta A)_{s} \left(\left| \Delta_{+} Y_{s}\right|^2+2Y_{s}\Delta_{+} Y_s \right).
			\end{split}
		\end{equation*}

