[Lem Lemma: Dimension bound under proper factor condition of arXiv:2605.16921, '${\ASL_n}(\mathbb Z)$ invariant random subsets of $\mathbb Z^n$'] Let $X$ be an ergodic $\mathbb{Z}^{d'}$-system, $f \in L^\infty(X)$, and $\delta > 0$. Let $D \geq 0$ and let $(N_n)_{n \geq 0}$ be nilfactors of $X$, each of dimension at most $D$, satisfying:
    \begin{equation}
        \|\mathbb{E}[f \mid N_n] - \mathbb{E}[f \mid N_n']\|_2 > \delta
    \end{equation}
    for every $n \geq 0$ and every strict nilfactor $N_n' \to N_n$ (i.e.\ of dimension strictly smaller than $\dim N_n$). Then for every finite $I \subset \mathbb{N}$, the joining of $\{N_n\}_{n \in I}$ inside $X$ is a nilsystem of dimension at most $D \|f\|_2^2 \delta^{-2}$.

[Lemma lem-entridentshreds of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] For any box $W\Subset \mathbb{R}^d$ and any $\xi\in{\mathcal M }_1({\mathcal S }_W)$, 
\begin{equation}
\begin{aligned}
H_{{\mathcal S }_{W}}\big(\xi\,\big|\, \partial\Pi_{W}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)\otimes{\tt K}_W\big)
&=\int_{{\mathcal T }_W}\partial\Pi_{W}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)({\rm d} \mu)\, H_{{\mathcal S }_W}\Big(\xi(\mu,\cdot)\,\Big|\,\bigotimes_{i\in I}\Pi_i(\xi(\mu,\cdot))\Big)\\
&\quad +\int_{{\mathcal T }_W}\partial\Pi_{W}^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)({\rm d} \mu)\, \sum_{i\in I}H_{{\mathcal C }_{l_i}}\big( \Pi_i(\xi(\mu,\cdot))\,\big|\, q_{x_i,y_i}^{{{\scriptscriptstyle{({l_i,W}})}}}\big),
\end{aligned}
\end{equation}
where we wrote $\mu=\sum_{i\in I}\delta_{(x_i,l_i,y_i)}$ and $\Pi_i\colon {\mathcal C }^I\to {\mathcal C }$ for the canonical projection on the $i$-th factor and $\xi(\mu,\cdot)$ for the kernel $(\xi)_{{\mathcal T }_W\to{\mathcal S }_W}(\mu,\cdot)$.

[Proposition of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] There exists a constant $C_0>0$ such that 
    \begin{equation}
        \int_0^T\int_0^1 \frac{|\nabla\rho_t(x)|^2}{\sigma(\rho_t(x))}\;dx\;dt\leq C_0\{I_{[0,T]}(\rho)+1\}
    \end{equation}
    for any path $u\in  {\mathcal{D}}_{\mathcal{E}}([0,T],{\mathcalboondox M}_{ac})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

