body:
[Theorem phi of arXiv:2411.05204, '\Large\bf Sample Path Properties of the Fractional Wiener--Weierstrass Bridge'] Let $ Y $ be a fractional Wiener--Weierstrass  bridge with parameters $\alpha$, $b$, and $H$, and $K=\min\{1,({-\log_b\alpha})\}$.
\begin{enumerate}[(i)]
\item  If $H<K$, 
\begin{align}
{\mathbb P}\left(\frac{1}{L}<v_\Phi( Y )<\infty\right)=1\quad\text{ for }\quad\Phi(x)=\bigg(\frac{x}{\sqrt{2\log\log(1/x)}}\bigg)^{1/H}.
\end{align}
\item  If $H=K$, 
\begin{align}
{\mathbb P}\left(\frac{1}{L}<v_\Phi( Y )<\infty\right)=1\quad\text{ for }\quad\Phi(x)=\bigg(\frac{x}{\sqrt{2\log(1/x)\log\log(1/x)/H}}\bigg)^{1/H}.
\end{align}
 \item  If $H>K$, 
\[
{\mathbb P}(0<v_\Phi( Y )<\infty)=1\quad\text{ for }\quad\Phi(x)=x^{1/K}.
\]
\end{enumerate}
Moreover, in all three cases, if $\Theta:[0,\infty)\to[0,\infty)$ is a function such that  $\Phi(x)=o(\Theta(x))$ as $x\to 0^+$, then $v_{\Theta}( Y )=\infty$ almost surely. Conversely, if $\Theta(x)=o(\Phi(x))$ as $x\to 0^+$, then $v_\Theta(Y)=0$ almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:max-poisson of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] For any $\lambda>0$,
\begin{equation}
    \mu(\lambda):=\max_{i\ge 0} p_i(\lambda) 
    = \frac{\lambda^{\lfloor\lambda\rfloor}}{\lfloor\lambda\rfloor!}   e^{-\lambda}, 
\end{equation}
and, for $\lambda\geq1$,
\begin{equation}
    \mu(\lambda)<\frac{1}{\sqrt{2\pi \lfloor\lambda\rfloor}}.
\end{equation}
In particular, the maximal probability of the Poisson distribution with parameter $\lambda > 0$ tends to zero as $\lambda \rightarrow \infty$. Moreover, the following modification of the estimate (equation eq:mulambdale1overla of the paper) holds true: 
\begin{equation}
    \mu(\lambda)<\frac{1}{\sqrt{2\pi \lambda}}\left(1+\frac{1}{(\lambda-1)\vee 1}\right)^{\frac12}\exp\left(-\frac1{12\lambda+1}\right), \qquad\lambda>1.
\end{equation}

