[Thm sym-mon-localization-for-modes of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let ${\mathcal{C}}\in\CAlg(\CAT_T^\textup{$S$-cc})$, let $X\in\CMon(\SPC_T)$, and let $I\colon X\to{\mathcal{C}}$ be a map in $\CMon(\CAT_T)$. 

    \begin{enumerate}
        \item There exists a map $F\colon{\mathcal{C}}\to{\mathcal{D}}$ in $\CAlg(\CAT^\textup{$S$-cc}_T)$ such that $FI\colon X\to{\mathcal{D}}$ lands in the tensor-invertible objects, and which is universal in the sense that for any ${\mathcal{E}}\in\CAlg(\CAT_T^\textup{$S$-cc})$ the induced map
        \[
            -\circ F\colon{\textup{Hom}}_{\CAT_T^\textup{$S$-cc}}({\mathcal{D}},{\mathcal{E}})\to{\textup{Hom}}_{\CAT_T^\textup{$S$-cc}}({\mathcal{C}},{\mathcal{E}})
        \]
        is the inclusion of the components consisting of all $G\colon{\mathcal{C}}\to{\mathcal{E}}$ such that $GI$ factors through the invertible objects.
        \item If ${\mathcal{C}}$ is $S$-presentable and $X$ is small, then ${\mathcal{D}}$ is $S$-presentable.
        \item If ${\mathcal{C}}$ is idempotent, then so is ${\mathcal{D}}$. Moreover, an ${\mathcal{M}}\in\CAlg(\CAT_T^\textup{$S$-cc})$ is a ${\mathcal{D}}$-module if and only if it is a ${\mathcal{C}}$-module and the map $I(x)\cdot-\colon{\mathcal{M}}(A)\to{\mathcal{M}}(A)$ given by the ${\mathcal{C}}$-module structure is an equivalence for every $A\in T$ and $x\in X(A)$.
    \end{enumerate}
    \begin{proof} Consider the pushout
        \begin{equation}
            \begin{tikzcd}
                \mathcal P_{S\triangleright T}(X)^{\otimes}\arrow[r,"\mathcal P(f)^{\otimes}"]\arrow[d,"\tilde I"']\arrow[dr,phantom,"\ulcorner"{very near end}] & \mathcal P_{S\triangleright T}(X^{\textup{grp}})^{\otimes}\arrow[d]\\
                {\mathcal{C}}\arrow[r] & {\mathcal{D}}
            \end{tikzcd}
        \end{equation}
        in $\CAlg(\CAT_T^\textup{$S$-cc})$, where the left-hand vertical map is adjunct to $S$ and the horizontal map is induced by a group completion. We may then identify for any ${\mathcal{E}}\in\CAlg(\CAT_T^\textup{$S$-cc})$ the map ${\textup{Hom}}({\mathcal{D}},{\mathcal{E}})\to{\textup{Hom}}({\mathcal{C}},{\mathcal{E}})$ with the projection 
        \[
            {\textup{Hom}}(\mathcal P_{S\triangleright T}(X^{\textup{grp}})^{\otimes},{\mathcal{E}})\times_{{\textup{Hom}}(\mathcal P_{S\triangleright T}(X)^{\otimes},{\mathcal{E}})}{\textup{Hom}}({\mathcal{C}},{\mathcal{E}})\to{\textup{Hom}}({\mathcal{C}},{\mathcal{E}}),
        \]
        which by adjunction is the inclusion of those path components of symmetric monoidal $S$-cocontinuous $G\colon{\mathcal{C}}\to{\mathcal{E}}$ such that $GI$ factors through invertible objects.

        For the second claim we observe that the assumptions on $X$ and ${\mathcal{C}}$ guarantee that all objects in $((diag:pushout-inversion of the paper))$ except possibly the bottom right one are $S$-presentable. As $\CAlg(\textup{Pr}^S_T)\subset\CAlg(\CAT_T^\textup{$S$-cc})$ is closed under small colimits as a consequence of Proposition~(prop:PrS-T-vs-Cat-S-cc of the paper), we conclude that also ${\mathcal{D}}$ is $S$-presentable.

        For the final claim, we first observe that ${\mathcal{D}}$ is a ${\mathcal{C}}$-algebra, hence in particular a ${\mathcal{C}}$-module. Thus $\ul\Spc_{S\triangleright T}\otimes{\mathcal{D}}\to{\mathcal{C}}\otimes{\mathcal{D}}$ is an equivalence, and it will suffice for idempotency that 
        \begin{equation}
            {\textup{Hom}}_{\CAlg(\CAT_T^\textup{$S$-cc})}({\mathcal{D}}\otimes{\mathcal{D}},{\mathcal{E}})\xrightarrow{\;\smash{\raisebox{-0.25ex}{\ensuremath{\scriptstyle\sim}}}\;}{\textup{Hom}}_{\CAlg(\CAT_T^\textup{$S$-cc})}({\mathcal{C}}\otimes{\mathcal{D}},{\mathcal{E}})
        \end{equation}
        for any ${\mathcal{C}}$-algebra ${\mathcal{E}}$. Since the symmetric monoidal product is the coproduct on $\CAlg(\CAT_T^\textup{$S$-cc})$, we may view $((eq:check-idempotency of the paper))$ as a map
        \[
            {\textup{Hom}}({\mathcal{D}},{\mathcal{E}})\times{\textup{Hom}}({\mathcal{D}},{\mathcal{E}})\to{\textup{Hom}}({\ (Proof in the paper; no proof environment follows the statement in the TeX.)

