[Theorem 3 of arXiv:2605.20026, 'Quasihelix properties\\ of selected Volterra Gaussian processes'] Let $\gamma\in[0,1)$. Then for any $0<T_1<T_2$ the following statements hold.
\begin{enumerate}
\item[$(i)$]
Let $\alpha \in (-1/2, 1/2)$.
Then 
\begin{equation}
\ex\left(U^{(2)}(t)-U^{(2)}(s)\right)^2
\sim C(\alpha)(t-s)^{2\alpha+1}s^{-\gamma},
\quad \text{as } t\downarrow s,
\end{equation}
for any $s\in[T_1,T_2]$,
where
\begin{equation}
C(\alpha) = \int_0^\infty \bigl[(1+z)^\alpha-z^\alpha\bigr]^2\,dz
+ \frac{1}{2\alpha+1}
= \frac{\Gamma(\alpha+1)^2} {\Gamma(2\alpha+2)\cos(\pi\alpha)}.
\end{equation}
Consequently, the process $U^{(2)}$ is a local $(\alpha+\frac12,T_1,T_2)$-quasihelix.

\item[$(ii)$]
If $\alpha=1/2$, then the process  $U^{(2)}$ is a local $(1,1-\varepsilon,T_1,T_2)$-generalized quasihelix for any $\varepsilon\in(0,1)$.

\item[$(iii)$]
If $\alpha > 1/2$, then the process $U^{(2)}$ is a local $  (1,T_1,T_2)$-quasihelix.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma unique root of arXiv:2609.02073, 'Existence of closed non-planar $p$-elasticae'] Let $f:[0,\infty)\to \R$ be given as
  \begin{equation*}
    f(x) := \frac{p-1}{p} x^{\frac{p+1}{p-1}} - \frac{\lambda}{p} x^{\frac{1}{p-1}} - C^2 x^{-3}
  \end{equation*}
  with $\lambda \in  \R$ and $C^2>0$. 
  Then $f$ has only one strictly positive root. The sign change at this strictly positive root is negative-positive.

