[Theorem theo:existence of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] For all $d,L\in \mathbb{N}$ and $a>1$ there exists an isometry-invariant kernel $J$ on $\mathbb{H}^d_L$ satisfying 
	   \vspace{-0.5em} \begin{align*}
		J \sim \frac{a L^d \log\log n}{n^{2d}}
	\end{align*}
	such that $\mathbb{P}_{J} \left( |K_0| = \infty \right)> 0$. 
	On the other hand, if $J$ is an isometry-invariant kernel on $\mathbb{H}^d_L$ such that
	\begin{align*}
	\limsup_{n\to \infty}
	 \frac{L^{-d} \left( L^n \right)^{2d}}{\log\log \left( L^n \right)} J\!\left(L^n\right) \leq 1
	\end{align*}
	then $\mathbb{P}_{J} \left( |K_0| = \infty \right) = 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:laweq of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] For each $n \in \mathbb{N}$, consider the half-space geometric line ensemble $(L_i^n)_{i\ge 1}$ defined in Definition (def:le of the paper).  We have the following.
    \begin{enumerate} [label=(\roman*), font=\normalfont]
         \item   $ (L_1^n(j))_{j\in \llbracket 0,n\rrbracket}$ has the same distribution  as $G\bigl((1,1),(n+j,n)\bigr)_{j\in \llbracket 0,n\rrbracket}$, where the vertex weights are distributed as in Definition (def:GLPPc of the paper).

        \item  Fix any $m\in \llbracket 1,n\rrbracket$. When $c\in (q,q^{-1})$, we have
\begin{align} 
         \mathbb P\left(L_1^n\llbracket 0,m\rrbracket=B | \mathcal{F}_{\mathrm{ext}}^1\right) \stackrel{a.s.}{=} \frac{\mathbb P_{\mathrm{Geom};c^{-1}q}^{m,y}\left(\{Q=B\}\cap \{Q(j) \ge g(j+1) \mbox{ for }j\in \llbracket 0,m-1\rrbracket\}\right)}{\mathbb P_{\mathrm{Geom};c^{-1}q}^{m,y}\left(Q(j) \ge g(j+1) \mbox{ for }j\in \llbracket 0,m-1\rrbracket\right)}
    \end{align}
    where $\mathcal{F}_{\mathrm{ext}}^1=\sigma(L_i^n(j) : (i,j)\not\in \{1\}\times \llbracket0,m-1\rrbracket)$, $y=L_1^n(m)$, and $g=L_2^n\llbracket0,m\rrbracket$.
    \item  Fix any $m\in \llbracket 1,n\rrbracket$. When $c\in [0,q^{-1})$ we have
    \begin{align}
        & \mathbb P\left(L_i^n\llbracket 0,m\rrbracket=B_i \mbox{ for }i\in \{1,2\}| \mathcal{F}_{\mathrm{ext}}^{\llbracket1,2\rrbracket}\right) \\ & \hspace{2cm} \stackrel{a.s.}{=} \frac{\mathbb P_{\mathrm{Inter};q,c}^{m,(y_1,y_2)}\left(\{Q_1=B_1\}\cap\{Q_2=B_2\}\cap \{Q_2(j) \ge g(j+1) \mbox{ for }j\in \llbracket 0,m-1\rrbracket\}\right)}{\mathbb P_{\mathrm{Inter};q,c}^{m,(y_1,y_2)}\left(Q_2(j) \ge g(j+1) \mbox{ for }j\in \llbracket 0,m-1\rrbracket\right)}
    \end{align}
    where $\mathcal{F}_{\mathrm{ext}}^{\llbracket1,2\rrbracket}=\sigma(L_i^n(j) : (i,j)\not\in \{1,2\}\times \llbracket0,m-1\rrbracket)$, $y_1=L_1^n(m)$, $y_2=L_2^n(m)$, and $g=L_3^n\llbracket0,m\rrbracket$.
    \end{enumerate}

[Mylem 2.1 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] $Sub_{\varphi}(\Omega)$  is a Banach space with respect to the norm 
		\begin{equation}
			\tau_{\varphi}(X)=\inf \{a \geq 0: \textsf{E} \exp \{\lambda X\} \leq \exp \{\varphi(a \lambda)\}, \,\,\text{for all}\,\,\lambda \in \mathbb{R}\}.
		\end{equation}
		The norm above is equivalent to the one in Lemma (l2 of the paper), we recommend referring to [Buldyginbook] for proof, with the norm above, for any $u>0$, the  $\varphi$-sub-Gaussian process $(X_{t})_{t\in T}$ satisfies the following incremental inequality:
		\begin{equation}
			\textsf{P}\left(|X_t-X_s| \geqslant u \tau_\varphi(X_t- X_s)\right) \leqslant 2 \exp \left\{-\varphi^*(u)\right\},
		\end{equation}
		where $t,s\in T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma D-gamma-inv-h of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Under Assumptions~(ass:LR of the paper), (ass:diff2 of the paper), (ass:SC of the paper), and~(ass:SC-raised of the paper) at target $q^* = q/(q-2)$ (where $q \in (2,\infty]$ is the exponent from Assumption~(ass:nondeg of the paper)(ii), with $q^* = 1$ at $q = \infty$; cf.\ Remark~(rem:SC-raised-role of the paper)), let $h$ satisfy Assumption~(ass:nondeg of the paper) (all three clauses, including the Cameron--Martin compatibility~(equation eq:CM-compat-axiom of the paper)--(equation eq:CM-compat-dominator of the paper)). Assume the fixed-Tikhonov substitution regularity~(hyp:iii-F-prime of the paper) of Theorem~(thm:tikhonov-trace of the paper) for $(\mathcal{T}, \gamma_F, h) = (\Phi, \gamma_t, h)$, through either of two admissible sufficient routes. The operator-level route asks that $u_h^{(\varepsilon)} = \Phi^{*}(\gamma_t + \varepsilon I)^{-1}h$ lie in $\mathbb{D}^{1,2}(H_W)$ for every $\varepsilon \in (0,1]$, as in~(equation eq:uheps-D12 of the paper). The basis-wise route, which is the one used below, asks instead that $G^{(\varepsilon)} = (\gamma_t + \varepsilon I)^{-1}h$ lie in $\mathbb{D}^{1,2}(H)$ for every $\varepsilon > 0$, together with the H\"older-pair joint integrability~(equation eq:linear-sub-Holder of the paper) of the pair $(\Phi, G^{(\varepsilon)})$, these being the hypotheses of Theorem~(thm:linear-sub-D12 of the paper). Both routes are available automatically at the symmetric edge $p^* \geq 6$, equivalently $2 < q \leq 3$ on the edge choice $p^* = 2q/(q-2)$; sufficient conditions for $q > 3$ are catalogued in Remark~(rem:covering-iiiF-SPDE of the paper).

For each $\varepsilon > 0$, the Tikhonov regularisation
\[
  G^{(\varepsilon)} := (\gamma_t + \varepsilon I)^{-1}\,h
\]
belongs to $\mathbb{D}^{1,2}(H)$ with the exact Leibniz formula
\begin{equation}
  \mathcal{D}_r G^{(\varepsilon)} = -(\gamma_t + \varepsilon I)^{-1}\,(\mathcal{D}_r\gamma_t)\,(\gamma_t + \varepsilon I)^{-1}\,h,
\end{equation}
and the pointwise spectral bound $\norm{G^{(\varepsilon)}}_H \leq \norm{\gamma_t^{\dagger}h}_H$ together with $G^{(\varepsilon)} \to \gamma_t^{\dagger}h$ in $L^q(\Omega; H)$ as $\varepsilon \downarrow 0$. Define the associated covering fields intrinsically via the Hilbert--Schmidt kernel $\Phi_r := D_r X(t) \in L_2(U, H)$:
\[
  v_h^{(\varepsilon)}(r) := \Phi_r^{*}\,G^{(\varepsilon)}, \qquad v_h(r) := \Phi_r^{*}\,\gamma_t^{\dagger}h.
\]

Then the covering fields satisfy the explicit sharp spectral $H_W$-estimate
\begin{equation}
  \mathbb{E}\!\left[\int_0^t \norm{v_h^{(\varepsilon)}(r) - v_h(r)}_U^2\,\mathrm{d}r\right] \;\leq\; \frac{\varepsilon}{4}\,\mathbb{E}\!\left[\norm{\gamma_t^{\dagger}h}_H^2\right],
\end{equation}
so that $v_h^{(\varepsilon)} \to v_h$ in $L^2(\Omega;H_W)$ at the rate $O(\varepsilon^{1/2})$. Each $v_h^{(\varepsilon)}$ belongs to $\mathbb{D}^{1,2}(H_W) \subset \operatorname{Dom}(\delta_U)$, the limit $v_h$ belongs to $\operatorname{Dom}(\delta_U)$, and
\begin{equation}
  \delta_U\bigl(v_h^{(\varepsilon)}\bigr) \;\longrightarrow\; \delta_U(v_h) \qquad \text{in } L^2(\Omega).
\end{equation}
Consequently, the scalar correction integral, defined intrinsically with the positive sign convention so that $\delta_U(v_h^{(\varepsilon)}) = M^{(\varepsilon)} + C^{(\varepsilon)}$ (i.e., absorbing the Nualart minus sign of~(equation eq:nualart-substitution of the paper) via the identity $\mathcal{D} G^{(\varepsilon)} = -(\gamma_t+\varepsilon I)^{-1}(\mathcal{D}\gamma_t)(\gamma_t+\varepsilon I)^{-1}h$),
\begin{equation}
  C^{(\varepsilon)} \;:=\; -\int_0^t \operatorname{Tr}_U\bigl[\Phi_r^{*}\,\mathcal{D}_r G^{(\varepsilon)}\bigr]\,\mathrm{d}r \;=\; \int_0^t \operatorname{Tr}_U\bigl[\Phi_r^{*}\,(\gamma_t+\varepsilon I)^{-1}\,[\mathcal{D}_r\gamma_t]\,(\gamma_t+\varepsilon I)^{-1}\,h\bigr]\,\mathrm{d}r,
\end{equation}
converges in $L^2(\Omega)$ as $\varepsilon \downarrow 0$; the limit is independent of the Moore--Penrose freedom of $\mathcal{D}_r(\gamma_t^{\dagger}h)$ on $\ker(\gamma_t)$ and is denoted symboli (Proof in the paper; no proof environment follows the statement in the TeX.)

