[Lemma 14 (Karamata's Integration Theorem) of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] \cite{RV}

Let $L(x)$ be a function slowly varying at infinity. For $\rho>-1$, we have:
\begin{align*}
\int_0^x t^\rho L(t)\text{d} t\sim \frac{x^{\rho+1}L(x)}{\rho+1},\quad x\to\infty.
\end{align*}
For $\rho<-1$, we have:
\begin{align*}
\int_x^\infty t^\rho L(t)\text{d} t\sim \frac{x^{\rho+1}L(x)}{-(\rho+1)},\quad x\to\infty.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 21 ($H^1$-energy estimate) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d\in \{3,4\}$, $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$, and suppose that Assumption~\ref{assumption_weakened_setting} holds. Let $(u,\sigma)$ be the unique maximal solution to \eqref{eq:SCHtorus} and $(\sigma_m)_{m\ge 1}$ a localising sequence for $(u,\sigma)$. Let $C_\psi$ denote a constant that depends on the constants in Assumption~\ref{assumption_weakened_setting}. Then we have for all $t\in[0,T]$  $\mathbb{P}$-a.s.
    \begin{equation}
    \begin{aligned}
    \frac{1}{2}|u(t \land \sigma_m)|^2_{H^1}
    &\le \frac{1}{2}|u_0|^2_{H^1}
    - \inttm \intsO |\grad \Delta u|^2 \dx \ds
    + \inttm \intsO  (3u^2 \grad u- \grad u) \cdot \grad \Delta u \dx \ds  \\
    &\phantom{\le } + M_{t\land\sigma_m}
    +  C_\psi\inttm  \intsO  (1+|u|^2+|\grad u|^2 + |u|^2|\grad u|^2) \dx \ds  + C_\psi \inttm   |u|_{H^2}^2 \ds
    \end{aligned}
    \end{equation}
    for a continuous local martingale  $M$ with quadratic variation $[M]$ which satisfies for all $t\in[0,T]$  and $\varepsilon>0$
    \begin{equation}

    \begin{aligned}
    \E\big[ [M]^{1/2}_{t\wedge \sigma_m}\big] & \leq \varepsilon \E\bigg[\sup_{s\in[0,t\wedge \sigma_m]}  \|\grad u(s) \|^2_{L^2} \bigg]  +  \frac{C_\psi}{4\varepsilon}\E\Big[ \inttm  \intsO(1+|u|^2+|\grad u|^2 + |u|^2|\grad u|^2)\dx\ds\Big] \\
    &  \quad + \frac{C_\psi}{4\varepsilon}\E\Big[ \inttm  |u|_{H^2}^2 \ds\Big].
    \end{aligned}
    \end{equation}

