[Proposition thmappen of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The pmf $\hat{p}_{\bar{\mathcal{M}}}(\bar{n},t)$, $\bar{n}\ge\bar{0}$ of $\{\bar{\mathcal{M}}(t)\}_{t\ge0}$ solves the following system of differential equations:
{\small\begin{equation*}
\frac{\mathrm{d}}{\mathrm{d}t}\hat{p}_{\bar{\mathcal{M}}}(\bar{n},t)=-\sum_{j_0=1}^{k_0}\mu_{j_0}(1-e^{-j_0\lambda})\hat{p}_{\bar{\mathcal{M}}}(\bar{n},t)+\sum_{\bar{m}\succ\bar{0}}\hat{p}_{\bar{\mathcal{M}}}(\bar{n}-\bar{m},t)\sum_{j_0=1}^{k_0}\mu_{j_0}e^{-j_0\Lambda}\sum_{\substack{\Omega(k_i,m_i)\\i=1,2,\dots,q}}\prod_{i=1}^{q}\prod_{j_i=1}^{k_i}\frac{(j_0\lambda_{ij_i})^{x_{ij_i}}}{x_{ij_i}!}
\end{equation*}}
with initial condition $\hat{p}_{\bar{\mathcal{M}}}(\bar{n},0)=\delta_{\bar{n}}(\bar{0})$.

[Definition 6 of arXiv:2609.01333, '2609.01333'] Let $e_1 =(1,0)$  and  $\mathbb{S}^1= \partial B_1$ be the unit sphere of $\mathbb{R}^2$. For  $i=0,1$ and $n\geq i$  we define the function $\beta\mapsto T^i_n(\beta)$, $\beta>0$ by

\begin{align}

T_n^i(\beta)=\int_{\mathbb{S}^1}|\theta-e_1|^n K_i(\beta|\theta-e_1|)\mathrm{d}\theta.
\end{align}
Note that, for $\theta =  (\theta_1, \theta_2) \in \mathbb{S}^1$, since  $|\theta - e_1|^2 = 2(1-\theta\cdot e_1)= 2(1-\theta_1)$, by a change of variable over the sphere $\mathbb{S}^1$, see for instance \cite[Appendix D.3]{Gra14}, together with the change of variavles $r= \beta\sqrt{2(1-\theta_1)}$ so that
$ \mathrm{d} \theta_1 = -\beta^{-2}rdr$, we have
\begin{align}
\begin{split}
T^i_n(\beta) &= 2 \int_{-1}^{1}(2(1-\theta_1))^{n/2}  (1-\theta_1^2)^{-1/2} K_i(\beta \sqrt{2(1-\theta_1)}) \mathrm{d} \theta_1\\
&=  4 \beta^{{-n-1}}\int_{0}^{2\beta } \big(4-\frac{r^2}{\beta^2}\big)^{-1/2} r^n K_i(r) \mathrm{d}r.  
\end{split}
\end{align}

Furthermore, using the formulas in \eqref{eq:Bessel1} we easily find that

\begin{align}
(-T^0_n)'(\beta)=  T^1_{n+1}(\beta)
\quad\text{ and }\quad
(-T^1_n)'(\beta)=  T^0_{n+1}(\beta)+\beta^{-1}T^1_{n}(\beta).
\end{align}

[Them contre_exemple of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] There exists a centered stationary Gaussian measure $P \in \mathcal{P}\left(\mathbb{R}^\mathbb{R}\right)$ whose set of weak local Markov transforms is the set of all the measures $P'$ satisfying:
		\begin{enumerate}
			\item The measure $P'$ is centered Gaussian with constant variance function equal to $1$;
			\item The covariance function of $P'$ is non-negative;
			\item The measure $P'$ is Markov.

		\end{enumerate}

[Lemma 8 of arXiv:2607.11773, '2607.11773'] Suppose that {\bf(H1)}-{\bf(H4)}, \eqref{thetaassum2},  \eqref{dissip1} and \eqref{dissip2} hold.  
    Then  there exists
     $ \varepsilon^{*} = \varepsilon^{*}(\theta) \in (0, 1) $
     such that 
     for every  
    $\tau \in \mathbb{R}$ and $D = \{ D(\tau): \tau \in \mathbb{R} \} \in \mathcal{D}$,
   there exists $T = T(\tau, D) \ge { 3} \rho$  
   such that 
   the solution $u$ to \eqref{lmvlds-2} satisfies,
    for all $t \ge T$,
   $r\in [\tau - {2} \rho, \tau]$
    and $\varepsilon \in (0, \varepsilon^{*})$, 
   \begin{align*}
	    & \mathbb{E}
	             \left[ \sup_{r \in [\tau - { 2}\rho,\tau]}
	                                   \|u(r;\tau-t,\varphi)\|^{\theta}
    	         \right]  
    	     + \mathbb{E}
	 	                         \left[ \int_{\tau-t}^{r} e^{\beta (s-r)}
	 	                                       \|u(s;\tau-t, \varphi)\|^{\theta} ds
	 	                         \right]  \nonumber\\
	    & + \mathbb{E}
	 	                     \left[ \int_{\tau-t}^{r} e^{\beta (s-r)}
	        	                              \|u(s;\tau-t, \varphi)\|^{\theta-2}
	 	                                  \|u(s;\tau-t, \varphi)\|_p^{\,p} ds
	 	                     \right]  \nonumber\\
   \le & C_{\beta,\theta, \rho}
                  \int_{-\infty}^{\tau} e^{\beta (s-\tau)}
	                  \Big( \|g(s)\|^{\theta}
	                           + \|h(s)\|^{\theta}
	                           + \|\widetilde{h}(s)\|^{\theta}_{L^{\theta}(\mathbb{Y}, \nu; \ell^2)}
	                           + \|\widetilde{h}(s)\|^{\theta}_{L^{2}(\mathbb{Y}, \nu; \ell^2)}
	                  \Big) ds                           
	         + C_{\beta,\theta, \rho},
   \end{align*} 
   where 
   $\varphi \in L^{\theta}(\Omega, \mathcal{F}_{\tau - t}; D_{\rho})$ with law $\mathcal{L}_{\varphi} \in D(\tau-t)$,
   and 
   $C_{\beta, \theta, \rho} > 0$ is a constant depending on $\beta$, $\theta$ and $\rho$, but not on $\varepsilon$.

