[Theorem 6 of arXiv:2605.25719, 'A note on convergence rate for reflected BSDEs with quadratic generators by penalization m'] Let assumptions $(A1^{'})$, $(A2)-(A4)$ and $(H)$ be satisfied, then for $p \geq 2$,
\begin{equation}
\Vert Y^{n,\lambda}-Y \Vert_{\mathcal{S}^{p}(\mathbb{R})} \leq C_p\sqrt{\frac{\lambda^{max\{8-4\varepsilon,\frac{8}{\epsilon}-4\}}}{n^{\varepsilon+1}}+\frac{\lambda^{2}}{n}+\frac{1}{\lambda}}.
\end{equation}
\begin{proof}
For any $i=1,\dots,n$, applying It\^{o}'s formula to $e^{2\overline{C}t}\vert Y^{n,i,\lambda}_{t}-Y^{\lambda}_{t} \vert^{2}$ in the interval $[T_{n-i},T_{n-i+1}]$ yields that
\begin{equation*}
\begin{aligned}
&e^{2\overline{C}t}\vert Y^{n,i,\lambda}_{t}-Y^{\lambda}_{t} \vert^{2}+\int_{t}^{T_{n-i+1}}2e^{2\overline{C}s}(Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s})(Z^{n,i,\lambda}_{s}-Z^{\lambda}_{s})dW_{s} \\
&+\int_{t}^{T_{n-i+1}}e^{2\overline{C}s}\vert Z^{n,i,\lambda}_{s}-Z^{\lambda}_{s} \vert^{2}ds \\
=&e^{2\overline{C}T_{n-i+1}}\vert Y^{n,i,\lambda}_{T_{n-i+1}}-Y^{\lambda}_{T_{n-i+1}} \vert^{2} - \int_{t}^{T_{n-i+1}}2\overline{C}e^{2\overline{C}s}\vert Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s} \vert^{2}ds \\
&+\int_{t}^{T_{n-i+1}}2e^{2\overline{C}s}(Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s})\left[ f^{\lambda}(s,E^{\mathcal{F}_{s}} [ Y_{T_{n-i+1}}^{n,i-1,\lambda} ],Z_{s}^{n,i,\lambda})-f^{\lambda}(s,Y_{s}^{\lambda},Z_{s}^{\lambda}) \right]ds\\
\leq&e^{2\overline{C}T_{n-i+1}}\vert Y^{n,i,\lambda}_{T_{n-i+1}}-Y^{\lambda}_{T_{n-i+1}} \vert^{2} - \int_{t}^{T_{n-i+1}}2\overline{C}e^{2\overline{C}s}\vert Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s} \vert^{2}ds \\
&+\int_{t}^{T_{n-i+1}}2e^{2\overline{C}s}(Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s})\left[ f^{\lambda}(s,E^{\mathcal{F}_{s}} [ Y_{T_{n-i+1}}^{n,i-1,\lambda} ],Z_{s}^{n,i,\lambda})-f^{\lambda}(s,Y_{s}^{\lambda},Z_{s}^{n,i,\lambda}) \right]ds\\
&+\int_{t}^{T_{n-i+1}}2e^{2\overline{C}s}(Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s})\left[ f^{\lambda}(s,Y_{s}^{\lambda},Z_{s}^{n,i,\lambda})-f^{\lambda}(s,Y_{s}^{\lambda},Z_{s}^{\lambda}) \right]ds.
\end{aligned}
\end{equation*}
We write 
\begin{equation*}
f^{\lambda}(t,Y_{t}^{\lambda},Z_{t}^{n,\lambda})-f^{\lambda}(t,Y_{t}^{\lambda},Z_{t}^{\lambda})=\beta_{t}^{n,\lambda}(Z^{n,\lambda}_{t}-Z^{\lambda}_{t}), t \in [0,T].
\end{equation*}
Then we have $\vert \beta_{t}^{n,\lambda} \vert \leq \overline{C}(1+\vert Z^{n,\lambda}_{t} \vert+\vert Z^{\lambda}_{t} \vert)$ and  
\begin{equation*}
\sup \limits_{n\in \mathbb{N}} \left\{ \Vert \beta^{n,\lambda}\cdot W \Vert_{BMO} \right\} \leq C_{\lambda}
\end{equation*}
from Lemma \ref{l2} and \ref{boundary_lemma}. We define $W_{t}^{n,\lambda}=W_{t}-\int_{0}^{s}\beta_{s}^{n,\lambda}ds$ under an equivalent probability measure $dP^{n,\lambda}=\mathcal{E}(\beta_{s}^{n,\lambda}\cdot W)_{0}^{T}dP$. The inequality can be written as 
\begin{equation*}
\begin{aligned}
&e^{2\overline{C}t}\vert Y^{n,i,\lambda}_{t}-Y^{\lambda}_{t} \vert^{2}+\int_{t}^{T_{n-i+1}}2e^{2\overline{C}s}(Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s})(Z^{n,i,\lambda}_{s}-Z^{\lambda}_{s})dW_{s}^{n,\lambda} \\
&+\int_{t}^{T_{n-i+1}}e^{2\overline{C}s}\vert Z^{n,i,\lambda}_{s}-Z^{\lambda}_{s} \vert^{2}ds \\
\leq & e^{2\overline{C}T_{n-i+1}}\vert Y^{n,i,\lambda}_{T_{n-i+1}}-Y^{\lambda}_{T_{n-i+1}} \vert^{2} - \int_{t}^{T_{n-i+1}}2\overline{C}e^{2\overline{C}s}\vert Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s} \vert^{2}ds \\
&+\int_{t}^{T_{n-i+1}}2e^{2\overline{C}s}(Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s})\left[ f^{\lambda}(s,E^{\mathcal{F}_{s}} [ Y_{T_{n-i+1}}^{n,i-1,\lambda} ],Z_{s}^{n,i,\lambda})-f^{\lambda}(s,Y_{s}^{\lambda},Z_{s}^{n,i,\lambda}) \right]ds\\
\leq & e^{2\overline{C}T_{n-i+1}}\vert Y^{n,i,\lambda}_{T_{n-i+1}}-Y^{\lambda}_{T_{n-i+1}} \vert^{2}+ \int_{t}^{T_{n-i+1}}2e^{2\overline{C}s} \vert Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s} \vert \vert E^{\mathcal{F}_{s}} [ Y_{T_{n-i+1}}^{n,i-1,\lambda} ]-Y^{n,i,\lambda}_{s}\vert ds \\
&+\int_{t}^{T_{n-i+1}}2e^{2\overline{C}s} \vert Y^{n,i,\lambda}_{s}-Y^{\lambda}_{s} \vert \vert \lambda (E^{\mathcal{F}_{s}} [ Y_{T_{n-i+1}}^{n,i-1,\lambda} ]-S_{s})^{-}-\lambda(Y^{\lambda}_{s}-S_{s})^{-}\vert ds
\end{aligned}
\end{equation*}
