[Proposition e.1282aN of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] We have 
\begin{equation}
  \begin{split}
    \frac{d {\mathbf{H}}_N^{(V)}(t;f_N) }{dt}=& \int_{\Omega_N}  {\mathcal S}^{(\alpha)}_N   \mathcal{Q}^{(N)}_V(t,u;
 f_N)   \log \mathcal{Q}^{(N)}_V(t,u;
 f_N)  
 \nu_{S}^{(N)} (du) \\
 &
 +\mathbf{E}_{{\mu_N(0)}} {\frak
  l}_{N,V}\Big(u_{N,V}(t) \Big).
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pr:norm<N of arXiv:2510.00214, 'On the local well-posedness of randomly forced reaction-diffusion equations with $\bm{L^2}'] Choose and fix real numbers $\alpha>0$, $\beta\ge1$, $\tau,\mu\in(0\,,1)$, and 
	let $\{X(t\,,x)\}_{(t,x)\in \mathscr{D}(\infty)}$ denote a space-time random field
	such that, for some $k \ge 4(\tau^{-1}+\mu^{-1})$,
	\begin{equation}
		C = \adjustlimits\sup_{\varepsilon\in(0,1)}\sup_{t>0}\sup_{0\le x<y\le1}\left(
		\frac{t^\alpha\mathrm{e}^{- \beta t}\|X(t+\varepsilon\,,x) - X(t\,,y)\|_k}{
		\varepsilon^\tau \vee |x-y|^\mu}\right)<\infty.
	\end{equation}
	Then, $\E( \|X\|_{\mathscr{C}_\infty(\bar\alpha,\bar\beta)}^k)
	\le (1280L)^k[ \mathcal{N}_{k,\alpha,\beta,\infty}(X)+C]^k$
	for all $\bar\alpha>\alpha$ and $\bar\beta > \beta$,
	where
	\begin{equation}\begin{split}	
		L = L(\alpha\,,\bar\alpha\,,\beta\,,\bar\beta) =
		\max\left( \frac{2^{\bar\alpha}}{2^{\bar\alpha-\alpha} - 1}
		~, \sum_{n=0}^\infty (n+1)^{\bar\alpha+\alpha}\
		\mathrm{e}^{-n(\bar\beta-\beta)/\beta}\right).
	\end{split}\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2609.02581, '\bfseries Interior Curvature Estimates for the Graphical Scalar Curvature Equation in All '] Suppose that \(u\) and \(v\) satisfy \eqref{u} and \eqref{v}. Then there is \(C=C(n,K,\lambda_u,\lambda_v)\) such that
\begin{equation}
 v(y)-u(y)\geq d(y)\geq C^{-1}
 \qquad (\forall~ y\in B_{1/2}).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem main of arXiv:2608.30575, 'A Counterexample to Belinsky's Conjecture on Ces\`aro Means at Lebesgue Points'] There exist a strictly convex increasing sequence $(a_m)$ of positive
integers and a function $f\in L^1(\mathbb T)$ such that
\begin{enumerate}
 \item[(a)] $a_m\leq7m^8$ for every $m\geq1$;
 \item[(b)] $0$ is a Lebesgue point of $f$ and $f(0)=0$;
 \item[(c)]
 \begin{equation*}
  \sup_{m\geq1}\left|\frac{1}{m}\sum_{k=1}^mS_{a_k}f(0)\right|=\infty.
 \end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:ricci-scalar-dimer of arXiv:2608.29403, 'Kac's Walk on Rotation Matrices Mixes in $\boldsymbol{\Theta(n^2)}$ Steps:\\ A Proof Disco'] Let
\[
 \mathcal C_{1,{\rm R}}
 =\sum_{t=1}^m[A_t,X_{\mathfrak B^-_{t-1}}]v_t,
\]
and let $\mathcal C_{k,{\rm R}}^{\rm dim}$ be the part of the
Christoffel--Darboux/monomer--dimer expansion in which every factor on
both sides of the Ricci root is a recurrence dimer.  Then
\[
 \boxed{
 \mathcal C_{k,{\rm R}}^{\rm dim}
 =\mathbf1_{\{k\ \mathrm{odd}\}}\frac{k+1}{2}
   (-\gamma)^{(k-1)/2}\mathcal C_{1,{\rm R}}.}
\tag{3.3.1w$_{12k_0}$}
\]
Moreover
\[
 \boxed{
 \mathbb E\|\mathcal C_{1,{\rm R}}\|^2
 \le\frac{m(m-1)}{Nn},
 \qquad
 \mathbb E\|\mathcal C_{k,{\rm R}}^{\rm dim}\|^2
 \le Cn c^{k+1}(k+1)^2.}
\tag{3.3.1w$_{12k_1}$}
\]

[Lm Supremum Lemma of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] For some constants $C,c(T)>0$. We have the following sub-Gaussianity estimates. For any $u,\epsilon>0$ we have
    \begin{gather}
        \mathbb{P}\bigg(\sup_{t \in [0,T]}(||\theta(t)||-1)>\frac{u}{\sqrt{n}}\bigg) \leq  Ce^{-c(T)\frac{u^2}{\log(n)}},\\
     \mathbb{P}\bigg(\sup_{t \in [0,T]}||M(t)||_{op}-(2+\epsilon)\sqrt{n}>u\bigg) \leq Ce^{-c(T)\frac{u^2}{\log(n)}},\\ 
    \mathbb{P}\bigg(\sup_{t\in [0,T]}|\Tilde{G}(M(t)/\sqrt{n},\theta(t))-\mathbb{E}[\Tilde{G}(M(t)/\sqrt{n},\theta(t))]|>u\bigg) \leq Ce^{-c(T)\frac{nu^2}{\log(n)}}.
    \end{gather}

