body:
[Lemma lem:pole-form-ledger of arXiv:2608.16119, 'Fully nonlinear parabolic equations under a fixed reference diffusion: weighted \texorpdfs'] There exists a constant $C=C(T,\lambda,\Lambda)>0$ such that the following assertions hold
under (equation eq:pole-coefficient-class of the paper).  For every $0<t\leq T$,
$q\in C_c^\infty(\mathbb R^d)$, and $\delta>0$,
\begin{equation}
 \begin{aligned}
 \int\mathscr R_t^{\mathrm{pole}}(\nabla^{g_t}q,\nabla^{g_t}q)\,\mathrm d\gamma_t
 \geq{}&-2\delta\int|D_y^2q|^2\,\mathrm d\gamma_t\\
 &-C\Bigl[
   \sqrt d\bigl(M_2+K_1\bigr)+M_1^2+K_0
   +\delta^{-1}\bigl(M_1^2+K_1^2\bigr)\Bigr]
   \int|D_yq|^2\,\mathrm d\gamma_t.
 \end{aligned}

\end{equation}
For every $0<\theta<1$ and
$K\geq C\theta^{-1}\mathcal M_d(a)$, the same $t,q$ satisfy
\begin{equation}
 \int\mathscr R_t^{\mathrm{pole}}(\nabla^{g_t}q,\nabla^{g_t}q)\,\mathrm d\gamma_t
 +\theta\int|\operatorname{Hess}_{g_t}q|_{g_t}^2\,\mathrm d\gamma_t
 +K\int|\nabla^{g_t}q|_{g_t}^2\,\mathrm d\gamma_t\geq0.

\end{equation}
This estimate extends to the form domain as follows.  Fix
$\alpha,\kappa\geq0$, let $K\geq K_\theta^\star(a)$, and put
$w=w_{\alpha,K;\kappa}$.  If $0\leq r_0<r_1\leq T$ and
$I=(r_0,r_1)$, then every
$q\in\mathfrak C_{\rm B}(I,w)$ satisfies, for $I_\tau=(\tau,r_1)$ and every
$\tau\in I$,
\begin{equation}
 \begin{aligned}
 &\int_{I_\tau\times\mathbb R^d}
   \mathscr R_{w,t}(\nabla^{g_t}q,\nabla^{g_t}q)\,\mathrm d\mathfrak m
   +\theta\norm{\operatorname{Hess}_gq}_{w,g;I_\tau}^2\geq
 \int_{I_\tau\times\mathbb R^d}
  \left(\frac{2\alpha-1}{t}+4\kappa\right)
  w|\nabla^{g_t}q|_{g_t}^2\,\mathrm d\mathfrak m.
 \end{aligned}

\end{equation}
Moreover, for every $0<r\leq T$, put
$\mathsf A_r(s,\xi)=a(rs,\sqrt{rs}\,\xi)$, $0<s\leq1$.
\begin{equation}
 \sup_{0<s\leq1}\frac1s\left(
  \left\lVert \mathsf A_r(s)-I_d\right\rVert_{L^4(\gamma_d;\mathrm{op})}
 +\left\lVert D_\xi\mathsf A_r(s)\right\rVert_{L^4(\gamma_d)}
 \right)
 \leq C\bigl(\sqrt d\,M_2+K_0+K_1\bigr)r.

\end{equation}
The remaining scaled jet bounds are
\begin{equation}
 \begin{aligned}
  \sup_{0<s\leq1}\left\lVert D_\xi\mathsf A_r(s)\right\rVert_{\infty}
  &\leq M_1\sqrt r, \qquad
  \sup_{0<s\leq1}\frac1s
  \left\lVert D_\xi^2\mathsf A_r(s)\right\rVert_{\infty}
  \leq rM_2.
 \end{aligned}

\end{equation}
Here and in the proof, the argument $a$ in the coefficient profiles is
suppressed.

