body:
[Proposition prop:ZIM_tree_monotonicity_mu of arXiv:2607.29409, 'The Zombie Infection Model'] Consider a tree $G=(V,E)$, parameters
		$\mu,\lambda \in (0,\infty)$ and $c\geq1$, and an initial set $\Delta \subset V$ consisting of one connected cluster. Then the following holds:
		\begin{enumerate}[label=\alph*)]
			\item  There is a coupling $\widehat{\BP}^{\ZIM}$ of $\big(\eta_{t}^{(1)}\big) \sim\BP^{\ZIM}_{\lambda,\mu,G,\Delta}$ and $\big(\eta_{t}^{(2)}\big)\sim
				\BP^{\ZIM}_{\lambda, c\mu,G,\Delta}$ such that
				\begin{equation}
					\widehat{\BP}^{\ZIM}\!\left( \eta_{t}^{(1)}
					\geq \eta_{t}^{(2)}\: \forall \: t\in [0,\infty) \right) =1.
				\end{equation}

			\item  There is a coupling $\widehat{\BP}^{\SIR}$ of $\big(\xi_{t}^{(1)}\big) \sim\BP^{\SIR}_{\lambda,\mu,G,\Delta}$ and $\big(\xi_{t}^{(2)}\big)\sim
				\BP^{\SIR}_{\lambda, c\mu,G,\Delta}$ such that
				\begin{equation}
					\widehat{\BP}^{\SIR}\!\left( \xi_{t}^{(1)}
					\geq \xi_{t}^{(2)}\: \forall \: t\in [0,\infty) \right) =1.
				\end{equation}
		\end{enumerate}

[Definition 5 of arXiv:2608.05185, '\large\bf ON THE HEAT FLOW CONJECTURE FOR RANDOM MATRICES'] For \(z=x+\mathrm{i}y\), write
\(\dd A(z)=\dd x\,\dd y\) for planar Lebesgue measure.
We use the notation
\[
 \D=\{z\in\C:|z|<1\},
 \qquad
 \mathscr{D}(z,r)=\{w\in\C:|w-z|<r\}
 \quad (z\in\C,\ r>0).
\]
For \(S>0\) and \(c\in\C\) with \(\left|c\right|<S\), define
\begin{equation}
 \mathscr{E}_{S,c}
 \overset{\mathrm{def}}{=}
 \left\{\sqrt{S}\,u+\frac{c}{\sqrt{S}}\overline{u}:
                 u\in\C,\ \left|u\right|\leq1\right\},
\end{equation}
If \(c=\left|c\right|\mathrm{e}^{2\mathrm{i}\theta}\), this ellipse has
semiaxes \(\sqrt{S}\pm\left|c\right|/\sqrt{S}\) and is rotated through
\(\theta\).  Let \(\mu_{S,c}\) be its normalised planar area measure.
Equivalently,
\begin{equation}
 \dd\mu_{S,c}(z)
 =\frac{S}{\pi(S^2-\left|c\right|^2)}
 \mathbf{1}_{\mathscr{E}_{S,c}}(z)\dd A(z).
\end{equation}

