body:
[Prop 9 of arXiv:2606.17472, '2606.17472'] Let $n\ge 2$ and $a_1<\cdots <a_n$. Then the following statements hold:
\begin{enumerate}
  \item If $h(x)=0$ for $x<0$, then
  \begin{align*}
    \mu_{\{a_1,...,a_n\}}(dy)=\delta_{a_n}(dy),\qquad k(\{a_1,...,a_n\})=0.
  \end{align*}
   \item If $h(x)=0$ for $x>0$, then
  \begin{align*}
    \mu_{\{a_1,...,a_n\}}(dy)=\delta_{a_1}(dy),\qquad k(\{a_1,...,a_n\})=0.
  \end{align*}
  \item If $h(x)>0$ for $x\neq 0$, then
  \begin{gather*}
    \mu_{\{a_1,...,a_n\}}(dy)=\frac{1}{\bm{1}^T\bm{H}^{-1}\bm{1}}\sum_{i=1}^n (\bm{H}^{-1}\bm{1})_i\delta_{a_i}(dy),\\
    k(\{a_1,...,a_n\})=\frac{1}{\bm{1}^T\bm{H}^{-1}\bm{1}}.
  \end{gather*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2606.08115, '2606.08115'] Let sequences $\{a_n\}_{n \in \mathbb{N}}$, $\left\{\delta_{n, m}\right\}_{n, m \in \mathbb{N}}$, $\left\{b_{n, m}\right\}_{n, m \in \mathbb{N}}$ be such that the equality $a_n = \delta_{n, m} + b_{n, m}$ takes place for every natural $n, m$. Assume that the following conditions are valid:
\begin{enumerate}
\item[1)] $\delta_{n, m} \ge 0$, $b_{n, m} \ge 0$ for $n$, $m \in \mathbb{N}$;
\item[2)] $\displaystyle \varliminf\limits_{m \to \infty} \varlimsup\limits_{n \to \infty} \delta_{n, m} = 0$;
\item[3)] for every natural $m$ there exists the finite limit $\displaystyle \lim_{n \to \infty} b_{n, m} =: b_{m}$.
\end{enumerate}
Then $a:= \displaystyle \lim_{n \to \infty} a_n = \lim_{m \to \infty} b_{m}< \infty.$ Moreover, if $b_m > 0$ for some $m$, then $a > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 25 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] Under the conditions of Theorem \ref{t.050601}, we have 
  \begin{align*}
    \lim _{R \rightarrow \infty} \limsup _{\varepsilon \rightarrow 0} \varepsilon \ln \mu_\sigma^{\varepsilon}\left(B_R^c\right)=-\infty, \quad m \text{-a.s.}.
  \end{align*}

