[Lemma 54 (Polynomial rearrangement and convolution tails) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Assume \eqref{eq:group-growth}.  If $0<\theta\le D$, $R\ge1$, and
$E\subset\Gamma$ is finite with $\#E\le C_0R^D$, then
\begin{align}

 \sum_{x\in E}\langle x\rangle^{-\theta}
 &\le C_{\Gamma,D,C_0,\theta}
 \begin{cases}
  R^{D-\theta},&0<\theta<D,\\
  \log(e+R),&\theta=D.
 \end{cases}
\end{align}
Moreover,
\begin{equation}

 \sum_{x\in E}\langle x\rangle^{-D}\log(e+\langle x\rangle)
 \le C_{\Gamma,D,C_0}\log(e+R)^2.
\end{equation}

Let $D/2<\alpha\le D$, put $\gamma:=2\alpha-D$, and define
\[
 H_\alpha(z):=
 \sum_{x\in\Gamma}
 \langle x\rangle^{-\alpha}
 \langle x^{-1}z\rangle^{-\alpha}.
\]
Then
\begin{equation}

 H_\alpha(z)\le C_{\Gamma,D,\alpha}
 \begin{cases}
  \langle z\rangle^{-\gamma},&D/2<\alpha<D,\\
  \langle z\rangle^{-D}\log(e+\langle z\rangle),&\alpha=D.
 \end{cases}
\end{equation}
For $M\ge1$, the truncated tail
\[
 H_{\alpha,>M}(z):=
 \sum_x
 \langle x\rangle^{-\alpha}
 \langle x^{-1}z\rangle^{-\alpha}
 \mathbf1_{\{\max(|x|,|x^{-1}z|)>M\}}
\]
satisfies
\begin{equation}

 H_{\alpha,>M}(z)\le C_{\Gamma,D,\alpha}
 \begin{cases}
  \max\{M,\langle z\rangle\}^{-\gamma},&D/2<\alpha<D,\\
  \max\{M,\langle z\rangle\}^{-D}
       \log(e+\langle z\rangle),&\alpha=D.
 \end{cases}
\end{equation}

[Definition 37 (Wick product) of arXiv:2605.14630, '2605.14630'] The \emph{Wick product} of $f\in\H^{\otimes n}$ and $g\in\H^{\otimes m}$
is defined by 
\begin{equation}
 \hat I_n(f) \diamond \hat I_m(g) = \hat I_{n+m}(f\otimes g)\;.
\end{equation}

[Lemma LemmaFiniteOccurrenceTimes of arXiv:2606.13615, 'Data-Driven Subsampling Rates for Diffusion Parameter Estimation of SDEs'] Suppose that Assumption~(Assumptions of the paper) holds and that (equation eqGenSDEIntro of the paper) admits an invariant measure $\mu$. Let $\mathbf{X}_0 \sim \mu$ be independent of $\mathbf{W}$, let $\mathbf{X} = (\mathbf{X}_t)_{t \geq 0}$ be the corresponding solution process to (equation eqGenSDEIntro of the paper) with $d$-th component $X = (X_t)_{t \geq 0}$, and assume that the ergodicity condition (equation eqErgoCond of the paper) is fulfilled. Then there exists a $\tilde{\delta} > 0$ such that 
\begin{equation*}
P(R_{j,\delta}(X) < \infty) = 1
\end{equation*}
for all $\delta \in (0, \tilde{\delta}]$ and all $j \in \mathbb{N}$.

