[Theorem thm:zerosZak of arXiv:2609.00481, 'The frameset of the second-order B-spline along $ab=1/q$'] Let $b\geq\frac{3}{2}$, $N=R(b)$, and $\varepsilon=F(b)$. For $(x,\gamma)\in[0,1)^2$, $(Z_{1/b}Q_2)(x,\gamma)=0$ only if $x\in[|\varepsilon|,1-|\varepsilon|]$, and moreover only if either
\begin{enumerate}[(i)]
    \item $\gamma=k/N$ for some $k\not\equiv0\pmod N$, in which case 
    \begin{align}
        (Z_{1/b}Q_2)(x,k/N)=0 \text{ for every } x\in[|\varepsilon|,1-|\varepsilon|]; 
    \end{align}
 or
    \item $\gamma$ satisfies
    \begin{align}
        \tfrac12\cot(\pi\gamma) + (b-N)\cot(N\pi\gamma) = 0, 
    \end{align}
    in which case $x=\tfrac12$ is the unique zero.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 10 of arXiv:2605.30560, 'Projected McKean--Vlasov Dynamics for Entropic Weak Optimal Transport'] For any $\pi \in \Pi(\mu,\nu)$, we formally identify the tangent space as
\begin{align}
T^{\rm ad}_{\pi}\left( \Pi(\mu,\nu)\right)
&\;\simeq\;
\Big(\overline{\nabla^{\rm ad}_{\pi}(\mathcal{V})}^{\,L^2(\pi)}\Big)^{\perp} \\
& \; = \;
\Big\{
g\in T^{\rm ad}_{\pi}\Pc_2(\R^{2d}):\
\int g(x,y)\cdot \nabla^{\rm ad}_{\pi} h(x,y) \, \pi(dx,dy)=0,
\ \ \forall \, h\in \mathcal{V}
\Big\}. \notag
\end{align}

[Defination 16 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] A  symmetric  matrix  $A \in \mathcal{M}_n(\mathbb{R})$ is 

							\begin{enumerate}
								\item positive definite if  $x^\top Ax>0$  for  all  nonzero $ x \in \mathbb{R}^n$;
								\item positive semi-definite if  $x^\top Ax \geq 0$  for  all  nonzero $ x \in \mathbb{R}^n$.
							\end{enumerate}

