				\partial_{m}\log f
				&= \frac{2(x-m)}{(x-m)^{2}+\gamma^{2}}
				= \frac{2\sin\theta\cos\theta}{\gamma}
				= \frac{\sin 2\theta}{\gamma},\\
				\partial_{\gamma}\log f
				&= \frac1\gamma - \frac{2\gamma}{(x-m)^{2}+\gamma^{2}}
				= -\frac{\cos 2\theta}{\gamma}.
			\end{align*}
			Hence
			$I_{mm} = \frac{1}{\pi\gamma^{2}}
			\int_{-\pi/2}^{\pi/2}\sin^{2}2\theta\,d\theta = \frac{1}{2\gamma^{2}}$,
			$I_{\gamma\gamma} = \frac{1}{\pi\gamma^{2}}
			\int_{-\pi/2}^{\pi/2}\cos^{2}2\theta\,d\theta = ...","release_manifest_digest":"sha256:bdd6ed0c25c8da38e0ef74e271753a8536548d7eec73ab45e51a8385cb661deb","revision_digest":"sha256:2b2ddd4f67517655e9413f18a995e3a7c8cb18261275843e5f4da6ce4a758ee8","source_id":"arxiv:2607.24705","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

