[Proposition prop:harmonic of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] Fix an input $x$ and a parameter $\theta$.
For every truncation order $T \ge 1$,
\begin{equation}
J^{(T)}_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{T} \frac{1}{k}\Big(\text{\emph{Best-of-}}k(\theta;x) - 1\Big),

\end{equation}
and if $J_{\mathrm{TailRL{}}}(\theta;x) > -\infty$, the same identity holds for the full series,
\begin{equation}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty} \frac{1}{k}\Big(\text{\emph{Best-of-}}k(\theta;x) - 1\Big).

\end{equation}

[Defn DefIntro: general polynomial process of arXiv:2605.16921, '${\ASL_n}(\mathbb Z)$ invariant random subsets of $\mathbb Z^n$'] With the data $(k, m, T, \pi, s)$ as above, let $\nu$ be the Haar probability measure on a closed subgroup of $T_{\leq k}[X_1, \ldots, X_d]$ stable under $P \mapsto \alpha(\gamma, x)(P) \circ \gamma^{-1}$ for every $\gamma \in \SL_d(\mathbb{Z})$, and let $f: T \to [0, 1]$ be a measurable function invariant under the range of $\alpha$. The associated \emph{polynomial point process} $\Lambda(k,m,T,\nu,\pi,s,f)$ on $\mathbb{Z}^d$ is obtained as follows:
    \begin{itemize}
        \item draw a random polynomial $\underline{P}$ according to $\nu$;
        \item independently across $t \in \mathbb{Z}^d$, keep $t$ with probability $f(\underline{P}(t))$.
    \end{itemize}

[Lemma 15 of arXiv:2606.27520, 'Critical curve of loop percolation on the $d$-regular tree'] For $n\geq 1$, 
    \begin{align}
    q_n = (1 - \tau_\kappa^{2})^\alpha (1 -\tau_\kappa^{2(n+1)})^{- \alpha}. 
    \end{align}

[Lemma 8 (Matrix development and the evaluated signature) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $q\geq1$, write $I=I_q$, let $\beta:[0,T_\beta]\to V$ be continuous and of bounded variation, and let $\Phi:V_{\C}\to M_q(\C)$ be complex linear. For $z\in\C$, let $U^z$ be the solution of the right matrix-development equation
\begin{equation}
\dd U_t^z=U_t^z\,z\Phi(\dd\beta_t),
\qquad U_0^z=I.
\end{equation}
Then
\begin{align}
U_{T_\beta}^z
&=I+\sum_{n\geq1}z^n
  \int_{0<t_1<\cdots<t_n<T_\beta}
  \Phi(\dd\beta_{t_1})\cdots\Phi(\dd\beta_{t_n}) \notag\\
&=\sum_{n\geq0}z^n\Phi^{(n)}\!\left(S_n(\beta)\right).

\end{align}
The series converges absolutely and locally uniformly in $z$, and
\[
\norm{U_{T_\beta}^z}
 \leq \exp\!\bigl(\abs{z}\,\norm{\Phi}\,L(\beta)\bigr).
\]
If $R(\log S(\beta))=\infty$ and
$\log S(\beta)=\sum_{n\geq1}b_n$, then
\begin{equation}
U_{T_\beta}^z
 =\exp\!\left(\sum_{n\geq1}z^n\Phi^{(n)}(b_n)\right).
\end{equation}

[Lemma 17 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, $D\subset \widetilde{\mathbb{Z}}^d$ and $v\neq w\in  \widetilde{\mathbb{Z}}^d\setminus D$, the total mass of the measure $\mathbf{e}_{v,w}^{D}$ equals to $\mathbb{K}_{D\cup \{v,w\}}(v,w)$. Consequently,
		\begin{equation}
		\bar{\mathbf{e}}_{v,w}^{D}(\cdot):= [\mathbb{K}_{D\cup \{v,w\}}(v,w)]^{-1}\cdot \mathbf{e}_{v,w}^{D}(\cdot)
	\end{equation}
	defines a probability measure.

