\begin{equation}
 \mathbb{E}\tau_p(\epsilon;f_0)
 \le \frac{n}{\lambda_p(G)}
 \left[
 \log\!\left(
 \frac{2^p|E|D^{p-1}}{\epsilon^p}
 \right)+3
 \right].
