[Defn 4 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] For a fixed integer $N$, let $\mathcal{C}_1,\dots,\mathcal{C}_N$ be a collection of positively oriented closed complex integration contours satisfying:
    \begin{itemize}
        \item For all $1\leq i\leq N$, each contour $\mathcal{C}_i$ encloses the point 1 and does not enclose the points $0,q^{-1}$ and $(1-q-\alpha)/\alpha$.
        \item For all $1\leq i<j\leq N$, each $\mathcal{C}_i$ is completely contained within the interior of each $\mathcal{C}_j$. Additionally, $q\mathcal{C}_j$ lies completely outside the interior of $\mathcal{C}_i$, where $q\mathcal{C}_j$ denotes the image of $\mathcal{C}_j$ under multiplication by $q$. This also implies that no part of $\mathcal{C}_j$ is contained within the interior of $q^{-1}\mathcal{C}_i$.
        \item For all $1\leq k,\ell\leq N$, the contours $\mathcal{C}_k$ and $q^{-1}\mathcal{C}_\ell^{-1}$ do not intersect and have completely disjoint interiors. The contour $\mathcal{C}_\ell^{-1}$ is the contour which traverses the points which are the reciprocal of those on $\mathcal{C}_\ell$, and whose orientation is fixed so that $q^{-1}\mathcal{C}_\ell^{-1}$ encloses the point $q^{-1}$.
    \end{itemize}

[Lemma lem:good_convergence of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Jointly with~(equation eq cv subsequence of the paper),~(equation eq cv Hausdorff balls of the paper) and~(equation eq cv subsequence boundary of the paper), for all $t \in \BQ_{\ge 0}$, $x \in \BD_\BQ$, $\alpha \in \SCS'$, along a subsequence again denoted by $(\kappa_n)_{n \ge 0}$, we have
	\begin{equation*}
		\left(
		\SCB^{\kappa_n, \partial}_{\ka_{\kappa_n} s}(\SCB_{\ka_{\kappa_n}t}^{\kappa_n} (\SCL^{\kappa_n}(x))), \SCB^{\kappa_n, \partial}_{\ka_{\kappa_n} s}(\SCB_{\ka_{\kappa_n}t}^{\kappa_n} (\alpha))
		\right)_{s \in \BQ_{\ge 0}}
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( 
		\SCB^\partial_{ s}(\SCB_{t} (\SCL(x))), \SCB_{ s}^\partial(\SCB_{t} (\alpha))
		\right)_{s \in \BQ_{\ge 0}},
	\end{equation*}
	for the product topology where each component is equipped with the Hausdorff topology and $(\SCB^\partial_{ s}(\SCB_{t} (\alpha)))_{s\ge 0}$ (resp.~$(\SCB_{ s}^\partial(\SCB_{t} (\SCL(x))))_{s\ge 0}$) has the same law as a collection of independent uniform explorations of the $\CLE_4$, started from the whole boundary of each connected component of $\BD \setminus \SCB_{t}(\alpha)$ (resp.~$\BD \setminus\SCB_{t}(\SCL(x))$). Moreover, jointly with~(equation eq cv subsequence of the paper),~(equation eq cv Hausdorff balls of the paper),~(equation eq cv subsequence boundary of the paper), and the above convergence, for all $t \in \BQ_{\ge 0}$, $x,y \in \BD_\BQ$, $\alpha \in \SCS'$,
	\begin{equation}

		\left(K^{\kappa_n, \partial}_{\SCB_{\ka_{\kappa_n} t}^{\kappa_n} (\alpha), \SCL^{\kappa_n}(y)}, K^{\kappa_n, \partial}_{\SCB_{\ka_{\kappa_n} t}^{\kappa_n} (\SCL^{\kappa_n}(x)), \SCL^{\kappa_n}(y)} \right)
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( K^\partial_{\SCB_t(\alpha), \SCL(y)}, K^\partial_{\SCB_t(\SCL(x)), \SCL(y)}
		\right),
	\end{equation}
	for the Hausdorff topology, where $K^\partial_{\SCB_t(\alpha), \SCL(y)}, K^\partial_{\SCB_t(\SCL(x)), \SCL(y)}$ are random compact subsets of $\overline{ \BD}$.

[Lemma lem:s3 of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] Let $b$ be an eternal solution, and assume there exists $s \in \mathbb{R}$ such that $\pmb{\xi}^{b,s}$ contains at least two colors. Then, for all $x \in \mathbb{R}$,
  \begin{equation}

  \begin{aligned}
         &\quad \;b(x,s)-b(\mathfrak{a}_{\xi_0},s) \\
         &=
         \begin{cases}
            \sum_{j=0}^{i-1}W^{\xi_j}\left(\mathfrak{a}_{\xi_j},s;\mathfrak{a}_{\xi_{j+1}},s \right)+W^{\xi_{i}}\left({\mathfrak{a}_{\xi_{i}},s;x,s}\right) & x\in[\mathfrak{a}_{\xi_i},\mathfrak{a}_{\xi_{i+1}}), i \in \mathbb{Z}_{\ge 0}\\
             -\sum_{j=i+1}^{-1}W^{\xi_j}\left(\mathfrak{a}_{\xi_{j}},s;\mathfrak{a}_{\xi_{j+1}},s\right)+W^{\xi_i}(\mathfrak{a}_{\xi_{i+1}},s;x,s) & x\in(\mathfrak{a}_{\xi_i},\mathfrak{a}_{\xi_{i+1}}], i \in \mathbb{Z}_{< 0},
         \end{cases}
         \end{aligned}
     \end{equation}
     where we have used the shorthand notation $\xi_i = \xi_i^s$ and $\mathfrak{a}_\xi = \mathfrak{a}_\xi^s$ for our particular choice of $s$. Here, in the $i = 0$ and $i = -1$ cases, we interpret the empty sum $\sum_{j = 0}^{-1}$ as $0$.

[Definition def:extFLE of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] For $\mathbf{x}, \mathbf{y} \in \mathbb{A}_+^n$ and functions
$\mathbf{f}, \mathbf{g}: (\ell,r) \to \mathbb{A}_+^n$ with $\mathbf{f} \prec \mathbf{g}$ and $\bm{\lambda} : (\ell,r) \to \mathbb{R}^n$,
let  $\mathcal{L}^{\mathbf{x},\mathbf{y},\bm{\lambda}}_{n,\ell,r,\mathbf{f},\mathbf{g}}$ denote the probability measure
with the following Radon--Nikodym derivative relative to the
Brownian bridge measure $\mathcal{B}^{\mathbf{x},\mathbf{y}}_{n,\ell,r}$:
\begin{equation}
    \frac{d\mathcal{L}^{\mathbf{x},\mathbf{y},\bm{\lambda}}_{n,\ell,r,\mathbf{f},\mathbf{g}}}{d\mathcal{B}^{\mathbf{x},\mathbf{y}}_{n,\ell,r}}(\mathbf{X}_n)
    \propto \Exp{-2 \sum_{i=1}^n \int_\ell^r \lambda^i(t) X^i_n(t) \,dt}
    \ind{\mathbf{X}_n(t) \in \mathbb{A}_+^n \text{ for all } t \in [\ell,r]}
    \mathbf{1}_{\{\mathbf{f} \prec \mathbf{X}_n \prec \mathbf{g}\}}.
\end{equation}
Note that to recover the geometrically increasing area tilts, we should
take $\bm{\lambda}(t) \equiv (1,\lambda,\lambda^2,\dotsb,\lambda^{n-1})$.

[Definition def:phi_i of arXiv:2605.10491, 'Zero-couplings of infinite measures with cyclically monotone support and multivariate regu'] Let $\bar\gamma$ be a Borel measure on $\reals^d\times\reals^d$. The left and right marginals, zero-marginals of $\bar\gamma$ are defined as the measures $\phi_1 \bar\gamma, \phi_2 \bar\gamma$ and $\varphi_1 \bar\gamma, \varphi_2 \bar\gamma$ respectively where
    \begin{align*}
        \phi_1 \bar\gamma(A) = \bar\gamma(A \times \mathbb{R}^d)
        \quad &\text{and} \quad
        \phi_2 \bar\gamma(A) = \bar\gamma(\mathbb{R}^d \times A) 
        \quad \text{for $A \in \mathcal{B}(\mathbb{R}^d)$,}
        \\
        \varphi_1 \bar\gamma(A) = \bar\gamma(A \times \mathbb{R}^d)
        \quad &\text{and} \quad
        \varphi_2 \bar\gamma(A) = \bar\gamma(\mathbb{R}^d \times A) 
        \quad \text{for $A \in \mathcal{B}(\reals^d_{\smallsetminus 0})$.}
    \end{align*}
    For a Borel measure $\gamma$ on $(\reals^d\times\reals^d)\setminus\{0\}$ we define $\phi_i\gamma=\phi_i\tilde\gamma$ for $i=1,2$ where $\tilde\gamma$ is the extension of $\gamma$ with $\tilde\gamma\rbr{\left\{0\right\}}=0$.

[Lemma 7 of arXiv:2505.20799, 'A note on the improved sparse Hanson-Wright inequalities'] Let $\xi$ be a random variable such that for $r\ge r_{0}$
	\begin{align}
		\Vert \xi\Vert_{L_r}\le \sum_{k=1}^{m}C_{k}r^{\beta_{k}}+C_{m+1},\nonumber
	\end{align}
	where $C_{1},\cdots, C_{m+1}> 0$ and $\beta_{1},\cdots, \beta_{m}>0$. Then for $t>0$,
	\begin{align}
		\mathbb{P}\big\{ \vert \xi\vert>e(mt+C_{m+1}) \big\}\le e^{r_{0}}\exp\Big(-\min\big\{\big(\frac{t}{C_{1}}\big)^{1/\beta_{1}},\cdots, \big(\frac{t}{C_{m}}\big)^{1/\beta_{m}}\big\}\Big).\nonumber
	\end{align}

