body:
[Theorem 19 ($\AW_2$ between Gaussian distributions) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] { \ }
\begin{itemize}
\item[(i)] For any Gaussian distribution $\mu = \cN(a, A)$, where $(a, A) \in \bR^{Nd} \times \mathscr{S}_+(Nd)$, we have
\begin{equation} 
\AW_2(\bG^{a, \cC_{\min}(A)}, \bX^{\mu}) = 0,
\end{equation}
where $\bX^{\mu}$ is the canonical representation given in Definition \ref{def:embedding}.
\item[(ii)] For $\mu = \cN_{Nd}(a, A)$ and $\nu = \cN_{Nd}(b, B)$, we have
\begin{equation} 
\AW_2^2(\mu, \nu) =  \|a - b\|_2^2 + \dist_{\AW}^2(\cC_{\min}(A), \cC_{\min}(B)).
\end{equation}
\end{itemize}

