[Corollary cor: GNZwithoutAdditionalInfluence of arXiv:2411.02917, '\hspace*{2mm}\\[-16mm] Stein's Method for Spatial Random Graphs'] Let $(\Xi, \Sigma) \sim P \otimes Q$ be a random graph with the property that the distribution of the edge process $\Sigma\vert_{\xi^{\langle2\rangle}}$ given $\Xi=\xi+\delta_x$ is the same as given $\Xi=\xi$ for $P$-a.e.\ $\xi$.
  Then we have for any measurable function $h:\mathfrak{N} \times \mathfrak{N}_2 \times \mathcal{X} \times \mathfrak{N}_2 \to \R_+$
  \begin{equation*}
  \begin{split}
      \E \biggl(\int_{\mathcal{X}} &h \bigl(\Xi-\delta_x, \Sigma \vert_{(\Xi-\delta_x)^{\langle2\rangle}}, x, \Sigma \vert_{\langle \Xi-\delta_x,x \rangle} \bigr) \; \Xi(dx) \biggr) \\
      &= \E \biggl( \int_{\mathcal{X}} \E \Bigl( h \bigl(\Xi, \Sigma, x, \Tilde{\Sigma}_{\Xi,\Sigma,x} \bigr) \Bigm| \Xi, \Sigma \Bigr) \; L(dx \,|\, \Xi) \biggr),
  \end{split}
  \end{equation*}
  where $\Tilde{\Sigma}_{\xi,\sigma,x}$ is the random element on $\mathfrak{N}_2$ with distribution $\mathcal{L} \bigl( \Sigma \vert_{\langle \xi, x \rangle} \bigm| \Xi = \xi+\delta_x, \Sigma \vert_{\xi^{\langle2\rangle}} = \sigma \bigr) = \tilde{Q}_{2 \,|\, 1}(\xi,x,\sigma ;\, \cdot)$.

  In particular, if $h$ is constant in the last argument,
  \begin{equation*}
  \begin{split}
      \E \biggl( \int_{\mathcal{X}} &h \bigl(\Xi-\delta_x, \Sigma \vert_{(\Xi-\delta_x)^{\langle2\rangle}}, x\bigr) \; \Xi(dx) \biggr) = \E \biggl( \int_{\mathcal{X}} h \bigl(\Xi, \Sigma, x\bigr) \; L(dx \,|\, \Xi) \biggr).
  \end{split}
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2505.10256, 'Stochastic Oscillators out of equilibrium:\\ scaling limits and correlation estimates'] Fix a pair of bounded measurable functions $v_0,e_0:\mathbb T\to \mathbb R$. 
We say that a pair of measurable functions $(v,e)=(v(t,u), e(t,u)) \in L^2([0,T]\times \mathbb T)^2$ is a weak solution of (equation eq:hdl of the paper) if for every $G\in C^{2}(\mathbb T)$, it holds that 
\begin{equation*}
\begin{aligned}
\int_{\mathbb T}v(t,u)G(u)du - \int_{\mathbb T}v_0(u) G(u)du 

+ \int_0^t\int_{\mathbb T}v(s,u) 
\big(\Delta G(u) - 2\alpha\nabla G(u)\big) du ds = 0
\end{aligned}
\end{equation*}
and 
\begin{equation*}
\begin{aligned}
& \int_{\mathbb T}e(t,u)G(u)du - \int_{\mathbb T}e_0(u) G(u)du \\
&\quad
+ \int_0^t\int_{\mathbb T}e(s,u) 
\Delta G(u) du ds 
- \int_0^t\int_{\mathbb T} v(s,u)^2 \nabla G(u) du ds = 0.
\end{aligned}
\end{equation*}

[Theorem 33 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $A, B \in \mathcal{M}_{d}(\mathbb{R})$, $d \in \mathbb{N}$, symmetric and positive semi-definite matrices, then 
					\begin{equation}
					\trace(AB) \leq   \vert \trace(AB)\vert \leq \vert A \vert_2  \trace (B) 
					\end{equation}
					where $\vert A \vert_2 $   denotes the  spectral  norm  or  largest  singular  value  of  $A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2609.03282, 'Characteristic-free characterizations of projective space for smooth toric varieties'] Let $D$ be a Cartier divisor on $X$, and let $m\geq1$ be an integer such that
\begin{equation}
D\cdot\gamma_R\geq m
\qquad\text{for every extremal ray }R.
\end{equation}
For a subset $J\subset\Sigma(1)$, the divisor $D-D_J$ is ample if $|J|<m$, and nef if $|J|=m$.

[Theorem thm:main of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] \mbox{}
            \begin{enumerate}

                \item  Suppose that there exist some $\mathbf{q} \in \mathcal{Q}$ {and} $k \in {\mathbb{N}}$ such that $q_{k} > 0$ and the following step-interpolation process, 
                    \begin{align}
                        t \mapsto \frac{1}{n} M^{{\left(0\right)}}_{k}\left(\eta, \left\lfloor n^2 t \right\rfloor \right) - t  \mathbb{E}_{\nu_{\mathbf{q}}}\left[ M^{{\left(0\right)}}_{k}\left( n \right) \right],
                    \end{align} 
                converges weakly {in $D\left([0,\mathbf{T}]\right)$, $\mathbf{T} > 0$} to the centered Brownian motion with variance $G_{k}\left(\mathbf{q}\right)$ under $\nu_{\mathbf{q}}$. Then, {for any $i \in {\mathbb{Z}}$,} the following step-interpolation process 
                    \begin{align}
                        t \mapsto 
                        \frac{1}{n} Y^{{i}}_{k}\left(\eta, \left\lfloor n^2 t \right\rfloor \right) - nt v^{\mathrm{eff}}_{k}\left( \mathbf{q} \right),
                    \end{align}
                also converges weakly {in $D\left([0,\mathbf{T}]\right)$, $\mathbf{T} > 0$} to the centered Brownian motion with variance $D_{k}\left(\mathbf{q}\right)$ under $\nu_{\mathbf{q}}$, where $D_{k}\left(\mathbf{q}\right)$ is given by 
                    \begin{align}
                        D_{k}\left(\mathbf{q}\right) := \frac{v^{\mathrm{eff}}_{k}\left(\mathbf{q}\right)^2 G_{k}\left(\mathbf{q} \right)}{v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right)^2}  + 4\sum_{\ell = 1}^{k-1} \frac{v^{\mathrm{eff}}_{\ell}\left(\mathbf{q}\right)^2 v^{\mathrm{eff}}_{k-\ell}\left(\theta^{\ell}\mathbf{q}\right) \beta_{\ell}\left(\mathbf{q}\right)}{v^{\mathrm{eff}}_{1}\left(\theta^{\ell-1}\mathbf{q}\right)^2},
                    \end{align}
                {and $\beta_{\ell}\left(\mathbf{q}\right)$ is defined in (equation def:beta of the paper)}.

                \item  Suppose that there exist some $\mathbf{q} \in \mathcal{Q}$, $k \in {\mathbb{N}}$ and $i \in {\mathbb{Z}}$ such that $q_{k} > 0$ and the following limit 
                    \begin{align}
                        \Lambda^{M {,i}}_{\mathbf{q},k}\left(\lambda\right) &:= \lim_{n \to \infty} \frac{1}{n} \log\left({\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ \exp\left( \lambda \left(n - M^{{i}}_{k}\left( n \right) \right) \right) \right] \right) \in {\mathbb{R}},
                    \end{align}
                exists for any $\lambda \in {\mathbb{R}}$, and $\Lambda^{M{,i}}_{\mathbf{q},k}\left( \ \cdot \ \right)$ is essentially smooth in the sense of [DZ]. Then, the following limit 
                    \begin{align}
                        \Lambda^{Y{,i}}_{\mathbf{q}, k}\left(\lambda\right) &:= \lim_{n \to \infty} \frac{1}{n} \log\left({\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ \exp\left( \lambda  Y^{{i}}_{k}\left( n \right) \right)  \right] \right) \in {\mathbb{R}} \cup \{\infty\},
                    \end{align}
                exists for any $\lambda \in {\mathbb{R}}$, and $\Lambda^{Y{,i}}_{\mathbf{q}, k}\left(\lambda\right)$ satisfies (equation eq:Lambda_Y of the paper).  In addition, we have   $\sup_{|\lambda| \le \delta} \left| \Lambda^{Y{,i}}_{\mathbf{q},k}\left(\lambda\right) \right| < \infty$ for sufficiently small $\delta > 0$, and
                $\Lambda^{Y{,i}}_{\mathbf{q},k}\left( \ \cdot \ \right)$ is also essentially smooth. Consequently, thanks to the G\"{a}rtner-Ellis theorem (cf. [DZ]), {under $\nu_{\mathbf{q}}$,} the sequence {$\left(Y^{{i}}_{k}\left(n\right) / n\right)_{n \in {\mathbb{N}}}$} satisfies the LDP with the good rate function $I^{Y{,i}}_{\mathbf{q},k}$, where 
                \begin{align}
                    I^{Y{,i}}_{\mathbf{q},k}\left(u\right) := \sup_{\lambda \in {\mathbb{R}}} \left\{ \lambda u - \Lambda^{Y{,i}}_{\mathbf{q},k}\left(\lambda\right) \right\}.
                \end{align}
            \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:MF-comparison-final of arXiv:2606.29557, 'Propagation of chaos for Belavkin equations beyond pure states'] For every \(T>0\), there exists a constant \(C_T<\infty\), independent of
\(N\), \(j\) and \(\eta\in(0,1]\), such that
\begin{equation}
  \sup_{0\le t\le T}
  \mathbb E_{\mathbb Q^{N,\alpha}}
  \left[
    \left\|
      \gamma_t^{N,\alpha,j}
      -
      \gamma_t^{N,\beta,j}
    \right\|_1
  \right]
  \le
  C_Td_N.

\end{equation}

[Prop 46 of arXiv:2609.01389, 'K-stability and birational rigidity of Fano 3-fold weighted complete intersections'] The following assertions hold.
\begin{enumerate}
\item If $\varphi' \colon Y' \to \mbP (1, 2, 4, 5)$ contracts a divisor, then $\msp$ is not a maximal center.
\item If $\varphi'$ does not contract a divisor, then $\varphi$ initiates a Sarkisov self-link.
\end{enumerate}

[Proposition 13 (Small components and surplus tails) of arXiv:2608.04799, '2608.04799'] Recall the coordinates \(X_{n,i}\) of \(\mathbf X_n\) from
\eqref{eq:Xn-def}.
There is \(C=C(\lambda)<\infty\) such that, for \(0<\varepsilon\le1\),
\begin{equation}
  \sup_{n\ge n_\lambda}
  \E\sum_{i:X_{n,i}\le\varepsilon}X_{n,i}^2
  \le C\sqrt\varepsilon.
\end{equation}
For every \(0<a<b<\infty\),
\begin{equation}
  \lim_{R\to\infty}\sup_{n\ge n_\lambda}
  \E\Xi_n([a,b]\times\{R+1,R+2,\ldots\})=0.
\end{equation}

