[Lemma lemma Poisson approximation sequence of arXiv:2505.15940, 'Degrees of Freedom for Critical Random 2-SAT'] Let $(X^{(r)})_{r\in[-1,R]}$ be a sequence of random variables where $X^{(-1)}=M_1^{(-1)}$, $X^{(0)}=M_1^{(0)}$ and $X^{(r)}|X^{(r-1)}\sim\text{Poisson}\big(X^{(r-1)}\big)$ for $r\in[R].$ Then for $x^{(-1)},x^{(0)},\dotsc,x^{(R)}\in[0,\lfloor n^q\log{n}\rfloor]$ it holds that
    \begin{align*}
        &\mathbb{P}\big(M_1^{(r)}=x^{(r)},\; r\in[R]\big|M_1^{(-1)}=x^{(-1)},\,M_1^{(r)}=x^{(0)}\big)\\
    \geq& \mathbb{P}\big(X^{(r)}=x^{(r)},\; r\in[R]\big|X^{(-1)}=x^{(-1)},X^{(0)}=x^{(0)}\big)\cdot E(n),
    \end{align*}
    where $E$ is a function satisfying that $\lim_{n\rightarrow\infty}E(n)=1$.

[Proposition prop:invariantmeasures of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] For any $\rho\in [0,1]$ and any $\mathcal{E}\in [\rho ,\kappa\rho]$, the measure $\mu_{\rho ,\mathcal{E}}$ is reversible for the symmetric generator $\mathcal{L}_S$, and invariant for the generator $\mathcal{L}$. Moreover, for all~$x\in\mathbb{Z}$, it satisfies
    \begin{equation*}
        \mathbb{E}_{\rho ,\mathcal{E}}[\xi_x] = \rho \qquad\mbox{ and }\qquad \mathbb{E}_{\rho ,\mathcal{E}}[\eta_x] =\mathcal{E}.
    \end{equation*}

[Cor consequences of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Assume that $D(\mathcal F_{\beta})\cap X^{a,b}_{p,p'}\neq \emptyset$ and  let $\mathsf{P}^*\in X^{a,b}_{p,p'}$ be the unique minimizer of $\mathcal F_{\beta}$ on $X^{a,b}_{p,p'}$. Then for any $\mathsf{P}\in X^{a,b}_{p,p'}\cap D(\mathcal F_{\beta})$
   \begin{align}
       \frac{\beta }{2a^{\frac{2-p}{p}}} \mathscr W_p^2(\mathsf{P},\mathsf{P}^*)\leq \mathcal F_{\beta}(\mathsf{P})-\mathcal F_{\beta}(\mathsf{P}^*)\leq \frac{a^{\frac{2-p}{p}}}{2\beta } \abs{\partial \mathcal F_{\beta}}^2(\mathsf{P}).
    \end{align}
    Moreover, for any curve of maximal slope $(\mathsf{P}_t)_{t>0}$ w.r.t. $\abs{\partial \mathcal F_{\beta}}$ in $X^{a,b}_{p,p'}$ satisfies for every $t\geq t_0>0$
    \begin{align}
        \frac{\beta }{2a^{\frac{2-p}{p}}}\mathscr W_p^2(\mathsf{P}_t,\mathsf{P}^*)\leq \mathcal F_{\beta}(\mathsf{P}_t)-\mathcal F_{\beta}(\mathsf{P}^*)\leq (\mathcal F_{\beta}(\mathsf{P}_{t_0})-\mathcal F_{\beta}(\mathsf{P}^*))e^{-2\beta a^{\frac{p-2}{p}}(t-t_0)}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 of arXiv:2605.11279, 'Flocking with Multiple Types: Competition, Fluid Limits and Traveling Waves'] Suppose that Assumption \ref{assumption0} holds. For every $t \geq 0$ and $f\in\HHH$, 
    \begin{align*}
        \sup_{s\in [0, t]} \abs*{A_{s, f}\big(\mu_n(\cdot)\big)} \cpinf{n} 0,
    \end{align*}
    where recall, for $t\geq 0$ and $f\in \HHH$, recall that
    \begin{align*}
        A_{t,f}\big(\mu_n(\cdot)\big) = \biginner{f, \mu_n(t)} - \biginner{f, \mu_n(0)} - \int_0^t\! \biginner{\LLL f(\cdot, \mu_n(s)), \mu_n(s)} \di s.
    \end{align*}

