[Prop of arXiv:2512.12796, 'Symmetrization and the Planar Skorokhod Embedding Problem'] The following facts hold. 
\begin{enumerate}
\item $\mathcal{E}_{s}(U)>0\Longleftrightarrow\mathcal{E}_{s}(\mu)>0.$ 
\item It may happen that $\mathcal{E}_{s}(U)=+\infty\,\,\text{and}\,\,\mathcal{E}_{s}(\mu)<+\infty$
for some positive $s$.
\end{enumerate}

[Lemma Prop local asymp expect CR 1 8 ver 1 of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] As $\max(\varepsilon_1,\varepsilon_2)\to 0$, we have that
\begin{multline*}
\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^v)
=
\varepsilon_{1}^{1/8}
\varepsilon_{2}^{1/8}
(\mathbf{C}_{\rm{SLE}4}^{\rm loop})^2
\\
\times
\mathbb{E}
\big[
\CR(z_1,\widehat{D}_{r_0}(z_1))^{-1/8}
\CR(z_2,\widehat{D}_{r_0}(z_2))^{-1/8}
\1_{E_{r_0,\varepsilon_1,\varepsilon_2}}
\1_{\{\mathbb{D}(z_j,r(\varepsilon_j))
\subset
\widehat{D}_{r_0}(z_j), j\in\{1,2\}\}}
\big]
(1+o(1))
.
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pr:daviesmooth of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Suppose that $X\in C^1$ and that $\sigma$ is smooth. Then any solution $Z$ to (equation integral form of the paper) satisfies
		\begin{equation}
			Z_{st}^{[m+1]} = \delta Z_{st}-\sum_{\tau\in{\mathcal T}^{\leq m}}\Upsilon_\tau(Z_s) \, \mathbb X_{st}(\tau)=O\left((t-s)^{m+1}\right)
		\end{equation}
		uniformly for $0\le s\le t\le T$, for any $m\geq 0$, where $\mathbb X$ is the smooth rough path (equation Eq: definition smooth rough of the paper).

[Lemma 11 (Expression for the directional derivative) of arXiv:2608.24294, 'Existence of densities and atoms for the running maximum of time-inhomogeneous jump diffus'] Under Assumptions~\ref{ass:Levy} and~\ref{ass:jump}, with $\Theta=(0,v)$ as above,
the directional derivative satisfies
\begin{equation}
D_\Theta X_t
= \exp\Big(\int_0^t \partial_x b(s,X_s)\,\dd s\Big)\,
\int_0^t\int_{\R_0}
\kappa(s)^2\exp\Big(-2\int_0^s \partial_x b(u,X_u)\,\dd u\Big)\eta(z)\,N(\dd s,\dd z).
\end{equation}
In particular, $D_\Theta X_t\ge 0$ for all $t\in[0,T]$.

[Theorem thm:pointwise of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] There exist universal constants $c, C > 0$ such that the following holds for any $\epsilon \in (0,1)$:
\begin{proplist}
    \item If $\beta = o(1)$, then with probability at least $1 - \epsilon^{-2} e^{ - c \log m } - 2 e^{-cn\epsilon^2}$, we have
    \begin{align*}
        \big|  
            \log \| X \theta \|
            -
            Z
        \big| 
        \;\leq\; 
        C
        \Big(
            \mfrac{\epsilon}{1-\epsilon}    
            +
            \mfrac{\beta^2 \log m}{n}
        \Big)
        \;;
    \end{align*}
    \item If $\beta = \Omega(1)$, $\log m = o(N^{1/3})$ and $N=o(n^3)$, then  
    \begin{align*}
        \mfrac{1}{\beta^2 \log m}
        \big|  
            \log \| X \theta \|
            -
            Z
        \big| 
        \;\leq\; 
        C \Big( \mfrac{\epsilon}{(1-\epsilon) \beta \log m}
                    +
                    \mfrac{1}{ \beta (\log m)^{1/4}}
                \Big)
        \;
    \end{align*}
    with probability at least $1 - (1+ \epsilon^{-2}) e^{ - c  \, (\log m)^{3/4} } - 2e^{-cn\epsilon^2}$.
\end{proplist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 (branching capacity defined by the past) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] For all finite sets \(A \subset \Z^{d}\),

\begin{equation*}{
\bcp(A):=\sum_{a \in A} \P(\Tree_{+}^{a} \cap A = \emptyset) = \sum_{a \in A} \P(\Tree_{-}^{a} \cap A = \emptyset).
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary thm:PF-log-lower of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] For $n\ge2$ and $t\ge1$,
\begin{equation}
 d_{K_{\mathrm{PF}}}(t)
 \ge
 \max\left\{
  \frac{n}{n+2}\lambda_{2,\mathrm{PF}}^t,\,
  1-\frac{t+\log 3}{\log n}
 \right\}.
\end{equation}
Consequently, for every fixed $0<\varepsilon<1$,
\begin{equation}
 t_{\mathrm{mix},K_{\mathrm{PF}}}(\varepsilon)
 \ge(1-\varepsilon)\log n-\log 3
\end{equation}
for all sufficiently large $n$.

[Lemma 31 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such that for any $T>0$, $D\subset \widetilde{\mathbb{Z}}^d$ and $z_1,z_2,z_3\in \widetilde{\mathbb{Z}}^d\setminus D$ with $\min_{i\neq j}|z_i-z_j|\ge d$, 
	\begin{equation} 
		\mathbb{P}\big( \widehat{\mathcal{L}}_{1/2}^{D,z_1}\ge T \mid  z_1 \xleftrightarrow{(D)} z_2, z_2 \xleftrightarrow{(D)} z_3 \big) \le Ce^{-cT}. 
	\end{equation}

