[Lemma eq:pmab of arXiv:2606.05830, '{ Biased Random Walk on $\mathbb Z_+$ with Traps of Linearly Increasing Depth}\footnote{Su'] For $0\le a\le m\le b$,
  \begin{equation}
P_m(a,b,+) =
\begin{cases}
\dfrac{1 - \lambda^{m-a}}{1 - \lambda^{b-a}}, & \text{if } \lambda \neq 1,\\[10pt]
\dfrac{m-a}{b-a}, & \text{if } \lambda = 1.
\end{cases}
\end{equation}

