[Corollary 24 (Law attractor and pathwise fibers) of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Assume \textnormal{(A1)-(A4)}. For every $\epsilon\in[0,\epsilon_0]$, the law semiflow $\varphi_P^\epsilon$ possesses a unique $\mathfrak D_P$-global attractor
	\begin{align}
		\mathcal A_P^\epsilon
		=
		\bigcap_{\tau\geq0}
		\overline{
		\bigcup_{t\geq\tau}\varphi_P^\epsilon(t)K_P
		}^{P}.
	\end{align}
	Moreover, $\mathcal A_P^\epsilon\subset K_P$, so $\mathcal A_P^\epsilon\in\mathfrak D_P$, and
	\begin{align}
		\Pi_P\mathcal A^\epsilon(\omega)=\mathcal A_P^\epsilon,
		\qquad \omega\in\Omega_0.
	\end{align}
	For $\mu\in\mathcal A_P^\epsilon$, define
	\begin{align*}
		\mathcal A_H^\epsilon(\omega,\mu)
		=\big\{x\in H:(x,\mu)\in\mathcal A^\epsilon(\omega)\big\}
	\end{align*}
	and
	\begin{align*}
		\Theta_{-t}^\epsilon\mu
		=\big\{\nu\in\mathcal A_P^\epsilon:
		\varphi_P^\epsilon(t)\nu=\mu\big\}.
	\end{align*}
	Then, for every $t\geq0$,
	\begin{align}
		\mathcal A_H^\epsilon(\omega,\mu)
		=
		\bigcup_{\nu\in\Theta_{-t}^\epsilon\mu}
		\varphi_H^\epsilon\big(
		t,\theta_{-t}\omega,
		\mathcal A_H^\epsilon(\theta_{-t}\omega,\nu),\nu
		\big),
	\end{align}
	and, for every $B_H\in\mathfrak D_H$,
	\begin{align}
		\lim_{t\to\infty}
		\sup_{\nu\in\Theta_{-t}^\epsilon\mu}
		\operatorname{dist}_H\left(
		\varphi_H^\epsilon\big(
		t,\theta_{-t}\omega,B_H(\theta_{-t}\omega),\nu
		\big),
		\mathcal A_H^\epsilon(\omega,\mu)
		\right)=0.
	\end{align}

[Corollary cor:asep-F-equation of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] For \(\zeta \in \mathbb{C} \setminus \mathbb{R}_{\geq 0}\), the
\(\tau\)-Laplace transform
\(\mathcal{L}_{t,x,m}(\zeta)
=\det_H(I+K_{t,x,m})\) satisfies
\begin{align}
\mathcal{L}_{t,x,m}\partial_t\mathcal{L}_{t,x,m+1}
-\mathcal{L}_{t,x,m+1}\partial_t\mathcal{L}_{t,x,m}
+\gamma\left[
\mathcal{L}_{t,x+1,m}\mathcal{L}_{t,x-1,m+1}
-\mathcal{L}_{t,x,m}\mathcal{L}_{t,x,m+1}
\right]=0.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 (Rademacher contraction with a deterministic offset) of arXiv:2608.22179, '\bf Token-Level Likelihood-Array Regression for Membership Inference and AI-Generated Text'] Let \(\varepsilon_1,\ldots,\varepsilon_n\) be independent Rademacher variables.
For an index set \(\mathcal T\), let \(x_i(t)\in\R\), let
\(\phi_i:\R\to\R\) be one-Lipschitz with \(\phi_i(0)=0\), and let
\(\Omega:\mathcal T\to\R\) be deterministic. Whenever the suprema below are
measurable,
\[
\E_\varepsilon\sup_{t\in\mathcal T}
\left\{
\frac1n\sum_{i=1}^n\varepsilon_i\phi_i\{x_i(t)\}-\Omega(t)
\right\}
\leq
\E_\varepsilon\sup_{t\in\mathcal T}
\left\{
\frac1n\sum_{i=1}^n\varepsilon_i x_i(t)-\Omega(t)
\right\}.
\]

