[Lemma lem:eta.dym of arXiv:2607.07598, 'Universal Central Limit Theorem for non-exchangeable interacting diffusions'] Let $f\in C_b^2({\mathbb{R}}^d)$. For $t \in [0,T]$,
			\begin{align}
				\begin{split}
					\langle \eta^n_t, f \rangle
					&= \langle \eta^n_0, f \rangle
					+ \int_0^t \big\langle \eta^n_s, {\mathcal{L}}_{s,\mu^n_s} f\big\rangle \,\mathrm{d} s 
					+ \frac{n}{n-1} \int_0^t \big\langle \widehat{\eta}^n_s(\mathrm{d} x, \mathrm{d} y), b(s,x,y)\cdot \nabla f(x)\big\rangle \,\mathrm{d} s \\
					&\quad
					+\frac{\sqrt{n}}{n-1}\int_0^t \big\langle \mu_s^n(\mathrm{d} x)\mu_s^n(\mathrm{d} y), b(s,x,y)\cdot \nabla f(x)\big\rangle \,\mathrm{d} s
					+ \frac{\sigma}{\sqrt{n}} \sum_{i=1}^{n} \int_0^t \nabla f(X^i_s)\cdot \mathrm{d} B^i_s .
				\end{split}
			\end{align}

