[Proposition 28 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] Let $\mu_\epsilon$ be the sequence of measures defined in \eqref{q:rev:recov_seq_2}. Then,
\begin{equation}
\theta_\epsilon^{(\widehat{\mf q})}\ms I_\epsilon(\mu_\epsilon)
\,\leq \,
\sum_{k = 1}^{\mf u_{\widehat{\mf q}}-1} 
\sum_{r=1}^{\mf r_{k-1,k}}
\theta_\epsilon^{(\widehat{\mf q})}\int_{B_{\sigma_{k-1,k}^{\widehat{\mf q},r}}^{\widehat{\mf q}}\,\cup
\,\Lambda_{\sigma_{k-1,k}^{\widehat{\mf q},r}}^{\widehat{\mf q}}}
\big[J'_{\mc S_{\widehat{\mf q}},\epsilon} (x) \big]^2\;
\frac{e^{-S(x)/\epsilon}}
{c(\epsilon)}\;dx \,+\, R(\epsilon)\,,
\end{equation}
where $R(\epsilon)$ is an error term that vanishes as $\epsilon\to 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition of arXiv:2608.10415, 'Continuous random variables'] We have the following results, valid for group algebras:
\begin{enumerate}
\item $C^*(\Gamma),C^*(\Lambda)$ are independent inside $C^*(\Gamma\times\Lambda)$.

\item $C^*(\Gamma),C^*(\Lambda)$ are free inside $C^*(\Gamma*\Lambda)$.
\end{enumerate}

[Theorem 39 of arXiv:2609.00183, '2609.00183'] Let $u=(V,v):B_{\sigma_j}(0) \to \mathbb{R}^j \times Y_C^{N-j}$ be a local representation of a harmonic map into a conical DM-complex $Y_C^N$ satisfying $\Ord_{\phi,v}(0,R_0)\leq \Lambda$ and $\sup_{B_{\sigma_j}(0)}|\nabla u| \leq M.$ Given $k\in\{0,...,n-1\}$ and $0<\eta<\eta_1$ where $\eta_1$ is chosen as in Lemma \ref{bd5.12}, there exist $\delta=\delta(n,\eta,Y_C,\Lambda)>0, \, C=C(n)>0,$ and $\sigma\in (0,\sigma_{\ref{bd:A2}}]$ such that the following holds.

    Let $0<s<S<\frac{\sigma}{8}$ and $x \in B_{\sigma}(0)$. Suppose that $D \subseteq \calS_{0,\eta,\delta s}^k \cap B_S(x)$ is any subset and $\Gamma:=\Ord_{\phi,v}(y,8S).$ Then there is a finite decomposition of $D$ into sets $D_x,$ a finite set $\calC \subseteq B_{2\sigma}(0),$ and a collection of balls $\{B_{s_x}(x)\}_{x \in \calC}$ with $s_x \geq s,$ such that:
    \begin{itemize}
        \item [(1)]$D_x \subseteq B_{s_x}(x),$
        \item [(2)]$\sum s_x^k \leq CS^k,$
        \item [(3)]for each $x \in \calC,$ either $s_x=s$ or for any $y \in D_x,$
        \begin{equation*}
            \Ord_{\phi,v}(y,8s_x) \leq \Gamma-\delta.
        \end{equation*}
    \end{itemize}

[Lemma 14 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] For the quotient \eqref{adj:eq:quotient-general},
\begin{equation}
 Q_0({a_n})=\frac{x+y}{xy(y-x)^2},
\end{equation}
and
\begin{equation}
 \frac{Q_1({a_n})}{Q_0({a_n})}=\frac{2xy}{x+y},
 \qquad
 \frac{Q_2({a_n})}{Q_1({a_n})}=\frac{x+y}{2}.
\end{equation}
Consequently,
\begin{align*}
 \rho({a_n})=\frac{(y-x)^2}{(x+y)^2},
\end{align*}
and
\begin{equation}
 \Vcal({a_n})=\frac{(y-x)^2}{4xy}.
\end{equation}

[Lemma lem:local-global-side-consistency of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] For an incident pair $(m,i)$, set $j=j(m,i)$ and let $B_{m,i}^{[m]}(\sidedistat{m}{i},\eta,v)$ be the rotated endpoint pullback $B_j\bigl(s_{m,i}^{\rm ve}(\sidedistat{m}{i}),\eta,O_mv\bigr)$. If $r_{m}<2\ell_{\mathrm{vtx}}$, then every field assembled from a nonincident side vanishes identically. For the incident side $j=j(m,i)$, away from the single point $\sigma_i=\eta_i=0$,
\begin{align}
 (\operatorname{Ext}_j^\varepsilon B_j)
 \bigl(V_m+\varepsilon O_mY,O_mv\bigr)=
 \mathbf 1_{\{\sigma_i>0\}}
 \Theta\!\left(\tfrac{\eta_i}{\sigma_i}\right)
 B_{m,i}^{[m]}(\varepsilon\sigma_i,\eta_i,v).

\end{align}
Thus coefficient extraction from the globally assembled side hierarchy uses the local operator $\mathfrak E_i$, with the factor $\Theta$ occurring once.

[Lemma lem:circle-uniform-cylinder-upper-bound-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Assume the minimal Kahane--Peyri\`ere regime. If \(0<\beta<A_{\mathrm{loc}}(W)\), then, almost surely, there exists a finite random constant \(C_\beta\) such that
\begin{equation}
\mu_\circ(\mathcal I_v)\le C_\beta 2^{-\beta \lvert v \rvert}
\end{equation}
for every finite binary word \(v\).

