[Lemma 1 of arXiv:2511.23453, 'Convergence rates of self-repellent random walks, their local time and Event Chain Monte C'] \begin{enumerate}[(i)]
        \item The probability measure $\hat\mu = \mu\otimes\unif(\Z_n)$ is invariant for the Markov process $(\mathcal L(t),X(t))_{t\geq 0}$.
        \item Functions $f\in C_b^1(\S\times\mathbb Z_n)$ are contained in the domains of the adjoints of the operators $\T$, $\J_+$, $\J_-$ and $\hatL$ in $L^2(\hat\mu)$, and
        \begin{align*}
            \T^*f(\ell,i) &\ =\ -\T f(\ell,i) - (\Delta_n\ell)_if(\ell,i)\,,\\
            \J_\pm ^*f(\ell,i) &\ =\ q^\pm (\ell,i\mp 1)f(\ell,i\mp 1) - q^\pm (\ell,i)f(\ell,i)\,,\\
             \hatL ^*f(\ell,i)&\ =\ -\T f(\ell,i)+ (\ell_i')_+\big(f(\ell,i+1)-f(\ell,i)\big) + (\ell_{i-1}')_-\big(f(\ell,i-1)-f(\ell,i)\big)\,.
        \end{align*}
    \end{enumerate}

