[Theorem thm:central-bound of arXiv:2606.27073, 'Retention Profiles and KL Contraction Bounds in Finite Markov Chains'] For any $\mu\neq\pi$,
\[
  \frac{D_{\mathrm{KL}}(\mu P\|\pi)}{D_{\mathrm{KL}}(\mu\|\pi)}
  \;\le\;
  M\cdot\frac{D_{\mathrm{KL}}(\mu\|\pi)+H(\mu)}{D_{\mathrm{KL}}(\mu\|\pi)}
  \;-\;
  \frac{I_\mu(X;Y)}{D_{\mathrm{KL}}(\mu\|\pi)},
\]
where $H(\mu)=-\sum_x\mu(x)\log\mu(x)$ is the Shannon entropy.
Equality holds if and only if $r(x)=M$ for all $x$ in the support of $\mu$.

[Lem L2.2 of arXiv:2609.03848, 'The mean-field limit of the Schr\"{o}dinger-Lohe model\\ and emergent dynamics'] \emph{[C-C-H]}
For $T \in (0, \infty]$, let $\{ \psi_k \}$ be a smooth solution to (equation SL of the paper) in the time-interval $[0, T)$. Then, we have
\begin{align}
\begin{aligned}  
& \frac{d}{dt}||\psi_k-\psi_j||_{\mathfrak{H}}^2 \\
& \hspace{0.5cm} \leq-\frac{2}{\hbar}\int_{\mathbb T^d}(V_k-V_j)\mbox{Im}(\psi_k{\overline\psi}_j)dx-\frac{2}{\hbar}\int_{\mathbb T^d}\omega\star_x (|\psi_k|^2-|\psi_j|^2)\mbox{Im}(\psi_k{\overline \psi}_j)dx 
\\
&\hspace{0.7cm} +\frac{\kappa}{N}\sum_{k=1}^N \Big[\Big(||\psi_k-\psi_k||_{\mathfrak{H}} +||\psi_j-\psi_k||_{\mathfrak{H}}  - 1\Big)\cdot||\psi_k-\psi_j||_{\mathfrak{H}}^2-|1-\langle \psi_k|\psi_j \rangle|^2 \Big]. 
\end{aligned}
\end{align}

