body:
[Definition 28 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] The group $\{X_t\}_{t\in \R}$ of measure-preserving transformations is called a \emph{measure-preserving flow of $\vi$}, if
	for all $t\in \R$ we have
	\begin{equation}
		X_t - \operatorname{id} = \int_0^t \v \circ X_s \, ds. 
	\end{equation}

[Theorem CLT of arXiv:2411.14876, 'Limit theorems for stochastic exponentials of matrix-valued L\'evy processes \\'] Let $L$ be a L\'evy process in $\mathbb{R}^{d\times d}$ fulfilling (equation eq-nonsingular of the paper) and let $X$ be the corresponding stochastic exponential.
	Assume that $G_X$  is unbounded and acts strongly irreducibly on $\R^d$, and that $\E \big[\sup_{0 \le s \le 1} (\log M(X_s))^2\big]<\infty$.

	Then there is $\lambda \in \R$ such that
	\begin{equation}
		 \frac{1}{t} \log F(X_t) \to \lambda \quad \text{a.s.},
	\end{equation}
	and $\sigma^2>0$ such that
	\begin{equation}
		\frac{\log F(X_t) - t \lambda}{\sqrt{t}} \stackrel{d}{\to} \mathcal{N}(0, \sigma^2), \quad t\to \infty,
	\end{equation}
	where $F : \operatorname{GL}(\mathbb{R},d) \to [0,\infty)$ can be chosen as $F(a)=\|a \|$ as well as $F(a)=\|ya \|$ for any $y \in \R^d$ with $\|y \|=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_phi of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] For each $\sigma \in \{-,0,+\}$, we define the maps $\phi^{\sigma}$ by setting,
\begin{equation*}
\begin{array}{cccc}
\phi^{\sigma}:&\Omega_n^{(0)}(\mu,2^{-R}\varepsilon) & \longrightarrow & \Omega_{\overline{\alpha}_{\sigma,n}} \\
& w & \longmapsto &
\begin{cases}
u^{1,\sigma} \cdot \xi^{1,\sigma} \cdot u^{2,\sigma} \cdot \xi^{2,\sigma} \, \cdots \, u^{\#J^{\sigma},\sigma} \cdot b^{\sigma}, & \text{if } \#J^{\sigma}>0, \\
b^{\sigma}, & \text{if } \#J^{\sigma}=0,
\end{cases}
\end{array}
\end{equation*}
where for all $h \in \llbracket 1,\#J^{\sigma}-1 \rrbracket$, $\xi^{h,\sigma}$ is the one-letter word connecting $u^{h,\sigma}_{-1}$ to $u^{h+1,\sigma}_1$, which exists by Lemma~(lemma_existence_connecting_one_letter_word of the paper) and $b^{\sigma}$ is the word introduced in Definition~(def_b_sigma of the paper).

[Proposition 3 of arXiv:2606.24056, 'Decorated stable $p$-adic self-similar processes with stationary increments'] Let \(0<\alpha\le2\) and \(H>0\). In the above setting, suppose that \(f_t\in L^\alpha(E,\mu)\) for each \(t\in\Q_p\), and
define
\begin{align}
    X(t)=\int_E f_t(x)\,M_\alpha(dx).
\end{align}
Then
\begin{equation}
  \E \left[\exp\left(i\sum_{j=1}^r\theta_jX(t_j)\right)\right]
  =
  \exp\left(-\int_E
  \bigg|\sum_{j=1}^r\theta_jf_{t_j}(x)\bigg|^\alpha\mu(dx)\right).
\end{equation}
Moreover, \(X\) is \(p\)-adic \(H\)-sssi if and only if the following two identities
hold for every \(r\ge1\), \(t_1,\ldots,t_r\in\Q_p\),
\(\theta_1,\ldots,\theta_r\in\R\), \(h\in\Q_p\), and \(a\in\Q_p^\times\):
\begin{equation}
  \int_E\bigg|\sum_{j=1}^r\theta_j(f_{t_j+h}-f_h)\bigg|^\alpha d\mu
  =
  \int_E\bigg|\sum_{j=1}^r\theta_jf_{t_j}\bigg|^\alpha d\mu
\end{equation}
and
\begin{equation}
  \int_E\bigg|\sum_{j=1}^r\theta_jf_{a t_j}\bigg|^\alpha d\mu
  =
  \abs{a}_p^{\alpha H}
  \int_E\bigg|\sum_{j=1}^r\theta_jf_{t_j}\bigg|^\alpha d\mu .
\end{equation}

[Lemma 16 of arXiv:2604.00598, 'Allowing for Imprecision in the Game-theoretic Characterisation of the Poisson Process'] For any \(t,\Delta\in\posreals\),
\begin{equation*}
\oscuprev{\indica{\set{N_{t+\Delta}=N_t}}}[t]
= e^{-\Delta\llambda}
\quad\text{with }
\set{N_{t+\Delta}=N_t}\coloneqq\set{\pth\in\countpaths\colon \pth\gr{t+\Delta}=\pth\gr{t}}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 33 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] Let $E\in\Borel(\R^N)$ satisfy $\mathcal L^N(E)=0$.  Then, for every
$\mathbf q\in\mathcal Q_N$,
\begin{equation}
 \Prob\bigl(
 \mathcal S_{\mathbf q}
 \cap\{\boldsymbol\Lambda\in E\}
 \bigr)=0.

\end{equation}

[Theorem 1 of arXiv:2608.30174, 'Exact counting of spherical metrics with one conical singularity on rectangular tori'] \cite[Corollary 4]{BartolucciTarantelloCMP}
For any closed interval $K\Subset (0,+\infty)\setminus 8\pi \mathbb{N}_{\geq 1}$, there exists a constant $C_{K}$ such that for any solution $u(z)$ of \eqref{eq:mfe} with $\rho\in K$, 
$$\big\|u+\rho G\big\|_{C^2(E_{\tau})}\leq C_{K}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 (First-order local sufficiency) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] For $m<r$ and a tangent block $T\subset T_{\theta_0}\Theta$, the depth-$m$ window is \emph{first-order locally sufficient relative to depth $r$ on $T$} if
\begin{equation}
\Ker\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_T\bigr) \subset \Ker\bigl(Dq_{\cQ}^{(r)}(\theta_0)|_T\bigr).
\end{equation}

