[Theorem 3 (Transition trajectories and transition path process share the same distribution) of arXiv:2506.09462, 'Transition Path Theory For L\'{e}vy-Type Processes: SDE Representation and Statistics'] Let \(X_t\) satisfy the L\'{e}vy SDE \eqref{eqn:SDE}, and let \(Y^n\) denote the \(n\)-th \(A \to B\) transition trajectory defined by \eqref{eqn:reactive}. Let \(Y_t\) be the process defined in Theorem \ref{theo:TPPSDE}. Then, for any bounded and continuous functional \(H: C([0, \infty)) \to \mathbb{R}\), we have  
    \begin{equation*}
        \mathbb{E}[H(Y^n)] = \widehat{\mathbb{E}}\left[H(Y) \ \Big| \ Y_0 \sim X_{\tau_{A,n}^-} \right],
    \end{equation*}
     where $\widehat{\mathbb{E}}$ denotes the expectation taken under the measure  $\mathbb{Q}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2606.01881, '2606.01881'] For $n\ge2$, $m\ge1$, $j_1,\ldots,j_m>n$, and $a_1,\ldots,a_m\ge1$,
\begin{equation}
\begin{aligned}
&\Pp\Biggl(
        \bigcap_{j=2}^{n}D_j\cap
        \bigcap_{k=1}^{m}\{L_{j_k}\ge a_k\}
        \,\Bigm|\,\mathcal F_{T_n}\Biggr) \\
&\quad\ge
        \Pp\Biggl(
        \bigcap_{j=2}^{n-1}D_j\cap
        \bigcap_{k=1}^{m}\{L_{j_k}\ge a_k\}
        \,\Bigm|\,\mathcal F_{T_n}\Biggr)
        \Pp(D_n\mid\mathcal F_{T_n})
        \qquad\text{a.s.}
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] For any $n \in \mathbb{N}$, $a,b \geq 1$, $p \in [1,\infty]$, and for any partition $	\mathcal P_{M} : = \{B_{1},...,B_{M}\}$ and any $r$-coloring of this partition,  $\mathcal C_{r}[\mathcal P_{M}]$,
	\begin{align*}
		\left \| \sup_{f\in\mathcal{F}}  \mathbb G_{n}(f)   \right\|_{L^{1}(\mathbb P)} \lesssim &   \sqrt{K_{r}}  \max_{m \in [M]} \Gamma_{p}(B_{m})  \gamma_{2,a}(\mathcal F ,   \max_{i \in N_{n}}   || \cdot ||_{L^{2p}(P_{Z_{i}}) } )   \\
		& + \left(   \frac{K_{r}  \max_{m \in [M]} |B_{m}|}{\sqrt{n}}  + \sqrt{n} 	\bar{\tau}_{\operatorname{cone} \mathcal F,G_n}
		\left(
		\mathcal P_{M},
		\mathcal C_{r}[\mathcal P_{M}]
		\right) \right)  \gamma_{1,b}(\mathcal F ,   ||\cdot||_{\infty}).
	\end{align*}

[Lemma 4 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] Assume that there are constants $\lambda=\lambda(\theta,a)>0$ and $c(\theta,a)>0$ not depending on $x$ or $n$ and a continuous function $h$ such that
  $$p_n^{a,x}(\theta)\sim c(\theta,a)h(x)\lambda^{n+1}$$
  holds as $n\to\infty$ for all $x\in[-a,1]$. Then,
  \begin{align} 
    \lambda h(x) & =\lim_{n\to\infty}\frac{1}{c(\theta,a)\lambda^{n}}\, p_n^{a,x}(\theta) =\int_{\{y>\theta x\}\cap[-a,1]}h(y)\,\frac{1}{a+1}\,\d y.
  \end{align}

