[Theorem 4 (Deterministic perturbation bound) of arXiv:2609.01319, 'Matched Queries for Curvature and Density at Branching Junctions'] Assume $\sigma_{\min}(B)=\gamma>0$. Let the implemented design be $\widehat B=B+E$ and the observed response be $\widehat y=y+e$. If $\norm{E}_{\op}<\gamma$, the least-squares estimator obeys
\begin{equation}
\norm{\widehat\theta-\theta}
\le
\frac{
 C_{\mathrm{bias}}\sigma^\alpha
 +\norm{e}
 +\norm{E}_{\op}\norm{\theta}
}{\gamma-\norm{E}_{\op}}.

\end{equation}
If the two normalized score fields have stacked errors $\varepsilon_\sigma$ and $\varepsilon_{\lambda\sigma}$, and the center remainder in \cref{eq:provisional-center} is $r_\sigma$, one may take
\begin{equation}
\norm{e}
\le
\frac{\varepsilon_\sigma+\varepsilon_{\lambda\sigma}}{(\lambda-1)\sigma}
+C_{\mathrm{ctr}}\frac{\norm{r_\sigma}}{\sigma^2}.

\end{equation}
Errors in recovered directions and weights enter through $E$ by smooth dependence of the basis on the first-order geometry over any declared separated, positive-weight class. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ GUE matrix. For any $n_1,n_2\in \N\cup\{0\}$ and $\bm{k}\in \N^{n_1}$, $\bm{l}\in \N^{n_2}$ it holds that
\begin{equation}
\Phi_0(\bm{k},\bm{l})=\delta_{n_1,n_2}\frac{\ii^{|\bm{k}|-|\bm{l}|}}{2^{|\bm{k}|+|\bm{l}|}} \prod_{j=1}^n \frac{1}{(k_j-1)!(l_j-1)!}\sum_{\sigma\in S_{n}} \prod_{j=1}^n (k_j+l_{\sigma(j)}-1)!. 

\end{equation}
Here in the case $n_1=n_2$ we denoted $n:=n_1$, and $S_n$ is the set of permutations of $[n]$. For any $d\ge 1$ we further have
\begin{equation}
\Phi_d(\bm{k},\bm{l})=0.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def of cH of arXiv:2609.01984, 'Instantaneous shrinking of supports for stochastic PDEs\footnote{JY was supported by a KIA'] Let $\tau\le T$ be a bounded stopping time and $u\in\mathbb H_p^\eta(\tau)$.
\begin{enumerate}[(i)]
\item 
We write $u\in\mathcal{H}^{\eta}_p(\tau)$ if $u_0\in U_{p}^{\eta}$ and there exists $(f,g)\in
\mathbb{H}_{p}^{\eta-2}(\tau)\times\mathbb{H}_{p}^{\eta-1}(\tau,\ell_2)$ such that
\begin{equation*}
\mathrm{d} u = f\mathrm{d} t+\sum_{k=1}^{\infty} g^k \mathrm{d} w_t^k,\quad   t\in (0, \tau]\,; \quad u(0,\cdot) = u_0
\end{equation*}
in the sense of distributions, i.e., for any $\varphi\in C_c^\infty$, the equality
\begin{equation} 
(u(t,\cdot),\varphi) = (u_0,\varphi) + \int_0^t(f(s,\cdot),\varphi)\mathrm{d} s + \sum_{k=1}^{\infty} \int_0^t(g^k(s,\cdot),\varphi)\mathrm{d} w_s^k
\end{equation}
holds for all $t\in [0,\tau]$ almost surely. Here, $(w^k)_{k\geq 1}$ is a family of independent one-dimensional Brownian motions. In this case, we write
\begin{equation*}
\mathbb{D} u:= f,\quad \mathbb{S} u:=g.
\end{equation*}
\item
The norm of $\mathcal{H}_{p}^{\eta}(\tau)$ is defined by
\begin{equation*}
\| u \|_{\mathcal{H}_{p}^{\eta}(\tau)} :=  \| u \|_{\mathbb{H}_{p}^{\eta}(\tau)} + \| \mathbb{D} u \|_{\mathbb{H}_{p}^{\eta-2}(\tau)} + \| \mathbb{S} u \|_{\mathbb{H}_{p}^{\eta-1}(\tau,\ell_2)} + \| u_0 \|_{U_{p}^{\eta}}.
\end{equation*}

\end{enumerate} For another bounded stopping time $\bar{\tau}\le \tau$, we write $\mathcal{H}_{p}^{\eta}( \bar{\tau},\tau)$ for the corresponding space on the shifted time interval $\text{\,\raise.2ex\hbox{${\scriptstyle
|}$}\kern-.34em$($} \bar{\tau},\tau\text{$]$\kern-.15em$]$}$.

[Thm 13 (Local Martingale Criterion) of arXiv:2606.04245, 'Properties of a Special Type of Filtration and its Martingale Criteria'] Let $F=(F(t))_{t\in\cT}$ be an $\cH$-measurable process with càdlàg paths and $\EE[\sup\limits_{t\in[0,t_G)} |F(t)|]<+\infty$. Let $L$ be an integrable random variable (i.e., $\EE[|L|]<+\infty$).
    We define the process $M = (M_t)_{t\in\RRl_+} $ by the equality: 
    \begin{equation}
       M_t =F(t)\ind_{\{t<\gamma\} }+L\ind_{\{t\geq \gamma\}}. 
    \end{equation}   
    Then the following are equivalent: 
    \begin{enumerate}
        \item  $(M_t)_{t\in\cT}$ is a martingale.
        \item  The process $M$ is local martingale on $\RRl_+$, and the following equality holds on the set $\{\gamma=t_G\}$: 
        $$
        \EE(L|\cH)\ind \{\gamma=t_G\}=F(0)\ind \{\gamma=t_G\}
        $$
    \end{enumerate}

