[Theorem thm:multi of arXiv:2601.10359, 'An Operator It\^o Formula for Volterra Gaussian Processes:\\ The Intrinsic Bracket via Cau'] Let $W$ be a standard Brownian motion and let $X = (X^1,\ldots,X^n)$ where each $X^i_t = \int_0^t K_i(t,s)\,dW_s$ is a centered Volterra Gaussian process driven by the same $W$, with each $K_i$ satisfying the Decreusefond--\"Ust\"unel conditions.
Let $\varphi\in C^3_b(\mathbb{R}^n)$. Then
\begin{align*}
\varphi(X_t) &= \varphi(0) + \sum_{i=1}^n \delta(\partial_i\varphi(X)\Pi DX^i\cdot\mathbf{1}_{[0,t]})\\
&\quad + \frac{1}{2}\sum_{i,j=1}^n \int_0^t \partial_i\partial_j\varphi(X_s)\,d\langle X^i, X^j\rangle^{(D,\Pi)}_s.
\end{align*}

[Lemma criterion_survival of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] [maillard2025generalisedprincipaleigenvaluesglobal]
    Suppose there exists a bounded measurable function $q:\mathbb{R}^d \to \mathbb{R}$, $\delta \in (0,1)$, and $\rho\geq 1$ such that, for every $x\in \mathbb{R}^d$,
    \begin{equation}
        \mathbb{E}_x\Big[\sum_{v\in I_1^{T_0,\epsilon}}q(X_t(v))\exp\Big( -\delta \sum_{v\in I_1^{T_0,\epsilon}}q(X_t(v)) \Big)\Big] \geq \rho q(x).
    \end{equation}
    Then, if $q(x)>0$, $ \proba{x}{}{\# I_n^{T_0,\epsilon} \neq 0 \ \forall n\in \mathbb{N} } \geq  \proba{x}{}{\liminf_{n\to \infty}\rho^{-n}\# I_n^{T_0,\epsilon}>0  }\geq 1-e^{-\delta q(x)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main_spectral of arXiv:2603.24803, 'Critical Spectral Invariants in Random Walks with Geometric Resetting'] The ruin probability under geometric resetting with rate $\gamma \in (0,1)$ 
admits the closed-form spectral representation
\begin{equation}

\boxed{
q_z(\gamma) 
= \frac{\displaystyle \sum_{\nu=1}^{a-1} A_\nu(z)\, f_\nu(\gamma)}
{\displaystyle \sum_{\nu=1}^{a-1} \big[A_\nu(z) + B_\nu(z)\big]\, f_\nu(\gamma)}
}
\end{equation}
where $f_\nu(\gamma)$, $\lambda_\nu$, $A_\nu(z)$, and $B_\nu(z)$ are given 
by~(equation eq:f_nu of the paper), (equation eq:eigenvalues of the paper), (equation eq:A_nu of the paper), 
and~(equation eq:B_nu of the paper), respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: f Lipschitz with respect to alpha norm of arXiv:2609.03589, 'Correlated initialization of deep residual networks'] Let \(\sigma\colon \mathbb{R}\times \banachSpace[W] \times \banachSpace[X] \to \linOp{\banachSpace[V]}{\banachSpace[X]}\) satisfy Assumption (assmpt: sufficiently nice function of the paper),
    Then for every \(R>0\) there exist \((const: f holder bound of the paper), (const: f_bound of the paper) > 0\)
    such that for all \(w\in C^\alpha([0,T], \banachSpace[W])\) with \(\norm{w}_\alpha \le R\)
    and all \(x,y \in C^\alpha([\underline{t},\overline{t}], \banachSpace[X])\)
    \begin{align}

        \holder{f(y) - f(x)}_{\alpha, [\underline{t}, \overline{t}]}
        &\le (const: f holder bound of the paper)
        (1+\norm{x}_{\alpha, [\underline{t}, \overline{t}]}
        + \norm{y}_{\alpha, [\underline{t}, \overline{t}]})
        \Bigl(
            \holder{y-x}_{\alpha,[\underline{t},\overline{t}]}
            +\min_{t\in [\underline{t}, \overline{t}]}\abs{x_t-y_t}
        \Bigr)
        \\

        \holder{f(x)}_{\alpha, [\underline{t}, \overline{t}]}
        &\le (const: f_bound of the paper)(1+\norm{x}_{\alpha, [\underline{t}, \overline{t}]}).
    \intertext{And with the additional assumption (it: extra assumption of the paper) it holds that
        for all \(R, \tilde R > 0\) there exists \((const: f w diff holder bound of the paper) > 0\) such that
        for all \(w, \tilde w \in C^\alpha([0,T], \banachSpace[W])\)
        with \(\norm{w}_\alpha, \norm{\tilde w}_\alpha \le R\)
        and all \(x\in C^\alpha([\underline{t},\overline{t}], \banachSpace[X])\) with \(\norm{x}_\alpha \le \tilde R\)
    }

        \holder{f(w,x) - f(\tilde w, x)}_{\alpha, [\underline{t}, \overline{t}]}
        &\le (const: f w diff holder bound of the paper)\norm{w-\tilde w}_\alpha .
    \end{align}
    Moreover the constants may be chosen as
    \begin{align}
        \defConst{f holder bound}
        &\coloneq \abs{D_x\sigma(0,0,0)} + 2 K_c^R(1+R)(1+T^\alpha)
        & K_c^R \coloneq \smash{\max_{\substack{t\in [0,T]\\ r,s \in [0, R]}}}
        \max\set[\big]{c(t, r, s), \mathsf c(r) }< \infty
        \\
        \defConst{f_bound}
        &\coloneq K_c^R(1+2R)
        \\
        \defConst{f w diff holder bound}
        &\coloneq \abs{D_w \sigma(0, 0, 0)} + K_c^{R, \tilde R}(1+2\tilde R + 3R + T^\alpha)
    \end{align}
    with
    \[
        K_{c}^{R, \tilde{R}} \coloneq \max_{\substack{t\in [0,T]\\ r_w,s_w \in [0, R]\\ r_x,s_x \in [0, \tilde R]}}
        \max\set[\big]{\tilde c(t, r_w, s_w, r_x, s_x), \tilde{\mathsf c}(r_w, r_x)}
        < \infty.
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 1 ({\cite[Theorem D) of arXiv:2608.28234, 'A note on the positivity of $Q$-curvature via the continuity method'] {GurMal2015}}]
Let $(M^n, g)$ be a closed Riemannian manifold of dimension $n \geq 5$ satisfying 
\begin{equation}
Q_{g} \geq 0, ~~ Q_g \not\equiv 0, ~~ R_g \geq 0.
\end{equation}
Then there is a conformal metric $\tilde{g}:= u^{4/(n-4)}g$ with positive scalar curvature and constant positive $Q$-curvature. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Prop_SlicesAreTameFrechetSubmanifolds of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] For every $(Z_0,[{\mathfrak l}_0]) \in \mathbf{Ram}$, normal data $(N,h,I)$ for $Z_0$, and $({\mathbf{p}},[{\mathfrak l}]) \in \mathbf{Sl}$ the tangent space $T_{{\mathbf{p}},[{\mathfrak l}]}\mathbf{Sl}$ decomposes into three tame Fréchet space subspaces
  \begin{align*}
    T_{{\mathbf{p}},[{\mathfrak l}]}\mathbf{Sl}
    =
    H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl} \oplus V_{\mathscr{G};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl} \oplus V_{\nabla,\mathrm{Uh};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}
  \end{align*}
  defined by
  \begin{align*}
    H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}
    &\coloneq
      \set[\big]{
      (\dot g;\dot\gamma^\mathrm{BG},\dot\nabla^\mathrm{BG};0) \in H_{\mathrm{BG};{\mathbf{p}},[{\mathfrak l}]}
      :
      \dot g|_Z \in \Gamma(Z,\Hom(S^2TZ,\mathbb{R}))
      }, \\
    V_{\mathscr{G};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}
    &\coloneq
      \set[\big]{
      (0;[\xi,\gamma],-\nabla\xi;0) \in V_{\mathscr{G};{\mathbf{p}},[{\mathfrak l}]}
      :
      [\xi|_Z,\gamma|_{\Lambda^2N}] = 0
      }, \quad\text{and} \\
    V_{\nabla,\mathrm{Uh};{\mathbf{p}},[{\mathfrak l}]}^\mathbf{Sl}
    &\coloneq
      V_{\nabla,\mathrm{Uh};{\mathbf{p}},[{\mathfrak l}]};
  \end{align*}
  in particular,
  $V_{\nabla;{\mathbf{p}}} \oplus 0 \subseteq T_{{\mathbf{p}},[{\mathfrak l}]}\mathbf{Sl}$.

