[Lemma lem:asy_theta of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] The $\alpha$-stable theta function $\theta_{\alpha}(x, \tau)$ defined in (equation theta of the paper) satisfies the following asymptotic properties for $x \in \mathbb{T}^d$ and $\tau > 0$.
\begin{enumerate}
     \item[(i)] \textbf{(Small $\tau$ regime)} As $\tau \to 0$,
    \begin{equation}
        \theta_{\alpha}(x, \tau) = f_{\alpha}(x, \tau) + O(\tau).
    \end{equation}
    \item[(ii)] \textbf{(Large $\tau$ regime)} As $\tau \to \infty$,
    \begin{equation}
        \theta_{\alpha}(x, \tau) = 1 + O\big(e^{-c_{\alpha} (2\pi)^{\alpha} \tau}\big).
    \end{equation}
    \item[(iii)] \textbf{(Uniform upper bound)} There exists a constant $C > 0$ such that
    \begin{equation}
        \theta_{\alpha}(x, \tau) \le C\big(1 + \tau^{-\frac{d}{\alpha}}\big).
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 (Geometric meaning of the trisecant sign) of arXiv:2609.00285, 'Multicrossing complex of knot and secant classes'] Assume that $\nu$ is the unit vector of the axis $Oz$ and $s$ is a horizontal trisecant on arcs $\alpha_1(t)$, $\alpha_2(t)$ and $\alpha_3(t)$ in a plane $z=z_0$. Assume also that $(\dot\alpha_i,\nu)>0$, $i=1,2,3$.
\begin{enumerate}
    \item Let $\sgn(s)\ne 0$.  Then for a small $\epsilon>0$, the sign $\sgn(s)$ coincides with the orientation of the triangle $A_1A_2A_3$ where $A_i=\alpha_i\cap\{z=z_0+\epsilon\}$ (see Fig.~\ref{fig:positive_trisecant}).
\begin{figure}
    \centering
    \includegraphics[width=0.4\linewidth]{pics/positive_trisecant.eps}
    \caption{A positive trisecant}

\end{figure}

\item Denote the surface formed by horizontal $2$-secants on $\alpha_1(t)$ and $\alpha_3(t)$ by $B(\alpha_1,\alpha_3)$. Then $\sgn(s)=0$ if and only if $\alpha_2(t)$ is tangent to $B(\alpha_1,\alpha_3)$ at $t=0$.
\end{enumerate}

