[Theorem 1 (Forest stabilization result) of arXiv:2506.10476, 'Construction of ergodic \textsc{idla} forests in $\mathbb{Z}^d$'] Let $d \geq 2$. For all $n \geq 1$ and $K \geq 1$, the following holds with probability one: 
\begin{equation}

	\exists N_0 = N_0(n,K) \geq 0 , \, \forall N \geq N_0 , \, \fdag{n}[N] \cap \mathbb{Z}_K = \fdag{n}[N_0] \cap \mathbb{Z}_K ~,
\end{equation}
where the above identity means that all vertices and edges of $\fdag{n}[N]$ and $\fdag{n}[N_0]$ inside the strip $\mathbb{Z}_K$ coincide. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor.DF_cancel of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Under the setting of Lemma~(lem.decom_DF of the paper), the following observations hold.
		\begin{enumerate}
			\item If $F \nsubseteq \mathcal{E}(\mathscr{C}_{\operatorname{bc}}^F({\scaleobj{1}{\square}}_m))$, i.e. $F_\circ \neq \emptyset$, then 
			\begin{align}
				\forall x \in \mathscr{C}_{\operatorname{bc}}^F({\scaleobj{1}{\square}}_m), \qquad (D_F v_m)(x) = 0.
			\end{align}
			\item For all $x \in  {\scaleobj{1}{\square}}_m \setminus  \mathscr{C}_{\operatorname{bc}}^F({\scaleobj{1}{\square}}_m)$, if $F_\circ \nsubseteq \mathcal{E}(\mathscr{O}^{F_\circ}(x))$, then $(D_F v_m)(x) = 0$.
		\end{enumerate}

