[Proposition finalfuckpropositionga of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $A_{n+1}\sim\operatorname{Sym}_{n+1}(\zeta)$, $X\sim\operatorname{Col}_n(\zeta)$  and $\lambda_1,\lambda_2\in\mathbb{R}$ . For any $p>1$ and $\delta_1,\delta_2>0$, we have the following estimate:
    $$\begin{aligned}
           &\mathbb{P}(\sigma_{min}(A_{n+1}-\lambda_i I_{n+1})\leq\delta_i n^{-1/2},i=1,2)\lesssim \delta_1\delta_2+e^{-\Omega(n)}\\&+\sup_{r_1,r_2\in\mathbb{R}}\mathbb{P}_{A_n,X}\left(
    \frac{|\langle (A_n-\lambda_i I_n)^{-1}X,X\rangle-r_i|}{\|(A_n-\lambda_i I_n)^{-1}X\|_2}\leq\delta_i,i=1,2,\frac{\mu_1(\lambda_1)\mu_1(\lambda_2)}{n}\leq(\delta_1\delta_2)^{-p}
    \right),\end{aligned}$$ where we denote $\mu_1(\lambda_i):=\sigma_{max}((A_n-\lambda_i I_n)^{-1})$ for both $i=1,2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:spectralfracpw of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [MR3772040] 
Let $\beta \in (0,1)$,  $w,z\ge 0$ and $w^\beta + z >0$.  Then
\begin{align}
	\frac{1}{w^{\beta} + z} = \frac{\sin (\pi \beta )}{\pi}  \int_{0}^\infty \frac{1}{ s^\beta ( w+s ) \sigma_\beta (s,z)} {\rm d} s 

\end{align}
where $\sigma_{\beta} (s, z) =  1 + s^{-2\beta} z^2 + 2 z s^{-\beta} \cos (\pi \beta) > 0$ whenever $s > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 26 of arXiv:2608.26662, 'Boundary–Moment Universality and Curvature Corrections in Random Geometric Graphs on Riema'] There exist constants $C<\infty$ and $r_0>0$ such that, for every
$n\ge3$ and $0<r<r_0$, the path--triangle contrast satisfies
\begin{equation}
\operatorname{Var} C_n(r)
\le
C\left(
n^3r^{2d}
+n^4r^{3d}
+n^5r^{4d+4}
\right).
\end{equation}
Accordingly, its normalized estimator obeys
\begin{equation}
\operatorname{Var}\widehat{\mathcal G}_{3,n}(r)
\le
C\left(
\frac1{n^3r^{2d+4}}
+
\frac1{n^2r^{d+4}}
+
\frac1n
\right).
\end{equation}

Now let $r_n\downarrow0$.  If the bandwidth sequence satisfies
\begin{equation}
n^3r_n^{2d+4}\longrightarrow\infty,
\qquad
n^2r_n^{d+4}\longrightarrow\infty,
\end{equation}
then the normalized contrast consistently estimates the intrinsic functional:
\[
\widehat{\mathcal G}_{3,n}(r_n)
\xrightarrow{\Pp}
\mathcal G_3(f;g).
\]

[Dfn of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] A sequence $(\eta_n)_{n\geq 1} \subset \mathcal{M}_{reg}^+$ is said to converge $m$-weakly to $\eta \in \mathcal{M}_{reg}^+$ if the following is satisfied:
	\begin{enumerate}
		\item[(i)]  For all open sets $U \subset \mathbb{R}$ such that $\eta(U) = \infty$ it follows that $\lim_{ n\rightarrow \infty}\eta_n(U) = \infty$.
		\item[(ii)] For all compact sets $K \subset \mathcal{R}_\eta$ there exists $M>0$ and $N \in \mathbb{N}$ such that $\eta_n(K) <M$ for all
		$n \geq N$.
		\item[(iii)] For all $\phi \in \mathcal{C}_c(\mathcal{R}_\eta)$ it holds that 
		\begin{equation*}
			\lim_{n \rightarrow \infty}\int \phi d\eta_n = \int \phi d\eta.
		\end{equation*} 
	\end{enumerate}

[Proposition pro:approximation_cluster of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] There exist finite positive constants $C_1$ and $s_1$ that depend on $d,\mathfrak{p}$ such that, for every $t>0$, the following holds:
		\begin{multline}
			\sup_{f\in 1\text{-}\mathrm{Lip}(\mathbb{R}^d)} \Bigg\vert \sum_{x: x + y\in\mathscr{C}_\infty}f(x)\theta(\mathfrak{p})^{-1}\bar{p}(t,x)-\int_{\mathbb{R}^d}f(x)\bar{p}(t,x)\, {\mathrm{d}} x\Bigg\vert \\
			\leqslant 
			\left\{ 		
			\begin{array}{ll}
				\mathcal{O}_{s_1}\left(C_1\lfloor\frac{1}{2}\log_3t \rfloor\right),  & d=2,  \\ 
				\mathcal{O}_{s_1}(C_1), & d\geqslant 3.
			\end{array}\right. 
		\end{multline} 


		Moreover, for each $\delta >0$, there exist finite positive constants $C_2$ and $s_2$ that depend on $d,\mathfrak{p},\delta$ and a nonnegative $\omega$-measurable random variable $\mathcal{T}_{dense,\delta}(y)$ satisfying
		\begin{equation}
			\forall T\geqslant 0, \qquad \mathbb{P}_{\mathfrak{p}}\left(\mathcal{T}_{dense,\delta}(y)\geqslant T\right)\leqslant C_2 \exp\left(-\frac{T^{s_2}}{C_2}\right),
		\end{equation}
		such that on the event $\{y\in\mathscr{C}_\infty\}$, for every $t>\mathcal{T}_{dense,\delta}(y)$, we have 
		\begin{equation}
			\sup_{f\in 1\text{-}\mathrm{Lip}(\mathbb{R}^d)}\Bigg\vert \sum_{x: x + y\in\mathscr{C}_\infty}f(x)\theta(\mathfrak{p})^{-1}\bar{p}(t,x)-\int_{\mathbb{R}^d}f(x)\bar{p}(t,x)\, {\mathrm{d}} x\Bigg\vert\leqslant C_2t^\delta.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:GaussianMatrix2 of arXiv:2410.23915, 'Asymptotic Bounds and Online Algorithms for Average-Case Matrix Discrepancy'] The joint probability density function of two $m \times m$ GOE matrices with correlation $\rho \in (-1,1)$ is given by
        \begin{equation*}
            (X,Y) \mapsto K_{m}^2 (1 - \rho^2)^{-m(m+1)/4} \exp{-\frac{\tr(X^2 - 2\rho XY + Y^2)}{4(1 - \rho^2)}}
        \end{equation*}
        on the space of pairs of $m \times m$ symmetric matrices, where the constant $K_m$ is defined as in (equation eq:NormalizationConstant1 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma ske-lem of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper), and $\rho$ be a nonnegative function satisfying $\mathcal{I}(\rho)<+\infty$, then there
exists a function $\Psi^{\rho}$, such that $\sqrt{\rho}\nabla\Psi^{\rho} \in L^2_{[0,T]}L^2_{\mathbb{T}^2}$, and $\rho$ is a weak solution of 
\begin{equation}
\partial_t\rho+\nabla\cdot(\rho \mathcal{V}[\rho])=\Delta\rho-\nabla\cdot(\rho\nabla\Psi^{\rho}),
\end{equation}
and the rate function $\mathcal{I}$ defined in (equation I0-intro of the paper) has an equivalent representation
\begin{align}
\mathcal{I}(\rho)=\frac{1}{2}\|\sqrt{\rho}\nabla\Psi^{\rho}\|_{L_{[0,T]}^2L^2_{\mathbb{T}^2}}^2.
\end{align}
If we further assume that $\rho \in L^\infty_{[0,T]}L^\infty_{\mathbb{T}^2}$,  then $\rho$ is also a renormalized kinetic solution of the skeleton equation (equation ske of the paper) with control $g=\sqrt{\rho}\nabla\Psi^{\rho}$.

[Definition 30 (The support of a measure and the range of a measure-valued process) of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu \in \mathcal{M}_F(\mathbb{R}^d)$. Then $\mathbb{R}^d$ has a largest open subset $U_\mu$ such that $\mu(U_\mu)=0$ -- this is the union of all open subsets $U$ such that $\mu(U)=0$. The \emph{support} of $\mu$ is defined to be $\text{supp}(\mu) \coloneqq \mathbb{R}^d \backslash U_\mu$.
    \par
    For a measure-valued c\`adl\`ag process $\mathcal{W}=(\mathcal{W}_s)_{s \geq 0}$ we define the \emph{range} to be 
    \begin{equation*}
        \mathcal{R}(\mathcal{W}) = \bigcup_{\delta > 0} \overline{\bigcup_{y \geq \delta} \text{supp}(\mathcal{W}_y)}.
    \end{equation*}

