[Theorem thLIL2 of arXiv:2608.30848, '\huge \bf Limit Laws of the Iterated Logarithm Under Sub-linear Expectations'] Assume ((eqLILmomentcondition1 of the paper)), ((eqLILmeanzerocondition of the paper)), ((eqLILmomentcondition2 of the paper)), ((eqLILmomentcondition3 of the paper)), and condition (CC) holds for the family of probability measures $\mathscr{P}$. Then
 \begin{description}
   \item[\rm (i)] For any continuous function $\sigma(x_1,x_2,\ldots)$ on $\mathbb R^{\mathbb N}$ taking values in $[\underline{\sigma},\overline{\sigma}]$, there exists $P\in\mathscr{P}$ such that
 \begin{align} 
 P\bigg(Cl\bigg\{\frac{S_n}{\sqrt{2n\log\log n}}\bigg\}=\Big[-\sigma(Y_1,Y_2,\ldots),\sigma(Y_1,Y_2,\ldots)\Big]\bigg)=1,
 \end{align}
 \begin{align}
 &P\bigg(\lim_{n\to \infty} \max_{k\le n} \frac{S_k}{\sqrt{2k\log\log n}}=\sigma(Y_1,Y_2,\ldots) \nonumber\\
 & \qquad \text{and } \lim_{n\to \infty} \min_{k\le n} \frac{S_k}{\sqrt{2k\log\log n}}=-\sigma(Y_1,Y_2,\ldots)\bigg)=1;
  \end{align}
   \item[\rm (ii)] For any finite-dimensional Borel-measurable function $\sigma(x_1,\ldots,x_d)$ taking values in $[\underline{\sigma},\overline{\sigma}]$, there exists $P\in\text{core}(\widehat{\mathbb E})$ such that ((eq:thLIL2:1 of the paper)) and ((eq:thLIL2:2 of the paper)) hold for $\sigma(x_1,x_2,\ldots)=\sigma(x_1,\ldots,x_d)$.
 \end{description}

 It is easy to see that in (i), replacing $P$ by $\mathbb V^{\mathscr{P}}$ or $\widehat{\mathbb V}^{\ast}$, ((eq:thLIL2:1 of the paper)) and ((eq:thLIL2:2 of the paper)) hold; in (ii), replacing $P$ by $\mathbb V^{\text{core}(\widehat{\mathbb E})}$ or $\widehat{\mathbb V}^{\ast}$, ((eq:thLIL2:1 of the paper)) and ((eq:thLIL2:2 of the paper)) hold. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 25 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Let $\lambda\in\Delta_d$, let $k_t\in\N^d$ satisfy $|k_t-t\lambda|_1=o(t)$, and let $r>0$. If $r>\kappa(\lambda)$, then

\begin{equation*}
- r\inf_{y\in B^<(\lambda/r)}I_Y(y)
\leq
\liminf_{t\to\infty}\frac{1}{t}\log \Pp_{\mathfrak a}(\mathfrak N(k_t)\geq rt)
\end{equation*}

and

\begin{equation*}
\limsup_{t\to\infty}\frac{1}{t}\log \Pp_{\mathfrak a}(\mathfrak N(k_t)\geq rt)
\leq
- r\inf_{y\in B^\leq(\lambda/r)}I_Y(y).
\end{equation*}

If $0<r<\kappa(\lambda)$, then

\begin{equation*}
- r\inf_{y\notin B^\leq(\lambda/r)}I_Y(y)
\leq
\liminf_{t\to\infty}\frac{1}{t}\log \Pp_{\mathfrak a}(\mathfrak N(k_t)< rt)
\end{equation*}

and

\begin{equation*}
\limsup_{t\to\infty}\frac{1}{t}\log \Pp_{\mathfrak a}(\mathfrak N(k_t)< rt)
\leq
- r\inf_{y\notin B^<(\lambda/r)}I_Y(y).
\end{equation*}

In particular, whenever the two infima in the corresponding upper and lower bounds coincide, the logarithmic limit exists.

