[Lemma lem-alpha>2-second-round of arXiv:2607.22324, 'The conclave process'] {}
    When $\alpha\geq 2$, define
    \begin{align*}
        \mathfrak M_{\alpha} = \Big\{ & (M,\delta): \frac{(\log n)^{\alpha}}{(\log\log n)^{2\alpha}} \leq M \leq (\log n)^{\alpha}(\log \log n)^\alpha,  \\
        & \frac{(\log \log n)^{-300-\alpha}}{\log n} \leq \delta \leq \frac{(\log \log n)^{300+\alpha}}{\log n} \Big\} \,.  
    \end{align*}
    Also define
    \begin{align*}
        \mathfrak M_{\alpha}' = \Big\{ & (M,\delta): \frac{(\log n)^{\alpha}}{(\log \log n)^{2\alpha}} \leq M \leq (\log n)^{\alpha}(\log \log n)^\alpha, \\
        &\frac{(\log \log n)^{-300-\alpha}}{(\log n)^{\frac{\alpha}{2}}} \leq \delta \leq \frac{(\log \log n)^{300+\alpha}}{(\log n)^{\frac\alpha 2}}  \Big\} \,.
    \end{align*}
    We have
    \begin{align*}
        &\mathbb P_n^{\alpha}\left( (\mathbf X^{(1)}_2,\ldots,\mathbf X^{(n)}_2) \in \cup_{(M,\delta) \in \mathfrak M_\alpha} \overline{\Omega}_n(M,\delta) \mid E_{\mathsf{unique}} \right) = 1-o(1) \,; \\
        &\mathbb P_n^{\alpha}\left( (\mathbf X^{(1)}_2,\ldots,\mathbf X^{(n)}_2) \in \cup_{(M,\delta) \in \mathfrak M_\alpha'} \overline{\Omega}_n(M,\delta) \mid E_{\mathsf{unique}}^c \right) = 1-o(1) \,.
    \end{align*}
    Moreover, for $\alpha > 2$ we have
    \begin{align*}
        &\mathbb P_n^{\alpha}\Big( \mathcal L(\mathbf X_2) = \mathcal L(\mathbf X_1)  \mid E_{\mathsf{unique}} \Big) = 1-o(1) \,; \\
        &\mathbb P_n^{\alpha}\Big( \mathcal L(\mathbf X_2) \subsetneq \mathcal L(\mathbf X_1), |\mathcal L(\mathbf X_2)| = 1  \mid E_{\mathsf{unique}}^c \Big) = 1-o(1) \,.
    \end{align*}

