[Definition 13 (Admissible Fourier-multiplier Gaussian forcing) of arXiv:2607.10813, '2607.10813'] Let the channel-dependent upper orders $\betaW,\betaK$ satisfy
\eqref{eq:parameter-vector}.  For $a\in\mathfrak C$, let
\[
 \mathfrak h_a\in S^{\beta_a}_{1,0}(\R^3;\R),
 \qquad
 \mathfrak h_a(-\xi)=\mathfrak h_a(\xi).
\]
For $L\in\N_0$, set
\begin{equation}
 [\mathfrak h_a]_{\beta_a,L}
 :=\max_{|\alpha|\le L}\sup_{\xi\in\R^3}
 \langle\xi\rangle^{-\beta_a+|\alpha|}
 |\partial_\xi^\alpha\mathfrak h_a(\xi)|<\infty.
\end{equation}
Set
\begin{equation}
 \mathfrak H_{\mathrm{prof}}
 :=\max_{a\in\mathfrak C}[\mathfrak h_a]_{\beta_a,0}
 =\max_{a\in\mathfrak C}\sup_{\xi\in\R^3}
   \langle\xi\rangle^{-\beta_a}|\mathfrak h_a(\xi)|.
\end{equation}
For a real test function
$\varphi\in C_c^\infty((0,\infty)\times\R^3)$, the multiplier
$\mathfrak h_a(D_x)$ acts only in the spatial variable.  The map
$\varphi\mapsto\mathfrak h_a(D_x)\varphi$ is continuous from
$C_c^\infty((0,\infty)\times\R^3)$ to the real Gaussian Hilbert space
$\mathfrak H$.  Hence the formula
\begin{equation}
 \xi_a(\varphi):=\mathbf W_a(\mathfrak h_a(D_x)\varphi),
 \qquad a\in\mathfrak C,
\end{equation}
defines a real centered Gaussian random distribution.  Set
\[
 \mathfrak q_a(\xi):=|\mathfrak h_a(\xi)|^2,
 \qquad
 Q_a:=\mathfrak h_a(D_x)^*\mathfrak h_a(D_x)
      =\mathfrak h_a(D_x)^2.
\]
Then $\mathfrak q_a(\xi)\lesssim\langle\xi\rangle^{2\beta_a}$ and
\begin{equation}
\begin{aligned}
 \E[\xi_a(\varphi)\xi_b(\psi)]
 &=\delta_{ab}
   \langle\mathfrak h_a(D_x)\varphi,
          \mathfrak h_a(D_x)\psi\rangle_{\mathfrak H}\\
 &=\delta_{ab}\int_0^\infty
   \langle Q_a\varphi(t),\psi(t)\rangle_{L_x^2}\dd t.
\end{aligned}
\end{equation}
Equivalently, in the non-conjugated Fourier random-measure convention,
\begin{equation}
 \E[\widehat\xi_a(\dd\xi,\dd t)
       \widehat\xi_b(\dd\eta,\dd s)]
 =\delta_{ab}(2\pi)^3\delta(t-s)\delta(\xi+\eta)
  \mathfrak q_a(\xi)\dd\xi\dd\eta\dd t\dd s.
\end{equation}
Thus the forcing is white in time, stationary in space, and independent
between the two colors.  Its law depends on the profile only through the
spectral density $\mathfrak q_a$.

[Lemma lem:F-properties of arXiv:2606.10973, 'Quasisymmetric rigidity of the Brownian sphere'] \begin{enumerate}
        \item The event $F_{\zz,\rr,\SCI}$ is almost surely determined by $\Phi_2|_{A_{\rr/2,\rr}(\zz)}$ modulo additive constant. 
        \item The probability $\BP\lbrack F_{\zz,\rr,\SCI}\rbrack$ does not depend on $\zz$ and $\rr$. 
        \item For each $q \in (0,1)$, we may choose the parameter $a$ sufficiently small, depending only on $\eta$ and $q$, so that $\BP\lbrack F_{\zz,\rr,\SCI}\rbrack \ge q$ for every sequence of admissible intervals $\SCI$.
    \end{enumerate}

