[Lemma ferrestimate of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Consider the function {\small$\mathfrak{f}_{\mathrm{err}}$} from (equation eq:msheIIfa of the paper)-(equation eq:msheIIfe of the paper). We have the identity 

\begin{align}
[\mathscr{S}^{N}\star(\mathfrak{f}_{\mathrm{err}}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot})]_{\x}&=[\mathscr{S}^{N}\star(\mathfrak{f}_{\mathrm{err}}[\tau_{\cdot}\bphi_{\t}]\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}.
\end{align}

Also, the operator {\small$\mathsf{f}_{\cdot}\mapsto\mathscr{S}^{N}\star(\mathfrak{f}_{\mathrm{err}}[\tau_{\cdot}\bphi_{\t}]\mathbf{R}^{N}_{\t,\cdot}\mathsf{f}_{\cdot})$}, which acts on functions {\small$\mathsf{f}:\Z\to\R$}, satisfies the following pointwise estimate (in which {\small$\delta_{\mathbf{S}}$} is a small parameter from Definition (definition:zsmooth of the paper) and {\small$\mathrm{C}=\mathrm{O}(1)$}):

\begin{align}
|[\mathscr{S}^{N}\star(\mathfrak{f}_{\mathrm{err}}[\tau_{\cdot}\bphi_{\t}]\mathbf{R}^{N}_{\t,\cdot}\mathsf{f}_{\cdot})]_{\x}|\lesssim N^{-\frac12+\mathrm{C}\delta_{\mathbf{S}}}\cdot N^{-1+\delta_{\mathbf{S}}}\sum_{|\w|\lesssim N^{1-\delta_{\mathbf{S}}}}\Big(1+\sum_{|\z|\lesssim1}|\bphi_{\t,\x+\w+\z}|^{\mathrm{C}}\Big)\cdot|\mathbf{R}^{N}_{\t,\x+\w}|\cdot|\mathsf{f}_{\x+\w}|.
\end{align}

[Lem 13 of arXiv:2607.22414, 'Asymptotic fluctuations in supercritical multi-type Crump--Mode--Jagers processes'] Assume~\ref{assumpt:Malthusian alpha}. Let $f : \R \to \R^p$ be a deterministic c\`adl\`ag characteristic satisfying~\ref{assumpt:dRimean}. Then
	\begin{enumerate}[\normalfont(i)]
		\item $\chi_f$ is a well-defined, c\`adl\`ag, centered characteristic.
		\item  If~\ref{assumpt:hreprMoments} holds and the function $t \mapsto m_t^f e^{-\frac\alpha2 t} (1 + t^2)$ is bounded,
		then $\chi_f$ satisfies~\ref{assumpt:dRimean} through~\ref{assumpt:local ui}.
		\item If the assumptions of~\ref{item:chif1} hold or $f$ is supported on $[0,\infty)$, then	
		\begin{equation}
			\cZ_t^{\chi_f} = \cZ_t^f - \be_{\tau(\varnothing)}^\trans m_t^f.
		\end{equation}
	\end{enumerate}

