body:
[Proposition 12 of arXiv:2608.30570, '2608.30570'] There exists $\epsilon_0=\epsilon_0(m,n)>0$ such that the following holds.

	Assume  $\Sigma$ is an $m$-dimensional complete immersed submanifold in ${\mathbb R}^n$.
    \begin{enumerate}
    \item If $A\subset \Sigma$ is a set of finite perimeter such that  $$\int_{A}|{\bf H}|^md\mathrm{vol}\le \epsilon_0,$$
then the isoperimetric inequality holds
\begin{align}
\left(\mathcal{H}^{m}(A)\right)^{1-\frac{1}{m}}\le D_1 \mathcal{H}^{m-1}(\partial A)
\end{align}
for some  $D_1=D_1(m,n)<\infty$.
\item  If there exists $r_1>0$ such that
        \begin{align}
        \lim_{R\to \infty}\sup_{x\in \Sigma\backslash \hat{B}_{R}(p_0)}\int_{\hat{B}_{r_1}(x)}|{\bf H}|^md\mathrm{vol}\le \epsilon_0,
        \end{align}
 then there exists a compact subset $K\subset \Sigma$ such that  for any $\hat{B}_r(x)\subset \Sigma\backslash K$ with $r\le r_1$, there holds
\begin{align}
\mathrm{Vol}(\hat{B}_r(x))\ge \kappa r^m,
\end{align}
where $\kappa=\frac{1}{m^mD_1^m}$.

\item In addition to \eqref{finite total mean curvature},  if we also  assume
\begin{align*}
{\rm{Vol}}(\Sigma\cap B_R(0))<+\infty \  \ {\rm for \ all} \ R>0,
\end{align*}
then $\Sigma$ is properly immersed in $\mathbb{R}^n$ and only has  finitely many ends.
\end{enumerate}

