[Lemma Gen_lady-3 of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] In this lemma, we recall a couple to inequalities which will be used in the sequel:
		\begin{itemize}
			\item   The well-known Gagliardo-Nirenberg inequality  ([Nirenberg_1959]) gives (for $d\in \{2,3\}$)
			\begin{align}
				\|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|_{{3}} &\leq C \|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|^{\frac{12+d}{3(4+d)}}_{{2}} \|\nabla \textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|^{\frac{2d}{3(4+d)}}_{{4}}, && \quad \text{	for all } \; \textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\in \mathbb{L}^{2} (\mathbb{Q})\cap\mathbb{W}_0^{1,4}(\mathbb{Q}), \\
				\|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|_{{4}} &\leq C \|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|^{\frac{4}{4+d}}_{{2}} \|\nabla \textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|^{\frac{d}{4+d}}_{{4}}, && \quad \text{	for all } \; \textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\in \mathbb{L}^{2} (\mathbb{Q})\cap\mathbb{W}_0^{1,4}(\mathbb{Q}).
			\end{align}
			\item  There exists a constant $C_{S,d}>0$ ([Kesavan_1989]) such that 
			\begin{align}
				\|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|_{\infty} \leq C_{S,d} \|\nabla\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|_{4}, \quad \text{	for all } \;	\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\in	\mathbb{W}_0^{1,4}(\mathbb{Q}).
			\end{align}

			\item  There	exists a constant $C_{K,d}>0$	such	that (a Korn-type inequality, see	[DiFratta+Solombrino_Arxiv] and [Kondratev+Oleinik_1988])
			\begin{align}
				\Vert	\nabla \textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}} \Vert_{4}	\leq	C_{K,d}\Vert	\boldsymbol{\mathcal{E}}(\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}})	\Vert_4,\quad \text{	for all } \;	\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\in	\mathbb{W}_0^{1,4}(\mathbb{Q}).
			\end{align}		
			\item In view of (equation Sobolev-embedding3 of the paper) and (equation Korn-ineq of the paper), there exists a constant $\mathrm{M}_d>0$ such that
			\begin{align}
				\|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|_{\infty} \leq \mathrm{M}_d \|\boldsymbol{\mathcal{E}}(\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}})\|_{4}, \quad \text{	for all } \;	\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\in	\mathbb{W}_0^{1,4}(\mathbb{Q}).
			\end{align}

		\item In view of (equation Gen_lady-4 of the paper), (equation Korn-ineq of the paper) and Young's inequality, there exists a constant $\mathrm{N}_d>0$ such that
		\begin{align}
			\|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|^4_4 \leq \mathrm{N}_d\mathopen{}\mathclose\bgroup\originalleft[ \|\boldsymbol{\mathcal{E}}(\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}})\|_{4}^4 + \|\textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\|_{2}^4 \aftergroup\egroup\originalright], \quad \text{	for all } \;  \textbf{W}^{\varepsilon}_{{\theta}^{\varepsilon}}\in \mathbb{L}^{2} (\mathbb{Q} )\cap\mathbb{W}_0^{1,4}(\mathbb{Q} ).
		\end{align}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem prop-nSD of arXiv:2411.15401, 'The reference interval in higher-order stochastic dominance'] Fix $a,b,c,d\in\mathbb{R}$ with $a<b\le c<d$ and $n\in\mathbb{N}$.
\begin{align}

\mbox{For  all $X,Y\in\mathcal X_{[a,b]}$}:  X\ge_n^{[a,c]}Y ~\Longrightarrow~ 
 X\ge_n^{[a,d]}Y.
\end{align} 
The backward implication of (equation eq:implies of the paper) holds
if and only if  $n\le 3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 42 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] \begin{align}
			& x- \log(1+x) \geq 0 \;\;\forall x > -1,
			\\
			& x - \log(1+x) \leq x^2 \;\; \forall x > -\frac{1}{2}.
		\end{align}
		In particular, 
		\begin{align}
			0 \leq x - \log(1+x) \leq x^2 \;\; \forall |x| < \frac{1}{2}.
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

