body:
[Lemma 25 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] The functions $f_+$ and $f_-$ are strictly convex, satisfying
\begin{equation}
 f_+(0)=f_-(0)=0,\qquad f_-(1)=0,\qquad
 f_+(1)=-\log R.
\end{equation}
Moreover, there is a constant $c>0$ such that
\begin{align*}
 f_+(u)&\le-(\log R)u, \qquad0\le u\le1;\\
 f_-(u)&\le-cu, \qquad~\,\qquad0\le u\le\tfrac12;\\
 f_-(u)&\le-c(1-u), \qquad\tfrac12\le u\le1.
\end{align*}

[Corollary cor:randomtime of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] Let $\Theta$ be a nonnegative random time such that
  $\mathbb{E}[e^{\lambda \Theta}] < \infty$ for some $\lambda > 0$. Then
  \begin{equation}
    \mathbb{E}[H_\Theta^2] < \infty,
  \end{equation}
  and, more generally,
  \begin{equation}
    \mathbb{E}\!\left[\left(\int_{r_0}^{r_1} \beta_1^\Theta(r)\, \psi(r)\, dr\right)^{\!2}\right]
    < \infty
  \end{equation}
  for every bounded Borel $\psi$ supported in $[r_0, r_1]$.

[Thm wound simple loops WLE of arXiv:2508.13827, 'Surface sums in two-dimensional large-$N$ lattice Yang--Mills: Cancellations and explicit '] Let $\upbeta\in \mathbb{R}$. Suppose $\ell$ is a simple loop and set $a_{\ell}=\area(\ell)$. For $n\in \mathbb{N}$, let $\ell^n$ denote the loop $\ell$ wound around itself $n$ times. Then,
    \begin{equation}
        c(\ell^n, K_{\ell^n}) = \frac{(-1)^{n+1}}{n}\binom{na_{\ell}-2}{n-1},
    \end{equation}
    where, when $a_{\ell}=1$, the above expression should be interpreted as $c(\ell^n, K_{\ell^n}) =\mathds{1}_{n=1}$.
    In particular, since $\mathcal{K}_{\ell^n} = \{K_{\ell^n}\}$ thanks to (rem:card-set-cK of the paper), we deduce that
    \begin{align}
        \phi(\ell^n) = \frac{(-1)^{n+1}}{n}\binom{na_{\ell}-2}{n-1}\upbeta^{na_{\ell}}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2607.02406, 'On the range of competing random walks'] Let $f\in\mathcal S(\RR^d)$ and suppose that $\int_{\RR^d}\d x f(x)=1$. We let $\hat f$ denote the Fourier transform of $f$. Then for any $n\ge1$, $\delta\in(0,1)$, we may find a constant $C$ such that for any $x_1,\dots,x_n\in\RR^d$,
    \begin{equation*}
        \left|1-\prod_{k=1}^n\hat f(x_k)\right|\le C\sum_{k=1}^n|x_k|^\delta.
    \end{equation*}

