[Prop weak-triangle of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] For any probability measures $\mu$, $\nu$, $\pi$, any R\'enyi order $q \in [1,\infty]$, and any relaxation parameter $\lambda \in (0,1)$, 
    \begin{align*}
        \mathsf{R}_q(\mu \mathbin{\|} \pi) \leqslant \frac{q-\lambda}{q-1}\,\mathsf{R}_{q/\lambda}(\mu \mathbin{\|} \nu) + \mathsf{R}_{(q-\lambda)/(1-\lambda)}(\nu \mathbin{\|} \pi)\,.
    \end{align*}
    In particular (by setting $\lambda = 1-\varepsilon$, $q = 1+\varepsilon$, and letting $\varepsilon\searrow 0$),
    \begin{align*}
        \KL(\mu \mathbin{\|} \pi) \leqslant 2 \KL(\mu \mathbin{\|} \nu) + \log(1+\chi^2(\nu \mathbin{\|} \pi))\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 7 of arXiv:2606.00648, 'Asymptotic estimates for multiple point ranges of transient random walks on graphs'] Assume that $(U_1)$ holds and $F_{\inf} < 1$. 
Then for every $x \in \mathcal{X}$, 
\begin{equation} 
C_{\inf}(f) \le \liminf_{n \to \infty} \frac{G_n (f)}{n} \le C_{\sup}(f), \ \textup{ $P^x$-a.s.}  
\end{equation}

[Theorem KR of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Suppose that  $F:\Omega\times \EuScript{V}\to{\boldsymbol{U}}$ is an ample  $C^1$, Gaussian random field, $m=\dim{\boldsymbol{V}}=\dim{\boldsymbol{U}}$. Denote by $p_{F(v)}$ the probability density of the nondegenerate Gaussian vector $F(v)$. For any box $B\subset \mathscr{V}$ and any nonnegative  continuous function $w\in C(B)$ we set
 \[
 \EuScript{Z}_B(w,F)=\sum_{\substack{ F(v)=0,\\ v\in B} } w(v)\in [0,\infty].
 \]
 In particular $\EuScript{Z}(B,F):= \EuScript{Z}_B(1,F)$ is the number of zeros of $F$ in $B$. Then $\EuScript{Z}_B({\varphi}, F)$,  is measurable, $\mathrm{a.s.}$ finite  and
 \begin{equation}
{\mathbb E}\big[\,  \EuScript{Z}_B(w, F)\,\big]=\int_B w(v) \rho_{KR}(v) dv
\end{equation}
 where $\rho_{KR}$   is the  \emph{Kac-Rice density}
 \begin{equation}
 \rho_{KR}(v):= {\mathbb E}\big[\, J_{F}(v)\big\vert\, F(v)=0\,\big]  p_{F(v)}(0).
 \end{equation}\nobreak\hfill\penalty250 \hbox{}\nobreak\hfill$\rlap{$\sqcap$}\sqcup$\vskip\aline (Proof in the paper; no proof environment follows the statement in the TeX.)

