body:
[Definition 6 (Kunita-Watanabe projection) of arXiv:2606.08776, 'Approximation of certain stochastic integrals with anticipating integrands'] Let $\xi \in L_2$ be such that
\begin{equation}
\xi = \E \xi + \int_0^1 k_t dW_t \quad \mbox{ a.s.},
\end{equation}
where $k$ is progressively measurable and
$\E\int_0^1 k_t^2 dt < \infty$.
Assume $\tau =\{0 = t_0 < t_1 < \dots < t_N = 1\}$ and the process $X$ defined in \eqref{equation:dX_t}.
Then the  Kunita-Watanabe projection (KW-projection) is defined as
\begin{equation} 
P_\tau^X \xi := \sum_{n=1}^N g_{n-1} (X_{t_n}-X_{t_{n-1}})
\sptext{.5}{with}{.5}
 g_{n-1}
   :=  \frac{\E_{t_{n-1}} \int_{t_{n-1}}^{t_n} \s(X_t) k_t dt}
            {\E_{t_{n-1}}\int_{t_{n-1}}^{t_n} \s^2(X_t)   dt}.
\end{equation}

[Thm 1 of arXiv:2608.21090, 'Ornstein--Uhlenbeck process conditioned to have restricted $L_2$-norm'] Let $0<\theta<\frac{1}{2\gamma}$. Assume there are $K>0$ and $\beta\in(0,1/2)$ such that the sequence $y_T$ satisfies $|y_T-\theta T|\leq K T^\beta$. Then
    \begin{equation*}
        \P_x\left((U_t)_{t\geq0}\in~\cdot~\vert~Z_T \leq y_T\right)
        \overset{w}{\longrightarrow}\mathcal{L}(\tilde{U}), \qquad \text{as $T\to\infty$,}
    \end{equation*}
     where $\tilde{U}$ is an Ornstein--Uhlenbeck process started at $x$ with parameter $\frac{1}{2\theta}$ and $\overset{w}{\longrightarrow}$ stands for weak convergence on $\CC([0,\infty))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor: ReductionBoundedWithoutSym of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Suppose that $\bM_{p,\beta} \sim \operatorname{Haar}(R_{p,\beta}^{n\times n})$. 
    Let $\rank_q(\cdot)$ refer to the rank over $\bbF_q \cong \bbZ[x]/(p\bbZ[x] + \beta(x)\bbZ[x])$. 
    Then, for every $k\leq n$,  as random $R_{p,\beta}$ modules, 
    \begin{align}
        \bbP\Bigl(\coker\bigl(\bM_{p,\beta},\bigr) \in  *  \mid \rank_{q}\bigl(\bM_{p,\beta}\bigr) = n-k\Bigr) = \bbP\Bigl(\coker\bigl(\bK  \bigr) \in  * \Bigr),
    \end{align}
    where $\bK$ is a $k\times k$ matrix with entries Haar distributed on $pR_{p,\beta} + \beta(x) R_{p,\beta}$. 
    That is, 
    \begin{align}
        \bK  \sim  p\operatorname{Haar}(R_{p,\beta}^{k\times k})  + \beta(x) \operatorname{Haar}(R_{p,\beta}^{k\times k}).   
    \end{align}

[Defi def:curve of maximal slope of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [AGS08]
    Let $(S,d)$ be a metric space and $F:S\to (-\infty,\infty]$ measurable. A locally absolutely continuous curve $v:(a,b)\to S$ is a curve of maximal slope for the functional $F$ with respect to its strong upper gradient $g$, if $F\circ v$ is $\mathsf{Leb}_{\IR}-$a.e. equal to  a non-increasing map $f$ and \begin{align*}
        f'(t)\leq -\frac{1}{2}\left\lvertv'\right\rvert^2(t)-\frac{1}{2}g^2(v(t)) \text{ in } (0,\infty).
    \end{align*}

[Lem lm:shocksandwich of arXiv:2604.12963, 'Shocks, instability, and the twenty networks\\ of infinite geodesics in the Directed Lands'] For all $\omega\in\Omega_0$, $x,s,\theta\in\mathbb{R}$, ${\raisebox{-0pt}{\scaleobj{1.1}{\boxempty}}}\in\{-,+\}$, and any $\theta{\raisebox{-0pt}{\scaleobj{1.1}{\boxempty}}}$ shock interface $\tau$ from $(x,s)$, 
  \begin{align}
  \Upsilon_{(x,s)}\dir{L}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}\preceq\tau\preceq\Upsilon_{(x,s)}\dir{R}{\theta}{{\raisebox{1.5pt}{\scaleobj{0.6}{\boxempty}}}}.
  \end{align}
  Consequently, 
  \begin{align}
  \lim_{r\to-\infty}r^{-1}\tau(r)=(\theta,1).
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] For any $\widehat{\mathbf{x}}\in\widehat{C}^{\alpha,p}_o$ and some $\beta>0$ and $\gamma\geq\lfloor 1/\alpha\rfloor$, let
    \begin{equation*}
        \psi(\widehat{\mathbf{x}}) := \exp\left(\beta(\lVert \widehat{\mathbf{x}} \rVert_{\textup{hom $p$-var};[0,T]} + \lVert \widehat{\mathbf{x}} \rVert_{\textup{hom $\alpha$-H\"{o}l};[0,T]})^\gamma\right).
    \end{equation*}
    Also, let
    \begin{equation*}
        B_\psi(\widehat{C}^{\alpha,p}_o) := \Bigg\{f:\widehat{C}^{\alpha,p}_o\rightarrow\mathbb{R} \,:\, \lVert f\rVert
        _{\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)}:=\sup_{\widehat{\mathbf{x}}\in\widehat{C}^{\alpha,p}_o}\frac{f(\widehat{\mathbf{x}})}{\psi(\widehat{\mathbf{x}})}<\infty\Bigg\}
    \end{equation*}
    and $\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)$ be the closure with respect to $\lVert \cdot\rVert_{\mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)}$ of the space $C_b^0\left(\widehat{C}^{\alpha,p}_o;\mathbb{R}\right)$ of bounded and continuous real-valued functions over $\widehat{C}^{\alpha,p}_o$. Then, for every map $f\in \mathcal{B}_\psi(\widehat{C}^{\alpha,p}_o)$ and for every $\varepsilon>0$, there exists a linear function of the form 
    \begin{equation*}
        (T(\mathbb{R}^{k+1}))\ni S(\widehat{\mathbf{x}})_T \longmapsto \langle\ell,S(\widehat{\mathbf{x}})_T\rangle := \sum_{0\leq |I|\leq N} \alpha_I\big\langle \varepsilon_I, S^{|I|}(\widehat{\mathbf{x}})_T \big\rangle_{(\mathbb{R}^{k+1})^{\otimes |I|}},
    \end{equation*}
    where $N\in\mathbb{N}$, $\alpha_I\in\mathbb{R}$, $I=(i_1,\dots,i_m)\in\{1,\dots,k\}^m$ is a multi-index with $|I|=m$, $\varepsilon_I:=\varepsilon_{i_1}\otimes\dots\otimes\varepsilon_{i_m}$ are the basis elements of $(\mathbb{R}^{k+1})^{\otimes m}$, and $\langle \cdot,\cdot\rangle_{(\mathbb{R}^{k+1})^{\otimes |I|}}$ is the usual inner product on $(\mathbb{R}^{k+1})^{\otimes |I|}$, such that
    \begin{equation*}
        \sup_{t\in[0,T]}\sup_{\widehat{\mathbf{x}}\in \widehat{C}^{\alpha,p}_o} \frac{ \big|f(\widehat{\mathbf{x}}_{\cdot\wedge t}) -\langle\ell,S(\widehat{\mathbf{x}})_t\rangle\big| }{ \psi(\widehat{\mathbf{x}}_{\cdot\wedge t}) } < \varepsilon.
    \end{equation*}

[Lemma 25 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Fix $k\geq 0$ and $l,m\geq 1$.
Let $\eta>0$ and $\varepsilon>0$.
Then
\begin{multline*}
\E\Big[
\big\Vert
V_{A,\varepsilon}^{k}
\,\nu_{A,\varepsilon}^{l}
\, :\Phi_{D\setminus A,\varepsilon}^{m}:
\big\Vert_{H^{-\eta}(\C)}^{2}
\Big]
=
\\
\int_{\substack{d(z,D)<\varepsilon\\ d(w,D)<\varepsilon}}
\LK_{\eta}(\vert w-z\vert)
\E\Big[V_{A,\varepsilon}(z)^{k}
V_{A,\varepsilon}(w)^{k}\nu_{A,\varepsilon}(z)^{l}\nu_{A,\varepsilon}(w)^{l}
:\Phi_{D\setminus A,\varepsilon}^{m}:(z)
:\Phi_{D\setminus A,\varepsilon}^{m}:(w)
\Big]
\,d^{2}z\,d^{2}w.
\end{multline*}

