body:
[Lemma 30 of arXiv:2609.04033, 'From configuration spaces to graph complexes via $\mathbf{FA}$-modules'] There is an isomorphism of graded $S_n$-representations $$H^\ast_c(F(S^1\vee S^1,n))\tensor_{\mathbb{Z}_2\times S_3}( Id\boxtimes V_{2,1})\cong\bigoplus_\lambda \Sigma^{|\lambda|} q_\lambda\Phi[n,\lambda^\ast]$$ where

$$
q_{\lambda} = \begin{cases}
	\left\lfloor \ds\frac{a-b+2}{3} \right\rfloor & \text{ if } \lambda = (a,b) \text{ and } a\equiv b \text{ mod } 2, \\ \\
	0 & \text{ else.}
\end{cases} 
$$

[Definition Def:alpha-mixing of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] A sequence $\{X_k\}_{k\geq 1}$ of $d$-dimensional random vectors on a sublinear expectation space $(\Omega, \mathcal{H}, \hat{\mathbb{E}})$ is called $\alpha$-mixing if there exist $c_X>0,\alpha>0$ such that for any non-empty finite subset $\Lambda^1,\Lambda^2\subset \mathbb{N}$ with $\Lambda^1_{max}:=\max_{u_1\in \Lambda^1}u_1\leq \min_{u_2\in \Lambda^2}u_2=:\Lambda^2_{min}$ and $\phi\in C_{lip}(\mathbb{R}^{2d})$ with Lipschitz constant $l_{\phi}>0$,
		\begin{equation*}
			\begin{split}
				|\hat{\mathbb{E}}[\phi(\bar{X}_{\Lambda^1}, \bar{X}_{\Lambda^2})] - \hat{\mathbb{E}}[\hat{\mathbb{E}}[\phi(x, \bar{X}_{\Lambda^2})]|_{x=\bar{X}_{\Lambda^1}}]| \leq c_X l_{\phi} e^{-\alpha |\Lambda^2_{min}-\Lambda^1_{max}|},
			\end{split}
		\end{equation*}
		where $\bar{X}_{\Lambda^i}=\frac{1}{|\Lambda^i|}\sum_{u_i\in \Lambda^i}X_{u_i}$  and $|\Lambda^i|$ is the number of elements in $\Lambda^i$, $i=1,2$.

[Theorem 6 of arXiv:2606.25501, 'An RDT based approach to large deviations of Wishart and Wigner matrices spectral edges'] (\cite{Gordon85})
 Assume the setup of Theorem \ref{thm:minGordonpos1}. Let $\psi_q(\cdot)$ be an increasing function on the real axis. Then
\begin{equation*}
\mE(\min_{i}\max_{j}\psi_q(X_{ij}))\leq \mE(\min_i\max_{j} \psi_q(Y_{ij})).
\end{equation*}
Also, let $\psi_q(\cdot)$ be a decreasing function on the real axis. Then
\begin{equation*}
   \mE(\max_{i}\min_{j}\psi_q(X_{ij}))\geq \mE(\max_i\min_{j}\psi_q(Y_{ij})).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 9 of arXiv:2608.23450, 'The Oldest Allele in a Moran Model'] If $\tilde Z^n(0)=0$ then $\tilde Z^n(1/\alpha_n) \Rightarrow V$ where the density of $V$ on $(0,1)$ is given by 
\begin{equation} 
p(x) = \theta(1 - x)^{\theta - 1}.
\end{equation}

[Theorem thm:ligthcone_and_sle of arXiv:2412.04005, '$\SLE_{\kappa}(\rho)$ processes in the light cone regime on\\ Liouville quantum gravity'] Fix $\kappa \in (0,4)$,  $\rho \in [\kappa/2-4,-2)$ and $\rho > -2 - \kappa/2$,  and suppose that $h$ is a \text{GFF} on $\mathbf{H}$ whose boundary data is given by $-\lambda$ on $\mathbf{R}_-$ and $\lambda (1+\rho)$ on $\mathbf{R}_+$.  Let $\eta$ be an ${\rm SLE}_{\kappa}(\rho)$ process on $\mathbf{H}$ from $0$ to $\infty$ where its force point is located at $0_+$.  For each $t \geq 0$,  let $K_t$ denote the closure of the complement of the unbounded connected component of $\mathbf{H} \setminus \eta([0,t])$,  let $g_t : \mathbf{H} \setminus K_t \to \mathbf{H}$ be the unique conformal transformation with $g_t(z)-z \to 0$ as $z \to \infty$,  and let $(W,V)$ be the Loewner driving pair for $\eta$.  There exists a unique coupling of $h$ and $\eta$ such that the following is true.  For each $\eta$-stopping time $\tau$,  the conditional law of 
\begin{align*}
h \circ g_{\tau}^{-1} - \chi \arg(g_{\tau}^{-1})'
\end{align*}
given $\eta|_{[0,\tau]}$ is that of a \text{GFF} on $\mathbf{H}$ with boundary conditions given by 
\begin{align*}
h|_{(-\infty,W_{\tau}]} \equiv -\lambda,\quad h|_{(	W_{\tau},V_{\tau}]} \equiv \lambda,\quad \text{and} \quad h|_{(V_{\tau},\infty)}\equiv \lambda (1+\rho),
\end{align*}
where $\lambda = \pi / \sqrt{\kappa}$.

Moreover,  in the coupling $(h,\eta)$,  $\eta$ is a.s.\ determined by $h$.  Finally,  let 
\begin{equation}
\theta = \theta_{\rho} = \pi \!\left ( \frac{\rho + 2}{\kappa / 2 - 2} \right ).
\end{equation}
Then the range of $\eta$ is a.s.\ equal to ${\mathbf L}_{\mathbf{R}_-}(0,\theta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 (Exact reflection) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] Let $T(p)=1-\delta-p$. Then, for every $n,k,t$ and $p\in[0,1-\delta]$,
\begin{equation*}
 P_{n,k,t,\delta}(p)=P_{n,k,k-t,\delta}(T(p)).
\end{equation*}
Consequently, when $k=2t$,
\begin{equation*}
 P_{n,k,t,\delta}(\pc+u)=P_{n,k,t,\delta}(\pc-u),
 \qquad \pc=\frac{1-\delta}{2},
\end{equation*}
whenever both arguments belong to $[0,1-\delta]$.

[Lemma 8 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] Let $(p_n)$ be a sequence of real numbers. Let $z_0>0$. Assume that
\begin{equation}
\sum_{n=0}^\infty p_n z^n = \frac{f(z)}{z_0-z},
\end{equation}
for complex $|z| < z_0$. Further assume that $f$ is analytic on $|z|<z_1$ with $z_0<z_1$ and that $f(z_0)\neq 0$. Then
$$
p_n \sim f(z_0) \cdot z_0^{-(n+1)},\qquad \text{as $n\to\infty$.}
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

