\begin{align*}
\lim_{\epsilon\to 0} \frac{1}{\sqrt{\epsilon}} \,
e^{-[ \mf h_{\widehat{\mf q}}+S(\mz M_{\widehat{\mf q}}(k))]/\epsilon}\,
\sum_{\sigma\in \mc W_{j,j+1}^{(\widehat{\mf q})}}
\int_{\sigma-\eta_0}^{\sigma+\eta_0}
