body:
[Lemma lem-prelim-gap-est-time-2-to-200 of arXiv:2607.22324, 'The conclave process'] {}
   Suppose that 
   \begin{equation}
       M \geq \frac{(\log n)^{\alpha}}{(\log \log n)^{2\alpha}}, \quad \frac{1}{ (\log n)^{0.1+\frac{\alpha}{2}} } \leq\delta\leq \frac{1}{(\log n)^{0.9}}, \quad Z \leq n\log\log n \,.
   \end{equation}
   Define $\mathfrak T(M,\delta,Z)$ to be the collection of $(M',\delta')$ such that 
   \begin{equation}{}
       \frac{M^{\alpha}n}{2Z} \leq M' \leq \frac{2M^{\alpha}n}{Z}\,,\quad \frac{\alpha\delta}{2} < \delta' < 2\alpha\delta\,,
   \end{equation}
   Given any $(\mathbf X_1,\ldots,\mathbf X_n) \in \overline{\Omega}_n(M,\delta,Z)$, we have
   \begin{equation}
       \mathbb P\left( \mathcal L(\mathbf X') = \mathcal L(\mathbf X)\,, (\mathbf X_1',\ldots,\mathbf X_n') \in \cup_{ (M',\delta') \in \mathfrak T(M,\delta,Z) } \overline{\Omega}_n(M',\delta') \right) \geq 1-o\left( \frac{1}{\log n} \right) \,.
   \end{equation}

