&\varlimsup_{\varepsilon\to 0}\frac{E\left[\mathscr{Z}_t^\vartheta(B_\varepsilon(0),B_\varepsilon(0))^2\right]
}{(2\pi \varepsilon^2)^4\left( \log \frac{1}{\varepsilon}\right)^2}\leq C_{\vartheta,t}.

\end{align*}

