body:
[Theorem SSK with critically scaled external field \cite{Baiketal21,landon2020fluctuations} of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] When the external field is critically scaled as described below, the free energy of SSK exhibits the following convergence in distribution as $N\to\infty$.
\begin{enumerate}[(i)]
\item If $\beta<1$ and $h=HN^{-1/4}$ for fixed $H>0$, then
 \begin{equation} 
N(F_N(\beta,h)-F(\beta,h))\to\mathcal{N}(-\frac12 \sigma^2,\sigma^2)
 \end{equation} 
where $\sigma^2=-\frac12\log(1-\beta^2)+\frac{H^4\beta^4}{2(1-\beta^2)}$.

\item If $\beta>1$ and $h=HN^{-1/6}$ for fixed $H>0$, then
 \begin{equation} 
\frac{2N^{2/3}}{\beta-1}(F_N(\beta,h)-F(\beta,h))\to \tilde{\mathcal{F}}_{\beta,H}
 \end{equation} 
where $\tilde{\mathcal{F}}_{\beta,H}$ is a function of Gaussian random variables and a GOE Airy point process.
\end{enumerate} 
The limiting free energy $F(\beta,h)$ in this setting is given by the formula
 \begin{equation} 
F(\beta,h)=\begin{cases}
\frac14\beta^2+\frac12\beta^2h^2& \text{for }\beta\leq1,\\
\beta-\frac12\log\beta-\frac34+\frac12\beta h^2 & \text{for }\beta\geq1.
\end{cases}
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2506.22040, '\vspace{-3em} Khinchin inequalities for uniforms on spheres with a deficit'] Let $d \geq 2$ be a fixed dimension, let $\xi_1, \xi_2, \dots$ be independent random vectors uniform on the unit Euclidean sphere $S^{d-1}$ in $\R^d$. Let $p \geq 2$. For every $n \geq 2$, every real scalars $a_1, \dots, a_n$ with $\sum_{j=1}^n a_j^2 = 1$, we have
\begin{equation}
\E\left|\sum_{j=1}^n a_j\xi_j\right|^p \leq \E\left|\sum_{j=1}^n \frac{1}{\sqrt{n}}\xi_j\right|^p - \tilde{c}_{p,d}\sum_{j=1}^n \left(\frac{1}{n}-a_j^2\right)^2,
\end{equation}
where
\[ 
\tilde{c}_{p,d} = \frac{p(p-2)}{4d}\begin{cases}
\frac{(p+d-2)(p+d-4)}{d(d+2)}, & 2 \leq p \leq 4, \\ 0.385, & p > 4. \end{cases}
 \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem THM:1 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] Let $Q \in \mathbb{Z}$ with $Q \neq 0$, and $L_\varepsilon =\varepsilon^{-\frac 12+\eta}$ with $\eta>0$ arbitrarily small but fixed.

\begin{itemize}
\item[(i)] There exists $c>0$ such that for any $\delta>0$ 
\begin{align}
\limsup_{\varepsilon \to 0} \varepsilon \log \rho_\varepsilon^Q  \big(\{   \textup{dist}(\phi, \mathcal{M}_Q ) \ge \delta   \} \big) \le -c \delta^2,

\end{align}

\noindent
where $\textup{dist}$ denotes the $L^2(\mathbb{R})$-distance and the multi-soliton manifold\footnote{The multi-soliton profile $m(\cdot-\xi_1)+\dots +m(\cdot-\xi_Q)$ is invariant under permutation of the labels $i=1,\ldots, |Q|$. Each unordered configuration corresponds to $Q!$ identical ordered configurations. Because of the indistinguishable nature, we work with the ordered set.} is defined as
\begin{align}
\mathcal{M}_Q:=\Big\{\sum_{j=1}^Q m(\cdot-\xi_j): -\infty<\xi_1\le \dots \le \xi_Q<\infty  \Big\}, \quad Q>0.

\end{align}

\noindent 
For $Q<0$, we define the corresponding multi-soliton manifold with anti-kinks. 

\medskip 

\item[(ii)] There exists $c>0$ such that  
\begin{align} 
\limsup_{\varepsilon \to 0} \varepsilon \log \rho_\varepsilon^Q  \big(\{   \textup{dist}(\phi, \mathcal{M}_Q^{<d} ) < \delta  \big) \le - c e^{- d},

\end{align}

\noindent
for any $\delta>0$, $d>0$ satisfying\footnote{ Later, we prove that the collision manifold $\mathcal{M}_Q^{<d}$ is an unlikely event. Therefore, when the field $\phi$ is sufficiently close to $\mathcal{M}_Q^{<d}$, in the sense that $ c e^{-d } \ge \delta^2$, we obtain the same result. See Lemmas~(LEM:GAP2 of the paper) and~(lem:gap-multikink of the paper).} $ c  e^{-d } \ge \delta^2$, where the collision manifold $\mathcal{M}_Q^{<d}$, $Q>0$, is defined as 
\begin{align}
\mathcal{M}^{<d}_{Q}:=\Big\{\sum_{j=1}^Q m(\cdot-\xi_j) : -\infty<\xi_1\le \dots \le \xi_{Q}<\infty \; \; \textup{and} \; \; \min_{i \neq j} |\xi_i-\xi_j|<d \Big\}.

\end{align}

\noindent
For $Q<0$, we define the corresponding manifold with anti-kinks. 

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition lem:tail_bounds of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] For any relative deviation $\varepsilon \in (0, 1)$, the following upper and lower tail bounds hold:
  \begin{equation}
    \begin{gathered}
    \mathbb{P}\big(\bar{X} \ge \rho(1+\varepsilon)\big) \le \exp\braces*{-n \frac{\rho \varepsilon^2}{3\Gamma}},\\
     \mathbb{P}\big(\bar{X} \le \rho(1-\varepsilon)\big) \le \exp\braces*{ -n \frac{\rho \varepsilon^2}{2\Gamma}}.
     \end{gathered}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 212 (budget constraint) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Fix parameters $\alpha,L,\iota,\epsilon$. Let $M,N\to\infty$ with $M/N\to\alpha$. Let $\omega$ denote a random variable. Let $\bG,\bXi$ be $M\times N$ matrices with i.i.d.\ standard gaussian entries, with rows $\bg^1,\ldots,\bg^M$ and $\bmeta^1,\ldots,\bmeta^M$ respectively,  such that $\bXi$ is independent of $(\bG,\omega)$. Let $\bar{\bx}\equiv \bar{\bx}(\bG)$ and $\hat{\by} \equiv \hat{\by}(\bG,\bXi)$ be $L$-Lipschitz, $\R^N$-valued functions such that 
	\begin{align*}
	&\E(\|\bar{\bx}\|^2)=\E(\|\hat{\by}\|^2)=N,\\
	&\E(\hat{\by}\,|\,\bG)=0 \textup{ almost surely.}
	\end{align*}
Suppose for some $r,s \ge 1$ we have a partition, which is permitted to depend on $(\bG,\omega)$ but not on $\bXi$:
	 \begin{align*}
    [M] = \bigsqcup_{j=1}^r B_j \textup{ with } 
    \frac{|B_j|}{M}
    = \lambda_j(\bG,\omega)\,,\\
    [N] = \bigsqcup_{j=1}^s 
    K_j \textup{ with } 
    \frac{|K_j|}{N}
    = \mu_j(\bG,\omega)\,,
    \end{align*}
such that $\min_j\lambda_j\ge\iota$ and $\min_j\mu_j\ge\iota$ hold $(\bG,\omega)$-almost surely. Then define the random variables
     \begin{align}

    \bbb_j \equiv \bbb(B_j)
        &\equiv 
        \frac{1}{|B_j|}
        \sum_{a\in B_j}
        \frac{(\bmeta^a,\by)}{N^{1/2}}
        \,,\\

    \vvv_j \equiv \vvv(B_j)
        &\equiv 
        \frac{1}{|B_j|}
        \sum_{a\in B_j}
        \frac{(\bar{\bg}^a,\by)^2}{N}
        \,,\\

    \uuu_j \equiv \uuu(B_j)
        &\equiv 
        \frac{1}{|B_j|}
        \sum_{a\in B_j}
        \frac{(\bmeta^a,\bar{\bx})
        (\bar{\bg}^a,\by)}{N}
        \,,\\

    \www_j
    \equiv \www(K_j) 
    &\equiv \frac{1}{|K_j|}
        \sum_{i\in K_j}
        (\by_i)^2\,.\end{align}
Recall the definition of the function $\Cost\equiv\Cost_0$ from \eqref{e:cost}. Then, for all sufficiently large $N$, we have
    \[
    \sum_{j=1}^r
    \frac{|B_j|}{M}
    \Cost(\bbb_j,\vvv_j,\uuu_j)
    \le
    \frac{1}{\alpha}
    \bigg( \sum_{j=1}^s
        \frac{|K_j|}{N}
        (\www_j)^{1/2}\bigg)^2
     +  \epsilon\,,
    \]
with probability at least $1-e^{-cN}$, where $c$ is a positive constant depending on the parameters $\alpha,L,\iota,\epsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$, $f\in \Sob^k(\Rbb^n,\gamma_n)$, $\kappa\in \Nbb^n$ with $|\kappa|=k$, and $t\geq 0$,
\begin{equation}
    \Dop^\kappa \Pop_t f = \upe^{-t|\kappa|} \Pop_t \Dop^\kappa f,
\end{equation}
and consequently, for all $k\in \Nbb$,
\begin{equation}
    \left|\grad^k \Pop_t f\right| \leq \upe^{-kt}\Pop_t \left|\grad^k f\right|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 30 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] For $p \in (0,1)$,
\begin{equation}
    \fr{\Cnt}{2^{2^{d-1}}} \psim \polymerpf^\cE + \polymerpf^\cO.
\end{equation}
where the terms on the RHS were defined in \eqref{eq:polymerpfdef}. (Proof in the paper; no proof environment follows the statement in the TeX.)

