[Definition 35 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Hellinger Integral of Order $\alpha$}

    Let $\mu, \nu$ be two probability measures \st{} $\mu \ll \nu$. We define the Hellinger integral of order $\alpha$ as 
    \begin{align*}
        H_\alpha (\mu || \nu)
        := \int \Parent{\frac{d\mu}{d\nu}}^\alpha d\nu. 
    \end{align*}

[Definition 12 of arXiv:2608.18557, 'Randomly Permuted Orthogonal Products and Fast Dimension Reduction'] Let \(I\subseteq [d]\) with \(|I|=m\), let $A,B \in O(d)$, and let \(X\subseteq \mathbb S^{d-1}\). We define the \emph{sampled column energy}
	of \(A\) by
	\begin{equation}
		\kappa_I(A)
		:=
		\frac dm
		\max_{k\in[d]}
		\sum_{j\in I}A_{jk}^2
	\end{equation}
	and the \emph{maximal variance} of \(B\) on \(X\) by
	\begin{equation}
		\Theta_B(X)
		:=
		d\sup_{\substack{x\in X\\k\in[d]}}
		\sum_{j=1}^dB_{kj}^2x_j^2.
	\end{equation}

[Lemma l:taylor of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $\gamma\geq 0$. Suppose that $f\in C^{\lceil \gamma \rceil}(\R^d)$ with $f(x) = 0$ for all $x\in B_1^c$. Then there are mappings $R: (0,\infty) \times \R^d \times  \R^d \to \C$ and $g: (0,\infty) \times \R^d \to [0,1]$ such that for all $r>0,x,y\in\R^d$,
\begin{align}
    f_r(y+x) &= \sum_{q=0}^{\lfloor \gamma \rfloor} \frac{1}{q!} f_r^{(q)}(y) x^{\otimes q} + R(r,y,x),\\
    |R(r,y,x)| &\leq \frac{2\|f^{(\lfloor \gamma \rfloor)}\|_\infty + \|f^{(\lceil \gamma \rceil)}\|_\infty}{\lfloor\gamma\rfloor!}\frac{\|x\|^\gamma}{r^\gamma} g(r, x),\\
    g(r, x) &\xrightarrow{r\to\infty} 0, 
\end{align}
and for all $r>0,x\in\R^d,y\in B_r^c$
\begin{equation}
    R(r,y,x) = f_r(y+x).
\end{equation}
\begin{proof}
First of all, one can define $R$ simply by
\begin{equation}
    R(r,y,x) := f_r(y+x) - \sum_{q=0}^{\lfloor \gamma \rfloor} \frac{1}{q!} f_r^{(q)}(y) x^{\otimes q},\quad r>0, x,y\in\R^d.
\end{equation}
Then~(equation e:taylor1 of the paper) is fulfilled and~(equation e:taylor3 of the paper) directly follows from the fact that $f(x) = 0$ for all $x\in B_1^c$ and therefore also $f^{(q)}(x) = 0$ for all $x\in B_1^c, q\in\N_0$.
If $\gamma\notin \N_0$, i.e., $\lceil\gamma\rceil = \lfloor \gamma\rfloor + 1$, by Taylor's theorem and Remark~(r: f_r formulas of the paper), we know that
\begin{equation*}
    R(r,y,x) = \frac{1}{(\lceil \gamma \rceil-1)! r^{\lceil \gamma \rceil}} \int_0^1 (1-t)^{\lceil \gamma \rceil-1} f^{(\lceil \gamma \rceil)}(\tfrac{tx+y}{r}) x^{\otimes \lceil \gamma \rceil} \ dt,\quad r>0,x,y\in\R^d,
\end{equation*}
where we performed a Taylor-approximation of degree $\lfloor \gamma \rfloor$. This formula directly gives rise to the bound
\begin{equation}
    |R(r,y,x)| \leq \frac{\|f^{(\lceil \gamma \rceil)}\|_\infty}{\lceil \gamma \rceil!} \frac{\|x\|^{\lceil \gamma \rceil}}{r^{\lceil \gamma \rceil}}.
\end{equation}
similarly, if $\lfloor \gamma \rfloor \geq 1$, a Taylor-approximation of degree $\lfloor \gamma \rfloor - 1$ yields
\begin{equation}
    R(r,y,x) = \frac{1}{(\lfloor \gamma \rfloor-1)! r^{\lfloor \gamma \rfloor}} \int_0^1 (1-t)^{\lfloor \gamma \rfloor-1} f^{(\lfloor \gamma \rfloor)}(\tfrac{tx+y}{r}) x^{\otimes \lfloor \gamma \rfloor} \ dt - \frac{1}{\lfloor \gamma \rfloor! r^{\lfloor \gamma \rfloor}} f^{(\lfloor \gamma \rfloor)}(\tfrac{y}{r}),
\end{equation}
from which we can derive
\begin{equation}
    |R(r,y,x)| \leq \frac{1}{\lfloor \gamma\rfloor!} \frac{\|x\|^{\lfloor \gamma\rfloor}}{r^{\lfloor \gamma\rfloor}} \sup\big\{ \|f^{(\lfloor \gamma \rfloor)}(y)-f^{(\lfloor \gamma \rfloor)}(z) \| : y,z\in\R^d, \|y-z\|\leq \tfrac{\|x\|}{r}\big\},
\end{equation}
for $r>0,x,y\in\R^d$.
The supremum is finite and goes to $0$ as $r\to\infty$ for every $x\in\R^d$, since $f^{(\lfloor\gamma\rfloor)}$ is continuous and compactly supported and therefore also uniformly continuous.
For $\lfloor \gamma \rfloor = 0$, this bound is trivially obtained from~(equation e:taylor11 of the paper). A combination of~(equation e:taylor21 of the paper) and~(equation e:taylor22 of the paper) yields 
\begin{equation*}
    |R(r,y,x)| \leq \frac{2\|f^{(\lfloor \gamma \rfloor)}\|_\infty + \|f^{(\lceil \gamma \rceil)}\|_\infty}{\lfloor\gamma\rfloor!}\frac{\|x\|^\gamma}{r^\gamma} g(r, x),
\end{equation*}
with $g$, for $r>0, x\in\R^d$, defined as
\begin{align*}
    g(r, x) := \min\bigg(&\frac{\|x\|^{\lceil\gamma\rceil-\gamma}}{r^{\lceil\gamma\rceil-\gamma}}, \nonumber\\
    &\frac{r^{\gamma-\lfloor\gamma\rfloor}}{\|x\|^{\gamma-\lfloor\gamma\rfloor}}\sup\bigg\{ \frac{\|f^{(\lfloor \gamma \rfloor)}(y)-f^{(\lfloor \gamma \rfloor)}(z)\|}{2\|f^{(\lfloor \gamma \rfloor)}\|_\infty} : y,z\in\R^d, \|y-z\|\leq \tfrac{\|x\|}{r}\bigg\}\bigg),
\end{align*}
whereby it fulfills~(equation e:taylor4 of the paper).
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem eq:kappa_condition of arXiv:2605.20697, 'Uniform-in-time propagation of chaos for \\ Second-Order Consensus-Based Optimization'] Let the objective function $f$ satisfy (assumption:bounded,assumption:lip of the paper). Assume the parameters are chosen such that the $2q$-th moments decay exponentially with rate $\lambda_{2q} > 0$ (as per (thm:exp-decay-centered-moments of the paper)). 

    For any decay rate $\kappa$ satisfying the condition:
    \begin{equation} 
        \kappa < \frac{\lambda_{2q}}{q},
    \end{equation}
    there exists a finite constant $C' > 0$ (depending on $q, \kappa, \lambda_{2q}$) such that for any threshold $A > 0$ and particle number $J \in \mathbb{N}_+$, the following concentration inequality holds:
    \begin{equation}
        \mathbf P\left[ \sup_{t \geqslant 0} e^{\kappa t} \mathfrak{M}_2(\mu_{X_t^J}) \geqslant \frac{\mathbf{E}[\mathcal{L}_{2q}(\mu_{(Y_0, \hat{Z}_0)})] + A}{c_1} \right] \leqslant \frac{C'}{A^q} J^{-\frac{q}{2}},
    \end{equation}
    where $c_1$ is the coercivity constant from (lem:hypercoercivity of the paper).

