[Proposition thm:uniquefixed of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $\mathcal{L}_S$ be defined in (equation def:lsbip of the paper), where $\mathcal{L}^A$ is a primitive QMS generator on the subsystem $A$ with invariant state $\sigma^A \in \mathcal{D}_+(\mathcal{M}_A)$. Suppose that (asspA2 of the paper) holds. Then, 
\begin{itemize}
    \item There exists a state $\sigma^B \in \mathcal{D}_+(\mathcal{M}_B)$ such that 
    \begin{align} 
        \sigma = \sigma^A \otimes \sigma^B\,.
    \end{align} 
    Moreover, $\mathcal{L}^A$ is $\sigma^A$-KMS detailed balanced. 
    \item It holds that 
    \begin{align} 
        \left[\sigma^A, H^A \right] = 0\,,\quad \left[\sigma^B, H^B\right] = 0\,,\quad \left[\sigma, H^{AB}\right] = 0\,,
    \end{align}
    where Hamiltonians $H^A$, $H^B$, and $H^{AB}$ are given in (equation eq:hamil of the paper).
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 2D FK expectation and covariance of arXiv:2607.17393, 'Optimal Covariance Estimates for Schr\"odinger Semigroups with White Noise in $d=1,2$'] For $d=2$, there exists $\vartheta>0$ such that for every $s,t\in(0,\vartheta)$
    \begin{align}
        \mathbb{E}[\mathrm{Tr}[e^{-tH}]] = \mathcal{P}^d(t,t)^{1/2}\int_{\mathbb{R}^d}\mathbb{E}[e^{-\int_0^tV(B_t^{x,x}(u))du+\mathcal{D}^d_t(x)}]dx.
    \end{align}
    \begin{align}
        \mathrm{Cov}\big[\mathrm{Tr}[e^{-tH}],\mathrm{Tr}[e^{-sH}]\big] = \mathcal{P}^d(t,s)\int_{(\mathbb{R}^d)^2}\mathbb{E}\left[(e^{\mathcal{A}_{t,s}(x,y)+B^d_{t,s}(x,y)})(e^{\mathcal{C}_{t,s}(x,y)}-1)\right]dxdy
    \end{align}
For $d=1$, the same formulas hold for every $s,t>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Theorem:DensityKunita of arXiv:2411.13765, 'Schr\"odinger Bridge Problem for Jump Diffusions'] [kunita2019stochastic]
    Let $L$ be a jump-diffusion operator given by (equation ReferenceGenerator of the paper) with coefficients satisfying Assumptions \textup{(Assumptions-(C) of the paper)} and $\left\{ X_t \right\}_{[0,T]}$ be the solution to the SDE (equation ReferenceLevyIto of the paper) associated with $L$. Assume that there exists a family of star-shaped neighborhoods $\left\{ A_0(r) \right\}_{0<r<1}$ with respect to which $\nu$ satisfies the order condition. Let $\Gamma_0$ and $K(t,x)$ be as above. Further suppose that $\sigma(t,x)\sigma^T(t,x)+K(t,x)\Gamma_0K^T(t,x)$ is positive definite for every $(t,x)\in[0,T]\times\mathbb{R}^n$.

    Then, $\left\{ X_t \right\}_{[0,T]}$ admits a transition density function $p(s,x,t,y)$ for $0\leq s< t\leq T$ and $x,y\in \mathbb{R}^n$. Moreover,
    \begin{enumerate}
        \item for every $0\leq s<t\leq T$, $(x,y)\in\mathbb{R}^n\times\mathbb{R}^n\mapsto p(s,x,t,y)$ is a $C^{\infty,\infty}$-function, and for every multi-index $\mathbf{i}$ and every $x\in\mathbb{R}^n$, $y\mapsto\partial_x^{\mathbf{i}}p(s,x,t,y)$ is rapidly decreasing\footnote{That is, for any integer $k$ and any multi-index $\mathbf{j}$, $\abs{\partial_y^{\mathbf{j}}\partial_x^{\mathbf{i}}p(s,x,t,y)}(1+|y|)^k$ converges to $0$ as $|y|\to\infty$.};
        \item for every $(t,y)\in[0,T]\times\mathbb{R}^n$, $(s,x)\in (0,t)\times\mathbb{R}^n\mapsto p_{t,y}(s,x):=p(s,x,t,y)$ is a $C^{1,\infty}$-function that satisfies ${\mathfrak L} p_{t,y}(s,x)=0$, where ${\mathfrak L}:=\frac{\partial}{\partial s}+L$;
        \item for every $(s,x)\in[0,T]\times\mathbb{R}^n$,  $(t,y)\in(s,T)\times\mathbb{R}^n\mapsto p^{s,x}(t,y):=p(s,x,t,y)$ is a $C^{1,\infty}$-function that satisfies ${\mathfrak L}^*p^{s,x}(t,y)=0$, where ${\mathfrak L}^*:=-\frac{\partial}{\partial t}+L^*$ is the $L^2([0,T]\times\mathbb{R}^n)$-adjoint of ${\mathfrak L}$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2607.19873, 'Local limit theorem for the operator norm of products of random matrices'] Let $\mu$ be a Borel probability measure on $G$. 
Assume that the action of $G$ on $B$ satisfies the contraction property \eqref{contraction-property-on-B}.
Then, the operator $P_{\mu}$ admits a unique invariant Borel probability measure $\nu$ on $B$, and 
for any continuous function $\varphi$ on $B$, we have, uniformly in $b \in B$, 
\begin{align*}
 P_{\mu}^n \varphi(b) 
=    \bb E \varphi(g_n \cdots g_1 b) 
\xrightarrow[n\to\infty]{}  \int_{B} \varphi(b')  \nu(d b'). 
\end{align*}

