[Lemma 14 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let $q : = \max_{m \in [M]} |B_{m}|$. For any fixed measurable function \(g\) and any $n \in \mathbb{N}$ and  \(t>0\),
	\begin{align*}
		\mathbb P^{\ast} \!\left( 	\left|\mathbb G_{n}^{(k),\ast}(g)\right|  \ge t
		\right)
		\le  2\exp\left(
		-\frac{t^2}{
			4 \sum_{m\in\mathcal C_k} \frac{|B_{m}|}{n}  ||g||^{2}_{B_{m}}
			+\frac{2}{3}  \frac{q}{\sqrt{n}} ||g||_{\infty}   t   
		}
		\right).
	\end{align*}


	Equivalently, for every \(x>0\),
	\begin{align}
		\mathbb P^{\ast} \!\left(
		\left|\mathbb G_{n}^{(k),\ast}(g)\right|
		\ge
		2 \sqrt{x}  	\sqrt{  \sum_{m\in\mathcal C_k} \frac{|B_{m}|}{n}  ||g||^{2}_{B_{m}}   }
		+\frac{2}{3}  \frac{q}{\sqrt{n}}    ||g||_{\infty} x
		\right)
		\le 2e^{-x}.
	\end{align}

[Lem le:Tilde_X_bound of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] For any $2 \leq p \leq \frac{1}{\kappa}$\,, there exists some $C(p)$ such that for any $j \geq 0$ and $0 \leq a \leq 1$, we have 
	\begin{equ}
		\mathbb{E}\int_0^a \|\Delta_j \Tilde{X}[t]\|_{L^p}^p \mathrm{d} t \leq C(p) \alpha_0^p\cdot a^{1-\kappa p}\;.
	\end{equ}

