body:
[Theorem 22 of arXiv:2609.03098, 'Standing waves for Schr\"odinger equations with Kato class potentials and $L^\infty$-bound'] Assume that one of the conditions $(LL)_{\pm}$ holds. Then the maximal invariant set $K_\infty$ for the semiflow $\Phi$ determined by $(P)_\lambda$ is isolated in $H^{1}(\R^{N})$, and its Conley index is given by 
\begin{equation}
h(\Phi, K_\infty)=\left\{\begin{aligned}
&\Sigma^{d_\infty^+} && \text{ if } \ (LL)_+ \ \text{holds},\\ 
&\Sigma^{d_\infty} && \text{ if } \ (LL)_-  \ \text{holds},
\end{aligned}\right.
\end{equation}
where $d_\infty := d(V,\lambda)$ and $d_\infty^+:=d(V,\lambda) + \dim \ker (-\Delta+V-\lambda)$.

[Lem of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] For any $\varepsilon,t,\delta>0$, and an $\alpha$-good potential $V$,
     there exists a local function
    $q_{\varepsilon}:\mathcal{G}_{[0,C],C}\times[0,1]\rightarrow\mathbb{R}^N$ which can be written
    as a finite sum

    \begin{align*}
    \text{\boldmath $q$}_{\varepsilon}(G;\beta) = \sum_{X\in\mathcal{S}} c_X(\beta) \text{\boldmath $t$}(X,G)\, ,
    \end{align*}
    such that $\mathcal{S}$ is a finite set, the coefficients $c_X(\beta)$
    are  polynomials in $\beta$ independent of $G$, and 
    for all $G\in\mathcal{G}_{[0,C],C}$ and $\beta\in[0,1]$, we have (for $K=t/\delta$)

    \begin{align*}
    \left| \frac{1}{N}\mathbb{E}[H(\text{\boldmath $\psi$}^{(K)})] - q_{\varepsilon} (G;\beta) \right| \le \varepsilon.
    \end{align*}

[Definition 10 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] \la{def:Kato}
    \begin{enumerate}[(1)]
    \item A smooth measure $\mu \in \cS$ is said to be in Kato class ($\cK$) if
      the associated PCAF $A_{t}^{\mu}$ satisfies
      \begin{align}

      \lim_{t \to 0} \sup_{x \in \bR^{d}} \bE_{x}[A_{t}^{\mu}] = 0. 
      \end{align}
    \item A smooth measure $\mu \in \cS$ is said to be 
    in the class $\cK_{\infty}$
      if for any $\varepsilon > 0$, there is a Borel set $K = K(\varepsilon)$ of
      finite $\mu$-measure and a constant $\delta = \delta(\varepsilon) > 0$
      such that for all measurable sets $B \subset K$ with $\mu(B) < \delta$,
      \begin{align}

        \sup_{x \in \mathbb{R}^{d}} G(1_{B \cup K^{c}} \mu)(x) < \varepsilon.
      \end{align}
     \item A smooth measure $\mu$ is said to be in the class $\cS_{\infty}$
       if for any $\varepsilon > 0$ there exists a Borel subset $K = K(\varepsilon)$
       of finite $\mu$-measure and a constant $\delta = \delta(\varepsilon) > 0$
       such that for all measurable sets $B \subset K$ with $\mu(B) < \delta$,
       \begin{align}

         \sup_{(x,z) \in \bR^{d} \times \bR^{d}} \int_{B \cup K^{c}}^{ }
         \frac{G(x,y) G(y,z)}{G(x,z)} \mu(dy) \le \varepsilon.
       \end{align}
    \end{enumerate}

[Proposition 29 (Repulsive logarithmic partition bound) of arXiv:2608.24863, 'Uniform Logarithmic Sobolev Inequalities for the 2D Coulomb Gas at the Diffusive Temperatu'] For every compact interval $I\Subset(0,\infty)$ and every $T>0$,
\begin{equation}
 \sup_{\beta\in I}\sup_{0<t\le T}\sup_{N\ge2}
 \mathsf K_{N,t}(\mu_\beta)<\infty.
\end{equation}

