            & = G_A(x_1, x_1) \cdots F(A_i; x_i, x_{i+1}) \cdots G_{A_k}(x_k, x_k)\\
            & = G_A(x_1, x_1) \cdots F(A_i; x_{i+1}, x_{i}) \cdots G_{A_k}(x_k, x_k)\\
            & = G_A(x_1, x_1) ...","release_manifest_digest":"sha256:dea55fd06d1843e82853b9ad9272380beedbd1c4e0516f5789d30eb3f67f7065","revision_digest":"sha256:2f703a63d3e52fae8f67c8fd4d4b15019d62bd41b8aeea9429c44c4ca8a9ad9c","source_id":"arxiv:2411.09988","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

