[Lemma of arXiv:2607.19658, 'Hitting time mixing for random $k$-cycles'] For $t \geq t^*$, conditioned on the marked set $M_t$, $\rho_t$ is uniform on $\Omega_{t}(S_t)$. In particular, $\rho_{\tau_3}|\tau_3= t$ is uniform on $\Omega_t$. Consequently, we have
\begin{align*}
    \rho_{\tau_3}\sim \mathbb{P}(\tau_3\text{ is even})\, U_{\mathfrak{A}_n}+\mathbb{P}(\tau_3\text{ is odd})\, U_{\mathfrak{A}_n^c}.
\end{align*}

[Theorem 11 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $(G^\uparrow, G, H)$ be an inhomogeneous correlated graph system, and assume that $G^\uparrow$ is weakly inhomogeneous. Define

    \begin{equation}
    x_{sparse} = \lim_{\eps \to 0} \operatorname*{pliminf}_{n \to +\infty} \frac{|V_{\leq (1-\eps)}|}{n}.
\end{equation}
    Furthermore, assume that for some $r \geq 0$,
    \begin{equation} 
        \min_{e \in E} p_e \geq \frac{1}{n (\log n)^r} \qquad \text{whp.}
    \end{equation}
    Then, if $\hat{\pi}$ is an estimator of $\pi^*$, there exist at least $x_{sparse}(n - o_\Proba(n))$ vertices $v \in [n]$ such that $\hat{\pi}(v) \neq \pi^*(v)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2606.22940, 'From smooth to discontinuous kernels: a variance transfer principle for hyperuniform proce'] Let  $ x_{ N}\in  \Sigma $ such that  $ d(x_{ N},\partial  \Sigma ) \to \infty $,    and a limit point $ \P = \lim_{ N_{ j}\to \infty } \tau _{- x_{ N_{ j}}} \X _{ N_{ j}}$.   

 Let $ \alpha \geqslant 0.$ Let $ R_{ N}\to \infty .$ Assume that for some non-negative  non-degenerate $ f\in \B_{ c}^{}(B_{ 1})$ there is $ C_{ f}$ such that  for all $ N\geqslant 1,R\in [1,R_{ N}]  $,
\begin{align*}
\sup_{ x\in \Sigma ^{ R}} \mathbf E \left[\;\overline{\X_{ N}}(\tau _{ x}f_{ R })^{ 2}
\right]\leqslant C_{ f}R^{ d-\alpha }.
\end{align*}
Then for $\gamma >0,\varphi \in \F_{ \gamma }$ continuous $ \Leb$-a.e.,   $R\geqslant R_{ f}^{\circ }, L \geqslant  { R^{ d + 2}},$  
\begin{align}

\sup_{ x_{ 0}\in \mathbb{R}^{ d}}\displaystyle\int_{ [-L/2,L/2 ]^{ d}}  \textrm{Var}\left(\P(\tau _{ x_{ 0} + x}\varphi _{ R})\right)\frac{ dx}{L^{ d}}\leqslant C_{ \varphi,f }V_{ \alpha ,\gamma }(R)
 \end{align}
 where $ R^\circ _{ f},C_{ \varphi ,f}$ depend explicitly   on $ f,\varphi ,d,C_{ f}$. 

If $ \P$ is furthermore assumed to be stationary,  we have the result for all $   x\in \mathbb{R}^{ d}, R\geqslant R_{ f}^{\circ }$ 
\begin{align}

  \textrm{Var}\left(\P(\tau _{ x}\varphi _{ R})\right)\leqslant C_{ \varphi,f }V_{ \alpha ,\gamma }(R),
\end{align}
which means that $ \P$ is $ \alpha $-hyperuniform. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma withrate of arXiv:2412.04013, 'Rate estimates for total variation distance with applications\thanks{The author gratefully'] Let $X_{1}$, $X_{2}$ be random variables, let $\phi_{1},\phi_{2}$ denote the corresponding
characteristic functions. Assume that
\begin{equation}
|\phi_{i}(u)|\leq c_{\phi}(1+|u|)^{-d-\gamma},\quad i=1,2,	
\end{equation}
hold for some $c_{\phi},\gamma>0$ and also
\begin{equation}
E[|X_{i}|^{\delta}]\leq c_{f},\quad i=1,2,	
\end{equation}
for some $c_{f},\delta>0$. Then
\begin{equation}
d_{TV}(X_{1},X_{2})\leq G d_{FM}^{g}(X_{1},X_{2})	
\end{equation}
holds for 
$$
g=\frac{\gamma\delta}{(d+1+\gamma)(d+\delta)}
$$
and for some constant $G>0$ which depends only on $d$, $\gamma$, $\delta$, $c_{\phi}$ and $c_{f}$. 
The random variables have respective density functions $f_{1},f_{2}$ and
\begin{equation}
\sup_{x\in\mathbb{R}^{d}}|f_{1}(x)-f_{2}(x)|\leq \bar{G} d_{FM}^{\bar{g}}(X_{1},X_{2})
\end{equation}
holds for $\bar{g}=\frac{\gamma}{(d+1+\gamma)}$ and for a suitable $\bar{G}$, depending only
on $d$, $\gamma$ and $c_{\phi}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 (Anchored constant-speed estimate for normal families) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Let \(I\subset\R\) be an interval and let
\(f\colon I\times\Sph^1\to\R^d\) be a smooth family of immersed
closed curves whose velocity is everywhere normal, namely
\begin{equation}

 \langle\partial_tf,\partial_xf\rangle=0.
\end{equation}
Let \(\widetilde f\) be the anchored constant-speed parametrization
defined as in \eqref{eq:anchored-gauge}.  Write
\[
 L(f)=\int_{\Sph^1}\dd s_f,\qquad
 E_{\R^d}(f)=\frac12\int_{\Sph^1}|\vec\kappa_f|^2\dd s_f .
\]
Then, at every time,
\begin{equation}

 \|\partial_t\widetilde f\|_{L^2(\dd x)}
 \leq
 \left(\frac2{L(f)}+16E_{\R^d}(f)\right)^{1/2}
 \|\partial_tf\|_{L^2(\dd s_f)} .
\end{equation}

[Theo t_extinct_zeros of arXiv:2506.15500, 'On extinction and survival of the Bak-Sneppen model on arbitrary graphs'] Let $d$ be the maximal degree of~$G$. There is $q_0=q_0(d)>\frac{1}{d+1}$ (see~(equation def_q0 of the paper)) such that if $q:=1-p\leq q_0$, then the zeros ``become extinct'', in the sense that
\begin{equation}
 \pi(\eta: \text{there are more than $k$ zeros})\leq c_1e^{-c_2k} 
\end{equation}
for some positive constants $c_1,c_2$ depending on~$d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 (Concentration of linear statistics) of arXiv:2601.16377, '2601.16377'] There exists
$C>0$ such that for any any positive integer $\N$, any $t >0$ and real numbers $\mathfrak{a} < \mathfrak{b}$, we have
\begin{equation*}
 \amsmathbb P_\N\Bigg[\exists f \in \mathscr{H}_{\textnormal{Lip},\frac{1}{2}}\quad  \min_{h=1,2} \bigg|\int_{\amsmathbb R}
 f(x) \dd(\mu_{\N,h} - \mu_h)(x)\bigg| \geq t |\!| f
 |\!|_{\frac{1}{2}}+ \tfrac{C}{\N} \big( |\!|f|\!|_\textnormal{Lip} +|\!|f|\!|_\infty \big) \Bigg]  \leq  e^{C \N\log \N-\N^2 \frac{t^2}{C}},
\end{equation*}
where $\mathscr{H}_{\textnormal{Lip},\frac{1}{2}}$ is the space of Lipschitz functions on $[\hat{a}_h,\hat{b}_h]$ with finite Sobolev $\frac{1}{2}$-norm (see \eqref{eq_Fourier}), and
\begin{equation}

\hspace{-0.3cm}\amsmathbb P_\N\bigg[\Big|\#\big\{i \,\,\big| \,\,\ell_i \in [\N \mathfrak{a}, \N \mathfrak{b}]\big\} - \N \mu([\mathfrak{a},\mathfrak{b}]) \Big|
\geq  C \cdot \N^{\frac{1}{2}} \log^2 \N\bigg] \leq e^{-\frac{\N}{C}\log^2
\N}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

