body:
[Proposition prop:triangular-equation of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] For every \(k\ge1\),
\begin{equation}

    p_k'(t)
    =\sum_{i=1}^{k-1}i^{-\alpha}p_i(t)p_{k-i}(t)
     -k^{-\alpha}p_k(t),
    \qquad
    p_k(0)=\mathbf 1_{\{k=1\}}.
\end{equation}
In particular,
\begin{equation}

\begin{aligned}
    p_1(t)&=e^{-t},\\
    p_k(t)&=\int_0^t e^{-k^{-\alpha}(t-s)}
      \sum_{i=1}^{k-1}i^{-\alpha}p_i(s)p_{k-i}(s)\,ds,
      \qquad k\ge2.
\end{aligned}
\end{equation}

