body:
[Theorem thm:covering-stability of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Let $X^{(n)}$ be a sequence of variational solutions to (equation eq:SPDE of the paper) with coefficients $(\mathcal{A}^{(n)}, \mathcal{B}^{(n)})$ satisfying Assumptions (ass:LR of the paper), (ass:diff2 of the paper), (ass:SC of the paper), and (ass:nondeg of the paper) uniformly in $n$. Let $Y^{(n)}$, $\gamma_t^{(n)}$, and $v_h^{(n)}$ denote the associated first variation, Malliavin covariance, and covering field, and write $\Phi_r^{(n)} := Y^{(n)}(t,r)\mathcal{B}^{(n)}(r, X^{(n)}(r))$ and $\Phi_r := Y(t,r)\mathcal{B}(r, X(r))$. Fix $q \in (2,\infty)$ from clause~\textup{(iii)} below, and set $k := q/(q-2)$. Suppose:
\begin{enumerate}[(i)]
  \item $X^{(n)}(t) \to X(t)$ in $L^2(\Omega; H)$;
  \item \textup{(Strong joint $L^{2k}$-convergence of $\Phi$.)} 
  \begin{equation}
    \mathbb{E}\Bigl[\Bigl(\int_0^t \norm{\Phi^{(n)}_r - \Phi_r}^2_{L_2(U,H)}\,\mathrm{d}r\Bigr)^{\!k}\Bigr] \;\longrightarrow\; 0 \qquad (n \to \infty),
  \end{equation}
  with the uniform majorisation
  \begin{equation}
    \sup_n \mathbb{E}\Bigl[\Bigl(\int_0^t \norm{\Phi^{(n)}_r}^2_{L_2(U,H)}\,\mathrm{d}r\Bigr)^{\!k}\Bigr] \;<\; \infty;
  \end{equation}
  \item $h \in \operatorname{Ran}(\gamma_t)$ a.s., $\mathbb{E}[\norm{\gamma_t^{\dagger}h}_H^q] < \infty$, and $\sup_n \mathbb{E}[\norm{(\gamma_t^{(n)})^{\dagger}h}_H^q] < \infty$, for the same $q > 2$.
\end{enumerate}
Then $v_h^{(n)} \to v_h$ in $L^2(\Omega; H_W)$. If, additionally,
\begin{enumerate}[(i),resume]
  \item each $v_h^{(n)}$ lies in $\operatorname{Dom}(\delta_U)$ and the sequence $\{\delta_U(v_h^{(n)})\}_{n \ge 1}$ is $L^2(\Omega)$-Cauchy,
\end{enumerate}
then $v_h \in \operatorname{Dom}(\delta_U)$ and $\delta_U(v_h^{(n)}) \to \delta_U(v_h)$ in $L^2(\Omega)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: eigenvector bounds limiting of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists $q>2$ such that, for every $i \in \mathbb N$, there exists $c(q,i)>0$ such that
\begin{equation}
\| e_i\|_{L^q(\nu^0)} \leq c(q,i),
\end{equation}
where $e_i$ is a normalized eigenvector associated to eigenvalue $E_i$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem eq:alphabdry of arXiv:2608.30031, 'Ziggurats, taut foliations, and contact structures'] There exists a neighborhood $U$ of $T$ and coordinates $U \cong \mathbb{T}^2_{x,y} \times (-1,0]_r$ such that $\xi$ is defined by a $1$-form $\alpha_\partial$ of the form
   \begin{align} 
    \alpha_\partial = \lambda + r \mu
\end{align}
where $\lambda$ and $\mu$ are $1$-forms on $\mathbb{T}^2$ satisfying $\mu \wedge \lambda > 0$.

[Proposition prop.rsint of arXiv:2412.05698, 'Controlled rough SDEs, pathwise stochastic control and dynamic programming principles'] Suppose that \((Z,Z')\) belongs to \(\mathbf{D}_X^{\kappa,\kappa'} L_{p,q}\) with \(\alpha+\kappa>1/2\), \(\alpha+\min(\alpha,\kappa)+\kappa'>1\). Then the Riemann sums
   \begin{align*}
      \sum_{[u,v]\in{\mathcal P}, u\le t}Z_u \delta X_{u,v\wedge t}+Z'_u\ensuremath{\mathbb{X}}_{u,v\wedge t}
   \end{align*}
   converge uniformly in time \(t\in[0,T]\) in \(L_p\), as \(|{\mathcal P}|\) goes to 0, to a continuous adapted process, denoted by \(\int_0^\cdot (Z,Z')d\mathbf{X}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

