[Lemma lem:exp-log-differentials-app of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] For a Hermitian endomorphism $u$ and an endomorphism-valued one-form $X$,
\begin{align}
 e^{-u}\mathcal D(\exp)_u(X)
 &=\int_0^1e^{-su}Xe^{su}\,ds,
 \\
 \mathcal D(\log)_G(B)
 &=\int_0^\infty(G+\rho\operatorname{Id}_E)^{-1}B(G+\rho\operatorname{Id}_E)^{-1}\,d\rho.

\end{align}
If $u=\operatorname{diag}(\ell_1,\ldots,\ell_r)$ at a point, then
\begin{equation}
 \bigl(e^{-u}\mathcal D(\exp)_u(X)\bigr)_{ab}
 =\chi(\ell_b-\ell_a)X_{ab},
 \qquad \chi(s)=\frac{e^s-1}{s},
\end{equation}
with $\chi(0)=1$.

[Definition def:capacity of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Let $W$ be a simple random walk on $\mathbb{Z}^d$ for $d\geq 3$ and denote by $\mathbb{P}_y$ the law of $W$ with $W(0)=y\in\mathbb{Z}^d$. For a set $A\subset\mathbb{Z}^d$, the capacity of $A$ is defined as
\begin{equation}
    \Ca(A):=\lim_{\|y\|\rightarrow\infty}\frac{\mathbb{P}_y(W[0,\infty)\cap A\neq\varnothing)}{G(0,y)}=\sum_{a\in A}\mathbb{P}_a(W[1,\infty)\cap A=\varnothing),
\end{equation}
where $G$ is the SRW Green's function on $\mathbb{Z}^d$ and $\|y\|$ denotes the Euclidean norm of $y$.

[Lemma 31 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] Let $R_0\in(0,1)$ and $\gamma\in(0,1/2)$. There is $b<\infty$ such that, for
  every $N\geq1$,
  \begin{equation}
    \sup_{q\in[R_0,1]}
    \Ee\left[
      F_{A,N}(q,G)^{-\gamma N}
    \right]
    \leq
    e^{bN}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 107 of arXiv:2601.16377, '2601.16377'] Suppose that $B_2 \leq {A}_1\leq {B}_1 \leq {A}_2$ and consider the measure \eqref{zwdiscretemd} on the state space \eqref{eq_ZW_model_state_space} with weight
\begin{equation}
 w(x) =\frac{\N^{B_1 + B_2 - A_1 - A_2+2}}{2\pi} \cdot \frac{\Gamma\big(x - B_2\big)\cdot \Gamma\big(A_2 - x\big)}{\Gamma\big(B_1 + 1 - x\big)\cdot \Gamma\big(x + 1 - A_1\big)}.
\end{equation}
Then the following value of the partition function makes \eqref{zwdiscretemd} with weight \eqref{weightzwminus} a probability measure.
\begin{equation}
\begin{split}
\Z_{\N}^{\textnormal{ref}}
& = \frac{\N^{-\theta N^2 + (B_1 + B_2 - A_1 - A_2 +2 + \theta)N}}{(2\pi)^N} \cdot \prod_{1 \leq i < j \leq N} \frac{\Gamma\big(\theta(j - i) + 1\big) \cdot\Gamma\big(\theta(j -i) + \theta\big)}{\Gamma\big(\theta(j - i)\big)\cdot\Gamma\big(\theta(j - i) + 1 - \theta\big)} \\
& \times \prod_{i = 1}^N \frac{\Gamma\big(A_2 - B_2 + (i - 1)\theta\big)\cdot\Gamma\big(A_2 - B_1 + (i - 1)\theta\big)\cdot\Gamma\big(A_1 - B_2 + (i - 1)\theta\big)}{\Gamma\big((i-1)\theta +1\big)\cdot\Gamma\big(A_1 + A_2 - B_1 - B_2 + (2N - i - 1)\theta\big)\cdot\Gamma\big(B_1 - A_1 - (i - 1)\theta + 1\big)}.
\end{split}
\end{equation}

