[Proposition 6 (Proposition~3 in \cite{shi2020power}) of arXiv:2604.26396, '\LARGE Limiting spectral distributions of large consistent rank correlation matrices'] Let $\mZ=(Z_1,Z_2)^\tp\in\R^2$ be Lebesgue absolutely continuous, and let $\mZ_1,\mZ_2,\ldots$ be independent copies of $\mZ$. Then the following four statements are equivalent:

\begin{enumerate}
  \item $\E\big[h_D(\mZ_1,\ldots,\mZ_5)\big]=0$;
  \item $\E\big[h_R(\mZ_1,\ldots,\mZ_6)\big]=0$;
  \item $\E\big[h_{\tau^*}(\mZ_1,\ldots,\mZ_4)\big]=0$;
  \item $Z_1$ is independent of  $Z_2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem main of arXiv:2411.02362, 'Limit theorems for random Dirichlet series: boundary case'] Assume that $\mathbb{E}[\eta]=0$ and $\sigma^2=\mathbb{E}[\eta^2]\in(0,\infty)$. Then
\begin{equation}
C\Big(\Big(\Big(\frac{1}{2\sigma^2\log 1/s\, \log \log\log 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k : s\in(0, {\rm e}^{-{\rm e}})\Big)\Big)=[-1,1]\quad\text{\rm a.s.}
\end{equation}
In particular,
\begin{equation}
\limsup_{s\to 0+}\Big(\frac{1}{\log 1/s\, \log\log\log 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k=(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation}
and
\begin{equation}
\liminf_{s\to 0+}\Big(\frac{1}{\log 1/s\, \log\log\log 1/s}\Big)^{1/2}\sum_{k\ge 2}\frac{(\log k)^{-1/2}}{k^{1/2+s}}\eta_k=-(2\sigma^2)^{1/2}\quad\text{\rm a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:domstochdisorder of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any $L \in \ensuremath{\mathbb{N}}$ and any $\beta \geq 0$, one has the stochastic domination
\begin{equation} 
    \nu_{L , \beta} \preceq \mathbb{P}_{\Lambda_L , p_0(\beta)}^{\mathrm{site}}.
\end{equation}
For any $L \in \ensuremath{\mathbb{N}}$, any $n \in \ensuremath{\mathbb{N}}$ and any $\beta_1 , \beta_2 \in (0, \infty)$, one has the stochastic domination

\begin{equation} 
    \nu_{L , n , \beta_1 , \beta_2}  \preceq \mathbb{P}_{\Lambda_L , p_0(\beta_1)}^{\mathrm{site}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Fix $a<0<b$. Under $\mathbb{P}_{a,b}^{<}$, the following identities hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item For the pre-infimum process,
\begin{equation*}\small
\mathbb{P}_{a,b}^{<}\{M_{0,H_I}^-<d\}=\begin{cases}
0, & d\le -a,\\
\displaystyle
1-\left[\frac{W^{(\gamma)\prime}(d)W^{(\gamma)}(b-a)-W^{(\gamma)\prime}(b-a)W^{(\gamma)}(d)}{W^{(\gamma)\prime}(-a)W^{(\gamma)}(b-a)-W^{(\gamma)\prime}(b-a)W^{(\gamma)}(-a)}\right]
\left(\frac{W^{(\gamma)}(-a)}{W^{(\gamma)}(d)}\right),
& -a<d<b-a,\\
1, & d\ge b-a.
\end{cases}
\end{equation*}

\item For the intermediate process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_I,H_S}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{W^{(\gamma)}(b-a)}{W^{(\gamma)}(d)}
\exp\left\{-(b-a-d)\frac{W_+^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}\right\},
& 0<d<b-a,\\[12pt]
1, & d\ge b-a.
\end{cases}
\end{equation*}

\item For the post-supremum process,
\begin{equation*}
\mathbb{P}_{a,b}^{<}\{M_{H_S,T}^-<d\}=\begin{cases}
0, & d\le0,\\[4pt]
\displaystyle
\frac{\bigl(Z^{(\gamma)}(d)-1\bigr)\dfrac{W^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}-\gamma W^{(\gamma)}(d)}
{\bigl(Z^{(\gamma)}(b-a)-1\bigr)\dfrac{W^{(\gamma)\prime}(b-a)}{W^{(\gamma)}(b-a)}-\gamma W^{(\gamma)}(b-a)},
& 0<d<b-a,\\[14pt]
1, & d\ge b-a.
\end{cases}
\end{equation*}
\end{enumerate}

