[Proposition prop:poly-approx-relu-network of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] Suppose that $\mu$ is a probability distribution over $\RR^d$. Then for any $f\in \cH_{\mathsf{ReLU}}$, there exists a polynomial $p$ of 
    \begin{enumerate}
        \item degree $O(\varepsilon^{-r})$ under $r$-strictly sub-exponential input $\mu$;
        \item degree $O(\exp\{O(\varepsilon^{-1})\})$ under sub-exponential input $\mu$, 
    \end{enumerate}
    such that $\norm{f - p}_\mu\le \varepsilon$.

[Theorem 6 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\geq 1$. There exists a map
    \begin{equation*}
        S(\cdot)_T:C_o^{\textup{$p$-var}}([0,T],G^{\lfloor p\rfloor}(\mathbb{R}^k))\rightarrow (T(\mathbb{R}^k)):=\prod_{\ell=0}^\infty (\mathbb{R}^k)^{\otimes \ell};\quad S(\mathbf{x})_T=\left(1,S(\mathbf{x})^{(1)}_T,S(\mathbf{x})^{(2)}_T,\dots\right)
    \end{equation*}
    such that $S(\mathbf{x})_T^{(m)}=\mathbf{x}^{(m)}_T$ for all $m=0,\dots,\floor{p}$. Moreover, $S(\mathbf{x})_T=S(\mathbf{y})_T$ if and only if $\mathbf{x}\sim_t\mathbf{y}$, where $\sim_t$ denotes the tree-like equivalence (see Definition \ref{def:tree_like_eq} below).

[Thm main of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ is a generalised preferential attachment tree. Then,
    \begin{enumerate} 
        \item  If \[\sum_{j=0}^{\infty} \frac{1}{F(j)^2} = \infty \quad \text{almost surely},\] then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ almost surely does not have a persistent hub. 
        \item  Suppose that the following two conditions are satisfied: 
        \begin{enumerate}
            \item There exists a sequence $(x_{j})_{j \in \mathbb{N}_0}$ with $\sum_{j=0}^{\infty} \frac{1}{x_{j}^2} < \infty$ such that,
				\begin{equation}            
             		F(j) \geq x_{j} \quad \text{almost surely.}
             	\end{equation} 
            \item There exists a $\lambda > 0$ such that 
                \begin{equation} 
                \sum_{i=0}^{\infty} \prod_{j=0}^{i}\E{\frac{F(j)}{F(j) + \lambda}} < \infty.
                \end{equation}
        \end{enumerate}
        Then $(\mathcal{T}_{i})_{i \in \mathbb{N}_{0}}$ has a unique persistent hub almost surely. 
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Df 6 of arXiv:2608.21787, 'Stability of extremal hyperplane projections of balls in $\ell_p^n(\R)$'] Let $X$ and $Y$ be symmetric random variables. We say that $X$ is dominated by $Y$ in the Choquet ordering and denote $X \preceq Y$ if for every convex function $\phi \colon \R \to [0, \infty)$ we have
        \begin{align*}
            \E\phi(X) \le \E\phi(Y).
        \end{align*}

[Lemma lem:local of arXiv:2608.23638, 'Replicable Conformal Prediction'] Let $F$ be continuous, let $S_1,\ldots,S_n$ be i.i.d.\ with cdf $F$,
let $k_n=\lceil(1-\alpha)(n+1)\rceil\le n$, and put
$\widetilde{\tau}=S_{(k_n)}$.  Under Assumption~(ass:margin of the paper),
$|F(\widetilde{\tau})-p|<f_{\min}\Delta$ implies $\widetilde{\tau}\in I$, and for every
$a,b\in I$,
\begin{equation}
|a-b|\le\frac{|F(a)-F(b)|}{f_{\min}}.
\end{equation}
Moreover, if $n\ge4/(f_{\min}\Delta)$, then
\begin{equation}
\mathbb{P}\{|F(\widetilde{\tau})-p|\ge f_{\min}\Delta\}
\le2\exp\{-2n(f_{\min}\Delta-2/n)^2\}
\le2\exp\!\left(-\frac{n f_{\min}^{2}\Delta^{2}}2\right).
\end{equation}

[Lemma random_walk_range of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $G$ be a quasi-transitive graph that is of superlinear polynomial growth.
Consider a continuous-time simple random walk on $G$. 
There exist positive constants $c_0 = c_0(G)$ and $c_1 = c_1(G)$ such that the following is true.
Let $x \in V$ and $a > 1$.
For any $H \subseteq B_x(a)$ with $|H| \leq \frac{3}{4}|B_{x}(a)|$  and any $y \in B_x(a)$, if we define $\widetilde{\mathrm{R}}^{\text{H}}_y(t) := \mathrm{R}_y(t) \cap (B_x(a) \setminus H)$, \footnote{Here we omit the dependency of $\mathrm{R}_{y}^{i}(t)$ on the particle label since this is true for any random walk starting at $y$. We also omit the dependency on $y$ when it is clear from the context.} then

\vspace{2mm}

\begin{align*}
    \mathbb P_y \left( |\widetilde{\mathrm{R}}^{\text{H}}(a^2)| \geq c_1 \cdot \theta(a) \right) \geq c_0 \, ,
\end{align*}
where $\theta(a)$ is defined as 
\begin{align}
    \theta(a) := \begin{cases}
        a^2 & \text{if } d \geq 3, \\
        a^2 / \log a & \text{if } d = 2.
    \end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Define a nonlinear map
\begin{equation}

H_{1,n} \ni \phi_n \mapsto \cp_n\coloneqq \pi_{1,n}( \Atwo \phi_n + \psi^\prime(\phi_n) - \avg{\psi^\prime(\phi_n)})  \in H_{1,n}.
\end{equation}
Then, there exists a constant $C>0$ such that, for every $n$ and all $\phi_n \in H_{1,n}$, 
\begin{align}

\lvert \Atwo \phi_n \rvert_{L^2}^3 &\leq  C (\lvert \cp_n \rvert_{\newone{H}}^{2} \lvert \phi_n \rvert_{L^2} + \lvert \phi_n \rvert_{L^2}^3),
\\

\lvert \Atwo^{3/2} \phi_n \rvert_{\mathbb{L}^2}^{3/2} &\leq C (\lvert \cp_n \rvert_{\newone{H}}^{3/2} + \lvert \phi_n \rvert_{L^2}^{3/4} \lvert \Atwo \phi_n \rvert_{L^2}^{3/4} +  \lvert \phi_n \rvert_{L^2}^{3/2} \Vert \phi_n \Vert_{H^2}^{3}),\; \mbox{ for d=2 or d=3},
\\

\lvert \Atwo^{3/2} \phi_n \rvert_{\mathbb{L}^2}^2
&\leq C(\lvert \cp_n \rvert_{\newone{H}}^2 + \lvert \phi_n \rvert_{\newone{H}}^2 +  \lvert \phi_n \rvert_{L^2}^2 \lvert \phi_n \rvert_{\newone{H}}^2 \Vert \phi_n \Vert_{H^2}^2), \mbox{ for d=2}.
\end{align}

