[Theorem 3 (Carlen theorem) of arXiv:2604.14427, 'A criterion for proving entropy chaos on path space'] Consider $(\Omega, \mathcal F, \mathcal F_t,X_t) $ with
$\Omega=C(\R_+,\R^d)$, $X$ the canonical process
$X_t(\omega)=\omega(t)$, $\omega\in\Omega$, and $\mathcal F_t=\sigma(X_s, s\leq t)$
its natural filtration.
  If $(\rho,v)$ is a proper infinitesimal characteristics  pair in the sense of Definition \ref{conservativediffusiondefinition}, putting 
  \begin{equation} 
    b\deq u+v, \quad 
    u(x,t)\deq
    \begin{cases}
      \frac{\nabla\rho(x,t)}{2\rho(x,t)}, & \rho(x,t)\ne 0,\\
      0, & \rho(x,t)=0,
    \end{cases}
  \end{equation}
  then there exists a unique Borel
  probability measure $\mathbb P$ on $\Omega$ such that
  \begin{enumerate}[(i)]
  \item $(\Omega, \mathcal F, \mathcal F_t,X(t),\mathbb P) $ is a Markov
    process;

  \item the image of $\mathbb P$ under $X(t)$ has a density
    $\rho(x,t)$;

  \item $W(t):=X(t)-X(0)-\int_0^tb(X(s),s)ds$ is a $(\mathbb P,\mathcal F_t)$-Brownian motion, which means that the following Brownian-driven SDE, 
    \begin{equation}
      \dd X(t) = b(X(t),t)\dd t + \dd W(t),
    \end{equation}
    admits a weak solution.
      \end{enumerate}

[Lem 56 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Suppose that $\bX$ is randomized-$\mu$-like, $\nu\sim \bP(\bX,K)$ and $K\leq (\widetilde C_{\mu}-\eps) \log N$. We have
        \begin{equation}
            \nu\lt(A_{\mu,\chi,\rho,\varphi}\rt)\to 1.
        \end{equation}

