[Theorem 13 of arXiv:2609.03187, 'Duality for a Martingale Transport Problem with Moment Constraints'] Let $\pi^*$ be the optimal coupling from Corollary~\ref{cor:plan-structure}, and let $\lambda^*$ be the corresponding dual optimizer in
\eqref{eq:strong-dual}. Define
\[
f_{\lambda^*}(y) := \frac{1}{2} y^2 +  \Lambda_{\lambda^*}(y) \in L^1(\nu^*),
\]
where $\nu^*$ is the second marginal of $\pi^*$. Then:
\begin{enumerate}
    \item $\pi^*$ is the law of $(M_0,M_1)$ for the Bass martingale 
    \[
    M_t = \mathbb E\!\left[v'(B_1)\mid B_t\right], \qquad 0\leq t\leq 1,
    \]
    where $v = H_{\lambda^*}$, $v':= v'_- = T_{\lambda^*}$, $B_t:=\xi+W_t$, $\xi \sim (a_{\lambda^*})_\# \mu$, and $(W_t)_{0\leq t\leq 1}$ is a standard Brownian motion independent of $\xi$;

    \item $\pi^*$ solves the weak martingale transport problem \eqref{eq:wmot} for its marginals $(\mu, \nu^*)$;

    \item The convex envelope $f^{**}_{\lambda^*}$ of $f_{\lambda^*}$ solves the dual problem of \cite{BVBST} for the pair of marginals $(\mu, \nu^*)$:
    \begin{equation}
    \inf_{\substack{
    \psi\in L^1(\nu^*),\\ \psi \text{ convex}}} \left \{\int \psi\, d\nu^* - \int (\psi^* * \gamma)^*(x) d\mu \right \}.
    \end{equation}
    Thus, $\lambda^*$ determines a solution of the dual problem with prescribed marginals.
\end{enumerate}

