[Lemma 179 of arXiv:2601.16377, '2601.16377'] Let $\mu$ be an absolutely continuous compactly-supported complex measure on a surface, such that its density with respect to the Lebesgue measure (relative to coordinate charts) is smooth. If we have a holomorphic function $z$ on the surface which is a local coordinate near every point, we can also write the measure element $\dd\mu(p) = \mu(p)|\dd z(p)|^2$, where $\mu(p)$ is a smooth function of a point $p$ on the surface.

The Gaussian free field on this surface is such that $\int \textnormal{GFF}(p)\dd \mu(p) = \int \textnormal{GFF}(p)\mu(p)|\dd z(p)|^2$ is a well-defined centered Gaussian random variable. Moreover, if we have two such measures $\mu_1$ and $\mu_2$, then
\begin{equation*}
\begin{split}
 \amsmathbb E \left[ \bigg(\int \textnormal{GFF}(p_1)\dd\mu_1(p_1)\bigg) \cdot \bigg(\int\textnormal{GFF}(p_2)\dd\mu_2(p_2)\bigg)\right] & =\iint \textnormal{Gr}(p_1,p_2) \dd \mu_1(p_1) \dd \mu_2(p_2) \\
 & = - \int \mu_1(p) \big(\Delta^{-1} \mu_2(p)\big) |\dd z(p)|^2,
\end{split}
\end{equation*}
where $\Delta^{-1}$ is the inverse of the Laplace operator $4\partial_z\partial_{z^*}$ with Dirichlet boundary conditions on the surface. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 of arXiv:2412.00822, '\textsc{Ideal Poisson--Voronoi tessellations \\ beyond hyperbolic spaces}'] $_{}$\\
\begin{itemize}
\vspace{-10pt}
\item[(i)] Almost surely, the set of points $z \in \mathcal{M}$ at equal separation from any corona points is unbounded;
\item[(ii)]  The separation seen from $(X_{t},Y_{t})$ can be rescaled so to converge in distribution when $t\to \infty$ to a stationary Poisson process $S_{\infty}(\eta,\xi)$ over $\mathbb{R}\times \mathbb{R}\times \mathbb{R}_{\geq 0}$ of intensity measure
$$
\nu_{\infty}(\eta,\xi) = 4\pi^{2}\frac{\Re(\eta)}{|\eta+i \hat{\theta}|^{2}} \mathbf{1}_{\Re(\eta)\geq 0} \;\mathrm{d}\hat{\theta} \frac{\Re(\xi)}{|\xi+i \hat{\phi}|^{2}}\mathbf{1}_{\Re(\xi)\geq 0} \;\mathrm{d}\hat{\phi}\,  \mathbf{1}_{y\geq 0}\mathrm{d}y  \,,
$$
where $(\eta,\xi)\in \mathbb{C}\times \mathbb{C}$ and $\Re(\eta)$ denotes the real part of $z \in \mathbb{C}$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem integralordering of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $\mathbf{n} =(n_1, n_2, n_3)\in {\mathbb N}^3$ and ${\boldsymbol \sigma} = 3^{n_{31}}2^{n_{21}}1^{n_{1}}2^{n_{22}}3^{n_{32}}$ with $n_{21}+n_{22}=n_2$ and $n_{31}+n_{32}=n_3$. 
Then the following hold for every ${\boldsymbol \tau} \in \mathcal S_{\mb{n}}$. Here, $\#$ denotes an integer whose exact value is not specified.\footnote{It is possible to determine the value of $\#$. For example, $\#=i(1+b_1)+j+k(i-j) + (j+k)(b_3+n_2-n_3)$ for (a), if $\type({\boldsymbol \tau})= (b_{123}, b_{12}, b_{23}, b_1, b_2, b_3)$.}
\begin{enumerate}[(a)]
\item We have 
\begin{equation*}
    \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} 
    =  \sum_{i=0}^{n_1 \wedge n_{22}} \sum_{j=0}^{i \wedge n_{32}}  \sum_{k=0}^{(n_2-i) \wedge n_{31}} 
    (-1)^{\#} \mathsf{A}^{n_{1}, n_{22}}_i \mathsf{A}^{i,n_{32}}_j \mathsf{A}^{n_2-i,n_{31}}_{k}
    \, \mathrm I^{{\boldsymbol \sigma}_{ijk}}_{\tau},
\end{equation*}
where  ${\boldsymbol \sigma}_{ijk} =2^{n_{2}-i-k}(23)^k3^{n_{3}-j-k}(123)^j(12)^{i-j}1^{n_{1}-i}$. 

\item We have  
\begin{equation*}
    \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} 
    =  \sum_{i=0}^{n_1 \wedge n_{22}}    \sum_{j=0}^{i \wedge n_{32}} \sum_{k=0}^{(n_2-i) \wedge (n_{32}-j)}
    (-1)^{\#} \mathsf{A}^{n_1, n_{22}}_i \mathsf{A}^{i,n_{32}}_j \mathsf{A}^{n_2-i, n_{32}-j}_k 
    \, \mathrm I^{{\boldsymbol \sigma}_{ijk}}_{\tau},
\end{equation*}
where ${\boldsymbol \sigma}_{ijk} =3^{n_{3}-j-k}(23)^k2^{n_{2}-i-k}(123)^j(12)^{i-j}1^{n_{1}-i}$. 

\item We have 
\begin{equation*}
    \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} 
    = \sum_{i=0}^{n_{22} \wedge n_{32}}  \sum_{j=0}^{n_{21} \wedge (n_{32}-i)}  \sum_{k=0}^{n_{1} \wedge i} \sum_{l=0}^{(n_{21}-j) \wedge (n_1-k)}
    (-1)^{\#} 
    \mathsf{A}^{n_{22}, n_{32}}_i \mathsf{A}^{n_{21}, n_{32}-i}_j \mathsf{A}^{n_1, i}_k \mathsf{A}^{n_{21}-j, n_1-k}_l
    \, \mathrm I^{{\boldsymbol \sigma}_{ijkl}}_{\tau}, 
\end{equation*}
where  ${\boldsymbol \sigma}_{ijkl} =  3^{n_{3}-i-j}(23)^{i+j-k} (123)^{k} 1^{n_{1}-k-l} (12)^l 2^{n_{2}-i-j-l}$. 
\end{enumerate}

