[Lemma lem: bulk law-technical-2 of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] The limiting renormalized cost function has the following approximation properties. 	
\begin{enumerate}
\item[(i)] For every $\mu \in \overline{\mathcal X}$ and every $K \in \mathbb N^*$, there exists $\mu_K\in \mathcal X$ such that
\begin{equation}
|\widetilde{\mathbb F}^{f;\varphi_0,\varphi_+}_\infty (\mu) - \widetilde{\mathbb F}^{f;\varphi_0,\varphi_+}_\infty(\mu_K)| < 1/K.
\end{equation}
\item[(ii)] Let $\mu \in \mathcal X$. If $\Xi^{\infty}(\varphi_{0}^T,\varphi_{+}^T)\to \Xi^{\infty}(\varphi_{0}^\infty,\varphi_{+}^\infty)$ in $\boldsymbol{\mathcal B}$, then
\begin{equation} 
\lim_{T \rightarrow \infty} \widetilde {\mathbb F}^{f;\varphi^T_0,\varphi^T_+}_T(\mu) = \widetilde{\mathbb F}^{f;\varphi_0,\varphi_+}_\infty(\mu). 
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem_maximum_hitting_time_of_0 of arXiv:2411.13964, 'Long-time analysis of a pair of on-lattice and continuous run-and-tumble particles with ja'] Let $\tau = \inf \left\{ t \ge 0 : X_D(t) = (0, *^0_{(1, -1)} ) \right\}$. There exists $C > 0$ such that
\begin{align*}
\sup_{X_0 \in E_D} E_{X_0} \left[\tau\right] \le C \frac{1}{\omega} \left(1 + \omega^2 \ell^2\right).
\end{align*}

