[Prop symmetric-tree-geometry of arXiv:2609.03856, 'Consensus time for asynchronous $\ell^p$ relaxation: graph dependence'] Assume $d_0\ge2$.  Then $o$ minimizes $T_G(r)$.  If
\begin{equation}
 S=\sum_{1\le i\le j\le k-1}
 (d_i d_{i+1}\cdots d_j)^{1/(p-1)},
\end{equation}
where the sum is empty for $k=1$, then
\begin{equation}
 1+S\le T_G\le1+2S.
\end{equation}
The actual maximum degree is
\begin{equation}
 \Delta_G=\max\left\{d_0,\ 1+\max_{1\le i<k}d_i\right\},
\end{equation}
with the second maximum omitted for $k=1$.

[Lemma 23 of arXiv:2605.16868, '\ttl'] Let $\boldsymbol{F}_1$ and $\boldsymbol{F}_2$ be two operators in $\mathcal{R}$ with respective bounded parameters $(\gamma_1,k_1)$ and $(\gamma_2,k_2)$. Then for any $X\in \mathcal{D}_T(L_1)$ and all $n\geq1$, $m\geq0$, $i=1,2$,
\begin{enumerate}[label=(\roman*)]

\item
\begin{equation}

\|\boldsymbol{F}_i^{(m)}\pi^n_{X,F_i}(0)\|_{T,1} \leq \|\boldsymbol{F}_i^{(m)}\|_{op}\|X\|_{T,1} + \|\boldsymbol{F}_i^{(m+1)}\pi^{n-1}_{X,F_i}(0)\|_{T,1}\,,
\end{equation}

\item
\begin{equation}

\|\pi^n_{X,F_i}(0)\|_{T,1} \leq \bigg(\sum_{j=0}^{n-1}\|\boldsymbol{F}_i^{(j)}\|_{op}\bigg)\|X\|_{T,1}\,,
\end{equation}

\item
\begin{equation}

\begin{split}
&\boldsymbol{F}_2^{(m)}\sup_{0\leq s\leq t}\big|(\pi^n_{X,F_1}(0))(s) - (\pi^n_{X,F_2}(0))(s)\big| \\&\leq \boldsymbol{F}_2^{(m)}\sup_{0\le s\le t}\big|(\boldsymbol{F}_1-\boldsymbol{F}_2)(\pi^{n-1}_{X,F_1}(0))(s)\big|  \\
& \quad+ \boldsymbol{F}_2^{(m+1)}\sup_{0\leq s\leq t}\big|(\pi^{n-1}_{X,F_1}(0))(s) - (\pi^{n-1}_{X,F_2}(0))(s)\big|\,, 
\end{split}
\end{equation}

\item
\begin{equation}

\|\pi^n_{X,F_1}(0) - \pi^n_{X,F_2}(0)\|_{T,1} \leq \bigg(\sum_{j=0}^{n-1}\|\boldsymbol{F}_2^{(j)}\|_{op}\bigg)\frac{k_1\|\boldsymbol{F}_1-\boldsymbol{F}_2\|_{op}\|X\|_{T,1}}{1-\gamma_1}\,,
\end{equation}

\item
\begin{equation}

\|\Psi_{F_i}(X)\|_{T,1} \leq \frac{k_i\|X\|_{T,1}}{1-\gamma_i}\,,
\end{equation}

\item
\begin{equation}

\|\Psi_{F_1}(X)-\Psi_{F_2}(X)\|_{T,1} \leq \frac{k_1k_2\|\boldsymbol{F}_1-\boldsymbol{F}_2\|_{op}\|X\|_{T,1}}{(1-\gamma_1)(1-\gamma_2)}\,. 
\end{equation}
\end{enumerate}

[Lemma lem:L-property of arXiv:2603.01823, 'on a fractional stochastic heat equation arising from the disordered pinning model'] Let $F_s$ be an adapted process  and $f(s)$ be a deterministic measurable  function. Then
\begin{align}
&\quad\mathbf{E}_{(t,x)}\left[\int_0^t F_s{\mathrm d} L_s\right]=\int_0^t \mathbf{E}_{(s,0)}\left[F_s\right]g_\rho(t-s,x){\mathrm d} \mathbf{s},
\\&\quad\mathbf{E}_{(t,x)}\left[\int_0^t f(s){\mathrm d} L_s\right]= \int_0^t f(s)g_\rho(t-s,x){\mathrm d} \mathbf{s},
\end{align}
provided the right-hand sides exist.  For a deterministic measurable symmetric function $f(s_1,\cdots,s_n)$, we have 
 \begin{equation}
\begin{aligned}
&\quad\mathbf{E}_{(t,x)}\left[\int_{[0,t]^n}f(s_1,\cdots
,s_n){\mathrm d} L_{s_1}\cdots{\mathrm d} L_{s_n}\right]\\
=&n!\int_{[0,t]_<^n}f(s_1,\cdots
,s_n)g_\rho(s_2-s_1,0)\cdots g_\rho(t-s_n,x){\mathrm d} \mathbf{s},
\end{aligned}
\end{equation}
provided the right-hand side exists.

