  \end{enumerate}

[Lem finite_energy_approx of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For $\mathsf{P}\in  \mathcal P_{s,1}(\Gamma)$ with  $\mathcal F_{\beta}({P})<\infty$  there exists a sequence $\mathsf{P}^n\in \mathcal P_{s,1}(\Gamma)$ with $\mathcal{W}^{int}(\mathsf{P}^n)\leq \mathcal{W}^{int}(\mathsf{P})+1/n$, $\mathcal E(\mathsf{P}^n)\leq \mathcal E(\mathsf{P})+1/n$ and 
    \begin{align}
        \int \sum_{x\in \xi\cap \Lambda_1}\left\lvertx^+-x\right\rvert^p\mathsf{P}^n(d\xi)<\infty.
    \end{align}
    Furthermore, $\mathsf{P}^n\xrightarrow{n\to \infty}\mathsf{P}$  w.r.t. $\mathcal T_{\mathcal L}$ (in particular weakly) and for $n\in \IN$ there exists $q_n>0$  such that the measure $\mathsf{P}^n$ is concentrated on the set \begin{align}
        \Gamma_{q_n}=\{\xi\in \Gamma: \varphi(x-y)\leq q_n,1/q_n\leq \left\lvertx-y\right\rvert \text{ for any two distinct }x,y\in \xi \}.
    \end{align}

