[Theorem of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Let $ f, g \in L^{2}_{\mathbb{F}}(0, T; H) $ and $ a, b \in L^{2}_{\mathcal{F}_{s}} (\Omega) $, $ 0 \leq s  < t \leq T $. Then 
    \begin{enumerate}[(i)]
        \item $ \displaystyle \int_s^t f d W \in L_{\mathbb{F}}^2(\Omega ; C([s, t] ; H)) $;
        \item $ \displaystyle \int_s^t(a f+b g) d W=a \int_s^t f d W+b \int_s^t g d W, \text { a.s. } $;
        \item $ \displaystyle \mathbb{E}\Big(\int_s^t f d W\Big)=0 $;
        \item $ \displaystyle \mathbb{E}\Big(\Big\langle\int_s^t f d W, \int_s^t g d W\Big\rangle_H\Big)=\mathbb{E}\Big(\int_s^t\langle f(\tau, \cdot), g(\tau, \cdot)\rangle_H d \tau\Big) $.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: asymp of dimension ratio with r K f of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $r,K,f$ be three integers such that $0\leq K \leq r\leq f/2$. As $n\to \infty$, uniformly over all $\lambda \vdash n$ such that $r(\lambda)= r$ and all $\mu \vdash f$ such that $\mu \subset \lambda$ and $r(\mu) = r - K$, we have
    \begin{equation}
     \frac{d_{\mu}}{d_\lambda} \asymp_r \left(\frac{f}{n} \right)^r f^{-K};
    \end{equation}
and moreover, if $K=0$ (that is, if $\mu^* = \lambda^*$), we have, denoting $k = n-f$, 
\begin{equation}
    \frac{d_{\mu}}{d_\lambda} = \left( \frac{f}{n} \right)^r \left( 1 - T(r)\frac{k}{fn} + O_r\left( \frac{1}{f^2}\right) \right).
\end{equation}

