[Lemma 25 (minorisation on interior) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:scheme-density}
  Let $I,[a,b]\subset(0,\infty)$ be compact and let $T_\star>0$; assume \eqref{eq:nonconvex-hyp}. There
  are thresholds $\theta,T_0>0$, depending only on $\delta,\lambda,\beta$ and the position of
  $I\cup[a,b]$, such that if
  \begin{equation}
    \operatorname{diam}(I\cup[a,b])\ \le\ \theta
    \qquad\text{and}\qquad
    T_\star\ \le\ T_0 ,
  \end{equation}
  then there exist $c_\star,h_2>0$ with
  \begin{equation}
    K_h^{m}(x',\cdot)\ \ge\ c_\star\,\mathrm{Leb}|_{[a,b]},
    \qquad\text{ for $x'\in I,\ \ h\le h_2,\ \ |m-T_\star/h|\le1$.}
  \end{equation}

[Theorem 10 (Structure of the continuation region) of arXiv:2608.12291, 'When should one stop the most exciting game?\\ {\tiny Sequential Inference for win-marting'] There exists a lower semicontinuous boundary $b_T:[0,T)\to(1/2,1)$
such that
\begin{equation}
    \mathcal{C}_T
    =
    \{(t,x)\in\mathcal{S}_T:1-b_T(t)<x<b_T(t)\}.
\end{equation}
The first hitting time in \eqref{eq:definition_optimal_stopping_time} is given by
\begin{equation*}
    \tau^*_T(t,x)=\inf\{0\le u<T-t:X_u^x\not\in(1-b_T(t+u), b_T(t+u))\}\wedge(T-t)
\end{equation*}
and is an optimal stopping time for \eqref{eq:OSP_T} if $T<\infty$ and \eqref{eq:inf_horizon_osp} if $T=\infty$. 
Furthermore,
\begin{equation*}
    \gamma(t)<b_T(t)<1,\qquad t<T.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 9 (Algorithmic guarantee for the mixture objective) of arXiv:2608.21466, 'Spectral partitioning for $k$-block averaging kernels of finite Markov chains'] Let $k\in\llbracket 2,n-1\rrbracket$.
The output of Algorithm~\ref{alg:additive-mixture-sweep} satisfies
\begin{equation}
    0\leq H(\widehat{\mathcal O}_H)-H_k^*
    \leq\frac12\left(
       W_P\overline\delta_{P,\ell}
       -g_P\delta_{P,k}^*
      \right).

\end{equation}
If at least one candidate is a $\rho$-approximation for weighted
$k$-means, so that
$\overline\delta_{P,\ell}\leq\rho\delta_{P,k}^*$, then
\begin{equation}
    H(\widehat{\mathcal O}_H)-H_k^*
    \leq\frac12(\rho W_P-g_P)\delta_{P,k}^*.

\end{equation}

[Definition 9 of arXiv:2511.02725, 'Mixing of general biased adjacent transposition chains'] For a vector $\vec{\ell} = (\ell_i^-,\ell_i^+)_{i\in [n]}\in \R^{2n}$ with $\ell_i^\pm \ge 0$, we say  $\sigma$ is \emph{$\vec{\ell}$-localized} if 
    \begin{align*}
    \si \in \vloc :=
        \bigcap_{1\le k \le n} \{ \sigma^{-1}(k) -k \in [-\ell_k^-, \ell_k^+ ]\}.
    \end{align*}
    We let $\ell_{\max}^-=\fl{\max_k \ell_k^-}$, $\ell_{\max}^+=\fl{\max_k \ell_k^+}$, and $\ell_{\max} = \max\{\ell_{\max}^-, \ell_{\max}^+\}$.

[Theorem t: univ ent of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Assume the conditions of Theorem~(t: univ pro of the paper) hold, along with the origin dominance condition (equation e:ds of the paper). Then 
 \begin{equation}
      \frac{ \langle \tilde{f}_T, \eta_T \rangle }{ \sqrt{2m(d-\alpha) \log T }  }  \to \langle h_\alpha , \eta \rangle  \quad \text{in probability, \quad as } T\to\infty, \end{equation}
