[Proposition inversibilite de A of arXiv:2412.00865, 'On the spectral problem and fractional diffusion limit for Fokker-Planck with(-out) drift '] Let $\eta_0>0$ and $\lambda_0>0$ small enough. Let $\eta \in [0,\eta_0]$ and $\lambda \in \mathbb{C}$ fixed, with $|\lambda|\leqslant \lambda_0$. 
For all $F \in \mathcal{H}_\eta'$,  equation (equation formulation fable of the paper) admits a unique solution $\psi^{\lambda,\eta} \in \mathcal{H}_\eta\subset  \mathcal{H}_0$, satisfying the following estimate
\begin{equation}
\| \psi^{\lambda,\eta} \|_{\mathcal{H}_0} \leqslant \| \psi^{\lambda,\eta} \|_{\mathcal{H}_\eta} \leqslant C \| F \|_{\mathcal{H}_\eta'} ,
\end{equation}
where $C$ is a positive constant that does not depend on $\lambda$ and $\eta$. Moreover, for $F \in L^2_{\langle v\rangle^2} \subset \mathcal{H}_\eta'$ we have
\begin{equation}
\| \psi^{\lambda,\eta} \|_{\mathcal{H}_0} \leqslant\| \psi^{\lambda,\eta} \|_{\mathcal{H}_\eta} \leqslant C \| F \|_{L^2_{\langle v\rangle^2}} ,
\end{equation}
where $L^2_{\langle v\rangle^2}$ denote the weighted $L^2$ space: $\displaystyle L^2_{\langle v\rangle^2}:=\left\{f: \mathbb{R}^d \longrightarrow \mathbb{C} \ ; \ \int_{\mathbb{R}^d} |f|^2 \langle v\rangle^2 \mathrm{d}v < \infty \right\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:order-bounded-equivalent of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Let $M$ be a subset of $\mathcal P_2(\mathbb R)$.
Then the following statements are true.
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item $M$ is bounded from above in $\mathcal P_2(\mathbb R)$ with respect to the stochastic order if and only if
\begin{equation}
\int_0^{\8}\bigg(\sup_{\mu\in M}\mu\big((u,\8)\big)\bigg)u\mathop{}\!\mathrm{d} u<\8.
\end{equation}
\item $M$ is bounded from below in $\mathcal P_2(\mathbb R)$ with respect to the stochastic order if and only if
\begin{equation}
\int_0^{\8}\bigg(\sup_{\mu\in M}\mu\big((-\8,-u]\big)\bigg)u\mathop{}\!\mathrm{d} u<\8.
\end{equation}
\end{enumerate}

