body:
[Lemma 68 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $\emptyset \ne \Omega \subset \RR^d$ be an arbitrary bounded domain.
    Let $A_1,A_2 \in \{B,F\}$.
    Let $s_1,s_2 \in \RR$ and let $0<p_1,q_1,p_2,q_2\le\infty$ (with $p_i <\infty$ if $A_i = F$).
    Assume that
    \begin{equation*}
       s_1 > s_2
       \quad \text{and}\quad
       s_1 - \frac{1}{p_1} > s_2 - \frac{1}{p_2}.
    \end{equation*}
    Then the embedding $\iota\colon S^{s_1}_{p_1,q_1}A_1(\Omega) \embeds S^{s_2}_{p_2,q_2}A_2(\Omega)$
    is compact and there exist constants $C_1,C_2>0$ and $u_1,u_2\ge0$ such that
    \begin{equation*}
        C_1 \cdot k^{-(s_1-s_2)}\cdot (\ln (e k))^{u_1}
        \le \en_k(\iota)
    \le C_2 \cdot k^{-(s_1-s_2)} \cdot (\ln (e k))^{u_2}
    \quad \text{for all $k\in \NN$.}
    \end{equation*}

[Proposition p:pseudo ergodic of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $\Phi$ be a locally square-integrable invariant random complex measure. Then
    \begin{equation}
        \frac{\hat\beta_\Phi(\{0\})}{(2\pi)^d} = \lim_{r\to\infty}\frac{\BV[\Phi(B_r)]}{\lambda_d(B_r)^2} = \BV\bigg[\lim_{r\to\infty}\frac{\Phi(B_r)}{\lambda_d(B_r)}\bigg],
    \end{equation}
    where the limit in the variance is taken with respect to the $L^2$-norm and is well defined. In particular, $\Phi$ is always $(-d)$-uniform, and $\Phi$ is beyond $(-d)$-uniform iff $\Phi$ is pseudo-ergodic.
\begin{proof}
    First, we see that by~(equation e: spectral covariance formula of the paper),
    \begin{align*}
        \frac{\BV[\Phi(B_r)]}{\lambda_d(B_r)^2} &=(2\pi)^{-d}\kappa_d^{-2} r^{-2d} \int |\hat\I_{B_r}(k)|^2 \, \hat\beta_\Phi(dk)\\
        &= (2\pi)^{-d}\kappa_d^{-2} \int |\hat\I_{B_1}(rk)|^2 \, \hat\beta_\Phi(dk)\\
        &= \frac{\hat\beta_\Phi(\{0\})}{(2\pi)^d} + (2\pi)^{-d}\kappa_d^{-2} \int_{\R^d\setminus \{0\}} |\hat\I_{B_1}(rk)|^2 \, \hat\beta_\Phi(dk),
    \end{align*}
    where $\kappa_d:=\lambda_d(B_1)$ is the volume of the unit ball.
    Further, we know that $\hat\beta_\Phi$ is translation-bounded (recall (equation e: translation-bounded of the paper)), and $\hat\I_{B_1}(k) \leq c_2(1+\|k\|)^{-\frac{d+1}{2}}$ as $\|k\|\to\infty$, for some $c_2>0$; see Examples~(ex: fourier smooth of the paper). Since translation-bounded measures behave just like the Lebesgue measure with respect to decreasing functions, one can apply the theorem of dominated convergence. Therefore, 
    \begin{equation*}
        (2\pi)^{-d}\kappa_d^{-2} \int_{\R^d\setminus \{0\}} |\hat\I_{B_1}(rk)|^2 \, \hat\beta_\Phi(dk) \xrightarrow{r\to\infty} 0,
    \end{equation*}
    which yields the first equality. The second equality follows from the $L^2$-ergodic theorem, whereby $\frac{\Phi(B_r)}{\lambda_d(B_r)}$ converges in $L^2$ as $r\to\infty$; see, e.g.,~[Kallenberg_2021].
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] For almost every $s$, given any maximizer $A_{t,s}$, it holds
	\begin{equation}
		\int_{A_{t,s}}\Delta u\,d x
		\leq d^{2-2/d}\omega_d^{2/d} s^{2-2/d}m_{ss}(t,s).
	\end{equation}

