[Theorem maintheorem of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] Fix $s>0$. Then in the limit $k\to\infty$ it holds that
\begin{align}
P_k\big(e^{-s/k}\big)=\frac{A(s)}{\sqrt{k\pi}}\, e^{-k\Psi (s)} (1+O(1/k))
\end{align}
with
\begin{align*}
A(s)=\sqrt{\frac{\log z_s}{2(z_s-s)}}, \quad \Psi(s)=\log z_s+\frac{1}{s} \operatorname{Li}_2(1-z_s),
\end{align*}
where
$z_s=e^{s+w_s}$ and $w_s=W_{-1}(-se^{-s})$ when $s\in(0,1)$ and $w_s=W_{0}(-se^{-s})$ when $s\ge 1$.
Moreover, for $t>0$,
\begin{align}
P_k\big(t; e^{-s/k}\big)=z_se^{t(1-z_s)} P_k\big(e^{-s/k}\big) \big(1+O(1/k)\big)\, .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:multiplier of arXiv:2608.30888, 'Three-term asymptotics for discrete\\ Hardy--Rellich constants in high dimension'] For every fixed $q\in\mathbb N$ and $\beta>0$, there are
$N^{\mathrm{mult}}_{\beta,q}\in\mathbb N$ and positive constants
$C_{\beta,q},c_\beta$ such that, for all
$N\geq N^{\mathrm{mult}}_{\beta,q}$,
\begin{equation}
 \sup_{\substack{g\in\operatorname{ran}P_{<q}\\ \left\lVert g\right\rVert_2=1}}
 \int_{\mathbb T^N}|1-\rho^{-\beta}|^2|g|^2\,d\mu
 \leq \frac{C_{\beta,q}}N+C_{\beta,q}e^{-c_{\beta}N}.
\end{equation}
Consequently, for the same dimensions, if $h=\rho^\beta$,
$\phi\in\mathscr F_{q,N}$ and $v=h\phi$,
then
\begin{equation}
 \norm{P_{<q}v}_2\leq C_{\beta,q}N^{-1/2}\left\lVert v\right\rVert_2.
\end{equation}

[Lemma 21 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] There is a constant $C<\infty$, depending only on
  $A,\varrho,\delta,C_0$, such that, for all $T_N\in\N_0$ and all
  sufficiently large $N$,
  \begin{equation}
    \prod_{u=s}^{t-1}(1\vee\alpha_{u,N})
    +
    \beta_{s,N}
    \prod_{u=s+1}^{t-1}(1\vee\alpha_{u,N})
    \leq
    \exp\{C(\log\log N)^2\}
  \end{equation}
  for all $0\leq s<t\leq T_N$.

[Lemma Half-space:WeakLowerEstimate of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Fix $\epsilon\in (0,1)$. There exist $T_0=T_0(\epsilon)>0$, $K=K(\epsilon, d)\in \mathbb{N}$, and $ \eta \in (0,1)$, such that
    \begin{equation}
        \inf_{x\in \mathbb{R}^d} \mathbf{P}_x[ \forall t>KT_0, \ \sup_{v\in \mathcal{N}_t} \{(X_t(v)-x-t\bar{\mathbf{v}})\cdot e\}\geq (1-\epsilon)\Tilde{c}(e)t]\geq \eta.
    \end{equation}

[Theo 21 of arXiv:2609.02261, 'Quantization and process'] Set, for $\theta>0$, $\alpha\in\N$ and $x\in\R$,

  $$ H_{\alpha}(x,\theta  ) =   e^{ \frac {\theta   } { 2 } |x |^2  } 
   \partial ^ {\alpha  }  e^{-  \theta  |x |^2  } .$$

 Then,

   \be \Vert  H_{\alpha} ( \cdot ,\theta  )\Vert _{L^1(\R^n)}
   \leq ( C \sqrt \theta )^{|\alpha | } \theta ^{-n/2} \sqrt {\alpha ! }. \ee (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2608.26803, 'On bubbling of Fueter maps'] Let $(M, g_M)$ be a closed oriented Riemannian $3$--manifold and let $(X, g_X, I_1, I_2, I_3)$ be a closed hyperk\"ahler manifold. Suppose that $(H_i)$ is a sequence of parameters in $\cP$ converging to $H \in \cP$. Let $(f_i)$ be a sequence of solutions of the $H_i$--perturbed Fueter equation satisfying a uniform energy bound. As explained above, after passing to a subsequence, we can extract a limiting $H$--Fueter map $f$ and a bubbling locus $\Gamma$. Assume that
  \begin{enumerate}[
  label=\textnormal{(\roman*)},
  topsep=0pt,
  partopsep=0pt
  ]
    \item $f$ extends smoothly across the whole of $M$; 
    \item $\Gamma$ contains a nontrivial Lipschitz arc $A$;
    \item for $\cH^1$-almost every $x \in A$, the point $f(x)$ lies in the image of a bubble at $x$.
  \end{enumerate} 
  Then $H \in \cP^\times$, where $\cP^\times$ is an infinite-codimensional\footnote{By this we mean that for any compact finite-dimensional smooth manifold $K$, the set $\{ \fp \in C^\infty(K, \cP) \, | \, \fp(t) \notin \cP^\times \; \text{ for all } t\in K \}$ is residual in $C^\infty(K, \cP)$ endowed with its standard Fréchet topology.} subset of $\cP$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 15 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\pi\in\Pi_{\mathrm{c}}(\bar{G}_2)$ and $\varphi\in\1_{n-2}\boxplus\pi$ be $s$-independent. Also, recall \optionA{$\P_v(\lambda;\varphi_v,f_v,f_{v,s})$}\optionB{$\P_v(s,\lambda;\varphi_v,f_v,\Phi_v)$} from \eqref{eq:main-RS-period-local} and $\lambda_{\mathrm{D}}(s)$ from \eqref{eq:def-lambda-discrete}. Then
		\begin{equation*}
			\optionA{
				\frac{\P_v(-\lambda_{\mathrm{D}}(s);\varphi_v,f_v,f_{v,s})}{L_v\left(\tfrac{n-1}{2}+\tfrac{n}{2}s,\pi_v\right)L_v\left(\tfrac{1}{2}+\tfrac{n}{2}s,\pi_v\right)}
			}
			\optionB{
				\frac{\P_v(s,-\lambda_{\mathrm{D}}(s);\varphi_v,\Phi_v)}{L_v\left(\tfrac{n-1}{2}+\tfrac{n}{2}s,\pi_v\right)L_v\left(\tfrac{1}{2}+\tfrac{n}{2}s,\pi_v\right)}
			}
		\end{equation*}
		can be analytically continued in $s\in\C$ as an entire function.

[Lemma 14 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $z\in\C^+$. With respect to the canonical basis of $\C^2$, the matrix representation of $\calJ(z)$ is
        \begin{align}
                \begin{pmatrix}\avg{\Pi_{21}\Sg\Pi_{12}}_N & \avg{\Pi_{22}^2}_N          \\
               \avg{(\Pi_{11}\Sg)^2}_N     & \avg{\Pi_{21}\Sg\Pi_{12}}_N\end{pmatrix}. 
        \end{align}
        If $\calI-\calJ$ is invertible on $\C^2$, then $\calB$ is invertible and
        \begin{align}
                \calB^{-1}=\calI+\calC_\Pi\calE(\calI-\calJ)^{-1}\calP. 
        \end{align}

