[Lemma lem identity for coefficient of density in eigenbasis of arXiv:2512.20338, 'Up-down chains and scaling limits: \\ application to permuton- and graphon-valued diffusio'] The following identity holds:
    \begin{equation*}
		\sum_{ k = i }^{ j }
			 \eta _{ i, k }
			 \eta^* _{ k, j }
    		=
				 \mathbbm 1 ( i = j )
    		,
    			\qquad
				0 \le i \le j
			.

    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Fully connected MLPs of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $d,D,L\in\mathbb{N}$, and let $d_0,d_1,\dots,d_L\in\mathbb{N}$ such that $d_0=d$ and $d_L=D$.
Let $\sigma\in \mathcal{C}(\mathbb{R})$ be an activation function.
A fully-connected MLP with depth $L$ and activation function $\sigma$ is a map $f:\mathbb{R}^d\to\mathbb{R}^D$ with iterative representation:
\begin{align*} 
    &X^{(0)} 
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}  X, \\
    &X^{(j+1)} 
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}  
    \sigma\bullet({\bf A}^{(j)} X^{(j)} + b^{(j)}) \qquad j=0,1,\dots,L-2,
    \qquad \\
    &f(X)
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}  
    {\bf A}^{(L-1)} X^{(L-1)} + b^{(L-1)},
\end{align*}
where $\bullet$ denotes component-wise application, ${\bf A}^{(j)}\in\mathbb{R}^{d_{j+1}\times d_j}$, and $b^{(j)}\in\mathbb{R}^{d_{j+1}}$.

[Lemma 7 of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] There exists a positive constant $C$ independent of $N$ such that
\begin{equation}
  |\beta-\beta_-|,  \ |p-p_-|, \ |q-q_-|, \ |\Dtil-\Dtil_-|, \ |v-v_-|\le \frac{C}{N}.
\end{equation}

[Lemma l4.6 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] Fix $K < \infty $. Consider any sequence $\{(\varphi^{k},{{\boldsymbol{ {\Pi}}}}^{k})\}_{k\in\mathbb{N}}\subset\mathscr{V}_{(x,\bar{X},\Theta,\nu^{\mathscr{L}_{\bar{X}}})}$ such that
	\begin{equation}
		\sup_{k\in \mathbb{N}}\int_{\mathbb{R}^d\times\mathbb{R}^m\times\mathscr{P}_2(\mathbb{R}^m)\times[0,T]}\big(|h|^2+|y|^4+M_4(\rho)\big){{\boldsymbol{ {\Pi}}}}^k(dhdyd\rho dt)\leq K.
	\end{equation}
	Then $\{(\varphi^{k},{{\boldsymbol{ {\Pi}}}}^{k})\}_{k\in\mathbb{N}}$ is pre-compact.

