[Defi def_stationaryIncr of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] A real valued field $(X_\eta)_{\eta\in\mathcal{M}}$ indexed by a homogeneous Riemannian manifold $\mathcal{M}$ is said to possess \emph{strong} stationary increments if for all $\zeta\in\mathcal{M}$ we have
    \begin{align*}
        (X_\eta - X_\zeta)_{\eta\in\mathcal{M}} {~\stackrel{(d)}{=}~} (X_{\psi_\zeta^{-1}(\eta)})_{\eta\in\mathcal{M}},
    \end{align*}
    where the equality is in finite dimensional distribution.

    A real valued field $(X_\eta)_{\eta\in\mathcal{M}}$ indexed by a Riemannian manifold $\mathcal{M}$ is said to possess \emph{weak} stationary increments if for all $\eta,\zeta\in\mathcal{M}$ the distribution of the increments is a function of the distance $d(\eta,\zeta)$, i.e.\
    \begin{align*}
        \expec{e^{i \lambda (X_\eta - X_\zeta)}} = f(\lambda, d(\eta,\zeta))
    \end{align*}
    for some function $f:\mathbb{R}\times\mathbb{R}_{\geq 0} \to \mathbb{C}$, any $\eta,\zeta\in\mathcal{M}$ and $\lambda\in\mathbb{R}$.

[Proposition 23 of arXiv:2604.09933, 'Explicit cutoff profiles for colored top-\texorpdfstring{$m$}{m}-to-random shuffles'] If \(M\ll U\), then
\begin{equation}
\|M-U\|_{\TV}
=\mathbb E_U\Bigl[\Bigl(\frac{M(X)}{U(X)}-1\Bigr)_+\Bigr].
\end{equation}

[Thm 4 of arXiv:2608.13374, 'Nearly Sharp Comparison Results for sliced and max-sliced Wasserstein distances'] Let $p \geq 1$ and $1 \leq k < d$, let $\mu \in \cP_p(\R^d)$, and let $\nu$ be a probability measure supported on a countable closed set $\cY$.
	If Condition~\ref{cond:voronoi} holds, then
	\begin{equation}
		W_p(\mu, \nu) \leq C \sqrt{\frac dk}\, K^{(k)}_{\mu,\nu}\, \SW_{p,k}(\mu, \nu)\,,
	\end{equation}
	where $C$ is a universal constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Averaged mass of the SHF on balls, upper bound) of arXiv:2608.13359, 'Fractional moments of the Stochastic Heat Flow and\\2D Directed Polymers'] There exist constants \(C,c>0\) such that, for any \(p \in (0,1)\), uniformly in \(t>0\), \(\th\in \R\) and \(r \in (0,\sqrt{t}]\), we have
  \begin{equation}

    \EE\bigl[\mathscr{Z}_{t}^{\th}(\cU_r)^{p}\bigr]
    \leq C\, \EE\bigl[\mathscr{Z}_{t}^{\th}(\cU_r)^{2}\bigr]^{c\, p (p-1)} \,.
  \end{equation}
  In fact, we  have a more explicit upper bound: there exist constants \(C',c'>0\) such that, for any \(p \in (0,1)\), uniformly in \(t>0\), \(\th\in \R\) and \(r \in (0,\sqrt{t}]\), we have
  \begin{equation}

    \EE\bigl[\mathscr{Z}_{t}^{\th}(\cU_r)^{p}\bigr]
    \leq C' \Bigl(1+ \log\Bigl(1+\frac{t}{r^2}\Bigr)\,\cV\bigl(t \,\e^{\th}\bigr) \Bigr)^{c'\, p (p-1)}\,,
  \end{equation}
  where \(\cV(T) \coloneqq \int_0^{\infty} \frac{T^s}{\Gamma(s+1)} \dd s\) is the so-called Volterra function (see~\eqref{eq:asymp-V} for its asymptotics as \(T\) goes to \(0\) or~\(\infty\)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] Fix $t \in \mathbb{R}$, $x,T > 0$ with $xT \geq 1$. If $h_T$ is as in (\ref{Eq.HeightFunction}), then for some universal $C_3 > 0$
\begin{equation}
\E[h_T(t, x)] \leq C_3 (Tx)^{3/2} e^{-\frac{4}{3} (Tx)^{3/2}}.
\end{equation}

