[Prop macroscopic coupling of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] {prevost2023phase}, [CT16]}]

    Let $\delta \in (0,1)$. For every $u>0$, $\rho \in (0,1)$ and $N \in \mathbb{N}$, there exists a coupling $\widetilde{\mathsf{P}}$ between the random walk under $\mathsf{P}$ and the random interlacements $\mathcal{I}^{u(1\pm\rho)}$ such that
    \begin{equation}

        \widetilde{\mathsf{P}}\Big(\mathcal{I}^{u(1-\rho)} \cap Q_\delta \subset X[0, uN^d] \cap \boldsymbol{Q}_\delta \subset \mathcal{I}^{u(1+\rho)} \cap Q_\delta \Big) \geq \;1-CN^{2d} \lceil uN^{d-2}\rceil \exp\Big(-c\rho\sqrt{uN^{d-2}}\Big)
    \end{equation}
    holds for some constants $c,C \in (0, \infty)$ depending only on $\delta$ and $d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: Slopes at P_3 of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let $$\ell<d, \ \ r=r_+(d,\ell)=1+\frac{d-1}{(1+\sqrt{\ell})^2},$$ then at $P_3$:
 \begin{equation}

\left|\begin{array}{l}
\sigma^\infty_3=\frac{1}{1+\sqrt{\ell}}\\
w^\infty_3=\frac{\sqrt{\ell}}{1+\sqrt{\ell}}
\end{array}\right.,\quad
\left|\begin{array}{l}
c^\infty_1=-\frac{2\sqrt{\ell}(d+\sqrt{\ell})}{(1+\sqrt{\ell})^3}\\
c^\infty_2=-\frac{2}{(1+\sqrt{\ell})^2}\\
c^\infty_3=-\frac{2\sqrt{\ell}(d+\sqrt{\ell})}{(1+\sqrt{\ell})^3}\\
c^\infty_4=-\frac{2}{(1+\sqrt{\ell})^2}
\end{array}\right.,\quad
\left|\begin{array}{l}
c^\infty_-=-1\\
c^\infty_+=\frac{\sqrt{\ell}(d+\sqrt{\ell})}{1+\sqrt{\ell}}\\
\lambda^\infty_+=0\\
\lambda^\infty_-=-\frac{2\left[\ell+(d+1)\sqrt{\ell}+1\right]}{(1+\sqrt{\ell})^3}.
\end{array}\right.
\end{equation}
Moreover,
\begin{equation}

\mu^\infty_+=(\partial_b\lambda_+)_{b=0}=\frac{2\sqrt{d-1}(\ell-d)}{(1+\sqrt{\ell})\ell^{\frac{1}{4}}(1+(d+1)\sqrt{\ell}+\ell)}<0.
\end{equation}

