[Lemma lem-Step 3 of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Let $C$ be the set defined in  (equation eqn-C_set of the paper). Let  $\overline{N}_{a_k}=\left( \overline{N}_{a_k}(t): t\geq 0\right)$ be the $\mathbb{R}$-valued process defined by
\begin{equation}
\overline{N}_{a_k}(t) \coloneqq \sum\limits_{s\leq t} a_k(\Delta \overline{M} (s)) - \int_0^t \int_{Y} a_k(F(s,\overline{u}(s),y))\, \nu (\mathrm{d} y) \, \mathrm{d}s,\;\; t\geq 0.
\end{equation}
Then for every pair  $(s,t)\in C^2_{+}$ 
\begin{equation}
\overline{\mathbb{E}} \bigl[  \overline{N}_{a_k}  (t)\lvert \mathscr{H}_{s} \bigr]= \overline{N}_{a_k}(s).
\end{equation}
Moreover,
\begin{align}
\sup_{k \ge 2}\;\;\sup_{t \in C  }\; \overline{\mathbb{E}} \left[ \lvert{\overline{N}_{a_k}(t)}\rvert^{2} \right] <\infty.
\end{align}

