[Proposition 10 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] There exists $\Omega_*\in\Borel(\Omega)$ such that
\begin{equation*}
 \Omega_*\subset\Omega_{\rm can}\cap\Omega_{\rm Fr}(\alpha),
 \qquad
 \Prob(\Omega_*)=1,
\end{equation*}
and the following assertions hold for every $b\in\Omega_*$.
\begin{enumerate}[label=\textnormal{(\roman*)}]
\item
\begin{equation}
 0<M_b(D)<\infty,\qquad M_b\perp dx,\qquad \supp M_b=D,\qquad
 M_b(\{x\})=0\quad(x\in D),

\end{equation}
and
\begin{equation*}
 M_b(B(x,r)\cap D)
 \le C_\alpha C_{{\rm Fr},\alpha}(b)r^\alpha,
 \qquad x\in D,\quad0<r\le1.
\end{equation*}
\item For every $\E$-polar set $N$ and every $u\in H_0^1(D)$,
\begin{equation}
 M_b(N)=0,\qquad
 \widetilde u=0\ M_b\text{-a.e.}
 \Longrightarrow u=0\quad\E\text{-q.e.}

\end{equation}
Thus $M_b$ is smooth and has full quasi-support.
\item The time-changed form
\begin{equation}
 V_b=\{u\in H_0^1(D):\widetilde u\in L^2(M_b)\},
 \qquad (\E,V_b)

\end{equation}
is densely defined and closed on $L^2(M_b)$.
\end{enumerate}

