[Corollary 17 (Stationary visible transitions under edge homogeneity) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Under the hypotheses of \cref{prop:edge-markov}, if the process is started in stationarity, then for every visible state $y\in\cS_m$ with last edge $e$ and every admissible appended edge $a$ from $e$,
\begin{equation}
q_{y,U_m(y,a)}^{(m)}(\theta)=\mu_\theta(a\mid e)
\end{equation}
for all $\theta$ near $\theta_0$.

[Definition def:nmlsi of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] For all $h\in\G_\ensuremath{\mathcal A}$, let $\ensuremath{\mathcal S}_h$ be the set of $f:\O\to {\ensuremath{\mathbb R}} _+$ such that $\mu_{J,h}[f] = 1$ and such that $f\mu_{J,h}\in\ensuremath{\mathcal P}(\O)$ has the same magnetization vector of $\mu_{J,h}$, that is \[m_\ensuremath{\mathcal A}(\mu_{J,h})=m_\ensuremath{\mathcal A}(f\mu_{J,h}).\]  The system is said to satisfy the {\em Nonlinear MLSI} with rate function \(\ensuremath{\mathcal I}:\G_\ensuremath{\mathcal A}\to {\ensuremath{\mathbb R}} _+\) if for all $h\in\G_\ensuremath{\mathcal A}$, 
\begin{equation}
    \mathcal{D}_{\mu_{J,h}}(f)  \ge \ensuremath{\mathcal I}(h)\,\mu_{J,h}\left[f\log f\right] 

\,,\qquad f\in\ensuremath{\mathcal S}_h 
\,.
\end{equation}

[Prop 11 (Deterministic profile joint factorial moments) of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] Suppose that $A_k = (a_k,b_k]$, $1 \le k \le m$, are finite and disjoint, and define $A \subset \R$ by
\begin{equation}
	A = ( \min\{a_1, \ldots, a_m\}, \max\{b_1, \ldots, b_m\}]. 
\end{equation}
Then for any $\eta \in \{0, K\}^\Z \subset \sX_K$ and $n_1, \ldots, n_m \in \N$, 
\begin{align*}
	0&\le  \prod_{k=1}^m ( \mu^\eta_{t/K}(A_k) )^{n_k} - \E_{\eta}\bigg[ \prod_{k=1}^m N_{t/K}^{(n_k)}(A_k^{n_k}) \bigg] \\
	&\le K^2 {n_1 + \cdots + n_m \choose 2} ( \mu_{t/K}^\eta(A) )^{n_1 + \cdots + n_m - 2} ( \kappa_t(A, \{\eta > 0\}) + \tau_t(A, \{\eta > 0\}) ). 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 25 of arXiv:2601.16377, '2601.16377'] We introduce a further decomposition of holomorphic functions in $\amsmathbb{M}_h$
\begin{equation}

\Phi_h^{\pm}(z) = \phi_h^{\pm}(z) + \frac{\phi_{h}^{\pm,[1]}(z)}{\N} + \frac{\phi_h^{\pm,[2]}(z)}{\N^2} + \frac{\mathbbm{f}_h^{\pm}(z)}{\N^3}.
\end{equation}
where
\begin{equation}

\begin{split}
\phi_h^{+,[1]}(z) & =  \frac{\phi_h^+(z)}{\hat{b}'_h - z} \cdot \bigg(\sum_{j = 1}^{\iota_h^+} \big(\rho_{h,j}^+ - \theta_{h,h}\big)\bigg), \\
 \phi_h^{-,[1]}(z) & =  \frac{\phi_h^-(z)}{z - \hat{a}_h'} \cdot  \bigg(\sum_{j = 1}^{\iota_h^-} \big(\rho_{h,j}^- - \theta_{h,h}\big)\bigg), \\
\phi_h^{+,[2]}(z) & = \phi_h^{+}(z) \cdot \Bigg[-\frac{\partial_z^3 U_h(z)}{12} + \frac{1}{(\hat{b}'_h - z)^2} \cdot \bigg( \sum_{1 \leq j_1 < j_2 < \iota_h^+} (\rho_{h,j_1}^{+} - \theta_{h,h})(\rho_{h,j_2}^+ - \theta_{h,h})\bigg)\Bigg], \\
\phi_h^{-,[2]}(z) & = \frac{\phi_h^-(z)}{(z - \hat{a}_h')^2} \cdot \bigg(\sum_{1 \leq j_1 < j_2 \leq \iota_h^-} (\rho_{h,j_1}^{-} - \theta_{h,h})(\rho_{h,j_2}^- - \theta_{h,h})\bigg),
\end{split}
\end{equation}
and the error $\mathbbm{f}_h^{\pm}(z)$ is defined to make \eqref{Phifinerdec} holds.

[Theorem 4 of arXiv:2603.25452, 'New approach to optimal control of delayed stochastic Volterra integral equations'] {\textbf{(Stochastic Maximum Principle: Adjoint Equation)}}\\
Assume $({\bf A1})$-$({\bf A3})$. Then there exists an adapted adjoint process $(p(t), q(.,t))$ satisfying the following advanced backward stochastic Volterra equation  
\begin{eqnarray}
p(t) = \frac{\partial g}{\partial x}\big(X(T)\big)+\int_t^T\mu(s,p(s+\delta),q(s,s+\delta))ds- \int_t^T q(t,s)\, dB(s)
\end{eqnarray}
where  
\begin{eqnarray*}
\mu(t,p(t+\delta),q(t,t+\delta))&=&\frac{\partial f}{\partial x}(t+\delta,X^{u}(t),u(t+\delta)) + \frac{\partial b}{\partial x}(t+\delta,t+\delta,X^{u}(t),u(t+\delta))p(t+\delta)\\
&&\frac{\partial \sigma}{\partial x}(t+\delta,t+\delta,X^{u}(t),u(t+\delta))p(t+\delta)\\
&&+\int_{t+\delta}^{T}\left(p(s) \frac{\partial^2 b}{\partial s \partial x}(s,t+\delta,X^{u}(s),u(s))ds\right.\\
&&\left.+q(s,t+\delta) \frac{\partial^2 \sigma}{\partial s \partial x}(s,t+\delta,X^{u}(s),u(s))\right)ds
\end{eqnarray*}

