[Cor equilibriumFreeEnergyCorrection of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Fix $\beta>0$, and let $\mu_\beta$ be an absolutely continuous thermal equilibrium measure satisfying
\begin{align}
 \mathop{}\!\mathrm d\mu_\beta=Z_{\mu_\beta}^{-1}e^{-\beta(V+h_{\mu_\beta})}\,\mathop{}\!\mathrm d x
\end{align}
and the hypotheses of (thm:partitionFunctionBound of the paper)(ii).  Then the canonical partition function satisfies the exact identity
\begin{align}
 Z_{N,\beta}
 =e^{-\beta N\mathcal F_{\beta,V}(\mu_\beta)}
 {\mathsf{K}}_{N,\beta}(\mu_\beta),
\end{align}
and consequently
\begin{align}
\log Z_{N,\beta}
={}&-\beta N\mathcal F_{\beta,V}(\mu_\beta)
+\beta I_{\mu_\beta}
-\frac12\log\mathrm{det}_2(\mathrm{Id}+\beta T_{\mu_\beta})
+O_{\beta,\mu_\beta}(r_{N,\mathsf{s}}),
\end{align}
where
\begin{align}
 r_{N,\mathsf{s}}
 \coloneqq
 \begin{cases}
 (\log(e+N))^{-\frac{\mathsf{d}-2\mathsf{s}}{2\mathsf{s}}},&0<\mathsf{s}<\mathsf{d}/2,\\[0.3em]
 (e+N)^{-c_{\log}(\beta,\mu_\beta)},&\mathsf{s}=0.
 \end{cases}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Bernstein-bound of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] Let $\mathcal{H}_m$ be a Euclidean class with exponent $V$ consisting of measurable permutation-symmetric functions. There exist absolute constants $c,C>0$ with the following properties. If $\max(V,t)\frac{m^2}{N}\leq c$, then for all $0<\varepsilon\leq 1$

    \begin{multline*}
    \sup_{h\in \mathcal H_m} \left| U_{N,m}(h) - \mathbb E U_{N,m}(h) \right| 
    \leq (1+\varepsilon)\mathbb E\sup_{h\in \mathcal H_m}\left|\frac{m}{N} \sum_{i=1}^N h^{(1)}\left(X_i\right)\right| 
    \\
    + \sqrt{2t m\sigma^2_{\mathcal H_m}}\sqrt{\frac{m}{N}} +C\left(\frac{1}{\varepsilon}+\sqrt{\frac{Vm^2\log(m)}{N}}\right)\frac{tm}{N}
    +\frac{CV}{N}\log^{3/2}(m)
\end{multline*}
with probability at least $1-2e^{-t}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 31 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let us define the deduction rules of $\sfu\RS$ as follows, where \emph{in the sequent $[\ttX]\vdash \Gamma$, every set term is a term in $\calL^u_{\ttX+\{\ttOmega\},\ttOmega}$.}
    \begin{center}
    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{}
        \RightLabel{$(\mathrm{Ax}) \quad (x\in y\in u)$}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ x\in y$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{}
        \RightLabel{$(\mathrm{Ax}) \quad (x\notin y\in u,\ x\in u)$}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ x\notin y$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ A$}
        \AxiomC{$[\ttX]\fCenter  \Gamma,\ B$}
        \RightLabel{$(\land)$}
        \BinaryInfC{$[\ttX]\fCenter \Gamma,\ A\land B$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ A$}
        \RightLabel{$(\lor)$}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ A\lor B$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ B$}
        \RightLabel{$(\lor)$}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ A\lor B$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ s\dotin t\land r=s$}
        \RightLabel{$(\in)$ \hspace{2em} ($|s|<|t|$, $r\in t$ not basic.)}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ r\in t$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$\cdots \quad [\ttX_s] \fCenter \Gamma,\ s\dotin t\to r\neq s \quad \cdots$ ($\heartsuit$)}
        \RightLabel{$(\notin)$}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ r\notin t$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ s\dotin t \land B(s)$}
        \RightLabel{$(\rmb\exists)$ \hspace{2em} ($|s|<|t|$)}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ \exists x\in t B(x)$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$ \cdots \quad [\ttX_s]\fCenter \Gamma,\ s\dotin t\to B(s) \quad \cdots$ ($\heartsuit$)}
        \RightLabel{$(\rmb\forall)$}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ \forall x\in t B(x)$}
    \end{mathprooftree}

    \vspace{1em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ A^{\ttL(u)_\ttOmega}$}
        \RightLabel{(Refl) \hspace{2em} ($A$ is a $\Sigma$-formula)}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ \exists z\in \ttL(u)_\ttOmega A^z$}
    \end{mathprooftree}
    \hspace{3em}
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ A$}
        \AxiomC{$[\ttX]\fCenter \Gamma,\ \lnot A$}
        \RightLabel{(Cut)}
        \BinaryInfC{$[\ttX]\fCenter \Gamma$}
    \end{mathprooftree}
    \vspace{1em}
    \end{center}
    Here $(\heartsuit)$ is the following conditions over $s$ and $\ttX_s$:
    \begin{itemize}
        \item The restriction of the $\ttX_s$-order to $\ttX_s\setminus\ttX$ coincides with the inherited order from $\bbN$.\footnote{Recall that template orders are finite linear orders whose underlying set is a finite initial segment of $\bbN$. This condition ensures uniqueness.  Once indiscernibles or variables are added, they must be added in increasing order of their $\bbN$-indices.} It is possible that $\ttX_s = \ttX$.
        \item $\ttX_s\vDash |s|<|t|$.
    \end{itemize}
    $(\heartsuit)$-labeled rules have hypotheses for each $s$ and $\ttX_s$ ($\alpha_s$ is from $s$) under the constraint $(\heartsuit)$. 
    Every tree formed by the given rule is a $\rmbeta$-preproof. We call a $\rmbeta$-preproof $\pi$

[Definition def:axioms of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] By a (strong) $\CLE_4$ metric, we mean a family of \textbf{deterministic} measurable mappings 
    \begin{equation*}
        D = \left\{D^U \colon \mathscr{LoopEns}(U) \to \BR^{U_\BQ \times U_\BQ},\quad  \Gamma_U \mapsto D_{\Gamma_U}^U\right\}_U,
    \end{equation*}
    where $U \subsetneq \BC$ ranges over all simply connected domains, such that the following conditions are satisfied whenever $U \subsetneq \BC$ is a deterministic simply connected domain and $\Gamma_U$ is a non-nested $\CLE_4$ in $U$:
    \begin{enumerate}[label=(\Roman*), ref=\Roman*]
        \item {\bfseries (Geodesic metric)} The mapping $D_{\Gamma_U}^U$ a.s.\ determines a metric on $\Gamma_U$ such that for each $\SCL_1, \SCL_2 \in \Gamma_U$, there exists an admissible path $P$ (which we shall refer to as a \emph{$D_{\Gamma_U}^U$-geodesic}) connecting $\SCL_1$ and $\SCL_2$ such that $D_{\Gamma_U}^U(\SCL_1, \SCL_2) = \len(P; D_{\Gamma_U}^U)$. Moreover, for all conformal mapping $\phi \colon U \to \BD$, the process $(\phi(\SCB_t(\SCL; D^U_{\Gamma_U})))_{t\ge 0}$ is c\`adl\`ag with respect to the Hausdorff distance, and, for all $t, s\ge 0$, if $\SCB_t(\SCL_1; D^U_{\Gamma_U}) \cap \SCB_s(\SCL_2; D^U_{\Gamma_U}) \neq \emptyset$, then $D^U_{\Gamma_U} (\SCL_1, \SCL_2) \le t+s$. The same is true with a deterministic connected arc (resp.\ two deterministic disjoint connected arcs) of $\partial U$ in place of $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
        \item {\bfseries (Locality)} Let $V \subseteq U$ be a deterministic simply connected subdomain. Then, a.s., for each connected component $V_j$ of $V^\star$, 
        \begin{equation*}
            D_{\Gamma_U}^U(\SCL_1, \SCL_2; V_j) = D_{\Gamma_U|_{V_j}}^{V_j}(\SCL_1, \SCL_2), \quad \forall \SCL_1, \SCL_2 \in \Gamma_U|_{V_j}.
        \end{equation*}
        \item {\bfseries (Conformal invariance)} Let $\phi \colon U \to \phi(U)$ be a deterministic conformal mapping. Then, a.s., 
        \begin{equation*}
            D_{\Gamma_U}^U(\SCL_1, \SCL_2) = D_{\phi(\Gamma_U)}^{\phi(U)}(\phi(\SCL_1), \phi(\SCL_2)), \quad \forall \SCL_1, \SCL_2 \in \Gamma_U. 
        \end{equation*}









        \item {\bfseries (Uniform exploration)} The collection $\{(\SCL, D_{\Gamma_U}^U(\SCL, \partial U))\}_{\SCL \in \Gamma_U}$ has the law of a uniform exploration of $\Gamma_U$ (cf.\ [CoInCLEExpl]).
    \end{enumerate}

[Definition of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] A stochastic process \(X:[0,T]\times \Omega \to \mathbb{R}^d\) is:
\begin{itemize}
	\item \emph{measurable} if it is \(\mathcal{B}([0,T])\otimes \mathcal{F}\)-measurable,
	\item \(\{\mathcal{F}_t\}_{t\in[0,T]}\)-adapted (or simply adapted, when the filtration is understood) if \(X(t,\cdot)\) is \(\mathcal{F}_t\)-measurable for every \(t\in [0,T]\),
	\item a process with \emph{continuous paths} if \(X(\cdot,\omega) \in \mathcal{C}_T^d\) for \(\mathbb{P}\)-almost every \(\omega \in \Omega\).
\end{itemize}
We define \(L^2_a([0,T]\times \Omega)\) as the class of processes \(X:[0,T]\times \Omega \to \mathbb{R}^d\) satisfying the following conditions:
\begin{enumerate}
	\item \(X\) is measurable,
	\item \(X\) is \(\{\mathcal{F}_t\}_{t\in[0,T]}\)-adapted,
	\item \(\mathbb{E}\int_{0}^{T} \vert X(t)\vert^2 dt < \infty\).
\end{enumerate}

