body:
[Lem apriori of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] There exist universal constants $C, c>0$ such that 
\begin{equation}

	\mathbf{P}[\|X^N\|>K] \le Cr e^{-cN},
\end{equation}
where $K:=(Cr)^{q_0}\|X_{\rm F}\|$. Moreover, we have
\begin{equation}

	| \mathbf{E}[ \mathop{\textnormal{tr}} h(X^N)]| \le 2\sobnorm{h}{0}{[-K,K]}
\end{equation}
and
\begin{equation}

	|\mathbf{E}[\mathop{\textnormal{tr}}  h(X^N) \cdot 1_{\{\|X^N\|>K \}} ] | 
	\leq C \sqrt{r} e^{-cN} \sobnorm{h}{0}{[-K, K]}
\end{equation}
for every $h \in \mathcal{P}_q$ with $q\le \frac{N}{q_0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] (\textbf{Lukasiewicz path, height process}) 
$(\textbf{a})\, $ Let $\fftree \ino \bbT$ be \emph{finite} and let $(u_l)_{0\leq l<\# t}$ be the vertices of $\fftree$ listed in 
increasing lexicographical order. By convenience we set $u_{\# t} \eqo \varnothing$ 
and we define $V(\fftree)\eqo (V_l(\fftree))_{0\leq l\leq  \# t}$ and $H(\fftree)\eqo (H_l(\fftree))_{0\leq l \leq  \# t}$ by setting $V_{0}(t)\eqo 0$, $H_{\# t} (t)\eqo 0$  and for all $0\leqo l \leko \# t$,
\begin{equation}

V_{l+1} (\fftree) \! = \! V_{l}(\fftree)  + k_{u_{l}} (\fftree)\! -\! 1 \quad \textrm{and} \quad H_l (\fftree) \! =\!  |u_{l}|. 
\end{equation}
$V(\fftree)$ is the \emph{Lukasiewicz path} of $\fftree$ and $H(\fftree)$ is the \emph{height process} of $\fftree$. We extend $H(t)$ continuously on $[0, \#t]$ as follows: for all integer $0\leqo l\leko \#t $ and all $s\ino [0,1]$, we set 
\begin{equation}

H_{l+s}(t)  = \left\{  \begin{array}{ll}
H_l (t)\! - \! \big(H_l (t) \! -\! |u_l \! \wedge \! u_{l+1}| \big) (2s\! \wedge \! 1)  + (2s\! -\! 1 )_+   &  \textrm{if $|u_{l+1}| \! \leq \! |u_l |$ } \\
H_l (t) + s   & \textrm{if  $|u_{l+1}| \geko | u_l | $.}
\end{array} \right.
\end{equation}
(see Remark \ref{bijecfor} $(\textbf{c})$ for a motivation).  

\smallskip

\noi
$(\textbf{b})\, $ Let $(t^{_{(k)}}_{^{\, }})_{k\in \bbN^*}$ be a forest of finite trees and $t\ino \bbT$ its associated tree as in Definition \ref{Ulamtree} $(\textbf{c})$. The Lukasiewicz path and the height process of the forest are denoted resp.~by $V(t)$ and $H(t)$ and they are obtained by concatenating the $V(t^{_{(k)}}_{^{\, }}) $ and $H(t^{_{(k)}}_{^{\, }}) $ in the following way. We set 
$\sigma_0\eqo 0$ and for all $k\ino \bbN^*$, we set $\sigma_k\! = \#  t^{_{(1)}}_{^{\, }}+ \ldots+  \# t^{_{(k)}}_{^{\, }}$. Moreover, for all $l \ino \lgeo \sigma_{k-1}, \sigma_k\lgeo \,$ and for all $ s\ino [ \sigma_{k-1}, \sigma_k] $, we set 
\begin{equation}

V_l (t)\eqo V_{l-\sigma_{k-1}} (t^{_{(k)}}_{^{\, }}) \! -\! (k\! -\! 1) \quad \textrm{and} \quad  H_s (t)\eqo H_{s-\sigma_{k-1}} (t^{_{(k)}}_{^{\, }}). \qquad \square
\end{equation}

[Definition 32 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For each $z,z' \in \mbR^d$, we define a linear map ${\chi}_{z; \eps, (\nu)}^{z'} : \langle \tcT_1 \rangle \to \mbR$ by setting for each $\mfl \in \mfL_+, \mft \in \mfL_-$
	\begin{align*}
		\chi_{z; \eps, (\nu)}^{z'} (\mcI_{(\mfl, \partial)}^k \sigma) &= k! \mcQ_{X^k} [ J^\mfl(z') H_{\sigma; \eps, (\nu)}^{z, g}(z') + \mathcal{N}_{\gamma_{\sigma}}^{\mfl} H_{\sigma; \eps, (\nu)}^{z, g}(z')] \\ & \qquad - \sum_{|l|_\mfs < |\mcI_{\mfl}^k \sigma|_\mfs} \frac{(z'-z)^l}{l!} D^{k+l} K_\mfl \ast \mcR H_{\sigma; \eps, (\nu)}^{z, g}(z),\\		
		\chi_{z; \eps, (\nu)}^{z'}(\Xi_{(\mft, \partial)}) &= \begin{cases}
			g_\eps \ast \rho^{\nu}(z') \qquad & \text{ if } \mft = \<b0>,
			\\
			g_{\eps^\alpha} \ast \rho^{\nu}(z') \qquad & \text{ if } \mft = \<p0>,
			\\
			\eps^{-1/2} \partial_x K \ast g_{\eps, \eps^\alpha} \ast \rho^{\nu}(z') \qquad & \text{ if } \mft = \<s(1)0>,
		\end{cases}
	\end{align*}
	and for $\eta \in \mcT_+$ defining
	\begin{align*}
		\chi_{z; \eps, (\nu)}^{z'}(\mcI_{(\mfl, \partial)}^k \sigma \cdot \eta) = \chi_{z; \eps, (\nu)}^{z'}(\mcI_{(\mfl, \partial)}^k \sigma) \cdot \gamma_{z'z}(\eta)
	\end{align*}
	where $\gamma_{z'z}$ is the element of $\mathcal{G}_+$ corresponding to $\tilde \Gamma_{z'z}^{\eps, (\nu)}$.

