body:
[Corollary cor:deg-equality of arXiv:2609.02845, 'Degeneracy bounds, stability, and a sharp gap for $B$-colorings'] Let $d$ and $\Delta$ be integers with $1\le d\le\Delta$.  The maximum
possible value of $q_B(G)$ among all finite simple $d$-degenerate
graphs $G$ with $\Delta(G)\le\Delta$ is $d\Delta$.  Moreover, for
every such graph $G$, the following are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $q_B(G)=d\Delta$;
\item $G$ contains a copy of $K_{d,\Delta}$;
\item $G$ has at least $d$ vertices of degree $\Delta$ with the same
      open neighborhood.
\end{enumerate}

[Lemma lmx1cn of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] Suppose $X^N, X_1^N, \ldots, X_N^N$ are  distributed according to Eq.\ (equation eq:PXiJ of the paper)  with  $\alpha$ random and $\Psi_N$ fixed for $N$ fixed as detailed in Def.\ (ralpha of the paper).   


  Recall  $r_N$ from Eq.\ (equation rn of the paper), and let  $m := \lim_{N\to \infty} \ensuremath{\mathds{E}\left[ (X)^2  \right]}$ when $X\sim L(\alpha_2)$.




Then  as $N\to \infty$, \bjarki{needs to be reworked given Eq (equation eq:PXiJ of the paper)}

\begin{enumerate}
\item in case $\alpha_2 > 2$    we have 
\begin{equation}
\begin{split}

Nr_N & \to \text{constant} +  \text{constant}\times   \overline{B}( \tfrac{ m }{ m + K}; \alpha_1, 2 - \alpha_1 );  \\

\end{split}
\end{equation}
\item in case $\alpha_2 = 2$,  
\begin{equation}
\begin{split}
 \frac{N}{\log N} r_N &  \to  \text{constant}  + \text{constant}\times \overline{B}(  \tfrac{ m }{ m + K}; \alpha_1, 2 - \alpha_1 ). \\

\end{split}
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:center_manifold of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume the same setting as in Theorem (thm:stable_manifold of the paper). Suppose that at least one Lyapunov exponent is zero, denoted by $\mu_{i_c}$. Therefore, $\mu_{i_c} = 0$, $\mu^{-} = \max\{\mu_{i} : \mu_{i} < 0\} = \mu_{i_c+1}$, and if $i_{c} > 1$, then $\mu^{+} = \min\{\mu_{i} : \mu_{i} > 0\} = \mu_{i_c-1}$; otherwise, we set $\mu^{+} := \infty$. We also set $C_\omega := H^{i_c}_{\omega}$.
			Then we can find a continuous cocycle $\tilde{\varphi}$ defined on $\{E_\omega\}_{\omega \in \Omega}$. That is, for every $p, q \in \mathbb{N}$ and $\omega \in \Omega$, the map $\tilde{\varphi}^p_{\omega}: E_\omega \to E_{\theta_{rp}\omega}$ is continuous, and we have $\tilde{\varphi}^{p+q}_{\omega} = \tilde{\varphi}^p_{\theta_{qr}\omega} \circ \tilde{\varphi}^q_{\omega}$. For this new cocycle, and for every $0 < \upsilon < \min\{\mu^{+}, -\mu^{-}\}$, on a set of full measure $\tilde{\Omega}$, which is $\theta_r$-invariant, the following items hold:
			\begin{itemize}
				\item[(i)] There exists a positive random variable $\rho^c:\Omega \to (0, \infty)$ such that
				\begin{align*}
					\liminf_{m \rightarrow \pm \infty} \frac{1}{m} \log \rho^c(\theta_{mr}\omega) \geq 0,
				\end{align*}
				and if $\|\xi_{\omega} - Y_\omega\|_{E_\omega} \leq \rho^c(\omega)$, then $\tilde{\varphi}^{1}_{\omega}(Y_\omega + \xi_\omega) = \varphi^{1}_{\omega}(Y_\omega + \xi_\omega)$.

				\item[(ii)] We can find a map
				\begin{align*}
					h_{\omega}: C_{\omega} \rightarrow \mathcal{M}^{c,\upsilon}_{\omega},
				\end{align*}
				such that this map is a homeomorphism, Lipschitz continuous, and differentiable at zero.

				\item[(iii)] The manifold $\mathcal{M}^{c,\upsilon}_{\omega}$ obtained from the previous item is a topological Banach manifold modeled on $C_\omega$.

				\item[(iv)] $\mathcal{M}^{c,\upsilon}_{\omega}$ is $\tilde{\varphi}$-invariant, i.e., for every $m \in \mathbb{N}_0$, $\tilde{\varphi}^{m}_{\omega}(\mathcal{M}^{c,\upsilon}_{\omega}) \subset \mathcal{M}^{c,\upsilon}_{\theta_{mr}\omega}$.

				\item[(v)] For every $\xi_\omega \in \mathcal{M}^{c,\upsilon}_{\omega}$, we can find a sequence $\{\xi_{\theta_{-mr}\omega}\}_{m \geq 1}$ such that if we set
				\begin{align*}
					\tilde{\varphi}^{jr}_{\omega}(\xi_\omega) \coloneqq \xi_{\theta_{jr}\omega}
				\end{align*}
				for $j \leq 0$, then
				\begin{align*}
					\tilde{\varphi}^p_{\theta_{qr}\omega}(\tilde{\varphi}^q_{\omega}(\xi_\omega)) = \tilde{\varphi}^{p+q}_{\omega}(\xi_\omega)
				\end{align*}
				for all $(p, q) \in \mathbb{N} \times \mathbb{Z}$, and
				\begin{align*}
					\sup_{j \in \mathbb{Z}} \exp(-\nu |j|) \| \tilde{\varphi}^{jr}_{\omega}(\xi_\omega) - Y_{\theta_{jr}\omega} \|_{E_{\theta_{rj}\omega}} < \infty.
				\end{align*}
			\end{itemize}

[Lemma lem:mainlemdis of arXiv:2410.23250, 'Strict inequalities for arm exponents in planar percolation'] Let $n\geq k \ge 1$ be such that $10k\le n$.  Writing  $F(\eta,\xi)$ for  the indicator that $(A_n(b),A_n(b))$ occurs disjointly in $(\eta,\xi)$, we have
\begin{equation}
  \forall t\in[t_k,t_{2k}]\quad
\sum_{x\in\mathbb H( \Lambda_{k,3k})} \mathbb{E}[D_xF(\omega,\omega_{1-t}) ]\gtrsim k^2\cdot \alpha_k\cdot \psi_n(1-t).
\end{equation}

