[Proposition of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Let the hypotheses of (thm:dragoverkill of the paper) hold for each $\ell$, with respect to $r=r_\ell, \lambda=\lambda_\ell,\delta=\delta_\ell,\sigma=\sigma_\ell$. If moreover, the field satisfies an analogous of the Weyl law, meaning that (eq:pseudoweyl of the paper) holds for some sequence $w_\ell$,
then
\begin{equation}
 \int_{M\times M}\|\sigma_\ell^{-2}j^{1,1}_{x,y}E_\ell\|^4_{\lambda_\ell^2 g} \dd x \dd y\le O(1)r_\ell^{n}
 +w_\ell \delta_\ell^2.
\end{equation}

[Proposition of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] For any $1\le i\le q$ and $1\le l\le q$, the codifference of $\{M_i(M_0(t))\}_{t\ge0}$ and $\{M_l(M_0(t))\}_{t\ge0}$ is given by
	{\small\begin{align*}
			\tau(M_i(M_0(t)),M_l(M_0(t)))&=
			\sum_{j_0=1}^{k_0}\mu_{j_0}t\Big(2-\exp\Big(\sum_{j_i=1}^{k_i}j_0\lambda_{ij_i}(e^{\omega j_i}-1)\Big)+\exp\Big(\sum_{j_l=1}^{k_l}j_0\lambda_{lj_l}(e^{-\omega j_l}-1)\Big)\Big)\\
			&\ \ -\sum_{j_0=1}^{k_0}\mu_{j_0}t\Big(1-\exp\Big(\sum_{j_i=1}^{k_i}j_0\lambda_{ij_i}(e^{\omega j_i}-1)+\sum_{j_l=1}^{k_l}j_0\lambda_{lj_l}(e^{-\omega j_l}-1)\Big)\Big)\mathbb{I}_{\{i\ne l\}}.
	\end{align*}}

