[Proposition prop:Buse_limits_1 of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix  $\xi \in (0,\xi_{\max}^c)$. Then, as $n \to \infty$, when $\mathbf x,\mathbf y \in \mathbb{Z}^2_{\mathrm{HS}}$, the following limit exists on a $\xi$-dependent event of probability one:
\begin{equation} 
W_\xi^c(\mathbf x,\mathbf y) := \lim_{n \to \infty} G\bigl((-\lfloor \xi n\rfloor,-n),\mathbf y\bigr) - G\bigl((-\lfloor \xi n\rfloor,-n),\mathbf x\bigr)
\end{equation}
Furthermore, the family of limits $W_\xi^c(\mathbf x,\mathbf y)$  has the following properties.  
\begin{enumerate} [label=(\roman*), font=\normalfont]
\item  For any fixed $\mathbf x \in \mathbb{Z}^2_{\mathrm{HS}}$, $(m,n) \mapsto W_\xi^c\bigl(\mathbf x,(m,n)\bigr)$ is an eternal solution.
\item  For each $t \in \mathbb{Z}$, the process 
    $\bigl(W_\xi^c((t,t),(k + t,t))\bigr)_{k \in \mathbb{N}}$ has law $\mu_{c,s}$, where $s = (X_c \circ T_c)^{-1}(\xi)$.
    \item  For $\zeta < \xi$, $t \in \mathbb{Z}$, and $k \in \mathbb{Z}_{\ge t}$, we have 
    \begin{align}
    &W_\xi^c\bigl((k,t),(k+1,t)\bigr) \le  W_\zeta^c\bigl((k,t)(k+1,t)\bigr),\qquad\text{and}  \\
    &W_\xi^c\bigl((k,t),(k,t+1)\bigr) \ge W_\zeta^c\bigl((k,t),(k,t+1)\bigr). 
    \end{align}
\end{enumerate}

[Theorem 8 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Consider Scenario~\eqref{Scenario_1}. Assume that \eqref{contraction_criterion_H_{0}} holds, or that $g\in\mathcal{C}^{(1)}(\mathcal{S})$ and \eqref{contraction_criterion_g} holds. Let
\begin{equation}
\alpha^{*}=\frac{\partial H_{0}}{\partial x}\Big|_{(x^{*},y^{*})}, \quad \beta^{*}=\frac{\partial H_{0}}{\partial y}\Big|_{(x^{*},y^{*})}, \quad \rho=\min\left\{1,1-q_{1}\alpha^{*}+q_{2}\beta^{*}\right\}, \quad z^{*}=\frac{(1-q_{1})x^{*}}{q_{1}},
