    \begin{equation}
        \hat{\mathsf{A}}_{\mathsf{T}}\Big( \overline{M}_{0}\big(Z,[\bP^1]\big) \Big)
        =
        \prod_{i=2}^5 \prod_{k=0}^{\deg \cL_i}
            \varsigma(\epsilon_i - k\epsilon_1)^{-1} \,,
    \end{equation}
    where we interpret $\prod_{k=0}^{d} a(k) \coloneqq \prod_{k=1}^{-d-1} a(-k)^{-1}$ whenever $d<0$.

