[Lemma Lem.StrongGP of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Assume the same notation as in Definition (DefSGP of the paper). Then, for any $\{ B_i \in \Omega(a, b, x_i , y_i) \}_{i = 1}^k$
\begin{equation}
{\bf 1}_{A} \cdot \mathbb{P}\left( L_{i + k_1-1}\llbracket a,b \rrbracket = B_{i} \mbox{ for $i \in \llbracket 1, k \rrbracket$} \, \vert  \mathcal{F}_{\mathrm{ext}} \right) = {\bf 1}_{A} \cdot \mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{a,b, \vec{x}, \vec{y}, f, g} \left( \cap_{i = 1}^k\{ Q_i = B_i \} \right),
\end{equation}
where $\mathcal{F}_{\mathrm{ext}} = \sigma(L_i(j): (i,j) \in \Sigma \times \llbracket T_0, T_1 \rrbracket \setminus \llbracket k_1, k_2 \rrbracket \times \llbracket a+1, b-1 \rrbracket)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:Qh of arXiv:2608.05262, 'The law of $(1+1)$D SOS with an area tilt in a wedge'] For independent random variables $\tilde \mathfrak X_k(j) \sim \mathbb P_{\theta_k(j)}$,  we denote by $\mathbb Q_\star(\cdot)$
the joint law of $\underline{\widetilde{\phi}}(\cdot):=(\widetilde{\phi}_1(\cdot),\ldots,\widetilde{\phi}_K(\cdot))$,
where 
\begin{equation}
    \widetilde \phi_k(i) = \sum_{j=-N}^{i-1} \big[ \tilde \mathfrak X_k(j) - \operatorname{sgn}(j) \big],    \qquad i \in [-N,N] \,,  \;\;
    1 \le k \le K \,,  
\end{equation} 
using $\mathbb E_\star(\cdot)$ for the associated expectation. 

Let $\mathbb Q_\mathfrak h$ be the 
probability measure whose density {\sc{\lowercase{wrt}}} $\mathbb Q_\star$ is 
proportional to $e^{-\mathfrak h {\mathcal W}^-} e^{-\mathfrak h {\mathcal W}^+}$, 
where
\begin{align}
{\mathcal W}^- &:= \sum_{k=1}^K \frac{\lambda^{k-1}}{N} 
\sum_{t=-N}^{a_k^-} \big(\widetilde \phi_k(t) \vee 0\big)
- \sum_{k=1}^K \frac{\lambda^{k-1}}{N} \{a_k\} \big(\widetilde \phi_k (a_k^-) \vee 0\big)
, \\
{\mathcal W}^+ &:= \sum_{k=1}^K \frac{\lambda^{k-1}}{N}
\sum_{t=a_k^+}^N (\widetilde \phi_k(t) \vee 0)
- \sum_{k=1}^K \frac{\lambda^{k-1}}{N} \{a_k\} \big(\widetilde \phi_k (a_k^+) \vee 0\big)
\,.

\end{align}

[Proposition stima_ctrl_alpha_caso_part of arXiv:2605.07832, 'A Bismut -Elworthy formula for BSDEs with degenerate noise'] Assume that condition (equation cond_traccia_gamma of the paper) is verified and let $T>0$ and $\alpha\in(0,1)$ be fixed. Hence, there exists a positive constant $c$, which only depends on $T$, such that
\begin{align}

\|\widetilde u_t\|_{L^2(0,T;U)}    
