[Theorem of arXiv:2606.27549, 'On Analytically Tractable Multidimensional Diffusions via Doob $h$-Transforms, with Resett'] The two-dimensional linear diffusion process $\widehat{\bf X}_t$  
    having infinitesimal moments (equation inf_mom_lin_bid of the paper) satisfies a SDE analogous to ((NEWsde_x_trasf of the paper)) with potential  
    \begin{align*}
        \widehat{U}({\bf x})&=-\left({\bf x}\cdot M \cdot {\bf x}^\top+{\bf m}\cdot{\bf x}^\top\right)+k \nonumber \\
        &=-\left(\frac{\theta_{11}}{2}x_1^2+\frac{\theta_{22}}{2}x_2^2+\theta_{12}x_1x_2+\theta_{13}x_1+\theta_{23}x_2\right)+k, 
        \qquad {\bf x}\in \mathbb{R}^2, \quad k\in \mathbb{R}.
    \end{align*}
    Hence, the critical point ${\bf x}^*$ of $\widehat{U}({\bf x})$ is given by:
    \begin{equation*}
        {\bf x}^*= \frac{1}{|M|} \left(  \theta_{12}\theta_{23}-\theta_{22}\theta_{13} , \; 
         \theta_{12}\theta_{13}-\theta_{11}\theta_{23}\right).
    \end{equation*}

[Proposition 11 of arXiv:2608.31008, 'Stability of gravitational instantons with a bounded Killing vector field'] If $\Delta u=a_nV+\lambda$, then
\begin{equation}
 k=\nabla^2u-\kappa\otimes\kappa
       +\left(b_nV+\frac{\lambda}{n}\right)g
\end{equation}
is TT and
\begin{equation}
 \cE_gk=(F\circ F)_0
       -\frac{n-4}{2(n-1)}(\nabla^2V)_0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:drift of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] Let $\mathsf M\in\mathbb R^{d_1\times d_1}$ satisfy $\rho(\mathsf M)<1$, let $\mathsf G\in\mathbb R^{d_1\times d_2}$, and let $F:\mathbb R^{d_1}\times\mathbb R^{d_2}\to\mathbb R^{d_1}$ be continuous with $B:=\sup_{z,\xi}\lvert F(z,\xi)\rvert<\infty$. Let $(\xi_k)_{k\ge1}$ be independent $\mathcal N(0,\mathrm{Id}_{d_2})$ variables, and consider the Markov chain on $\mathbb R^{d_1}$ defined by
\begin{equation}
 Z_{k+1}=\mathsf MZ_k+\mathsf G\xi_{k+1}+F(Z_k,\xi_{k+1}),
 \qquad k\ge0.
\end{equation}
Then the chain admits an invariant probability law $\pi$ satisfying
\begin{equation}
 \int\lvert z\rvert^2\,\pi(dz)
 \le8\lVert P\rVert^3\bigl(\operatorname{tr}(\mathsf G\mathsf G^\top)+B^2\bigr),
 \qquad
 P:=\sum_{j=0}^\infty(\mathsf M^\top)^j\mathsf M^j.
\end{equation}

