[Lemma lem:maximum principle of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] Assume that $\psi (t)=(\psi (t, n ))_{ n \in \mathbb N^M} $ is a sequence of functions that is such that for every $n \in \mathbb N^M $ the function $ t \mapsto f(t, n ) $ is continuously differentiable and satisfies 
        \begin{align} 
 \partial_s  \psi(s, n)   -  
   \mathcal L_r[ \psi (s) ](n) - \mathcal L_s [ \psi (s) ](n) \leq 0 , \quad s\geq 0,  \quad n \in \mathbb N^M   . 
\end{align}
Then we have that 
        \begin{align*}
       \sup_{ t \in [0, \infty ) } \sup_{ n \in \mathbb N^M } \psi (t, n ) \leq    \sup_{ n \in \mathbb N^M } \psi_0 ( n ). 
    \end{align*}
        Moreover if $\psi $ attains a maximum at time $ t= \overline t  $, then $ \psi $ is constant.  

          Assume that $\psi (t)=(\psi (t, n ))_{ n \in \mathbb N^M} $ is a sequence of functions that is such that for every $n \in \mathbb N^M $ the function $ t \mapsto f(t, n ) $ is continuously differentiable and satisfies 
        \begin{align} 
 \partial_s  \psi(s, n)   -  
   \mathcal L_r[ \psi (s) ](n) - \mathcal L_s [ \psi (s) ](n) \geq 0 , \quad s\geq 0  \quad  n \in \mathbb N^M   . 
\end{align}
Then we have that 
        \begin{align*}
       \inf_{ t \in [0, \infty ) } \inf_{ n \in \mathbb N^M } \psi (t, n ) \geq    \inf_{ n \in \mathbb N^M }  \psi_0 ( n ). 
    \end{align*}
        Moreover if $\psi$ attains a minimum at time $ t= \overline t  $, then $ \psi $ is constant.

[Corollary 53 of arXiv:2609.03403, 'Hyperpositive functions, sector bounded functions and a trace formula'] Let $F\in\mathcal{SB}_T$. Then, in the operator norm,
      \begin{equation}

\|F(z)\|\le\frac{\|T^{1/2}\|}{\|(T+T^{-1})^{1/2}\|-\|T^{-1/2}\|},\quad z\in\mathbb C_r.
        \end{equation}

[Proposition prop:DKS-propositions of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] The following statements hold for any finite $n$ and sufficiently large $\beta$. Let $A=(A_1,A_2), B=(B_1,B_2)$ be any two points, and assume that $A$ is to the left of $B$. Let $\theta_{A, B}$, $M_{A, B}$, $\ell_{A, B}$ denote the angle, horizontal length, and length of the line segment $\overline{AB}$ respectively, and assume that $|\theta_{A, B}|$ is bounded away from $\pi/2$. Let $\ensuremath{\mathcal S} = \ensuremath{\mathcal S}(A, B)$ denote the infinite vertical strip with $A, B$ on its boundary, and let $W \supset \ensuremath{\mathcal S}$.
		\begin{enumerate}[(i)]
			\item [DKS92] Let $\overline{h}_t(\gamma)$ be the maximum height of $\gamma$ above $\overline{AB}$ at the line $x = A_1 + t$. There exist constants $C, c> 0$ such that for any $A, B$ as above,
			\begin{equation*}
				{\widehat Z}^n_{W, \mathbb Z^2}(A, B \mid \overline{h}_t(\gamma) \geq j) \leq C\sqrt{M_{A, B}}e^{-c(j \wedge j^2/t)}{\widehat Z}^n_{W, \mathbb Z^2}(A, B)\,.
			\end{equation*}
			Let $\ell_t(\gamma)$ be the number of bonds in $\gamma$ to the left of $x = A_1 + t$. For some constant $K(\theta_{A, B})$, we have
			\begin{equation*}
				{\widehat Z}^n_{W, \mathbb Z^2}(A, B \mid \ell_t(\gamma) \geq j + K(\theta_{A, B})t) \leq C\sqrt{M_{A, B}}e^{-c(j \wedge j^2/t)}{\widehat Z}^n_{W, \mathbb Z^2}(A, B)\,.
			\end{equation*}

			\item [DKS92] There exists $C > 0$ such that for any $A, B$ as above,
			\begin{align*}
				&\left|\log {\widehat Z}^n_{\mathbb Z^2, \mathbb Z^2}(A, B) + \tau_{\beta, n}\ell_{A, B} + \tfrac12\log M_{A, B}\right| \leq C\,, \mbox{ and }\\
				&\left|\log {\widehat Z}^n_{\ensuremath{\mathcal S}, \mathbb Z^2}(A, B) + \tau_{\beta, n}\ell_{A, B} + \tfrac12\log M_{A, B}\right| \leq C\,.
			\end{align*} 

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 18 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Let $k \in \mathbb{N}$ and $\mathfrak{W}_k$ denote the set of signatures of length $k$, i.e.
\begin{equation}
\mathfrak{W}_k = \{ \vec{x} = (x_1, \dots, x_k) \in \mathbb{Z}^k: x_1 \geq  x_2 \geq  \cdots \geq  x_k \}.
\end{equation}
Let $\vec{x}, \vec{y} \in \mathfrak{W}_k$, $T_0, T_1 \in \mathbb{Z}$ with $T_0 < T_1$, and $f: \llbracket T_0, T_1 \rrbracket \rightarrow (-\infty, \infty]$ and $g: \llbracket T_0, T_1 \rrbracket \rightarrow [-\infty, \infty)$ be two functions. With the above data we define the {\em $(f,g)$-interlacing geometric line ensemble on the interval $\llbracket T_0, T_1 \rrbracket$ with entrance data $\vec{x}$ and exit data $\vec{y}$} to be the $\Sigma$-indexed geometric line ensemble $\mathfrak{Q}$ with $\Sigma = \llbracket 1, k\rrbracket$ on $\llbracket T_0, T_1 \rrbracket$ and with the law of $\mathfrak{Q}$ equal to $\mathbb{P}^{T_0,T_1, \vec{x},\vec{y}}_{\operatorname{Geom}}$ (the law of $k$ independent uniform increasing paths $\{B_i: \llbracket T_0, T_1 \rrbracket \rightarrow \mathbb{Z} \}_{i = 1}^k$ from $B_i(T_0) = x_i$ to $B_i(T_1) = y_i$), conditioned on 
\begin{equation}
\begin{split}
\ice  = &\left\{ B_0 \succeq B_1 \succeq B_2 \succeq \cdots \succeq B_{k+1} \right\},
\end{split}
\end{equation}
with the convention that $B_0(x) = f(x)$ and $B_{k+1}(x) = g(x)$.

The above definition is well-posed if there exist $B_i \in \Omega(T_0,T_1,x_i,y_i)$ for $i \in \llbracket 1, k \rrbracket$ that satisfy the conditions in $\ice$. We denote by $\Omega_{\ice}(T_0, T_1, \vec{x}, \vec{y}, f,g)$ the set of collections of $k$ increasing paths that satisfy the conditions in $\ice$ and then the distribution of $\mathfrak{Q}$ is simply the uniform measure on $\Omega_{\ice}(T_0, T_1, \vec{x}, \vec{y}, f,g)$. We denote the probability distribution of $\mathfrak{Q}$ as $\mathbb{P}_{\ice, \operatorname{Geom}}^{T_0,T_1, \vec{x}, \vec{y}, f, g}$ and write $\mathbb{E}_{\ice, \operatorname{Geom}}^{T_0, T_1, \vec{x}, \vec{y}, f, g}$ for the expectation with respect to this measure. If $f=+\infty$ and $g=-\infty$, we drop them from the notation and simply write $\Omega_{\ice}(T_0,T_1,\vec{x},\vec{y})$, $\mathbb{P}^{T_0, T_1, \vec{x},\vec{y}}_{\ice, \operatorname{Geom}}$, and $\mathbb{E}^{T_0, T_1, \vec{x},\vec{y}}_{\ice, \operatorname{Geom}}$.

[Proposition prop::BPZ_free of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Suppose that $-\infty<x_1<\cdots<x_{2n}<\infty$ and let $x_1^a<\cdots<x_{2n}^a$ be $2n$ vertices in $a\mathbb{Z}$ satisfy $\lim_{a\to 0}x_j^a=x_j$ for $1\leq j\leq 2n$. Then we have, 
	\begin{equation} 
\begin{split}
			\langle \sigma_{x_1}\cdots\sigma_{x_{2N}}\rangle_{\mathbb{H}}^{\mathbf{f}}:=&\lim_{a\to 0} a^{-2n}\times \mathbb{E}_{\mathbb{H}}^{(a,\mathbf{f})}\left[\sigma_{x_1^a}\cdots \sigma_{x_{2n}^a}\right]\\
	=&C^n_4\mathrm{Pf}\left[\frac{1}{x_k-x_j}\right]_{j,k=1}^{2n}=C^n_4\sum_{\varpi\in\Pi_n}\mathrm{sgn}(\varpi)\prod_{\{c,d\}\in \varpi} \frac{1}{x_d-x_c}, 
\end{split}
	\end{equation}
	where $C_4$ is the constant in~(equation eqn::FK_bd_two_three of the paper). As a consequence, for each $j\in \{1,2,\ldots,2n\}$, the function $\langle \sigma_{x_1}\ldots \sigma_{x_{2N}}\rangle_{\mathbb{H}}^{\mathbf{f}}$ defined by~(equation eqn::Pfa_free of the paper) is annihilated by
	\begin{equation} 
	\frac{3}{2}\partial^2_{j}+\sum_{k\neq j} \frac{2}{x_k-x_j}\partial_k-\frac{1}{(x_k-x_j)^2}.
\end{equation}

[Theorem thm: main of arXiv:2509.20779, 'Diffusive Scaling limit of stochastic Box-Ball systems and P\MakeLowercase{ush}TASEP'] Let $R= [R_1, R_2, \dotsm R_k]$ be a $d \times k$ weak-$\mathcal S$ matrix with respect to a function $f$ such that
	\begin{itemize}
		\item [(1)] $f(j) \not = \emptyset$ for all $j$,
		\item [(2)] for each $1 \le i\le m$, $f(j) = \{i\}$ if and only if $j = i$.
	\end{itemize}
	For each positive integer $n$, let $W^n, X^n \in C([0,\infty), \mathbb{R}^d)$ and $Y^n \in C([0,\infty),\mathbb{R}^k)$ be continuous processes defined on some probability space $(\Omega^n, \mathcal F^n, P^n)$ such that 
	\begin{itemize}
		\item [(i)] $W^n = X^n + RY^n$, 
		\item [(ii)] $W^n(t) \in S$ for all $t \ge 0$, $P^n$-a.s.,
		\item [(iii)] $X^n$ converges in distribution as $n \to \infty$ to a $d$-dimensional Brownian motion with drift $\mathbf 0$, covariance matrix $\Sigma$ and initial distribution $\delta_{\mathbf0}$, 
		\item [(iv)] there are constants $\delta^n \ge 0$ such that $\delta^n \to 0$ as $n \to \infty$ and $P^n$-a.s. for $j = 1,2, \dots, k$, 
		\begin{itemize}
			\item [(a)] $Y_j^n(0) = 0$,
			\item [(b)] $Y_j^n$ is non-decreasing, 
			\item [(c)] $\int^t_0 \mathbf{1}_{F^{\delta^n}_{f(j)}}(W^n(s)) dY_j^n(s) = Y_j^n(t)$ for all $t \ge 0$. Here, $F^\delta_i:=\{x \in S: 0 \le n_i \cdot x-b_i\le \delta\}$ and $F_I^\delta:=\cap_{i \in I}F_i^\delta$ for $\delta>0$, $i \in \{1,2,\dots, m\}$, $\emptyset \neq I \subseteq \{1,2,\dots,m\}$.
		\end{itemize}
		\item [(v)] For each (weak) limit point $(W',X',Y')$ of $\{(W^n, X^n,Y^n)\}_{n=1}^\infty$, $X'$ is a $\mathcal F'_t$-martingale, where $\mathcal F'_t = \sigma\{(W',X',Y')(s): 0\le s\le t\}$ for all $t \ge 0$.
	\end{itemize}
	Then $(W^n, X^n, Y^n) \Rightarrow (W,X,Y)$ as $n\rightarrow\infty$ where $Y_j \equiv 0$ a.s. for each $j>m$ and $W$ is an SRBM associated with $(S; \mathbf 0, \Sigma, \hat R, \delta_0)$ with (standard) Skorokhod decomposition $W = X + \hat R\hat Y$. Here, $\hat R := [R_1, R_2, \dots, R_m]$ and $\hat Y = (Y_1, Y_2, \dots, Y_m)^\top$. (Proof in the paper; no proof environment follows the statement in the TeX.)

