[Theorem thm:soft_ogp0 of arXiv:2412.03511, 'Near-optimal shattering in the Ising pure $p$-spin and \\ rarity of solutions returned by '] For $\bar{\beta}_{d} < \beta < \beta_c$, there exists $0<\underline{q}<\overline{q} <1$ depending on $\beta$ and $\xi$ such that  
  \begin{equation}
     \operatorname{\mathbb{E}} \mu_{\beta,\bm{G}}\Big(\Big\{\bm{\sigma} : \exists\, \bm{\sigma}' \,\textup{s.t.}\, H_N(\bm{\sigma}') \ge \beta \xi(1) N ,\,  \underline{q} \le \langle \bm{\sigma},\bm{\sigma}'\rangle/N  \le \overline{q} \Big\}\Big) \le e^{-cN}\,, 
\end{equation}
where $c = c(\beta,\xi)> 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Them mimicking of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Let  $X=(X_t)_{t \in \mathbb{R}}$ be a Gaussian process with  continuous covariance function $K$ and positive variance function. Assume $\alpha^K$, the instantaneous decay rate of $K$, is well-defined and continuous. 		
		\begin{enumerate}
			\item \emph{Existence:} There exists a Gaussian process $Y =(Y_t)_{t \in \mathbb{R}}$ with covariance $K'$ satisfying:
			\begin{itemize}
				\leftskip=0.3in
				\item[(1)] For every $t \in \mathbb{R}$, $\text{Law}(X_t) = \text{Law}(Y_t)$;
				\item[(2)] $\alpha^{K'} = \alpha^{K}$;
				\item[(3)] $(Y_t)_{t \in \mathbb{R}}$ is a Markov process.
			\end{itemize}
			Moreover, for every $s<t \in \mathbb{R}^2$,
			\begin{equation}
				\sup_{v \in  [s,t] } \left| \alpha^K(v) - L_v^{K'}(h) \right| \xrightarrow[h \to 0^+]{} 0.
			\end{equation} 

			If a Gaussian process $Y$ satisfies $(1),(2)$ and $(3)$, we allow ourselves to say that $Y$ is a \emph{mimicking process} of $X.$
			\item \emph{Uniqueness in law:} Every mimicking process of $X$ with covariance function $K' :\mathbb{R}^2 \to \mathbb{R}$ has the same mean function as $(X_t)_{t \in \mathbb{R}}$ and, for every $s<t \in \mathbb{R}^2$,
			\begin{equation}
				 K'(s,t) = K(s,s)^{1/2}K(t,t)^{1/2} \exp\left(-\int_s^t \alpha^K(u) du\right).
			\end{equation}
			\item \emph{Underlying dynamic of the mimicking process: } Assume $m : t \mapsto \mathbb{E}(X_t)$ and $\sigma : t \mapsto K(t,t)^{1/2}$ are continuously differentiable. Then strong existence and strong uniqueness \footnote{Strong uniqueness is meant in the sense of [karatzas_brownian_1988]. By strong existence, we mean existence of a strong solution for any given brownian motion and independent condition. We refer to [karatzas_brownian_1988] for the definition of a strong solution.} hold for the  SDE 
			\begin{equation}
				\begin{cases*}
					Z_t =\left[m'(t) +(\sigma'(t)-\alpha^K(t))Z_t\right]dt + \sigma(t)\sqrt{2 \alpha^K(t)}dB_t \\
					Z_0 \sim \mathcal{N}(0,1)
				\end{cases*}
			\end{equation}

			\begin{comment}
				Moreover, fix a probability space $(\tilde{\Omega}, \ti{\mathcal{F}}, \ti{\mathbb{P}})$ equipped with a standard Brownian motion $(B_t)_{t \geq 0}$ and a random variable $Z \sim \mathcal{N}(0,1)$ which is independent from $(B_t)_{t \geq 0}$. Then, there exists a strong solution to the SDE (equation eq:SDE_complet of the paper) relatively to the standard Brownian motion $(B_t)_{t \geq 0}$ and the initial condition $Z.$
			\end{comment}
			 Moreover, the\footnote{Since strong uniqueness holds, this process is unique up to indistinguishability.} law of its solution is the law of the mimicking process of $X$ (restricted to $\mathbb{R}_+$).
			\item \emph{The mimicking process is a Markov transform (under a reinforced condition):} Assume (equation eq:correlation of the paper) is verified, \textnormal{i.e.} ,\ $$\sup_{v \in [s,t]} \left| \alpha^K(v) - \frac{1}{h}\left(1 - \frac{K(v,v+h)}{\sqrt{K(v,v)}\sqrt{K(v+h,v+h)}} \right) \right| \xrightarrow[h \to 0^+]{} 0,$$
			for every $s<t \in \mathbb{R}^2.$ Let  $(R_n)_{n \geq 1} \in \mathcal{A}$ be an admissible sequence and $Y$ be a mimicking process. For every $n \geq 1$, we denote by $X^{R_n}$ the transformation of $X$ made Markov at times $R_n$. Then $(X^{R_n})_{n\geq 1}$ and $Y$ almost surely have continuous paths and $X^{R_n}$ converges weakly to $Y$ on compact sets\footnote{This means that, for every $a<b \in \mathbb{R}^2$, \ $\text{Law}\left((X^{R_n}_t)_{t \in [a,b]}\right) \xrightarrow[n \to + \infty]{w}  \text{Law}\left((Y_t)_{t \in [a,b]} \right).$}. In particular, the strong global Markov transform of $X$ is the mimicking process of $X$.
		\end{enumerate}

[Definition 16 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix a set $\Sigma = \llbracket 1, N \rrbracket$ with $N \in \mathbb{N} \cup \{\infty\}$, and an interval $\Lambda= [0,T]$ with $T \in (0,\infty)$ or $\Lambda = [0,T)$ with $T \in (0, \infty]$. A $\Sigma$-indexed line ensemble $\mathcal{L}$ on $\Lambda$ satisfies the {\em pinned half-space Brownian Gibbs property} if its restriction to $\Lambda\cap(0,\infty)$ is non-intersecting and for any $b \in \Lambda \cap (0, \infty)$, any $k\in\llbracket 1,\lfloor(N-1)/2\rfloor\rrbracket$, and any bounded Borel-measurable function $F: C(\llbracket 1,2k\rrbracket \times [0,b]) \rightarrow \mathbb{R}$,
\begin{equation}
\mathbb{E} \left[ F\left(\mathcal{L}|_{\llbracket 1,2k\rrbracket \times [0,b]} \right) \,\big|\, \mathcal{F}_{\mathrm{ext}} (\llbracket 1,2k\rrbracket \times [0,b))  \right] =\mathbb{E}_{\mathrm{pin}}^{b,\vec{y}, g} \bigl[ F( \mathcal{Q} ) \bigr],\quad \mathbb{P}\text{-almost surely.} 
\end{equation}
Here, $g = \mathcal{L}_{2k + 1}[0,b]$, $\vec{y}=(\mathcal{L}_1(b), \dots, \mathcal{L}_{2k}(b))\in\weyl_{2k}$, $\mathcal{Q}$ has law $\mathbb{P}_{\mathrm{pin}}^{b,\vec{y}, g}$, and
\[\mathcal{F}_{\mathrm{ext}} (\llbracket 1,2k\rrbracket \times [0,b)) := \sigma \left\{ \mathcal{L}_i(s): (i,s) \in  \Sigma \times \Lambda \setminus \llbracket 1,2k\rrbracket \times [0,b) \right\}.
\]

[Lemma lem:finite-bias of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] Fix \(q\ge2\) and \(0<\rho<1/2\). There exist constants \(c=c(q,\rho)>0\) and \(C=C(q,\rho)<\infty\) such that the following holds.	
			Let \(Q\) be a real polynomial of degree at most $q$ in independent fair Bernoulli variables \(Z_{j,k}\), \(1\le j\le q\), \(1\le k\le L\), written in multilinear form. Let \(A(k_1,\ldots,k_q)\) be the coefficient of $Z_{1,k_1}\cdots Z_{q,k_q}.$
			Assume the diagonal estimate
			\begin{equation}
			\left\|A(k,k,\ldots,k)\right\|\geq \rho \qquad(1\le k\le L).
			\end{equation}
			We define the future mass
			\begin{equation}
				m := \sum_{\substack{1\le k_1,\ldots,k_q\le L\\
					(k_1,\ldots,k_{q-1})\succ(k_q,\ldots,k_q)}}
				|A(k_1,\ldots,k_q)|.
			\end{equation}
			Then,
			\begin{equation}
				\left|\mathbb E e(Q(Z))\right|
				\le
				C\bigl(e^{-cL}+m \bigr)^{2^{-q}}.
			\end{equation}

