[Proposition prop:positive-generator of arXiv:2607.18070, 'The Brownian loop-catcher'] For every finite \(E\subset V\) and every \(0\le\lambda\le1\), the matrix
\(\mathcal A_\lambda^E\) satisfies:
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.2em]
\item \(\mathcal A_\lambda^E(U,S)=0\) unless \(S\subset U\);
\item each column sum is zero;
\item if \(S\subsetneq U\), then \(\mathcal A_\lambda^E(U,S)\ge0\);
\item if \(S\ne\varnothing\), \(S\subsetneq U\), and some connected component
of \(G_E^{\rm und}[U]\) is disjoint from \(S\), then
\(\mathcal A_\lambda^E(U,S)=0\).
\end{enumerate}

[Definition 18 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] Let $1<\alpha<2$. A $[0,\infty)$-valued Markov process is called a $\alpha$-stable continuous-state branching process ($\alpha$-stable CSBP) with scaling constant $c_0>0$ if it has transition semigroup $(Q_t)_{t\geq 0}$ defined by
	\begin{equation}
		\int_0^\infty e^{-\lambda y}Q_t(x,\d y)=e^{-xu^\lambda(t)}, \quad \lambda\geq 0,x\geq 0,
	\end{equation}
	where $t\mapsto u^\lambda(t)$ is the unique positive solution of 
	\begin{equation}
		\frac{\d u^\lambda(t)}{\d t}=-c_0[u^\lambda(t)]^\alpha,\quad u^\lambda(0)=\lambda.
	\end{equation}

[Theorem 7 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to [-1,1]$, and $p\in [1,2)$,
\begin{equation}
    \max_{J\subseteq[n]:|J|=k}\left\|\Dop_J f\right\|_{\Leb^p}^{p} \geq C^{\text{\rm\ref{thm:high-order-partial-isoper-Boolean}}}(p)^k\, \frac{\Wop^{\geq k}(f)}{\binom{n}{k}} \left[1+ \frac{1}{2k} \ln\left(\frac{\binom{n}{k}}{\Wop^{\geq k}(f)}\right)\right]^k,
\end{equation}
where $C^{\text{\rm\ref{thm:high-order-partial-isoper-Boolean}}}(p) = \left(1+\frac{1}{\upe(2-p)}\right)^{-1} \gtrsim 2-p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Kirchhoff's formula for infinite graphs) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Suppose $(G, \weight)$ is an infinite connected weighted graph and let $\bP^\weight_G$ be the law of the (wired) USF, then
	\begin{equation*}
	    \bP^\weight_G(e \in \cT) = \weight(e) \effR{G, \weight}{e^-}{e^+},
	\end{equation*}
    where
    \begin{equation} 
        \effR{G, \weight}{e^-}{e^+} = \left\{ \Vert\theta\Vert^2_r \, : \, \theta \text{ is a unit flow from } e^- \text{ to } e^+ \right\}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $\sigma \in \{\emptyset, -,+\}$. The $\varphi^4_3$ amplitude on $M^\sigma$ is the map
\begin{equation}
	\mathcal A_\infty^\sigma:C^\infty(M_\sigma)\times \mathcal C^{-1/2-\kappa}(\mathbb T^2) \times \mathcal C^{-1/2-\kappa}(\mathbb T^2) \rightarrow \mathbb R
\end{equation}
defined for every $f \in C^\infty(M_\sigma)$ and almost surely for every $\varphi_-,\varphi_+$ independent admissible boundary conditions by
\begin{equation}
	\mathcal A^\sigma_\infty(f \mid \varphi_-,\varphi_+) := \boldsymbol{\mathcal A}^\sigma_\infty (f, \Xi^\partial_\infty(\varphi_-,\varphi_+)),
\end{equation}
where the lifted amplitude $\boldsymbol{\mathcal A}^\sigma_\infty$ is constructed in Theorem (thm: bulk of the paper) and the limiting enhanced boundary field is constructed in Theorem (thm: enhancement converge of the paper).

[Theorem T: main subdiffusive of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Assume that $\mathbf{P}\{ f_{+},f_{-} \in \mathcal{S} \} = 1$, (equation E: decay two of the paper) holds, $\sigma = 0$, and $a > 0$.  Fix a $\theta \in \mathbb{R}$ and let $p^{(N)} = 1/2 + \theta N^{-1}$.  For each $N \in \mathbb{N}$, let $\{X^{(N,n)}\}$ be a solution of the RDE 
	\begin{equation*}
		X^{(N,n)} \overset{d}{=} \Phi^{(N)} ( X^{(N,n-1)}_{1}, X^{(N,n-1)}_{2} ),
	\end{equation*}
where $(X^{(N,n-1)}_{1},X^{(N,n-1)}_{2})$ are i.i.d.\ copies of $X^{(N,n-1)}$ and $\Phi^{(N)}$ is given by (equation E: main forcing of the paper) with bias parameter $p = p^{(N)}$.

Assume that there is a function $F_{\text{in}}$ such that, at the initial time $n = 0$, the following limit holds:
		\begin{align*}
			\lim_{N \to +\infty} \mathbb{P} \{ N^{-1/3} X^{(N,0)} \leq x\} = F_{\text{in}}(x) \quad \text{for almost every} \, \, x \in \mathbb{R}.
		\end{align*}
	If $\{F_{N}\}$ is the sequence of rescaled CDF's defined in $\mathbb{R} \times [0,+\infty)$ by
		\begin{align*}
			F_{N}(x,t) = \mathbb{P} \{ N^{-1/3} X^{(N, [ N t ] )} \leq x \},
		\end{align*}
	then $F_{N} \to F$ locally uniformly in $\mathbb{R} \times (0,+\infty)$ as $N \to +\infty$, where $F$ is the unique bounded discontinuous viscosity solution of the initial-value problem
				\begin{align} 
					\left\{ \begin{array}{r l}
						\partial_{t} F - a | \partial_{x} F | \partial_{x}^{2} F + 2 \theta F ( 1 - F ) = 0 & \text{in} \, \, \mathbb{R} \times (0,+\infty), \\
						F(x,0) = F_{\text{in}}(x).
					\end{array} \right.
				\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 11 (Uniform bounds for the defect measures) of arXiv:2607.28238, 'Well-posedness and large deviations for the obstacle problem of first-order stochastic con'] For every $p\geq0$, there exists $C_p>0$, independent of $\alpha\in(0,1)$ and $n\in\mathbb N$, such that
\begin{align}
&\E \bigg[\bigg|\int_{\mathbb{T}^N\times[0,T]\times\mathbb{R}}(1+|\xi|^p)\dd m_{\alpha,n}\bigg|^2\bigg]\\
&+\E\bigg[\bigg|\int_{\mathbb{T}^N\times[0,T]\times\mathbb{R}}(1+|\xi|^p)\dd \lambda_{\alpha,n}\bigg|^2\bigg]\leq C(p,D_0,M_\psi,T),
\end{align}
where $m_{\alpha,n}$ is defined by \eqref{rs-34} and $\lambda_{\alpha,n}$ is given by \eqref{eq:def-lambda-eta-epsilon}.

