body:
[Theorem thm:dragoverkill of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] There exists a smooth function $\mathrm{O}(t)>-1$, defined for $t\in [0,1)$ such that $\mathrm{O}(0)=0$, and such that the following holds.
Let $(M,g)$ be a compact smooth Riemannian manifold of dimension $n$, possibly with boundary. Let $\phi$ be a Gaussian field of class $\mathcal{C}^3(M)$ with covariance function $E$ and parameters $\lambda=\lambda(\phi)>0,\sigma=\sigma(\phi)>0,\varepsilon=\varepsilon(\phi)$ defined as in [cgv2025StecconiTodino] (see also (def:three of the paper)), and let $\tau:=\tau(\phi)$ be as in (eq:defe03 of the paper).
Assume that there exist positive numbers: $ \frac{c} {\lambda} \le r\le \rho$, $\delta$ and $B$, satisfying the following assumptions.
\begin{enumerate}
\item The eccentricity is less than one:
\begin{equation} 
\varepsilon=\varepsilon(\phi)<1, \quad \text{and} \quad \tau=\tau(\phi)<1.
\end{equation}
\item The pull-back field satisfies: 
\begin{equation} 
\sup_{\substack{x,y\in M,
\\
 \mathrm{dist}(x,y)\le r}
}
\sigma^{-2}\|j^{3,3}_{x,y}E\|_{g^{\lambda}}

\le B
\end{equation}
\item The field satisfies:
    \begin{equation} 
\sup_{\substack{x,y\in M,
\\
r
\le \mathrm{dist}(x,y)\le \rho
}}

\sigma^{-2}\|j^{1,1}_{x,y}E\|_{g^{\lambda}}
\le \delta  <\frac{(1-\varepsilon)^2}{2\left(1+\mathrm{O}(\tau)\right)} 

\end{equation}

\end{enumerate}
Then, we have the following quantitative Law Of Large Numbers:
\begin{gather}

{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_f(M)}{\lambda}\right\}\le

{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_f(M)[2]}{\lambda}\right\}

+\mathfrak{C}\rho^{-n}\cdot  \Bigg(\mathfrak{D}r^{n}+
\\

+

\frac{(1+\mathrm{O}(\tau))(1+\mathrm{O}(\varepsilon))}{1-\delta\frac{2 (1+\mathrm{O}(\tau))}{(1-\varepsilon)^2}}
\frac{2^4}{n}\int_{\substack{x,y\in M,
\\
r
\le \mathrm{dist}(x,y)\le \rho}}\|\sigma^{-2}j^{1,1}_{x,y}E\|^4_{g^{\lambda}} \dd x \dd y 
\Bigg).
\end{gather}
where $\mathfrak{D}=\mathfrak{D}(n,M,g;B,c)$ is a constant depending only on $n,M,g$ and on the constants $B,c$; $\mathfrak{C}=\mathfrak{C}(n,M,g)$ depends only on the geometry.

[Theo thm:fBm-loc-ord of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] Let $ B^H$ be a fractional Brownian motion with Hurst parameter   $ H \in ( 0 ,1)$  and let $W^H$ be the probability law of $B^H$. Then  $W^H$-almost surely the local order  of the standard Wiener measure $W$ (for the uniform norm) at $ B^H$ is given by
        \begin{equation*}
            \mathsf{ord}_{ \mathrm{loc}  } W ( B^H) =
            \begin{dcases}
                2 ( H^{-1} - 1) & \qquad  \text{ if } \, 0 < H < 1/2 \\
                2 & \qquad \text{ if } \, 1/2  \le  H <  1  \, .
            \end{dcases}
        \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma est_hall_term of arXiv:2604.07497, 'The Three-Dimensional Stochastic EMHD System: Local Well-Posedness and Maximal Pathwise So'] The nonlinear hall term in Proposition (prop:uni_energy_estimate of the paper) satisfies the following estimate: 
\begin{align}
&\int_0^t \Ltwoinner{\chi_r^2 {\mathcal P}_n \varLambda^s \left( B_n \times \nabla \times B_n \right), \varLambda^s \left( \nabla \times B_n \right)} \VertB_n\Vert_{H^s({\mathbb T}^3)}^{p-2} d\tau \notag \\
\leq &\  C_r \int_0^t \VertB_n\Vert_{H^s({\mathbb T}^3)}^p d\tau + \frac{\mu}{2} \int_0^t \VertB_n\Vert_{H^s({\mathbb T}^3)}^{p-2} \left\lVertB_n\right \rVert_{H^{s+\frac{\alpha}{2}}({\mathbb T}^3)}^2 d\tau.    
\end{align}

