body:
[Pro 10 (Limits as one \(\theta_i\to\pm\infty\)) of arXiv:2605.30779, '2605.30779'] Suppose that \(\beta>0\). Let \(r\) be a fixed positive integer when
\(\beta\in\{1,2\}\), and let \(r=1\) otherwise. Fix
\(i\in\{1,\dots,r\}\). When \(\beta\in\{1,2\}\), let
\(\Theta^{(i)}\) be defined as in \eqref{eq:Theta_i}; otherwise, set
\(\Theta^{(i)}=()\).

The symbols
\(\theta_i\), \(a_{\beta,k}^{\Theta^{(i)}}\),
\(s_{\beta,k}^{(i)}\),
\(\mathcal G^{(\beta)}_{(r-1),i^c}\), and
\(\xi_{\beta,k}^2\) have the meanings specified in
Theorem~\ref{finite_spikes_GOE} for the GOE case with \(\beta=1\)
and the GUE case with \(\beta=2\). For all other \(\beta>0\), they
stand for \(\theta\), \(a_{\beta,k}\), \(s_{\beta,k}\),
\(\mathcal G^{(\beta)}\), and \(\xi_{\beta,k}^2\), respectively, as
in Theorem~\ref{one_spike_beta}. The \(o(1)\) terms in
Parts~\ref{enu:one-coordinate-BBP:positive}--
\ref{enu:one-coordinate-BBP:negative-k1} are understood almost surely.

\begin{enumerate}[label=\textup{(\roman*)}]

\item
For every fixed \(k\ge1\), as \(\theta_i\to+\infty\),
\begin{equation}
\begin{aligned}
s_{\beta,k}^{(i)}
&=
a_{\beta,k}^{\Theta^{(i)}}
+\frac{\beta^{-1}\xi_{\beta,k}^2}{\theta_i}
\bigl(1+o(1)\bigr),
&\qquad
-\frac{1}{
\bigl(\mathcal G^{(\beta)}_{(r-1),i^c}\bigr)'
\bigl(s_{\beta,k}^{(i)}\bigr)}
&=
\frac{\beta^{-1}\xi_{\beta,k}^2}{\theta_i^2}
\bigl(1+o(1)\bigr).
\end{aligned}
\end{equation}

\item 
For every fixed \(k\ge2\), as \(\theta_i\to-\infty\),
\begin{equation}
\begin{aligned}
s_{\beta,k}^{(i)}
&=
a_{\beta,k-1}^{\Theta^{(i)}}
-\frac{\beta^{-1}\xi_{\beta,k-1}^2}{|\theta_i|}
\bigl(1+o(1)\bigr),
&\qquad
-\frac{1}{
\bigl(\mathcal G^{(\beta)}_{(r-1),i^c}\bigr)'
\bigl(s_{\beta,k}^{(i)}\bigr)}
&=
\frac{\beta^{-1}\xi_{\beta,k-1}^2}{\theta_i^2}
\bigl(1+o(1)\bigr).
\end{aligned}
\end{equation}

\item
As \(\theta_i\to-\infty\),
\begin{equation}
\begin{aligned}
s_{\beta,1}^{(i)}
&=
\theta_i^2\bigl(1+o(1)\bigr),
&\qquad
-\frac{1}{
\bigl(\mathcal G^{(\beta)}_{(r-1),i^c}\bigr)'
\bigl(s_{\beta,1}^{(i)}\bigr)}
&=
2|\theta_i|+o(1).
\end{aligned}
\end{equation}

\item 
If, in addition, \(\beta\in\{1,2\}\), then, as
\(\theta_i\to-\infty\),
\begin{equation}
\begin{aligned}
\frac{s_{\beta,1}^{(i)}-\theta_i^2}
{2(-\theta_i)^{1/2}}
&\Longrightarrow
\mathcal N\!\left(0,\frac1\beta\right),
&\qquad
(-\theta_i)^{1/2}
\left[
-\frac{1}{
\bigl(\mathcal G^{(\beta)}_{(r-1),i^c}\bigr)'
\bigl(s_{\beta,1}^{(i)}\bigr)}
+2\theta_i
\right]
&\Longrightarrow
\mathcal N\!\left(0,\frac2\beta\right).
\end{aligned}
\end{equation}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

