[Defin def:stable of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] For any $\alpha\in(0,2]$, the law of 
an $\alpha$-stable L\'evy process $\bm{Z}$
 is given by a generating triplet $(\bm{\gamma_Z},\bm{\Sigma_Z}\bm{\Sigma_Z}^{\scalebox{0.6}{$\top$}},\nu_{\bm{Z}})$
(for the cutoff function $\bm{w}\mapsto\1_{B_{\bm{0}}(1)}(\bm{w})$)
as follows: the L\'evy measure is given by~(equation eq:Levy-measure-stable of the paper), i.e.,
\begin{equation*}

    \nu_{\bm{Z}}(A)
    \coloneqq c_\alpha\int_0^\infty\int_{\mathbb{S}^{d-1}}
        \1_{A}(r\bm{v})\sigma(\mathrm{d}\bm{v})r^{-\alpha-1}\mathrm{d} r,
    \quad A\in\mathcal{B}(\mathbb{R}^d_{\bm{0}}),
\end{equation*}
where $\sigma$ is a probability measure  on $\mathcal{B}(\mathbb{S}^{d-1})$  
and  $c_\alpha\in[0,\infty)$ an ``intensity'' parameter, satisfying
\begin{itemize}[leftmargin=1em, nosep]
    \item $\alpha=2$ [Brownian motion with zero drift]: $\bm{\Sigma_Z}\ne \bm{0}$, $\bm{\gamma_Z}=\bm{0}$ and $c_\alpha=0$ (i.e. $\nu_{\bm{Z}}\equiv 0$);
    \item $\alpha\in(1,2)$ [infinite variation,  zero-mean process]: $c_\alpha>0$, $\bm{\gamma_Z}=-\int_{\mathbb{R}^d\setminus B_{\bm{0}}(1)}\bm{x}\nu_{\bm{Z}}(\mathrm{d}\bm{x})$ and $\bm{\Sigma_Z}=\bm{0}$;
    \item $\alpha=1$ [Cauchy process]: either $c_\alpha>0$, with symmetric angular component $\int_{\mathbb{S}^{d-1}}\bm{v}\sigma(\mathrm{d}\bm{v})=\bm{0}$, or $c_\alpha=0$ and the process $\bm{Z}$ is  a deterministic nonzero linear drift, i.e. $\bm{Z}_t=\bm{\gamma_Z}t$ for all times $t$;
    \item $\alpha\in(0,1)$ [finite variation and zero natural drift]:  $c_\alpha>0$ and  
    $\bm{\gamma_Z}=\int_{B_{\bm{0}}(1)\setminus\{\bm0\}}\bm{x}\nu_{\bm{Z}}(\mathrm{d}\bm{x})$.
\end{itemize}

[Lem Pibound of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Let $\mathbf{n}=(n_1, n_2, n_3) \in {\mathbb N}^3$ and ${\boldsymbol \sigma},{\boldsymbol \tau} \in \mathcal S_{\mb{n}}$. 
Set $\mathbf{a} = \type({\boldsymbol \sigma})$ and $\mathbf b = \type({\boldsymbol \tau})$. 
Suppose that $\gamma_*$ and $\Gamma_*$ for $*\in \mathcal A_3$ are twelve contours, all contained in the disk of radius $2$ centered at the origin, and that every pair is separated by a distance of at least $d>0$. 
Then, 
\begin{equation} 
    |\Pi^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}(\boldsymbol{\xi}, \boldsymbol{\eta}) | \le \frac{2^{4|\mathbf{n}|}}{d^{|\mathbf{a}|+|\mathbf b|}}
    \sqrt{n_1! (n_2-n_1+a_1+b_1)! (n_2-n_3+a_3+b_3)! n_3!}
\end{equation} 
for every $\boldsymbol{\xi} = ( \boldsymbol{\xi}^{123}, \boldsymbol{\xi}^{12}, \boldsymbol{\xi}^{23}, \boldsymbol{\xi}^1, \boldsymbol{\xi}^2, \boldsymbol{\xi}^3)$ and $\boldsymbol{\eta} = ( \boldsymbol{\eta}^{123}, \boldsymbol{\eta}^{12}, \boldsymbol{\eta}^{23}, \boldsymbol{\eta}^1, \boldsymbol{\eta}^2, \boldsymbol{\eta}^3)$ satisfying $\boldsymbol{\xi}^*\in (\gamma_*)^{a_*}$ and $\boldsymbol{\eta}^*\in (\Gamma_*)^{b_*}$ for each $*\in \mathcal A_3$.

