[Lemma of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:block_permutations}
    Let $G$ be a transitive graph of polynomial growth, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$.

    For $k \in \mathbf{N}$ and $\mathbf{m} \in \mathcal{M}(b,k)$,

    \begin{multline}
        \frac{1}{(b-1)!}
        \sum_{\mathbf{B} \in \mathcal{A}(b,\mathbf{m})}
        \mathbf{P}_{\beta}
        \left(
            \mathcal{H}(\mathbf{B}) \text{ is connected}
        \right)
        \\
        \leq 
        \sum_{\mathbf{f} \in \mathcal{F}(b)}
        \prod_{i = 1}^{b-1}
        \frac{1}{f_i !}
        \sum_{\mathbf{B} \in \mathcal{A}(b,\mathbf{m})}
        \mathbf{P}_{\beta}
        \left(
            \mathcal{H}(\mathbf{B}) \text{ is } \mathbf{f} \text{-connected}
        \right).
    \end{multline}

[Theorem 9 of arXiv:2512.10686, 'Maximal rigidity of random measures and uniqueness pairs: stealthy processes, quasicrystal'] [\cite{Shapiro},Theorem A']
     Let $ B$ a minor cone, and $ \psi :\mathbb{R}^{d}\to \mathbb{C}$ a tempered function such that for some $ \delta >0$,
\begin{align*}
\int_{ B^{ c}} | \psi (t) | e^{\delta  | t | }dt<\infty 
\end{align*}
and such that $ \F \psi  = 0$ on some nonempty open set. Then $ \psi \equiv 0.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l4.9 of arXiv:2603.14447, '\Large \bf Backward doubly stochastic differential equations with and without reflection u'] \sl
		Let the conditions \(\textbf{(A2)}\),  \(\textbf{(G2)}\) and \(\textbf{(S2)}\) be satisfied. Moreover, let   \(\hat{M}\triangleq \|\xi\|_{\infty}\vee \|S\|_{\infty} \),
		\( C >0 \) be a constant, \(a:[0,T] \longmapsto \mathbb{R}_+ \) and \( b: [0,T]\longmapsto \mathbb{R}_+\) be two non-negative functions, such that for all \((t,y,z)\in [0,T]\times\mathbb{R}\times\mathbb{R}^d\), 
		\begin{align*}
			|f(t,y,z)|\leqslant a_t+b_t|y|+C|z|^2,\quad\ \hbox{a.s.}
		\end{align*}
		If \((Y,Z,K)\in S^\infty_{\mathbb{F}}([0,T];\mathbb{R})\times L^2_{\mathbb{F}}([0,T];\mathbb{R}^d)\times A^2_{\mathbb{F}}([0,T];\mathbb{R}_+)\) is a solution of RBDSDE (equation r1 of the paper),
		then for any \(t\in[0,T]\),
		\begin{align}
			Y_t\geqslant  -\|\xi\|_{\infty}\exp\left\{\int_t^T b_sds\right\}-\int_t^T a_s \exp\left\{\int_t^s b_rdr\right\}ds-\frac{4C}{1-\alpha}\int_t^T|\lambda(s)|^2\exp\left\{\int_t^s b_rdr\right\}ds,\quad\ \hbox{a.s.}
		\end{align}
		respectively,
		\begin{align}
			\Big(		Y_t\leqslant \hat{M}\exp\left\{\int_t^T b_sds\right\}+\int_t^T a_s \exp\left\{\int_t^s b_rdr\right\}ds+\frac{4C}{1-\alpha}\int_t^T|\lambda(s)|^2\exp\left\{\int_t^s b_rdr\right\}ds,\quad\ \hbox{a.s.} \Big)
		\end{align}

		Furthermore, there exists a constant $\hat{K}>0$ which depends on $\alpha,C,T, \|a\|_{L^1([0,T];\mathbb{R}_+)}, \|b\|_{L^1([0,T];\mathbb{R}_+)}$, \(\|S\|_{\infty}\) and $\|Y\|_{S_{\mathbb{F}}^\infty([0,T];\mathbb{R})}$, such that
		\begin{align}
			\mathbb{E}\int_0^T|Z_s|^2ds\leqslant \hat{K}.
		\end{align}

