	\begin{equation*}
		\angled{\varphi_t}{\boldsymbol{\mu}_t} = \angled{\varphi_0}{\boldsymbol{\mu}_0} + \boldsymbol{A}_t(\varphi) - \boldsymbol{D}_t(\varphi) + \int_0^t \angled{\partial_t\varphi_s + r(\boldsymbol{\mu}_s)\partial_x\varphi_s + \partial_y\varphi_s}{\boldsymbol{\mu}_s}ds
	\end{equation*} 
	surely. Recall that the arrival process $\boldsymbol{A}(\varphi)$ and departure process $\boldsymbol{D}(\varphi)$ are defined as:
	\begin{equation*}
		\boldsymbol{A}_t(\varphi) \vcentcolon= \sum_{i = 1}^{\mathcal{R}(t)} \varphi_{a_i}(0, 0) \quad \text{and} \quad \boldsymbol{D}_t(\varphi) \vcentcolon= \sum_{i = 1 - M}^{\mathcal{R}(t)} \mathbbm{1}_{\left\{t \geq d_i\right\}}\varphi_{d_i}\left(\boldsymbol{x}_i(d_i), \boldsymbol{y}_i(d_i)\right).
	\end{equation*}

