[Def of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] In what follows, let $\eta\in\Omega_N$ , $f:\Omega_N\to\mathbb{R}$ and $x,y,z\in\mathbb{T}_N$ be arbitrary:
\begin{itemize}
        \item Let $\pi_x:\Omega_N\to\{0,1\}$ be the projection $\pi_x(\eta)=\eta(x)$;

        \item $\tau:\eta\mapsto\tau\eta$ is defined as the shift operator, $\pi_x(\tau\eta)=\pi_{x+1}(\eta)$, and short-write $\tau^i=\circ_{j=1}^i\tau$ for its $i$-th composition;

        \item Denote by $\theta_{x,y}$ the operator that exchanges the occupation-value of the sites $x,y$,
        \begin{align}
            (\theta_{x,y}\eta)(z)
            =\eta(z)1_{z\neq x,y}
            +\eta(y)1_{z=x}
            +\eta(x)1_{z=y};
        \end{align}

        \item For $\mathcal{O}$ any of the previously introduced operators, let $\mathcal{O} f(\eta):=f(\mathcal{O}\eta)$.
    \end{itemize}
    Moreover, introduce the linear operators $\nabla_{x,y},\nabla,\Delta$ through 
    \begin{align}
        \nabla_{x,y}[f]:=\theta_{x,y}f-f
        ,\quad
        \nabla[f]:=\tau f-f 
        \quad\text{and}\quad
        \Delta[f]=\nabla^2[\tau^{-1}f]
        .
    \end{align}
    Note that $\nabla$ corresponds to the forward difference operator and $\Delta$ to the discrete Laplacian operator.

[Lemma 9 of arXiv:2506.11799, 'Quenched limit for diffusive biased random walks in random environment'] There exists a positive constant $C>0$, such that, uniformly over all $U_1, U_2 \in \mathbb{V}_d$ for all $n \in \mathbb{N}$ 
	\begin{equation*}
		\mathbb{E}_{U_1, U_2}\left[ \left(\frac{\tilde{\mu}^{(1)}_{1}}{n^{1/2}} \wedge 1\right) \left(\frac{\tilde{\mu}^{(2)}_{1}}{n^{1/2}} \wedge 1\right) \Big| \mathcal{D}^{\bullet} = \infty\right]\le Cn^{2\varepsilon - 1}.
	\end{equation*}

