[Lemma 21 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Let Assumptions \ref{ass-G+Sigma}-\ref{ass-bg+sigma} be satisfied. Then, for every $t \in[0,T]$, we have
    \begin{equation}
        \nu \,\duality{\Stokes\bu}{\bu}{\StokesV}{\StokesVp} - \frac12 \Vert \bSi(t)\bu \Vert_{\ell^2(\StokesH)}^2 
       \geq  \delta_0 \Vert \bu \Vert_{\StokesV}^2, \;\; \bu \in \StokesV,
    \end{equation}
and
        \begin{equation}
            \Vert \bSi(t)\bu \Vert_{\ell^2(\StokesH)}^2
             \leq 
             2(\nu-\delta_0) \Vert \bu \Vert_{\StokesV}^2, \;\; \bu \in \StokesV.
        \end{equation}
Furthermore, there exists a constant $C_4>0$ such that for every $t \in[0,T]$,
   \begin{equation}
       \Vert \bSi(t)\bu \Vert_{\ell^2(\StokesVp)}^2
      \leq C_4 \lvert \bu \rvert_{\StokesH}^2, \;\; \bu \in \StokesH.
   \end{equation}

