[Corollary linear_growth_functional_convergence_alpha_quantile_time of arXiv:2605.20471, 'Note on the Weak Convergence of Hyperplane $α$-Quantile Functionals and Their Continuity i'] Let $X^n\Rightarrow X$ and $X^n$ are all martingales in their respective filtrations. Suppose that $f:\mathbb{R}\to \mathbb{R}$ satisfies the growth condition $|f(z)|^p\leq D(1+|z|^p)$ for some $p>1,D>0$. \textcolor{black}{
		Let $v>0$.} Define $g(m,u)=f(m)\mathbf{1}_{(v,\infty)}(u)$ and its continuity set $C(g)$. If 
	\begin{enumerate}
		\item $\sup_{n \in \mathbb{N}}E^{P^n}[|(\gamma \cdot X^n)_T|^p]<\infty$;
		\item $P((M_{T,\alpha}(X),\tau_{M_{T,\alpha}}(X))\in C(g))=1$;
	\end{enumerate}
	Then $E^{P^n}[f(M_{T,\alpha}(X^n))\mathbf{1}_{(v,\infty)}(\tau_{M_{T,\alpha}}(X^n))]\to E^P[f(M_{T,\alpha}(X))\mathbf{1}_{(v,\infty)}(\tau_{M_{T,\alpha}}(X))]$ as $n \to \infty$.

[Proposition 22 (Uniform-in-time second Malliavin derivative bounds) of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume that Assumptions \ref{ass:smooth},
\ref{ass:second-malliavin-uniform}, \ref{ass:coeff-level-new}(i)(ii),
and \ref{ass:first-malliavin-uniform} hold. Then, there exists a constant
$ C > 0 $ such that, for all $ N \ge 1 $, all $ 0 \le r,s \le u $, all
$ i,j,k \in \left\{ 1,\dots,N \right\} $, and all
$ \alpha,\beta \in \left\{ 1,\dots,m \right\} $,
\begin{equation}

\E\left(
\norm{D_r^{k,\beta} D_s^{j,\alpha} X_u^{i,N}}^4
\right)^{1/4}
\le
C e^{-\hat{\omega}\left( u-\min\left\{ r,s \right\} \right)}
\left(
\mathbf{1}_{\left\{ i=j=k \right\}}
+
\frac{1}{N}
\left(
\mathbf{1}_{\left\{ i=j \right\}}
+
\mathbf{1}_{\left\{ i=k \right\}}
+
\mathbf{1}_{\left\{ j=k \right\}}
\right)
+
\frac{1}{N^2}
\right).
\end{equation}

