body:
[Lem corridor_of_boxes of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] The following holds for $R \in \mathbf N$ large enough. Fix $0<p'<1$. Suppose that $M,a$ are chosen so that $\mathbf{P}(F_1\cap F_2\cap F_3)\geq 1-p'/2$. For $0<b<a$, consider a grid of evenly spaced sites at distance $br$ of each other, such that boxes of side length $br$ centered at those sites cover $B(x,2r)$. Let $F_4(b)$ be the event that for any $\phi_i$, there exists a sequence of boxes $B_1,\ldots, B_t$, such that:
\begin{enumerate}
\item[$\bullet$] the boxes are consecutive, i.e., $B_{\tilde{t}}$ and $B_{\tilde{t}+1}$ share a side for all $1\leq \tilde t <t$;
\item[$\bullet$] $B_t$ intersects $\partial B(x,2r)$, $B_1\cap \phi_i \neq \emptyset$ and $\bar{B}_1\cap \psi_i \neq \emptyset$ where $\bar{B}_1$ denotes the set of all sites of $B_1$ as well as all the sites neighboring those;
\item[$\bullet$] $4B_{\tilde{t}}$ does not intersect $\phi \setminus \phi_i$ for any $1\leq \tilde{t}\leq t$. 
\end{enumerate}

Then there exists $b_0=b_0(p',M,a)$ such that for all $b<b_0$ we have that $\mathbf{P}(F_1\cap \cdots \cap F_4)\geq 1-p'$ holds for all annuli of radius $r$ with $r\geq \frac{R}{bn}$.

[Corollary 82 (Renormalisation of the $\Phi^4_d$ model with $d\in(3,4)$) of arXiv:2605.14630, '2605.14630'] Let 
\begin{equation}

\gamma =  \gamma_{N,d}(\alpha) = 
 - \sum_{n=2}^{n^*_{\textup{e}}(d)}
 \frac{(-\alpha)^n}{n!} \Pi_N\tilde\cA(\cP(\bX^n))\;. 
\end{equation} 
Then the $\Phi^4_d$ model with $d\in(3,4)$, mass counterterm $\beta$ 
and energy counterterm $\gamma$ satisfies 
\begin{equation}

 \log\frac{\cZ_{d,\alpha,N}}{\cZ_{d,0,N}} 

 \asymp -\sum_{n\geqs n^*_{\textup{e}}(d)} \frac{(-\alpha)^n}{n!} 
 \Pi_N\cA(\cP(\bX^n))\;,
\end{equation} 
where the coefficients are bounded uniformly in the cut-off $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2603.25400, 'One-arm probabilities for the two-dimensional metric-graph and discrete Gaussian free fiel'] Let $h\in\mathbb{R}$, $x\in\wt B_{\frac34N}$, $y\in\mZ$ that satisfies $|y-x|=\delta\in(0,1]$, and $V$ be any subset of $\mB_{N}$ containing $x$. Define the event
     \begin{equation}
         \mathcal D:=\{\mphi_{N,z}\ge h,\forall z\in V\}\cap\{\mphi_{N,z}<h,\forall z\in B_N\setminus V, |z-x|\ge1 \}.
     \end{equation}
    Then, there exists $c_1>0$ such that for all large $N$,
    \begin{equation}
        \mathbb E[\mphi_{N,y}\mid\mathcal D]\ge h-c_1\delta^{\frac12},\quad \forall h\le\sqrt{\log N};
    \end{equation}
    \begin{equation}
        \mathbb E[\mphi_{N,y}\mid\mathcal D]\ge\frac12 h,\quad \forall h>\sqrt{\log N}.
    \end{equation}

[Lemma decomposition_lemma of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] Fix a path $\pi(t,dx)=\rho_t(x)\;dx$ in $ {\mathcal{D}}([0,T],\mathscr{M}_{ac})$. Assume that $ {\rho}$ is continuous in $\Omega_T$, smooth in time and that there exists an $\epsilon>0$ such that $\epsilon\leq  {\rho}_t(x)\leq 1-\epsilon,$  {for all} $(t,x)\in\Omega_T$ and that $I_{[0,T]}(\rho)<\infty$. We have that $I_{[0,T]}(\rho)=I_{[0,T]}^{(1)}(\rho)+I_{[0,T]}^{(2)}(\rho)$ where
    \begin{equation*}
        I_{[0,T]}^{(1)}(\rho)=\frac{1}{4}||\mathfrak{L}_0||^2_{-1,\sigma(\rho)}\quad\quad\text{and}\quad\quad I_{[0,T]}^{(2)}(\rho)=\int_0^T\Phi_t(a_t,b_t)\;dt,
    \end{equation*}
     {where $a_t$ and $b_t$ were introduced in (equation def_a_and_b of the paper).} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Deff def:strong of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Fix $r \in [2,\infty), \theta \in \mathbb{R}$, a stopping time $\tau$, and assume $x \in L^p(\Omega;C([0,T];B))$. 
   We say a process $x_t$ is a strong solution in $\mathcal{B}_{\theta,r}$ to (equation eq:gefx of the paper) up to time $\tau$
    if for all $T > 0$:
    \begin{enumerate}[label=(\roman*)]
        \item $\mathbb{E}[\int_0^{T\wedge \tau} \|x_t\|_{1+\theta, r} dt] < \infty$
        \item $F: B \to \mathcal{B}_{\theta, r}$ and $\mathbb{E}[\int_0^{T\wedge \tau} \|F(x_t)\|_{\theta,r} dt] < \infty$
        \item $G: B \to \gamma(\mathcal{U},\mathcal{B}_{\theta, r})$ and $\mathbb{E}[\int_0^{T\wedge\tau} \|G(x_t)\|_{\theta,r}^2dt] < \infty$
    \end{enumerate}
    (see (fractional-domains-deff of the paper) for the definition of the norms) and furthermore
    \begin{equation}
    x_{t \wedge \tau} = x_0 + \int_0^{t \wedge \tau} Ax_s + F(x_s)ds + \int_0^{t \wedge \tau} G(x_s)dW_s \,.    
    \end{equation}

[Theorem directions_poles of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Suppose $\alpha^* > 0$ (i.e., $\phi_2$ has a pole). Then:
\begin{itemize}
\item If $r(\alpha - \alpha^{*})^2\to 0$, then:
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
\frac{1}{2}h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}.
  \end{equation}  
\nb{where $h_{\alpha^*}(z_0)$ is given by (equation harm2 of the paper).}
\item If $r(\alpha - \alpha^{*})^2\to K>0$ for some constant $K$, then for $\alpha < \alpha^*$ (resp. $\alpha > \alpha^*$),
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
c_Kh_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}
  \end{equation}  
  $$\left(resp.\quad g^{z_0}(r\cos(\alpha), r\sin(\alpha))\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
\tilde c_Kh_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}\right).$$
where constants $c_K > 0$, $\tilde c_K > 0$ are independant of initial condition $z_0$.
\item If $r(\alpha-\alpha^{*})^2\to \infty$, then:
\begin{itemize}
\item If $\alpha<\alpha^{*}$, then \begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}.
  \end{equation}  
\item If $\alpha>\alpha^{*}$, then:
\begin{equation}
g^{z_0}(r\cos(\alpha), r\sin(\alpha))
\underset{r\to\infty \atop \alpha\to \alpha^*}{\sim} 
h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha)} \frac{1}{\sqrt{r}}\frac{C}{\alpha-\alpha^{*}}
  \end{equation} where $C$ is a positive constant independent of initial condition $z_0$.
\end{itemize}
\end{itemize}
Furthermore, $h_{\alpha^*}(z_0) > 0$.

Constants $c_K, \tilde c_K$ and $C$, are made explicit in~[franceschi2023asymptotics]. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:CS(Dir) of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] For a given $\delta > 0$, we say that $(\mathcal{E},\mathcal{F})$ satisfies the \emph{cutoff Sobolev inequality} (eq:CS(Dir) of the paper) if there is a constant $C \geq 1$ for which the following holds.
    For every $x \in X$ and $R \in (0,\diam(X))$ there is a cutoff function $\xi \in \mathcal{F}_p$ for $B(x,R) \subseteq B(x,2R)$ such that
    \begin{equation}
    \tag{$\textup{CS}_{\delta}(\Psi)$}
    \int_{B(y,r)} f_{qc}^2 \, d\Gamma\Span{\xi} \leq C \left(\frac{r}{R}\right)^\delta \left( \int_{B(y,2r)} \, d\Gamma\Span{f} + \frac{1}{\Psi(r)} \int_{B(y,2r)} f^2 \, d\mu \right). \end{equation}
    for all $y \in X$, $0 < r \leq 3R$ and $f \in \mathcal{F}$.
    Here $f_{qc}$ is any quasicontinuous $\mu$-representative of $f$; see [FOT] for a detailed exposition on quasicontinuity.
    If $\Psi(r) = r^\beta$ for some $\beta \geq 2$, we write \hyperref[eq:CS(Dir)]{$\textup{CS}_\delta(\beta)$} instead.

[Theorem thm:limit_shape of arXiv:2605.03896, 'Dimer models on astroidal zig-zag graphs'] {Assume that the angle function is periodic.}
For~$(x,y)\in \mathcal D_c^\circ~$, 
\begin{equation}
\mathfrak h(x,y)=-\frac{1}{2\pi\mathrm{i}}\int_{C_{u_0}^{\zeta_*}}\lambda_c(x,y),
\end{equation}
where~$C_{u_0}^{\zeta_*}$ is the curve going from~$\sigma(\zeta_*)$ to~$\zeta_*$ crossing~$A_0$ only once in the component of~$A_0\backslash \bm \alpha$ corresponding to~$u_0$ as in Definition~(def:contours_whole_plane of the paper). The point~$\zeta_*\in \Sigma_+$ is defined as in Definition~(def:zero of the paper) if~$(x,y)$ lies in a phase region and defined by continuity otherwise. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm t:AJRAS-Z-existence of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {AJRS22}}]
    There exists a measurable map
    $\mathcal{Z} : (\Xi,\mathcal{F},\mathbb{P}) \to C(\mathbb{R}^{4}_{\uparrow}\times\mathbb{R}_{\geqslant 0}, \mathbb{R})$, denoted $\xi\mapsto \mathcal{Z}^\xi_{{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}}}({\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}},{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}};{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}},{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}})$,
    such that
    \begin{enumerate}[label={\rm(\roman*)}]
        \item\textup{(Chaos expansion).}        
        For each $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ 
        and $\beta\geqslant 0$, 
        the random variable $\xi\mapsto \mathcal{Z}_\beta^\xi(s,x;t,y)$ belongs to $L^2(\Xi,\mathcal{F},\mathbb{P})$,
        and its chaos expansion ((p:chaos-expansion of the paper)) is given by 
        \begin{align}
            \mathcal{Z}_\beta^\xi(s,x;t,y) = \sum_{n=0}^\infty \beta^n I_n\left(
                p^{(n)}_{(s,x),(t,y)}
            \right),
        \end{align}
        where $p^{(n)}_{(s,x),(t,y)}$ is defined in (equation e:def-pn of the paper).
        The above equality is as elements of $L^2(\Xi,\mathcal{F},\mathbb{P})$.

        \item\textup{(Strict positivity).}
        For $\mathbb{P}$-a.e. $\xi\in\Xi$, we have $\mathcal{Z}_\beta^\xi(s,x;t,y) > 0$
        for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$ and all $\beta\geqslant 0$.

        We henceforth replace $\mathcal{Z}$ with a strictly positive version, i.e. we assume $\mathcal{Z}_\beta^\xi(s,x;t,y)>0$ for \emph{all} $\xi\in\Xi$ and $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}, \beta\geqslant0$.

        \item\textup{(Adapted).} 
        For all $s<t$ and all $\beta\geqslant 0$, 
        the random function 
        $\xi\mapsto \mathcal{Z}_\beta^\xi(s,{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}};t,{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}})$ is $\mathcal{F}_{[s,t]\times\mathbb{R}}$-measurable.
        \footnote{
            As mentioned earlier, $\mathcal{F}_{[s,t]\times\mathbb{R}}$ is indeed the same $\sigma$-algebra as that in [AJRS22], by (l:nested of the paper).
        }  

        \item\textup{(Coupling of SHEs).}
        For each $(s,x)\in\mathbb{R}^2$ and $\beta\geqslant 0$, we have
        \begin{align*}
            \mathbb{P}\Bigl(
                \mathcal{Z}_\beta^\xi(s,x;t,y) = \mathcal{Z}^{\mathrm{SHE}}_{\beta}(s,x;t,y)
                \quad\textup{for all $t>s$ and all $y\in \mathbb{R}$}
            \Bigr)=1,
        \end{align*}
        where $\mathcal{Z}^{\mathrm{SHE}}_\beta(s,x;{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}},{\raisebox{1.1pt}{\hspace{0.6pt}\scaleobj{0.55}{\bullet}\hspace{0.75pt}}})$ is the unique (up to indistinguishability) continuous and $\{\mathcal{F}_{[s,t]\times\mathbb{R}}\}_{t\geqslant s}$-adapted mild solution to (equation e:she of the paper) (see [AJRS22] for details).
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:FP-trace-defect of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $F_{t,\mathbf{x},\mathbf{a}}
\vcentcolon= \det_{L^2(\mathbb{R})}(I - K_{t,\mathbf{x},\mathbf{a}})$.
Then
$\partial_{\mathbf{a}} \log F = \operatorname{tr}_{\mathbb{R}^m} \mathcal{A}$,
and
\begin{equation}
\Bigl[D_{t,\mathbf{a}}
+ \tfrac{1}{4}D_{\mathbf{x}}^2
+ \tfrac{1}{12}D_{\mathbf{a}}^4\Bigr] F \cdot F
= F^2\bigl((\operatorname{tr}_{\mathbb{R}^m}
\partial_{\mathbf{a}}\mathcal{A})^2
- \operatorname{tr}_{\mathbb{R}^m}
((\partial_{\mathbf{a}}\mathcal{A})^2)\bigr),
\end{equation}
where $D_{\mathbf{a}}$, $D_{\mathbf{x}}$, $D_t$
denote Hirota derivatives with respect to the
collective variables.

[Lemma 5 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] Assume that
  $$p_n^{a,x}(\theta)\sim c(\theta,a)h(x)\lambda^{n+1}$$
   holds as $n\to\infty$ for all $x\in[-a,1]$, a continuous function $h$ which is strictly positive on $[-a,1]$ and constants $\lambda=\lambda(\theta,a)>0$, $c(\theta,a)>0$ not depending on $x$ or $n$.
Then, for any $y\in[-a,1]$, the limit
\begin{align*}
    \lim_{n\to\infty}\P_y((M_k)_{1\leq k\leq m}\in\cdot~|\Omega_n)=\P_y((M'_k)_{1\leq k\leq m}\in\cdot~)
\end{align*}
exists, and $M'$ is a Markov chain with reduced transition kernel 
\begin{align} 
    p'(x_1,\d x_2)\coloneqq \mathds{1}_S(x_2,x_1)\frac{h(x_2)}{h(x_{1})}\frac{1}{\lambda}\frac{1}{a+1}\,\d x_2,~~~~~~~~x_1,x_2\in[-a,1].
\end{align}

