[Lemma L:K of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] When $\beta\in \{1,2\}$ and $\gamma = 0$, the constant
  $K(\alpha,\beta,\gamma;H,\ell;\nu,d)$, together with $\rho_0 = \beta + \gamma -
    1 + H - \ell\beta/(2\alpha)$, in~(equation E:SecMom-K of the paper) can be explicitly computed
  as follows:
  \begin{enumerate}[\rm (i)]
    \item For $\beta = 1$, we have that $\rho_0 = H-\ell/(2\alpha)$. Moreover, if $H\in(1/2,1)$,
          \begin{subequations}
            \begin{align}
              K(\alpha,1,0;H,\ell;\nu,d)
               & = \frac{2^{3+\ell/\alpha} H \pi^{(2+d)/2} \Gamma\left(\ell/\alpha\right) \lMr{2}{F}{1}\left(1,\ell/\alpha;2H;-1\right) }{\nu^{\ell/\alpha} \Gamma\left(d/2\right) (2\alpha H-\ell)};
            \end{align}
            and if $H=1/2$
            \begin{align}
              K(\alpha,1,0;1/2,\ell;\nu,d)
               & = \frac{2^{2}\pi^{(2+d)/2} \Gamma(\ell/\alpha) }{\nu^{\ell/\alpha}\Gamma (d / 2) (\alpha-\ell)}.
            \end{align}
          \end{subequations}
    \item
          For $\beta = 2$, we have the following cases:

          \begin{enumerate}[\rm a)]

            \item if $H = 1/2$ and $\ell\in(0,\alpha)\setminus\{\alpha/2\}$, then $\rho_0
                    = 1+ H -\ell /\alpha$ and
                  \begin{align}
                    K(\alpha,2,0;1/2,\ell;\nu,d)
                    = \frac{ 2^{3-\ell/\alpha} \nu^{1-\ell/\alpha} \pi^{(d+2)/2} \Gamma\left(2(\ell/\alpha-1)\right) \cos\left(\pi\ell/\alpha\right) }{\Gamma(d/2) \left(3\alpha-2\ell\right) };
                  \end{align}

            \item if $H = 1/2$ and $\ell = \alpha/2$, then $\rho_0 = 1$ and
                  \begin{align}
                    K(\alpha,2,0;1/2,\alpha/2;\nu,d)
                    = \frac{ 2^{1/2} \nu^{1/2} \pi^{(d+4)/2} }{\Gamma(d/2) \alpha };
                  \end{align}

            \item if $H\in (1/2,1)$ and
                  $\ell\in(0,(1/2+H)\alpha)\setminus\{\alpha/2,\alpha\}$, then $\rho_0 = 1+ H
                    - \ell/\alpha$ and
                  \begin{align}
                    \begin{aligned}
                       & K(\alpha,2,0;H,\ell;\nu,d)
                      =  \frac{ 2^{\ell/\alpha} \nu^{1-\ell/\alpha} H \pi^{(d+2)/2}  }{ \Gamma(d/2) } \times \Gamma(2(\ell/\alpha-1))\cos\left(\pi\ell/\alpha\right)                                                                                                   \\
                       & \qquad \times \Bigg[ \frac{ \alpha[1-2H] }{ (\alpha[1/2+H]-\ell) (\alpha[1+H]-\ell) }                                                               + 2 \frac{ \lMr{2}{F}{1}\left(1,2(\ell/\alpha-1);2H;-1\right) }{\alpha[1+H]-\ell} \Bigg];
                    \end{aligned}
                  \end{align}

            \item if $H\in (1/2,1)$ and $\ell=\alpha/2$, then $\rho_0 = 1/2 + H$ and
                  \begin{align}
                    K(\alpha,2,0;H,\alpha/2;\nu,d)
                    = \frac{ 2^{3/2} \nu^{1/2} \pi^{(d+4)/2}}{ \alpha  (1+2H) \Gamma\left(d/2\right) };
                  \end{align}

            \item if $H\in (1/2,1)$ and $\ell=\alpha$, then $\rho_0 = H$ and
                  \begin{align}
                    K(\alpha,2,0;H,\alpha;\nu,d)
                    = \frac{ 2^2 \pi^{(d+2)/2} }{ \alpha \Gamma (d/2) } \left(\frac{\lMr{2}{F}{1}(1,1;1+2H;-1)}{2H}+\frac{1}{2H-1}\right)
                  \end{align}
                  which does not depend on $\nu$. See Fig.(F:K-5 of the paper) for some plots related
                  to this constant.

          \end{enumerate}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 9 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Let  \(G_n=(N_n,V_n)\) be a directed dyadic dependency graph and let $(Z_{ij})_{i,j \in N_{n}}$ be defined as in expression \ref{eqn:Z.Fform}. Then, for any $p>1$ and $a,b>0$,
	\begin{align}
		\left\|
\sup_{f\in\mathcal F}\mathbb G_n(f)
\right\|_{L^1(\mathbb P)}
		\lesssim
		\sqrt n\,
		\gamma_{2,a}
		\left(
		\mathcal F,
		\|\cdot\|_{L^{2p}(P)}
		\right)
		+
	\frac{1}{\sqrt{n}}
		\gamma_{1,b}
		\left(
		\mathcal F,
		\|\cdot\|_\infty
		\right).
	\end{align}

[Lemma lema_q of arXiv:2607.13302, 'Extending an Order-Statistic Characterization of the Exponential Distribution'] Let $F$ be a distribution function that belongs to $ \mathcal{F}$. If for all natural $q$ holds
\begin{equation}
f^{(q)}(0) = (-1)^qf^{q+1}(0),
\end{equation}
then $f(x) = \lambda e^{-\lambda x}$ for some $ \lambda > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

