[Lemma lem::one_arm_bd_aux2 of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] We have the convergence
	\begin{equation*}
		\lim_{a\to 0} 2^{-1/4}a^{-\frac{1}{2}}|F^a(u_3^{a,\diamond})|=|\phi(\mathfrak{i};[-2,2]^2;-1-\mathfrak{i},1-\mathfrak{i})|,
	\end{equation*}
where $\phi(\cdot;[-2,2]^2;-1-\mathfrak{i},-1+\mathfrak{i})$ is the unique (up to a sign) holomorphic function defined in~[FPWFKIsing].

[Definition 24 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] The stochastic process on the probability space
$(\Omega,\mathcal{C},P)$ where $P$ is $\mathbb{H}$-valued is called
a $\mathbb{H}$-valued Brownian motion if it is Gaussian and if 
\begin{equation}
E_{\mathbb H}(B_{p}B_{q})=p\wedge q,\quad p,q\in\mathbb{H}_{+}
\end{equation}
and more generally, using \eqref{p-q} 
\begin{equation}
E_{\mathbb H}(B_{p}B_{q})=\frac{1}{2}\left(|p|_{\mathbb{H}}+|q|_{\mathbb{H}}-|p-q|_{\mathbb{H}}\right),\quad p,q\in\mathbb{H}.
\end{equation}

[Lem 48 of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] For the embedding of $|\Gamma_{M''}\cup L''|$ defined in Construction \ref{constr:hor-glue},
    \begin{enumerate}
        \item $|\Gamma_{M''}\cup L''|$ is a surgery presentation for $(\ol{M''}\#(S^1\times S^2), |\Gamma_{M''}|)$.
        \item The link trace $X_{L''}$ has the same signature as $X_L \cup_{V_{\parOut M}} X_{L'}$.
    \end{enumerate}

[Corollary 6 ($L^2$ control) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] For any $T>0$, there exists $C>0$ such that
    \begin{equation}
    \bigl\Vert p^{i,n}(t,\cdot) \bigr\Vert_2^2 \leq \frac{C}{\sqrt{t}},\quad t\in(0,T],
    \end{equation}
    where $C$ can be chosen uniformly in $i=1,\ldots, n$ and $n\geq 1$.

[Lemma lem:barrier-exclusion of arXiv:2608.30700, 'Convex hulls and area minimizing currents in asymptotically locally hyperbolic manifolds'] Let $\Omega=\Omega_{\psi,c}$, where $c\geq c_0(\psi)$, and let $V$ be a rectifiable $p$-varifold in $M$, $1\leq p\leq n$, which is stationary in $\Omega$. Suppose that
    \begin{equation}
        \overline{\spt V}^{\,\overline{M}}
        \cap\partial_\infty\Omega=\emptyset.
    \end{equation}
    Then $\spt V\cap\Omega=\emptyset$. In particular, if $T$ is a compactly supported integral $p$-current, $|T|$ is stationary in $M\setminus\spt\partial T$, and $\spt\partial T\cap\Omega=\emptyset$, then $\spt T\cap\Omega=\emptyset$.

[Prop 6 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] Let $L(x,{\d} y)$ be a kernel on $E\times\mathscr{B}(E)$ and ${\sf d}$ be a distance function consistent with the underlying topology.
Assume there exists $D_2, C > 0$ such that:
\begin{enumerate}
    \item $L(x,{\d} y) 
    \leq D_2 \frac{{\m}({\d} y)}{{\sf d}(x,y)^p}$,
    \item ${\m}(B_r(x))\leq Cr^d$ for every $x \in E$ and $r > 0$,
\end{enumerate}
for some $d, p \in \R$, $p >d\geq0$. Here $B_r(x):=\{y\in E\mid {\sf d}(x,y)<r\}$. Then $M_\beta < \infty$, i.e.,
\eqref{eq:MbetaFinite} holds, for any $\beta > p - d$.

