[Lemma 15 (Malliavin total variation estimate) of arXiv:2608.08177, 'Uniform-in-Time Smoluchowski--Kramers Approximation\\ in Total Variation for Fractional SD'] Let $F\in\mathbb D^{2,4}$ and $G\in\mathbb D^{1,2}$.  Suppose
$\norm{\D F}_{\cH}>0$ almost surely and
$u_F=\D F/\norm{\D F}_{\cH}^2$ belongs to the domain of $\delta$.  Then
\begin{equation}
 d_{\TV}(\Law(F),\Law(G))
 \le C\norm{F-G}_{\mathbb D^{1,2}}
 \left(
   \norm{\delta(u_F)}_{L^2}
   +\norm{\norm{\D F}_{\cH}^{-1}}_{L^2}
 \right).
\end{equation}
Moreover,
\begin{equation}
 \norm{\delta(u_F)}_{L^2}
 \le C\left(
  \norm{\norm{\D F}_{\cH}^{-1}}_{L^4}
  +\norm{\D^2F}_{L^4(\cH^{\otimes2})}
   \norm{\norm{\D F}_{\cH}^{-2}}_{L^4}
 \right).
\end{equation}

[Theorem 4 of arXiv:2506.18063, 'Reduced critical branching processes in non-favorable random environment \thanks{ This wor'] If Condition B1 is valid, then for any fixed $w\geq
0, $ $y\geq 0$ and $t>0$ the following relations are valid:

1) (\cite[Theorem 1]{VD2024})
\begin{equation*}
\lim_{n\gg k\gg r\rightarrow \infty }\mathbf{P}_{w}\left( S_{\tau
_{r,n}}\leq ya_{r}|\mathcal{B}(ta_{k},n)\right) =C^{\ast \ast }\mathcal{H}
(y),
\end{equation*}
where $C^{\ast \ast }$ is the same as in (\ref{Def_Cstar})

2) if $k\sim \theta r,\theta \in (0,\infty )$, then (\cite[Theorem 2]{VD2024}
)
\begin{equation*}
\lim_{n\gg k\rightarrow \infty }\mathbf{P}_{w}\left( S_{\tau _{r,n}}\leq
ya_{r}|\mathcal{B}(ta_{k},n)\right) =W(t\theta ^{1/\alpha },\theta
^{1/\alpha }t\wedge y);
\end{equation*}

3) (\cite[Theorem 3]{VD2024})
\begin{equation*}
\lim_{\min (r,n-r)\gg k\rightarrow \infty }\mathbf{P}_{w}\left( S_{\tau
_{r,n}}\leq ya_{k}|\mathcal{B}(ta_{k},n)\right) =1-\left( 1-\frac{t\wedge y}{
t}\right) ^{\alpha \rho +1};
\end{equation*}

4) if $k\sim \theta (n-r),\theta \in (0,\infty ),$ and $n-r=o(n)$ as $
n\rightarrow \infty $, then \cite[Theorem 4]{VD2024}
\begin{equation*}
\lim_{n\gg k\rightarrow \infty }\mathbf{P}_{w}\left( S_{\tau _{r,n}}\leq
ya_{k}|\mathcal{B}(ta_{k},n)\right) =A(\theta ^{1/\alpha }t,\theta
^{1/\alpha }\left( t\wedge y\right) ).
\end{equation*}
\bigskip (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (First-order functional limit) of arXiv:2608.01674, '\textbf{Limit Theorems for Tempered Linear Processes with Innovations in the Domain of Att'] Let \cref{ass:innovations,ass:filter,ass:tempering} hold and let
$T<\infty$.  Then
\begin{equation}
 \left\{\frac{S_N(t)}{B_NQ_N}:0\le t\le T\right\}
 \xrightarrow{\fdd}
 \{Z_\alpha(t):0\le t\le T\},

\end{equation}
as $N$ goes to infinity.
If $1<\alpha<2$, then the convergence is functional:
\begin{equation}
 \frac{S_N}{B_NQ_N}\RightarrowM Z_\alpha
 \quad\text{in }D[0,T].

\end{equation}
If $\alpha=2$, $\E\varepsilon_0^2<\infty$, and
$\E|\varepsilon_0|^{2+\delta}<\infty$ for some $\delta>0$, then
\begin{equation}
 \frac{S_N}{B_NQ_N}\RightarrowJ Z_2
 \quad\text{in }D[0,T].

\end{equation}
Because the limit in \eqref{eq:firstJ1} is continuous, this is
equivalent to locally uniform weak convergence after polygonal
interpolation. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theoremGinibreineq of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] One has the following inequalities:
 \begin{itemize}
  \item For any pair of integers $k, l \in \mathbb{N}$, any collection $m_1 , \ldots, m_k \in \mathbb{Z}^l$ and any sequence of plus and minus signs,
 \begin{equation} 
     \int_{[0, 2\pi]^l \times [0, 2\pi]^l} \prod_{i = 1}^k \left( \cos ( m_i \cdot \theta) \pm  \cos ( m_i \cdot \theta') \right) \prod_{j =1}^l d\theta_j d \theta'_j \geq 0.
 \end{equation}
 \item For any pair of vertices $x , y \in \Lambda$,
\begin{equation} 
    \left\langle \cos(\theta_x - \theta_y) \right\rangle_{\Lambda, J}^{\mathrm{XY}} \geq 0 \hspace{5mm} \mbox{and} \hspace{5mm} J = (J_{uv}) \mapsto \left\langle \cos(\theta_x - \theta_y ) \right\rangle_{\Lambda, J}^{\mathrm{XY}} ~\mbox{is increasing}.
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma concavity-right of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] For $x\leq s\leq 1$ we have 
\begin{equation}
p_{n}(s)\geq p+\frac{1-p}{1-x}(s-x).  
\end{equation}
Consequently, 
\begin{equation}
\int_{x}^{1}p_{n}(s)\,ds\geq \frac{(1-x)(p+1)}{2}.  
\end{equation}

