[Theorem thm:growthRate2 of arXiv:2507.03552, 'On one-dimensional Cluster cluster model'] Let $d=1, -2<\alpha<0$, $0<p<1$.
    $\forall \varepsilon>0, \delta>0$, $\exists T(\varepsilon,\delta)>0, c(\varepsilon,\delta)>0$ s.t $\forall t>T$:
    \begin{equation}
        \Prob{\frac{1}{c}t^{\frac{1}{\alpha+2}-\delta} \le \abs{\mathfs{C}_0(t)} \le ct^{\frac{1}{\alpha+2}}} \ge 1-\varepsilon
    .\end{equation}  
    For $\alpha < -2$:
    \begin{equation}
        \lim_{t \to \infty}{\Prob{\abs{\mathfs{C}_0(t)} < \infty}} = 0
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:alpha_family of arXiv:2608.28169, 'characteristic polynomial of self-normalized random matrices'] Let $\alpha \in (0, 2)$ and let 
    $\left(N_q^{(\alpha)}\right)_{q \geqslant 1}$ be independent $q$-Poisson processes defined in Definition (def:q_poisson_process of the paper). Then, for $q \geqslant 1$ and $m \geqslant 2$, let us set 
\begin{equation}

    V_{q, m}^{(\alpha)} \coloneqq  q \int f_m(u)  N_q^{(\alpha)}(\,\mathrm{d} u) = q \sum_{i \geqslant 1} f_m \left(\xi_{q,i}^{(\alpha)} \right) \,.
\end{equation}
For $m=1$, since $f_1 \notin \mathrm{L}^1(\nu_q^{(\alpha)})$ but $f_1 \in \mathrm{L}^2(\nu_q^{(\alpha)})$, we define $V_{q, 1}^{(\alpha)}$ as a compensated Poisson integral
\begin{equation*}
    V_{q, 1}^{(\alpha)} \coloneqq  q \int f_1(u)  \tilde{N}_q^{(\alpha)}(\,\mathrm{d} u) \in \mathrm{L}^2({\mathbb P})  \,,
\end{equation*}
where $\tilde N_q^{(\alpha)}(\,\mathrm{d} u)
    =N_q^{(\alpha)}(\,\mathrm{d} u)-\nu_q^{(\alpha)}(\,\mathrm{d} u)$.
 We call an \textit{$\alpha$-Poisson family} the family $\left(Z_k^{(\alpha)} \right)_{k \geqslant 1}$ given by 
\begin{equation}

    Z_k^{(\alpha)} \coloneqq  \sum_{q | k} V_{q, k/q}^{(\alpha)} \, , \qquad k \geqslant 1 \,,
\end{equation}
where the summation in (equation eq:family_alpha of the paper) is over all divisors of $k$.

[Lemma 17 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every fixed \(r\in\mathbb D\),
\begin{equation}
  \sup\{-m_F(r):F\subset\mathbb D\text{ finite}\}<\infty.

\end{equation}

[Lemma of arXiv:2609.00425, 'Individual and Uniform Eventual Positivity of Self-Adjoint Semigroups'] The space $H$ decomposes as $H = H_{\mathrm{even}} \oplus H_{\mathrm{odd}}$, where
    \begin{align*}
        H_{\mathrm{even}}
        &\coloneqq
        \set{x\in\ell^2(\mathbb{Z}) : x_n=x_{-n}\text{ for all }n\in\mathbb{Z}}, \\
        H_{\mathrm{odd}}
        &\coloneqq
        \set{x\in\ell^2(\mathbb{Z}) : x_n=-x_{-n}\text{ for all }n\in\mathbb{Z}}.
    \end{align*}
    Moreover, the following assertions hold:
    \begin{enumerate}[\upshape (i)]
        \item The sequence $(p_n)_{n \in \mathbb{N}_0}$ is an orthonormal basis of $H_{\mathrm{even}}$, where $p_0 \coloneqq e_0$ and
        \begin{align*}
            p_n \coloneqq \frac{1}{\sqrt{2}}(e_n+e_{-n}) \in \ell^2(\mathbb{Z}), \quad n \in \mathbb{N}.
        \end{align*}
        \item The sequence $(q_n)_{n \in \mathbb{N}}$ is an orthonormal basis of $H_{\mathrm{odd}}$, where
        \begin{align*}
            q_n \coloneqq \frac{1}{\sqrt{2}} (e_n - e_{-n}) \in \ell^2(\mathbb{Z}), \quad n \in \mathbb{N}.
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:S6V-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = L^2(C_r)$.  The seed functions
$\psi_{t,x,m}$ and $\phi_{t,x,m}$ defined in
(equation eq:S6V-seed-def of the paper) satisfy the linear problem
(equation eq:Linear-Psi-3 of the paper) and the adjoint linear problem
(equation eq:Linear-Phi-Prob of the paper) on $\mathcal{V}$ with edge
weights $(c_k, \lambda_k)$.  Explicitly:
\begin{align}
\psi_{t,x+1,m-1}
&= \psi_{t,x,m-1} + \tau^{-1}\psi_{t,x,m},
 \\
\psi_{t-1,x,m-1}
&= \psi_{t,x,m-1} + \alpha\psi_{t,x,m},

\end{align}
and
\begin{align}
\phi_{t,x,m-1}
&= \phi_{t,x+1,m-1}
   + \tau^{-1}\phi_{t,x+1,m-2},
 \\
\phi_{t,x,m-1}
&= \phi_{t-1,x,m-1}
   + \alpha\phi_{t-1,x,m-2}.

\end{align}

[Proposition prop:Schauder of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Fix $\alpha \in (0,1)$.  Suppose $g$ is a solution to (equation eq:linear_kinetic of the paper) in $Q_2$ satisfying (equation eq:uniform_ellipticity of the paper) in $Q_2$ for some values of $\lambda$ and $\Lambda$.  Suppose that $\mathcal A, \mathcal B, \mathcal C \in C^{0,\alpha}_{\rm kin}(Q_2)$.  Then, we have
        \begin{equation}
        [g]_{C^{2,\alpha}_{\rm kin}(Q_1)} \lesssim \left(1 + [\mathcal A]_{C^{0,\alpha}_{\rm kin}(Q_2)}^\frac{2+\alpha}{\alpha}
        + [\mathcal B]_{C^{0,\alpha}_{\rm kin}(Q_2)}^\frac{2+\alpha}{1+\alpha}
        + [\mathcal C]_{C^{0,\alpha}_{\rm kin}(Q_2)}\right) \left\|g\right\|_{L^\infty(Q_2)}.
    \end{equation}   
    Further suppose that for some $k \ge 3$ and some $\alpha \in (0,1)$,
    \begin{equation}
        \left\|\mathcal A\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)}
        + \left\|\nabla_v \mathcal A\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)}
        + \left\|\mathcal B\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)}
        + \left\|\mathcal C\right\|_{C^{k-3,\alpha}_{\rm kin}(Q_2)} \le \Lambda_k.
    \end{equation}
    Then there is $p_{k,\alpha}$, depending only on $k$ and $\alpha$ such that
    \begin{equation}
        [g]_{C^{k-1,\alpha}_{\rm kin}(Q_1)} \lesssim \left(1+\Lambda_k^{p_{k,\alpha}}\right) \left\|g\right\|_{L^\infty(Q_2)}.
    \end{equation}
    The implicit constants depends only on $\lambda$, $\Lambda$, and $\alpha$ and, in the case of~(equation e.Schauder_k of the paper), on $k$ as well. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 60 (Finite negative-rank reflection) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $m\ge1$, and every $0\le r\le m$,
\begin{equation}
 \HH_r(K;q^{-m},q)=\HH_{m-r}(K;q^{-m},q).
\end{equation}
Moreover, for every zero-framed knot $K$ and every $r\ge0$,
\begin{equation}
 \HH_r(K;q,q)=1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:62 of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] The following hold:
\begin{align} & 
\sup_{ \rR , i \in \mathbb{N} } E [ \lvert \ \uLXRi (t) - \uLXRi (u) \rvert ^4 ] 
 \le (;76 of the paper) \lvert t - u \rvert ^ 2 , \text{ } 0 \le t,u < \infty 
,\\ &
\limi{a} \liminfi{ R }
P ( \max_{1\le i \le m } \maxT \lvert \ \uLXRi (t) \rvert \le a ) = 1 
,\quad m , T \in \mathbb{N} 

,\\&
\limil \inf_{ R \in \mathbb{N} }
P ( \IRT ( \uLXR ) \le l ) = 1 
