[Definition def:skellam_process of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] The \textbf{Skellam point process} is the random point process on $\mathbb{R}$ whose $k$-point correlation measures $R^{\mathrm{(Skellam)}}_{\mu;k}(dx_1,\ldots,dx_k)$ are the unique Radon measures determined by the following Sine-transform identity. For any $t_1, \dots, t_k > 0$ and $m \in \{4, 8, 10\}$,
\begin{equation} 
    \int_{\mathbb{R}^k} \prod_{j=1}^k \frac{\sin^{m} (t_j\sqrt{-x_j})}{(t_j\sqrt{-x_j})^{m}} \, R^{\mathrm{(Skellam)}}_{\mu;k}(dx_1,\ldots,dx_k) = \sum_{\Pi \in \mathscr{P}([k])} \prod_{\pi \in \Pi} \tau_{\mathrm{(Skellam)}}(\{t_j\}_{j \in \pi}),
\end{equation}
where the deformed limiting cumulants $\tau_{\mathfrak{A}}$ are defined by the sum over connected typical diagrams:
\begin{equation*}
    \tau_{\mathrm{(Skellam)}}(\{t_j\}_{j \in \pi}) = \sum_{\Gamma \in \mathcal{T}_{|\pi|}} \int_{0}^1 \cdots \int_{0}^1 \left[ \prod_{j \in \pi} \mathcal{Q}_m(\xi_j) \right] \mathcal{F}^{\mathrm{(Skellam)}}_{\Gamma}(\{\xi_j t_j\}_{j \in \pi}; \lambda) \prod_{j \in \pi} d\xi_j.
\end{equation*}
Here $\mathcal{F}^{\mathrm{(Skellam)}}_{\Gamma}$ is the deformed limiting diagram function defined as
\begin{equation}
    \mathcal{F}^{\mathrm{(Skellam)}}_{\Gamma}(\{t_j\}_{j \in \pi}; \mu)=\mu^{-|E|+s} \sum_{\alpha_v\in \mathbb{T}_D^d}\int_{\lambda_e:\mathfrak{C}(\{t_i\})}
    \prod_{e\in E(\Gamma)}p^{\mathrm{(Skellam)}}(\alpha_{u}-\alpha_{v},\lambda_e) \prod_{e\in E(\Gamma)}d\lambda_e.
\end{equation}

[Lemma lowerestimate of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Fix $e\in S^{d-1}$. Let $I_e$ be defined by (equation eq:goodratefunction of the paper), $\Tilde{c}(e)$ be defined by (equation eq:Intro:SpeedRelativeTo of the paper), and $\bar{\mathbf{v}}$ be the effective drift (equation eq:Intro:EffectiveDrift of the paper). Fix $\epsilon\in (0,1)$. There exist constants $C=C(e)>0$ and $T=T(e)>0$ such that for every $t>T$ and $\kappa\in (0,1)$,
    \begin{equation}
        \inf_{x\in \mathbb{R}^d}\mathbb{E}_{x}\Big[\sum_{v\in \mathcal{N}_t} \mathds{1}_{\{(1-\kappa \epsilon)t\Tilde{c}(e)\geq (X_t(v)-X_0(v)-t\bar{\mathbf{v}})\cdot e\geq (1-\epsilon)t\Tilde{c}(e) \}} \Big] \geq Ce^{ t[\kappa\epsilon\lambda_e \Tilde{c}(e)-2I_{e}(c^*(e)-\kappa\epsilon\Tilde{c}(e))] }.
    \end{equation}
    Furthermore, there is $\epsilon_0=\epsilon_0(e)\in (0,1)$ such that for $\epsilon\in (0,\epsilon_0)$ and for any $\kappa \in (0,1)$, 
    $$\kappa\epsilon\lambda_e \Tilde{c}(e)-2I_{e}(c^*(e)-\kappa\epsilon\Tilde{c}(e)) >0.$$ In particular, for any $\epsilon\in (0,\epsilon_0)$, the expected value in (equation eq:lowerdirectionalestimate of the paper) grows to $+\infty$ as $t\uparrow +\infty$.

[Theorem 13 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] Let $\psi: [0, \infty) \to [0, \infty)$ be a nonnegative Borel function. Then for all $x\in \Sigma$, for $\mu_\ph-$a.e. $y \in \Sigma$, 
\begin{equation}
\int_0^\infty \psi(t) \mathbf{p}_t (x,y)\dd t  = \int_0^\infty  \bdec{x}{y}{t}  [ \psi( F(t))] p^\Sigma_t(x,y) \dd t ,
\end{equation}
where $ \bdec{x}{y}{t}$ denotes expectation with respect to the law of an ordinary Brownian bridge $(b_s)_{0\le s \le t}$ from $x$ to $y$ of duration $t$ (independent of the realisation of the underlying field $\ph$), $F(t) = \lim_{\eps \to 0} \eps^{\gamma^2/2}\int_0^t e^{\gamma \ph_\eps( b_s)} \dd s$ is the quantum clock appearing in the definition of Liouville Brownian motion, and $p_t^\Sigma(x,y)$ is the ordinary transition probabilities of Brownian motion killed when it leaves $\Sigma$ (thus $p_t^\Sigma(x,\cdot)$ is a subprobablity kernel). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:XYheightandIVGFFintro of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let $L \in \ensuremath{\mathbb{N}}$ be an integer, $\beta \in (0 , \infty)$ be an inverse temperature and $\omega \in \{0 , 1 \}^{E(\ensuremath{\mathbb{Z}}^2)}$ be an edge percolation configuration. We define:
\begin{itemize}
    \item \underline{The disordered integer-valued Gaussian free field} to be the probability distribution on the set $\Omega_{\Lambda_L}$ given by the identity
\begin{equation} 
    \mu_{\Lambda_L , \beta, \omega}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta , \omega}} \exp \left( - \frac{1}{2\beta} \sum_{x \sim y}  \frac{\left( \varphi(x) - \varphi(y) \right)^2}{\omega_{xy}} \right),
\end{equation}
    where we used the convention $\frac{k^2}{0} = \infty$ for $k \in \ensuremath{\mathbb{Z}} \setminus \{ 0 \}$ and $\frac{k^2}{0} = 0$ for $k=0$.
    We denote by $\mathrm{Var}_{L , \beta, \omega}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}}$ the variance with respect to this measure (and omit the index $\omega$ for the percolation configuration $\omega \equiv 1$).
    \item \underline{The disordered XY height function} to be the probability distribution on the set $\Omega_{\Lambda_L}$ given by the identity
\begin{equation} 
    \mu_{\Lambda_L , \beta,\omega}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta , \omega}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}} \prod_{x \sim y} I_{\left(\varphi(x) - \varphi(y)\right)} \left( \omega_{xy} \beta \right).
\end{equation}
We denote by $\mathrm{Var}_{L , \beta, \omega}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$ the variance with respect to this measure (and omit the index $\omega$ for the percolation configuration $\omega \equiv  1$).

\end{itemize}

[Proposition 72 (Size of $k_i$ at the $\sqrt{n}$ threshold) of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Let $i_* := \inf \{1 \le i \le S : k_i > \sqrt{n}\}$. Then there exists $c=c(\varepsilon)>0$ such that for all $n\ge 1$,
    \begin{align}
\widetilde{\p}_n\bigg( k_{i_*}> \sqrt{n}\Big( 1+ \frac{2}{(\log n)^\alpha}\Big) \,\bigg|\, i_*\le S\bigg) \le \exp\Big(-\frac{c \sqrt{n}}{(\log n)^{2\alpha}}\Big).
\end{align}

[Proposition prop:ladder-estimate-paper of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Fix \(q\in(1,2)\) with \(\rho(q)<1\), let
\(0<\beta<\beta_X(q)\), and fix \(\alpha_{\mathrm{gr}}>1\).  Then there exist
constants
\[
    C_{\mathrm{lad}}<\infty,\qquad
    \tau_{\mathrm{lad}}<\infty,\qquad
    n_0\ge1,
\]
depending on \(q,\beta,\alpha_{\mathrm{gr}}\) and on the law of the cascade,
such that, for every \(n\ge n_0\) and every \(0\le k\le n\),
\begin{equation}
    A^{(q,\alpha_{\mathrm{gr}})}_{k,n}
    \le
    C_{\mathrm{lad}} n^{\tau_{\mathrm{lad}}}2^{-q\beta k}.
\end{equation}
In particular,
\begin{equation}
    A^{(q,\alpha_{\mathrm{gr}})}_{n,n}
    \le
    C_{\mathrm{lad}} n^{\tau_{\mathrm{lad}}}2^{-q\beta n}
    \qquad(n\ge n_0).
\end{equation}

