[Theorem 1 of arXiv:2608.27398, 'Strict Stability and Strict Minimality of Regular Area-Minimizing Hypercones: A Quantitati'] There exists a constant $c_{\C}>0$ such that, for every $R>0$ and every set
$F\subset\R^{n+1}$ of locally finite perimeter satisfying
$F\mathbin\triangle E\Subset B_R$,
\begin{equation}
    \frac{D_R(F)}{R^n}
    \geq
    c_{\C}
    \left(
        \frac{\cL^{n+1}(F\mathbin\triangle E)}{R^{n+1}}
    \right)^2.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:master-generating of arXiv:2609.02544, 'A finiteness theorem for geodesic Leech wheels'] A geodesic Leech labeling satisfies the following identity.
\begin{equation}
  \sum_{r=1}^{N}z^r
  =P_A(z)+P_B(z)+C_B(z)
  +\frac{P_A(z)^2-P_A(z^2)}2-C_A(z).
\end{equation}

[Definition def-weak-solution-skeleton-equation of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] Let $\theta_0\in H^{\alpha-2\beta}(\mathbb{T}^2)$ and $g\in L^2([0,T];H)$. We say that $\theta$ is a weak solution of (equation PDE-SQG of the paper) with initial data $\theta_0$ if 

	(i)
	$
	\theta\in  L^\infty([0,T];H^{\alpha-2\beta}(\mathbb{T}^2)) \cap  L^2([0,T];H^{2\alpha-2\beta}(\mathbb{T}^2))\cap C([0,T];H_w^{\alpha-2\beta}(\mathbb{T}^2)).
	$

	(ii) For every $\varphi\in  C^\infty([0,T];H^\infty(\mathbb{T}^2))$, for all $ t\in[0,T]$,
	\begin{equation}
		\begin{aligned}
			&\langle \theta(t),\varphi(t)\rangle=\langle \theta_0,\varphi(0)\rangle+\int^t_0\langle \theta,\partial_s\varphi\rangle \,\mathrm{d}s-\int^t_0\langle \theta,\Lambda^{2\alpha}\varphi\rangle  \,\mathrm{d}s\\&-\frac{1}{2}\int^t_0\left\langle R_2 \theta,\left[\Lambda, \partial_1 \varphi\right]\Lambda^{-1} \theta\right\rangle \,\mathrm{d} s+\frac{1}{2}\int_0^t\left\langle R_1 \theta  ,\left[\Lambda, \partial_2 \varphi\right]\Lambda^{-1} \theta\right\rangle \,\mathrm{d}s+\int^t_0\langle\Lambda^{2\beta}\varphi,g\rangle \,\mathrm{d}s.
		\end{aligned}
	\end{equation}

