[Theorem th: Naz_Sod of arXiv:2412.07690, 'A law of large numbers concerning the distribution of critical points of random Fourier se'] Fix $\ell\in {{\mathbb N}}_0$ and $\alpha\in (0,1)$. Suppose that $\EuScript{V}$ is an open subset of ${\mathbb R}^m$ and $X:\Omega\times \EuScript{V}\to{\mathbb R}$ is a  centered Gaussian function with covariance kernel  $\EuScript{K}_X$. Assume that $\EuScript{K}\in C^{2\ell+2}\big(\, \EuScript{V}\times \EuScript{V})$.  Then $X$ admits a $C^{\ell,\alpha}$-modification. Moreover, for every box $B\subset \EuScript{V}$ and every $p\geq 1$  there exists a constant $C_p=C(B,\EuScript{V},\ell,\alpha)$ such that
   \begin{equation}
   {\mathbb E}\big[\, \Vert X\Vert^p_{C^{\ell,\alpha}(B)}\,\big] \leq C\big\Vert\, \EuScript{K}_X\,\big\Vert^{p+1}_{C^{2\ell+2}(B\times B)},
  \end{equation}
   where $C^{k,\alpha}$  denotes the spaces of functions that are  $k$ times differentiable and the $k$-th differential is H\"{o}lder continuous with exponent $\alpha$.\nobreak\hfill\penalty250 \hbox{}\nobreak\hfill$\rlap{$\sqcap$}\sqcup$\vskip\aline (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:mainv1 of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $\gamma \in (0,1)$ and $(M^n , [\hat{h}])$ be the conformal infinity of an asymptotically hyperbolic manifold $(X^{n+1},g^+ )$ such that $\Lambda_{\gamma} (M,[\hat{h}]) < \Lambda_{\gamma} (\mathbb{S}^n ,[h_{0}])$. Then, there exist constants $C>0$ and $\theta \geq 0$ such that
    \begin{align*}
        I_{\gamma} [w,\hat{h}]  - \Lambda_{\gamma} (M,[\hat{h}]) \geq C d(w,\mathcal{M})^{2+\theta} \quad \forall w \in H^{\gamma}(M,\mathbb{R}_+),
    \end{align*}
    where
    \begin{align*}
        d(w,\mathcal{M}) := \frac{\inf \{\|w-u\|_{H^{\gamma}(M)} : u \in \mathcal{M} \} }{\|w\|_{H^{\gamma}(M)}},
    \end{align*}
    and $\mathcal{M}$ is the set of minimizers of $I_{\gamma}[-,\hat{h}]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 40 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] [\cite{splitting}, Lemma 3.3] 
	Let $(v_{N})_{N \in \N}$ be a sequence of functions defined on $\R^{d} \times [a,b]$ which satisfies the following conditions:
	\begin{enumerate}
		\item There exists $C> 0$ such that for all $N \in \N$ and $t \in [a,b]$,
		\begin{equation*}
			\norm{v_{N}(\cdot,t)}_{L^{1}(\R^{d})} \leq C \text{ and } \norm{v_{N}(\cdot,t)}_{L^{\infty}(\R^{d})} \leq C.
		\end{equation*}
		\item There exists a spatial modulus of continuity $\nu$ such that for all $N\in \N$ and $t \in [a,b]$,
		\begin{equation*}
			\norm{v_{N}(\cdot + y,t) - v_{N}(\cdot,t)}_{L^{1}(\R^{d})} \leq \nu(|y|).
		\end{equation*}
		\item There exists an approximate temporal modulus of continuity $\om$ such that for all $N \in \N$ and $s, t \in [a,b]$,
		\begin{equation*}
			\norm{v_{N}(\cdot,t) - v_{N}(\cdot,s)}_{L^{1}(\R^{d})} \leq \om(|t-s| + \tfrac{1}{N}).
		\end{equation*}
	\end{enumerate}
	Then $(v_{N})_{N\in \N}$ is compact in the strong topology of $L^{1}_{\loc}(\R^{d}\times[a,b])$. Moreover, if $v$ is an $L^{1}_{\loc}(\R^{d}\times[a,b])$-limit point of $(v_{N})_{N \in \N}$, then $v \in L^{1}(\R^{d}\times[a,b])\cap L^{\infty}(\R^{d}\times[a,b]) \cap C([a,b];L^{1}(\R^{d}))$, and $v$ has a spatial modulus of continuity $\nu$ on $\R^{d}\times[a,b]$ and $v$ has a temporal modulus of continuity $\om$ on $\R^{d}\times[a,b]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:exp prof of conv power of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $Q_{n}$ be a polynomial with real nonnegative roots of the form \begin{equation}
			Q_{n}(z)=\sum_{k=0}^{n}(-1)^{n-k}\binom{n}{k}b_{k,n}^nz^k
		\end{equation} and suppose for every $u\in (0,1)$ \begin{equation}
			\lim\limits_{n\rightarrow\infty} b_{\lfloor un\rfloor,n}=e^{\tilde{g}(u)}
		\end{equation} for some function $\tilde{g}:(0,1)\rightarrow\mathbb{R}$. Then, $\llbracket Q_{n}\rrbracket$ converges weakly to the probability measure $\mu$ on $[0,\infty)$ with $S$-transform \begin{equation}
			S_{\mu}(z)=e^{\tilde{g}'(1+z)},
		\end{equation} for $z\in(-1,0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:changingMass of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] For any $\lambda>0$, $\beta \geq 0$, there exists a unique $m \in (0,1)$, which arises as the solution to the gap equation
\begin{equation}
 \frac{m^{2}}{\lambda}+\bigg (1+\frac{2}{N} \bigg )\frac{1}{L^{2}}\sum_{ \xi \in \Lambda_{L}^{*}} \left(\frac{1}{1+|\xi|^{2} }-\frac{1}{m^{2}+|\xi|^{2} } \right)=-\beta,    \end{equation}
such that the probability measures $\nu^{N}_{L}$ and $\nu^{N}_{m,L}$, defined in (eq:defsec3 of the paper) and (def:LSMFinite of the paper) respectively, are equal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 (cMMSE-area inequality) of arXiv:2608.11031, 'A Bayesian Proof of the Bernoulli Theorem'] For every $\mu\in\cP(T)$,
\begin{equation}
  b(T)
  \ge
  \frac{1}{4\pi}
  \int_0^\infty \mathrm{cMMSE}_\mu(t)\,dt.

\end{equation}

