[Thm 5.1 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Let $(E,d)$ be a metric space whose induced topological space is Lusin, and let $\mu$ be a $\sigma$-finite Borel measure on $E$ with full support such that, for some constants $C_0>0$ and $\alpha>0$,
\begin{equation}
    \mu(B(x, r))\le C_0 r^\alpha,\quad \forall x\in E, r>0,
\end{equation}
where $B(x,r):=\{y\in E:d(y,x)<r\}$. Consider a Borel right process $X$ on $E$ whose transition function satisfies the absolute continuity condition (AC) with respect to $\mu$. Assume further that its transition density function satisfies the following sub-Gaussian upper bound estimate: 
\begin{equation}
p(t,x,y)\le \frac{C_1}{t^{\alpha/\beta}}\exp\left\{-C_2\left(\frac{d(x,y)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall  t>0, \, x,y\in E,
\end{equation}
for some $\beta>1$ and $C_1,C_2>0$. Then, for any $0<\delta<1$, there exists a constant $C_3>0$, depending only on $C_0, C_1, C_2, \alpha, \beta, \delta$ (not on $x$ or $B$), such that  
\begin{equation}
{\mathbb{P}}^x\left[\sigma_{B}\le t\right] \le C_3 \exp\left\{-C_2(1-\delta)\left(\frac{\widetilde d(x, B)}{t^{1/\beta}}\right)^{\beta/(\beta -1)}\right\}, \quad \forall t>0, \, x\in E, B\in \mathscr{B}^n(E),
\end{equation}
where $C_2$ is the same constant as in (equation subGaussianHKUB of the paper) and $\widetilde{d}(x,B)$ is defined as (equation eq:63 of the paper).

[Corollary 5 of arXiv:2512.19517, 'Spiking and Resetting'] For any $t>0$ and any $0<a\le b\le1$, the probability distribution $P^\varepsilon_c( \cdot \, : \, t,a,b)$ over $\mathbb N_0$ converges in law to a Poisson distribution with parameter 
\begin{equation}

\begin{split}
f(0) \, t\,  \lambda_* ( [a,b]) = f(0)\,  t \, \int_a^b \cfrac{dx}{x^2} = f(0) \, t \,  (a^{-1}- b^{-1}) \  . 
\end{split}
\end{equation}
Furthermore, we have that, for any $n\ge 0$, the function
\begin{equation}

\begin{split}
\Phi_n^\varepsilon: r \in[0,\infty) \mapsto \mathbb P ( e_1^\varepsilon \ge r, N^\varepsilon_{(0,r]} ([a,b]) = n) \in [0,1]
\end{split}
\end{equation}
converges uniformly on any compact interval $[0,t]$, $t>0$, as $\varepsilon$ vanishes to 
\begin{equation}

\begin{split}
\Phi_n: r \in [0,\infty) \mapsto e^{-r f(0)} e^{-r \lambda_* ([a,b]} \frac{(r \lambda_* ([a,b]))^n}{n!} \in [0,1] \ .
\end{split}
\end{equation}

