[Lem conditionalwalk2 of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] Fix $h>0$, $x>0$. As  $N\rightarrow\infty$, we have
    \begin{equation}
    \begin{split}
        &N^{2/3}\cdot\frac{|\mathcal{W}(\lfloor h\sigma N^{1/3}\rfloor,0,\lfloor xN^{2/3}\rfloor ;N)|}{V_{N}(z_{c}(N))^{\lfloor xN^{2/3}\rfloor}}\rightarrow (2P_{-1})^{-1}\cdot \mathbf{F}_{0}(x,h),\\
        &N^{2/3}\cdot\frac{|\mathcal{W}(0,\lfloor h\sigma N^{1/3}\rfloor,\lfloor xN^{2/3}\rfloor ;N)|}{V_{N}(z_{c}(N))^{\lfloor xN^{2/3}\rfloor}}\rightarrow \sigma^{-2}\cdot \mathbf{F}_{0}(x,h),\\
        &N\cdot \frac{|\mathcal{W}(0,0,\lfloor xN^{2/3}\rfloor;N)|}{V_{N}(z_{c}(N))^{\lfloor x N^{2/3}\rfloor}}\to(2P_{-1}\sigma)^{-1}\mathbf{F}_{0,0}(x).
        \end{split}
    \end{equation}

