[Lemma 17 of arXiv:2606.09691, '\textsc{Degenerate Diffusions on Continuum Percolation and Hamilton-Jacobi-Bellman Equatio'] Under Assumptions \ref{f1} and \ref{f2}--\ref{f4}, for every $T>0$ there exists a constant $\bar C_{T,f}$ such that
\begin{equation}
|V_f(t,x)|
\leq
\bar C_{T,f}(1+|x|)
\qquad
\text{for all }
(t,x)\in[0,T]\times\mathcal C_\infty(\omega).
\end{equation}

Moreover, if $f$ is uniformly bounded, then there exists
$\bar C_{T,f}>0$ such that
\begin{equation}
|V_f(t,x)|
\leq
\bar C_{T,f}
\qquad
\text{for all }
(t,x)\in[0,T]\times\mathcal C_\infty(\omega).
\end{equation}

[Lemma 4 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] We have the asymptotic as $z\to 0$: 
\begin{equation} 
	H_1(t;z) = \frac{2}{z} + \LE(t) z + O(z^3), \quad \text{as } z \to 0, 
\end{equation}
where $\LE$ is defined in~\eqref{eqn::Def_LE}.

[Theoremletter Thm:Neumayer of arXiv:2609.00324, 'Quantitative Stability for Fractional Yamabe minimizers'] Let $(M,g)$ be a closed Riemannian manifold of dimension $n\geq 3$ that is not conformally equivalent to the round sphere. Then, there exist constants $C>0$ and $\theta\geq 0$, depending on $(M,g)$, such that
    \begin{align*}
        Q(u)-Y(M,[g]) \geq C d(u,\mathcal{M})^{2+\theta} \quad \forall u \in H^1 (M,\mathbb{R}_+ ),
    \end{align*}
    where $d(-,\mathcal{M})$ is a suitable distance to the set of minimizers $\mathcal{M}$. Moreover, there exists an open dense subset $\mathcal{G}$ in the $C^2$ topology on the space of smooth conformal classes of metrics on $M$ such that if $[g]\in \mathcal{G}$ then $\theta = 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma est of arXiv:2412.09471, 'On the moderate deviation principles in the sparse multi-type Erd\H{o}s R\'enyi random gra'] For any $n\in{\mathbb N}$ and $k\in {\mathbb N}^d$,
    \begin{equation}
    \left(1-\frac{\Vert\kappa\Vert_\infty}{n}\right)^{\frac{|k|^2}2}\leq\frac{p_n(k)}{n^{1-|k|}\tau(k)}\leq 1,
    \end{equation}
    where $\tau(k)$ is defined in~(equation tau(k) of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

