[Definition def:finite boxplus of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $p_n$ and $q_n$ be degree $n$ monic polynomials with corresponding polynomials  $P_n$ and $Q_{n}$ of degree $n$ such that $p_n(z)=P_n(\partial_{z})z^{n}$ and $q_{n}(z)=Q_n(\partial_{z})z^n$, respectively.  
	Then, the finite free additive convolution  of $p_n$ and $q_n$ is the unique degree $n$ polynomial $p_n\boxplus_{n}q_n$ such that \begin{equation}
		p_n\boxplus_{n}q_{n}(z)=Q_n(\partial_{z})P_n(\partial_{z})z^n=Q_{n}(\partial_{z})p_n(z)=P_{n}(\partial_z)q_n(z).
	\end{equation}
	Equivalently, if $p_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(p_n)\binom{n}{k}z^{n-k}$ and $q_n(z)=\sum_{k=0}^{n}(-1)^{k}e_{k}(q_n)\binom{n}{k}z^{n-k}$, then \begin{equation*}
		p_n\boxplus_{n}q_n(z)=\sum_{k=0}^{n}z^{n-k}(-1)^{k}\binom{n}{k}\Bigg(\sum_{j=0}^k\binom k j  e_{j}(p_n)e_{k-j}(q_n)\Bigg) . 
	\end{equation*}

[Definition 6 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $x \in V \otimes V$ be arbitrary.
\begin{enumerate}
\item We call $x$ \emph{symmetric} if $x^* = x$.

\item We call $x$ \emph{antisymmetric} if $x^* = -x$.
\end{enumerate}

[Proposition p:skewBM RK ii of arXiv:2411.04773, 'Meeting of squared Bessel flow lines and application to the skew Brownian motion'] For any $r\ge 0$, a.s.
    \begin{equation}
        L^{-r}_{\tau^0_z} = \inf\{x\in [-r,z)\,:\, \widehat {\mathcal S}^+_{x,z}\circ \mathcal S_{-r,x}^+(0)>0\} \land z.
    \end{equation}
    As a result,  $(L^{-r}_{\tau^0_z},\, r\ge 0)$ is distributed as the process $(V(-r),\, r\ge 0)$ of Section (s:meeting* of the paper) with $(2+\delta,0)$ in place of $(\delta,\widehat{\delta})$ and Theorem (thm: skewBM RK of the paper) (ii) holds.

