[Lemma lem:blockwise_J of arXiv:2604.10214, 'Large deviations for maximum local time of simple random walk in dimensions \texorpdfstrin'] Uniformly for \(i\in[1,K]\), \(k\in I_i\), an index set \(J\) with decomposition
(equation eq:J_decomposition of the paper), and \(t_0,\dots,t_m\in\mathbb R_+\), we have
\begin{equation}
\begin{aligned}
    &\mathbb Q\Bigl(
\widetilde{\ell}(J_r,S_k)\ge t_r\ \forall\,r=0,\ldots,m,\ \mathcal J_{S_k}=J
\Bigr)\\
\lesssim\,&
\left[
\prod_{r=1}^{m}
\frac{n^{\beta_1}}{\bigl((i_{2r}-i_{2r-1}-1)n^{\beta_2}\bigr)^{d/2}}
\right]
\exp\Bigl\{-\gamma\sum_{r=0}^{m}t_r\Bigr\}. 
\end{aligned}   
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 (Local maximum at equal
radii) of arXiv:2608.06591, 'Random Triangles on Concentric Circles'] \protect\hypertarget{prp-local}{}

Normalize the squared radii to \(a_k = r_k^2\) with
\(a_1 + a_2 + a_3 = 3\) and write \(a_k = 1 + \alpha_k\). Then, as
\(\alpha \to 0\), \begin{equation}\phantomsection{
P(\text{obtuse}) = \frac{3}{4} - \frac{1}{4\pi^2}\sum_{k<l}
  (\alpha_k - \alpha_l)^2 \log\frac{1}{\lvert \alpha_k - \alpha_l \rvert}
  + O\!\left(\lvert\alpha\rvert^2\right) ,
}\end{equation} where a vanishing difference contributes nothing to the
sum. In particular \(3/4\) is a strict local maximum over radius ratios,
attained only at \(r_1 = r_2 = r_3\), and \(P\) is differentiable but
not twice differentiable there. The remainder is uniform in the
direction of \(\alpha\); Lemma~\ref{lem-endpoint} supplies the exact
endpoint decomposition on which that rests. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2605.29608, '2605.29608'] Let $(\{Y_{k}\}_{k\in\mathbb{Z}^{+}},\mathbb{P})$ be the Markov chain generated by the Wolff dynamics, and let  $\mu_{N}$ denote the Gibbs measure of the 1D Ising model defined in Equation~\eqref{eq:isinggibbs}. Then the following conclusions hold.
	\begin{enumerate}
		\item For $\hat{J}\in(0,+\infty)$, consider a configuration $\sigma\in\Omega$ and a connected subset $A\subset[N]$ such that $\sigma_i\sigma_j=+1$ for all $i,j\in A$. The transition probability  $P_{\text{W}}(\sigma,\sigma^{A})$ is then given by
		\begin{equation}\begin{split}
				P_{\text{W}}(\sigma,\sigma^{A})
				:=&	\mathbb{P}(Y_{2}=\sigma^{A}\mid Y_{1}=\sigma)\\
				=&\frac{\#\{A\}}{N}\begin{cases}
					\kappa^{\#\{A\}-1}\hat{\kappa}^{2}, & \#\{\partial A\cap\mathcal{B}_{+}^{\sigma}\}=2,  \\
					\kappa^{\#\{A\}-1}\hat{\kappa}, & \#\{\partial A\cap\mathcal{B}_{+}^{\sigma}\}=1,  \\
					\kappa^{\#\{A\}-1}, & \partial A\subset\mathcal{B}_{-}^{\sigma},\#\{\partial A\}\neq0,\\
					(N\hat{\kappa}+\kappa)\kappa^{N-1}, & \tilde{\mathcal{C}}^{\sigma} \tilde{\mathcal{D}}^{\sigma}=0, \#\{A\}=N,
				\end{cases}
			\end{split}
		\end{equation}
		where $\kappa=1-e^{-2\hat{J}}$ and $\hat{\kappa}=e^{-2\hat{J}}$.
		Moreover, $P_{\text{W}}(\sigma,\sigma^{A})$ admits a more detailed representation in terms of the connected components

















		\begin{align}
			P_{\text{W}}(\sigma,\sigma^{A})
			=\frac{\#\{A\}}{N}
			\begin{cases}
				1, 
				& \exists r:\ A\subset\mathcal{K}_r^\sigma,\ 
				\#\{\hat{\partial}\mathcal{K}_r^\sigma\}=1,\\[4pt]
				\kappa^{\#\{A\}-1}\hat{\kappa}^{2}, 
				& \exists r:\ A\subset\mathcal{K}_r^\sigma,\ 
				\#\{\hat{\partial}\mathcal{K}_r^\sigma\}=2,\ \#\{A\cap\hat{\partial}\mathcal{K}_{r}^{\sigma}\}=0,\\[4pt]
				\kappa^{\#\{A\}-1}\hat{\kappa}, 
				& \exists r:\ A\subset\mathcal{K}_r^\sigma,\ 
				\#\{\hat{\partial}\mathcal{K}_r^\sigma\}=2,\
				\#\{A\cap\hat{\partial}\mathcal{K}_{r}^{\sigma}\}=1,\\[4pt]
				\kappa^{\#\{A\}-1}, 
				& \exists r:\ A\subset\mathcal{K}_r^\sigma,\
				\#\{A\cap\hat{\partial}\mathcal{K}_{r}^{\sigma}\}=2,\\[4pt]
				\kappa^{\#\{A\}-1}\hat{\kappa}^{2}, 
				& \tilde{\mathcal C}^\sigma\tilde{\mathcal D}^\sigma=0,\ \#\{A\}\leq N-1,\\[4pt]
				(N\hat{\kappa}+\kappa)\kappa^{N-1}, 
				& \tilde{\mathcal C}^\sigma\tilde{\mathcal D}^\sigma=0,\ \#\{A\}=N,
			\end{cases}
		\end{align}	
		where
		\begin{align*}
			\mathcal{K}_r^\sigma\in\{\mathcal{C}_{r}^{\sigma},\mathcal{D}_{r}^{\sigma}\}.
		\end{align*}
		If $A$ is not connected, or if $A\subset[N]$ fails to satisfy $\sigma_i\sigma_j=+1$ for all $i,j\in A$, then 
		\begin{align*}
			P_{\text{W}}(\sigma,\sigma^{A})=\mathbb{P}(Y_{2}=\sigma^{A}\mid Y_{1}=\sigma)=0.
		\end{align*}
		In addition, for $\hat{J}=0$, we have $P_{\text{W}}(\sigma,\sigma^{A})=0$ for all $\#\{A\}\geq 2$ and for $A=\{i\}\subset[N]$, the transition probability reduces to
		\begin{equation}
			P_{\text{W}}(\sigma,\sigma^{i}):=P_{\text{W}}(\sigma,\sigma^{\{i\}})
			=\frac{1}{N}.
		\end{equation}
		Hence, when $\hat{J}=0$, the Wolff dynamics reduces to the simple random walk on the hypercube $\Omega=\{-1,+1\}^{N}$. 
		\item 
		For $\hat{J}\in [0,+\infty)$, the transition kernel $P_{\text{W}}$ satisfies the following detailed balance condition
		\begin{align*}	
			\mu_{N}(\eta)P_{\text{W}}(\eta,\sigma)=\mu_{N}(\sigma)P_{\text{W}}(\sigma,\eta),\qquad \eta,\sigma\in\Omega.
		\end{align*}
	\end{enumerate}

