[Thm dinh ly 6 of arXiv:2411.04081, 'A Multi-level Monte Carlo simulation for invariant distribution of Markovian switching L\''] Assume that \textbf{C4} holds with $q = 4p_0$ and  $p_0 \geq 2\max\{ l+ 3, 2m + 2\}$. Assume that   $\sigma_\Delta$ and $\gamma_\Delta$ satisfy (equation T3T4 of the paper), (equation cdelta of the paper), (equation T5 of the paper). Moreover, assume that 
 there exists a positive constant $L_4$ such that for all $i \in S; x \in \mathbb{R}^d$,
	\begin{align} 
		|\sigma(i,x)-\sigma_{\Delta}(i,x)| \le L_4 \Delta^{1/2}|\sigma(i,x)|^2,\qquad |\gamma(i,x)-\gamma_{\Delta}(i,x)| \le L_4 \Delta^{1/2} |\gamma(i,x)|^2(1+|b(i,x)|). 
	\end{align}
Then for any $T>0$, there exist  positive constants  $K_T$ and $K'_T$ such that
	\begin{equation} 
	\underset{0 \le t \le T}{\sup} \mathbb{E} \left[  |\widehat{X}_t - X_t|^2 \right] \le  K_T \Delta,
	\end{equation}
and for any $p\in (0,2)$,
	\begin{equation} 
	 \mathbb{E} \left[ \underset{0 \le t \le T}{\sup} |\widehat{X}_t - X_t|^p \right] \le  \left(\dfrac{4-p}{2-p}\right) (K'_T\Delta)^{p/2}.
	\end{equation}
	Moreover, when  $\widetilde{{\zeta_0}} < 0$ and $\alpha < 0$, there exists a positive constant  $K$, which does not depend on $T$,  such that
	\begin{equation} 
	\underset{t \ge 0}{\sup}\ \mathbb{E} \left[  |\widehat{X}_t - X_t|^2 \right] \le  K \Delta.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 (Spectral decomposition of Liouville heat kernel) of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] For all $t\ge 0$, all $x \in \Sigma$, almost surely and for $\mu_\ph-$almost every $y \in \Sigma$ we have
\begin{equation}
\mathbf{p}_t (x,y) = \sum_{n=1}^\infty e^{-\bl_n t} \ef_n(x) \ef_n(y). 
\end{equation}
The series on the right hand side converges a.s. uniformly on $(\eps, \infty) \times \Sigma \times \Sigma$ for any $\eps>0$. As a result, there is a (necessarily unique) \emph{jointly continuous} version of the Liouville heat kernel $\mathbf{p}_t(x,y)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $(\rho,\Theta)$ be the underlying MAP of $\mathcal{R}$ from (\ref{ssMp_item_d_specific}) with respect to the norm  $\|\cdot\|_1$. Then, the operator $A:\mathcal{D}\to C^2_b(\mathbb{R}\times\mathcal{S}^{d,+}_{1})$, where $\mathcal{D}$ is the collection of functions from (\ref{def:8zillion}), is given by
	\begin{align*}
		Af(x,\boldsymbol{\theta})&= \sum_{i=0}^d b_i(\boldsymbol{\theta})\frac{\partial f}{\partial y_i}(x,\boldsymbol{\theta}) + \frac{1}{2}\sum_{i,j=0}^d a_{ij}(\boldsymbol{\theta})\frac{\partial^2 f}{\partial y_i\partial y_j}(x,\boldsymbol{\theta}),
	\end{align*}
	where for $\boldsymbol{\theta}=(\theta_1,\ldots,\theta_d)\in\mathcal{S}^{d,+}_{1}$ and  $1\leq i\leq d$,
	\begin{equation*}
		b_0(\boldsymbol{\theta})=-\frac{d}{2},\quad b_i(\boldsymbol{\theta})=d\theta_i-1,\quad a_{00}(\boldsymbol{\theta})= d,\quad a_{ii}(\boldsymbol{\theta})=(1-\theta_i)^2+(d-1)\theta_i^2,\quad a_{0i}(\boldsymbol{\theta})=a_{i0}(\boldsymbol{\theta})= 1-d\theta_i,
	\end{equation*}

	\begin{equation*}
		a_{ij}(\boldsymbol{\theta})=a_{ji}(\boldsymbol{\theta})= d\theta_i\theta_j-\theta_i-\theta_j,\qquad i,j\in\{1,\ldots,d\},\enspace i\neq j,
	\end{equation*}
solves the martingale problem for $(\rho,\Theta)$.

