[Lem 138 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Adopt the notation and assumptions of \Cref{cor:cella2}, and denote
  	\begin{flalign}
		\widetilde{\mathcal{H}} (\hat{x}, \hat{y}) = \mathfrak{d}^{-2} \mathcal{H}_{q;a,b,c} (x, y). 
	\end{flalign}
	\noindent Then, we have $\widetilde\cH(\hat{x},\hat{y})=\frak H_{q,\gamma'',\gamma'''}(\hat x,\hat y)+\mathcal O(\md^2)$, where
  {  \begin{multline}
     \frak H_{q,\gamma'',\gamma'''}(\hat x,\hat y)=\mathtt H_{\gamma''}(\hat x,\hat y)        + \frac{\mathfrak d}{\pi\sqrt{\gamma''}}
        \left[
            \left(\frac{\gamma''}{3}-\frac{q}{6}+\frac{2\gamma'''}{9\gamma''}\right) (2\hat{y}-\gamma''\hat{x}^2)^{3/2}
            - \frac{\gamma'''}{3\gamma''} \hat{y}\sqrt{2\hat{y}-\gamma''\hat{x}^2}
        \right],\\
\mathtt H_{\gamma''}(\hat x,\hat y)
        = \displaystyle\frac{\hat{y}}{2}
        - \frac{1}{\pi}\left[
            \frac{\hat{x}}{2}\sqrt{\gamma''}\,\sqrt{2\hat{y}-\gamma''\hat{x}^2}
            + \hat{y}\,\arctan\!\left(\frac{\sqrt{\gamma''} \hat{x}}{\sqrt{2\hat{y}-\gamma''\hat{x}^2}}\right)
        \right].
    \end{multline}
} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:limit_uniq of arXiv:2411.09482, 'Anomalous Regularization in Kazantsev-Kraichnan Model'] Assume $d\ge 2$, $s\in (0,d/2)$ and $\alpha\in (0,1)$, let $M_0$ be in $\dot{H}^{-s}$. Let $M$ be a solution to (equation eq:KK of the paper) (in the sense of (def:sol of the paper)) which is also in $L^2_{t,\omega}(H^{-s}))$. For every $\delta>0$ and $R>0$, we have
    \begin{align}
    \begin{aligned}
        \mathbb{E} \int_{\mathbb{R}^d} &|\widehat{M}^R_t(n)|^2 \widehat{G_\delta}(n) \,\mathrm{d} n -\int_{\mathbb{R}^d} |\widehat{M}_0(n)|^2 \widehat{G_\delta}(n) \,\mathrm{d} n \\
        &= (2\pi)^{-d/2}\mathbb{E} \int_0^{t\wedge \tau_R} \int_{\mathbb{R}^d} \overline{\widehat{M}}_r(n) \cdot \mathbb H_\delta(n)\widehat{M}_r(n) \,\mathrm{d} n \,\mathrm{d} r,
    \end{aligned}
    \end{align}
    where
    \begin{align*}
        \mathbb H_\delta(n) &= \mathbb F_{\gamma_\delta}(n) -(2\pi)^{d/2}c_0|n|^{-2s+2}I \\
        &= \int_{\mathbb{R}^d} \langle n-k \rangle^{-d-2\alpha} (\varphi_\delta(k)|k|^{-2s}-\varphi_\delta(n)|n|^{-2s}) |P^\perp_{n-k}k|^2 I \,\mathrm{d} k \\
        &\quad +(d-1)\int_{\mathbb{R}^d} \langle n-k \rangle^{-d-2\alpha} \varphi_\delta(k)|k|^{-2s} kk^\top \,\mathrm{d} k \\
        &\quad -2\int_{\mathbb{R}^d} \langle n-k \rangle^{-d-2\alpha} \varphi_\delta(k)|k|^{-2s} P^\perp_{n-k} kk^\top \,\mathrm{d} k
    \end{align*}
    and $\mathbb F_{\gamma_\delta}$ is defined in (equation eq:F_gamma of the paper) with $\gamma_\delta(\,\mathrm{d} n) =\hat{G}_\delta (n)\,\mathrm{d} n$.

