body:
[Lemma 11 of arXiv:2607.01629, 'Quadratic fluctuations of speed-change Kawasaki dynamics'] For every test function $f$, we have the following moment estimates for the remainder term $\mathcal R_1^N$:
		\begin{align*}
			&N^2\sum_{i=1}^d\sum_{x}\E_{\rho}\left[\mathcal R_{1}^N(f,x,i)^2\right]
			\leq C_{f}\left(N^{-2}L^2+N^{-d}L^{d+2}\right),
		\end{align*}
		and
		\begin{multline*}
			\quad N^4\sum_{i=1}^d\sum_{x}\E_{\rho}\left[\mathcal R_{1}^N(f,x,i)^4\right]\\
			\leq C_{f}N^{-d}\left(N^{-4}L^4+N^{-2-d}L^{d+3}+N^{-2d}L^{2d+3}+\left(N^{-4-d}L^{-2d}+N^{-2d}L^{-1}\right)\Vert \phi_L\Vert_\infty^4\right)\notag.
		\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\chi\in\Pi(G_1)$ and $\varphi\in\1_{n-2}\boxplus\chi\boxplus\chi^{-1}$ be $(s,z)$-independent.
		Also, recall
		\optionA{$\P_v(\lambda;\varphi_v,f_v,f_{v,s})$}
		\optionB{$\P_v(s,\lambda;\varphi_v,\Phi_v)$} from \eqref{eq:main-RS-period-local} and $\lambda_{\mathrm{C}}(s,z)$ from \eqref{eq:def-lambda-cont}. Then
		\begin{equation*}
			\optionA{\frac{\P_v(-\lambda_{\mathrm{C}}(s,z);\varphi_v,f_v,f_{v,s})L_v(1+2z,\chi_v^2)}
				{\prod_{\pm}L_v\left(\tfrac{n-1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)
					L_v\left(\tfrac{1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)}}
			\optionB{\frac{\P_v(s,-\lambda_{\mathrm{C}}(s,z);\varphi_v,\Phi_v)L_v(1+2z,\chi_v^2)}
				{\prod_{\pm}L_v\left(\tfrac{n-1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)
					L_v\left(\tfrac{1}{2}+\tfrac{n}{2}s\pm z,\chi^\pm_v\right)}}
		\end{equation*}
		can be analytically continued in $s,z\in\C^2$ as an entire function.

