[Proposition Prop.BDG of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] For two constants $p\geq 1$ and $T>0$, assume that
   \begin{eqnarray*}
 	\sup_{t\in[0,T]}\mathbf{E}\Big[\big|X(t)\big|^{p}\Big]<\infty
 	\quad \mbox{and}\quad 
 	\int_0^T ds \int_0^\infty \big|g(s,y)\big|^{2p}\mu(dy) <\infty.
   \end{eqnarray*}
  Then there exists a constant $C>0$ depending only on $p$ such that
   \begin{eqnarray} 
 	\sup_{t\in[0,T]}\mathbf{E}\Big[ \big| B(f,t) \big|^{2p}  \Big] 
 	\leq C\cdot \sup_{t\in[0,T]}\mathbf{E} \Big[\big|X(t)\big|^p \Big] \cdot \bigg| \int_0^T   \big|f(s)\big|^{2} ds  \bigg|^{p}
   \end{eqnarray}
  and 
   \begin{eqnarray} 
 	\sup_{t\in[0,T]}\mathbf{E}\Big[ \big| \widetilde{N}(g,t) \big|^{2p}  \Big] 

 	\!\!\!&\leq\!\!\!& C  \cdot \sup_{t\in[0,T]}\mathbf{E} \Big[\big|X(t)\big|^p \Big] \cdot \bigg| \int_0^T ds \int_0^\infty\big|g(s,y)\big|^{2} \mu(dy)  \bigg|^{p} \cr
 	\!\!\!&\!\!\!& + C \cdot \sup_{t\in[0,T]}\mathbf{E}\Big[\big|X(t)\big|\Big]\cdot \int_0^T ds \int_0^\infty\big|g(s,y)\big|^{2p} \mu(dy) .
   \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 16 (Euclidean exit interval) of arXiv:2608.26834, 'Small-time annealed large deviations principle for one-dimensional diffusions in a random '] Set
		\begin{align*}
		r_W(x,R):=\min\Biggl\{&
		\int_{x-R}^{x}\sqrt{\frac{\exp\{\rho(z,W)-a(z,W)\}}{2}}\,\dd z,\\
		&\int_x^{x+R}\sqrt{\frac{\exp\{\rho(z,W)-a(z,W)\}}{2}}\,\dd z
		\Biggr\}.
		\end{align*}
		There exist positive constants $C,N$ such that, for every $x\in\R$, $R>0$, and $0<t\le1$,
		\begin{equation*}
			P_x^W\left(\tau_{(x-R,x+R)}\le t\right)
			\le Ct^{-N}e^{CM((x-R,x+R))}
			\exp\left\{-a_\theta\frac{r_W(x,R)^2}{t}\right\}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem septhm of arXiv:2412.08334, 'Maker-Breaker on Galton-Watson trees'] If the offspring distribution is separable, i.e.\ $\xi\stackrel{d}{=}X_1+X_2$ with i.i.d.\ $(X_1,X_2)$, and $\mathbb{E}\,\xi>2$ then the probabilities of Breaker winning on the corresponding GW-tree with the nodes carrying no further information is given by
 \begin{equation}
 	p=\rho\,\bigg(1-\frac{\sigma\cdot\rho_\mathrm{odd}}{1-\theta\cdot(1-\theta_\mathrm{odd})}\bigg)
 \end{equation}
and
\begin{equation}
	\bar{p}=\rho^2\,\bigg(1-\frac{2\sigma\cdot\rho_\mathrm{odd}\,(1-\rho_\mathrm{odd})}{1-\theta\cdot(1-\theta_\mathrm{odd})}\bigg)
\end{equation}
depending on whether Breaker or Maker starts the game.

 The (conditional) probabilities $\rho$, $\sigma$ and $\theta$ as well as $\rho_\mathrm{odd}$ and $\theta_\mathrm{odd}$  appearing here refer to the ones introduced in (equation probs of the paper), corresponding to the left-continuous random walk on $\mathbb{Z}$ starting at $0$ with i.i.d.\ increments distributed as $X_1-1$.

[Lemma lem:discrete-L of arXiv:2604.04882, 'On a Problem of M. Kac on Laplace Distributions'] Let $L:[0,\infty)\to(0,1]$ be injective and completely monotone with $L(0)=1$. If $\eta\in\cB$ and $a\ge 0$, then
    \begin{align}
        G_a^\eta(z)\coloneqq L(a\eta(1-z)), \qquad |z|\le 1,
    \end{align}
    is a probability generating function.

