	\end{align}  
	\end{subequations}
We define the \emph{array of velocity variables} by:
	\begin{align} 
		\velocityarray \eqdef (v^1,v^2,v^3).
	\end{align}

We define the \emph{array of small velocity variables} by:
	\begin{align} 
		\velocityarraypartial \eqdef (v^2,v^3)
	\end{align}

