In particular,    in a  measurable subset of full $\mathbf{N}^*_x$  measure, the process $(L^*_t: t \geq 0)$ is  continuous, non-decreasing and null at $0$.

[Defi of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] [AGS08]
    Let $(S,d)$ be a metric space and $F:S\to (-\infty,\infty]$ measurable. Let $D(F):=\{s\in S\mid F(s)<\infty\}$ be the domain of $F$. The local slope $ \left\lvert\partial  F\right\rvert$ of $F$ is defined by \begin{align*}
        \left\lvert\partial  F\right\rvert(s):=\limsup_{s'\to s}\frac{(F(s)-F(s'))_+}{d(s,s')},\quad \forall s\in D(F).
    \end{align*}

[Theorem Thm: pgf of X of arXiv:2411.10296, 'Parking on a random rooted binary tree'] Let X be the number of cars that visit the root of a BGW(2,1/2) tree with, for some $\alpha > 0$, an independent $Po(\alpha)$ number of cars initially choosing each vertex. Write $p \coloneq \mathds{P}(X=0)$.
    \begin{enumerate}
        \item For $0 \leq \alpha \leq 2 - \sqrt{2}$, the probability generating function of X is
        \[G(s) = 1 - \alpha + s(2 - \alpha) + 2s^2 e^{\alpha (1-s)} + 2s e^{\alpha (1-s)} \sqrt{s^2 - e^{\alpha (s-1)} (1 - \alpha + s(2 - \alpha))}.\]
        Furthermore, $p = 1 - \alpha$ and $\mathds{E}[X] = 2 - \alpha - \sqrt{2(\alpha^2 - 4\alpha + 2)}$.
        \item For $\alpha > 2 - \sqrt{2}$, the probability generating function of X is





        \begin{align*}
            G(s) &= p + s(1-p) + 2s^2 e^{\alpha (1-s)} \\
            &+ \begin{cases} 
             2s e^{\alpha (1-s)} \sqrt{s^2 - e^{\alpha (s-1)} (p + s(1+p))}, & 0 \leq s \leq s_p \\
            - 2s e^{\alpha (1-s)} \sqrt{s^2 - e^{\alpha (s-1)} (p + s(1+p))}, & s_p < s \leq 1,
            \end{cases}
        \end{align*}
        where $s_p = \frac{1 + (1+\alpha)p - \sqrt{(1 + (1+\alpha)p)^2 - 8\alpha p(1+p)}}{2\alpha(1+p)}$. Furthermore, $p > 1-\alpha$ and $\mathds{E}[X] = \infty$.
        \item If $\alpha > 2 - \sqrt{2}$, then $\frac{e^{-\alpha}}{4} \lor (1 - \alpha) < p < c(\alpha)$ where
        \[
        c(\alpha) \coloneq 
        \begin{cases}
            \frac{(3 - 2\sqrt{2})\alpha - 1}{\alpha^2 - 6\alpha + 1} & \alpha \neq 3 + 2\sqrt{2} \\
            \frac{3\sqrt{2} - 4}{8} & \alpha = 3 + 2\sqrt{2}.
        \end{cases}
        \]
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:locally dissipative of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] The equation (equation eq:mvsystem of the paper) is called locally dissipative at $a\in\mathbb R$ with configuration $(r,g)$, if
\begin{enumerate}[label=(\roman*)]
\item the function $g:\mathbb R_+\times\mathbb R_+\to\mathbb R$ satisfies, for all $x\in\mathbb R$, $\mu\in\mathcal P_2(\mathbb R)$,
\begin{equation*}
-2xV'(x+a)-2x(W'*\mu)(x)+\sigma^2(x+a)\leq -g(x^2,\|\mu\|_2^2);
\end{equation*}
\item the number $r>0$ and the function $g$ satisfy
\begin{equation*}
\begin{split}
&g(\cdot,r^2) \text{ is continuous and convex};\\
&\inf_{0\leq w\leq r^2}g(z,w)=g(z,r^2);\\
&\inf_{z\geq r^2}g(z,r^2)>0.
\end{split}
\end{equation*}
\end{enumerate}

