[Lemma 38 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] Let $\nu$ be a supercritical offspring distribution whose mean is denoted by $\ttm_\nu$. 
 We assume that there exists $\ttb' \ino (1, \infty)$ such that $\mnu (\ttb' )\! := \!  \sum_{k\in \bbN} k^{\ttb '} \nu (k) \leko \infty$. 
For all rooted ordered tree $t\ino \bbT$ as in Definition \ref{Ulamtree}, we next set 
\begin{equation}

\mathtt U (t)= \liminf_{n\to \infty} \;  \mnu^{-n} \, \# \big\{ u \ino t : |u|\eqo n\big\} \in [0, \infty] \; .
\end{equation}
Here, $(\bT, \boo)$ is either a GW($\nu$)-tree as in Definition~\ref{GWfordef} $(\textbf a)$ (in this case: $\boo\eqo \varnothing$), or an infinite GW($\nu$)-tree as in Definition~\ref{GWptdef} $(\textbf b)$, or an invariant GW($\nu$)-tree as in 
Definition~\ref{definvRW}. 
For all $x\ino \bT$, we 
recall from (\ref{curshitr}) that the subtree $\theta_x \bT $ stemming from $x$ belongs to $\bbT$ and we set $U_x = \mathtt U (\theta_x \bT)$. Then the following holds true. 
\begin{compactenum}

\smallskip

\item[$(i)$]  $\bP$-a.s.~ for all $x\ino \bT$, 
\end{compactenum}
\begin{equation}

U_x \! = \! \lim_{n\to \infty} \;  \mnu^{-n} \, \# \big\{ y \ino \bT :  x\preceq y,\,\bbn y\bbn \eqo  \bbn x \bbn \! +\!  n \, \big\} \ino (0, \infty) \quad \textrm{and} \quad U_x = \frac{1}{\mnu}\!\!\!\! \!\! \!\! \!\!   \sum_{\qquad y\in \bT : \overleftarrow{y} = x} \!\! \!\! \!\! \!\!  \!\! U_y .
\end{equation}
\begin{compactenum}

\smallskip

\item[$(ii)$] Suppose that $\ttb\ino (1, \infty)$ is such that $\sum_{k\in \bbN} k^{\ttb} \nu (k) \leko \infty$. 
Then, 
$\bE [ U_\boo^\ttb]\leko \infty$ if $\bT$ is a GW($\nu$)-tree or an infinite  
GW($\nu$)-tree. If $\bT$ is 
an invariant GW($\nu$)-tree, then $\bE [ U_\boo^{\ttb-1}] \leko \infty$ if $\ttb \ino (2, \infty)$. 

\item[$(iii)$] The harmonic coordinates are the $\bbR$-valued r.v.~$(S_x)_{x\in \bT}$ defined by the following  
\end{compactenum}
\begin{equation}

S_\boo \eqo 0 \quad \textrm{and} \quad \forall x \ino \bT\backslash \{ \varnothing\} , \quad S_x \! -\! S_{\overleftarrow{x}}\eqo U_x  ,  
\end{equation}
\begin{compactenum}
\item[] on the event where (\ref{welldefcoo}) holds true and by $S_x \eqo 0$, $x\ino \bT$, on the $\bP$-negligible complementary event. 
Let $\overline{X}_n \eqo (\bT, X_n)$, $n\ino \bbN$, be a $\mathtt m_\nu$-biased RW such that $X_0 \eqo \boo$. We denote by $\ccF_{\! n}$ the $\sigma$-field generated by $(\overline{X}_k)_{0\leq k\leq n}$. Then $(S_{X_n})_{n\in \bbN}$ is a $(\ccF_{\! n})_{n\in \bbN}$-martingale:
\end{compactenum}
\begin{equation}

\textrm{$\bP$-a.s.~for all $n\in \bbN^*$, } \quad \bE  \big[ S_{X_{n+1} } \, \big| \, \ccF_{\! n} \big] = S_{X_{n}} 
\end{equation}

\item[$(iv)$] We keep the previous notation and for all $n\ino \bbN$, we set $\Delta_n\eqo  S_{X_{n+1} } \! -\!  S_{X_{n} }$ and 
$\Phi_\ttb (\overline{X}_n) \eqo  \bE  \big[ |\Delta_{n}|^\ttb \big|  \ccF_{\! n}\big]$.  Then, 
\begin{equation}

\Phi_\ttb (\overline{X}_n)  \leq \frac{\ttm_\nu^\ttb +\ttm_\nu}{\ttm_\nu \! +\!  k_{X_n} \! (\bT)} U^\ttb_{X_n}  \quad \textrm{and} \quad \Phi_\ttb (\overline{X}_n) \eqo \Phi_\ttb \big( \mathtt{cent} ( \overline{X}_n)\big) \; .
\end{equation}
If $\ttb \ino (1, \infty)$ is such that $\sum_{k\in \bbN} k^{\ttb} \nu (k) \leko \infty$ and if $\bT$ is an invariant GW($\nu$)-tree, then $\bE[\Phi_\ttb (\overline{X}_n) ]\eqo \bE [ \Phi_\ttb (\overline{X}_0) ] \leko \infty$.  
In the specific case where $\ttb\eqo 2$, then
\begin{equation}

\bE \big[ \Phi_2  ( \overline{X}_n)\big]\eqo \frac{\ttm_\nu(2)\! -\! \ttm_\nu}{\ttm_\nu^2\! -\! \ttm_\nu} = : \sigma_\nu^2.  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

