[Lemma 9 (Lemma 3.4 in \cite{pierre2010global}) of arXiv:2604.06645, '2604.06645'] Let $v_1,v_2$ be regular functions in the sense of \eqref{eq: system classical solution} satisfying
\begin{equation}
\partial_t v_1 - d_1 \Delta v_1 + \theta_1 v_1 
\le \theta_2 \partial_t v_2 - d_2 \Delta v_2 + \theta_3 v_2 + H
\end{equation}
together with the same constant Neumann or Dirichlet boundary conditions for $v_1,v_2$, where $\theta_i \in \mathbb{R}$ and $H \in L^p(Q_T)$, $H \ge 0$. Then, there exists $C>0$ depending on $p,d_1,d_2$ and the domain $D$ such that, for all $1<p<\infty$, $t\in (0,T]$, 
and with bounded initial data,
\begin{equation}
\|v_1^+\|_{L^p(Q_t)} \leq C \left( \|v_2\|_{L^p(Q_t)} + \|v_1(0)\|_{L^p(D)} + |\theta_2|  \|v_2(0)\|_{L^p(D)} + \int_0^t \|H(s)\|_{L^p(D)} ds \right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 1 of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] Let $\mathcal H_m$ be a Euclidean class with exponent $V$. Then for any $p \geq 2$ and $1 \leq j \leq m$,   
    \begin{align*}
    \left(\mathbb E \sup_{h \in \mathcal{H}_m} \lvert V_{N,j}(h) \rvert^p \right)^{1/p}  \leq C^j\max\left\{B_1(p,j), B_2(p,j)\right\} 
\end{align*}
where 
    \begin{align*}
    B_1(p,j) &= p^{j/2}\left(\frac{m}{j}\right)^{j/2} D(p,j)\,,
    \\
    B_2(p,j) &= 
    \left(C_1V \left[j\log\left(\frac{C_2m}{j}\right) \bigvee \log\left( \frac{e}{\Sigma_{\mathcal H_m}}\right)\right]\right)^{j/2} D(p,j).
    \end{align*}
    Moreover, if $p\geq 4V$, then $B_2(p,j)$ can be chosen as
    \[
    B_2(p,j) = ( pj)^{j/2} e^{-pj/V}.
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:rescaling of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Let $a,b,c>0$ and let $X$ be a solution to (equation eq:SPDE1 of the paper). Then 
	\begin{equation*}
		\tilde{X}_t(x) = cX_{at}(bx), \quad t \geq 0, \quad x\in \mathbb{R}, 
	\end{equation*}
	is a solution to 
	\begin{equation*}
	\begin{split}
		d_t \tilde{X}_t(x) &= \frac{a}{2b^2}\Delta\tilde{X}_t(x) + ach_c(\tilde{X}_t(x)) + \frac{c^{1/2}a^{1/2}}{b^{1/2}}\sqrt{\tilde{X}_t(x)} \dot{W}(t,x),\quad x\in \mathbb{R} ,t\geq 0,\\
	\tilde{X}_0(x) &= cX_0(bx), \quad x\in \mathbb{R} ,
		\end{split}
	\end{equation*}
	where $h_c(x) = h(c^{-1}x)$ for $x\in \mathbb{R}$.

