[Lemma lemma4 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Suppose that assumptions (A1 of the paper)-(A7 of the paper) hold and let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, we have the following:
\begin{enumerate}[label=(\textbf{\roman*})]
\item  For every $t \in \mathbb{R}$, $n \in \mathbb{N}_{0}$ and $k=0, \dots, h+1$, 
\begin{align} 
\sum_{|u|=n} |\varphi_{u}^{(k)}(t-S(u))| \in L^{2}(\Omega, \mathcal{F}, \mathbb{P}). 
\end{align}

\item  Suppose that $\varphi$ also satisfies (C5 of the paper) and let $\varepsilon >0$ be as defined in (C5 of the paper). Then, for any $t \in \mathbb{R}$, $k=0, \dots, h+1$ and $i=0, \dots, h$, 
\begin{align} 
\left( \left(\sum_{|u|=i} |\varphi_{u}^{(k)}(s-S(u))| \right)^{2} \right)_{|s-t| \leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}

\item   Suppose that $\varphi$ also satisfies (C4 of the paper). Then, for $i=0, \dots, h$ and $k=0, \dots, h+1$, 
\begin{align}
t \in \mathbb{R} \mapsto  \sum_{|u|=i} \varphi_{u}^{(k)}(t-S(u))
\end{align}
\noindent almost surely has c\`adl\`ag  paths. 
\end{enumerate}

