body:
[Proposition prop:theRGthm of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $\eta \in [0,1/2)$,  $d\ge d_{c,u}$ and $g >0$ be sufficiently small,  $(\vec{\textbf{a}}_{c,k})_{k \in \N \cup \{\infty\}}$ be as in Theorem~(thm:theStableManifold of the paper) and $\nu_c$ be as in Definition~(defi:nuc of the paper).
There exist convergent sequences $(\epsilon_k, \epsilon'_k )_{k \in \N \cup \{\infty \}}$ such that $\epsilon_k \rightarrow 0$,  $\epsilon'_k \downarrow 0$ and satisfy the following.
On $\Lambda = \Lambda_N$,  consider $\vec{\textbf{a}}$ given by $\textbf{a}^{(\km)} = \textbf{a}_{c,k}^{(\km)}$ for each $\km \in \kA_1$,  $\textbf{a}^{(\emptyset)} = \epsilon'_k$ and
\begin{align}
	Z_{N,\varnothing} (\varphi) = \E_{w_N} \theta \big[ \exp (-V_{0,\varnothing} (\Lambda,\varphi)) \big] 
\end{align}
where $V_0$ is defined using $\nu_0^{(\emptyset)} = \nu_c + \epsilon_k$, 
$\nu_0^{(\km_1)} = - \textbf{a}^{(\km_1)}_{c,k}$ for $\km_1 \in \ko_{2,\nabla}$,
$g^{(\emptyset)}_0 = g$ and $g^{(\km_2)} = 0$ for $\km_2 \in \ko_{4,\nabla}$.  Then
\begin{align}
	Z_{N,\varnothing} (\varphi) = e^{-u_{N,\varnothing} ( \Lambda_N )} \left( I_{N,\varnothing} (\varphi) + K_{N,\varnothing} \right) 
\end{align}
for some $u_{N,\varnothing} (\Lambda_N) \in \R$,  $V_{N,\varnothing} \in \tilde\cD_N^{(0)}$ and $K_{N,\varnothing} \in M \cK_N$ where $I_{N,\varnothing} = \cI_N (V_{N,\varnothing})$ is as in Section~(sec:WIcoords of the paper) and $M >0$ is a (possibly $L$-dependent) constant.

[Definition 16 (Proper graph coloring) of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] A proper $(r,K)$-coloring of
	$\mathcal P_{N_n,M}$, denoted by
	$\mathcal C_{r,K}[\mathcal P_{N_n,M}]$, is a partition $\left\{
		C_1,\ldots, C_K
		\right\}$  	of $[M]$ such that, for every $k\in[K]$,
	\begin{align}
		m,m'\in C_k,
		\qquad
		m\neq m'
		\quad\Longrightarrow\quad
		d_n(B_m,B_{m'})
		>
		r.

	\end{align}


	The minimal number of colors is
	\begin{align}
		K_{r} : = K\left(
		r,
		\mathcal P_{N_n,M}
		\right)
		:=
		\min\left\{
		K\in\mathbb N:
		\mathcal P_{N_n,M}
		\text{ admits a proper }(r,K)\text{-coloring}
		\right\}.

	\end{align}
	We refer to
	$K(r,\mathcal P_{N_n,M})$ as the
	$r$-chromatic number of the block partition. Under this choice, we use 	$\mathcal C_{r}[\mathcal P_{N_n,M}]$ to denote the proper coloring.

[Theorem 1 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] For the model described in \S\ref{subsec:model_fixed_sample_size}, the sequence $\{(n^{-1}A_{n},n^{-1}B_{n},n^{-1}C_{n})\}$ converges almost surely to a compact, connected, internally chain transitive invariant set, contained in $\mathcal{S}$, corresponding to the autonomous ODE
\begin{equation}
\left(\dot{a}(t),\dot{b}(t),\dot{c}(t)\right)=h\left(a(t),b(t),c(t)\right) \text{ for }t\geqslant 0, \text{ with } (a(0),b(0),c(0))=(A_{N}/N,0,0),
\end{equation}
where the function $h$ is as defined in \eqref{h_defn_fixed_size}, and $A_{N}$ is as defined via \eqref{A_{n}_defn}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] Let $\kappa$ be a positive Borel measure on $\Gamma_{\kappa,\theta}(\subset \Gamma)$,  and let $\theta$ be a positive,  symmetric measure on $(\Gamma_{\kappa,\theta}\times \Gamma_{\kappa,\theta})\setminus d$,  where $d$ denotes the diagonal of $\Gamma \times \Gamma$. 
The pair $(\kappa, \theta)$ is called \emph{quasi-admissible} if the following conditions hold:
\begin{itemize}
\item[(1)] $B_{\kappa,\theta}:=\Gamma\setminus \Gamma_{\kappa,\theta}$ is quasi-closed.
\item[(2)] $\kappa+\bar\theta$ is smooth with respect to the part Dirichlet form of $(\mathbf{D}, \tilde{H}^1(\Omega))$ on $\overline{\Omega}\setminus B_{\kappa,\theta}$,  where $\bar{\theta}(dx):=\theta(dx,\Gamma_{\kappa, \theta})$.  
\end{itemize}

[Lemma 47 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Suppose that $f \in \cB_{p,q}^{\alpha - \beta}$ where $\alpha \in \mbR$ and $p,q \in [1,\infty]$. Then given a $\beta$-regularising kernel $K$ in the sense of \cite[Assumption 5.1]{H0}, we have that \begin{align*}
		\| 2^{n \alpha} & \| \sup_{\psi \in \mcB_{\bar{\alpha}}^r} \langle K \ast f, \psi_y^n \rangle \|_{L^p(\mfK; dz')} \|_{\ell^q(n)} + \| \sup_{\psi \in \mcB^r} \langle K \ast f, \psi_y \rangle \|_{L^p(\mfK ; dy)}
		\\ 
		\lesssim& 	\| 2^{n (\alpha - \beta)} \| \sup_{\psi \in \mcB_{\bar{\alpha} - \beta}^r} \langle f, \psi_y^n \rangle \|_{L^p(\bar{\mfK}; dy)} \|_{\ell^q(n)} + \| \sup_{\psi \in \mcB^r} \langle f, \psi_y \rangle \|_{L^p(\bar{\mfK} ; dy)}
	\end{align*}
	for each $\bar{\alpha} > \alpha$ where $\mcB_\alpha^r$ denotes the set of elements of $\mcB^r$ that annihilate polynomials of degree less than $\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:scaling limit of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ satisfy $\lim_{n\rightarrow\infty}\mu\sqrt{n}=\alpha\in\mathbb R$.
    Let $\mathbf{T}_n=\mathbf T^\mu$ be a $\mu$-height-biased tree of size $n$, let $d_n$ denote the graph distance on $\mathbf{T}_n$ with each edge having length 1, and let $\sigma_n$ denote the uniform measure on the  vertices of ~$\mathbf T_n$. Then
    \begin{align*}
        \left(\mathbf{T}_n,\frac{d_n}{\sqrt{2n}}, {\sigma_n}\right) \overset d\longrightarrow \big(\mathbfcal{T}_{\alpha},d_{\alpha}\,, \sigma_{\alpha}\big),
    \end{align*}
    where the convergence in distribution above is with respect to the Gromov-Hausdorff-Prokhorov (GHP) topology. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2606.15843, 'Long-time behaviour of DLRA for SDEs'] Suppose Assumptions (H3), (H7) and (H8) hold.
			Moreover, suppose  Assumption~\ref{AS:relation2} holds. Furthermore, suppose the initial condition $(\zeta,\xi)\in L^p(\Omega,V_r(\bb R^d)\times\bb R^r)$. Then, there exists a constant $C(b,\sigma,p)>0$, one has
             \begin{align}
                \bb E[\|U_t^{(\mu)}\|_{\rrm {HS}}^p]=r^\frac{p}{2},
            \end{align}
             and
			\begin{align}
				\bb E[|Y_t^{(\mu)}|^p]\le \rrm e^{-\lambda \frac{p}{2}t}\bb E[|\xi|^p]+\frac{2C(b,\sigma,p)}{\lambda p},
			\end{align}   
            where $\lambda=2L_{b,7}-2(p-1)L_{\sigma,1}-\frac{2}{p}$.

