[Proposition CH1 of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] For $s>0$, $q\in[1,\infty]$ and ${\boldsymbol{p}}\in[1,\infty]^2$, an equivalent norm of ${\mathbb B}^{s,q}_{{\boldsymbol{p}};{\boldsymbol{a}}}$ is given by
\begin{align}
\|f\|_{{\mathbb B}^{s,q}_{{\boldsymbol{p}};{\boldsymbol{a}}}}\asymp \left(\int_{{\mathbb R}^{2d}}\left(\frac{\|\delta_h^{([s]+1)}f\|_{{\boldsymbol{p}}}}{|h|^s_{\boldsymbol{a}}}\right)^q\frac{d h}{|h|^{4
d}_{\boldsymbol{a}}}\right)^{1/q}+\|f\|_{{\boldsymbol{p}}}=:[f]_{{\mathbb B}^{s,q}_{{\boldsymbol{p}};{\boldsymbol{a}}}}+\|f\|_{{\boldsymbol{p}}},
\end{align}
where $[s]$ is the integer part of $s$. In particular, ${\mathbb C}^s_{{\boldsymbol{a}}}:=\mathbf{B}^{s,\infty}_{\infty;{\boldsymbol{a}}}$ is the anisotropic
H\"older-Zygmund space, and for $s\in(0,1)$, there is a constant $C=C(\alpha,d,s)>0$ such that
\begin{align*}
  \|f\|_{{\mathbb C}^s_{{\boldsymbol{a}}}} \asymp_C\|f\|_\infty+\sup_{z\not= z'}|f(z)-f(z')|/|z-z'|^{s}_{\boldsymbol{a}},
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:empb-fixn of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Suppose $\alpha \in (0,1)$.
    Let $ \mathbf{X} _1,\dots, \mathbf{X} _n$ be adapted $\mathcal{S}_d^{[0,1]}$-valued random matrices with constant conditional mean $ \mathbf{M}  =  \mathbb E  ( \mathbf{X} _i|\mathcal{F}_{i-1})$ and constant conditional variance $ \mathbf{V}  =  \mathbb E (  ( \mathbf{X} _i -  \mathbf{M} )^2|\mathcal{F}_{i-1} )$.  Let $\overline{ \mathbf{X} }_i = \frac{1}{i}( \mathbf{X} _1+\dots+ \mathbf{X} _i)$ and $\overline{ \mathbf{X} }_0 = 0$.
     Define the following variance proxies
    \begin{gather}
       \overline{ \mathbf{V} }_0 = \frac
       1 4  \mathbf{I} , \quad  \overline{ \mathbf{V} }_k = \frac{1}{k}\sum_{i=1}^k ( \mathbf{X} _i - \overline \mathbf{X} _k)^2, \quad  \overline{v}_k = \|\overline{ \mathbf{V} }_{k}\| \vee \frac{5\log(d/\alpha)}{n},
    \end{gather}
    and set $\gamma_i = \sqrt{\frac{2\log(d/\alpha)}{n \overline{v}_{i-1}}}$ for $i=1,\dots, n$. Then,
    \begin{equation}
          \mathbb P \left( \lambda_{\max} \left( \overline{ \mathbf{X} }_n^{\gamma} -  \mathbf{M}  \right) \geqslant D_n^{\mathsf{meb2}}  \right) \leqslant \alpha, \, \text{where} \ D_n^{\mathsf{meb2}} = \frac{  \log(d/\alpha) +\lambda_{\max}\left( \sum_{i=1}^n \psi_{\mathrm{E}}(\gamma_i) ( \mathbf{X} _i - \overline{ \mathbf{X} }_{i-1})^2 \right)  }{\gamma_1 + \dots + \gamma_n}.
     \end{equation}
    Further, 










        asymptotically,
        \begin{equation}
          \lim_{n \to \infty} \sqrt{n}   D_n^{\mathsf{meb2}} = \sqrt{2\log(d/\alpha) \| \mathbf{V} \|} \quad \text{almost surely}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

