body:
[Theorem FPE of arXiv:2608.16946, 'A diffusion model for time-dependent compositional data'] Assume the coefficients $\mu$ and $\sigma$ are independent of time $t$, smooth enough to make desired
derivatives exist and continuous, and the invariant measure has a density, then the steady state probability density
function $f(x)$  verifies the  following partial differential equation: 
\begin{equation} 
\sum_{i=1}^d \frac{\partial}{\partial x_i} [\mu_i(x)f(x)]=\frac{1}{2} \sum_{i=1}^d \sum_{j=1}^d \frac{\partial^2}{\partial x_i \partial x_j} [a_{ij}(x)f(x)],
\end{equation}
where $a=\sigma \sigma^T.$

Conversely, if a function $f$ is a solution of~(equation fp-equation of the paper)
satisfying the appropriate positivity and normalization conditions, then $f$ is the steady state density function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def: good paths prop of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] For $F \subset \mathbb{T}_N$, we say a path collection $\mathcal{A} \subset \Omega_{T_3}$ is $(F,\varepsilon,M_0)$-good if for all $\omega \in \mathcal{A}$,
    \begin{subequations}

        \begin{gather}

            \mathbb{T}_N \setminus F \subset \omega[0,T_3];\\

            \boldsymbol{r}_{x}(\omega) \leq l_N \text{ for all } x \in  \mathcal{L}_{F}^{\beta_N}(\omega);\\

            2d\cdot\mathsf{Mdist}\big(\mathcal{L}_{F}^{\beta_N}(\omega)\big)\leq J(F,M_0),
        \end{gather}
    \end{subequations}
    where 
\begin{equation}

        J(F,M_0)\overset{\rm def.}{=} 2d M_0\cdot|F|N^{-d\gamma}.
    \end{equation}
    For an event $A\in \mathcal{F}_{T_3}$, we also say $A$ is $(F,\varepsilon,M_0)$-good if the path collection $\mathcal{A}=\pi_{T_3}(A)$ (see (equation eq: paths correspond to event of the paper) for definition) is $(F,\varepsilon,M_0)$-good.

[Definition 239 of arXiv:2601.16377, '2601.16377'] Let $\mathfrak{G}^{[2]}$ be the subgroup of $\textnormal{GL}\big((\amsmathbb{R}^{H} \otimes \amsmathbb{R}^H) \oplus \amsmathbb{R}\big)$ generated by $T^{(h)}_i$ indexed by $i = 1,2$ and $h \in [H]$ and defined by
\begin{equation}

\begin{split}
T^{(h)}_1\big(\boldsymbol{w}_1\otimes \boldsymbol{w}_2\,,\,t\big) & = \left(T^{(h)}(\boldsymbol{w}_1) \otimes \boldsymbol{w}_2\,,\, t - \frac{\lambda_h(\boldsymbol{w}_1)\lambda_h(\boldsymbol{w}_2)}{\theta_{h,h}}\right) , \\
T^{(h)}_2\big(\boldsymbol{w}_1\otimes \boldsymbol{w}_2\,,\,t\big) & = \left(\boldsymbol{w}_1 \otimes T^{(h)}(\boldsymbol{w}_2)\,,\,t - \frac{\lambda_h(\boldsymbol{w}_1)\lambda_h(\boldsymbol{w}_2)}{\theta_{h,h}}\right) ,
\end{split}
\end{equation}
where the linear form $\lambda_h : \amsmathbb{R}^H \rightarrow \amsmathbb{R}$ extracts the $h$-th component of a vector.

[Theorem FK of arXiv:2509.10990, 'On the Continuity of Enhancement Percolation'] There is a universal constant $C$ so that the following holds: Let $A$ be a symmetric, increasing event on the Hamming cube $Q_n = \left\{0,1\right\}^n$ endowed with the Bernoulli product measures. If $\mathbb{P}_p\left( A \right) > \epsilon,$ then 
    \[\mathbb{P}_q\left( A \right) > 1-\epsilon\]
    for $q = p + C\log\left( 1/2\epsilon \right)/\log n\,.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 46 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] The process  
\[
 \bX_n(t)-\bX_n(0)-\int_0^t \bF_n(\bX_n(s))\, \d s =\int_0^t \newG_{0,n}(s,\bX_n(s))\,\d W(s),\;\; t \in [0,T],
\]
is a square integrable $\mathbb{H}_n$-valued martingale on the original probability space. 
\newline
If $f: \mathbb{R} \to \mathbb{C}$ is a $C^2_b$-class function and   $z \in \nU$, then the  following process 
    \begin{equation}
      h(\bX_n(t)) - h(\bX_n(0))-\int_0^t \mathscr{L}_{n,s}(h)(\bX_n(s))\,\d s,\;\; t \in [0,T],
   \end{equation}
where   the function $h:\nU^\prime \to \mathbb{C}$ has the following form,
\begin{equation}
    h(\bX)=f(\duality{\bX}{z}{}{}),\;\; \bX \in \nU^\prime
    \end{equation} 
 and $\mathscr{L}_{n,s}$ is given by
     \begin{equation}
         \mathscr{L}_{n,s} (h)(\bX) \coloneqq D h(\bX) \left[\bF_n(\bX)\right] 
         + \frac12 \sum_{k=1}^\infty D^2 h(\bX) \Bigl[[\newG_{0,n}(s,\bX)](\tilde{e}_k), [\newG_{0,n}(s,\bX)](\tilde{e}_k)\Bigr],\;\; \bX \in \nU^\prime,  
     \end{equation}
is a martingale. \newdela{NOTE: as written the sentence reads ``the function $h$ \dots\ and $\mathscr{L}_{n,s}$ \dots\ is a martingale'', but the martingale is the \emph{process} \eqref{eqn-h(X_n)}; $h$ and $\mathscr{L}_{n,s}$ are just its ingredients. Recommend rephrasing: ``\dots\ the process \eqref{eqn-h(X_n)}, where $h$ is given by \eqref{eqn-h} and $\mathscr{L}_{n,s}$ by \eqref{eqn-L_n}, is a martingale.''} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:BL-limits-pp of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Let  $\tilde{\mathcal{P}}$  be a  marked point process on $\mathbb{R}^d\times\mathbb{K}$ with uniformly bounded  first correlation function  $\rho^{(1)}\le \kappa_1<\infty$.   Let $\xi : \mathbb{R}^d \times \mathbb{K} \times \hat\mathcal{N}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ be a real-valued marking function (score) which is $L^1$-stabilizing on finite windows of $\tilde{\mathcal{P}}$ as in~(equation Lq-stab-windows of the paper) with $p=1$ and  satisfies the first  moment condition on finite windows as in ~(equation e:xinpmom of the paper) with $p=1$. 
\begin{enumerate}[wide,label=(\roman*),labelindent=0pt]
\item  Then the ground point process marked by the score function 
$\xi$ on finite windows converges weakly in the vague topology to a stationary marking  $\tilde{\mathcal{P}}^\Upsilon$ of this ground point process on the entire space, i.e.,
\begin{equation}
\tilde{\mathcal{P}}^\xi_n=\sum_{x \in \mathcal{P}_n} \delta_{(x, \xi(\tilde{x}, \tilde{\mathcal{P}}_n))}
\xrightarrow[n \to \infty]{d}
\tilde{\mathcal{P}}^\Upsilon=\sum_{x \in \mathcal{P}} \delta_{(x, \Upsilon(x))}.
\end{equation}

\item  If moreover  for $p\in\mathbb{N}$ the input process $\mathcal{P}$ has finite moments of order $p+\epsilon$ for some $\epsilon>0$; i.e., $\mathbb{E} [\mathcal{P}(B)^{p+\epsilon}]<\infty$ for all $B\in\mathcal{B}_b$, with a uniformly bounded correlation function $\rho^{(p)}\le\kappa_p<\infty$, and $\xi$ satisfies~(equation Lq-stab-windows of the paper) then the  Palm distributions $\mathcal{M}_{\bk x1p}^{\Upsilon}$ of $\tilde{\mathcal{P}}^\Upsilon$ of order $p$ satisfy 
$$\mathcal{M}_{\bk x1p}^{\Upsilon}(\cdot) = \mathbb{P}\{\Upsilon_{\bk x1p} \in \cdot\}\quad \text{for $\rho^{(p)}(\bk x1p)\,\mathrm{d} \bk x1p$-almost all $\bk x1p\in\mathbb{R}^{dp}$,}$$
where $\Upsilon_{\bk x1p}$  are limits of  the Palm distributions of the score function $\bk{\xi}1p(\tilde{x},\tilde{\mathcal{P}}_n) \xrightarrow[n \to \infty]{\textnormal{BL},\bk x1p} \Upsilon_{\bk x1p}$ stated in~(equation e:BL-n-limit of the paper).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 8 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Consider the event $\{\mathcal C(0; \mathcal Q_{z, i}^c)=B\}$ for a given $B$.
\begin{itemize}
\item Denote by $\mathrm{Reg}_i(B)$ a maximal subset of $K$-regular points on $\partial \mathcal Q_{z, i}$ whose pairwise $\ell_\infty$-distances are at least $3K$. (If there is more than one possibility for this set, then we choose one arbitrarily according to some fixed procedure.)
\item For each $x \in  \mathrm{Reg}_i(B)$, we define $L_x$ to be a line segment of length $K$ extending from $x$ inside $\mathcal Q_{z, i}$, perpendicularly to the face upon which $x$ is sited. If $x$ lies within a distance $K$ from the intersection of at least two faces of $\mathcal Q_{z, i}$, then $L_x$ is defined to be the union of (at most) $d$ line segments inside $\mathcal Q_{z, i}$ of total length at most $dK$ that connect $x$ to a point that is at a distance $K$ from $\partial \mathcal Q_{z, i}$. Note that, since the vertices are separated by a distance at least $3K$, two distinct $L_x$ are separated by a distance at least $K$.
\item For each $x \in  \mathrm{Reg}_i(B)$, we consider the maximal line segment from $x$ that is contained in $L_x$ and formed by open edges. We write $L(B)$ for the union of all these line segments. (Note this is a random set, depending on $B$ and the configuration within $\mathcal Q_{z, i}$.)
\end{itemize}
A point $x\in \mathrm{Reg}_i(B)$ is said to be $K$-line good if all edges of $L_x$ are open. For such points, write $x'$ for the point of $L_x$ at maximal distance from $x$, and let $\mathrm{Reg}'_i(B)$ be the collection of such points. We write $X_{r,i}^{K-\mathrm{line-good}}$ for the number of $K$-line good points on $\partial Q_{z, (i\varepsilon+1)r}$. (See Figure \ref{fig:KLgooddef}.) Moreover, for the set $\mathcal Q_{z, i}^c$, we define the corresponding extended cluster by setting
\begin{align}
\mathcal C_e(0; \mathcal Q_{z, i}^c)=\mathcal C(0;\mathcal Q_{z, i}^c)\cup L(\mathcal C(0;\mathcal Q_{z, i}^c)). 
\end{align}

[Prop 25 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Recall $M_{11}(s)$ from \eqref{eq:M11-before-magic}. We have
		\begin{equation*}
			M_{11}(s)=\left\langle \phi, \Eis\left(\M f\cdot \M\ol{f_s}\right)\right\rangle_{[\bar{G}_n]}
		\end{equation*}
		where $\M$ is as in \eqref{eq:def-main-intertwiner}.

