[Lem 20 of arXiv:2604.25725, 'What is The Probability That A Random Graph With A Given Degree Sequence is Connected?'] For any $m$ large enough, $0<\gamma<1$, $0<\epsilon<10^{-10}$, $n_1 \le m^{1-\gamma}$, $n_2<\eps m$, $0<C \le m^{\gamma /20}$, $1\leq i$, $0\leq r\le C(\log m)^2$, the following holds: if $2|E(H_{i-1})|+X_{i-1} \le \epsilon m$ then  
\begin{equation*}
    \Cprob{\sum_{t=i}^{i+r-1} J_t\I{X_t\leq X_{t-1}} \ge \frac{C}{3} \text{ and }\forall i\leq t\leq i+r-1: X_{t-1}\le 2C}{H_{i-1}} <m^{-\gamma C/4}.
\end{equation*}

[Lemma 13 of arXiv:2607.26944, 'Improved bounds on the inradius and inverse inradius process of the convex hull of planar '] For $\Psi_1$ as in~\eqref{eq:defn_object_funct_mean_inradi} and $\mathfrak{F}(1)$ as in~\eqref{eq:feasible_region_F(r)}, we have
\begin{equation*}
    \E[\Theta^\sfr] \le \inf_{(m,b,a)\in \mathfrak{F}(1)} \Psi_1(m,b,a)\le 18.7460.
\end{equation*}

[Thm 30 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] \cite[Freedman, Theorem 1.6]{freedman}
If $|Y_{n+1} - Y_n| \le 1$ for all $n$, then for any $a, b>0$,
$$\mathbb P\left(\exists n: Y_n \ge a \text{ and } \sum_{j=1}^n V_j \le b\right) \le \exp\left(-{a^2 \over 2(a+b)}\right).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

